within AdvancedNoise.Distributions.Bates;
function cumulative "Cumulative distribution function of Bates distribution"
  import AdvancedNoise.Math.factorial;
  import AdvancedNoise.Math.binomial;
  extends Modelica.Math.Distributions.Interfaces.partialCumulative;
  input Real y_min=0 "Lower limit of band" ;
  input Real y_max=1 "Upper limit of band" ;
  input Integer n=12 "Number of uniform random values" ;
protected
  Real x "Abbreviation into the interval (0,1)";
algorithm

  // This is the formula for the PDF:
  // pdf = n^n    /(n-1)!*sum( (-1)^k * binomial(n,k) * (x-k/n)^(n-1) , k = 0..floor(n*x))

  // The integral is actually only once over x
  // cdf = n^(n-1)/(n-1)!*sum( (-1)^k * binomial(n,k) * (x-k/n)^( n ) , k = 0..floor(n*x))

  // Map the scaled distribution to the stable region
  x := (u - y_min) / (y_max - y_min);
  if u > 0.5*(y_min+y_max) then
    x := 1 - x;
  end if;

  // Only calculate a number within the boundary
  y := 0;
  if u >= y_min and u <= y_max then

    // Loop over k = 0 .. floor(n*x)
    for k in 0:integer(n*x) loop
      // Sum up the inner part
      y := y + (-1)^k * binomial(n,k) * (x-k/n)^(n);
    end for;
    // Multiply by the outer factor
    y := n^(n-1) / factorial(n-1) * y;

  elseif u > y_max then
    y := 1;
  end if;

  // Invert the CDF for x > 0.5
  if u > 0.5*(y_min+y_max) and u <= y_max then
    y := 1 - y;
  end if
  ;
end cumulative;

within AdvancedNoise.Distributions.Bates;
function density "Density of Bates distribution"
  import AdvancedNoise.Math.factorial;
  import AdvancedNoise.Math.binomial;
  extends Modelica.Math.Distributions.Interfaces.partialDensity;
  input Real y_min=0 "Lower limit of band" ;
  input Real y_max=1 "Upper limit of band" ;
  input Integer n=12 "Number of uniform random values" ;
protected
  Real x "Abbreviation into the interval (0,1)";
algorithm
  // This is the formula for the PDF:
  // pdf = n^n/(n-1)!*sum( (-1)^k * binomial(n,k) * (x-k/n)^(n-1)               , k = 0..floor(n*x))

  // Map the scaled distribution to the stable region
  x := (u - y_min) / (y_max - y_min);
  if u > 0.5*(y_min+y_max) then
    x := 1 - x;
  end if;

  // Only calculate a number within the boundary
  y := 0;
  if u >= y_min and u <= y_max then

    // Loop over k = 0 .. floor(n*x)
    for k in 0:integer(n*x) loop
      // Sum up the inner part
      y := y + (-1)^k * binomial(n,k) * (x-k/n)^(n-1);
    end for;
    // Multiply by the outer factor
    y := n^(n)/3 / factorial(n-1) * y;

  end if

  ;
end density;

within AdvancedNoise.Distributions.Bates;
function quantile "Quantile of Bates distribution"
  extends Modelica.Math.Distributions.Interfaces.partialQuantile;
  input Real y_min=0 "Lower limit of band" ;
  input Real y_max=1 "Upper limit of band" ;
  input Integer n=12 "Number of uniform random values" ;
protected
  Real tol = 1e-6 "Required accuracy of the quantile";
  Real y_l, y_m, y_h "Random values during search";
  Real p_l, p_m, p_h "Probabilities during search";
  Integer i "A counter for debugging";
algorithm

  // Return the limits, if the probability is not in (0,1)
  if u > 1 then
    y := y_max;
  elseif u < 0 then
    y := y_min;

  // Iterate the value, because we have not found an inverse CDF
  else

    // Initialize variables
    i   := 0;
    y_l := y_min;
    y_h := y_max;
    p_l := cumulative(y_l, y_min, y_max, n);
    p_h := cumulative(y_h, y_min, y_max, n);

    // Keep iterating as long as both estimations are not close enough
    while abs(u-p_l) > tol and abs(u-p_h) > tol loop
      i   := i + 1;

      // Calculate an intermediate point
      y_m := y_l + (y_h-y_l)/(p_h-p_l)*(u-p_l);
      p_m := cumulative(y_m, y_min, y_max, n);

      // Select narrower boundaries than before
      if p_m >= u then
        y_h := y_m;
        p_h := p_m;
      end if;
      if p_m <= u then
        y_l := y_m;
        p_l := p_m;
      end if;
    end while;

    // Select correct boundary
    if abs(u-p_l) < abs(u-p_h) then
      y := y_l;
    else
      y := y_h;
    end if;
  end if

  ;
end quantile;

within AdvancedNoise.Distributions.Discrete;
function cumulative "Cumulative distribution function of discrete distribution"
  extends Modelica.Math.Distributions.Interfaces.partialCumulative;
  input Real x[:] = {0,1} "Discrete values to be chosen from" ;
  input Real p[size(x,1)] = ones(size(x,1))/size(x,1)
    "The probabilities of the discrete values" ;
algorithm
  y := 0;
  for i in 1:size(x,1) loop
    if u >= x[i] then
      y := y + p[i];
    end if;
  end for;
  y := y / sum(p)

  ;
end cumulative;

within AdvancedNoise.Distributions.Discrete;
function density "Density of discrete distribution (undefined!)"
  extends Modelica.Math.Distributions.Interfaces.partialDensity;
