    "The probabilities of the discrete values" ;
algorithm
  assert(false, "The density of the discrete distribution is not defined.")

  ;
end density;

within AdvancedNoise.Distributions.Discrete;
function quantile
  "Quantile of discrete distribution (= inverse cumulative distribution function)"
  extends Modelica.Math.Distributions.Interfaces.partialQuantile;
  input Real x[:] = {0,1} "Discrete values to be chosen from" ;
  input Real p[size(x,1)] = ones(size(x,1))/size(x,1)
    "The probabilities of the discrete values" ;
protected
  Integer iSorted[size(x,1)] "Sorted indices";
  Real    xSorted[size(x,1)] "Sorted values of x";
  Real    pSorted[size(x,1)] "Sorted values of p";
  Real    cdf;
algorithm
  (xSorted, iSorted) := Modelica.Math.Vectors.sort(x);

  cdf := 0;
  for i in 1:size(x,1) loop
    if u > cdf/sum(p) then
      y := xSorted[i];
    end if;
    cdf := cdf + p[iSorted[i]];
  end for

  ;
end quantile;

within AdvancedNoise.Distributions.TruncatedDiscrete;
function cumulative "Cumulative distribution function of discrete distribution"
  extends Modelica.Math.Distributions.Interfaces.partialTruncatedCumulative;
  input Real x[:] = {0,1} "Discrete values to be chosen from" ;
  input Real p[size(x,1)] = ones(size(x,1))/size(x,1)
    "The probabilities of the discrete values" ;
protected
  Real x0[size(x,1)+2];
  Real p0[size(x,1)+2];
algorithm
  x0 := cat(1,x,{u_min,u_max});
  p0 := cat(1,p,{    0,    0});
  for i in 1:size(x,1) loop
    if x[i] < u_min then
      p0[end-1] := p0[end-1] + p0[i];
      p0[i]     := 0;
    elseif x[i] > u_max then
      p0[end-0] := p0[end-0] + p0[i];
      p0[i]     := 0;
    end if;
  end for;
  AdvancedNoise.Distributions.Discrete.cumulative(
    u,
    x0,
    p0)

  ;
end cumulative;

