within AdvancedNoise.Statistics;
block Correlation "Calculates the correlation of two signals"
  extends Modelica.Blocks.Interfaces.SI2SO;

// Parameters
public
  parameter Modelica.Units.SI.Time delta_t(min=0) = 0.0
    "Time delay for auto-correlation of signal";

// The start time of the simulation
protected
  parameter Modelica.Units.SI.Time t_0(fixed=false) "Start time of the simulation";
initial equation
  t_0 = time;

// The local integration time
public
  Modelica.Units.SI.Time t = max(0, time - delta_t - t_0)
    "The local integration time (starts only after an offset of delta_t";

// The actual signals to correlate
public
  Real X = u1
    "The first random variable to calculate the correlation coefficient";
  Real Y = delay(u2,delta_t, delta_t+0.1)
    "The second random variable to calculate the correlation coefficient";

// Some integrals
public
  Real int_X "The integral of X";
  Real int_Y "The integral of Y";
  Real int_X2 "The integral of X^2";
  Real int_Y2 "The integral of Y^2";
  Real int_XY "The integral of X*Y";
initial equation
  int_X  = 0;
  int_Y  = 0;
  int_X2 = 0;
  int_Y2 = 0;
  int_XY = 0;
equation
  der(int_X)  = if t <  0 then 0 else X;
  der(int_Y)  = if t <  0 then 0 else Y;
  der(int_X2) = if t <  0 then 0 else X^2;
  der(int_Y2) = if t <  0 then 0 else Y^2;
  der(int_XY) = if t <  0 then 0 else X*Y;

// The mean values
public
  Real mean_X = if t <= 0 then X else int_X / t "The mean value of X";
  Real mean_Y = if t <= 0 then Y else int_Y / t "The mean value of Y";

// The variance values
public
  Real var_X =  if t <= 0 then 0 else (int_X2 - 2*mean_X*int_X + mean_X^2*t)                   / t
    "The variance of X";
  Real var_Y =  if t <= 0 then 0 else (int_Y2 - 2*mean_Y*int_Y + mean_Y^2*t)                   / t
    "The variance of Y";
  Real cov_XY = if t <= 0 then 0 else (int_XY - mean_X*int_Y - mean_Y*int_X + mean_X*mean_Y*t) / t
    "The co-variance of X and Y";

// The actual correlation
public
  Real r = noEvent(if var_X       <= 0        then 1.0 else
                   if var_Y       <= 0        then 1.0 else
                   if var_X*var_Y <= cov_XY^2 then 1.0 else cov_XY / sqrt(abs(var_X)) / sqrt(abs(var_Y)))
    "The Bravais- or Pearson-Correlation-Coefficient r = cov_XY / std_X / std_Y";

equation
  y=r

  ;
end Correlation;

within AdvancedNoise.Statistics;
block CorrelationTest
  "Tests the null hypothesis that two signals are uncorrelated"
  extends Modelica.Blocks.Interfaces.SI2SO;

// The start time of the simulation
protected
  parameter Modelica.Units.SI.Time t_0(fixed=false) "Start time of the simulation";
public
  parameter Modelica.Units.SI.Time t_eps = 0.001
    "Start evaluating shortly after simulation start";
initial equation
  t_0 = time;

// The distribution parameters
public
  final parameter Real rho = 0.0 "Expected correlation of null hypothesis (=0)";
  Real sigma = if time-t_0 > t_eps then 1 / sqrt(time-t_0) else 1/sqrt(t_eps);
protected
  encapsulated model FisherTransformation
    "Transforms a correlation to be approximately normally distributed"
    import Modelica;
    extends Modelica.Blocks.Interfaces.SISO;
    parameter Real r_max = 0.99 "Cut-off for correlation coefficient";
  equation
    y = noEvent(if u >=  r_max then 0.5 * log( (1+r_max) / (1-r_max))  else
                if u <= -r_max then 0.5 * log( (1+r_max) / (1-r_max))  else 0.5 * log(max(1e-8, (1+u) / (1-u))));
  end FisherTransformation;
public
  Correlation correlation
    ;
  SignificanceTest significanceTest(redeclare function H =
        Modelica.Math.Distributions.Normal.cumulative (mu=rho, sigma=sigma))
    ;
  FisherTransformation fisherTransformation
    ;
equation
  connect(correlation.u1, u1) ;
  connect(correlation.u2, u2) ;
  connect(correlation.y, fisherTransformation.u) ;
  connect(fisherTransformation.y, significanceTest.u) ;
  connect(significanceTest.y, y) 

    ;
end CorrelationTest;

within AdvancedNoise.Statistics;
model FaultTrigger "Triggers a fault given a time history of the failure rate"
  extends Modelica.Blocks.Interfaces.partialBooleanSO(y(start=false,fixed=true));

  Modelica.Blocks.Interfaces.RealInput u "The current failure rate"
    ;

// Calculate the probability to have failed by now
// => (1-F) is the probability to not yet have failed by now
// =>   u   is the probability/time to fail right now
// The fault is triggered, when F reaches a random threshold r in (0,1).
public
  Real F(min=0,max=1) "The current probability to have failed already";
equation
  der(F) = (1-F) * u;
  y      = F >= r;

// We need a random number to determine the trigger for F
protected
  outer Modelica.Blocks.Noise.GlobalSeed globalSeed
    "Definition of global seed via inner/outer";
public
  Real r(min=0,max=1) "Value to trigger the fault";
equation
  when {initial(), reset and pre(y)} then
    r = Modelica.Math.Random.Utilities.impureRandom(globalSeed.id_impure);
    reinit(F, 0.0);
  end when;

// Does the fault reset and is triggered again?
public
  input Boolean reset = true "=true: fault is triggered multiple times"


  ;

end FaultTrigger;

