within AixLib.Fluid.Actuators.Valves.ExpansionValves.Utilities;
model ModularSensors
  "Model that contains mass flow, pressure, temperature and quality sensors 
  for modular heat pump models"

  // Definition of parameters
  //
  parameter Modelica.Units.SI.Time tau=1 "Time constant at nominal flow rate"
    ;

  parameter Boolean transferHeat=false
    "if true, temperature T converges towards TAmb when no flow"
    ;
  parameter Modelica.Units.SI.Temperature TAmb=Medium.T_default
    "Fixed ambient temperature for heat transfer"
    ;
  parameter Modelica.Units.SI.Time tauHeaTra=1200
    "Time constant for heat transfer, default 20 minutes"
    ;

  parameter Modelica.Blocks.Types.Init initType=
    Modelica.Blocks.Types.Init.InitialState
    "Type of initialization (InitialState and InitialOutput are identical)"
    ;
  parameter Modelica.Units.SI.Temperature T_start=Medium.T_default
    "Initial or guess value of output (= state)"
    ;
  parameter Modelica.Units.SI.SpecificEnthalpy h_out_start=
      Medium.specificEnthalpy_pTX(
      p=Medium.p_default,
      T=Medium.T_default,
      X=Medium.X_default) "Initial or guess value of output (= state)"
    ;

  // Extensions
  //
  extends Interfaces.PartialModularPort_ab;

  // Definition of variables
  //
  Medium.SaturationProperties satPro[nPorts]
    "Saturation states for each fluid port";

  Modelica.Units.SI.SpecificEnthalpy bubEnt[nPorts]
    "Bubble enthalpies for each fluid port";
  Modelica.Units.SI.SpecificEnthalpy dewEnt[nPorts]
    "Dew enthalpies for each fluid port";
  Real pTriCri[nPorts]
    "Trigger to check if medium exceeds critical pressure";

  // Definition of models
  //
  Sensors.MassFlowRate senMasFlo[nPorts](
    redeclare each final package Medium = Medium) "Mass flow sensors"
    ;
  Sensors.Pressure senPre[nPorts](
    redeclare each final package Medium = Medium) "Pressure sensors"
    ;
  Sensors.TemperatureTwoPort senTem[nPorts](
    redeclare each final package Medium = Medium,
    each final m_flow_nominal=m_flow_nominal,
    each final m_flow_small=m_flow_small,
    each final tau=tau,
    each final initType=initType,
    each final T_start=T_start,
    each final transferHeat=transferHeat,
    each final TAmb=TAmb,
    each final tauHeaTra=tauHeaTra) "Temperature sensors"
    ;
  Sensors.SpecificEnthalpyTwoPort senSpeEnt[nPorts](
    redeclare each final package Medium = Medium,
    each final m_flow_nominal=m_flow_nominal,
    each final m_flow_small=m_flow_small,
    each final tau=tau,
    each final initType=initType,
    each final h_out_start=h_out_start) "Specific enthalpy sensors"
    ;

  // Definition of connectors
  //
  Modelica.Blocks.Interfaces.RealOutput preMea[nPorts]
    "Pressures measured by sensors"
    ;
  Modelica.Blocks.Interfaces.RealOutput temMea[nPorts]
    "Temperatures measured by sensors"
    ;
  Modelica.Blocks.Interfaces.RealOutput masFloMea[nPorts]
    "Mass flow rates measured by sensors"
    ;
  Modelica.Blocks.Interfaces.RealOutput quaMea[nPorts]
    "Qualities measured by sensors"
    ;

equation
  // Calculating vapour qualities
  //
  for i in 1:nPorts loop
    satPro[i] = Medium.setSat_p(senPre[i].p) "Set saturation properties";
    bubEnt[i] = Medium.bubbleEnthalpy(satPro[i]) "Calculate bubble enthalpies";
    dewEnt[i] = Medium.dewEnthalpy(satPro[i]) "Calculate dew enthalpies";
    pTriCri[i] = senPre[i].p/Medium.fluidConstants[1].criticalPressure
      "Check if medium exceeds critical pressure";
   quaMea[i] = noEvent(if (pTriCri[i]<1 and senSpeEnt[i].h_out<bubEnt[i]) then 0
     else if (pTriCri[i]<1 and senSpeEnt[i].h_out>bubEnt[i] and
     senSpeEnt[i].h_out<dewEnt[i]) then (senSpeEnt[i].h_out - bubEnt[i])/
     max(dewEnt[i] - bubEnt[i], 1e-6) else 1.0)
     "Calculate vapour qualities";
  end for;

  // Connection of sensors
  //
  for i in 1:nPorts loop
    connect(ports_a[i],senMasFlo[i].port_a);
    connect(senMasFlo[i].port_b,senPre[i].port);
    connect(senMasFlo[i].port_b,senTem[i].port_a);
    connect(senTem[i].port_b,senSpeEnt[i].port_a);
    connect(senSpeEnt[i].port_b,ports_b[i]);
  end for;

  // Connection of outputs
  //
  connect(preMea,senPre.p);
  connect(temMea,senTem.T);
  connect(masFloMea,senMasFlo.m_flow)

  ;
end ModularSensors;

within AixLib.Fluid.MassExchangers.MembraneBasedEnthalpyExchangers.BaseClasses.Functions;
function SherwoodNumberMuzychka
  "calculates sherwood number out of reynolds and prandtl number according to Muzychka et. al"
  input Real Re "Reynolds number";
  input Real Sc "Schmidt number";
  input Real aspRat "aspect ratio between duct height and width";
  input Real zStern "dimensionless length";
  input Boolean uniWalTem "true if uniform wall temperature boundary conditions";
  input Boolean local "true if local nusslet number or false if average shall be calculated";
  input Real gamma "shape parameter (rectangular duct: 0.1)";

  output Real Sh "Sherwood number";

protected
  Real m "exponent";
  Real C1 "constant C1: 3.24 for UWT(uniform wall temperature), 3.86 for UWF(uniform wall flux)";
  Real C2 "constant C2: 1 for local Nusselt number, 1.5 for average Nusselt number";
  Real C3 "constant C3: 0.409 for UWT, 0.501 for UWF";
  Real C4 "constant C4: 1 for local Nusselt number, 2 for average Nusselt number";
  Real fSc "function for boundary conditions";
  Real fRe "product of Reynolds and friction factor";
  constant Real pi = Modelica.Constants.pi;
algorithm
  // Definition for exponent
  m :=2.27 + 1.65*Sc^(1/3);

  // Defintion for boundary function
  if uniWalTem == true then
    fSc := 0.564/(1+(1.644*Sc^(1/6))^(9/2))^(2/9);
    C1 := 3.24;
    C3 := 0.409;
  else
    fSc := 0.886/(1+(1.909*Sc^(1/6))^(9/2))^(2/9);
    C1 := 3.86;
    C3 := 0.501;
  end if;

  if local == true then
    C2 := 1;
    C4 := 1;
  else
    C2 := 1.5;
    C4 := 2;
  end if;

  // Definition of product of reynolds and friciton factor
  fRe := 12/(sqrt(aspRat) * (1+aspRat) * (1 - (192*aspRat)/(pi^5) * tanh(pi/(2*aspRat))));

  //Calculation of Nusselt number
  Sh := (((C4 * fSc)/sqrt(zStern))^m + ((C2 * C3 * (fRe/zStern)^(1/3))^5 + (C1 * (fRe/(8 * sqrt(pi)*aspRat^gamma)))^5)^(m/5))^(1/m)

  ;
end SherwoodNumberMuzychka;

within AixLib.Fluid.Sensors;
model MassFractionTwoPort "Ideal two port mass fraction sensor"
  extends AixLib.Fluid.Sensors.BaseClasses.PartialDynamicFlowSensor(
    redeclare replaceable package Medium =
        Modelica.Media.Interfaces.PartialCondensingGases);
  extends AixLib.Fluid.BaseClasses.IndexMassFraction(substanceName = "water");
  extends Modelica.Icons.RoundSensor;

  parameter Medium.MassFraction X_start=Medium.X_default[i_x]
    "Initial or guess value of output (= state)"
    ;

  Modelica.Blocks.Interfaces.RealOutput X(min=-1e-3,
                                          max=1.001,
                                          start=X_start,
                                          final unit="kg/kg")
    "Mass fraction of the passing fluid"
    ;

protected
  Medium.MassFraction XMed(start=X_start)
    "Mass fraction to which the sensor is exposed";
  Medium.MassFraction XiVec[Medium.nXi](
    final quantity=Medium.substanceNames[1:Medium.nXi])
    "Mass fraction vector, needed because indexed argument for the operator inStream is not supported";
initial equation
  // Assign initial conditions
  if dynamic then
    if initType == Modelica.Blocks.Types.Init.SteadyState then
      der(X) = 0;
     elseif initType == Modelica.Blocks.Types.Init.InitialState or
           initType == Modelica.Blocks.Types.Init.InitialOutput then
      X = X_start;
    end if;
  end if;
equation
  if allowFlowReversal then
    XiVec = Modelica.Fluid.Utilities.regStep(
              x=port_a.m_flow,
              y1=port_b.Xi_outflow,
              y2=port_a.Xi_outflow,
              x_small=m_flow_small);
  else
    XiVec = port_b.Xi_outflow;
  end if;
  XMed = if i_x > Medium.nXi then (1-sum(XiVec)) else XiVec[i_x];
  // Output signal of sensor
  if dynamic then
    der(X)  = (XMed-X)*k*tauInv;
  else
    X = XMed;
  end if
;
end MassFractionTwoPort;

within AixLib.Obsolete.YearIndependent.FastHVAC.Components.HeatGenerators.CHP;
model CHP_PT1 "Simple general CHP model"
extends AixLib.Obsolete.BaseClasses.ObsoleteModel;

 /* *******************************************************************
      BHKW Parameters
      ******************************************************************* */
    parameter Boolean selectable=true "CHP record";

    parameter FastHVAC.Data.CHP.BaseDataDefinition param=
      FastHVAC.Data.CHP.Ecopower()
    "Paramter contains data from CHP records" ;

  parameter Modelica.Units.SI.Efficiency eta_el=0.25
    "CHP's electrical efficiency "
    ;
  parameter Modelica.Units.SI.Efficiency eta_th=0.65
    "CHP's thermal efficiency "
    ;

    parameter FastHVAC.Media.BaseClasses.MediumSimple medium=
      FastHVAC.Media.WaterSimple()
    "Standard flow charastics for water (heat capacity, density, thermal conductivity)"
    ;
    constant Real LHV(unit="J/kg")=47300000 "Lower heating value [J/kg]";
protected
  parameter Modelica.Units.SI.Volume V_water=3e-3 "Water volume inside the CHP";
public
  parameter Modelica.Units.SI.Temperature T0=
      Modelica.Units.Conversions.from_degC(20) "Initial temperature ";
  parameter Modelica.Units.SI.Power capP_el=1000 "CHPs electrical capacity"
    ;
 /* *******************************************************************
      Variables
      ******************************************************************* */

  Modelica.Units.SI.Efficiency eff_tot "Total efficiency ";
  Modelica.Units.SI.HeatFlowRate Q_th "Thermal power";
  Modelica.Units.SI.MassFlowRate dotm_fuel "Fuel mass flow rate ";
  Modelica.Units.SI.HeatFlowRate dotE_fuel "Fuel energy consumption ";
  Modelica.Units.SI.Efficiency eff_el "CHP's electrical efficiency ";
  Modelica.Units.SI.Efficiency eff_th "CHP's thermal efficiency ";
  Modelica.Units.SI.Power P_el "Capacity ";

    Real sigma(  start=0.4) "Nominal power to heat ratio";
  /* *******************************************************************
      Components
      ******************************************************************* */

    Modelica.Blocks.Continuous.FirstOrder firstOrderQ_th(T=param.tauQ_th,
    y_start=0,
    initType=Modelica.Blocks.Types.Init.SteadyState)
    "dynamic behavior of thermal power output [W]"
    ;
    Modelica.Blocks.Continuous.FirstOrder firstOrderP_el(T=param.tauP_el,
    y_start=0,
    initType=Modelica.Blocks.Types.Init.SteadyState)
    "dynamic behavior of electrical power output [W]"
    ;
    FastHVAC.BaseClasses.WorkingFluid fluidCHP(
    medium=medium,
    m_fluid=V_water*medium.rho,
    T0=T0)
    ;
    Modelica.Thermal.HeatTransfer.Sources.PrescribedHeatFlow
                                  varHeatFlow
      ;
    Modelica.Blocks.Interfaces.BooleanInput onOff "CHP on/off switch"
      ;
    FastHVAC.Interfaces.EnthalpyPort_b enthalpyPort_b
    ;

    FastHVAC.Interfaces.EnthalpyPort_a enthalpyPort_a ;

    Modelica.Blocks.Interfaces.RealOutput Energy[3](each unit="J")
    "1=W_el 2=Q_th 3=E_fuel"
    ;
    Modelica.Blocks.Continuous.Integrator integrator[3]
      ;
    Modelica.Blocks.Interfaces.RealOutput Capacity[3](each unit="W")
    "1=P_el 2=dotQ_th 3=dotE_fuel" ;
  FastHVAC.Components.Controller.SwitchCounter switchCounter
    ;
  FastHVAC.Components.Sensors.MassFlowSensor massFlowRate ;
  FastHVAC.Components.Sensors.TemperatureSensor T_flow ;
  FastHVAC.Components.Sensors.TemperatureSensor T_return ;

  Modelica.Blocks.Interfaces.RealInput P_elRel( unit="1")
    "Capacity of electrical power [0 to 1]"
    ;

equation
    integrator[1].u = P_el;
    integrator[2].u = Q_th;
    integrator[3].u = dotE_fuel;

      P_el = firstOrderP_el.y;
      Q_th = firstOrderQ_th.y;

       if onOff and selectable then
       eff_el =param.a_0 + param.a_1*(P_el/1000)^2 + param.a_2*(P_el/1000) +
      param.a_3*massFlowRate.dotm^2 + param.a_4*massFlowRate.dotm + param.a_5*
      Modelica.Units.Conversions.to_degC(T_return.T)^2 + param.a_6*
      Modelica.Units.Conversions.to_degC(T_return.T);
       eff_th =param.b_0 + param.b_1*(P_el/1000)^2 + param.b_2*(P_el/1000) +
      param.b_3*massFlowRate.dotm^2 + param.b_4*massFlowRate.dotm + param.b_5*
      Modelica.Units.Conversions.to_degC(T_return.T)^2 + param.b_6*
      Modelica.Units.Conversions.to_degC(T_return.T);
       firstOrderQ_th.u = param.P_elRated*P_elRel / sigma;
       firstOrderP_el.u=param.P_elRated*P_elRel;
       sigma=eff_el/eff_th;
       dotE_fuel = P_el / eff_el;
       elseif onOff then  //CHP is on
       dotE_fuel = P_el / eff_el;
       sigma=eff_el/eff_th;
       eff_el=eta_el;
       eff_th=eta_th;
       firstOrderQ_th.u = capP_el*P_elRel / sigma;
       firstOrderP_el.u=capP_el*P_elRel;
     else //CHP is off
       eff_el=0;
       eff_th=0;
       firstOrderP_el.u=0;
       firstOrderQ_th.u = 0;
       sigma=0;
       dotE_fuel =0;
     end if;

    eff_tot = eff_th + eff_el;
    dotm_fuel = dotE_fuel / (LHV/1000);
    Capacity[3] = dotE_fuel;

  connect(onOff, switchCounter.u) ;
  connect(integrator.y, Energy) ;
  connect(firstOrderP_el.y, Capacity[1]);
  connect(firstOrderQ_th.y, Capacity[2]) ;
  connect(firstOrderQ_th.y, varHeatFlow.Q_flow) ;
  connect(fluidCHP.heatPort, varHeatFlow.port) ;
  connect(fluidCHP.enthalpyPort_b, T_return.enthalpyPort_a) ;
  connect(T_return.enthalpyPort_b, enthalpyPort_b) ;
  connect(T_flow.enthalpyPort_b, fluidCHP.enthalpyPort_a) ;
  connect(enthalpyPort_a, massFlowRate.enthalpyPort_a) ;
  connect(massFlowRate.enthalpyPort_b, T_flow.enthalpyPort_a) 
    ;
end CHP_PT1;

within AixLib.Utilities.Math;
block IntegerReplicator "Integer signal replicator"
  extends Modelica.Blocks.Icons.IntegerBlock;
  parameter Integer nout=1 "Number of outputs";
  Modelica.Blocks.Interfaces.IntegerInput u "Connector of integer input signal"
    ;
  Modelica.Blocks.Interfaces.IntegerOutput y[nout]
    "Connector of integer output signals"
    ;
equation
