within AixLib.Fluid.MassExchangers.MembraneBasedEnthalpyExchangers.BaseClasses.Functions;
function CoefficientCrossToCounterFlow
  "Calculates coefficient of efficiency of cross flow exchanger to counter flow exchanger based on NTU-method"
  input Real NTU "number of transfer units";
  output Real coeCroCou "coefficient for reduced efficiency in quasi-counter flow";
algorithm
  coeCroCou :=-9E-5*NTU^3 + 0.0023*NTU^2 - 0.0207*NTU + 0.956;
  // polynom calculated by curve fit for min(m_flow * cp)/max(m_flow * cp) = 1 with accuracy of 0,2 percent standard deviation
  ;
end CoefficientCrossToCounterFlow;

within AixLib.Utilities.Psychrometrics.Functions;
function X_pSatpphi "Humidity ratio for given water vapor pressure"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.AbsolutePressure pSat "Saturation pressure";
  input Modelica.Units.SI.Pressure p "Pressure of the fluid";
  input Real phi(min=0, max=1) "Relative humidity";
  output Modelica.Units.SI.MassFraction X_w(
    min=0,
    max=1,
    nominal=0.01) "Water vapor concentration per total mass of air";

protected
  constant Real k = 0.621964713077499 "Ratio of molar masses";
algorithm
  X_w := phi*k/(k*phi+p/pSat-phi)

  ;
end X_pSatpphi;

within AixLib.Utilities.Math.Functions;
function fallingFactorial "Returns the k-th falling factorial of n"
  extends Modelica.Icons.Function;
  input Integer n "Integer number";
  input Integer k "Falling factorial power";
  output Integer f "k-th falling factorial of n";
protected
  Integer maxInt = 2147483646 "Max 32-bit integer";
algorithm
  if k > n then
    f := 0;
  else
    f := 1;
    for i in 0:(k-1) loop
      assert(f <= maxInt/(n-i), "Integer overflow");
      f := f*(n-i);
    end for;
  end if

;
end fallingFactorial;

