within AixLib.Fluid.Sensors;
model DensityTwoPort "Ideal two port density sensor"
  extends AixLib.Fluid.Sensors.BaseClasses.PartialDynamicFlowSensor;
  extends Modelica.Icons.RoundSensor;
  Modelica.Blocks.Interfaces.RealOutput d(final quantity="Density",
                                          final unit="kg/m3",
                                          min=0) "Density of the passing fluid"
    ;
  parameter Medium.Density d_start=
     Medium.density(state=Medium.setState_pTX(
       p=p_start, T=T_start, X=X_start))
    "Initial or guess value of output (=state)"
    ;
  parameter Modelica.Units.SI.Temperature T_start=Medium.T_default
    "Temperature used to compute d_start"
    ;
  parameter Modelica.Units.SI.Pressure p_start=Medium.p_default
    "Pressure used to compute d_start"
    ;
  parameter Modelica.Units.SI.MassFraction X_start[Medium.nX]=Medium.X_default
    "Mass fraction used to compute d_start"
    ;
protected
  Medium.Density dMed(start=d_start)
    "Medium density to which the sensor is exposed";

  Medium.Density d_a_inflow "Density of inflowing fluid at port_a";
  Medium.Density d_b_inflow
    "Density of inflowing fluid at port_b, or rho_a_inflow if uni-directional flow";
initial equation
  if dynamic then
    if initType == Modelica.Blocks.Types.Init.SteadyState then
      der(d) = 0;
     elseif initType == Modelica.Blocks.Types.Init.InitialState or
           initType == Modelica.Blocks.Types.Init.InitialOutput then
      d = d_start;
    end if;
  end if;
equation
  if allowFlowReversal then
     d_a_inflow = Medium.density(
       state=Medium.setState_phX(p=port_b.p, h=port_b.h_outflow, X=port_b.Xi_outflow));
     d_b_inflow = Medium.density(
       state=Medium.setState_phX(p=port_a.p, h=port_a.h_outflow, X=port_a.Xi_outflow));
     dMed = Modelica.Fluid.Utilities.regStep(
       x=port_a.m_flow, y1=d_a_inflow, y2=d_b_inflow, x_small=m_flow_small);
  else
     dMed = Medium.density(
       state=Medium.setState_phX(p=port_b.p, h=port_b.h_outflow, X=port_b.Xi_outflow));
     d_a_inflow = dMed;
     d_b_inflow = dMed;
  end if;
  // Output signal of sensor
  if dynamic then
    der(d) = (dMed-d)*k*tauInv;
  else
    d = dMed;
  end if
;
end DensityTwoPort;

within AixLib.Controls.Continuous.Examples;
model LimPIDWithReset
  "Example that demonstrates the controller output reset"
  extends Modelica.Icons.Example;

  Plant plaWitRes "Plant connected to controller with reset" ;
  Controller conWitRes(reset=AixLib.Types.Reset.Parameter)
    "Controller with reset" ;
  Plant plaNoRes "Plant connected to controller without reset" ;
  Controller conNoRes(reset=AixLib.Types.Reset.Disabled)
    "Controller without reset" ;
  Modelica.Blocks.Sources.Pulse TSet(
    amplitude=20,
    width=50,
    offset=293.15,
    y(unit="K"),
    period=180)    "Temperature set point"
    ;

protected
  model Plant
    "Plant model"
    extends Modelica.Blocks.Icons.Block;

    Modelica.Blocks.Interfaces.RealInput Q_flow(unit="W")
      "Heat flow rate added to system"
      ;
    Modelica.Blocks.Interfaces.RealOutput T(unit="K")
      "Controlled temperature"
      ;

    Modelica.Thermal.HeatTransfer.Components.HeatCapacitor cap(
      C=10,
      T(fixed=true,
        start=293.15)) "Heat capacitor"
      ;
    Modelica.Thermal.HeatTransfer.Components.HeatCapacitor cap1(
      C=10,
      T(fixed=true,
          start=293.15)) "Heat capacitor"
      ;

    Modelica.Thermal.HeatTransfer.Sensors.TemperatureSensor temSen
      "Temperature sensor"
      ;
    Modelica.Thermal.HeatTransfer.Sources.PrescribedHeatFlow preHea
      "Prescribed heat flow rate"
      ;
    Modelica.Thermal.HeatTransfer.Components.ThermalConductor theCon(G=5)
      "Thermal conductor"
      ;
    Modelica.Thermal.HeatTransfer.Sources.FixedTemperature TBou(T=293.15)
      "Boundary condition"
      ;
    Modelica.Thermal.HeatTransfer.Components.ThermalConductor theCon1(G=1)
      "Thermal conductor"
      ;

  equation
    connect(Q_flow, preHea.Q_flow)
      ;
    connect(T, temSen.T)
      ;
    connect(TBou.port, theCon.port_a)
      ;
    connect(cap.port, theCon1.port_a)
      ;
    connect(theCon1.port_b, cap1.port)
      ;
    connect(cap1.port, temSen.port)
      ;
    connect(theCon.port_b, cap.port)
      ;
    connect(preHea.port, cap.port)

    ;
  end Plant;

  model Controller "PID controller with optional output reset"
    extends Modelica.Blocks.Icons.Block;

    parameter AixLib.Types.Reset reset=AixLib.Types.Reset.Disabled
      "Type of controller output reset";

    Modelica.Blocks.Interfaces.RealInput TSet(unit="K") "Temperature set point"
      ;

    Modelica.Blocks.Interfaces.RealInput u_m(unit="K")
      "Measured temperature"
      ;

    Modelica.Blocks.Interfaces.RealOutput y
      "Control signal"
      ;

    AixLib.Controls.Continuous.LimPID conPID(
      final reset=reset,
      yMax=1,
      yMin=0,
      Ti=1,
      k=10) "PI controller"
      ;
    Modelica.Blocks.Math.Gain gain(k=5000)
                                          "Gain for heat flow rate"
      ;
    Modelica.Blocks.Logical.GreaterThreshold trigger(threshold=303.15)
      "Trigger input for controller reset"
      ;

  equation
    connect(conPID.y,gain. u)
      ;
    connect(trigger.y,conPID. trigger) ;
    connect(u_m, conPID.u_m) ;
    connect(conPID.u_s, TSet) ;
    connect(trigger.u, TSet) ;
    connect(gain.y, y)

    ;
  end Controller;

equation
  connect(plaWitRes.T, conWitRes.u_m) ;
  connect(conWitRes.y, plaWitRes.Q_flow)
    ;

  connect(plaNoRes.T, conNoRes.u_m) ;
  connect(conNoRes.y, plaNoRes.Q_flow)
    ;
  connect(TSet.y, conWitRes.TSet) ;
  connect(TSet.y, conNoRes.TSet) 
 ;
end LimPIDWithReset;

