within AixLib.Fluid.HeatPumps.Calibration.BaseClasses;
model PartialWaterToWater
  "Partial model for calibration of water to water heat pumps"

  replaceable package Medium1 = Modelica.Media.Interfaces.PartialMedium
    "Medium model at the condenser side";

  replaceable package Medium2 = Modelica.Media.Interfaces.PartialMedium
    "Medium model at the evaporator side";

  replaceable package ref = AixLib.Media.Refrigerants.R410A
    "Refrigerant model";

  parameter Modelica.Units.SI.MassFlowRate m1_flow_nominal
    "Nominal mass flow rate on condenser side";
  parameter Modelica.Units.SI.MassFlowRate m2_flow_nominal
    "Nominal mass flow rate on evaporator side";

  parameter Modelica.Units.SI.Pressure dp1_nominal=1000
    "Pressure drop at nominal mass flow rate on condenser side";
  parameter Modelica.Units.SI.Pressure dp2_nominal=1000
    "Pressure drop at nominal mass flow rate on evaporator side";

  parameter Modelica.Units.SI.ThermalConductance UACon
    "Thermal conductance of condenser";

  parameter Modelica.Units.SI.ThermalConductance UAEva
    "Thermal conductance of evaporator";

  Modelica.Blocks.Sources.CombiTimeTable calDat(
    tableOnFile=true,
    columns=2:5)
    ;

  Modelica.Blocks.Routing.DeMultiplex4 splDat
    "De-multiplex"
    ;

  AixLib.Fluid.Sources.Boundary_pT sin2(
    redeclare final package Medium = Medium2,
    nPorts=1) "Boundary condition"
    ;
  Modelica.Fluid.Sources.MassFlowSource_T Sou(
    redeclare final package Medium = Medium2,
    nPorts=1,
    use_m_flow_in=true,
    use_T_in=true)
    "Mass flow source"
    ;
  AixLib.Fluid.Sources.Boundary_pT sin1(
    redeclare final package Medium = Medium1,
    nPorts=1) "Pressure boundary condition"
    ;

  Modelica.Fluid.Sources.MassFlowSource_T loa(
    redeclare final package Medium = Medium1,
    nPorts=1,
    use_m_flow_in=true,
    use_T_in=true) "Mass flow source"
    ;

  replaceable AixLib.Fluid.HeatPumps.BaseClasses.PartialWaterToWater heaPum
    constrainedby AixLib.Fluid.HeatPumps.BaseClasses.PartialWaterToWater(
    redeclare final package Medium1 = Medium1,
    redeclare final package Medium2 = Medium2,
    redeclare final package ref = ref,
    final m1_flow_nominal=m1_flow_nominal,
    final m2_flow_nominal=m2_flow_nominal,
    final dp1_nominal=dp1_nominal,
    final dp2_nominal=dp2_nominal,
    enable_variable_speed=false,
    show_T=true)
    ;

  Modelica.Blocks.Sources.IntegerConstant isOn(k=1)
    "Control signal"
    ;

equation
  connect(calDat.y, splDat.u)
    ;
  connect(splDat.y1[1], Sou.T_in) ;
  connect(splDat.y3[1], Sou.m_flow_in) ;
  connect(splDat.y4[1],loa.m_flow_in)  ;
  connect(loa.ports[1], heaPum.port_a1) ;
  connect(sin2.ports[1], heaPum.port_b2) ;
  connect(Sou.ports[1], heaPum.port_a2)
    ;
  connect(sin1.ports[1], heaPum.port_b1) ;
  connect(splDat.y2[1],loa.T_in)  ;

  connect(isOn.y, heaPum.stage) 
  ;
end PartialWaterToWater;

within AixLib.Fluid.HeatExchangers.Examples.BaseClasses;
partial model EffectivenessNTUMassFlow
  "Partial model of epsilon-NTU coil that tests variable mass flow rates"
  package Medium1 = AixLib.Media.Water "Medium model for water";
  package Medium2 = AixLib.Media.Air
    "Medium model for air";
  parameter Modelica.Units.SI.Temperature T_a1_nominal=5 + 273.15
    "Nominal water inlet temperature";
  parameter Modelica.Units.SI.Temperature T_b1_nominal=10 + 273.15
    "Nominal water outlet temperature";
  parameter Modelica.Units.SI.Temperature T_a2_nominal=30 + 273.15
    "Nominal air inlet temperature";
  parameter Modelica.Units.SI.Temperature T_b2_nominal=15 + 273.15
    "Nominal air outlet temperature";
  parameter Modelica.Units.SI.HeatFlowRate Q_flow_nominal=m1_flow_nominal*4200*
      (T_a1_nominal - T_b1_nominal) "Nominal heat transfer";
  parameter Modelica.Units.SI.MassFlowRate m1_flow_nominal=0.1
    "Nominal mass flow rate medium 1";
  parameter Modelica.Units.SI.MassFlowRate m2_flow_nominal=m1_flow_nominal*4200
      /1000*(T_a1_nominal - T_b1_nominal)/(T_b2_nominal - T_a2_nominal)
    "Nominal mass flow rate medium 2";
  AixLib.Fluid.Sources.MassFlowSource_T sin_2(
    redeclare package Medium = Medium2,
    T=T_a2_nominal,
    use_m_flow_in=true) "Sink for air"
    ;
  AixLib.Fluid.Sources.Boundary_pT sou_2(
    redeclare package Medium = Medium2,
    T=T_a2_nominal,
    X={0.02,1 - 0.02},
    use_T_in=true,
    use_X_in=true) "Source for air"
    ;
  AixLib.Fluid.Sources.MassFlowSource_T sin_1(
    redeclare package Medium = Medium1,
    T=T_a1_nominal,
    use_m_flow_in=true) "Sink for water"
    ;
  AixLib.Fluid.Sources.Boundary_pT sou_1(
    redeclare package Medium = Medium1,
    use_T_in=false,
    T=T_a1_nominal) "Source for water"
    ;

  Modelica.Blocks.Sources.Constant relHum(k=0.8) "Relative humidity"
    ;
  AixLib.Utilities.Psychrometrics.X_pTphi x_pTphi(use_p_in=false)
    ;
  Modelica.Blocks.Sources.Constant temSou_2(k=T_a2_nominal)
    "Temperature boundary condition"
    ;
  Modelica.Blocks.Math.Gain mWat_flow(k=-m1_flow_nominal)
    "Water mass flow rate"
    ;
  Modelica.Blocks.Sources.TimeTable mWatGai(
    table=[0,1; 0.1,1; 0.2,0.01; 0.3,0.01],
    timeScale=3600)
    "Gain for water mass flow rate"
    ;
  Modelica.Blocks.Sources.TimeTable mAirGai(
    table=[0,1; 0.5,1; 0.6,-1; 0.7,0; 1,0],
    timeScale=3600)
    "Gain for air mass flow rate"
    ;
  Modelica.Blocks.Math.Gain mAir_flow(k=-m2_flow_nominal) "Air mass flow rate"
    ;
equation
  connect(x_pTphi.X, sou_2.X_in) ;
  connect(relHum.y, x_pTphi.phi) ;
  connect(temSou_2.y, x_pTphi.T) ;
  connect(temSou_2.y, sou_2.T_in) ;
  connect(mWatGai.y, mWat_flow.u) ;
  connect(mWat_flow.y, sin_1.m_flow_in) ;
  connect(mAirGai.y, mAir_flow.u) ;
  connect(mAir_flow.y, sin_2.m_flow_in) 
  ;
end EffectivenessNTUMassFlow;

