    ;
  Modelica.Thermal.HeatTransfer.Sources.FixedTemperature TWes(T=298.15)
    "Fixed temperature"
    ;
  Modelica.Thermal.HeatTransfer.Sources.FixedTemperature TEas(T=293.15)
    "Fixed temperature"
    ;
