within AixLib.Fluid.HeatExchangers.ActiveBeams.BaseClasses;
model DerivativesCubicSpline "Cubic spline for interpolation"
  extends Modelica.Blocks.Icons.Block;
  parameter Real[:] xd={0,0.5,1};
  parameter Real[size(xd, 1)] yd={0,0.75,1};

  Modelica.Blocks.Interfaces.RealInput u
    "Independent variable for interpolation"
    ;
  Modelica.Blocks.Interfaces.RealOutput y "Interpolated value"
    ;
protected
  parameter Real[size(xd, 1)] dMonotone(each fixed=false) "Derivatives";
  Integer i "Counter to pick the interpolation interval";

initial algorithm
  // Get the derivative values at the support points

  dMonotone := AixLib.Utilities.Math.Functions.splineDerivatives(
    x=xd,
    y=yd,
    ensureMonotonicity=true);

algorithm
  i := 1;
  for j in 1:size(xd, 1) - 1 loop
    if u > xd[j] then
      i := j;
    end if;
  end for;
  // Extrapolate or interpolate the data
  y :=
    AixLib.Utilities.Math.Functions.cubicHermiteLinearExtrapolation(
    x=u,
    x1=xd[i],
    x2=xd[i + 1],
    y1=yd[i],
    y2=yd[i + 1],
    y1d=dMonotone[i],
    y2d=dMonotone[i + 1])
;
end DerivativesCubicSpline;

within AixLib.Obsolete.YearIndependent.FastHVAC.Components.Pumps;
model FluidSource " Ideal fluid source "
  extends AixLib.Obsolete.BaseClasses.ObsoleteModel;

  /* *******************************************************************
      Medium
     ******************************************************************* */

  parameter FastHVAC.Media.BaseClasses.MediumSimple medium=
      FastHVAC.Media.WaterSimple()
    "Standard  charastics for water (heat capacity, density, thermal conductivity)"
    ;
protected
  parameter Modelica.Units.SI.SpecificHeatCapacity cp=medium.c
    "medium's specific heat capacity";
  /* *******************************************************************
      Components
     ******************************************************************* */

public
  FastHVAC.Interfaces.EnthalpyPort_b enthalpyPort_b
    "Thermal port for output values (temperature, mass flow rate, specific enthalpy, constant specific heat capacity)"
    ;
  Modelica.Blocks.Interfaces.RealInput T_fluid( unit="K")
    "External real input to set the temperature of the fluid"
    ;
  Modelica.Blocks.Interfaces.RealInput dotm( unit="kg/s")
    "External real input to set the mass flow rate"
    ;
equation
  // balances
