model Distributor "Heating circuit distributor for underfloor heating systems"
  extends AixLib.Fluid.Interfaces.LumpedVolumeDeclarations;

  //General
  parameter Integer n(min=1) "Number of underfloor heating circuits / registers"
    ;

  parameter Modelica.Units.SI.MassFlowRate m_flow_nominal
    "Nominal mass flow rate" ;

  parameter Modelica.Units.SI.Time tau=10
    "Time constant at nominal flow (if energyDynamics <> SteadyState)"
    ;

  // Assumptions
  parameter Boolean allowFlowReversal=true
    "= false to simplify equations, assuming, but not enforcing, no flow reversal"
    ;

  Modelica.Fluid.Interfaces.FluidPort_a mainFlow(redeclare final package Medium =
               Medium)
    ;

  Modelica.Fluid.Interfaces.FluidPort_b mainReturn(redeclare final package Medium =
               Medium) ;
  MixingVolumes.MixingVolume vol_flow(
    final nPorts=n + 1,
    final m_flow_nominal=m_flow_nominal,
    final V=m_flow_nominal*tau/rho_default,
    redeclare final package Medium = Medium,
    final energyDynamics=energyDynamics,
    final massDynamics=massDynamics,
    final p_start=p_start,
    final T_start=T_start,
    final X_start=X_start,
    final C_start=C_start,
    final mSenFac=mSenFac,
    each final C_nominal=C_nominal,
    final allowFlowReversal=allowFlowReversal) ;
  MixingVolumes.MixingVolume vol_return(
    final nPorts=n + 1,
    final m_flow_nominal=m_flow_nominal,
    final V=m_flow_nominal*tau/rho_default,
    redeclare final package Medium = Medium,
    final energyDynamics=energyDynamics,
    final massDynamics=massDynamics,
    final p_start=p_start,
    final T_start=T_start,
    final X_start=X_start,
    final C_start=C_start,
    final mSenFac=mSenFac,
    each final C_nominal=C_nominal,
    final allowFlowReversal=allowFlowReversal) ;
  Modelica.Fluid.Interfaces.FluidPorts_b flowPorts[n](redeclare each final
      package                                                                      Medium =
                       Medium) ;
  Modelica.Fluid.Interfaces.FluidPorts_a returnPorts[n](redeclare each final
      package                                                                        Medium =
                       Medium) ;

protected
  parameter Medium.ThermodynamicState sta_default=Medium.setState_pTX(
      T=Medium.T_default,
      p=Medium.p_default,
      X=Medium.X_default);
  parameter Modelica.Units.SI.Density rho_default=Medium.density(sta_default)
    "Density, used to compute fluid volume";
equation
  connect(mainFlow, vol_flow.ports[1]) ;
  connect(mainReturn, vol_return.ports[1]) ;

  for k in 1:n loop
    connect(vol_flow.ports[k + 1], flowPorts[k])
      ;
    connect(vol_return.ports[k + 1], returnPorts[k])
      ;
  end for

  ;
end Distributor;

within AixLib.Obsolete.YearIndependent.Utilities;
package HeatTransfer "\"Models for different types of heat transfer\""
  extends Modelica.Icons.Package;
  model HeatConvPipeInside
    "Model for Heat Transfer through convection inside a pipe, based on Nussel Correlations"
    extends AixLib.Obsolete.BaseClasses.ObsoleteModel;
    extends Modelica.Thermal.HeatTransfer.Interfaces.Element1D;
    parameter Modelica.Units.SI.Length length(min=0) "length of total pipe";
    parameter Modelica.Units.SI.Length d_i(min=0) "inner diameter of pipe";
    parameter Modelica.Units.SI.Length d_a(min=0) "outer diameter of pipe";
    parameter Modelica.Units.SI.Area A_sur(min=0) "surface for heat transfer";
    parameter Boolean calcHCon=true "Use calculated value for inside heat coefficient";
    parameter Modelica.Units.SI.CoefficientOfHeatTransfer hConIn_const=30
      "Constant convective heat transfer coefficient (Inside)"
      ;
    parameter Obsolete.YearIndependent.FastHVAC.Media.BaseClasses.MediumSimple
      medium=Obsolete.YearIndependent.FastHVAC.Media.WaterSimple();
    Modelica.Units.SI.ReynoldsNumber Re;
    Modelica.Units.SI.Velocity v;
    Modelica.Units.SI.NusseltNumber Nu;
    Modelica.Units.SI.NusseltNumber Nu_lam_1;
    Modelica.Units.SI.NusseltNumber Nu_lam_2;
    Modelica.Units.SI.NusseltNumber Nu_lam;
    Modelica.Units.SI.NusseltNumber Nu_tur;
    Modelica.Units.SI.PrandtlNumber Pr;
    Modelica.Units.SI.CoefficientOfHeatTransfer hCon
      "Convective heat transfer coefficient";
    Real zeta "pressure loss coefficient";

    Modelica.Blocks.Interfaces.RealInput m_flow ;
  equation
    if calcHCon then
      v      =        4*m_flow/(Modelica.Constants.pi * d_i^2 * medium.rho);
      Re     =    Modelica.Fluid.Pipes.BaseClasses.CharacteristicNumbers.ReynoldsNumber(
        v,medium.rho,medium.eta, d_i)
                                     "Reynolds numbers";
      Pr     =        medium.eta *medium.c /medium.lambda;
      zeta   =        (1.8*log10(max(1e-10,Re))-1.5)^(-2);
      Nu_lam_1 =      3.66;
      Nu_lam_2 =      1.615 * (Re*Pr*d_i/length)^(1/3);
      Nu_lam   =      (Nu_lam_1^3 + 0.7^3 + (Nu_lam_2 - 0.7)^3)^(1/3);
      Nu_tur   =      (zeta/8*Re*Pr)/(1+12.7*(zeta/8)^0.5*(Pr^(2/3)-1))*(1+(d_i/length)^(2/3));
      Nu       =      smooth(0,if Re<=2300 then Nu_lam else Nu_tur);
    else
      //prevent solver from solving the equations if they are not used
      v=0;
      Re=0;
      Pr=0;
      zeta=0;
      Nu_lam_1=0;
      Nu_lam_2=0;
      Nu_lam=0;
      Nu_tur=0;
      Nu=0;
      end if;
    hCon = if calcHCon then Nu*medium.lambda/d_i else hConIn_const;
    port_a.Q_flow =hCon*A_sur*(port_a.T - port_b.T)

    ;
  end HeatConvPipeInside;
end HeatTransfer;

within AixLib.Fluid.MassExchangers.MembraneBasedEnthalpyExchangers.BaseClasses.MassTransfer;
model CrossFlowReduction
  "model that calculates reduction factor for mass transfer in quasi-counter flow arrangement"

  // Parameters
  parameter Integer n=1 "number of discrete elements in flow direction";
  parameter Integer nParallel=1 "number of parallel membranes";

  parameter Modelica.Units.SI.Length thicknessMem "thickness of membranes";
  parameter Modelica.Units.SI.Area[n] surfaceAreas "Heat transfer areas";
  parameter Real aspRatCroToTot "ratio of cross flow of air duct";

  // Constants
  constant Real C_conv = 3.35*10^(-16)
    "conversion factor for permeance to calculate SI-units from Barrer";
  constant Modelica.Units.SI.MolarMass M_steam=0.01802;

  // Variables
  Real[n] k_tots "total mass transfer coefficient";
  Real[n] NTUs "number of heat transfer units";

  // Inputs
  Modelica.Blocks.Interfaces.RealInput perMem(unit="mol/(m.s.Pa)")
    "membrane permeability in Barrer";
  input Real[n] kCons1
    "convective mass transfer coefficients of air flow 1";
  input Real[n] kCons2
    "convective mass transfer coefficients of air flow 2";
  input Modelica.Units.SI.MassFlowRate m_flow1 "mass flow rate of air flow 1";
  input Modelica.Units.SI.MassFlowRate m_flow2 "mass flow rate of air flow 2";

  // Outputs
  Modelica.Blocks.Interfaces.RealOutput[n] coeCroCous
    "coefficient for heat transfer reduction due to cross-flow portion";

equation

  for i in 1:n loop
    1/k_tots[i] = 1/kCons1[i]+thicknessMem/(perMem*C_conv*M_steam)+1/kCons2[i];
    NTUs[i] = k_tots[i]*(surfaceAreas[i]*nParallel)/min(m_flow1,m_flow2);
    coeCroCous[i] = BaseClasses.Functions.CoefficientCrossToCounterFlow(NTUs[i])*
      aspRatCroToTot + (1 - aspRatCroToTot);
  end for

  ;
end CrossFlowReduction;

