    final n=order,
    final f=fCut,
    final normalized=true,
    final initType=init,
    final y_start=y_start) if use_inputFilter
    "Second order filter to approximate actuator opening time, and to improve numerics"
    ;

equation
  connect(filter.y, y_filtered)
    ;
