model ConservationEquation "Model that tests the conservation equation"
extends Modelica.Icons.Example;
 package Medium = AixLib.Media.Water "Medium model";
  AixLib.Fluid.Interfaces.ConservationEquation dyn(
    redeclare package Medium = Medium,
    energyDynamics=Modelica.Fluid.Types.Dynamics.FixedInitial,
    nPorts=2,
    fluidVolume=0.01,
    use_mWat_flow=true) "Dynamic conservation equation"
    ;

  AixLib.Fluid.Interfaces.StaticTwoPortConservationEquation ste(
    redeclare package Medium = Medium,
    m_flow_nominal=0.01,
    show_T=true,
    prescribedHeatFlowRate=true,
    use_mWat_flow=true) "Steady-state conservation equation"
    ;

  Modelica.Blocks.Sources.Constant mWat_flow(k=0)
    "Water mass flow rate added to the control volume"
    ;
  Modelica.Blocks.Sources.TimeTable QSen_flow(startTime=0, table=[
                                0,-100;
                                900,-100;
                                900,0;
                                1800,0;
                                1800,100])
    "Sensible heat flow rate added to the control volume"
    ;
  AixLib.Fluid.Sources.Boundary_pT sin(
    nPorts=2,
    use_p_in=false,
    redeclare package Medium = Medium,
    p=101325,
    T=283.15)
      ;
  AixLib.Fluid.FixedResistances.PressureDrop res1(
    from_dp=true,
    redeclare package Medium = Medium,
    m_flow_nominal=0.01,
    dp_nominal=100) "Flow resistance"
    ;
  AixLib.Fluid.Sources.MassFlowSource_T bou(
    nPorts=2,
    redeclare package Medium = Medium,
    m_flow=0.01) "Boundary condition for mass flow rate"
    ;
  AixLib.Fluid.FixedResistances.PressureDrop res2(
    from_dp=true,
    redeclare package Medium = Medium,
    m_flow_nominal=0.01,
    dp_nominal=100) "Flow resistance"
    ;

equation
  connect(QSen_flow.y, dyn.Q_flow) ;
  connect(mWat_flow.y, dyn.mWat_flow) ;

  connect(bou.ports[1], dyn.ports[1]) ;
  connect(res1.port_b, sin.ports[1]) ;
  connect(QSen_flow.y, ste.Q_flow) ;
  connect(mWat_flow.y, ste.mWat_flow) ;
  connect(res2.port_b, sin.ports[2]) ;
  connect(ste.port_a, bou.ports[2]) ;
  connect(ste.port_b, res2.port_a) ;
  connect(dyn.ports[2], res1.port_a) 
  ;
end ConservationEquation;

