within AixLib.ThermalZones.ReducedOrder.Windows.BaseClasses;
block VentilationHeat "heat input due to ventilation with closed sunblind"
  extends Modelica.Blocks.Icons.Block;
  parameter Real x_f(min=0,max=1) "Percentage of open windowarea"
    ;
  parameter Modelica.Units.SI.Distance d "Distance sunscreen to window"
    ;
  parameter Boolean screen "If screen: true, if blind: false"
    ;
  parameter Modelica.Units.SI.TransmissionCoefficient tau_e
    "Transmission coefficient of sunscreen"
    ;
  parameter Modelica.Units.SI.ReflectionCoefficient rho_e
    "Reflection coefficient of sunscreen" ;
  parameter Modelica.Units.SI.Angle til(displayUnit="deg") "Surface tilt. til=90 degree for walls; til=0 for ceilings; til=180 for
    roof" ;

   Modelica.Blocks.Interfaces.BooleanInput sunscreen
    "True: sunscreen closed, false: sunscreen open"
    ;
   Modelica.Blocks.Interfaces.RealInput HDirTil(final quantity=
     "RadiantEnergyFluenceRate", final unit="W/m2")
    "Direct radiation on a tilted surface"
   ;
   Modelica.Blocks.Interfaces.RealInput HDifTil(final quantity=
   "RadiantEnergyFluenceRate", final unit="W/m2")
    "Diffuse radiation on a tilted surface"
   ;
   Modelica.Blocks.Interfaces.RealInput HDifHor(final quantity=
     "RadiantEnergyFluenceRate",final unit="W/m2")
    "Diffuse radiation on horizontal surface"
   ;
   Modelica.Blocks.Interfaces.RealInput HDirNor(final quantity=
     "RadiantEnergyFluenceRate",final unit="W/m2")
    "Direct radiation on horizontal surface"
   ;
  Modelica.Blocks.Interfaces.RealOutput HVen(final quantity=
    "RadiantEnergyFluenceRate", final unit="W/m2")
    "Heat input due to ventilation"
    ;
  Modelica.Blocks.Interfaces.RealInput alt(
    final quantity="Angle",
    final unit="rad",
    displayUnit="deg") "Solar altitude angle"
    ;

  parameter Modelica.Units.SI.ReflectionCoefficient rho=0.2 "Ground reflection";
protected
   Real factor_gv "Calculation factor";

equation
  //calculating factor_gv
  if d<=0.15 and screen then
     factor_gv=0.35;
  elseif d<=0.4 and d>0.15 and screen then factor_gv=0.17;
  elseif d<=0.15 and screen==false then factor_gv=0.2;
  elseif d>0.15 and d<=0.4 and screen==false then factor_gv=0.1;
  else factor_gv=0;
  end if;
  //calculating Output HVen
  if sunscreen then
    HVen=(HDirTil+HDifTil+(HDifHor+HDirNor*Modelica.Math.sin(alt))*0.5*rho*
    (1-Modelica.Math.cos(
    AixLib.ThermalZones.ReducedOrder.Windows.BaseClasses.Conversions.to_surfaceTiltVDI(
    til))))*(1-rho_e-tau_e)*factor_gv*
    x_f;
  else
    HVen=0;
  end if
  ;
end VentilationHeat;

within AixLib.ThermalZones.ReducedOrder.Windows.Validation.BaseClasses;
model SolarHourAngleVDI6007 "Calculates the solar hour angle every hour based
  on the equations of VDI 6007 part 3. It is modelled to test other Models
   based on VDI2078. It doesn't consider summer time"

  extends Modelica.Blocks.Icons.Block;
  parameter Modelica.Units.SI.Angle lon "Longitude";
  Modelica.Units.SI.Angle J_ "Daily Angle for 105th day of the year";
  Modelica.Units.SI.Time zgl "Time equation";
  Modelica.Units.SI.Time woz "True time";
  Modelica.Blocks.Interfaces.RealOutput solHouAng(
    final quantity="Angle",
    final unit="rad",
    displayUnit="deg") "Solar hour angle"
    ;
protected
  constant Modelica.Units.SI.Time day=86400 "Number of seconds in a day";
equation
  J_=Modelica.Units.Conversions.from_deg(360*105/365);
  zgl=0.0066 + 7.3525*Modelica.Math.cos(J_ +
    Modelica.Units.Conversions.from_deg(85.9)) + 9.9359*Modelica.Math.cos(2*J_
     + Modelica.Units.Conversions.from_deg(108.9)) + 0.3387*Modelica.Math.cos(3
    *J_ + Modelica.Units.Conversions.from_deg(105.2));
    woz=(integer(time/3600) - 0.5 - integer(time/day)*24) - 4*(15 -
    Modelica.Units.Conversions.to_deg(lon))/60 + zgl/60;
  solHouAng=(12-woz)*2*Modelica.Constants.pi/24
  ;
end SolarHourAngleVDI6007;

within AixLib.Fluid.Actuators.BaseClasses;
partial model PartialTwoWayValveKv
  "Partial model for a two way valve using a Kv characteristic"
  extends AixLib.Fluid.Actuators.BaseClasses.PartialTwoWayValve;

equation
 kVal = phi*Kv_SI;
 if (dpFixed_nominal > Modelica.Constants.eps) then
   k = sqrt(1/(1/kFixed^2 + 1/kVal^2));
 else
   k = kVal;
 end if;

 if linearized then
   // This implementation yields m_flow_nominal = phi*kv_SI * sqrt(dp_nominal)
   // if m_flow = m_flow_nominal and dp = dp_nominal
   m_flow*m_flow_nominal_pos = k^2 * dp;
 else
   if homotopyInitialization then
     if from_dp then
         m_flow=homotopy(actual=AixLib.Fluid.BaseClasses.FlowModels.basicFlowFunction_dp(dp=dp, k=k,
                                m_flow_turbulent=m_flow_turbulent),
                                simplified=m_flow_nominal_pos*dp/dp_nominal_pos);
      else
         dp=homotopy(actual=AixLib.Fluid.BaseClasses.FlowModels.basicFlowFunction_m_flow(m_flow=m_flow, k=k,
                                m_flow_turbulent=m_flow_turbulent),
                                simplified=dp_nominal_pos*m_flow/m_flow_nominal_pos);
     end if;
   else // do not use homotopy
     if from_dp then
       m_flow=AixLib.Fluid.BaseClasses.FlowModels.basicFlowFunction_dp(dp=dp, k=k,
                                m_flow_turbulent=m_flow_turbulent);
      else
        dp=AixLib.Fluid.BaseClasses.FlowModels.basicFlowFunction_m_flow(m_flow=m_flow, k=k,
                                m_flow_turbulent=m_flow_turbulent);
      end if;
    end if; // homotopyInitialization
 end if; // linearized
  ;
end PartialTwoWayValveKv;

within AixLib.Fluid.Sensors;
model RelativePressure "Ideal relative pressure sensor"
  extends Modelica.Icons.RectangularSensor;
  replaceable package Medium =
    Modelica.Media.Interfaces.PartialMedium "Medium in the sensor"
      ;

  Modelica.Fluid.Interfaces.FluidPort_a port_a(m_flow(min=0),
                                p(start=Medium.p_default),
                                redeclare package Medium = Medium)
    "Fluid connector of stream a"
    ;
  Modelica.Fluid.Interfaces.FluidPort_b port_b(m_flow(min=0),
                                p(start=Medium.p_default),
                                redeclare package Medium = Medium)
    "Fluid connector of stream b"
    ;

  Modelica.Blocks.Interfaces.RealOutput p_rel(final quantity="PressureDifference",
                                              final unit="Pa",
                                              displayUnit="Pa")
    "Relative pressure of port_a minus port_b" ;
equation
  // Zero flow equations for connectors
  port_a.m_flow = 0;
  port_b.m_flow = 0;

  // No contribution of specific quantities
  port_a.h_outflow = 0;
  port_b.h_outflow = 0;
  port_a.Xi_outflow = zeros(Medium.nXi);
  port_b.Xi_outflow = zeros(Medium.nXi);
  port_a.C_outflow  = zeros(Medium.nC);
  port_b.C_outflow  = zeros(Medium.nC);

  // Relative pressure
  p_rel = port_a.p - port_b.p
  ;
end RelativePressure;

