within AixLib.Fluid.Movers.Compressors.Utilities.EngineEfficiency;
model PowerEngineEfficiency
  "Model describing flow engine efficiency on power approach"
  extends PartialEngineEfficiency;

  // Definition of parameters
  //
  parameter Types.EnginePowerModels powMod=Types.EnginePowerModels.MendozaMirandaEtAl2016
    "Chose predefined power model for flow coefficient"
    ;
  parameter Real a
    "Multiplication factor for generic power approach"
    ;
  parameter Real b[:]
    "Exponents for each multiplier"
    ;
  parameter Integer nT = size(b,1)
    "Number of terms used for the calculation procedure"
    ;

  // Definition of further parameters required for special approaches
  //
  parameter Modelica.Units.SI.MolarMass MRef=0.1 "Reference molar wheight"
    ;
  parameter Modelica.Units.SI.Frequency rotSpeRef=9.334
    "Reference rotational speed"
    ;

  // Definition of coefficients
  //
  Real p[nT]
    "Array that contains all coefficients used for the calculation procedure";
  Real corFac[2]
    "Array of correction factors used if efficiency model proposed in literature
    differs from efficiency model defined in PartialCompressor model";

equation
  // Calculation of coefficients
  //
  if (powMod == Types.EnginePowerModels.MendozaMirandaEtAl2016) then
    /*Power approach presented by Mendoza et al. (2016):
      etaEng = piPre^b1 * (rotSpeRef/rotSpe)^b2 * (1/((TInl+TOutISe)/2-TOut))^b3
               * (MRef/M)^b4

      Caution with parameters - Uses isentropic specific enthalpy difference      
    */
    p[1] = piPre
      "Pressure ratio";
    p[2] = rotSpeRef/rotSpe
      "Rotational Speed";
    p[3] = 1/((Medium.temperature(staInl)+Medium.temperature(
      Medium.setState_psX(s=Medium.specificEntropy(staInl),
      p=Medium.pressure(staOut))))/2-TAmb)
      "Temperature difference isentropic compression and ambient";
    p[4] = MRef/Medium.fluidConstants[1].molarMass
      "Molar Mass";

    corFac = {1,1}
      "No correction factors are needed";

  else
    assert(false, "Invalid choice of power approach");
  end if;

  // Calculationg of flow coefficient
  //
  etaEng = min(1, corFac[1] * a *
    product(abs(p[i])^b[i] for i in 1:nT)^corFac[2])
    "Calculation procedure of generic power approach"

  ;
end PowerEngineEfficiency;

within AixLib.Airflow.Multizone.BaseClasses;
function windPressureLowRise "Wind pressure coefficient for low-rise buildings"
  extends Modelica.Icons.Function;

  input Real Cp0
    "Wind pressure coefficient for normal wind incidence angle";
  input Modelica.Units.SI.Angle alpha
    "Wind incidence angle (0: normal to wall)";
  input Real G "Natural logarithm of side ratio";
  output Real Cp "Wind pressure coefficient";
protected
  constant Modelica.Units.SI.Angle pi2=2*Modelica.Constants.pi;
  constant Modelica.Units.SI.Angle aRDel=5*Modelica.Constants.pi/180
    "Lower bound where transition occurs";
  constant Modelica.Units.SI.Angle aRDel2=aRDel/2
    "Half-width of transition interval";
  constant Modelica.Units.SI.Angle aRMax=175*Modelica.Constants.pi/180
    "Upper bound where transition occurs";
  Real a180 = Modelica.Math.log(1.248 - 0.703 +
              0.131*Modelica.Math.sin(2*Modelica.Constants.pi*G)^3
              + 0.071*G^2) "Attenuation factor at 180 degree incidence angle";

  Modelica.Units.SI.Angle aR "alpha, restricted to 0...pi";
  Modelica.Units.SI.Angle incAng2 "0.5*wind incidence angle";
  Real sinA2 "=sin(alpha/2)";
  Real cosA2 "=cos(alpha/2)";
  Real a "Attenuation factor";
algorithm
  // Restrict incAng to [0...pi]

  // Change sign to positive
  aR :=if alpha < 0 then -alpha else alpha;
  // Constrain to [0...2*pi]
  if aR > pi2 then
    aR := aR - integer(aR/pi2)*pi2;
  end if;
  // Constrain to [0...pi]
  if aR > Modelica.Constants.pi then
    aR := pi2-aR;
  end if;

  // Evaluate eqn. 2-1 from FSEC-CR-163-86
  incAng2 :=aR/2;
  sinA2 :=Modelica.Math.sin(incAng2);
  cosA2 :=Modelica.Math.cos(incAng2);
  // Implementation of the wind pressure coefficient that is once
  // continuously differentiable for all incidence angles
  if aR < aRDel then
    Cp :=Cp0*AixLib.Utilities.Math.Functions.regStep(
      y1=Modelica.Math.log(1.248 - 0.703*sinA2 - 1.175*Modelica.Math.sin(aR)^2
         + 0.131*Modelica.Math.sin(2*aR*G)^3 + 0.769*cosA2 + 0.071*G^2*sinA2^2
         + 0.717*cosA2^2),
      y2=1,
      x=aR - aRDel2,
      x_small=aRDel2);
  elseif aR > aRMax then
    Cp :=Cp0*AixLib.Utilities.Math.Functions.regStep(
      y1=a180,
      y2=Modelica.Math.log(1.248 - 0.703*sinA2 - 1.175*Modelica.Math.sin(aR)^2
         + 0.131*Modelica.Math.sin(2*aR*G)^3 + 0.769*cosA2 + 0.071*G^2*sinA2^2
         + 0.717*cosA2^2),
      x=aR + aRDel2 - Modelica.Constants.pi,
      x_small=aRDel2);
  else
    Cp :=Cp0*Modelica.Math.log(1.248 - 0.703*sinA2 - 1.175*Modelica.Math.sin(aR)^2 +
      0.131*Modelica.Math.sin(2*aR*G)^3 + 0.769*cosA2 + 0.071*G^2*sinA2^2 + 0.717*cosA2^2);
  end if
;
end windPressureLowRise;

