within AixLib.Fluid.HeatExchangers;
model DynamicHX "Simple dynamic heat exchanger model"
  extends Interfaces.FourPortHeatExchanger;

  parameter Modelica.Units.SI.Time tau_C=10
    "Time constant of heat capacity at nominal heat flow and temperature difference."
    ;
  parameter Modelica.Units.SI.TemperatureDifference dT_nom
    "Temperature difference at nominal conditions (used to calculate Gc)"
    ;
  Modelica.Thermal.HeatTransfer.Components.HeatCapacitor heatCapacitor[nNodes](
    each final C=Q_nom/dT_nom*tau_C/nNodes,
    each final T(fixed=true, start=TCapacity_start))
    ;
  parameter Modelica.Units.SI.HeatFlowRate Q_nom "Temperature difference at nominal conditions (used to calculate Gc)" ;
  parameter Modelica.Units.SI.Temperature TCapacity_start=(T1_start + T2_start)/2
    "Start value of temperature"
    ;
  parameter Modelica.Units.SI.ThermalConductance Gc1 = Q_nom/dT_nom*2/nNodes
    "Signal representing the convective thermal conductance in [W/K]" ;
  parameter Modelica.Units.SI.ThermalConductance Gc2 = Q_nom/dT_nom*2/nNodes
    "Signal representing the convective thermal conductance in [W/K]"  ;
  Modelica.Blocks.Sources.RealExpression Gc1_Expression[nNodes](
  each final y=Gc1)
    ;
  Modelica.Thermal.HeatTransfer.Components.Convection convection1[nNodes]
    ;
  Modelica.Blocks.Sources.RealExpression Gc2_Expression[nNodes](
  each final y=Gc2)
    ;
  Modelica.Thermal.HeatTransfer.Components.Convection convection2[nNodes]
    ;
equation
  connect(convection2.solid, vol2.heatPort)
    ;

  connect(convection1[nNodes:-1:1].solid, vol1[1:nNodes].heatPort)
    ;

  connect(convection1.fluid, heatCapacitor.port)
    ;
  connect(convection2.fluid, heatCapacitor.port)
    ;
  connect(Gc1_Expression.y, convection1.Gc)
    ;
  connect(Gc2_Expression.y, convection2.Gc)

  ;
end DynamicHX;

within AixLib.Utilities.Psychrometrics.Functions.Examples;
model pW_TDewPoi_comparison
  "Model to test the approximation for pW_TDewPoi and its inverse function"
  extends Modelica.Icons.Example;

  Modelica.Units.SI.Temperature T "Dew point temperature";
  Modelica.Units.SI.Temperature TInv "Dew point temperature";
  Modelica.Units.SI.TemperatureDifference dT "Difference between temperatures";
  Modelica.Units.SI.Pressure p_w_ashrae
    "Water vapor partial pressure according to the ASHRAE handbook";
  Modelica.Units.SI.Pressure p_w "Water vapor partial pressure";

  constant Real conv(unit="K/s") = 30 "Conversion factor";
  Real r_p "Ratio of the two approximations";
equation
  T = conv*time + 273.15;
  p_w_ashrae = AixLib.Utilities.Psychrometrics.Functions.pW_TDewPoi(T);
  p_w = AixLib.Utilities.Psychrometrics.Functions.pW_TDewPoi_amb(T);
  r_p = p_w_ashrae/p_w;
  p_w = AixLib.Utilities.Psychrometrics.Functions.pW_TDewPoi_amb(TInv);
  dT = T - TInv;
  assert(abs(dT) < 10E-12, "Error in function implementation.")
  ;
end pW_TDewPoi_comparison;

