within AixLib.Fluid.Sensors;
model RelativeHumidityTwoPort "Ideal two port relative humidity sensor"
  extends AixLib.Fluid.Sensors.BaseClasses.PartialDynamicFlowSensor;
  extends Modelica.Icons.RoundSensor;
  Modelica.Blocks.Interfaces.RealOutput phi(final unit="1",
                                            min=0,
                                            start=phi_start)
    "Relative humidity of the passing fluid"
    ;
  parameter Real phi_start(final unit="1", min=0, max=1)=0.5
    "Initial or guess value of output (= state)"
    ;

protected
  Real phiMed(final unit="1", min=0, start=phi_start)
    "Relative humidity to which the sensor is exposed to";

protected
  Modelica.Units.SI.Temperature T_a
    "Temperature of the medium flowing from port_a to port_b";
  Medium.MassFraction Xi_a[Medium.nXi](
    quantity=Medium.substanceNames[1:Medium.nXi])
    "Mass fraction of the medium flowing from port_a to port_b";
  Real phi_a(final unit="1")
    "Relative humidity of the medium flowing from port_a to port_b";
  Modelica.Units.SI.Temperature T_b
    "Temperature of the medium flowing from port_b to port_a";
  Medium.MassFraction Xi_b[Medium.nXi](
    quantity=Medium.substanceNames[1:Medium.nXi])
    "Mass fraction of the medium flowing from port_b to port_a";
  Real phi_b(final unit="1")
    "Relative humidity of the medium flowing from port_b to port_a";

initial equation
  if dynamic then
    if initType == Modelica.Blocks.Types.Init.SteadyState then
      der(phi) = 0;
    elseif initType == Modelica.Blocks.Types.Init.InitialState or
           initType == Modelica.Blocks.Types.Init.InitialOutput then
      phi = phi_start;
    end if;
  end if;
equation

  // Since the sensor does not affect the medium, we can use
  // port_b.Xi_outflow = inStream(port_a.Xi_outflow).
  Xi_a = port_b.Xi_outflow;

  T_a=Medium.temperature_phX(
      p=port_a.p,
      h=port_b.h_outflow,
      X=Xi_a);

  phi_a = AixLib.Utilities.Psychrometrics.Functions.phi_pTX(
    p=port_a.p,
    T=T_a,
    X_w=Xi_a[1]);

  if allowFlowReversal then
    phi_b = AixLib.Utilities.Psychrometrics.Functions.phi_pTX(
      p=port_b.p,
      T=T_b,
      X_w=Xi_b[1]);
    T_b=Medium.temperature_phX(
      p=port_b.p,
      h=port_a.h_outflow,
      X=Xi_b);
    Xi_b = port_a.Xi_outflow;
    phiMed = Modelica.Fluid.Utilities.regStep(
               x=port_a.m_flow,
               y1=phi_a,
               y2=phi_b,
               x_small=m_flow_small);
  else
    phi_b = 0;
    T_b = 273.15;
    Xi_b = zeros(Medium.nXi);
    phiMed = phi_a;
  end if;
  // Output signal of sensor
  if dynamic then
    der(phi) = (phiMed-phi)*k*tauInv;
  else
    phi = phiMed;
  end if
;
end RelativeHumidityTwoPort;

within AixLib.Utilities.Math.Functions;
function binomial "Returns the binomial coefficient"
  extends Modelica.Icons.Function;

  input Integer n "Size of set";
  input Integer k(min=0) "Size of subsets";
  output Integer binom "Binomial coefficient";

algorithm
  assert(n >= k, "n must be k or greater.");
  assert(k >= 0, "k must be 0 or greater.");
  if k <= 0.5*n then
    binom := integer(AixLib.Utilities.Math.Functions.fallingFactorial(n,k)/AixLib.Utilities.Math.Functions.factorial(k));
  else
    binom := integer(AixLib.Utilities.Math.Functions.fallingFactorial(n,n-k)/AixLib.Utilities.Math.Functions.factorial(n-k));
  end if

;
end binomial;

within AixLib.Fluid.FMI.ExportContainers.Examples.FMUs;
block IdealSource_m_flow "Declaration of an FMU that exports a mass flow source and sink"
   extends AixLib.Fluid.FMI.ExportContainers.PartialTwoPort(
     redeclare replaceable package Medium = AixLib.Media.Air);

  Modelica.Blocks.Interfaces.RealInput m_flow_in(final unit="kg/s")
    "Prescribed mass flow rate"
    ;

equation
  assert(abs(inlet.m_flow-outlet.m_flow) < 1E-2,
  "The mass flow rate of port_a and port_b is not conserved.
   This indicates a wrong configuration of your system model.");
  outlet.m_flow = m_flow_in;

  // We use connect statements
  // because outlet.backward and inlet.backward
  // is removed if allowFlowReversal=false.
  // The connect is applied on the components of the port
  // to avoid also connecting the mass flow rate which would
  // yield an overdetermined system of equations.
  connect(inlet.forward, outlet.forward);
  connect(outlet.backward, inlet.backward);
  connect(outlet.p, inlet.p)

  ;
end IdealSource_m_flow;

