model ScrollCompressor
  "Model for a scroll compressor, based on Jin (2002)"
  extends AixLib.Fluid.HeatPumps.Compressors.BaseClasses.PartialCompressor;

  parameter Real volRat(
    min = 1.0,
    final unit = "1")
    "Built-in volume ratio";

  parameter Modelica.Units.SI.VolumeFlowRate V_flow_nominal(min=0)
    "Refrigerant volume flow rate at suction at full load conditions";

  parameter Modelica.Units.SI.MassFlowRate leaCoe(min=0)
    "Leakage mass flow rate at a pressure ratio of 1";

  parameter Modelica.Units.SI.Efficiency etaEle
    "Electro-mechanical efficiency of the compressor";

  parameter Modelica.Units.SI.Power PLos(min=0)
    "Constant part of the compressor power losses";

  parameter Modelica.Units.SI.TemperatureDifference dTSup(min=0)
    "Superheating at compressor suction";

  Modelica.Units.SI.MassFlowRate m_flow "Refrigerant mass flow rate";

  Modelica.Units.SI.MassFlowRate mLea_flow "Refrigerant leakage mass flow rate";

  Modelica.Units.SI.Power PThe "Theoretical power consumed by the compressor";

  Modelica.Units.SI.Efficiency COP(start=5) "Heating COP of the compressor";

protected
  Modelica.Units.SI.IsentropicExponent k(start=1.2)
    "Isentropic exponent of the refrigerant";

  Real v_norm
    "Normalized refrigerant volume flow rate at
      suction at part load conditions";

  Real PRInt(start = 2.0)
    "Built-in pressure ratio";

equation
  PRInt = volRat^k;

  // Limit compressor speed to the full load speed
  v_norm = AixLib.Utilities.Math.Functions.smoothLimit(y, 0.0, 1.0, 0.001);

  if isOn then
    // Suction pressure
    pSuc = pEva;
    // Discharge pressure
    pDis = pCon;
    // Refrigerant mass flow rate
    mLea_flow = leaCoe*PR;
    m_flow = v_norm*
      AixLib.Utilities.Math.Functions.smoothMax(
      V_flow_nominal/vSuc - mLea_flow,
      1e-5*V_flow_nominal/vSuc,
      1e-6*V_flow_nominal/vSuc);

    // Theoretical power of the compressor
    k = ref.isentropicExponentVap_Tv(TSuc, vSuc);
    // If the external pressure ratio does not match the built-in pressure ratio
    PThe = v_norm * k/(k - 1.0) * pSuc * V_flow_nominal
      * (((k - 1.0)/k) * PR/volRat + 1.0/k * PRInt^((k - 1.0)/k) - 1.0);
    // This equation reduces to the  equation for the built-in pressure ratio
    // if the external pressure ratio matches the built-in pressure ratio:
    // PThe = v_norm * k/(k - 1.0) * pSuc*v_flow * ((PRInt)^((k - 1.0)/k) - 1.0)

    // Temperature at suction of the compressor
    TSuc = port_a.T + dTSup;

    // Power consumed by the compressor
    P = (PThe/etaEle + PLos);

    // Energy balance of the compressor
     port_a.Q_flow = m_flow * (hEva - hCon);
     port_b.Q_flow = - (port_a.Q_flow + P);
     -port_b.Q_flow = P * COP;
  else
    // Heat pump is turned off
    k = 1.0;
    pSuc = pEva;
    pDis = pCon;
    mLea_flow = 0.0;
    m_flow = 0.0;
    PThe = 0.0;
    P = 0.0;
    TSuc = port_a.T;
    port_a.Q_flow = 0.0;
    port_b.Q_flow = 0.0;
    COP = 1.0;
  end if

  ;
end ScrollCompressor;

within AixLib.ThermalZones.ReducedOrder.Windows.BaseClasses;
block SelfShadowing
  "Self-shadowing due to projections for direct radiation"
  parameter Integer n(min = 1)=1 "Number of windows"
    ;
  extends Modelica.Blocks.Icons.Block;
  parameter Modelica.Units.SI.Length b[n] "Width of window"
    ;
  parameter Modelica.Units.SI.Height h[n] "Height of window"
    ;
  parameter Modelica.Units.SI.Length bLef[n] "Window projection left"
    ;
  parameter Modelica.Units.SI.Length bRig[n] "Window projection right"
    ;
  parameter Modelica.Units.SI.Length dLef[n]
    "Distance between projection (left) and window"
    ;
  parameter Modelica.Units.SI.Length dRig[n]
    "Distance between projection (right) and window"
    ;
  parameter Modelica.Units.SI.Length bAbo[n] "Window projection above"
    ;
  parameter Modelica.Units.SI.Length bBel[n] "Window projection below"
    ;
  parameter Modelica.Units.SI.Length dAbo[n]
    "Distance between projection (above) and window"
    ;
  parameter Modelica.Units.SI.Length dBel[n]
    "Distance between projection (below) and window"
    ;
  parameter Modelica.Units.SI.Angle azi[n](each displayUnit="deg") "Surface azimuth. azi=-90 degree if surface outward unit normal points
     toward east; azi=0 if it points toward south"
    ;
  parameter Modelica.Units.SI.Angle til[n](each displayUnit="deg") "Surface tilt. til=90 degree for walls; til=0 for ceilings; til=180 for
    roof" ;

   Modelica.Blocks.Interfaces.RealInput incAng[n](
    each final quantity="Angle",
    each final unit="rad",
    each displayUnit="deg")
    "Incidence angle of the sun beam on a tilted surface"
    ;
  Modelica.Blocks.Interfaces.RealInput solAzi(
    final quantity="Angle",
    final unit="rad",
    displayUnit="deg") "Solar Azimuth"
     ;
  Modelica.Blocks.Interfaces.RealInput alt(
    final quantity="Angle",
    final unit="rad",
    displayUnit="deg") "Solar altitude angle"
    ;
  Modelica.Blocks.Interfaces.RealOutput x_As[n](each min=0,
    each final unit="1") "Not shaded percentage of window area"
    ;

protected
  Real e_hn[n] "Horizontal calculation factor";
  Real e_vn[n] "Vertical calculation factor";
  Modelica.Units.SI.Length x1[n] "Auxiliary variable for shadow from left";
  Modelica.Units.SI.Length x2[n] "Auxiliary variable for shadow from right";
  Modelica.Units.SI.Length x3[n] "Auxiliary variable for shadow from above";
  Modelica.Units.SI.Length x4[n] "Auxiliary variable for shadow from below";
  Modelica.Units.SI.Length s_h[n] "Horizontal reduction of window";
  Modelica.Units.SI.Length s_v[n] "Vertical reduction of window";
  Modelica.Units.SI.Area A_S[n] "Auxiliary variable for effective area";
  Modelica.Units.SI.Area A_s[n] "Effective windowarea";
equation
  for i in 1:n loop
  //Calculating e_hn and e_vn
    if Modelica.Math.cos(incAng[i])<=0 then
       e_hn[i]=10^20;
       e_vn[i]=10^20;
    else
      e_hn[i]=Modelica.Math.sin(
      AixLib.ThermalZones.ReducedOrder.Windows.BaseClasses.Conversions.to_northAzimuth(
      azi[i])-
      AixLib.ThermalZones.ReducedOrder.Windows.BaseClasses.Conversions.to_northAzimuth(
      solAzi))*Modelica.Math.cos(alt)/Modelica.Math.cos(incAng[i]);
      e_vn[i]=(Modelica.Math.sin(alt)*Modelica.Math.sin(
      AixLib.ThermalZones.ReducedOrder.Windows.BaseClasses.Conversions.to_surfaceTiltVDI(
      til[i]))-Modelica.Math.cos(alt)*Modelica.Math.cos(
      AixLib.ThermalZones.ReducedOrder.Windows.BaseClasses.Conversions.to_surfaceTiltVDI(
      til[i]))*Modelica.Math.cos(
      AixLib.ThermalZones.ReducedOrder.Windows.BaseClasses.Conversions.to_northAzimuth(
      azi[i])-
      AixLib.ThermalZones.ReducedOrder.Windows.BaseClasses.Conversions.to_northAzimuth(
      solAzi)))/Modelica.Math.cos(incAng[i]);
    end if;

  //Calculating s_h
  x1[i]=e_hn[i]*bLef[i]-dLef[i];
  x2[i]=-e_hn[i]*bRig[i]-dRig[i];
  if e_hn[i]>=0 then                          //Shadowing left
    if x1[i]<0 then                             //No shadow
      s_h[i]=0;
    elseif (e_hn[i]*bRig[i]+dRig[i])<0 then     //Additional shadow right
      s_h[i]=x1[i]-e_hn[i]*bRig[i]-dRig[i];
    else
      s_h[i]=x1[i];                             //Normal shadow left
    end if;
  else                                        //Shadowing right
    if x2[i]<0 then                             //No shadow
      s_h[i]=0;
    elseif (-e_hn[i]*bLef[i]+dLef[i])<0 then    //Additional shadow left
      s_h[i]=x2[i]+e_hn[i]*bLef[i]-dLef[i];
    else                                        //Normal shadow right
      s_h[i]=x2[i];
    end if;
  end if;
  //Calculating s_v
  x3[i]=e_vn[i]*bAbo[i]-dAbo[i];
  x4[i]=-e_vn[i]*bBel[i]-dBel[i];
  if e_vn[i]>=0 then                        //Shadowing above
    if x3[i]<0 then                            //No shadow
      s_v[i]=0;
    elseif (e_vn[i]*bBel[i]+dBel[i])<0 then    //Additional shadow below
      s_v[i]=x3[i]-e_hn[i]*bBel[i]-dBel[i];
    else                                       //Normal shadow above
      s_v[i]=x3[i];
    end if;
  else                                      //Shadowing below
    if x4[i]<0 then                            //No shadow
      s_v[i]=0;
    elseif (-e_vn[i]*bAbo[i]+dAbo[i])<0 then   //Additional shadow above
      s_v[i]=x4[i]-e_vn[i]*bAbo[i]-dAbo[i];
    else                                       //Normal shadow below
      s_v[i]=x4[i];
    end if;
  end if;
  //Calculating A_s
  if (b[i]-s_h[i])<0 then
     A_S[i]=0;
  elseif (h[i]-s_v[i])<0 then
     A_S[i]=0;
  else
     A_S[i]=(b[i]-s_h[i])*(h[i]-s_v[i]);
  end if;
  A_s[i] = max(0,A_S[i]);
  x_As[i]=A_s[i]/(b[i]*h[i]);
  end for
     ;
end SelfShadowing;

within AixLib.Airflow.Multizone.BaseClasses;
function powerLawFixedM
  "Power law used in orifice equations when m is constant"
  extends Modelica.Icons.Function;

  input Real C "Flow coefficient, C = V_flow/ dp^m";
  input Modelica.Units.SI.PressureDifference dp(displayUnit="Pa")
    "Pressure difference";
  input Real m(min=0.5, max=1)
    "Flow exponent, m=0.5 for turbulent, m=1 for laminar";
  input Real a "Polynomial coefficient";
  input Real b "Polynomial coefficient";
  input Real c "Polynomial coefficient";
  input Real d "Polynomial coefficient";
  input Modelica.Units.SI.PressureDifference dp_turbulent(min=0) = 0.001
    "Pressure difference where regularization starts";
  output Modelica.Units.SI.VolumeFlowRate V_flow "Volume flow rate";
protected
  constant Real gamma(min=1) = 1.5
    "Normalized flow rate where dphi(0)/dpi intersects phi(1)";
  Real pi "Normalized pressure";
  Real pi2 "Square of normalized pressure";
algorithm
 if (dp >= dp_turbulent) then
   V_flow :=C *dp^m;
 elseif (dp <= -dp_turbulent) then
   V_flow :=-C*(-dp)^m;
 else
   pi  := dp/dp_turbulent;
   pi2 := pi*pi;
   V_flow :=C *dp_turbulent^m * pi * ( a + pi2 * ( b + pi2 * ( c + pi2 * d)));
 end if

  ;
end powerLawFixedM;

within AixLib.Fluid.Movers.PumpsPolynomialBased.Controls;
model CtrlDpVarH "'dp variable' for PumpHeadControlled"
  extends BaseClasses.PumpController;

  parameter Modelica.Units.NonSI.AngularVelocity_rpm Nstart=pumpParam.nMin + (
      pumpParam.nMax - pumpParam.nMin)*0.8 "pump speed at start of simulation";
  parameter Real Qnom(
    quantity="VolumeFlowRate",
    unit="m3/h",
    displayUnit="m3/h") = 0.5*max(pumpParam.maxMinSpeedCurves[:,1]) "Nominal volume flow rate in m³/h";
  parameter Modelica.Units.SI.Height Hnom=
      AixLib.Fluid.Movers.PumpsPolynomialBased.BaseClasses.polynomial2D(
      pumpParam.cHQN,
      Qnom,
      Nstart) "Nominal pump head in m (water)";
  parameter Modelica.Units.SI.Height H0=0.5*Hnom "pump head when Q == 0 m3/h";

  parameter Real k(unit="1") = 50 "Gain of controller";
  parameter Modelica.Units.SI.Time Ti(min=Modelica.Constants.small) = 0.01
    "Time constant of Integrator block";
  parameter Modelica.Units.SI.Time Td(min=0) = 0.001
    "Time constant of Derivative block";

  Modelica.Blocks.Sources.RealExpression headControl(y=(Hnom - H0)/Qnom*Q.y +
        H0)    "The given pump head according to controll strategy"
    ;
protected
  Modelica.Blocks.Routing.RealPassThrough powerPassThrough ;
  Modelica.Blocks.Routing.RealPassThrough efficiencyPassThrough ;
  Modelica.Blocks.Routing.RealPassThrough Q
    "Dummy for volume flow rate signal." ;
public
  parameter Modelica.Blocks.Types.SimpleController controllerTypePID=.Modelica.Blocks.Types.SimpleController.PID
    "Type of controller";
  Modelica.Blocks.Routing.BooleanPassThrough onOffPassThrough1
    ;
equation
  connect(pumpBus.PelMea, powerPassThrough.u) ;
  connect(powerPassThrough.y, pumpControllerBus.PelMea) ;
  connect(pumpBus.efficiencyMea, efficiencyPassThrough.u) ;
  connect(efficiencyPassThrough.y, pumpControllerBus.efficiencyMea) ;
  connect(pumpBus.vFRcur_m3h, Q.u) ;
  connect(headControl.y, pumpBus.dpSet) ;
  connect(pumpControllerBus.onSet, onOffPassThrough1.u) ;
  connect(onOffPassThrough1.y, pumpBus.onSet) 
  ;
end CtrlDpVarH;

