model JSONWriter "Model for writing results to a json file"
  extends Modelica.Blocks.Icons.DiscreteBlock;
  parameter Integer nin
    "Number of inputs"
    ;
  parameter String fileName = getInstanceName() + ".json"
    "File name, including extension";
  parameter String[nin] varKeys = {"key" + String(i) for i in 1:nin}
    "Key names, indices by default";
  parameter AixLib.Utilities.IO.Files.BaseClasses.OutputTime outputTime=
    AixLib.Utilities.IO.Files.BaseClasses.OutputTime.Terminal
    "Time when results are written to file"
    ;
  parameter Modelica.Units.SI.Time customTime=0
    "Custom time when results are stored, used if outputTime=Custom only"
    ;

  Modelica.Blocks.Interfaces.RealVectorInput[nin] u "Variables that are saved"
     ;
protected
  parameter String insNam = getInstanceName() "Instance name";
  AixLib.Utilities.IO.Files.BaseClasses.JSONWriterObject jsonWri=
      AixLib.Utilities.IO.Files.BaseClasses.JSONWriterObject(
        insNam,
        fileName,
        outputTime==AixLib.Utilities.IO.Files.BaseClasses.OutputTime.Terminal,
        varKeys)
    "File writer object";
equation
  if outputTime==AixLib.Utilities.IO.Files.BaseClasses.OutputTime.Terminal then
    AixLib.Utilities.IO.Files.BaseClasses.cacheVals(jsonWri, u);
  end if;

  if outputTime==AixLib.Utilities.IO.Files.BaseClasses.OutputTime.Initial then
    when initial() then
      AixLib.Utilities.IO.Files.BaseClasses.writeJSON(jsonWri, u);
    end when;
  end if;

  if outputTime==AixLib.Utilities.IO.Files.BaseClasses.OutputTime.Custom then
    when time>=customTime then
      AixLib.Utilities.IO.Files.BaseClasses.writeJSON(jsonWri, u);
    end when;
  end if

  ;
end JSONWriter;

