within AixLib.BoundaryConditions.WeatherData.Old.WeatherTRY.BaseClasses;
function DeterminePositionsInWeatherVector
  "Determines position in weather vector"
  input Boolean Cloud_cover "Cloud cover";
  input Boolean Wind_dir "Wind direction";
  input Boolean Wind_speed "Wind speed";
  input Boolean Air_temp "Air temperature";
  input Boolean Air_press "Air pressure";
  input Boolean Mass_frac "Mass fraction of water in dry air";
  input Boolean Rel_hum "Relative humidity";
  input Boolean Sky_rad "Long wave sky radiation on horizontal surface";
  input Boolean Ter_rad
    "Long Wave terrestrial radiation from horizontal surface";
  output Integer[9] PosWV = fill(0, 9)
    "Determined postition in weather data vector";
protected
  Integer m;
algorithm
  m := 1;
  if Cloud_cover then
    PosWV[1] := m;
    m := m + 1;
  end if;
  if Wind_dir then
    PosWV[2] := m;
    m := m + 1;
  end if;
  if Wind_speed then
    PosWV[3] := m;
    m := m + 1;
  end if;
  if Air_temp then
    PosWV[4] := m;
    m := m + 1;
  end if;
  if Air_press then
    PosWV[5] := m;
    m := m + 1;
  end if;
  if Mass_frac then
    PosWV[6] := m;
    m := m + 1;
  end if;
  if Rel_hum then
    PosWV[7] := m;
    m := m + 1;
  end if;
  if Sky_rad then
    PosWV[8] := m;
    m := m + 1;
  end if;
  if Ter_rad then
    PosWV[9] := m;
    m := m + 1;
  end if
  ;
end DeterminePositionsInWeatherVector;

within AixLib.Utilities.Math.Functions.BaseClasses;
function der_inverseXRegularized "Derivative of inverseXRegularised function"
  extends Modelica.Icons.Function;
 input Real x "Abscissa value";
 input Real delta(min=Modelica.Constants.eps)
    "Abscissa value below which approximation occurs";
 input Real deltaInv = 1/delta "Inverse value of delta";

 input Real a = -15*deltaInv "Polynomial coefficient";
 input Real b = 119*deltaInv^2 "Polynomial coefficient";
 input Real c = -361*deltaInv^3 "Polynomial coefficient";
 input Real d = 534*deltaInv^4 "Polynomial coefficient";
 input Real e = -380*deltaInv^5 "Polynomial coefficient";
 input Real f = 104*deltaInv^6 "Polynomial coefficient";

 input Real x_der "Abscissa value";
 output Real y_der "Function value";

algorithm
  y_der :=if (x > delta or x < -delta) then -x_der/x/x elseif (x < delta/2 and x > -delta/2) then x_der/(delta*delta) else
    AixLib.Utilities.Math.Functions.BaseClasses.der_smoothTransition(
       x=x,
       x_der=x_der,
       delta=delta,
       deltaInv=deltaInv,
       a=a, b=b, c=c, d=d, e=e, f=f)
;
end der_inverseXRegularized;

within AixLib.Electrical.PVSystem.BaseClasses;
model CellTemperatureOpenRack
   "Empirical model for determining the cell temperature of a PV module mounted on an 
   open rack"

 extends AixLib.Electrical.PVSystem.BaseClasses.PartialCellTemperature;

  final parameter Modelica.Units.SI.Temperature T_a_0=293.15
    "Reference ambient temperature";
 final parameter Real coeff_trans_abs = 0.9
 "Module specific coefficient as a product of transmission and absorption.
 It is usually unknown and set to 0.9 in literature";

equation

 T_c = if noEvent(radTil >= Modelica.Constants.eps) then
 (T_a)+(T_NOCT-T_a_0)*radTil/radNOCT*9.5/(5.7+3.8*winVel)*(1-eta/coeff_trans_abs)
 else
 (T_a)

 ;
end CellTemperatureOpenRack;

within AixLib.Fluid.Storage.BaseClasses;
model HeatTransferLambdaEff "Heat transfer with buoyancy and effective conductivity"
  extends AixLib.Fluid.Storage.BaseClasses.PartialHeatTransferLayers;

  Modelica.Units.SI.HeatFlowRate[n - 1] qFlow
    "Heat flow rate from segment i+1 to i";

protected
  parameter Real kappa=0.41 "Karman constant";
  parameter Modelica.Units.SI.Length height=data.hTank/n
    "Height of fluid layers";
  parameter Real beta=350e-6 "Thermal expansion coefficient in 1/K";
  parameter Modelica.Units.SI.Area A=Modelica.Constants.pi/4*data.dTank^2
    "Area of heat transfer between layers";
  parameter Modelica.Units.SI.Density rho=1000
    "Density, used to compute fluid mass";
  parameter Modelica.Units.SI.SpecificHeatCapacity c_p=4180
    "Specific heat capacity";
                              //
  Modelica.Units.SI.TemperatureDifference dT[n - 1]
    "Temperature difference between adjoining volumes";
  Modelica.Units.SI.ThermalConductance[n - 1] k
    "Effective heat transfer coefficient";
  Modelica.Units.SI.ThermalConductivity[n - 1] lambda
    "Effective heat conductivity";
  parameter Modelica.Units.SI.ThermalConductivity lambdaWater=0.64
    "Thermal conductivity of water";
equation

  for i in 1:n-1 loop
    dT[i] = therm[i].T-therm[i+1].T;
    lambda[i]^2=noEvent(max((9.81*beta*dT[i]/height)*(2/3*rho*c_p*kappa*height^2)^2,0));
    k[i]=(noEvent(if dT[i]>0 then lambda[i] else 0)+lambdaWater)*A/height;
    qFlow[i] = k[i]*dT[i];
  end for;

// Positive heat flows here mean negative heat flows for the fluid layers
  therm[1].Q_flow = qFlow[1];
  for i in 2:n-1 loop
       therm[i].Q_flow = -qFlow[i-1]+qFlow[i];
  end for;
  therm[n].Q_flow = -qFlow[n-1]
  ;
end HeatTransferLambdaEff;

