within AixLib.Fluid.HeatExchangers.BaseClasses;
model HACoilInside "Calculates the hA value for water inside a coil"
  extends Modelica.Blocks.Icons.Block;

  parameter Modelica.Units.SI.MassFlowRate m_flow_nominal
    "Water mass flow rate"
    ;

  Modelica.Blocks.Interfaces.RealInput m_flow(unit="kg/s") "Mass flow rate"
    ;
  Modelica.Blocks.Interfaces.RealInput T(unit="K") "Temperature"
    ;

  Modelica.Blocks.Interfaces.RealOutput hA(unit="W/K")
    "Inside convective heat transfer" ;

  parameter Modelica.Units.SI.ThermalConductance hA_nominal(min=0)
    "Convective heat transfer coefficient"
    ;
  parameter Real n(min=0, max=1)=0.85
    "Water-side exponent for convective heat transfer coefficient, h proportional to m_flow^n";
  parameter Modelica.Units.SI.Temperature T_nominal=
      Modelica.Units.Conversions.from_degC(20) "Nominal water temperature"
    ;
  parameter Boolean flowDependent=true
    "Set to false to make hA independent of mass flow rate"
    ;
  parameter Boolean temperatureDependent = true
    "Set to false to make hA independent of temperature"
    ;

protected
  Real x(min=0)
    "Factor for temperature dependent variation of heat transfer coefficient";
  parameter Real s(min=0, fixed=false)
    "Coefficient for temperature dependence of heat transfer coefficient";
  Real fm "Fraction of actual to nominal mass flow rate";

initial equation
  s =if temperatureDependent then 0.014/(1 + 0.014*
    Modelica.Units.Conversions.to_degC(T_nominal)) else 1;
equation
  fm = if flowDependent then m_flow / m_flow_nominal else 1;
  x = if temperatureDependent then 1 + s * (T-T_nominal) else 1;
  if flowDependent and temperatureDependent then
    hA = x * hA_nominal * AixLib.Utilities.Math.Functions.regNonZeroPower(fm, n, 0.1);
  elseif flowDependent then
    hA = hA_nominal * AixLib.Utilities.Math.Functions.regNonZeroPower(fm, n, 0.1);
  elseif temperatureDependent then
    hA = x * hA_nominal;
  else
    hA = hA_nominal;
  end if

;
end HACoilInside;

within AixLib.Fluid.Storage.BaseClasses;
model HeatTransferLambdaSimple "Heat transfer with effective conductivity"
  extends AixLib.Fluid.Storage.BaseClasses.PartialHeatTransferLayers;

  Modelica.Units.SI.HeatFlowRate[n - 1] qFlow
    "Heat flow rate from segment i+1 to i";

  parameter Modelica.Units.SI.ThermalConductivity const_lambda_eff=100
    "Effective thermal conductivity";

  Modelica.Blocks.Logical.TriggeredTrapezoid triggeredTrapezoid[n - 1](
    each u(start=false),
    rising=100,
    falling=10,
    amplitude=const_lambda_eff,
    offset=lambdaWater)
    "Triggered trapezoid for conductivity between layers"
                ;

protected
  parameter Modelica.Units.SI.Length height=data.hTank/n
    "Height of fluid layers";
  parameter Modelica.Units.SI.Area A=Modelica.Constants.pi/4*data.dTank^2
    "Area of heat transfer between layers";
  Modelica.Units.SI.TemperatureDifference dT[n - 1]
    "Temperature difference between adjoining volumes";
  Modelica.Units.SI.ThermalConductance k[n - 1]
    "Effective heat transfer coefficient";
  parameter Modelica.Units.SI.ThermalConductivity lambdaWater=0.64
    "Thermal conductivity of water";

equation

  for i in 1:n-1 loop
    dT[i] = therm[i].T-therm[i+1].T;
    triggeredTrapezoid[i].u=dT[i]>0;
    k[i]=triggeredTrapezoid[i].y*A/height;
    qFlow[i] = k[i]*dT[i];
  end for;

  // Positive heat flows here mean negative heat flows for the fluid layers
  therm[1].Q_flow = qFlow[1];
  for i in 2:n-1 loop
       therm[i].Q_flow = -qFlow[i-1]+qFlow[i];
  end for;
  therm[n].Q_flow = -qFlow[n-1]
  ;
end HeatTransferLambdaSimple;

