within AixLib.Fluid.Movers.Compressors.SimpleCompressors.CompressionProcesses;
model RotaryCompression
  "Model that describes the compression process of a rotary compressor"
  extends BaseClasses.PartialCompression;

equation
  // Calculation of mass flow
  //
  m_flow = homotopy(rotSpe*oveVolEff.lamH*VDis*dInl,
                    rotSpe*oveVolEff.lamH*VDis*dInl0)
    "This covers initialisation case as well as shut-down case";

  // Calculation of energy balances
  //
  hOutIse = Medium.specificEnthalpy(Medium.setState_psX(p=pOut,
    s=Medium.specificEntropy(staInl)))
    "Isentropic specific enthalpy at outlet";
  oveIseEff.etaIse*dh = dhIse "Specific enthalpy difference";
  dhIse = (hOutIse - hInl) "Isentropic specific enthalpy difference";

  Q_flow_ref = m_flow *dh "Power absorbed by refrigerant";
  if not useIseWor then
    oveEngEff.etaEng*PEle = Q_flow_ref "Compressor's power consumption";
  else
    oveEngEff.etaEng*PEle = m_flow *dhIse "Compressor's power consumption";
  end if;
  /*Some efficiency models calculate the compressor's power consumptions based
    on the compressors isentropic work. Therefore, a distinction is made above.
  */

  // Calculate pressures at inlet and outlet of compressor
  //
  pInl = port_a.p "Pressure at inlet";
  pOut = port_b.p "Pressure at outlet";

  // Calculate specific enthalpies
  //
  hInl = actualStream(port_a.h_outflow) "Specific enthalpy at inlet";
  hOut = actualStream(port_b.h_outflow) "Specific enthalpy at outlet";

  port_a.h_outflow = inStream(port_a.h_outflow)
    "Compressor behaves as perfect valve if flow is reserved";
  port_b.h_outflow = smooth(1,noEvent(if m_flow > 0
    then hInl + dh else inStream(port_a.h_outflow)))
    "Compressor behaves as perfect valve if flow is reserved";
  /*It is assumed that the compressor works as perfectly closed valve if the 
    mass flow is reserved. Hence, specific enthalpies flowing out of the system
    will meet the specific enthalpies flowing into the system.
  */

  // Connect heat port with internal variables
  //
  heatPort.Q_flow = Q_flow_ref-PEle

  ;
end RotaryCompression;

within AixLib.Fluid.BoilerCHP.BaseClasses;
model CondensingBoilerEfficiency
  "Model for temperature depending efficiency of a condensing boiler"
  parameter Real lambda=0.01 "Offset variable of weighting coefficients sigmas";

  parameter Modelica.Units.SI.Temperature T_nom=343.15 "Nominal temperature";
  parameter Modelica.Units.SI.Temperature T_part=308.15
    "Intermediate temperature";
  parameter Modelica.Units.SI.Efficiency eta_nom=1
    "Nominal net heating value efficiency";
  parameter Modelica.Units.SI.Efficiency eta_int=1
    "Intermediate net heating value efficiency";
  parameter Real eta_max=1.11
    "Ratio gross (high) heating value / net (low) heating value defined according to the fuel";

  parameter Real ak=-0.0002 "Sensible temperature depending efficiency decrease per K";
  Real etaSens;
  Real etaCond;
  Real sigmaSens;
  Real sigmaCond;
  Real etaRP;
  Modelica.Units.SI.Temperature Tc(
    start=360,
    max=380,
    min=323,
    nominal=360)
    "Temperature of Sensitive and Latent characteristic intersection";
  //start value is important: equation below has two solutions

  Modelica.Blocks.Interfaces.RealInput T_in(
    final quantity="ThermodynamicTemperature",
    final unit="K",
    displayUnit="degC") "Ambient air temperature" ;
  Modelica.Blocks.Interfaces.RealOutput eta "Value of Real output" ;
algorithm
  //The boiler is launched for partLoadRate (boilerBus.PLR) > PLR_min, if partLoadRate < PLR_min there is no combustion and the efficiency etaRP is zero
  //Determination of the efficiency for the law without condensation
  etaSens := eta_nom + ak*(T_in - T_nom);
  //Determination of the efficiency for the law characterizing the condensation
  etaCond := eta_int + (eta_max - eta_int)*(1 - AixLib.Utilities.Psychrometrics.Functions.saturationPressure(T_in)/AixLib.Utilities.Psychrometrics.Functions.saturationPressure(T_part)*T_part/T_in);
  sigmaCond := 1/(1 + exp(T_in - Tc - lambda));
  sigmaSens := 1 - 1/(1 + exp(T_in - Tc + lambda));
  etaRP := sigmaSens*etaSens + sigmaCond*etaCond;


equation
  //Calculation of Tc
  eta_nom + ak*(Tc - T_nom) = eta_int + (eta_max - eta_int)*(1 - AixLib.Utilities.Psychrometrics.Functions.saturationPressure(Tc)/AixLib.Utilities.Psychrometrics.Functions.saturationPressure(T_part)*
    T_part/Tc);

  eta = etaRP
  ;
end CondensingBoilerEfficiency;

