  ;
end RelativeAirMass;

within AixLib.Media.Refrigerants.R410A;
function dPressureVap_dSpecificVolume_Tv
  "Derivative of the Martin-Hou equation of state with regards to specific volume"

  input Modelica.Units.SI.Temperature T "Temperature of refrigerant";
  input Modelica.Units.SI.SpecificVolume v "Specific volume of refrigerant";
  output Real dpdv(
    final unit="Pa.kg/m3")
     "Derivative of pressure with regards to specific volume";

protected
  Modelica.Units.SI.SpecificVolume v_abs "Smoothed specific volume";

algorithm

  v_abs := AixLib.Utilities.Math.Functions.smoothMax(v, 1.01*b, 0.01*b);

  dpdv := -R*T/(v_abs-b)^2;
  for i in 1:size(A, 1) loop
    dpdv := dpdv - (i+1)*(A[i] + B[i]*T + C[i]*Modelica.Math.exp(-k*T/TCri))/(v_abs - b)^(i+2);
  end for

;
end dPressureVap_dSpecificVolume_Tv;

within AixLib.Fluid.FixedResistances.BaseClasses;
model PlugFlowHeatLoss
  "Heat loss model for pipe with delay as an input variable"
  extends Fluid.Interfaces.PartialTwoPortTransport(
    final allowFlowReversal=true,
    final dp_start=0);
    // allowFlowReversal set to true because this model is used for inlet and outlets

  parameter Real C(unit="J/(K.m)")
    "Thermal capacity per unit length of pipe";
  parameter Real R(unit="(m.K)/W")
    "Thermal resistance per unit length from fluid to boundary temperature";

  parameter Modelica.Units.SI.MassFlowRate m_flow_nominal
    "Nominal mass flow rate";
  parameter Modelica.Units.SI.Temperature T_start "Initial output temperature";

  final parameter Modelica.Units.SI.Time tau_char=R*C
    "Characteristic delay time";

  Modelica.Blocks.Interfaces.RealInput tau(unit="s") "Time delay at pipe level"
    ;
  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a heatPort
    "Heat port to connect environment (negative if heat is lost to ambient)"
    ;

  Modelica.Units.SI.Temperature T_a_inflow(start=T_start)
    "Temperature at port_a for inflowing fluid";
  Modelica.Units.SI.Temperature T_b_outflow(start=T_start)
    "Temperature at port_b for outflowing fluid";
  Modelica.Units.SI.Temperature TAmb=heatPort.T "Environment temperature";

protected
  parameter Medium.ThermodynamicState sta_default=Medium.setState_pTX(
      T=Medium.T_default,
      p=Medium.p_default,
      X=Medium.X_default) "Default medium state";
  parameter Modelica.Units.SI.SpecificHeatCapacity cp_default=
      Medium.specificHeatCapacityCp(state=sta_default)
    "Heat capacity of medium";

equation
  dp = 0;

  port_a.h_outflow = inStream(port_b.h_outflow);

  port_b.h_outflow =Medium.specificEnthalpy(
    Medium.setState_pTX(
      port_a.p,
      T_b_outflow,
      port_b.Xi_outflow)) "Calculate enthalpy of output state";

    T_a_inflow = Medium.temperature(
      Medium.setState_phX(
        port_a.p,
        inStream(port_a.h_outflow),
        port_b.Xi_outflow));

  // Heat losses
  T_b_outflow = TAmb + (T_a_inflow - TAmb)*Modelica.Math.exp(-tau/tau_char);

  heatPort.Q_flow = -AixLib.Utilities.Math.Functions.spliceFunction(
    pos=(T_a_inflow - T_b_outflow)*cp_default,
    neg=0,
    x=port_a.m_flow,
    deltax=m_flow_nominal/1000)*port_a.m_flow

  ;
end PlugFlowHeatLoss;

