model EvaporatorCondenser
  "Evaporator or condenser with refrigerant experiencing constant temperature phase change"
  extends AixLib.Fluid.Interfaces.TwoPortHeatMassExchanger(redeclare final
      AixLib.Fluid.MixingVolumes.MixingVolume vol(final
        prescribedHeatFlowRate=false));

  parameter Modelica.Units.SI.ThermalConductance UA
    "Thermal conductance of heat exchanger";
  parameter Modelica.Units.SI.ThermalConductance UA_small=UA/10
    "Small thermal conductance for regularisation of heat transfer "
    ;

  Modelica.Blocks.Interfaces.RealOutput Q_flow(unit="W")
    "Heat added to the fluid"
    ;
  Modelica.Blocks.Interfaces.RealOutput T(unit="K") "Medium temperature"
    ;

  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a port_ref
    "Temperature and heat flow from the refrigerant"
    ;

  Modelica.Units.SI.Efficiency NTU=UA/(AixLib.Utilities.Math.Functions.smoothMax(
      abs(port_a.m_flow),
      m_flow_small,
      m_flow_small)*cp_default) "Number of transfer units of heat exchanger";

  Modelica.Units.SI.Efficiency eps=AixLib.Utilities.Math.Functions.smoothMin(
      AixLib.Fluid.HeatExchangers.BaseClasses.epsilon_ntuZ(
        NTU,
        0,
        Integer(AixLib.Fluid.Types.HeatExchangerFlowRegime.ConstantTemperaturePhaseChange)),
      0.999,
      1.0e-4) "Effectiveness of heat exchanger";

  Modelica.Blocks.Sources.RealExpression UAeff(
    final y=AixLib.Utilities.Math.Functions.smoothMax(
      x1=UA,
      x2=eps*cp_default*abs(port_a.m_flow)/(1 - eps),
      deltaX=UA_small))
    "Effective heat transfer coefficient"
    ;

protected
  parameter Modelica.Units.SI.SpecificHeatCapacity cp_default=
      Medium.specificHeatCapacityCp(sta_default)
    "Density, used to compute fluid volume";

  Modelica.Thermal.HeatTransfer.Sensors.HeatFlowSensor heaFlo
    "Heat flow sensor"
    ;
  Modelica.Thermal.HeatTransfer.Components.Convection con
    "Convective heat transfer"
    ;
  Modelica.Thermal.HeatTransfer.Sensors.TemperatureSensor senTem
    "Temperature sensor"
    ;
equation
  connect(heaFlo.port_b, vol.heatPort) ;
  connect(heaFlo.Q_flow, Q_flow) ;
  connect(port_ref, con.solid) ;
  connect(con.fluid, heaFlo.port_a)
    ;
  connect(UAeff.y, con.Gc) ;
  connect(senTem.port, vol.heatPort)
    ;
  connect(senTem.T, T) 
  ;
end EvaporatorCondenser;

