  parameter Boolean use_attNameReal=false "Get real attributes from fileName"
    ;
  parameter Boolean use_attNameInt=false "Get integer attributes from fileName"
    ;
  parameter String varName[:]={""} "Array name in .nc file"
    ;
  parameter String attNameReal[:]={""}
    "Name of attribute of type real in .nc file"
    ;
  parameter String attNameInt[:]={""}
    "Name of attribute of type integer in .nc file"
    ;
  parameter Modelica.Units.SI.Time offset=0
    "Time period prior current simulation time";
  Modelica.Blocks.Interfaces.RealOutput y[size(varName, 1)]
    if use_varName
    "Output Vector with all variables"
    ;
  Modelica.Blocks.Interfaces.RealOutput yAttReal[size(attNameReal, 1)]
    if use_attNameReal
    "Output Vector with all attributes of type double" ;
  Modelica.Blocks.Interfaces.IntegerOutput yAttInt[size(attNameInt, 1)]
    if use_attNameInt
    "Output Vector with all attributes of type integer" ;
protected
  Modelica.Blocks.Interfaces.RealOutput y_internal[size(varName, 1)]
    "Needed to connect to conditional connector";
  Modelica.Blocks.Interfaces.RealOutput yAttReal_internal[size(attNameReal, 1)]
    "Needed to connect to conditional connector";
  Modelica.Blocks.Interfaces.IntegerOutput yAttInt_internal[size(attNameInt, 1)]
    "Needed to connect to conditional connector";
equation
  connect(y, y_internal);
  connect(yAttReal, yAttReal_internal);
  connect(yAttInt, yAttInt_internal);

  if use_varName then
    for i in 1:size(varName, 1) loop
      y_internal[i] = nc.ncEasyGet1D(
        fileName,
        varName[i],
        time - offset);
    end for;
  else
    for i in 1:size(varName, 1) loop
      y_internal[i] = 0;
    end for;
  end if;

  if use_attNameReal then
    for i in 1:size(attNameReal, 1) loop
      yAttReal_internal[i] = nc.ncEasyGetAttributeDouble(
        fileName,
        "",
        attNameReal[i]);
    end for;
  else
    for i in 1:size(attNameReal, 1) loop
      yAttReal_internal[i] = 0;
    end for;
  end if;

  if use_attNameInt then
    for i in 1:size(attNameInt, 1) loop
      yAttInt_internal[i] = nc.ncEasyGetAttributeLong(
        fileName,
        "",
        attNameInt[i]);
    end for;
  else
    for i in 1:size(attNameInt, 1) loop
      yAttInt_internal[i] = 0;
    end for;
  end if
  ;
end NcDataReader;

within AixLib.Utilities.Math.Functions.BaseClasses;
function der_2_regNonZeroPower
  "Power function, regularized near zero, but nonzero value for x=0"
  extends Modelica.Icons.Function;
 input Real x "Abscissa value";
 input Real n "Exponent";
 input Real delta = 0.01 "Abscissa value where transition occurs";
 input Real der_x;
 input Real der_2_x;
 output Real der_2_y "Function value";
protected
  Real a1;
  Real a3;
  Real delta2;
  Real x2;
  Real y_d "=y(delta)";
  Real yP_d "=dy(delta)/dx";
  Real yPP_d "=d^2y(delta)/dx^2";
algorithm
  if abs(x) > delta then
   der_2_y := n*(abs(x)^(n-1)*sign(x)*der_2_x
              + (n-1)*abs(x)^(n-2)*der_x^2);
  else
   delta2 :=delta*delta;
   x2 :=x*x;
   y_d :=delta^n;
   yP_d :=n*delta^(n - 1);
   yPP_d :=n*(n - 1)*delta^(n - 2);
   a1 := -(yP_d/delta - yPP_d)/delta2/8;
   a3 := (yPP_d - 12 * a1 * delta2)/2;

   der_2_y := (12*a1*x2+2*a3)*der_x^2
              +x * ( 4 * a1 * x2 + 2 * a3)*der_2_x;
  end if
;
end der_2_regNonZeroPower;

