within AixLib.Fluid.FMI.Adaptors;
model Inlet "Adaptor for connecting a fluid inlet to the FMI interface"

  replaceable package Medium =
    Modelica.Media.Interfaces.PartialMedium "Medium in the component"
      ;

  parameter Boolean allowFlowReversal = true
    "= true to allow flow reversal, false restricts to design direction (inlet -> outlet)"
    ;

  parameter Boolean use_p_in = true
    "= true to use a pressure from connector, false to output Medium.p_default"
    ;

  AixLib.Fluid.FMI.Interfaces.Inlet inlet(
    redeclare final package Medium = Medium,
    final allowFlowReversal=allowFlowReversal,
    final use_p_in=use_p_in) "Fluid inlet"
    ;

  Modelica.Fluid.Interfaces.FluidPort_b port_b(
    redeclare final package Medium=Medium) "Fluid port"
                ;
  AixLib.Fluid.FMI.Interfaces.PressureOutput p
  if use_p_in "Pressure"
  ;
protected
  AixLib.Fluid.FMI.Interfaces.FluidProperties bacPro_internal(
    redeclare final package Medium = Medium)
    "Internal connector for fluid properties for back flow";
  AixLib.Fluid.FMI.Interfaces.PressureOutput p_in_internal
    "Internal connector for pressure";
  AixLib.Fluid.FMI.Interfaces.MassFractionConnector X_w_in_internal
    "Internal connector for mass fraction of forward flow properties";
  AixLib.Fluid.FMI.Interfaces.MassFractionConnector X_w_out_internal
    "Internal connector for mass fraction of backward flow properties";
initial equation
   assert(Medium.nXi < 2,
   "The medium must have zero or one independent mass fraction Medium.nXi.");
equation
  // To locally balance the model, the pressure is only imposed at the
  // outlet model.
  // The sign is negative because inlet.m_flow > 0
  // means that fluid flows out of this component
  -port_b.m_flow     = inlet.m_flow;

  port_b.h_outflow  = Medium.specificEnthalpy_pTX(
                        p = p_in_internal,
                        T = inlet.forward.T,
                        X = if Medium.nXi == 1 then cat(1, {X_w_in_internal}, {1-X_w_in_internal}) else zeros(Medium.nX));

  port_b.C_outflow  = inlet.forward.C;

  // Conditional connector for mass fraction for forward flow
  if Medium.nXi == 0 then
    X_w_in_internal = 0;
  else
    connect(X_w_in_internal, inlet.forward.X_w);
  end if;
  port_b.Xi_outflow = fill(X_w_in_internal, Medium.nXi);

  // Conditional connector for flow reversal
  connect(inlet.backward, bacPro_internal);

  // Mass fraction for reverse flow
  X_w_out_internal = if Medium.nXi > 0 and allowFlowReversal then inStream(port_b.Xi_outflow[1]) else 0;
  connect(bacPro_internal.X_w, X_w_out_internal);

  if allowFlowReversal then
    bacPro_internal.T  = Medium.temperature_phX(
                           p = p_in_internal,
                           h = inStream(port_b.h_outflow),
                           X = cat(1, inStream(port_b.Xi_outflow), {1-sum(inStream(port_b.Xi_outflow))}));
    bacPro_internal.C  = inStream(port_b.C_outflow);
  else
    bacPro_internal.T  = Medium.T_default;
    bacPro_internal.C  = fill(0, Medium.nC);
  end if;

  // Conditional connectors for pressure
  if use_p_in then
  connect(inlet.p, p_in_internal);
  else
    p_in_internal = Medium.p_default;
  end if;
  connect(p, p_in_internal)

  ;
end Inlet;

within AixLib.Controls.HeatPump.SafetyControls;
block DefrostControl
  "Control block to ensure no frost limits heat flow at the evaporator"
  parameter Real minIceFac "Minimal value above which no defrost is necessary";
  parameter Boolean use_chiller=true
    "True if defrost operates by changing mode to cooling. False to use an electrical heater" ;
  parameter Modelica.Units.SI.Power calcPel_deFro
    "Calculate how much eletrical energy is used to melt ice"
    ;
  parameter Real deltaIceFac = 0.1 "Bandwitdth for hystereses. If the icing factor is based on the duration of defrost, this value is necessary to avoid state-events.";
  Modelica.Blocks.Logical.Hysteresis            iceFacGreMinHea(
    final uLow=minIceFac,
    final uHigh=minIceFac + deltaIceFac,
    final pre_y_start=true)
                  if not use_chiller
    "Check if icing factor is greater than a boundary" ;
 Modelica.Blocks.Interfaces.RealOutput Pel_deFro if not use_chiller
    "Relative speed of compressor. From 0 to 1" ;
  Modelica.Blocks.Sources.BooleanConstant conTrueNotUseChi(final k=true)
 if not use_chiller
    "If ice is melted with an additional heater, HP can continue running"
    ;
  Modelica.Blocks.Sources.Constant constPel_deFro(final k=calcPel_deFro)
                                                                        if not
    use_chiller "Calculate how much eletrical energy is used to melt ice"
    ;
  Modelica.Blocks.Interfaces.BooleanInput modeSet "Set value of HP mode"
    ;
  Modelica.Blocks.Interfaces.RealInput nSet
    "Set value relative speed of compressor. Analog from 0 to 1"
    ;
  Utilities.Logical.SmoothSwitch swiErr
    "If an error occurs, the value of the conZero block will be used(0)"
    ;
  Modelica.Blocks.Sources.Constant conOne(final k=1)
    "If Defrost is enabled, HP runs at full power"
    ;
  Modelica.Blocks.Interfaces.RealOutput nOut
    "Relative speed of compressor. From 0 to 1"
    ;
  Modelica.Blocks.Interfaces.BooleanOutput modeOut
    ;
  Interfaces.VapourCompressionMachineControlBus sigBusHP
    ;
  Utilities.Logical.SmoothSwitch swiPel if not use_chiller
    "If defrost is on, output will be positive" ;
  Modelica.Blocks.Sources.Constant conZero(final k=0) if not use_chiller
    "If Defrost is enabled, HP runs at full power"
    ;
  Modelica.Blocks.Logical.Hysteresis            iceFacGreMinChi(
    final uLow=minIceFac,
    final uHigh=minIceFac + deltaIceFac,
    final pre_y_start=true)
                  if use_chiller
    "Check if icing factor is greater than a boundary" ;
  Modelica.Blocks.Logical.LogicalSwitch logicalSwitch
    "If a chiller is used to defrost, mode will be false"
    ;
  Modelica.Blocks.Sources.BooleanConstant conFalseNotUseChi(final k=true)
                                                                       if not
    use_chiller "Just to omit warnings"
    ;
  Modelica.Blocks.Sources.BooleanConstant conTrueUseChi(final k=false)
 if use_chiller "Set mode to false to simulate the defrost cycle"
    ;
equation
  connect(conOne.y, swiErr.u3) ;
  connect(swiErr.y, nOut) ;
  connect(nSet, swiErr.u1) ;
  connect(sigBusHP.iceFacMea, iceFacGreMinHea.u) ;
  connect(Pel_deFro, swiPel.y)
    ;
  connect(conTrueNotUseChi.y, swiErr.u2) ;
  connect(iceFacGreMinHea.y, swiPel.u2) ;

  connect(constPel_deFro.y, swiPel.u3) ;
  connect(swiPel.u1, conZero.y) ;
  connect(sigBusHP.iceFacMea, iceFacGreMinChi.u) ;
  connect(iceFacGreMinChi.y, swiErr.u2) ;
  connect(logicalSwitch.y, modeOut) ;
  connect(modeSet, logicalSwitch.u1) ;
  connect(conTrueNotUseChi.y, logicalSwitch.u2) ;
  connect(conFalseNotUseChi.y, logicalSwitch.u3) ;
  connect(iceFacGreMinChi.y, logicalSwitch.u2) ;
  connect(conTrueUseChi.y, logicalSwitch.u3) 
  ;
end DefrostControl;

