within AixLib.Fluid.HeatExchangers.BaseClasses;
function determineWaterIndex
  "Determine the index of water in a 2-component medium model"
  input String[:] substanceNames "Names of substances of media";
  output Integer idxWat "Index of water";
protected
  Boolean found(fixed=false) "Flag, used for error checking";
  Integer N = size(substanceNames, 1) "Number of substances";
algorithm
  found:=false;
  idxWat := 1;
  for i in 1:N loop
    if Modelica.Utilities.Strings.isEqual(
        string1=substanceNames[i],
        string2="water",
        caseSensitive=false) then
        idxWat := i;
        found := true;
    end if;
  end for;
  assert(found,
    "Did not find medium species 'water' in the medium model. " +
    "Change medium model.")
  ;
end determineWaterIndex;

within AixLib.Fluid.MassExchangers.MembraneBasedEnthalpyExchangers.BaseClasses.Functions;
function NusseltNumberStephan
  "calculates nusselt number out of reynolds and prandtl number according to Stephan, K."

  // Inputs
  input Modelica.Units.SI.Length dimension "characteristic dimension";
  input Modelica.Units.SI.Length length "length of flat gap";
  input Real Pr "Prandtl number";
  input Real Re "Reynolds number";

  // Outputs
  output Real Nu "Nusselt number";

algorithm

  Nu := 7.55+(0.024*(Pr*Re*dimension/length)^(1.14))/(1+0.0358*Pr^(0.81)*
        (Pr*dimension/length)^(0.64))

  ;
end NusseltNumberStephan;

