    "If chiller is off, no heat will be exchanged"
    ;
  Modelica.Blocks.Sources.Constant constZero(final k=0)
    "Power if HP is turned off"
    ;
  SDF.NDTable nDTableQEva(
    final nin=3,
    final readFromFile=true,
    final filename=filename_QCon,
    final dataset=dataset_QCon,
    final dataUnit=dataUnit_QCon,
    final scaleUnits=scaleUnits_QCon,
    final interpMethod=interpMethod,
    final extrapMethod=extrapMethod)
    "SDF-Table data for evaporator heat flow"
    ;
  SDF.NDTable nDTablePel(
    final nin=3,
    final readFromFile=true,
    final filename=filename_Pel,
    final dataset=dataset_Pel,
    final dataUnit=dataUnit_Pel,
    final scaleUnits=scaleUnits_Pel,
    final interpMethod=interpMethod,
    final extrapMethod=extrapMethod) "SDF table data for electrical power"
                                     ;
  Modelica.Blocks.Routing.Multiplex3 multiplex3_1(
    final n1=1,
    final n2=1,
    final n3=1) "Concat all inputs into an array"
    ;

  Modelica.Blocks.Logical.GreaterThreshold greaterThreshold(final threshold=
        Modelica.Constants.eps) ;
  Modelica.Blocks.Math.Product scalingFacTimesQEva ;
  Modelica.Blocks.Math.Product scalingFacTimesPel ;
protected
  Modelica.Blocks.Sources.Constant realCorr(final k=scalingFactor)
    "Calculates correction of table output based on scaling factor"
    ;
equation
  connect(switchPel.y, Pel) ;

  connect(constZero.y,switchQEva. u3) ;
  connect(constZero.y, switchPel.u3) ;
  connect(multiplex3_1.y,nDTableQEva. u) ;
  connect(multiplex3_1.y, nDTablePel.u) ;
  connect(sigBus.TConInMea,t_Co_in. u) ;
  connect(sigBus.TEvaOutMea, t_Ev_ou.u) ;
  connect(sigBus.nSet, greaterThreshold.u) ;
  connect(greaterThreshold.y,switchQEva. u2) ;
  connect(greaterThreshold.y, switchPel.u2) ;
  connect(sigBus.nSet, nConGain.u) ;
  connect(nConGain.y, multiplex3_1.u3[1]) ;
  connect(t_Ev_ou.y, multiplex3_1.u1[1]) ;
  connect(t_Co_in.y, multiplex3_1.u2[1]) ;
  connect(switchPel.y, calcRedQCon.u2) ;
  connect(switchQEva.y, calcRedQCon.u1) ;
  connect(calcRedQCon.y, QCon)
    ;
  connect(switchQEva.y, QEva) ;
  connect(realCorr.y, scalingFacTimesPel.u2)
    ;
  connect(realCorr.y, scalingFacTimesQEva.u1) ;
  connect(nDTablePel.y, scalingFacTimesPel.u1) ;
  connect(nDTableQEva.y, scalingFacTimesQEva.u2)
    ;
  connect(scalingFacTimesQEva.y, switchQEva.u1) ;
  connect(scalingFacTimesPel.y, switchPel.u1) 
  ;
end LookUpTableND;

within AixLib.Fluid.Sources.BaseClasses;
partial model PartialSource
  "Partial component source with one fluid connector"

  replaceable package Medium =
    Modelica.Media.Interfaces.PartialMedium "Medium in the component"
      ;

  parameter Integer nPorts=0 "Number of ports" ;
  parameter Boolean verifyInputs = false
    "Set to true to stop the simulation with an error if the medium temperature is outside its allowable range"
    ;

  Modelica.Fluid.Interfaces.FluidPorts_b ports[nPorts](
    redeclare each package Medium = Medium,
    each m_flow(max=if flowDirection == Modelica.Fluid.Types.PortFlowDirection.Leaving
                    then 0 else +Modelica.Constants.inf,
                min=if flowDirection == Modelica.Fluid.Types.PortFlowDirection.Entering
                    then 0 else -Modelica.Constants.inf))
    "Fluid ports"
    ;

protected
  parameter Modelica.Fluid.Types.PortFlowDirection flowDirection=Modelica.Fluid.Types.PortFlowDirection.Bidirectional
    "Allowed flow direction" ;
  Modelica.Blocks.Interfaces.RealInput p_in_internal(final unit="Pa")
    "Needed to connect to conditional connector";
  Medium.BaseProperties medium if verifyInputs "Medium in the source";
  Modelica.Blocks.Interfaces.RealInput Xi_in_internal[Medium.nXi](
    each final unit = "kg/kg")
    "Needed to connect to conditional connector";
  Modelica.Blocks.Interfaces.RealInput X_in_internal[Medium.nX](
    each final unit = "kg/kg")
    "Needed to connect to conditional connector";
  Modelica.Blocks.Interfaces.RealInput C_in_internal[Medium.nC](
    final quantity=Medium.extraPropertiesNames)
    "Needed to connect to conditional connector";


initial equation
  // Only one connection allowed to a port to avoid unwanted ideal mixing
  for i in 1:nPorts loop
    assert(cardinality(ports[i]) <= 1,"
 Each ports[i] of boundary shall at most be connected to one component.
 If two or more connections are present, ideal mixing takes
 place in these connections, which is usually not the intention
 of the modeller. Increase nPorts to add an additional port.
 ");
  end for;

equation
  connect(medium.p, p_in_internal)

  ;
end PartialSource;

