package CellDivison "Tyson1991_CellCycle_6var"
  extends BioChem.Icons.Example;

  model cell
    extends BioChem.Compartments.MainCompartment(V(start = 1));
    import BioChem.Math.*;
    import BioChem.Constants.*;

    model EmptySet_
      extends BioChem.Substances.BoundarySubstance;
    end EmptySet_;

    model C2_
      extends BioChem.Substances.Substance
      ;
    end C2_;

    model CP_
      extends BioChem.Substances.Substance
      ;
    end CP_;

    model M_
      extends BioChem.Substances.Substance
      ;
    end M_;

    model pM_
      extends BioChem.Substances.Substance
      ;
    end pM_;

    model Y_
      extends BioChem.Substances.Substance
      ;
    end Y_;

    model YP_
      extends BioChem.Substances.Substance
      ;
    end YP_;

    model YT_
      extends BioChem.Substances.SignalSubstance
      ;
    end YT_;

    model CT_
      extends BioChem.Substances.SignalSubstance
      ;
    end CT_;

    model Reaction1_
      extends BioChem.Interfaces.Reactions.Ubi;
      parameter Real k6 = 1;
      outer Real cell_V "Variable used to access the volume of an outer compartment. Do not edit.";
    equation
      rr = cell_V * k6 * s1.c
      ;
    end Reaction1_;

    model Reaction2_
      extends BioChem.Interfaces.Reactions.Uui;
      parameter Real k8notP = 1000000.0;
      outer Real cell_V "Variable used to access the volume of an outer compartment. Do not edit.";
    equation
      rr = cell_V * s1.c * k8notP
      ;
    end Reaction2_;

    model Reaction3_
      extends BioChem.Interfaces.Reactions.Uui;
      parameter Real k9 = 1000;
      outer Real cell_V "Variable used to access the volume of an outer compartment. Do not edit.";
    equation
      rr = cell_V * s1.c * k9
      ;
    end Reaction3_;

    model Reaction4_
      extends BioChem.Interfaces.Reactions.Bui;
      parameter Real k3 = 200;
      outer Real cell_V "Variable used to access the volume of an outer compartment. Do not edit.";
    equation
      rr = cell_V * s1.c * k3 * s2.c
      ;
    end Reaction4_;

    model Reaction5_
      extends BioChem.Interfaces.Reactions.Uui;
      parameter Real k5notP = 0;
      outer Real cell_V "Variable used to access the volume of an outer compartment. Do not edit.";
    equation
      rr = cell_V * k5notP * s1.c
      ;
    end Reaction5_;

    model Reaction6_
      extends BioChem.Interfaces.Reactions.Uui;
      parameter Real k1aa = 0.015;
      outer Real cell_V "Variable used to access the volume of an outer compartment. Do not edit.";
    equation
      rr = cell_V * k1aa
      ;
    end Reaction6_;

    model Reaction7_
      extends BioChem.Interfaces.Reactions.Uui;
      parameter Real k2 = 0;
      outer Real cell_V "Variable used to access the volume of an outer compartment. Do not edit.";
    equation
      rr = cell_V * k2 * s1.c
      ;
    end Reaction7_;

    model Reaction8_
      extends BioChem.Interfaces.Reactions.Uui;
      parameter Real k7 = 0.6;
      outer Real cell_V "Variable used to access the volume of an outer compartment. Do not edit.";
    equation
      rr = cell_V * k7 * s1.c
      ;
    end Reaction8_;

    model Reaction9_
      extends BioChem.Interfaces.Reactions.Uui;
      extends BioChem.Interfaces.Reactions.Modifiers.Modifier;
      parameter Real k4 = 180;
      parameter Real k4prime = 0.018;
      outer Real cell_V "Variable used to access the volume of an outer compartment. Do not edit.";
    equation
      rr = cell_V * s1.c * (k4prime + k4 * (p1.c / m1.c) ^ 2)
      ;
    end Reaction9_;

    inner Real cell_V = V "Variable used to make the compartment volume accessible for inner components. Do not edit.";
    CellDivison.cell.EmptySet_ EmptySet(c(start = 0)) ;
    CellDivison.cell.C2_ C2(c(start = 0)) "cdc2k" ;
    CellDivison.cell.CP_ CP(c(start = 0.75)) "cdc2k-P" ;
    CellDivison.cell.M_ M(c(start = 0)) "p-cyclin_cdc2" ;
    CellDivison.cell.pM_ pM(c(start = 0.25)) "p-cyclin_cdc2-p" ;
    CellDivison.cell.Y_ Y(c(start = 0)) "cyclin" ;
    CellDivison.cell.YP_ YP(c(start = 0)) "p-cyclin" ;
    CellDivison.cell.YT_ YT(c(start = 0)) "total_cyclin" ;
    CellDivison.cell.CT_ CT(c(start = 0)) "total_cdc2" ;
    CellDivison.cell.Reaction1_ Reaction1 "cyclin_cdc2k dissociation" ;
    CellDivison.cell.Reaction2_ Reaction2 "cdc2k phosphorylation" ;
    CellDivison.cell.Reaction3_ Reaction3 "cdc2k dephosphorylation" ;
    CellDivison.cell.Reaction4_ Reaction4 "cyclin cdc2k-p association" ;
    CellDivison.cell.Reaction5_ Reaction5 "deactivation of cdc2 kinase" ;
    CellDivison.cell.Reaction6_ Reaction6 "cyclin biosynthesis" ;
    CellDivison.cell.Reaction7_ Reaction7 "default degradation of cyclin" ;
    CellDivison.cell.Reaction8_ Reaction8 "cdc2 kinase triggered degration of cyclin" ;
    CellDivison.cell.Reaction9_ Reaction9 "activation of cdc2 kinase" ;
  equation
    connect(CP.n1, Reaction2.p1) ;
    connect(C2.n1, Reaction2.s1) ;
    connect(CP.n1, Reaction3.s1) ;
    connect(CP.n1, Reaction4.s1) ;
    connect(C2.n1, Reaction3.p1) ;
    connect(C2.n1, Reaction1.p1) ;
    connect(Y.n1, Reaction4.s2) ;
    connect(pM.n1, Reaction4.p1) ;
    connect(Y.n1, Reaction7.s1) ;
    connect(Y.n1, Reaction6.p1) ;
    connect(M.n1, Reaction1.s1) ;
    connect(M.n1, Reaction5.s1) ;
    connect(M.n1, Reaction9.p1) ;
    connect(pM.n1, Reaction5.p1) ;
    connect(pM.n1, Reaction9.s1) ;
    connect(CT.n1, Reaction9.m1) ;
    connect(EmptySet.n1, Reaction6.s1) ;
    connect(EmptySet.n1, Reaction7.p1) ;
    connect(EmptySet.n1, Reaction8.p1) ;
    connect(YP.n1, Reaction8.s1) ;
    connect(YP.n1, Reaction1.p2) ;
    YT.c = Y.c + YP.c + M.c + pM.c;
    CT.c = C2.c + CP.c + M.c + pM.c
    ;
  end cell

  ;
