package GMO "Goldbeter1991_MinMitOscil"
  extends BioChem.Icons.Example;

  model cell "cell"
    extends BioChem.Compartments.MainCompartment(V(start = 1));
    import BioChem.Math.*;
    import BioChem.Constants.*;

    model C_
      extends BioChem.Substances.Substance
      ;
    end C_;

    model M_
      extends BioChem.Substances.Substance
      ;
    end M_;

    model X_
      extends BioChem.Substances.Substance;
    end X_;

    model reaction1_
      extends BioChem.Interfaces.Reactions.Uui;
      parameter Real vi = 0.025;
      outer Real cell_V "Variable used to access the volume of an outer compartment. Do not edit.";
    equation
      rr = cell_V * vi
      ;
    end reaction1_;

    model reaction2_
      extends BioChem.Interfaces.Reactions.Uui;
      parameter Real kd = 0.01;
      outer Real cell_V "Variable used to access the volume of an outer compartment. Do not edit.";
    equation
      rr = s1.c * cell_V * kd
      ;
    end reaction2_;

    model reaction3_
      extends BioChem.Interfaces.Reactions.Uui;
      extends BioChem.Interfaces.Reactions.Modifiers.Modifier;
      parameter Real vd = 0.25;
      parameter Real Kd = 0.02;
      outer Real cell_V "Variable used to access the volume of an outer compartment. Do not edit.";
    equation
      rr = s1.c * cell_V * vd * m1.c * (s1.c + Kd) ^ (-1)
      ;
    end reaction3_;

    model reaction4_
      extends BioChem.Interfaces.Reactions.Uui;
      parameter Real K1 = 0.005;
      outer Real cell_V "Variable used to access the volume of an outer compartment. Do not edit.";
      Real V1;
    equation
      rr = cell_V * (1 + (-1) * p1.c) * V1 * (K1 + (-1) * p1.c + 1) ^ (-1)
      ;
    end reaction4_;

    model reaction5_
      extends BioChem.Interfaces.Reactions.Uui;
      parameter Real V2 = 1.5;
      parameter Real K2 = 0.005;
      outer Real cell_V "Variable used to access the volume of an outer compartment. Do not edit.";
    equation
      rr = cell_V * s1.c * V2 * (K2 + s1.c) ^ (-1)
      ;
    end reaction5_;

    model reaction6_
      extends BioChem.Interfaces.Reactions.Uui;
      parameter Real K3 = 0.005;
      outer Real cell_V "Variable used to access the volume of an outer compartment. Do not edit.";
      Real V3;
    equation
      rr = cell_V * V3 * (1 + (-1) * p1.c) * (K3 + (-1) * p1.c + 1) ^ (-1);
    end reaction6_;

    model reaction7_
      extends BioChem.Interfaces.Reactions.Uui;
      parameter Real K4 = 0.005;
      parameter Real V4 = 0.5;
      outer Real cell_V "Variable used to access the volume of an outer compartment. Do not edit.";
    equation
      rr = cell_V * V4 * s1.c * (K4 + s1.c) ^ (-1);
    end reaction7_;

    inner Real cell_V = V "Variable used to make the compartment volume accessible for inner components. Do not edit.";
    BioChem.Examples.GMO.cell.C_ C(c(start = 0.01)) "Cyclin" ;
    BioChem.Examples.GMO.cell.M_ M(c(start = 0.01)) "CDC-2 Kinase" ;
    BioChem.Examples.GMO.cell.X_ X(c(start = 0.01)) "Cyclin Protease" ;
    Real V1 "V1";
    Real V3 "V3";
    parameter Real VM1 = 3 "VM1";
    parameter Real VM3 = 1 "VM3";
    parameter Real Kc = 0.5 "Kc";
    BioChem.Substances.AmbientSubstance ambientSubstance ;
    BioChem.Examples.GMO.cell.reaction1_ reaction1 "creation of cyclin" ;
    BioChem.Examples.GMO.cell.reaction2_ reaction2 "default degradation of cyclin" ;
    BioChem.Examples.GMO.cell.reaction3_ reaction3 "cdc2 kinase triggered degration of cyclin" ;
    BioChem.Examples.GMO.cell.reaction4_ reaction4(V1 = V1) "activation of cdc2 kinase" ;
    BioChem.Examples.GMO.cell.reaction5_ reaction5 "deactivation of cdc2 kinase" ;
    BioChem.Examples.GMO.cell.reaction6_ reaction6(V3 = V3) "activation of cyclin protease" ;
    BioChem.Examples.GMO.cell.reaction7_ reaction7 "deactivation of cyclin protease" ;
  equation
    connect(X.n1, reaction7.s1) ;
    connect(ambientSubstance.n1, reaction7.p1) ;
    connect(X.n1, reaction6.p1) ;
    connect(X.n1, reaction3.m1) ;
    connect(ambientSubstance.n1, reaction6.s1) ;
    connect(M.n1, reaction4.p1) ;
    connect(ambientSubstance.n1, reaction4.s1) ;
    connect(M.n1, reaction5.s1) ;
    connect(ambientSubstance.n1, reaction5.p1) ;
    connect(C.n1, reaction2.s1) ;
    connect(ambientSubstance.n1, reaction2.p1) ;
    connect(C.n1, reaction1.p1) ;
    connect(ambientSubstance.n1, reaction1.s1) ;
    connect(ambientSubstance.n1, reaction3.p1) ;
    connect(C.n1, reaction3.s1) ;
    V1 = C.c * VM1 * (C.c + Kc) ^ (-1);
    V3 = M.c * VM3
    ;
  end cell

  ;
end GMO;

