within BioChem.Math;

function factorial "factorial function, product of all positive integers less than or equal to n"
  input Integer n "input value";
  output Integer y "output value";
protected
  Integer i;
algorithm
  y := n;
  i := n;
  while i > 1 loop
    i := i - 1;
    y := y * i;
  end while
  ;
end factorial;

