model IncrementalEncoder "Incremental encoder"
  extends Modelica.Mechanics.Rotational.Interfaces.PartialOneFlangeAndSupport;
  import Modelica.Constants.pi;
  parameter Integer pRev(final min=1, start=128) "Pulses per revolution";
  Modelica.Blocks.Interfaces.BooleanOutput y[3] "Encoder signals"
    ;
  Modelica.Mechanics.Rotational.Sensors.RelAngleSensor relAngleSensor
    ;
  Modelica.Blocks.Math.WrapAngle wrapAngle1(positiveRange=true)
    ;
  Modelica.Blocks.Math.Gain gain(k=pRev)
    ;
  ToMSL.IntervalTest intervalTest1(
    constantLowerLimit=0,
    constantUpperLimit=2*pi/pRev/4,
    InsideInterval=true)
    ;
  ToMSL.IntervalTest intervalTest2(
    constantLowerLimit=pi/2,
    constantUpperLimit=3*pi/2,
    InsideInterval=false)
    ;
  ToMSL.IntervalTest intervalTest3(
    constantLowerLimit=0,
    constantUpperLimit=pi,
    InsideInterval=true)
    ;
  Modelica.Blocks.Math.WrapAngle wrapAngle2(positiveRange=true)
    ;
equation
  connect(relAngleSensor.flange_b, flange)
    ;
  connect(internalSupport, relAngleSensor.flange_a) ;
  connect(relAngleSensor.phi_rel, wrapAngle1.u)
    ;
  connect(wrapAngle1.y, gain.u)
    ;
  connect(intervalTest2.y, y[2])
    ;
  connect(intervalTest3.y, y[3]) ;
  connect(intervalTest1.y, y[1]) ;
  connect(wrapAngle1.y, intervalTest1.u) ;
  connect(gain.y, wrapAngle2.u)
    ;
  connect(wrapAngle2.y, intervalTest2.u)
    ;
  connect(wrapAngle2.y, intervalTest3.u) 
  ;
end IncrementalEncoder;

within BLDC.Sensors;
model SinCosResolver "Sin/Cos-Resolver"
  extends Modelica.Mechanics.Rotational.Interfaces.PartialOneFlangeAndSupport;
  import Modelica.Constants.pi;
  parameter Integer p(final min=1, start=2) "Number of pole pairs";
  parameter Real offset=1.5 "Offset of output";
  parameter Real amplitude=1 "Amplitude of output";
  parameter Modelica.Units.SI.Angle phi0=0 "Initial mechanical angle (zero position)";
  Modelica.Mechanics.Rotational.Sensors.RelAngleSensor relAngleSensor
    ;
  Modelica.Blocks.Math.Add add(k1=p, k2=p)
    ;
  Modelica.Blocks.Sources.Constant const(k=phi0)
    ;
  Modelica.Blocks.Math.Cos cos1
    ;
  Modelica.Blocks.Math.Sin sin1
    ;
  Modelica.Blocks.Interfaces.RealOutput y[4] "Resolver signals"
    ;
  Modelica.Blocks.Math.Add add1(k1=+amplitude)
    ;
  Modelica.Blocks.Math.Add addOffset2(k1=-amplitude)
    ;
  Modelica.Blocks.Math.Add addOffset3(k1=amplitude)
    ;
  Modelica.Blocks.Math.Add addOffset4(k1=-amplitude)
    ;
  Modelica.Blocks.Sources.Constant constOffset(k=offset)
    ;
equation
  connect(add.u1, relAngleSensor.phi_rel)
    ;
  connect(const.y, add.u2)
    ;
  connect(add.y, sin1.u)
    ;
  connect(add.y, cos1.u)
    ;
  connect(addOffset4.y, y[4]) ;
  connect(addOffset3.y, y[3]) ;
  connect(addOffset2.y, y[2]) ;
  connect(add1.y, y[1]) ;
  connect(internalSupport, relAngleSensor.flange_a)
    ;
  connect(sin1.y, addOffset4.u1) ;
  connect(sin1.y, addOffset3.u1) ;
  connect(cos1.y, addOffset2.u1) ;
  connect(cos1.y, add1.u1) ;
  connect(constOffset.y, addOffset4.u2) ;
  connect(constOffset.y, addOffset3.u2) ;
  connect(constOffset.y, addOffset2.u2) ;
  connect(constOffset.y, add1.u2) ;
  connect(relAngleSensor.flange_b, flange) 
  ;
end SinCosResolver;

within BLDC.ToMSL;
block IntervalTest
  "Output y is true, if input u is within the specified interval"
   extends Modelica.Blocks.Interfaces.partialBooleanSO;
  parameter Boolean useConstantLimits=true "Otherwise dynamic inputs" ;
  parameter Real constantLowerLimit "Lower limit of interval" ;
  parameter Boolean ClosedOnLeft=false "Include lower limit?" ;
  parameter Real constantUpperLimit "Upper limit of interval" ;
  parameter Boolean ClosedOnRight=false "Include upper limit?" ;
  parameter Boolean InsideInterval=true "u inside interval?" ;
  Modelica.Blocks.Interfaces.RealInput u ;
  Modelica.Blocks.Interfaces.RealInput lowerLimit if not useConstantLimits
    ;
  Modelica.Blocks.Interfaces.RealInput upperLimit if not useConstantLimits
    ;
protected
  Modelica.Blocks.Interfaces.RealInput lowerLimitInternal ;
  Modelica.Blocks.Interfaces.RealInput upperLimitInternal ;
equation
  if useConstantLimits then
    upperLimitInternal = constantUpperLimit;
    lowerLimitInternal = constantLowerLimit;
  else
    connect(upperLimitInternal, upperLimit);
    connect(lowerLimitInternal, lowerLimit);
  end if;
  assert(upperLimitInternal>lowerLimitInternal,"Erroneous interval limits");
  if ClosedOnLeft then
    if ClosedOnRight then
      if InsideInterval then
        y = u>=lowerLimitInternal and u<=upperLimitInternal;
      else
        y = u< lowerLimitInternal or  u> upperLimitInternal;
      end if;
    else
      if InsideInterval then
        y = u>=lowerLimitInternal and u< upperLimitInternal;
      else
        y = u< lowerLimitInternal or  u>=upperLimitInternal;
      end if;
    end if;
  else
    if ClosedOnRight then
      if InsideInterval then
        y = u> lowerLimitInternal and u<=upperLimitInternal;
      else
        y = u<=lowerLimitInternal or  u> upperLimitInternal;
      end if;
    else
      if InsideInterval then
        y = u> lowerLimitInternal and u< upperLimitInternal;
      else
        y = u<=lowerLimitInternal or  u>=upperLimitInternal;
      end if;
    end if;
  end if
  ;
end IntervalTest;

