block ElectronicCommutator "Polyphase electronic commutator"
  extends Modelica.Blocks.Icons.BooleanBlock;
  import Modelica.Units.SI;
  import Modelica.Constants.pi;
  import Modelica.ComplexMath.j;
  import Modelica.ComplexMath.arg;
  import Modelica.Math.wrapAngle;
  import Modelica.Electrical.Polyphase.Functions.symmetricOrientation;
  parameter Integer m(min=3) = 3 "Number of stator phases";
  parameter Modelica.Units.SI.Angle orientation[m]=symmetricOrientation(m)
    "Orientation of phases";
  parameter Boolean useConstantPWM=true "Otherwise input" ;
  parameter Boolean ConstantPWM=true "PWM resp. direction" ;
  Modelica.Blocks.Interfaces.BooleanInput pwm if not useConstantPWM
    ;
  Modelica.Blocks.Interfaces.BooleanInput uC[m] "Commutation signals"
    ;
  Modelica.Blocks.Interfaces.BooleanOutput fire_p[m]
    "Fire signals of positive potential transistors"
    ;
  Modelica.Blocks.Interfaces.BooleanOutput fire_n[m]
    "Fire signals of negative potential transistors"
    ;
protected
  constant SI.Angle eps=1e-3;
  parameter Modelica.Units.SI.Angle wrappedOrientation[m]=wrapAngle(orientation, true) "Orientation of phases within [0, 2*pi)";
  Complex cRotorPosition=Modelica.ComplexMath.sum({if uC[k] then Modelica.ComplexMath.exp(j*orientation[k]) else Complex(0) for k in 1:m})
    "Phasor pointing into the direction of the rotor";
  SI.Angle rotorPosition=wrapAngle(arg(cRotorPosition), true) "Rotor position in the range [0, 2*pi]";
  SI.Angle diff[m]=wrapAngle(orientation - fill(rotorPosition, m), false) "Difference between orientation and rotor position";
  Modelica.Blocks.Interfaces.BooleanInput internalPWM ;
equation
  if useConstantPWM then
    internalPWM=ConstantPWM;
  else
    connect(internalPWM, pwm);
  end if;
  assert(mod(m,2)<>0, "Electronic commutator not working properly for even number of phases!");
  fire_p={if abs(diff[k] - pi/2)<=pi/(2*m)+eps then internalPWM
      elseif abs(diff[k] + pi/2)<=pi/(2*m)+eps then not internalPWM else false for k in 1:m};
  fire_n={if abs(diff[k] + pi/2)<=pi/(2*m)+eps then internalPWM
      elseif abs(diff[k] - pi/2)<=pi/(2*m)+eps then not internalPWM else false for k in 1:m}
  ;
end ElectronicCommutator;

within BLDC.Utilities;
block ElectronicCommutator3phase "Electronic commutator for 3 phases"
  extends Modelica.Blocks.Icons.BooleanBlock;
  constant Integer m=3 "Number of phases";
  parameter Boolean useConstantPWM=true "Otherwise input" ;
  parameter Boolean ConstantPWM=true "PWM resp. direction" ;
  Modelica.Blocks.Interfaces.BooleanInput pwm if not useConstantPWM
    ;
  Modelica.Blocks.Interfaces.BooleanInput uC[m] "Commutation signals"
    ;
  Modelica.Blocks.Interfaces.BooleanOutput fire_p[m]
    "Fire signals of positive potential transistors"
    ;
  Modelica.Blocks.Interfaces.BooleanOutput fire_n[m]
    "Fire signals of negative potential transistors"
    ;
protected
  constant Integer I1[6]={2,3,2,1,1,3} "Indices of on states in sectors";
  constant Integer I0[6]={3,1,1,2,3,2} "Indices of off states in sectors";
  constant Integer Ix[6]={1,2,3,3,2,1} "Indices of open states in sectors";
  //Angle    0  60 120 180 240 300
  //Sector   1   2   3   4   5   6
  //Hall   100 110 010 011 001 101
  //Fire   x10 01x 0x1 x01 10x 1x0
  Integer c=sum({if uC[k] then integer(2^(k - 1)) else 0 for k in 1:m}) "Sector code";
  Modelica.Blocks.Interfaces.BooleanInput internalPWM ;
equation
  if useConstantPWM then
    internalPWM=ConstantPWM;
  else
    connect(internalPWM, pwm);
  end if;
algorithm
  assert(c>=1 and c<=6, "Hall sensor sector error!");
  fire_p[I1[c]]:=internalPWM;
  fire_n[I1[c]]:=not internalPWM;
  fire_p[I0[c]]:=not internalPWM;
  fire_n[I0[c]]:=internalPWM;
  fire_p[Ix[c]]:=false;
  fire_n[Ix[c]]:=false
  ;
end ElectronicCommutator3phase;

within BLDC.Utilities;
block EncoderPulseCount "Count pulses of an incremental encoder"
  extends Modelica.Blocks.Interfaces.DiscreteBlock(samplePeriod=0.01);
  extends BLDC.Interfaces.EncoderEvaluation;
  import Modelica.Constants.pi;
  import BLDC.Functions.directionOfRotation;
protected
  Integer count(start=0, fixed=true) "count of edges";
algorithm
  when {edge(A), edge(notA), edge(B), edge(notB)} then
    count:=pre(count) + directionOfRotation(A, pre(A), B, pre(B));
  end when;
  when sampleTrigger then
    w:=pre(count)*2*pi/(4*pRev)/samplePeriod;
    count:=0;
  end when
  ;
end EncoderPulseCount;

within BLDC.Utilities;
block EncoderTimeAndCount
  "Measure time spaen between first and last edge of an incremental encoder with samplePrriod"
  extends Modelica.Blocks.Interfaces.DiscreteBlock(samplePeriod=0.01);
  extends BLDC.Interfaces.EncoderEvaluation;
  import Modelica.Constants.pi;
  import Modelica.Constants.eps;
  import BLDC.Functions.directionOfRotation;
protected
  Integer count(start=0, fixed=true) "count of edges";
  Boolean firstEdge(start=true, fixed=true) "true at first edge";
  discrete Modelica.Units.SI.Time t1(start=0, fixed=true) "time instant of first edge";
  discrete Modelica.Units.SI.Time t2(start=0, fixed=true) "time instant of last edge";
algorithm
  when {edge(A), edge(notA), edge(B), edge(notB)} then
    count:=pre(count) + directionOfRotation(A, pre(A), B, pre(B));
    if pre(firstEdge) then
      firstEdge:=false;
      t1:=time;
    else
      t2:=time;
    end if;
  end when;
  when sampleTrigger then
    w:=if noEvent(pre(t2) - pre(t1) < eps) then 0
  else sign(pre(count))*(abs(pre(count)) - 1)*2*pi/(4*pRev)/(pre(t2) - pre(t1));
    count:=0;
    firstEdge:=true;
    t1:=0;
    t2:=0;
  end when
  ;
end EncoderTimeAndCount;

within BLDC.Utilities;
block EncoderTimeSpan "Time span between edges of incremental encoder signals"
  extends Modelica.Blocks.Icons.DiscreteBlock;
  extends BLDC.Interfaces.EncoderEvaluation;
  import Modelica.Constants.pi;
  import Modelica.Constants.eps;
  import BLDC.Functions.directionOfRotation;
protected
  Boolean firstEdge "true at first edge";
  discrete Modelica.Units.SI.Time t0 "time instant of preceding edge";
initial equation
  firstEdge=true;
  t0=time;
equation
  when {edge(A), edge(notA), edge(B), edge(notB)} then
    w=directionOfRotation(A, pre(A), B, pre(B))*
      (if noEvent(time - pre(t0) < eps) or pre(firstEdge) then 0
       else 2*pi/(4*pRev)/(time - pre(t0)));
    firstEdge=false;
    t0=time;
  end when
  ;
end EncoderTimeSpan;

within BLDC.Utilities;
block HallTimeSpan "Time span between edges of Hall signals"
  extends Modelica.Blocks.Icons.DiscreteBlock;
  import Modelica.Units.SI;
  import Modelica.Constants.pi;
  import Modelica.Constants.eps;
  import Modelica.Math.BooleanVectors.firstTrueIndex;
  import BLDC.Functions.addIndex;
  parameter Integer p(final min=1, start=2) "Number of pole pairs";
  parameter Integer m(min=3) = 3 "Number of stator phases";
  parameter SI.Angle orientation[m]=
    Modelica.Electrical.Polyphase.Functions.symmetricOrientation(m) "Orientation of phases";
  parameter SI.Angle phi0=0 "Initial mechanical angle (zero position)";
  Modelica.Blocks.Interfaces.BooleanInput uC[m] "Hall signals"
    ;
  Modelica.Blocks.Interfaces.RealOutput w(final unit="rad/s", displayUnit="rpm", start=0, fixed=true)
    "Mechanical anglar velocity"
    ;
  Modelica.Blocks.Interfaces.RealOutput phi(final unit="rad", displayUnit="deg")
    "Mechanical angle"
    ;
protected
  Boolean notC[m]=not uC;
  Boolean firstEdge "true at first edge";
  Modelica.Units.SI.Time t0 "time instant of last edge";
initial equation
  pre(uC)=fill(false,m);
  pre(notC)=fill(true,m);
  firstEdge=true;
  t0=time;
  phi=phi0;
equation
  der(phi)= w;
  when {edge(uC[k]) for k in 1:m} then
    w= (if not uC[addIndex(firstTrueIndex(uC and not pre(uC)), 1, m)] then +1 else -1)*
       (if noEvent(time - pre(t0) < eps) or pre(firstEdge) then 0 else 2*pi/(2*m)/(time - pre(t0)));
    firstEdge= false;
    t0= time;
  elsewhen {edge(notC[k]) for k in 1:m} then
    w= (if not uC[addIndex(firstTrueIndex(notC and not pre(notC)), 1, m)] then -1 else +1)*
       (if noEvent(time - pre(t0) < eps) or pre(firstEdge) then 0 else 2*pi/(2*m)/(time - pre(t0)));
    firstEdge= false;
    t0= time;
  end when
  ;
end HallTimeSpan;

