  Modelica.Blocks.Sources.Constant pMaxSig(k=pMax)
    ;
  Modelica.Blocks.Sources.Constant pMinSig(k=pMin)
    ;
  Modelica.Blocks.Math.Add pSet "Pressure setpoint"
    ;
  Modelica.Blocks.Math.Product product
    ;
equation
