  connect(ySet.y, limPID.u_s) ;
  connect(max.y, limPID.u_m) ;
  connect(limPID.y, product.u1) ;
  connect(pMaxSig.y, dp.u1) ;
  connect(pMinSig.y, dp.u2) ;
  connect(dp.y, product.u2) ;
  connect(pMinSig.y, pSet.u2) ;
  connect(pSet.y, y) ;
  connect(product.y, pSet.u1) 
  ;
