  // thermal properties
  input Modelica.Units.SI.ThermalConductivity kMed
    "Thermal conductivity of the fluid";
  input Modelica.Units.SI.DynamicViscosity muMed
    "Dynamic viscosity of the fluid";
  input Modelica.Units.SI.SpecificHeatCapacity cpMed
    "Specific heat capacity of the fluid";
  input Modelica.Units.SI.MassFlowRate m_flow "Mass flow rate";
  input Modelica.Units.SI.MassFlowRate m_flow_nominal "Nominal mass flow rate";

  // Outputs
  output Modelica.Units.SI.ThermalResistance RFluPip
    "Convection resistance (or conduction in fluid if no mass flow)";

protected
  Modelica.Units.SI.Radius rTub_in=rTub - eTub "Pipe inner radius";
  Modelica.Units.SI.CoefficientOfHeatTransfer h
    "Convective heat transfer coefficient of the fluid";

  Real k(unit="s/kg")
    "Coefficient used in the computation of the convective heat transfer coefficient";
  Modelica.Units.SI.MassFlowRate m_flow_abs=
      Buildings.Utilities.Math.Functions.spliceFunction(
      m_flow,
      -m_flow,
      m_flow,
      m_flow_nominal/30);
  Real Re "Reynolds number";
  Real NuTurb "Nusselt at Re=2400";
  Real Nu "Nusselt";

algorithm
  // Convection resistance and Reynolds number
  k := 2/(muMed*Modelica.Constants.pi*rTub_in);
  Re := m_flow_abs*k;

  if Re>=2400 then
    // Turbulent, fully-developped flow in a smooth circular pipe with the
    // Dittus-Boelter correlation: h = 0.023*k_f*Re*Pr/(2*rTub)
    // Re = rho*v*DTub / mue_f
    //    = m_flow/(pi r^2) * DTub/mue_f = 2*m_flow / ( mue*pi*rTub)
    Nu := 0.023*(cpMed*muMed/kMed)^(0.35)*
      Buildings.Utilities.Math.Functions.regNonZeroPower(
        x=Re,
        n=0.8,
        delta=0.01*m_flow_nominal*k);
  else
    // Laminar, fully-developped flow in a smooth circular pipe with uniform
    // imposed temperature: Nu=3.66 for Re<=2300. For 2300<Re<2400, a smooth
    // transition is created with the splice function.
    NuTurb := 0.023*(cpMed*muMed/kMed)^(0.35)*(2400)^(0.8);
    Nu := Buildings.Utilities.Math.Functions.spliceFunction(NuTurb,3.66,Re-(2300+2400)/2,((2300+2400)/2)-2300);
  end if;
  h := Nu*kMed/(2*rTub_in);

  RFluPip := 1/(2*Modelica.Constants.pi*rTub_in*hSeg*h)

  ;
end convectionResistanceCircularPipe;

within Buildings.Fluid.CHPs.BaseClasses.Functions;
function polynomialtrivariate
  "Polynominal function used for efficiency calculation"
  extends Modelica.Icons.Function;

  input Real x1 "Independent variable";
  input Real x2 "Independent variable";
  input Real x3 "Independent variable";
  input Real a[27] "Coefficients";
  output Real y "Result";

protected
 Real x1Sq = x1^2;
 Real x2Sq = x2^2;
 Real x3Sq = x3^2;

algorithm
  y := a[1] + a[2]*x1Sq + a[3]*x1
            + a[4]*x2Sq + a[5]*x2
            + a[6]*x3Sq + a[7]*x3
            + a[8]*x1Sq*x2Sq + a[9]*x1*x2 + a[10]*x1*x2Sq + a[11]*x1Sq*x2
            + a[12]*x1Sq*x3Sq + a[13]*x1*x3 + a[14]*x1*x3Sq + a[15]*x1Sq*x3
            + a[16]*x2Sq*x3Sq + a[17]*x2*x3 + a[18]*x2*x3Sq + a[19]*x2Sq*x3
            + a[20]*x1Sq*x2Sq*x3Sq + a[21]*x1Sq*x2Sq*x3 + a[22]*x1Sq*x2*x3Sq + a[23]*x1*x2Sq*x3Sq
            + a[24]*x1Sq*x2*x3 + a[25]*x1*x2Sq*x3 + a[26]*x1*x2*x3Sq
            + a[27]*x1*x2*x3

;
end polynomialtrivariate;

within Buildings.Controls.OBC.CDL.Logical.Sources;
block Pulse
  "Generate pulse signal of type Boolean"
  parameter Real width(
    final min=Constants.small,
    final max=1,
    final unit="1")=0.5
    "Width of pulse in fraction of period";
  parameter Real period(
    final quantity="Time",
    final unit="s",
    final min=Constants.small)
    "Time for one period";
  parameter Real shift(
    final quantity="Time",
    final unit="s")=0
    "Shift time for output";
  Buildings.Controls.OBC.CDL.Interfaces.BooleanOutput y
    "Connector of Boolean output signal"
    ;

protected
  parameter Real t0(
    final quantity="Time",
    final unit="s",
    fixed=false)
    "First sample time instant";
  parameter Real t1(
    final quantity="Time",
    final unit="s",
    fixed=false)
    "First end of amplitude";

initial algorithm
  t0 := Buildings.Utilities.Math.Functions.round(
    x=integer((time)/period)*period+mod(shift,period),
    n=6);
  t1 := t0+width*period;
  // Make sure t0 and t1 are within time + period.
  if time+period < t1 then
    t0 := t0-period;
    t1 := t1-period;
  end if;
  // Make sure time is between t0 and t1, or t1 and t0
  // Now, t0 < t1
  if time >= t1 then
    t0 := t0+period;
  elseif time < t0 then
    t1 := t1-period;
  end if;
  // Assert that t0 <= t < t1 or t1 <= t < t0
  if
    (t0 < t1) then
    assert(
      t0 <= time and time < t1,
      getInstanceName()+": Implementation error in initial time calculation: t0 = "+String(t0)+", t1 = "+String(t1)+",  period = "+String(period)+", time = "+String(time));
    y := time >= t0 and time < t1;
  else
    assert(
      t1 <= time and time < t0,
      getInstanceName()+": Implementation error in initial time calculation: t0 = "+String(t0)+", t1 = "+String(t1)+",  period = "+String(period)+", time = "+String(time));
    y := not
            (time >= t1 and time < t0);
  end if;

equation
  when sample(
    t0,
    period) then
    y=true;
  elsewhen sample(
    t1,
    period) then
    y=false;
  end when
  ;
end Pulse;

