within Buildings.Templates.Plants.Controls.StagingRotation;
block StageAvailability
  "Compute stage availability"
  parameter Real staEqu[:,:](
    each unit="1",
    each min=0,
    each max=1)
    "Staging matrix – Equipment required for each stage";
  final parameter Integer nSta=size(staEqu, 1)
    "Number of stages"
    ;
  final parameter Integer nEqu=size(staEqu, 2)
    "Number of equipment"
    ;
  Buildings.Controls.OBC.CDL.Interfaces.BooleanInput u1Ava[nEqu]
    "Equipment available signal"
    ;
  Buildings.Controls.OBC.CDL.Interfaces.BooleanOutput y1[nSta]
    "Stage available signal"
    ;
  Buildings.Controls.OBC.CDL.Reals.Sources.Constant matStaEqu[nSta, nEqu](
    final k=staEqu)
    "Staging matrix"
    ;
  Buildings.Controls.OBC.CDL.Reals.GreaterThreshold isReq[nSta, nEqu](
    each final t=0.99)
    "Return true if equipment required without lead/lag alternate"
    ;
  Buildings.Controls.OBC.CDL.Reals.GreaterThreshold isReqPosAlt[nSta, nEqu](
    each final t=0)
    "Return true if equipment required (with or without lead/lag alternate)"
    ;
  Buildings.Controls.OBC.CDL.Reals.LessThreshold isNotReqNoAlt[nSta, nEqu](
    each final t=1)
    "Return true if equipment not required or required with lead/lag alternate"
    ;
  Buildings.Controls.OBC.CDL.Routing.BooleanVectorReplicator booVecRep(
    final nin=nEqu,
    final nout=nSta)
    "Replicate equipment available signal"
    ;
  Buildings.Controls.OBC.CDL.Logical.And isReqAva[nSta, nEqu]
    "Return true if equipment required without lead/lag alternate and available"
    ;
  Buildings.Controls.OBC.CDL.Logical.And isReqAltAva[nSta, nEqu]
    "Return true if equipment required (with or without lead/lag alternate) and available"
    ;
  Buildings.Controls.OBC.CDL.Logical.Or isReqAvaOrNotReq[nSta, nEqu]
    "Return true if equipment required without lead/lag alternate and available, or if not required"
    ;
  Buildings.Controls.OBC.CDL.Logical.MultiAnd all[nSta](
    each final nin=nEqu)
    "Return true if previous block condition valid for all elements"
    ;
  Buildings.Controls.OBC.CDL.Logical.And isAva[nSta]
    "Return true if stage available"
    ;
  Buildings.Controls.OBC.CDL.Reals.MultiSum nEquSta[nSta](
    each final nin=nEqu)
    "Return the number of equipment required at each stage"
    ;
  Buildings.Controls.OBC.CDL.Conversions.BooleanToInteger booToInt[nSta, nEqu]
    "Convert to integer"
    ;
  Buildings.Controls.OBC.CDL.Integers.GreaterEqual isReqAltAvaGreReq[nSta]
    "Return true if number of required available equipment higher than number of required equipment"
    ;
  Buildings.Controls.OBC.CDL.Integers.MultiSum nReqAltAva[nSta](
    each final nin=nEqu)
    "Number of equipment required (with or without lead/lag alternate) and available"
    ;
  Buildings.Controls.OBC.CDL.Conversions.RealToInteger nEquStaInt[nSta]
    "Integer cast of number of equipment required at each stage"
    ;
equation
  connect(matStaEqu.y, isReq.u)
    ;
  connect(matStaEqu.y, isReqPosAlt.u)
    ;
  connect(matStaEqu.y, isNotReqNoAlt.u)
    ;
  connect(isReq.y, isReqAva.u1)
    ;
  connect(booVecRep.y, isReqAva.u2)
    ;
  connect(booVecRep.y, isReqAltAva.u2)
    ;
  connect(isReqAva.y, isReqAvaOrNotReq.u2)
    ;
  connect(isNotReqNoAlt.y, isReqAvaOrNotReq.u1)
    ;
  connect(isAva.y, y1)
    ;
  connect(isReqAvaOrNotReq.y, all.u)
    ;
  connect(matStaEqu.y, nEquSta.u)
    ;
  connect(nReqAltAva.y, isReqAltAvaGreReq.u1)
    ;
  connect(nReqAltAva.u, booToInt.y)
    ;
  connect(nEquSta.y, nEquStaInt.u)
    ;
  connect(nEquStaInt.y, isReqAltAvaGreReq.u2)
    ;
  connect(u1Ava, booVecRep.u)
    ;
  connect(isReqPosAlt.y, isReqAltAva.u1)
    ;
  connect(isReqAltAva.y, booToInt.u)
    ;
  connect(isReqAltAvaGreReq.y, isAva.u1)
    ;
  connect(all.y, isAva.u2)

  ;
end StageAvailability;

within Buildings.Fluid.Movers.BaseClasses.Euler;
function getPeak
  "Find peak condition from power characteristics"
  extends Modelica.Icons.Function;
  input Buildings.Fluid.Movers.BaseClasses.Characteristics.flowParameters
    pressure "Pressure vs. flow rate";
  input BaseClasses.Characteristics.powerParameters
    power "Power vs. flow rate";
  output Buildings.Fluid.Movers.BaseClasses.Euler.peak
    peak "Operation point at maximum efficiency";

protected
  parameter Integer nPre = size(pressure.V_flow, 1) "Size of the pressure array";
  parameter Integer nPow = size(power.V_flow, 1) "Size of the power array";
  parameter Integer n = max(nPre, nPow) "Bigger of the two arrays";
  parameter Modelica.Units.SI.VolumeFlowRate V_flow_hal=
    if max(pressure.V_flow) < 1E-6
      then 0
    else (pressure.V_flow[nPre]
                -(pressure.V_flow[nPre] - pressure.V_flow[nPre - 1])
                /(pressure.dp[nPre] - pressure.dp[nPre - 1])
                * pressure.dp[nPre])/2
    "Half of max flow, max flow is where dp=0";
  parameter Modelica.Units.SI.PressureDifference dpHalFlo=
    if max(pressure.V_flow) < 1E-6
      then 0
    else Buildings.Utilities.Math.Functions.smoothInterpolation(
               x=V_flow_hal,
               xSup=pressure.V_flow,
               ySup=pressure.dp,
               ensureMonotonicity=true)
    "Pressure rise at half flow";

  Modelica.Units.SI.VolumeFlowRate V_flow[n] "Flow rate";
  Modelica.Units.SI.PressureDifference dp[n] "Pressure rise";
  Modelica.Units.SI.Power P[n] "Power";

  Real eta[n] "Efficiency series";
  Boolean etaLes "Efficiency series has less than four points";
  Boolean etaMon "Efficiency series is monotonic";

  // A b = y
  Real A[n,5] "Design matrix";
  Real b[5] "Parameter vector";
  Real r[3,2] "Roots";
algorithm

  if max(pressure.V_flow) < 1E-6 and
     max(pressure.dp)     < 1E-6 then
    // If there is no pressure curve, no estimation can be made
    peak.V_flow:=0;
    peak.dp:=0;
    peak.eta:=0.7;

  elseif max(power.P) < 1E-6 then
    // If a pressure curve is available, but no power curve,
    //   peak.V_flow = V_flow_max / 2,
    //   peak.dp = dp(V_flow = V_flow_max / 2)
    peak.V_flow:=V_flow_hal;
    peak.dp:=dpHalFlo;
    peak.eta:=0.7;

  else
    // Both a pressure curve and a power curve are available.

    // Create arrays of the equal size
    if nPre == nPow then
      V_flow:= pressure.V_flow;
      dp:= pressure.dp;
      P:= power.P;
    else
      if nPre > nPow then
        V_flow:= pressure.V_flow;
        dp:= pressure.dp;
        for i in 1:n loop
          P[i]:= Buildings.Utilities.Math.Functions.smoothInterpolation(
                   x=V_flow[i],
                   xSup=power.V_flow,
                   ySup=power.P,
                   ensureMonotonicity=false);
        end for;
      else
        V_flow:= power.V_flow;
        P:= power.P;
        for i in 1:n loop
          dp[i]:= Buildings.Utilities.Math.Functions.smoothInterpolation(
                    x=V_flow[i],
                    xSup=pressure.V_flow,
                    ySup=pressure.dp,
                    ensureMonotonicity=true);
        end for;
      end if;
    end if;

    // Compute efficiency array
    eta:=V_flow.*dp./P;
    etaLes:=n<4;
    etaMon:=Buildings.Utilities.Math.Functions.isMonotonic(
      x=eta,
      strict=false);

    if etaLes or etaMon then
    // If less than four data points are provided or the efficiency curve is
    //   monotonic, use the one of two which has the higher efficiency:
    //   1. the interpolated point at half of max flow;
    //   2. the available point with the highest efficiency.
      peak.eta:=Buildings.Utilities.Math.Functions.smoothInterpolation(
               x=V_flow_hal,
               xSup=V_flow,
               ySup=eta,
               ensureMonotonicity=
                 Buildings.Utilities.Math.Functions.isMonotonic(eta, strict=false));
      if peak.eta>max(eta) then
             peak.V_flow:=V_flow_hal;
             peak.dp:=dpHalFlo;
      else
        peak.eta:=max(eta);
        for i in 1:n loop
          if abs(eta[i]-peak.eta)<1E-6 then
            peak.V_flow:=V_flow[i];
            peak.dp:=dp[i];
          end if;
        end for;
      end if;
    else

      // Constructs the matrix equation A b = y for quartic regression, where
      //   A is a 5-by-n design matrix,
      //   b is a parameter vector with length 5,
      //   and y = eta is the response vector with length n.
      A[:,1]:=ones(n); // Avoids 0^0
      for i in 2:5 loop
        A[:,i]:=V_flow[:].^(i-1);
      end for;
      b:=Modelica.Math.Matrices.leastSquares(A,eta);

      // Solve the derivative for the max eta and corresponding V_flow.
      // This assumes that there will only be one real solution
      //   and it falls within the range of V_flow[:].
      r:=Modelica.Math.Polynomials.roots({b[5]*4,b[4]*3,b[3]*2,b[2]});
      for i in 1:3 loop
        if abs(r[i,2])<=1E-6 and
          r[i,1]>V_flow[1] and r[i,1]<V_flow[n] then
          peak.V_flow:=r[i,1];
        end if;
      end for;
      peak.eta:=Buildings.Utilities.Math.Functions.smoothInterpolation(
        x=peak.V_flow,
        xSup=V_flow,
        ySup=eta,
        ensureMonotonicity=false);
      peak.dp:=Buildings.Utilities.Math.Functions.smoothInterpolation(
        x=peak.V_flow,
        xSup=V_flow,
        ySup=dp,
        ensureMonotonicity=false);
    end if;
  end if

  ;
end getPeak;

