    or ATotExt > 0 and not ATotWin > 0 and AInt > 0 and AFloor > 0
    or ATotExt > 0 and ATotWin > 0 and not AInt > 0 and AFloor > 0 then
    connect(thermSplitterIntGains.portOut[3], floorRC.port_a);
