within Buildings.Controls.OBC.CDL.Reals;
block Derivative
  "Block that approximates the derivative of the input"
  parameter Real y_start=0
    "Initial value of output (= state)"
    ;

  Buildings.Controls.OBC.CDL.Interfaces.RealInput k
    "Connector for gain signal"
    ;
  Buildings.Controls.OBC.CDL.Interfaces.RealInput T(
    final quantity="Time",
    final unit="s",
    min=100*Buildings.Controls.OBC.CDL.Constants.eps)
    "Time constant (T>0 required; T=0 is ideal derivative block)"
    ;
  Buildings.Controls.OBC.CDL.Interfaces.RealInput u
    "Input to be differentiated"
    ;
  Buildings.Controls.OBC.CDL.Interfaces.RealOutput y
    "Approximation of derivative du/dt"
    ;
protected
  Real T_nonZero(final unit="s") "Non-zero value for T";

  output Real x
    "State of block";

initial equation
  x= if abs(k) < Buildings.Controls.OBC.CDL.Constants.eps then u else u - T*y_start/k;

equation
  T_nonZero = max(T, 100*Buildings.Controls.OBC.CDL.Constants.eps);
  der(x) = (u-x)/T_nonZero;
  y = (k/T_nonZero)*(u-x)

  ;
end Derivative;

within Buildings.Controls.OBC.CDL.Logical.Sources;
block TimeTable
  "Table look-up with respect to time with constant segments"
  parameter Real table[:,:]
    "Table matrix with time as a first column (in seconds, unless timeScale is not 1) and 0 for False or 1 for True in all other columns";
  parameter Real timeScale(
    final unit="1")=1
    "Time scale of first table column. Set to 3600 if time in table is in hours";
  parameter Real period(
    final quantity="Time",
    final unit="s")
    "Periodicity of table";
  Buildings.Controls.OBC.CDL.Interfaces.BooleanOutput y[nout]
    "Output of the table"
    ;

protected
  final parameter Integer nout=size(
    table,
    2)-1
    "Dimension of output vector";
  final parameter Integer nT=size(
    table,
    1)
    "Number of table points";
  Integers.Sources.TimeTable intTimTab(
    final table=table,
    final timeScale=timeScale,
    final period=period)
    "Time table"
    ;
  Integers.GreaterThreshold intGreThr[nout](
    each t=0)
    "Converts to boolean"
    ;

initial equation
  // Check that all values in the second column are Integer values
  for i in 1:nT loop
    for j in 2:size(
      table,
      2) loop
      assert(
        (abs(
          table[i,j]) < Constants.small) or
                                           (abs(
          table[i,j]-1.0) < Constants.small),
        "Table value table["+String(i)+", "+String(j)+"] = "+String(
          table[i,j])+" does not equal either 0 or 1.");
    end for;
  end for;

equation
  connect(intTimTab.y,intGreThr.u)
    ;
  connect(intGreThr.y,y)

  ;
end TimeTable;

