    final t=TOutLck)
    if typ == Buildings.Templates.Plants.Controls.Types.Application.Cooling
    "Return true if OAT > lockout temperature"
    ;
  Buildings.Controls.OBC.CDL.Reals.LessThreshold lesLck(
    final t=TOutLck)
    if typ == Buildings.Templates.Plants.Controls.Types.Application.Heating
    "Return true if OAT < lockout temperature"
    ;
  Buildings.Controls.OBC.CDL.Logical.Pre preEna
    "Left limit (in discrete-time) of enable signal"
    ;
  Buildings.Controls.OBC.CDL.Logical.Timer timEna(
    final t=dtRun)
    "Return true if system has been enabled for specified duration"
    ;
  Buildings.Controls.OBC.CDL.Logical.Not dis
    "Return true if disabled"
    ;
  Buildings.Controls.OBC.CDL.Logical.Timer runDis(
    final t=dtRun)
    "Return true if system has been disabled for specified duration"
    ;
  Buildings.Controls.OBC.CDL.Logical.MultiAnd mulAnd(
    nin=4)
    "Combine enable conditions"
    ;
  Buildings.Controls.OBC.CDL.Logical.MultiOr mulOr(
    nin=3)
    "Combine disable conditions"
    ;
  Buildings.Controls.OBC.CDL.Logical.Not disSch
    "Return true if disabled by schedule"
    ;
  Buildings.Controls.OBC.CDL.Integers.LessEqualThreshold lowIgn(
    final t=nReqIgn)
    "Return true if number of requests ≤ number of ignored requests"
    ;
  Buildings.Controls.OBC.CDL.Logical.Timer timLowReq(
    final t=dtReq)
    "Return true if low number of requests for specified duration"
    ;
  Buildings.Controls.OBC.CDL.Reals.LessThreshold lowLckHys(
    final t=TOutLck - dTOutLck)
    if typ == Buildings.Templates.Plants.Controls.Types.Application.Cooling
    "Return true if OAT < lockout temperature - hysteresis"
    ;
  Buildings.Controls.OBC.CDL.Reals.GreaterThreshold greLckHys(
    final t=TOutLck + dTOutLck)
    if typ == Buildings.Templates.Plants.Controls.Types.Application.Heating
    "Return true if OAT > lockout temperature + hysteresis"
    ;
  Buildings.Controls.OBC.CDL.Logical.And andRun
    "Disable conditions met AND enable minimum runtime exceeded"
    ;
  Buildings.Controls.OBC.CDL.Logical.Latch lat
    "Clear enable signal if disable conditions are met"
    ;
equation
  connect(nReqPla, greIgn.u)
    ;
  connect(TOut, greLck.u)
    ;
  connect(TOut, lesLck.u)
    ;
  connect(preEna.y, dis.u)
    ;
  connect(dis.y, runDis.u)
    ;
  connect(preEna.y, timEna.u)
    ;
  connect(runDis.passed, mulAnd.u[1])
    ;
  connect(schEna.y[1], mulAnd.u[2])
    ;
  connect(u1Sch, mulAnd.u[2])
    ;
  connect(greIgn.y, mulAnd.u[3])
    ;
  connect(schEna.y[1], disSch.u)
    ;
  connect(u1Sch, disSch.u)
    ;
  connect(disSch.y, mulOr.u[1])
    ;
  connect(nReqPla, lowIgn.u) ;
  connect(lowIgn.y, timLowReq.u)
    ;
  connect(timLowReq.passed, mulOr.u[2])
    ;
  connect(greLck.y, mulAnd.u[4])
    ;
  connect(lesLck.y, mulAnd.u[4])
    ;
  connect(TOut, lowLckHys.u)
    ;
  connect(lowLckHys.y, mulOr.u[3])
    ;
  connect(TOut, greLckHys.u)
    ;
  connect(greLckHys.y, mulOr.u[3])
    ;
  connect(timEna.passed, andRun.u1)
    ;
  connect(mulOr.y, andRun.u2)
    ;
  connect(y1, lat.y)
    ;
  connect(mulAnd.y, lat.u)
    ;
  connect(andRun.y, lat.clr)
    ;
  connect(y1, preEna.u)

  ;
end Enable;

within Buildings.Fluid.HeatExchangers.Examples;
model DryCoilCounterFlowPControl
  "Model that demonstrates use of a heat exchanger without condensation and with feedback control"
  extends Modelica.Icons.Example;
  package Medium1 = Buildings.Media.Water;
  package Medium2 = Buildings.Media.Air;

  parameter Modelica.Units.SI.Temperature T_a1_nominal=5 + 273.15;
  parameter Modelica.Units.SI.Temperature T_b1_nominal=10 + 273.15;
  parameter Modelica.Units.SI.Temperature T_a2_nominal=30 + 273.15;
  parameter Modelica.Units.SI.Temperature T_b2_nominal=15 + 273.15;
  parameter Modelica.Units.SI.MassFlowRate m1_flow_nominal=0.1
    "Nominal mass flow rate medium 1";
  parameter Modelica.Units.SI.MassFlowRate m2_flow_nominal=m1_flow_nominal*4200
      /1000*(T_a1_nominal - T_b1_nominal)/(T_b2_nominal - T_a2_nominal)
    "Nominal mass flow rate medium 2";
  Buildings.Fluid.Sources.Boundary_pT sin_2(
    redeclare package Medium = Medium2,
    nPorts=1,
    use_p_in=false,
    p(displayUnit="Pa") = 101325,
    T=303.15) ;
  Buildings.Fluid.Sources.Boundary_pT sou_2(
    redeclare package Medium = Medium2,
    nPorts=1,
    T=T_a2_nominal,
    X={0.02,1 - 0.02},
    use_T_in=true,
    use_X_in=true,
    p(displayUnit="Pa") = 101325 + 300) ;
  Buildings.Fluid.Sources.Boundary_pT sin_1(
    redeclare package Medium = Medium1,
    nPorts=1,
    use_p_in=false,
    p=300000,
    T=293.15) ;
  Buildings.Fluid.Sources.Boundary_pT sou_1(
    redeclare package Medium = Medium1,
    nPorts=1,
    use_T_in=true,
    p=300000 + 12000)
                   ;
  Buildings.Fluid.FixedResistances.PressureDrop res_2(
    from_dp=true,
    redeclare package Medium = Medium2,
    dp_nominal=100,
    m_flow_nominal=m2_flow_nominal)
    ;
  Buildings.Fluid.FixedResistances.PressureDrop res_1(
    from_dp=true,
    redeclare package Medium = Medium1,
    dp_nominal=3000,
    m_flow_nominal=m1_flow_nominal)
    ;
  Buildings.Fluid.Sensors.TemperatureTwoPort temSen(redeclare package Medium =
               Medium2, m_flow_nominal=m2_flow_nominal)
    ;
  Buildings.Fluid.Actuators.Valves.TwoWayEqualPercentage val(
    redeclare package Medium = Medium1,
    m_flow_nominal=m1_flow_nominal,
    dpValve_nominal=6000) "Valve model"           ;
  Modelica.Blocks.Sources.TimeTable TSet(table=[0,288.15; 600,288.15; 600,
        298.15; 1200,298.15; 1800,283.15; 2400,283.15; 2400,288.15])
    "Setpoint temperature" ;
  Buildings.Fluid.HeatExchangers.DryCoilCounterFlow hex(
    redeclare package Medium1 = Medium1,
    redeclare package Medium2 = Medium2,
    m1_flow_nominal=m1_flow_nominal,
    m2_flow_nominal=m2_flow_nominal,
    dp2_nominal(displayUnit="Pa") = 200,
    allowFlowReversal1=true,
    allowFlowReversal2=true,
    dp1_nominal(displayUnit="Pa") = 3000,
    UA_nominal=m1_flow_nominal*4200*(T_a1_nominal - T_b1_nominal)/
       Buildings.Fluid.HeatExchangers.BaseClasses.lmtd(
        T_a1_nominal,
        T_b1_nominal,
        T_a2_nominal,
        T_b2_nominal),
    show_T=true,
    energyDynamics=Modelica.Fluid.Types.Dynamics.FixedInitial)
                             ;
  Modelica.Blocks.Sources.Constant const(k=0.8)
    ;
  Buildings.Utilities.Psychrometrics.X_pTphi x_pTphi(use_p_in=false)
    ;
  Modelica.Blocks.Sources.Constant const1(k=T_a2_nominal)
    ;
  Buildings.Controls.Continuous.LimPID con(
    Td=1,
    reverseActing=false,
    yMin=0,
    k=0.1,
    Ti=60) "Controller"
    ;
  Modelica.Blocks.Sources.Ramp TWat(
    height=30,
    offset=T_a1_nominal,
    startTime=300,
    duration=2000) "Water temperature, raised to high value at t=3000 s"
    ;
equation
  connect(hex.port_b1, res_1.port_a) ;
  connect(val.port_b, hex.port_a1) ;
  connect(sou_1.ports[1], val.port_a) ;
  connect(sin_1.ports[1], res_1.port_b) ;
  connect(sin_2.ports[1], res_2.port_b) ;
  connect(sou_2.ports[1], hex.port_a2) ;
  connect(temSen.port_b, res_2.port_a) ;
  connect(x_pTphi.X, sou_2.X_in) ;
  connect(const.y, x_pTphi.phi) ;
  connect(const1.y, x_pTphi.T) ;
  connect(const1.y, sou_2.T_in) ;
  connect(TSet.y, con.u_s)    ;
  connect(temSen.T, con.u_m)    ;
  connect(TWat.y, sou_1.T_in) ;
  connect(con.y, val.y)    ;
  connect(temSen.port_a, hex.port_b2) 
  ;
end DryCoilCounterFlowPControl;

