within Buildings.HeatTransfer.Windows.BaseClasses;
model ExteriorConvectionCoefficient
  "Model for the heat transfer coefficient at the outside of the window"
  extends Modelica.Blocks.Icons.Block;
  parameter Modelica.Units.SI.Area A "Heat transfer area";

  Modelica.Blocks.Interfaces.RealOutput GCon(unit="W/K")
    "Convective thermal conductance"
    ;
  Modelica.Blocks.Interfaces.RealInput v(unit="m/s") "Wind speed"
    ;

equation
  GCon = A*(4+4*Buildings.Utilities.Math.Functions.smoothMax(v, -v, 0.1))
  ;
end ExteriorConvectionCoefficient;

within Buildings.Fluid.HeatExchangers.Examples;
model DryCoilDiscretized
  "Model that demonstrates use of a finite volume model of a heat exchanger without condensation"
  extends Modelica.Icons.Example;

  package Medium1 = Buildings.Media.Water;
  package Medium2 = Buildings.Media.Air;

  parameter Modelica.Units.SI.Temperature T_a1_nominal=60 + 273.15;
  parameter Modelica.Units.SI.Temperature T_b1_nominal=40 + 273.15;
  parameter Modelica.Units.SI.Temperature T_a2_nominal=5 + 273.15;
  parameter Modelica.Units.SI.Temperature T_b2_nominal=20 + 273.15;
  parameter Modelica.Units.SI.MassFlowRate m1_flow_nominal=5
    "Nominal mass flow rate medium 1";
  parameter Modelica.Units.SI.MassFlowRate m2_flow_nominal=m1_flow_nominal*4200
      /1000*(T_a1_nominal - T_b1_nominal)/(T_b2_nominal - T_a2_nominal)
    "Nominal mass flow rate medium 2";

  Buildings.Fluid.HeatExchangers.DryCoilDiscretized hex(
    redeclare package Medium1 = Medium1,
    redeclare package Medium2 = Medium2,
    nPipPar=1,
    nPipSeg=3,
    nReg=2,
    m1_flow_nominal=m1_flow_nominal,
    m2_flow_nominal=m2_flow_nominal,
    UA_nominal=m1_flow_nominal*4200*(T_a1_nominal-T_b1_nominal)/
      Buildings.Fluid.HeatExchangers.BaseClasses.lmtd(
        T_a1_nominal,
        T_b1_nominal,
        T_a2_nominal,
        T_b2_nominal),
    dp2_nominal=200,
    dp1_nominal=5000,
    show_T=true,
    energyDynamics=Modelica.Fluid.Types.Dynamics.FixedInitial,
    from_dp1=true,
    from_dp2=true)             ;
  Sources.MassFlowSource_T            sin_2(
    redeclare package Medium = Medium2,
    nPorts=1,
    use_m_flow_in=true,
    T=303.15)             ;
    Modelica.Blocks.Sources.Ramp PIn(
    offset=101525,
    height=-199,
    duration=60,
    startTime=120)
                 ;
  Buildings.Fluid.Sources.Boundary_pT sou_2(
    redeclare package Medium = Medium2,
    use_p_in=true,
    use_T_in=true,
    T=283.15,
    nPorts=1)             ;
    Modelica.Blocks.Sources.Ramp TWat(
    duration=60,
    startTime=60,
    height=5,
    offset=273.15 + 60) "Water temperature"
                 ;
  Modelica.Blocks.Sources.Constant TDb(k=273.15 + 5) "Drybulb temperature"
    ;
  Buildings.Fluid.Sources.Boundary_pT sin_1(
    redeclare package Medium = Medium1,
    p=300000,
    T=293.15,
    use_p_in=true,
    nPorts=1)             ;
  Buildings.Fluid.Sources.Boundary_pT sou_1(
    redeclare package Medium = Medium1,
    p=300000 + 5000,
    use_T_in=true,
    T=293.15,
    nPorts=1)             ;
    Modelica.Blocks.Sources.Ramp PSin_1(
    startTime=240,
    offset=300000,
    height=4990,
    duration=60) ;
    Modelica.Blocks.Sources.Ramp m_flow_2(
    duration=60,
    startTime=120,
    height=28 - 0.124,
    offset=-28) "Mass flow rate on air side" ;
equation
  connect(PIn.y,sou_2. p_in) ;
  connect(TDb.y, sou_2.T_in) ;
  connect(TWat.y, sou_1.T_in)
    ;
  connect(PSin_1.y, sin_1.p_in) ;
  connect(sou_1.ports[1], hex.port_a1) ;
  connect(sou_2.ports[1], hex.port_a2) ;
  connect(sin_2.ports[1], hex.port_b2) ;
  connect(hex.port_b1, sin_1.ports[1]) ;
  connect(m_flow_2.y, sin_2.m_flow_in) 
  ;
end DryCoilDiscretized;

within Buildings.Controls.OBC.CDL.Integers;
block Change
  "Output whether the Integer input changes values, increases or decreases"
  parameter Integer pre_u_start=0
    "Start value of pre(u) at initial time";
  Buildings.Controls.OBC.CDL.Interfaces.IntegerInput u
    "Connector of Integer input signal"
    ;
  Buildings.Controls.OBC.CDL.Interfaces.BooleanOutput y
    "Connector of Boolean output signal"
    ;
  Buildings.Controls.OBC.CDL.Interfaces.BooleanOutput up
    "Connector of Boolean output signal indicating input increase"
    ;
  Buildings.Controls.OBC.CDL.Interfaces.BooleanOutput down
    "Connector of Boolean output signal indicating input decrease"
    ;

initial equation
  pre(u)=pre_u_start;

equation
  y=change(u);
  up=u > pre(u);
  down=u < pre(u)
  ;
end Change;

