  Buildings.Controls.OBC.CDL.Interfaces.IntegerInput u2
    "Connector of Integer input signal 2"
    ;
  Buildings.Controls.OBC.CDL.Interfaces.IntegerOutput y
    "Connector of Integer output signal"
    ;

equation
  y=min(
    u1,
    u2)
  ;
end Min;

