  parameter Real kout1 = 100. "Validation output 1";

  Buildings.Controls.OBC.UnitConversions.To_ton to_ton
  "Unit converter from watt to ton of refrigeration "
    ;
  Buildings.Controls.OBC.UnitConversions.To_ton to_ton1
