within Buildings.Fluid.DXSystems.Cooling.BaseClasses;
block DryWetSelector "Selects results from dry or wet coil"

  constant Modelica.Units.SI.MassFraction deltaX=0.0001
    "Range of x where transition between dry and wet coil occurs";
  Modelica.Blocks.Interfaces.RealInput XEvaIn "Inlet air mass fraction"
    ;
  Modelica.Blocks.Interfaces.RealInput XADP "Mass fraction at ADP"
    ;

  Modelica.Blocks.Interfaces.RealInput EIRWet "Energy Input Ratio"
     ;
  Modelica.Blocks.Interfaces.RealInput QWet_flow(
    max=0,
    unit="W") "Total cooling capacity"
     ;
  Modelica.Blocks.Interfaces.RealInput SHRWet(
    min=0,
    max=1.0)
    "Sensible Heat Ratio: Ratio of sensible heat load to total heat load"
    ;
  Modelica.Blocks.Interfaces.RealInput mWetWat_flow(
    quantity="MassFlowRate",
    unit="kg/s") "Mass flow rate of water condensed at cooling coil"
    ;
  Modelica.Blocks.Interfaces.RealInput EIRDry "Energy Input Ratio"
     ;
  Modelica.Blocks.Interfaces.RealInput QDry_flow(max=0, unit="W")
    "Total cooling capacity"
     ;
  Modelica.Blocks.Interfaces.RealOutput EIR "Energy Input Ratio"
     ;
  Modelica.Blocks.Interfaces.RealOutput Q_flow(
    max=0,
    unit="W") "Total cooling capacity"
     ;
  Modelica.Blocks.Interfaces.RealOutput SHR(
    min=0,
    max=1.0)
    "Sensible Heat Ratio: Ratio of sensible heat load to total heat load"
    ;
  Modelica.Blocks.Interfaces.RealOutput mWat_flow(
    quantity="MassFlowRate",
    unit="kg/s") "Mass flow rate of water condensed at cooling coil"
    ;

 output Real fraDry(min=0, max=1)
    "Fraction of results that are taken from the dry coil model";
 output Real fraWet(min=0, max=1)
    "Fraction of results that are taken from the wet coil model";
protected
  output Modelica.Units.SI.MassFraction dX(min=-1, max=1)
    "Difference between apparatus dew point mass fraction of wet coil and inlet air mass fraction";
equation
  dX = XADP-XEvaIn;
  fraDry=Buildings.Utilities.Math.Functions.spliceFunction(
    pos=+1,
    neg=0,
    x= dX+deltaX,
    deltax= deltaX);
  fraWet=1-fraDry;
  EIR       = fraDry * EIRDry    + fraWet * EIRWet;
  Q_flow    = fraDry * QDry_flow + fraWet * QWet_flow;
  SHR       = fraDry             + fraWet * SHRWet;
  mWat_flow =                      fraWet * mWetWat_flow

  ;
end DryWetSelector;

within Buildings.Utilities.Math.Functions;
function factorial "Returns the value n! as an integer"
  extends Modelica.Icons.Function;

  input Integer n(min=0, max=12) "Integer number";
  output Integer f "Factorial of n";

algorithm
  assert(n >= 0, "n must be 0 or greater.");
  assert(n <= 12, "n must be 12 or less.");
  f := 1;
  for k in 1:n loop
    f := k*f;
  end for

;
end factorial;

within Buildings.Fluid.HeatPumps.ModularReversible.Examples.BaseClasses;
model OneRoomRadiatorHeatPumpControl
  "Helper model for the control of the system"
  parameter Boolean witCoo=true
    "=true to simulate cooling behaviour";
  parameter Modelica.Units.SI.Temperature TRooSetHea=293.15
    "Room set temperature for heating";
  parameter Modelica.Units.SI.Temperature TRooSetCoo=296.15
    "Room set temperature for cooling";
  parameter Modelica.Units.SI.Temperature TRadMinSup=290.15
    "Minimal radiator supply temperature to avoid condensation effects";
  parameter Modelica.Units.SI.TemperatureDifference dTHysRoo=2
    "Temperature hysteresis for room control";
  Modelica.Blocks.Logical.Hysteresis hysHea(
    final uLow=TRooSetHea - dTHysRoo,
    final uHigh=TRooSetHea + dTHysRoo,
    final pre_y_start=false)
    "Hysteresis controller for heating" ;
  Modelica.Blocks.Logical.Hysteresis hysCoo(
    final uLow=TRooSetCoo - dTHysRoo,
    final uHigh=TRooSetCoo + dTHysRoo,
    final pre_y_start=false)
    if witCoo
    "Hysteresis controller for cooling" ;
  Modelica.Blocks.Sources.BooleanConstant conFal(final k=false)
                                                          if not witCoo
    "No cooling if witCoo=false"
    ;
  Modelica.Blocks.Logical.Not heaIsOn
    "If lower than hysteresis, heating demand" ;
  Modelica.Blocks.Logical.Switch swiHeaCooYSet if witCoo
    "Switch ySet for heating and cooling" ;
  Modelica.Blocks.Continuous.LimPID PIDCoo(
    controllerType=Modelica.Blocks.Types.SimpleController.PI,
    k=0.01,
    Ti=800,
    yMax=1,
    yMin=0.3,
    I(use_reset=true, reset=booPasThrCoo.y)) if witCoo
              "PI control for cooling, inverse"
    ;
  Modelica.Blocks.Continuous.LimPID PIDHea(
    controllerType=Modelica.Blocks.Types.SimpleController.PI,
    k=0.01,
    Ti=800,
    yMax=1,
    yMin=0.3,
    I(use_reset=true, reset=hysHea.y))
              "PI control for heating"
    ;
  Modelica.Blocks.Sources.Constant constTSetRooHea(final k=TRooSetHea)
    "Room set point temperature for heating"
    ;
  Modelica.Blocks.Sources.Constant constTSetRooCoo(final k=TRooSetCoo) if witCoo
    "Room set point temperature for cooling"
    ;
  Modelica.Blocks.Sources.Constant constYSetZer(final k=0) "ySet equals zero"
    ;
  Modelica.Blocks.Logical.Switch swiYSet "If no demand, switch heat pump off"
    ;
  Modelica.Blocks.Logical.Switch swiSecForCoo
    "If in cooling mode, heat pump can't operate below condensing temperature of 15 °C"
    ;
  Modelica.Blocks.Logical.Hysteresis hysSecCoo(
    final uLow=TRadMinSup,
    final uHigh=TRadMinSup + 1,
    final pre_y_start=false)
            if witCoo
    "Hysteresis for avoiding temperatures below 15 °C when cooling"
    ;
  Modelica.Blocks.Sources.BooleanConstant conTru(final k=true)
                                                         if not witCoo
    "No cooling if witCoo=false, then no safety is necessary" ;
  Modelica.Blocks.Interfaces.RealInput TRooMea(unit="K", displayUnit="degC")
                                               "Room measurement temperature"
    ;
  Modelica.Blocks.Interfaces.RealInput TRadSup(displayUnit="degC", unit="K")
                                               "Radiator supply temperature"
    ;
  Modelica.Blocks.Interfaces.RealOutput ySet "Heat pump set speed"
    ;
  Modelica.Blocks.Interfaces.BooleanOutput hea if witCoo
    "Heat pump in normal mode"
    ;
  Modelica.Blocks.Logical.Or heaOrCooIsOn "Heating or cooling is on"
    ;

  Modelica.Blocks.Logical.Or cooValOrHea
    "Cooling safety control is used only when the device is not heating" ;
  Modelica.Blocks.Routing.BooleanPassThrough booPasThrCoo "Used for reset of PID"
    ;
equation
  connect(hysHea.y, heaIsOn.u)
    ;
  connect(swiHeaCooYSet.u2, hysCoo.y)
    ;
  connect(swiYSet.u2, heaOrCooIsOn.y) ;
  connect(heaIsOn.y, heaOrCooIsOn.u1) ;
  connect(PIDHea.u_s,constTSetRooHea. y)
    ;
  connect(PIDHea.y, swiHeaCooYSet.u3) ;
  connect(constTSetRooCoo.y,PIDCoo. u_m) ;
  connect(swiSecForCoo.u3, constYSetZer.y) ;
  connect(constYSetZer.y, swiYSet.u3) ;
  connect(hysCoo.u, TRooMea) ;
  connect(TRooMea, hysHea.u) ;
  connect(swiSecForCoo.y, ySet) ;
  connect(hysSecCoo.u, TRadSup)
    ;
  connect(swiYSet.y, swiSecForCoo.u1) ;
  connect(PIDCoo.u_s, TRooMea) ;
  connect(PIDHea.u_m, TRooMea) ;
  connect(PIDCoo.y, swiHeaCooYSet.u1) ;
  connect(swiHeaCooYSet.y, swiYSet.u1) ;
  connect(heaOrCooIsOn.u2, conFal.y) ;
  connect(hysCoo.y, heaOrCooIsOn.u2) ;
  connect(heaIsOn.y, hea) ;
  connect(cooValOrHea.y, swiSecForCoo.u2) ;
  connect(cooValOrHea.u2, conTru.y) ;
  connect(cooValOrHea.u2, hysSecCoo.y) ;
  connect(heaIsOn.y, cooValOrHea.u1) ;
  if not witCoo then
    connect(PIDHea.y, swiYSet.u1) ;
  end if;
  connect(hysCoo.y, booPasThrCoo.u) ;
  connect(conFal.y, booPasThrCoo.u) 
  ;
end OneRoomRadiatorHeatPumpControl;

