within Buildings.Fluid.Actuators.Valves.Validation;
model ThreeWayValveParameterization
  "Test model for parameterization of three-way valves"
  extends Modelica.Icons.Example;
  package Medium = Buildings.Media.Water "Medium in the component";

  parameter Modelica.Units.SI.MassFlowRate m_flow_nominal=0.4
    "Design mass flow rate";
  parameter Modelica.Units.SI.PressureDifference dp_nominal=4500
    "Design pressure drop";

  parameter Real Kv_SI = m_flow_nominal/sqrt(dp_nominal)
    "Flow coefficient for fully open valve in SI units, Kv=m_flow/sqrt(dp) [kg/s/(Pa)^(1/2)]";

  parameter Real Kv = Kv_SI/(rhoStd/3600/sqrt(1E5))
    "Kv (metric) flow coefficient [m3/h/(bar)^(1/2)]";
  parameter Real Cv = Kv_SI/(rhoStd*0.0631/1000/sqrt(6895))
    "Cv (US) flow coefficient [USG/min/(psi)^(1/2)]";
  parameter Modelica.Units.SI.Area Av=Kv_SI/sqrt(rhoStd)
    "Av (metric) flow coefficient";

  parameter Modelica.Units.SI.Density rhoStd=Medium.density_pTX(
      101325,
      273.15 + 4,
      Medium.X_default) "Standard density";

  Buildings.Fluid.Actuators.Valves.ThreeWayEqualPercentageLinear valOPPoi(
    redeclare package Medium = Medium,
    m_flow_nominal=m_flow_nominal,
    CvData=Buildings.Fluid.Types.CvTypes.OpPoint,
    dpValve_nominal(displayUnit="kPa") = 4500,
    use_inputFilter=false,
    energyDynamics=Modelica.Fluid.Types.Dynamics.SteadyState)
                           "Three way valve with operating point as parameter"
    ;

  Buildings.Fluid.Actuators.Valves.ThreeWayEqualPercentageLinear valKv(
    redeclare package Medium = Medium,
    CvData=Buildings.Fluid.Types.CvTypes.Kv,
    m_flow_nominal=m_flow_nominal,
    Kv=Kv,
    use_inputFilter=false,
    energyDynamics=Modelica.Fluid.Types.Dynamics.SteadyState)
                           "Three way valve with Kv-value as parameter"
    ;

  Buildings.Fluid.Actuators.Valves.ThreeWayEqualPercentageLinear valCv(
    redeclare package Medium = Medium,
    m_flow_nominal=m_flow_nominal,
    CvData=Buildings.Fluid.Types.CvTypes.Cv,
    Cv=Cv,
    use_inputFilter=false,
    energyDynamics=Modelica.Fluid.Types.Dynamics.SteadyState)
                           "Three way valve with Cv-value as parameter"
    ;

  Buildings.Fluid.Actuators.Valves.ThreeWayEqualPercentageLinear valAv(
    redeclare package Medium = Medium,
    m_flow_nominal=m_flow_nominal,
    Av=Av,
    use_inputFilter=false,
    CvData=Buildings.Fluid.Types.CvTypes.Av,
    energyDynamics=Modelica.Fluid.Types.Dynamics.SteadyState)
    "Three way valve with Av-value as parameter"
    ;

  Buildings.Fluid.Sources.Boundary_pT sou1(
    redeclare package Medium = Medium,
    nPorts=4,
    use_p_in=false,
    p(displayUnit="Pa") = 300000 + 4500,
    T=293.15) "Boundary condition for flow source"
    ;
  Buildings.Fluid.Sources.Boundary_pT sin(
    redeclare package Medium = Medium,
    nPorts=4,
    use_p_in=false,
    p=300000,
    T=293.15) "Boundary condition for flow sink"    ;
    Modelica.Blocks.Sources.Ramp y(
    duration=1,
    height=1,
    offset=0) "Control signal"
    ;

  Buildings.Fluid.Sensors.MassFlowRate senM_flowOpPoi(
    redeclare package Medium = Medium) "Mass flow rate sensor"
    ;
  Buildings.Fluid.Sensors.MassFlowRate senM_flowKv(
    redeclare package Medium = Medium) "Mass flow rate sensor"
    ;
  Buildings.Fluid.Sensors.MassFlowRate senM_flowCv(
    redeclare package Medium = Medium) "Mass flow rate sensor"
    ;

  Buildings.Fluid.Sensors.MassFlowRate senM_flowAv(redeclare package Medium =
        Medium) "Mass flow rate sensor"
    ;
  Buildings.Fluid.Sources.Boundary_pT sou3(
    redeclare package Medium = Medium,
    nPorts=4,
    use_p_in=false,
    p(displayUnit="Pa") = 300000 + 4500,
    T=293.15) "Boundary condition for flow source"
    ;
equation
  connect(sou1.ports[1], valOPPoi.port_1) ;
  connect(sou1.ports[2], valKv.port_1) ;
  connect(sou1.ports[3], valCv.port_1) ;
  connect(sou1.ports[4], valAv.port_1) ;
  connect(sou3.ports[1], valOPPoi.port_3) ;
  connect(sou3.ports[2], valKv.port_3) ;
  connect(sou3.ports[3], valCv.port_3) ;
  connect(sou3.ports[4], valAv.port_3) ;
  connect(valOPPoi.port_2, senM_flowOpPoi.port_a)
    ;
  connect(valKv.port_2, senM_flowKv.port_a)
    ;
  connect(valCv.port_2, senM_flowCv.port_a)
    ;
  connect(valAv.port_2, senM_flowAv.port_a)
    ;
  connect(senM_flowOpPoi.port_b, sin.ports[1]) ;
  connect(senM_flowKv.port_b, sin.ports[2]) ;
  connect(senM_flowCv.port_b, sin.ports[3]) ;
  connect(senM_flowAv.port_b, sin.ports[4]) ;
  connect(y.y, valOPPoi.y) ;
  connect(y.y, valKv.y) ;
  connect(y.y, valCv.y) ;
  connect(y.y, valAv.y) 
  ;
end ThreeWayValveParameterization;

within Buildings.HeatTransfer.Windows.Functions;
function glassAbsExteriorIrradiationExteriorShading
  "Angular and hemispherical absorptance of each glass pane for exterior irradiation with exterior shading"
  input Real absExtIrrNoSha[N, HEM, NSta](each min=0, each max=1)
    "Angular and hemispherical absorptance of each glass pane for exterior irradiation without shading";
  extends
    Buildings.HeatTransfer.Windows.Functions.BaseClasses.partialWindowShadingRadiation;

  output Real absExtIrrExtSha[N, HEM, NSta](each min=0, each max=1)
    "Angular and hemispherical absorptance of each glass pane for exterior irradiation with exterior shading";

protected
  Real c "Intermediate variable";

algorithm
  for iSta in 1:NSta loop
    for iD in 1:HEM loop
      c := traExtShaDev*(1 + traRef[Ra, 1, N, iD, iSta]*refExtShaDev/
        (1 - traRef[Ra, 1, N, HEM, iSta]*refExtShaDev));
      for i in 1:N loop
        absExtIrrExtSha[i, iD, iSta] := c*absExtIrrNoSha[i, iD, iSta];
       end for;
    end for;
  end for

  ;
end glassAbsExteriorIrradiationExteriorShading;

within Buildings.Media.Refrigerants.R410A;
function isentropicExponentVap_Tv
  "Function that calculates the isentropic exponent of R410A vapor based on temperature and specific volume"
  input Modelica.Units.SI.Temperature T "Temperature of refrigerant";
  input Modelica.Units.SI.SpecificVolume v "Specific volume of refrigerant";
  output Modelica.Units.SI.IsentropicExponent k
    "Specific isobaric heat capacity";

protected
  Modelica.Units.SI.SpecificHeatCapacity cp "Specific isobaric heat capacity";

  Modelica.Units.SI.SpecificHeatCapacity cv "Specific isochoric heat capacity";

algorithm
  // Evaluate the specific isobaric and isochoric heat capacities
  cp := Buildings.Media.Refrigerants.R410A.specificIsobaricHeatCapacityVap_Tv(T, v);
  cv := Buildings.Media.Refrigerants.R410A.specificIsochoricHeatCapacityVap_Tv(T, v);

  k := cp / cv

;
end isentropicExponentVap_Tv;

