  connect(switch.y, y)
    ;
  connect(TMax.y, dTCon.u1) ;
  connect(TMin.y, dTEva.u1) ;
  connect(dTEva.u2, TEva) ;
  connect(dTCon.u2, TCon) ;
  connect(dTEva.y, hysLow.u)
    ;
  connect(hysHig.u, dTCon.y)
    ;
  connect(on.y, switch.u2)
    ;
  connect(dTEvaCon.y, hysdTConEva.u)
    ;
