  connect(andRes.y, triSam.trigger)
    ;
  connect(andRes.y, lat.u)
    ;
  connect(notRes.y, andRes.u2)
    ;
  connect(pre1.y, notRes.u) ;
  connect(lat.y, truDel.u)
    ;
  connect(truDel.y, yEna)


;
end PLRToPulse;

