within Buildings.Controls.OBC.CDL.Reals;
block Line
  "Output the value of the input x along a line specified by two points"
  parameter Boolean limitBelow=true
    "If true, limit input u to be no smaller than x1"
    ;
  parameter Boolean limitAbove=true
    "If true, limit input u to be no larger than x2"
    ;
  Buildings.Controls.OBC.CDL.Interfaces.RealInput x1
    "Support point x1, with x1 < x2"
    ;
  Buildings.Controls.OBC.CDL.Interfaces.RealInput f1
    "Support point f(x1)"
    ;
  Buildings.Controls.OBC.CDL.Interfaces.RealInput x2
    "Support point x2, with x2 > x1"
    ;
  Buildings.Controls.OBC.CDL.Interfaces.RealInput f2
    "Support point f(x2)"
    ;
  Buildings.Controls.OBC.CDL.Interfaces.RealInput u
    "Independent variable"
    ;
  Buildings.Controls.OBC.CDL.Interfaces.RealOutput y
    "f(x) along the line specified by (x1, f1) and (x2, f2)"
    ;

protected
  Real a
    "Intercept";
  Real b
    "Slope";
  Real xLim
    "Input value after applying the limits";

equation
  if limitBelow or limitAbove then
    assert(
      x2 > x1,
      "x2 must be bigger than x1 in "+getInstanceName(),
      AssertionLevel.warning);
  end if;
  b=(f2-f1)/(x2-x1);
  a=f2-b*x2;
  if limitBelow and limitAbove then
    xLim=min(
      x2,
      max(
        x1,
        u));
  elseif limitBelow then
    xLim=max(
      x1,
      u);
  elseif limitAbove then
    xLim=min(
      x2,
      u);
  else
    xLim=u;
  end if;
  y=a+b*xLim
  ;
end Line;

within Buildings.Templates.Plants.Controls.Utilities;
block TrueArrayConditional
  "Output a Boolean array with a given number of true elements and a priority order"
  parameter Integer nin(
    min=0)=0
    "Size of input array"
    ;
  parameter Integer nout(
    min=0)=nin
    "Size of output array"
    ;
  Buildings.Controls.OBC.CDL.Interfaces.IntegerInput u
    "Number of true elements"
    ;
  Buildings.Controls.OBC.CDL.Interfaces.IntegerInput uIdx[nin]
    "Array of indices by order of priority to be true"
    ;
  Buildings.Controls.OBC.CDL.Interfaces.BooleanOutput y1[nout]
    "Output"
    ;
protected
  Integer iTru
    "Iteration variable - Count number of true elements";
  Integer iIdx
    "Iteration variable - Count number of indices in input vector";
initial equation
  pre(u)=0;
algorithm
  iTru := 0;
  iIdx := 1;
  y1 := fill(false, nout);
  while
       (iTru < u) and (iIdx <= nin) loop
    if (uIdx[iIdx] >= 1) and (uIdx[iIdx] <= nout) then
      y1[uIdx[iIdx]] := true;
      iTru := iTru + 1;
    end if;
    iIdx := iIdx + 1;
  end while
  ;
end TrueArrayConditional;

within Buildings.Controls.OBC.CDL.Reals;
block GreaterThreshold
  "Output y is true, if input u is greater than threshold"
  parameter Real t=0
    "Threshold for comparison";
  parameter Real h(
    final min=0)=0
    "Hysteresis"
    ;
  parameter Boolean pre_y_start=false
    "Value of pre(y) at initial time"
    ;
  Buildings.Controls.OBC.CDL.Interfaces.RealInput u
    "Input"
    ;
  Buildings.Controls.OBC.CDL.Interfaces.BooleanOutput y
    "Output"
    ;

protected
  final parameter Boolean have_hysteresis=h >= 1E-10
    "True if the block has no hysteresis"
    ;
  GreaterWithHysteresis greHys(
    final h=h,
    final t=t,
    final pre_y_start=pre_y_start) if have_hysteresis
    "Block with hysteresis"
    ;
  GreaterNoHysteresis greNoHys(
    final t=t) if not have_hysteresis
    "Block without hysteresis"
    ;
  block GreaterNoHysteresis
    "Greater block without hysteresis"
    parameter Real t=0
      "Threshold for comparison";
    Buildings.Controls.OBC.CDL.Interfaces.RealInput u
      "Input u"
      ;
    Buildings.Controls.OBC.CDL.Interfaces.BooleanOutput y
      "Output y"
      ;

  equation
    y=u > t
    ;
  end GreaterNoHysteresis;

  block GreaterWithHysteresis
    "Greater block without hysteresis"
    parameter Real t=0
      "Threshold for comparison";
    parameter Real h(
      final min=0)=0
      "Hysteresis"
      ;
    parameter Boolean pre_y_start=false
      "Value of pre(y) at initial time"
      ;
    Buildings.Controls.OBC.CDL.Interfaces.RealInput u
      "Input u"
      ;
    Buildings.Controls.OBC.CDL.Interfaces.BooleanOutput y
      "Output y"
      ;

  initial equation
    assert(
      h >= 0,
      "Hysteresis must not be negative");
    pre(y)=pre_y_start;

  equation
    y=(not pre(y) and u > t or pre(y) and u > t-h)
    ;
  end GreaterWithHysteresis;

equation
  connect(u,greHys.u)
    ;
  connect(greHys.y,y)
    ;
  connect(u,greNoHys.u)
    ;
  connect(greNoHys.y,y)

  ;
end GreaterThreshold;

