    "Needed to connect to conditional connector";
  Modelica.Blocks.Interfaces.RealInput dp_internal(unit="Pa")
    "Needed to connect to conditional connector";

equation
  // Ideal control
  if control_m_flow then
    m_flow = m_flow_internal;
  else
    m_flow_internal = 0;
  end if;
  if control_dp then
    dp = dp_internal;
  else
    dp_internal = 0;
