model Ren2014ACBedroom
  "A model to predict occupants' AC behavior in bedroom with indoor temperature"
  extends Modelica.Blocks.Icons.DiscreteBlock;
  parameter Real u1 = 304.40 "Threshold for turning off the AC of the Weibull Distribution";
  parameter Real u2 = 301.90 "Threshold for turning on the AC of the Weibull Distribution";
  parameter Real L1 = 13.34 "Normalization factor for turning off the AC of the Weibull Distribution";
  parameter Real L2 = 42.86 "Normalization factor for turning on the AC of the Weibull Distribution";
  parameter Real k1 = 1.73 "Shape factor for turning off the AC of the Weibull Distribution";
  parameter Real k2 = 1.80 "Shape factor for turning on the AC of the Weibull Distribution";
  parameter Modelica.Units.SI.Time samplePeriod=120 "Sample period";
  parameter Integer seed = 10 "Seed for random number generator";

  Modelica.Blocks.Interfaces.RealInput TIn(
    final unit="K",
    displayUnit="degC") "Indoor air temperature"
    ;
  Modelica.Blocks.Interfaces.BooleanInput occ
    "Indoor occupancy, true for occupied"
    ;

  Modelica.Blocks.Interfaces.BooleanOutput on "State of AC"
    ;

  Real pOn(
    final unit="1",
    final min=0,
    final max=1) "Probability of turning on the AC";
  Real pOff(
    final unit="1",
    final min=0,
    final max=1) "Probability of turning off the AC";

protected
  parameter Modelica.Units.SI.Time t0(final fixed=false)
    "First sample time instant";
  output Boolean sampleTrigger "True, if sample time instant";
  Real curSeed "Current value for seed as a real-valued variable";

initial equation
  t0 = time;
  curSeed = t0*seed;
  on = false "The initial state of AC is off";
  pOn = 0;
  pOff = 0;

equation
  sampleTrigger = sample(t0,samplePeriod);
  when sampleTrigger then
    curSeed = seed*time;
    pOff = if TIn <= u1 then 1 - Modelica.Math.exp(-((u1-TIn)/L1)^k1*samplePeriod) else 0;
    pOn = if TIn >= u2 then 1 - Modelica.Math.exp(-((TIn-u2)/L2)^k2*samplePeriod) else 0;
    if occ then
      if pre(on) then
        on = not Buildings.Occupants.BaseClasses.weibull1DOFF(
          x=TIn,
          u=u1,
          L=L1,
          k=k1,
          dt=samplePeriod,
          globalSeed=integer(curSeed));
      else
        on = Buildings.Occupants.BaseClasses.weibull1DON(
          x=TIn,
          u=u2,
          L=L2,
          k=k2,
          dt=samplePeriod,
          globalSeed=integer(curSeed));
      end if;
    else
      on = false;
    end if;
  end when

  ;
end Ren2014ACBedroom;

