model PIDHysteresisTimer
  "PID controller with anti-windup, hysteresis and timer to prevent short cycling"
  extends Modelica.Blocks.Interfaces.SVcontrol;
  extends Buildings.Obsolete.BaseClasses.ObsoleteModel;

  parameter Real minOffTime=600
    "Minimum time that devices needs to be off before it can run again"
      ;
  parameter Real eOn = 1
    "if off and control error > eOn, switch to set point tracking"
    ;
  parameter Real eOff = -eOn "if on and control error < eOff, set y=0"
    ;
  parameter Boolean pre_y_start=false
    "Value of hysteresis output at initial time"
    ;

  parameter Modelica.Blocks.Types.SimpleController controllerType=Modelica.Blocks.Types.SimpleController.PI
    "Type of controller"
      ;
  parameter Real k=1 "Gain of controller"
      ;
  parameter Modelica.Units.SI.Time Ti "Time constant of Integrator block"
    ;
  parameter Modelica.Units.SI.Time Td "Time constant of Derivative block"
    ;
  parameter Real yMax=1 "Upper limit of modulating output"
      ;
  parameter Real yMin=0.3
    "Lower limit of modulating output (before switch to 0)"
      ;
  parameter Real wp=1 "Set-point weight for Proportional block (0..1)"
      ;
  parameter Real wd=0 "Set-point weight for Derivative block (0..1)"
      ;
  parameter Real Ni=0.9 "Ni*Ti is time constant of anti-windup compensation"
      ;
  parameter Real Nd=10 "The higher Nd, the more ideal the derivative block"
      ;
  parameter Boolean reverseActing = true
    "Set to true for reverse acting, or false for direct acting control action"
     ;

  parameter Modelica.Blocks.Types.Init initType=Modelica.Blocks.Types.Init.InitialState
    "Type of initialization (1: no init, 2: steady state, 3: initial state, 4: initial output)"
    ;
  parameter Real xi_start=0
    "Initial or guess value value for integrator output (= integrator state)"
    ;
  parameter Real xd_start=0
    "Initial or guess value for state of derivative block"
    ;
  parameter Real y_start=0 "Initial value of output"
    ;

  parameter Boolean strict=true "= true, if strict limits with noEvent(..)"
    ;

  Modelica.Blocks.Interfaces.RealOutput tOn "Time since boiler switched on"
    ;
  Modelica.Blocks.Interfaces.RealOutput tOff "Time since boiler switched off"
    ;

  Buildings.Controls.Continuous.LimPID con(
    final controllerType=controllerType,
    final k=k,
    final Ti=Ti,
    final Td=Td,
    final wp=wp,
    final wd=wd,
    final Ni=Ni,
    final Nd=Nd,
    final initType=initType,
    final xi_start=xi_start,
    final xd_start=xd_start,
    final y_start=y_start,
    final yMin=yMin,
    final yMax=yMax,
    final reverseActing=reverseActing,
    final strict=strict) "Controller to track setpoint"
    ;
  Buildings.Controls.Continuous.OffTimer offHys
    ;
  Modelica.Blocks.Logical.Timer onTimer
    ;
  Modelica.Blocks.Logical.Timer offTimer
    ;
         Modelica.Blocks.Interfaces.BooleanOutput on
    "Outputs true if boiler is on"        ;
  Modelica.Blocks.Math.Feedback feeBac
    ;
  Modelica.Blocks.Logical.Hysteresis hys(
    final pre_y_start=pre_y_start,
    final uLow=eOff,
    final uHigh=eOn) "Hysteresis element to switch controller on and off"
    ;
protected
  Modelica.Blocks.Sources.Constant zer(final k=0) "Zero signal"
    ;
  Modelica.Blocks.Logical.Switch switch2
    ;
  Modelica.Blocks.Logical.GreaterEqualThreshold greaterEqualThreshold(threshold=
       minOffTime)
    ;
  Modelica.Blocks.Logical.And and3
    ;
  Modelica.Blocks.Logical.Not not1
    ;
  Modelica.Blocks.Logical.Switch switch1
    ;
equation
  connect(u_m, con.u_m) ;
  connect(zer.y,switch2. u3) ;
  connect(switch2.y, y) ;
  connect(and3.y,switch2. u2) ;
  connect(greaterEqualThreshold.y, and3.u1) ;
  connect(offHys.y, greaterEqualThreshold.u)   ;
  connect(con.y,switch2. u1) ;
  connect(onTimer.y, tOn) ;
  connect(offTimer.y, tOff) ;
  connect(and3.y, on) ;
  connect(and3.y, onTimer.u) ;
  connect(and3.y, not1.u) ;
  connect(not1.y, offTimer.u) ;
  connect(and3.y, switch1.u2) ;
  connect(u_s, switch1.u1) ;
  connect(u_m, switch1.u3) ;
  connect(switch1.y, con.u_s) ;
  connect(u_s, feeBac.u1) ;
  connect(u_m, feeBac.u2) ;
  connect(feeBac.y, hys.u) ;
  connect(hys.y, offHys.u) ;
  connect(hys.y, and3.u2) 
  ;
end PIDHysteresisTimer;

within Buildings.Electrical.AC.ThreePhasesUnbalanced.Lines;
model TwoPortRLC "Model of an RLC element with two electrical ports"
  extends Modelica.Electrical.Analog.Interfaces.ConditionalHeatPort;
  extends Buildings.Electrical.AC.ThreePhasesUnbalanced.Interfaces.TwoPort(
    terminal_p(phase(v(each nominal = V_nominal))),
    terminal_n(phase(v(each nominal = V_nominal))));

  parameter Modelica.Units.SI.Resistance R "Resistance at temperature T_ref";
  parameter Modelica.Units.SI.Capacitance C "Capacity";
  parameter Modelica.Units.SI.Inductance L "Inductance";
  parameter Modelica.Units.SI.Temperature T_ref=298.15 "Reference temperature"
    ;
  parameter Modelica.Units.SI.Temperature M=507.65
    "Temperature constant (R_actual = R*(M + T_heatPort)/(M + T_ref))"
    ;
  parameter Modelica.Units.SI.Voltage Vc1_start[2]=V_nominal/sqrt(3)*{1,0}
    "Initial voltage phasor of the capacitance located in the middle of phase 1"
    ;
  parameter Modelica.Units.SI.Voltage Vc2_start[2]=V_nominal/sqrt(3)*{-1/2,-
      sqrt(3)/2}
    "Initial voltage phasor of the capacitance located in the middle of phase 1"
    ;
  parameter Modelica.Units.SI.Voltage Vc3_start[2]=V_nominal/sqrt(3)*{-1/2,+
      sqrt(3)/2}
    "Initial voltage phasor of the capacitance located in the middle of phase 1"
    ;
  parameter Buildings.Electrical.Types.Load mode(
    min=Buildings.Electrical.Types.Load.FixedZ_steady_state,
    max=Buildings.Electrical.Types.Load.FixedZ_dynamic)=
    Buildings.Electrical.Types.Load.FixedZ_steady_state
    "Type of model (e.g., steady state, dynamic, prescribed power consumption, etc.)"
    ;
  parameter Modelica.Units.SI.Voltage V_nominal(min=0, start=480)
    "Nominal voltage (V_nominal >= 0)"
    ;
  OnePhase.Lines.TwoPortRLC phase1(
    final T_ref=T_ref,
    final M=M,
    final R=R/3,
    final L=L/3,
    final C=C/3,
    final mode=mode,
    final V_nominal = V_nominal/sqrt(3),
    final useHeatPort=useHeatPort,
    Vc_start=Vc1_start) "Impedance line 1"
    ;
  OnePhase.Lines.TwoPortRLC phase2(
    final T_ref=T_ref,
    final M=M,
    final R=R/3,
    final L=L/3,
    final C=C/3,
    final mode=mode,
    final V_nominal = V_nominal/sqrt(3),
    final useHeatPort=useHeatPort,
    Vc_start=Vc2_start) "Impedance line 2"
    ;
  OnePhase.Lines.TwoPortRLC phase3(
    final T_ref=T_ref,
    final M=M,
    final R=R/3,
    final L=L/3,
    final C=C/3,
    final mode=mode,
    final V_nominal = V_nominal/sqrt(3),
    final useHeatPort=useHeatPort,
    Vc_start=Vc3_start) "Impedance line 3"
    ;
equation
  // Joule Losses
  LossPower = phase1.LossPower + phase2.LossPower + phase3.LossPower;

  connect(terminal_n.phase[1], phase1.terminal_n) ;
  connect(terminal_n.phase[2], phase2.terminal_n) ;
  connect(terminal_n.phase[3], phase3.terminal_n) ;
  connect(phase1.terminal_p, terminal_p.phase[1]) ;
  connect(phase2.terminal_p, terminal_p.phase[2]) ;
  connect(phase3.terminal_p, terminal_p.phase[3]) ;

  connect(phase1.heatPort, heatPort) ;
  connect(phase3.heatPort, heatPort) ;
  connect(phase2.heatPort, heatPort) 
  ;
end TwoPortRLC;

