within Buildings.Controls.OBC.CDL.Logical;
block TrueDelay
  "Delay a rising edge of the input, but do not delay a falling edge."
  parameter Real delayTime(
    final quantity="Time",
    final unit="s")
    "Delay time";
  parameter Boolean delayOnInit=false
    "Set to true to delay initial true input";
  Buildings.Controls.OBC.CDL.Interfaces.BooleanInput u
    "Connector of Boolean input signal"
    ;
  Buildings.Controls.OBC.CDL.Interfaces.BooleanOutput y
    "Connector of Boolean output signal"
    ;

protected
  parameter Real t_past(
    final quantity="Time",
    final unit="s",
    fixed=false)
    "Time before simulation started";
  Real t_next(
    final quantity="Time",
    final unit="s")
    "Next event time";

initial equation
  t_past=time-1000;
  pre(u)=false;
  pre(t_next)=time-1000;

equation
  when initial() then
    t_next=
      if not delayOnInit then
        t_past
      else
        time+delayTime;
    y=if not
            (delayOnInit and delayTime > 0) then
        u
      else
        false;
  elsewhen u then
    t_next=time+delayTime;
    y=if delayTime > 0 then
        false
      else
        true;
  elsewhen not u then
    t_next=t_past;
    y=false;
  elsewhen time >= pre(t_next) then
    t_next=t_past;
    y=u;
  end when
  ;
end TrueDelay;

