within Buildings.Utilities.Math.Functions.BaseClasses;
function der_2_smoothTransition
  "Second order derivative of smoothTransition with respect to x"
  extends Modelica.Icons.Function;
  input Real x "Abscissa value";
  input Real delta(min=Modelica.Constants.eps)
    "Abscissa value below which approximation occurs";

  input Real deltaInv "Inverse value of delta";
  input Real a "Polynomial coefficient";
  input Real b "Polynomial coefficient";
  input Real c "Polynomial coefficient";
  input Real d "Polynomial coefficient";
  input Real e "Polynomial coefficient";
  input Real f "Polynomial coefficient";

  input Real x_der "Derivative of x";
  input Real x_der2 "Second order derivative of x";
  output Real y_der2 "Second order derivative of function value";
protected
  Real aX "Absolute value of x";
  Real ex "Intermediate expression";
algorithm
 aX:= abs(x);
 ex     := 2*c + aX*(6*d + aX*(12*e + aX*20*f));
 y_der2 := (b + aX*(2*c + aX*(3*d + aX*(4*e + aX*5*f))))*x_der2
         + x_der*x_der*( if x > 0 then ex else -ex)

;
end der_2_smoothTransition;

within Buildings.Fluid.HeatExchangers.BaseClasses.Examples;
model EpsilonNTUZ "Test model for the functions epsilon_ntuZ and ntu_epsilonZ"
  extends Modelica.Icons.Example;
  import f = Buildings.Fluid.Types.HeatExchangerFlowRegime;
  Real Z[6] "Ratio of capacity flow rates";
  Real epsilon[6] "Heat exchanger effectiveness";
  Real eps[6] "Heat exchanger effectiveness";
  Real ntu[6] "Number of transfer units";
  Real diff[6] "Difference in results";

protected
  constant Real uniCon(final unit="1/s") = 1
    "Unit conversion to satisfy unit check";

equation
  for conf in {Integer(f.ParallelFlow),
               Integer(f.CounterFlow),
               Integer(f.CrossFlowUnmixed),
               Integer(f.CrossFlowCMinMixedCMaxUnmixed),
               Integer(f.CrossFlowCMinUnmixedCMaxMixed),
               Integer(f.ConstantTemperaturePhaseChange)} loop
    Z[conf]       = abs(cos(uniCon*time));
    epsilon[conf] = 0.01 + 0.98*abs(sin(uniCon*time)) * 1/(1+Z[conf]);
    ntu[conf]     = ntu_epsilonZ(epsilon[conf], Z[conf], conf);
    eps[conf]     = epsilon_ntuZ(ntu[conf],     Z[conf], conf);
    diff[conf]    = epsilon[conf] - eps[conf];
  end for
  ;
end EpsilonNTUZ;

