//   elseif InitType ==BuildSysPro.Utilitaires.Types.InitCond.Value then
//     T=Tinit;
  end if;

equation
  port_a.Q_flow=G*(port_a.T-T);
  port_b.Q_flow=G*(port_b.T-T);
  C*der(T)=port_a.Q_flow+port_b.Q_flow

  ;
end MaterialLayer;

