within BuildSysPro.BaseClasses.Media.OLD_THERMHYGAERO.AirFunctions;
function Lv "Latent heat depending on temperature"
  input Real T "Air temperature [K]";
  input Real TKref "Absolute temperature of reference at 0°C [K]";
  input Real rv "Specific constant of water vapour [J/(kg.K)]";
  output Real Lv "Latent heat depending on temperature [J/kg]";
protected
  parameter Real Tmin=273.16;
  parameter Real Tmax=647.3;
  parameter Real tk=min(Tmax,max(Tmin,T));
  Real a;
  Real b;
  Real c;
  Real d;
algorithm
  if tk<=TKref then
        a :=-6086.67457;
        b :=0.258146988;
        c :=0;
        d :=27.2497986;
  elseif (tk <= 333.15) then
        a :=-6722.94637;
        b :=-4.77551358;
        c :=0;
        d :=57.8181266;
  else  a :=-7797.09834;
        b :=-11.2831932;
        c :=0.00993664096;
        d :=95.5324251;
  end if;
  Lv := rv*T*T*(-a/(T*T) + b/T + c)

  ;
end Lv;

within BuildSysPro.BaseClasses.Media.OLD_THERMHYGAERO.AirFunctions;
function Psat "Saturation pressure depending on temperature"
  AirConstants.CteAH AH;
  input Real T "Air temperature [K]";
  output Real Psat "Vapour saturation pressure [Pa]";
protected
  parameter Real Tmin=273.16;
  parameter Real Tmax=647.3;
  parameter Real tk=min(Tmax,max(Tmin,T));
  Real a;
  Real b;
  Real c;
  Real d;
algorithm
  if tk<=AH.TKref then
        a :=-6086.67457;
        b :=0.258146988;
        c :=0;
        d :=27.2497986;
  elseif (tk <= 333.15) then
        a :=-6722.94637;
        b :=-4.77551358;
        c :=0;
        d :=57.8181266;
  else  a :=-7797.09834;
        b :=-11.2831932;
        c :=0.00993664096;
        d :=95.5324251;
  end if;
  Psat:=exp(a/tk + b*log(tk) + c*tk + d)

  ;
end Psat;

within BuildSysPro.BoundaryConditions.Radiation;
function BESTESTSolarDistrib
  "Computation of solar fractions following the procedure described in BESTEST appendix"

input Integer np "Number of walls";
input Integer nf "Number of windows";
input Real Sp[np] "Walls surface areas";
input Real Sf[nf] "Windows surface areas";
input Real AbsP "Short-wave diffuse absorptance of walls";
input Real AbsF "Short-wave diffuse absorptance of windows";
input Real TrF "Short-wave diffuse transmittance of windows";

input Real FFp[np] "Form factor between walls and floor for the computation of the first reflection /
BESTEST : 1-ceiling, 2-floor, 3-North, 4-South, 5-East, 6-West";

input Real FFf[nf]
    "Form factor between windows and floor for the computation of the first reflection";

// Several outputs: beware of the order!
output Real[np] SFp
    "Solar fractions of walls / BESTEST : 1-ceiling, 2-floor, 3-North, 4-South, 5-East, 6-West";
output Real[nf] SFf
    "Solar fractions of windows/ BESTEST : 1-South OR 1-East, 2-West";

//Intermediate solar fractions for walls
protected
Real B1p[np];
Real B2p[np];
Real B3p[np];
Real BRp[np];

// Intermediate solar fraction for windows
Real[nf] B1f_abs;
Real[nf] B1f_lost;
Real[nf] B2f_abs;
Real[nf] B2f_lost;
Real[nf] B3f_abs;
Real[nf] B3f_lost;
Real[nf] BRf_abs;
Real[nf] BRf_lost;

// Intermediate sums of solar fractions and surfaces
Real B2t;
Real B3t;
Real BRt;
Real St;

algorithm
// calculation of surfaces sum
St :=sum(Sp)+sum(Sf);

// B1 calculation- First reflection of the incident short-wave radiation - Hypothesis = everything hit the floor
for i in 1:np loop
  B1p[i]:= if i<>2 then 0 else AbsP;  //i=2 représente le plancher
end for;
for i in 1:nf loop
  B1f_abs[i]:= 0;
  B1f_lost[i]:= 0;
end for;

// B2 calculation - Second reflection of the incident short-wave radiation - Hypothesis = diffuse redistribution through the floor proportionally to the term : absorptance x form factor
for i in 1:np loop
  B2p[i]:= if i<>2 then (1-AbsP)*AbsP*FFp[i] else 0;
end for;
for i in 1:nf loop
  B2f_lost[i]:= (1-AbsP)*(TrF-AbsF/2)*FFf[i];
  B2f_abs[i]:= (1-AbsP)*(AbsF/2)*FFf[i];
end for;
B2t := sum(B2p)+sum(B2f_abs)+sum(B2f_lost);

// B3 calculation- Third reflection of the incident short-wave radiation - Hypothesis = remaining distribution on each surface proportionally to the term : absorptance x form factor
for i in 1:np loop
  B3p[i]:= (1-AbsP-B2t)*AbsP*Sp[i]/St;
end for;
for i in 1:nf loop
  B3f_lost[i]:= (1-AbsP-B2t)*(TrF-AbsF/2)*Sf[i]/St;
  B3f_abs[i]:= (1-AbsP-B2t)*(AbsF/2)*Sf[i]/St;
end for;
B3t := sum(B3p)+sum(B3f_abs)+sum(B3f_lost);

// BR calculation - Remaining flux distribution proportionally to the third reflection
for i in 1:np loop
  BRp[i]:= (1-AbsP-B2t-B3t)*B3p[i]/B3t;
end for;
for i in 1:nf loop
  BRf_abs[i]:= (1-AbsP-B2t-B3t)*B3f_abs[i]/B3t;
  BRf_lost[i]:= (1-AbsP-B2t-B3t)*B3f_lost[i]/B3t;
end for;

// Form factors (FF) calculation
for i in 1:np loop
  SFp[i]:= B1p[i]+B2p[i]+B3p[i]+BRp[i];
end for;
for i in 1:nf loop
  SFf[i]:= B1f_abs[i] +B2f_abs[i] +B3f_abs[i] +BRf_abs[i];
end for

  ;
end BESTESTSolarDistrib;

within BuildSysPro.BoundaryConditions.Radiation;
model FractionSolarDistrib
  "Redistribution of short-wave radiation entering a zone on each wall and window - based on absorptance/transmittance coefficients, surfaces and form factors"

extends RadDistrib;
  BuildSysPro.BoundaryConditions.Solar.Interfaces.SolarFluxInput FluxEntrant
    "Solar irradiation to be redistributed" ;

parameter Real AbsP "Short-wave diffuse absorptance of walls"  ;
parameter Real AbsF "Short-wave diffuse absorption coefficient of windows" ;
parameter Real TrF "Short-wave diffuse transmission coefficient of windows" ;
parameter Real FFp[np]={0.49420,0,0.14610,0.05681,0.10680,0.10680} "Form factor between walls and floor for the calculation of the first reflection/ 
    BESTEST : 1-ceiling, 2-floor, 3-North, 4-South, 5-East, 6-West";
parameter Real FFf[nf]={0.08929}
    "Form factor between windows and floor for the calculation of the first reflection";

//  Intermediate solar fractions for windows
Real[np] SFp
    "Walls solar fractions / BESTEST : 1-ceiling, 2-floor, 3-Northe, 4-South, 5-East, 6-West";
Real[nf] SFf "Windows solar fractions/ BESTEST : 1-South OR 1-East, 2-West";

algorithm
 when initial() then
    (SFp,SFf) := BESTESTSolarDistrib(
              np=np,
              nf=nf,
              Sp=Sp,
              Sf=Sf,
              FFp=FFp,
              FFf=FFf,
              AbsP=AbsP,
              AbsF=AbsF,
              TrF=TrF);
 end when;

equation
  for i in 1:np loop
  FLUXParois[i]=FluxEntrant*SFp[i];
end for;
for i in 1:nf loop
  FLUXFenetres[i]=FluxEntrant*SFf[i];
end for

  ;
end FractionSolarDistrib;

within BuildSysPro.BoundaryConditions.Radiation;
model PintRadDistrib
  "Redistribution of radiative heat flow entering a zone on each wall and window - based on surfaces only"

extends RadDistrib;
Modelica.Blocks.Interfaces.RealInput                            RayEntrant
    "Entering radiative heat flow to be redistributed" ;

Real St "Total surface area of walls and windows";
Real SFp[np]
    "Walls radiative fractions / BESTEST : 1-ceiling, 2-floor, 3-North, 4-South, 5-East, 6-West";
Real SFf[nf]
    "Windows radiative fractions / BESTEST : 1-South OR 1-East, 2-West";

algorithm
St :=sum(Sp)+sum(Sf);
for i in 1:np loop
  SFp[i] := Sp[i]/St;
end for;
for i in 1:nf loop
  SFf[i] := Sf[i]/St;
end for;

equation
for i in 1:np loop
  FLUXParois[i]=RayEntrant*SFp[i];
end for;
for i in 1:nf loop
  FLUXFenetres[i]=RayEntrant*SFf[i];
end for

  ;
end PintRadDistrib;

