within BuildSysPro.BoundaryConditions.Solar.Irradiation;
block DirectAbs
  "Compute the direct solar irradiation absorbed by a glazing surface"
extends Modelica.Blocks.Icons.Block;

parameter Integer choix=2 "Formula used" ;
parameter Real AbsDir "Direct window absorptance at normal incidence";

  BuildSysPro.BoundaryConditions.Solar.Interfaces.SolarFluxInput FluxIncExt[3]
    "Input connector for solar irradiation 1-Diffuse, 2-Direct, 3-Cos i"
    ;
  BuildSysPro.BoundaryConditions.Solar.Interfaces.SolarFluxOutput FluxAbsDir
    "Direct irradiation absorbed in the glazing surface" ;

// Variables internes
protected
Real cosi;
Real PondAbsDir;
// Coefficients calculés pour la formule de Fauconnier
parameter Real a0 = 0.0016 - 0.0619*AbsDir - 0.0368*AbsDir^2;
parameter Real a1 = -0.007 + 1.65*AbsDir - 0.443*AbsDir^2;
parameter Real a2 = 0.005 - 0.5849*AbsDir + 0.4835*AbsDir^2;

// Coefficients calculés pour la formule de la RT
parameter Real alpha30 = -8.5884e-4 + 1.0869*AbsDir - (6.1151e-2)*AbsDir^2;
parameter Real alpha60 = -1.7566e-3 + 1.2352*AbsDir - (2.7231e-1)*AbsDir^2;
parameter Real d1 = 6.4646*AbsDir - 11.7745*alpha30 + 9.4645*alpha60;
parameter Real d2 = -20.394*AbsDir + 35.3234*alpha30 - 20.394*alpha60;
parameter Real d3 = 14.9294*AbsDir - 23.5489*alpha30 + 10.9295*alpha60;

algorithm
cosi :=FluxIncExt[3];
if choix == 1 then
  // Fauconnier
  PondAbsDir := if noEvent(cosi>0.05) then max(0,a0/cosi + a1 + a2*cosi) else 0;
elseif choix ==2 then
  // RT
  PondAbsDir := if noEvent(cosi>0) then d1*cosi + d2*cosi^2 + d3*cosi^3 else 0;
elseif choix ==3 then
 // Formule de Cardonnel
  PondAbsDir := if noEvent(cosi>0) then (if noEvent(cosi>0.8) then AbsDir else AbsDir*2.5*cosi*(1-0.625*cosi)) else 0;
else
  PondAbsDir := if noEvent(cosi>0) then cosi*AbsDir else 0;
end if;

  FluxAbsDir := PondAbsDir*FluxIncExt[2]

  ;
end DirectAbs;

within BuildSysPro.BoundaryConditions.Solar.Irradiation;
block DirectTrans
  "Compute the direct solar irradiation transmited through a glazing surface"
extends Modelica.Blocks.Icons.Block;

parameter Integer choix=2 "Formula used" ;
parameter Real TrDir "Direct window transmittance at normal incidence";

  BuildSysPro.BoundaryConditions.Solar.Interfaces.SolarFluxInput FluxIncExt[3]
    "Input connector for solar irradiation 1-Diffuse, 2-Direct, 3-Cos i"
    ;
  BuildSysPro.BoundaryConditions.Solar.Interfaces.SolarFluxOutput FluxTrDir
    "Direct irradiation transmitted through the glazing surface" ;

// Internal variables
protected
Real cosi;
Real PondTransDir;
// Coefficients calculated for the Fauconnier formula
parameter Real c0 = 0.0139 - 0.1093*TrDir - 0.0079*TrDir^2;
parameter Real c1 = -0.0895 + 0.7662*TrDir + 0.4706*TrDir^2;
parameter Real c2 = 0.0751 + 0.3489*TrDir - 0.4563*TrDir^2;

// Coefficients calculated for the RT formula
parameter Real tau30 = -7.068e-4 + TrDir*9.3967e-1 + (TrDir^2)*7.0476e-2;
parameter Real tau60 = -1.6265e-2 + TrDir*6.9767e-1 + (TrDir^2)*2.4509e-1;
parameter Real b1 = 6.4646*TrDir - 11.7745*tau30 + 9.4645*tau60;
parameter Real b2 = -20.3940*TrDir + 35.3234*tau30 - 20.3940*tau60;
parameter Real b3 = 14.9294*TrDir - 23.5489*tau30 + 10.9295*tau60;

algorithm
cosi :=FluxIncExt[3];
if choix == 1 then
  // Fauconnier
  PondTransDir := if noEvent(cosi>0.05) then max(0,c0/cosi + c1 + c2*cosi) else 0;
elseif choix ==2 then
  // RT
  PondTransDir := if noEvent(cosi>0) then b1*cosi + b2*cosi^2 + b3*cosi^3 else 0;
elseif choix ==3 then
 // Cardonnel formula
  PondTransDir := if noEvent(cosi>0) then (if noEvent(cosi>0.8) then TrDir else TrDir*2.5*cosi*(1-0.625*cosi)) else 0;
else
  PondTransDir := if noEvent(cosi>0) then cosi*TrDir else 0;
end if;

  FluxTrDir := PondTransDir*FluxIncExt[2]

  ;
end DirectTrans;

