within BuildSysPro.BoundaryConditions.Solar.Irradiation;
model FLUXzone "Calculation of irradiance and illuminance for a zone model"

parameter Real albedo=0.2 "Albedo of the environment";
parameter Boolean ChoixAzimuth=false
    "Provide azimuth for each surface or considered a parallelepipedic zone"
    ;
parameter Real beta=0
    "Zone orientation azimut=beta+azimut, (if beta=0 : azimut={N=180,S=0,E=-90,O=90})"
    ;
parameter Real azim[5]={0,beta+180,beta,beta-90,beta+90}
    "Walls azimuth, by default 1-Ceiling, 2-North, 3-South, 4-East, 5-West"
      ;
parameter Real incl[5]={0,90,90,90,90}
    "Walls tilt, by default 1-Ceiling, 2-North, 3-South, 4-East, 5-West";
  BuildSysPro.BoundaryConditions.Solar.Interfaces.SolarFluxOutput FluxIncExtNorth[3]
    "Irradiance for the North facing surface [W/m²] 1-Diffuse, 2-Direct and 3-Cosi"
    ;

  BuildSysPro.BoundaryConditions.Solar.Interfaces.SolarFluxOutput FluxIncExtSouth[3]
    "Irradiance for the South facing surface [W/m²] 1-Diffuse, 2-Direct and 3-Cosi"
    ;
  BuildSysPro.BoundaryConditions.Solar.Interfaces.SolarFluxOutput FluxIncExtRoof[3]
    "Irradiance for the sky facing surface [W/m²] 1-Diffuse, 2-Direct and 3-Cosi"
    ;
  BuildSysPro.BoundaryConditions.Solar.Interfaces.SolarFluxOutput FluxIncExtEast[3]
    "Irradiance for the East facing surface [W/m²] 1-Diffuse, 2-Direct and 3-Cosi"
    ;
  BuildSysPro.BoundaryConditions.Solar.Interfaces.SolarFluxOutput FluxIncExtWest[3]
    "Irradiance for the West facing surface [W/m²] 1-Diffuse, 2-Direct and 3-Cosi"
    ;

Modelica.Blocks.Interfaces.RealInput G[10]
    "Inputs data {DIFH, DIRN, DIRH, GLOH, t0, CosDir[1:3], solar azimuth angle, solar elevation angle}"
    ;

  Modelica.Units.SI.HeatFlux DIRH;
  Modelica.Units.SI.HeatFlux DIRN;
  Modelica.Units.SI.HeatFlux GLOH;
  Modelica.Units.SI.HeatFlux DIFH;
  Real FLUX[15];
  Real DiffusSol[5];
  output Real sin_h;
  output Real cosi[5];
protected
  parameter Real azim_in[5]=if ChoixAzimuth then azim[1:5] else {0,beta+180,beta,beta-90,beta+90};
  constant Real d2r=Modelica.Constants.pi/180;
  final parameter Real s[5]={incl[i]*d2r for i in 1:5} "tilt";
  final parameter Real g[5]={azim_in[i]*d2r  for i in 1:5} "Orientation";
  final parameter Real coef1[5]={0.5*(1 - cos(s[i]))*albedo for i in 1:5};
  final parameter Real coef2[5]={0.5*(1 + cos(s[i])) for i in 1:5};
  // Direction cosines of the plan
  final parameter Real l[5]={cos(s[i]) for i in 1:5};
  final parameter Real m[5]={sin(s[i])*sin(g[i]) for i in 1:5};
  final parameter Real n[5]={sin(s[i])*cos(g[i]) for i in 1:5};

  Real Idn "Direct normal irradiance";
  Real Idi "Isotropic horizontal diffuse irradiance";
  Real Edn "Direct normal illuminance";
  Real Edi "Diffuse horizontal illuminance";
  Real gamma "Solar elevation angle above the horizon [rad]";
  Real pi=Modelica.Constants.pi;
  Real phi "Sun azimuth relative to South [rad]";
  Real teta[5] "Angle between solar beam and surface normal [rad]";
  Real Erp[5] "Direct illuminance on the surfaces [lux]";
  Real Efp[5] "Diffuse illuminance on the surfaces [lux]";
  Real ERrp[5] "Illuminance reflected by the ground on the surfaces [lux]";

public
  Modelica.Blocks.Interfaces.RealOutput IlluSouth[3]
    "Illuminance for the South facing surface [lumen] 1-Direct, 2-Diffuse and 3-Reflected"
    ;

  Modelica.Blocks.Interfaces.RealOutput IlluNorth[3]
    "Illuminance for the North facing surface [lumen] 1-Direct, 2-Diffuse and 3-Reflected"
    ;
  Modelica.Blocks.Interfaces.RealOutput IlluWest[3]
    "Illuminance for the West facing surface [lumen] 1-Direct, 2-Diffuse and 3-Reflected"
    ;
  Modelica.Blocks.Interfaces.RealOutput IlluEast[3]
    "Illuminance for the East facing surface [lumen] 1-Direct, 2-Diffuse and 3-Reflected"
    ;
  Modelica.Blocks.Interfaces.RealOutput IlluRoof[3]
    "Illuminance for the sky facing surface [lumen] 1-Direct, 2-Diffuse and 3-Reflected"
    ;

algorithm
  // sin_h and cosi computations
  sin_h :=G[6];  //First direction consine of the solar vector
  cosi:={max(0, l[i]*G[6] + m[i]*G[7] + n[i]*G[8]) for i in 1:5};

//equation
//// Irradiance computation
//Direct irradiance calculation: if sin h is negative, direct irradiance is canceled"
  DIFH:=G[1];
  DIRN:=G[2];
  DIRH:=G[3];
  GLOH:=G[4];

 for i in 1:5 loop
   // FLUX vector for irradiance on the surfaces: diffuse, direct, cosi
   DiffusSol[i] :=max(0, coef1[i]*GLOH);
   FLUX[3*i-2] :=max(0, coef2[i]*DIFH) + DiffusSol[i];
   FLUX[3*i-1] :=if noEvent(sin_h > 0.01) then max(0, cosi[i])*DIRN else 0; //To avoid cases with a non-zero direct irradiance when the sun is below the horizon
   FLUX[3*i] :=cosi[i];
 end for;
  FluxIncExtRoof := FLUX[1:3];
  FluxIncExtNorth := FLUX[4:6];
  FluxIncExtSouth := FLUX[7:9];
  FluxIncExtEast := FLUX[10:12];
  FluxIncExtWest := FLUX[13:15];

equation

 //Computation of natural illuminance (French building regulation RT2012)
  Idn=DIRN;
  Idi=DIFH;
  gamma=G[10]*pi/180;
  Edn=Idn*(-1.0375321*10^(-8)*gamma^6+2.90312257*10^(-6)*gamma^5-3.31804423*10^(-4)*gamma^4+1.99283162*10^(-2)*gamma^3-6.72171072*10^(-1)*gamma^2+1.24650445*10*gamma+2.38954889);
  if Idn<1 then
    Edi=124*Idi;
  else if Idn>120 then
        Edi=128*Idi;
  else Edi=116*Idi;
  end if;
  end if;

algorithm
  // Computation of illuminance (direct, diffuse and reflected) without shading
  phi:=G[9]*pi/180;
  for i in 1:5 loop
  teta[i]:=min(pi/2, acos(cos(gamma)*sin(incl[i]*pi/180)*cos(phi - azim[i]*pi/180)+ sin(gamma)*cos(incl[i]*pi/180)));
  Erp[i]:=cos(teta[i])*Edn;
  Efp[i]:=Edi*0.5*(1 + cos(incl[i]*pi/180));
  ERrp[i]:=(Edn*sin(gamma) + Edi)*albedo*0.5*(1 - abs(cos(incl[i]*pi/180)));
  end for;

  IlluRoof := {Erp[1],Efp[1],ERrp[1]};
  IlluNorth := {Erp[2],Efp[2],ERrp[2]};
  IlluSouth := {Erp[3],Efp[3],ERrp[3]};
  IlluEast := {Erp[4],Efp[4],ERrp[4]};
  IlluWest
         :={Erp[5],Efp[5],ERrp[5]}

;
end FLUXzone;

within BuildSysPro.BoundaryConditions.Solar.Irradiation;
model LightTransCoeff
  "Calculation of direct and global light transmittance throught a window"

  parameter Real H=1 "Window height";
  parameter Real L=1 "Window width";
  parameter Real e=0.35 "Wall thickness";
  parameter Real azimut=0
    "Surface azimuth (Orientation relative to the south) - S=0°, E=-90°, W=90°, N=180°";

  parameter Real TLw=0.5 "Global light transmittance without solar shading";
  parameter Real TLw_dif=0 "Diffuse light transmittance without solar shading";

  parameter Real TLws=0 "Global light transmittance with solar shading";
  parameter Real TLws_dif=0 "Diffuse light transmittance with solar shading";

  parameter Boolean MasqueProche=false
    ;
  parameter Boolean Protection=false
    ;
protected
  Real K "Form coefficient";
  Real R_dir "Share of the total direct incident radiation on the bay window";
  Real Fbati_dir;
  Real Fbati_dif;
  Real Friv_dir;
  Real Friv_dif;
  Real k;
  Real l;
  Real m;

public
  Modelica.Blocks.Interfaces.RealOutput CoeffTransLum[4]
    "Light transmittance -global without protection,- diffuse without protection, - global with protection, -diffuse with protection"
    ;

equation
if (L>0 and H>0) then

  //Calculation of form coefficient characterizing the bay window (formula 7 of Th-L rules)
  K=L*H/(e*(L+H));

  //Computation of correction coefficients
  //Share of the total direct incident radiation on the bay window (table 9 of Th-L rules)
  if azimut==0 then
    R_dir=0.5;
  else if azimut==90 then
    R_dir=0.4;
  else if azimut==-90 then
    R_dir=0.4;
  else R_dir=0.05;
  end if;
  end if;
  end if;

  //Correction coefficients associated with the integration to work (Tables 10 and 11 of Th-L Rules)
if MasqueProche==false then
    if K<=1 then
      Fbati_dif=0.5;
        if azimut==0 then
          Fbati_dir=0.45;
        else if azimut==90 then
          Fbati_dir=0.55;
        else if azimut==-90 then
          Fbati_dir=0.55;
        else Fbati_dir=0.15;
        end if;
        end if;
  end if;
else if K<5 then
  Fbati_dif=0.7;
  if azimut==0 then
          Fbati_dir=0.70;
        else if azimut==90 then
          Fbati_dir=0.75;
        else if azimut==-90 then
          Fbati_dir=0.75;
        else Fbati_dir=0.30;
        end if;
        end if;
        end if;
else Fbati_dif=0.85;
  if azimut==0 then
          Fbati_dir=0.85;
        else if azimut==90 then
          Fbati_dir=0.90;
        else if azimut==-90 then
          Fbati_dir=0.90;
        else Fbati_dir=0.60;
        end if;
        end if;
        end if;
    end if;
    end if;
else
Fbati_dir=1;
Fbati_dif=1;
end if;

  //Correction coefficients related to the variable incidence (Table 18 of Th-L Rules)
  if K<1.5 then
    k=1;
  else k=0;
  end if;
  if Protection==true then
    l=1;
  else l=0;
  end if;
  m=l+k;
  if m>0 then
    Friv_dir=1;
    Friv_dif=1;
  else Friv_dir=0.95;
    Friv_dif=0.95;
  end if;

  //Light transmission coefficients with and without sun protection (formula 1,2,3 and 4 of Th-L Rules)
  CoeffTransLum[1]=(R_dir*Fbati_dir*Friv_dir+(1-R_dir)*Fbati_dif*Friv_dif)*TLw;
  CoeffTransLum[2]=(R_dir*Fbati_dir*Friv_dir+(1-R_dir)*Fbati_dif*Friv_dif)*TLw_dif;
  CoeffTransLum[3]=(R_dir*Fbati_dir*Friv_dir+(1-R_dir)*Fbati_dif*Friv_dif)*TLws;
  CoeffTransLum[4]=(R_dir*Fbati_dir*Friv_dir+(1-R_dir)*Fbati_dif*Friv_dif)*TLws_dif;

else
  //Window dimensions are null
  K=0;
  Fbati_dir=0;
  Fbati_dif=0;
  Friv_dir=0;
  Friv_dif=0;
  R_dir=0;
  k=0;
  l=0;
  m=0;
  CoeffTransLum[1]=0;
  CoeffTransLum[2]=0;
  CoeffTransLum[3]=0;
  CoeffTransLum[4]=0;
end if

  ;
end LightTransCoeff;

within BuildSysPro.BoundaryConditions.Solar.Irradiation;
model NaturalIlluminance "Natural illuminance transmitted to a zone"

parameter Real S_gr=100 "Total surface of the group (m²)";
parameter Real Aecl_nat=80
    "Surface of the group with access to natural light (m²)";
protected
Real R_gr=4.5
    "Ratio of the total surface of the group's walls to the living surface";

Real Flt1
    "Transmitted illuminance to the group by all the group windows in direct form [lumen]";
Real Flt2
    "Transmitted illuminance to the group by all the group windows in hemispherical form [lumen]";
Real Flt3
    "Transmitted illuminance to the group by all the group windows in half-hemispherical form [lumen]";
Real Flteq
    "Equivalent illuminance entering the group parts having access to light [lumen]";
Real C2;
public
parameter Real PinstEcl=1.4 "Conventional power lighting [W/m²]";
parameter Real C1=0.9
    "Lighting utilization rates in the absence of natural lighting";
    parameter Real EclNatRef=200 "Reference natural illuminance for the room";

parameter Real C2ref=0.05;

  Modelica.Blocks.Interfaces.RealInput FlumPlafond[3]
    "Incident illuminance coming from the ceiling -direct -diffuse -reflected [lumen]"
    ;
  Modelica.Blocks.Interfaces.RealInput FlumSud[3]
    "Incident illuminance coming from the South facing window -direct -diffuse -reflected [lumen]"
    ;
  Modelica.Blocks.Interfaces.RealInput FlumNord[3]
    "Incident illuminance coming from the North facing window -direct -diffuse -reflected [lumen]"
    ;
  Modelica.Blocks.Interfaces.RealInput FlumOuest[3]
    "Incident illuminance coming from the West facing window -direct -diffuse -reflected [lumen]"
    ;
  Modelica.Blocks.Interfaces.RealInput FlumEst[3]
    "Incident illuminance coming from the East facing window -direct -diffuse -reflected [lumen]"
    ;
  Modelica.Blocks.Interfaces.RealOutput EclNat
    "Global natural illuminance transmitted to the group [lux]"
                                                    ;
  Modelica.Blocks.Interfaces.RealOutput Pecl "Power lighting to supply [W]"
    ;
  Modelica.Blocks.Interfaces.RealInput Occupation "1 = presence, 0 = absence"
    ;
  Modelica.Blocks.Interfaces.RealInput ConsigneEclairage
    "Use of artificial lighting (1 = Yes, 0 = No)"
    ;

equation
  Flt1=FlumPlafond[1]+FlumSud[1]+FlumNord[1]+FlumOuest[1]+FlumEst[1];
  Flt2=FlumPlafond[2]+FlumSud[2]+FlumNord[2]+FlumOuest[2]+FlumEst[2];
  Flt3=FlumPlafond[3]+FlumSud[3]+FlumNord[3]+FlumOuest[3]+FlumEst[3];
  Flteq=0.2*Flt1+Flt2+0.6*Flt3;
  EclNat=(1.8*Flteq)/(R_gr*Aecl_nat*0.75);

  if EclNat < 100 then
    C2 = 1;
  elseif EclNat < EclNatRef then
    C2 = 1+(EclNat-100)*(C2ref-1)/(EclNatRef-100);
  elseif EclNat < 2800 then
    C2 = 0.05+(EclNat-EclNatRef)*(0-C2ref)/(2800-EclNatRef);
  else
    C2 = 0;
  end if;

  Pecl= PinstEcl*C1*C2*Occupation*S_gr*ConsigneEclairage

  ;
end NaturalIlluminance;

