within BuildSysPro.BoundaryConditions.Solar.SolarMasks;
function FullMask
  "Calculation of the sunny area for the full mask (horizontal+vertical)"

  input Modelica.Units.SI.Distance Av "Overhang";
  input Modelica.Units.SI.Distance Ha
    "Distance between the overhang and the top of the surface (window)";
  input Modelica.Units.SI.Distance Lf "Surface (window) width";
  input Modelica.Units.SI.Distance Hf "Surface (window) height";
  input Modelica.Units.SI.Distance Dd "Lateral overhang (right hand side)";
  input Modelica.Units.SI.Distance Dg "Lateral overhang (left hand side)";
  input Modelica.Units.NonSI.Angle_deg AzimutSoleil
    "Solar azimuth angle (Orientation relative to the south) - S=0°, E=-90°, W=90°, N=180°";
  input Modelica.Units.NonSI.Angle_deg HauteurSoleil "Solar elevation angle";
  input Modelica.Units.NonSI.Angle_deg azimut
    "Surface tilt - downwards = 180° skyward = 0°, vertical = 90°";

  output Modelica.Units.SI.Area A0 "Sunny surface of the window";

protected
  Modelica.Units.SI.Distance X0
    "Intermediate variable for the calculation of A0";
  Modelica.Units.SI.Distance Y0
    "Intermediate variable for the calculation of A0";
constant Real Convert=Modelica.Constants.pi/180
    "Conversion factor degrees->radians";

algorithm
  //Calculation of Y0
  Y0 := Av * tan(HauteurSoleil*Convert)/cos((azimut-AzimutSoleil)*Convert);
  if Y0 <= Ha then
    Y0 := Ha;
  end if;
  if Y0 >= Ha+Hf then
    Y0 := Ha+Hf;
  end if;

  //Calculation of X0
  if AzimutSoleil<=azimut then
    X0 :=Av * tan((azimut-AzimutSoleil)*Convert);
    if X0 <= Dg then
      X0 := Dg;
    end if;
    if X0 >= Dg + Lf then
      X0 := Dg + Lf;
    end if;
    A0 := (Lf+Dg-X0)*(Ha+Hf-Y0);
  else
    X0 :=Av * tan((AzimutSoleil-azimut)*Convert);
    if X0 <= Dd then
      X0 := Dd;
    end if;
    if X0 >= Dd + Lf then
      X0 := Dd + Lf;
    end if;
    A0 := (Lf+Dd-X0)*(Ha+Hf-Y0);
  end if

  ;
end FullMask;

within BuildSysPro.BoundaryConditions.Solar.SolarMasks;
function HorizontalMask
  "Calculation of the sunny area for an horizontal shading device"

  input Modelica.Units.SI.Distance Av "Overhang";
  input Modelica.Units.SI.Distance Ha
    "Distance between the overhang and the top of the surface (window)";
  input Modelica.Units.SI.Distance Lf "Surface (window) width";
  input Modelica.Units.SI.Distance Hf "Surface (window) height";
  input Modelica.Units.SI.Distance Dd "Lateral overhang (right hand side)";
  input Modelica.Units.SI.Distance Dg "Lateral overhang (left hand side)";
  input Modelica.Units.NonSI.Angle_deg AzimutSoleil
    "Solar azimuth angle (orientation relative to the south) - S=0°, E=-90°, W=90°, N=180°";
  input Modelica.Units.NonSI.Angle_deg HauteurSoleil "Solar elevation angle";
  input Modelica.Units.NonSI.Angle_deg azimut
    "Surface tilt - downwards = 180° skyward = 0°, vertical = 90°";
  output Modelica.Units.SI.Area Asol "Sunny surface of the window";

protected
Integer Cas
    "Number of the shading shape - see ISO 13791 standard - For validations";
  Modelica.Units.SI.Area A0 "Shadow surface on the window";
constant Real Convert=Modelica.Constants.pi/180
    "Conversion factor degrees->radians";
  Modelica.Units.NonSI.Angle_deg Phi "Sun azimuth - Surface azimuth";
Boolean DebordGauche
    "=true if the sun comes through the left overhang, false otherwise";
  Modelica.Units.SI.Distance T "Shadow depth";
  Modelica.Units.SI.Distance M "Shadow offset";
  Modelica.Units.SI.Distance X0
    "X coordinates of the horizontal mask corner projection on the wall";
  Modelica.Units.SI.Distance Y0
    "Y coordinates of the horizontal mask corner projection on the wall";
    Boolean Inclus "=true if the point belongs to the surface";
    Real Xdeb "Overhang X coordinates";
    Real Ydeb "Overhang Y coordinates";
    Boolean continue=true "True while the good case is not found";
Real b;

// Intersections with the vertical and horizontal edges
Real Yi0;
Real YiL;
Real Xi0;
Real XiH;
Real X2iH
    "Intermediate Size - intersection of the other overhang for case 1 discrimination";

algorithm
   Phi := AzimutSoleil-azimut; //Beware if Phi = 0 => M=0 => shape of the shadow determined according to the value of T
   DebordGauche := if (Phi < 0) then true else false;
   T := Av * tan(HauteurSoleil*Convert)/cos(Phi*Convert);
   M := Av * tan(Phi*Convert);

// First cases determined if Phi = 0
if (not (M<>0)) then
  continue := false;
  // Particular cases 1,2 or 3
  if (T >= Ha+Hf) then
    Cas := 2;
  elseif (T <= Ha) then
    Cas := 1;
  else
    Cas := 3;
  end if;
end if;

//Cases determined through the knowledge of the horizontal mask corner projection coordinates in the direction of light rays
if DebordGauche==true then
  b := Dg;
  Xdeb := Lf +Dg;
else
  b := Dd;
  Xdeb:= -Dd;
end if;
Ydeb := Ha + Hf;
X0 := Xdeb + M;
Y0 := Ydeb - T;

if (continue == true) then
  //Calculation of the coordinates (X,Y) of the intersection between the incident ray from (Xdeb,Ydeb) and the edges of the window
  //Calculation of Y coordinates of the intersection with the window edge x=0
  Yi0 :=Ydeb+T*Xdeb/M;
  // Calculation of Y coordinates of the intersection with the window edge x=Lf
  YiL :=Ydeb+(T/M)*(Xdeb-Lf);
  // Calculation of X coordinates of the intersection with the window edge y=0
  Xi0 :=Xdeb+M*Ydeb/T;
  // Calculation of X coordinates of the intersection with the window edge y=Hf
  XiH :=Xdeb+(M/T)*Ha;

  // Cases 4 &amp; 7 depending if 0 belongs to the glazing or not
    Inclus :=BuildSysPro.BoundaryConditions.Solar.SolarMasks.PointOnSurface(
      Lf=Lf,
      Hf=Hf,
      X0=X0,
      Y0=Y0);

  if (Inclus == true) then
    continue := false;
    // Case 4 or 7
    if ((XiH>=0) and (XiH<=Lf)) then
      Cas := 4;
    else
      Cas := 7;
    end if;
  end if;
end if;

// Case 1 discrimination
if (continue == true) then
   X2iH := if DebordGauche then (M/T)*Ha-Dd else (M/T)*Ha+Dg+Lf;
   if ((T<=Ha) or ((not DebordGauche) and X2iH >=Lf and XiH >=Lf) or (DebordGauche and X2iH <=0 and XiH <=0)) then
     continue := false;
     Cas := 1;
   end if;
end if;

// Cases 2,3,5,6,8,9
if (continue == true) then
  if (XiH >=0 and XiH <=Lf) then
    //Case 5 or 6
    if (Xi0 >=0 and Xi0 <=Lf) then
      Cas := 5;
    else
      Cas := 6;
    end if;
  else
    //Cases 2,3,8,9
    if (Yi0 >=0 and Yi0 <=Hf) and (YiL >=0 and YiL <=Hf) and ((DebordGauche and X0<=0) or ((not DebordGauche) and X0 >=Lf)) then
      Cas := 9;
    else
      //Cases 2,3,8
      if (Y0 >=0 and Y0 <=Hf) then
        Cas := 3;
      else
        if (Xi0 >=0 and Xi0 <=Lf) then
          Cas := 8;
        else
          Cas := 2;
        end if;
      end if;
    end if;
  end if;
end if;

////// Calculation of shadow area (A0) and sunny area (Asol)
M := abs(M); // For following areas formulas the absolute value of M is taken
if Cas == 1 then
  A0 := 0;
elseif Cas == 2 then
  A0 := Hf*Lf;
elseif Cas == 3 then
  A0 := Lf*(T-Ha);
elseif Cas == 4 then
  A0 := (T-Ha)*(Lf+b-M*0.5*(1+Ha/T));
elseif Cas == 5 then
  A0 := Hf*(Lf+b-(Ha+0.5*Hf)*M/T);
elseif Cas == 6 then
 A0 := ((((Lf+b)*T/M)-Ha)^2)*0.5*M/T;
elseif Cas == 7 then
  A0 := (T-Ha)*Lf-((M-b)^2)*T*0.5/M;
elseif Cas == 8 then
  A0 := Hf*Lf-0.5*(T/M)*(M*(Ha+Hf)/T-b)^2;
else //Cas 9
  A0 := Lf*((b+0.5*Lf)*T/M-Ha);
end if;

Asol := Hf*Lf - A0

  ;
end HorizontalMask;

within BuildSysPro.BoundaryConditions.Solar.SolarMasks;
model Masks
  "Base model - Solar incident irradiance and illuminance on a surface considering solar mask"

// Paramètres propres au masque
parameter Boolean useEclairement=false
  ;
  parameter Modelica.Units.NonSI.Angle_deg azimut=0
    "Surface azimuth (Orientation relative to the south) - S=0°, E=-90°, W=90°, N=180°"
    ;
parameter Integer TypeMasque ;
  parameter Modelica.Units.SI.Distance Av=0.5 "Overhang"
    ;
  parameter Modelica.Units.SI.Distance Ha=0.3
    "Distance between the overhang and the top of the surface (window)"
    ;
  parameter Modelica.Units.SI.Distance Lf=1 "Surface (window) width"
    ;
  parameter Modelica.Units.SI.Distance Hf=1 "Surface (window) height"
    ;
  parameter Modelica.Units.SI.Distance Dd=0.5
    "Lateral overhang (right hand side)"
    ;
  parameter Modelica.Units.SI.Distance Dg=0.5
    "Lateral overhang (left hand side)"
    ;

parameter Boolean MasqueLointain=false
;
  parameter Modelica.Units.SI.Distance dE=5
    "Distance from the surface (window) to the distant masks"
    ;
  parameter Modelica.Units.SI.Distance hpE=2 "Height of the distant mask"
    ;

  Modelica.Units.NonSI.Angle_deg AzimutSoleil "Solar azimuth angle";
  Modelica.Units.NonSI.Angle_deg HauteurSoleil "Solar elevation angle";
  Modelica.Units.SI.HeatFlux DiffusSol
    "Share of the diffuse incident radiation from the reflection on the ground";
output Real FacMasqueDir
    "Close mask factor for direct fluxes (these are the same for thermal flux and luminous flux)";
output Real FacMasqueDif
    "Close mask factor for diffuse fluxes (these are the same for thermal flux and luminous flux)";
output Real FE_dir
    "Direct solar radiation attenuation factor due to a vertical distance mask";

  Modelica.Units.SI.Area A0 "Sunny window surface";

Real pi=Modelica.Constants.pi;
  BuildSysPro.BoundaryConditions.Solar.Interfaces.SolarFluxOutput FluxMasques[3]
    "Solar irradiation for the surface considering the shading effects 1-Diffuse, 2- Direct and 3-Cosi"
    ;
  BuildSysPro.BoundaryConditions.Solar.Interfaces.SolarFluxInput FluxIncExt[3]
    "Incident irradiance 1-Diffuse, 2- Direct and 3-Cosi" ;
  Modelica.Blocks.Interfaces.RealInput AzHSol[3]
    "Irradiation data: 1-Solar azimuth angle 2-Solar elevation angle 3-Incident flux from ground"    ;
  Modelica.Blocks.Interfaces.RealInput Ecl[3] if useEclairement
    "Natural incident illuminance -direct -diffuse -reflected [lumen]"                                  ;
  Modelica.Blocks.Interfaces.RealOutput EclMasques[3] if useEclairement
    "Natural illuminance considering shading effects -direct -diffuse -reflected [lumen]"
    ;
  Modelica.Blocks.Sources.RealExpression CalculEclMasques[3](y={Ecl[1]*
        FacMasqueDir*FE_dir,Ecl[2]*FacMasqueDif,Ecl[3]})              if useEclairement
    "Lighting illuminations with close mask vector: direct, diffuse, reflected"
    ;
algorithm

AzimutSoleil:=AzHSol[1];
HauteurSoleil:=AzHSol[2];
DiffusSol:=AzHSol[3];

if TypeMasque==0 then

  //Full mask
  if noEvent(abs(azimut-AzimutSoleil)>=90) or (noEvent(HauteurSoleil<=0)) then
      A0:=0;
  else
      A0 :=BuildSysPro.BoundaryConditions.Solar.SolarMasks.FullMask(
        Av=Av,
        Ha=Ha,
        Lf=Lf,
        Hf=Hf,
        Dd=Dd,
        Dg=Dg,
        AzimutSoleil=AzimutSoleil,
        HauteurSoleil=HauteurSoleil,
        azimut=azimut);
      FacMasqueDir:= A0/(Lf*Hf);
  end if;
  FacMasqueDif:=(Dd+Lf+Dg)*(Ha+Hf)/((Dd+Lf+Dg)*(Ha+Hf)+(Dd+Lf+Dg)*Av+2*(Hf+Ha)*Av);
else if TypeMasque==1 then
  //Horizontal mask
  if noEvent(abs(azimut-AzimutSoleil)>=90) or (noEvent(HauteurSoleil<=0)) then
      A0:=0;
  else
      A0 :=BuildSysPro.BoundaryConditions.Solar.SolarMasks.HorizontalMask(
          Av=Av,
          Ha=Ha,
          Lf=Lf,
          Hf=Hf,
          Dd=Dd,
          Dg=Dg,
          AzimutSoleil=AzimutSoleil,
          HauteurSoleil=HauteurSoleil,
          azimut=azimut);
      FacMasqueDir:= A0/(Lf*Hf);
     //FacMasqueDir:= min(max(0,1-(max(0,Av*tan(HauteurSoleil*Convert)/cos((AzimutSoleil-azimut)*Convert))-Ha)/Hf),1); //Formule RT2012
  end if;
  FacMasqueDif:=((Dd+Lf+Dg)*(Ha+Hf)+2*Av*(Ha+Hf))/((Dd+Lf+Dg)*(Ha+Hf)+(Dd+Lf+Dg)*Av+2*(Hf+Ha)*Av);
  //FacMasqueDif:=(2/Modelica.Constants.pi)*atan((Ha+Hf/2)/Av); //Formule RT2012
else
  FacMasqueDir:=1;
  FacMasqueDif:=1;
end if;
end if;

//Distant mask defined by a vertical plan
if MasqueLointain==true and cos((AzimutSoleil-azimut)*pi/180)>10^(-5) then //if distant mask and sun entry in the considered plan
       if hpE>0 then
         if (dE*tan(HauteurSoleil*pi/180)/cos((AzimutSoleil-azimut)*pi/180))>hpE then FE_dir:=1;else FE_dir:=0;end if;
    else FE_dir:=1;
    end if;
else FE_dir:=1;
       end if;

equation
  //Vector FLUX on a glazing with close mask / output: diffuse, direct, cosi
 FluxMasques[1] =((FluxIncExt[1] - DiffusSol)*FacMasqueDif + DiffusSol)*FE_dir;
 FluxMasques[2] =FacMasqueDir*FluxIncExt[2];
 FluxMasques[3] =FluxIncExt[3];

  if useEclairement then
    connect(CalculEclMasques.y, EclMasques) ;
  end if
  ;
end Masks;

within BuildSysPro.BoundaryConditions.Solar.SolarMasks;
function PointOnSurface "Function to determine if a point belongs to a surface"

  input Modelica.Units.SI.Distance Lf "Surface width";
  input Modelica.Units.SI.Distance Hf "Surface height";
input Real X0 "X coordinate of the point";
input Real Y0 "Y coordinate of the point";

output Boolean Inclus "=true if the point belongs to surface";

algorithm
if (X0 < 0) or (X0 > Lf) then
  Inclus := false;
else
  if (Y0 < 0) or (Y0 > Hf) then
    Inclus :=false;
  else
    Inclus := true;
  end if;
end if

  ;
end PointOnSurface;

within BuildSysPro.BoundaryConditions.Solar.Utilities;
function CosDirSunVector "Sun's direction cosines"
  input Real t0=0 "Time in seconds at t=0";
  input Modelica.Units.SI.Time t "Universal time in seconds";
  input Modelica.Units.NonSI.Angle_deg longitude "Longitude in degrees";
  input Modelica.Units.NonSI.Angle_deg latitude "Latitude in degrees";
  output Real CosDir[3] "Sun's direction cosine";
protected
  constant Real pi=Modelica.Constants.pi;
  constant Real d2r=pi/180;
  constant Real w=2*pi/365.25;
  Real d=mod((t+t0)/86400,365)+1;
//  Real d=mod(integer(t+t0)/86400,365);
  Real wd1=w*d;
  Real wd2=2*wd1;
  Real wd3=3*wd1;
  // Sun declination in radians
  Real delta= (0.302 - 22.93*cos(wd1) - 0.229*cos(wd2) - 0.243*cos(wd3)
                + 3.851*sin(wd1) + 0.002*sin(wd2) - 0.055*sin(wd3))*d2r;
  // Equation of time in hours
  Real ET = 0.128*sin(w*(d-2)) + 0.164*sin(2*w*(d+10));
  // Real solar time in radians
  Real TSV= (t+t0)/3600+longitude/15-ET;
  // Hour angle
  Real AH= (TSV-12)*pi/12;
  // Latitude in radians
  Real phi=latitude*d2r;
algorithm
  CosDir[1]:=sin(phi)*sin(delta)+cos(phi)*cos(delta)*cos(AH) "=CosV=SinH";
  CosDir[2]:=cos(delta)*sin(AH) "=CosW";
  CosDir[3]:=cos(delta)*sin(phi)*cos(AH)-sin(delta)*cos(phi) "=CosS"
  ;
end CosDirSunVector;

within BuildSysPro.BoundaryConditions.Solar.Utilities;
function CosDirSunVectorHeightAz
  "Compute the sun's direction cosine, the solar elevation and azimuth angle"

  input Real t0=0 "Time in seconds at t=0";
  input Modelica.Units.SI.Time t "Universal time in seconds";
  input Modelica.Units.NonSI.Angle_deg longitude "Longitude in degrees";
  input Modelica.Units.NonSI.Angle_deg latitude "Latitude in degrees";
  output Real CosDir[3] "Sun's direction cosine";
  output Real Az "Solar azimuth angle";
  output Real Haut "Solar elevation angle";
protected
  constant Real pi=Modelica.Constants.pi;
  constant Real d2r=pi/180;
  constant Real w=2*pi/365.25;
  Real d=mod((t+t0)/86400,365)+1;
//  Real d=mod(integer(t+t0)/86400,365);
  Real wd1=w*d;
  Real wd2=2*wd1;
  Real wd3=3*wd1;
  // Sun's declination in radians
  Real delta= (0.302 - 22.93*cos(wd1) - 0.229*cos(wd2) - 0.243*cos(wd3)
                + 3.851*sin(wd1) + 0.002*sin(wd2) - 0.055*sin(wd3))*d2r;
  // Equation of time in hours
  Real ET = 0.128*sin(w*(d-2)) + 0.164*sin(2*w*(d+10));
  // Real Solar Time in hours
  Real TSV= (t+t0)/3600+longitude/15-ET;
  // Hour Angle
  Real AH= (TSV-12)*pi/12;
  // Latitude in radians
  Real phi=latitude*d2r;
  Real cosh;
  Real sinAz;
  Real cosAz;
algorithm
  CosDir[1]:=sin(phi)*sin(delta)+cos(phi)*cos(delta)*cos(AH) "=CosV=SinH";
  CosDir[2]:=cos(delta)*sin(AH) "=CosW";
  CosDir[3]:=cos(delta)*sin(phi)*cos(AH)-sin(delta)*cos(phi) "=CosS";
  cosh:=if CosDir[1] > 0 then sqrt(1 - CosDir[1]*CosDir[1]) else 1;
  sinAz:=CosDir[2]/cosh;
  cosAz:=CosDir[3]/cosh;
  Haut:=asin(CosDir[1])/d2r;
  if sinAz>=0 then
      Az:=acos(cosAz*0.999)/d2r;
  else
      Az:=-acos(cosAz*0.999)/d2r;
  end if
  ;
end CosDirSunVectorHeightAz;

within BuildSysPro.BoundaryConditions.Solar.Utilities;
function CosI "Cosine of the angle of incidence"
  input Modelica.Units.NonSI.Angle_deg azimut "Surface azimuth in degree";
  input Modelica.Units.NonSI.Angle_deg incl "Surface tilt in degree";
  input Real CosDir[3] "Sun's direction cosines";
  output Real cosi "Cosine of the angle of incidence";
protected
  constant Real d2r=Modelica.Constants.pi/180;
  Real s=incl*d2r "Tilt";
  Real g=azimut*d2r "Orientation";
  // Direction cosines of the plane
  Real l=cos(s);
  Real m=sin(s)*sin(g);
  Real n=sin(s)*cos(g);
algorithm
  //cosi:=max(0,l*CosDir[1]+m*CosDir[2]+n*CosDir[3]);
  cosi:=max(0,{l,m,n}*CosDir)

  ;
end CosI;

within BuildSysPro.BoundaryConditions.Solar.Utilities;
function HourAngle "Hour Angle (HA)"
  input Modelica.Units.SI.Time t0=0 "Time in seconds at t=0";
  input Modelica.Units.SI.Time t "Universal time in seconds";
  input Modelica.Units.NonSI.Angle_deg longitude "longitude in degrees";
  output Real AH "Hour Angle in radians: HA = 15*TSV*pi/180";
protected
  Real TSV=BuildSysPro.Utilities.Time.ApparentSolarTime(
      t0=t0,
      t=t,
      longitude=longitude);
algorithm
  AH:=(TSV-12)*Modelica.Constants.pi/12
  ;
end HourAngle;

within BuildSysPro.BoundaryConditions.Solar.Utilities;
function SineH "Sine of the solar elevation angle"
  input Real t0=0 "Time in seconds at t=0";
  input Modelica.Units.SI.Time t "Universal time in seconds";
  input Modelica.Units.NonSI.Angle_deg longitude "Longitude in degrees";
  input Modelica.Units.NonSI.Angle_deg latitude "Latitude in degrees";
  output Real sin_h "Sine of the solar elevation angle";
protected
  constant Real d2r=Modelica.Constants.pi/180;
  Real phi=latitude*d2r;
  Real AH=HourAngle(
      t0=t0,
      t=t,
      longitude=longitude);
  Real delta=SunDeclination(t0=t0, t=t);
algorithm
  sin_h:=sin(phi)*sin(delta)+cos(phi)*cos(delta)*cos(AH);
  sin_h:=max(0, sin_h)
  ;
end SineH;

within BuildSysPro.BoundaryConditions.Solar.Utilities;
function SunDeclination "Sun declination"
  input Real t0=0 "Time in seconds at t=0";
  input Modelica.Units.SI.Time t "Time in seconds";
  output Modelica.Units.SI.Angle delta "Sun's declination (angle in radians)";
protected
  constant Real pi=Modelica.Constants.pi;
  Real wd1=(2*pi/365.25)*mod((t+t0)/86400,365);
  Real wd2=2*wd1;
  Real wd3=3*wd1;
algorithm
  delta:=(0.302 - 22.93*cos(wd1) - 0.229*cos(wd2) - 0.243*cos(wd3)
                + 3.851*sin(wd1) + 0.002*sin(wd2) - 0.055*sin(wd3))*pi/180
  ;
end SunDeclination;

within BuildSysPro.BoundaryConditions.Solar.Utilities;
function TimeEquation "Equation of time"
  input Real t0=0 "Time in seconds at t=0";
  input Modelica.Units.SI.Time t "Time in seconds";
  output Real ET "Equation of time (in hour)";
protected
  Real w=2*Modelica.Constants.pi/365.25;
  Real d=mod((t+t0)/86400,365)+1;
algorithm
  ET:= 0.128*sin(w*(d-2)) + 0.164*sin(2*w*(d+10));

within BuildSysPro.BoundaryConditions.Solar.Utilities;
function TimeEquationClim2000 "Equation of time"
  input Real t0=0 "Time in seconds at t=0";
  input Modelica.Units.SI.Time t "Time in seconds";
  output Real ET "Equation of time (in hour)";
protected
  constant Real pi=Modelica.Constants.pi;
  Real wd1=(2*pi/365.25)*mod((t+t0)/86400,365);
  Real wd2=2*wd1;
  Real wd3=3*wd1;
algorithm
  ET:=(0.0002 - 0.4197*cos(wd1) + 3.2265*cos(wd2) + 0.0903*cos(wd3)
              + 7.3509*sin(wd1) + 9.3912*sin(wd2) + 0.3361*sin(wd3))/60.0
  ;
end TimeEquationClim2000;

within BuildSysPro.BoundaryConditions.Weather;
model AnalyticIrradiance "Irradiance scenario"

  Modelica.Blocks.Interfaces.RealOutput G
    "Global irradiance on south facing surface"                                   ;

parameter Real midi=12 "Hour of solar noon [h]";
parameter Real DureeJour=10 "Day duration [h]";
parameter Real H=5000 "Solar energy over the day [Wh/m²]";
parameter Real Gmax=1000 "Maximum irradiance (at solar noon)";

protected
  Real t "Current time [h] and equal to 0 at solar noon";
parameter Real t0 = 0.5*DureeJour "Time of sunset, with the convention on t";
parameter Real s=(Modelica.Constants.pi*H/(4*t0*Gmax)-1)/(1-Modelica.Constants.pi/4);

equation
t= mod(time/3600,24)- midi;
G=  if t>-t0 and t<t0 then max(0,Gmax*cos(Modelica.Constants.pi*t/(2*t0)) * (1 + s*(1-cos(Modelica.Constants.pi*t/(2*t0))))) else
                                                                                              0

  ;
end AnalyticIrradiance;

within BuildSysPro.BoundaryConditions.Weather;
model AnalyticText "External temperature scenario"

  Modelica.Blocks.Interfaces.RealOutput T_ext "Analytic external temperature"
    ;

parameter Real Htmax=14 "Hour of maximum temperature [h]";
parameter Real midi=12 "Hour of solar noon [h]";
parameter Real Tmin=15 "Minimum temperature [°C]";
parameter Real Tmax=30 "Maximum temperature [°C]";
parameter Real DureeJour = 10 "Day duration [h]";

protected
Real t "Current time [h] and equal to 0 at solar noon";
parameter Real t0 = 0.5*DureeJour "Time of sunset, with the convention on t";

equation
t=  time/3600 - midi;
  T_ext = Tmax + (Tmin - Tmax)*(cos(Modelica.Constants.pi*(t - Htmax + midi)/(2
    *t0)) - 1)/(cos(Modelica.Constants.pi*(t0 + Htmax + midi)/(2*t0)) - 1)
  ;
end AnalyticText;

within BuildSysPro.BoundaryConditions.Weather;
model ColdWaterTempReader "Cold water temperature reader"

  parameter String pth=Modelica.Utilities.Files.loadResource("modelica://BuildSysPro/Resources/Donnees/Meteos/RT2012/eau_froide_H1a.txt")
    "Path to the meteo file" ;

  BaseClasses.HeatTransfer.Interfaces.HeatPort_b T_cold
    "Cold water temperature [K]" ;
  BaseClasses.HeatTransfer.Sources.PrescribedTemperature prescribedTef
    ;
  Modelica.Thermal.HeatTransfer.Celsius.ToKelvin toKelvinTef
    ;
  Modelica.Blocks.Tables.CombiTable1Ds combiTimeTable(
    tableOnFile=true,
    tableName="data",
    fileName=pth,
    smoothness=Modelica.Blocks.Types.Smoothness.ContinuousDerivative,
    columns={2}) ;
public
  Modelica.Blocks.Sources.RealExpression Temps(y=mod(time, 31536000))
    ;
equation
  connect(prescribedTef.port, T_cold) ;
  connect(toKelvinTef.Kelvin, prescribedTef.T) ;
  connect(Temps.y, combiTimeTable.u) ;
  connect(combiTimeTable.y[1], toKelvinTef.Celsius) 
  ;
end ColdWaterTempReader;

within BuildSysPro.BoundaryConditions.Weather;
block CombiTable1Ds_ForStepMeteo
  "Table look-up in one dimension (matrix/file) with one input and n outputs"
  extends Modelica.Blocks.Interfaces.SIMO(final nout=size(columns, 1));
  parameter Boolean tableOnFile=false
    "= true, if table is defined on file or in function usertab"
    ;
  parameter Real table[:, :] = fill(0.0, 0, 2)
    "Table matrix (grid = first column; e.g., table=[0,2])"
    ;
  parameter String tableName="NoName"
    "Table name on file or in function usertab (see docu)"
    ;
  parameter String fileName="NoName" "File where matrix is stored"
    ;
  parameter Boolean verboseRead=true
    "= true, if info message that file is loading is to be printed"
    ;
  parameter Integer columns[:]=2:size(table, 2)
    "Columns of table to be interpolated"
    ;
  parameter Modelica.Blocks.Types.Smoothness smoothness=Modelica.Blocks.Types.Smoothness.LinearSegments
    "Smoothness of table interpolation"
    ;

  parameter Real delta_t=3600 "Constant time step of the file in [s]";
  parameter Integer option[nout]=fill(1,nout)
    "=0 if piecewise constant function";
  Real u1=integer(u/delta_t)*delta_t+delta_t/2;

protected
  Modelica.Blocks.Types.ExternalCombiTable1D tableID=
      Modelica.Blocks.Types.ExternalCombiTable1D(
        if tableOnFile then tableName else "NoName",
        if tableOnFile and fileName <> "NoName" and not Modelica.Utilities.Strings.isEmpty(fileName) then fileName else "NoName",
        table,
        columns,
        smoothness) "External table object";
  parameter Real tableOnFileRead(fixed=false)
    "= 1, if table was successfully read from file";

  function readTableData "Read table data from ASCII text or MATLAB MAT-file"
    extends Modelica.Icons.Function;
    input Modelica.Blocks.Types.ExternalCombiTable1D tableID;
    input Boolean forceRead = false
      "= true: Force reading of table data; = false: Only read, if not yet read.";
    input Boolean verboseRead
      "= true: Print info message; = false: No info message";
    output Real readSuccess "Table read success";
    external"C" readSuccess = ModelicaStandardTables_CombiTable1D_read(tableID, forceRead, verboseRead)
      ;
  end readTableData;

  function getTableValue "Interpolate 1-dim. table defined by matrix"
    extends Modelica.Icons.Function;
    input Modelica.Blocks.Types.ExternalCombiTable1D tableID;
    input Integer icol;
    input Real u;
    input Real tableAvailable
      "Dummy input to ensure correct sorting of function calls";
    output Real y;
    external"C" y = ModelicaStandardTables_CombiTable1D_getValue(tableID, icol, u)

    ;
  end getTableValue;

  function getTableValueNoDer
    "Interpolate 1-dim. table defined by matrix (but do not provide a derivative function)"
    extends Modelica.Icons.Function;
    input Modelica.Blocks.Types.ExternalCombiTable1D tableID;
    input Integer icol;
    input Real u;
    input Real tableAvailable
      "Dummy input to ensure correct sorting of function calls";
    output Real y;
    external"C" y = ModelicaStandardTables_CombiTable1D_getValue(tableID, icol, u)
      ;
  end getTableValueNoDer;

  function getDerTableValue
    "Derivative of interpolated 1-dim. table defined by matrix"
    extends Modelica.Icons.Function;
    input Modelica.Blocks.Types.ExternalCombiTable1D tableID;
    input Integer icol;
    input Real u;
    input Real tableAvailable
      "Dummy input to ensure correct sorting of function calls";
    input Real der_u;
    output Real der_y;
    external"C" der_y = ModelicaStandardTables_CombiTable1D_getDerValue(tableID, icol, u, der_u)
      ;
  end getDerTableValue;

initial algorithm
  if tableOnFile then
    tableOnFileRead := readTableData(tableID, false, verboseRead);
  else
    tableOnFileRead := 1.;
  end if;
equation
  if tableOnFile then
    assert(tableName <> "NoName",
      "tableOnFile = true and no table name given");
  else
    assert(size(table, 1) > 0 and size(table, 2) > 0,
      "tableOnFile = false and parameter table is an empty matrix");
  end if;
  if smoothness == Modelica.Blocks.Types.Smoothness.ConstantSegments then
    for i in 1:nout loop
      y[i] = getTableValueNoDer(tableID, i, u, tableOnFileRead);
    end for;
  else
    for i in 1:nout loop
      //y[i] = getTableValue(tableID, i, u, tableOnFileRead);
      y[i] = getTableValue(tableID, i, if option[i]==0 then u1 else u, tableOnFileRead);
    end for;
  end if
  ;
end CombiTable1Ds_ForStepMeteo;

within BuildSysPro.BoundaryConditions.Weather;
model ZoneWind "Wind computation for a zone model"

parameter Boolean ChoixAzimuth=false
    "Choice to enter either a common azimuth correction or each azimuth values"
    ;
parameter Real beta=0
    "Vertical walls azimuth correction in such a way that azimuth=beta+azimuth, (beta=0 : {N=180,S=0,E=-90,O=90})"
    ;
parameter Real azim[4]={beta+180,beta,beta-90,beta+90}
    "Output walls azimuth, by default 1-North, 2-South, 3-East, 4-West"
      ;
  parameter Real incl[4]={90,90,90,90}
    "Walls tilt, by default 1-North, 2-South, 3-East, 4-West";

Modelica.Blocks.Interfaces.RealOutput VENTNord
    "Wind speed on the northern-facing wall [m/s]" ;

Modelica.Blocks.Interfaces.RealOutput VENTSud
    "Wind speed on the south-facing wall [m/s]" ;
Modelica.Blocks.Interfaces.RealOutput VENTEst
    "Wind speed on the east-facing wall [m/s]"  ;
Modelica.Blocks.Interfaces.RealOutput VENTOuest
    "Wind speed on the west-facing wall [m/s]"  ;

Modelica.Blocks.Interfaces.RealInput V[2]
    "1- wind speed [m/s] 2- wind direction (0- North, 90 - East, 180 - South, 270 - West)"
    ;

protected
  parameter Real azim_in[4]=if ChoixAzimuth then azim[1:4] else {beta+180,beta,beta-90,beta+90};
  constant Real d2r=Modelica.Constants.pi/180;

algorithm
//  Calculation of walls normal wind speeds
VENTNord:=max(0,cos((V[2]+180-azim_in[1])*d2r))*V[1];
VENTSud:=max(0,cos((V[2]+180-azim_in[2])*d2r))*V[1];
VENTEst:=max(0,cos((V[2]+180-azim_in[3])*d2r))*V[1];
VENTOuest:=max(0,cos((V[2]+180-azim_in[4])*d2r))*V[1]
;
end ZoneWind;

within BuildSysPro.BoundaryConditions.Weather.Functions;
function CalculPs "Compute the saturation pressure"
  output Real ps;
  input Real T;

protected
  Real Tmin=273.16;
  Real Tmax=647.3;
  Real tk;
  Real a;
  Real b;
  Real c;
  Real d;

algorithm
  tk:=min(Tmax,max(Tmin,T));
  if tk<=273.15 then
        a :=-6086.67457;
        b :=0.258146988;
        c :=0;
        d :=27.2497986;
  elseif (tk <= 333.15) then

          a :=-6722.94637;
        b :=-4.77551358;
        c :=0;
        d :=57.8181266;
  else  a :=-7797.09834;
        b :=-11.2831932;
        c :=0.00993664096;
        d :=95.5324251;
  end if;
  ps:=exp(a/tk + b*log(tk) + c*tk + d)

  ;
end CalculPs;

within BuildSysPro.BoundaryConditions.Weather.Functions;
function CalculTsky_withoutRH
  "Compute the sky temperature not knowing the relative humidity"
  input Modelica.Units.SI.Time t "Time";
  input Real T_seche "Dry bulb temperature [K]";
  input Real G[10] "Solar information vector";
  output Real T_ciel "Sky tempereture [K]";

protected
  constant Real d2r=Modelica.Constants.pi/180;
  constant Modelica.Units.SI.HeatFlux Isc=1367 "constante solaire";
  Modelica.Units.SI.HeatFlux I0
    "éclairement extraterrestre sur une surface horizontale (hors atmosphère)";
  Real Kt "clearness index";
  Real sin_h "sinus de la hauteur du soleil";

algorithm
  sin_h := G[6];
  I0 :=max(0, Isc*(1 + 0.033*cos((360*(floor((t + G[5])/86400) + 1)/365)*d2r))*
    sin_h);
  Kt:=if noEvent(sin_h>0.02 and I0>0) then (if noEvent(G[4]<I0) then G[4]/I0 else 1) else 0;
  T_ciel:=-29-19.9*Kt+1.09*T_seche

  ;
end CalculTsky_withoutRH;

within BuildSysPro.BoundaryConditions.Weather.Functions;
function CalculTsky_withRH
  "Compute the sky temperature knowing the relative humidity"
  input Modelica.Units.SI.Time t "Time";
  input Real T_seche "Dry  bulb temperature [K]";
  input Real G[10] "Solar information vector";
  input Real Pvap "Water vapor pressure [Pa]";
  output Real T_ciel "Sky tempereture [K]";

protected
  constant Real d2r=Modelica.Constants.pi/180;
  constant Modelica.Units.SI.HeatFlux Isc=1367 "Solar constant";
  Modelica.Units.SI.HeatFlux I0
    "Extraterrestrial irradiance on a horizontal surface (outside the atmosphere)";

  Real Kt "Clearness index";
  Real sin_h "Sine of the sun's elevation";

algorithm
  sin_h := G[6];
  I0 :=max(0, Isc*(1 + 0.033*cos((360*(floor((t + G[5])/86400) + 1)/365)*d2r))*
    sin_h);
  Kt:=if noEvent(sin_h>0.02 and I0>0) then (if noEvent(G[4]<I0) then G[4]/I0 else 1) else 0;
  T_ciel:=94+12.6*log(Pvap)-13*Kt+0.341*T_seche

  ;
end CalculTsky_withRH;

