within BuildSysPro.Building.BuildingEnvelope.Functions;
function CalculAlphaTauDoubleGlazing
  "Calculation of absorption and transmission coefficients of a double glazing window"

  input Modelica.Units.SI.CoefficientOfHeatTransfer Uw
    "Heat transfert coefficient of the window";
  input Real g "Solar factor of the window [between 0 and 1]";
  input Real tau0 "Coefficient of energy transmission [between 0 and 1]";
  input Modelica.Units.SI.CoefficientOfHeatTransfer Hext=21
    "Global surface exchange coefficient on the outer face of the window";
  input Modelica.Units.SI.CoefficientOfHeatTransfer Hint=8.29
    "Global surface exchange coefficient on the inner face of the window";
  output Real alpha_dir "Direct absorption coefficient of the window";
  output Real alpha_dif "Diffuse absorption coefficient of the window";
  output Real tau_dir "Direct transmission coefficient of the window";
  output Real tau_dif "Diffuse transmission coefficient of the window";

protected
  Real rho_dir;
  Real rho_dif;
  Real alpha_30;
  Real alpha_60;
  Real tau_30;
  Real tau_60;
  Real a1;
  Real a2;
  Real a3;
  Real b1;
  Real b2;
  Real b3;

algorithm
  //Direct coefficients (standard EN 410)
  //First glazing
  alpha_dir := (g-tau0)/(1+Uw*((1/Hext)-(1/Hint)));
  tau_dir := ((2*tau0*(1-alpha_dir))+sqrt((2*tau0*(1-alpha_dir))^2+4*(1+tau0)*tau0*alpha_dir*(2-alpha_dir)))/(2*(1+tau0));
  rho_dir := 1-alpha_dir-tau_dir;
  //Global glazing
  tau_dir := (tau_dir)^2/(1-(rho_dir)^2);
  rho_dir := rho_dir*(1+tau_dir);
  alpha_dir := 1-tau_dir-rho_dir;

  //Diffuse coefficients (method Th-S from RT)
  alpha_30 := -8.5884e-4+1.0869*alpha_dir-6.1151e-2*(alpha_dir^2);
  alpha_60 := -1.7566e-3+1.2352*alpha_dir-2.7231e-1*(alpha_dir^2);
  tau_30 := -7.068e-4+9.3967e-1*tau_dir+7.0476e-2*(tau_dir^2);
  tau_60 := -1.6265e-2+6.9767e-1*tau_dir+2.4509e-1*(tau_dir^2);
  a1 := 6.4646*alpha_dir-11.7745*alpha_30+9.4645*alpha_60;
  a2 := -20.394*alpha_dir+35.3234*alpha_30-20.394*alpha_60;
  a3 := 14.9294*alpha_dir-23.5489*alpha_30+10.9295*alpha_60;
  b1 := 6.4646*tau_dir-11.7745*tau_30+9.4645*tau_60;
  b2 := -20.394*tau_dir+35.3234*tau_30-20.394*tau_60;
  b3 := 14.9294*tau_dir-23.5489*tau_30+10.9295*tau_60;
  alpha_dif := (a1/3+a2/4+a3/5)*2;
  tau_dif := (b1/3+b2/4+b3/5)*2

  ;
end CalculAlphaTauDoubleGlazing;

within BuildSysPro.Building.BuildingEnvelope.Functions;
function U_Wall
  "U-value calculated from the wall composition (GenericWall record)"

  import      Modelica.Units.SI;

  input BuildSysPro.Utilities.Records.GenericWall wall_record
    "Wall composition record";
  input SI.SurfaceCoefficientOfHeatTransfer hs_int = 7.69
    "Internal surface coefficient of heat transfer";
  input SI.SurfaceCoefficientOfHeatTransfer hs_ext = 25
    "External surface coefficient of heat transfer";

  output SI.SurfaceCoefficientOfHeatTransfer U_value
    "U_value of the wall";

protected
  SI.ThermalInsulance R_h_surf
    "Thermal resistance of the internal + external boundary layers";
  SI.ThermalInsulance R_without_h_surf
    "Thermal resistance without the bounrady layers";
  SI.ThermalInsulance R_total
    "Total thermal resistance of the wall";

algorithm

  R_without_h_surf :=0;
  for i in 1:wall_record.n loop
    R_without_h_surf := R_without_h_surf + wall_record.e[i]/wall_record.mat[i].lambda;
  end for;

  R_h_surf := 1/hs_int + 1/hs_ext;
  R_total := R_h_surf + R_without_h_surf;

  U_value := 1/R_total

      ;
end U_Wall;

within BuildSysPro.Building.BuildingEnvelope.HeatTransfer;
model Basement "Buried basement"

  parameter Real Hauteur=2.2 "Height";
  parameter Real Longueur=10 "Length";
  parameter Real Largeur=5 "Width";
  parameter Real Sgarage=2*3 "Garage surface";
  parameter Real hc_lat=9 "Side wall convective coefficient";
  parameter Real hc_plancher=5 "Floor convective coefficient";
  parameter Real Ugarage=1/16+1/9 "Garage transmission coefficient";
  parameter Real TauRVT=0.2 "Air renewal rate";
  parameter BuildSysPro.Utilities.Records.GenericSolid mat_Sol
    ;
  parameter BuildSysPro.Utilities.Records.GenericSolid mat_Lat
    ;
  parameter BuildSysPro.Utilities.Records.GenericSolid mat_Pla
    ;
  parameter Modelica.Units.SI.Temperature Tinit=281.15;
protected
  final parameter Real Perimetre=2*(Longueur*Largeur);
  final parameter Real Splancher=Longueur*Largeur;
  final parameter Real Slaterale=Perimetre*Hauteur-Sgarage;
  final parameter Real Volume=Hauteur*Splancher;

public
  Modelica.Thermal.HeatTransfer.Components.HeatCapacitor NoeudAir(
    C=1.2*720*Volume,
    der_T(fixed=true),
    T(fixed=false, start=281.15)) ;
  Modelica.Thermal.HeatTransfer.Components.ThermalConductor Gplancher(G=hc_plancher*Splancher)
    ;
  Modelica.Thermal.HeatTransfer.Components.ThermalConductor Glateral(G=hc_lat*Slaterale)
    ;
  Modelica.Thermal.HeatTransfer.Sources.PrescribedTemperature TsolLat
                           ;
  Modelica.Thermal.HeatTransfer.Sources.PrescribedTemperature TsolPlancher
                           ;
  Modelica.Thermal.HeatTransfer.Components.ThermalConductor Rvt(G=0.34*TauRVT*Volume)
    ;
  Modelica.Thermal.HeatTransfer.Components.ThermalConductor PorteGarage(G=Ugarage*Sgarage) ;
  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a T_ext
    "Outdoor temperature" ;
  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a T_int
    "Indoor temperature" ;
  BaseClasses.HeatTransfer.Components.HomogeneousNLayersWall
    paroiNCouchesHomogenes3(
    n=1,
    mat={BuildSysPro.Utilities.Data.Solids.Concrete()},
    m={180},
    e={9}) ;
  Modelica.Thermal.HeatTransfer.Sensors.TemperatureSensor temperatureSensor
    ;
  Modelica.Thermal.HeatTransfer.Sources.FixedTemperature fixedTemperature(T=
        283.15) ;
  BaseClasses.HeatTransfer.Components.HomogeneousNLayersWall
    paroiNCouchesHomogenes4(
    n=1,
    m={20},
    e={1},
    mat={BuildSysPro.Utilities.Data.Solids.Concrete()}) ;
  BaseClasses.HeatTransfer.Components.HomogeneousNLayersWall
    paroiNCouchesHomogenes5(
    n=1,
    m={20},
    e={1},
    mat={BuildSysPro.Utilities.Data.Solids.Concrete()}) ;
  BaseClasses.HeatTransfer.Components.HomogeneousNLayersWall
    paroiNCouchesHomogenes2(
    n=1,
    m={20},
    e={1},
    mat={BuildSysPro.Utilities.Data.Solids.Concrete()}) ;
equation

  connect(NoeudAir.port, Glateral.port_a) ;

  connect(Rvt.port_a, NoeudAir.port) ;
  connect(PorteGarage.port_a, NoeudAir.port) ;
  connect(T_ext, PorteGarage.port_b) ;
  connect(T_ext, Rvt.port_b) ;
  connect(Gplancher.port_a, NoeudAir.port) ;
  connect(NoeudAir.port, T_int) ;
  connect(fixedTemperature.port, paroiNCouchesHomogenes3.port_b) ;
  connect(paroiNCouchesHomogenes4.port_a, T_ext) ;
  connect(paroiNCouchesHomogenes4.port_b, paroiNCouchesHomogenes3.port_a)
    ;
  connect(paroiNCouchesHomogenes4.port_b, temperatureSensor.port) ;
  connect(temperatureSensor.T, TsolLat.T) ;
  connect(temperatureSensor.T, TsolPlancher.T) ;
  connect(Glateral.port_b, paroiNCouchesHomogenes2.port_a) ;
  connect(paroiNCouchesHomogenes2.port_b, TsolLat.port) ;
  connect(paroiNCouchesHomogenes5.port_a, Gplancher.port_b) ;
  connect(paroiNCouchesHomogenes5.port_b, TsolPlancher.port) 
  ;
end Basement;

within BuildSysPro.Building.BuildingEnvelope.HeatTransfer;
model B_Coefficient
  "Simple boundary conditions (linear combination of temperature) for unheated space"
parameter Real b=0.1 "Weighting coefficient";
  BuildSysPro.BaseClasses.HeatTransfer.Interfaces.HeatPort_a port_ext
    ;
  BuildSysPro.BaseClasses.HeatTransfer.Interfaces.HeatPort_a Tponder
    ;
  BuildSysPro.BaseClasses.HeatTransfer.Interfaces.HeatPort_a port_int
    ;

equation
  Tponder.T=b*port_ext.T+(1-b)*port_int.T;
  port_int.Q_flow=0;
  port_ext.Q_flow=-Tponder.Q_flow

;
end B_Coefficient;

within BuildSysPro.Building.BuildingEnvelope.HeatTransfer;
model SimpleWall "Wall simple model"

  import      Modelica.Units.SI;

  // Optional parameters
  parameter Boolean RadInterne=false
    "Inclusion of irradiation which is absorbed on the inner face"
    ;
  parameter Boolean RadExterne=false
    "Inclusion of irradiation which is absorbed on the outer face"
    ;
  parameter Boolean GLOext=false
    "Inclusion of LW radiation (infrared) between the wall, the environment and the sky"
    ;

  // General properties
  parameter SI.Area S=1 "Wall surface without windows"
    ;
  replaceable parameter BuildSysPro.Utilities.Records.GenericWall caracParoi
    "Wall composition"
    ;
  parameter SI.CoefficientOfHeatTransfer hs_ext=25
    "Global or convective surface exchange coefficient on the outer face depending on the selected mode (GLOext)"
    ;
  parameter SI.CoefficientOfHeatTransfer hs_int=7.69
    "Surface exchange coefficient on the inner face"
    ;
  parameter Real skyViewFactor=0
    "Average sky view factor between walls and the sky (example: skyViewFactor(flat roof)=1, skyViewfactor(vertical wall in clear environment)=0.5)"
    ;
  parameter Real alpha_ext=0.6
    "Absorption coefficient of the outer wall in the visible (around 0.3 for clear walls and 0.9 for dark shades)"
    ;
  parameter Real eps=0.9 "Emissivity of the outer surface of the wall in LWR (concrete 0.9)"
    ;

  // Initialization
  parameter SI.Temperature Tp=293.15
    "Initial temperature of the wall"
    ;
  parameter BuildSysPro.Utilities.Types.InitCond InitType=BuildSysPro.Utilities.Types.InitCond.SteadyState
    ;

  // Wall U-value
  final parameter SI.SurfaceCoefficientOfHeatTransfer U_value = BuildSysPro.Building.BuildingEnvelope.Functions.U_Wall(
    wall_record=caracParoi,
    hs_int=hs_int,
    hs_ext=hs_ext)
    "Wall U-value";

  // Heat ports
  BuildSysPro.BaseClasses.HeatTransfer.Interfaces.HeatPort_a T_ext
    "Outdoor air temperature"
    ;
  BuildSysPro.BaseClasses.HeatTransfer.Interfaces.HeatPort_a Ts_ext
    "Outdoor temperature on the wall surface"
    ;
  BuildSysPro.BaseClasses.HeatTransfer.Interfaces.HeatPort_b Ts_int
    "Indoor temperature on the wall surface"
    ;
  BuildSysPro.BaseClasses.HeatTransfer.Interfaces.HeatPort_b T_int
    "Indoor air temperature"
    ;
  BuildSysPro.BaseClasses.HeatTransfer.Interfaces.HeatPort_a T_sky if GLOext
    "Sky temperature"
    ;
  BuildSysPro.BoundaryConditions.Solar.Interfaces.SolarFluxInput FluxIncExt
 if RadExterne
    "SWR incident surface flux on the outer face"
    ;
  Modelica.Blocks.Interfaces.RealInput FluxAbsInt if RadInterne
    "LWR and/or SWR flows which are absorbed by this wall on its inner face"
    ;

  // Internal components

  // Solar irradiation
protected
  Modelica.Blocks.Math.Gain AbsMurExt(k=alpha_ext*S) if RadExterne
    ;
  BuildSysPro.BaseClasses.HeatTransfer.Sources.PrescribedHeatFlow prescribedCLOAbsExt
 if RadExterne ;

  BuildSysPro.BaseClasses.HeatTransfer.Sources.PrescribedHeatFlow prescribedCLOAbsInt
 if RadInterne ;

  // Surface heat transfer on both wall faces
  BuildSysPro.BaseClasses.HeatTransfer.Components.LinearExtLWR EchangesGLOext(
    S=S,
    eps=eps,
    skyViewFactor=skyViewFactor) if GLOext
    ;
  BuildSysPro.BaseClasses.HeatTransfer.Components.ThermalConductor Echange_a(
    G=hs_ext*S)
    ;
  BuildSysPro.BaseClasses.HeatTransfer.Components.ThermalConductor Echange_b(
    G=hs_int*S)
    ;

  // Conduction heat transfer through the wall
  BuildSysPro.BaseClasses.HeatTransfer.Components.HomogeneousNLayersWall ParoiNCouchesHomogenes(
    S=S,
    Tinit=Tp,
    InitType=InitType,
    n=caracParoi.n,
    m=caracParoi.m,
    e=caracParoi.e,
    mat=caracParoi.mat)
    ;

equation
  //slices connection in the case of a conventional wall
  connect(ParoiNCouchesHomogenes.port_a, Ts_ext);
  connect(ParoiNCouchesHomogenes.port_b, Ts_int);

  // Solar irradiation
  connect(FluxIncExt, AbsMurExt.u) ;
  connect(AbsMurExt.y, prescribedCLOAbsExt.Q_flow) ;
  connect(prescribedCLOAbsExt.port, Ts_ext) ;
  connect(prescribedCLOAbsInt.Q_flow, FluxAbsInt) ;
  connect(prescribedCLOAbsInt.port, Ts_int) ;

  // Surface heat transfer on both wall faces
  connect(T_sky, EchangesGLOext.T_sky) ;
  connect(T_ext, EchangesGLOext.T_ext) ;
  connect(EchangesGLOext.Ts_ext, Ts_ext) ;
  connect(Echange_a.port_b, Ts_ext) ;
  connect(T_ext, Echange_a.port_a) ;
  connect(Echange_b.port_b, T_int) ;
  connect(Echange_b.port_a, Ts_int) 
    ;
end SimpleWall;

within BuildSysPro.Building.BuildingEnvelope.HeatTransfer;
model SimpleWindow "Simple model of glazing"

// General properties

parameter Boolean useVolet=false "Presence of a shutter" ;
parameter Boolean GLOext=false
    "Inclusion of LW radiation (infrared) between the wall and the environment and the sky in linearized form"
    ;
  parameter Modelica.Units.SI.Area S=1 "Glazing surface"
    ;
  parameter Modelica.Units.SI.CoefficientOfHeatTransfer hs_ext=16
    "Global or convective surface exchange coefficient on the outer face depending on the selected mode (GLOext)"
    ;
  parameter Modelica.Units.SI.CoefficientOfHeatTransfer hs_int=8.29
    "Surface exchange coefficient on the inner face"
    ;
  parameter Modelica.Units.SI.ThermalInsulance R_volet=0.2
    "Additional thermal resistance (shutters closed)"
    ;
  parameter Modelica.Units.SI.CoefficientOfHeatTransfer k=1.43
    "Glazing coefficient of surface transmission Ug  - without convective exchanges"
    ;
parameter Real skyViewFactor=0
    "Sky view factor between glazings and the sky (exemple: skyViewFactor(flat roof)=1, skyViewfactor(vertical wall in clear environment)=0.5)"
                                                                                                        ;

// Optical properties
parameter Real Abs=0.1 "Window absorption coefficient" ;
parameter Real eps=0.9 "Glazing emissivity in LWR" ;

// Public components
  BuildSysPro.BoundaryConditions.Solar.Interfaces.SolarFluxInput FluxTr
    "Global solar flux information for the transmission. Must integrate the impact of incidence."
    ;
  BuildSysPro.BoundaryConditions.Solar.Interfaces.SolarFluxInput FluxIncExt
    "SWR incident surface fluxes on the outer face [W/m2]"
    ;
  BuildSysPro.BoundaryConditions.Solar.Interfaces.SolarFluxOutput CLOTr
    "SW radiation transmitted inside [W]" ;
  BuildSysPro.BaseClasses.HeatTransfer.Interfaces.HeatPort_a T_ext
    "Outdoor temperature" ;
  BuildSysPro.BaseClasses.HeatTransfer.Interfaces.HeatPort_a Ts_ext
    "Temperature of outer surface" ;
  BuildSysPro.BaseClasses.HeatTransfer.Interfaces.HeatPort_b Ts_int
    "Temperature of inner surface" ;
  BuildSysPro.BaseClasses.HeatTransfer.Interfaces.HeatPort_b T_int
    "Indoor temperature" ;
  BuildSysPro.BaseClasses.HeatTransfer.Interfaces.HeatPort_a T_sky  if GLOext
    "Sky temperature for LW radiation" ;
public
  Modelica.Blocks.Interfaces.RealInput fermeture_volet      if useVolet==true
    "Closing rate of the shutter" ;

// Internal components

protected
  BaseClasses.HeatTransfer.Components.ControlledThermalConductor echange_a1
    ;
  BuildSysPro.BaseClasses.HeatTransfer.Sources.PrescribedHeatFlow prescribedCLOAbsExt
    ;

  BuildSysPro.BaseClasses.HeatTransfer.Components.ThermalConductor echange_int(G=hs_int*
        S) ;
  BuildSysPro.BaseClasses.HeatTransfer.Components.ThermalConductor echange_ext(G=hs_ext*
        S) ;

Modelica.Blocks.Math.Gain FluxAbsorbe(k=S*Abs)                     ;
Modelica.Blocks.Math.Gain FluxTransmis(k=S)    ;

  BuildSysPro.BaseClasses.HeatTransfer.Components.LinearExtLWR gLOextLinear(
    S=S,
    eps=eps,
    skyViewFactor=skyViewFactor) if GLOext
    ;
protected
  Modelica.Blocks.Interfaces.RealInput volet_internal
     ;
  Modelica.Blocks.Interfaces.RealInput G_internal ;
equation

  // The flux is transmitted only through the window (blackout shutter)
  FluxTransmis.u=(1-volet_internal)*FluxTr;

  // Calculation of the full window thermal conductance (glazing + shutters) excluding convection
  if useVolet then
    if volet_internal>=0.95 then
      G_internal=S/(1/k+R_volet);
    else
      G_internal=k*S;
    end if;
  else
    G_internal=k*S;
  end if;

  if not useVolet then
    volet_internal=0;
  end if;

  connect(echange_ext.port_b, Ts_ext) ;
  connect(T_ext, echange_ext.port_a) ;
  connect(Ts_ext, echange_a1.port_a) ;
  connect(echange_a1.port_b, Ts_int) ;
  connect(Ts_int, echange_int.port_a) ;
  connect(echange_int.port_b, T_int) ;
  connect(prescribedCLOAbsExt.port, Ts_ext) ;

  connect(FluxAbsorbe.y, prescribedCLOAbsExt.Q_flow) ;
  connect(FluxIncExt, FluxAbsorbe.u) ;
  connect(CLOTr, FluxTransmis.y) ;
  connect(gLOextLinear.Ts_ext, Ts_ext) ;
  connect(gLOextLinear.T_sky, T_sky) ;
  connect(gLOextLinear.T_ext, T_ext) ;
  connect(volet_internal, fermeture_volet) ;
  connect(G_internal, echange_a1.G) 
   ;
end SimpleWindow;

