  connect(fLUXzone.FluxIncExtNorth, FenetreNord.FluxIncExt) ;
  connect(fLUXzone.FluxIncExtSouth, FenetreSud.FluxIncExt) ;
  connect(fLUXzone.FluxIncExtEast, FenetreEst.FluxIncExt) ;
  connect(fLUXzone.FluxIncExtWest, FenetreOuest.FluxIncExt) ;
  connect(RenouvellementAir.port_b, noeudAir.port_a) ;
  connect(meteofile.G, fLUXzone.G) ;
  connect(meteofile.T_dry, RenouvellementAir.port_a) ;
  connect(meteofile.T_dry, Plafond.T_ext) ;
  connect(meteofile.T_dry, ParoiNord.T_ext) ;
  connect(meteofile.T_dry, ParoiSud.T_ext) ;
  connect(meteofile.T_dry, ParoiEst.T_ext) ;
  connect(meteofile.T_dry, ParoiOuest.T_ext) ;
  connect(Plancher.T_int, noeudAir.port_a) ;
  connect(FenetreNord.CLOTr, multiSum.u[1]) ;
  connect(FenetreSud.CLOTr, multiSum.u[2]) ;
  connect(FenetreEst.CLOTr, multiSum.u[3]) ;
