within BuildSysPro.BuildingStock.CollectiveHousing.CollectiveHousingBuilding.BuildingR2.CommonZones;
model Basement "Basement for complete collective housing assembly"

// Temperatures of interest
  BuildSysPro.BaseClasses.HeatTransfer.Interfaces.HeatPort_a T_ext
    "Température exterieure" ;
  BuildSysPro.BaseClasses.HeatTransfer.Interfaces.HeatPort_a T_int_Gauguin
    "Upper Gauguin apartment temperature" ;
  BuildSysPro.BaseClasses.HeatTransfer.Interfaces.HeatPort_a T_int_Picasso
    "Upper Picasso apartment temperature" ;
  BuildSysPro.BaseClasses.HeatTransfer.Interfaces.HeatPort_a T_int_Matisse
    "Upper Matisse apartment temperature" ;
  BuildSysPro.BaseClasses.HeatTransfer.Interfaces.HeatPort_a T_int_landing
    "Upper unheated room temperature" ;
  BuildSysPro.BaseClasses.HeatTransfer.Interfaces.HeatPort_a T_int_basement
    "Basement temperature" ;

// Calculation of weighted temperature
  BuildSysPro.BaseClasses.HeatTransfer.Sources.PrescribedTemperature
    TintMoy
    ;
  BuildSysPro.Building.BuildingEnvelope.HeatTransfer.B_Coefficient
    Ponderation(b=b_LNC)
    ;

// Temperature sensors
  BuildSysPro.BaseClasses.HeatTransfer.Sensors.TemperatureSensor TMat
    ;
  BuildSysPro.BaseClasses.HeatTransfer.Sensors.TemperatureSensor TGau
    ;
  BuildSysPro.BaseClasses.HeatTransfer.Sensors.TemperatureSensor TPic
    ;
  BuildSysPro.BaseClasses.HeatTransfer.Sensors.TemperatureSensor TLNC
    ;

protected
  parameter Real S_Gauguin=BuildSysPro.BuildingStock.Utilities.Records.Geometry.CollectiveHousing.SettingsGauguin.Surf_PlancherBas
    "Surface of upper Gauguin apartment";
  parameter Real S_Picasso=BuildSysPro.BuildingStock.Utilities.Records.Geometry.CollectiveHousing.SettingsPicasso.Surf_PlancherBas
    "Surface of upper Picasso apartment";
  parameter Real S_Matisse=BuildSysPro.BuildingStock.Utilities.Records.Geometry.CollectiveHousing.SettingsMatisse.Surf_PlancherBas
    "Surface of upper Matisse apartment";
  parameter Real S_LNC=paraMaisonRT.S_LNC "Surface of upper unheated room";
  parameter Real b_LNC= paraMaisonRT.b_SousSol
    "Weighted coefficient of basement temperature";
public
  replaceable parameter
    BuildSysPro.BuildingStock.Utilities.Records.BuildingData.CollectiveHousing.BuildingDataUNHEATEDROOM.BuildingType
    paraMaisonRT "French building regulation to use" ;
  parameter Modelica.Units.SI.Temperature Tp=293.15
    "Initial temperature of walls"
    ;

equation
  TintMoy.T=(TGau.T*S_Gauguin+TMat.T*S_Matisse+TPic.T*S_Picasso+TLNC.T*S_LNC)/(S_LNC+S_Gauguin+S_Matisse+S_Picasso);

  connect(Ponderation.Tponder, T_int_basement) ;
  connect(T_ext, Ponderation.port_ext) ;
  connect(TintMoy.port, Ponderation.port_int) ;
  connect(T_int_Matisse, TMat.port) ;
  connect(T_int_Gauguin, TGau.port) ;
  connect(T_int_Picasso, TPic.port) ;
  connect(T_int_landing, TLNC.port) ;
  );
end Basement;

within BuildSysPro.BuildingStock.CollectiveHousing.CollectiveHousingBuilding.BuildingR2.CommonZones;
model UnheatedRoom
  "Unheated room to be used as landing for complete collective housing assembly"

  BuildSysPro.BaseClasses.HeatTransfer.Interfaces.HeatPort_a T_ext
    "Exterior temperature" ;

  BuildSysPro.BaseClasses.HeatTransfer.Interfaces.HeatPort_a T_int_landing
    "Stairwell temperature" ;

// Public parameters
public
  replaceable parameter
    BuildSysPro.BuildingStock.Utilities.Records.BuildingData.CollectiveHousing.BuildingDataUNHEATEDROOM.BuildingType
    paraMaisonRT "French building regulation to use" ;
parameter Boolean GLOEXT=false
    "Integration of LW radiation (infrared) toward the environment and the sky"
    ;
  parameter BuildSysPro.Utilities.Types.InitCond InitType=BuildSysPro.Utilities.Types.InitCond.SteadyState
    "Type of initialization for walls"
    ;
parameter Integer PositionEtage=2 "Floor position"
   ;
 parameter Real beta=0
    "Correction of azimuth for vertical walls such as azimuth=beta+azimuth, {beta=0 : N=180,S=0,E=-90,O=90}"
 ;
  parameter Modelica.Units.SI.Temperature Tp=293.15
    "Initial temperature of walls"
    ;
protected
  parameter Modelica.Units.SI.CoefficientOfHeatTransfer HE=if GLOEXT == false
       then paraMaisonRT.Hsext else paraMaisonRT.Hsext - 5.15;
  parameter Modelica.Units.SI.ThermalConductance Gpontsthermiques=if
      PositionEtage == 1 then paraMaisonRT.PontsTh_Generique + paraMaisonRT.PontsTh_Bas
       elseif PositionEtage == 2 then paraMaisonRT.PontsTh_Generique else
      paraMaisonRT.PontsTh_Generique + paraMaisonRT.PontsTh_Haut;
parameter Real ValeurQVconstant=paraMaisonRT.TauxRenouvAir*
      BuildSysPro.BuildingStock.Utilities.Records.Geometry.CollectiveHousing.SettingsUnheatedRoom.VolumeLNC
    "Default value if the air change rate is constant (m^3/h)"                         ;

protected
  BuildSysPro.Building.BuildingEnvelope.HeatTransfer.Wall PlancherBas(
    caracParoi=paraMaisonRT.PlancherBas,
    ParoiInterne=true,
    hs_ext=paraMaisonRT.HsPlancherBas,
    Tp=Tp,
    InitType=paraMaisonRT.InitType,
    S=paraMaisonRT.S_LNC,
    hs_int=paraMaisonRT.Hsint,
    RadInterne=false) if PositionEtage == 1        ;
  BuildSysPro.Building.BuildingEnvelope.HeatTransfer.Wall PlancherInterm(
    ParoiInterne=true,
    hs_ext=paraMaisonRT.HsPlancherBas,
    Tp=Tp,
    InitType=paraMaisonRT.InitType,
    hs_int=paraMaisonRT.Hsint,
    S=paraMaisonRT.S_LNC,
    caracParoi=paraMaisonRT.PlancherInterm,
    RadInterne=false) if PositionEtage >= 2        ;
public
  BuildSysPro.BaseClasses.HeatTransfer.Interfaces.HeatPort_b T_int_inf
    "Lower unheated room temperature" ;

protected
  BuildSysPro.Building.BuildingEnvelope.HeatTransfer.Wall MurSud(
    caracParoi=paraMaisonRT.MurExt,
    hs_ext=HE,
    hs_int=paraMaisonRT.Hsint,
    Tp=Tp,
    InitType=InitType,
    GLOext=GLOEXT,
    RadInterne=false,
    RadExterne=false,
    S=BuildSysPro.BuildingStock.Utilities.Records.Geometry.CollectiveHousing.SettingsUnheatedRoom.Surf_MurSud)
    ;
public
  BuildSysPro.BaseClasses.HeatTransfer.Interfaces.HeatPort_a T_sky   if GLOEXT
     == true ;
protected
  BuildSysPro.BoundaryConditions.Solar.Irradiation.FLUXzone fLUXzone(beta=
       beta)
    ;
public
Modelica.Blocks.Interfaces.RealInput G[10]
    "DIFH, DIRN, DIRH, GLOH, t0, CosDir[1:3], solar azimuth angle, solar elevation angle"
      ;
protected
  BuildSysPro.Building.AirFlow.HeatTransfer.AirNode noeudAir(Tair=Tp, V=
        BuildSysPro.BuildingStock.Utilities.Records.Geometry.CollectiveHousing.SettingsUnheatedRoom.VolumeLNC)
    ;
  BuildSysPro.Building.BuildingEnvelope.HeatTransfer.Wall MurEst(
    caracParoi=paraMaisonRT.MurExt,
    hs_ext=HE,
    hs_int=paraMaisonRT.Hsint,
    Tp=Tp,
    InitType=InitType,
    GLOext=GLOEXT,
    RadInterne=false,
    RadExterne=false,
    S=BuildSysPro.BuildingStock.Utilities.Records.Geometry.CollectiveHousing.SettingsUnheatedRoom.Surf_MurEst)
    ;
  BuildSysPro.Building.AirFlow.HeatTransfer.AirRenewal renouvellementAir(Qv=
        ValeurQVconstant, use_Qv_in=false) ;
  BuildSysPro.BaseClasses.HeatTransfer.Components.ThermalConductor
    PontsThermiques(G=Gpontsthermiques) ;
equation
  connect(PlancherInterm.T_ext, T_int_inf) ;
  connect(PlancherBas.T_ext, T_int_inf) ;
  connect(fLUXzone.G,G)  ;
  connect(fLUXzone.FluxIncExtSouth, MurSud.FluxIncExt) ;
  connect(T_sky, MurSud.T_sky) ;
  connect(T_ext, MurSud.T_ext) ;
  connect(MurSud.T_int, noeudAir.port_a) ;
  connect(PlancherBas.T_int, noeudAir.port_a) ;
  connect(PlancherInterm.T_int, noeudAir.port_a) ;
  connect(noeudAir.port_a, T_int_landing) ;
  connect(MurEst.T_int, noeudAir.port_a) ;
  connect(MurEst.T_sky, MurSud.T_sky) ;
  connect(fLUXzone.FluxIncExtEast, MurEst.FluxIncExt) ;
  connect(renouvellementAir.port_b, noeudAir.port_a) ;
  connect(renouvellementAir.port_a, T_ext) ;
  connect(PontsThermiques.port_b, noeudAir.port_a) ;
  connect(PontsThermiques.port_a, T_ext) ;
