      Medium =
        Medium) "Fluid port that connects to the bottom of the door"
    ;
  Airflow.Multizone.DoorDiscretizedOperable door(
    redeclare package Medium = Medium,
    LClo=20*1E-4,
    wOpe=1,
    hOpe=2.2,
    CDOpe=0.78,
    CDClo=0.78,
