model Example5
  "Example 5 model of Modelica code that is inefficiently compiled into C-code"
  extends Modelica.Icons.Example;
  parameter Boolean efficient = false
  ;

  parameter Real[3] a = 1:3;
  parameter Real b=sum(a);

  Real c;
