within BuildSysPro.IBPSA.Fluid.FixedResistances;
model CheckValve "Check valve that avoids flow reversal"
  extends IBPSA.Fluid.BaseClasses.PartialResistance(
    dp(nominal=2000),
    final dp_nominal=dpValve_nominal + dpFixed_nominal,
    final m_flow_turbulent=deltaM*abs(m_flow_nominal),
    final from_dp=true,
    final linearized=false,
    allowFlowReversal=true);
  extends IBPSA.Fluid.Actuators.BaseClasses.ValveParameters(rhoStd=
        Medium.density_pTX(
        101325,
        273.15 + 4,
        Medium.X_default));

  parameter Modelica.Units.SI.PressureDifference dpFixed_nominal(
    displayUnit="Pa",
    min=0) = 0 "Pressure drop of pipe and other resistances that are in series"
    ;

  parameter Modelica.Units.SI.PressureDifference dpValve_closing=
      dpValve_nominal/2 "Pressure drop when the check valve starts to close"
    ;

  parameter Real l(min=1e-10, max=1)=0.001 "Valve leakage, l=Kv(y=0)/Kv(y=1)";

  parameter Real kFixed(unit="", min=0)=
    if dpFixed_nominal > Modelica.Constants.eps then
      m_flow_nominal/sqrt(dpFixed_nominal)
    else 0
    "Flow coefficient of fixed resistance that may be in series with valve,
    k=m_flow/sqrt(dp), with unit=(kg.m)^(1/2).";

  Real k(min=Modelica.Constants.small)
    "Flow coefficient of valve and pipe in series in allowed/forward direction,
    k=m_flow/sqrt(dp), with unit=(kg.m)^(1/2).";

protected
  Real a
    "Scaled pressure variable";
  Real cv
    "Twice differentiable Heaviside check valve characteristic";
  Real kCv
    "Smoothed restriction characteristic";

initial equation
  assert(dpFixed_nominal > -Modelica.Constants.eps,
    "In " + getInstanceName() + ": We require dpFixed_nominal >= 0.
    Received dpFixed_nominal = " + String(dpFixed_nominal) + " Pa.");
  assert(l > -Modelica.Constants.eps,
    "In " + getInstanceName() + ": We require l >= 0. Received l = " + String(l));
equation
  a = dp/dpValve_closing;
  cv = smooth(2, max(0, min(1, a^3*(10+a*(-15+6*a)))));
  kCv = Kv_SI*(cv*(1-l) + l);

  if (dpFixed_nominal > Modelica.Constants.eps) then
    k = sqrt(1/(1/kFixed^2 + 1/kCv^2));
  else
    k = kCv;
  end if;

  if homotopyInitialization then
    m_flow = homotopy(actual=
      IBPSA.Fluid.BaseClasses.FlowModels.basicFlowFunction_dp(
      dp=dp,
      k=k,
      m_flow_turbulent=m_flow_turbulent), simplified=m_flow_nominal_pos*dp/
      dp_nominal_pos);
  else
    m_flow = IBPSA.Fluid.BaseClasses.FlowModels.basicFlowFunction_dp(
      dp=dp,
      k=k,
      m_flow_turbulent=m_flow_turbulent);
  end if
  ;
end CheckValve;

within BuildSysPro.IBPSA.Fluid.FixedResistances;
model HydraulicDiameter "Fixed flow resistance with hydraulic diameter and m_flow as parameter"
  extends IBPSA.Fluid.FixedResistances.PressureDrop(final deltaM=eta_default*dh
        /4*Modelica.Constants.pi*ReC/m_flow_nominal_pos, final dp_nominal=fac*
        dpStraightPipe_nominal);

  parameter Modelica.Units.SI.Length dh=sqrt(4*m_flow_nominal/rho_default/
      v_nominal/Modelica.Constants.pi)
    "Hydraulic diameter (assuming a round cross section area)";

  parameter Modelica.Units.SI.Length length "Length of the pipe";

  parameter Real ReC(min=0)=4000
    "Reynolds number where transition to turbulence starts";

  parameter Modelica.Units.SI.Velocity v_nominal=if rho_default < 500 then 1.5
       else 0.15
    "Velocity at m_flow_nominal (used to compute default value for hydraulic diameter dh)"
    ;

  parameter Modelica.Units.SI.Length roughness(min=0) = 2.5e-5
    "Absolute roughness of pipe, with a default for a smooth steel pipe (dummy if use_roughness = false)";

  parameter Real fac(min=1) = 2
    "Factor to take into account resistance of bends etc., fac=dp_nominal/dpStraightPipe_nominal";

  final parameter Modelica.Units.SI.PressureDifference dpStraightPipe_nominal(
      displayUnit="Pa")=
    Modelica.Fluid.Pipes.BaseClasses.WallFriction.Detailed.pressureLoss_m_flow(
    m_flow=m_flow_nominal,
    rho_a=rho_default,
    rho_b=rho_default,
    mu_a=mu_default,
    mu_b=mu_default,
    length=length,
    diameter=dh,
    roughness=roughness,
    m_flow_small=m_flow_small)
    "Pressure loss of a straight pipe at m_flow_nominal";

  Modelica.Units.SI.Velocity v=m_flow/(rho_default*ARound)
    "Flow velocity (assuming a round cross section area)";

protected
  parameter Modelica.Units.SI.Area ARound=dh^2*Modelica.Constants.pi/4
    "Cross sectional area (assuming a round cross section area)";

  parameter Medium.ThermodynamicState state_default=
    Medium.setState_pTX(
      T=Medium.T_default,
      p=Medium.p_default,
      X=Medium.X_default[1:Medium.nXi]) "Default state";

  parameter Modelica.Units.SI.Density rho_default=Medium.density(state_default)
    "Density at nominal condition";

  parameter Modelica.Units.SI.DynamicViscosity mu_default=
      Medium.dynamicViscosity(state_default)
    "Dynamic viscosity at nominal condition"

;
