    final use_X_in=Medium.nXi > 0,
    final use_C_in=Medium.nC > 0,
    final m_flow=0) "Boundary conditions for HVAC system"
    ;

  IBPSA.Fluid.FMI.Conversion.AirToOutlet con[nPorts](redeclare each final
      package       Medium =
                       Medium, each final allowFlowReversal=true)
    "Converter between the different connectors"
    ;

  Sensors.MassFlowRate senMasFlo[nPorts](
    redeclare each final package Medium = Medium,
    each allowFlowReversal=true) "Mass flow rate sensor"
    ;

  IBPSA.Fluid.FMI.BaseClasses.X_w_toX x_w_toX(redeclare final package
      Medium =
        Medium) if Medium.nXi > 0 "Conversion from X_w to X"
    ;

  Modelica.Blocks.Sources.RealExpression hSup[nPorts](
    final y={inStream(ports[i].h_outflow) for i in 1:nPorts})
    "Supply air specific enthalpy"
    ;

  RealVectorExpression XiSup[nPorts](
    each final n = Medium.nXi,
    final y={inStream(ports[i].Xi_outflow) for i in 1:nPorts})
    if Medium.nXi > 0 "Water vapor concentration of supply air"
    ;

  RealVectorExpression CSup[nPorts](
    each final n=Medium.nC,
    final y={inStream(ports[i].C_outflow) for i in 1:nPorts})
    if Medium.nC > 0 "Trace substance concentration of supply air"
    ;

  ///////////////////////////////////////////////////////////////////////////
  // Internal blocks
  block RealVectorExpression
    "Set vector output signal to a time varying vector Real expression"
    parameter Integer n "Dimension of output signal";
    Modelica.Blocks.Interfaces.RealOutput[n] y "Value of Real output"


  ;

  end RealVectorExpression;

initial equation
   assert(Medium.nXi < 2,
   "The medium must have zero or one independent mass fraction Medium.nXi.");
equation

  connect(con.outlet, fluPor)
    ;
  connect(senMasFlo.m_flow, con.m_flow) ;
  connect(hSup.y, con.h) ;
  for i in 1:nPorts loop
    connect(XiSup[i].y, con[i].Xi) ;
    connect(CSup[i].y, con[i].C) ;
  end for;
  connect(senMasFlo.port_b, bou.ports)
    ;
  connect(ports, senMasFlo.port_a)
    ;
  connect(con[1].TAirZon, bou.T_in)
    ;
  connect(con[1].X_wZon, x_w_toX.X_w) ;
  connect(x_w_toX.X, bou.X_in) ;
  connect(con[1].CZon, bou.C_in) ;
  connect(con.TAirZon, TAirZon) ;
  connect(con.X_wZon, X_wZon) ;
  connect(con.CZon, CZon) 
  ;
end HVAC;

within BuildSysPro.IBPSA.Fluid.FMI.Adaptors;
model Inlet "Adaptor for connecting a fluid inlet to the FMI interface"

  replaceable package Medium =
    Modelica.Media.Interfaces.PartialMedium "Medium in the component"
      ;

  parameter Boolean allowFlowReversal = true
    "= true to allow flow reversal, false restricts to design direction (inlet -> outlet)"
    ;

  parameter Boolean use_p_in = true
    "= true to use a pressure from connector, false to output Medium.p_default"
    ;

  IBPSA.Fluid.FMI.Interfaces.Inlet inlet(
    redeclare final package Medium = Medium,
    final allowFlowReversal=allowFlowReversal,
    final use_p_in=use_p_in) "Fluid inlet"
    ;

  Modelica.Fluid.Interfaces.FluidPort_b port_b(
    redeclare final package Medium=Medium) "Fluid port"
                ;
  IBPSA.Fluid.FMI.Interfaces.PressureOutput p if use_p_in "Pressure"
    ;
protected
  IBPSA.Fluid.FMI.Interfaces.FluidProperties bacPro_internal(redeclare final
      package       Medium =
                       Medium)
    "Internal connector for fluid properties for back flow";
  IBPSA.Fluid.FMI.Interfaces.PressureOutput p_in_internal
    "Internal connector for pressure";
  IBPSA.Fluid.FMI.Interfaces.MassFractionConnector X_w_in_internal
    "Internal connector for mass fraction of forward flow properties";
  IBPSA.Fluid.FMI.Interfaces.MassFractionConnector X_w_out_internal
    "Internal connector for mass fraction of backward flow properties";
initial equation
   assert(Medium.nXi < 2,
   "The medium must have zero or one independent mass fraction Medium.nXi.");
equation
  // To locally balance the model, the pressure is only imposed at the
  // outlet model.
  // The sign is negative because inlet.m_flow > 0
  // means that fluid flows out of this component
  -port_b.m_flow     = inlet.m_flow;

  port_b.h_outflow  = Medium.specificEnthalpy_pTX(
                        p = p_in_internal,
                        T = inlet.forward.T,
                        X = if Medium.nXi == 1 then cat(1, {X_w_in_internal}, {1-X_w_in_internal}) else zeros(Medium.nX));

  port_b.C_outflow  = inlet.forward.C;

  // Conditional connector for mass fraction for forward flow
  if Medium.nXi == 0 then
    X_w_in_internal = 0;
  else
    connect(X_w_in_internal, inlet.forward.X_w);
  end if;
  port_b.Xi_outflow = fill(X_w_in_internal, Medium.nXi);

  // Conditional connector for flow reversal
  connect(inlet.backward, bacPro_internal);

  // Mass fraction for reverse flow
  X_w_out_internal = if Medium.nXi > 0 and allowFlowReversal then inStream(port_b.Xi_outflow[1]) else 0;
  connect(bacPro_internal.X_w, X_w_out_internal);

  if allowFlowReversal then
    bacPro_internal.T  = Medium.temperature_phX(
                           p = p_in_internal,
                           h = inStream(port_b.h_outflow),
                           X = cat(1, inStream(port_b.Xi_outflow), {1-sum(inStream(port_b.Xi_outflow))}));
    bacPro_internal.C  = inStream(port_b.C_outflow);
  else
    bacPro_internal.T  = Medium.T_default;
    bacPro_internal.C  = fill(0, Medium.nC);
  end if;

  // Conditional connectors for pressure
  if use_p_in then
  connect(inlet.p, p_in_internal);
  else
    p_in_internal = Medium.p_default;
  end if;
  connect(p, p_in_internal)

  ;
end Inlet;

within BuildSysPro.IBPSA.Fluid.FMI.Adaptors;
model Outlet "Adaptor for connecting a fluid outlet to the FMI interface"

  replaceable package Medium =
    Modelica.Media.Interfaces.PartialMedium "Medium in the component"
      ;

  parameter Boolean allowFlowReversal = true
    "= true to allow flow reversal, false restricts to design direction (inlet -> outlet)"
    ;

  parameter Boolean use_p_in = true
    "= true to use a pressure from connector, false to output Medium.p_default"
    ;

  IBPSA.Fluid.FMI.Interfaces.Outlet outlet(
    redeclare final package Medium = Medium,
    final allowFlowReversal=allowFlowReversal,
    final use_p_in=use_p_in) "Fluid outlet" ;

  Modelica.Fluid.Interfaces.FluidPort_a port_a(
    redeclare final package Medium=Medium) "Fluid port"
                ;
  IBPSA.Fluid.FMI.Interfaces.PressureInput p if use_p_in
    "Pressure to be sent to outlet" ;
protected
  IBPSA.Fluid.FMI.Interfaces.FluidProperties bacPro_internal(redeclare final
      package       Medium =
                       Medium)
    "Internal connector for fluid properties for back flow";
  IBPSA.Fluid.FMI.Interfaces.PressureOutput p_in_internal
    "Internal connector for pressure";

  IBPSA.Fluid.FMI.Interfaces.MassFractionConnector X_w_in_internal
    "Internal connector for mass fraction of forward flow properties";
  IBPSA.Fluid.FMI.Interfaces.MassFractionConnector X_w_out_internal
    "Internal connector for mass fraction of backward flow properties";
initial equation
   assert(Medium.nXi < 2,
   "The medium must have zero or one independent mass fraction Medium.nXi.");
equation
  port_a.m_flow = outlet.m_flow;

  outlet.forward.T = Medium.temperature_phX(
    p = p_in_internal,
    h = inStream(port_a.h_outflow),
    X = cat(1, inStream(port_a.Xi_outflow), {1-sum(inStream(port_a.Xi_outflow))}));

  inStream(port_a.C_outflow)  = outlet.forward.C;

  // Mass fraction for forward flow
  X_w_in_internal = if Medium.nXi > 0 then inStream(port_a.Xi_outflow[1]) else 0;
  connect(outlet.forward.X_w, X_w_in_internal);

  // Conditional connector for mass fraction for backward flow
  if Medium.nXi > 0 and allowFlowReversal then
    connect(X_w_out_internal, outlet.backward.X_w);
  else
    X_w_out_internal = 0;
  end if;
  port_a.Xi_outflow = fill(X_w_out_internal, Medium.nXi);

  // Conditional connector for flow reversal
  connect(outlet.backward, bacPro_internal);
  if not allowFlowReversal then
    bacPro_internal.T  = Medium.T_default;
    bacPro_internal.C  = fill(0, Medium.nC);
    if Medium.nXi > 0 then
      // This test for nXi is needed for IBPSA.Fluid.FMI.Validation.HeaterFan_noReverseFlow
      // to work with IBPSA.Media.Water
      connect(bacPro_internal.X_w, X_w_out_internal);
    end if;
  end if;
  bacPro_internal.T  = Medium.temperature_phX(
    p = p_in_internal,
    h = port_a.h_outflow,
    X = port_a.Xi_outflow);
  bacPro_internal.C  = port_a.C_outflow;

  // Conditional connectors for pressure
  if use_p_in then
    connect(outlet.p, p_in_internal);
  else
    p_in_internal = Medium.p_default;
  end if;
  connect(p, p_in_internal);
  port_a.p = p_in_internal

    ;
end Outlet;

within BuildSysPro.IBPSA.Fluid.FMI.Adaptors;
model ThermalZone
  "Adaptor for connecting a thermal zone to signal ports which then can be exposed at an FMI interface"

  replaceable package Medium =
    Modelica.Media.Interfaces.PartialMedium "Medium in the component"
      ;

  // Don't use  for nPorts because
  // otherwise, in IBPSA.Fluid.FMI.ExportContainers.Examples.FMUs.HVACZones
  // the fluid ports can not be assigned between the different zones by the user.
  parameter Integer nPorts(final min=2) "Number of fluid ports"
    ;

  Interfaces.Inlet fluPor[nPorts](
    redeclare each final package Medium = Medium,
    each final allowFlowReversal=true,
    each final use_p_in=false) "Fluid connector" ;

  Modelica.Fluid.Interfaces.FluidPorts_b ports[nPorts](
    redeclare each final package Medium = Medium)
    ;

  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a heaPorAir
    "Heat port for sensible heat input" ;

protected
  x_i_toX_w x_i_toX(
    redeclare final package Medium = Medium)
 if Medium.nXi > 0 "Conversion from x_i to X_w"
    ;

  RealVectorExpression XiSup(
    final n=Medium.nXi,
    final y=inStream(ports[1].Xi_outflow))
    if Medium.nXi > 0
      "Water vapor concentration of supply air"
    ;

  RealVectorExpression CSup(
    final n=Medium.nC,
    final y=inStream(ports[1].C_outflow))
 if Medium.nC > 0 "Trace substance concentration of supply air"
    ;

  Sources.MassFlowSource_T bou[nPorts](
    each final nPorts=1,
    redeclare each final package Medium = Medium,
    each final use_T_in=true,
    each final use_C_in=Medium.nC > 0,
    each final use_X_in=Medium.nXi > 0,
    each use_m_flow_in=true) "Mass flow source"
    ;

  Conversion.InletToAir con[nPorts](redeclare each final package
      Medium =
        Medium) "Connector between FMI signals and real input and real outputs"
    ;

  Modelica.Thermal.HeatTransfer.Sensors.TemperatureSensor senTemAir
    "Room air temperature sensor"
    ;

  BaseClasses.X_w_toX x_w_toX[nPorts](redeclare final package Medium = Medium)
    if Medium.nXi > 0 "Conversion from X_w to X"
    ;

  Modelica.Blocks.Math.MultiSum multiSum(final nu=nPorts, final k=fill(1,
        nPorts)) "Sum of air mass flow rates"
    ;

  IBPSA.Utilities.Diagnostics.AssertEquality assEqu(message=
        "\"Mass flow rate does not balance. The sum needs to be zero.",
      threShold=1E-4) "Tests whether the mass flow rates balance to zero"
    ;
  Modelica.Blocks.Sources.Constant const(final k=0) "Outputs zero"
    ;

  ///////////////////////////////////////////////////////////////////////////
  // Internal blocks
  block RealVectorExpression
    "Set vector output signal to a time varying vector Real expression"
    parameter Integer n "Dimension of output signal";
    Modelica.Blocks.Interfaces.RealOutput[n] y "Value of Real output"

    ;
  end RealVectorExpression;

  block x_i_toX_w "Conversion from Xi to X"
    extends Modelica.Blocks.Icons.Block;

    replaceable package Medium =
      Modelica.Media.Interfaces.PartialMedium "Medium model within the source"
     ;
    Modelica.Blocks.Interfaces.RealInput Xi[Medium.nXi](each final unit="kg/kg")
   if Medium.nXi > 0 "Water vapor concentration in kg/kg total air"
      ;

    Modelica.Blocks.Interfaces.RealOutput X_w(
      final unit="kg/kg") "Water vapor concentration in kg/kg total air"
      ;
  protected
    Modelica.Blocks.Interfaces.RealInput Xi_internal[Medium.nXi](
      each final unit = "kg/kg")
      "Internal connector for water vapor concentration in kg/kg total air";

    Modelica.Blocks.Interfaces.RealInput X_w_internal(
      final unit = "kg/kg")
      "Internal connector for water vapor concentration in kg/kg total air";

  equation
  // Conditional connector
  connect(Xi_internal, Xi);
  if Medium.nXi == 0 then
    Xi_internal = zeros(Medium.nXi);
  end if;

  X_w_internal = sum(Xi_internal);
  connect( X_w, X_w_internal)
  ;
  end x_i_toX_w;

initial equation
   assert(Medium.nXi < 2,
   "The medium must have zero or one independent mass fraction Medium.nXi.");
equation

  for i in 1:nPorts loop
    connect(bou[i].ports[1], ports[i]) ;
  end for;
  connect(con.inlet, fluPor)
    ;
  connect(con.X_w, x_w_toX.X_w) ;

  connect(x_w_toX.X, bou.X_in)
    ;
  connect(con.C, bou.C_in) ;
  connect(heaPorAir, senTemAir.port) ;
  connect(XiSup.y, x_i_toX.Xi)
    ;
  connect(con.T, bou.T_in) ;
  connect(con[1:nPorts].m_flow, multiSum.u[1:nPorts]) ;
  connect(multiSum.y, assEqu.u2) ;
  connect(const.y, assEqu.u1) ;
  for i in 1:nPorts loop
  connect(senTemAir.T, con[i].TAirZon) ;
  if Medium.nXi > 0 then
    connect(x_i_toX.X_w, con[i].X_wZon) ;
  end if;
  connect(CSup.y, con[i].CZon)
    ;
  end for;
  connect(bou.m_flow_in, con.m_flow) 
  ;
end ThermalZone;

