within BuildSysPro.IBPSA.Fluid.FMI.Conversion.Validation;
model InletToAirMoistAir
  "Validation model for inlet to IBPSA.Media.Air conversion without trace substances"
  extends Modelica.Icons.Example;

  replaceable package Medium = IBPSA.Media.Air constrainedby
    Modelica.Media.Interfaces.PartialMedium                "Medium model";
  parameter Boolean use_p_in = false
    "= true to use a pressure from connector, false to output Medium.p_default"
    ;

  Modelica.Blocks.Sources.Constant m_flow(k=0.2) "Mass flow rate"
    ;
  Modelica.Blocks.Sources.Constant T(k=295.13) "Room temperature"
    ;

  IBPSA.Fluid.FMI.Conversion.InletToAir conAir(redeclare package
      Medium =
        Medium, allowFlowReversal=false) "Converter for air"
    ;

  Source_T sou(
    redeclare package Medium = Medium,
    use_p_in=use_p_in,
    allowFlowReversal=false)
    "Source for mass flow rate and pressure"
    ;
  Modelica.Blocks.Sources.Constant pIn(k=100000) "Inlet pressure"
    ;
  Modelica.Blocks.Sources.Constant X_w_in(k=0.01) "Inlet mass fraction"
    ;
  Modelica.Blocks.Sources.Constant C[Medium.nC](each k=0.01)
  if Medium.nC > 0 "Trace substances for forward flow"
    ;
  IBPSA.Fluid.FMI.Conversion.InletToAir conAirRevFlo(redeclare package
              Medium =
        Medium, allowFlowReversal=true) "Converter for air with reverse flow"
    ;
  Source_T souRev(
    redeclare package Medium = Medium,
    use_p_in=use_p_in,
    allowFlowReversal=true)
    "Source for mass flow rate and pressure with reverse flow"
    ;
  Modelica.Blocks.Sources.Constant TRev(k=283.15)
    "Temperature for reverse flow"
    ;
  Modelica.Blocks.Sources.Constant X_w(k=0.012)
    "Mass flow fraction for reverse flow"
    ;
equation
  connect(m_flow.y, sou.m_flow_in) ;
  connect(sou.outlet, conAir.inlet)
    ;
  connect(sou.T_in, T.y) ;
  connect(pIn.y, sou.p_in) ;
  connect(X_w_in.y, sou.X_w_in) ;
  connect(C.y, sou.C_in) ;
  connect(m_flow.y, souRev.m_flow_in) ;
  connect(souRev.outlet, conAirRevFlo.inlet)
    ;
  connect(souRev.T_in, T.y) ;
  connect(pIn.y, souRev.p_in) ;
  connect(X_w_in.y, souRev.X_w_in) ;
  connect(C.y, souRev.C_in) ;
  connect(TRev.y, conAirRevFlo.TAirZon) ;
  connect(X_w.y, conAirRevFlo.X_wZon) 
;
end InletToAirMoistAir;

