    ;
  Modelica.Thermal.HeatTransfer.Sensors.TemperatureSensor temSen2
    "Temperature sensor (that approximates the radiative temperature by the air temperature)"
    ;

equation
  connect(weaDat.weaBus,weaBus)  ;
  connect(theCon1.port_b, vol1.heatPort) ;
  connect(preHea1.port, vol1.heatPort) ;
  connect(TAirOut.T, weaBus.TDryBul) ;
  connect(TAirOut.port, theCon1.port_a)
    ;

  connect(TOut, weaBus.TDryBul) ;
  connect(theCon2.port_b, vol2.heatPort) ;
  connect(preHea2.port, vol2.heatPort) ;
  connect(TAirOut.port, theCon2.port_a) ;
  connect(vol1.heatPort, theZonAda[1].heaPorAir) ;
  connect(vol2.heatPort, theZonAda[2].heaPorAir) ;
  connect(theZonAda[2].ports, senMasFlo1.port_a) ;
  connect(senMasFlo.port_a, theZonAda[1].ports) ;
  connect(senMasFlo1.port_b, vol2.ports[1:3]) ;
  connect(senMasFlo.port_b, vol1.ports[1:3]) ;
  connect(temSen1.port, vol1.heatPort) ;
  connect(temSen2.port, vol2.heatPort) ;
  connect(temSen1.T, TRad1)
    ;
  connect(temSen2.T, TRad2) 
    ;
end ThermalZones;

