    ;
  connect(Rpg1.port_b, Rgb1.port_a) ;
  connect(Rgb1.port_b, port_wall) ;
  connect(capFil1.port, Rgb1.port_a)
    ;
  connect(Rgg.port_a, Rgb1.port_a)
    ;
  connect(port_2, Rpg2.port_b)
    ;
  connect(Rgg.port_b, Rpg2.port_a) ;
