     dis^2/(4*aSoi*t)) else 0.0
;
end infiniteLineSource;

within BuildSysPro.IBPSA.Fluid.Geothermal.Borefields.BaseClasses.HeatTransfer.ThermalResponseFactors;
function shaGFunction
  "Returns a SHA1 encryption of the formatted arguments for the g-function generation"
  extends Modelica.Icons.Function;
  input Integer nBor "Number of boreholes";
  input Modelica.Units.SI.Position cooBor[nBor,2] "Coordinates of boreholes";
  input Modelica.Units.SI.Height hBor "Borehole length";
  input Modelica.Units.SI.Height dBor "Borehole buried depth";
  input Modelica.Units.SI.Radius rBor "Borehole radius";
  input Modelica.Units.SI.ThermalDiffusivity aSoi
    "Ground thermal diffusivity used in g-function evaluation";
  input Integer nSeg "Number of line source segments per borehole";
  input Integer nClu "Number of clusters for g-function calculation";
  input Integer nTimSho "Number of time steps in short time region";
  input Integer nTimLon "Number of time steps in long time region";
  input Real ttsMax "Maximum adimensional time for gfunc calculation";

  output String sha
  "SHA1 encryption of the g-function arguments";

protected
  constant String formatStrGen =  "1.3e" "String format for general parameters";
  constant String formatStrCoo =  ".2f" "String format for coordinate";
algorithm
  sha := IBPSA.Utilities.Cryptographics.sha(String(nBor, format=formatStrGen));
  sha := IBPSA.Utilities.Cryptographics.sha(sha + String(hBor, format=
    formatStrGen));
  sha := IBPSA.Utilities.Cryptographics.sha(sha + String(dBor, format=
    formatStrGen));
  sha := IBPSA.Utilities.Cryptographics.sha(sha + String(rBor, format=
    formatStrGen));
  sha := IBPSA.Utilities.Cryptographics.sha(sha + String(aSoi, format=
    formatStrGen));
  sha := IBPSA.Utilities.Cryptographics.sha(sha + String(nSeg, format=
    formatStrGen));
  sha := IBPSA.Utilities.Cryptographics.sha(sha + String(nClu, format=
    formatStrGen));
  sha := IBPSA.Utilities.Cryptographics.sha(sha + String(nTimSho, format=
    formatStrGen));
  sha := IBPSA.Utilities.Cryptographics.sha(sha + String(nTimLon, format=
    formatStrGen));
  sha := IBPSA.Utilities.Cryptographics.sha(sha + String(ttsMax, format=
    formatStrGen));
  for i in 1:nBor loop
    sha := IBPSA.Utilities.Cryptographics.sha(sha + String(cooBor[i, 1], format=
       formatStrCoo));
    sha := IBPSA.Utilities.Cryptographics.sha(sha + String(cooBor[i, 2], format=
       formatStrCoo));
  end for

;
end shaGFunction;

within BuildSysPro.IBPSA.Fluid.Geothermal.Borefields.BaseClasses.HeatTransfer.ThermalResponseFactors;
function timeGeometric "Geometric expansion of time steps"
  extends Modelica.Icons.Function;

  input Modelica.Units.SI.Duration dt "Minimum time step";
  input Modelica.Units.SI.Time t_max "Maximum value of time";
  input Integer nTim "Number of time values";

  output Real t[nTim] "Time vector";

protected
  Real r(min=1.) "Expansion rate of time values";
  Real dr "Error on expansion rate evaluation";

algorithm
  if t_max > nTim*dt then
    // Determine expansion rate (r)
    dr := 1e99;
    r := 2;
    while abs(dr) > 1e-10 loop
      dr := (1+t_max/dt*(r-1))^(1/nTim) - r;
      r := r + dr;
    end while;
    // Assign time values
    for i in 1:nTim-1 loop
      t[i] := dt*(1-r^i)/(1-r);
    end for;
      t[nTim] := t_max;

  else
    // Number of time values too large for chosen parameters:
    // Use a constant time step
    for i in 1:nTim loop
      t[i] := i*dt;
    end for;

  end if
;
end timeGeometric;

