within BuildSysPro.IBPSA.Fluid.Geothermal.Borefields.Examples;
model RectangularBorefield "Example model of a rectangular borefield"
  extends Modelica.Icons.Example;

  package Medium = IBPSA.Media.Water "Medium model";

  parameter Modelica.Units.SI.Time tLoaAgg=300
    "Time resolution of load aggregation";

  parameter Modelica.Units.SI.Temperature TGro=283.15 "Ground temperature";
  parameter Modelica.Units.SI.Velocity v_nominal=1 "Nominal velocity";
  parameter Modelica.Units.SI.MassFlowRate m_flow_nominal=nBorHol*v_nominal*
      rTub^2*3.14*1000 "Nominal mass flow rate";
  parameter Modelica.Units.SI.Pressure dpBorFie_nominal=(hBor + (xBorFie +
      yBorFie)/2)*2 "Pressure losses for the entire borefield";
  parameter Modelica.Units.SI.Pressure dpHex_nominal=10000
    "Pressure drop heat exchanger";
  parameter Modelica.Units.SI.Pressure dp_nominal=dpBorFie_nominal +
      dpHex_nominal "Total pressure drop";

  parameter Modelica.Units.SI.Height hBor=100 "Total height of the borehole";
  parameter Modelica.Units.SI.Radius rTub=0.02 "Outer radius of the tubes";
  parameter Modelica.Units.SI.Length xBorFie=10 "Borefield length";
  parameter Modelica.Units.SI.Length yBorFie=30 "Borefield width";
  parameter Modelica.Units.SI.Length dBorHol=5 "Distance between two boreholes";

  final parameter Integer nXBorHol = integer((xBorFie+dBorHol)/dBorHol) "Number of boreholes in x-direction";
  final parameter Integer nYBorHol = integer((yBorFie+dBorHol)/dBorHol) "Number of boreholes in y-direction";
  final parameter Integer nBorHol = nXBorHol*nYBorHol "Number of boreholes";

  final parameter IBPSA.Fluid.Geothermal.Borefields.Data.Filling.Bentonite filDat
    ;
  final parameter IBPSA.Fluid.Geothermal.Borefields.Data.Soil.SandStone soiDat
    "Soil data" ;
  final parameter IBPSA.Fluid.Geothermal.Borefields.Data.Configuration.Template
    conDat(
    final borCon=IBPSA.Fluid.Geothermal.Borefields.Types.BoreholeConfiguration.SingleUTube,
    final use_Rb=false,
    final mBor_flow_nominal=m_flow_nominal/(nXBorHol*nYBorHol),
    final mBorFie_flow_nominal=m_flow_nominal,
    final hBor=hBor,
    final dBor=1,
    final rBor=0.2,
    final rTub=rTub,
    final kTub=0.5,
    final eTub=0.002,
    final xC=0.05,
    final dp_nominal=dpBorFie_nominal,
    final cooBor={{dBorHol*mod((i - 1), nXBorHol),dBorHol*floor((i - 1)/
        nXBorHol)} for i in 1:nBorHol}) "Borefield configuration"
    ;

  final parameter IBPSA.Fluid.Geothermal.Borefields.Data.Borefield.Template borFieDat(
    final filDat=filDat,
    final soiDat=soiDat,
    final conDat=conDat) "Borefield parameters"
    ;

  IBPSA.Fluid.Geothermal.Borefields.OneUTube borFie(
    redeclare package Medium = Medium,
    borFieDat=borFieDat,
    energyDynamics=Modelica.Fluid.Types.Dynamics.FixedInitial,
    TExt0_start=280.65,
    allowFlowReversal=false) "Geothermal borefield"
    ;

  IBPSA.Fluid.Sources.Boundary_pT bou(redeclare package Medium = Medium, nPorts=
       1) "Pressure boundary condition"
    ;

  IBPSA.Fluid.Movers.FlowControlled_m_flow pum(
    redeclare package Medium = Medium,
    addPowerToMedium=false,
    use_inputFilter=false,
    energyDynamics=Modelica.Fluid.Types.Dynamics.SteadyState,
    inputType=IBPSA.Fluid.Types.InputType.Constant,
    m_flow_nominal=borFieDat.conDat.mBorFie_flow_nominal,
    allowFlowReversal=false)
    ;
  IBPSA.Fluid.HeatExchangers.Heater_T hea(
    redeclare package Medium = Medium,
    show_T=true,
    m_flow_nominal=borFieDat.conDat.mBorFie_flow_nominal,
    m_flow(start=borFieDat.conDat.mBorFie_flow_nominal),
    energyDynamics=Modelica.Fluid.Types.Dynamics.SteadyStateInitial,
    dp_nominal=dpHex_nominal,
    allowFlowReversal=false) "Heater"
    ;
  Modelica.Blocks.Sources.Constant TSou(k=293.15)
    "Temperature of water that goes into the borefield"
    ;
equation

  connect(hea.port_b, pum.port_a)
    ;
  connect(TSou.y, hea.TSet) ;
  connect(pum.port_b, borFie.port_a)
    ;
  connect(borFie.port_b, hea.port_a) ;
  connect(pum.port_a, bou.ports[1])

  ;
end RectangularBorefield;

within BuildSysPro.IBPSA.Fluid.Geothermal.Borefields.Validation;
model Sandbox "Validation of BorefieldOneUTube based on the experiment of Beier et al. (2011)"
  extends Modelica.Icons.Example;
  package Medium = IBPSA.Media.Water;

  parameter Modelica.Units.SI.Temperature T_start=273.15 + 22.09
    "Initial temperature of the sandbox";

  // mSenFac is set to its numerical value because it is a constant in the borehole model.
  // mSenFac = 1 +
  //  (1.8e6*Modelica.Constants.pi*(borFieDat.conDat.rTub^2
  //        -(borFieDat.conDat.rTub-borFieDat.conDat.eTub)^2)
  //        +2.4e6*2*Modelica.Constants.pi*borFieDat.conDat.rBor*0.002/2)
  //        /(4.2e6*Modelica.Constants.pi*(borFieDat.conDat.rTub-borFieDat.conDat.eTub)^2)

  constant Real mSenFac = 1.59186
  "Scaling factor for the borehole capacitances, modified to account for the thermal mass of the pipes and the borehole casing";

  IBPSA.Fluid.Geothermal.Borefields.OneUTube borHol(
    redeclare package Medium = Medium,
    borFieDat=borFieDat,
    tLoaAgg=60,
    energyDynamics=Modelica.Fluid.Types.Dynamics.FixedInitial,
    mSenFac=mSenFac,
    TExt0_start=T_start,
    dT_dz=0) "Borehole"
    ;
  IBPSA.Fluid.Movers.FlowControlled_m_flow pum(
    redeclare package Medium = Medium,
    T_start=T_start,
    addPowerToMedium=false,
    use_inputFilter=false,
    energyDynamics=Modelica.Fluid.Types.Dynamics.SteadyState,
    m_flow_nominal=borFieDat.conDat.mBorFie_flow_nominal,
    nominalValuesDefineDefaultPressureCurve=true,
    inputType=IBPSA.Fluid.Types.InputType.Constant,
    dp_nominal=60E3) "Circulation pump"
    ;
  IBPSA.Fluid.Sensors.TemperatureTwoPort TBorFieIn(
    redeclare package Medium = Medium,
    T_start=T_start,
    m_flow_nominal=borFieDat.conDat.mBorFie_flow_nominal,
    tau=0) "Inlet temperature of the borefield"
    ;
  IBPSA.Fluid.Sensors.TemperatureTwoPort TBorFieOut(
    redeclare package Medium = Medium,
    T_start=T_start,
    m_flow_nominal=borFieDat.conDat.mBorFie_flow_nominal,
    tau=0) "Outlet temperature of the borefield"
    ;
  parameter
    IBPSA.Fluid.Geothermal.Borefields.Validation.BaseClasses.SandBox_Borefield borFieDat
    "Borefield data"
    ;
  IBPSA.Fluid.Sources.Boundary_ph sin(redeclare package Medium = Medium, nPorts=
       1) "Sink" ;
  Modelica.Blocks.Sources.CombiTimeTable sandBoxMea(
    tableOnFile=true,
    tableName="data",
    offset={0,0,0},
    columns={2,3,4},
    fileName=Modelica.Utilities.Files.loadResource(
      "modelica://BuildSysPro/IBPSA/Resources/Data/Fluid/Geothermal/Borefields/HeatTransfer/Validation/Beier_Smith_Spitler_2011_SandBox.txt"))
    ;
  IBPSA.Fluid.HeatExchangers.HeaterCooler_u hea(
    redeclare package Medium = Medium,
    dp_nominal=10000,
    show_T=true,
    energyDynamics=Modelica.Fluid.Types.Dynamics.SteadyState,
    T_start=T_start,
    Q_flow_nominal=1056,
    m_flow_nominal=borFieDat.conDat.mBorFie_flow_nominal,
    m_flow(start=borFieDat.conDat.mBorFie_flow_nominal),
    p_start=100000) "Heater"
    ;
equation
  connect(TBorFieIn.port_b, borHol.port_a)
    ;
  connect(borHol.port_b, TBorFieOut.port_a)
    ;
  connect(pum.port_b, TBorFieIn.port_a) ;
  connect(sin.ports[1], TBorFieOut.port_b) ;
  connect(hea.port_b, pum.port_a)
    ;
  connect(hea.port_a, TBorFieOut.port_b) ;
  connect(sandBoxMea.y[3], hea.u) 
  ;
end Sandbox;

