model ModificationFactor "Factor to modify nominal capacity"
  extends Modelica.Blocks.Icons.Block;

  parameter Integer nBeams(min=1) "Number of beams in parallel";

  parameter Data.Generic per "Performance data"
    ;

  Modelica.Blocks.Interfaces.RealInput TWat(
    final unit="K",
    displayUnit="degC") "Temperature of the water entering the beams"
    ;
  Modelica.Blocks.Interfaces.RealInput mWat_flow(
    final unit="kg/s") "Mass flow rate of the water entering the beams"
    ;
  Modelica.Blocks.Interfaces.RealInput mAir_flow(
    final unit="kg/s") "Mass flow rate of the primary air entering the beams"
    ;

  Modelica.Blocks.Interfaces.RealInput TRoo(
    final unit="K",
    displayUnit="degC") "Room air temperature"
    ;

  Modelica.Blocks.Interfaces.RealOutput y(final unit="1")
    "Total modification factor"
    ;

protected
  Modelica.Blocks.Sources.Constant temDif_nom(
    final k=1/per.dT_nominal)
    "Nominal temperature difference between water and room air"
    ;
  Modelica.Blocks.Sources.Constant watFlo_nom(final k=1/(nBeams*per.mWat_flow_nominal))
                                     "Nominal water mass flow rate"
    ;
  Modelica.Blocks.Sources.Constant airFlo_nom(final k=1/(nBeams*per.mAir_flow_nominal))
                                     "Nominal water mass flow rate"
    ;

  DerivativesCubicSpline temDif_mod(
    final xd=per.dT.r_dT,
    final yd=per.dT.f)
    "Derivatives of the cubic spline for the temperature difference between room and water"
    ;
  DerivativesCubicSpline watFlo_mod(
    final xd=per.water.r_V,
    final yd=per.water.f) "Derivatives of the cubic spline for the water flow"
    ;
  DerivativesCubicSpline airFlo_mod(
    final xd=per.primaryAir.r_V,
    final yd=per.primaryAir.f)
    "Derivatives of the cubic spline for the air flow"
    ;

  Modelica.Blocks.Math.Product pro_3
    "Ratio of actual/nominal temperature difference"
    ;
  Modelica.Blocks.Math.Product pro_2 "Ratio of actual/nominal water flow rate"
    ;
  Modelica.Blocks.Math.Product pro_1 "Ratio of actual/nominal air flow rate"
    ;

  Modelica.Blocks.Math.MultiProduct mulPro(final nu=3)
    "Product of the three modification factors"
    ;

  Modelica.Blocks.Math.Add add(final k1=+1, final k2=-1)
    "Temperature difference between water and room air"
    ;

equation
  connect(mAir_flow, pro_1.u1) ;
  connect(airFlo_nom.y, pro_1.u2) ;
  connect(pro_1.y, airFlo_mod.u)
    ;
  connect(mulPro.y, y)
    ;
  connect(mWat_flow, pro_2.u1) ;
  connect(pro_2.y, watFlo_mod.u)
    ;
  connect(watFlo_nom.y, pro_2.u2) ;
  connect(TWat, add.u1) ;
  connect(add.u2, TRoo) ;
  connect(temDif_nom.y, pro_3.u2) ;
  connect(add.y, pro_3.u1) ;
  connect(pro_3.y, temDif_mod.u)
    ;
  connect(watFlo_mod.y, mulPro.u[1]) ;
  connect(airFlo_mod.y, mulPro.u[2]) ;
  connect(temDif_mod.y, mulPro.u[3]) 
  ;
end ModificationFactor;

within BuildSysPro.IBPSA.Fluid.HeatExchangers.BaseClasses;
function determineWaterIndex
  "Determine the index of water in a 2-component medium model"
  input String[:] substanceNames "Names of substances of media";
  output Integer idxWat "Index of water";
protected
  Boolean found(fixed=false) "Flag, used for error checking";
  Integer N = size(substanceNames, 1) "Number of substances";
algorithm
  found:=false;
  idxWat := 1;
  for i in 1:N loop
    if Modelica.Utilities.Strings.isEqual(
        string1=substanceNames[i],
        string2="water",
        caseSensitive=false) then
        idxWat := i;
        found := true;
    end if;
  end for;
  assert(found,
    "Did not find medium species 'water' in the medium model. " +
    "Change medium model.")
  ;
end determineWaterIndex;

within BuildSysPro.IBPSA.Fluid.HeatExchangers.BaseClasses;
function dynamicViscosityWater "Returns the dynamic viscosity for water"
  input Modelica.Units.SI.Temperature T "Thermodynamic state record";
  output Modelica.Units.SI.DynamicViscosity mu "Dynamic viscosity";
algorithm
        mu := ((2.86651*10^(-5))*T^4-0.039376307*T^3+20.32805026*T^2-
        4680.303158*T+406389.0375)*10^(-6);
        //Equation is a fourth order polynomial fit to data from Fundamentals of
        //Heat and Mass Transfer (Fourth Edition), Frank Incropera & David DeWitt,
        //John Wiley & Sons, 1996

;
end dynamicViscosityWater;

within BuildSysPro.IBPSA.Fluid.HeatExchangers.BaseClasses;
function epsilon_C
  "Computes heat exchanger effectiveness for given capacity flow rates and heat exchanger flow regime"
  input Modelica.Units.SI.ThermalConductance UA "UA value";
  input Modelica.Units.SI.ThermalConductance C1_flow
    "Enthalpy flow rate medium 1";
  input Modelica.Units.SI.ThermalConductance C2_flow
    "Enthalpy flow rate medium 2";
  input Integer flowRegime
    "Heat exchanger flow regime, see  IBPSA.Fluid.Types.HeatExchangerFlowRegime";
  input Modelica.Units.SI.ThermalConductance CMin_flow_nominal
    "Minimum enthalpy flow rate at nominal condition";
  input Modelica.Units.SI.ThermalConductance CMax_flow_nominal
    "Maximum enthalpy flow rate at nominal condition";
  input Real delta = 1E-3 "Small value used for smoothing";
  output Real eps(min=0, max=1) "Heat exchanger effectiveness";

protected
  Modelica.Units.SI.ThermalConductance deltaCMin
    "Small number for capacity flow rate";
  Modelica.Units.SI.ThermalConductance deltaCMax
    "Small number for capacity flow rate";
  Modelica.Units.SI.ThermalConductance CMin_flow "Minimum capacity flow rate";
  Modelica.Units.SI.ThermalConductance CMax_flow "Maximum capacity flow rate";
  Modelica.Units.SI.ThermalConductance CMinNZ_flow
    "Minimum capacity flow rate, bounded away from zero";
  Modelica.Units.SI.ThermalConductance CMaxNZ_flow
    "Maximum capacity flow rate, bounded away from zero";
  Real gaiEps(min=0, max=1)
    "Gain used to force UA to zero for very small flow rates";
  Real gaiNTU(min=1E-10, max=1)
    "Gain used to force NTU to a number slightly above zero for very small flow rates. Because NTU is used in NTU^-(0.22), it must not be zero.";
  Real NTU "Number of transfer units";
  Real Z(min=0, max=1) "Ratio of capacity flow rate (CMin/CMax)";

algorithm
  deltaCMin := delta*CMin_flow_nominal;
  deltaCMax := delta*CMax_flow_nominal;
  // effectiveness
  CMin_flow := IBPSA.Utilities.Math.Functions.smoothMin(
    C1_flow,
    C2_flow,
    deltaCMin/4);
  CMax_flow := IBPSA.Utilities.Math.Functions.smoothMax(
    C1_flow,
    C2_flow,
    deltaCMax/4);
  // CMin and CMax, constrained to be non-zero to compute eps-NTU-Z relationship
  CMinNZ_flow := IBPSA.Utilities.Math.Functions.smoothMax(
    CMin_flow,
    deltaCMin,
    deltaCMin/4);
  CMaxNZ_flow := IBPSA.Utilities.Math.Functions.smoothMax(
    CMax_flow,
    deltaCMax,
    deltaCMax/4);
  Z := CMin_flow/CMaxNZ_flow+1E-10*deltaCMin;
  // Gain that goes to zero as CMin_flow gets below deltaCMin
  // This is needed to allow zero flow
  gaiEps := IBPSA.Utilities.Math.Functions.spliceFunction(
    pos=1,
    neg=0,
    x=CMin_flow - deltaCMin,
    deltax=deltaCMin/2);
  gaiNTU := IBPSA.Utilities.Math.Functions.spliceFunction(
    pos=1,
    neg=delta,
    x=CMin_flow - deltaCMin,
    deltax=deltaCMin/2);

  NTU := gaiNTU*UA/CMinNZ_flow;
  eps := gaiEps*IBPSA.Fluid.HeatExchangers.BaseClasses.epsilon_ntuZ(
    NTU=NTU,
    Z=Z,
    flowRegime=flowRegime)

  ;
end epsilon_C;

within BuildSysPro.IBPSA.Fluid.HeatExchangers.BaseClasses;
function epsilon_ntuZ
  "Computes heat exchanger effectiveness for given number of transfer units and heat exchanger flow regime"
  import f = BuildSysPro.IBPSA.Fluid.Types.HeatExchangerFlowRegime;
  input Real NTU "Number of transfer units";
  input Real Z(min=0, max=1) "Ratio of capacity flow rate (CMin/CMax)";
  input Integer flowRegime
    "Heat exchanger flow regime, see  IBPSA.Fluid.Types.HeatExchangerFlowRegime";
  output Real eps(min=0, max=1) "Heat exchanger effectiveness";
protected
  Real a "Auxiliary variable";
algorithm
  if (flowRegime == Integer(f.ParallelFlow)) then // parallel flow
    a := 0;
    eps := (1 - Modelica.Math.exp(-NTU*(1 + Z)))/(1 + Z);
  elseif (flowRegime == Integer(f.CounterFlow)) then// counter flow
   // a is constraining Z since eps is not defined for Z=1.
    a := smooth(1, if Z < 0.97 then Z else
      IBPSA.Utilities.Math.Functions.smoothMin(
      x1=Z,
      x2=0.98,
      deltaX=0.01));
    eps := (1 - Modelica.Math.exp(-NTU*(1 - a)))/(1 - a*Modelica.Math.exp(-NTU*(
      1 - a)));
  elseif (flowRegime == Integer(f.CrossFlowUnmixed)) then
   a := NTU^(-0.22);
    eps := 1 - Modelica.Math.exp( ( Modelica.Math.exp( - NTU * Z * a)  - 1)  / (Z * a));
  elseif (flowRegime == Integer(f.CrossFlowCMinUnmixedCMaxMixed)) then
    // cross flow, (single pass), CMax mixed, CMin unmixed. (Coil with one row.)
    a := 0;
    eps := (1 - Modelica.Math.exp(-Z*(1 - Modelica.Math.exp(-NTU))))/Z;
  elseif (flowRegime == Integer(f.CrossFlowCMinMixedCMaxUnmixed)) then
    // cross flow, (single pass), CMin mixed, CMax unmixed.
    a := 0;
    eps := 1 - Modelica.Math.exp(-(1 - Modelica.Math.exp(-Z*NTU))/Z);
  elseif (flowRegime == Integer(f.ConstantTemperaturePhaseChange)) then
    // one side is experiencing constant temperature phase change
    // Z is unused
    a := 0;
    eps := 1 - Modelica.Math.exp(-NTU);
  else
    a := 0;
    eps := 0;
    assert(Integer(f.ParallelFlow) <= flowRegime and
           flowRegime <= Integer(f.ConstantTemperaturePhaseChange),
           "Flow regime is not implemented.");
  end if
  ;
end epsilon_ntuZ;

within BuildSysPro.IBPSA.Fluid.HeatExchangers.BaseClasses;
model HACoilInside "Calculates the hA value for water inside a coil"
  extends Modelica.Blocks.Icons.Block;

  parameter Modelica.Units.SI.MassFlowRate m_flow_nominal
    "Water mass flow rate"
    ;

  Modelica.Blocks.Interfaces.RealInput m_flow(unit="kg/s") "Mass flow rate"
    ;
  Modelica.Blocks.Interfaces.RealInput T(unit="K") "Temperature"
    ;

  Modelica.Blocks.Interfaces.RealOutput hA(unit="W/K")
    "Inside convective heat transfer" ;

  parameter Modelica.Units.SI.ThermalConductance hA_nominal(min=0)
    "Convective heat transfer coefficient"
    ;
  parameter Real n(min=0, max=1)=0.85
    "Water-side exponent for convective heat transfer coefficient, h proportional to m_flow^n";
  parameter Modelica.Units.SI.Temperature T_nominal=
      Modelica.Units.Conversions.from_degC(20) "Nominal water temperature"
    ;
  parameter Boolean flowDependent=true
    "Set to false to make hA independent of mass flow rate"
    ;
  parameter Boolean temperatureDependent = true
    "Set to false to make hA independent of temperature"
    ;

protected
  Real x(min=0)
    "Factor for temperature dependent variation of heat transfer coefficient";
  parameter Real s(min=0, fixed=false)
    "Coefficient for temperature dependence of heat transfer coefficient";
  Real fm "Fraction of actual to nominal mass flow rate";

initial equation
  s =if temperatureDependent then 0.014/(1 + 0.014*
    Modelica.Units.Conversions.to_degC(T_nominal)) else 1;
equation
  fm = if flowDependent then m_flow / m_flow_nominal else 1;
  x = if temperatureDependent then 1 + s * (T-T_nominal) else 1;
  if flowDependent and temperatureDependent then
    hA = x*hA_nominal*IBPSA.Utilities.Math.Functions.regNonZeroPower(
      fm,
      n,
      0.1);
  elseif flowDependent then
    hA = hA_nominal*IBPSA.Utilities.Math.Functions.regNonZeroPower(
      fm,
      n,
      0.1);
  elseif temperatureDependent then
    hA = x * hA_nominal;
  else
    hA = hA_nominal;
  end if

;
end HACoilInside;

within BuildSysPro.IBPSA.Fluid.HeatExchangers.BaseClasses;
model HADryCoil
  "Sensible convective heat transfer model for air to water coil"
  extends Modelica.Blocks.Icons.Block;

  parameter Modelica.Units.SI.ThermalConductance UA_nominal(min=0)
    "Thermal conductance at nominal flow"
    ;

  parameter Modelica.Units.SI.MassFlowRate m_flow_nominal_w
    "Water mass flow rate"
    ;
  parameter Modelica.Units.SI.MassFlowRate m_flow_nominal_a
    "Air mass flow rate"
    ;

  Modelica.Blocks.Interfaces.RealInput m1_flow(final unit="kg/s") "Mass flow rate medium 1"
    ;
  Modelica.Blocks.Interfaces.RealInput m2_flow(final unit="kg/s") "Mass flow rate medium 2"
    ;
  Modelica.Blocks.Interfaces.RealInput T_1(final unit="K") "Temperature medium 1"
    ;
  Modelica.Blocks.Interfaces.RealInput T_2(final unit="K") "Temperature medium 2"
    ;

  Modelica.Blocks.Interfaces.RealOutput hA_1(final unit="W/K")
    "Convective heat transfer medium 1" ;
  Modelica.Blocks.Interfaces.RealOutput hA_2(final unit="W/K")
    "Convective heat transfer medium 2" ;

  parameter Real r_nominal(min=0)=0.5
    "Ratio between air-side and water-side convective heat transfer coefficient"
          ;
  parameter Modelica.Units.SI.ThermalConductance hA_nominal_w(min=0)=
    UA_nominal*(r_nominal + 1)/r_nominal
    "Water side convective heat transfer coefficient"
    ;
  parameter Modelica.Units.SI.ThermalConductance hA_nominal_a(min=0)=
    r_nominal*hA_nominal_w
    "Air side convective heat transfer coefficient, including fin resistance"
    ;
  parameter Real n_w(min=0, max=1)=0.85
    "Water-side exponent for convective heat transfer coefficient, h~m_flow^n";
  parameter Real n_a(min=0, max=1)=0.8
    "Air-side exponent for convective heat transfer coefficient, h~m_flow^n";
  parameter Modelica.Units.SI.Temperature T0_w=
      Modelica.Units.Conversions.from_degC(20) "Water temperature"
    ;
  parameter Modelica.Units.SI.Temperature T0_a=
      Modelica.Units.Conversions.from_degC(20) "Air temperature"
    ;
  parameter Boolean waterSideFlowDependent=true
    "Set to false to make water-side hA independent of mass flow rate"
    ;
  parameter Boolean airSideFlowDependent = true
    "Set to false to make air-side hA independent of mass flow rate"
    ;
  parameter Boolean waterSideTemperatureDependent = true
    "Set to false to make water-side hA independent of temperature"
    ;
  parameter Boolean airSideTemperatureDependent = true
    "Set to false to make air-side hA independent of temperature"
    ;
protected
  Real x_a(min=0)
    "Factor for air side temperature dependent variation of heat transfer coefficient";
  Real x_w(min=0)
    "Factor for water side temperature dependent variation of heat transfer coefficient";
  parameter Real s_w(min=0, fixed=false)
    "Coefficient for temperature dependence of water side heat transfer coefficient";
  Real fm_w "Fraction of actual to nominal mass flow rate";
  Real fm_a "Fraction of actual to nominal mass flow rate";
initial equation
  s_w =if waterSideTemperatureDependent then 0.014/(1 + 0.014*
    Modelica.Units.Conversions.to_degC(T0_w)) else 1;
equation
  fm_w = if waterSideFlowDependent then
              m1_flow / m_flow_nominal_w else 1;
  fm_a = if airSideFlowDependent then
              m2_flow / m_flow_nominal_a else 1;
  x_w = if waterSideTemperatureDependent then
         1 + s_w * (T_1-T0_w) else
              1;
  x_a = if airSideTemperatureDependent then
         1 + 7.8532E-4 * (T_2-T0_a) else
              1;
  if waterSideFlowDependent then
    hA_1 = x_w*hA_nominal_w*IBPSA.Utilities.Math.Functions.regNonZeroPower(
      fm_w,
      n_w,
      0.1);
  else
    hA_1 = x_w * hA_nominal_w;
  end if;

  if airSideFlowDependent then
    hA_2 = x_a*hA_nominal_a*IBPSA.Utilities.Math.Functions.regNonZeroPower(
      fm_a,
      n_a,
      0.1);
  else
    hA_2 = x_a * hA_nominal_a;
  end if
;
end HADryCoil;

within BuildSysPro.IBPSA.Fluid.HeatExchangers.BaseClasses;
function isobaricExpansionCoefficientWater
  "Returns the isobaric expansion coefficient for water"
  input Modelica.Units.SI.Temperature T "Thermodynamic state record";
    output Real beta( unit="1/K") "Dynamic viscosity";
algorithm
        beta := (-8.53296*10^(-6)*T^4+0.011562287*T^3-5.88800657*T^2+
        1341.798661*T-115406.5225)*10^(-6);
        //Equation is a fourth order polynomial fit to data from Fundamentals of
        //Heat and Mass Transfer (Fourth Edition), Frank Incropera & David DeWitt,
        //John Wiley & Sons, 1996

;
end isobaricExpansionCoefficientWater;

within BuildSysPro.IBPSA.Fluid.HeatExchangers.BaseClasses;
function lmtd "Log-mean temperature difference"
  input Modelica.Units.SI.Temperature T_a1 "Temperature at port a1";
  input Modelica.Units.SI.Temperature T_b1 "Temperature at port b1";
  input Modelica.Units.SI.Temperature T_a2 "Temperature at port a2";
  input Modelica.Units.SI.Temperature T_b2 "Temperature at port b2";
  output Modelica.Units.SI.TemperatureDifference lmtd
    "Log-mean temperature difference";
protected
  Modelica.Units.SI.TemperatureDifference dT1 "Temperature difference side 1";
  Modelica.Units.SI.TemperatureDifference dT2 "Temperature difference side 2";
algorithm
  dT1 :=T_a1 - T_b2;
  dT2 :=T_b1 - T_a2;
  lmtd :=(dT2 - dT1)/Modelica.Math.log(dT2/dT1)
;
end lmtd;

within BuildSysPro.IBPSA.Fluid.HeatExchangers.BaseClasses;
function ntu_epsilonZ
  "Computes number of transfer units for given heat exchanger effectiveness and heat exchanger flow regime"
  import f = BuildSysPro.IBPSA.Fluid.Types.HeatExchangerFlowRegime;
  input Real eps(min=0, max=0.999) "Heat exchanger effectiveness";
  input Real Z(min=0, max=1) "Ratio of capacity flow rate (CMin/CMax)";
  input Integer flowRegime
    "Heat exchanger flow regime";
  output Real NTU "Number of transfer units";

protected
  Real a "Auxiliary variable";

  function epsilon_ntuZ_crossFlowUnmixed
    "Internal function to solve eps=f(NTU, Z) for NTU for cross flow unmixed"
    extends Modelica.Math.Nonlinear.Interfaces.partialScalarFunction;

    input Real eps(min=0, max=0.999) "Heat exchanger effectiveness";
    input Real Z(min=0, max=1) "Ratio of capacity flow rate (CMin/CMax)";

  protected
    Real NTUExp "Auxiliary variable";

  algorithm
    NTUExp := u^(-0.22);
    y := 1 - Modelica.Math.exp( ( Modelica.Math.exp( - u * Z * NTUExp)  - 1)  / (Z * NTUExp))-eps;
  end epsilon_ntuZ_crossFlowUnmixed;

algorithm
  if (flowRegime == Integer(f.ParallelFlow)) then // parallel flow
    a := Z+1;
    assert(eps < 1/a,
      "Invalid input data. eps > 1/(1+Z) is physically not possible for parallel flow.
  Received eps = " + String(eps) + "
             Z = " + String(Z) + "
       1/(Z+1) = " + String(1/a));
    NTU := -(Modelica.Math.log(1-eps*a))/(a);
  elseif (flowRegime == Integer(f.CounterFlow)) then// counter flow
   // a is constraining Z since eps is not defined for Z=1.
    a := smooth(1, if Z < 0.97 then Z else
      IBPSA.Utilities.Math.Functions.smoothMin(
      x1=Z,
      x2=0.98,
      deltaX=0.01));
    NTU := Modelica.Math.log((1-eps)/(1-eps*a)) / (a-1);

  elseif (flowRegime == Integer(f.CrossFlowUnmixed)) then
    a := 0;
    // The function Internal.solve evaluates epsilon_ntuZ at NTU=x_min-1e-10 and NTU=x_max+1e-10
    // when it solves iteratively epsilon_ntuZ for ntu
    // Therefore, we set x_min=1.5*1e-10 to prevent computing NTU^(-0.22)=(-1e-10)^(-0.22).
    NTU :=Modelica.Math.Nonlinear.solveOneNonlinearEquation(
      f=function epsilon_ntuZ_crossFlowUnmixed(eps=eps, Z=Z),
      u_min=1.5*1e-10,
      u_max=1e6);
  elseif (flowRegime == Integer(f.CrossFlowCMinUnmixedCMaxMixed)) then
    // cross flow, (single pass), CMax mixed, CMin unmixed. (Coil with one row.)
    a := smooth(1, if Z > 0.03 then Z else
      IBPSA.Utilities.Math.Functions.smoothMin(
      x1=0.02,
      x2=Z,
      deltaX=0.01));
    NTU := -Modelica.Math.log(1+(Modelica.Math.log(1-eps*a)/a));
  elseif (flowRegime == Integer(f.CrossFlowCMinMixedCMaxUnmixed)) then
    // cross flow, (single pass), CMin mixed, CMax unmixed.
    a := smooth(1, if Z > 0.03 then Z else
      IBPSA.Utilities.Math.Functions.smoothMin(
      x1=0.02,
      x2=Z,
      deltaX=0.01));
    NTU := -Modelica.Math.log(1+Z*Modelica.Math.log(1-eps))/Z;
  elseif (flowRegime == Integer(f.ConstantTemperaturePhaseChange)) then
    // one side is experiencing constant temperature phase change
    // Z is unused
    a := 0;
    NTU := -Modelica.Math.log((1-eps));
  else
    a := 0;
    NTU := 0;
    assert(Integer(f.ParallelFlow) <= flowRegime and
           flowRegime <= Integer(f.ConstantTemperaturePhaseChange),
           "Flow regime is not implemented.");
  end if

  ;
end ntu_epsilonZ;

within BuildSysPro.IBPSA.Fluid.HeatExchangers.BaseClasses;
partial model PartialEffectiveness
  "Partial model to implement heat exchangers based on effectiveness model"
  extends Fluid.Interfaces.StaticFourPortHeatMassExchanger(
    prescribedHeatFlowRate1=true,
    prescribedHeatFlowRate2=true,
    show_T=false);

  Medium1.Temperature T_in1 = if allowFlowReversal1 then
    fra_a1 * Medium1.temperature(state_a1_inflow) + fra_b1 * Medium1.temperature(state_b1_inflow) else
    Medium1.temperature(state_a1_inflow)
    "Inlet temperature medium 1";
  Medium2.Temperature T_in2 = if allowFlowReversal2 then
    fra_a2 * Medium2.temperature(state_a2_inflow) + fra_b2 * Medium2.temperature(state_b2_inflow) else
    Medium2.temperature(state_a2_inflow)
    "Inlet temperature medium 2";
  Modelica.Units.SI.ThermalConductance C1_flow=abs(m1_flow)*(if
      allowFlowReversal1 then fra_a1*Medium1.specificHeatCapacityCp(
      state_a1_inflow) + fra_b1*Medium1.specificHeatCapacityCp(state_b1_inflow)
       else Medium1.specificHeatCapacityCp(state_a1_inflow))
    "Heat capacity flow rate medium 1";
  Modelica.Units.SI.ThermalConductance C2_flow=abs(m2_flow)*(if
      allowFlowReversal2 then fra_a2*Medium2.specificHeatCapacityCp(
      state_a2_inflow) + fra_b2*Medium2.specificHeatCapacityCp(state_b2_inflow)
       else Medium2.specificHeatCapacityCp(state_a2_inflow))
    "Heat capacity flow rate medium 2";
  Modelica.Units.SI.ThermalConductance CMin_flow(min=0) = min(C1_flow, C2_flow)
    "Minimum heat capacity flow rate";
  Modelica.Units.SI.HeatFlowRate QMax_flow=CMin_flow*(T_in2 - T_in1)
    "Maximum heat flow rate into medium 1";
protected
  parameter Real delta=1E-3 "Parameter used for smoothing";

  parameter Modelica.Units.SI.SpecificHeatCapacity cp1_default(fixed=false)
    "Specific heat capacity of medium 1 at default medium state";
  parameter Modelica.Units.SI.SpecificHeatCapacity cp2_default(fixed=false)
    "Specific heat capacity of medium 2 at default medium state";
  parameter Modelica.Units.SI.ThermalConductance CMin_flow_small(fixed=false)
    "Small value for smoothing of minimum heat capacity flow rate";
  Real fra_a1(min=0, max=1) = if allowFlowReversal1
    then Modelica.Fluid.Utilities.regStep(
      m1_flow,
      1,
      0,
      m1_flow_small)
    else 1
    "Fraction of incoming state taken from port a1 (used to avoid excessive calls to regStep)";
  Real fra_b1(min=0, max=1) = if allowFlowReversal1
    then 1-fra_a1
    else 0
    "Fraction of incoming state taken from port b1 (used to avoid excessive calls to regStep)";
  Real fra_a2(min=0, max=1) = if allowFlowReversal2
    then Modelica.Fluid.Utilities.regStep(
      m2_flow,
      1,
      0,
      m2_flow_small)
    else 1
    "Fraction of incoming state taken from port a2 (used to avoid excessive calls to regStep)";
  Real fra_b2(min=0, max=1) = if allowFlowReversal2
    then 1-fra_a2
    else 0
    "Fraction of incoming state taken from port b2 (used to avoid excessive calls to regStep)";
initial equation
  cp1_default = Medium1.specificHeatCapacityCp(Medium1.setState_pTX(
    Medium1.p_default,
    Medium1.T_default,
    Medium1.X_default));
  cp2_default = Medium2.specificHeatCapacityCp(Medium2.setState_pTX(
    Medium2.p_default,
    Medium2.T_default,
    Medium2.X_default));
  CMin_flow_small = min(m1_flow_small*cp1_default, m2_flow_small*cp2_default)

  ;
end PartialEffectiveness;

within BuildSysPro.IBPSA.Fluid.HeatExchangers.BaseClasses;
partial model PartialPrescribedOutlet
  "Ideal heater, cooler, humidifier or dehumidifier with prescribed outlet conditions"
  extends IBPSA.Fluid.Interfaces.PartialTwoPortInterface;
  extends IBPSA.Fluid.Interfaces.TwoPortFlowResistanceParameters(final
      computeFlowResistance=(abs(dp_nominal) > Modelica.Constants.eps));

  constant Boolean homotopyInitialization = true "= true, use homotopy method"
    ;

  // Dynamics
  parameter Modelica.Fluid.Types.Dynamics energyDynamics=Modelica.Fluid.Types.Dynamics.SteadyState
    "Type of energy balance: dynamic (3 initialization options) or steady state"
    ;

  parameter Modelica.Units.SI.Time tau(min=0) = 10
    "Time constant at nominal flow rate (used if energyDynamics not equal Modelica.Fluid.Types.Dynamics.SteadyState)"
    ;

protected
  IBPSA.Fluid.FixedResistances.PressureDrop preDro(
    redeclare final package Medium = Medium,
    final m_flow_nominal=m_flow_nominal,
    final deltaM=deltaM,
    final allowFlowReversal=allowFlowReversal,
    final show_T=false,
    final from_dp=from_dp,
    final linearized=linearizeFlowResistance,
    final homotopyInitialization=homotopyInitialization,
    final dp_nominal=dp_nominal) "Flow resistance"
    ;

  IBPSA.Fluid.Interfaces.PrescribedOutlet outCon(
    redeclare final package Medium = Medium,
    final energyDynamics=energyDynamics,
    final allowFlowReversal=allowFlowReversal,
    final m_flow_small=m_flow_small,
    final show_T=false,
    final m_flow_nominal=m_flow_nominal,
    final tau=tau) "Model to set outlet conditions"
    ;
initial equation
  assert(homotopyInitialization, "In " + getInstanceName() +
    ": The constant homotopyInitialization has been modified from its default value. This constant will be removed in future releases.",
    level = AssertionLevel.warning);

equation
  connect(port_a, preDro.port_a) ;
  connect(preDro.port_b,outCon. port_a) ;
  connect(outCon.port_b, port_b) 
  ;
end PartialPrescribedOutlet;

within BuildSysPro.IBPSA.Fluid.HeatExchangers.BaseClasses;
function prandtlNumberWater "Returns the Prandtl number for water"
  input Modelica.Units.SI.Temperature T "Thermodynamic state record";
    output Real Pr "Prandtl number";
algorithm
        Pr := ((2.55713*10^(-7))*T^4-0.000350293*T^3+0.180259651*T^2-
        41.34104323*T+3571.372195);
        //Equation is a fourth order polynomial fit to data from Fundamentals
        //of Heat and Mass Transfer (Fourth Edition), Frank Incropera & David DeWitt,
        //John Wiley & Sons, 1996

;
end prandtlNumberWater;

within BuildSysPro.IBPSA.Fluid.HeatExchangers.BaseClasses;
model WetCoilDryRegime
  "Fully dry coil model"

  // - water
  input Modelica.Units.SI.ThermalConductance UAWat "UA for water side";
  input Modelica.Units.SI.MassFlowRate mWat_flow "Mass flow rate for water";
  input Modelica.Units.SI.MassFlowRate mWatNonZer_flow(min=Modelica.Constants.eps)
    "Mass flow rate for water, bounded away from zero";

  input Modelica.Units.SI.SpecificHeatCapacity cpWat
    "Specific heat capacity of water";
  input Modelica.Units.SI.Temperature TWatIn "Water temperature at inlet";
  // -- air
  input Modelica.Units.SI.ThermalConductance UAAir "UA for air side";
  input Modelica.Units.SI.MassFlowRate mAir_flow(min=Modelica.Constants.eps)
    "Mass flow rate of air";
  input Modelica.Units.SI.MassFlowRate mAirNonZer_flow(min=Modelica.Constants.eps)
    "Mass flow rate for air, bounded away from zero";
  input Modelica.Units.SI.SpecificHeatCapacity cpAir
    "Specific heat capacity of moist air at constant pressure";
  input Modelica.Units.SI.Temperature TAirIn "Temperature of air at inlet";
  // -- misc.
  input IBPSA.Fluid.Types.HeatExchangerFlowRegime cfg
    "Flow regime of the heat exchanger";
  input Modelica.Units.SI.MassFlowRate mAir_flow_nominal
    "Nominal mass flow rate for air";
  input Modelica.Units.SI.MassFlowRate mWat_flow_nominal
    "Nominal mass flow rate for water";

  parameter Real delta = 1E-3 "Small value used for smoothing";

  output Modelica.Units.SI.HeatFlowRate QTot_flow
    "Heat transferred from water to air";
  output Modelica.Units.SI.Temperature TWatOut "Temperature of water at outlet";
  output Modelica.Units.SI.Temperature TAirOut
    "Temperature of air at the outlet";
  output Real eps(min=0, max=1, unit="1")
    "Effectiveness for heat exchanger";
  Modelica.Units.SI.ThermalConductance CWat_flow=mWat_flow*cpWat
    "Capacitance rate of water";
  Modelica.Units.SI.ThermalConductance CAir_flow=mAir_flow*cpAir
    "Capacitance rate of air";
  Modelica.Units.SI.ThermalConductance CMin_flow_nominal=min(mAir_flow_nominal*
      cpAir, mWat_flow_nominal*cpWat) "Minimum capacity rate";
  Modelica.Units.SI.ThermalConductance CMax_flow_nominal=max(mAir_flow_nominal*
      cpAir, mWat_flow_nominal*cpWat) "Maximum capacity rate";
  Modelica.Units.SI.ThermalConductance CMin_flow=
      IBPSA.Utilities.Math.Functions.smoothMin(
      x1=CAir_flow,
      x2=CWat_flow,
      deltaX=1E-3*(CMax_flow_nominal - CMin_flow_nominal))
    "Minimum capacity rate";
  Modelica.Units.SI.ThermalConductance UA "Overall heat transfer coefficient";
  output Modelica.Units.SI.Temperature TSurAirOut
    "Surface Temperature at air outlet";
equation
  UA = 1/ (1 / UAAir + 1 / UAWat);

  eps=epsilon_C(
    UA=UA,
    C1_flow=CWat_flow,
    C2_flow=CAir_flow,
    flowRegime=Integer(cfg),
    CMin_flow_nominal= CMin_flow_nominal,
    CMax_flow_nominal=CMax_flow_nominal,
    delta= delta);

  QTot_flow = eps*CMin_flow*(TAirIn-TWatIn);
  TAirOut=TAirIn-QTot_flow/(mAirNonZer_flow*cpAir);
  TWatOut=TWatIn+QTot_flow/(mWatNonZer_flow*cpWat);
  TSurAirOut = (TAirOut * UAAir + TWatIn * UAWat) / (UAAir + UAWat)

  ;
end WetCoilDryRegime;

