    ;
  IBPSA.Fluid.Sources.Boundary_pT sou_2(
    redeclare package Medium = Medium2,
    nPorts=1,
    use_p_in=false,
    use_T_in=false,
    p(displayUnit="Pa") = 101625,
    T=T_a2_nominal) "Boundary condition"
    ;
  IBPSA.Fluid.Sources.Boundary_pT sin_1(
    redeclare package Medium = Medium1,
    use_p_in=false,
    p=300000,
    T=293.15,
    nPorts=1) "Boundary condition"
    ;
  IBPSA.Fluid.Sources.Boundary_pT sou_1(
    redeclare package Medium = Medium1,
    p=300000 + 9000,
    nPorts=1,
    use_T_in=false,
    T=T_a1_nominal) "Boundary condition"
    ;
  IBPSA.Fluid.Sensors.TemperatureTwoPort temSen(redeclare package
      Medium =
        Medium2, m_flow_nominal=m2_flow_nominal) "Temperature sensor"
    ;
  IBPSA.Fluid.Actuators.Valves.TwoWayEqualPercentage val(
    redeclare package Medium = Medium1,
    l=0.005,
    m_flow_nominal=m1_flow_nominal,
    dpFixed_nominal=2000 + 3000,
    dpValve_nominal=6000) "Valve"
    ;
  IBPSA.Controls.Continuous.LimPID P(
    Ti=30,
    k=0.1,
    Td=1) "Controller"
    ;
  Modelica.Blocks.Sources.Pulse TSet(
    amplitude=5,
    period=3600,
    offset=273.15 + 22) "Temperature setpoint"
    ;
  IBPSA.Fluid.HeatExchangers.DryCoilEffectivenessNTU hex(
    redeclare package Medium1 = Medium1,
    redeclare package Medium2 = Medium2,
    show_T=true,
    m1_flow_nominal=m1_flow_nominal,
    m2_flow_nominal=m2_flow_nominal,
    Q_flow_nominal=m1_flow_nominal*4200*(T_a1_nominal - T_b1_nominal),
    configuration=IBPSA.Fluid.Types.HeatExchangerConfiguration.CounterFlow,
    T_a1_nominal=T_a1_nominal,
    T_a2_nominal=T_a2_nominal,
    dp1_nominal(displayUnit="Pa") = 0,
    dp2_nominal(displayUnit="Pa") = 200 + 100) "Heat exchanger"
    ;

equation
  connect(val.port_b, hex.port_a1) ;
  connect(sou_1.ports[1], val.port_a) ;
  connect(sou_2.ports[1], hex.port_a2) ;
  connect(hex.port_b2, temSen.port_a) ;
  connect(TSet.y, P.u_s) ;
  connect(temSen.T, P.u_m) ;
  connect(P.y, val.y) ;
  connect(hex.port_b1, sin_1.ports[1]) ;
  connect(temSen.port_b, sin_2.ports[1]) 
  ;
end DryCoilEffectivenessNTUPControl;

