within BuildSysPro.IBPSA.Fluid.HeatExchangers.Examples.BaseClasses;
partial model EffectivenessNTUMassFlow
  "Partial model of epsilon-NTU coil that tests variable mass flow rates"
  package Medium1 = IBPSA.Media.Water "Medium model for water";
  package Medium2 = IBPSA.Media.Air
    "Medium model for air";
  parameter Modelica.Units.SI.Temperature T_a1_nominal=5 + 273.15
    "Nominal water inlet temperature";
  parameter Modelica.Units.SI.Temperature T_b1_nominal=10 + 273.15
    "Nominal water outlet temperature";
  parameter Modelica.Units.SI.Temperature T_a2_nominal=30 + 273.15
    "Nominal air inlet temperature";
  parameter Modelica.Units.SI.Temperature T_b2_nominal=15 + 273.15
    "Nominal air outlet temperature";
  parameter Modelica.Units.SI.HeatFlowRate Q_flow_nominal=m1_flow_nominal*4200*
      (T_a1_nominal - T_b1_nominal) "Nominal heat transfer";
  parameter Modelica.Units.SI.MassFlowRate m1_flow_nominal=0.1
    "Nominal mass flow rate medium 1";
  parameter Modelica.Units.SI.MassFlowRate m2_flow_nominal=m1_flow_nominal*4200
      /1000*(T_a1_nominal - T_b1_nominal)/(T_b2_nominal - T_a2_nominal)
    "Nominal mass flow rate medium 2";
  IBPSA.Fluid.Sources.MassFlowSource_T sin_2(
    redeclare package Medium = Medium2,
    T=T_a2_nominal,
    use_m_flow_in=true) "Sink for air"
    ;
  IBPSA.Fluid.Sources.Boundary_pT sou_2(
    redeclare package Medium = Medium2,
    T=T_a2_nominal,
    X={0.02,1 - 0.02},
    use_T_in=true,
    use_X_in=true) "Source for air"
    ;
  IBPSA.Fluid.Sources.MassFlowSource_T sin_1(
    redeclare package Medium = Medium1,
    T=T_a1_nominal,
    use_m_flow_in=true) "Sink for water"
    ;
  IBPSA.Fluid.Sources.Boundary_pT sou_1(
    redeclare package Medium = Medium1,
    use_T_in=false,
    T=T_a1_nominal) "Source for water"
    ;

  Modelica.Blocks.Sources.Constant relHum(k=0.8) "Relative humidity"
    ;
  IBPSA.Utilities.Psychrometrics.X_pTphi x_pTphi(use_p_in=false)
    ;
  Modelica.Blocks.Sources.Constant temSou_2(k=T_a2_nominal)
    "Temperature boundary condition"
    ;
  Modelica.Blocks.Math.Gain mWat_flow(k=-m1_flow_nominal)
    "Water mass flow rate"
    ;
  Modelica.Blocks.Sources.TimeTable mWatGai(
    table=[0,1; 0.1,1; 0.2,0.01; 0.3,0.01],
    timeScale=3600)
    "Gain for water mass flow rate"
    ;
  Modelica.Blocks.Sources.TimeTable mAirGai(
    table=[0,1; 0.5,1; 0.6,-1; 0.7,0; 1,0],
    timeScale=3600)
    "Gain for air mass flow rate"
    ;
  Modelica.Blocks.Math.Gain mAir_flow(k=-m2_flow_nominal) "Air mass flow rate"
    ;
equation
  connect(x_pTphi.X, sou_2.X_in) ;
  connect(relHum.y, x_pTphi.phi) ;
  connect(temSou_2.y, x_pTphi.T) ;
  connect(temSou_2.y, sou_2.T_in) ;
  connect(mWatGai.y, mWat_flow.u) ;
  connect(mWat_flow.y, sin_1.m_flow_in) ;
  connect(mAirGai.y, mAir_flow.u) ;
  connect(mAir_flow.y, sin_2.m_flow_in) 
  ;
end EffectivenessNTUMassFlow;

within BuildSysPro.IBPSA.Fluid.HeatExchangers.Examples.BaseClasses;
partial model Heater "Base class for example model for the heater and cooler"

  replaceable package Medium =
      Modelica.Media.Interfaces.PartialMedium
    "Medium model";

  parameter Modelica.Units.SI.Volume V=6*6*2.7 "Volume";

  parameter Modelica.Units.SI.MassFlowRate m_flow_nominal=V*1.2*6/3600
    "Nominal mass flow rate";
  parameter Modelica.Units.SI.HeatFlowRate Q_flow_nominal=30*6*6
    "Nominal heat loss of the room";

  IBPSA.Fluid.MixingVolumes.MixingVolume vol(
    redeclare package Medium = Medium,
    T_start=289.15,
    V=V,
    energyDynamics=Modelica.Fluid.Types.Dynamics.FixedInitial,
    m_flow_nominal=m_flow_nominal,
    mSenFac=2,
    nPorts=3) ;
  Modelica.Thermal.HeatTransfer.Components.ThermalConductor theCon(
    G=Q_flow_nominal/20) "Thermal conductance to the outside"
    ;
  Modelica.Thermal.HeatTransfer.Sources.PrescribedTemperature TBou
    "Fixed temperature boundary condition"
    ;
  Modelica.Thermal.HeatTransfer.Sensors.TemperatureSensor TVol
    "Sensor for volume temperature"
    ;
  IBPSA.Fluid.Movers.FlowControlled_m_flow mov(
    redeclare package Medium = Medium,
    m_flow_nominal=m_flow_nominal,
    addPowerToMedium=false,
    energyDynamics=Modelica.Fluid.Types.Dynamics.SteadyState) "Fan or pump"
    ;
  Modelica.Blocks.Sources.RealExpression TOut(
    y(final unit="K", displayUnit="degC")=
      273.15 + 16 - 5*cos(time/86400*2*Modelica.Constants.pi))
    "Outdoor temperature"
    ;
  Modelica.Blocks.Sources.Pulse TSet(
    amplitude=4,
    period=86400,
    offset=273.15 + 16,
    startTime=7*3600,
    y(final unit="K", displayUnit="degC")) "Setpoint for room temperature"
    ;
  Controls.Continuous.LimPID conPI(
    k=1,
    yMax=1,
    yMin=0,
    Ti=120) "Controller"
    ;
  Modelica.Blocks.Sources.Constant mFan_flow(k=m_flow_nominal)
    "Mass flow rate of the fan"
    ;
  IBPSA.Fluid.Sources.Boundary_pT bou(redeclare package Medium = Medium, nPorts=
       1)
    "Fixed pressure boundary condition, required to set a reference pressure"
    ;
  Sensors.TemperatureTwoPort THeaOut(
    redeclare package Medium = Medium,
    m_flow_nominal=m_flow_nominal,
    T_start=289.15) "Outlet temperature of the heater"
    ;
  FixedResistances.PressureDrop res(
    redeclare package Medium = Medium,
    m_flow_nominal=m_flow_nominal,
    dp_nominal=100,
    linearized=true) "Flow resistance to decouple pressure state from boundary"
    ;
equation
  connect(theCon.port_a, TBou.port) ;
  connect(vol.heatPort, theCon.port_b) ;
  connect(vol.heatPort, TVol.port) ;
  connect(TOut.y, TBou.T) ;
  connect(TVol.T, conPI.u_m) ;
  connect(TSet.y, conPI.u_s) ;
  connect(mFan_flow.y,mov. m_flow_in) ;
  connect(THeaOut.port_b, vol.ports[1]) ;
  connect(vol.ports[2],mov. port_a) ;
  connect(res.port_b, bou.ports[1])
    ;
  connect(res.port_a, vol.ports[3]) 
  ;
end Heater;

