  IBPSA.Fluid.HeatPumps.Compressors.BaseClasses.TemperatureProtection temPro(TConMax=
        313.15, TEvaMin=278.15) "Temperature protection block"
    ;
  Modelica.Blocks.Sources.Cosine TEva(
