    ;
  connect(heaPum.port_b1, sin1.ports[1]) ;
  connect(heaPum.port_a1, loa.ports[1])
    ;
  connect(heaPum.port_b2, sin2.ports[1]) ;
  connect(sin2.ports[2], heaPum1.port_b2) ;
  connect(mLoa.y, loa.m_flow_in) ;
