  connect(TLoa.y, loa1.T_in) ;
  connect(TLoa.y, loa.T_in) ;
  connect(loa1.ports[1], heaPum1.port_a1) ;
  connect(heaPum1.port_b1, sin1.ports[2]) ;
  connect(N.y, realToInteger.u)
    ;
  connect(realToInteger.y, heaPum.stage) ;
