  connect(vol2.ports[2], senSpeEnt.port_a) ;
  connect(senSpeEnt.port_b, senMasFlo.port_a) ;
  connect(hSol.y,cheSpeEnt. u1) ;
  connect(mFloSol.y,cheMasFlo. u1) ;
  connect(senMasFra.port_b, sin.ports[1]) 
