within BuildSysPro.IBPSA.Fluid.Movers.Examples;
model SpeedControlled_y_pumpCurves
  "Pumps that illustrates the use of the pump curves"
  extends Modelica.Icons.Example;
  package Medium = IBPSA.Media.Water "Medium model";

  // For OpenModelica, changed m_flow_nominal to a constant. Otherwise
  // the translation fails with "Error: Cyclically dependent parameters found"
  constant Modelica.Units.SI.MassFlowRate m_flow_nominal=0.5
    "Nominal mass flow rate";
  // For OpenModelica, changed dp_nominal to a constant. Otherwise
  // the compilation fails.
  constant Modelica.Units.SI.PressureDifference dp_nominal=10000
    "Nominal pressure";

   model pumpModel = IBPSA.Fluid.Movers.SpeedControlled_y (
      redeclare package Medium = Medium,
      use_inputFilter=false,
      energyDynamics=Modelica.Fluid.Types.Dynamics.SteadyState,
      per(pressure(V_flow=2/1000*m_flow_nominal*{0.2,0.4,0.6,0.8}, dp=
              dp_nominal*{0.9,0.85,0.6,0.2})))
    "Declaration of pump model";

  pumpModel pum(
    inputType=IBPSA.Fluid.Types.InputType.Constant,
    per(constantSpeed=1)) "Pump"
    ;
  pumpModel pum1(
    inputType=IBPSA.Fluid.Types.InputType.Constant,
    per(constantSpeed=0.5)) "Pump"
    ;
  pumpModel pum2(
    inputType=IBPSA.Fluid.Types.InputType.Constant,
    per(constantSpeed=0.05)) "Pump"
    ;
  pumpModel pum3(
    inputType=IBPSA.Fluid.Types.InputType.Constant,
    per(constantSpeed=0.01)) "Pump"
    ;

  Modelica.Blocks.Sources.Ramp y(
    offset=1,
    duration=0.5,
    startTime=0.25,
    height=-0.999)
               "Input signal"
                 ;
  IBPSA.Fluid.Sources.Boundary_pT sou(
    redeclare package Medium = Medium,
    use_p_in=false,
    p=300000,
    T=293.15,
    nPorts=4) ;

  IBPSA.Fluid.Sources.Boundary_pT sou1(
    redeclare package Medium = Medium,
    use_p_in=false,
    nPorts=4,
    p(displayUnit="Pa") = 300000,
    T=293.15) ;
  IBPSA.Fluid.Actuators.Valves.TwoWayLinear dp1(
    redeclare package Medium = Medium,
    m_flow_nominal=m_flow_nominal,
    dpValve_nominal=0.01*dp_nominal,
    use_inputFilter=false) "Pressure drop"
    ;

  IBPSA.Fluid.Actuators.Valves.TwoWayLinear dp2(
    redeclare package Medium = Medium,
    m_flow_nominal=m_flow_nominal,
    dpValve_nominal=0.01*dp_nominal,
    use_inputFilter=false) "Pressure drop"
    ;

  IBPSA.Fluid.Actuators.Valves.TwoWayLinear dp3(
    redeclare package Medium = Medium,
    m_flow_nominal=m_flow_nominal,
    dpValve_nominal=0.01*dp_nominal,
    use_inputFilter=false) "Pressure drop"
    ;
  IBPSA.Fluid.Actuators.Valves.TwoWayLinear dp4(
    redeclare package Medium = Medium,
    m_flow_nominal=m_flow_nominal,
    dpValve_nominal=0.01*dp_nominal,
    use_inputFilter=false) "Pressure drop"
    ;
equation
  connect(dp1.port_b, pum.port_a)      ;
  connect(dp1.port_a, sou.ports[1]) ;
  connect(y.y, dp1.y) ;
  connect(dp2.port_b, pum1.port_a)     ;
  connect(y.y,dp2. y) ;
  connect(sou.ports[2], dp2.port_a) ;
  connect(dp3.port_b, pum2.port_a)     ;
  connect(y.y,dp3. y) ;
  connect(dp3.port_a, sou.ports[3]) ;
  connect(dp4.port_b, pum3.port_a)     ;
  connect(y.y,dp4. y) ;
  connect(dp4.port_a, sou.ports[4]) ;
  connect(pum3.port_b, sou1.ports[1]) ;
  connect(pum2.port_b, sou1.ports[2]) ;

  connect(pum1.port_b, sou1.ports[3]) ;
  connect(pum.port_b, sou1.ports[4]) 
  ;
end SpeedControlled_y_pumpCurves;

