   ;
  connect(H_a_flow.H_flow, str.H_flow[1]) ;
  connect(H_vol_flow[1:nSeg-1].H_flow, str.H_flow[2:nSeg])   ;
  connect(H_b_flow.H_flow, str.H_flow[nSeg + 1]) ;
  connect(str.heatPort, vol.heatPort)    ;
  connect(port_a, str.fluidPort[1]) ;
