within BuildSysPro.IBPSA.Media.Refrigerants.R410A;
function pressureSatVap_T
  "Function that calculates the pressure of saturated R410A vapor based on temperature"
  input Modelica.Units.SI.Temperature T "Temperature of refrigerant";
  output Modelica.Units.SI.AbsolutePressure p
    "Pressure of saturated refrigerant vapor";

protected
  final Real a[:] = {-1.440004, -6.865265, -0.5354309, -3.749023, -3.521484, -7.75}
    "Coefficients for polynomial equation";

  final Real x0 = 0.2086902
    "x0 for saturation pressure of refrigerant vapor";

  Real x
    "Independent variable";

algorithm
  // Independent variable
  x := IBPSA.Utilities.Math.Functions.smoothMax(
    1 - T/TCri,
    1e-4,
    5e-3) - x0;
  // Pressure of saturated refrigerant vapor
  p := pCri*Modelica.Math.exp(TCri/T*IBPSA.Utilities.Math.Functions.polynomial(
    a=a, x=x))

;
end pressureSatVap_T;

within BuildSysPro.IBPSA.Media.Refrigerants.R410A;
function pressureVap_Tv
"Function that calculates the pressure R410A vapor based on temperature and specific volume"
  input Modelica.Units.SI.Temperature T "Temperature of refrigerant";
  input Modelica.Units.SI.SpecificVolume v "Specific volume of refrigerant";
  output Modelica.Units.SI.AbsolutePressure p "Pressure of refrigerant vapor";

protected
  Modelica.Units.SI.SpecificVolume v_abs "Smoothed specific volume";

algorithm
  v_abs := IBPSA.Utilities.Math.Functions.smoothMax(
    v,
    1.01*b,
    0.01*b);

  p := R*T/(v_abs-b);
  for i in 1:size(A, 1) loop
    p := p + (A[i] + B[i]*T + C[i]*Modelica.Math.exp(-k*T/TCri))/(v_abs - b)^(i+1);
  end for

;
end pressureVap_Tv;

within BuildSysPro.IBPSA.Media.Refrigerants.R410A;
function specificIsobaricHeatCapacityVap_Tv
  "Function that calculates the specific isobaric heat capacity of R410A vapor based on temperature and specific volume"
  input Modelica.Units.SI.Temperature T "Temperature of refrigerant";
  input Modelica.Units.SI.SpecificVolume v "Specific volume of refrigerant";
  output Modelica.Units.SI.SpecificHeatCapacity cp
    "Specific isobaric heat capacity";

protected
  Real dpdT
    "First derivative w.r.t. temperature of the Martin-Hou equation";

  Real dpdv
    "First derivative w.r.t. specific volume of the Martin-Hou equation";

  Modelica.Units.SI.SpecificHeatCapacity cv "Specific isochoric heat capacity";

algorithm
  cv := IBPSA.Media.Refrigerants.R410A.specificIsochoricHeatCapacityVap_Tv(T, v);
  dpdT := IBPSA.Media.Refrigerants.R410A.dPressureVap_dTemperature_Tv(T, v);
  dpdv := IBPSA.Media.Refrigerants.R410A.dPressureVap_dSpecificVolume_Tv(T, v);

  cp := cv - T * dpdT^2 / dpdv

;
end specificIsobaricHeatCapacityVap_Tv;

within BuildSysPro.IBPSA.Media.Refrigerants.R410A;
function specificIsochoricHeatCapacityVap_Tv
  "Function that calculates the specific isochoric heat capacity of R410A vapor
  based on temperature and specific volume"
  input Modelica.Units.SI.Temperature T "Temperature of refrigerant";
  input Modelica.Units.SI.SpecificVolume v "Specific volume of refrigerant";
  output Modelica.Units.SI.SpecificHeatCapacity cv
    "Specific isochoric heat capacity";

protected
  Real a[:] = {2.676087e-1, 2.115353e-3, -9.848184e-7, 6.493781e-11}
    "Coefficients for ideal gas specific isobaric heat capacity";

  Real integral_of_d2pdT2
    "Integral over v of the second derivative w.r.t. temperature of the Martin-Hou equation";

  Modelica.Units.SI.SpecificHeatCapacity cpo
    "Ideal gas specific isobaric heat capacity";

  Modelica.Units.SI.SpecificHeatCapacity cvo
    "Ideal gas specific isochoric heat capacity";

algorithm
  // Ideal gas isobaric heat capacity from polynomial equation
  cpo := 1.0e3*IBPSA.Utilities.Math.Functions.polynomial(a=a, x=T);
  cvo := cpo - R;

  // Integral of second derivative of pressure w.r.t. temperature
  integral_of_d2pdT2 := (k/TCri)^2 * Modelica.Math.exp(-k*T/TCri) * sum(C[i]/(i*(v - b)^(i)) for i in 1:size(C, 1));

  cv := cvo - T * integral_of_d2pdT2

;
end specificIsochoricHeatCapacityVap_Tv;

within BuildSysPro.IBPSA.Media.Refrigerants.R410A;
function specificVolumeVap_pT
  "Function that calculates the specific volume R410A vapor based on pressure and temperature"
  input Modelica.Units.SI.AbsolutePressure p "Pressure of refrigerant vapor";
  input Modelica.Units.SI.Temperature T "Temperature of refrigerant";
  output Modelica.Units.SI.SpecificVolume v "Specific volume of refrigerant";

protected
  Modelica.Units.SI.SpecificVolume dv "Error on specific volume of refrigerant";

  Modelica.Units.SI.Pressure dp "Error on pressure of refrigerant";

  Real dpdv( final unit = "(Pa.kg)/m3") "Partial derivative dp/dv";

  Integer m "Counter";

algorithm

  // Initial guess of specific volume
  v := R*T/p + b;
  dv := 1e99;
  m := 0;
  while abs(dv/v) > 1e-10 loop
    assert(m < 1E3,
      "Failed to converge in IBPSA.Media.Refrigerants.R410A.specificVolumeVap_pT");
    m := m + 1;

    // Evaluate first derivative of pressure w.r.t. specific volume
    dpdv := IBPSA.Media.Refrigerants.R410A.dPressureVap_dSpecificVolume_Tv(T, v);
    // Error on pressure
    dp := p - IBPSA.Media.Refrigerants.R410A.pressureVap_Tv(T, v);
    // Corresponding linear adjustment of specific volume
    dv := dp/dpdv;
    v := v + dv;

end while

;
end specificVolumeVap_pT;

within BuildSysPro.IBPSA.Media.Refrigerants.Validation;
model R410A_dSpecificVolumeVap_pT
  "Validation of the derivatives of the specific volume with regards to p and T"
  extends Modelica.Icons.Example;

  parameter Modelica.Units.SI.AbsolutePressure p=400e3
    "Pressure of refrigerant vapor";

  parameter Modelica.Units.SI.Temperature T=273.15 "Temperature of refrigerant";

  parameter Real dp(final unit="Pa") = 1.0
    "Delta of pressure of refrigerant vapor";

  parameter Real dT(final unit="K") = 0.01
    "Delta of temperature of refrigerant";

  Real dvdp(
    final unit="m3/(kg.Pa)")
     "Derivative of specific volume with regards to pressure";

  Real dvdT(
    final unit="m3/(kg.K)")
     "Derivative of specific volume with regards to temperature";

  Real dvdp_num(
    final unit="m3/(kg.Pa)")
     "Numerical derivative ofspecific volume with regards to pressure";

  Real dvdT_num(
    final unit="m3/(kg.K)")
     "Numerical derivative of specific volume with regards to temperature";

protected
  Real dv_p(
    final unit="m3/(kg)")
    "Delta of specific volume of refrigerant with regards to pressure";

  Real dv_T(
    final unit="m3/(kg)")
    "Delta of specific volume of refrigerant with regards to temperature";

  Real dv_p_num(
    final unit="m3/(kg)")
    "Numerical delta of specific volume of refrigerant with regards to
    pressure";

  Real dv_T_num(
    final unit="m3/(kg)")
    "Numerical delta of specific volume of refrigerant with regards to
    temperature";

  constant Modelica.Units.SI.Time oneSec=1.0
    "Unit time variable for unit conversion of time derivatives";

equation

  // Analytical derivatives
  dv_p = IBPSA.Media.Refrigerants.R410A.dSpecificVolumeVap_pT(
    p,
    T,
    dp/oneSec,
    0.0)*oneSec;

  dv_T = IBPSA.Media.Refrigerants.R410A.dSpecificVolumeVap_pT(
    p,
    T,
    0.0,
    dT/oneSec)*oneSec;

  dvdp = dv_p / dp;

  dvdT = dv_T / dT;

  // Numerical derivatives
  dv_p_num = IBPSA.Media.Refrigerants.R410A.specificVolumeVap_pT(p + 0.5*dp, T)
     - IBPSA.Media.Refrigerants.R410A.specificVolumeVap_pT(p - 0.5*dp, T);

  dv_T_num = IBPSA.Media.Refrigerants.R410A.specificVolumeVap_pT(p, T + 0.5*dT)
     - IBPSA.Media.Refrigerants.R410A.specificVolumeVap_pT(p, T - 0.5*dT);

  dvdp_num = dv_p / dp;

  dvdT_num = dv_T / dT
  ;
end R410A_dSpecificVolumeVap_pT;

