within BuildSysPro.IBPSA.Utilities.Psychrometrics;
block TWetBul_TDryBulPhi
  "Model to compute the wet bulb temperature based on relative humidity"
  extends Modelica.Blocks.Icons.Block;
  replaceable package Medium =
    Modelica.Media.Interfaces.PartialCondensingGases "Medium model"
    ;

  parameter Boolean approximateWetBulb=false
    "Set to true to approximate wet bulb temperature" ;
  Modelica.Blocks.Interfaces.RealInput TDryBul(
    start=Medium.T_default,
    final quantity="ThermodynamicTemperature",
    final unit="K",
    min=0) "Dry bulb temperature"
    ;

  Modelica.Blocks.Interfaces.RealInput phi(min=0, max=1)
    "Relative air humidity"
    ;

  Modelica.Blocks.Interfaces.RealInput p(final quantity="Pressure",
                                         final unit="Pa",
                                         min = 0) "Pressure"
    ;

  Modelica.Blocks.Interfaces.RealOutput TWetBul(
    start=Medium.T_default-2,
    final quantity="ThermodynamicTemperature",
    final unit="K",
    min=0) "Wet bulb temperature"
    ;

protected
  Modelica.Units.NonSI.Temperature_degC TDryBul_degC
    "Dry bulb temperature in degree Celsius";
  Real rh_per(min=0) "Relative humidity in percentage";
  Modelica.Units.SI.MassFraction XiDryBul
    "Water vapor mass fraction at dry bulb state";
  Modelica.Units.SI.MassFraction XiSat
    "Water vapor mass fraction at saturation";
  Modelica.Units.SI.MassFraction XiSatRefIn
    "Water vapor mass fraction at saturation, referenced to inlet mass flow rate";

equation
  if approximateWetBulb then
    TDryBul_degC = TDryBul - 273.15;
    rh_per       = 100*phi;
    TWetBul      = 273.15 + TDryBul_degC
       * Modelica.Math.atan(0.151977 * sqrt(rh_per + 8.313659))
       + Modelica.Math.atan(TDryBul_degC + rh_per)
       - Modelica.Math.atan(rh_per-1.676331)
       + 0.00391838 * rh_per^(1.5) * Modelica.Math.atan( 0.023101 * rh_per)  - 4.686035;
    XiSat    = 0;
    XiDryBul = 0;
    XiSatRefIn=0;
  else
    XiSatRefIn=(1-XiDryBul)*XiSat/(1-XiSat);
    XiSat = IBPSA.Utilities.Psychrometrics.Functions.X_pSatpphi(
      pSat=IBPSA.Utilities.Psychrometrics.Functions.saturationPressureLiquid(
        TWetBul),
      p=p,
      phi=1);
    XiDryBul = IBPSA.Utilities.Psychrometrics.Functions.X_pSatpphi(
      p=p,
      pSat=IBPSA.Utilities.Psychrometrics.Functions.saturationPressureLiquid(
        TDryBul),
      phi=phi);
    (TWetBul - IBPSA.Utilities.Psychrometrics.Constants.T_ref)*((1 - XiDryBul)*
      IBPSA.Utilities.Psychrometrics.Constants.cpAir + XiSatRefIn*IBPSA.Utilities.Psychrometrics.Constants.cpSte
       + (XiDryBul - XiSatRefIn)*IBPSA.Utilities.Psychrometrics.Constants.cpWatLiq)
      = (TDryBul - IBPSA.Utilities.Psychrometrics.Constants.T_ref)*((1 -
      XiDryBul)*IBPSA.Utilities.Psychrometrics.Constants.cpAir + XiDryBul*IBPSA.Utilities.Psychrometrics.Constants.cpSte)
       + (XiDryBul - XiSatRefIn)*IBPSA.Utilities.Psychrometrics.Constants.h_fg;

    TDryBul_degC = 0;
    rh_per       = 0;
  end if

;
end TWetBul_TDryBulPhi;

within BuildSysPro.IBPSA.Utilities.Psychrometrics;
block TWetBul_TDryBulXi
  "Model to compute the wet bulb temperature based on mass fraction"
  extends Modelica.Blocks.Icons.Block;

  replaceable package Medium =
    Modelica.Media.Interfaces.PartialCondensingGases "Medium model"                          ;

  parameter Boolean approximateWetBulb=false
    "Set to true to approximate wet bulb temperature" ;

  Modelica.Blocks.Interfaces.RealInput TDryBul(
    start=303,
    final quantity="ThermodynamicTemperature",
    final unit="K",
    min=0) "Dry bulb temperature"
    ;
  Modelica.Blocks.Interfaces.RealInput p(  final quantity="Pressure",
                                           final unit="Pa",
                                           min = 0) "Pressure"
    ;
  Modelica.Blocks.Interfaces.RealOutput TWetBul(
    start=293,
    final quantity="ThermodynamicTemperature",
    final unit="K",
    min=0) "Wet bulb temperature"
    ;
  Modelica.Blocks.Interfaces.RealInput Xi[Medium.nXi]
    "Species concentration at dry bulb temperature"
    ;

protected
  Modelica.Units.NonSI.Temperature_degC TDryBul_degC
    "Dry bulb temperature in degree Celsius";
  Real rh_per(min=0) "Relative humidity in percentage";

  Modelica.Units.SI.MassFraction XiSat(start=0.01, nominal=0.01)
    "Water vapor mass fraction at saturation";
  Modelica.Units.SI.MassFraction XiSatRefIn
    "Water vapor mass fraction at saturation, referenced to inlet mass flow rate";

 parameter Integer iWat = sum({(
   if Modelica.Utilities.Strings.isEqual(string1=Medium.substanceNames[i], string2="Water", caseSensitive=false)
   then i else 0) for i in 1:Medium.nX})
     "Index of water in medium composition vector";

initial equation
  assert(iWat > 0, "Did not find medium species 'water' in the medium model. Change medium model.");

equation
  if approximateWetBulb then
    TDryBul_degC = TDryBul - 273.15;
    rh_per = 100*p/IBPSA.Utilities.Psychrometrics.Functions.saturationPressure(
      TDryBul)*Xi[iWat]/(Xi[iWat] + IBPSA.Utilities.Psychrometrics.Constants.k_mair
      *(1 - Xi[iWat]));
    TWetBul      = 273.15 + TDryBul_degC
       * Modelica.Math.atan(0.151977 * sqrt(rh_per + 8.313659))
       + Modelica.Math.atan(TDryBul_degC + rh_per)
       - Modelica.Math.atan(rh_per-1.676331)
       + 0.00391838 * rh_per^(1.5) * Modelica.Math.atan( 0.023101 * rh_per)  - 4.686035;
    XiSat = 0;
    XiSatRefIn=0;
  else
    XiSatRefIn=(1-Xi[iWat])*XiSat/(1-XiSat);
    XiSat = IBPSA.Utilities.Psychrometrics.Functions.X_pSatpphi(
      pSat=IBPSA.Utilities.Psychrometrics.Functions.saturationPressureLiquid(
        TWetBul),
      p=p,
      phi=1);
    (TWetBul - IBPSA.Utilities.Psychrometrics.Constants.T_ref)*((1 - Xi[iWat])*
      IBPSA.Utilities.Psychrometrics.Constants.cpAir + XiSatRefIn*IBPSA.Utilities.Psychrometrics.Constants.cpSte
       + (Xi[iWat] - XiSatRefIn)*IBPSA.Utilities.Psychrometrics.Constants.cpWatLiq)
      = (TDryBul - IBPSA.Utilities.Psychrometrics.Constants.T_ref)*((1 - Xi[
      iWat])*IBPSA.Utilities.Psychrometrics.Constants.cpAir + Xi[iWat]*IBPSA.Utilities.Psychrometrics.Constants.cpSte)
       + (Xi[iWat] - XiSatRefIn)*IBPSA.Utilities.Psychrometrics.Constants.h_fg;
    TDryBul_degC = 0;
    rh_per       = 0;
  end if

;
end TWetBul_TDryBulXi;

