model TWetBul_TDryBulPhi "Model to test the wet bulb temperature computation"
  extends Modelica.Icons.Example;

  package Medium = IBPSA.Media.Air "Medium model"
           ;

  IBPSA.Utilities.Psychrometrics.TWetBul_TDryBulPhi wetBulPhi(redeclare package
              Medium =
               Medium) "Model for wet bulb temperature"
    ;
  Modelica.Blocks.Sources.Constant p(k=101325) "Pressure"
                                    ;
    Modelica.Blocks.Sources.Ramp phi(
    duration=1,
    height=1,
    offset=0) "Relative humidity"
                 ;
  Modelica.Blocks.Sources.Constant TDryBul(k=273.15 + 29.4)
    "Dry bulb temperature"          ;
  IBPSA.Utilities.Psychrometrics.TWetBul_TDryBulPhi wetBulPhiApp(redeclare
      package Medium = Medium, approximateWetBulb=true)
    "Model for wet bulb temperature"
    ;
  IBPSA.Utilities.Psychrometrics.TWetBul_TDryBulXi wetBulXi(redeclare package
              Medium =
               Medium)
    "Model for wet bulb temperature using Xi as an input, used to verify consistency with wetBulPhi"
    ;
  IBPSA.Utilities.Psychrometrics.X_pTphi x_pTphi "Computes mass fraction"
    ;

protected
  block Assertions
    extends Modelica.Blocks.Icons.Block;
    constant Modelica.Units.SI.Temperature dT_max=0.1
      "Maximum allowed deviation with reference result";

    Modelica.Blocks.Interfaces.RealInput phi "Relative humidity"
      ;
    Modelica.Blocks.Interfaces.RealInput wetBulPhi_TWetBul
      "Wet bulb temperature from wetBulPhi_phi"
      ;
    Modelica.Blocks.Interfaces.RealInput wetBulXi_TWetBul
      "Wet bulb temperature from wetBulXi_phi"
      ;
  equation
    // Validation of one data point based on example 17.1 in
    // Ananthanarayanan, P. N. Basic refrigeration and air conditioning. Tata McGraw-Hill Education, 2013.
    if abs(phi-0.48)<0.001 then
      assert(abs(wetBulPhi_TWetBul - 21.1-273.15) < dT_max,
      "Error in computation of wet bulb temperature, deviation with reference result is larger than "
       + String(dT_max) + " K since the wet bulb temperature equals " +String(wetBulPhi_TWetBul));
    end if;

    assert(abs(wetBulPhi_TWetBul-wetBulXi_TWetBul)<1e-2, "Inconsistent implementation of wetBulPhi and wetBulXi.");
  end Assertions;

  Assertions assertions "Verifies that the results are correct"
    ;
equation
  connect(p.y, wetBulPhi.p)
                         ;
  connect(TDryBul.y, wetBulPhi.TDryBul) ;
  connect(phi.y, wetBulPhi.phi) ;
  connect(p.y, wetBulPhiApp.p)
                         ;
  connect(TDryBul.y, wetBulPhiApp.TDryBul)
                                        ;
  connect(phi.y, wetBulPhiApp.phi)
                                ;
  connect(wetBulXi.TDryBul, TDryBul.y) ;
  connect(wetBulXi.p, p.y) ;
  connect(x_pTphi.p_in, p.y) ;
  connect(x_pTphi.T, TDryBul.y) ;
  connect(x_pTphi.phi, phi.y) ;
  connect(x_pTphi.X[1], wetBulXi.Xi[1])
    ;
  connect(wetBulPhi.TWetBul, assertions.wetBulPhi_TWetBul) ;
  connect(wetBulXi.TWetBul, assertions.wetBulXi_TWetBul) ;
  connect(assertions.phi, phi.y) 
    ;
end TWetBul_TDryBulPhi;

within BuildSysPro.IBPSA.Utilities.Psychrometrics.Functions;
function density_pTX
  "Density of air as a function of pressure, temperature and species concentration"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Pressure p "Absolute pressure of the medium";
  input Modelica.Units.SI.Temperature T "Dry bulb temperature";
  input Modelica.Units.SI.MassFraction X_w
    "Water vapor mass fraction per unit mass total air";
  output Modelica.Units.SI.Density d "Mass density";
protected
  Modelica.Units.SI.SpecificHeatCapacity R
    "Gas constant (of mixture if applicable)";
algorithm
  R :=Modelica.Media.IdealGases.Common.SingleGasesData.Air.R_s*(1 - X_w) +
    Modelica.Media.IdealGases.Common.SingleGasesData.H2O.R_s*X_w;
  d := p/(R*T)

  ;
end density_pTX;

within BuildSysPro.IBPSA.Utilities.Psychrometrics.Functions;
function phi_pTX
  "Relative humidity for given pressure, dry bulb temperature and moisture mass fraction"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Pressure p "Absolute pressure of the medium";
  input Modelica.Units.SI.Temperature T "Dry bulb temperature";
  input Modelica.Units.SI.MassFraction X_w
    "Water vapor mass fraction per unit mass total air";
  output Real phi(unit="1") "Relative humidity";
algorithm
  phi := p/saturationPressure(T)*X_w/(X_w + IBPSA.Utilities.Psychrometrics.Constants.k_mair
    *(1 - X_w))
  ;
end phi_pTX;

within BuildSysPro.IBPSA.Utilities.Psychrometrics.Functions;
function pW_TDewPoi
  "Function to compute the water vapor partial pressure for a given dew point temperature of moist air"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Temperature T(min=100) "Dew point temperature";
  output Modelica.Units.SI.Pressure p_w(displayUnit="Pa", min=100)
    "Water vapor partial pressure";
protected
  constant Real C8=-5.800226E3;
  constant Real C9=1.3914993E0;
  constant Real C10=-4.8640239E-2;
  constant Real C11=4.1764768E-5;
  constant Real C12=-1.4452093E-8;
  constant Real C13=6.5459673E0;

algorithm
  p_w := Modelica.Math.exp(C8/T + C9 + T*(C10 + T*(C11 + T*C12)) + C13*
    Modelica.Math.log(T))
  ;
end pW_TDewPoi;

within BuildSysPro.IBPSA.Utilities.Psychrometrics.Functions;
function pW_TDewPoi_amb
  "Function to compute the water vapor partial pressure for a given dew point temperature of moist air"
  extends Modelica.Icons.Function;

  input Modelica.Units.SI.Temperature T "Dew point temperature";
  output Modelica.Units.SI.Pressure p_w(displayUnit="Pa", min=100)
    "Water vapor partial pressure";
protected
  constant Modelica.Units.SI.Temperature T1=283.15 "First support point";
  constant Modelica.Units.SI.Temperature T2=293.15 "Second support point";
  constant Modelica.Units.SI.Pressure p1=1227.97 "First support point";
  constant Modelica.Units.SI.Pressure p2=2338.76 "Second support point";

  constant Real a1=(Modelica.Math.log(p2) - Modelica.Math.log(p1)*T2/T1)/(1 -
      T2/T1);
  constant Real a2(unit="1/K")=(Modelica.Math.log(p1) - a1)/T1;

algorithm
  p_w := Modelica.Math.exp(a1 + a2*T)
  ;
end pW_TDewPoi_amb;

within BuildSysPro.IBPSA.Utilities.Psychrometrics.Functions;
function pW_X "Water vapor pressure for given humidity ratio"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.MassFraction X_w(
    min=0,
    max=0.99999,
    nominal=0.01) "Species concentration at dry bulb temperature";
  input Modelica.Units.SI.Pressure p=101325 "Total pressure";
  output Modelica.Units.SI.Pressure p_w(displayUnit="Pa")
    "Water vapor pressure";

protected
  Modelica.Units.SI.MassFraction x_w(nominal=0.01)
    "Water mass fraction per mass of dry air";
algorithm
  x_w := X_w/(1 - X_w);
  p_w := p*x_w/(0.62198 + x_w)
  ;
end pW_X;

within BuildSysPro.IBPSA.Utilities.Psychrometrics.Functions;
function saturationPressure
  "Saturation curve valid for 223.16 <= T <= 373.16 (and slightly outside with less accuracy)"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Temperature TSat(displayUnit="degC", nominal=300)
    "Saturation temperature";
  output Modelica.Units.SI.AbsolutePressure pSat(displayUnit="Pa", nominal=1000)
    "Saturation pressure";

algorithm
  pSat := IBPSA.Utilities.Math.Functions.regStep(
    y1=IBPSA.Utilities.Psychrometrics.Functions.saturationPressureLiquid(TSat),
    y2=IBPSA.Utilities.Psychrometrics.Functions.sublimationPressureIce(TSat),
    x=TSat - 273.16,
    x_small=1.0)
  ;
end saturationPressure;

within BuildSysPro.IBPSA.Utilities.Psychrometrics.Functions;
function saturationPressureLiquid
  "Return saturation pressure of water as a function of temperature T in the range of 273.16 to 373.16 K"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Temperature TSat(displayUnit="degC", nominal=300)
    "Saturation temperature";
  output Modelica.Units.SI.AbsolutePressure pSat(displayUnit="Pa", nominal=1000)
    "Saturation pressure";
algorithm
  pSat := 611.657*Modelica.Math.exp(17.2799 - 4102.99/(TSat - 35.719))

  ;
end saturationPressureLiquid;

within BuildSysPro.IBPSA.Utilities.Psychrometrics.Functions;
function sublimationPressureIce
  "Return sublimation pressure of water as a function of temperature T between 190 and 273.16 K"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Temperature TSat(displayUnit="degC", nominal=300)
    "Saturation temperature";
  output Modelica.Units.SI.AbsolutePressure pSat(displayUnit="Pa", nominal=1000)
    "Saturation pressure";
protected
  Modelica.Units.SI.Temperature TTriple=273.16 "Triple point temperature";
  Modelica.Units.SI.AbsolutePressure pTriple=611.657 "Triple point pressure";
  Real r1=TSat/TTriple "Common subexpression";
  Real a[2]={-13.9281690,34.7078238} "Coefficients a[:]";
  Real n[2]={-1.5,-1.25} "Coefficients n[:]";
algorithm
  pSat := exp(a[1] - a[1]*r1^n[1] + a[2] - a[2]*r1^n[2])*pTriple
  ;
end sublimationPressureIce;

within BuildSysPro.IBPSA.Utilities.Psychrometrics.Functions;
function TDewPoi_pW
  "Function to compute the water vapor partial pressure for a given dew point temperature of moist air"
  extends Modelica.Icons.Function;

  input Modelica.Units.SI.Pressure p_w(displayUnit="Pa", min=200)
    "Water vapor partial pressure";
  output Modelica.Units.SI.Temperature T "Dew point temperature";

protected
  function pW_TDewPoi_inversion
    "Internal function to solve eps=f(NTU, Z) for NTU for cross flow unmixed"
    extends Modelica.Math.Nonlinear.Interfaces.partialScalarFunction;

    input Modelica.Units.SI.Pressure p_w(displayUnit="Pa", min=200)
      "Water vapor partial pressure";

  algorithm
    y := IBPSA.Utilities.Psychrometrics.Functions.pW_TDewPoi(T=u) - p_w;
  end pW_TDewPoi_inversion;

algorithm
  T := Modelica.Math.Nonlinear.solveOneNonlinearEquation(
      f=function pW_TDewPoi_inversion(p_w=p_w),
      u_min=200,
      u_max=400)
  ;
end TDewPoi_pW;

within BuildSysPro.IBPSA.Utilities.Psychrometrics.Functions;
function TDewPoi_pW_amb
  "Function to compute the dew point temperature of moist air for a given water vapor partial pressure"
  extends Modelica.Icons.Function;

  input Modelica.Units.SI.Pressure p_w(displayUnit="Pa", min=100)
    "Water vapor partial pressure";
  output Modelica.Units.SI.Temperature T "Dew point temperature";
protected
  constant Modelica.Units.SI.Temperature T1=283.15 "First support point";
  constant Modelica.Units.SI.Temperature T2=293.15 "Second support point";
  constant Modelica.Units.SI.Pressure p1=1227.97 "First support point";
  constant Modelica.Units.SI.Pressure p2=2338.76 "Second support point";

  constant Real a1=(Modelica.Math.log(p2) - Modelica.Math.log(p1)*T2/T1)/(1 -
      T2/T1);
  constant Real a2(unit="1/K")=(Modelica.Math.log(p1) - a1)/T1;

algorithm
  T := (Modelica.Math.log(p_w) - a1)/a2
  ;
end TDewPoi_pW_amb;

within BuildSysPro.IBPSA.Utilities.Psychrometrics.Functions;
function X_pSatpphi "Humidity ratio for given water vapor pressure"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.AbsolutePressure pSat "Saturation pressure";
  input Modelica.Units.SI.Pressure p "Pressure of the fluid";
  input Real phi(min=0, max=1) "Relative humidity";
  output Modelica.Units.SI.MassFraction X_w(
    min=0,
    max=1,
    nominal=0.01) "Water vapor concentration per total mass of air";

protected
  constant Real k = 0.621964713077499 "Ratio of molar masses";
algorithm
  X_w := phi*k/(k*phi+p/pSat-phi)

  ;
end X_pSatpphi;

within BuildSysPro.IBPSA.Utilities.Psychrometrics.Functions;
function X_pTphi
  "Absolute humidity for given pressure, dry bulb temperature and relative humidity"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Pressure p "Absolute pressure of the medium";
  input Modelica.Units.SI.Temperature T "Dry bulb temperature";
  input Real phi(unit="1") "Relative humidity";
  output Modelica.Units.SI.MassFraction X_w
    "Water vapor mass fraction per unit mass total air";

algorithm
  X_w := phi/((p/saturationPressure(T) - phi)/IBPSA.Utilities.Psychrometrics.Constants.k_mair
     + phi)
  ;
end X_pTphi;

within BuildSysPro.IBPSA.Utilities.Psychrometrics.Functions;
function X_pW "Mass fraction for given water vapor pressure"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Pressure p_w(
    displayUnit="Pa",
    min=0.003,
    nominal=1000) "Water vapor pressure";
  input Modelica.Units.SI.Pressure p=101325 "Total pressure";
  output Modelica.Units.SI.MassFraction X_w(
    min=0,
    max=1,
    nominal=0.01) "Species concentration at dry bulb temperature";

protected
  Modelica.Units.SI.MassFraction x_w(nominal=0.01)
    "Water mass fraction per mass of dry air";
algorithm
  x_w := 0.62198*p_w/(p - p_w);
  X_w := x_w/(1 + x_w)
  ;
end X_pW;

within BuildSysPro.IBPSA.Utilities.Psychrometrics.Functions.BaseClasses;
function der_pW_TDewPoi "Derivative of function pW_TDewPoi"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Temperature T "Dew point temperature";
  input Real dT "Temperature differential";
  output Real dp_w "Differential of water vapor partial pressure";
protected
  constant Real C8=-5.800226E3;
  constant Real C9=1.3914993E0;
  constant Real C10=-4.8640239E-2;
  constant Real C11=4.1764768E-5;
  constant Real C12=-1.4452093E-8;
  constant Real C13=6.5459673E0;
algorithm
  dp_w := Modelica.Math.exp(C8/T + C9 + T*(C10 + T*(C11 + T*C12)) + C13*
    Modelica.Math.log(T))*(-C8/T/T + C10 + 2*C11*T + 3*C12*T*T + C13/T)*dT
  ;
end der_pW_TDewPoi;

within BuildSysPro.IBPSA.Utilities.Psychrometrics.Functions.BaseClasses;
function der_pW_TDewPoi_amb "Derivative of function pW_TDewPoi_amb"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Temperature T "Dew point temperature";
  input Real dT;
  output Real dp_w "Differential of water vapor partial pressure";
protected
  constant Modelica.Units.SI.Temperature T1=283.15 "First support point";
  constant Modelica.Units.SI.Temperature T2=293.15 "Second support point";
  constant Modelica.Units.SI.Pressure p1=1227.97 "First support point";
  constant Modelica.Units.SI.Pressure p2=2338.76 "Second support point";

  constant Real a1=(Modelica.Math.log(p2) - Modelica.Math.log(p1)*T2/T1)/(1 -
      T2/T1);
  constant Real a2(unit="1/K")=(Modelica.Math.log(p1) - a1)/T1;

algorithm
  dp_w:=a2*Modelica.Math.exp(a1 + a2*T)*dT

  ;
end der_pW_TDewPoi_amb;

within BuildSysPro.IBPSA.Utilities.Psychrometrics.Functions.BaseClasses;
function der_pW_X "Derivative of function pW_X"
  extends Modelica.Icons.Function;

  input Modelica.Units.SI.MassFraction X_w(
    min=0,
    max=1,
    nominal=0.01) "Species concentration at dry bulb temperature";
  input Modelica.Units.SI.Pressure p=101325 "Total pressure";

  input Real dX_w
    "Differential of species concentration at dry bulb temperature";
  input Real dp "Differential of total pressure";

  output Real dp_w "Differential of water vapor pressure";

protected
  Modelica.Units.SI.MassFraction x_w(nominal=0.01)
    "Water mass fraction per mass of dry air";
  Real dX_w_dX "Differential d (x_w) / d X_w";
algorithm
  x_w := X_w/(1 - X_w);
  dX_w_dX := 1/(1-X_w)^2;
  dp_w := p * 0.62198 / (0.62198 + x_w)^2 * dX_w_dX * dX_w + x_w/(0.62198 + x_w) * dp

  ;
end der_pW_X;

within BuildSysPro.IBPSA.Utilities.Psychrometrics.Functions.BaseClasses;
function der_saturationPressureLiquid
  "Derivative of the function saturationPressureLiquid"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Temperature TSat "Saturation temperature";
  input Real dTSat(unit="K/s") "Saturation temperature derivative";
  output Real psat_der(unit="Pa/s") "Differential of saturation pressure";

algorithm
  psat_der:=611.657*Modelica.Math.exp(17.2799 - 4102.99
            /(TSat - 35.719))*4102.99*dTSat/(TSat - 35.719)^2

  ;
end der_saturationPressureLiquid;

within BuildSysPro.IBPSA.Utilities.Psychrometrics.Functions.BaseClasses;
function der_sublimationPressureIce
  "Derivative of function sublimationPressureIce"
    extends Modelica.Icons.Function;
  input Modelica.Units.SI.Temperature TSat(displayUnit="degC", nominal=300)
    "Saturation temperature";
    input Real dTSat(unit="K/s") "Sublimation temperature derivative";
    output Real psat_der(unit="Pa/s") "Sublimation pressure derivative";
protected
  Modelica.Units.SI.Temperature TTriple=273.16 "Triple point temperature";
  Modelica.Units.SI.AbsolutePressure pTriple=611.657 "Triple point pressure";
    Real r1=TSat/TTriple "Common subexpression 1";
    Real r1_der=dTSat/TTriple "Derivative of common subexpression 1";
    Real a[2]={-13.9281690,34.7078238} "Coefficients a[:]";
    Real n[2]={-1.5,-1.25} "Coefficients n[:]";
algorithm
    psat_der := exp(a[1] - a[1]*r1^n[1] + a[2] - a[2]*r1^n[2])*pTriple*(-(a[1]
      *(r1^(n[1] - 1)*n[1]*r1_der)) - (a[2]*(r1^(n[2] - 1)*n[2]*r1_der)))
    ;
end der_sublimationPressureIce;

within BuildSysPro.IBPSA.Utilities.Psychrometrics.Functions.BaseClasses;
function der_TDewPoi_pW_amb "Derivative of function TDewPoi_pW_amb"
  extends Modelica.Icons.Function;

  input Modelica.Units.SI.Pressure p_w "Water vapor partial pressure";
  input Real dp_w "Differential of water vapor partial pressure";
  output Real dT "Differential of dew point temperature";

protected
  constant Modelica.Units.SI.Temperature T1=283.15 "First support point";
  constant Modelica.Units.SI.Temperature T2=293.15 "Second support point";
  constant Modelica.Units.SI.Pressure p1=1227.97 "First support point";
  constant Modelica.Units.SI.Pressure p2=2338.76 "Second support point";

  constant Real a1=(Modelica.Math.log(p2) - Modelica.Math.log(p1)*T2/T1)/(1 -
      T2/T1);
  constant Real a2(unit="1/K")=(Modelica.Math.log(p1) - a1)/T1;
algorithm
  dT := dp_w / (a2*p_w)

  ;
end der_TDewPoi_pW_amb;

within BuildSysPro.IBPSA.Utilities.Psychrometrics.Functions.BaseClasses.Examples;
model DewPointTemperatureDerivativeCheck
  "Model to test correct implementation of derivative"
  extends Modelica.Icons.Example;

  Real y "Function value";
  Real y_comp "Function value for comparison";
  Real err "Integration error";
  Modelica.Units.SI.Temperature T "Temperature";
initial equation
  y=y_comp;
equation
  T =  273.15 + 50 + time^3 * 50;
  y = IBPSA.Utilities.Psychrometrics.Functions.pW_TDewPoi(T=T);
  der(y)=der(y_comp);
  err = y-y_comp;
  assert(abs(err)/max(1, abs(y)) < 1E-2, "Derivative implementation has an error or solver tolerance is too low.")
;
end DewPointTemperatureDerivativeCheck;

