within BuildSysPro.Systems.Controls;
model PIDDualMode
  "Heating and cooling regulation with constant or prescribed setpoints"

  parameter Boolean use_T_input=false "Temperature setpoints entry"
    ;
  parameter Boolean use_power_integrators=false "Integrators on the heating and cooling power outputs"
    ;

  parameter Modelica.Units.SI.Power power_nom_heat=1000
    "Nominal heating power of the system"
    ;
  parameter Modelica.Units.SI.Power power_nom_cool=1000
    "Nominal cooling power of the system (defined as positive)"
    ;

  parameter Modelica.Units.NonSI.Temperature_degC T_heat_sp=20
    "Heating setpoint temperature in °C" ;
  parameter Modelica.Units.NonSI.Temperature_degC T_cool_sp=25
    "Cooling setpoint temperature in °C" ;

  parameter Real k(min=0) = 1e4 "Gain of controller"
    ;
  parameter Modelica.Units.SI.Time Ti(
    min=Modelica.Constants.small,
    start=0.5) = 60 "Time constant of Integrator block"
    ;
  parameter Modelica.Units.SI.Time Td(
    min=0,
    start=0.1) = 0 "Time constant of Derivative block"
    ;

  BuildSysPro.BaseClasses.HeatTransfer.Interfaces.HeatPort_a T_room ;
  BuildSysPro.BaseClasses.HeatTransfer.Sensors.TemperatureSensor measT_room ;

  Modelica.Blocks.Sources.Constant T_heat_param(k=T_heat_sp)  if not use_T_input
    "Temperature setpoint for heating (parameter) °C"
    ;
  Modelica.Blocks.Sources.Constant T_cool_param(k=T_cool_sp)  if not use_T_input
    "Temperature setpoint for cooling (parameter) °C"
    ;

  Modelica.Blocks.Interfaces.RealInput T_heat_sp_input
                                                     if use_T_input
    "Temperature setpoint for heating (RealInput) °C" ;
  Modelica.Blocks.Interfaces.RealInput T_cool_sp_input
                                                     if use_T_input
    "Temperature setpoint for cooling (RealInput) °C" ;

  BuildSysPro.BaseClasses.HeatTransfer.Units.ToKelvin toKelvin_cool
    ;
  BuildSysPro.BaseClasses.HeatTransfer.Units.ToKelvin toKelvin_heat
    ;

  Modelica.Blocks.Continuous.LimPID PID_heat(
    yMin=0.,
    k=k,
    Ti=Ti,
    Td=Td,
    yMax=power_nom_heat,
    initType=Modelica.Blocks.Types.Init.InitialState)
    ;
  Modelica.Blocks.Continuous.LimPID PID_cool(
    controllerType=Modelica.Blocks.Types.SimpleController.PID,
    yMax=0,
    k=k,
    Ti=Ti,
    Td=Td,
    yMin=-power_nom_cool,
    initType=Modelica.Blocks.Types.Init.InitialState)
    ;

  BuildSysPro.BaseClasses.HeatTransfer.Sources.PrescribedHeatFlow prescribedHeating
 if (use_T_input or twoDifferentSetpoints)
    ;
  BuildSysPro.BaseClasses.HeatTransfer.Sources.PrescribedHeatFlow prescribedCooling
 if (use_T_input or twoDifferentSetpoints)
    ;

  BuildSysPro.BaseClasses.HeatTransfer.Sources.PrescribedTemperature prescribedTemperature
 if (not use_T_input and not twoDifferentSetpoints)
  ;

  BuildSysPro.BaseClasses.HeatTransfer.Sensors.HeatFlowSensor heatFlux
    ;

  Modelica.Blocks.Sources.Constant Zero(k=0)
    ;
  Modelica.Blocks.Math.Max heatingFilter
    ;
  Modelica.Blocks.Math.Min coolingFilter
    ;

  Modelica.Blocks.Interfaces.RealOutput heating_power_W "Heating Power [W]"
    ;
  Modelica.Blocks.Math.Gain NegToPos(k=-1)
    ;
  Modelica.Blocks.Interfaces.RealOutput cooling_power_W "Cooling Power [W]"
    ;

  Modelica.Blocks.Continuous.Integrator integratorHeating(k=1/(1000*3600)) if use_power_integrators
    ;
  Modelica.Blocks.Continuous.Integrator integratorCooling(k=1/(1000*3600)) if use_power_integrators
    ;
  Modelica.Blocks.Interfaces.RealOutput heating_energy_kWh
                                                          if use_power_integrators
    "Heating Energy [kWh]" ;
  Modelica.Blocks.Interfaces.RealOutput cooling_energy_kWh
                                                          if use_power_integrators
    "Cooling Energy [kWh]" ;

protected
  parameter Boolean twoDifferentSetpoints = (T_heat_sp <> T_cool_sp);

equation

  if use_T_input then
    connect(toKelvin_heat.Celsius, T_heat_sp_input) ;
    connect(toKelvin_cool.Celsius, T_cool_sp_input) ;
  else
    connect(T_heat_param.y, toKelvin_heat.Celsius)
      ;
    connect(T_cool_param.y, toKelvin_cool.Celsius)
      ;
  end if;

  connect(heatFlux.port_b, T_room) ;
  connect(T_room,measT_room. port) ;

  connect(measT_room.T, PID_heat.u_m) ;
  connect(toKelvin_heat.Kelvin, PID_heat.u_s) ;
  connect(PID_heat.y, prescribedHeating.Q_flow) ;
  connect(prescribedHeating.port, heatFlux.port_a) ;

  connect(measT_room.T, PID_cool.u_m) ;
  connect(toKelvin_cool.Kelvin, PID_cool.u_s) ;
  connect(PID_cool.y, prescribedCooling.Q_flow) ;
  connect(prescribedCooling.port, heatFlux.port_a) ;

  connect(toKelvin_heat.Kelvin, prescribedTemperature.T) ;
  connect(prescribedTemperature.port, heatFlux.port_a) ;

  connect(heatFlux.Q_flow, heatingFilter.u1) ;
  connect(heatFlux.Q_flow, coolingFilter.u2) ;

  connect(Zero.y, heatingFilter.u2) ;
  connect(Zero.y, coolingFilter.u1) ;

  connect(heatingFilter.y, heating_power_W) ;
  connect(heatingFilter.y, integratorHeating.u) ;
  connect(integratorHeating.y, heating_energy_kWh)
    ;

  connect(coolingFilter.y, NegToPos.u) ;
  connect(NegToPos.y, cooling_power_W)
    ;
  connect(NegToPos.y, integratorCooling.u) ;
  connect(integratorCooling.y, cooling_energy_kWh)


  ;
end PIDDualMode;

