    ;
  BaseClasses.HeatTransfer.Sensors.TemperatureSensor temperatureSensor
    ;
  BaseClasses.HeatTransfer.Interfaces.HeatPort_a T_room ;
  Modelica.Blocks.Sources.CombiTimeTable combiTimeTable1(
    smoothness=smoothness,
    offset={0},
    startTime=0,
    tableOnFile=tableauSurFichier,
    table=tableau,
    tableName=nomTableau,
    fileName=nomFichier,
    columns={2},
    extrapolation=Modelica.Blocks.Types.Extrapolation.HoldLastPoint)
                         if saisieTableau
                      ;
  Modelica.Blocks.Continuous.Integrator integrator ;
  Modelica.Blocks.Math.Gain gain(k=1/(1000*3600))
                                           ;
  Modelica.Blocks.Interfaces.RealOutput Pth "Thermal power demand"
                                          ;
  Modelica.Blocks.Interfaces.RealOutput kWh_th "Thermal kWh cumulated"
                                           ;
  Modelica.Blocks.Interfaces.RealInput T_sp  if not saisieTableau
    "Setpoint temperature [K]" ;
equation
  connect(PID.y,prescribedHeatFlow. Q_flow) ;
  connect(temperatureSensor.T,PID. u_m) ;
  connect(temperatureSensor.port,T_room)  ;
  connect(gain.y,integrator. u) ;
  connect(integrator.y,kWh_th)  ;
  connect(prescribedHeatFlow.port,T_room)  ;
  connect(PID.y, gain.u) ;
  connect(PID.y, Pth) ;
 if saisieTableau then
   connect(combiTimeTable1.y[1],PID.u_s);
 else
    connect(T_sp, PID.u_s);
 end if
  ;
end PIDPrescribedSingleMode;

within BuildSysPro.Systems.Controls;
model PIDSingleOrDualMode
  "Heating and cooling regulation with constant or prescribed setpoints"

  parameter Boolean heating_mode=true "Activation of heating"
    ;
  parameter Boolean cooling_mode=true "Activation of cooling"
    ;
  parameter Boolean use_T_input=false "Temperature setpoints entry"
    ;
  parameter Boolean use_power_integrators=false "Integrators on the heating and cooling power outputs"
    ;

  parameter Modelica.Units.SI.Power power_nom_heat=1e4
    "Nominal heating power of the system"
    ;
  parameter Modelica.Units.SI.Power power_nom_cool=1e4
    "Nominal cooling power of the system (defined as positive)"
    ;

  parameter Modelica.Units.NonSI.Temperature_degC T_heat_sp_degC=20
    "Heating setpoint temperature [degC]" ;
  parameter Modelica.Units.NonSI.Temperature_degC T_cool_sp_degC=25
    "Cooling setpoint temperature [degC]" ;

  parameter Real k(min=0) = 1e5 "Gain of controller"
    ;
  parameter Modelica.Units.SI.Time Ti(
    min=Modelica.Constants.small,
    start=0.5) = 900 "Time constant of Integrator block"
    ;
  parameter Modelica.Units.SI.Time Td(
    min=0,
    start=0.1) = 0 "Time constant of Derivative block"
    ;

  BuildSysPro.BaseClasses.HeatTransfer.Interfaces.HeatPort_a T_room
   ;
  BuildSysPro.BaseClasses.HeatTransfer.Sensors.TemperatureSensor measT_room
    ;

  Modelica.Blocks.Sources.Constant T_heat_param(k=T_heat_sp_degC)
 if (heating_mode and not use_T_input)
    "Temperature setpoint for heating (parameter) [degC]"
    ;
  Modelica.Blocks.Sources.Constant T_cool_param(k=T_cool_sp_degC)
 if (cooling_mode and not use_T_input)
    "Temperature setpoint for cooling (parameter) [degC]"
    ;

  Modelica.Blocks.Interfaces.RealInput T_heat_sp_input_degC
 if (heating_mode and use_T_input)
    "Temperature setpoint for heating (RealInput) [degC]"
    ;
  Modelica.Blocks.Interfaces.RealInput T_cool_sp_input_degC
 if (cooling_mode and use_T_input)
    "Temperature setpoint for cooling (RealInput) [degC]"
      ;

  BuildSysPro.BaseClasses.HeatTransfer.Units.ToKelvin toKelvin_heat if heating_mode
    ;
  BuildSysPro.BaseClasses.HeatTransfer.Units.ToKelvin toKelvin_cool if cooling_mode
    ;

  Modelica.Blocks.Continuous.LimPID PID_heat(
    k=k,
    Ti=Ti,
    Td=Td,
    yMax=power_nom_heat,
    yMin=0.,
    initType=Modelica.Blocks.Types.Init.InitialState) if heating_mode
    ;
  Modelica.Blocks.Continuous.LimPID PID_cool(
    k=k,
    Ti=Ti,
    Td=Td,
    yMax=0,
    yMin=-power_nom_cool,
    initType=Modelica.Blocks.Types.Init.InitialState) if cooling_mode
    ;

  BuildSysPro.BaseClasses.HeatTransfer.Sources.PrescribedHeatFlow prescribedHeating if heating_mode
    ;
  BuildSysPro.BaseClasses.HeatTransfer.Sources.PrescribedHeatFlow prescribedCooling if cooling_mode
    ;

  Modelica.Blocks.Interfaces.RealOutput heating_power_W if heating_mode
    "Heating Power [W]"
    ;
  Modelica.Blocks.Math.Gain NegToPos(k=-1) if cooling_mode
    ;
  Modelica.Blocks.Interfaces.RealOutput cooling_power_W if cooling_mode
    "Cooling Power [W]"
    ;

  Modelica.Blocks.Continuous.Integrator integratorHeating(k=1/(1000*3600))
 if (heating_mode and use_power_integrators)
    ;
  Modelica.Blocks.Continuous.Integrator integratorCooling(k=1/(1000*3600))
 if (cooling_mode and use_power_integrators)
    ;
  Modelica.Blocks.Interfaces.RealOutput heating_energy_kWh
 if (heating_mode and use_power_integrators)
    "Heating Energy [kWh]"
    ;
  Modelica.Blocks.Interfaces.RealOutput cooling_energy_kWh
 if (cooling_mode and use_power_integrators)
    "Cooling Energy [kWh]"
    ;

equation

  connect(toKelvin_heat.Celsius, T_heat_sp_input_degC) ;
  connect(toKelvin_cool.Celsius, T_cool_sp_input_degC) ;
  connect(T_heat_param.y, toKelvin_heat.Celsius) ;
  connect(T_cool_param.y, toKelvin_cool.Celsius) ;

  connect(measT_room.T, PID_heat.u_m) ;
  connect(toKelvin_heat.Kelvin, PID_heat.u_s) ;
  connect(PID_heat.y, prescribedHeating.Q_flow) ;

  connect(measT_room.T, PID_cool.u_m) ;
  connect(toKelvin_cool.Kelvin, PID_cool.u_s) ;
  connect(PID_cool.y, prescribedCooling.Q_flow) ;

  connect(prescribedCooling.port, T_room) ;
  connect(prescribedHeating.port, T_room) ;
  connect(T_room,measT_room. port) ;

  connect(PID_heat.y, heating_power_W) ;
  connect(PID_heat.y, integratorHeating.u) ;
  connect(integratorHeating.y, heating_energy_kWh)
    ;

  connect(PID_cool.y, NegToPos.u) ;
  connect(NegToPos.y, cooling_power_W) ;
  connect(NegToPos.y, integratorCooling.u) ;
  connect(integratorCooling.y, cooling_energy_kWh)


  ;
end PIDSingleOrDualMode;

within BuildSysPro.Systems.DHW.Electric;
model ResistiveWaterHeater
  "Electric hot water tank with homogeneous temperature"
  parameter Modelica.Units.SI.Volume V=0.200 "Volume"
    ;
  parameter Modelica.Units.SI.Length d=0.50 "Diameter"
    ;
  parameter Modelica.Units.SI.Power P=2500 "Max electric power"
    ;
  parameter Modelica.Units.SI.Temperature T_sp=273.15 + 60
    "Setpoint temperature" ;
  parameter Modelica.Units.SI.TemperatureDifference dT=3 "Hysteresis band"
    ;
  parameter Modelica.Units.SI.Length e=0.04 "Thickness"
    ;
  parameter Modelica.Units.SI.ThermalConductivity lambda=0.04
    "Thermal conductivity"
    ;
  parameter Modelica.Units.SI.Density rho=1000 "Density"
    ;
  parameter Modelica.Units.SI.SpecificHeatCapacity Cp=4185
    "Specific heat capacity"
    ;
  //Modelica.SIunits.Temperature T "Water temperature in the tank";
  Integer Hyst(start=0) "Hysteresis";

  Real PertekWh "Energy loss through the tank envelope in kWh";
  Real EnergieCHkWh "Energy of tank water heating in kWh";

protected
  constant Real pi=Modelica.Constants.pi;
  constant Real coef36=1.0/3.6e6;
  constant Modelica.Units.SI.CoefficientOfHeatTransfer he=10
    "Outside exchange coefficient";

  parameter Modelica.Units.SI.Area Sb=pi*d*d/4 "Surface of the tank base";
  parameter Modelica.Units.SI.Length H=V/Sb "Tank height";
  parameter Modelica.Units.SI.Area St=pi*d*H + 2*Sb "Total exchange surface";

  parameter Modelica.Units.SI.CoefficientOfHeatTransfer h=1.0/(1/he + e/lambda)
    "Outside exchange coefficient";
  parameter Modelica.Units.SI.ThermalConductance KS=(1.1 + 0.05/V)*h*St;
  parameter Modelica.Units.SI.HeatCapacity C=rho*Cp*V;

public
  Modelica.Blocks.Interfaces.RealInput T_cold
    "Cold water temperature in degrees C" ;
  Modelica.Blocks.Interfaces.RealInput debit "Drawing rate in kg/s"
    ;
  Modelica.Blocks.Interfaces.RealInput OnOff
    "Signal ON(1)/OFF(0) of the electrical resistance" ;
  Modelica.Blocks.Interfaces.RealOutput Pelec "Electric power injected in W"
                                   ;
  Modelica.Blocks.Interfaces.RealOutput Cons "Electric consumption in kWh"
    ;
  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_b T_int "Air ambiant"
    ;
  Modelica.Thermal.HeatTransfer.Components.ThermalConductor deperdition(G=KS)
    ;
  Modelica.Thermal.HeatTransfer.Celsius.ToKelvin toKelvin ;
  Modelica.Thermal.HeatTransfer.Sources.PrescribedTemperature
    prescribedTemperature ;
  Modelica.Thermal.HeatTransfer.Components.Convection ChauffageEau
                                                                 ;
  Modelica.Blocks.Math.Gain gain(k=Cp)
    ;
  Modelica.Thermal.HeatTransfer.Sources.PrescribedHeatFlow prescribedHeatFlow
    ;
  Modelica.Blocks.Sources.RealExpression Puissance(y=Pelec)
    ;
  Modelica.Thermal.HeatTransfer.Components.HeatCapacitor Eau(C=C)
    ;
  Modelica.Blocks.Interfaces.RealOutput T_tank
    "Water temperature in the tank [K]" ;
equation
  Hyst=if T_tank < T_sp - dT then 1 elseif T_tank > T_sp + dT then 0 else pre(
     Hyst);
  Pelec=OnOff*P*Hyst;
  T_tank = Eau.T;
  der(Cons) = Pelec*coef36;
  der(EnergieCHkWh)=ChauffageEau.solid.Q_flow*coef36;
  der(PertekWh)=deperdition.port_a.Q_flow*coef36;
initial equation
//  der(T)=0.0;
  T_tank = T_sp;
  EnergieCHkWh=0.0;
  PertekWh=0.0;

equation
  connect(deperdition.port_b, T_int) ;
  connect(toKelvin.Celsius, T_cold) ;
  connect(toKelvin.Kelvin, prescribedTemperature.T) ;
  connect(prescribedTemperature.port, ChauffageEau.fluid)
                                                        ;
  connect(debit, gain.u) ;
  connect(gain.y, ChauffageEau.Gc)
                                 ;
  connect(Puissance.y, prescribedHeatFlow.Q_flow)      ;
  connect(prescribedHeatFlow.port, Eau.port) ;
  connect(deperdition.port_a, Eau.port) ;
  connect(ChauffageEau.solid, Eau.port) 
  ;
end ResistiveWaterHeater;

within BuildSysPro.Systems.DHW.HeatPump.Components;
model MixedWaterTank
  "Uniform water tank"

  // Initialization
  parameter Modelica.Units.SI.Temperature initialTemperature=10 + 273.15
    "Initial water temperature in the tank [K]";

  // Tank geometry
  parameter Modelica.Units.SI.Volume tankVolume=0.2 "Tank volume [m3]";
  parameter Boolean UA_userdefined=true
    "If true, user defines UA else based normative test sequence" ;
  parameter Modelica.Units.SI.ThermalConductance UA=1
    "Insulating heat transfer coefficient [W/K]"
    ;
  parameter Modelica.Units.SI.Power standbyPower=25 "Standby power [W]"
    ;
  // Boundary conditions
  parameter Modelica.Units.SI.Temperature T_amb=20 + 273.15
    "Ambient temperature [K]";

  // Auxiliary element
  parameter Modelica.Units.SI.Power auxiliaryPower=1800
    "Fixed heating power of the auxiliary heater [W]";

  // Tank unknowns
  Modelica.Units.SI.Temperature T_tank(start=initialTemperature, fixed=true)
    "Water temperature in the tank [K]";
  Modelica.Units.SI.Energy E_stored(start=0)
    "Energy stored in the tank [J]";
  Modelica.Units.SI.Power P_loss(start=0)
    "Power losses [W]";

protected
  Modelica.Units.SI.ThermalConductance UAcalc;

  Modelica.Units.SI.Power electricPower;

  // Water thermo-hydraulic properties
  constant Modelica.Units.SI.Density rho_water=1000 "Water density";
  constant Modelica.Units.SI.SpecificHeatCapacityAtConstantPressure cp=4185
    "Water specific heat capacity";
  constant Modelica.Units.SI.Temperature T_en_base_tank=10 + 273.15
    "Base temperature for energy calculation [K]";

public
  Modelica.Blocks.Interfaces.RealInput m_flow
    "Inlet cold water mass flow rate [kg/s]"
    ;
  Modelica.Blocks.Interfaces.RealInput T_in "Inlet cold water temperature [K]"
    ;

  Modelica.Blocks.Interfaces.BooleanInput onOffAuxiliary
    "Boolean for switching on/off the auxiliaries"
    ;

  Modelica.Blocks.Interfaces.RealInput heatInput
    "Injected heat power [W]"
    ;
  Modelica.Blocks.Interfaces.RealOutput T_sensor
    "Water temperature in the tank [K]"
    ;
equation

  // 52.5+273.15 corresponds to an average temperature in the tank during standby test hypothesis
  UAcalc=if UA_userdefined then UA else standbyPower/(52.5+273.15-T_amb);

  electricPower=if onOffAuxiliary then auxiliaryPower else 0;
  der(T_tank) =(-heatInput+electricPower+m_flow*cp*(T_in-T_tank)+P_loss)/(cp*rho_water*tankVolume);

  // Analysis data
  P_loss=UAcalc*(T_amb-T_tank);
  E_stored=tankVolume*rho_water*cp*(T_tank-T_en_base_tank);
  T_sensor=T_tank

  ;
end MixedWaterTank;

within BuildSysPro.Systems.DHW.HeatPump.Components;
model StratifiedWaterTank
  "Stratified water tank"

  // Initialization
  parameter Modelica.Units.SI.Temperature initialTemperature=10 + 273.15
    "Initial water temperature in the tank [K]";

  // Tank geometry
  parameter Modelica.Units.SI.Volume tankVolume=0.2 "Tank volume [m3]";
  parameter Modelica.Units.SI.Height tankHeight=1.7 "Tank height [m]";
  parameter Modelica.Units.SI.ThermalConductance UA=10
    "Insulating heat transfer coefficient [W/K]";
  parameter Integer nCells=10 "Number of cells";
  parameter Integer iHX_top=5 "Top condenser position";
  parameter Integer iHX_bottom=2 "Bottom condenser position";
  parameter Integer iAux_top=3 "Top auxiliary position";
  parameter Integer iAux_bottom=1 "Bottom auxiliary position";
  parameter Integer i_sensor=1 "Temperature sensor position";

  final parameter Modelica.Units.SI.Area tankSurface=tankVolume/tankHeight
    "Floor surface of the tank in m2";

  // Boundary conditions
  parameter Modelica.Units.SI.Temperature T_amb=20 + 273.15
    "Ambient temperature [K]";

  // Auxiliary element
  parameter Modelica.Units.SI.Power auxiliaryPower=1800
    "Fixed heating power of the auxiliary heater [W]";

  // Tank unknowns
  Modelica.Units.SI.Temperature T_tank[nCells](
    each start=initialTemperature,
    fixed=true)
    "Vector containing the water temperature of each layer [K]";
  Modelica.Units.SI.Energy E_stored(start=0)
    "Energy stored in the tank [J]";
  Modelica.Units.SI.Power P_loss(start=0)
    "Power losses [W]";

  Modelica.Blocks.Interfaces.RealInput m_flow
    "Inlet cold water mass flow rate [kg/s]"
    ;

  Modelica.Blocks.Interfaces.RealInput T_in "Inlet cold water temperature [K]"
    ;

  Modelica.Blocks.Interfaces.BooleanInput onOffAuxiliary
    "Boolean for switching on/off the auxiliaries"
    ;
  Modelica.Blocks.Interfaces.RealOutput T_sensor
    "Temperature of the sensor [K]"
    ;

protected
  Modelica.Units.SI.Power electricPower[nCells];
  Modelica.Units.SI.Power thermalPower[nCells];
  Modelica.Units.SI.Power heatLoss[nCells];
  Modelica.Units.SI.Power conv[nCells];
  Modelica.Units.SI.ThermalConductance cond=lambda*tankSurface/(tankHeight/
      nCells);

  // Water thermo-hydraulic properties

  constant Modelica.Units.SI.Density rho_water=1000 "Water density";
  constant Modelica.Units.SI.SpecificHeatCapacityAtConstantPressure cp=4185
    "Water specific heat capacity";
  constant Modelica.Units.SI.ThermalConductivity lambda=0.62
    "Water thermal conductivity";
  constant Modelica.Units.SI.CoefficientOfHeatTransfer kup=1e6
    "Higher convection coefficient";
  constant Modelica.Units.SI.CoefficientOfHeatTransfer kdown=10
    "Higher convection coefficient";
  constant Modelica.Units.SI.Temperature T_en_base_tank=10 + 273.15
    "Base temperature for energy calculation";
public
  Modelica.Blocks.Interfaces.RealInput heatInput
    "Injected heat power [W]"
    ;

  // Thermocline development model
  Integer i_thermocline(start=1);
  Boolean convection[iHX_top-iHX_bottom+1];

algorithm

   for  i in iHX_bottom:iHX_top loop
     if abs(heatInput)>100 and m_flow<1e-4 and not convection[i-iHX_bottom+1] then
       i_thermocline:=i-1;
       break;
     elseif abs(heatInput)>100 and m_flow<1e-4 then
       i_thermocline:=iHX_top;
     else
       i_thermocline:=iHX_bottom;
     end if;
   end for;

equation

  convection[1]=true;
  for i in iHX_bottom+1:iHX_top loop
     convection[i-iHX_bottom+1]=(pre(convection[i-iHX_bottom+1]) or (T_tank[i-iHX_bottom] >= T_tank[i-iHX_bottom+1]-1*(tankHeight/nCells)/0.043)) and (convection[i-iHX_bottom] and abs(heatInput)>100 and m_flow<1e-4);
  end for;

  T_sensor=T_tank[i_sensor];

  // Distribution of powers transferred to the water per layer

  for i in 1:nCells loop

    if i>=iAux_bottom and i<=iAux_top and onOffAuxiliary then
      electricPower[i]= -auxiliaryPower/(iAux_top-iAux_bottom+1);
    else
      electricPower[i]= 0;
    end if;

    if i>=iHX_bottom and i<=iHX_top then
      thermalPower[i]=if convection[i-iHX_bottom+1] then heatInput/(i_thermocline-iHX_bottom+1) else 0;
    else
       thermalPower[i]=0;
     end if;

  end for;

  // If there is just one layer there can be no conduction -> mixed tank
  if nCells>2 then
    conv[1]=(if T_tank[1] > T_tank[2] then kup else kdown)*tankSurface*(T_tank[2] - T_tank[1]);
  else
    conv[1]=0;
  end if;

  // Heat balance on the layer 1 after setting exchanges with the room (loss) and with upper and lower layers (conv)

  der(T_tank[1])=-(-(conv[1])+electricPower[1]+thermalPower[1]+m_flow*cp*(T_tank[1]-T_in)+ heatLoss[1]+ (if nCells==1 then 0 else -cond*(T_tank[2]-T_tank[1])))/(cp*rho_water*tankVolume/nCells);
  heatLoss[1]=(UA/nCells)*(T_tank[1]-T_amb);

  // Heat balance on intermediate layers

  for i in 2:nCells-1 loop

     conv[i]=(if T_tank[i] > T_tank[i + 1] then kup else kdown)*tankSurface*(T_tank[i + 1] - T_tank[i]);
     der(T_tank[i])=-(electricPower[i]+thermalPower[i]+m_flow*cp*(T_tank[i]-T_tank[i-1])+heatLoss[i]-(conv[i]-conv[i-1]) -cond*(T_tank[i-1]+T_tank[i+1]-2*T_tank[i]))/(cp*rho_water*tankVolume/nCells);
     heatLoss[i]=(UA/nCells)*(T_tank[i]-T_amb);

  end for;

  // Heat balance on the upper layer

  der(T_tank[nCells])=-(electricPower[nCells]+thermalPower[nCells]+m_flow*cp*(T_tank[nCells]-T_tank[nCells-1])+heatLoss[nCells] -(conv[nCells]-conv[nCells-1]) -cond*(T_tank[nCells-1]-T_tank[nCells]))/(cp*rho_water*tankVolume/nCells);
  conv[nCells]=0;
  heatLoss[nCells]=(UA/nCells)*(T_tank[nCells]-T_amb);

  // Analysis data
  P_loss=sum(heatLoss);
  E_stored=sum((tankVolume/nCells)*rho_water*cp*(T_tank[i]-T_en_base_tank) for i in 1:nCells)

  ;
end StratifiedWaterTank;

within BuildSysPro.Systems.DHW.HeatPump.Components;
model WaterHeaterHeatPumpController
  "Simple Hysteresis control with Time of Use switch and Auto mode"

  parameter Modelica.Units.SI.Temperature T_set=55 + 273.15
    "HPWH setpoint temperature [K]";
  parameter Boolean activateTOU=false
    "Activate time of use prioritization" ;
  parameter Boolean HP_only=false
    "HP only mode (no auxiliary back up)" ;
  parameter Boolean manualOnOff=false "Activate external manual on/off signal" ;
  parameter Modelica.Units.SI.Temperature T_set_low=45 + 273.15
    "HPWH setpoint temperature outside TOU period [K]"
    ;
  parameter Modelica.Units.SI.TemperatureDifference delta_T=10
    "Temperature hysteresis [K]";

  parameter Modelica.Units.SI.Temperature T_min_HP=273.15 - 5
    "Minimal HPWH operating condition [K]";

  parameter Real compSpeed=50 "Compressor operating speed [Hz]";
  final parameter Real compIddleSpeed=20.0;

  Modelica.Units.SI.Temperature T_set_cold(start=55 + 273.15)
    "HP setpoint temperature at low external air temperatures [K]";

  Boolean minHP(start=false)
    "HP operating region for the heat pump";

  Modelica.Blocks.Interfaces.RealOutput freq(start=50,fixed=true)
    "Compressor frequency [Hz]"
    ;

  Modelica.Blocks.Interfaces.BooleanOutput OnOff "System on off signal"
    ;

  Modelica.Blocks.Interfaces.RealInput T_water "Water temperature [K]"
    ;

// protected
  Boolean Hyst(start=true,fixed=true) "Hysteresis signal";
  Boolean HystAux(start=true,fixed=true) "Hysteresis signal";
  // Time of use variables
  Boolean TOU( start=true,fixed=true) "Time of use tarif signal";
  Real initTime(start=0,fixed=true);
  Integer day(start=1,fixed=true);

public
  Modelica.Blocks.Interfaces.RealInput T_air "External air temperature [K]"
    ;

  Modelica.Blocks.Interfaces.BooleanOutput OnOffAuxiliary
    "Auxiliary on off control"
    ;
  Modelica.Blocks.Interfaces.BooleanInput onOffSwitch if manualOnOff
    "External on off switch"                                                   ;

protected
  Modelica.Blocks.Interfaces.BooleanInput onOffSwitch_internal;

initial equation

  pre(OnOff)=true;

equation
  connect(onOffSwitch, onOffSwitch_internal);
  if not manualOnOff then
    onOffSwitch_internal=false;
  end if;
  day= (integer(floor(mod(time, 3.1536e7)/86400 + 1)));

//   Mode AUTO
  if T_air<-2+273.15  and not HP_only then
    T_set_cold=45+273.15;
  elseif T_air>=-2+273.15 and T_air<2+273.15  and not HP_only then
    T_set_cold=50+273.15;
  else
    T_set_cold=T_set;
  end if;

  freq= if OnOff then compSpeed else compIddleSpeed;

  TOU=if (time-initTime)<=21600 or (time-initTime)>=79200 then true else false;

  if activateTOU and not TOU then
    Hyst=if T_water<T_set_low-delta_T then true else (if T_water>=T_set_low then false else pre(Hyst));
    HystAux=if T_water<T_set_low-delta_T then true else (if T_water>=T_set_low then false else pre(HystAux));
  else
    Hyst=if T_water<T_set_cold-delta_T then true else (if T_water>=T_set_cold then false else pre(Hyst));
    HystAux=if T_water<T_set-delta_T then true else (if T_water>=T_set then false else pre(HystAux));
  end if;

  OnOffAuxiliary=(not Hyst and HystAux) or (not minHP and Hyst);

  minHP=T_air>=T_min_HP and (T_water<=T_set_cold);
  OnOff=if not manualOnOff then (Hyst and minHP) else (onOffSwitch_internal and Hyst);

  when day<>pre(day) then
    initTime= time;
  end when

  ;
end WaterHeaterHeatPumpController;

within BuildSysPro.Systems.DHW.HeatPump.Components;
model WaterHeaterHeatPumpPoly
  "Polynomial model of air-source heat pump for water heating"

  parameter Modelica.Units.SI.Power Pe_max=670
    "Maximum absorbed power by the heat pump unit at 7°C external air,
    50Hz and a water temperature of 55°C [W]";
  parameter Modelica.Units.SI.Time t_heating=25750
    "Heat-up time at 7°C external air for 10->55°C in tank [s]";
  parameter Modelica.Units.SI.Volume V_tank=0.2
    "Heat-up time at 7°C external air for 10->55°C in tank [m3]";
   parameter Real n_inverter=0.95 "Inverter compressor efficiency";

   // Reference Model specifications
protected
  constant Modelica.Units.SI.Power Pe_max_ref=670
    "Maximum absorbed power by the heat pump unit at 7°C external air,
    50Hz and a water temperature of 55°C [W]";
  constant Modelica.Units.SI.Power Pe_fan_ref=67 "Fixed speed fan power [W]";
  constant Modelica.Units.SI.Time t_heating_ref=25750
    "Atlantic heat-up time at 7°C external air for 10->55°C in tank [s]";
  constant Modelica.Units.SI.Volume V_tank_ref=0.2
    "Heat-up time at 7°C external air for 10->55°C in tank [m3]";

parameter Real[10] Pe_poly_coefs={3.83165093e+04,  -4.34394686e+01,   3.26439628e-02,
        -8.95488047e+01,   4.10985298e-02,  -1.76706502e+02,
         1.84455287e-01,   2.36017967e-01,   8.12744660e-02,
         8.67503132e-02};

parameter Real[10] Pq_poly_coefs={ -1.93054762e+04,  -9.62000742e+01,  -9.94034808e-02,
         1.37286021e+02,  -9.70387915e-02,  -2.73772378e+01,
         2.44497450e-01,  -2.96119602e-01,   5.95326565e-01,
        -9.68183381e-02};

public
  Real Pe_fan(start=0);

  Modelica.Blocks.Interfaces.RealInput T_water "Water temperature [K]"
    ;
  Modelica.Blocks.Interfaces.RealInput T_air "External air temperature [K]"
    ;
  Modelica.Blocks.Interfaces.RealInput speed "Compressor speed [Hz]"
    ;
  Modelica.Blocks.Interfaces.BooleanInput OnOff ;

  Modelica.Blocks.Interfaces.RealOutput Pe_comp
    "Electrical power of the compressor [W]"
    ;
  Modelica.Blocks.Interfaces.RealOutput Pe_tot "Total electrical power [W]"
    ;
  Modelica.Blocks.Interfaces.RealOutput COP_comp "COP of the compressor"
    ;
  Modelica.Blocks.Interfaces.RealOutput COP_tot "Total COP"
    ;

  Modelica.Blocks.Interfaces.RealOutput Pq_cond
    "Heat power at the condensor [W]"
    ;
equation

  Pe_comp=if (OnOff) then (Pe_max/Pe_max_ref)*(Pe_poly_coefs[1]+Pe_poly_coefs[2]*speed+Pe_poly_coefs[3]*speed^2+Pe_poly_coefs[4]*T_water+Pe_poly_coefs[5]*T_water^2+Pe_poly_coefs[6]*T_air+Pe_poly_coefs[7]*T_air^2+Pe_poly_coefs[8]*T_air*T_water+Pe_poly_coefs[9]*T_air*speed+Pe_poly_coefs[10]*T_water*speed) else -1e-4;

  Pq_cond=if (OnOff) then -(t_heating_ref/t_heating)*(V_tank/V_tank_ref)*(Pq_poly_coefs[1]+Pq_poly_coefs[2]*speed+Pq_poly_coefs[3]*speed^2+Pq_poly_coefs[4]*T_water+Pq_poly_coefs[5]*T_water^2+Pq_poly_coefs[6]*T_air+Pq_poly_coefs[7]*T_air^2+Pq_poly_coefs[8]*T_air*T_water+Pq_poly_coefs[9]*T_air*speed+Pq_poly_coefs[10]*T_water*speed) else                                                                                                                                                                                                     -1e-4;

  Pe_fan=if (OnOff) then Pe_fan_ref*(Pe_max/Pe_max_ref) else 0;
  Pe_tot=Pe_comp/n_inverter+Pe_fan;
  COP_comp=sum(-Pq_cond)/noEvent(max(Pe_comp,1e-4));
  COP_tot=sum(-Pq_cond)/noEvent(max(Pe_tot,1e-4))
  ;
end WaterHeaterHeatPumpPoly;

