  connect(InjectionPertes.port, T_int) ;
  connect(InjectionPertes.Q_flow, eCSThermoSol.Perte) ;
  connect(eCSThermoSol.Cons, Cons) ;
  connect(eCSThermoSol.T_out, T_out) 
  ;
end SolarWaterHeater;

within BuildSysPro.Systems.Distribution;
model DistributionPipe "Modelization of a hot/cold distribution system"

  import      Modelica.Units.SI;

  parameter Integer Choix=1  ;

  parameter SI.Length L=20
    "Exchange length of dstribution pipe (if L = 0 then simplified and global calculation of heat losses according to QfouNom"
                                                                                                       ;
  parameter SI.ThermalConductivity U=0.04
    "Linear exchange coefficient, defining the distribution pipe"                               ;
  parameter SI.SpecificHeatCapacity CpLiq=4190
    "Thermal capacity of heat transfer fluid" ;
  parameter Real Rpnre= 0.8 "Ratio of non recoverable thermal losses"
                                                     ;
  parameter Modelica.Units.SI.Power QfouNom=8000
    "Rated power supplied by the production system (boiler)" ;
  parameter Real Cperte=0.025 "Default losses evaluated at 2.5% of QfouNom"
                                                  ;

protected
  SI.MassFlowRate Debit; //Mass flow in the pipe
SI.Power Qper; //Lost heat

public
  Modelica.Blocks.Interfaces.RealOutput WaterOut[2]
    "Vector containing 1- the output fluid temperature (K), 2- the output fluid flow rate (kg/s)"
    ;
  Modelica.Blocks.Interfaces.RealInput WaterIn[2]
    "Vector containing 1- the input fluid temperature (K), 2- the input fluid flow rate (kg/s)"
    ;
  BuildSysPro.BaseClasses.HeatTransfer.Interfaces.HeatPort_a T_int
    "Heatport to connect to the thermal zone" ;
// -----------------------------------------------------------------------------------
equation

// Conservation of flow : WaterIn[2]=WaterOut[2]
  Debit=WaterIn[2];

// Calculation of the distribution pipe losses
  if (L>0) then// CASE : KNOWN PIPE

  // Calculation of the output temperature
    if WaterIn[1] > T_int.T then
      WaterOut[1] = max(T_int.T, WaterIn[1] - (WaterIn[1] - T_int.T)*(1 - exp(-
        U*L/(Debit*CpLiq))));
    else
      WaterOut[1] = min(T_int.T, WaterIn[1] - (WaterIn[1] - T_int.T)*(1 - exp(-
        U*L/(Debit*CpLiq))));
    end if;
  // Calculation of losses
    Qper =Debit*CpLiq*(WaterIn[1] - WaterOut[1]);

  else // CASE : DEFAULT VALUES
  // Calculation of losses
    Qper = Cperte*QfouNom;

  // Calculation of the output temperature
    if (Debit>1e-4) then
      WaterOut[1] = WaterIn[1] - Qper/(Debit*CpLiq);
    else
      WaterOut[1] = T_int.T;
    end if;

end if;

// Calculation of the recoverable heat part
  T_int.Q_flow = -Qper*(1 - Rpnre);

  connect(WaterIn[2], WaterOut[2]) 
  ;
end DistributionPipe;

within BuildSysPro.Systems.Distribution;
model HydraulicPipe "Modeling of a hot or cold water network"

  import      Modelica.Units.SI;

  parameter Boolean Choix = true  ;
  parameter SI.Length L=20
    "Exchange length of dstribution pipe (if L = 0 then simplified and global calculation of heat losses according to QfouNom"
                                                                                                        ;
  parameter SI.ThermalConductivity U=0.04
    "Linear exchange coefficient, defining the distribution pipe"                                ;
  parameter SI.SpecificHeatCapacity CpLiq=4190
    "Thermal capacity of heat transfer fluid" ;
  parameter Real Rpnre= 0.8 "Ratio of non recoverable thermal losses"
                                                     ;
  parameter Modelica.Units.SI.Power QfouNom=8000
     "Rated power supplied by the production system (boiler)" ;
  parameter Real Cperte=0.025
    "Default losses evaluated at 2.5% of QfouNom"  ;

protected
SI.MassFlowRate Debit; ///Mass flow in the pipe
SI.Power Qper; //Lost heat
public
  Modelica.Blocks.Interfaces.RealOutput WaterOut[2]
       "Vector containing 1- the output fluid temperature (K), 2- the output fluid flow rate (kg/s)"
    ;
  Modelica.Blocks.Interfaces.RealInput WaterIn[2]
    "Vector containing 1- the input fluid temperature (K), 2- the input fluid flow rate (kg/s)"
    ;
  BuildSysPro.BaseClasses.HeatTransfer.Interfaces.HeatPort_a T_int
   "Heatport to connect to the thermal zone" ;
// -----------------------------------------------------------------------------------
equation

// Conservation of flow : WaterIn[2]=WaterOut[2]
  WaterIn[2] = WaterOut[2];
  Debit=abs(WaterIn[2]);

// Calculation of the distribution pipe losses
  if Choix then// CASE : KNOWN PIPE

  // Calculation of the output temperature
    if WaterIn[1] > T_int.T then
      WaterOut[1] = max(T_int.T, WaterIn[1] - (WaterIn[1] - T_int.T)*(1 - exp(-
        U*L/(Debit*CpLiq))));
    else
      WaterOut[1] = min(T_int.T, WaterIn[1] - (WaterIn[1] - T_int.T)*(1 - exp(-
        U*L/(Debit*CpLiq))));
    end if;
  // Calculation of losses
    Qper =Debit*CpLiq*(WaterIn[1] - WaterOut[1]);

  else // CASE : DEFAULT VALUES
  // Calculation of losses
    Qper = Cperte*QfouNom;

  // Calculation of the output temperature
    if (Debit>1e-4) then
      WaterOut[1] = WaterIn[1] - Qper/(Debit*CpLiq);
    else
      WaterOut[1] = T_int.T;
    end if;

end if;

// Calculation of the recoverable heat part
  T_int.Q_flow = -Qper*(1 - Rpnre)

  ;
end HydraulicPipe;

within BuildSysPro.Systems.Distribution;
model PumpElecCons "Electric consumption of a pump"

//  input Modelica.SIunits.MassFlowRate Me = 2.5 "Fluid mass flow";
//  input Modelica.SIunits.Temp_C Te = 12.8 "Input temperature of the fluid";
  import      Modelica.Units.SI;

// Weighting coefficients //FFLP = C0 + C1. PLR + C2. PLR 2 + C3.PLR3"
  parameter Real C0=0.350712 ;
  parameter Real C1=0.3085     ;
  parameter Real C2=-0.541370 ;
  parameter Real C3=0.8810   ;

// Rated parameters
  parameter SI.Efficiency etaM = 0.85 "Motor efficiency" ;
  parameter SI.VolumeFlowRate Vrat = 0.0001 "Volume flow rate" ;
  parameter SI.Power Wprat = 20 "Total rated power" ;
  parameter SI.Pressure DPrat = 89700 "Rated pression difference" ;
  parameter SI.VolumeFlowRate VratMin=Vrat/10 "Minimum volume flow" ;

// Fluid characteristics
  parameter SI.SpecificHeatCapacity CpLiq=4180 "Fluid specific heat capacity" ;
  parameter SI.Density rhoLiq=998 "Fluid density" ;
  parameter Real fmloss=0.5
    "Part of energy transmitted from the motor to the fluid"                          ;

protected
  SI.MassFlowRate Debit "Fluid mass flow";
  SI.Efficiency etaP "Pump efficiency";
  SI.Efficiency etaPM "Pump and motor efficiency";
  Real FFLP "Fraction of full-load power";
  Real PLR "Part-load flow ratio";
  SI.Power Wshaft "Shaft power";
  SI.Power qLoss "Heat transfert to fluid stream";

public
  Modelica.Blocks.Interfaces.RealOutput WaterOut[2]
    "Vector containing 1-output fluid temperature (K), 2-output fluid flow rate (kg/s)"
    ;
  Modelica.Blocks.Interfaces.RealInput WaterIn[2]
    "Vector containing 1-input fluid temperature (K), 2-input fluid flow rate (kg/s)"
    ;
  Modelica.Blocks.Interfaces.RealOutput Pelec
    "Electric power consumed by the pump"
    ;
// -----------------------------------------------------------------------------------
equation

// Volume flow conservation : WaterIn[2]=WaterOut[2]
  Debit=WaterIn[2];

// The both following lines are used to set internal parameters and are independent
// of component input values. In an hourly simulation, this block of code may
// be skipped after the first call.
  etaPM =  Vrat*DPrat/Wprat;
  etaP =  etaPM / etaM;

// Calculate the part load ratio based on rated flow
  PLR =  abs(Debit) / rhoLiq / Vrat;

// Calculate the fraction of full-load power based on rating point
  FFLP =  C0+C1*PLR+C2*PLR^2+C3*PLR^3;

// Calculate the actual pump shaft power and motor power
  if Debit>VratMin*rhoLiq then
    Pelec = Wprat*FFLP;
    Wshaft = Pelec*etaM;
  else
    Pelec=0;
    Wshaft=0;
  end if;

// Calculate the leaving fluid conditions
  qLoss =  Wshaft*(1-etaP) + (Pelec-Wshaft)*fmloss;
  WaterOut[1] = WaterIn[1] + qLoss/Debit/CpLiq;

  connect(WaterIn[2], WaterOut[2]) 
  ;
end PumpElecCons;

within BuildSysPro.Systems.Distribution;
function Pump_fct
  "Model of oriented pumps to calculate the consumption of air-conditioned buildings"

// INPUT VARIABLES :

// Input

  input Modelica.Units.SI.MassFlowRate Me=2.5 "Flow rate";
  input Modelica.Units.NonSI.Temperature_degC Te=12.8
    "Input fluid temperature";

//Parameters

// Weighting coefficients //FFLP = C0 + C1. PLR + C2. PLR 2 + C3.PLR3"

  input Real C0=0.350712                                                                                    ;

  input Real C1=0.3085                                                                                     ;

  input Real C2=-0.541370                                                                                  ;

  input Real C3=0.8810                                                                                  ;

// Nominal characteristics

  input Modelica.Units.SI.Efficiency etaM=0.85 "Motor efficiency"
    ;

  input Modelica.Units.SI.VolumeFlowRate Vrat=0.0063
    "Nominal volume flow"
    ;

  input Modelica.Units.SI.Power Wprat=1119 "Total nominal power"
    ;

  input Modelica.Units.SI.Pressure DPrat=89700
    "Nominal pressure difference"
    ;

// Fluid characteristics
  input Modelica.Units.SI.SpecificHeatCapacity CpLiq=4180
    "Heat capacity"
    ;
  input Modelica.Units.SI.Density rhoLiq=998 "Density of fluid"
    ;

  input Real fmloss "Transmitted energy to fluid" ;
 // OUTPUT VARIABLES

  output Modelica.Units.NonSI.Temperature_degC Ts
    "Output fluid temperature";
  output Modelica.Units.SI.Power Wp "Absorbed power by the motor";

  output Modelica.Units.SI.Power qLoss; // heat transfert to fluid stream

protected
  Modelica.Units.SI.Efficiency etaP;  //pump efficiency
  Modelica.Units.SI.Efficiency etaPM; //pump and motor efficiency
    Real FFLP; //fraction of full-load power
    Real PLR; //part-load flow ratio
  Modelica.Units.SI.Power Wshaft;  // shaft power

algorithm
// The both following lines are used to set internal parameters and is independent
//of component input values. In an hourly simulation, this block of code may
// be skipped after the first call.
        etaPM := Vrat*DPrat/Wprat;
        etaP := etaPM / etaM;

// Calculate the part load ratio based on rated flow
        PLR := abs(Me) / rhoLiq / Vrat;

// Calculate the fraction of full-load power based on rating point
        FFLP := C0+C1*PLR+C2*PLR^2+C3*PLR^3;

//Calculate the actual pump shaft power and motor power
        Wp :=Wprat*FFLP;
        Wshaft :=Wp*etaM;

// Calculate the leaving fluid conditions
        qLoss := Wshaft*(1-etaP) + (Wp-Wshaft)*fmloss;
        Ts := Te + qLoss/Me/CpLiq

  ;
end Pump_fct;

within BuildSysPro.Systems.Distribution;
model ThreeWayValveAndPump "Three ways valve with water pump"

  parameter Modelica.Units.SI.Power Pe_cons_WP=30;
  parameter Modelica.Units.SI.Time D=30
    "Delay time to switch from one way to other";
  parameter Modelica.Units.SI.MassFlowRate MFR=0.38 "Water mass flow rate";
parameter Real MFR_reduction=0.6
    "Percentage of water mass flow rate during compressor off function";
  parameter Modelica.Units.SI.MassFlowRate MFR_min=1e-3
    "Débit minimal du radiateur pour empecher l'arrêt de la simulation";
Real min_pos_V3V = 1e-3;

  Modelica.Units.SI.MassFlowRate m_flow;
  Modelica.Units.SI.Energy Ee_cons(start=0);
Real x_V3V;

  Modelica.Blocks.Interfaces.RealInput port_in_HP[2] "1:Temp / 2:m_flow"
    ;
  Modelica.Blocks.Interfaces.RealOutput port_out_HP[2] "1:Temp / 2:m_flow"
    ;
 input Modelica.Blocks.Interfaces.IntegerInput  mode
    ;

  Modelica.Blocks.Interfaces.RealInput port_in_DHW[2] "1:Temp / 2:m_flow"
    ;
  Modelica.Blocks.Interfaces.RealOutput port_out_DHW[2] "1:Temp / 2:m_flow"
    ;
  Modelica.Blocks.Interfaces.RealInput port_in_HC[2] "1:Temp / 2:m_flow"
    ;
  Modelica.Blocks.Interfaces.RealOutput port_out_HC[2] "1:Temp / 2:m_flow"
    ;

// mode : 1 - HEATING CIRCUIT - COMPRESSOR ON  + ELECTRIC BACKUP OFF  - WP ON NOMINAL MASS FLOW RATE
// mode : 2 - DHW CIRCUIT     - COMPRESSOR ON  + ELECTRIC BACKUP OFF  - WP ON NOMINAL MASS FLOW RATE
// mode : 3 - HEATING CIRCUIT - COMPRESSOR ON  + ELECTRIC BACKUP ON   - WP ON NOMINAL MASS FLOW RATE
// mode : 4 - DHW CIRCUIT     - COMPRESSOR OFF + ELECTRIC BACKUP ON   - WP OFF NOMINAL MASS FLOW RATE
// mode : 5 - HEATING CIRCUIT - COMPRESSOR OFF + ELECTRIC BACKUP ON   - WP ON NOMINAL MASS FLOW RATE
// mode : 6 - HEATING CIRCUIT - COMPRESSOR OFF + ELECTRIC BACKUP ON   - WP ON NOMINAL MASS FLOW RATE
// mode : 7 - HEATING CIRCUIT - COMPRESSOR OFF + ELECTRIC BACKUP OFF  - WP ON REDUCED MASS FLOW RATE
// mode : 8 - DHW CIRCUIT     - COMPRESSOR OFF + ELECTRIC BACKUP OFF  - WP ON REDUCED MASS FLOW RATE
// mode : 9 - ALL System OFF
// Connexions 1:Temp / 2:m_flow

  Modelica.Blocks.Continuous.FirstOrder firstOrder_x_V3V(T=D/10, y_start=
        MFR_min)
    ;
  Modelica.Blocks.Continuous.FirstOrder firstOrder_m_flow(T=D/10, y_start=
        MFR_min)
    ;

  Modelica.Blocks.Interfaces.RealOutput Pe_cons ;


equation

  //DHW
if noEvent(mode == 2) then
  x_V3V = 1-min_pos_V3V;
  m_flow = MFR;

  //HEATING
elseif noEvent(mode == 1) or noEvent(mode == 3) or noEvent(mode ==5) or noEvent(mode ==6) then
  x_V3V = min_pos_V3V;
  m_flow = MFR;

  //HEATING
elseif noEvent(mode == 7) then
  x_V3V = min_pos_V3V;
  m_flow = MFR*MFR_reduction;

    //DHW
elseif noEvent(mode == 8) then
  x_V3V = 1-min_pos_V3V;
  m_flow = MFR*MFR_reduction;

    //HEATING
elseif noEvent(mode == 9) then
  x_V3V = min_pos_V3V;
  m_flow = MFR_min;

else
  x_V3V = min_pos_V3V;
  m_flow = MFR_min;

end if;

firstOrder_x_V3V.u  = x_V3V;
firstOrder_m_flow.u = m_flow;

port_in_HP[1]   = port_out_DHW[1];
port_in_HP[1]   = port_out_HC[1];

//Mass flow rate distribution
port_out_DHW[2] = firstOrder_m_flow.y*firstOrder_x_V3V.y;
port_out_HP[2]  = firstOrder_m_flow.y;

//Mass balance
port_out_HP[2] = port_out_DHW[2] + port_out_HC[2];

//Energy balance
port_out_HP[2]*port_out_HP[1] = port_in_DHW[2]*port_in_DHW[1] + port_in_HC[2]*port_in_HC[1];

Pe_cons = if noEvent(mode==7) or noEvent(mode==8) then Pe_cons_WP*MFR_reduction elseif noEvent(mode==9) then 0.0 else Pe_cons_WP;
der(Ee_cons)=noEvent(Pe_cons)

 ;
end ThreeWayValveAndPump;

within BuildSysPro.Systems.HVAC.Emission.ElectricHeater;
model JouleHeatingPIControlled "Electric convector with PI control"

  parameter Modelica.Units.SI.Power Pnom=1500 "Nominal power of the convector"
    ;

protected
  Modelica.Blocks.Continuous.LimPID PI1(
    controllerType=Modelica.Blocks.Types.SimpleController.PI,
    Td=0.,
    yMin=0.,
    yMax=1,
    k=1,
    Ti=900,
    Ni=1,
    initType=Modelica.Blocks.Types.Init.NoInit) ;

  Modelica.Blocks.Continuous.FirstOrder         firstOrder(T=60) ;

public
 Modelica.Blocks.Interfaces.RealInput T_sp "Setpoint temperature"
    ;
  Modelica.Blocks.Interfaces.RealInput T_int "Indoor temperature measure"
    ;

  Modelica.Blocks.Interfaces.RealOutput Pelec
    ;
  Modelica.Blocks.Math.Gain gain(k=Pnom)
    ;
equation
  connect(PI1.u_s, T_sp) ;

  connect(PI1.u_m, T_int) ;
  connect(firstOrder.y, Pelec) ;
