within BuildSysPro.Systems.HVAC.Emission.Radiator;
model HotWaterRadiator "Hot water radiator"

  import      Modelica.Units.SI;

  parameter Integer Type=2
    "Radiator type for determination of inertia (water filling and radiator body) by a correlation based on rated power"
    ;
  parameter SI.EnergyFlowRate Pnom=1000
    "Radiator rated power. Certita database gives manufacturers data certified standard NF (French standard) for a 50°C temperature gap"
    ;
  parameter SI.TemperatureDifference DeltaTnom=50
    "According to water temperature of distribution system, temperature gap between air and radiator (by default, in Certita conditions : 50°C)"
    ;
  parameter Real nNom=1.29 "Slope of emission line"
    ;
  parameter Integer N=10 "Number of discretized elements"
    ;
  parameter Real CoeffCorrectif=1.1
    "For a low number of elements (<20), radiator rated power can be corrected with this parameter"
    ;
  parameter Real FracRad(min=0, max=1) = 0.35
    "Part of radiative emission in comparison with the convective part (between 0 and 1)"
    ;

  SI.Temperature Ta "Temperature of the room";
  SI.Temperature Te_m "mean temperature of water";
  SI.TemperatureDifference DeltaT_m
    "Mean temperature difference between an element of the radiator and the room";
  SI.EnergyFlowRate Ptot "Puissance dissipée par le radiateur à la pièce";

protected
  parameter Real Crecord[3,2]=[39.8,35.6;  13.8,11.1;  14.0,7.9];
  parameter SI.HeatCapacity Ceau=Crecord[Type,1]*Pnom
    "Volume of water in the radiator"
    ;
  parameter SI.HeatCapacity Cmetal=Crecord[Type,2]*Pnom
    "Mass of radiator body without water (linear function applied to a cast iron radiator of Cp = 500)"
    ;
  parameter SI.SpecificHeatCapacity CpEau=4180
    "Specific heat capacity of water"
    ;
  SI.HeatCapacity Ci "Heat capacity of an element [J/K]";
  SI.Temperature Te[N+1] "Temperature of input water in element i";
  SI.Temperature TRad[N] "Temperature of element i";
  SI.TemperatureDifference DeltaT[N]
    "Temperature difference between an element and the room";
  SI.EnergyFlowRate P[N] "Power dissipated by an element to the room";

public
  BuildSysPro.BaseClasses.HeatTransfer.Interfaces.HeatPort_b Rad
    "Radiative part of dissipated heat to the room" ;
  BuildSysPro.BaseClasses.HeatTransfer.Interfaces.HeatPort_b Conv
    "Convective part of dissipated heat to the room" ;

  Modelica.Blocks.Interfaces.RealInput WaterIn[2]
    "Vector containing 1- the input fluid temperature (K), 2- the input fluid flow rate (kg/s)"
    ;
  Modelica.Blocks.Interfaces.RealOutput WaterOut[2]
    "Vector containing 1- the output fluid temperature (K), 2- the output fluid flow rate (kg/s)"
    ;
equation
  // Heat capacity of an element
  Ci = (Cmetal + Ceau)/N;

  WaterOut[2] = WaterIn[2];

// Temperatures are fixed
  Ta           = Conv.T;
  Te[1]        =WaterIn[1];
  WaterOut[1] = TRad[N];

// Thermal balance of an element i
for i in 1:N loop
  Te[i+1]  = TRad[i];
  DeltaT[i]= abs(TRad[i]-Ta);
  if TRad[i]>Ta then
      P[i] = CoeffCorrectif*Pnom*(DeltaT[i]/DeltaTnom)^nNom/N;
  else // Particular case of air heating the radiator
      P[i] = -Pnom*(DeltaT[i]/DeltaTnom)/N;
  end if;
    WaterIn[2]*CpEau*(Te[i] - TRad[i]) = P[i] + Ci*der(TRad[i]);
end for;

// Means
 Te_m= sum(TRad)/N;
 DeltaT_m= sum(DeltaT)/N;

// Repartition of heating between radiative and convective
  Ptot        = sum(P);
  Rad.Q_flow  = -FracRad*Ptot;
  Conv.Q_flow = -(1-FracRad)*Ptot

  ;
end HotWaterRadiator;

within BuildSysPro.Systems.HVAC.Emission.Radiator;
model HotWaterRadiatorRegul "Hot water radiator with control"

  import      Modelica.Units.SI;

  parameter Integer Type=2
    "Radiator type for determination of inertia (water filling and radiator body) by a correlation based on rated power"
    ;
  parameter SI.EnergyFlowRate Pnom=1000
    "Radiator rated power. Certita database gives manufacturers data certified standard NF (French standard) for a 50°C temperature gap"
    ;
  parameter SI.TemperatureDifference DeltaTnom=50
    "According to water temperature of distribution system, temperature gap between air and radiator (by default, in Certita conditions : 50°C)"
    ;
  parameter Real nNom=1.29 "Slope of emission line"
    ;
  parameter SI.MassFlowRate DebitNom=0.01 "Nominal water flow rate"
    ;
  parameter Integer N=10 "Number of discretized elements"
    ;
  parameter Real CoeffCorrectif=1.1
    "For a low number of elements (<20), radiator rated power can be corrected with this parameter"
    ;
  parameter Real FracRad(min=0, max=1) = 0.35
    "Part of radiative emission in comparison with the convective part (between 0 and 1)"
    ;

  SI.MassFlowRate Debit "Water flow rate in radiator";
  SI.Temperature Ta "Temperature of the room";
  SI.EnergyFlowRate Ptot "Puissance dissipée par le radiateur à la pièce";

protected
  parameter Real Crecord[3,2]=[39.8,35.6;  13.8,11.1;  14.0,7.9];
  parameter SI.HeatCapacity Ceau=Crecord[Type,1]*Pnom
    "Volume of water in the radiator"
    ;
  parameter SI.HeatCapacity Cmetal=Crecord[Type,2]*Pnom
    "Mass of radiator body without water (linear function applied to a cast iron radiator of Cp = 500)"
    ;
  parameter SI.SpecificHeatCapacity CpEau=4180
    "Specific heat capacity of water"
    ;
  SI.HeatCapacity Ci "Heat capacity of an element [J/K]";
  SI.Temperature Te[N+1] "Temperature of input water in element i";
  SI.Temperature TRad[N] "Temperature of element i";
  SI.TemperatureDifference DeltaT[N]
    "Temperature difference between an element and the room";
  SI.EnergyFlowRate P[N] "Power dissipated by an element to the room";

public
  BuildSysPro.BaseClasses.HeatTransfer.Interfaces.HeatPort_b Rad
    "Radiative part of dissipated heat to the room" ;
  BuildSysPro.BaseClasses.HeatTransfer.Interfaces.HeatPort_b Conv
    "Convective part of dissipated heat to the room" ;
  Modelica.Blocks.Interfaces.RealInput Regulation
    "Valve opening control (between 0 and 1)"
     ;

  Modelica.Blocks.Interfaces.RealInput WaterIn[2]
    "Vector containing 1- the input fluid temperature (K), 2- the input fluid flow rate (kg/s)"
    ;
  Modelica.Blocks.Interfaces.RealOutput WaterOut[2]
    "Vector containing 1- the output fluid temperature (K), 2- the output fluid flow rate (kg/s)"
    ;
equation
// Heat capacity of an element
  Ci = (Cmetal + Ceau)/N;

// Water flow rate varies depending on room heating needs, and can not exceed nominal water flow rate
  Debit        = min(1,max(Regulation,0))*DebitNom;
  WaterOut[2] = Debit;

// Temperatures are fixed
  Ta           = Conv.T;
  Te[1]        =WaterIn[1];
  WaterOut[1] = TRad[N];

// Thermal balance of an element i
for i in 1:N loop
  Te[i+1]  = TRad[i];
  DeltaT[i]= abs(TRad[i]-Ta);
  if TRad[i]>Ta then
      P[i] = CoeffCorrectif*Pnom*(DeltaT[i]/DeltaTnom)^nNom/N;
  else // Particular case of air heating the radiator
      P[i] = -Pnom*(DeltaT[i]/DeltaTnom)/N;
  end if;
  Debit*CpEau*(Te[i]-TRad[i]) = P[i] + Ci*der(TRad[i]);
end for;

// Repartition of heating between radiative and convective
  Ptot        = sum(P);
  Rad.Q_flow  = -FracRad*Ptot;
  Conv.Q_flow = -(1-FracRad)*Ptot

  ;
end HotWaterRadiatorRegul;

within BuildSysPro.Systems.HVAC.Emission.Radiator;
model HotWaterRadiatorRegulDistrib
  "Hot water radiator with control and distribution"

  import      Modelica.Units.SI;

  parameter Integer Type=2
    "Radiator type for determination of inertia (water filling and radiator body) by a correlation based on rated power"
    ;
  parameter SI.EnergyFlowRate Pnom=1000
    "Radiator rated power. Certita database gives manufacturers data certified standard NF (French standard) for a 50°C temperature gap"
    ;
  parameter SI.TemperatureDifference DeltaTnom=50
    "According to water temperature of distribution system, temperature gap between air and radiator (by default, in Certita conditions : 50°C)"
    ;
  parameter Real nNom=1.29 "Slope of emission line"
    ;
  parameter SI.MassFlowRate DebitNom=0.01 "Nominal water flow rate"
    ;
  parameter Integer N=10 "Number of discretized elements"
    ;
  parameter Real CoeffCorrectif=1.1
    "For a low number of elements (<20), radiator rated power can be corrected with this parameter"
    ;
  parameter Real FracRad(min=0, max=1) = 0.35
    "Part of radiative emission in comparison with the convective part (between 0 and 1)"
    ;

  Modelica.Blocks.Interfaces.RealInput Regulation
    "Valve opening control (between 0 and 1)"           ;
  BuildSysPro.BaseClasses.HeatTransfer.Interfaces.HeatPort_b Rad
    "Radiative part of dissipated heat to the room" ;
  BuildSysPro.BaseClasses.HeatTransfer.Interfaces.HeatPort_b Conv
    "Convective part of dissipated heat to the room" ;

  HotWaterRadiatorRegul radiateurNF(
    N=N,
    Pnom=Pnom,
    DeltaTnom=DeltaTnom,
    nNom=nNom,
    DebitNom=DebitNom,
    CoeffCorrectif=CoeffCorrectif,
    FracRad=FracRad,
    Type=Type)
    ;

  Modelica.Blocks.Interfaces.RealInput WaterIn[2]
    "Vector containing 1- the input fluid temperature (K), 2- the input fluid flow rate (kg/s)"
    ;
  Modelica.Blocks.Interfaces.RealOutput WaterOut[2]
    "Vector containing 1- the output fluid temperature (K), 2- the output fluid flow rate (kg/s)"
    ;

equation
  // Water flow rate conservation
  WaterOut[2] = WaterIn[2];

// if the water flow is too low, heating needs are made null beacause
// - there is an error of dimensioning
// - distribution system is off and the radiator should not dissipate heat
  radiateurNF.Regulation=if DebitNom < WaterIn[2] then Regulation else 0;

// Output temperature is the weighted mean by water flows : on the output of the radiator and on the distribution system
  WaterOut[1] = (WaterIn[1]*(WaterIn[2] - radiateurNF.WaterOut[2]) +
    radiateurNF.WaterOut[1]*radiateurNF.WaterOut[2])/WaterOut[2];

  connect(radiateurNF.Conv, Conv) ;
  connect(radiateurNF.Rad, Rad) ;
  connect(WaterIn, radiateurNF.WaterIn) 
  ;
end HotWaterRadiatorRegulDistrib;

within BuildSysPro.Systems.HVAC.Emission.Radiator;
model Radiator_EN442 "Radiator model based on the EN442 standard"

  import      Modelica.Units.SI;
  extends
    BuildSysPro.Systems.HVAC.Emission.Radiator.Components.CharacteristicEquation;

  // Parameters

  /*parameter Integer Type=2 
    "Type de radiateur déterminant l'inertie (masse à sec et volume d'eau) par une corrélation sur la puissance nominale"
    ;*/

    parameter Boolean useInertia=false "Steady state modelling of dynamics"
  ;
    replaceable package Medium =
      Modelica.Media.Interfaces.PartialSimpleMedium                          ;

  parameter SI.Mass MediumMass "Mass of water" ;
  parameter SI.Mass BodyMass "Radiator mass" ;
  parameter SI.SpecificHeatCapacity cpBody=500
    "Specific heat capacity of the radiator body (ex. 500J/kg/K for cast iron)" ;

    // Variables

  SI.TemperatureDifference DTlm=(WaterIn[1] - WaterOut[1])/Modelica.Math.log((
      WaterIn[1] - (Conv.T + Rad.T)/2)/(WaterOut[1] - (Conv.T + Rad.T)/2))
    "Logaritmic mean temperature difference, given for information, EN442 being based on arithmetic mean temperature difference";
inner SI.Temperature   T_HWR(start=273.15+60)
    "Temperature of the hot water radiator";

// Components

  Modelica.Blocks.Interfaces.RealInput WaterIn[2](start={330,1})
    "1:Temp / 2:m_flow" ;
  Modelica.Blocks.Interfaces.RealOutput WaterOut[2](start={330,1})
    "1:Temp / 2:m_flow" ;

equation
  assert((WaterIn[1] - Conv.T)/(WaterOut[1] - Conv.T) < 3, "Arithmetic mean temperature difference assumption leads to a deviation exceeding 5% (compared to LMTD)");

  // Energy balance
  if not useInertia then
   0=WaterIn[2]*Medium.cp_const*(WaterIn[1] - WaterOut[1]) - radEqua.Qtot;
   T_HWR=(WaterIn[1] + WaterOut[1])/2;

  else
    (MediumMass*Medium.cp_const*WaterOut[1] + BodyMass*cpBody)*der(T_HWR) =
      WaterIn[2]*Medium.cp_const*(WaterIn[1] - WaterOut[1]) - radEqua.Qtot;
  //   T_HWR= (WaterIn[1]+WaterOut[1])/2; // Assure la cohérence de puissance entre le régime statique et dynamique
   T_HWR=WaterOut[1];   // Assure la continuité de la température de radiateur.
   //En revanche il faut intégrer une discrétisation sinon les conditions nominales ne fournissent pas
  end if;

   // Continuity equation
  WaterIn[2] = WaterOut[2]

  ;
end Radiator_EN442;

within BuildSysPro.Systems.HVAC.Emission.Radiator.Components;
partial model BasedCharacteristicEquation
  "Partial model for characteristic equation of a radiator (EN442)"
 import      Modelica.Units.SI;
  parameter SI.EnergyFlowRate Pnom=411
    "Nominal power for a DT=50 K, based on inlet temperature 75/65"
    ;

  parameter SI.TemperatureDifference DTnom=50
    "Temperature difference (air to water) at nominal operating point"
    ;

  parameter Real nNom=1.225 "Slope at nominal point"
    ;
  // Other parameters
  parameter Real FracRad(min=0, max=1) = 0.35 "Radiative fraction of heat"
    ;

  parameter Real Km=Pnom/DTnom^nNom
    "Km coefficient (sometimes refers as KS or UA coefficient) used in the Characteristic equation";

    // Variables
  outer SI.Temperature   T_HWR(start=273.15+60)
    "Temperature of the hot water radiator";

SI.EnergyFlowRate  Qtot "Heating power output from the radiator";
  //Components
  BaseClasses.HeatTransfer.Interfaces.HeatPort_b   Rad
    "HeatPort for long wave radiation exchanges"     ;

  BaseClasses.HeatTransfer.Interfaces.HeatPort_b             Conv
    "HeatPort for convective heat transfers"     ;
equation
  Qtot=-(Conv.Q_flow+Rad.Q_flow)
  ;
end BasedCharacteristicEquation;

within BuildSysPro.Systems.HVAC.Emission.Radiator.Components;
model BasedCharacteristicEquation1
  "Room temperature based on average between radiative and convective temperatures"
 import      Modelica.Units.SI;
  extends
    BuildSysPro.Systems.HVAC.Emission.Radiator.Components.BasedCharacteristicEquation;

   // Variables
   SI.TemperatureDifference DTam
    "Arithmetic mean temperature difference for radiation and convection";

protected
 Real g0 "Internal variable returned by the f_pow function";
  Real g1
    "Internal variable (corresponding to the derivative) returned by the f_pow function";
equation
    DTam= T_HWR-(Conv.T+Rad.T)/2;
    (g0,g1)=BuildSysPro.Utilities.Math.f_Pow(abs(DTam),0.1,nNom-1);
    -Conv.Q_flow=(1-FracRad)*Km*DTam*g0;
    -Rad.Q_flow=FracRad*Km*DTam*g0

  ;
end BasedCharacteristicEquation1;

within BuildSysPro.Systems.HVAC.Emission.Radiator.Components;
model BasedCharacteristicEquation2
  "Distinction between radiative and convective temperatures for heat transfers"

  import      Modelica.Units.SI;
  extends
    BuildSysPro.Systems.HVAC.Emission.Radiator.Components.BasedCharacteristicEquation;

   // Variables
   SI.TemperatureDifference DTam_rad
    "Arithmetic mean temperature difference for radiation";
   SI.TemperatureDifference DTam_conv
    "Arithmetic mean temperature difference for convective heat transfers";

protected
 Real g0_rad "Internal variable returned by the f_pow function";
  Real g1_rad
    "Internal variable (corresponding to the derivative) returned by the f_pow function";

 Real g0_conv "Internal variable returned by the f_pow function";
  Real g1_conv
    "Internal variable (corresponding to the derivative) returned by the f_pow function";
equation
 // Radiative part
    DTam_rad= T_HWR-Rad.T;
    (g0_rad,g1_rad)=BuildSysPro.Utilities.Math.f_Pow(abs(DTam_rad),0.1,nNom-1);
    -Rad.Q_flow=FracRad*Km*DTam_rad*g0_rad;

// Convective part
   DTam_conv= T_HWR-Conv.T;
    (g0_conv,g1_conv)=BuildSysPro.Utilities.Math.f_Pow(abs(DTam_conv),0.1,nNom-1);
    -Conv.Q_flow=(1-FracRad)*Km*DTam_conv*g0_conv

  ;
end BasedCharacteristicEquation2;

within BuildSysPro.Systems.HVAC.Emission.Radiator.Components;
partial model CharacteristicEquation
  "Model for characteristic equation of a radiator (EN442)"
 import      Modelica.Units.SI;

  parameter SI.EnergyFlowRate Pnom=411
    "Nominal power for a DT=50 K, based on inlet temperature 75/65"
    ;

  parameter SI.TemperatureDifference DTnom=50
    "Temperature difference (air to water) at nominal operating point"
    ;

  parameter Real nNom=1.225 "Slope at nominal point"
    ;
  // Other parameters
  parameter Real FracRad(min=0, max=1) = 0.35 "Radiative fraction of heat"
    ;

  final parameter Real Km=Pnom/DTnom^nNom
    "Km coefficient (sometimes refers as KS or UA coefficient) used in the Characteristic equation";

