    "Electrical power consumption at gamma=0 ";

protected
  Boolean x;

public
  Modelica.Blocks.Interfaces.BooleanInput SaisonChauff
    "Seasonal heating cut-off (=false)"   ;
  PGS.PGS_stove pGVH_poe(
    Pe0=Pe0,
