 if RegPI.y < (Pcombmin/Pcombmax) then
    x = false;
  elseif RegPI.y > (Pcombmin/Pcombmax + 0.20) then
    x = true;
  else
    x = pre(x);
 end if;

  connect(SaisonChauff, pGVH_poe.presence)
                                       ;
  connect(add.y, pGVH_poe.Toff) ;
  connect(CpEau.port, temperatureSensor.port) ;
  connect(CpEau.port, preHeaFlo1.port) ;
  connect(loiDEau.T_sp, add.u1) ;
  connect(realExpression.y, add.u2) ;
  connect(T_ext, loiDEau.T_ext) ;
  connect(BilanEau.y, preHeaFlo1.Q_flow) ;
  connect(loiDEau.T_sp, RegPI.u_s) ;
  connect(temperatureSensor.T, RegPI.u_m)        ;
  connect(pGVH_poe.PowerOut, CpEau.port) ;
  connect(pGVH_poe.Tsens, CpEau.port) ;
  connect(switch1.y, pGVH_poe.g) ;
  connect(RegPI.y, switch1.u1) ;
  connect(booleanExpression.y, switch1.u2) ;
  connect(realExpression2.y, switch1.u3) ;
  connect(add1.y, pGVH_poe.Ton) ;
  connect(loiDEau.T_sp, add1.u1) ;
  connect(realExpression1.y, add1.u2) ;
  connect(WaterIn, loiDEau.RetourDEau) ;
  connect(temperatureSensor.T, WaterOut[1]) ;
  connect(DebitExp.y, WaterOut[2]) 
  ;
end WoodBoiler;

within BuildSysPro.Systems.Solar.PV.BaseClasses.Optics;
model PVTransmissionFactors
  "Calculation of direct, diffuse and albedo transmission factors of incident rays on a photovoltaic module"

  //Model parameters
  parameter Boolean use_incl_in=false "Prescribed or fixed PV panel tilt"
                                                                         ;
  parameter Boolean use_azimut_in=false "Prescribed or fixed PV panel azimut"
                                                                             ;


  parameter Modelica.Units.NonSI.Angle_deg incl=30
    "PV panel tilt relative to the horizontal (0° upward, 180° downward)"
    ;
  parameter Modelica.Units.NonSI.Angle_deg azimut=0
    "PV panel azimuth - orientation relative to the South (S=0°, E=-90°, W=90°, N=180°)"
    ;
  parameter Integer salete=0
    "0 - Clean panels, 1 - Slightly dirt panels, 2 - Intermediately dirt panels, 3 - Very dirt panels"
    ;

  //Intermediate variables
protected
  Real cosIncidence "Cosine of incident rays angle relative to the normal";
  Modelica.Units.NonSI.Angle_deg angle_incidence "Angle of incidence in °";
  Real transmittance_rel "Relative transmittance due to dirt";
  Real a_r "Parameter a_r";
  Real c2 "Coefficient c2";

public
  BuildSysPro.BoundaryConditions.Solar.Interfaces.SolarFluxInput G[10]
    "Solar flux: {DIFH, DIRN, DIRH, GLOH, t0, CosDir[1:3], Solar azimuth angle, Solar elevation angle}"
    ;
  Modelica.Blocks.Interfaces.RealOutput FT_B "Direct transmission factor"
                                     ;
  Modelica.Blocks.Interfaces.RealOutput FT_D
    "Isotropic diffuse transmission factor" ;
  Modelica.Blocks.Interfaces.RealOutput FT_A
    "Albedo reflexion transmission factor" ;


  // Public connector for tilt and azimut
  Modelica.Blocks.Interfaces.RealInput incl_in if use_incl_in
    "PV panel tilt relative to the horizontal (0° upward, 180° downward)"
           ;
  Modelica.Blocks.Interfaces.RealInput azimut_in if use_azimut_in
    "PV panel azimuth - orientation relative to the South (S=0°, E=-90°, W=90°, N=180°)"
           ;

  //Internal connectors
protected
   Modelica.Blocks.Interfaces.RealInput incl_in_internal "Internal connector for optional configuration";
   Modelica.Blocks.Interfaces.RealInput azimut_in_internal "Internal connector for optional configuration";

equation
  connect(incl_in, incl_in_internal);
  if not use_incl_in then incl_in_internal=incl;
  end if;

  connect(azimut_in, azimut_in_internal);
  if not use_azimut_in then azimut_in_internal=azimut;
  end if;


  cosIncidence = BuildSysPro.BoundaryConditions.Solar.Utilities.CosI(
    azimut=azimut_in_internal,
    incl=incl_in_internal,
    CosDir=G[6:8]);
  angle_incidence = 180*acos(cosIncidence)/Modelica.Constants.pi;

  if salete == 0 then
    transmittance_rel = 1;
    a_r = 0.17;
    c2 = -0.069;
  elseif salete == 1 then
    transmittance_rel = 0.98;
    a_r = 0.20;
    c2 = -0.054;
  elseif salete == 2 then
    transmittance_rel = 0.97;
    a_r = 0.21;
    c2 = -0.049;
  else
    transmittance_rel = 0.92;
    a_r = 0.27;
    c2 = -0.023;
  end if;

  FT_B = if noEvent(angle_incidence < 90) then transmittance_rel*(1 - (
    Modelica.Math.exp(-cosIncidence/a_r) - Modelica.Math.exp(-1/a_r)/(1 -
    Modelica.Math.exp(-1/a_r)))) else 0;
  FT_D = if noEvent(abs(incl)<180) then transmittance_rel*(1 - Modelica.Math.exp(-1/a_r*(4/(3*Modelica.Constants.pi)
    *(Modelica.Math.sin(incl_in_internal*Modelica.Constants.pi/180) + (Modelica.Constants.pi
     - incl_in_internal*Modelica.Constants.pi/180 - Modelica.Math.sin(incl_in_internal*Modelica.Constants.pi
    /180))/(1 + Modelica.Math.cos(incl_in_internal*Modelica.Constants.pi/180))) + c2*(
    Modelica.Math.sin(incl_in_internal*Modelica.Constants.pi/180) + (Modelica.Constants.pi
     - incl_in_internal*Modelica.Constants.pi/180 - Modelica.Math.sin(incl_in_internal*Modelica.Constants.pi
    /180))/(1 + Modelica.Math.cos(incl_in_internal*Modelica.Constants.pi/180)))^2))) else 0;
  FT_A = if noEvent(abs(incl)>0) then transmittance_rel*(1 -
    Modelica.Math.exp(-1/a_r*(4/(3*Modelica.Constants.pi)*(
    Modelica.Math.sin(incl_in_internal*Modelica.Constants.pi/180) + (incl_in_internal*Modelica.Constants.pi
    /180 - Modelica.Math.sin(incl_in_internal*Modelica.Constants.pi/180))/(1 -
    Modelica.Math.cos(incl_in_internal*Modelica.Constants.pi/180))) + c2*(
    Modelica.Math.sin(incl_in_internal*Modelica.Constants.pi/180) + (incl_in_internal*Modelica.Constants.pi
    /180 - Modelica.Math.sin(incl_in_internal*Modelica.Constants.pi/180))/(1 -
    Modelica.Math.cos(incl_in_internal*Modelica.Constants.pi/180)))^2))) else 0

  ;
end PVTransmissionFactors;

within BuildSysPro.Systems.Solar.PV.BaseClasses.Thermal;
model EfficiencyFunctionOfTemp
  "Photovoltaic performance model depending on temperature"

  parameter Real eta_STC=0.15
    "PV panel (electric) efficiency in STC conditions";
  parameter Real mu_T=-0.5 "Temperature coefficient on the performance (% / K)";

  Modelica.Blocks.Interfaces.RealInput T "PV cells temperature (K)"
