model ParallelTubesActiveSolarWall
  "a tube height in the solar active wall"
  parameter Modelica.Units.NonSI.Temperature_degC Tstart=25;
  parameter Integer n=10 "number of meshes according to the direction of the tube";

  parameter Modelica.Units.SI.Area Stot=9 "solar collection surface";
  parameter Modelica.Units.SI.MassFlowRate q=Stot*30/3600
    "total mass flow";
  parameter Modelica.Units.SI.SpecificHeatCapacity cp=3200
    "specific heat of the coolant";

parameter Integer n_isol_f=5 "number of front face meshes";
parameter Integer n_stock=5 "number of stock meshes";
parameter Integer n_isol_b=3 "number of back side meshes";
  parameter Modelica.Units.SI.Length e_isol_f=0.16
    "front face insulation thickness";
  parameter Modelica.Units.SI.Length e_isol_b=0.03
     "back face insulation thickness";
  parameter Modelica.Units.SI.Length e_stock=0.2 "stock thickness";

  Modelica.Units.SI.Temperature T[n]
    "vector of fluid temperatures on the capture surface side";
  Modelica.Units.SI.Temperature Tem[n]
    "vector of fluid temepratures on the emission side";

protected
ElementXAxis[n] Tubes(
    S=Stot/n*fill(1, n),
    Tstart=Tstart*fill(1, n),
    n_isol_f=n_isol_f*fill(1, n),
    n_isol_b=n_isol_b*fill(1, n),
    n_stock=n_stock*fill(1, n),
    e_isol_f=e_isol_f*fill(1, n),
    e_isol_b=e_isol_b*fill(1, n),
    e_stock=e_stock*fill(1, n));

public
  Modelica.Blocks.Interfaces.RealInput G ;
  BaseClasses.HeatTransfer.Interfaces.HeatPort_a Tf "front panel temperature"
    ;
  BaseClasses.HeatTransfer.Interfaces.HeatPort_b Tb
    "back panel temperature"
    ;
  Modelica.Blocks.Interfaces.BooleanInput ON ;

equation
  // connection dof the pipe sections to each other via the flow rates;

for i in 1:n loop
T[i] = Tubes[i].Tfluide.T;
Tem[i] = Tubes[i].Temetteur.T;
end for;

Tubes[1].debit_s = if ON then q*cp*(Tubes[1].Temetteur.T-Tubes[1].Tfluide.T) else 0;
for i in 2:n loop
Tubes[i].debit_s = if ON then q*cp*(Tubes[i-1].Tfluide.T-Tubes[i].Tfluide.T) else 0;
end for;

for i in 1:n-1 loop
Tubes[1].debit_e = if ON then q*cp*(Tubes[i+1].Temetteur.T-Tubes[i].Temetteur.T) else 0;
end for;

Tubes[n].debit_e = if ON then q*cp*(Tubes[n].Tfluide.T-Tubes[n].Temetteur.T) else 0;

for i in 1:n loop
 Tubes[i].G = G*Stot/n;
 connect(Tubes[i].Tf,Tf);
connect(Tubes[i].Tb,Tb);
end for

  ;
end ParallelTubesActiveSolarWall;

within BuildSysPro.Systems.Storage.Electric;
model LiIonBattery "Lithium-Ion Battery"

public
  parameter Real R_c=0.97 "Coulomb efficiency" ;
      parameter Real R_charge=0.9 "Charge efficiency"
                                                     ;
parameter Real R_decharge=0.9 "Discharge efficiency"
                                                    ;
parameter Real C0=30 "No-load consumption of BMS and converters (W)"
                                                                    ;
parameter Real Pdecharge=0.9 "Allowable discharge depth"
                                                        ;
  replaceable parameter BuildSysPro.Utilities.Records.GenericBattery
    technoBattOnd "Chice of battery inverter couple" ;
//auxiliary variables
  Real R_charge_variable(start=1) " Charge efficiency with a power adjustment ";
  Real R_decharge_variable(start=1) " Discharge efficiency with a power adjustment ";
public
  Modelica.Blocks.Interfaces.RealOutput Pcmax
    "Maximum power available for storage (W)"
    ;

  Modelica.Blocks.Interfaces.RealOutput P
    "Power given by the battery (W)"
    ;
  Modelica.Blocks.Interfaces.RealInput P_consigne "Setpoint power (W)"
    ;
  Modelica.Blocks.Interfaces.RealOutput Pdmax
    "Maximum power available for destocking (W)"
    ;
  Modelica.Blocks.Interfaces.RealOutput SOC "SOC of battery"
    ;

Real P_vide(start=0) "Power consumed by the converters and the BSM";
equation

Pcmax=min(technoBattOnd.Pmaxc,technoBattOnd.P_onduleur);
Pdmax=min(technoBattOnd.Pmaxd,technoBattOnd.P_onduleur);
 R_charge_variable = if P_consigne < 0
                      then max(0.1, 0.98*0.95*(1 - exp(P_consigne/59)))
                      else 1;
  R_decharge_variable = if P_consigne < 0
                      then 1
                      else max(0.1, 0.98*0.95*(1 - exp(-P_consigne/61)));
if P_consigne < 0 then
  if (SOC/3600)<(Pdecharge*technoBattOnd.Cmax) then
    P = min(-R_charge*P_consigne,Pcmax);
    if SOC > 0 then
      P_vide = C0;
    else
      P_vide = 0;
    end if;
  else
      P=0;
      P_vide = 0;
  end if;
else
  if (SOC/3600)>((1-Pdecharge)*technoBattOnd.Cmax) then
      P = -min(R_decharge*R_c*P_consigne,Pdmax);
      if SOC > 0 then
        P_vide = C0;
      else
        P_vide = 0;
      end if;
  else
      P = 0;
      P_vide =0;
  end if;
end if;
  der(SOC)= (R_charge_variable/R_decharge_variable)*P - P_vide

   ;
end LiIonBattery;

