    ;
  Modelica.Blocks.Math.RealToBoolean realToBoolean
    ;
  Modelica.Blocks.Math.BooleanToReal booleanToReal
    ;
  Modelica.Blocks.Math.BooleanToReal booleanToReal1
    ;
  Modelica.Blocks.Math.RealToBoolean realToBoolean1
