  connect(realExpression2.y, product2.u2) ;
  connect(realExpression3.y, product1.u1) ;
  connect(product2.y, IntegraleTempChaud.u) ;
  connect(product1.y, IntegraleTempFroid.u) ;
  connect(realExpression6.y, OutNbHeureInconfortFroid) ;
  connect(realExpression7.y, OutNbHeureInconfortChaud) ;
  connect(fixedHeatFlow.port, Tint) ;
  connect(booleanToReal.y, IntegraleTempFroid1.u) ;
  connect(realToBoolean.y, booleanToReal.u) ;
  connect(realToBoolean.u, realExpression3.y) ;
  connect(realToBoolean1.y, booleanToReal1.u) ;
  connect(booleanToReal1.y, IntegraleTempChaud1.u) ;
  connect(realToBoolean1.u, realExpression2.y) 
  ;
end ThDiscomfort;

