within BuildSysPro.Utilities.Math;
function FindMultiExtremum
  "Extract the n smallest values (ascending=true) or greatest values (ascending=false) of a vector X"
  input Integer n "Number of extreme values to extract to the vector X";
  input Real[:] X "Vector of reals";
  input Boolean ascending=false;
  output Real Xm[n] "Ordered extreme values of the vector X";
  output Integer Indm[n] "Corresponding indexes in the vector X";
//  output Integer z[size(X,1)]=fill(0,size(X,1));

protected
  constant Real eps=Modelica.Constants.eps;
  parameter Integer k=size(X,1);
  Integer z[k]=fill(0,k);
  Real Y[k];
  Integer useless_index[k];
  Integer i;
  Integer j;

algorithm
  (Y, useless_index) := Modelica.Math.Vectors.sort(X, ascending);
  assert(n<=k, "The input parameter n must be lower than or equal to the size of X");
  assert(n>0, "The input parameter n must be greater than 0");
  Xm:=Y[1:n];
  for i in 1:n loop
     j:=1;
     while abs(Xm[i]-X[j])>eps or z[j]>0 loop
         j:=j+1;
     end while;
     z[j]:=i;
     Indm[i]:=j;
  end for

  ;
end FindMultiExtremum;

within BuildSysPro.Utilities.Math;
function findValue
  "Return the index of the real val in the vector x, 0 if val is not found"

  input Real[:] x "Input vector";
  input Real val "Value to seek";
  output Integer index "Index of the value in the vector";

algorithm
  index := 1;
  while index < size(x,1)+1 loop
    if x[index]== val then
     break;
    else
      index:=index +1;
    end if;
    end while;

  if index==size(x,1)+1 then
      index:=0;
  end if

  ;
end findValue;

within BuildSysPro.Utilities.Math;
function f_Pow "Power function"
  input Real x "X-axis";
  input Real xc "Junction X-axis";
  input Real n "Exponent of the function";
  output Real g "Value of the function g at x";
  output Real g1 "Value of the derivative function of g at x";
protected
  parameter Real a=(n - 1)*xc^(n - 2) "Coefficient a";
  parameter Real b=(2 - n)*xc^(n - 1) "Coefficient b";
  parameter Real y=abs(x);
  parameter Integer eps=if x<0 then -1 else 1;
algorithm
  g:=eps*(if y > xc then y^n else (a*y + b)*y);
  g1:=eps*(if y > xc then n*y^(n-1) else (2*a*y + b))
  ;
end f_Pow;

within BuildSysPro.Utilities.Math;
function f_Quadratic "Square law and power law"
  input Real x "Abscissa";
  input Real u "Junction abscissa";
  input Real n "Exponent of the function, in range ]1/2,1[";
  output Real q "Value of the function q at x";
  output Real q1 "Value of the derivative function of q at x";

protected
  parameter Real v=u^n "Value of q at u";
  parameter Real w=n*v/u "Value of q' at u";

  // Parameters of the square law
  parameter Real alpha=(1/w-u/v)/v "Coefficient alpha";
  parameter Real beta=2*u/v-1/w "Coefficient beta";

  // Auxiliary parameters
  parameter Real a=1/alpha "Coefficient alpha";
  parameter Real b=beta/(2*alpha) "Coefficient beta";
  parameter Real y=abs(x);
  parameter Integer eps=if x<0 then -1 else 1;
algorithm
  assert(n>0.5 and n<1,"incorrect value of n, the value of n should be strictly greater than 0.5 and less than 1");
  q:=eps*(if y >= u then y^n else sqrt(a*y+b*b)-b);
  q1:=eps*(if y >= u then n*y^(n-1) else a/2/(eps*q+b))

  ;
end f_Quadratic;

within BuildSysPro.Utilities.Math;
function IGCD "Integers greatest common divisor (fr: PGCD)"
  input Integer a,b;
  output Integer c;
algorithm
  c := if b == 0 then a else IGCD(b, mod(a, b))
  ;
end IGCD;

