function regStep
  "Approximation of a general step, such that the approximation is continuous and differentiable"
  extends Modelica.Icons.Function;
  input Real x "Abscissa value";
  input Real y1 "Ordinate value for x > 0";
  input Real y2 "Ordinate value for x < 0";
  input Real x_small(min=0) = 1e-5
    "Approximation of step for -x_small <= x <= x_small; x_small >= 0 required";
  output Real y "Ordinate value to approximate y = if x > 0 then y1 else y2";
algorithm
  y := smooth(1, if x >  x_small then y1 else
                 if x < -x_small then y2 else
                 if x_small > 0 then (x/x_small)*((x/x_small)^2 - 3)*(y2-y1)/4 + (y1+y2)/2 else (y1+y2)/2)

  ;
end regStep;

within BuildSysPro.Utilities.Time;
function ApparentSolarTime "Real Solar Time (RST)"
  input Real t0=0 "Time in seconds at t=0";
  input Modelica.Units.SI.Time t "Universal Time in seconds";
  input Modelica.Units.NonSI.Angle_deg longitude "Longitude in degrees";
  output Real TSV "Real Solar Time in hrs (RST = UT + longitude/15 - TM)";
algorithm
  TSV :=(t + t0)/3600 + longitude/15 -
    BoundaryConditions.Solar.Utilities.TimeEquation(t0=t0, t=t);
  TSV:=mod(TSV + 24, 24)
  ;
end ApparentSolarTime;

within BuildSysPro.Utilities.Time;
function ApparentSolarTimeToUniversalTime
  "Calculation of Universal Time (UT in hours) according to solar time RST"

input Real t0=0 "Time in seconds at t=0";
// input Real d0 "Number of the day in the month at t=0"; // deleted
  input Modelica.Units.SI.Time t "Elapsed time since t=0 [s]";

  input Modelica.Units.NonSI.Angle_deg long "Longitude, in degrees [°]";
  output Modelica.Units.NonSI.Time_hour tu "Universal Time, in hours [h]";

protected
          constant Real omega=2*Modelica.Constants.pi/365.25;

algorithm
  tu :=t/3600 - long/15 +
    BuildSysPro.BoundaryConditions.Solar.Utilities.TimeEquation(t0=t0, t=t)

  ;
end ApparentSolarTimeToUniversalTime;

within BuildSysPro.Utilities.Time;
function DayMonth "Day of the month at time t"
  input Real t0=0 "Time in second at t=0";
  input Real t "Elapsed time since t=0 [s]";
  output Real JM "Day of the month at time t";

protected
  parameter Integer fMois[13]={0,31,28,31,30,31,30,31,31,30,31,30,31};
  Integer cMois[13];//={sum({fMois[i] for i in 1:j}) for j in 1:13};
  Integer tJour=integer(mod((t+t0)/86400,365))+1;
algorithm

  cMois[1]:=0;
  for i in 2:13 loop
    cMois[i]:=cMois[i - 1] + fMois[i];
  end for;

  JM:=max({(if tJour > cMois[i] and tJour <= cMois[i + 1] then tJour - cMois[i] else 0) for i in 1:12})

  ;
end DayMonth;

