model ModelSettings "Setting important global variables within a model"
  extends Icons.ConverterName;
  // imports
  import BusinessSimulation.Types.InitializationOptions;
  import BusinessSimulation.Constants.small;
  import BusinessSimulation.Units.Time;
  import BusinessSimulation.Types.TimeBases;
  // set model time by changing the rhs of the following definition
  constant TimeBases modelDisplayTimeBase = TimeBases.seconds "The model's time base with regard to input and output" ;
  // modelDisplayTimeBase is used to lookup unit strings in some components and thus must have constant variability in SystemModeler
  parameter Time modelTimeHorizon(min = small) = 10 "The time horizon for the model (i.e., stopTime - startTime)" ;
  parameter Time modelStartTime(fixed = false) "Start time of the model (will be automatically determined)" ;
  parameter Time modelStopTime(fixed = false) "Stop time of the model (will be determined from startTime and modelTimeHorizon)" ;
  // inner constant String modelDisplayTimeUnit = BusinessSimulation.Constants.timeBaseUnits[modelDisplayTimeBase] "The global setting for 'displayUnit' of time vars" ;
  parameter Time dt(min = 0) = 0.25 "Smallest possible interval of time for compatibility with conventional fixed-step system dynamics models" ;
  parameter Time samplingPeriod(min = 0) = dt / 4 "Default sampling period for discrete model components (should be ≤ dt/4)" ;
  constant Boolean gaming = false "= true, if gaming mode is to be activated" ;
  // file names for exogenous data
  constant String lookupDataFileURI = "LookupData.txt" "URI for the lookup data file" ;
  constant String exogenousDataFileURI = "ExogenousData.txt" "URI for the exogenous data file" ;
  constant String modelDisplayTimeUnit = BusinessSimulation.Constants.timeBaseUnits[modelDisplayTimeBase] "Unit string according to modelDisplayTimeBase choice" ;
  // advanced options
  parameter InitializationOptions init = BusinessSimulation.Types.InitializationOptions.FixedValue "Provide InitializationOptions (Free, FixedValue, SteadyState) as global default" ;
initial equation
  // store the model's startTime
  modelStartTime = time;
  modelStopTime = modelStartTime + abs(modelTimeHorizon);
equation
  assert(dt > small, "dt must be greater than zero");
  assert(samplingPeriod > small, "samplingPeriod must be greater than zero")
  ;
end ModelSettings;

