model ComplexInteraction "Interaction with linear and nonlinear terms"
  import BusinessSimulation.Units.*;
  extends Interfaces.PartialCLD.Interaction(polA = "±", polB = "±");
  parameter Rate a_0 "Growth rate for A (independent)" ;
  parameter Rate a_A "Fractional rate of growth for A (self-coupling A)" ;
  parameter Rate a_B "Rate of growth for A per unit of B (coupling of B to A)" ;
  parameter Rate a_AB "Fractional rate of growth for A per unit of B (nonlinear coupling)" ;
  parameter Rate b_0 "Growth rate for B (independent)" ;
  parameter Rate b_B "Fractional growth rate for B (self-coupling)" ;
  parameter Rate b_A "Rate of growth for B per unit of A (coupling of A to B)" ;
  parameter Rate b_AB "Fractional growth rate for B per unit of A (nonlinear coupling)" ;
protected
  Flows.Interaction.ComplexInteraction complexInteraction(redeclare type OutputType_A = OutputType_A, redeclare type OutputType_B = OutputType_B) ;
  Converters.Vector.ScalarMultiplication actualCoefficients(nin = 8, redeclare type OutputType = Rate) ;
  Converters.Vector.ConstantConverter constantCoefficients(value = {a_0, a_A, a_B, a_AB, b_0, b_B, b_A, b_AB}) ;
  Interfaces.Connectors.RealOutput y_a0 ;
  Flows.Interaction.ComplexInteraction.InputConnector dataIn ;
  Interfaces.Connectors.RealOutput y_aA ;
  Interfaces.Connectors.RealOutput y_aB ;
  Interfaces.Connectors.RealOutput y_aAB ;
  Interfaces.Connectors.RealOutput y_b0 ;
  Interfaces.Connectors.RealOutput y_bA ;
  Interfaces.Connectors.RealOutput y_bB ;
  Interfaces.Connectors.RealOutput y_bAB ;
equation
  connect(portA, complexInteraction.portA) ;
  connect(complexInteraction.portB, portB) ;
  connect(constantCoefficients.y, actualCoefficients.u1) ;
  connect(actualCoefficients.y[1], y_a0) ;
  connect(u, actualCoefficients.u2) ;
  connect(one, actualCoefficients.u2) ;
  connect(dataIn, complexInteraction.dataIn) ;
  connect(y_a0, dataIn.a_0) ;
  connect(actualCoefficients.y[2], y_aA) ;
  connect(actualCoefficients.y[3], y_aB) ;
  connect(actualCoefficients.y[4], y_aAB) ;
  connect(actualCoefficients.y[5], y_b0) ;
  connect(actualCoefficients.y[7], y_bA) ;
  connect(actualCoefficients.y[6], y_bB) ;
  connect(actualCoefficients.y[8], y_bAB) ;
