model PID_Control "Directly influencing a stock to keep it at setpoint value"
  import BusinessSimulation.Units.*;
  import Modelica.Blocks.Types.Init;
  import BusinessSimulation.Constants.{small, inf};
  extends BusinessSimulation.Interfaces.PartialCLD.Control;
  outer ModelSettings modelSettings;
  replaceable type GainType = Unspecified constrainedby Unspecified "Type choice for controller gain" ;
  parameter GainType k(min = 0) = 1 "Gain of controller [GainType]";
  parameter Time Ti(min = small, start = 0.5) = inf "Time constant of integrator (i.e., gain for integrator = 1/Ti)";
  parameter Time Td(min = 0, start = 0.1) = 0 "Derivative gain (i.e., time span for error prediction)";
  parameter Init initType = Init.NoInit "Type of initialization (1: no init, 2: steady state, 3: initial state, 4: initial output)" ;
  parameter Real Nd(min = small) = 10 "The higher Nd, the more ideal the derivative block" ;
  parameter Fraction xi_start = 0 "Initial or guess value for integrator output (= integrator state)" ;
  parameter Fraction xd_start = 0 "Initial or guess value for state of derivative block" ;
  parameter OutputType y_start = 0 "Initial value of output" ;
protected
  Modelica.Blocks.Continuous.PID PID(k = k, Ti = Ti, Td = Td, initType = initType, Nd = Nd, xi_start = xi_start, xd_start = xd_start, y_start = y_start) ;
  Converters.Gap error "Gap between setpoint and current stock value" ;
  SourcesOrSinks.ExogenousChange changing "Flow to adjust the stock" ;
  Converters.Product_2 actualRate "Actual rate, which becomes zero when control is turned off" ;
equation
  connect(changing.massPort, flowPort) ;
  connect(onOff.y, actualRate.u2) ;
  connect(permanent.y, actualRate.u2) ;
  connect(actualRate.y, changing.u) ;
  connect(changing.y, y) ;
  connect(changing.y1, y1) ;
  connect(PID.y, actualRate.u1) ;
  connect(error.y, PID.u) ;
  connect(setpoint.y, error.u1) ;
  connect(currentValue.stock, error.u2) ;
  connect(u, error.u1) ;
  /* control */
  ;
end PID_Control;

