  parameter Real minValue = -maxValue "Minimum value (default = - infinity)" ;
  parameter Boolean hasConstantLimits = true "= true, if the limits are constant" ;
  parameter Boolean strict = true "= true, if strict limits with noEvent(..) (constantLimiter.strict)" ;
  parameter LimiterHomotopy homotopyType = LimiterHomotopy.Linear "Simplified model for homotopy-based initialization (constantLimiter.homotopyType)" ;
  parameter VariableLimiterHomotopy variableHomotopyType = VariableLimiterHomotopy.Linear "Simplified model for homotopy-based initialization (variableLimiter.homotopyType)" ;
protected
  Modelica.Blocks.Nonlinear.VariableLimiter variableLimiter(strict = strict, homotopyType = variableHomotopyType) if not hasConstantLimits "Clip input to variable limits" ;
  Modelica.Blocks.Nonlinear.Limiter constantLimiter(uMax = maxValue, uMin = minValue, strict = strict, homotopyType = homotopyType) if hasConstantLimits "Clip input to constant limits" ;
equation
  connect(u, constantLimiter.u) ;
  connect(constantLimiter.y, y) ;
  connect(u, variableLimiter.u) ;
  connect(u_max, variableLimiter.limit1) ;
  connect(u_min, variableLimiter.limit2) ;
