  Interfaces.Connectors.RealOutput y ;
  constant TimeBases timeBaseA = modelSettings.modelDisplayTimeBase "TimeBase to convert from" ;
  constant TimeBases timeBaseB = TimeBases.seconds "TimeBase to convert to (default = seconds)" ;
