model SoftMax "Gradual approach of a floor below which output can never fall"
  import BusinessSimulation.Units.*;
  import BusinessSimulation.Constants.*;
  extends Interfaces.PartialConverters.SISO;
  Interfaces.Connectors.RealInput u_min "The floor" ;
  parameter Real k(min = small) = 4.7 "Parameter to control the closeness to a hard maximum";
  parameter Boolean useMaxOperator = false "= true, if a regular 'hard' maximum is to be used" ;
  Gap u_min_shifted ;
  Gap u_shifted ;
  Logical.Switch switch ;
  Logical.ConstantConverterBoolean useHardMaxQ(value = useMaxOperator) ;
  Add_2 softmin_shifted ;
protected
  Max hardMax "Hard max operator" ;
  Gain scaledInput(c = k) if not useMaxOperator ;
  Exp expInput if not useMaxOperator ;
  Add_2 sumExp if not useMaxOperator ;
  Log logSum if not useMaxOperator ;
  Gain adjustmentFactor(c = 1 / k) if not useMaxOperator ;
  Exp expMin if not useMaxOperator ;
  Gain scaledMin(c = k) if not useMaxOperator ;
equation
  assert(k > small or useMaxOperator, "The parameter k must greater than zero");
  connect(scaledInput.y, expInput.u) ;
  connect(sumExp.y, logSum.u) ;
  connect(u, hardMax.u2) ;
  connect(u_min, hardMax.u1) ;
  connect(scaledMin.y, expMin.u) ;
  connect(expInput.y, sumExp.u2) ;
  connect(expMin.y, sumExp.u1) ;
  connect(hardMax.y, u_min_shifted.u2) ;
  connect(hardMax.y, u_shifted.u2) ;
  connect(u_min, u_min_shifted.u1) ;
  connect(u_min_shifted.y, scaledMin.u) ;
  connect(u, u_shifted.u1) ;
  connect(u_shifted.y, scaledInput.u) ;
  connect(hardMax.y, switch.u1) ;
  connect(useHardMaxQ.y, switch.u_cond) ;
  connect(switch.y, y) ;
  connect(hardMax.y, softmin_shifted.u1) ;
  connect(softmin_shifted.y, switch.u2) ;
  connect(logSum.y, adjustmentFactor.u) ;
  connect(adjustmentFactor.y, softmin_shifted.u2) 
  ;
end SoftMax;

