model SoftMin "Gradual approach of a ceiling that cannot be exceeded"
  import BusinessSimulation.Units.*;
  import BusinessSimulation.Constants.*;
  extends Interfaces.PartialConverters.SISO;
  Interfaces.Connectors.RealInput u_max "The ceiling" ;
  parameter Real k(min = small) = 4.7 "Parameter to control the closeness to a hard minimum";
  parameter Boolean useMinOperator = false "= true, if a regular 'hard' minimum is to be used" ;
  parameter Boolean clipNegativeOutput = true "= true, if output can never be less than zero" ;
  parameter Boolean strict = true "= true, if strict limits with noEvent(..) (clippedOutput.strict)" ;
protected
  Min hardMin if useMinOperator "Hard min operator" ;
  ZeroIfNegative clippedOutput(strict = strict) if clipNegativeOutput ;
  PassThrough unclippedOutput if not clipNegativeOutput ;
  Exp expMaxUtil if not useMinOperator ;
  Gain scaledMaxUtil(c = -k) if not useMinOperator ;
  Gain scaledInput(c = -k) if not useMinOperator ;
  Exp expInput if not useMinOperator ;
  Add_2 sumExp if not useMinOperator ;
  Log logSum if not useMinOperator ;
  Gain adjustmentFactor(c = -1 / k) if not useMinOperator ;
  Product_2 softMin if not useMinOperator ;
  ConstantConverter maxUtilization(value = 1, redeclare replaceable type OutputType = Dimensionless) if not useMinOperator "Maximum utilization" ;
  Division_Guarded utilization if not useMinOperator "Fraction of the maximum" ;
equation
  assert(k > small or useMinOperator, "The parameter k must greater than zero");
  connect(scaledMaxUtil.y, expMaxUtil.u) ;
  connect(scaledInput.y, expInput.u) ;
  connect(sumExp.y, logSum.u) ;
  connect(logSum.y, adjustmentFactor.u) ;
  connect(u, hardMin.u2) ;
  connect(u_max, hardMin.u1) ;
  connect(hardMin.y, unclippedOutput.u) ;
  connect(unclippedOutput.y, y) ;
  connect(clippedOutput.y, y) ;
  connect(hardMin.y, clippedOutput.u) ;
  connect(expInput.y, sumExp.u1) ;
  connect(expMaxUtil.y, sumExp.u2) ;
  connect(u_max, softMin.u1) ;
  connect(softMin.y, unclippedOutput.u) ;
  connect(adjustmentFactor.y, softMin.u2) ;
  connect(softMin.y, clippedOutput.u) ;
  connect(maxUtilization.y, scaledMaxUtil.u) ;
  connect(u_max, utilization.u2) ;
  connect(utilization.y, scaledInput.u) ;
  connect(u, utilization.u1) 
  ;
end SoftMin;

