  parameter Real initialOutput(start = initialValue, fixed = false) "Value to be used for initialization of the implicit stock" ;
  SourcesOrSinks.ExogenousChange changingPerception ;
  Gap gap "Difference between acutal information and perceived information" ;
  Division_Guarded rateOfChange(outputIfZero = 0) "Rate of change in perceived information" ;
  Stocks.InformationLevel perceivedInformation(initialValue = initialOutput, init = InitializationOptions.FixedValue) "Smoothed information" ;
