block AsymmetricSmoothN "Higher order smooth with different delay times for positive and negative changes"
  import BusinessSimulation.Types.InitializationOptions;
  import BusinessSimulation.Units.*;
  extends Interfaces.PartialConverters.SmoothSISO;
  Interfaces.Connectors.RealInput u_negDelayTime "Delay time for negative changes" ;
  Interfaces.Connectors.RealInput u_posDelayTime "Delay time for positive changes" ;
  parameter Integer n(min = 1) = 3 "Order of the smooth" ;
  parameter OutputType initialValue = 0 "Initial Output" ;
  parameter InitializationOptions init = modelSettings.init "Provide InitializationOptions (Free, FixedValue, SteadyState)" ;
  outer ModelSettings modelSettings;
protected
  AsymmetricSmooth smooth[n] ;
  ConstantConverter parN(value = n) ;
  Division partialPosDelayTime "Positive delay time for each smooth in the chain of smooths" ;
  Division partialNegDelayTime "Negative delay time for each smooth in the chain of smooths" ;
equation
  connect(u, smooth[1].u) ;
  connect(smooth[1:n - 1].y, smooth[2:n].u) ;
  connect(smooth[n].y, y) ;
  connect(parN.y, partialPosDelayTime.u2) ;
  connect(parN.y, partialNegDelayTime.u2) ;
  connect(u_posDelayTime, partialPosDelayTime.u1) ;
  connect(u_negDelayTime, partialNegDelayTime.u1) ;
  connect(partialPosDelayTime.y, smooth[1].u_posDelayTime) ;
  connect(partialNegDelayTime.y, smooth[1].u_negDelayTime) ;
  for i in 2:n loop
    connect(partialPosDelayTime.y, smooth[i].u_posDelayTime);
    connect(partialNegDelayTime.y, smooth[i].u_negDelayTime);
  end for
  ;
end AsymmetricSmoothN;

