model DelayInformation "Pipeline information delay with awareness"
  import BusinessSimulation.Units.*;
  import BusinessSimulation.Types.InitializationOptions;
  import BusinessSimulation.Constants.{inf, small, eps, e};
  extends Interfaces.PartialConverters.SmoothSISO;
  Interfaces.Connectors.RealInput u_history if hasExogenousHistory "Input of recent history (start time - initial delay time)" ;
  Interfaces.Connectors.RealOutput y_lookupTime if hasExogenousHistory "Time for looking up historical input" ;
  Interfaces.Connectors.RealInput u_delayTime if not hasConstantDelayTime "Delay time input" ;
  parameter Time delayTime(min = modelSettings.dt) = 1 "Constant delay time (optional)" ;
  parameter Time maximumDelayTime = 50 "Maximal value allowed for delay time (needed for variable delay time)" ;
  parameter OutputType initialValue = 0 "Initial constant output, if no exogenous history is given" ;
  parameter Boolean hasConstantDelayTime = true "= true, if the delay time is given by the parameter 'delayTime'" ;
  parameter Boolean hasExogenousHistory = false "= true, if the input 'u_history' gives the output for an initial period, otherwise the initial output will remain constant until delayTime is reached" ;
  parameter InitializationOptions init = modelSettings.init "Provide InitializationOptions (Free, FixedValue, SteadyState)" ;
  parameter Time samplingPeriod(min = small, max = modelSettings.dt) = modelSettings.samplingPeriod "Interval at which to check for increases in delay time" ;
  outer ModelSettings modelSettings;
protected
  // variables
  parameter Real initialOutput(start = initialValue, fixed = false) "Constant output if no exogenous history is provided" ;
  discrete Real storedInformation "Store information for use in case delayed information is even older";
  discrete Time t_stored "Time stamp for the stored information";
  // components
  ConstantConverterTime parDelayTime(value = delayTime) if hasConstantDelayTime "Constant delay time (optional)" ;
  ConstantConverter parInitialOutput(value = initialOutput) if not hasExogenousHistory "Initial output if not history is given" ;
  Clip clippedDelayTime(minValue = modelSettings.dt, maxValue = if not hasConstantDelayTime then maximumDelayTime else inf) "DelayTime has to be in the interval (dt, maximumDelayTime)" ;
  Modelica.Blocks.Nonlinear.VariableDelay delayedInput(delayMax = maximumDelayTime) if not hasConstantDelayTime ;
  PassThrough history ;
  Modelica.Blocks.Nonlinear.FixedDelay delayedInputConstant(delayTime = delayTime) if hasConstantDelayTime "Delayed input with constant delay time" ;
  PassThrough delayedInformation "Delayed input to use for further processing" ;
  InformationSources.TimeInput clock "Provide time starting with 0" ;
  Gap lookupTime "The actual time minus the delay time, i.e., the time stamp for the delayed information" ;
initial equation
  if init == InitializationOptions.FixedValue then
    initialOutput = initialValue;
  elseif init == InitializationOptions.SteadyState then
    initialOutput = u;
  end if;
  // initialize sampled values
  pre(t_stored) = modelSettings.modelStartTime - clippedDelayTime.y;
  pre(storedInformation) = history.y;
algorithm
  when sample(modelSettings.modelStartTime + samplingPeriod, samplingPeriod) then
    // store new information if more actual than the last recording
    if lookupTime.y > pre(t_stored) then
      t_stored := lookupTime.y;
      storedInformation := if lookupTime.y < modelSettings.modelStartTime then history.y else delayedInformation.y;
    end if;
  end when;
  y := storedInformation;
equation
  connect(u_delayTime, clippedDelayTime.u) ;
  connect(u_history, history.u) ;
  connect(parInitialOutput.y, history.u) ;
  connect(u, delayedInput.u) ;
  connect(u, delayedInputConstant.u) ;
  connect(parDelayTime.y, clippedDelayTime.u) ;
  connect(clippedDelayTime.y, delayedInput.delayTime) ;
  connect(delayedInputConstant.y, delayedInformation.u) ;
  connect(delayedInput.y, delayedInformation.u) ;
  connect(clock.y, lookupTime.u1) ;
  connect(clippedDelayTime.y, lookupTime.u2) ;
  connect(lookupTime.y, y_lookupTime) 
  ;
end DelayInformation;

