block SmoothN "N-th order exponential smooth with constant averaging time"
  import BusinessSimulation.Units.*;
  import BusinessSimulation.Types.InitializationOptions;
  import BusinessSimulation.Constants.{inf, small, eps, e};
  extends Interfaces.PartialConverters.SmoothSISO;
  Interfaces.Connectors.RealInput u_delayTime if not hasConstantDelayTime "Delay time input" ;
  parameter Integer n(min = 1) = 3 "Order of the smooth" ;
  parameter Time delayTime(min = 0) = 1 "Constant delay time (optional)" ;
  parameter OutputType initialValue = 0 "Initial Output" ;
  parameter Boolean hasConstantDelayTime = true "if true, the constant parameter value is used" ;
  parameter InitializationOptions init = modelSettings.init "Provide InitializationOptions (Free, FixedValue, SteadyState)" ;
  outer ModelSettings modelSettings;
protected
  Division partialDelayTime if not hasConstantDelayTime "Delay time for each smooth in the chain of smooths" ;
  Converters.DiscreteDelay.Smooth firstOrderSmooth[n](each hasConstantDelayTime = hasConstantDelayTime, each init = init, each initialValue = initialValue, each delayTime = delayTime / n) "Chain of n first-order exponential information delays" ;
  ConstantConverter parN(value = n) if not hasConstantDelayTime "Order of the delay" ;
equation
  connect(u_delayTime, partialDelayTime.u1) ;
  connect(parN.y, partialDelayTime.u2) ;
  connect(partialDelayTime.y, firstOrderSmooth[1].u_delayTime) ;
  for i in 2:n loop
    connect(partialDelayTime.y, firstOrderSmooth[i].u_delayTime);
  end for;
  connect(u, firstOrderSmooth[1].u) "Input signal" ;
  for i in 1:n - 1 loop
    connect(firstOrderSmooth[i].y, firstOrderSmooth[i + 1].u);
  end for;
  connect(firstOrderSmooth[n].y, y) "Output signal" 
  ;
end SmoothN;

