block ConcaveLookupNegative "Concave Lookup with negative slope; fixpoints are (0,y0) and (1,0)"
  import BusinessSimulation.Units.*;
  extends Interfaces.PartialConverters.SISO_Conversion;
  parameter Real s(min = 1, max = 50) = 1 "Slope parameter (1 <= slope <= 50)";
  parameter Real y0(min = 0) = 1 "Value of y when input is zero or less (intercept)";
  parameter Boolean strict = true "= true, if strict limits with noEvent(..)" ;
equation
  assert(s >= 1, "Slope parameter should not be less than 1", level = AssertionLevel.warning);
  assert(y0 >= 0, "Intercept should not be negative", level = AssertionLevel.warning);
  if strict then
    y_c = noEvent(if u_c <= 0 then y0 elseif u_c < 1 then y0 * (1 - u_c ^ s) else 0);
  else
    y_c = if u_c <= 0 then y0 elseif u_c < 1 then y0 * (1 - u_c ^ s) else 0;
  end if
  ;
end ConcaveLookupNegative;

within BusinessSimulation.Converters.Lookup;

block ConcaveLookupPositive "Concave Lookup with positive slope; fixpoints are (0,y0) and (1,1)"
  import BusinessSimulation.Units.*;
  extends Interfaces.PartialConverters.SISO_Conversion;
  parameter Real s(min = 0, max = 1) = 0.5 "Slope parameter (0< slope <= 1)";
  parameter Real y0(min = 0, max = 1) = 0 "Value of y when input is zero or less (intercept)";
  parameter Boolean strict = true "= true, if strict limits with noEvent(..)" ;
equation
  assert(y0 >= 0 and y0 <= 1, "Intercept should be within the closed unit interval [0,1]", level = AssertionLevel.warning);
  assert(s > 0 and s <= 1, "Slope should be within the interval (0,1]", level = AssertionLevel.warning);
  if strict then
    y_c = noEvent(if u_c <= 0 then y0 else y0 + (1 - y0) * u_c ^ s);
  else
    y_c = if u_c <= 0 then y0 else y0 + (1 - y0) * u_c ^ s;
  end if
  ;
end ConcaveLookupPositive;

