    Material machine1 "Material in first batch production";
    Material movingOn "Material on conveyor belt";
    Material intermediateStore "Material in buffer stock";
    Material machine2 "Material in second batch production";
    Material outgoingInventory "Finished goods inventory";
  end ModelOutput;
protected
  SourcesOrSinks.Growth beingReleased(rate = 2, hasConstantRate = true) "Material flowing into the assembly line" ;
  Stocks.MaterialStock incomingStore(initialValue = 7, redeclare replaceable type OutputType = Material) "Buffer stock for incoming material" ;
  Stocks.Oven machine1(hasConstantBatchSize = true, hasConstantProcessingTime = true, batchSize = 4, processingTime = 1, unloadingTime = 1, redeclare replaceable type OutputType = Material, hasFixedProcessingTime = true, hasConstantLoadingTime = true, hasConstantSetupTime = true, hasConstantUnloadingTime = true, setupTime = 0) "First processing unit" ;
  Flows.Unidirectional.Transition loading1(hasConstantRate = true, rate = 2) "Loading the processing unit" ;
  Flows.Unidirectional.OutflowDynamicStock enteringBelt "Outflow from machine 1" ;
  Stocks.MaterialStock intermediateStore(initialValue = 0, redeclare replaceable type OutputType = Material) "Buffer stock for material" ;
  Flows.Unidirectional.OutflowDynamicStock leavingBelt "Entering the intermediate store" ;
  Stocks.Oven machine2(hasConstantBatchSize = true, hasConstantProcessingTime = true, batchSize = 2, processingTime = 0.5, unloadingTime = 0.5, redeclare replaceable type OutputType = Material, hasFixedProcessingTime = true, hasConstantLoadingTime = true, hasConstantSetupTime = true, hasConstantUnloadingTime = true, setupTime = 0) "First processing unit" ;
  Flows.Unidirectional.Transition loading2(hasConstantRate = true, rate = 2) "Loading the processing unit" ;
  Flows.Unidirectional.OutflowDynamicStock unloading2 "Outflow from machine 1" ;
  Stocks.MaterialStock outgoingInventory(initialValue = 0, redeclare replaceable type OutputType = Material) "Finished goods for shipment" ;
  Stocks.SimpleConveyor movingOn(initialValue = 0, delayTime = 2, redeclare replaceable type OutputType = Material) "Conveyor belt transport" ;
equation
  connect(beingReleased.massPort, incomingStore.inflow) ;
  connect(incomingStore.outflow, loading1.portA) ;
  connect(loading1.portB, machine1.inflow) ;
  connect(machine1.outflow, enteringBelt.portA) ;
  connect(leavingBelt.portB, intermediateStore.inflow) ;
  connect(intermediateStore.outflow, loading2.portA) ;
  connect(loading2.portB, machine2.inflow) ;
  connect(unloading2.portB, outgoingInventory.inflow) ;
  connect(machine2.outflow, unloading2.portA) ;
  connect(enteringBelt.portB, movingOn.inflow) ;
  connect(movingOn.outflow, leavingBelt.portA) ;
  connect(incomingStore.y1, modelOutput.incomingStore) ;
  connect(movingOn.y1, modelOutput.movingOn) ;
  connect(intermediateStore.y2, modelOutput.intermediateStore) ;
  connect(outgoingInventory.y2, modelOutput.outgoingInventory) ;
  connect(machine1.y1, modelOutput.machine1);
  connect(machine2.y1, modelOutput.machine2)
  ;
