model HealTheWorld "Causal loop model of world dynamics"
  extends BusinessSimulation.Icons.Example;

  model Theta "Parameter definitions for the Base Case"
    extends Icons.Theta;
    // parameter Real c = +0.3 "Elasticity coefficient for the impact of environmental load upon societal action (≥0)";
    parameter Ratio campaignTarget = 1 / 0.3 "Target multiplier for the elasticity coefficient" ;
    parameter Time campaignStart = 1 "Start time for the intervention" ;
    parameter Time campaignDuration(min = modelSettings.dt) = 3 "Duration of the intervention" ;
    parameter Boolean withIntervention = true "= true, if there is to be a compaign to raise public awareness" ;
    outer ModelSettings modelSettings;
  end Theta;

  Theta theta ;
  inner ModelSettings modelSettings(modelDisplayTimeBase = BusinessSimulation.Types.TimeBases.seconds, modelTimeHorizon = 10, dt = 0.25) ;
  final Interfaces.Connectors.DataOutPort modelOutput "Index levels for the model's stocks" ;
protected
  CausalLoop.SimpleInformationLevel societalAction ;
  CausalLoop.SimpleInformationLevel environmentalLoad ;
  CausalLoop.SimpleInformationLevel population ;
  CausalLoop.SimpleInformationLevel consumption ;
  CausalLoop.InputControl campaign(startTime = theta.campaignStart, duration = theta.campaignDuration, initialInput = 1.0, finalInput = theta.campaignTarget) if theta.withIntervention "Awareness campain as 'control'" ;
  CausalLoop.ExponentialChange p1(rate = 0.01, hasRateOutput = false, redeclare replaceable type OutputType = Rate) "Exponential growth of the population" ;
  CausalLoop.Elasticity r1(coefficient = +1) "Population growth is tightly coupled to increases in environmental load" ;
  CausalLoop.Elasticity r2(coefficient = -0.1) "Societal action increases will slightly decrease population growth" ;
  CausalLoop.Elasticity r3(coefficient = -0.1) "Increases in environmental load will slightly decrease population growth" ;
  CausalLoop.Elasticity r4(coefficient = -1) "Societal action is tightly coupled to decreases in resource consumption" ;
  CausalLoop.Elasticity r5(coefficient = +1.1) "Environmental load increase will rather strongly increase the level of resource consumption" ;
  CausalLoop.Elasticity r6(coefficient = +0.3, hasFactor = theta.withIntervention) "Growth in the environmental load will slightly increase growth of societal action" ;
  CausalLoop.Elasticity r7(coefficient = +0.3) "Increases in the level of resource consumption will slightly increase population growth" ;
  CausalLoop.Elasticity r8(coefficient = +1) "Increases in resource consumption are tightly coupled to increases in environmental load" ;
  CausalLoop.LoopIndicator_CW R1 "consumption > environmentalLoad > consumption" ;
  CausalLoop.LoopIndicator_CW R2 "population > environmentalLoad > consumption > population" ;
  CausalLoop.LoopIndicator_CCW B1(pol = "–") "population > environmentalLoad > population" ;
  CausalLoop.LoopIndicator_CCW B2(pol = "–") "population > environmentalLoad > societalAction > population" ;
  CausalLoop.LoopIndicator_CCW B3(pol = "–") "population > environmentalLoad > societalAction > consumption > population" ;
  CausalLoop.MatFlowIndicator lab1 ;
  final CausalLoop.StockInformation indexInfo[4] "Index levels for the model's stocks" ;
equation
  connect(environmentalLoad.stockInfoOutput, r6.stockInfoInput) ;
  connect(r6.flowPort, societalAction.stockPort) ;
  connect(r1.flowPort, environmentalLoad.stockPort) ;
  connect(societalAction.stockInfoOutput, r2.stockInfoInput) ;
  connect(r2.flowPort, population.stockPort) ;
  connect(r3.flowPort, population.stockPort) ;
  connect(r3.stockInfoInput, environmentalLoad.stockInfoOutput) ;
  connect(r4.stockInfoInput, societalAction.stockInfoOutput) ;
  connect(r4.flowPort, consumption.stockPort) ;
  connect(environmentalLoad.stockInfoOutput, r5.stockInfoInput) ;
  connect(r5.flowPort, consumption.stockPort) ;
  connect(r8.flowPort, environmentalLoad.stockPort) ;
  connect(r8.stockInfoInput, consumption.stockInfoOutput) ;
  connect(r7.flowPort, population.stockPort) ;
  connect(p1.flowPort, population.stockPort) ;
  connect(campaign.y, r6.u) ;
  connect(population.stockInfoOutput, r1.stockInfoInput) ;
  connect(consumption.stockInfoOutput, r7.stockInfoInput) ;
  // invisible connections
  connect(population.stockInfoOutput, indexInfo[1].stockInfoInput) "Population";
  connect(environmentalLoad.stockInfoOutput, indexInfo[2].stockInfoInput) "Environmental load";
  connect(consumption.stockInfoOutput, indexInfo[3].stockInfoInput) "Consumption";
  connect(societalAction.stockInfoOutput, indexInfo[4].stockInfoInput) "Societal action";
  connect(indexInfo[1].y, modelOutput.population) "Index for the world population";
  connect(indexInfo[2].y, modelOutput.environmentalLoad) "Index for the environmental load";
  connect(indexInfo[3].y, modelOutput.consumption) "Index for resource consumption";
  connect(indexInfo[4].y, modelOutput.societalAction) "Index for societal action taken";
  // assertions
  assert(theta.campaignStart >= modelSettings.modelStartTime, "Campaign should not start before the model's start time", level = AssertionLevel.warning)
  ;
end HealTheWorld;

