model LookupFunctions "Showcase of lookup-functions"
  extends Icons.Example;
  ModelOutput modelOutput "The main model output" ;
  parameter Real slope1To50(min = 1, max = 50) = 2 "Slope parameter (general)";
  parameter Real slope(min = 0) = slope1To50 "Determines the gradient of the curve (Janoschek and S-Shaped)";
  parameter Real slopeUpTo1(min = 0, max = 1) = 0.5 "Slope parameter (0< slope <= 1) (concaveLookupPosisitve)";
  parameter Real interceptUpward(min = 0, max = 1) = 0. "Value of y when input is zero or less (y0) for upward sloping functions";
  parameter Real interceptDownward(min = 1) = 2. "Value of y when input is zero or less (y0) for downward sloping functions";
  parameter Real upperBound = 2 "Upper asymptote for u <= 0 (upperBound > lowerBound) (Janoschek and S-Shaped)";
  parameter Real lowerBound = 0 "Lower asymptote for u -> infinity (Janoschek)";
  parameter Real x_ref(min = 0) = 1 "x-value for point of inflection(>0) (Janoschek)";
  parameter Real y_ref = 1 "y-value for point of inflection(lowerBound < y_ref < upperBound) (Janoschek)";
  parameter Real table[:, :] = {{0, 0}, {2, 4}, {4, 6}, {6, 8}} "Table matrix (grid = first column; e.g., table=[0,2]) (combiTable1D.table) (tableFunction.table)";
  parameter Modelica.Blocks.Types.Smoothness smoothness = Modelica.Blocks.Types.Smoothness.LinearSegments "Smoothness of table interpolation (tableFunction.smoothness)";
  parameter Modelica.Blocks.Types.Extrapolation extrapolation = Modelica.Blocks.Types.Extrapolation.HoldLastPoint "Extrapolation of data outside the definition range (combiTable.extrapolation) (tableFunction.extrapolation)";
  inner ModelSettings modelSettings(modelTimeHorizon = 10) ;
  InformationSources.RampInput '0..10'(height = 10, duration = 10, offset = 0, startTime = 0) "Ramp from 0 to 10 in 10 units of time" ;
  InformationSources.RampInput '-5..5'(offset = -5, height = 10, duration = 10) "Ramp from -5 to 5 in 10 units of time" ;

  expandable connector ModelOutput "Main Output"
    extends Icons.DataOutPort;
  end ModelOutput;
protected
  Converters.Lookup.ConcaveLookupNegative concaveLookupNegative(s = slope1To50, y0 = interceptDownward) ;
  Converters.Lookup.ConcaveLookupPositive concaveLookupPositive(s = slopeUpTo1, y0 = interceptUpward) ;
  Converters.Lookup.ConvexLookupNegative convexLookupNegative(y0 = interceptDownward) ;
  Converters.Lookup.ConvexLookupPositive convexLookupPositive(s = slope1To50, y0 = interceptUpward) ;
  Converters.Lookup.JanoschekNegative janoschek_negative_x_y(growthRate = slope, x_ref = x_ref, y_ref = y_ref, lowerBound = lowerBound, upperBound = upperBound) ;
  Converters.Lookup.JanoschekPositive janoschek_positive_x_y(lowerBound = lowerBound, upperBound = upperBound, growthRate = slope, x_ref = x_ref, y_ref = y_ref) ;
  Converters.Lookup.SShapedNegative sShapedNegative_origin(s = slope, upperBound = upperBound) ;
  Converters.Lookup.SShapedPositive sShapedPositive_origin(s = slope, upperBound = upperBound) ;
  Converters.Lookup.TableFunction tableFunction(table = table, tableOnFile = false, extrapolation = extrapolation, smoothness = smoothness) ;
equation
  connect('0..10'.y, concaveLookupPositive.u) ;
  connect('0..10'.y, convexLookupNegative.u) ;
  connect('0..10'.y, janoschek_positive_x_y.u) ;
  connect('0..10'.y, convexLookupPositive.u) ;
  connect('0..10'.y, janoschek_negative_x_y.u) ;
  connect('-5..5'.y, sShapedNegative_origin.u) ;
  connect('-5..5'.y, sShapedPositive_origin.u) ;
  connect('0..10'.y, tableFunction.u) ;
  connect('0..10'.y, concaveLookupNegative.u) ;
  connect(concaveLookupNegative.y, modelOutput.concaveLookupNegative) ;
  connect(concaveLookupPositive.y, modelOutput.concaveLookupPositive) ;
  connect(convexLookupNegative.y, modelOutput.convexLookupNegative) ;
  connect(convexLookupPositive.y, modelOutput.convexLookupPositive) ;
  connect(janoschek_negative_x_y.y, modelOutput.janoschekNegative) ;
  connect(janoschek_positive_x_y.y, modelOutput.janoschekPositive) ;
  connect(tableFunction.y, modelOutput.tableFunction) ;
  connect(sShapedNegative_origin.y, modelOutput.sShapedNegative) ;
  connect(sShapedPositive_origin.y, modelOutput.sShapedPositive) 
  ;
end LookupFunctions;

