model LotkaVolterraEquationsRevisited "Predator-prey dynamics with an additional predator"
  extends Icons.Example;
  ModelOutput modelOutput "Main output for the model" ;
  inner ModelSettings modelSettings(init = BusinessSimulation.Types.InitializationOptions.FixedValue, modelTimeHorizon = 140, dt = 0.25) ;
  Theta theta ;

  expandable connector ModelOutput "Main output of the model"
    extends Icons.DataOutPort;
    Population wolves "Wolf population";
    Population foxes "Fox population";
    Population rabbits "Rabbit population";
  end ModelOutput;

  model Theta "Parameter definitions for the Base Case"
    extends Icons.Theta;
    // initial values for populations
    parameter Population IRA = 25 "Initial rabbit population";
    parameter Population IFO = 2 "Initial fox population";
    parameter Population IWO = 4 "Initial wolf population";
    // rates
    parameter Rate foxRabbit_beta = 0.02 "Rabbit fractional death rate per fox";
    parameter Rate foxRabbit_delta = 0.02 "Fox fractional reproduction rate per rabbit";
    parameter Rate foxesDeathRate = 0.4 "Fractional death rate for fox popultion";
    parameter Rate rabbitsReproRate = 0.1 "Fractional reproduction rate for rabbit population";
    parameter Rate wolfRabbit_beta = 0.02 "Rabbit fractional death rate per wolf";
    parameter Rate wolfRabbit_delta = 0.01 "Wolf fractional reproduction rate per rabbit";
    parameter Rate wolvesDeathRate = 0.4 "Fractional death rate for wolf population";
    parameter Rate wolfFox_beta = 0.04 "Fox fractional death rate per wolf";
    parameter Rate wolfFox_delta = 0.08 "Wolf fractional reproduction rate per fox";
  end Theta;
protected
  Stocks.MaterialStock rabbits(initialValue = theta.IRA, redeclare replaceable type OutputType = Population) "Population of rabbits" ;
  Stocks.MaterialStock foxes(initialValue = theta.IFO, redeclare replaceable type OutputType = Population) "Population of foxes" ;
  Stocks.MaterialStock wolves(initialValue = theta.IWO, redeclare replaceable type OutputType = Population) "Population of wolves" ;
  SourcesOrSinks.ExponentialGrowth reproduction(fractionalRate = theta.rabbitsReproRate, hasConstantRate = true) "Population growth for rabbit population" ;
  SourcesOrSinks.ExponentialDecline foxesStarving(hasConstantRate = true, fractionalRate = theta.foxesDeathRate) "Mortality for foxes" ;
  Flows.Interaction.NonlinearInteraction fox_rabbit_predation(hasConstantFactorA = true, hasConstantFactorB = true, a_AB = -theta.foxRabbit_beta, b_AB = theta.foxRabbit_delta) "Foxes predating on rabbits" ;
  Flows.Interaction.NonlinearInteraction wolf_rabbit_predation(hasConstantFactorA = true, hasConstantFactorB = true, a_AB = -theta.wolfRabbit_beta, b_AB = theta.wolfRabbit_delta) "Wolves predating on rabbits" ;
  Flows.Interaction.NonlinearInteraction wolf_fox_predation(hasConstantFactorA = true, hasConstantFactorB = true, a_AB = -theta.wolfFox_beta, b_AB = theta.wolfFox_delta) "Wolves predating on foxes" ;
  SourcesOrSinks.ExponentialDecline wolvesStarving(hasConstantRate = true, fractionalRate = theta.wolvesDeathRate) "Mortality for foxes" ;
public
equation
  connect(reproduction.massPort, rabbits.inflow) ;
  connect(rabbits.outflow, fox_rabbit_predation.portA) ;
  connect(fox_rabbit_predation.portB, foxes.inflow) ;
  connect(foxes.outflow, foxesStarving.massPort) ;
  connect(wolf_rabbit_predation.portA, rabbits.outflow) ;
  connect(wolf_fox_predation.portA, foxes.outflow) ;
  connect(wolves.outflow, wolvesStarving.massPort) ;
  connect(wolves.inflow, wolf_rabbit_predation.portB) ;
  connect(wolves.inflow, wolf_fox_predation.portB) ;
  connect(rabbits.y1, modelOutput.rabbits) ;
  connect(foxes.y1, modelOutput.foxes) ;
  connect(wolves.y1, modelOutput.wolves) 
  ;
end LotkaVolterraEquationsRevisited;

