model LotkaVolterraSystems "Predator-prey dynamics"
  extends Icons.Example;
  ModelOutput modelOutput "Main output of the model" ;
  inner ModelSettings modelSettings(modelDisplayTimeBase = BusinessSimulation.Types.TimeBases.seconds, dt = 0.25, modelTimeHorizon = 100) ;
  Theta theta ;

  model Theta "Parameter definitions for the Base Case"
    extends Icons.Theta;
    parameter Rate alpha = 0.1 "Reproduction rate of prey";
    parameter Rate beta = 0.02 "Mortality rate of prey per predator";
    parameter Rate gamma = 0.4 "Mortality rate of predator";
    parameter Rate delta = 0.02 "Reproduction rate of predators per prey";
  end Theta;

  expandable connector ModelOutput
    extends Icons.DataOutPort;
    Population rabbits "Rabbit population";
    Population foxes "Fox population";
    Population prey "Prey population";
    Population predators "Predator population";
  end ModelOutput;
protected
  Stocks.MaterialStock prey(initialValue = 10, init = BusinessSimulation.Types.InitializationOptions.FixedValue, redeclare replaceable type OutputType = Population) "Prey population" ;
  Stocks.MaterialStock predators(initialValue = 10, init = BusinessSimulation.Types.InitializationOptions.FixedValue, redeclare replaceable type OutputType = Population) "Predator population" ;
  Stocks.MaterialStock rabbits(initialValue = 10, init = BusinessSimulation.Types.InitializationOptions.FixedValue, redeclare replaceable type OutputType = Population) "Rabbit population" ;
  Stocks.MaterialStock foxes(initialValue = 10, init = BusinessSimulation.Types.InitializationOptions.FixedValue, redeclare replaceable type OutputType = Population) "Fox population" ;
  SourcesOrSinks.ExponentialGrowth reproducing(fractionalRate = theta.alpha, hasConstantRate = true) "Growth of rabbit population" ;
  SourcesOrSinks.ExponentialDecline starving(hasConstantRate = true, fractionalRate = theta.gamma) "Foxes mortality in absense of prey" ;
  Flows.Interaction.NonlinearInteraction predation(hasConstantFactorA = true, hasConstantFactorB = true, a_AB = -theta.beta, b_AB = theta.delta, redeclare replaceable type OutputType_A = AmountRate, redeclare replaceable type OutputType_B = AmountRate) "Foxes predating on rabbits" ;
  Flows.Interaction.LotkaVolterra predating(hasConstantAlpha = true, hasConstantBeta = true, hasConstantGamma = true, hasConstantDelta = true, alpha = theta.alpha, beta = theta.beta, delta = theta.delta, gamma = theta.gamma, redeclare replaceable type OutputType_A = AmountRate, redeclare replaceable type OutputType_B = AmountRate, redeclare replaceable type TypeA = Amount, redeclare replaceable type TypeB = Amount) "Compact interaction flow that combines all processes of growth and decline" ;
equation
  connect(prey.outflow, predating.portA) ;
  connect(predating.portB, predators.inflow) ;
  connect(reproducing.massPort, rabbits.inflow) ;
  connect(rabbits.outflow, predation.portA) ;
  connect(predation.portB, foxes.inflow) ;
  connect(foxes.outflow, starving.massPort) ;
  connect(rabbits.y2, modelOutput.rabbits) ;
  connect(prey.y1, modelOutput.prey) ;
  connect(predators.y1, modelOutput.predators) ;
  connect(foxes.y1, modelOutput.foxes) 
  ;
