model ManagingEmployment "Human resource planning"
  extends Icons.Example;
  ModelOutput modelOutput "The model's main output" ;
  inner ModelSettings modelSettings(modelDisplayTimeBase = BusinessSimulation.Types.TimeBases.seconds, modelTimeHorizon = 10, dt = 0.25) ;

  expandable connector ModelOutput "The model's main output"
    extends Icons.DataOutPort;
    Labor workforce "The workforce given as FTE";
    Labor desiredWorkforce "The desired workforce";
    Time experience "Average workexperience in the workforce";
  end ModelOutput;

  Converters.ConstantConverter gainingExperienceRate(redeclare type OutputType = BusinessSimulation.Units.Ratio, value = 1) "Gaining experience in units 1s per 1s" ;
protected
  SourcesOrSinks.Growth hiring "Workforce entering the company" ;
  Stocks.DelayN workforce(hasConstantDelayTime = false, hasStockInfoOutput = true, n = 3, redeclare replaceable type OutputType = Labor, initialValue = 750) "Workforce measured in full-time equivalents (FTE)" ;
  MoleculesOfStructure.Policy.FirstOrderStockAdjustment recruitingPolicy(adjTime = 0.5) "How many people are needed?" ;
  Stocks.HinesCoflow expertise(initialValue = 8, hasStockInfoOutput = false, redeclare type OutputType = BusinessSimulation.Units.Time) "Average erperience of employees measured in years" ;
  SourcesOrSinks.Growth gainingExperience(hasConstantRate = false) "Gaining experience on the job" ;
  Flows.Unidirectional.OutflowDynamicStock attrition "Workforce leaving the company" ;
  SourcesOrSinks.Cloud cloud1 ;
  Converters.ConstantConverterTime employmentPeriod(value = 5, redeclare type OutputType = BusinessSimulation.Units.Time) "Average length of employment" ;
  Converters.DiscreteDelay.Smooth perceivedAttrition(delayTime = 1, init = BusinessSimulation.Types.InitializationOptions.SteadyState, redeclare replaceable type OutputType = LaborGrowthRate) "The rate of leaving the company reported with delay" ;
  InformationSources.RampInput experienceNewEmployees(redeclare type OutputType = BusinessSimulation.Units.Time, offset = 5, startTime = 1, height = -3, duration = 4) "The prior experience of new employees given in years" ;
  InformationSources.RampInput desiredWorkforce(offset = 750, startTime = 1, height = 450, duration = 6, redeclare replaceable type OutputType = Labor) "The desired Workforce given in FTE" ;
public
equation
  connect(hiring.massPort, workforce.inflow) ;
  connect(recruitingPolicy.y, hiring.u) ;
  connect(workforce.y_stockInfo, expertise.u_stockInfo) ;
  connect(gainingExperience.massPort, expertise.inflow) ;
  connect(workforce.outflow, attrition.portA) ;
  connect(attrition.portB, cloud1.massPort) ;
  connect(employmentPeriod.y, workforce.u) ;
  connect(attrition.y, perceivedAttrition.u) ;
  connect(perceivedAttrition.y, recruitingPolicy.u_outflow) ;
  connect(workforce.y2, recruitingPolicy.u_current) ;
  connect(experienceNewEmployees.y, expertise.u) ;
  connect(workforce.y1, modelOutput.workforce) ;
