model SIR "Classical epidemic model by Kermack and McKendrick"
  import BusinessSimulation.Units.*;
  extends Icons.Example;
  inner ModelSettings modelSettings(modelDisplayTimeBase = BusinessSimulation.Types.TimeBases.seconds, modelTimeHorizon = 100, dt = 0.25) ;

  expandable connector ModelOutput "The model's main output"
    extends Icons.DataOutPort;
    Amount infected "Infected population";
    Amount susceptible "Susceptible population";
    Amount removed "Removed population";
  end ModelOutput;

  model Theta "Parameter definitions for the Base Case"
    extends Icons.Theta;
    parameter Dimensionless baseReproductionNumber = 2.5 "Base reproduction number (R0)";
    parameter Time infPeriod = 5 "Length of the infectious period";
    parameter Integer n(min = 1) = 3 "Order of the exponential delay for infected" ;
  end Theta;

  ModelOutput modelOutput "The model's main output" ;
  Theta theta ;
protected
  Stocks.MaterialStock susceptible(initialValue = 1e6, redeclare replaceable type OutputType = Amount) "Population in the susceptible stage of the disease" ;
  Stocks.MaterialStock removed(redeclare replaceable type OutputType = Amount) ;
  Stocks.DelayN infected(n = theta.n, initialValue = 1, hasConstantDelayTime = false, redeclare replaceable type OutputType = Amount) "Population in the infectious stage of the disease" ;
  MoleculesOfStructure.Actuators.Diffusion becoming_infected(hasConstantOtherAdopters = true, hasConstantOtherPopulation = false, hasConstantFractionalAdoptionRate = true, hasConstantAdoptionFraction = true, nextStageIsInfluencing = true, fractionalAdoptionRate = 0, adoptionFraction = 1, otherAdopters = 0) "The infection is spread by a process of social diffusion" ;
  Flows.Unidirectional.OutflowDynamicStock being_removed ;
  Converters.ConstantConverterTime infectiousPeriod(value = theta.infPeriod) "Time interval during which an individual is infectious" ;
  Converters.ConstantConverter R0(value = theta.baseReproductionNumber) "Basic reproduction number for the infectious disease" ;
  Converters.Division transmissionRate "Effective contact rate" ;
  Interfaces.Connectors.DataInPort inputDiffusion "Collected (named) input for the infection process" ;
equation
  connect(susceptible.outflow, becoming_infected.portA) ;
  connect(becoming_infected.portB, infected.inflow) ;
  connect(infected.outflow, being_removed.portA) ;
  connect(being_removed.portB, removed.inflow) ;
  connect(R0.y, transmissionRate.u1) ;
  connect(infectiousPeriod.y, transmissionRate.u2) ;
  connect(becoming_infected.dataIn, inputDiffusion) ;
  connect(removed.y, inputDiffusion.otherPopulation) ;
  connect(infectiousPeriod.y, infected.u) ;
  connect(transmissionRate.y, inputDiffusion.contactRate) ;
  connect(susceptible.y1, modelOutput.susceptible) ;
  connect(infected.y1, modelOutput.infected) ;
  connect(removed.y1, modelOutput.removed) 
  ;
end SIR;

