model BrokenTransition "The inflow to B is proportional to the outflow from A"
  import BusinessSimulation.Units.*;
  import BusinessSimulation.Constants.*;
  extends Interfaces.Basics.GenericFlow;
  extends Interfaces.Basics.Interaction4SO;
  extends Icons.Interaction;
  Interfaces.Connectors.RealInput u_rate if not hasConstantRate "Rate of outflow from A" ;
  Interfaces.Connectors.RealInput u_factor if not hasConstantFactor "Factor of proportionality (units B / units A)" ;
  parameter OutputType_A rate(final min = 0) = unspecified "Constant rate of outflow for the stock A" ;
  parameter Real factor(final min = 0) = 1 "Constant factor of proportionality to be multiplied with the outflow from A [base units B/base units A]" ;
  parameter OutputType_B outputB(final min = 0) = 1 "Constant output of B to specify the conversion factor as the ratio outputB : inputA" ;
  parameter OutputType_A inputA(final min = 0) = 1 "Constant input of A to specify the conversion factor as the ratio outputB : inputA" ;
  parameter Boolean hasConstantFactor = false "= true, if the factor is to be given by the constant parameter" ;
  parameter Boolean hasConstantRate = false "= true, if the outflow rate for A is to be given by the constant parameter" ;
  parameter Boolean useExplicitRatio = false "= true, if instead of a constant factor a constant ratio of output per input is to be entered" ;
protected
  parameter Real cr = if useExplicitRatio then outputB / inputA else 1. "Explicit conversion ratio to be used instead of a factor" ;
  Converters.Gain conversionFactor(final c = cr) ;
  SourcesOrSinks.Decline flowingOut "Outflow for stock A" ;
  Converters.PassThrough u_OutflowRate_A if not hasConstantRate "Input of outflow rate" ;
  Converters.ConstantConverter parOutflowRate_A(final value = rate) if hasConstantRate "Constant rate of outflow for A" ;
  Converters.Product_2 inflowRate_B "Rate of inflow to stock B" ;
  SourcesOrSinks.Growth flowingIn "Inflow to stock B" ;
  Converters.PassThrough u_FactorOfProportionality if not hasConstantFactor "Continuous input" ;
  Converters.ConstantConverter parFactorOfProportionality(final value = factor) if hasConstantFactor "Constant input" ;
equation
  assert(not hasConstantRate or rate < inf, "Parameter rate needs to be specified");
  assert(inputA > 0, "InputA has to be greater than zero to specify conversion ratio");
  connect(portA, flowingOut.massPort) ;
  connect(u_OutflowRate_A.y, flowingOut.u) ;
  connect(parOutflowRate_A.y, flowingOut.u) ;
  connect(flowingIn.massPort, portB) ;
  connect(inflowRate_B.y, flowingIn.u) ;
  connect(flowingOut.y2, inflowRate_B.u2) ;
  connect(flowingOut.y, y1_A) ;
  connect(flowingOut.y, y_A) ;
  connect(flowingIn.y1, y_B) ;
  connect(flowingIn.y1, y1_B) ;
  connect(u_factor, u_FactorOfProportionality.u) ;
  connect(u_rate, u_OutflowRate_A.u) ;
  connect(conversionFactor.y, inflowRate_B.u1) ;
  connect(u_FactorOfProportionality.y, conversionFactor.u) ;
  connect(parFactorOfProportionality.y, conversionFactor.u) 
  ;
end BrokenTransition;

