  Interfaces.Connectors.RealInput u_factor if not hasConstantFactor "Factor of proportionality (amount of A per amount of B)" ;
  parameter OutputType_B rate(final min = 0) = unspecified "Constant rate of inflow to the stock B" ;
  parameter Real factor(final min = 0) = 1 "Constant factor of proportionality to be multiplied with the inflow to B [base units A/base units B]" ;
  parameter OutputType_A inputA(final min = 0) = 1 "Constant input of A to specify the conversion factor as the ratio inputA : outputB" ;
  parameter OutputType_B outputB(final min = 0) = 1 "Constant output of B to specify the conversion factor as the ratio inputA : outputB" ;
  parameter Boolean hasConstantFactor = false "= true, if the factor is to be given by the constant parameter" ;
  parameter Boolean hasConstantRate = false "= true, if the outflow rate for A is to be given by the constant parameter" ;
  parameter Boolean useExplicitRatio = false "= true, if instead of a constant factor a constant ratio of output per input is to be entered" ;
protected
  parameter Real cr = if useExplicitRatio then inputA / outputB else 1. "Explicit conversion ratio to be used instead of a factor" ;
  Converters.Gain conversionFactor(final c = cr) ;
  SourcesOrSinks.Decline flowingOut "Outflow for stock A" ;
  Converters.PassThrough u_InflowRate_B if not hasConstantRate "Input of inflow rate for B" ;
  Converters.ConstantConverter parInflowRate_B(final value = rate) if hasConstantRate "Constant rate of inflow to B" ;
  Converters.Product_2 outflowRate_A "Rate of outflow from stock A" ;
  SourcesOrSinks.Growth flowingIn "Inflow to stock B" ;
  Converters.PassThrough u_Factor if not hasConstantFactor "Input for factor of proportionality" ;
