  connect(flowingIn.y1, y_B) ;
  connect(flowingIn.y1, y1_B) ;
  connect(u_factor, u_Factor.u) ;
  connect(u_rate, u_InflowRate_B.u) ;
  connect(parInflowRate_B.y, flowingIn.u) ;
  connect(u_InflowRate_B.y, flowingIn.u) ;
  connect(flowingIn.y2, outflowRate_A.u2) ;
  connect(outflowRate_A.y, flowingOut.u) ;
  connect(conversionFactor.y, outflowRate_A.u1) ;
  connect(conversionFactor.u, u_Factor.y) ;
  connect(conversionFactor.u, parFactor.y) 
