model ComplexInteraction "Combined linear and nonlinear interaction"
  import BusinessSimulation.Units.*;
  extends Icons.Interaction;
  extends Interfaces.Basics.GenericFlow;
  extends Interfaces.Basics.Interaction4SO;
  InputConnector dataIn "Expandable connector for continuous input" ;
  replaceable type TypeA = Unspecified "Type selector for stock A" ;
  replaceable type TypeB = Unspecified "Type selector for stock B" ;
  parameter TypeA refA(min = 0) = 1 "Reference value, i.e., divisor, for the couplings b_A, b_AB";
  parameter TypeB refB(min = 0) = 1 "Refrence value, i.e., divisor, for the couplings a_B, a_AB";

  encapsulated expandable connector InputConnector "Data bus for inputs"
    import ICON = BusinessSimulation.Icons.DataInPort;
    extends ICON;
    // coefficients for net flow equations A
    Real a_0 "Growth rate for A (independent)";
    Real a_A "Fractional rate of growth for A (self-coupling A)";
    Real a_B "Rate of growth for A per unit of B (coupling of B to A)";
    Real a_AB "Fractional rate of growth for A per unit of B (nonlinear coupling)";
    // coefficients for net flow equation B
    Real b_0 "Growth rate for B (independent)";
    Real b_B "Fractional growth rate for B (self-coupling)";
    Real b_A "Rate of growth for B per unit of A (coupling of A to B)";
    Real b_AB "Fractional growth rate for B per unit of A (nonlinear coupling)";
  end InputConnector;
protected
  LinearInteraction linearInteraction(refB = refB, refA = refA) "Linear interaction between A and B" ;
  NonlinearInteraction nonlinearInteraction(refB = refB, refA = refA) "Nonlinear interaction between A and B" ;
  Converters.Add_2 netRate_B ;
  Converters.Add_2 netRate_A ;
  Interfaces.Connectors.RealOutput a_0 "Growth rate for A (independent)" ;
  Interfaces.Connectors.RealOutput a_A "Fractional rate of growth for A (self-coupling A)" ;
  Interfaces.Connectors.RealOutput a_B "Rate of growth for A per unit of B (coupling of B to A)" ;
  Interfaces.Connectors.RealOutput a_AB "Fractional rate of growth for A per unit of B (nonlinear coupling)" ;
  Interfaces.Connectors.RealOutput b_0 "Growth rate for B (independent)" ;
  Interfaces.Connectors.RealOutput b_B "Fractional growth rate for B (self-coupling)" ;
  Interfaces.Connectors.RealOutput b_A "Rate of growth for B per unit of A (coupling of A to B)" ;
  Interfaces.Connectors.RealOutput b_AB "Fractional growth rate for B per unit of A (nonlinear coupling)" ;
  Interfaces.Connectors.DataBus dataBus ;
equation
  assert(refA > 0, "Reference value for A must be greater than zero");
  assert(refB > 0, "Reference value for B must be greater than zero");
  connect(portA, linearInteraction.portA) ;
  connect(linearInteraction.portB, portB) ;
  connect(portA, nonlinearInteraction.portA) ;
  connect(nonlinearInteraction.portB, portB) ;
  // inputConnector to connectors
  connect(dataIn.a_0, a_0) ;
  connect(dataIn.a_A, a_A) ;
  connect(dataIn.a_B, a_B) ;
  connect(dataIn.a_AB, a_AB) ;
  connect(dataIn.b_0, b_0) ;
  connect(dataIn.b_B, b_B) ;
  connect(dataIn.b_A, b_A) ;
  connect(dataIn.b_AB, b_AB) ;
  // connectors to interior inputConnectors
  connect(a_0, dataBus.a_0) ;
  connect(a_A, dataBus.a_A) ;
  connect(a_B, dataBus.a_B) ;
  connect(a_AB, dataBus.a_AB) ;
  connect(b_0, dataBus.b_0) ;
  connect(b_B, dataBus.b_B) ;
  connect(b_A, dataBus.b_A) ;
  connect(b_AB, dataBus.b_AB) ;
  // other connections
  connect(linearInteraction.y_A, netRate_A.u1) ;
  connect(nonlinearInteraction.y1_A, netRate_A.u2) ;
  connect(netRate_A.y, y_A) ;
  connect(netRate_A.y, y1_A) ;
  connect(nonlinearInteraction.y_B, netRate_B.u2) ;
  connect(linearInteraction.y1_B, netRate_B.u1) ;
  connect(netRate_B.y, y_B) ;
  connect(netRate_B.y, y1_B) ;
  connect(linearInteraction.dataIn, dataBus) ;
  connect(nonlinearInteraction.dataIn, dataBus) ;
  , Icon(coordinateSystem(extent = {{-100, -100}, {100, 100}}, preserveAspectRatio = true, initialScale = 0.1, grid = {10, 10}), graphics = {Text(visible = true, origin = {0, 75}, textColor = {0, 128, 0}, extent = {{-100, -12}, {100, 12}}, textString = "Linear & Nonlinear", fontName = "Lato", textStyle = {TextStyle.Bold})}));
end ComplexInteraction;

within BusinessSimulation.Flows.Interaction;

model LotkaVolterra "The Lotka-Volterra equations to model predator-prey-dynamics"
  import BusinessSimulation.Units.*;
  import BusinessSimulation.Constants.*;
  extends Interfaces.Basics.GenericFlow;
  extends Interfaces.Basics.Interaction4SO;
  extends Icons.Interaction;
  InputConnector dataIn if not (hasConstantAlpha and hasConstantBeta and hasConstantGamma and hasConstantDelta) "Inputs for predator-prey model" ;
  replaceable type TypeA = Unspecified "Type selector for stock A" ;
  replaceable type TypeB = Unspecified "Type selector for stock B" ;
  parameter TypeA refA(min = 0) = 1 "Reference value, i.e., divisor, for the couplings b_A, b_AB";
  parameter TypeB refB(min = 0) = 1 "Refrence value, i.e., divisor, for the couplings a_B, a_AB";
  parameter Rate alpha = unspecified "Fractional growth rate of prey population (A)" ;
  parameter Rate beta = unspecified "Fractional rate of decline for prey population (A) per predator" ;
  parameter Rate gamma = unspecified "Fractional rate of decline for predator population (B)" ;
  parameter Rate delta = unspecified "Fractional rate of growth for predator population (B) per prey" ;
  parameter Boolean hasConstantAlpha = false "= true, if the constant parameter value is to be used instead of the input connector" ;
  parameter Boolean hasConstantBeta = false "= true, if the constant parameter value is to be used instead of the input connector" ;
  parameter Boolean hasConstantGamma = false "= true, if the constant parameter value is to be used instead of the input connector" ;
  parameter Boolean hasConstantDelta = false "= true, if the constant parameter value is to be used instead of the input connector" ;

  encapsulated expandable connector InputConnector "DataBus for inputs"
    import ICON = BusinessSimulation.Icons.DataInPort;
    extends ICON;
    Real alpha "Fractional growth rate of prey population (A)";
    Real beta "Fractional rate of decline for prey population (A) per predator";
    Real delta "Fractional rate of growth for predator population (B) per prey";
    Real gamma "Fractional rate of decline for predator population (B)"
    ;
  end InputConnector;
protected
  ComplexInteraction complexInteraction(refA = refA, refB = refB) ;
  Converters.ConstantConverter zeroRate(value = 0) "Zero rate input" ;
  Converters.Gain fractionalGrowthRatePredator(c = -1) "Convert rate of delince to growth rate" ;
  Converters.Gain couplingFactorForPrey(c = -1) "Convert rate of delince to growth rate" ;
  Converters.ConstantConverter parAlpha(value = alpha) if hasConstantAlpha "Constant alpha (optional)" ;
  Converters.ConstantConverter parBeta(value = beta) if hasConstantBeta "Constant beta (optional)" ;
  Converters.ConstantConverter parGamma(value = gamma) if hasConstantGamma "Constant gamma (optional)" ;
  Converters.ConstantConverter parDelta(value = delta) if hasConstantDelta "Constant delta (optional)" ;
  Interfaces.Connectors.RealOutput u_alpha if not hasConstantAlpha ;
  Interfaces.Connectors.RealOutput u_beta if not hasConstantBeta ;
  Interfaces.Connectors.RealOutput u_gamma if not hasConstantGamma ;
  Interfaces.Connectors.RealOutput u_delta if not hasConstantDelta ;
  Interfaces.Connectors.DataBus dataBus ;
equation
  assert(not hasConstantAlpha or alpha < inf, "Parameter alpha needs to be specified");
  assert(not hasConstantBeta or beta < inf, "Parameter beta needs to be specified");
  assert(not hasConstantGamma or gamma < inf, "Parameter gamma needs to be specified");
  assert(not hasConstantDelta or delta < inf, "Parameter delta needs to be specified");
  assert(refA > 0, "Reference value for A must be greater than zero");
  assert(refB > 0, "Reference value for B must be greater than zero");
  connect(dataIn.alpha, u_alpha) ;
  connect(dataIn.beta, u_beta) ;
  connect(dataIn.gamma, u_gamma) ;
  connect(dataIn.delta, u_delta) ;
  connect(portA, complexInteraction.portA) ;
  connect(complexInteraction.portB, portB) ;
  connect(complexInteraction.y1_B, y1_B) ;
  connect(complexInteraction.y1_B, y_B) ;
  connect(complexInteraction.y_A, y_A) ;
  connect(complexInteraction.y_A, y1_A) ;
  connect(complexInteraction.dataIn, dataBus) ;
  connect(u_beta, couplingFactorForPrey.u) ;
  connect(parBeta.y, couplingFactorForPrey.u) ;
  connect(parGamma.y, fractionalGrowthRatePredator.u) ;
  connect(u_gamma, fractionalGrowthRatePredator.u) ;
  // feeding the dataBus
  connect(u_alpha, dataBus.a_A) ;
  connect(parAlpha.y, dataBus.a_A) ;
  connect(couplingFactorForPrey.y, dataBus.a_AB) ;
  connect(fractionalGrowthRatePredator.y, dataBus.b_B) ;
  connect(parDelta.y, dataBus.b_AB) ;
  connect(u_delta, dataBus.b_AB) ;
  // setting parameters a_0,b_0,a_B,b_A to zero
  connect(zeroRate.y, dataBus.a_0) ;
  connect(zeroRate.y, dataBus.a_B) ;
  connect(zeroRate.y, dataBus.b_0) ;
  connect(zeroRate.y, dataBus.b_A) 
  ;
end LotkaVolterra;

