within BusinessSimulation.Functions;

encapsulated function allocateAvailable "Allocate an available amount using priority profiles given by distributions"
  import PP = BusinessSimulation.Types.PriorityProfiles;
  import ICON = BusinessSimulation.Icons.Function;
  import BusinessSimulation.Functions.allocatedAmounts;
  import Modelica.Math.Nonlinear.solveOneNonlinearEquation;
  import BusinessSimulation.Functions.UtilityFunctions.findClearAttrac;
  import BusinessSimulation.Constants.eps;
  extends ICON;
  input Real x "Available amount to be allocated";
  input Real[:] vecA "Vector of attractiveness (i.e., priority) scores for recipients";
  input Real[size(vecA, 1)] vecC "Vector of supply capacities or demand saturation levels";
  input Real[size(vecA, 1)] vecW "Vector of width parameters for priority distributions";
  input PP pp = PP.uniform "Priority distribution to be used for allocation";
  input Real tolerance = 100 * eps;
  output Real[size(vecA, 1)] y "Allocated amounts";
protected
  Integer n = size(vecA, 1) "Number of recipients (i.e., length of vecA)";
  Real totalCap = sum(vecC) "The sum of all elements in the vector vecC";
  Real cA "The clearing attractiveness";
  Real w_max "Maximum element in vecW";
  Real u_min "Lower bound for finding cA";
  Real u_max "Upper bound for finding cA";
algorithm
  // nothing available
  if x <= 0 then
    y := zeros(n);
    return;
    // no scarcity
  elseif x >= totalCap then
    y := vecC;
    return;
    // find a clearing attractiveness that allocates the available amount according to priorities
  else
    w_max := max(vecW);
    u_min := -w_max;
    // assuming min(vecA) = 0
    u_max := max(vecA) + w_max;
    cA := solveOneNonlinearEquation(function findClearAttrac(amount = x, vecA = vecA, vecC = vecC, vecW = vecW, pp = pp), u_min = u_min, u_max = u_max, tolerance = tolerance);
    y := allocatedAmounts(cA, vecA, vecC, vecW, pp);
  end if
  ;
end allocateAvailable;

within BusinessSimulation.Functions;

encapsulated function allocatedAmounts "Allocate a scarce resoure using priority profiles given by distributions"
  import PP = BusinessSimulation.Types.PriorityProfiles;
  import ICON = BusinessSimulation.Icons.Function;
  import BusinessSimulation.Functions.{allocateUniform, allocateTriangular, allocateNormal, allocateExtremeValue};
  extends ICON;
  input Real x "Clearing attractiveness";
  input Real[:] vecA "Vector of attractiveness (i.e., priority) scores for recipients";
  input Real[size(vecA, 1)] vecC "Vector of supply capacities or demand saturation levels";
  input Real[size(vecA, 1)] vecW "Vector of width parameters for priority distributions";
  input PP pp = PP.uniform "Priority distribution to be used for allocation";
  output Real[size(vecA, 1)] y "Allocated amounts";
protected
  Integer n = size(vecA, 1) "Number of recipients (i.e., length of vecA)";
  Real[n] vecAllocFrac "Vector of fractions allocated";
algorithm
  vecAllocFrac := if pp == PP.triangular then array(allocateTriangular(x, vecA[i], vecW[i]) for i in 1:n) elseif pp == PP.normal then array(allocateNormal(x, vecA[i], vecW[i]) for i in 1:n)
   elseif pp == PP.extremeValue then array(allocateExtremeValue(x, vecA[i], vecW[i]) for i in 1:n) else array(allocateUniform(x, vecA[i], vecW[i]) for i in 1:n);
  y := vecAllocFrac .* vecC
  ;
end allocatedAmounts;

within BusinessSimulation.Functions;

encapsulated function allocateExtremeValue "Allocate a scarce resoure using an extreme value priority distribution"
  import ICON = BusinessSimulation.Icons.Function;
  extends ICON;
  input Real x "Clearing attractiveness";
  input Real a "Attractiveness of recipient";
  input Real w "Width of distribution (i.e., defining a highest density region with probability of 0.997)";
  output Real y "Fraction of total capacity or demand allocated to the recipient";
algorithm
  y := if w <= 0.0 then 0.0 else 1.0 - exp(-exp(8.12447 * (a - x) / w))
  ;
end allocateExtremeValue;

within BusinessSimulation.Functions;

encapsulated function allocateNormal "Allocate a scarce resoure using a normal priority distribution"
  import ICON = BusinessSimulation.Icons.Function;
  import Modelica.Math.Special.erf;
  extends ICON;
  input Real x "Clearing attractiveness";
  input Real a "Attractiveness of recipient";
  input Real w "Width of distribution (i.e., six times the standard deviation)";
  output Real y "Fraction of total capacity or demand allocated to the recipient";
algorithm
  y := if w <= 0.0 then 0.0 else 0.5 * (1.0 + erf(3.0 * sqrt(2) * (a - x) / w))
  ;
end allocateNormal;

within BusinessSimulation.Functions;

encapsulated function allocateTriangular "Allocate a scarce resoure using a triangular priority distribution"
  import ICON = BusinessSimulation.Icons.Function;
  extends ICON;
  input Real x "Clearing attractiveness";
  input Real a "Attractiveness of recipient";
  input Real w "Width of distribution (i.e., span of the triangular distribution)";
  output Real y "Fraction of total capacity or demand allocated to the recipient";
protected
  Real lb = a - w / 2.0;
  Real ub = a + w / 2.0;
  Real w2 = w ^ 2;
algorithm
  y := if w <= 0.0 then 0.0 elseif lb <= x and x <= a then 1.0 - 2.0 * (x - lb) ^ 2 / w2
   elseif a < x and x <= ub then 2.0 * (ub - x) ^ 2 / w2
   elseif x > ub then 0.0 else 1.0
  ;
end allocateTriangular;

within BusinessSimulation.Functions;

encapsulated function allocateUniform "Allocate a scarce resoure using a uniform priority distribution"
  import ICON = BusinessSimulation.Icons.Function;
  extends ICON;
  input Real c "Clearing attractiveness";
  input Real a "Attractiveness of recipient";
  input Real w "Width of distribution (i.e., span of the uniform distribution)";
  output Real y "Fraction of total capacity or demand allocated to the recipient";
protected
  Real twoA = 2. * a;
  Real twoC = 2. * c;
algorithm
  y := if w <= 0.0 then 0.0 elseif twoA > w + twoC then 1.0
   elseif twoA <= w + twoC and twoA + w >= twoC then (twoA + w - twoC) / (2.0 * w) else 0.0
  ;
end allocateUniform;

within BusinessSimulation.Functions;

function allTrueQ "Gives true, if all elements in a vector of Booleans are true"
