function constrainedRate "Set rate for a port according to signals from stock"
  extends BusinessSimulation.Icons.Function;
  input Real indicatedRate "Proposed rate for port of flow element";
  input Boolean stopInflow "Signal from connected stock";
  input Boolean stopOutflow "Signal from connected stock";
  output Real actualRate "The rate to use";
protected
  // neagtive rate is inflow to stock
  Boolean indRateIsInflow = indicatedRate < 0;
algorithm
  // set rate to zero if stopSignal matches character of flow
  actualRate := if stopInflow and indRateIsInflow then 0 elseif stopOutflow and not indRateIsInflow then 0 else indicatedRate
  ;
end constrainedRate;

within BusinessSimulation.Functions;

function constrainedRateBoolean "Return true, if the indicated rate meets restrictions"
  extends BusinessSimulation.Icons.Function;
  // neagtive rate is inflow to stock
  input Boolean indRateIsInflow "Proposed rate is inflow to a connected stock";
  input Boolean stopInflow "Signal from connected stock";
  input Boolean stopOutflow "Signal from connected stock";
  output Boolean useRate "= true, if the indicated rate does not violate restrictions";
algorithm
  // set rate to zero if stopSignal matches character of flow
  useRate := if stopInflow and indRateIsInflow then false elseif stopOutflow and not indRateIsInflow then false else true
  ;
end constrainedRateBoolean;

within BusinessSimulation.Functions;

function evalmf "Evaluate a fuzzy membership function"
  import BusinessSimulation.Types.MembershipFunctionTypes;
  import BusinessSimulation.Functions.{rampmf, trimf, smf, sigmf, pimf, psigmf, gaussmf, gbellmf, trapmf};
  extends BusinessSimulation.Icons.Function;
  input Real x "Input value for which the degree of membership is to be computed";
  input MembershipFunctionTypes mft = MembershipFunctionTypes.trapezoidal "Type of membership function to be used";
  input Real a "Parameter of membership function";
  input Real b "Parameter of membership function";
  input Real c "Parameter of membership function";
  input Real d "Parameter of membership function";
  output Real y "Degree of membership";
algorithm
  y := if mft == MembershipFunctionTypes.ramp then rampmf(x, a, b) elseif mft == MembershipFunctionTypes.triangular then trimf(x, a, b, c)
   elseif mft == MembershipFunctionTypes.sshaped then smf(x, a, b)
   elseif mft == MembershipFunctionTypes.sigmoidal then sigmf(x, a, c)
   elseif mft == MembershipFunctionTypes.pishaped then pimf(x, a, b, c, d)
   elseif mft == MembershipFunctionTypes.psigmoidal then psigmf(x, a, b, c, d)
   elseif mft == MembershipFunctionTypes.gaussian then gaussmf(x, a, c)
   elseif mft == MembershipFunctionTypes.bell then gbellmf(x, a, b, c) else trapmf(x, a, b, c, d)
  ;
end evalmf;

within BusinessSimulation.Functions;

function gaussmf "Gaussian membership function"
  extends BusinessSimulation.Icons.Function;
  input Real x "Input value for which the degree of membership is to be computed";
  input Real a "Half width at half maximum (HWHM)";
  input Real c "Mean value";
  output Real y "Degree of membership";
protected
  // sigma = a / sqrt(log(4))
  Real sigma = a / 1.177410022515474691;
algorithm
  y := exp(-(x - c) ^ 2 / (2 * sigma ^ 2))
  ;
end gaussmf;

within BusinessSimulation.Functions;

function gbellmf "Generalized bell-shaped membership function"
  extends BusinessSimulation.Icons.Function;
  input Real x "Input value for which the degree of membership is to be computed";
  input Real a "Width of core (i.e., the interval for which the function gives 1)";
  input Real b "Shape parameter (larger values → steeper transition";
  input Real c "Center of membership function";
  output Real y "Degree of membership";
algorithm
  y := 1 / (1 + abs((x - c) / a) ^ (2 * b))
  ;
end gbellmf;

within BusinessSimulation.Functions;

function geometricMean "(Weighted) geometric mean"
  import BusinessSimulation.Constants.{inf, small};
  extends BusinessSimulation.Icons.Function;
  input Real[:] x "Vector input";
  input Real[size(x, 1)] weights = ones(size(x, 1)) "Vector of weights";
  output Real y;
protected
  Real[n] w "Normalized and clipped weights";
  Integer n = size(x, 1) "Length of the input vector";
algorithm
  // clip weights to eliminate negative values
  w := BusinessSimulation.Functions.clip(weights, {0, inf});
  y := if min(x) < small then 0 else exp(sum(log(x[i]) * w[i] for i in 1:n) / sum(w))
  ;
end geometricMean;

