encapsulated function hunt "Find left index in an ordered list of value given a start index value"
  import BusinessSimulation.Icons.Function;
  import BusinessSimulation.Functions.bitShiftRight;
  extends Function;
  input Real x "Value to locate in a list";
  input Real[:] xVals "Ordered list of values";
  input Integer jsav = 1 "Start index value for the search";
  output Integer res "Index for the list so that xVals[res] <= x <= xVals[res+1]";
protected
  Integer n = size(xVals, 1) "Length of the list of values";
  Boolean ascendingQ "= true, if the list is ascending";
  Integer jl, jm, ju "Index values for the search";
  Integer inc "Increment";
  Boolean cond "Partial condition in a nested Boolean expression";
algorithm
  // initialize the hunt
  ascendingQ := xVals[n] >= xVals[1];
  inc := 1;
  jl := jsav;
  if jl < 1 or jl > n then
    // if the initial guess is not useful go to bisection immediately
    jl := 1;
    ju := n;
  else
    // either hunt up or down
    cond := x >= xVals[jl];
    if cond == ascendingQ then
      // hunt up
      while true loop
        ju := jl + inc;
        if ju >= n then
          // then off end of list
          ju := n;
          break;
        else
          cond := x < xVals[ju];
          if cond == ascendingQ then
            // found bracket
            break;
          else
            // not done, so double the increment and try again
            jl := ju;
            inc := inc + inc;
          end if;
        end if;
      end while;
    else
      // hunt down
      ju := jl;
      while true loop
        jl := jl - inc;
        if jl <= 1 then
          // end of table
          jl := 1;
          break;
        else
          cond := x >= xVals[jl];
          if cond == ascendingQ then
            // found bracket
            break;
          else
            // not done, so double the increment and try again
            ju := jl;
            inc := inc + inc;
          end if;
        end if;
      end while;
    end if;
  end if;
  // hunt is done, so begin final bisection phase
  while ju - jl > 1 loop
    jm := bitShiftRight(ju + jl);
    cond := x >= xVals[jm];
    if cond == ascendingQ then
      jl := jm;
    else
      ju := jm;
    end if;
  end while;
  // return jl
  res := jl
  ;
end hunt;

within BusinessSimulation.Functions;

encapsulated function interpolate "Interpolate in an ordered list of tuples"
  import BusinessSimulation.Icons.Function;
  import BusinessSimulation.Functions.{rawInterpolate, hunt, locate};
  extends Function;
  input Real x "Value to locate in a list";
  input Real[:, 2] tuples "Ordered list of values";
  input Integer jlo = 1 "Index start value for the search";
  output Real y "Interpolated value";
  output Integer jsav "Index value used for the current interpolation";
protected
  Integer n = size(tuples, 1) "Length of the list of tuples";
  Real[n] xVals = tuples[:, 1] "Abscissa values for the list of tuples";
algorithm
  jsav := max(1, jlo);
  if jsav == 1 then
    // use locate
    jsav := locate(x, xVals);
  else
    // use hunt
    jsav := hunt(x, xVals, jsav);
  end if;
  y := rawInterpolate(x, tuples, jsav)
  ;
end interpolate;

within BusinessSimulation.Functions;

function janoschek "Janoschek's Growth Curve"
  extends BusinessSimulation.Icons.Function;
  input Real x "x-Value";
  input Real b "Lower asymptote";
  input Real l "Upper asymptote";
  input Real k "Growth rate";
  input Real d "Control of abscissa for the point of inflection";
  output Real y;
algorithm
  y := l - (l - b) * exp(-k * x ^ d)
  ;
end janoschek;

within BusinessSimulation.Functions;

encapsulated function locate "Find left index in an ordered list of values"
  import BusinessSimulation.Icons.Function;
  import BusinessSimulation.Functions.bitShiftRight;
  extends Function;
  input Real x "Value to locate in a list";
  input Real[:] xVals "Ordered list of values";
  output Integer res "Index for the list so that xVals[res] <= x <= xVals[res+1]";
protected
  Integer n = size(xVals, 1) "Length of the list of values";
  Boolean ascendingQ "= true, if the list is ascending";
  Integer jl, jm, ju "Index values for the search";
  Boolean cond "Partial condition in a nested Boolean expression";
algorithm
  // initialize the search
  ascendingQ := xVals[n] >= xVals[1];
  jl := 1;
  ju := n;
  // while we are not yet done iterate
  while ju - jl > 1 loop
    // find mid point for ju and jl
    jm := bitShiftRight(ju + jl);
    // replace either the lower or the upper limit as appropriate
    cond := x >= xVals[jm];
    if cond == ascendingQ then
      jl := jm;
    else
      ju := jm;
    end if;
  end while;
  // return jl
  res := jl
  ;
end locate;

