function pimf "Pi-shaped membership function"
  extends BusinessSimulation.Icons.Function;
  input Real x "Input value for which the degree of membership is to be computed";
  input Real a "Foot of the s-shaped part(lower bound of the support)";
  input Real b "Shoulder of the s-haped part (lower bound of the core)";
  input Real c "Shoulder of the z-shaped part (upper bound of the core)";
  input Real d "Foot of the z-shaped part (upper bound of the support)";
  output Real y "Degree of membership";
protected
  Real midpointS = (a + b) / 2;
  Real midpointZ = (c + d) / 2;
algorithm
  y := if x <= a then 0 elseif a < x and x <= midpointS then 2 * ((x - a) / (b - a)) ^ 2
   elseif midpointS < x and x <= b then 1 - 2 * ((x - b) / (b - a)) ^ 2
   elseif b < x and x <= c then 1
   elseif c < x and x <= midpointZ then 1 - 2 * ((x - c) / (d - c)) ^ 2
   elseif midpointZ < x and x <= d then 2 * ((x - d) / (d - c)) ^ 2 else 1
  ;
end pimf;

within BusinessSimulation.Functions;

encapsulated function plCDF "Generate a piecewise linear cumulative distribution function from a piecewise linear density function"
  import BusinessSimulation.Icons.Function;
  import BusinessSimulation.Functions.{normalizePLpdf, areaLineSegment};
  extends Function;
  input Real[:, 2] tuples "Piecewise linear function, i.e., { {x1,f(x1), {x2,f(x2)}, ... }";
  input Boolean rescaleQ = true "= true, if the support is to be rescaled to the unit interval";
  output Real[size(tuples, 1), 2] cdf "Piecewise linear cumulated distribution function";
protected
  Integer n = size(tuples, 1) "Number of points in the piecewise linear density function";
  Real[n, 2] pdf "Piecewise linear density function";
  Real nc "Normalization constant";
algorithm
  // normalize piecewise function if needed
  pdf := if rescaleQ then normalizePLpdf(tuples, rescaleQ = true) else normalizePLpdf(tuples, rescaleQ = false);
  // initialize cdf
  cdf[1] := {pdf[1, 1], 0};
  for i in 2:n loop
    cdf[i] := {pdf[i, 1], cdf[i - 1, 2] + areaLineSegment(pdf[i - 1], pdf[i])};
  end for;

within BusinessSimulation.Functions;

function polynomialFunction "Polynomial function of degree n"
  extends BusinessSimulation.Icons.Function;
  input Real x "Independent variable";
  input Real a[:] "Vector of coefficients";
  output Real y "Value of the polynomial equation";
protected
  Integer i;
  Integer n = size(a, 1);
algorithm
  y := 0;
  for i in 1:n loop
    y := y + a[i] * x ^ (i - 1);
  end for
  ;
end polynomialFunction;

within BusinessSimulation.Functions;

function psigmf "Product of two sigmoidal membership functions"
  import BusinessSimulation.Functions.sigmf;
  extends BusinessSimulation.Icons.Function;
  input Real x "Input value for which the degree of membership is to be computed";
  input Real a "Shape parameter controlling the width of s-shaped transition area (higher values → steeper transition)";
  input Real b "Center of s-shaped transition area";
  input Real c "Shape parameter controlling the width of z-shaped transition area (higher values → steeper transition)";
  input Real d "Center of z-shaped transition area";
  output Real y "Degree of membership";
algorithm
  y := sigmf(x, a = a, c = b) * sigmf(x, a = -c, c = d)
  ;
end psigmf;

within BusinessSimulation.Functions;

function rampmf "Bounded ramp membership function"
  extends BusinessSimulation.Icons.Function;
  input Real x "Input value for which the degree of membership is to be computed";
  input Real a "Lower bound";
  input Real b "Upper bound";
  output Real y "Degree of membership";
algorithm
  y := max(min((x - a) / (b - a), 1), 0)
  ;
end rampmf;

