encapsulated function rawInterpolate "Interpolate in a list of tuples given the index value for the index value to the left"
  import BusinessSimulation.Icons.Function;
  import BusinessSimulation.Functions.bitShiftRight;
  extends Function;
  input Real x "Value to locate in a list";
  input Real[:, 2] tuples "Ordered list of values";
  input Integer jlo "Index value to the left of x";
  output Real y "Interpolated value";
protected
  Integer n = size(tuples, 1) "Length of the list of tuples";
  Real[n] xVals = tuples[:, 1] "Abscissa values for the list of tuples";
  Boolean ascendingQ "= true, if the list of xVals is ascending";
  Boolean cond "Partial condition in a nested Boolean expression";
algorithm
  ascendingQ := xVals[n] >= xVals[1];
  cond := x < xVals[jlo];
  if cond == ascendingQ then
    // return the left side table value
    y := tuples[jlo, 2];
  else
    cond := x > xVals[jlo + 1];
    if cond == ascendingQ then
      // return right table value
      y := tuples[jlo + 1, 2];
    else
      // x is within the interval [ xVals[jlo], xVals[jlo+1] ]
      y := tuples[jlo, 2] + (tuples[jlo + 1, 2] - tuples[jlo, 2]) / (xVals[jlo + 1] - xVals[jlo]) * (x - xVals[jlo]);
    end if;
  end if
  ;
end rawInterpolate;

within BusinessSimulation.Functions;

function rescale "Rescale values from one range to another"
  extends BusinessSimulation.Icons.Function;
  input Real x "Value to be transformed";
  input Real x_range[2] "Original range [min,max] given as a list";
  input Real y_range[2] = {0, 1} "Rescaled range [y_min, y_max] given as a list (default = {0,1})";
  output Real y "Rescaled value to run from y_min to y_max over the range min to max";
protected
  Real x_min = x_range[1];
  Real x_max = x_range[2];
  Real y_min = y_range[1];
  Real y_max = y_range[2];
algorithm
  y := y_min + (x - x_min) * (y_max - y_min) / (x_max - x_min) 
  ;
end rescale;

within BusinessSimulation.Functions;

function rescaleVector "Rescale a list of values from one range to another"
  extends BusinessSimulation.Icons.Function;
  input Real x[:] "List of values (vector) to be rescaled";
  input Real x_range[2] = {min(x), max(x)} "Original range [min,max] given as a list (default = {min(x), max(x)})";
  input Real y_range[2] = {0, 1} "Rescaled range [y_min, y_max] given as a list (default = {0,1})";
  output Real y[size(x, 1)] "Rescaled value to run from y_min to y_max over the range min to max";
algorithm
  y := y_range[1] .+ (x .- x_range[1]) .* (y_range[2] - y_range[1]) / (x_range[2] - x_range[1])
  ;
end rescaleVector;

within BusinessSimulation.Functions;

function shiftList "Shift a list n steps, report carry, and fill gaps"
  extends BusinessSimulation.Icons.Function;
  input Real[:] list "List of values to be shifted";
  input Integer n "Number of steps to shift the list( n < 0 => shift to the left)";
  input Real fill = 0 "Value to fill the gaps with (default = 0)";
  output Real[size(list, 1)] shiftedList "Shifted list";
  output Real carry "Sum of elements that were pushed out of range by the shift";
protected
  Integer length = size(list, 1) "Length of the list of values";
  Integer nAbs = min(abs(n), length) "Absolute value of n, clipped to never be larger than length";
algorithm
  if n == 0 then
    // do nothing really
    carry := 0.;
    shiftedList := list;
  elseif n < 0 then
    // shift left
    carry := sum(list[1:nAbs]);
    shiftedList := if nAbs < length then cat(1, list[nAbs + 1:end], zeros(nAbs)) else zeros(nAbs);
  else
    // n > 0
    // shift right
    carry := sum(list[end - nAbs + 1:end]);
    shiftedList := if nAbs < length then cat(1, zeros(nAbs), list[1:end - nAbs]) else zeros(nAbs);
  end if
  ;
end shiftList;

within BusinessSimulation.Functions;

function sigmf "Sigmoidal membership function"
  extends BusinessSimulation.Icons.Function;
  input Real x "Input value for which the degree of membership is to be computed";
  input Real a "Shape parameter controlling the width of s-shaped transition area (higher values → steeper transition)";
  input Real c "Center of the s-shaped transition area";
  output Real y "Degree of membership";
algorithm
  y := 1 / (1 + exp(-a * (x - c)))
  ;
end sigmf;

within BusinessSimulation.Functions;

function smf "S-shaped membership function"
  extends BusinessSimulation.Icons.Function;
  input Real x "Input value for which the degree of membership is to be computed";
  input Real a "Foot of the function (i.e., f(a) = 0)";
  input Real b "Shoulder of the function (i.e., f(b) = 1)";
  output Real y "Degree of membership";
protected
  Real midpoint = (a + b) / 2;
algorithm
  y := if x <= a then 0 elseif a < x and x <= midpoint then 2 * ((x - a) / (b - a)) ^ 2
   elseif midpoint < x and x <= b then 1 - 2 * ((x - b) / (b - a)) ^ 2 else 1
  ;
end smf;

within BusinessSimulation.Functions;

function stringToTimeBase "Find the corresponding element of the TimeBases enumeration for a given time base string"
  extends BusinessSimulation.Icons.Function;
  import BusinessSimulation.Types.TimeBases;
  import Modelica.Utilities.Strings.isEqual;
  input String timeBaseString "String for a time base given in lower case";
  output TimeBases timeBase "Element in the enumeration corresponding to the string given";
protected
  Boolean ignoreCase = false "= true, to set caseSensitive flag to true";
algorithm
  timeBase := if isEqual(timeBaseString, "minute", ignoreCase) or isEqual(timeBaseString, "min", ignoreCase) then TimeBases.minutes else if isEqual(timeBaseString, "hour", ignoreCase) or isEqual(timeBaseString, "hours", ignoreCase) or isEqual(timeBaseString, "h", ignoreCase) then TimeBases.hours else if isEqual(timeBaseString, "day", ignoreCase) or isEqual(timeBaseString, "days", ignoreCase) or isEqual(timeBaseString, "d", ignoreCase) then TimeBases.days else if isEqual(timeBaseString, "week", ignoreCase) or isEqual(timeBaseString, "weeks", ignoreCase) or isEqual(timeBaseString, "wk", ignoreCase) then TimeBases.weeks else if isEqual(timeBaseString, "month", ignoreCase) or isEqual(timeBaseString, "months", ignoreCase) or isEqual(timeBaseString, "mo", ignoreCase) then TimeBases.months else if isEqual(timeBaseString, "quarter", ignoreCase) or isEqual(timeBaseString, "quarters", ignoreCase) or isEqual(timeBaseString, "qtr", ignoreCase) then TimeBases.quarters else if isEqual(timeBaseString, "year", ignoreCase) or isEqual(timeBaseString, "years", ignoreCase) or isEqual(timeBaseString, "yrCal", ignoreCase) or isEqual(timeBaseString, "y", ignoreCase) then TimeBases.years else TimeBases.seconds
  ;
end stringToTimeBase;

within BusinessSimulation.Functions;

function trapmf "Trapezoidal membership function"
  extends BusinessSimulation.Icons.Function;
  input Real x "Input value for which the degree of membership is to be computed";
  input Real a "Lower bound for the support (i.e., f(a) = 0)";
  input Real b "Lower bound for the core (i.e., f(b) = 1)";
  input Real c "Upper bound for the core (i.e., f(c) = 1)";
  input Real d "Upper bound for the support(i.e., f(d) = 0)";
  output Real y "Degree of membership";
algorithm
  y := max(min(1, min((x - a) / (b - a), (d - x) / (d - c))), 0)
  ;
end trapmf;

within BusinessSimulation.Functions;

function trimf "Triangular membership function"
  extends BusinessSimulation.Icons.Function;
  input Real x "Input value for which the degree of membership is to be computed";
  input Real a "Lower bound (i.e., f(a) = 0)";
  input Real b "Peak (i.e., f(b) = 1)";
  input Real c "Upper bound (i.e., f(c) = 0)";
  output Real y "Degree of membership";
algorithm
  y := max(min((x - a) / (b - a), (c - x) / (c - b)), 0)
  ;
end trimf;

