block ConstantInputRate "Input signal with constant rate information"
  import BusinessSimulation.Units.*;
  import BusinessSimulation.Types.TimeBases;
  extends Icons.Converter;
  extends Icons.InformationSourceIndicator;
  extends Interfaces.Basics.OutputTypeChoice_Rate;
  replaceable type ValueType = Unspecified constrainedby Unspecified "Basic type for the quantity that is transported per unit of time" ;
  RealOutput y "Constant output signal" ;
  parameter ValueType value "Constant rate given in unit and displayUnit pertaining to ValueType per time base";
  constant String timeBaseString = "second" "Time base of the rate entered (default = second)" ;
protected
  constant ValueType unitValue = 1 "Multiplicative identity with the same units as ValueType";
  constant Real unitBaseRate(unit = rateUnitInput) = 1;
  constant String rateUnitInput = BusinessSimulation.Constants.timeBaseRateUnits[timeBase] "Dimensionless rate units according to the time base entered" ;
  constant TimeBases timeBase = Functions.stringToTimeBase(timeBaseString) "Element of the enumeration TimeBases corresponding to the timeBase given as string" ;
  Converters.ConstantConverter rateInTimeBase(value = value / unitValue * unitBaseRate) ;
  Converters.RateConversion convertRate(timeBaseA = timeBase, timeBaseB = TimeBases.seconds) "Convert the rate input to a rate per seconds" ;
equation
  y = convertRate.y * unitValue;
  connect(rateInTimeBase.y, convertRate.u) 
  ;
end ConstantInputRate;

