block ExogenousData "Reading external data from a file using Modelica's CombiTimeTable format (MCTT)"
  import BusinessSimulation.Units.*;
  import BusinessSimulation.Constants.*;
  import Modelica.Blocks.Types.{Smoothness, Extrapolation, TimeEvents};
  extends Interfaces.Basics.BaseConverter;
  extends Icons.InformationSourceIndicator;
  RealOutput y if combiTimeTable.nout == 1 "Single Output" ;
  RealMultiOutput[combiTimeTable.nout] y_nout if combiTimeTable.nout > 1 "Output vector" ;
  // RealMultiOutput y_nout[combiTimeTable.nout] if combiTimeTable.nout > 1 "Output vector" ;
  parameter Boolean tableOnFile = true "= true, if table is defined on file or in function usertab (combiTimeTable.tableOnFile)" ;
  parameter Real table[:, :] = fill(0.0, 2, 2) "Table matrix (time = first column; e.g., table=[0, 0; 1, 1; 2, 4]) (combiTimeTable.table)" ;
  parameter String tableName = "NoName" "Table name on file or in function usertab (see docu) (combiTimeTable.tableName)" ;
  parameter String fileNameURI = modelSettings.exogenousDataFileURI "URI for the exogenous data file" ;
  parameter Boolean verboseRead = true "= true, if info message that file is loading is to be printed (combiTimeTable.verboseRead)" ;
  parameter Integer columns[:] = 2:size(table, 2) "Columns of table to be interpolated (combiTimeTable.columns)" ;
  parameter Smoothness smoothness = Smoothness.LinearSegments "Smoothness of table interpolation (combiTimeTable.smoothness)" ;
  parameter Extrapolation extrapolation = Extrapolation.LastTwoPoints "Extrapolation of data outside the definition range (combiTimeTable.extrapolation)" ;
  parameter Time timeScale(min = eps) = 1 "Time scale of first table column (combiTimeTable.timeScale)" ;
  parameter Real offset[:] = {0} "Offsets of output signals (combiTimeTable.offset)" ;
  parameter Time startTime = 0 "Output = offset for time < startTime (combiTimeTable.startTime)" ;
  parameter Time shiftTime = startTime "Shift time of first table column (combiTimeTable.shiftTime)" ;
  parameter TimeEvents timeEvents = TimeEvents.Always "Time event handling of table interpolation (combiTimeTable.timeEvents)" ;
  parameter Boolean verboseExtrapolation = false "= true, if warning messages are to be printed if time is outside the table definition range (combiTimeTable.verboseExtrapolation)" ;
  outer ModelSettings modelSettings;
protected
  parameter String fileName = if tableOnFile then Modelica.Utilities.Files.loadResource(fileNameURI) else "NoName" ;
  Modelica.Blocks.Sources.CombiTimeTable combiTimeTable(tableOnFile = tableOnFile, table = table, tableName = tableName, fileName = fileName, verboseRead = verboseRead, columns = columns, smoothness = smoothness, extrapolation = extrapolation, timeScale = timeScale, offset = offset, startTime = startTime, shiftTime = shiftTime, timeEvents = timeEvents, verboseExtrapolation = verboseExtrapolation) ;
equation
  connect(combiTimeTable.y[1], y) ;
  connect(combiTimeTable.y, y_nout) 
  ;
end ExogenousData;

