  parameter InputType coefficient = 1 "Constant coefficient";
  parameter Boolean hasFactor = false "= true, if coefficient is to be multiplied with input u" ;
protected
  ConstantConverter parCoefficient(value = coefficient) "Constant coefficient (optional)" ;
  Product_2 actualCoefficient ;
  RealInput one = 1.0 if not hasFactor "Default factor" ;
  AbsoluteSensor absoluteSensor1 ;
equation
  connect(stockInfoInput, absoluteSensor1.u_stockInfo) ;
  connect(parCoefficient.y, actualCoefficient.u2) ;
