partial model Delay "Partial model of a delay for CLD+ modeling"
  Connectors.StockPort portA ;
  Connectors.FlowPort portB ;
  Connectors.RealInput u if hasFactor "Factor input" ;
  Connectors.StockInfoOutput stockInfoOutput if hasStockInfoOutput ;
  parameter Time delayTime = 1 "Time of delay";
  parameter Boolean subtractDelayedOutflow = true "= true, if a delayed outflow is to be deducted before it actually leaves the stock" ;
  parameter Boolean hasFactor = false "= true, if coefficients are to be multiplied with input u" ;
  parameter Boolean hasStockInfoOutput = false "= true, if information from the internal 'in process' stock is to be made accessible" ;
  parameter MaterialType IDI = 0 "Initial material in the process of flowing into the connected stock" ;
  parameter MaterialType IDO = 0 "Initial material in the process of flowing into the connected stock" ;
  replaceable type MaterialType = Unspecified constrainedby Unspecified "Type choice for material flowing in and out of the connected stock" ;
protected
  parameter Real k2 = if subtractDelayedOutflow then -1 else 0 "Gain of outflowing elements of stock B being delayed" ;
  Sensors.FlowPortSensor stockB ;
  Converters.Product_2 adjustedDelayTime ;
  Connectors.RealOutput one = 1.0 if not hasFactor "Default factor" ;
  Converters.ConstantConverterTime parDelayTime(value = delayTime) ;
  Connectors.RealOutput growthRate "Indicated rate of growth" ;
  Connectors.RealOutput declineRate "Indicated rate of decline" ;
  Modelica.Blocks.Math.Add actualStockB(k2 = k2) ;
equation
  // set stock port variables
  portA.stopInflow = portB.stopInflow;
  portA.stopOutflow = portB.stopOutflow;
  portA.stock = actualStockB.y;
  // set rate inputs
  growthRate = if portA.rate >= 0 then abs(portA.rate) else 0;
  declineRate = if growthRate > 0 then 0 else abs(portA.rate);
  // connect equations
  connect(one, adjustedDelayTime.u1) ;
  connect(u, adjustedDelayTime.u1) ;
  connect(parDelayTime.y, adjustedDelayTime.u2) ;
  connect(stockB.flowPort, portB) ;
  connect(actualStockB.u1, stockB.stock) 
  ;
end Delay;

