encapsulated partial block SISO_Conversion "Partial SISO converter class with input and output conversions for lookup functions"
  import BusinessSimulation.Interfaces.Connectors;
  import Modelica.Utilities.Files.loadResource;
  import BusinessSimulation.Converters.{RateConversion, PassThrough, TimeConversion};
  import BusinessSimulation.Types.TimeBases;
  import BusinessSimulation.ModelSettings;
  import BusinessSimulation.Interfaces.PartialConverters.SISO;
  import BusinessSimulation.Units.*;
  extends SISO;
  replaceable type InputType = Unspecified "The type of the input" ;
  parameter Boolean convertInput = false "= true, if the input value is a rate or time variable that needs to be converted" ;
  parameter Boolean inputIsRate = false "= true, if the input is given in units of time, otherwise it is assumed to be a rate" ;
  parameter Boolean convertOutput = false "= true, if the output value is a rate or time variable that needs to be converted" ;
  parameter Boolean outputIsRate = false "= true, if the output is given in units of time, otherwise it is assumed to be a rate" ;
  constant TimeBases timeBaseInput = TimeBases.seconds "TimeBase to convert from (default = seconds)" ;
  constant TimeBases timeBaseTableIn = modelSettings.modelDisplayTimeBase "TimeBase used for the lookup function input (default = modelDisplayTimeBase)" ;
  constant TimeBases timeBaseTableOut = modelSettings.modelDisplayTimeBase "TimeBase assumed for the lookup function output (default = modelSettings.modelDisplayTimeBase)" ;
  constant TimeBases timeBaseOutput = TimeBases.seconds "TimeBase used for the output (default = seconds)" ;
  outer ModelSettings modelSettings;
protected
  RateConversion rateConversionIn(timeBaseA = timeBaseInput, timeBaseB = timeBaseTableIn) if convertInput and inputIsRate "Convert the input (rate) to another time base" ;
  PassThrough noConversionIn if not convertInput "Use input as is" ;
  TimeConversion timeConversionIn(timeBaseA = timeBaseInput, timeBaseB = timeBaseTableIn) if convertInput and not inputIsRate "Convert the input to another time base" ;
  PassThrough noConversionOut if not convertOutput "Use output as is" ;
  RateConversion rateConversionOut(timeBaseA = timeBaseTableOut, timeBaseB = timeBaseOutput) if convertOutput and outputIsRate "Convert the output (rate) to 1/s" ;
  TimeConversion timeConversionOut(timeBaseA = timeBaseTableOut, timeBaseB = timeBaseOutput) if convertOutput and not outputIsRate "Convert the output to seconds" ;
  Connectors.RealOutput u_c "Input after conversion" ;
  Connectors.RealOutput y_c "Output before conversion" ;
equation
  connect(u, noConversionIn.u) ;
  connect(u, rateConversionIn.u) ;
  connect(u, timeConversionIn.u) ;
  connect(noConversionOut.y, y) ;
  connect(timeConversionOut.y, y) ;
  connect(rateConversionOut.y, y) ;
  connect(rateConversionIn.y, u_c) ;
  connect(noConversionIn.y, u_c) ;
  connect(timeConversionIn.y, u_c) ;
  connect(y_c, noConversionOut.u) ;
  connect(y_c, rateConversionOut.u) ;
  connect(y_c, timeConversionOut.u) 
  ;
end SISO_Conversion;

