partial model BidirectionalFlow "Generic bi-directional flow between two stocks"
  extends Basics.GenericFlow;
  extends Icons.BidirectionalFlow;
  extends Basics.ThreeSO_rate;
protected
  // indicated rates; positive rates will drain the conected stock
  Real A_rate "Indicated rate for portA";
  Real B_rate "Indicated rate for portB";
  Boolean useA_rate "= true, if indicated rate for portA meets restrictions";
  Boolean useB_rate "= true, if indicated rate for portB meets restrictions";
initial equation
  // make sure that discrete vars are properly initialized
  pre(useA_rate) = Functions.constrainedRateBoolean(A_rate < 0, portA.stopInflow, portA.stopOutflow);
  pre(useB_rate) = Functions.constrainedRateBoolean(B_rate < 0, portB.stopInflow, portB.stopOutflow);
equation
  // set indicated rates according to flow rules
  A_rate = -B_rate;
  // make sure that stock constraints are met
  useA_rate = Functions.constrainedRateBoolean(A_rate < 0, portA.stopInflow, portA.stopOutflow);
  useB_rate = Functions.constrainedRateBoolean(B_rate < 0, portB.stopInflow, portB.stopOutflow);
  // set flow to zero if constraints are not met
  portA.rate = if useA_rate and useB_rate then A_rate else 0;
  portB.rate = -portA.rate;
  // report the actual rate of flow at Port A
  y = portA.rate;
  y1 = portA.rate;
  y2 = portA.rate
  ;
end BidirectionalFlow;

within BusinessSimulation.Interfaces.PartialFlows;

partial model Interaction "Describes two separate flows to or from sinks or sources"
  extends Basics.GenericFlow;
  extends Basics.Interaction4SO;
  extends Icons.Interaction;
protected
  // positive rates will fill the conected stock (think of the rates as A's and B's inflow!)
  // indicated rates (may be overriden by stock restrictions)
  Real A_rate "Indicated rate for portA";
  Real B_rate "Indicated rate for portB";
  // acutal rates
  Real setA_rate "Rate to be used for portA meeting the constraints imposed by the stock";
  Real setB_rate "Rate to be used for portB meeting the constraints imposed by the stock";
equation
  // Children of this class need to procvide eplicit equations for A_rate and B_rate
  // make sure that stock constraints are met
  // positive values for A_rate and/or B_rate mean, that the connected stock will be filled
  setA_rate = Functions.constrainedRate(-A_rate, portA.stopInflow, portA.stopOutflow);
  setB_rate = Functions.constrainedRate(-B_rate, portB.stopInflow, portB.stopOutflow);
  // set flow to zero if constraints are not met
  portA.rate = setA_rate;
  portB.rate = setB_rate;
  // report the rate of flow at Port A
  y_A = -portA.rate;
  y1_A = -portA.rate;
  y_B = -portB.rate;
  y1_B = -portB.rate
  ;
end Interaction;

