partial model Sink "Outflow to a stock with infinity capacity"
  extends Basics.GenericSourceOrSink;
  extends Icons.Sink;
protected
  // a positive rate should drain the stock (which here matches Modelica's rule for flows)
  OutputType rate(min = 0);
equation
  // observe stock signals and constraints
  assert(rate >= 0, "Rate must be positive and will be set to zero", level = AssertionLevel.warning);
  massPort.rate = Functions.constrainedRate(max(rate, 0), massPort.stopInflow, massPort.stopOutflow);
  // report current rate of flow via output connectors
  // so that it may be used directly as exogenous rate by another sink element (e.g., positive rate!)
  y = massPort.rate;
  y1 = massPort.rate;
  y2 = massPort.rate
  ;
end Sink;

within BusinessSimulation.Interfaces.PartialSourcesOrSinks;

partial model Source "Inflow from a stock with infinite capacity"
  extends Basics.GenericSourceOrSink;
  extends Icons.Source;
protected
  // a positive rate will fill the stock - the elements rate should thus be negative following Modelica's rule for rates
  OutputType rate(min = 0);
equation
  assert(rate >= 0, "Rate must be positive", level = AssertionLevel.warning);
  // switch signs for setting the rate in accordance with Modelica's rule for rates
  // observe stock signals and constraints
  massPort.rate = Functions.constrainedRate(-max(rate, 0), massPort.stopInflow, massPort.stopOutflow);
  // report current rate of flow via output connectors
  // so that it may be used directly as exogenous rate by another source element (e.g., positive rate)
  y = -massPort.rate;
  y1 = -massPort.rate;
  y2 = -massPort.rate
  ;
end Source;

within BusinessSimulation.Interfaces.PartialSourcesOrSinks;

partial model SourceOrSink "Source or sink with regard to a connected stock"
  extends Basics.GenericSourceOrSink;
  extends Icons.SourceOrSink;
protected
  // positive rate should fill the connected stock stock; negative rate should drain it
  OutputType rate;
equation
  // switch signs in accordance with Modelica's rule for rates
  // observe constraining signals from stock
  massPort.rate = Functions.constrainedRate(-rate, massPort.stopInflow, massPort.stopOutflow);
  // report current rate of flow via output connectors so that it can be used as exogenous input for another source or sink (e.g., switch signs!)
  y = -massPort.rate;
  y1 = -massPort.rate;
  y2 = -massPort.rate
  ;
end SourceOrSink;

within BusinessSimulation.Interfaces.PartialStocks;

partial model BasicStock "Unrestricted reservoir to store information"
  import BusinessSimulation.Types.InitializationOptions;
  extends Icons.Stock;
  extends Interfaces.Basics.GenericStock(hasStockInfoOutput = false, y.start = initialValue, init = modelSettings.init);
  parameter OutputType initialValue(min = minValue, max = maxValue) = 0 "Initial level (should be different from 0 to find non-trivial steady state solution)";
  parameter OutputType maxValue = inf "Maximum admissable value";
  parameter OutputType minValue = -inf "Minimum admissable value";
  parameter Boolean useAssert = false "= true, if  leaving the admissable range is to cause an error or warning" ;
  parameter Boolean causeError = true "= true, if leaving the admissable range is to cause an error instead of simply a warning" ;
  outer ModelSettings modelSettings;
protected
  Sensors.StockInfo stockInfoSensor if hasStockInfoOutput ;
  OutputType x(start = initialValue, min = minValue, max = maxValue) "State variable" ;
  Converters.Special.RangeAssert rangeControl(maxValue = maxValue, minValue = minValue, causeError = causeError) if useAssert "Use assert() to check admissable values" ;
initial equation
  // initialize the stock by finding a valid initial value, by using a given initialValue, or by trying to find a steady state solution
  if init == InitializationOptions.FixedValue then
    x = initialValue;
  elseif init == InitializationOptions.SteadyState then
    der(x) = 0;
  end if;
equation
  // rate of change for the stock
  der(x) = inflow.rate + outflow.rate;
  // ports shall have level information for stock
  inflow.stock = x;
  outflow.stock = x;
  // children of this class need to set the boolean flags for inflow and outflow ports:
  //   inflow.stopInflow = true | false;
  //   outflow.stopInflow = true | false;
  //   inflow.stopOutflow = true | false;
  //   outflow.stopOutflow = ture | false;
  // report current value of stock via output connectors
  y = inflow.stock;
  y1 = inflow.stock;
  y2 = inflow.stock;
  connect(inflow, stockInfoSensor.inPort) ;
  connect(stockInfoSensor.outPort, outflow) ;
  connect(y, stockInfoSensor.levelInfo) ;
  connect(stockInfoSensor.y_stockInfo, y_stockInfo) ;
  // issue warnings if values out of range
  connect(y, rangeControl.u) 
  ;
end BasicStock;

