encapsulated partial model BaseSubsystem "Partial subsystem with flexible number of connectors"
  import BusinessSimulation.Icons.{SubsystemBlock, SubsystemIncubator, SubsystemTransceiver, SubsystemActuator};
  import BusinessSimulation.Interfaces.Connectors.{DataBus, RealInput, RealMultiInput, RealOutput, RealMultiOutput, FlowMultiPort, FlowPort, StockPort, StockMultiPort, StockInfoMultiInput, StockInfoInput, StockInfoMultiOutput, StockInfoOutput};
  constant Integer nin(min = 0) = 0 "Number of input connectors" ;
  constant Integer nout(min = 0) = 0 "Number of output connectors" ;
  constant Integer n_stockPorts(min = 0) = 0 "Number of stock port connectors" ;
  constant Integer n_flowPorts(min = 0) = 0 "Number of flow port connectors" ;
  constant Integer n_stockInfoInputs(min = 0) = 0 "Number of stockInfo input connectors" ;
  constant Integer n_stockInfoOutputs(min = 0) = 0 "Number of stockInfo output connectors" ;
  constant Boolean hasDataBus = true "= true, if the system is to have an expandable connector" ;
  constant Boolean hasMultiInput = false "= true, if the system has an array of input connectors" ;
  constant Boolean hasMultiOutput = false "= true, if the system has an array of output connectors" ;
  constant Boolean hasMultiStockPort = false "= true, if the system has an array of stock ports" ;
  constant Boolean hasMultiFlowPort = false "= true, if the system has an array of flow ports" ;
  constant Boolean hasMultiStockInfoInput = false "= true, if the system has an array of stock info input connectors" ;
  constant Boolean hasMultiStockInfoOutput = false "= true, if the system has an array of stock info output connectors" ;
  FlowMultiPort flowPorts[n_flowPorts] if hasMultiFlowPort and n_flowPorts > 0 "Flow port connectors" ;
  FlowPort flowPort if not hasMultiFlowPort and n_flowPorts > 0 and n_flowPorts < 2 "Flow port connector" ;
  StockMultiPort stockPorts[n_stockPorts] if hasMultiStockPort and n_stockPorts > 0 "Stock port connectors" ;
  StockPort stockPort if not hasMultiStockPort and n_stockPorts > 0 and n_stockPorts < 2 "Stock port connector" ;
