block EffectOfFatigue "Modeling the influence of excessive workloads on productivity or quality"
  import BusinessSimulation.Units.*;
  import BusinessSimulation.Constants.*;
  import BusinessSimulation.Types.InitializationOptions;
  extends Icons.SubsystemBlock;
  Interfaces.Connectors.RealInput u "Input of workload" ;
  Interfaces.Connectors.RealInput u_ref if not hasConstantReference "Input for the reference workload (optional)" ;
  Interfaces.Connectors.RealOutput y "Effect on Productivity given as a multiplier" ;
  parameter Time timeToGetFatigued(min = 0) "Time constant for the exponential smooth of overtime in periods";
  parameter Rate referenceWorkload(min = 0.1) = 1 "Constant reference workload (optinal)" ;
  parameter Integer delayOrder(min = 1) = 1 "Delay order of the smooth for workload" ;
  parameter Real effectMax(min = 1) = 1.1 "The upper bound for the effect of less work than normal on PDY (MAX >= 1)";
  parameter Real effectMin(min = 0, max = 1) = 0 "The lower bound for the effect of fatigue on PDY (MIN >= 0)";
  parameter Real steepness(min = 0) = 10 "High values indicate a steep gradient for the lookup curve (JanoschoekNegative.growthRate)";
  parameter Boolean hasConstantReference = true "= true, if the reference workload is given by a constant parameter" ;
  parameter Boolean clipEffect = false "= true, if the maximum effect is to be 1.0" ;
  parameter Real initialFatigue = 1 "Initial Output (fatigue.initialValue)" ;
  parameter InitializationOptions init = modelSettings.init "Provide InitializationOptions (Free, FixedValue, SteadyState)" ;
  parameter Boolean strict = true "= true, if strict limits with noEvent(..) (clippedEffect.strict)" ;
  outer ModelSettings modelSettings;
protected
  Converters.DmnlInput normalizedWorkload(hasConstantReference = false) "Workload divided by the normal workload" ;
  Converters.ConstantConverter parRef(value = referenceWorkload, redeclare replaceable type OutputType = Rate) if hasConstantReference "Constant reference value for the workload (optional)" ;
  Converters.Lookup.JanoschekNegative effectOnOutcome(lowerBound = effectMin, upperBound = effectMax, growthRate = steepness) "The multiplicative effect of fatigue on productivity or quality" ;
  Converters.DiscreteDelay.SmoothN fatigue(initialValue = initialFatigue, delayTime = timeToGetFatigued, n = delayOrder, hasConstantDelayTime = true) "Fatigue is an n-th order smooth of overtime" ;
  Converters.Clip clippedEffect(minValue = -inf, maxValue = 1, redeclare replaceable type OutputType = Dimensionless, hasConstantLimits = true, strict = strict) if clipEffect "Clip Effect to only allow values within the closed unit interval" ;
  Converters.PassThrough unchangedEffect if not clipEffect "Leave the effect unchanged" ;
equation
  assert(effectMin < effectMax, "The lower bound for the effect must be smaller than the upper bound", level = AssertionLevel.warning);
  assert(effectMax > 1, "The upper bound for the lookup must be above 1—use clipEffect to constrict the effect", level = AssertionLevel.warning);
  assert(steepness > 0, "Steepness should by greater than zero", level = AssertionLevel.warning);
  connect(fatigue.y, effectOnOutcome.u) ;
  connect(normalizedWorkload.y, fatigue.u) ;
  connect(u, normalizedWorkload.u) ;
  connect(parRef.y, normalizedWorkload.u_reference) ;
  connect(u_ref, normalizedWorkload.u_reference) ;
  connect(effectOnOutcome.y, unchangedEffect.u) ;
  connect(unchangedEffect.y, y) ;
  connect(effectOnOutcome.y, clippedEffect.u) ;
  connect(clippedEffect.y, y) 
  ;
end EffectOfFatigue;

