block ExperienceCurve "Unit cost degression due to gaining experience"
  import BusinessSimulation.Units.*;
  import BusinessSimulation.Interfaces.Basics.OutputTypeChoice;
  extends OutputTypeChoice;
  extends Icons.SubsystemBlock;
  Interfaces.Connectors.RealInput u "Input of output the cumulation of which triggeres learning" ;
  Interfaces.Connectors.RealOutput y "Costs, productivity, defects etc. being affected by experience" ;
  parameter OutputType initialCost = 1 "Inial value of cost, time, defects etc. being affected by experience";
  parameter Dimensionless learningRate(min = -1, max = 1) = 0.2 "Learning rate (LR) stating the relative reduction for each doubling of cumulated production";
  parameter OutputType costLimit(min = 0) = 0 "Minimum or maximum cost level (depending on sign of learning rate), which is not to be exceeded" ;
  parameter Boolean hasCumulatedInput = false "= true, if input u is cumulated production value; false, if u is the current production value" ;
  parameter Boolean hasLimit = false "= true, if output y will not be below the given limit or exceed it" ;
  outer ModelSettings modelSettings;
protected
  parameter Real initialProduction(fixed = false) "Value to be used for initialization of the implicit stock" ;
  parameter Real valReferenceProduction = if hasCumulatedInput == true and initialProduction >= 1 then initialProduction else 1 "Initialize reference production" ;
  parameter Real b = if learningRate < 1 then log(1 - learningRate) / log(2) else 0 "Exponent for experience effect calculation" ;
  Stocks.InformationLevel cumulatedProduction(init = BusinessSimulation.Types.InitializationOptions.FixedValue, initialValue = 1) if not hasCumulatedInput "Accumulated output driving learning" ;
  SourcesOrSinks.Growth producing if not hasCumulatedInput "Output generation" ;
  Converters.Division normalizedOuput ;
  Converters.ConstantConverter referenceProduction(value = valReferenceProduction) "Reference level of output" ;
  Converters.Power effectLearning(hasConstantExponent = false) "Total effect of experience" ;
  Converters.Max cumulatedOutput if hasCumulatedInput "Cumulated output driving learning if input  is already cumulated value" ;
  Converters.ConstantConverter log2ProgressRatio(value = b) "Binary logarithm of progress ratio" ;
  Converters.Product_2 actualCosts "Actual level for influenced variable" ;
  Converters.ConstantConverter referenceCost(value = initialCost) "Initial level of influenced variable" ;
  Converters.ConstantConverter minCumProd(value = 1) if hasCumulatedInput "Minimum cumulated production" ;
  Converters.PassThrough unchanged if not hasLimit ;
  Converters.Clip ceiling(maxValue = costLimit, minValue = 0, hasConstantLimits = true) if hasLimit and learningRate < 0 "Do not exceed maximum value" ;
  Converters.Clip floor(minValue = costLimit, hasConstantLimits = true) if hasLimit and learningRate >= 0 "Do not go below minimum value" ;
initial equation
  initialProduction = u "Initialize  reference production to initial input";
equation
  connect(producing.massPort, cumulatedProduction.inflow) ;
  connect(u, producing.u) ;
  connect(cumulatedOutput.y, normalizedOuput.u1) ;
  connect(referenceProduction.y, normalizedOuput.u2) ;
  connect(cumulatedProduction.y1, normalizedOuput.u1) ;
  connect(log2ProgressRatio.y, effectLearning.u_exponent) ;
  connect(normalizedOuput.y, effectLearning.u) ;
  connect(effectLearning.y, actualCosts.u2) ;
  connect(referenceCost.y, actualCosts.u1) ;
  connect(u, cumulatedOutput.u1) ;
  connect(minCumProd.y, cumulatedOutput.u2) ;
  connect(actualCosts.y, unchanged.u) ;
  connect(unchanged.y, y) ;
  connect(actualCosts.y, ceiling.u) ;
  connect(ceiling.y, y) ;
  connect(actualCosts.y, floor.u) ;
  connect(floor.y, y) 
  ;
end ExperienceCurve;

