model Account "Basic model of an account with optional interest"
  import BusinessSimulation.Types.InitializationOptions;
  import BusinessSimulation.Units.*;
  import BusinessSimulation.Constants.*;
  extends Icons.SubsystemIncubator;
  extends Interfaces.Basics.OutputTypeChoice;
  Interfaces.Connectors.StockPort inflow "Increasing the balance of the account" ;
  Interfaces.Connectors.StockPort outflow "Decreasing the balance of the account" ;
  Interfaces.Connectors.RealInput u_plus if hasRateInputs "Rate of inflow increasing the account (or net rate of flow)" ;
  Interfaces.Connectors.RealInput u_minus if not hasNetRateInput and hasRateInputs "Rate of outflow decreasing the account" ;
  Interfaces.Connectors.RealInput u_interestPlus if withInterest and not hasConstantInterest "Fractional interest rate for positive balances (optional)" ;
  Interfaces.Connectors.RealInput u_interestMinus if withInterest and not hasConstantInterest "Fractional interest rate for negative balances (optional)" ;
  RealOutput y_intEarned if withInterest "Interest earned (optional)" ;
  RealOutput y_intPaid if withInterest "Interest paid (optional)" ;
  RealOutput y "Balance of the account (e.g., amount in the stock)" ;
  parameter OutputType initialBalance = 0 "Initial balance of the account";
  parameter Rate interestRatePlus = unspecified "Constant fractional interest rate for positive balances (optional)" ;
  parameter Rate interestRateMinus = unspecified "Constant fractional interest rate for negative balances (optional)" ;
  parameter Boolean hasRateInputs = true "= true, if input connectors should allow giving transaction rates increasing/decreasing the balance of the account" ;
  parameter Boolean hasNetRateInput = false "= true, if the rate of flow is given a net rate (u_plus only)" ;
  parameter Boolean withInterest = false "= true, if positive and negative balances lead to interest earned or paid" ;
  parameter Boolean hasConstantInterest = true "= true, if the optional interest rates are given as constant parameters" ;
  parameter InitializationOptions init = modelSettings.init "Provide InitializationOptions (Free, FixedValue, SteadyState) (accountBalance.init)" ;
  parameter Boolean strict = true "= true, if strict limits with noEvent(..) (positiveBalance.strict)" ;
  outer ModelSettings modelSettings;
protected
  Stocks.InformationLevel accountBalance(hasStockInfoOutput = false, useAssert = false, causeError = false, initialValue = initialBalance, init = init) "Balance of the account" ;
  SourcesOrSinks.ExogenousChange netFlow if hasRateInputs "Net flow to or from the account" ;
  Converters.Gain negativeRate(c = -1) if not hasNetRateInput and hasRateInputs "The rate of decrease is turned into a negative rate" ;
  Converters.Add_2 netRate(redeclare replaceable type OutputType = Unspecified) if not hasNetRateInput and hasRateInputs "Net rate of flow" ;
  Converters.PassThrough netRateInput if hasNetRateInput and hasRateInputs "Input u_plus net rate of flow" ;
  Converters.ConstantConverter interestPlus(value = interestRatePlus) if withInterest and hasConstantInterest "Constant rate of interest for positive balances" ;
  Converters.ConstantConverter interestMinus(value = interestRateMinus) if withInterest and hasConstantInterest "Constant rate of interest for negative balances" ;
  Converters.ZeroIfNegative positiveBalance(strict = strict) if withInterest "Positive balance or zero" ;
  Converters.ZeroIfNegative negativeBalance(strict = strict) if withInterest "Negative balance or zero" ;
  Converters.Gain invertedBalance(c = -1) if withInterest ;
  Converters.Product_2 rateDecline if withInterest "Rate of decline" ;
  SourcesOrSinks.Decline interestPaid if withInterest "Interest decreasing the balance" ;
  SourcesOrSinks.Growth interestEarned if withInterest "Interest payments increasing the balance" ;
  Converters.Product_2 rateIncrease if withInterest "Rate of decline" ;
  parameter Boolean interestRates_enabled = withInterest and hasConstantInterest "Switch for interestRatePlus parameter display" ;
equation
  // check that parameter inputs are explicitly given if needed
  assert(not interestRates_enabled or interestRatePlus < inf, "Parameter interestRatePlus needs to be specified");
  assert(not interestRates_enabled or interestRateMinus < inf, "Parameter interestRateMinus needs to be specified");
  connect(u_minus, negativeRate.u) ;
  connect(negativeRate.y, netRate.u2) ;
  connect(u_plus, netRate.u1) ;
  connect(u_plus, netRateInput.u) ;
  connect(netRateInput.y, netFlow.u) ;
  connect(netRate.y, netFlow.u) ;
  connect(netFlow.massPort, accountBalance.inflow) ;
  connect(accountBalance.y, y) ;
  connect(accountBalance.y2, positiveBalance.u) ;
  connect(accountBalance.y1, invertedBalance.u) ;
  connect(invertedBalance.y, negativeBalance.u) ;
  connect(interestPaid.massPort, accountBalance.outflow) ;
  connect(rateDecline.y, interestPaid.u) ;
  connect(negativeBalance.y, rateDecline.u1) ;
  connect(interestMinus.y, rateDecline.u2) ;
  connect(u_interestMinus, rateDecline.u2) ;
  connect(interestPlus.y, rateIncrease.u2) ;
  connect(positiveBalance.y, rateIncrease.u1) ;
  connect(u_interestPlus, rateIncrease.u2) ;
  connect(rateIncrease.y, interestEarned.u) ;
  connect(interestEarned.massPort, accountBalance.inflow) ;
  connect(accountBalance.outflow, outflow) ;
  connect(inflow, accountBalance.inflow) ;
  connect(interestPaid.y2, y_intPaid) ;
  connect(interestEarned.y1, y_intEarned) 
  ;
end Account;

