  Interfaces.Connectors.StockPort stockPort ;
  Interfaces.Connectors.RealMultiOutput[nin] y_flows(each quantity = "Rate", each unit = "1/s") "Output of netflows with regard to the multiple stock ports" ;
  parameter Integer nin(min = 1) = 2 "Number of stock ports to be joined in the collector" ;
  parameter OutputType initialValue = 0 "Initial level of stock";
  parameter OutputType maxValue = inf "Maximum admissable value (reservoir.maxValue)";
  parameter OutputType minValue = -inf "Minimum admissable value (reservoir.minValue)";
  parameter Boolean hasStockInfoOutput = false "= true, if a StockInfoOutput should be added to the stock (reservoir.hasStockInfoOutput)" ;
  parameter InitializationOptions init = modelSettings.init "Provide InitializationOptions (Free, FixedValue, SteadyState) (reservoir.init)" ;
  parameter Boolean useAssert = false "= true, if  leaving the admissable range is to cause an error or warning (reservoir.useAssert)" ;
  parameter Boolean causeError = true "= true, if leaving the admissable range is to cause an error instead of simply a warning (reservoir.causeError)" ;
  replaceable Stocks.InformationLevel collectingReservoir(initialValue = initialValue, hasStockInfoOutput = hasStockInfoOutput, init = init, useAssert = useAssert, causeError = causeError, maxValue = maxValue, minValue = minValue) constrainedby BusinessSimulation.Interfaces.PartialStocks.BasicStock "The joint collecting reservoir" ;
  outer ModelSettings modelSettings;
protected
  Sensors.StockPortSensor[nin] sensor ;
equation
  connect(collectingReservoir.outflow, stockPort) ;
  connect(collectingReservoir.y, y1) ;
  connect(collectingReservoir.y, y) ;
  connect(collectingReservoir.y1, y2) ;
  connect(collectingReservoir.y_stockInfo, y_stockInfo) ;
  connect(stockMultiPort, sensor.stockPort) ;
  connect(sensor.netFlow, y_flows) ;
  connect(sensor[1].flowPort, collectingReservoir.inflow) ;
  for i in 2:nin loop
    connect(sensor[i].flowPort, collectingReservoir.inflow);
  end for
  ;
end Collector;

