model AggregatePerformance "Aggregate the information received from a set of performance indicators"
  import BusinessSimulation.Units.*;
  import BusinessSimulation.Types.AggregateFunctions;
  extends Interfaces.PartialConverters.InformationProcessing_SO(redeclare replaceable type OutputType = Dimensionless);
  Interfaces.Connectors.RealMultiInput[nin] u "Vector of performance indicator inputs" ;
  Interfaces.Connectors.RealMultiInput[nin] u_weights if useWeights and not hasConstantWeights "Vector of weights (optional)" ;
  parameter Integer nin(min = 1) = 2 "Number of performance indicator inputs (length of input vector)" ;
  parameter AggregateFunctions func = BusinessSimulation.Types.AggregateFunctions.arithmeticMean "Function to apply for aggregation" ;
  parameter Real[:] weights = ones(nin) "Constant weights to be used for performance inputs" ;
  parameter Boolean useWeights = false "= true, if the output is to be a weighted arithmetic mean" ;
  parameter Boolean hasConstantWeights = true "= true, if the weights are constant" ;
protected
  Converters.Vector.ConstantConverter parWeights(value = weights) if hasConstantWeights and useWeights "Constant weights" ;
  Converters.Vector.ArithmeticMean arithAvgPerformance(useWeights = useWeights, hasConstantWeights = false, nin = nin, redeclare replaceable type OutputType = Dimensionless) if func == AggregateFunctions.arithmeticMean "(Weighted) arithmetic mean" ;
  Converters.Vector.GeometricMean geomAvgPerformance(nin = nin, useWeights = useWeights, hasConstantWeights = false, redeclare replaceable type OutputType = Dimensionless) if func == AggregateFunctions.geometricMean "(Weighted) geometric mean" ;
  Converters.Vector.Max maximumPerformance(nin = nin, redeclare replaceable type OutputType = Dimensionless) if func == AggregateFunctions.maximum "Maximum of the performance inputs" ;
  Converters.Vector.Min minimumPerformance(nin = nin, redeclare replaceable type OutputType = Dimensionless) if func == AggregateFunctions.minimum "Minimum of the performance inputs" ;
equation
  connect(parWeights.y, geomAvgPerformance.u_weights) ;
  connect(u_weights, geomAvgPerformance.u_weights) ;
  connect(u, arithAvgPerformance.u) ;
  connect(u, geomAvgPerformance.u) ;
  connect(u, maximumPerformance.u) ;
  connect(u, minimumPerformance.u) ;
  connect(geomAvgPerformance.y, y) ;
  connect(arithAvgPerformance.y, y) ;
  connect(maximumPerformance.y, y) ;
  connect(minimumPerformance.y, y) ;
  connect(parWeights.y, arithAvgPerformance.u_weights) ;
  connect(u_weights, arithAvgPerformance.u_weights) 
  ;
end AggregatePerformance;

