model BasicOrientation "Assessing a system's performance and sustainability according to basic orientors"
  import BusinessSimulation.Units.*;
  import BusinessSimulation.Types.{BasicOrientors, AggregateFunctions};
  extends Icons.InformationProcessing;
  Interfaces.Connectors.RealMultiInput u_weights[nPerf] if not hasConstantWeights "Weights to be used for performance measurement" ;
  Interfaces.Connectors.RealMultiInput u[BasicOrientors] "Basic orientors to monitor a system's sustainability" ;
  Interfaces.Connectors.RealInput u_psy if hasSentinentBeings "Psychological needs indicator (optional)" ;
  Interfaces.Connectors.RealOutput y_perf(final unit = "1") "Aggregate performance score for the monitored system" ;
  Interfaces.Connectors.RealOutput y_sus(final unit = "1") "Aggregate degree of sustainability for the monitored system" ;
  parameter Real[:] weights = ones(nPerf) "Weights for calculating a weighted average performance score (default = equal weights)" ;
  parameter Boolean hasSentinentBeings = false "= true, if the system comprises sentinent beings with psychological needs" ;
  parameter Boolean hasConstantWeights = true "= true, if constant weights are to be used for performance aggregation" ;
  parameter AggregateFunctions func = AggregateFunctions.arithmeticMean "Function to apply for aggregation (aggregatePerformance.func)";
protected
  constant Integer nOrientors = size(u, 1) "Number of basic orientors valid for any system";
  parameter Integer nPerf = if hasSentinentBeings then nOrientors + 1 else nOrientors "Number of orientors used for perfomance calculation" ;
  AggregatePerformance aggregatePerformance(useWeights = true, hasConstantWeights = false, nin = nPerf, func = func) ;
  Converters.PassThrough sustainabilityNonSentinent if not hasSentinentBeings "Sustainability score for systems without sentinent beings" ;
  Converters.Min sustainabilitySentinent if hasSentinentBeings "Sustainability score for systems with sentinent beings" ;
  Converters.Vector.ConstantConverter parWeights(redeclare final type OutputType = Dimensionless, final value = weights) if hasConstantWeights "Weights for performance score" ;
  Converters.Vector.Min basicSustainability(redeclare final type OutputType = Dimensionless, nin = nOrientors) "Sustainability score according to basic orientors" ;
equation
  connect(u, basicSustainability.u) ;
  connect(basicSustainability.y, sustainabilityNonSentinent.u) ;
  connect(sustainabilityNonSentinent.y, y_sus) ;
  connect(u_psy, sustainabilitySentinent.u1) ;
  connect(sustainabilitySentinent.y, y_sus) ;
  connect(basicSustainability.y, sustainabilitySentinent.u2) ;
  connect(u, aggregatePerformance.u[1:6]) ;
  connect(u_psy, aggregatePerformance.u[7]) ;
  connect(parWeights.y, aggregatePerformance.u_weights) ;
  connect(aggregatePerformance.y, y_perf) ;
  connect(u_weights, aggregatePerformance.u_weights) 
  ;
end BasicOrientation;

