block ResidenceTime "Calculate average time of residence or time needed for completion"
  import BusinessSimulation.Units.*;
  import BusinessSimulation.Constants.*;
  extends Icons.InformationProcessing;
  parameter Time durationAtZeroRate = inf "Value for duration if the rateOfDepletion becomes zero";
  Interfaces.Connectors.RealInput u_level "Current level of work to do or simply level of stock being depleted by flow" ;
  Interfaces.Connectors.RealInput u_rate "The rate at which the stock is drained or the tasks being completed" ;
  Interfaces.Connectors.RealOutput y(quantity = "Time", unit = "s") "Time needed to complete work or drain stock" ;
protected
  Converters.Division_Guarded residenceTime(outputIfZero = durationAtZeroRate, redeclare replaceable type OutputType = Time) "Average time of residence in a stock that is being depleted" ;
  Converters.ZeroIfNegative currentLevel "Current amount that is being depleted" ;
  Converters.ZeroIfNegative rateOfDepletion(redeclare replaceable type OutputType = Unspecified) "Rate of Depletion" ;
equation
  connect(residenceTime.y, y) ;
  connect(u_level, currentLevel.u) ;
  connect(currentLevel.y, residenceTime.u1) ;
  connect(u_rate, rateOfDepletion.u) ;
  connect(rateOfDepletion.y, residenceTime.u2) ;

