block TimeValueOfMoney "Calculate the time value of money (TVM) using continuous compounding"
  import BusinessSimulation.Units.*;
  extends Interfaces.PartialConverters.InformationProcessing_SO;
  Interfaces.Connectors.RealInput u "Current value input" ;
  Interfaces.Connectors.RealInput u_T(quantity = "Time", unit = "s") if not hasConstantHorizon "Time horizon(T >0 → FV, T < 0 → PV)" ;
  Interfaces.Connectors.RealInput u_r(quantity = "Rate", unit = "1/s") if not hasConstantRate "Interest rate" ;
  parameter Rate rate "Constant compounding rate" ;
  parameter Time T "Constant time horizon (T >0 → FV, T < 0 → PV)" ;
  parameter Boolean hasConstantRate = false "= true, if the discount rate is given by the constant parameter" ;
  parameter Boolean hasConstantHorizon = false "= true, if the time horizon is given by a constant parameter" ;
  parameter Boolean isCCR = true "= true, the rate does not need conversion to a continuously compounding rate" ;
protected
  Converters.Product_2 rate_x_T ;
  Converters.Exp timeValueFactor ;
  Converters.Product_2 timeValue "Time value of money" ;
  Converters.ConstantConverterRate parConstantRate(value = rate) if hasConstantRate "Constant rate for compounding" ;
  Converters.ForceOfInterest CCR if not isCCR "Continuously compounding rate" ;
  Converters.PassThrough unchangedRate if isCCR ;
  Converters.ConstantConverterTime parT(value = T) if hasConstantHorizon "Constant time into the future (time horizon)" ;
equation
  connect(u_r, CCR.u) ;
  connect(parConstantRate.y, CCR.u) ;
  connect(u_r, unchangedRate.u) ;
  connect(parConstantRate.y, unchangedRate.u) ;
  connect(unchangedRate.y, rate_x_T.u1) ;
  connect(rate_x_T.y, timeValueFactor.u) ;
  connect(CCR.y, rate_x_T.u1) ;
  connect(u, timeValue.u2) ;
  connect(timeValueFactor.y, timeValue.u1) ;
  connect(timeValue.y, y) ;
  connect(u_T, rate_x_T.u2) ;
  connect(parT.y, rate_x_T.u2) 
  ;
end TimeValueOfMoney;

