block Trend "Calculating a fractional rate of change to be used in forecasting"
  import BusinessSimulation.Units.*;
  import BusinessSimulation.Types.InitializationOptions;
  extends Interfaces.PartialConverters.InformationProcessing_SO(redeclare replaceable type OutputType = Rate);
  Interfaces.Connectors.RealInput u "Current value as basis for trend formulation" ;
  Interfaces.Connectors.RealOutput y_ppc if reportPPC "Report the perceived present condition (optional)" ;
  parameter Rate initialTrend = 0 "Initial trend" ;
  parameter Time tppc(min = 0) = 1 "Averaging time for perception of current quantity (i.e., the present condition)";
  parameter Time thrc(min = 0) = 1 "Time horizon for reference condition";
  parameter Time tpt(min = 0) = 1 "Time to perceive the trend (i.e., there is gradual adaptation to a new trend)" ;
  parameter Boolean smoothTrend = false "= true, if the calculated trend is to be smoothed" ;
  parameter Boolean reportPPC = false "= true, if the perceived present conditon is to be reported" ;
  parameter InitializationOptions init = modelSettings.init "Provide InitializationOptions (Free, FixedValue, SteadyState)" ;
  outer ModelSettings modelSettings;
protected
  parameter Real initialRC(fixed = false) "Initial Value for the reference condition" ;
  parameter Real initialPPC(fixed = false) "InitialValue for the perceived present condition" ;
  Converters.PassThrough actualTrend if not smoothTrend ;
  Converters.DiscreteDelay.Smooth rc(initialValue = initialRC, hasConstantDelayTime = false, init = init) "Reference condition for calculating the fractional trend" ;
  Converters.DiscreteDelay.Smooth ppc(initialValue = initialPPC, hasConstantDelayTime = false, init = init) "Perceived present condition" ;
  Converters.ConstantConverterTime parTPPC(value = tppc) "Time to perceive present condition" ;
  Converters.ConstantConverterTime parTHRC(value = thrc) "Time horizon for the reference condition (duration of trend formulation)" ;
  Converters.ConstantConverterTime parTPT(value = tpt) if smoothTrend "Time to perceive the trend (i.e., adjustment time)" ;
  Converters.DiscreteDelay.Smooth perceivedTrend(initialValue = initialTrend, hasConstantDelayTime = false, redeclare replaceable type OutputType = Rate, init = init) if smoothTrend "Perceived growth rate" ;
  Converters.Division_Guarded indicatedTrend "Indicated fractional growth rate (trend)" ;
  Converters.Gap delta "Difference between perceived present condition and reference condition" ;
  Converters.Product_2 rcTimesTHRC "Referenc condition times time horizon for reference condition" ;
initial equation
  initialPPC = u / (1 + tppc * initialTrend);
  initialRC = initialPPC / (1 + thrc * initialTrend);
equation
  connect(ppc.y, rc.u) ;
  connect(u, ppc.u) ;
  connect(perceivedTrend.y, y) "Fractional trend (fractional rate of growth)" ;
  connect(parTPPC.y, ppc.u_delayTime) ;
  connect(parTHRC.y, rc.u_delayTime) ;
  connect(parTPT.y, perceivedTrend.u_delayTime) ;
  connect(indicatedTrend.y, perceivedTrend.u) ;
  connect(ppc.y, delta.u1) ;
  connect(delta.y, indicatedTrend.u1) ;
  connect(rc.y, delta.u2) ;
  connect(rcTimesTHRC.y, indicatedTrend.u2) ;
  connect(parTHRC.y, rcTimesTHRC.u2) ;
  connect(rc.y, rcTimesTHRC.u1) ;
  connect(indicatedTrend.y, actualTrend.u) ;
  connect(actualTrend.y, y) ;
  connect(ppc.y, y_ppc) 
  ;
end Trend;

within BusinessSimulation.MoleculesOfStructure.InformationProcessing;

block TrendBasedForecast "Trend-based forecast for an exponentially growing quantity"
  import BusinessSimulation.Units.*;
  extends Interfaces.PartialConverters.InformationProcessing_SO;
  Interfaces.Connectors.RealInput u "Current value as basis for trend formulation" ;
  parameter Units.Rate initialTrend = 0 "Initial trend (fracGrowthRate.initialTrend)";
  parameter Time fcsth(min = 0) = 1 "Forecast horizon";
  parameter Time tppc(min = 0) = 1 "Averaging time for perception of current quantity (i.e., the present condition)";
  parameter Time thrc(min = 0) = 1 "Time horizon for reference condition";
  parameter Time tpt(min = 0) = 1 "Time to perceive the trend (i.e., there is gradual adaptation to a new trend)" ;
  parameter Boolean smoothTrend = false "= true, if the calculated trend is to be smoothed (fracGrowthRate.smoothTrend)" ;
protected
  Converters.Product_2 fractionalGrowth "FractionalGrowthRate times perceptionTime" ;
  Converters.Add_2 extrapolationFactor "Extrapolaton factor using fractional growth rate and perception time to eliminate perception lage" ;
  Trend fracGrowthRate(tppc = tppc, thrc = thrc, tpt = tpt, reportPPC = true, initialTrend = initialTrend, smoothTrend = smoothTrend) "TREND-formulation is used to calculate a fractional growth rate" ;
  Converters.Product_2 extrapolPC "Present Condition extrapolated from perceived quantity and the time to perceive it" ;
  TimeValueOfMoney futureValue "Future value according to exponential growth model" ;
  Converters.ConstantConverterTime timePPC(value = tppc) "Time to perceive present condition" ;
  Converters.ConstantConverterTime forecastHorizon(value = fcsth) "Forecast horizon (T)" ;
  Converters.ConstantConverter one(value = 1, redeclare replaceable type OutputType = Dimensionless) "Time to perceive present condition" ;
equation
  connect(u, fracGrowthRate.u) ;
  connect(futureValue.y, y) ;
  connect(forecastHorizon.y, futureValue.u_T) ;
  connect(extrapolPC.y, futureValue.u) ;
  connect(fractionalGrowth.y, extrapolationFactor.u2) ;
  connect(one.y, extrapolationFactor.u1) ;
  connect(timePPC.y, fractionalGrowth.u1) ;
  connect(extrapolationFactor.y, extrapolPC.u1) ;
  connect(fracGrowthRate.y, futureValue.u_r) ;
  connect(fracGrowthRate.y_ppc, extrapolPC.u2) ;
  connect(fracGrowthRate.y, fractionalGrowth.u2) 
  ;
end TrendBasedForecast;

