block Allocation "Allocate an available amount according to priorities and capacity restrictions"
  import BusinessSimulation.Units.*;
  import PP = BusinessSimulation.Types.PriorityProfiles;
  import BusinessSimulation.Functions.allocatedAmounts;
  extends Interfaces.PartialConverters.Policy_MO;
  Interfaces.Connectors.RealInput u "Available amount to be allocated" ;
  Interfaces.Connectors.RealMultiInput u_p[nout](each min = 0) "Priorities for allocation (i.e., utilities)" ;
  Interfaces.Connectors.RealMultiInput u_w[nout](each min = 0) "Widths for priority profiles (i.e., priority distribution functions)" ;
  Interfaces.Connectors.RealMultiInput u_c[nout](each min = 0) "Constraints for allocated amounts (i.e., maximum capacity/saturation level)" ;
  parameter Types.PriorityProfiles pp = PP.uniform "Priority distribution to be used for allocation" ;
protected
  Real totalCap = sum(u_c) "The sum of all elements in the vector u_c";
  Real clearing(start = 10) "The clearing priority";
equation
  // find clearing priority
  0 = u - sum(allocatedAmounts(x = clearing, vecA = u_p, vecC = u_c, vecW = u_w, pp = pp));
  y = if u <= 0 then zeros(nout) elseif u >= totalCap then u_c else allocatedAmounts(x = clearing, vecA = u_p, vecC = u_c, vecW = u_w, pp = pp)
  ;
end Allocation;

within BusinessSimulation.MoleculesOfStructure.Policy;

encapsulated block Allocation_Brent "Allocate an available amount according to priorities and capacity restrictions"
  import BusinessSimulation.Units.*;
  import BusinessSimulation.Constants.eps;
  import PP = BusinessSimulation.Types.PriorityProfiles;
  import BusinessSimulation.Functions.allocatedAmounts;
  import Modelica.Math.Nonlinear.solveOneNonlinearEquation;
  import BusinessSimulation.Functions.UtilityFunctions.findClearAttrac;
  import BusinessSimulation.Interfaces.Connectors.{RealInput, RealMultiInput};
  import ICON = BusinessSimulation.Interfaces.PartialConverters.Policy_MO;
  extends ICON;
  RealInput u "Available amount to be allocated" ;
  RealMultiInput u_p[nout](each min = 0) "Priorities for allocation (i.e., utilities)" ;
  RealMultiInput u_w[nout](each min = 0) "Widths for priority profiles (i.e., priority distribution functions)" ;
  RealMultiInput u_c[nout](each min = 0) "Constraints for allocated amounts (i.e., maximum capacity/saturation level)" ;
  parameter PP pp = PP.uniform "Priority distribution to be used for allocation" ;
  parameter Real tolerance = 100 * eps "Tolerance for Brent algorithm" ;
protected
  Real totalCap = sum(u_c) "The sum of all elements in the vector u_c";
  Real clearing "The clearing priority";
  Real w_max = max(u_w) "Maximum element in vecW";
  Real u_min "Lower bound for finding cA";
  Real u_max "Upper bound for finding cA";
equation
  u_min = -w_max;
  u_max = max(u_p) + w_max;
  // find clearing priority
  clearing = solveOneNonlinearEquation(function findClearAttrac(amount = u, vecA = u_p, vecC = u_c, vecW = u_w, pp = pp), u_min = u_min, u_max = u_max, tolerance = tolerance);
  y = if u <= 0 then zeros(nout) elseif u >= totalCap then u_c else allocatedAmounts(x = clearing, vecA = u_p, vecC = u_c, vecW = u_w, pp = pp)
  ;
end Allocation_Brent;

