block CloseGap "Determine the rate of flow (action) to close a gap between a quantity and its desired value"
  import BusinessSimulation.Units.*;
  import BusinessSimulation.Constants.*;
  import Modelica.Blocks.Types.LimiterHomotopy;
  extends Interfaces.PartialConverters.Policy_SO;
  Interfaces.Connectors.RealInput u_reference "Desired or reference value for the controlled quantity (i.e., the goal)" ;
  Interfaces.Connectors.RealInput u_current "Current value of controlled quantity" ;
  Interfaces.Connectors.RealInput u_adjTime if not hasConstantAdjTime "Time to close the gap" ;
  parameter Time adjTime(min = 0) = 1 "Time to close the gap" ;
  parameter OutputType maxRate = inf "Maximum rate feasible" ;
  parameter OutputType minRate = 0 "Minimum rate feasible" ;
  parameter Boolean hasConstantAdjTime = true "= true, if the time to close the gap is a constant paramater" ;
  parameter Boolean invertOutput = false "= true, if the output is to be multiplied with (-1)" ;
  parameter Boolean clipOutput = false "= true, if the indicated rate is to clipped to not exceed limitations" ;
  parameter Boolean strict = true "= true, if strict limits with noEvent(..) (constantLimiter.strict) (clip1.strict)" ;
  parameter LimiterHomotopy homotopyType = LimiterHomotopy.Linear "Simplified model for homotopy-based initialization (clip1.homotopyType)" ;
  outer ModelSettings modelSettings;
protected
  Converters.PassThrough unchanged1 if not invertOutput "Use the calculated net rate of flow" ;
  Converters.Gain invertedAction(c = -1) if invertOutput "This will turn negative rates to positive ones (for use with an outflow)" ;
  Converters.PassThrough unchanged2 if not clipOutput "Use the calculated net rate of flow" ;
  Converters.Clip clip1(maxValue = maxRate, minValue = minRate, hasConstantLimits = true, strict = strict, homotopyType = homotopyType) if clipOutput ;
  Converters.ConstantConverterTime parAdjTime(final value = adjTime) if hasConstantAdjTime "Constant time to close the gap (optional)" ;
  Converters.Gap gap "Difference between the goal and the current value" ;
  Converters.Division_Guarded actionToCloseGap(final outputIfZero = 0) "Rate of (net) flow to close the gap" ;
equation
  connect(u_reference, gap.u1) ;
  connect(u_current, gap.u2) ;
  connect(gap.y, actionToCloseGap.u1) ;
  connect(u_adjTime, actionToCloseGap.u2) ;
  connect(parAdjTime.y, actionToCloseGap.u2) ;
  connect(actionToCloseGap.y, unchanged1.u) ;
  connect(actionToCloseGap.y, invertedAction.u) ;
  connect(unchanged1.y, unchanged2.u) ;
  connect(unchanged2.y, y) ;
  connect(invertedAction.y, unchanged2.u) ;
  connect(unchanged1.y, clip1.u) ;
  connect(invertedAction.y, clip1.u) ;
  connect(clip1.y, y) 
  ;
end CloseGap;

