block FirstOrderStockAdjustment "Maintain a stock at a desired level"
  import BusinessSimulation.Units.*;
  import BusinessSimulation.Constants.*;
  import Modelica.Blocks.Types.LimiterHomotopy;
  extends Interfaces.PartialConverters.Policy_SO;
  Interfaces.Connectors.RealInput u_reference "Desired or reference amount in the stock under control" ;
  Interfaces.Connectors.RealInput u_current "Current amount in the stock under control" ;
  Interfaces.Connectors.RealInput u_outflow "Current outflow from the stock under control" ;
  Interfaces.Connectors.RealInput u_adjTime if not hasConstantAdjTime "Variable time for adjustment (optional)" ;
  parameter Time adjTime(min = 0) = 1 "Time constant for the adjustment to the desired level (optional)" ;
  parameter OutputType maxRate = inf "Maximum rate feasible (clippedRate.maxValue)" ;
  parameter Boolean hasConstantAdjTime = true "= true, if adjustment time is to be given by a constant parameter" ;
  parameter Boolean clipOutput = false "= true, if the indicated rate is to clipped to not exceed limitations" ;
  parameter Boolean strict = true "= true, if strict limits with noEvent(..) (constantLimiter.strict) (clip1.strict)" ;
  parameter LimiterHomotopy homotopyType = LimiterHomotopy.Linear "Simplified model for homotopy-based initialization (clip1.homotopyType)" ;
  outer ModelSettings modelSettings;
protected
  Converters.Clip clippedRate(strict = strict, homotopyType = homotopyType, hasConstantLimits = true, minValue = 0, maxValue = maxRate) if clipOutput "Limit rate to feasible values" ;
  Converters.PassThrough unchanged if not clipOutput "Leave the indicated rate unchanged" ;
  CloseGap adjustment(hasConstantAdjTime = false, invertOutput = false, clipOutput = false) "Inflow needed to reach desired level of stock" ;
  Converters.Add_2 totalAdjustment "Closing gap and compensate for outflow from stock" ;
  Converters.ConstantConverterTime parAdjTime(value = adjTime) if hasConstantAdjTime "Constant time of adjustment (optional)" ;
equation
  connect(u_outflow, totalAdjustment.u2) ;
  connect(u_reference, adjustment.u_reference) ;
  connect(u_current, adjustment.u_current) ;
  connect(adjustment.y, totalAdjustment.u1) ;
  connect(u_adjTime, adjustment.u_adjTime) ;
  connect(parAdjTime.y, adjustment.u_adjTime) ;
  connect(totalAdjustment.y, unchanged.u) ;
  connect(unchanged.y, y) ;
  connect(totalAdjustment.y, clippedRate.u) ;
  connect(clippedRate.y, y) 
  ;
end FirstOrderStockAdjustment;

