block PID "Limited PID controller"
  import BusinessSimulation.Units.*;
  import BusinessSimulation.Constants.*;
  extends Interfaces.PartialConverters.Policy_SO(redeclare replaceable type OutputType = Rate);
  import Modelica.Blocks.Types.Init;
  import Modelica.Blocks.Types.LimiterHomotopy;
  import Modelica.Blocks.Types.SimpleController;
  Interfaces.Connectors.RealInput u_desiredValue "The goal to meet (setpoint)" ;
  Interfaces.Connectors.RealInput u_currentValue "The measured state of the system under control" ;
  Interfaces.Connectors.RealInput u_feedForward if hasFeedForward "An optional feedforward input" ;
  parameter SimpleController controllerType = SimpleController.PID "Type of controller" ;
  parameter GainType k(min = 0) = 1 "Gain of controller [GainType]";
  parameter Time Ti(min = small) = 0.5 "Time constant of integrator (i.e., gain for integrator = 1/Ti)" ;
  parameter Time Td(min = 0) = 0.1 "Derivative gain (i.e., time span for error prediction)" ;
  parameter OutputType yMax = inf "Upper limit of output";
  parameter OutputType yMin = -yMax "Lower limit of output";
  parameter Fraction wp = 1 "Set-point weight for Proportional block (0..1)";
  parameter Fraction wd = 0 "Set-point weight for Derivative block (0..1)" ;
  parameter Dimensionless Ni(min = 100 * eps) = 0.9 "Ni*Ti is time constant of anti-windup compensation" ;
  parameter Dimensionless Nd(min = 100 * eps) = 10 "The higher Nd, the more ideal the derivative block" ;
  parameter Dimensionless kFF = 1 "Gain of feed-forward input" ;
  parameter Init initType = Init.NoInit "Type of initialization (1: no init, 2: steady state, 3: initial state, 4: initial output)" ;
  parameter Unspecified xi_start = 0 "Initial or guess value for integrator output (= integrator state)" ;
  parameter Unspecified xd_start = 0 "Initial or guess value for state of derivative block" ;
  parameter OutputType y_start = 0 "Initial value of output" ;
  parameter LimiterHomotopy homotopyType = LimiterHomotopy.Linear "Simplified model for homotopy-based initialization" ;
  parameter Boolean hasFeedForward = false "Use feed-forward input?" ;
  parameter Boolean strict = false "= true, if strict limits with noEvent(..)" ;
  parameter Boolean limitsAtInit = true "Has no longer an effect and is only kept for backwards compatibility (the implementation uses now the homotopy operator)" ;
protected
  replaceable type GainType = Rate constrainedby Unspecified "Type choice for controller gain" ;
  Modelica.Blocks.Continuous.LimPID PID(controllerType = SimpleController.PID, withFeedForward = hasFeedForward, Ti = Ti, k = k, Td = Td, yMax = yMax, yMin = yMin, wp = wp, wd = wd, Ni = Ni, Nd = Nd, kFF = kFF, xi_start = xi_start, xd_start = xd_start, y_start = y_start, homotopyType = homotopyType) ;
equation
  connect(u_desiredValue, PID.u_s) ;
  connect(u_currentValue, PID.u_m) ;
  connect(PID.y, y) ;
  connect(u_feedForward, PID.u_ff) 
  ;
end PID;

