model Chain "A chain of serially connected reservoirs"
  import BusinessSimulation.Units.*;
  import BusinessSimulation.Constants.*;
  import BusinessSimulation.Types.InitializationOptions;
  extends Icons.SubsystemTransceiver;
  extends Interfaces.Basics.OutputTypeChoice;
  Interfaces.Connectors.StockPort stockPort "Inflow-side of the chain" ;
  Interfaces.Connectors.FlowPort flowPort if hasFlowPort "Outflow side of the chain conditional upon `endWithCloud` switch" ;
  Interfaces.Connectors.RealMultiInput[n] u "Vector input of transition rates" ;
  RealMultiOutput[n] y "Amounts contained in the stocks" ;
  Interfaces.Connectors.StockInfoOutput[n] y_stockInfo if hasStockInfoOutput "Optional StockInfoOutput" ;
  parameter Integer n(min = 2) = 2 "The number of stocks in the chain" ;
  parameter Real[n] initialValue = zeros(n) "Vector of initial values for the stocks in the chain";
  parameter OutputType[n] maxValue = fill(inf, n) "Maximum admissable value";
  parameter OutputType[n] minValue = fill(-inf, n) "Minimum admissable value";
  parameter Boolean hasFlowPort = true "= true, if the outflow from the stock will go to a flow port instead of a cloud" ;
  parameter Boolean useAssert = false "= true, if  leaving the admissable range is to cause an error or warning" ;
  parameter Boolean causeError = true "= true, if leaving the admissable range is to cause an error instead of simply a warning" ;
  parameter Boolean hasStockInfoOutput = false "= true, if a StockInfoOutput should be added to the stock" ;
protected
  Reservoir reservoir[n](initialValue = initialValue, maxValue = maxValue, minValue = minValue, each hasStockInfoOutput = hasStockInfoOutput, each useAssert = useAssert, each causeError = causeError) ;
  SourcesOrSinks.Cloud cloud if not hasFlowPort ;
equation
  connect(stockPort, reservoir[1].stockPort) ;
  // connect the outflow from reservoir i to the stock port (inflow) of reservoir i+1
  for i in 1:n - 1 loop
    connect(reservoir[i].flowPort, reservoir[i + 1].stockPort);
  end for;
  // connect the outflow from the last reservoir to the flow port of the chain
  connect(reservoir[end].flowPort, flowPort) ;
  connect(reservoir[end].flowPort, cloud.massPort) "alternative end of chain" ;
  connect(u, reservoir.u) ;
  connect(reservoir.y, y) ;
  connect(reservoir.y_stockInfo, y_stockInfo) 
  ;
end Chain;

