model Reservoir "A single stock drained by an outflow at a given rate"
  import BusinessSimulation.Units.*;
  import BusinessSimulation.Constants.*;
  import BusinessSimulation.Types.InitializationOptions;
  extends Icons.SubsystemTransceiver;
  extends Interfaces.Basics.OutputTypeChoice;
  Interfaces.Connectors.StockPort stockPort "Receiving side of the element" ;
  Interfaces.Connectors.FlowPort flowPort if hasFlowPort ;
  Interfaces.Connectors.RealInput u "Rate of outflow from the stock" ;
  Interfaces.Connectors.StockInfoOutput y_stockInfo if hasStockInfoOutput "Optional StockInfoOutput" ;
  RealOutput y "Amount in the stock" ;
  parameter OutputType initialValue = 0 "Initial level of stock";
  parameter OutputType maxValue = inf "Maximum admissable value (reservoir.maxValue)";
  parameter OutputType minValue = -inf "Minimum admissable value (reservoir.minValue)";
  parameter Boolean hasStockInfoOutput = false "= true, if a StockInfoOutput should be added to the stock (reservoir.hasStockInfoOutput)" ;
  parameter Boolean hasFlowPort = true "= true, if the outflow from the stock will go to a flow port instead of a cloud" ;
  parameter InitializationOptions init = modelSettings.init "Provide InitializationOptions (Free, FixedValue, SteadyState) (reservoir.init)" ;
  parameter Boolean useAssert = false "= true, if  leaving the admissable range is to cause an error or warning (reservoir.useAssert)" ;
  parameter Boolean causeError = true "= true, if leaving the admissable range is to cause an error instead of simply a warning (reservoir.causeError)" ;
  outer ModelSettings modelSettings;
protected
  replaceable Stocks.InformationLevel stock(initialValue = initialValue, hasStockInfoOutput = hasStockInfoOutput, init = init, useAssert = useAssert, causeError = causeError, maxValue = maxValue, minValue = minValue) constrainedby BusinessSimulation.Interfaces.PartialStocks.BasicStock "The reservoir that is filled or drained by the connected flows." ;
  Flows.Unidirectional.Transition movingOn ;
  SourcesOrSinks.Cloud cloud if not hasFlowPort "System boundary" ;
equation
  connect(u, movingOn.u) ;
  connect(stock.outflow, movingOn.portA) ;
  connect(movingOn.portB, flowPort) ;
  connect(stock.inflow, stockPort) ;
  connect(stock.y, y) ;
  connect(stock.y_stockInfo, y_stockInfo) ;
  connect(movingOn.portB, cloud.massPort) 
  ;
end Reservoir;

