model SplitFlow "Splitting an arbitrary flow into n subflows"
  import BusinessSimulation.Units.*;
  extends Interfaces.Basics.OutputTypeChoice(redeclare replaceable type OutputType = Rate);
  extends Icons.SubsystemTransceiver;
  RealMultiOutput[nout] y "Rates of the split flows" ;
  Interfaces.Connectors.StockPort stockPort "Connected to incoming flow to be split or broken up" ;
  Interfaces.Connectors.FlowMultiPort flowPort[nout] "n-dimensional array of outgoing flows" ;
  Interfaces.Connectors.RealMultiInput u[nout] if not hasConstantWeights "Vector of weights for the splits or breaks" ;
  parameter Real[nout] weights = ones(nout) "Constant weights for splitting (optional)" ;
  parameter Integer nout(min = 1) = 2 "Number of flows to split into" ;
  parameter Boolean hasConstantWeights = false "= true, if the weights are constant parameters" ;
  parameter Boolean isSplit = true "= true, if the input given is assumed to be weights (adding up to one) splitting the flow" ;
  parameter Boolean shiftInputs = false "= true, if all values are to be shifted to prevent negative inputs, otherwise negative inputs are simply set to zero (proportionalSplitFactors.shiftInputs)" ;
protected
  Converters.Vector.ProportionalSplitFactors proportionalSplitFactors(nin = nout, shiftInputs = shiftInputs) if isSplit "Split factors adding up to one" ;
  Converters.PassThrough unchangedInput[nout] if not isSplit ;
  Sensors.StockPortSensor_Control sensor_A "Measuring the flow and seting the flags" ;
  Sensors.FlowPortSensor_Control sensor_B[nout] "Measuring stock level and Boolean flags" ;
  Converters.Logical.AnyTrue stopInflow(nin = nout) ;
  Converters.Logical.AnyTrue stopOutflow(nin = nout) ;
  Converters.Vector.ConstantConverter parWeights(value = weights, redeclare replaceable type OutputType = Dimensionless) if hasConstantWeights "Constant weights for splitting (optional)" ;
  Flows.Bidirectional.Switching splitFlows[nout] "The splitted outflow" ;
  SourcesOrSinks.Cloud cloudOutflow "Cloud connected to the aggregate outflow" ;
  SourcesOrSinks.Cloud[nout] cloudBrokenFlow "Clouds connected to the broken flows" ;
  Converters.Vector.ScalarMultiplication splitRates(nin = nout) "The rates for the split flows" ;
equation
  connect(cloudBrokenFlow.massPort, splitFlows.portA) ;
  connect(splitFlows.portB, flowPort) ;
  connect(proportionalSplitFactors.y, splitRates.u1) ;
  connect(u, proportionalSplitFactors.u) ;
  connect(splitRates.y, splitFlows.u) ;
  connect(u, unchangedInput.u) ;
  connect(unchangedInput.y, splitRates.u1) ;
  connect(stockPort, sensor_A.stockPort) ;
  connect(sensor_A.flowPort, cloudOutflow.massPort) ;
  connect(sensor_A.netFlow, splitRates.u2) ;
  connect(sensor_B.flowPort, flowPort) ;
  connect(sensor_B.stopInflow, stopInflow.u) ;
  connect(sensor_B.stopOutflow, stopOutflow.u) ;
  connect(stopInflow.y, sensor_A.u_stopInflow) ;
  connect(stopOutflow.y, sensor_A.u_stopOutflow) ;
  connect(splitFlows.y, y) ;
  connect(parWeights.y, unchangedInput.u) ;
  connect(parWeights.y, proportionalSplitFactors.u) 
  ;
end SplitFlow;

