model LogisticGrowth "Logistic growth model"
  import BusinessSimulation.Units.*;
  import BusinessSimulation.Constants.*;
  extends Interfaces.Basics.GenericSourceOrSink;
  extends Icons.Source;
  Interfaces.Connectors.RealMultiInput u[2] if not hasConstantInputs "[1] maximum fractional growth rate [2] carrying capacity" ;
  parameter Rate r(min = 0) = unspecified "Maximum fractional growth rate" ;
  parameter CapacityType K(min = 0) = unspecified "Carrying capacity or maximum sustainable amount for the connected stock (>0)" ;
  parameter Boolean isCCR = true "= true, if the maximum fractional rate given is assumed to be a continuously compounding rate else the rate will be converted" ;
  parameter Boolean hasConstantInputs = false "= true, if constant parameters aure to be used instead of the real inputs u[1] and u[2]" ;
  replaceable type CapacityType = Amount constrainedby Unspecified "Type for carrying capacity K" ;
protected
  Sensors.FlowPortSensor population "Current level of the connected stock" ;
  Cloud cloud "System boundary" ;
  Flows.Bidirectional.Switching growing "Process of logistic growth" ;
  Converters.Product_2 fractionalGrowthRate "Actual fractional rate of growth" ;
  Converters.Division_Guarded relativePopulation(outputIfZero = 1) "Population as percentage of carrying capacity" ;
  Converters.Gap residualCapacity "Percentage of the carrying capacity left for growth" ;
  Converters.ConstantConverter one(value = 1) "100 percent" ;
  Converters.Product_2 growthRate "Rate of growth" ;
  Converters.ConstantConverter carryingCapacity(value = K) if hasConstantInputs "Constant carrying capacity (optional)" ;
  Converters.ConstantConverter maxFractionalGrowthRate(value = r) if hasConstantInputs "Constant maximum rate of growth (optional)" ;
  Converters.ForceOfInterest convertedRate if not isCCR "Discrete compounding rate being converted to CCR" ;
  Converters.PassThrough identicalRate if isCCR "Use indicated rate if it is continuously compounding" ;
equation
  assert(relativePopulation.u2 > 0, "Carrying capacity must be larger than zero");
  assert(not hasConstantInputs or r < inf and K < inf, "Parameters r and K need to be specified");
  connect(population.flowPort, massPort) ;
  connect(cloud.massPort, growing.portA) ;
  connect(growing.y1, y2) ;
  connect(growing.y1, y) ;
  connect(growing.y1, y1) ;
  connect(growing.portB, massPort) ;
  connect(residualCapacity.y, fractionalGrowthRate.u1) ;
  connect(relativePopulation.y, residualCapacity.u2) ;
  connect(one.y, residualCapacity.u1) ;
  connect(population.stock, relativePopulation.u1) ;
  connect(fractionalGrowthRate.y, growthRate.u2) ;
  connect(population.stock, growthRate.u1) ;
  connect(growthRate.y, growing.u) ;
  connect(u[2], relativePopulation.u2) "Carrying capacity" ;
  connect(carryingCapacity.y, relativePopulation.u2) ;
  connect(maxFractionalGrowthRate.y, convertedRate.u) ;
  connect(convertedRate.y, fractionalGrowthRate.u2) ;
  connect(maxFractionalGrowthRate.y, identicalRate.u) ;
  connect(identicalRate.y, fractionalGrowthRate.u2) ;
  connect(u[1], identicalRate.u) "Continuous input of maximum fractional growth rate" ;
  connect(u[1], convertedRate.u) "Continuous input of fractional growth rate that needs to be converted" 
  ;
end LogisticGrowth;

