model CapacityRestrictedStock "Material stock, that cannot be drained or filled beyond its capacity limits"
  import BusinessSimulation.Types.InitializationOptions;
  import BusinessSimulation.Units.*;
  import BusinessSimulation.Constants.{small, zero, inf, INF};
  extends Interfaces.PartialStocks.BasicStock(initialValue(min = 0), minValue(min = zero) = zero, useAssert = false);
  extends Icons.MaterialStockIndicator;
  extends Icons.CapacityLabel;
  Interfaces.Connectors.RealInput u_min if hasVariableAdmissableRange "Variable minimum value to be monitored" ;
  Interfaces.Connectors.RealInput u_max if hasVariableAdmissableRange "Maximum value input" ;
  parameter Boolean hasVariableAdmissableRange = false "=true, if capacity restrictions are to be given by the variable inputs u_min and u_max" ;
  parameter Boolean reinitializeStock = false "= true, if the stock is to be reinitalized to guarante nonnegativity" ;
protected
  Converters.ConstantConverter parMinValue(value = minValue) if not hasVariableAdmissableRange ;
  Converters.ConstantConverter parMaxValue(value = maxValue) if not hasVariableAdmissableRange ;
  Converters.PassThrough theMinValue ;
  Converters.PassThrough theMaxValue ;
  Converters.Special.VariableRangeAssert variableRangeControl(causeError = causeError) if useAssert and hasVariableAdmissableRange "Use assert() to check admissable values" ;
initial equation
  // properly initialize discrete vars with fixed = false
  // provide Boolean signal when above capacity
  pre(inflow.stopInflow) = not x < theMaxValue.y - small;
  pre(outflow.stopInflow) = inflow.stopInflow;
  // provide Boolean signal when below capacity
  pre(inflow.stopOutflow) = not x > theMinValue.y + small;
  pre(outflow.stopOutflow) = pre(inflow.stopOutflow);
equation
  // provide Boolean signal when above capacity
  inflow.stopInflow = not x < theMaxValue.y - small;
  outflow.stopInflow = inflow.stopInflow;
  // provide Boolean signal when below capacity
  inflow.stopOutflow = not x > theMinValue.y + small;
  outflow.stopOutflow = inflow.stopOutflow;
  // optional reinitialize stock to zero if negative //
  if reinitializeStock then
    when x < 0 then
      reinit(x, 0);
    end when;
  end if;
  assert(theMinValue.y < theMaxValue.y, "Minimum capacity must be smaller than maximum capacity");
  connect(y1, variableRangeControl.u) ;
  connect(u_max, variableRangeControl.u_max) ;
  connect(u_min, variableRangeControl.u_min) ;
  connect(u_min, theMinValue.u) ;
  connect(parMinValue.y, theMinValue.u) ;
  connect(parMaxValue.y, theMaxValue.u) 
  ;
end CapacityRestrictedStock;

