model FlatTubeFinnedGeometry_N_cv "Discretized flatTubeFinned || Tube type"

  extends ClaRa.Basics.ControlVolumes.Fundamentals.Geometry.TubeType;
  extends ClaRa.Basics.ControlVolumes.Fundamentals.Geometry.GenericGeometry_N_cv(
    final volume={A_cross[i]*Delta_x[i] for i in 1:N_cv},
    final N_heat = 1,
    final A_heat = [{(A_f + A_ts)/(length*N_passes)*Delta_x[i] for i in 1:N_cv}],
    final A_cross=ones(N_cv)*heigth*width*(l_f-s_f)*(t_f-s_f)/((l_f+diameter_t)*t_f)/N_passes,
    Delta_x=ClaRa.Basics.Functions.GenerateGrid({0}, length*N_passes, N_cv),
    final z=cat(1,
               {(z_out - z_in)/(length*N_passes)*Delta_x[1]/2 + z_in},
               {((z_out - z_in)/(length*N_passes)*(sum(Delta_x[k] for k in 1:i - 1) + Delta_x[i]/2) + z_in) for i in 2:N_cv}),
    final Delta_z_in = {sum(Delta_x[1:i]) - Delta_x[i]/2 for i in 1:N_cv},
    final diameter_hyd={4*A_cross[i]*Delta_x[i]/A_heat[i,N_heat] for i in 1:N_cv});
  parameter ClaRa.Basics.Units.Length heigth=1 "Height of HX" ;
  parameter ClaRa.Basics.Units.Length width=1 "Width of HX (length of flat tube)" ;
  parameter ClaRa.Basics.Units.Length length=1 "Length of HX (width of flat tube)" ;
  parameter ClaRa.Basics.Units.Length diameter_t=0.01 "Outer diameter of the flat tube" ;
  parameter Integer N_tubes=1 "Number of tubes in parallel (one pass)"
                                                                      ;
  parameter Integer N_passes=1 "Number of passes of the tubes" ;
  parameter Integer flowOrientation=0 "Flow orientation" ;
  parameter ClaRa.Basics.Units.Length h_f=0.01 "Fin heigth" ;
  parameter ClaRa.Basics.Units.Length s_f=0.002 "Fin thickness" ;
  parameter ClaRa.Basics.Units.Length t_f=0.001 "Fin spacing" ;
  parameter ClaRa.Basics.Units.Length l_l=0.8*h_f "Length of one louver" ;
  parameter ClaRa.Basics.Units.Length t_l=0.001 "Louver spacing" ;
  parameter Real Phi(min=0) = 45 "Louver angle" ;
  final parameter ClaRa.Basics.Units.Length l_f=sqrt(h_f^2 + t_f^2) "Fin length" ;
  final parameter Real N_f = (integer(width / t_f) + 1) "Number of fins between two tubes" ;
  final parameter ClaRa.Basics.Units.Area A_f=2*(length + s_f)*h_f*N_f*(N_tubes+1)*N_passes + A_l "Finned heat transfer area" ;
  final parameter ClaRa.Basics.Units.Area A_ts=2*((width - s_f*N_f)*length + width*diameter_t)*(N_tubes+1)*N_passes "Tube side heat transfer area" ;
  final parameter ClaRa.Basics.Units.Area A_l=2*(l_l*N_f*N_l*s_f)*(N_tubes+1)*N_passes "Louver cutting heat transfer area" ;
  final parameter Integer N_l = if t_l <= 0 then 0 else integer(length/t_l) - 1 "Number of louvers alongside one fin" 
    ;
