  parameter Real CF_geo[N_heat](each min=Modelica.Constants.eps) = ones(N_heat) "Correction factor for heat transfer area: /1/ dedicated to lateral surface"
                                                                                          ;
  parameter Units.Area A_heat[N_cv,N_heat](each min=Modelica.Constants.eps) = ones(N_cv, N_heat) "Heat transfer area: /1/ dedicated to lateral surface" ;
  final parameter Units.Area A_heat_CF[N_cv,N_heat](each min=Modelica.Constants.eps) = {{A_heat[j, i]*CF_geo[i] for i in 1:N_heat} for j in 1:N_cv} "Corrected heat transfer area: /1/ dedicated to lateral surface" ;
  final parameter Units.Area A_heat_tot[N_heat]={sum(A_heat[:, i]) for i in 1:N_heat} "Total Heat transfer area: /1/ dedicated to lateral surface" ;
  parameter Units.Area A_cross[N_cv](min=ones(N_cv)*Modelica.Constants.eps) = ones(N_cv)*1 "Cross section for mass flow" ;
  final parameter Units.Area A_cross_FM[N_cv + 1](min=ones(N_cv + 1)*Modelica.Constants.eps) = cat(
    1,
    {A_cross[1]},
    {(A_cross[i] + A_cross[i + 1])/2 for i in 1:N_cv - 1},
    {A_cross[N_cv]}) "Cross section for mass flow" ;
  parameter Units.Length z_in=0 "Height of inlet ports" ;
  parameter Units.Length z_out=0 "Height of outlet ports" ;
  parameter Units.Length z[N_cv]=fill(1, N_cv) "Height of center of cells" ;
  parameter ClaRa.Basics.Units.Length Delta_z_in[N_cv]={sum(Delta_x[1:i]) - Delta_x[i]/2 for i in 1:N_cv} "Length from inlet to center of cells" ;
  parameter Units.Length diameter_hyd[N_cv]=ones(N_cv) "Hydraulic diameter of the component" ;
  parameter Integer N_cv=3 "Number of control volumes" ;
  parameter Units.Length Delta_x[N_cv]=fill(1, N_cv) "Discretisation scheme" ;
  parameter Units.Length Delta_x_FM[N_cv + 1]=cat(
      1,
      {Delta_x[1]/2},
      {(Delta_x[i - 1] + Delta_x[i])/2 for i in 2:N_cv},
      {Delta_x[N_cv]/2}) "Discretisation scheme (Flow model)" ;
  final parameter Units.Volume volume_FM[N_cv + 1]=cat(
      1,
      {volume[1]/2},
      {volume[i - 1]*Delta_x[i - 1]/2/Delta_x_FM[i] + volume[i]*Delta_x[i]/2/Delta_x_FM[i] for i in 2:N_cv},
      {volume[N_cv]/2})
    ;
end GenericGeometry_N_cv;

within ClaRa.Basics.ControlVolumes.Fundamentals.Geometry;
model HollowBlock "Block shape || No interior"
  extends ClaRa.Basics.ControlVolumes.Fundamentals.Geometry.BlockShape;
  extends ClaRa.Basics.ControlVolumes.Fundamentals.Geometry.GenericGeometry(
    final volume=width*height*length,
    final N_heat=1,
    final A_heat={if flowOrientation == ClaRa.Basics.Choices.GeometryOrientation.vertical then 2*(width + length)*height else 2*(width + height)*length},
    final A_cross=if flowOrientation == ClaRa.Basics.Choices.GeometryOrientation.vertical then (width*length) else (width*height),
    final A_front=A_cross,
    final A_hor=length*width,
    height_fill=height,
    final shape=[0, 1; 1, 1]);
  import SI = ClaRa.Basics.Units;
  parameter Units.Length height=1 "Height of the component; Fixed flow direction in case of vertical flow orientation" ;
  parameter Units.Length width=1 "Width of the component" ;
  parameter Units.Length length=1 "Length of the component; Fixed flow direction in case of horizontal flow orientation" ;
  parameter ClaRa.Basics.Choices.GeometryOrientation flowOrientation=ClaRa.Basics.Choices.GeometryOrientation.vertical "Flow orientation of the component" ;
equation
   for i in 1:N_inlet loop
     assert(if integer(height_fill) <> -1 then z_in[i]<=height_fill else true, "Position of inlet flange no. " +String(i)+ "("+String(z_in[i], significantDigits=3)+" m) must be below max. fill height of "+ String(height_fill, significantDigits=3) + " m in component " +  getInstanceName() + ".");
   end for;
   for i in 1:N_outlet loop
     assert(if integer(height_fill) <> -1 then z_out[i]<=height_fill else true, "Position of outlet flange no. " +String(i)+ "("+String(z_out[i], significantDigits=3)+" m) must be below max. fill height of "+ String(height_fill, significantDigits=3) + " m in component " +  getInstanceName() + ".");
   end for;
  for i in 1:N_inlet loop
    assert(z_in[i]>=0, "Position of inlet flange no. " +String(i)+ "("+String(z_in[i], significantDigits=3)+" m) must be positive in component " +  getInstanceName() + ".");
  end for;
  for i in 1:N_outlet loop
    assert(z_out[i]>=0, "Position of outlet flange no. " +String(i)+ "("+String(z_out[i], significantDigits=3)+" m) must be positive in component " +  getInstanceName() + ".");
  end for;
  assert(A_cross>0, "The cross section of the shell side must be > 0 but is "+String(A_cross, significantDigits=3) + " in instance" + getInstanceName() + ".");
  assert(volume>0, "The volume of the shell side must be > 0 but is "+String(volume, significantDigits=3) + " in instance" + getInstanceName() + ".")
    ;
end HollowBlock;

