model PlateGeometry "Plate || Tube type"

  extends ClaRa.Basics.ControlVolumes.Fundamentals.Geometry.TubeType;
  extends ClaRa.Basics.ControlVolumes.Fundamentals.Geometry.GenericGeometry(
    final volume=A_cross*length,
    final N_heat = 2,
    final A_heat = {(N_plates-2)*Phi*width*length,2*(N_plates*(thickness_wall+2*amp)-2*amp)*(width+length)+2*width*length},
    final A_cross=(N_plates-1)/2*width*2*amp,
    final A_front = A_cross,
    final A_hor = 1e-6,
    final shape = [0, 1; 1, 1],
    final height_fill = -1,
    final N_inlet=1,
    final N_outlet=1);
  parameter ClaRa.Basics.Units.Length width=1 "Plate width" ;
  parameter ClaRa.Basics.Units.Length length=1 "Plate length" ;
  parameter ClaRa.Basics.Units.Length thickness_wall=0.001 "Wall thickness" ;
  parameter Integer N_plates(min=3)=3 "Number of tubes in parallel"
                                                                   ;
  parameter ClaRa.Basics.Units.Length amp(min=1e-10) = 0.001 "Amplitude of corrugated plate" ;
  parameter ClaRa.Basics.Units.Length length_wave(min=1e-10) = 2*Modelica.Constants.pi*amp "Wave length of corrugated plate" ;
  parameter ClaRa.Basics.Units.Angle phi = 60*Modelica.Constants.pi/180 "Corrugation angle" ;
  final parameter Real X = 2*Modelica.Constants.pi*amp/length_wave "Wave number"
                                                                                ;
