within ClaRa.Basics.ControlVolumes.SolidVolumes.Fundamentals.Blocks;
block TinyPIP "A minimum implementation of a PI controller with anti windup compensation"
  parameter Real K_p = 1 "Controller gain" ;
  parameter ClaRa.Basics.Units.Time Tau_i "Integrator time constant" ;
  parameter Real N_i= 0.9 "Ni is time constant for anti-windup compensation"  ;
  parameter Real y_max = 1 "Maximum output"   ;
  parameter Real y_min = 0 "Minimum output"   ;
  parameter Integer initOption = 1 "Initialisation option" ;
  parameter Real y_start = 1 "Initial output" ;
  input Real u ;
  output Real y(start=y_start) ;
protected
  Real outputP;
  Real outputI(start=0);
initial equation
  if initOption == 1 then 
    outputI = 0;
  elseif initOption ==2 then 
    der(outputI)=0;
    der(y)=0;
  elseif initOption == 3 then 


  elseif initOption==4 then 

    y = min(y_max, max(y_min, y_start));
  else
    assert(false, "Unknown init option in component " + getInstanceName());
  end if;
equation

    der(outputI) = K_p/Tau_i*(u + 1/(K_p*N_i)*(min(max(y_min, y), y_max) - (outputI+outputP)));
  outputP = K_p*u;
  y = max(y_min, min(y_max, outputI + outputP))
    ;
end TinyPIP;

