within ClaRa.Basics.Functions;
function A_hor_intCyl "Horizontal area of a cylinder vertically intersecting a horizontal cylinder of large diameter"
  extends ClaRa.Basics.Icons.Function;
  input Real z "Vertical position";
  input Real D1 "Diameter of vertical cylinder";
  input Real D2 "Diameter of horizontal cylinder";
  input Real h1 "Length of vertical cylinder";
  input Real L "Length of horizontal cylinder";
  output Real A_intersectingCylinder "Intersecting area";
protected
  Real beta;
  Real x;
  Real h2;
  Real r1;
  Real r2;
algorithm
  r1:=D1/2;
  r2:=D2/2;
  x:=2*r2*sin(acos((r2-z+h1)/r2));
  beta:=2*acos(min(x/r1/2,1-Modelica.Constants.eps));
  h2:=r2*(1-cos(asin(r1/r2)))+h1;
  if z>=0 and z<= h1 then
    A_intersectingCylinder:=Modelica.Constants.pi *r1^2;
  elseif z>h1 and z<h2 then
    A_intersectingCylinder:=x*L+r1^2*(beta-sin(beta));
  else
    A_intersectingCylinder:= x*L;
  end if
;
end A_hor_intCyl;

within ClaRa.Basics.Functions;
function CalculateStateChangeFraction "Calculate the fraction of state change in two-phase region to total state change"
  extends ClaRa.Basics.Icons.Function;
  input ClaRa.Basics.Units.EnthalpyMassSpecific h_in "Inlet spec. enthalpy";
  input ClaRa.Basics.Units.EnthalpyMassSpecific h_out "Outlet spec.  enthalpy";
  input ClaRa.Basics.Units.EnthalpyMassSpecific h_dew "Dew spec. enthalpy";
  input ClaRa.Basics.Units.EnthalpyMassSpecific h_bub "Bubble spec. enthalpy";
  output Real yps_2ph "Fraction of state change in two-phase region";
  output Integer case;
algorithm
    if abs(h_in-h_out)<1e-3 then
          yps_2ph:=0;
          case:=0 "in=out";
    else
      if h_in < h_bub then 
        if h_out  < h_bub then 
            yps_2ph:=0;
            case:=1 "liq - liq";
        elseif h_out > h_dew then 
            yps_2ph :=min(1, max(0, abs((h_dew - h_bub)/(h_out - h_in))));
            case:=2 "liq - vap";
        else
            yps_2ph :=min(1, max(0, abs((h_out - h_bub)/(h_out - h_in))));
            case:=3 "liq - 2ph";
        end if;
      elseif  h_in >  h_dew then 
        if h_out  < h_bub then 
            yps_2ph:=min(1, max(0, abs((h_dew - h_bub)/(h_out - h_in))));
            case:=4 "vap - liq";
        elseif h_out > h_dew then 
            yps_2ph:=0;
            case:=5 "vap - vap";
        else 
            yps_2ph:=min(1, max(0, abs((h_out - h_dew)/(h_out - h_in))));
            case:=6 "vap - 2ph";
        end if;
      else 
        if h_out < h_bub then 
          yps_2ph :=min(1, max(0, abs((h_in - h_bub)/(h_out - h_in))));
          case:=7 "2ph - liq";
        elseif h_out > h_dew then 
          yps_2ph:=min(1, max(0, abs((h_in - h_dew)/(h_out - h_in))));
          case:=8 "2ph - vap";
        else 
          yps_2ph:=1;
          case:=9 "2ph - 2ph";
        end if;
      end if;
    end if
;
end CalculateStateChangeFraction;

