within ClaRa.Basics.Media.FuelFunctions;
function ashMassFraction_xi "Mass fraction of ash as function xi"














  input ClaRa.Basics.Units.MassFraction xi_c[:] "Composition";
  input ClaRa.Basics.Media.FuelTypes.BaseFuel fuelType=ClaRa.Basics.Media.FuelTypes.Fuel_refvalues_v1() "Fuel type";
  output ClaRa.Basics.Units.MassFraction xi_ash "Composition";
algorithm
  xi_ash :=if fuelType.ashIndex == fuelType.N_c then max(0, min(1, 1 - sum(xi_c))) else xi_c[fuelType.ashIndex]
    ;
end ashMassFraction_xi;

within ClaRa.Basics.Media.FuelFunctions;
function density_pTxi "Density as function of p,T,xi"














  input ClaRa.Basics.Units.Pressure p "Pressure";
  input ClaRa.Basics.Units.Temperature T "Temperature";
  input ClaRa.Basics.Units.MassFraction xi_c[:] "Composition";
   input ClaRa.Basics.Media.FuelTypes.BaseFuel fuelType=ClaRa.Basics.Media.FuelTypes.Fuel_refvalues_v1() "Fuel type";
  output ClaRa.Basics.Units.DensityMassSpecific rho "Density";
algorithm
     rho:= sum({xi_c[i]*fuelType.C_rho[i] for i in 1:fuelType.N_c-1}) + (1-sum(xi_c))*fuelType.C_rho[fuelType.N_c]
         ;
end density_pTxi;

within ClaRa.Basics.Media.FuelFunctions;
function elementaryComposition_xi "Elementary composition as function of fuel xi"














  input ClaRa.Basics.Units.MassFraction xi_c[:] "Composition of fuel";
  input ClaRa.Basics.Media.FuelTypes.BaseFuel fuelType=ClaRa.Basics.Media.FuelTypes.Fuel_refvalues_v1() "Fuel type";
  output ClaRa.Basics.Units.MassFraction xi_elements[fuelType.N_e - 1] "Composition of elements";
algorithm
    xi_elements:=zeros(fuelType.N_e - 1);
  if fuelType.N_c==fuelType.N_e then
    xi_elements :=xi_c;
  else
    for i in 1:fuelType.N_e-3 loop
      for j in 1: fuelType.N_c-2 loop
        xi_elements[i] := xi_elements[i] + xi_c[j].* fuelType.xi_e_waf[j,i];
      end for;
    end for;
    for j in 1: fuelType.N_c-2 loop
      xi_elements[fuelType.N_e-2] := xi_elements[fuelType.N_e-2] +  xi_c[j] .* (1 - sum(fuelType.xi_e_waf[j, :]));
    end for;
    xi_elements[fuelType.N_e-1]:=ashMassFraction_xi(xi_c, fuelType);
  end if
      ;
end elementaryComposition_xi;

within ClaRa.Basics.Media.FuelFunctions;
function enthalpy_pTxi "Specific enthalpy as function of p,T,xi"














  input ClaRa.Basics.Units.Pressure p "Pressure";
  input ClaRa.Basics.Units.Temperature T "Temperature";
  input ClaRa.Basics.Units.MassFraction xi_c[:] "Composition";
  input ClaRa.Basics.Media.FuelTypes.BaseFuel fuelType=ClaRa.Basics.Media.FuelTypes.Fuel_refvalues_v1() "Fuel type";
  output ClaRa.Basics.Units.EnthalpyMassSpecific h "Spec. enthalpy";
algorithm
      h := heatCapacity_pTxi(p,T,xi_c, fuelType)*(T-fuelType.T_ref)
          ;
end enthalpy_pTxi;

within ClaRa.Basics.Media.FuelFunctions;
function heatCapacity_pTxi "Heat capacity as function of p, T and xi"














  input ClaRa.Basics.Units.Pressure p "Pressure";
  input ClaRa.Basics.Units.Temperature T "Temperature";
  input ClaRa.Basics.Units.MassFraction xi_c[:] "Mass fraction of components";
  input ClaRa.Basics.Media.FuelTypes.BaseFuel fuelType=ClaRa.Basics.Media.FuelTypes.Fuel_refvalues_v1() "Fuel type";
  output ClaRa.Basics.Units.HeatCapacityMassSpecific cp;
algorithm
        cp:= sum({xi_c[i]*fuelType.C_cp[i] for i in 1:fuelType.N_c-1}) + (1-sum(xi_c))*fuelType.C_cp[fuelType.N_c]
            ;
end heatCapacity_pTxi;

