model CoalSupplyBoiler_01_XRG "A simple coal supply and boiler model using characteristic lines and transfer functions"
  extends ClaRa.Components.Control.PredictorModels_3508.Icons.BoilerPredictor;
  extends ClaRa.Basics.Icons.ComplexityLevel(complexity="01");
  outer ClaRa.SimCenter simCenter;
  parameter TILMedia.VLEFluidTypes.BaseVLEFluid medium = simCenter.fluid1 "Medium in the component"
    ;
  parameter ClaRa.Basics.Units.Pressure p_LS_nom= 300e5 "Nominal life steam pressure"
                                                                                  ;
  parameter ClaRa.Basics.Units.Pressure Delta_p_nom = 40e5 "Nominal life steam pressure loss"       ;
  parameter ClaRa.Basics.Units.EnthalpyMassSpecific h_LS_nom = 3279e3 "Nominal life steam specific enthalpy"
                                                                                            ;
  parameter ClaRa.Basics.Units.MassFlowRate m_flow_LS_nom = 419 "Nominal life steam flow rate" ;
  parameter Real CL_mflowLS_QF_[:,:]=[0, 0.32; 0.34, 0.32; 1, 1] "Characteristic line life steam flow as function of thermal output"
                                                                        ;
  parameter Real CL_pLS_QF_[:,:]=[0, 0.32; 0.34, 0.32; 1, 1] "Characteristic line life steam pressure as function of thermal output"
                                                                            ;
  parameter Real CL_Valve_[:,:]=[0,0; 1, 1] "Characteristics of the turbine valve"
                                           ;
  parameter Real CL_Deltap_mflowLS_[:,:]=[0,0;0.1, 0.01; 0.2, 0.04; 0.3, 0.09; 0.4, 0.16; 0.5, 0.25; 0.6, 0.36; 0.7, 0.49; 0.8, 0.64; 0.9, 0.81; 1, 1] "Characteristic line of life steam pressure drop as function of mass flow rate"
                                                                                    ;
  parameter Real CL_hEvap_pD_[:,:] = [0.34, 2806e3; 0.55, 2708e3; 0.75, 2559e3; 1, 2200e3] "Characteristic line evap outlet enthalpy over pressure"
                                                             ;
  parameter ClaRa.Basics.Units.Time tau_u = 120 "equivalent dead time of steam generation" ;
  parameter ClaRa.Basics.Units.Time Tau_g = 200 "balancing time of steam generation" ;
  parameter ClaRa.Basics.Units.Time Tau_s = 200 "Integration time of steam storage"  ;
  parameter ClaRa.Basics.Units.Time Tau_evap=5 "Time constant for energy storage in evaporator"
                                                    ;
  parameter Real y_T_const = 1 "Constant turbine valve aperture" ;
  input ClaRa.Basics.Units.Temperature T_LS = 823.15 "Value of life steam temperature" ;
  ClaRa.Basics.Units.Pressure p_LS "Life steam pressure";
  parameter Real p_LS_0=1 "Initial value of life steam pressure in p.u." ;
protected
  Modelica.Blocks.Sources.RealExpression h(y=TILMedia.Internals.VLEFluidConfigurations.FullyMixtureCompatible.VLEFluidFunctions.specificEnthalpy_pTxi(medium, p_LS, T_LS)/h_LS_nom) "Life Steam specific enthalpy"
                                   ;
public
  Modelica.Blocks.Continuous.LimIntegrator
                                        SteamStorage(k=1/Tau_s,
    initType=Modelica.Blocks.Types.Init.InitialOutput,
    y_start=p_LS_0,
    outMin=0,
    outMax=1.5) "A simple way to model the mass storage in the boiler"
    ;
  Modelica.Blocks.Math.Feedback feedback
    ;
  Modelica.Blocks.Continuous.TransferFunction heatRelease(a={Tau_g*tau_u,(Tau_g + tau_u),1},
    initType=Modelica.Blocks.Types.Init.InitialOutput,
    y_start=p_LS_0) "comprehends the coal supply, the heat release and the steam generation"
    ;
  Modelica.Blocks.Math.Product turbineValve "Effect of steam flow throtteling"
    ;
  Modelica.Blocks.Interfaces.RealInput yT_ "Turbine valve aperture"
    ;
  Modelica.Blocks.Tables.CombiTable1Dv turbineValveCaracteristics(table=CL_Valve_, columns={2}) ;
  Modelica.Blocks.Tables.CombiTable1Dv convert2LifeSteamFlow(columns={2}, table=CL_mflowLS_QF_) ;
  Modelica.Blocks.Tables.CombiTable1Dv convert2LifeSteamPressure(columns={2}, table=CL_pLS_QF_) ;
  Modelica.Blocks.Tables.CombiTable1Dv convert2PressureDrop(columns={2}, table=CL_Deltap_mflowLS_) ;
  Modelica.Blocks.Interfaces.RealInput QF_setl_ "Set value of thermal output in p.u."
                                          ;
  Basics.Interfaces.SteamSignal      steamSignal ;
  EnthalpyPredictor enthalpyPredictor(CL_hEvap_pD_=CL_hEvap_pD_,
      Tau_evap=Tau_evap,
    initType=Modelica.Blocks.Types.Init.SteadyState,
    h_evap_start=2200e3)
    ;
  Modelica.Blocks.Interfaces.RealOutput m_StG_ "Mass flow rate of steam generation in p.u."
                                                 ;
  Modelica.Blocks.Interfaces.RealOutput p_LS_ "Connector of Real output signal" ;
equation
 if cardinality(yT_)==0 then
   turbineValveCaracteristics.u[1]=y_T_const;
 else
  turbineValveCaracteristics.u[1]=yT_;
 end if;
 p_LS=convert2LifeSteamPressure.y[1]*p_LS_nom;
  connect(feedback.y, SteamStorage.u) ;
  connect(heatRelease.y, feedback.u1) ;
  connect(SteamStorage.y, turbineValve.u1) ;
  connect(turbineValve.y, feedback.u2) ;
  connect(turbineValveCaracteristics.y[1], turbineValve.u2) ;
  connect(turbineValve.y, convert2LifeSteamFlow.u[1]) ;
  connect(convert2LifeSteamPressure.u[1], SteamStorage.y) ;
  connect(convert2LifeSteamFlow.y[1], convert2PressureDrop.u[1]) ;
  connect(heatRelease.u, QF_setl_) ;
  connect(convert2LifeSteamFlow.y[1], steamSignal.m_flow_) ;
  connect(h.y, steamSignal.h_) ;
  connect(convert2LifeSteamPressure.y[1], steamSignal.p_) ;
  connect(SteamStorage.y, enthalpyPredictor.u) ;
  connect(enthalpyPredictor.y, steamSignal.h_evap) ;
  connect(heatRelease.y, m_StG_) ;
  connect(m_StG_, m_StG_) ;
  connect(convert2LifeSteamPressure.y[1], p_LS_) 
    ;
end CoalSupplyBoiler_01_XRG;

within ClaRa.Components.Control.PredictorModels_3508;
model EnthalpyPredictor "Prediction of evaporator outlet enthalpy using characteristic lines and transfer functions"
  extends Modelica.Blocks.Interfaces.SISO;
  extends ClaRa.Basics.Icons.ComplexityLevel(complexity="01");
  parameter Real CL_hEvap_pD_[:,:] = [0.34, 2806e3; 0.55, 2708e3; 0.75, 2559e3; 1, 2200e3] "Characteristic line evap outlet enthalpy over pressure"
                                                             ;
  parameter Modelica.Units.SI.Time Tau_evap=40 "Time constant for energy storage in evaporator" ;
  Modelica.Blocks.Tables.CombiTable1Dv convert2enthalpy(columns={2}, table=CL_hEvap_pD_) ;
  Modelica.Blocks.Continuous.FirstOrder firstOrder(T=Tau_evap,
    initType=initType,
    y_start=h_evap_start)
    ;
  Modelica.Blocks.Continuous.FirstOrder firstOrder1(T=Tau_evap,
    initType=initType,
    y_start=h_evap_start)
    ;
  Modelica.Blocks.Continuous.FirstOrder firstOrder2(T=Tau_evap,
    initType=initType,
    y_start=h_evap_start)
    ;
  Modelica.Blocks.Continuous.FirstOrder firstOrder3(T=Tau_evap,
    initType=initType,
    y_start=h_evap_start)
    ;
  parameter Modelica.Blocks.Types.Init initType=Modelica.Blocks.Types.Init.NoInit "Initialisation option" ;
  parameter Modelica.Units.SI.SpecificEnthalpy h_evap_start=0 "Initial evaporator outlet enthalpy" ;
equation
  connect(u, convert2enthalpy.u[1]) ;
  connect(convert2enthalpy.y[1], firstOrder.u) ;
  connect(firstOrder.y, firstOrder1.u) ;
