within ClaRa.Components.Mills.PhysicalMills.Volumes.Fundamentals.Grinding.Selection_Function;
model Selection_Kersting "Selection matrix according to Kersting (1986), p. 19-23"
  extends Selection_base;


  parameter Real mu = 0.7 "parameter mu = 0.7 according to Kersting (1986), Eq. 2.1-30 and to Steinmetz (1991), p. 111";
  parameter Real s0_start = 0.15/0.8 "according to Kersting (1986), p. 27";
  ClaRa.Basics.Units.Frequency s0[N_class] "base values selection matrix";




  parameter ClaRa.Basics.Units.Force F_grinding = 280e3 "grinding force per roll";

  parameter ClaRa.Basics.Units.SurfaceTension c_spring = 200e3 "spring constant";
  parameter Integer n_springs = 7 "number of springs per roll";

  ClaRa.Basics.Units.Frequency s[N_class] "frequency of selection due to rotating grinding table";
  ClaRa.Basics.Units.Frequency S[N_class,N_class] "selection matrix";

equation

  s0[1] = s0_start "element [1,1] of matrix s0";
  s0[N_class] = 0;
  for i in 2:N_class-1 loop
    s0[i] =  s0[1] * (diameter_prtcl[i+1]/diameter_prtcl[i])^((i-1)*mu);
  end for;

  s = s0 .* (1 + (F_grinding / (height_bed[n] * n_springs * c_spring)));
  S = diagonal(cat(1,s[1:N_class-1],{0}));  
    ;
end Selection_Kersting;

within ClaRa.Components.Mills.PhysicalMills.Volumes.Fundamentals.Grinding.Selection_Function;
model Selection_Steinmetz "Default selection matrix according to Steinmetz (1991), p. 108-119"
  extends Selection_base;



  parameter Real s0 = 325e-10 "base value selection according to Steinmetz (1991), p. 151" ;
  parameter Real mu = 0.45 "mu = 0.45 according to Sato(1996), mu = 0.7 according to Steinmetz (1991), p. 111" ;


  parameter ClaRa.Basics.Units.Area A_hydraulics = 0.035 "diameter of hydraulic cylinders per roll" ;
  parameter ClaRa.Basics.Units.SurfaceTension c_spring = 7*200e3 "spring constant (1e6 ... 5.6e6 N/m according to Schüler(1975))" ;
  parameter Integer n_rolls = 3 "number of grinding rolls" ;
  parameter ClaRa.Basics.Units.Length diameter_roll = 1.18 "diameter of roll" ;
  parameter ClaRa.Basics.Units.Length width_roll = 0.4 "width of roll annotation" ;
  parameter Real coeff_lever = 1 "coefficient to respect any lever" ;
protected
  parameter ClaRa.Basics.Units.Length radius_roll = diameter_roll/2;
  parameter ClaRa.Basics.Units.Mass mass_roll = Modelica.Constants.pi*(0.5*diameter_roll)^2*width_roll*7850 "mass of one grinding roll" ;

public
  ClaRa.Basics.Units.Force F_grinding "total grinding force per roll";
  ClaRa.Basics.Units.Frequency s[N_class] "frequency of selection due to rotating grinding table";
  ClaRa.Basics.Units.Frequency S[N_class,N_class] "selection matrix";
  Real coeff_operation;








  Modelica.Blocks.Tables.CombiTable1Ds tableHGI(table=[0.5,0.5,1; 0.69,0.69,1; 0.89,0.89,1; 1.08,1.08,1; 1.28,1.28,1; 1.47,1.47,1; 1.67,1.67,1])                                                                                                                                       ;
  Real coeff_HGI_slope;
  Real coeff_HGI_offset;
equation

  tableHGI.u = iCom.HGI/iCom.HGI_nom;
  tableHGI.y[1] = coeff_HGI_offset;
  tableHGI.y[2] = coeff_HGI_slope;


  F_grinding =  (coeff_lever * iCom.p_grinding * A_hydraulics + c_spring * (iCom.rho_bulk/iCom.rho) * (iCom.height_sum[iCom.n]- 0.05) + mass_roll*Modelica.Constants.g_n);

  coeff_operation =  iCom.rpm_table * n_rolls * F_grinding / max(Modelica.Constants.small,(iCom.rho_bulk/iCom.rho) * iCom.height_sum[iCom.n]);
  s = s0 .* coeff_operation .* coeff_HGI_offset .* diameter_prtcl.^(mu*coeff_HGI_slope);
  S = diagonal(cat(1,s[1:N_class-1],{0}));  
      ;
end Selection_Steinmetz;

within ClaRa.Components.Mills.PhysicalMills.Volumes.Fundamentals.Grinding.Transport_Velocity;
model Transport_complex "Coal transport velocity depending on pile friction angle"














  extends Transport_base;
protected
  parameter Real coeff_slope = 0.5 "0.3 ... 0.8";  
  parameter ClaRa.Basics.Units.Length delta_radius = iCom.radius_table/n "width of circular ring element";
  parameter Integer n = iCom.n;
public
  parameter ClaRa.Basics.Units.Angle alpha_start_vec[n-1] = alpha_start * linspace(1,0.7,n-1) "";
  ClaRa.Basics.Units.Length delta_height[n-1] "height of (i)th transported volume element";
  ClaRa.Basics.Units.Angle alpha[n-1](start = alpha_start_vec,each fixed=true) "angle auf coal pile between two ring elements";
  ClaRa.Basics.Units.Velocity w_r[n] "radial transport velocity of coal on table due to pile angle";
  ClaRa.Basics.Units.Angle delta_height_crit;
equation
  tan(alpha_crit) = delta_height_crit/delta_radius;
  for i in 1:n-1 loop
    delta_height[i] = iCom.height_sum[i] - iCom.height_sum[i+1];
    tan(alpha[i]) = delta_height[i]/delta_radius;
    w_r[i] = coeff_slope * max(0,delta_height[i] - delta_height_crit) / delta_radius;
  end for;

  w_r[n] = w_r[n-1]
      ;
end Transport_complex;

