model SensorFuel_L1_m_flow "Ideal two port mass flow sensor"
  extends ClaRa.Components.Sensors.FuelSensorBase;
  outer ClaRa.SimCenter simCenter;
  parameter Integer unitOption = 1 "Unit of output" ;
  parameter ClaRa.Basics.Units.MassFlowRate m_flow_ref[2]={0,1} "Reference flow rate [min,max]" ;
  Modelica.Blocks.Interfaces.RealOutput m_flow(
    final quantity="MassFlowRate",
    displayUnit="kg/s",
    final unit="kg/s") "Mass flow rate"          ;
equation
  if unitOption==1 then 
    m_flow = inlet.m_flow;
  elseif unitOption==2 then 
    m_flow = inlet.m_flow*3.6;
