model Convert2StateDiscrete "Converts a flaoting value to a discrete one. Value is changed when a certain threshold is violated"

    extends Modelica.Blocks.Interfaces.SISO;
  parameter Real threshold = 0.1 "Threshold of identification of changes";
  parameter Boolean smoothValue = true "True, if output value should be smoothed using a firstOrder";
  parameter ClaRa.Basics.Units.Time Tau=0.1 "Time constant for smoothing" ;
  discrete Real y_;
  discrete Real py_;
equation
  when abs(pre(y_)-u)>threshold then
    y_=u;
    py_=pre(y_);
  end when;
  if smoothValue then
    der(y) = (y_-y)/Tau;
  else
    y=y_;
  end if;
initial equation
  y_=u;
  if smoothValue then
    y=u;
  end if;
equation
  connect(y, y) 
    ;
end Convert2StateDiscrete;

within ClaRa.Components.Utilities.Blocks;
block DerivativeClaRa "Derivative block ( can be adjusted to behave as ideal or approximated)"
  import Modelica.Blocks.Types.Init;
  parameter Real k(unit="1")=1 "Gain";
  parameter ClaRa.Basics.Units.Time Tau(min=Modelica.Constants.small)=0.01 "Time constant (Tau>0 for approxomated derivative; Tau=0 is ideal derivative block)";
  parameter Integer initOption = 501 "Initialisation option" ;
  parameter Real x_start=0 "Initial or guess value of state"
    ;
  parameter Real y_start=0 "Initial value of output (= state)"
    ;
  extends Modelica.Blocks.Interfaces.SISO(y(start=y_start));
  output Real x(start=x_start) "State of block";
protected
  parameter Boolean zeroGain = abs(k) < Modelica.Constants.eps;
initial equation
  if initOption == 502 then
    der(x) = 0;
  elseif initOption == 799 then 
    x = x_start;
  elseif initOption == 504 then
    if zeroGain then
       x = u;
    else
       y = y_start;
    end if;
  elseif initOption == 501 then

  else
    assert(false, "Unknown init option in derivative instance " + getInstanceName());
  end if;
equation
  der(x) = if zeroGain or Tau < Modelica.Constants.eps then 0 else (u - x)/Tau;
  if zeroGain then
    y=0;
  elseif Tau < Modelica.Constants.eps then
    y=k*der(u);
  else
    y =(k/Tau)*(u - x);
  end if
  ;
end DerivativeClaRa;

