within ClaRa.Components.Utilities.Blocks;
model Noise "Adds a normally distributed noise to a given mean value"
  parameter Real Tau_sample = 1 "Sample period" ;
  parameter Real startTime = 1 "start time moment" ;
  parameter Boolean varMeanValue=false "True, if mean value is time dependent input"
                                                  ;
  parameter Boolean varStandardDeviation=false "True, if standard deviation is time dependent input"
                                                          ;
  parameter Real mean_const= 1 "Constant mean value" ;
  parameter Real stdDev_const= 1 "Constant standard deviation" ;
  parameter Modelica.Units.SI.Time Tau_smooth=Tau_sample/5 "Time constant for smoothing of the random values" ;
protected
  Real seed[3];
  Real y_;
  Real x;
public
  Real m_in;
  Real stdDev_in;
public
  Modelica.Blocks.Interfaces.RealOutput y ;
  Modelica.Blocks.Interfaces.RealInput mean=m_in if (varMeanValue) "Variable mass flow rate"
    ;
  Modelica.Blocks.Interfaces.RealInput sigma=stdDev_in if (varStandardDeviation) "Variable standard deviation"
    ;
algorithm
equation
  if (not varMeanValue) then
    m_in=mean_const;
  end if;
  if (not varStandardDeviation) then
    stdDev_in=stdDev_const;
  end if;
   x=smooth(1,div(time,Tau_sample));
  seed =  {noEvent(smooth(1,x)), noEvent(smooth(1,x)^3), noEvent(smooth(1,x^2))};
  if noEvent(time > startTime) then
    der(y_) =(ClaRa.Components.Utilities.Blocks.Fundamentals.normalvariate(
      m_in,
      stdDev_in,
      seed) - y_)/Tau_smooth;
  else
    der(y_)=(m_in-y_)/Tau_smooth;
  end if;
  der(y)=(y_-y)/Tau_smooth;
initial equation
  y=m_in;
  y_=m_in
  ;
end Noise;

within ClaRa.Components.Utilities.Blocks;
model ParameterizableTable1D "Table look-up in one dimension (matrix/file) with n inputs and n outputs "
  import Modelica.Blocks.Types;
  parameter Boolean tableOnFile=false "true, if table is defined on file or in function usertab"
    ;
  parameter Real table[:, :]=fill(0.0,0,2) "table matrix (grid = first column; e.g., table=[0,2])"
       ;
  parameter String tableName="NoName" "table name on file or in function usertab (see docu)"
       ;
  parameter String fileName="NoName" "file where matrix is stored"
       ;
  parameter Integer columns[:]=2:size(table, 2) "columns of table to be interpolated"
  ;
  parameter Modelica.Blocks.Types.Smoothness smoothness=Types.Smoothness.LinearSegments "smoothness of table interpolation"
  ;
  extends Modelica.Blocks.Interfaces.MIMOs(final n=size(columns, 1));
protected
  Integer tableID;
  function tableInit "Initialize 1-dim. table defined by matrix (for details see: Modelica/Resources/C-Sources/ModelicaTables.h)"
    input String tableName;
    input String fileName;
    input Real table[ :, :];
    input Modelica.Blocks.Types.Smoothness smoothness;
    output Integer tableID;
  external "C" tableID = ModelicaTables_CombiTable1D_init(
                 tableName, fileName, table, size(table, 1), size(table, 2),
                 smoothness) ;
  end tableInit;
  function tableIpo "Interpolate 1-dim. table defined by matrix (for details see: Modelica/Resources/C-Sources/ModelicaTables.h)"
    input Integer tableID;
    input Integer icol;
    input Real u;
    output Real value;
  external "C" value=ModelicaTables_CombiTable1D_interpolate(tableID, icol, u) ;
  end tableIpo;
equation
  if tableOnFile then
    assert(tableName<>"NoName", "tableOnFile = true and no table name given");
  end if;
  if not tableOnFile then
    assert(size(table,1) > 0 and size(table,2) > 0, "tableOnFile = false and parameter table is an empty matrix");
  end if;
  for i in 1:n loop
    y[i] = if not tableOnFile and size(table,1)==1 then
             table[1, columns[i]] else tableIpo(tableID, columns[i], u[i]);
  end for;
  when initial() then
    tableID=tableInit(if tableOnFile then tableName else "NoName",
                      if tableOnFile then fileName else "NoName", table, smoothness);
  end when
  ;
end ParameterizableTable1D;

