  parameter Boolean frictionAtInlet = false "True if pressure loss between first cell and inlet shall be considered" ;
  parameter Boolean frictionAtOutlet = false "True if pressure loss between last cell and outlet shall be considered" ;
  replaceable model PressureLoss = ClaRa.Basics.ControlVolumes.Fundamentals.PressureLoss.Generic_PL.LinearPressureLoss_L4 constrainedby ClaRa.Basics.ControlVolumes.Fundamentals.PressureLoss.PressureLossBaseVLE_L4  "Pressure Loss Model" ;
  replaceable model HeatTransfer = ClaRa.Basics.ControlVolumes.Fundamentals.HeatTransport.Generic_HT.CharLine_L4 constrainedby ClaRa.Basics.ControlVolumes.Fundamentals.HeatTransport.HeatTransferBaseVLE_L4 "Heat Transfer Model" ;
  replaceable model MechanicalEquilibrium = ClaRa.Basics.ControlVolumes.Fundamentals.SpacialDistribution.Homogeneous_L4 "Mechanic Model" ;
  parameter Boolean isAdiabat = false "True if adiabat" ;
  parameter ClaRa.Basics.Units.Length length=47.5 "Length of the pipe (one pass)" ;
  parameter ClaRa.Basics.Units.Length diameter_o=57e-3 "Outer diameter" ;
  parameter ClaRa.Basics.Units.Length diameter_i=49e-3 "Inner diameter of the pipe" ;
  parameter ClaRa.Basics.Units.Length z_in=104.58 "Height of inlet above ground" ;
  parameter ClaRa.Basics.Units.Length z_out=98.83 "Height of outlet above ground" ;
  parameter Integer N_tubes=1050 "Number Of parallel pipes" ;
  parameter Integer N_passes=1 "Number of passes of the tubes" ;
  parameter Integer N_cv=3 "Number of finite volumes" ;
  parameter ClaRa.Basics.Units.Length Delta_x[N_cv]=ClaRa.Basics.Functions.GenerateGrid(
      {0},
      pipeFlow.length*pipeFlow.N_passes,
      pipeFlow.N_cv) "Discretisation scheme" ;
  parameter ClaRa.Basics.Units.Pressure p_nom[N_cv]=ones(N_cv)*1e5 "Nominal pressure" ;
  parameter ClaRa.Basics.Units.EnthalpyMassSpecific h_nom[N_cv]=ones(N_cv)*1e5 "Nominal specific enthalpy for single tube" ;
  parameter ClaRa.Basics.Units.MassFlowRate m_flow_nom=100 "Nominal mass flow w.r.t. all parallel tubes" ;
  parameter ClaRa.Basics.Units.PressureDifference Delta_p_nom=1e4 "Nominal pressure loss w.r.t. all parallel tubes" ;
  parameter Integer initOption=0 "Type of initialisation" ;
  parameter ClaRa.Basics.Units.EnthalpyMassSpecific h_start[N_cv]=ones(N_cv)*800e3 "Initial specific enthalpy for single tube" ;
  parameter ClaRa.Basics.Units.Pressure p_start[N_cv]=ones(N_cv)*1e5 "Initial pressure" ;
  parameter ClaRa.Basics.Units.MassFraction xi_start[medium.nc - 1]=zeros(pipeFlow.medium.nc - 1) "Initial composition" ;
  parameter Boolean showExpertSummary=pipeFlow.simCenter.showExpertSummary "True, if an extended summary shall be shown, else false" ;
  parameter Boolean showData=false "True, if a data port containing p,T,h,s,m_flow shall be shown, else false" ;
  parameter Boolean contributeToCycleSummary=pipeFlow.simCenter.contributeToCycleSummary "True if component shall contribute to automatic efficiency calculation" ;
  parameter Boolean heatFlowIsLoss=true "True if negative heat flow is a loss (not a process product)" ;
  ClaRa.Components.VolumesValvesFittings.Pipes.PipeFlowVLE_L4_Simple pipeFlow(
    medium=medium,
    frictionAtInlet=frictionAtInlet,
    frictionAtOutlet=frictionAtOutlet,
    redeclare model PressureLoss = PressureLoss,
    redeclare model HeatTransfer = HeatTransfer,
    redeclare model MechanicalEquilibrium = MechanicalEquilibrium,
    p_nom=p_nom,
    h_nom=h_nom,
    m_flow_nom=m_flow_nom,
    Delta_p_nom=Delta_p_nom,
    initOption=initOption,
    h_start=h_start,
    p_start=p_start,
    xi_start=xi_start,
    showExpertSummary=showExpertSummary,
    showData=showData,
    length=length,
    diameter_i=diameter_i,
    z_in=z_in,
    z_out=z_out,
    N_tubes=N_tubes,
    N_passes=N_passes,
    N_cv=N_cv,
    Delta_x=Delta_x,
    contributeToCycleSummary=contributeToCycleSummary,
    heatFlowIsLoss=heatFlowIsLoss)
                  ;
  ClaRa.Basics.ControlVolumes.SolidVolumes.CylindricalThinWall_L4 pipeWall(
    redeclare model Material = Material,
    N_ax=N_cv,
    diameter_o=diameter_o,
    diameter_i=diameter_i,
    length=length,
    N_tubes=N_tubes,
    T_start={TILMedia.VLEFluidFunctions.temperature_phxi(
        medium,
        p_start[i],
        h_start[i],
        xi_start) for i in 1:N_cv},
    stateLocation=if isAdiabat then 1 else 2)
                     ;
  ClaRa.Components.Adapters.Scalar2VectorHeatPort adapt(N=N_cv) if not isAdiabat
                                                                ;
  ClaRa.Basics.Interfaces.FluidPortOut outlet(Medium=medium) "Outlet port" ;
  ClaRa.Basics.Interfaces.FluidPortIn inlet(Medium=medium) "Inlet port" ;
  ClaRa.Basics.Interfaces.HeatPort_a heat if not isAdiabat
                                          ;
  ClaRa.Basics.Interfaces.EyeOut eye if showData ;
equation
  connect(pipeFlow.heat, pipeWall.innerPhase) ;
  connect(pipeWall.outerPhase, adapt.heatVector) ;
  connect(pipeFlow.outlet, outlet) ;
  connect(pipeFlow.inlet, inlet) ;
  connect(adapt.heatScalar, heat) ;
  connect(pipeFlow.eye, eye) 
  ;
end TubeBundle_L4H1;

