      0.16; 0.5,0.25; 0.6,0.36; 0.7,0.49; 0.8,0.64; 0.9,0.81; 1,1] "Characteristic line of pressure drop as function of mass flow rate"
                                                                         ;
  parameter Real CharLine_dpIP_mRS_[:,:]=[0,0; 0.1,0.01; 0.2,0.04; 0.3,0.09; 0.4,
      0.16; 0.5,0.25; 0.6,0.36; 0.7,0.49; 0.8,0.64; 0.9,0.81; 1,1] "Characteristic line of pressure drop as function of mass flow rate"
                                                                         ;
parameter Real efficiency_Pump_FW=1 "Efficiency of freshwater pump" ;
parameter Real efficiency_Pump_cond=1 "Efficiency of condenser pump" ;
parameter Real efficiency_Pump_preheat=1 "Efficiency of preheater pump" ;
parameter Real efficiency_Turb_HP=1 "Efficiency of turbine" ;
parameter Real efficiency_Turb_LP=1 "Efficiency of turbine" ;
  parameter Basics.Units.Pressure p_shell_preheater=20700 "Pressure on preheater shell side" ;
