  ClaRa.StaticCycles.ValvesConnects.Valve_dp_nom1 valve_LP(Delta_p_nom=valve_IP_dp_nominal) ;
  ClaRa.StaticCycles.Storage.Feedwatertank3 feedwatertank(p_FWT_nom=p_FWT, m_flow_nom=m_flow_FW) ;
  ClaRa.StaticCycles.ValvesConnects.Valve_dp_nom1 valve_LP1(Delta_p_nom=valve_LP1_dp_nominal) ;
  ClaRa.StaticCycles.Machines.Pump1_real pump_cond(efficiency=efficiency_Pump_cond) ;
  ClaRa.StaticCycles.Machines.Turbine turbine_LP1(efficiency=efficiency_Turb_LP) ;
  ClaRa.StaticCycles.Machines.Turbine turbine_LP2(efficiency=efficiency_Turb_LP) ;
  ClaRa.StaticCycles.Fittings.Split1 split_LP ;
  ClaRa.StaticCycles.Fittings.Split1 split_LP1 ;
  ClaRa.StaticCycles.HeatExchanger.Preheater1 preheater_LP1(p_tap_nom=p_shell_preheater, m_flow_tap_nom=14) ;
  ClaRa.StaticCycles.Machines.Pump1_real pump_preheater(efficiency=efficiency_Pump_preheat) ;
  ClaRa.StaticCycles.Fittings.Mixer1 mixer ;
equation
  connect(boiler.liveSteam, turbine_HP.inlet) ;
  connect(feedwatertank.cond_out, pump_fw.inlet) ;
  connect(pump_cond.inlet, condenser.outlet) ;
  connect(turbine_LP2.outlet, condenser.inlet) ;
  connect(preheater_LP1.cond_in, pump_cond.outlet) ;
  connect(preheater_LP1.tap_in, valve_LP1.outlet) ;
  connect(pump_preheater.inlet, preheater_LP1.tap_out) ;
  connect(mixer.inlet_2, pump_preheater.outlet) ;
  connect(preheater_LP1.cond_out, mixer.inlet_1) ;
  connect(mixer.outlet, feedwatertank.cond_in) ;
  connect(feedwatertank.tap_in, valve_LP.outlet) ;
  connect(turbine_LP.outlet, split_LP.inlet) ;
  connect(turbine_LP1.outlet, split_LP1.inlet) ;
  connect(split_LP1.outlet_1, turbine_LP2.inlet) ;
  connect(split_LP1.outlet_2, valve_LP1.inlet) ;
  connect(split_LP.outlet_2, valve_LP.inlet) ;
  connect(split_LP.outlet_1, turbine_LP1.inlet) ;
  connect(turbine_HP.outlet, boiler.coldReheat) ;
  connect(boiler.hotReheat, turbine_LP.inlet) ;
  connect(pump_fw.outlet, boiler.feedWater) 
    ;
end InitSteamCycle_SimplePowerPlant1;

