  final parameter ClaRa.Basics.Units.EnthalpyMassSpecific h_cond_out=(m_flow_tap*(h_tap_in - h_tap_out) + m_flow_aux*(h_aux - h_tap_out))/m_flow_cond + h_cond_in "Spec. enthalpy at condenate outlet";
