model Scope "Dynamic graphical display of one variable"
  parameter Boolean hideInterface=true "Select for input interface" ;
  input Real inputVar=0 "Input variable (if showInterface=false)" ;
  parameter Real y_min=0 "Choose or guess the minimal value of the y-axis" ;
  parameter Real y_max(min=y_min+Modelica.Constants.eps)=1 "Choose or guess the maximal value of the y-axis"
                                                      ;
  parameter String Unit="[-]" "Unit for plot variable" ;
public
  parameter Modelica.Units.SI.Time t_start=0 "Start time of display" ;
  parameter Modelica.Units.SI.Time t_end=1 "Start time of display" ;
  parameter Modelica.Units.SI.Time t_sample(min=Modelica.Constants.eps) = (t_end - t_start)/100 "Output intervall for plot, use carefully since this creates scalars!" ;
  parameter ClaRa.Basics.Types.Color color={0,131,169} "Line color"         ;
  parameter Modelica.Units.SI.Time Tau_stab=0.01 "Stabilizing time constant, 0 means no stabilisation " ;
protected
  final parameter Real x[N_points] = linspace(1,100,N_points) "x-positions of line points" ;
  Real y[N_points] "y-positions of line points" ;
  final parameter Integer N_points = integer((t_end-t_start)/t_sample+1) "Number of points";
  Real f "Horizontal position of the cover-rectangle" ;
  Real u_in "Value to be displayed";
  Real u_aux "Auxilliary variable";
  Real xy[:,:] = [x,y] ;
public
  Modelica.Blocks.Interfaces.RealInput u = u_aux if not hideInterface "Input signal"
    ;
initial equation
   if Tau_stab>0 then
    u_in=u_aux;
   end if;
equation
  if Tau_stab>0 then
    der(u_in) =  (u_aux-u_in)/Tau_stab;
  else
    u_in= u_aux;
  end if;
   if hideInterface then
     u_aux = inputVar;
   end if;
  for i in 1:N_points loop
    when  time < (i)*t_sample+t_start and time >= (i-1)*t_sample+t_start and sample(t_start,t_sample) then
      y[i] = if u_in < y_min then     (1-(y_max -y_min)/(y_max - y_min))*100 else
                     if u_in > y_max then    (1-(y_max -y_max)/(y_max - y_min))*100 else
                        (1-(y_max -u_in)/(y_max - y_min))*100;
    end when;
  end for;
  f=if time  <= t_start then 0 else if time  >= (t_end-t_start)+t_start then 100 else  (time-t_sample-t_start)*100/(t_end-t_start);
  assert(y_max>=y_min, "Parameter failure: y_max shall be larger than y_min.");
  assert(t_end>t_start, "Parameter failure: t_end shall be larger than t_start")
;
end Scope;

