      Modelica.Mechanics.MultiBody.Interfaces.Frame_a frame_a ;
      Modelica.Mechanics.MultiBody.Interfaces.Frame_b frame_b ;

      Modelica.Mechanics.MultiBody.Parts.BodyCylinder shortSide1(
        r = {0,0,-armParameters.h},
        diameter = armParameters.Dh,
        density = 4*armParameters.Mh/(armParameters.Dh^2*pi*armParameters.h))
        ;

      Modelica.Mechanics.MultiBody.Parts.BodyCylinder shortSide2(
        r = {0,0,-armParameters.h},
        diameter = armParameters.Dh,
        density = 4*armParameters.Mh/(armParameters.Dh^2*pi*armParameters.h))
        ;

      Modelica.Mechanics.MultiBody.Parts.FixedRotation fixedRotation1(animation=false, r={0,0,armParameters.h/2}) ;
      Modelica.Mechanics.MultiBody.Parts.FixedRotation fixedRotation2(animation=false, r={0,0,armParameters.h/2});

equation
    connect(frame_a, fixedRotation1.frame_a) ;
    connect(frame_b, fixedRotation2.frame_a) ;
    connect(fixedRotation1.frame_b, shortSide1.frame_a) ;
    connect(fixedRotation2.frame_b, shortSide2.frame_a) ;

