model CubicTrajectory  "The outputs are three reference values for the three actuators of a Delta robot to follow a line with a cubic eqution of motion"
  extends DeltaRobot.Icons.CubicTrajectory; // Icon
  extends PartialTrajectoryModel;

  //Imports
    import ModelicaServices.Machine.eps;
    import Modelica.Math.Vectors.*;

  //Parameters
    parameter SI.Velocity initialSpeed = 0 "Initial platform speed (direction = stopPosition-startPosition, in base frame)";
    parameter SI.Velocity finalSpeed = 0 "Final platform speed (direction = stopPosition-startPosition, in base frame)";

  //Variables
    SI.Velocity speed[3] "Current speed vector";
    SI.Acceleration acceleration[3] "Current acceleration vector";
    SI.Velocity speedModule "Module of current speed vector";
    SI.Acceleration accelerationModule "Module of current acceleration vector";

protected
    parameter Real initialSpeedVector[3] = initialSpeed*direction;
    parameter Real finalSpeedVector[3] = finalSpeed*direction;

    parameter Real ap[4,3]={startPosition,
                            initialSpeedVector,
                            (-3*(startPosition-stopPosition)-(2*initialSpeedVector+finalSpeedVector)*transitionTime)/transitionTime^2,
                            (2*(startPosition-stopPosition)+(initialSpeedVector+finalSpeedVector)*transitionTime)/transitionTime^3}
                            "Coefficients of the cubic polynomial for position";

  function checkConstraints "Returns true if the position and velocity profiles are correct (no direction changes)"
    //Inputs and outputs
      input Real a[4,3] "Coefficients of the cubic polynomial";
      input SI.Time ti "Initial time";
      input SI.Time tf "Final time";
      output Boolean correct "=true, if the direction of motion doesn't change during the motion";

  protected
      Real A[3] = 3*a[4];
      Real B[3] = 2*a[3]-6*a[4]*ti;
      Real C[3] = a[2]-2*a[3]*ti+3*a[4]*ti^2;
      Real delta[3] = B.^2-4*A.*C;
      Real t1,t2 "Roots of the speed equation of motion, instants when the speed is null";

  algorithm
      correct := true;
      if ti>=tf then
        correct := false; //invalid inputs
      else
        for i in 1:3 loop
          if delta[i]-eps>0 then //if delta[i]<=0 the function position(time) is monotonically increasing/decreasing, no direction changes over all R
            t1 := min(  (-B[i]-sqrt(delta[i]))/(2*A[i]),    (-B[i]+sqrt(delta[i]))/(2*A[i]));
            t2 := max(  (-B[i]-sqrt(delta[i]))/(2*A[i]),    (-B[i]+sqrt(delta[i]))/(2*A[i]));

            if not (tf<=t1+2*eps or (t1-100*eps<=ti and tf<=t2+100*eps) or t2-2*eps<=ti) then
              correct := false;
            end if;
          end if;
        end for;
      end if;
  end checkConstraints;

equation
  assert(checkConstraints(ap,startTime,startTime+transitionTime),
        "CubicTrajectory: WARNING, change in direction during motion", level = AssertionLevel.warning);

  if time<startTime then
      position=startPosition;
      speed={0,0,0};
      acceleration={0,0,0};
      speedModule=0;
      accelerationModule=0;
    elseif time<startTime+transitionTime then
      position=ap[1]+ap[2]*(time-startTime)+ap[3]*(time-startTime)^2+ap[4]*(time-startTime)^3;
      speed=ap[2]+2*ap[3]*(time-startTime)+3*ap[4]*(time-startTime)^2;
      acceleration=2*ap[3]+6*ap[4]*(time-startTime);
      speedModule= if (direction*speed)>0 then norm(speed) else -norm(speed);
      accelerationModule= if (direction*acceleration)>0 then norm(acceleration) else -norm(acceleration);
    else
      position=stopPosition;
      speed={0,0,0};
      acceleration={0,0,0};
      speedModule=0;
      accelerationModule=0;
  end if;

end CubicTrajectory;

within DeltaRobot.ReferenceSignals;

model InverseKinematic "The outputs are the three actuators angles required to have the input position"
  extends DeltaRobot.Icons.InverseKinematic; // Icon

  // Imports
    import ModelicaServices.Machine.eps; //this constant is used to verify if there is a saturation
    import DeltaRobot.Types.*;

  // Parameters
    outer DeltaRobot.Components.GlobalParameters gp "Object with all global parameters";

    parameter DiscParameters base = gp.base "Parameters of the base";
    parameter DiscParameters platform = gp.platform "Parameters of the platform";    
    parameter ArmParameters armParameters = gp.armParameters[1] "Parameters of the arms";

    parameter Boolean limitOutputs = true "=true, if you want to limit the outputs within [minTheta,maxTheta]" ;
    parameter Boolean stopWhenSaturated = true "When a saturation is detected all output signals maintain their current values until all output signals return within the limits" ;
    parameter SI.Angle maxTheta[3] = {gp.armParameters[1].maxTheta, gp.armParameters[2].maxTheta, gp.armParameters[3].maxTheta} "Max actuator angle" ;
    parameter SI.Angle minTheta[3] = {gp.armParameters[1].minTheta, gp.armParameters[2].minTheta, gp.armParameters[3].minTheta} "Min actuator angle" ;

    parameter SI.Time T_velocity(min=Modelica.Constants.small) = 0.01 "Time constants for velocity derivative (T>0 required; T=0 is ideal derivative block)" ;
    parameter SI.Time T_acc(min=Modelica.Constants.small) = 0.1 "Time constants for acceleration derivative (T>0 required; T=0 is ideal derivative block)" ;

  // Variables
    SI.Angle thetaRef[3] "Output before saturation, result of inverse kinematic";
    SI.Angle thetaSat[3] "Output after saturation";
    Boolean saturationFlag "=true, when there is a saturation";
    SI.Angle outputSample[3] "When a saturation is detected this variable saves the last valid output";
    SI.AngularVelocity thetaVelocity[3] "Angles velocities, =der(theta)";
    SI.AngularAcceleration thetaAcceleration[3] "Legs accelerations, =der(thetaVelocity)";

  Modelica.Blocks.Interfaces.RealOutput theta[3] "Actuators angles for the input position" ;
  Modelica.Blocks.Nonlinear.Limiter limiter[3](uMax={maxTheta[1],maxTheta[2],maxTheta[3]}, uMin={minTheta[1],minTheta[2],minTheta[3]}) ;

  Modelica.Blocks.Continuous.Derivative posDerivative[3](each T=T_velocity, each initType=Modelica.Blocks.Types.Init.InitialOutput) ;
  Modelica.Blocks.Continuous.Derivative velDerivative[3](each T=T_acc, each initType=Modelica.Blocks.Types.Init.InitialOutput) ;

  Interfaces.Pose pose ;
  Modelica.Blocks.Routing.RealPassThrough realPassThrough[3] ;

initial equation
  outputSample = thetaRef;

equation
  assert(maxTheta[1]>=minTheta[1] and maxTheta[2]>=minTheta[2] and maxTheta[3]>=minTheta[3],"InverseKinematic: Limits must be consistent. However minTheta>maxTheta.");

  thetaRef = DeltaRobot.Functions.inverseKinematic(realPassThrough.y,armParameters.L,armParameters.l,base.D,platform.D,base.beta); //nresolve inverse kinematic

  limiter.u=thetaRef; //napply saturation
  thetaSat=limiter.y;

  if thetaRef[1]-eps>thetaSat[1] or thetaRef[2]-eps>thetaSat[2] or thetaRef[3]-eps>thetaSat[3] or
     thetaRef[1]+eps<thetaSat[1] or thetaRef[2]+eps<thetaSat[2] or thetaRef[3]+eps<thetaSat[3] 
  then                                                                                                        
    saturationFlag=true; // check if there was a saturation
  else
    saturationFlag=false;
  end if;

  when saturationFlag then // immidiatly after a saturation save the last output
    outputSample=thetaSat;
  end when;

  if limitOutputs == true then

    if stopWhenSaturated and saturationFlag then // Select the output based on the parameters and possible saturations
        theta=outputSample;
    else
        theta=thetaSat;
    end if;

  else
    theta=thetaRef;
  end if;

  posDerivative.u=theta; // compute the output derivatives with appropriate blocks
  thetaVelocity=posDerivative.y;

  velDerivative.u=thetaVelocity;
  thetaAcceleration=velDerivative.y;

  connect(realPassThrough.u, pose.position) ;

end InverseKinematic;

