  parameter SI.Time startTime = 0 "speedRef = 0, for time<startTime";
  parameter SI.Time deltaTime = 0 "Time between two repetitions of the reference speeds";
  parameter Real k = 1000*7.11/1500 "Gain";
  parameter String tableName = "Speeds";
  parameter String fileName = Modelica.Utilities.Files.loadResource("modelica://DeltaRobot/DataTables/SpeedCommand.txt");

  // Variables
  SI.AngularVelocity speed[3];

  // Models
  Modelica.Blocks.Sources.CombiTimeTable combiTimeTable1(
      table=fill(0.0, 0, 5),
      tableOnFile=true,
      tableName=tableName,
      columns=2:4,
      fileName=fileName,
      startTime=startTime) 
    ;

  Modelica.Blocks.Interfaces.RealOutput speedRef[3] "reference speeds in rad/s" ;

  Modelica.Blocks.Math.Gain gain[3](each k=k) ;

  Modelica.Blocks.Sources.CombiTimeTable combiTimeTable2(
      table=fill(0.0, 0, 5),
      tableOnFile=true,
      tableName=tableName,
      columns=2:4,
      fileName=fileName,
      startTime=startTime + combiTimeTable1.t_max + deltaTime)
    ;

  Modelica.Blocks.Sources.CombiTimeTable combiTimeTable3(
      table=fill(0.0, 0, 5),
      tableOnFile=true,
      tableName=tableName,
      columns=2:4,
      fileName=fileName,
      startTime=startTime + combiTimeTable1.t_max + combiTimeTable2.t_max + 2*deltaTime)
    ;

  Modelica.Blocks.Math.Sum sumX(nin=3) ;
  Modelica.Blocks.Math.Sum sumY(nin=3) ;
  Modelica.Blocks.Math.Sum sumZ(nin=3) ;

