  connect(combiTimeTable3.y[1], sumX.u[3]) ;
  connect(combiTimeTable1.y[2], sumY.u[1]) ;
  connect(combiTimeTable2.y[2], sumY.u[2]) ;
  connect(combiTimeTable3.y[2], sumY.u[3]) ;
  connect(combiTimeTable1.y[3], sumZ.u[1]) ;
  connect(combiTimeTable2.y[3], sumZ.u[2]) ;
  connect(combiTimeTable3.y[3], sumZ.u[3]) ;
  connect(sumX.y, gain[1].u) ;
  connect(sumY.y, gain[2].u) ;
  connect(sumZ.y, gain[3].u) 
  ;
end SpeedCommand;

