within DroneLibrary.Mechanical.Motor.Variants;
model DCMotor_DCPM "DC motor using DC machine from MSL"
extends DroneLibrary.Mechanical.Motor.Templates.DCMotor_Power;
  parameter Real k=-1
    "Propeller gain. Set to 1 for clockwise, -1 for counterclockwise";
