  parameter Modelica.Units.SI.Voltage V "Battery voltage";

  parameter Modelica.Units.SI.Resistance R=100
    "Resistance at temperature T_ref";
  Electrical.Sources.PowerControl powerControl(V=V, R=R) ;
  Modelica.Mechanics.Rotational.Sensors.MultiSensor multiSensor ;
  Modelica.Mechanics.MultiBody.Forces.WorldForce force(
    animation=false,
    color={244,0,4},
