    ;
  connect(gain1.y,realExtend1. u)
    ;
  connect(realExtend.y,force. force) ;
  connect(realExtend1.y,torque. torque)
    ;
  connect(gain1.u, multiSensor.tau) ;
  connect(multiSensor.flange_a, dcpm.flange)
    ;
  connect(fixed.flange, multiSensor.flange_b)
    ;
  connect(realExtend.u, thrust.y)
    ;
  connect(force_out, force.frame_b) ;
  connect(torque_1, torque.frame_b) ;
  connect(torque_2, torque.frame_a) ;
  connect(position, limiter.u) ;
  connect(p1, powerControl.Battery) 
  ;
end DCMotor_DCPM;

