  connect(torque.frame_a, force.frame_b) ;
  connect(torque.frame_b, bodyShape4.frame_a) ;
  connect(force.frame_b, frame_a) ;
  connect(relativeAngularVelocity.frame_a, force.frame_b) ;
  connect(relativeAngularVelocity.frame_b, bodyShape4.frame_a) ;
  connect(torque1.frame_a, force.frame_b) ;
  connect(torque1.frame_b, bodyShape4.frame_a) ;
  connect(relativeAngularVelocity.w_rel, realExtract.u)
    ;
