    ;
  connect(gain.y, realExtend2.u)
    ;
  connect(realExtend2.y, torque1.torque) ;
  connect(gain1.y, realExtend1.u)
    ;
  connect(dCmotor.force, gain1.u) ;
  connect(realExtend1.y, torque.torque) ;
  connect(realExtend.y, force.force) ;
  connect(dCmotor.torque, realExtend.u) ;
  connect(dCmotor.current, limiter.y)
    ;
  connect(position, limiter.u)

  ;
