  Modelica.Electrical.Polyphase.Sources.SignalVoltage signalV ;
  Modelica.Mechanics.Rotational.Sensors.SpeedSensor speedSensor ;
  Modelica.Electrical.Polyphase.Sensors.CurrentSensor iUp ;
  Modelica.Mechanics.Rotational.Components.Inertia inertia(J = 0.5, w(fixed=
          true, start=0))                                           ;
  EHPTlib.ElectricDrives.ASMArelated.ControlLogic logic(Rr = aimc.Rr, Rs = aimc.Rs, wmMax = 314.16 / 2, uBase = 100 * sqrt(3), Lstray = aimc.Lssigma + aimc.Lrsigma, pp = aimc.p) ;
  EHPTlib.ElectricDrives.ASMArelated.GenSines genSines ;
  Modelica.Blocks.Sources.Trapezoid tqReq(amplitude = 150, falling = 2, offset = 50, period = 100, rising = 2, startTime = 2, width = 3) ;
  Modelica.Mechanics.Rotational.Sources.QuadraticSpeedDependentTorque tqRes(tau_nominal = -150, w_nominal = 157.08) ;
equation
  connect(speedSensor.flange, inertia.flange_b) ;
  connect(inertia.flange_b, tqRes.flange) ;
  connect(logic.Tstar, tqReq.y) ;
  connect(genSines.Westar, logic.Westar) ;
  connect(genSines.U, signalV.v) ;
  connect(genSines.Ustar, logic.Ustar) ;
  connect(terminalBox.plug_sn, aimc.plug_sn) ;
  connect(terminalBox.plug_sp, aimc.plug_sp) ;
  connect(iUp.plug_n, terminalBox.plugSupply) ;
  connect(inertia.flange_a, aimc.flange) ;
  connect(ground.p, star.pin_n) ;
  connect(signalV.plug_n, star.plug_p) ;
  connect(pUp.pc, signalV.plug_p) ;
  connect(iUp.plug_p, pUp.nc) ;
  connect(logic.Wm, speedSensor.w) 
  ;
end tqFollowing;

