within EHPTexamples.PSD;
model PSecu1 "Full Power Split Device power train using Map-Based components"
  import Modelica.Constants.*;
  extends Modelica.Icons.Example;
  parameter Modelica.Units.SI.AngularVelocity wIceStart = 50;
  Modelica.Units.SI.Energy EbatDel(start=0, fixed=true) "energy delivered by the battery";
  Modelica.Units.SI.Energy EgenDelM( start=0, fixed=true)
                                                         "energy delivered by gen trough mechanical flange";
  Modelica.Units.SI.Energy Eroad(start=0, fixed=true) "mechanical energy absorbed by roas (friction & air)";
  Modelica.Units.SI.Energy EiceDel(start=0, fixed=true) "mechanical energy delivered by ice";
  Modelica.Units.SI.Energy Emot(start=0, fixed=true);
  Modelica.Units.SI.Energy Emass;
  Modelica.Mechanics.Rotational.Components.IdealPlanetary PSD(ratio = 78 / 30) ;
  Modelica.Mechanics.Rotational.Components.IdealGear idealGear(ratio = 3.905, flange_b(
        phi(start=0, fixed=true)))                                            ;
  Modelica.Mechanics.Translational.Sensors.SpeedSensor carVel ;
  Modelica.Mechanics.Translational.Components.Mass mass(v(fixed = true, start = 0), m = 1300) ;
  EHPTlib.SupportModels.Miscellaneous.DragForce dragForce(fc = 0.014, rho = 1.226, S = 2.2, Cx = 0.26, m = mass.m) ;
  EHPTlib.MapBased.IceConnP ice(flange_a(phi(start=0, fixed=true)))
                                ;
  EHPTlib.SupportModels.Miscellaneous.Batt1Conn bat(ECellMin = 0.9, ECellMax = 1.45, R0Cell = 0.0003, ns = 168, QCellNom = 2 * 6.5 * 3600.0, SOCInit = 0.6, ICellMax = 1e5, iCellEfficiency = 15 * 6.5) ;
  EHPTlib.SupportModels.ConnectorRelated.Conn d ;
  EHPTlib.MapBased.ECUs.Ecu1 ECU(genLoopGain = 1.0) ;
  EHPTlib.MapBased.TwoFlangeConn mot(effTableName = "motEffTable", mapsFileName = Modelica.Utilities.Files.loadResource("modelica://EHPTexamples/Resources/PSDmaps.txt"), mapsOnFile = true) ;
  Modelica.Mechanics.Rotational.Components.IdealRollingWheel wheel(radius = 0.31) ;
  Modelica.Electrical.Analog.Basic.Ground ground ;
  EHPTlib.MapBased.OneFlangeConn gen ;
  EHPTlib.SupportModels.Miscellaneous.PropDriver driver(CycleFileName = Modelica.Utilities.Files.loadResource("modelica://EHPTexamples/Resources/NEDC.txt"), k = 1, yMax = 1.8) ;
equation
  connect(ECU.tauRef, driver.tauRef) ;
  connect(carVel.v, driver.V) ;
  connect(mot.conn1, ECU.conn1) ;
  connect(gen.pin_p, bat.p) ;
  connect(gen.pin_n, bat.n) ;
  connect(gen.flange_a, PSD.sun) ;
  connect(gen.conn, ECU.conn1) ;
  connect(ground.p, bat.n) ;
  connect(wheel.flangeT, mass.flange_a) ;
  connect(wheel.flangeR, idealGear.flange_b) ;
  connect(PSD.ring, mot.flange_a) ;
  connect(idealGear.flange_a, mot.flange_b) ;
  connect(mot.pin_p, bat.p) ;
  connect(mot.pin_n, bat.n) ;
  connect(bat.conn, ECU.conn1) ;
  connect(ice.conn, ECU.conn1) ;
  connect(ECU.conn1, d) ;
  der(EbatDel) = (bat.p.v - bat.n.v) * bat.n.i;
  der(EgenDelM) = gen.pin_p.i * (gen.pin_p.v - gen.pin_n.v) + gen.flange_a.tau * der(gen.flange_a.phi);
  der(Eroad) = dragForce.flange.f * der(dragForce.flange.s);
  der(EiceDel) = -ice.flange_a.tau * der(ice.flange_a.phi);
  der(Emot) = mot.flange_a.tau * der(mot.flange_a.phi) + mot.flange_b.tau * der(mot.flange_b.phi);
  Emass = 0.5 * mass.m * der(mass.flange_a.s) ^ 2;
  connect(PSD.carrier, ice.flange_a) ;
  connect(dragForce.flange, mass.flange_b) ;
  connect(carVel.flange, mass.flange_b) 
  ;
end PSecu1;

