within EHPTlib.ElectricDrives.ASMArelated;
block ControlLogic "Follows upper fig. 12.15 from FEPE Book"
  import Modelica.Constants.pi;
  parameter Modelica.Units.SI.Resistance Rr(start=0.04)
    "Rotor resistance";
  parameter Modelica.Units.SI.Resistance Rs(start=0.03)
    "Stator resistance";
  parameter Modelica.Units.SI.Voltage uBase(start=400)
    "Base phase-to-phase RMS voltage";
  parameter Modelica.Units.SI.AngularVelocity weBase=314.16
    "Base electric frequency";
  parameter Modelica.Units.SI.Inductance Lstray(start=0.2036/weBase)
    "Combined stray inductance";
  parameter Modelica.Units.SI.AngularVelocity wmMax=314.16
    "Maximum mechanical Speed";
  parameter Integer pp(min = 1, start = 2) "number of pole pairs (Integer)";
  //La seguente keyword final consente fra l'altro di far scomparire questi parametri dalla maschera.
  final parameter Real Kw(fixed = true) = uBase / sqrt(3) / (weBase / pp) "Ratio U/Wmecc";
  Modelica.Blocks.Interfaces.RealInput Wm ;
  Modelica.Blocks.Interfaces.RealOutput Ustar ;
  Modelica.Blocks.Interfaces.RealInput Tstar ;
  Modelica.Blocks.Math.Add add ;
  Modelica.Blocks.Nonlinear.Limiter limWm(uMax=wmMax, uMin=uBase/sqrt(3)/
        100/Kw,
    homotopyType=Modelica.Blocks.Types.LimiterHomotopy.Linear)
    ;
  Modelica.Blocks.Interfaces.RealOutput Westar ;
  ASMArelated.TorqueToDW tauToDW(Rr = Rr, pp = pp, Kw = Kw, Lstray = Lstray, wmBase = weBase / pp) ;
  Modelica.Blocks.Math.Gain gain(k = pp) ;
  Modelica.Blocks.Math.Add add1(k1 = Rs, k2 = Kw) ;
  Modelica.Blocks.Nonlinear.Limiter limU(uMax = uBase / sqrt(3), uMin = 0) ;
  Modelica.Blocks.Logical.GreaterThreshold toWeakening(threshold = limU.uMax) ;
  Modelica.Blocks.Logical.GreaterThreshold toMaxSpeed(threshold = limWm.uMax) ;
  Modelica.Blocks.Sources.RealExpression toIstar(y = sqrt(abs(Tstar * tauToDW.y / (3 * Rs)))) ;
equation
  connect(toMaxSpeed.u, limWm.u) ;
  connect(limWm.u, add.y) ;
  connect(Tstar, tauToDW.u) ;
  connect(tauToDW.y, add.u1) ;
  connect(add.u2, Wm) ;
  connect(Westar, gain.y) ;
  connect(gain.u, limWm.y) ;
  connect(add1.y, limU.u) ;
  connect(limU.y, Ustar) ;
  connect(tauToDW.Wm, Wm) ;
  connect(add1.u2, limWm.y) ;
  connect(toWeakening.u, limU.u) ;
  connect(toIstar.y, add1.u1) 
  ;
end ControlLogic;

within EHPTlib.ElectricDrives.ASMArelated;
model DWToI "Delta Omega to I"
  // follows eq. 12.13 from FEPE Book
  parameter Modelica.Units.SI.Resistance Rr
    "rotor resistance in stato units";
  parameter Integer pp "pole pairs";
  parameter Real Kw "constant Komega of FEPE Book";
  parameter Modelica.Units.SI.Current iMax "maximum calue of rms current";
  parameter Modelica.Units.SI.Inductance Lstray
    "combined stray inductance";
  Modelica.Units.SI.Current I "current before limitation";
  Modelica.Blocks.Interfaces.RealInput u ;
  Modelica.Blocks.Interfaces.RealOutput y ;
  Modelica.Blocks.Sources.RealExpression I_(y = I) ;
  Modelica.Blocks.Nonlinear.Limiter limiter(uMax = iMax, uMin = 0) ;
equation
  I = sqrt(u ^ 2 * Kw ^ 2 / ((pp * u * Lstray) ^ 2 + Rr ^ 2));
  connect(I_.y, limiter.u) ;
  connect(y, limiter.y) 
  ;
end DWToI;

within EHPTlib.ElectricDrives.ASMArelated;
block GenSines "Generates three-phase sine waves"
  import Modelica.Constants.pi;
  Modelica.Blocks.Interfaces.RealInput Westar ;
  Modelica.Blocks.Interfaces.RealOutput U[3] ;
  Modelica.Blocks.Interfaces.RealInput Ustar "RMS phase" ;
  Modelica.Blocks.Math.Add add1[3] ;
  Modelica.Blocks.Math.Sin sin[3] ;
  Modelica.Blocks.Continuous.Integrator integrator ;
  Modelica.Blocks.Routing.Replicator replicator(nout = 3) ;
  Modelica.Blocks.Math.Product product[3] ;
  Modelica.Blocks.Math.Gain ToPeak(k = sqrt(2)) ;
  Modelica.Blocks.Sources.Constant phase[3](k = 2 * pi / 3 * {0, -1, 1}) ;
  Modelica.Blocks.Routing.Replicator replicator1(nout = 3) ;
equation
  connect(sin.u, add1.y) ;
  connect(product.y, U) ;
  connect(product.u2, replicator.y) ;
  connect(ToPeak.y, replicator.u) ;
  connect(sin.y, product.u1) ;
  connect(add1.u1, replicator1.y) ;
  connect(add1.u2, phase.y) ;
  connect(replicator1.u, integrator.y) ;
  connect(integrator.u, Westar) ;
  connect(ToPeak.u, Ustar) 
  ;
end GenSines;

within EHPTlib.ElectricDrives.ASMArelated;
model TorqueToDW "Torque to Delta Omega"
  parameter Modelica.Units.SI.Resistance Rr
    "Rotor resistance in stato units";
  parameter Integer pp "Pole pairs";
  parameter Real Kw "Constant Komega of FEPE Book";
  parameter Modelica.Units.SI.AngularVelocity wmBase=314.16
    "Base electric frequency";
  parameter Modelica.Units.SI.Inductance Lstray
    "Combined stray inductance";
  //The following is 12.11 of FEPE book, when U1=Kw*W (LS stands for low speed)
  Modelica.Units.SI.Torque Tmax;
public
  Modelica.Blocks.Interfaces.RealInput u ;
  Modelica.Blocks.Interfaces.RealOutput y ;
  Modelica.Blocks.Interfaces.RealInput Wm ;
  Modelica.Blocks.Interfaces.BooleanOutput tauIsMax ;
equation
  if Wm < wmBase then
    Tmax = 3 * Kw ^ 2 / (2 * pp * Lstray);
  else
    //The following is 12.11 of FEPE book
    Tmax = 3 * (Kw * wmBase) ^ 2 / (2 * pp * Wm ^ 2 * Lstray);
  end if;
  //Se la coppia richiesta supera la massima mi attesto al deltaW
  //che corrisponde al picco di coppia
  if u > Tmax then
    Tmax = 3 * Rr * y * Kw ^ 2 / ((pp * y * Lstray) ^ 2 + Rr ^ 2);
    //    y = Rr / (pp*Lstray);
    tauIsMax = true;
  elseif u < (-Tmax) then
    -Tmax = 3 * Rr * y * Kw ^ 2 / ((pp * y * Lstray) ^ 2 + Rr ^ 2);
    //    y = -Rr / (pp * Lstray);
    tauIsMax = true;
  else
    /* La seguente riga è eq. 12.14 di FEPE Book. Naturalmente essa 
        determina una richiesta di coppia corretta a pieno flusso, zona nella quale 
        vale la 12.14, mentre è approssimata in deflussaggio. Peraltro essendo 
        normalmente il controllo in velocità in retroazione, in questo modello 
        semplificato si accetta questo tipo di delta_omega, che determina una 
        potenza decrescente invece che costante come potrebbe essere.       
      */
    u = 3 * Rr * y * Kw ^ 2 / ((pp * y * Lstray) ^ 2 + Rr ^ 2);
    /*  Si potrebbe completare il controllo facendo in modo che al di sopra della 
        velocità base si applichi la formula 12.10 di FEPE in cui U1=Kw*wmBase.
        Al posto di W0 si può mettere Wm+y.
        Le formule si complicano e quindi per ragioni didattiche non lo facciamo.

        Si riporta comunque qui sotto un'implementazione provvisoria con coppia 
        valida in tutte le regioni, da ultimare e verificare:
        */
    //u=3*(Kw*wmBase)^2*Rr*y/(y^2*pp^2*(Wm+y)^2*Lstray^2+Rr^2*(Wm+y));
    tauIsMax = false;
  end if
  ;
end TorqueToDW;

within EHPTlib.ElectricDrives.SMArelated;
model FromPark "Semplice PMM con modello funzionale inverter"
  parameter Integer p "Number or pole pairs";
  Modelica.Electrical.Machines.SpacePhasors.Blocks.FromSpacePhasor fromSpacePhasor ;
  Modelica.Electrical.Machines.SpacePhasors.Blocks.Rotator rotator ;
  Modelica.Blocks.Routing.Multiplex2 multiplex2_1 ;
