model Genset "GenSet GMS+GEN+SEngine"
  import Modelica.Constants.inf;
  import Modelica.Constants.pi;
  parameter Real gsRatio = 2 "IdealGear speed reduction factor";
  parameter String mapsFileName = "maps.txt" "File containing data maps (maxIceTau, gensetDriveEffTable, specificCons, optiSpeed)";
  parameter Modelica.Units.SI.AngularVelocity maxGenW=1e6
    "Max generator angular speed";
  parameter Modelica.Units.SI.Torque maxTau=200
    "Max mechanical torque between internal ICE and generator";
  parameter Modelica.Units.SI.Power maxPow=20e3
    "Max mechanical of the internal generator";
  parameter Modelica.Units.SI.AngularVelocity wIceStart=167;
  Modelica.Mechanics.Rotational.Sensors.SpeedSensor speedSensor ;
  Modelica.Mechanics.Rotational.Sensors.PowerSensor IcePow ;
  Modelica.Blocks.Interfaces.RealInput powRef(unit = "W") "Reference genset power" ;
  Modelica.Electrical.Analog.Interfaces.PositivePin pin_p ;
  Modelica.Electrical.Analog.Interfaces.NegativePin pin_n ;
  Modelica.Blocks.Nonlinear.Limiter limiter(uMax = inf, uMin = 0) ;
  ECUs.GMS myGMS(mapsFileName = mapsFileName) ;
  EHPTlib.MapBased.OneFlange gen(
    wMax=maxGenW,
    mapsFileName=mapsFileName,
    mapsOnFile=true,
    powMax=maxPow,
    tauMax=maxTau,
    effTableName="gensetDriveEffTable") ;
  IceT01 mBiceT(tablesOnFile = true, mapsFileName = mapsFileName, wIceStart = wIceStart) ;
  Modelica.Blocks.Math.Gain gain(k = -1) ;
  Modelica.Blocks.Math.Gain gain1(k = 1) ;
  Modelica.Blocks.Continuous.Integrator toGrams(k = 1 / 3600) ;
  Modelica.Mechanics.Rotational.Components.IdealGear idealGear(ratio = gsRatio) ;
equation
  connect(gen.pin_p, pin_n) ;
  connect(gain.y, gen.tauRef) ;
  connect(gen.pin_n, pin_p) ;
  connect(IcePow.flange_b, gen.flange_a) ;
  connect(gain1.u, speedSensor.w) ;
  connect(myGMS.Wmecc, gain1.y) ;
  connect(limiter.u, powRef) ;
  connect(limiter.y, myGMS.pRef) ;
  connect(mBiceT.nTauRef, myGMS.throttle) ;
  connect(speedSensor.flange, mBiceT.flange_a) ;
  connect(gain.u, myGMS.tRef) ;
  connect(toGrams.u, mBiceT.fuelCons) ;
  connect(idealGear.flange_a, mBiceT.flange_a) ;
  connect(idealGear.flange_b, IcePow.flange_a) 
  ;
end Genset;

