  connect(limiter.y, gms.pRef) ;
  connect(speedSensor.w, gms.Wmecc) ;
  connect(limiter.u, powRef) ;
  connect(speedSensor.flange, idealGear.flange_a) ;
  connect(toGrams.u, mbIce.fuelCons) 
  ;
