within EHPTlib.SupportModels.MapBasedRelated;
block LimTau "Torque limiter"
  Modelica.Blocks.Interfaces.RealInput w ;
  Modelica.Blocks.Interfaces.RealOutput yH ;
  parameter Modelica.Units.SI.Power powMax=50000
    "Maximum mechanical power";
  parameter Modelica.Units.SI.Torque tauMax=400 "Maximum torque ";
  parameter Modelica.Units.SI.AngularVelocity wMax= 1500 "Maximum speed";
  Integer state "=0 below base speed; =1 before wMax; =2 in w limit, =3 above wMax";
  //0 or 1 if tauMax or powMax is delivered; =2 or 3 if w>wMax
protected
  parameter Real alpha = 0.10 "fraction of wMax over which the torque is to be brought to zero";
public
  Modelica.Blocks.Interfaces.RealOutput yL ;
algorithm
  if w < powMax / tauMax then
    state := 0;
    yH := tauMax;
  else
    state := 1;
    yH := powMax / w;
  end if;
  //over wMax the torque max is to be rapidly brought to zero
  if w > wMax then
    if w < (1 + alpha) * wMax then
      state := 2;
      yH := powMax / wMax * (1 - (w - wMax) / (alpha * wMax));
    else
      state := 3;
      yH := 0;
    end if;
  end if;
  yL := -yH
  ;
end LimTau;

within EHPTlib.SupportModels.MapBasedRelated;
block LimTorque "Torque limiter"
  Modelica.Blocks.Interfaces.RealInput w ;
  Modelica.Blocks.Interfaces.RealOutput yH ;
  parameter Boolean limitsOnFile = false "= true, if max torque is taken from a txt file";
  parameter Modelica.Units.SI.Power powMax=50000
    "Maximum mechanical power"
    ;
  parameter Modelica.Units.SI.Torque tauMax=400 "Maximum torque"
    ;
  parameter Modelica.Units.SI.AngularVelocity wMax= 1500 "Maximum speed" ;
  parameter String limitsFileName = "noName" "File where matrix is stored" ;
  parameter String maxTorqueTableName = "noName" "Name of the on-file maximum torque as a function of speed" ;
  parameter String minTorqueTableName = "noName" "Name of the on-file minimum torque as a function of speed" ;
  Integer state "=0 below base speed; =1 before wMax; =2 in w limit, =3 above wMax";
  //0 or 1 if tauMax or powMax is delivered; =2 or 3 if w>wMax; -1 if limitsOnFile
  Real yHidealised "valore del limite di coppia in caso di curve idealizzate (T cost. sotto la velocità base, P cost. sopra)";
protected
  parameter Real alpha = 0.10 "fraction of wMax over which the torque is to be brought to zero";
public
  Modelica.Blocks.Interfaces.RealOutput yL ;
  Modelica.Blocks.Tables.CombiTable1Ds toMaxTq(tableOnFile = limitsOnFile, table = [0, 0; 1, 1; 2, 4], tableName = maxTorqueTableName, fileName = limitsFileName, smoothness = Modelica.Blocks.Types.Smoothness.MonotoneContinuousDerivative2, extrapolation = Modelica.Blocks.Types.Extrapolation.LastTwoPoints) ;
  Modelica.Blocks.Tables.CombiTable1Ds toMinTq(tableOnFile = limitsOnFile, table = [0, 0; 1, 1; 2, 4], tableName = minTorqueTableName, fileName = limitsFileName, smoothness = Modelica.Blocks.Types.Smoothness.MonotoneContinuousDerivative2, extrapolation = Modelica.Blocks.Types.Extrapolation.LastTwoPoints) ;
  Modelica.Blocks.Math.UnitConversions.To_rpm to_rpm ;
algorithm
  if w < powMax / tauMax then
    state := 0;
    yHidealised := tauMax;
  else
    state := 1;
    yHidealised := powMax / w;
  end if;
  //over wMax the torque max is to be rapidly brought to zero
  if w > wMax then
    if w < (1 + alpha) * wMax then
      state := 2;
      yHidealised := powMax / wMax * (1 - (w - wMax) / (alpha * wMax));
    else
      state := 3;
      yHidealised := 0;
    end if;
  end if;
  if limitsOnFile then
    state := -1;
  end if;
equation
  if limitsOnFile then
    yH = toMaxTq.y[1];
    yL = toMinTq.y[1];
  else
    yH = yHidealised;
    yL = -yHidealised;
  end if;
  connect(w, to_rpm.u) ;
  connect(toMaxTq.u, toMinTq.u) ;
  connect(to_rpm.y, toMinTq.u) 
  ;
end LimTorque;

