within FluxTubesExtension;
package TestRecordFunctionInput "Test records as inputs of functions"
  extends Modelica.Icons.InternalPackage;

  package Examples
  extends Modelica.Icons.ExamplesPackage;
    model ShowSoftMagneticCharacteristic
      "Show characteristic of SoftMagnetic material"
      extends Modelica.Icons.Example;
      SI.MagneticFieldStrength H=-25E3 + 50E3*time
        "Magnetic field strength";
      parameter Material.BaseData material(
        N=4,
        Hk={250, 700, 3500, 16000},
        Bk={1.0, 1.4, 1.59, 1.8});
      SI.MagneticFluxDensity B=Material.BH_Approx(material, H)
        "Magnetic flux density";
      Real der_B(unit="T/s")=der(B)
        "Derivative of magnetic flux density"
        ;
    end ShowSoftMagneticCharacteristic;
  end Examples;

  package Material
    extends Modelica.Icons.MaterialPropertiesPackage;


    record BaseData "Coefficients for approximation of soft magnetic materials with piecewise linear interpolation"
      extends Modelica.Icons.Record;
      parameter String label="SoftMagnetic" "Name of material";
      parameter SI.RelativePermeability mu_i=Bk[1]/(mu_0*Hk[1])
        "Initial relative permeability at B=0";
      parameter Integer N=1 "Count of nodes";
      parameter SI.MagneticFieldStrength Hk[N]={0} "Field strength coefficients";
      parameter SI.MagneticFluxDensity Bk[N]={0} "Flux density coefficients"
      ;
    end BaseData;

    function BH_Approx "Piecewise linear B(H) interpolation"
      extends Modelica.Icons.Function;

      input BaseData material "Material specific parameters";
      input SI.MagneticFieldStrength H "Field strength in ferromagnetic flux tube element";

      output SI.MagneticFluxDensity B "Flux density in ferromagnetic flux tube element";

    protected
      Integer k=findInterval(material.Hk, H);
    algorithm
      B := if k<=1 then material.Bk[1]/material.Hk[1]*H else
           sign(H)*(material.Bk[k-1] + (material.Bk[k] - material.Bk[k-1])/(material.Hk[k] - material.Hk[k-1])*(abs(H) - material.Hk[k-1]))
      ;
    end BH_Approx;

    function derBH_Approx "Piecewise linear der_B(H) interpolation"
      extends Modelica.Icons.Function;

      input BaseData material "Material specific parameters";
      input SI.MagneticFieldStrength H "Field strength in ferromagnetic flux tube element";
      input Real der_H(unit="A/(m.s)") "Derivative of field strength in ferromagnetic flux tube element";

      output Real der_B(unit="T/s") "Derivative of flux density in ferromagnetic flux tube element";

    protected
      Integer k=findInterval(material.Hk, H);
    algorithm
      der_B := if k<=1 then material.Bk[1]/material.Hk[1]*der_H else
               (material.Bk[k] - material.Bk[k-1])/(material.Hk[k] - material.Hk[k-1])*der_H;
    end derBH_Approx;

    function findInterval "Find interval for piecewise linear interpolation"
      extends Modelica.Icons.Function;
      input SI.MagneticFieldStrength Xk[:] "Nodes";
      input SI.MagneticFieldStrength x "Value to find interval";
      output Integer k "Interval Xk[k-1]..Xk[k]";
    protected
      Integer n=size(Xk, 1);
    algorithm
      k:=1;
      while abs(x)>=Xk[k] loop
        k:=k+1;
        if k>n then
          k:=n;
          break;
        end if;
      end while;
    end findInterval

  ;


  end Material
  ;
end TestRecordFunctionInput;

within FluxTubesExtension.BaseClasses;
partial model FixedShape
  "Base class for flux tubes with fixed shape during simulation; linear or non-linear material characteristics"

  extends Modelica.Magnetic.FluxTubes.Interfaces.TwoPort;

  parameter Boolean nonLinearPermeability=true
    "= true, if non-linear rel. permeability is used, otherwise constant rel. permeability"
    ;
  parameter SI.RelativePermeability mu_rConst=1
    "Constant relative permeability; used if nonLinearPermeability = false"
    ;
  parameter FluxTubesExtension.Material.BaseSoftMagneticData material=
    FluxTubesExtension.Material.SoftMagnetic.BaseData()
    "Ferromagnetic material characteristics; used if nonLinearPermeability = true"
    ;

  SI.Reluctance R_m "Magnetic reluctance";
  SI.Permeance G_m "Magnetic permeance";
  SI.MagneticFluxDensity B "Magnetic flux density";
  SI.CrossSection A "Cross-sectional area penetrated by magnetic flux";
  SI.Length l_m "Length of field line";
  SI.MagneticFieldStrength H "Magnetic field strength";

  SI.RelativePermeability mu_r "Relative magnetic permeability";

protected
  Real B_N=abs(B)/material.B_myMax "Absolute value of normalized B";

equation
  if not nonLinearPermeability then
    mu_r = mu_rConst;
    H = B/(mu_0*mu_r);
  else
    if material.approximation==FluxTubesExtension.Types.Approximation.Roschke then
      mu_r = 1 + (material.mu_i - 1 + material.c_a*B_N)/(1 + material.c_b*B_N + B_N^material.n);
      H = B/(mu_0*mu_r);
    elseif material.approximation==FluxTubesExtension.Types.Approximation.Macfadyen then
      B = FluxTubesExtension.Material.SimpleSoftMagnetic.BH_Approx(
        material.N, material.Hk, material.Bk, H);
      mu_r = FluxTubesExtension.Material.SimpleSoftMagnetic.mu_rApprox(
        material.N, material.Hk, material.Bk, H);
    else//material.approximation==FluxTubesExtension.Types.Approximation.PiecewiseLinear
      B = FluxTubesExtension.Material.PiecewiseLinearSoftMagnetic.BH_Approx(
        material.N, material.Hk, material.Bk, H);
      mu_r = FluxTubesExtension.Material.PiecewiseLinearSoftMagnetic.mu_rApprox(
        material.N, material.Hk, material.Bk, H);
    end if;
  end if;
  G_m = mu_0*mu_r*A/l_m;
  R_m = 1/G_m;
  B = Phi/A;
//V_m = R_m*Phi;
  H = V_m/l_m

  ;
end FixedShape;

