within FluxTubesExtension.Material.PiecewiseLinearSoftMagnetic;
function BH_Approx "Piecewise linear B(H) interpolation"
  extends Modelica.Icons.Function;

  input Integer N "Count of nodes";
  input SI.MagneticFieldStrength Hk[N] "Field strength coefficients";
  input SI.MagneticFluxDensity Bk[N] "Flux density coefficients";
  input SI.MagneticFieldStrength H "Field strength in ferromagnetic flux tube element";

  output SI.MagneticFluxDensity B "Flux density in ferromagnetic flux tube element";

protected
  Integer k=findInterval(Hk, H);
algorithm
  B := if k<=1 then Bk[1]/Hk[1]*H else
       sign(H)*(Bk[k-1] + (Bk[k] - Bk[k-1])/(Hk[k] - Hk[k-1])*(abs(H) - Hk[k-1]))
  ;
end BH_Approx;

within FluxTubesExtension.Material.PiecewiseLinearSoftMagnetic;
function derBH_Approx "Piecewise linear der_B(H) interpolation"
  extends Modelica.Icons.Function;

  input Integer N "Count of nodes";
  input SI.MagneticFieldStrength Hk[N] "Field strength coefficients";
  input SI.MagneticFluxDensity Bk[N] "Flux density coefficients";
  input SI.MagneticFieldStrength H "Field strength in ferromagnetic flux tube element";
  input Real der_H(unit="A/(m.s)") "Derivative of field strength in ferromagnetic flux tube element";

  output Real der_B(unit="T/s") "Derivative of flux density in ferromagnetic flux tube element";

protected
  Integer k=findInterval(Hk, H);
algorithm
  der_B := if k<=1 then Bk[1]/Hk[1]*der_H else
           (Bk[k] - Bk[k-1])/(Hk[k] - Hk[k-1])*der_H;
end derBH_Approx;

within FluxTubesExtension.Material.PiecewiseLinearSoftMagnetic;
function findInterval "Find interval for piecewise linear interpolation"
  extends Modelica.Icons.Function;
  input SI.MagneticFieldStrength Xk[:] "Nodes";
  input SI.MagneticFieldStrength x "Value to find interval";
  output Integer k "Interval Xk[k-1]..Xk[k]";
protected
  Integer n=size(Xk, 1);
algorithm
  k:=1;
  while abs(x)>=Xk[k] loop
    k:=k+1;
    if k>n then
      k:=n;
      break;
    end if;
  end while;
end findInterval;

within FluxTubesExtension.Material.PiecewiseLinearSoftMagnetic;
function mu_rApprox "Piecewise linear mu_r(H) interpolation"
  extends Modelica.Icons.Function;

  input Integer N "Count of nodes";
  input SI.MagneticFieldStrength Hk[N] "Field strength coefficients";
  input SI.MagneticFluxDensity Bk[N] "Flux density coefficients";
  input SI.MagneticFieldStrength H "Field strength in ferromagnetic flux tube element";

  output SI.RelativePermeability mu_r "Relative magnetic permeability of ferromagnetic flux tube element";

protected
  Integer k=findInterval(Hk, H);
algorithm
  mu_r := if k<=1 then Bk[1]/(mu_0*Hk[1]) else
          (Bk[k-1] + (Bk[k] - Bk[k-1])/(Hk[k] - Hk[k-1])*(abs(H) - Hk[k-1]))/(mu_0*abs(H));
end mu_rApprox;

within FluxTubesExtension.Material.PiecewiseLinearSoftMagnetic;
function mu_rdApprox "Piecewise linear mu_rd(H) interpolation"
  extends Modelica.Icons.Function;

  input Integer N "Count of nodes";
  input SI.MagneticFieldStrength Hk[N] "Field strength coefficients";
  input SI.MagneticFluxDensity Bk[N] "Flux density coefficients";
  input SI.MagneticFieldStrength H "Field strength in ferromagnetic flux tube element";

  output SI.RelativePermeability mu_rd  "Differential relative magnetic permeability of ferromagnetic flux tube element";

protected
  Integer k=findInterval(Hk, H);
algorithm
  mu_rd := if k<=1 then Bk[1]/(mu_0*Hk[1]) else
           (Bk[k] - Bk[k-1])/(mu_0*(Hk[k] - Hk[k-1]));
end mu_rdApprox;

within FluxTubesExtension.Material.SimpleSoftMagnetic;
function BH_Approx
  "Approximation of B(H) for simple soft magnetic materials"
  extends Modelica.Icons.Function;

  input Integer N "Count of exponential summands";
  input SI.MagneticFieldStrength Hk[N] "Field strength coefficients";
  input SI.MagneticFluxDensity Bk[N] "Flux density coefficients";
  input SI.MagneticFieldStrength H
      "Field strength in ferromagnetic flux tube element";

  output SI.MagneticFluxDensity B
      "Flux density in ferromagnetic flux tube element";

algorithm
  B := mu_0*H + sign(H)*sum({Bk[k]*(1 - exp(-abs(H)/Hk[k])) for k in 1:N})
  ;
end BH_Approx;

within FluxTubesExtension.Material.SimpleSoftMagnetic;
function derBH_Approx
  "Approximation of der(B(H)) for simple soft magnetic materials"
  extends Modelica.Icons.Function;

  input Integer N "Count of exponential summands";
  input SI.MagneticFieldStrength Hk[N] "Field strength coefficients";
  input SI.MagneticFluxDensity Bk[N] "Flux density coefficients";
  input SI.MagneticFieldStrength H
      "Field strength in ferromagnetic flux tube element";
  input Real der_H(unit="A/(m.s)")
      "Derivative of field strength in ferromagnetic flux tube element";

  output Real der_B(unit="T/s")
      "Derivative of flux density in ferromagnetic flux tube element";

algorithm
  der_B := (mu_0 + sum({Bk[k]/Hk[k]*exp(-abs(H)/Hk[k]) for k in 1:N}))*der_H;
end derBH_Approx;

within FluxTubesExtension.Material.SimpleSoftMagnetic;
function mu_rApprox
  "Approximation of mu_r(H) for simple soft magnetic materials"
  extends Modelica.Icons.Function;

  input Integer N "Count of exponential summands";
  input SI.MagneticFieldStrength Hk[N] "Field strength coefficients";
  input SI.MagneticFluxDensity Bk[N] "Flux density coefficients";
  input SI.MagneticFieldStrength H
      "Field strength in ferromagnetic flux tube element";

  output SI.RelativePermeability mu_r
      "Relative magnetic permeability of ferromagnetic flux tube element";
protected
  SI.RelativePermeability mu_i=1 + sum({Bk[k]/(mu_0*Hk[k]) for k in 1:N});
algorithm
  if abs(H) < Modelica.Constants.small then
    mu_r :=mu_i;
  else
    mu_r :=1;
     for k in 1:N loop
       mu_r :=mu_r + Bk[k]/(mu_0*abs(H))*(1 - exp(-abs(H)/Hk[k]));
     end for;
  end if;
end mu_rApprox;

within FluxTubesExtension.Material.SimpleSoftMagnetic;
function mu_rdApprox
  "Approximation of mu_rd(H) for simple soft magnetic materials"
  extends Modelica.Icons.Function;

  input Integer N "Count of exponential summands";
  input SI.MagneticFieldStrength Hk[N] "Field strength coefficients";
  input SI.MagneticFluxDensity Bk[N] "Flux density coefficients";
  input SI.MagneticFieldStrength H
      "Field strength in ferromagnetic flux tube element";

  output SI.RelativePermeability mu_rd
      "Differential relative magnetic permeability of ferromagnetic flux tube element";

algorithm
  mu_rd := 1 + sum({Bk[k]/(mu_0*Hk[k])*exp(-abs(H)/Hk[k]) for k in 1:N});
end mu_rdApprox;

within Greenhouses.Components.Greenhouse;
model Air_Top "Temperature of air in top compartment computed by static equation because of
its small heat capacity"

  /******************** Parameters ********************/
  parameter Modelica.Units.SI.SpecificHeatCapacity c_p=1e3;
  parameter Modelica.Units.SI.Length h_Top
    "Height of the top air compartment (mean greenhouse height minus thermal screen height)";
  parameter Modelica.Units.SI.Area A "Greenhouse floor surface";

  /******************** Initialization ********************/
  parameter Modelica.Units.SI.Temperature T_start=298
    ;
  parameter Boolean steadystate=false
    "if true, sets the derivative of T to zero during Initialization"
    ;
  parameter Boolean steadystateVP=true
    "if true, sets the derivative of vapour pressure (VP) to zero during Initialization"
    ;

  /******************** Variables ********************/
  Modelica.Units.SI.HeatFlowRate Q_flow "Heat flow rate from port_a -> port_b";
  Modelica.Units.SI.Temperature T;
  Modelica.Units.SI.Density rho;
  Real RH(min=0,max=1) "Relative humidity of the air";
  Modelica.Units.SI.Volume V;

  Modelica.Units.SI.Pressure P_atm=101325 "Atmospheric pressure";
  Real R_a = 287 "Gas constant for dry air R_a = R_d (J/(kg.K))";
  Real R_s = 461.5;
  Modelica.Units.SI.MassFraction w_air "Air humidity ratio (kg water / kg dry air)";

  /******************** Connectors ********************/
protected
  Modelica.Thermal.HeatTransfer.Sources.PrescribedTemperature preTem
    "Port temperature"
    ;
  Modelica.Blocks.Sources.RealExpression portT(y=T) "Port temperature"
    ;
public
  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a heatPort(
    T(start=T_start)) "Heat port for sensible heat input"
    ;

  BasicComponents.AirVP air(V_air=V, steadystate=steadystateVP)
    ;
  Interfaces.Vapour.WaterMassPort_a massPort ;
equation
  V=A*h_Top;
  // Balance on the floor
  heatPort.Q_flow = Q_flow;
  rho = Modelica.Media.Air.ReferenceAir.Air_pT.density_pT(1e5,heatPort.T);
  der(T) = 1/(rho*c_p*V)*Q_flow;

  //RH = massPort.VP/.Greenhouses.Functions.SaturatedVapourPressure(heatPort.T -273.15);
  w_air = massPort.VP * R_a / (P_atm - massPort.VP) / R_s;
  RH=Modelica.Media.Air.MoistAir.relativeHumidity_pTX(P_atm, heatPort.T, {w_air});

  connect(portT.y,preTem. T)
    ;
  connect(preTem.port,heatPort)
    ;
  connect(air.port, massPort) ;
initial equation
  if steadystate then
    der(T)=0;
  end if
  ;
end Air_Top;

