within Greenhouses.Components.HVAC;
model HeatPump
  "Performance-based model of a heat pump in which we consider a constant secondary-law efficiency and a linear correlation between the nominal power and temperature"

  replaceable package Medium =
      Modelica.Media.Water.ConstantPropertyLiquidWater                          constrainedby
    Modelica.Media.Interfaces.PartialMedium "Medium in the component"
      ;

  parameter Modelica.Units.SI.Volume V=0.005 "Internal volume";
  parameter Modelica.Units.SI.Area A=10 "Heat exchange area";
  parameter Real eta_II = 0.4 "Second law efficiency of the HP";
  parameter Modelica.Units.SI.Time tau=60 "Start-up time constant";
  parameter Modelica.Units.SI.Power Qdot_nom=10E3 "Nominal heating capacity";
  parameter Modelica.Units.SI.Temperature Th_nom=35 + 273.15
    "Nominal heat sink temperature";
  parameter Modelica.Units.SI.Temperature Tc_nom=273.15
    "Nominal heat source temperature";
  parameter Modelica.Units.SI.Mass M_wall=69
    "Mass of the metal wall between the two fluids";
  parameter Modelica.Units.SI.SpecificHeatCapacity c_wall=500
    "Specific heat capacity of metal wall";
  parameter Modelica.Units.SI.Temperature Th_start=35 + 273.15
    "Start value for the condenser temperature"
    ;
  parameter Modelica.Units.SI.Temperature Tmax=273.15 + 100
    "Maximum temperature at the outlet";
  Real COP;
  Real COP_nom;
  Modelica.Units.SI.Power Wdot;
  Modelica.Units.SI.Power Wdot_nom;
  Modelica.Units.SI.Power Qdot;
  Modelica.Units.SI.Temperature Th;
  Modelica.Units.SI.Power Wdot_in;

  Flows.FluidFlow.Cell1DimInc                        fluid(
    redeclare package Medium = Medium,
    Mdotnom=0.1,
    Vi=V,
    Ai=A,
    hstart=Medium.specificEnthalpy_pTX(1E5, Th_start, Medium.reference_X),
    Unom=1000,
    redeclare model HeatTransfer =
        Greenhouses.Flows.FluidFlow.HeatTransfer.Constant,
    pstart=10000000000,
    Discretization=Greenhouses.Functions.Enumerations.Discretizations.upwind_AllowFlowReversal)
                        ;

  Modelica.Fluid.Interfaces.FluidPort_a
                           InFlow(redeclare package Medium = Medium)
    ;
  Modelica.Fluid.Interfaces.FluidPort_b
                           OutFlow(redeclare package Medium = Medium)
    ;
  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a HeatSource
    ;
  Interfaces.Heat.HeatPortConverter heatPortConverter(A=A, N=1)
    ;
  Modelica.Thermal.HeatTransfer.Sources.PrescribedHeatFlow prescribedHeatFlow
    ;
  Modelica.Blocks.Interfaces.BooleanInput on_off ;
  Modelica.Blocks.Continuous.FirstOrder firstOrder(T=tau)
    ;
equation
  Th = fluid.Wall_int.T;
  //Th = fluid.fluidState.T;   // this does not take the heat transfer into account
  COP_nom = eta_II * Th_nom/(Th_nom - Tc_nom);
  Wdot_nom = Qdot_nom/COP_nom;
  COP = eta_II* Th/ (Th - HeatSource.T);
  Qdot/Qdot_nom = HeatSource.T/Tc_nom;   // rough approximation
  Wdot = Qdot/COP;
  HeatSource.Q_flow = Qdot - Wdot;

  Wdot_in = firstOrder.y*firstOrder.u* Wdot;
  prescribedHeatFlow.Q_flow = firstOrder.y*firstOrder.u* Qdot;
  if cardinality(on_off)==0 then
    on_off = true "Pressure set by parameter";
  end if;
  assert(fluid.T < Tmax,"Maximum temperature reached at the heat pump outlet");
  firstOrder.u= if on_off then 1 else 0;

  connect(InFlow, fluid.OutFlow) ;
  connect(OutFlow, fluid.InFlow) ;
  connect(fluid.Wall_int, heatPortConverter.thermalPortL) ;
  connect(heatPortConverter.heatPort, prescribedHeatFlow.port) 
  ;
end HeatPump;

within Greenhouses.Components.HVAC.HeatStorageWaterHeater;
model Cell1DimInc_2ports
  "1-D incompressible fluid flow model with three thermal ports (two with a heat transfer model)"
  replaceable package Medium = Modelica.Media.Water.ConstantPropertyLiquidWater constrainedby
    Modelica.Media.Interfaces.PartialMedium "Medium in the component"
      ;

  /************ Thermal and fluid ports ***********/
  Modelica.Fluid.Interfaces.FluidPort_a
                           InFlow(redeclare package Medium = Medium)
    ;
  Modelica.Fluid.Interfaces.FluidPort_b
                           OutFlow(redeclare package Medium = Medium)
    ;
  Interfaces.Heat.ThermalPortL Wall_int ;

  /************ Geometric characteristics **************/
  constant Real pi=Modelica.Constants.pi "pi-greco";
  parameter Modelica.Units.SI.Volume Vi "Volume of a single cell";
  parameter Modelica.Units.SI.Area Ai "Lateral surface of a single cell";
  parameter Modelica.Units.SI.MassFlowRate Mdotnom "Nominal fluid flow rate";
  parameter Modelica.Units.SI.CoefficientOfHeatTransfer Unom;
  parameter Modelica.Units.SI.CoefficientOfHeatTransfer Unom_hx
    "Nominal Heat transfer coefficient ";

  parameter Modelica.Units.SI.Area A_hx;

  /************ FLUID INITIAL VALUES ***************/
  parameter Modelica.Units.SI.Pressure pstart "Fluid pressure start value"
    ;
  parameter Medium.SpecificEnthalpy hstart=1E5 "Start value of enthalpy"
    ;

  /****************** NUMERICAL OPTIONS  ***********************/
  parameter Boolean steadystate=true
    "if true, sets the derivative of h (working fluids enthalpy in each cell) to zero during Initialization"
    ;

  /********************************* HEAT TRANSFER MODEL ********************************/
  /* Heat transfer Model */
  replaceable model HeatTransfer =
      Flows.FluidFlow.HeatTransfer.MassFlowDependence
    constrainedby Flows.FluidFlow.HeatTransfer.BaseClasses.PartialHeatTransferZones
    "Convective heat transfer" ;
  parameter Boolean FlowReversal = false
    "Allow flow reversal (might complexify the final system of equations)";

  Flows.FluidFlow.HeatTransfer.MassFlowDependence
               heatTransfer(
    redeclare final package Medium = Medium,
    final n=1,
    final Mdotnom=Mdotnom,
    final Unom_l=Unom,
    final Unom_tp=Unom,
    final Unom_v=Unom,
    final M_dot=M_dot,
    final x=0,
    final FluidState={fluidState})
    ;

  Flows.FluidFlow.HeatTransfer.MassFlowDependence
               heatTransfer1(
    redeclare final package Medium = Medium,
    final n=1,
    final Mdotnom=Mdotnom,
    final Unom_l=Unom_hx,
    final Unom_tp=Unom_hx,
    final Unom_v=Unom_hx,
    final M_dot=M_dot,
    final x=0,
    final FluidState={fluidState})
    ;
  Interfaces.Heat.ThermalPortL HXInt ;

  /***************  VARIABLES ******************/
  Medium.ThermodynamicState fluidState;
  Medium.AbsolutePressure p(start=pstart);
  Modelica.Units.SI.MassFlowRate M_dot(start=Mdotnom);
  Medium.SpecificEnthalpy h(start=hstart, stateSelect=StateSelect.always)
    "Fluid specific enthalpy at the cells";
  Medium.Temperature T "Fluid temperature";
  //Modelica.SIunits.Temperature T_wall "Internal wall temperature";
  Medium.Density rho "Fluid cell density";
  Modelica.Units.SI.SpecificEnthalpy hnode_su(start=hstart)
    "Enthalpy state variable at inlet node";
  Modelica.Units.SI.SpecificEnthalpy hnode_ex(start=hstart)
    "Enthalpy state variable at outlet node";
  Modelica.Units.SI.HeatFlux qdot "heat flux at each cell";
  //   Modelica.SIunits.CoefficientOfHeatTransfer U
  //     "Heat transfer coefficient between wall and working fluid";
  Modelica.Units.SI.Power Q_tot "Total heat flux exchanged by the thermal port";
  Modelica.Units.SI.Mass M_tot "Total mass of the fluid in the component";

  Modelica.Units.SI.HeatFlux qdot_hx;

  /***********************************  EQUATIONS ************************************/

  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a direct_heat_port
    ;
equation
  /* Fluid Properties */
  fluidState = Medium.setState_ph(p, h);
  T = Medium.temperature(fluidState);
  rho = Medium.density(fluidState);
  /* ENERGY BALANCE */
  Vi*rho*der(h) + M_dot*(hnode_ex - hnode_su) - A_hx*qdot_hx = Ai*qdot + direct_heat_port.Q_flow
    "Energy balance";

  Q_tot = Ai*qdot "Total heat flow through the thermal port";
  M_tot = Vi*rho;

  qdot = heatTransfer.q_dot[1];

  qdot_hx = heatTransfer1.q_dot[1];

  if FlowReversal then
    hnode_ex = if M_dot >= 0 then h else inStream(OutFlow.h_outflow);
    hnode_su = if M_dot <= 0 then h else inStream(InFlow.h_outflow);
    InFlow.h_outflow = hnode_su;
  else
    hnode_su = inStream(InFlow.h_outflow);
    hnode_ex = h;
    InFlow.h_outflow = hstart;
  end if;

  //* BOUNDARY CONDITIONS *//
  /* Enthalpies */
  OutFlow.h_outflow = hnode_ex;
  /* pressures */
  p = OutFlow.p;
  InFlow.p = p;
  /*Mass Flow*/
  M_dot = InFlow.m_flow;
  OutFlow.m_flow = -M_dot;
  InFlow.Xi_outflow = inStream(OutFlow.Xi_outflow);
  OutFlow.Xi_outflow = inStream(InFlow.Xi_outflow);

  direct_heat_port.T = T;

initial equation
  if steadystate then
    der(h) = 0;
  end if;

equation
  connect(HXInt, heatTransfer1.thermalPortL[1]) ;
  connect(Wall_int, heatTransfer.thermalPortL[1]) 
  ;
end Cell1DimInc_2ports;

within Greenhouses.Components.HVAC.HeatStorageWaterHeater;
model Flow1DimInc
  "1-D fluid flow model (finite volume discretization - incompressible fluid model). Based on the Cell component"
  replaceable package Medium = Modelica.Media.Water.ConstantPropertyLiquidWater constrainedby
    Modelica.Media.Interfaces.PartialMedium "Medium in the component"
      ;
public
 record SummaryClass
    replaceable Arrays T_profile;
    record Arrays
    parameter Integer n;
      Modelica.Units.SI.Temperature[n] T_cell;
    end Arrays;
    parameter Integer n;
    Modelica.Units.SI.SpecificEnthalpy[n] h;
    Modelica.Units.SI.Temperature[n] T;
    Modelica.Units.SI.SpecificEnthalpy[n + 1] hnode;
    Modelica.Units.SI.Density[n] rho;
    Modelica.Units.SI.MassFlowRate Mdot;
    Modelica.Units.SI.Pressure p;
 end SummaryClass;
 SummaryClass Summary( T_profile(n=N, T_cell = Cells[:].T), n=N, h = Cells[:].h, hnode = hnode_, rho = Cells.rho, T = Cells.T, Mdot = InFlow.m_flow, p = Cells[1].p);
/************ Thermal and fluid ports ***********/
  Modelica.Fluid.Interfaces.FluidPort_a
                           InFlow(redeclare package Medium = Medium)
    ;
  Modelica.Fluid.Interfaces.FluidPort_b
                           OutFlow(redeclare package Medium = Medium)
    ;
  Interfaces.Heat.ThermalPort Wall_int(N=N) ;
/************ Geometric characteristics **************/
  parameter Integer Nt(min=1)=1 "Number of cells in parallel";
  constant Real pi = Modelica.Constants.pi "pi-greco";
  parameter Integer N(min=1)=10 "Number of cells";
  parameter Modelica.Units.SI.Area A=16.18
    "Lateral surface of the tube: heat exchange area";
  parameter Modelica.Units.SI.Volume V=0.03781 "Volume of the tube";
  parameter Modelica.Units.SI.MassFlowRate Mdotnom=0.2588 "Nominal fluid flow rate";
  parameter Modelica.Units.SI.CoefficientOfHeatTransfer Unom
    "if HTtype = Const: Heat transfer coefficient";
 /********************************* FLUID INITIAL VALUES ******************************/
  parameter Modelica.Units.SI.Pressure pstart "Fluid pressure start value"
    ;
  parameter Medium.Temperature Tstart_inlet "Inlet temperature start value"
     ;
  parameter Medium.Temperature Tstart_outlet "Outlet temperature start value"
     ;
  parameter Medium.SpecificEnthalpy hstart[N]=linspace(
        Medium.specificEnthalpy_pTX(pstart,Tstart_inlet,Medium.reference_X),Medium.specificEnthalpy_pTX(pstart,Tstart_outlet,Medium.reference_X),
        N) "Start value of enthalpy vector (initialized by default)"
    ;
/***************************************   NUMERICAL OPTIONS  ***************************************************/
  import Greenhouses.Functions.Enumerations.Discretizations;
  parameter Discretizations Discretization=Greenhouses.Functions.Enumerations.Discretizations.centr_diff
    "Selection of the spatial discretization scheme"
    ;
  parameter Boolean steadystate=true
    "if true, sets the derivative of h (working fluids enthalpy in each cell) to zero during Initialization"
    ;
  /******************************* HEAT TRANSFER MODEL **************************************/
replaceable model Flow1DimIncHeatTransferModel =
    Flows.FluidFlow.HeatTransfer.MassFlowDependence
constrainedby Flows.FluidFlow.HeatTransfer.BaseClasses.PartialHeatTransferZones
    "Fluid heat transfer model" ;
/***************  VARIABLES ******************/
  Modelica.Units.SI.Power Q_tot "Total heat flux exchanged by the thermal port";
  Modelica.Units.SI.Mass M_tot "Total mass of the fluid in the component";
  /********************************** CELLS *****************************************/
 Flows.FluidFlow.Cell1DimInc
        Cells[N](
    redeclare package Medium = Medium,
    redeclare each final model HeatTransfer = Flow1DimIncHeatTransferModel,
    each Vi=V/N,
    each Ai=A/N,
    each Nt=Nt,
    each Mdotnom=Mdotnom,
    each Unom=Unom,
    each pstart=pstart,
    each Discretization=Discretization,
    hstart = hstart,
    each steadystate=steadystate)
                        ;
  Interfaces.Heat.ThermalPortConverter thermalPortConverter(N=N)
    ;
protected
  Modelica.Units.SI.SpecificEnthalpy hnode_[N + 1];
  /*************************************** EQUATION *************************************/
equation
  // Connect wall and refrigerant cells with eachother
  for i in 1:N-1 loop
    connect(Cells[i].OutFlow, Cells[i+1].InFlow);
  end for;
  hnode_[1:N] = Cells.hnode_su;
  hnode_[N+1] = Cells[N].hnode_ex;
  Q_tot = A/N*sum(Cells.qdot)*Nt "Total heat flow through the thermal port";
  M_tot = V/N*sum(Cells.rho);
  connect(InFlow, Cells[1].InFlow) ;
  connect(thermalPortConverter.single, Cells.Wall_int) ;
  connect(thermalPortConverter.multi, Wall_int) ;
  connect(Cells[N].OutFlow, OutFlow) 
  ;
end Flow1DimInc;

within Greenhouses.ControlSystems;
model PID "ISA PID controller with anti-windup"
  parameter Real Kp "Proportional gain (normalised units)";
  parameter Modelica.Units.SI.Time Ti "Integral time";
  parameter Modelica.Units.SI.Time Td=0 "Derivative time";
  parameter Real Nd=1 "Derivative action up to Nd / Td rad/s";
  parameter Real Ni=1 "Ni*Ti is the time constant of anti-windup compensation";
  parameter Real b=1 "Setpoint weight on proportional action";
  parameter Real c=0 "Setpoint weight on derivative action";
  parameter Real PVmin "Minimum value of process variable for scaling";
  parameter Real PVmax "Maximum value of process variable for scaling";
  parameter Real CSmin "Minimum value of control signal for scaling";
  parameter Real CSmax "Maximum value of control signal for scaling";
  parameter Real PVstart=0.5 "Start value of PV (scaled)";
  parameter Real CSstart=0.5 "Start value of CS (scaled)";
  parameter Boolean steadyStateInit=false;
  Real P "Proportional action / Kp";
  Real I(start=CSstart/Kp) "Integral action / Kp";
  Real D "Derivative action / Kp";
  Real Dx(start=c*PVstart - PVstart) "State of approximated derivator";
  Real PVs "Process variable scaled in per unit";
  Real SPs "Setpoint variable scaled in per unit";
  Real CSs(start=CSstart) "Control signal scaled in per unit";
  Real CSbs(start=CSstart)
    "Control signal scaled in per unit before saturation";
  Real track "Tracking signal for anti-windup integral action";
  Modelica.Blocks.Interfaces.RealInput PV "Process variable signal"
    ;
  Modelica.Blocks.Interfaces.RealOutput CS "Control signal" ;
  Modelica.Blocks.Interfaces.RealInput SP "Set point signal" ;
equation
  // Scaling
  SPs = (SP - PVmin)/(PVmax - PVmin);
  PVs = (PV - PVmin)/(PVmax - PVmin);
  CS = CSmin + CSs*(CSmax - CSmin);
  // Controller actions
  P = b*SPs - PVs;
  if Ti > 0 then
    Ti*der(I) = SPs - PVs + track;
  else
    I = 0;
  end if;
  if Td > 0 then
    Td/Nd*der(Dx) + Dx = c*SPs - PVs "State equation of approximated derivator";
    D = Nd*((c*SPs - PVs) - Dx) "Output equation of approximated derivator";
  else
    Dx = 0;
    D = 0;
  end if;
  CSbs = Kp*(P + I + D) "Control signal before saturation";
//  CSs = smooth(0, if CSbs > 1 then 1 else if CSbs < 0 then 0 else CSbs)
//    "Saturated control signal";
  CSs = smooth(0, max(min(1,CSbs),0)) "Saturated control signal";
  track = (CSs - CSbs)/(Kp*Ni);
initial equation
  if steadyStateInit then
    if Ti > 0 then
      der(I) = 0;
    end if;
    if Td > 0 then
      D = 0;
    end if;
  end if
  ;
end PID;

within Greenhouses.ControlSystems.Climate;
model Control_Illu "Controller for the artificial illumination"
  Modelica.Units.SI.HeatFlux R_t_PAR=0 ;
  parameter Real R_illu(unit "W/m2")=100;

  Real E_acc(unit="W.s/m2") "Accumulated PAR light";
  Real E_acc_limit(unit="W.s/m2")
    "Accumulated PAR light limit above which lamps have to be switched off";
  Real R_PAR_tot(unit="W/m2");
  Real R_PAR_day(unit="W/m2");

  Modelica.StateGraph.InitialStep off(nOut=1, nIn=3) ;
  inner Modelica.StateGraph.StateGraphRoot stateGraphRoot
    ;
  Modelica.Blocks.Interfaces.RealInput h "Hour of the day" ;
  Modelica.Blocks.Interfaces.RealOutput y "Control signal" ;
  Modelica.StateGraph.Transition T1(condition=h >= 6 and h <= 22 and E_acc <
        E_acc_limit and R_t_PAR < 40)
    "We are in the light usage window and we do not exceed the accumulation limit"
    ;
  Modelica.StateGraph.Transition T4(
    enableTimer=true,
    waitTime=120*60,
    condition=R_t_PAR > 120) "Minimum on time of 2h. Then if I>120, turn off"
    ;
  Modelica.StateGraph.Step on(nIn=1, nOut=2) ;
  Modelica.StateGraph.Transition T2(
    condition=R_t_PAR < 40,
    enableTimer=true,
    waitTime=30*60) "Proving time"
    ;
  Modelica.StateGraph.Step off_ProvingTime(nIn=1, nOut=2) ;
  Modelica.StateGraph.Transition T5(
    enableTimer=true,
    waitTime=120*60,
    condition=h > 22 or h < 6) "Minimum on time of 2h. Then if I<120, turn off"
    ;
  Modelica.StateGraph.Transition T3(
    enableTimer=true,
    waitTime=30*60,
    condition=R_t_PAR >= 40 or (h < 6 and h > 22)) "Proving time"
    ;
  Modelica.StateGraph.InitialStep sameDay(nOut=1, nIn=1) ;
  Modelica.StateGraph.Transition T6(condition=h <= 0)
    "We are in the light usage window and we do not exceed the accumulation limit"
    ;
  Modelica.Blocks.Logical.Timer timer ;
  Modelica.StateGraph.TransitionWithSignal T7
    ;
  Modelica.Blocks.Logical.GreaterEqualThreshold greaterEqual1(threshold=
        3600)
    ;
  Modelica.StateGraph.StepWithSignal newDay(nIn=1, nOut=1)
    ;
equation
  E_acc_limit = 1.2*1000*3600 "1.2 kWh/m2";

  R_PAR_tot = if on.active then (R_t_PAR + 0.25*R_illu) else R_t_PAR;
  R_PAR_day = if newDay.active then R_PAR_tot else 0;

  der(E_acc) = 1/86400*(R_PAR_tot - R_PAR_day);

  y= if on.active then 1 else 0;

  connect(off.outPort[1],T1. inPort) ;
  connect(on.outPort[1], T4.inPort) ;
  connect(T1.outPort, off_ProvingTime.inPort[1]) ;
  connect(off_ProvingTime.outPort[1], T2.inPort) ;
  connect(T2.outPort, on.inPort[1]) ;
  connect(T4.outPort, off.inPort[1]) ;
  connect(on.outPort[2], T5.inPort) ;
  connect(T5.outPort, off.inPort[2]) ;
  connect(T3.inPort, off_ProvingTime.outPort[2]) ;
  connect(T3.outPort, off.inPort[3]) ;
  connect(sameDay.outPort[1], T6.inPort) ;
  connect(timer.y, greaterEqual1.u) ;
  connect(greaterEqual1.y,T7. condition) ;
  connect(T6.outPort, newDay.inPort[1]) ;
  connect(newDay.active, timer.u) ;
  connect(newDay.outPort[1], T7.inPort) ;
  connect(T7.outPort, sameDay.inPort[1]) 
  ;
end Control_Illu;

within Greenhouses.ControlSystems.Climate;
model Control_ThScreen
  "Controller for the thermal screen closure including a crack for dehumidification (of 2% and 4%)"
  Modelica.Units.SI.HeatFlux R_Glob_can=0 ;
  Modelica.Units.SI.HeatFlux R_Glob_can_min=32
    ;

  Integer op;
  Integer cl;
  Real opening_CD;
  Real opening_WD;
  Real closing_CD;
  Modelica.StateGraph.InitialStep closed(       nOut=3, nIn=3)
                                                        ;
  inner Modelica.StateGraph.StateGraphRoot stateGraphRoot
    ;
  Modelica.Blocks.Interfaces.RealInput T_out(
    quantity="Temperature",
    displayUnit="degC",
    unit="K")           ;
  Modelica.Blocks.Interfaces.RealInput SC_usable
                        ;
  Modelica.Blocks.Interfaces.RealInput T_air_sp(
    quantity="Temperature",
    unit="K",
    displayUnit="degC") ;
  Modelica.Blocks.Interfaces.RealOutput y "Control signal" ;
  Modelica.StateGraph.Transition T2(condition=R_Glob_can > R_Glob_can_min
         and T_out <= (T_air_sp - 7))
    ;
  Modelica.StateGraph.Transition T3(condition=R_Glob_can > R_Glob_can_min
         and T_out > (T_air_sp - 7))
    ;
  Modelica.StateGraph.Transition T4(condition=SC_usable > 0 and T_out < (
        T_air_sp - 7),
    enableTimer=true,
    waitTime=3600*2)
    ;
  Modelica.StateGraph.StepWithSignal opening_ColdDay(nIn=3, nOut=1)
    ;
  Modelica.Blocks.Logical.Timer timer ;
  Modelica.StateGraph.TransitionWithSignal T6 ;
  Modelica.Blocks.Logical.GreaterEqualThreshold greaterEqual(threshold=52*
        60)
    ;
  Modelica.StateGraph.Step open(nOut=1, nIn=2) ;
  Modelica.StateGraph.StepWithSignal opening_WarmDay(nIn=3, nOut=1)
    ;
  Modelica.Blocks.Logical.Timer timer1
                                      ;
  Modelica.StateGraph.TransitionWithSignal T7
    ;
  Modelica.Blocks.Logical.GreaterEqualThreshold greaterEqual1(threshold=32*
        60)
    ;
  Modelica.StateGraph.StepWithSignal closing_ColdDay(nIn=1, nOut=1)
    ;
  Modelica.Blocks.Logical.Timer timer2
                                      ;
  Modelica.StateGraph.TransitionWithSignal T1 ;
  Modelica.Blocks.Logical.GreaterEqualThreshold greaterEqual2(threshold=52*
        60)
    ;
  Utilities.SC_closing_value SC_OWD_value(warmDay=true, opening=true)
    ;
  Utilities.SC_closing_value SC_OCD_value(opening=true, warmDay=false)
    ;
  Utilities.SC_closing_value SC_CCD_value(warmDay=false, opening=false)
    ;
  Modelica.StateGraph.Transition T5(condition=RH_air > 0.83)
    ;
  Modelica.StateGraph.StepWithSignal crack(        nIn=1, nOut=4)
    ;
  Utilities.SC_crack SC_crack(SC_value=0.98)
    ;
  Modelica.Blocks.Interfaces.RealInput RH_air(quantity="Humidity")
                        ;
  Modelica.StateGraph.Transition T2b(condition=R_Glob_can > R_Glob_can_min
         and T_out <= (T_air_sp - 7)) ;
  Modelica.StateGraph.Transition T3b(condition=R_Glob_can > R_Glob_can_min
         and T_out > (T_air_sp - 7)) ;
  Modelica.StateGraph.Transition T8(condition=RH_air < 0.7)
    ;
  Modelica.StateGraph.Transition T9(
    condition=RH_air > 0.85,
    enableTimer=true,
    waitTime=15*60)
    ;
  Utilities.SC_crack SC_crack2(SC_value=0.96)
    ;
  Modelica.StateGraph.StepWithSignal crack2(       nIn=1, nOut=3)
    ;
  Modelica.StateGraph.Transition T8b(
                                    condition=RH_air < 0.7)
    ;
  Modelica.StateGraph.Transition T2c(condition=R_Glob_can > R_Glob_can_min and
        T_out <= (T_air_sp - 7)) ;
  Modelica.StateGraph.Transition T3c(condition=R_Glob_can > R_Glob_can_min and
        T_out > (T_air_sp - 7)) ;
equation
//   opening_CD = if opening_ColdDay.active then SC_OCD_value.y else 0;
//   opening_WD = if opening_WarmDay.active then SC_OWD_value.y else 0;
//   closing_CD = if closing_ColdDay.active then SC_CCD_value.y else 0;
  opening_CD = SC_OCD_value.y;
  opening_WD = SC_OWD_value.y;
  closing_CD = SC_CCD_value.y;
  op = if open.active then 0 else 0;
  cl = if closed.active then 1 else 0;
  y=opening_CD+opening_WD+closing_CD+op+cl+SC_crack.y+SC_crack2.y;

  connect(opening_ColdDay.active, timer.u) ;
  connect(timer.y, greaterEqual.u) ;
  connect(greaterEqual.y, T6.condition) ;
  connect(opening_ColdDay.outPort[1], T6.inPort) ;
  connect(opening_WarmDay.active, timer1.u) ;
  connect(timer1.y, greaterEqual1.u) ;
  connect(greaterEqual1.y, T7.condition) ;
  connect(opening_WarmDay.outPort[1], T7.inPort) ;
  connect(T6.outPort, open.inPort[1]) ;
  connect(T7.outPort, open.inPort[2]) ;
  connect(T2.outPort, opening_ColdDay.inPort[1]) ;
  connect(T3.outPort, opening_WarmDay.inPort[1]) ;
  connect(closing_ColdDay.active, timer2.u) ;
  connect(timer2.y, greaterEqual2.u) ;
  connect(greaterEqual2.y, T1.condition) ;
  connect(closing_ColdDay.outPort[1], T1.inPort) ;
  connect(T4.outPort, closing_ColdDay.inPort[1]) ;
  connect(closed.outPort[1], T2.inPort) ;
  connect(closed.outPort[2], T3.inPort) ;
  connect(open.outPort[1], T4.inPort) ;
  connect(T1.outPort, closed.inPort[1]) ;
  connect(closing_ColdDay.active, SC_CCD_value.u) ;
  connect(opening_ColdDay.active, SC_OCD_value.u) ;
  connect(opening_WarmDay.active, SC_OWD_value.u) ;
  connect(closed.outPort[3], T5.inPort) ;
  connect(T5.outPort, crack.inPort[1]) ;
  connect(crack.active, SC_crack.u) ;
  connect(crack.outPort[1], T2b.inPort) ;
  connect(T2b.outPort, opening_ColdDay.inPort[2]) ;
  connect(crack.outPort[2], T3b.inPort) ;
  connect(T3b.outPort, opening_WarmDay.inPort[2]) ;
  connect(crack.outPort[3], T8.inPort) ;
  connect(T8.outPort, closed.inPort[2]) ;
  connect(crack.outPort[4], T9.inPort) ;
  connect(crack2.active, SC_crack2.u) ;
  connect(T9.outPort, crack2.inPort[1]) ;
  connect(crack2.outPort[1], T2c.inPort) ;
  connect(T2c.outPort, opening_ColdDay.inPort[3]) ;
  connect(crack2.outPort[2], T3c.inPort) ;
  connect(T3c.outPort, opening_WarmDay.inPort[3]) ;
  connect(crack2.outPort[3], T8b.inPort) ;
  connect(T8b.outPort, closed.inPort[3]) 
  ;
end Control_ThScreen;

