    ;
  Modelica.Units.SI.Temperature T_air=293.15 ;

  Integer op;
  Integer cl;
  Real opening_CD;
  Real opening_WD;
  Real closing_CD;
  Modelica.StateGraph.InitialStep closed(nIn=1, nOut=2) ;
  inner Modelica.StateGraph.StateGraphRoot stateGraphRoot
    ;
  Modelica.Blocks.Interfaces.RealInput T_out(
    quantity="Temperature",
    displayUnit="degC",
    unit="K")           ;
  Modelica.Blocks.Interfaces.RealInput SC_usable
                        ;
  Modelica.Blocks.Interfaces.RealInput T_air_sp(
    quantity="Temperature",
    unit="K",
    displayUnit="degC") ;
  Modelica.Blocks.Interfaces.RealOutput y "Control signal" ;
  Modelica.StateGraph.Transition T2(condition=R_Glob_can > R_Glob_can_min
         and T_out <= (T_air_sp - 7))
    ;
  Modelica.StateGraph.Transition T3(condition=R_Glob_can > R_Glob_can_min
         and T_out > (T_air_sp - 7))
    ;
  Modelica.StateGraph.Transition T4(
    enableTimer=true,
    waitTime=3600*2,
    condition=SC_usable > 0 and T_out < T_out_sp.y)
    ;
  Modelica.StateGraph.StepWithSignal opening_ColdDay(nIn=1, nOut=1)
    ;
  Modelica.Blocks.Logical.Timer timer ;
  Modelica.StateGraph.TransitionWithSignal T6 ;
  Modelica.Blocks.Logical.GreaterEqualThreshold greaterEqual(threshold=52*60)
    ;
  Modelica.StateGraph.Step open(nOut=1, nIn=2) ;
  Modelica.StateGraph.StepWithSignal opening_WarmDay(nIn=1, nOut=1)
    ;
  Modelica.Blocks.Logical.Timer timer1
                                      ;
  Modelica.StateGraph.TransitionWithSignal T7
    ;
  Modelica.Blocks.Logical.GreaterEqualThreshold greaterEqual1(threshold=32*60)
    ;
  Modelica.StateGraph.StepWithSignal closing_ColdDay(nIn=1, nOut=1)
    ;
  Modelica.Blocks.Logical.Timer timer2
                                      ;
  Modelica.StateGraph.TransitionWithSignal T1 ;
  Modelica.Blocks.Logical.GreaterEqualThreshold greaterEqual2(threshold=52*60)
    ;
  Greenhouses.ControlSystems.Climate.Utilities.SC_closing_value SC_OWD_value(warmDay=
        true, opening=true)
    ;
  Greenhouses.ControlSystems.Climate.Utilities.SC_closing_value SC_OCD_value(opening=
        true, warmDay=false)
    ;
  Greenhouses.ControlSystems.Climate.Utilities.SC_closing_value SC_CCD_value(warmDay=
        false, opening=false)
    ;
  Modelica.Blocks.Interfaces.RealInput RH_air(quantity="Humidity")
                        ;
  Greenhouses.ControlSystems.PID PID_crack(
    Kp=0.5,
    Ti=600,
    PVmin=0.4,
    PVmax=1,
    CSmin=0.96,
    CSmax=1,
    PVstart=0.5,
    CSstart=0.5,
    steadyStateInit=false)
    ;
  Modelica.Blocks.Sources.Constant RH_air_SP(k=0.85)
    ;
  Modelica.Blocks.Sources.RealExpression T_out_sp(y=sp1.y + sp2.y)
    ;
  Modelica.Blocks.Sources.Step sp1(
    height=-2,
    startTime=3196800,
    offset=12 + 273.15)
    ;
  Modelica.Blocks.Sources.Step sp2(
    height=-2,
    offset=0,
    startTime=6480000)
    ;
  Greenhouses.ControlSystems.PID PID_crack_T(
    Kp=0.5,
    Ti=600,
    CSmax=1,
    PVstart=0.5,
    CSstart=0.5,
    steadyStateInit=false,
    PVmin=12,
    PVmax=28,
    CSmin=0.98) ;
  Modelica.Blocks.Sources.RealExpression T_air_sp_crack(y=T_air_sp + 1.5)
    ;
equation
  PID_crack_T.PV=T_air;
//   opening_CD = if opening_ColdDay.active then SC_OCD_value.y else 0;
//   opening_WD = if opening_WarmDay.active then SC_OWD_value.y else 0;
//   closing_CD = if closing_ColdDay.active then SC_CCD_value.y else 0;
  opening_CD = SC_OCD_value.y;
  opening_WD = SC_OWD_value.y;
  closing_CD = SC_CCD_value.y;
  op = if open.active then 0 else 0;
  cl = if closed.active then 1 else 0;
  y=opening_CD+opening_WD+closing_CD+op+cl*min(PID_crack.CS,PID_crack_T.CS);

  connect(opening_ColdDay.active, timer.u) ;
  connect(timer.y, greaterEqual.u) ;
  connect(greaterEqual.y, T6.condition) ;
  connect(opening_ColdDay.outPort[1], T6.inPort) ;
  connect(opening_WarmDay.active, timer1.u) ;
  connect(timer1.y, greaterEqual1.u) ;
  connect(greaterEqual1.y, T7.condition) ;
  connect(opening_WarmDay.outPort[1], T7.inPort) ;
  connect(T6.outPort, open.inPort[1]) ;
  connect(T7.outPort, open.inPort[2]) ;
  connect(T2.outPort, opening_ColdDay.inPort[1]) ;
  connect(T3.outPort, opening_WarmDay.inPort[1]) ;
  connect(closing_ColdDay.active, timer2.u) ;
  connect(timer2.y, greaterEqual2.u) ;
  connect(greaterEqual2.y, T1.condition) ;
  connect(closing_ColdDay.outPort[1], T1.inPort) ;
  connect(T4.outPort, closing_ColdDay.inPort[1]) ;
  connect(closed.outPort[1], T2.inPort) ;
  connect(closed.outPort[2], T3.inPort) ;
  connect(open.outPort[1], T4.inPort) ;
  connect(T1.outPort, closed.inPort[1]) ;
  connect(closing_ColdDay.active, SC_CCD_value.u) ;
  connect(opening_ColdDay.active, SC_OCD_value.u) ;
  connect(opening_WarmDay.active, SC_OWD_value.u) ;
  connect(RH_air, PID_crack.PV) ;
  connect(RH_air_SP.y, PID_crack.SP) ;
  connect(T_air_sp_crack.y, PID_crack_T.SP) 
  ;
end Control_ThScreen_2;

