model Control_1 "Controller for the CHP and heat pump and TES"
  parameter Modelica.Units.SI.Temperature T_max=273.15 + 60 "Fill level of tank 1";
  parameter Modelica.Units.SI.Temperature T_min=273.15 + 50
    "Lowest level of tank 1 and 2";
  parameter Modelica.Units.SI.Time waitTime=2 "Wait time, between operations";
  parameter Modelica.Units.SI.MassFlowRate Mdot_max=38
    "Maximum mass flow rate in the greenhouse heating circuit";
  Modelica.Units.SI.Temperature T_high_tank=90 + 273.15
    ;

  Modelica.StateGraph.InitialStep All_off(nIn=1, nOut=1)
                                          ;
  Modelica.Blocks.Interfaces.BooleanOutput CHP ;
  Modelica.Blocks.Interfaces.BooleanOutput ElectricalHeater ;
  Modelica.Blocks.Sources.BooleanExpression Set_CHP(y=runCHP.active)
    ;
  Modelica.Blocks.Sources.BooleanExpression Set_ElectricalHeater(y=not1.y
         and time > 1E3)
    ;
  inner Modelica.StateGraph.StateGraphRoot stateGraphRoot
    ;
  Modelica.Blocks.Interfaces.RealInput T_tank(quantity="ThermodynamicTemperature",unit="K",displayUnit="degC")
    ;
  Modelica.StateGraph.Step runCHP(nIn=1, nOut=1) ;
  Modelica.StateGraph.Transition T2(condition=T_tank > T_max or Mdot_1ry <= 0.1
        *Mdot_max or T_high_tank > T_max)
    ;
  Modelica.Blocks.Logical.Hysteresis hysteresis(
    pre_y_start=false,
    uLow=T_min - 5,
    uHigh=T_max - 5)
    ;
  Modelica.Blocks.Logical.Not not1
    ;
  Modelica.StateGraph.Transition T1(condition=T_tank < T_min and T_high_tank <
        T_max and Mdot_1ry > 0.1*Mdot_max or T_tank < T_max - 10 and Mdot_1ry
         > Mdot_max)
    ;
  Modelica.Blocks.Interfaces.RealInput Mdot_1ry(
    quantity="ThermodynamicMassFlowRate",
    unit="kg/s",
    displayUnit="kg/s") ;
  Modelica.Blocks.Interfaces.BooleanOutput HP ;
  Modelica.Blocks.Sources.BooleanExpression Set_HP(y=runCHP.active and
        T_low_TES < 333.15) ;
  Modelica.Blocks.Interfaces.RealInput T_low_TES(
    quantity="ThermodynamicTemperature",
    unit="K",
    displayUnit="degC") ;
equation

  connect(Set_CHP.y, CHP) ;
  connect(runCHP.outPort[1], T2.inPort) ;
  connect(T2.outPort, All_off.inPort[1]) ;
  connect(T_tank, hysteresis.u) ;
  connect(hysteresis.y, not1.u) ;
  connect(All_off.outPort[1],T1. inPort) ;
  connect(T1.outPort, runCHP.inPort[1]) ;
  connect(Set_ElectricalHeater.y, ElectricalHeater) ;
  connect(Set_HP.y, HP) 
  ;
end Control_1;

