model GlobalSystem_1
  "Greenhouse connected to a CHP and thermal energy storage"
  extends Modelica.Icons.Example;
  Real Mdot_2ry(start=0.528);
  Real E_gas_CHP(unit="kW.h");
  Real E_el_CHP(unit="kW.h");
  Real E_th_CHP(unit="kW.h");
  Real E_gen(unit="kW.h");
  Real E_G(unit="kW.h");
  Real E_amb_TES(unit="kW.h");
  Real Pi_buy(unit="1/(kW.h)")=0.05 "50euro/MWh";
  Real Pi_sell(unit="1/(kW.h)");
  Real E_el_sell(unit="kW.h");
  Real E_el_buy(unit="kW.h");
  Real C_sell;
  Real C_buy;
  Real E_gas_CHP_kWhm2(unit="kW.h/m2");
  Real E_el_CHP_kWhm2(unit="kW.h/m2");
  Real E_th_CHP_kWhm2(unit="kW.h/m2");
  Real E_gen_kWhm2(unit="kW.h/m2");
  Real E_G_kWhm2(unit="kW.h/m2");
  Real E_amb_TES_kWhm2(unit="kW.h/m2");
  Real E_el_sell_kWhm2(unit="kW.h/m2");
  Real E_el_buy_kWhm2(unit="kW.h/m2");
  Greenhouses.Components.HVAC.CHP CHP(
    redeclare package Medium = Modelica.Media.Water.ConstantPropertyLiquidWater,
    Tmax=373.15,
    Th_nom=773.15)
    ;
  Modelica.Fluid.Sensors.Temperature T_ex_CHP(redeclare package Medium =
        Modelica.Media.Water.ConstantPropertyLiquidWater)
    ;
  Modelica.Fluid.Sensors.Temperature T_su_CHP(redeclare package Medium =
        Modelica.Media.Water.ConstantPropertyLiquidWater)
    ;
  Modelica.Thermal.HeatTransfer.Sources.PrescribedHeatFlow Qdot_nom_gas_CHP
    ;
  Modelica.Blocks.Sources.Constant set_Qdot_nom_gas_CHP(k=2800e3)
    ;
  Greenhouses.Components.HVAC.HeatStorageWaterHeater.Heat_storage_hx_R TES(
    U_amb=2,
    steadystate_hx=false,
    Unom_hx=1000,
    steadystate_tank=false,
    redeclare package MainFluid =
        Modelica.Media.Water.ConstantPropertyLiquidWater,
    N1=1,
    N2=15,
    A_hx=3800,
    V_tank=385,
    Wdot_res=115500,
    redeclare package SecondaryFluid =
        Modelica.Media.Water.ConstantPropertyLiquidWater,
    htot=4,
    h1=0.2,
    h2=4,
    h_T=2,
    Tmax=373.15,
    Tstart_inlet_tank=303.15,
    Tstart_outlet_tank=323.15,
    Tstart_inlet_hx=333.15,
    Tstart_outlet_hx=313.15)
    ;
  Modelica.Fluid.Sensors.Temperature T_ex_TES(redeclare package Medium =
        Modelica.Media.Water.ConstantPropertyLiquidWater)
    ;
  Modelica.Fluid.Sensors.Temperature T_su_G(redeclare package Medium =
        Modelica.Media.Water.ConstantPropertyLiquidWater)
    ;
  Modelica.Fluid.Sensors.Temperature T_ex_G(redeclare package Medium =
        Modelica.Media.Water.ConstantPropertyLiquidWater)
    ;
  Greenhouses.Flows.FluidFlow.Pump_Mdot pump_2ry(redeclare package Medium =
        Modelica.Media.Water.ConstantPropertyLiquidWater, Mdot_0=20)
    ;
  Greenhouses.Flows.FluidFlow.Reservoirs.SinkP sinkP_2ry(redeclare package
      Medium = Modelica.Media.Water.ConstantPropertyLiquidWater, p0=1000000)
    ;
  Greenhouses.Flows.FluidFlow.Pdrop pdrop_2ry(
    Mdot_max=0.5,
    redeclare package Medium = Modelica.Media.Water.ConstantPropertyLiquidWater,
    DELTAp_max=1100)
    ;
  Greenhouses.Components.Greenhouse.Unit.Greenhouse   G
    ;
  ControlSystems.HVAC.Control_1 controller(
    T_high_tank=TES.flow1Dim.Cells[15].T,
    T_max=353.15,
    T_min=303.15,
    Mdot_max=86)
    ;
  Greenhouses.Flows.FluidFlow.Pump_Mdot pump_1ry(redeclare package Medium =
        Modelica.Media.Water.ConstantPropertyLiquidWater, Mdot_0=0.528)
    ;
  Greenhouses.Flows.FluidFlow.Pdrop pdrop_1ry(
    redeclare package Medium = Modelica.Media.Water.ConstantPropertyLiquidWater,
    Mdot_max=0.5,
    DELTAp_max=1100)
    ;
  Greenhouses.Flows.FluidFlow.Reservoirs.SinkP sinkP_1ry(redeclare package
      Medium = Modelica.Media.Water.ConstantPropertyLiquidWater, p0=1000000)
    ;
  Modelica.Blocks.Sources.RealExpression set_Mdot_2ry(y=Mdot_2ry)
    ;
equation
  Mdot_2ry = if time<1e4 then 20 else (if controller.CHP then 15 else 1);
  der(E_gas_CHP*1e3*3600) = CHP.Qdot_gas;
  der(E_el_CHP*1e3*3600) = CHP.Wdot_el;
  der(E_th_CHP*1e3*3600) = CHP.prescribedHeatFlow.Q_flow;
  E_gen = E_th_CHP;
  E_G = G.E_th_tot;
  der(E_amb_TES*1e3*3600) = sum(TES.cell1DimInc_hx.Q_tot);
  Pi_sell = Pi_buy/4;
  der(E_el_sell*1e3*3600) = max(0,CHP.Wdot_el-G.illu.W_el);
  der(E_el_buy*1e3*3600) = max(0,G.illu.W_el-CHP.Wdot_el);
  C_sell = Pi_sell*E_el_sell;
  C_buy = Pi_buy*E_el_buy;
  E_gas_CHP_kWhm2=E_gas_CHP/G.surface.k;
  E_el_CHP_kWhm2=E_el_CHP/G.surface.k;
  E_th_CHP_kWhm2=E_th_CHP/G.surface.k;
  E_gen_kWhm2=E_gen/G.surface.k;
  E_G_kWhm2=E_G/G.surface.k;
  E_amb_TES_kWhm2=E_amb_TES/G.surface.k;
  E_el_sell_kWhm2=E_el_sell/G.surface.k;
  E_el_buy_kWhm2=E_el_buy/G.surface.k;
  connect(T_ex_CHP.port, CHP.OutFlow) ;
  connect(T_su_CHP.port, CHP.InFlow) ;
  connect(Qdot_nom_gas_CHP.port, CHP.HeatSource) ;
  connect(set_Qdot_nom_gas_CHP.y, Qdot_nom_gas_CHP.Q_flow) ;
  connect(T_su_G.port, TES.MainFluid_ex) ;
  connect(T_ex_G.port, TES.MainFluid_su) ;
  connect(CHP.OutFlow, TES.SecondaryFluid_ex) ;
  connect(pdrop_2ry.OutFlow, pump_2ry.inlet) ;
  connect(sinkP_2ry.flangeB, pump_2ry.inlet) ;
  connect(T_ex_TES.port, TES.SecondaryFluid_su) ;
  connect(pdrop_2ry.InFlow, TES.SecondaryFluid_su) ;
  connect(TES.Temperature, controller.T_tank) ;
  connect(controller.CHP, CHP.on_off) ;
  connect(pdrop_1ry.OutFlow, pump_1ry.inlet) ;
  connect(sinkP_1ry.flangeB, pump_1ry.inlet) ;
  connect(G.flangeB, TES.MainFluid_su) ;
  connect(pump_1ry.outlet, G.flangeA) ;
  connect(pdrop_1ry.InFlow, TES.MainFluid_ex) ;
  connect(G.PID_Mdot_CS, pump_1ry.flow_in) ;
  connect(T_ex_TES.T, controller.T_low_TES) ;
  connect(G.PID_Mdot_CS, controller.Mdot_1ry) ;
  connect(set_Mdot_2ry.y, pump_2ry.flow_in) ;
  connect(pump_2ry.outlet, CHP.InFlow) 
  ;
end GlobalSystem_1;

within Greenhouses.Flows.CO2MassTransfer;
model CO2_Air "CO2 mass balance of an air volume"
  import Greenhouse = Greenhouses;

  /*********************** Parameters ***********************/
  Modelica.Units.SI.Length cap_CO2=4
    "Capacity of the air to store CO2, equals the height of the air compartment"
    ;

  /*********************** Initialization ***********************/
  parameter Real CO2_start(unit="mg/m3")=1940 ;
  parameter Boolean steadystate=true
    "if true, sets the derivative of VP to zero during Initialization"     ;

  /*********************** Variables ***********************/
  Real MC_flow(unit="mg/(m2.s)");
  Real CO2(unit="mg/m3",start=CO2_start,min=0);
  Real CO2_ppm;

  /******************** Connectors ********************/
  Greenhouse.Interfaces.CO2.CO2Port_a port(CO2(start=CO2_start))
    "Partial CO2 pressure" ;

  Greenhouse.Flows.Sources.CO2.PrescribedConcentration prescribedPressure
    ;
protected
  Modelica.Blocks.Sources.RealExpression portCO2(y=CO2) "Port temperature"
    ;
equation
  port.MC_flow = MC_flow;
  der(CO2) = 1/cap_CO2 * MC_flow;
  CO2_ppm = CO2/1.94
    "1ppm=1.94mgCO2/m3air from 22.71108 l/mol and molar mass of CO2 44.01 g/mol";

  connect(prescribedPressure.port, port) ;
  connect(portCO2.y, prescribedPressure.CO2) ;
initial equation
  if steadystate then
    der(CO2)=0;
  end if
  ;
end CO2_Air;

within Greenhouses.Flows.CO2MassTransfer;
model CO2_SetPoint
  "The CO2 setpoint depends on the global radiation and the aperture of the ventilation openings"
  parameter Modelica.Units.SI.HeatFlux I_g_max=500
    "Outdoor global radiation at which the maximum CO2 concentration set-point could be reached";
  parameter Real U_vents_max=0.1
    "Window aperture at which the minimum CO2 concentration set-point could be reached";
  parameter Real CO2_Air_ExtMax(unit="umol/mol")=850
    "Maximum CO2 concentration set-point";
  parameter Real CO2_Air_ExtMin(unit="umol/mol")=365
    "Minimum CO2 concentration set-point";

  Real U_vents=0 "Window aperture" ;
  Modelica.Units.SI.HeatFlux I_g=300 "Outdoor global radiation"
    ;

  Real f_Ig;
  Real g_Uv;
  Real CO2_Air_ExtOn(unit="umol/mol");

  Modelica.Blocks.Interfaces.RealOutput y(unit="mg/m3")
    ;
equation
  y=CO2_Air_ExtOn*1.94;
  CO2_Air_ExtOn = f_Ig*g_Uv*(CO2_Air_ExtMax-CO2_Air_ExtMin) + CO2_Air_ExtMin;
  f_Ig = min(1,I_g/I_g_max);
  g_Uv = 1/(1+exp(100*(U_vents-U_vents_max)))*(1-U_vents/U_vents_max)
  ;
end CO2_SetPoint;

