model MC_ventilation
  "CO2 mass flow exchange accompanying an air ventilation process. Distinguishes from the two different air zones on the presence of a thermal screen."
  extends Greenhouses.Interfaces.CO2.Element1D;

  /*********************** Parameters ***********************/
  parameter Boolean thermalScreen=false
    "presence of a thermal screen in the greenhouse";
  parameter Boolean topAir=false
    "False for: Main air zone; True for: Top air zone"                  ;

  /*********************** Varying inputs ***********************/
  Real SC=0 "Screen closure 1:closed, 0:open" ;
  Real U_vents(min=0,max=1)=0
    "From 0 to 1, control of the aperture of the roof vents"                             ;
  Modelica.Units.SI.Temperature T_a=300 "Temperature at port a (filled square)"
    ;
  Modelica.Units.SI.Temperature T_b=300 "Temperature at port b (empty square)"
    ;
  Modelica.Units.SI.Velocity u=0 "Wind speed"
    ;

  /*********************** Variables ***********************/
  Real f_vent;

  HeatAndVapourTransfer.VentilationRates.NaturalVentilationRate_2
    airExchangeRate(
    thermalScreen=thermalScreen,
    u=u,
    dT=T_a - T_b,
    U_roof=U_vents,
    SC=SC,
    T_a=T_a,
    T_b=T_b) ;
equation
  // CO2 exchange, dependent on the air exchange rate
  if thermalScreen then
    if not topAir then
      f_vent = airExchangeRate.f_vent_air;
    else
      f_vent = airExchangeRate.f_vent_top;
    end if;
  else
    f_vent = airExchangeRate.f_vent_air;
  end if;
  MC_flow = f_vent*dC

  ;
end MC_ventilation;

