model Cell1DimInc "1-D incompressible fluid flow model"
  import Greenhouse = Greenhouses;
  replaceable package Medium = Modelica.Media.Water.ConstantPropertyLiquidWater constrainedby
    Modelica.Media.Interfaces.PartialMedium "Medium in the component"
      ;

/************ Thermal and fluid ports ***********/
  Modelica.Fluid.Interfaces.FluidPort_a
                                      InFlow(redeclare package Medium = Medium)
    ;
  Modelica.Fluid.Interfaces.FluidPort_b
                                      OutFlow(redeclare package Medium = Medium)
    ;
  Greenhouse.Interfaces.Heat.ThermalPortL Wall_int ;
/************ Geometric characteristics **************/
  parameter Integer Nt(min=1)=1 "Number of cells in parallel";
  constant Real pi = Modelica.Constants.pi "pi-greco";
  parameter Modelica.Units.SI.Volume Vi "Volume of a single cell";
  parameter Modelica.Units.SI.Area Ai "Lateral surface of a single cell";
  parameter Modelica.Units.SI.MassFlowRate Mdotnom "Nominal fluid flow rate";
  parameter Modelica.Units.SI.CoefficientOfHeatTransfer Unom
    "Nominal Heat transfer coefficient ";
  /************ FLUID INITIAL VALUES ***************/
  parameter Modelica.Units.SI.Pressure pstart "Fluid pressure start value"
    ;
  parameter Medium.SpecificEnthalpy hstart=1E5 "Start value of enthalpy"
    ;
/****************** NUMERICAL OPTIONS  ***********************/
  import Greenhouses.Functions.Enumerations.Discretizations;
  parameter Discretizations Discretization=Greenhouse.Functions.Enumerations.Discretizations.centr_diff
    "Selection of the spatial discretization scheme"  ;
  parameter Boolean steadystate=true
    "if true, sets the derivative of h (working fluids enthalpy in each cell) to zero during Initialization"
    ;
/********************************* HEAT TRANSFER MODEL ********************************/
/* Heat transfer Model */
 replaceable model HeatTransfer =
 Greenhouses.Flows.FluidFlow.HeatTransfer.MassFlowDependence
 constrainedby
    Greenhouses.Flows.FluidFlow.HeatTransfer.BaseClasses.PartialHeatTransferZones
    "Convective heat transfer"                                                         ;
HeatTransfer heatTransfer( redeclare final package Medium = Medium,
final n=1,
final Mdotnom = Mdotnom/Nt,
final Unom_l = Unom,
final Unom_tp = Unom,
final Unom_v = Unom,
final M_dot = M_dot,
final x = 0,
final FluidState={fluidState})
                          ;
/***************  VARIABLES ******************/
  Medium.ThermodynamicState  fluidState;
  Medium.AbsolutePressure p(start=pstart);
  Modelica.Units.SI.MassFlowRate M_dot(start=Mdotnom/Nt);
  Medium.SpecificEnthalpy h(start=hstart, stateSelect = StateSelect.always)
    "Fluid specific enthalpy at the cells";
  Medium.Temperature T "Fluid temperature";
  //Modelica.SIunits.Temperature T_wall "Internal wall temperature";
  Medium.Density rho "Fluid cell density";
  Modelica.Units.SI.SpecificEnthalpy hnode_su "Enthalpy state variable at inlet node";
  Modelica.Units.SI.SpecificEnthalpy hnode_ex "Enthalpy state variable at outlet node";
  Modelica.Units.SI.HeatFlux qdot "heat flux at each cell";
//   Modelica.SIunits.CoefficientOfHeatTransfer U
//     "Heat transfer coefficient between wall and working fluid";
  Modelica.Units.SI.Power Q_tot "Total heat flux exchanged by the thermal port";
  Modelica.Units.SI.Mass M_tot "Total mass of the fluid in the component";
/***********************************  EQUATIONS ************************************/
equation
  /* Fluid Properties */
  fluidState = Medium.setState_ph(p, h);
  T = Medium.temperature(fluidState);
  rho = Medium.density(fluidState);
  /* ENERGY BALANCE */
  Vi*rho*der(h) + M_dot*(hnode_ex - hnode_su) = Ai*qdot "Energy balance";
  Q_tot = Ai*qdot*Nt "Total heat flow through the thermal port";
  M_tot = Vi*rho;
qdot = heatTransfer.q_dot[1];
  if (Discretization == Discretizations.centr_diff) then
    hnode_su = inStream(InFlow.h_outflow);
    hnode_ex = 2*h - hnode_su;
  elseif (Discretization == Discretizations.centr_diff_AllowFlowReversal) then
    if M_dot >= 0 then       // Flow is going the right way
      hnode_su = inStream(InFlow.h_outflow);
      hnode_ex = 2*h - hnode_su;
    else      // Reverse flow
      hnode_ex = inStream(OutFlow.h_outflow);
      hnode_su = 2*h - hnode_ex;
    end if;
  elseif (Discretization == Discretizations.upwind_AllowFlowReversal) then
    hnode_ex = if M_dot >= 0 then h else inStream(OutFlow.h_outflow);
    hnode_su = if M_dot <= 0 then h else inStream(InFlow.h_outflow);
  elseif (Discretization == Discretizations.upwind) then
    hnode_su = inStream(InFlow.h_outflow);
    hnode_ex = h;
  else                                           // Upwind scheme with smoothing (not implemented here)
    hnode_ex = if M_dot >= 0 then h else inStream(OutFlow.h_outflow);
    hnode_su = if M_dot <= 0 then h else inStream(InFlow.h_outflow);
  end if;
//* BOUNDARY CONDITIONS *//
 /* Enthalpies */
  hnode_su = InFlow.h_outflow;
  OutFlow.h_outflow = hnode_ex;
/* pressures */
  p = OutFlow.p;
  InFlow.p = p;
/*Mass Flow*/
  M_dot = InFlow.m_flow/Nt;
  OutFlow.m_flow/Nt = -M_dot;
  InFlow.Xi_outflow = inStream(OutFlow.Xi_outflow);
  OutFlow.Xi_outflow = inStream(InFlow.Xi_outflow);
initial equation
  if steadystate then
    der(h) = 0;
      end if;

equation
  connect(heatTransfer.thermalPortL[1], Wall_int) 
  ;
end Cell1DimInc;

within Greenhouses.Flows.FluidFlow;
model Flow1DimInc
  "1-D fluid flow model (finite volume discretization - incompressible fluid model). Based on the Cell component"
  import Greenhouse = Greenhouses;
  replaceable package Medium = Modelica.Media.Water.ConstantPropertyLiquidWater constrainedby
    Modelica.Media.Interfaces.PartialMedium "Medium in the component"
      ;
public
 record SummaryClass
    replaceable Arrays T_profile;
    record Arrays
    parameter Integer n;
      Modelica.Units.SI.Temperature[n] T_cell;
    end Arrays;
    parameter Integer n;
    Modelica.Units.SI.SpecificEnthalpy[n] h;
    Modelica.Units.SI.Temperature[n] T;
    Modelica.Units.SI.SpecificEnthalpy[n + 1] hnode;
    Modelica.Units.SI.Density[n] rho;
    Modelica.Units.SI.MassFlowRate Mdot;
    Modelica.Units.SI.Pressure p;
 end SummaryClass;
 SummaryClass Summary(T_profile(n=N, T_cell = Cells[:].T), n=N, h = Cells[:].h, hnode = hnode_, rho = Cells.rho, T = Cells.T, Mdot = InFlow.m_flow, p = Cells[1].p);
/************ Thermal and fluid ports ***********/
  Modelica.Fluid.Interfaces.FluidPort_a
                                      InFlow(redeclare package Medium = Medium)
    ;
  Modelica.Fluid.Interfaces.FluidPort_b
                                      OutFlow(redeclare package Medium = Medium)
    ;
/************ Geometric characteristics **************/
  parameter Integer Nt(min=1)=1 "Number of cells in parallel";
  constant Real pi = Modelica.Constants.pi "pi-greco";
  parameter Integer N(min=1)=10 "Number of cells";
  parameter Modelica.Units.SI.Area A=16.18
    "Lateral surface of the tube: heat exchange area";
  parameter Modelica.Units.SI.Volume V=0.03781 "Volume of the tube";
  parameter Modelica.Units.SI.MassFlowRate Mdotnom=0.2588 "Nominal fluid flow rate";
  parameter Modelica.Units.SI.CoefficientOfHeatTransfer Unom
    "if HTtype = Const: Heat transfer coefficient";
 /********************************* FLUID INITIAL VALUES ******************************/
  parameter Modelica.Units.SI.Pressure pstart "Fluid pressure start value"
    ;
  parameter Medium.Temperature Tstart_inlet "Inlet temperature start value"
     ;
  parameter Medium.Temperature Tstart_outlet "Outlet temperature start value"
     ;
  parameter Medium.SpecificEnthalpy hstart[N]=linspace(
        Medium.specificEnthalpy_pTX(pstart,Tstart_inlet,Medium.reference_X),Medium.specificEnthalpy_pTX(pstart,Tstart_outlet,Medium.reference_X),
        N) "Start value of enthalpy vector (initialized by default)"
    ;
/***************************************   NUMERICAL OPTIONS  ***************************************************/
  import Greenhouses.Functions.Enumerations.Discretizations;
  parameter Discretizations Discretization=Greenhouse.Functions.Enumerations.Discretizations.centr_diff
    "Selection of the spatial discretization scheme"  ;
  parameter Boolean steadystate=true
    "if true, sets the derivative of h (working fluids enthalpy in each cell) to zero during Initialization"
    ;
  /******************************* HEAT TRANSFER MODEL **************************************/
replaceable model Flow1DimIncHeatTransferModel =
    Greenhouses.Flows.FluidFlow.HeatTransfer.MassFlowDependence
constrainedby
    Greenhouses.Flows.FluidFlow.HeatTransfer.BaseClasses.PartialHeatTransferZones
    "Fluid heat transfer model" ;
/***************  VARIABLES ******************/
  Modelica.Units.SI.Power Q_tot "Total heat flux exchanged by the thermal port";
  Modelica.Units.SI.Mass M_tot "Total mass of the fluid in the component";
  /********************************** CELLS *****************************************/
 Greenhouses.Flows.FluidFlow.Cell1DimInc Cells[N](
    redeclare package Medium = Medium,
    redeclare each final model HeatTransfer = Flow1DimIncHeatTransferModel,
    each Vi=V/N,
    each Ai=A/N,
    each Nt=Nt,
    each Mdotnom=Mdotnom,
    each Unom=Unom,
    each pstart=pstart,
    each Discretization=Discretization,
    hstart=hstart,
    each steadystate=steadystate)
    ;
  Greenhouses.Interfaces.Heat.ThermalPortConverter thermalPortConverter(N=N)
    ;
protected
  Modelica.Units.SI.SpecificEnthalpy hnode_[N + 1];
  /*************************************** EQUATION *************************************/
public
  Greenhouse.Interfaces.Heat.HeatPortConverter_ThermoCycle_Modelica
    heatPort_ThermoCycle_Modelica(
    N=N,
    A=A,
    Nt=Nt) ;
public
  Greenhouse.Interfaces.Heat.HeatPorts_a[N] heatPorts_a ;
equation
  // Connect wall and refrigerant cells with eachother
  for i in 1:N-1 loop
    connect(Cells[i].OutFlow, Cells[i+1].InFlow);
  end for;
  hnode_[1:N] = Cells.hnode_su;
  hnode_[N+1] = Cells[N].hnode_ex;
  Q_tot = A/N*sum(Cells.qdot)*Nt "Total heat flow through the thermal port";
  M_tot = V/N*sum(Cells.rho);
  connect(InFlow, Cells[1].InFlow) ;
  connect(thermalPortConverter.single, Cells.Wall_int) ;
  connect(Cells[N].OutFlow, OutFlow) ;
  connect(heatPort_ThermoCycle_Modelica.thermocyclePort, thermalPortConverter.multi)
    ;
  connect(heatPort_ThermoCycle_Modelica.heatPorts, heatPorts_a) 
  ;
end Flow1DimInc;

within Greenhouses.Flows.FluidFlow;
model Pdrop "Linear pressure drop"
  extends Greenhouses.Icons.Water.PressDrop;
  replaceable package Medium = Modelica.Media.Water.ConstantPropertyLiquidWater constrainedby
    Modelica.Media.Interfaces.PartialMedium "Medium in the component"
      ;
   /* Define the type of pressure drop */
  import Greenhouses.Functions.Enumerations.PressureDrops;
  parameter PressureDrops DPtype=PressureDrops.UD;
  parameter Modelica.Units.SI.Pressure p_su_start=1e5 "Inlet pressure start value"
    ;
  parameter Modelica.Units.SI.Pressure DELTAp_start=10000
    "Start value for the pressure drop" ;
  parameter Modelica.Units.SI.MassFlowRate Mdot_start=0.1
    "Mass flow rate initial value" ;
  parameter Modelica.Units.SI.MassFlowRate Mdot_max=0.1 "flow rate at DELTAp_max";
  parameter Modelica.Units.SI.Pressure DELTAp_max=20E5 "Pressure drop at Mdot_max";
  /* Variables */
  Modelica.Units.SI.MassFlowRate Mdot(start=Mdot_start);
  Modelica.Units.SI.Pressure DELTAp(start=DELTAp_start);
  Modelica.Fluid.Interfaces.FluidPort_a InFlow(
                                              redeclare package Medium = Medium)
    ;
  Modelica.Fluid.Interfaces.FluidPort_b OutFlow(
                                               redeclare package Medium =
        Medium)
    ;
equation
  InFlow.m_flow + OutFlow.m_flow = 0 "Mass balance";
    if (DPtype == PressureDrops.ORCnextHP) then
    DELTAp = Greenhouses.Functions.TestRig.PressureDropCorrelation_HP(M_flow=
      Mdot);
    DELTAp = InFlow.p - OutFlow.p;
    elseif (DPtype == PressureDrops.ORCnextLP) then
    DELTAp = Greenhouses.Functions.TestRig.PressureDropCorrelation_LP(M_flow=
      Mdot);
    DELTAp = InFlow.p - OutFlow.p;
    else
     DELTAp = InFlow.p - OutFlow.p;
     Mdot = Mdot_max*DELTAp/DELTAp_max;
     end if;
  /* BOUNDARY CONDITIONS */
  Mdot = InFlow.m_flow;
  InFlow.h_outflow = inStream(OutFlow.h_outflow);
  inStream(InFlow.h_outflow) = OutFlow.h_outflow;
initial equation

  ;
end Pdrop;

within Greenhouses.Flows.FluidFlow;
model Pump_Mdot "Pump model - Prescribed mass flow rate"
  import Greenhouses;
  /***************************************** FLUID *****************************************/
  replaceable package Medium = Modelica.Media.Water.ConstantPropertyLiquidWater constrainedby
    Modelica.Media.Interfaces.PartialMedium "Medium in the component"
      ;
  extends Greenhouses.Icons.Water.Pump;

  /***************************************** PARAMETERS *****************************************/
  parameter Modelica.Units.SI.MassFlowRate Mdot_0=1
    "Mass flow if external signal not connected";
  parameter Real eta_is=1 "Overall Isentropic efficiency of the pump";
  parameter Boolean NeglectDELTAh=true
    "if true, neglects the enthalpy difference due to the compression";

  /***************************************** VARIABLES *****************************************/
  Modelica.Units.SI.MassFlowRate Mdot "Mass flow rate";
  Modelica.Units.SI.SpecificEnthalpy h "Fluid specific enthalpy";
  Modelica.Units.SI.Pressure p "Inlet pressure";
  Modelica.Units.SI.Density rho(start=1000) "Liquid density";
  Modelica.Units.SI.Power Wdot "Power Consumption";
  Modelica.Fluid.Interfaces.FluidPort_a inlet(
                                             redeclare package Medium = Medium)
    ;
  Modelica.Fluid.Interfaces.FluidPort_b outlet(
                                              redeclare package Medium = Medium)
    ;
  Modelica.Blocks.Interfaces.RealInput flow_in
                                            ;

equation
  Mdot = flow_in;
  if cardinality(flow_in) == 0 then
    flow_in = Mdot_0;
  end if;

  h = noEvent(if Mdot <= 0 then inStream(outlet.h_outflow) else inStream(inlet.h_outflow));
  p = noEvent(if Mdot <= 0 then outlet.p else inlet.p);
  //h = if Mdot <= 0 then inStream(outlet.h_outflow) else inStream(inlet.h_outflow);
  //p = if Mdot <= 0 then outlet.p else inlet.p;
  rho = Medium.density_phX(p,h,Medium.X_default);

  Wdot = Mdot * (outlet.p - inlet.p)/rho / eta_is;

  // Enthalpy difference due to compression and heating up in the pump is neglected:
  if NeglectDELTAh then
    outlet.h_outflow = inStream(inlet.h_outflow);
    inlet.h_outflow = inStream(outlet.h_outflow);
  else
    outlet.h_outflow = inStream(inlet.h_outflow)+(outlet.p - inlet.p)/rho / eta_is;
    inlet.h_outflow = inStream(outlet.h_outflow)+(inlet.p - outlet.p)/rho / eta_is;
  end if;
  /* Mass flow */
  inlet.m_flow = Mdot;
  outlet.m_flow = -Mdot "Flow rate is negative when leaving a component!"
  ;
end Pump_Mdot;

