model Constant "Constant: Constant heat transfer coefficient"
  extends
    Greenhouses.Flows.FluidFlow.HeatTransfer.BaseClasses.PartialSinglePhaseCorrelation;
  extends
    Greenhouses.Flows.FluidFlow.HeatTransfer.BaseClasses.PartialPipeCorrelation(
      final d_h=0, final A_cro=0);
  extends
    Greenhouses.Flows.FluidFlow.HeatTransfer.BaseClasses.PartialPlateHeatExchangerCorrelation(
      final d_h=0, final A_cro=0);

  parameter Modelica.Units.SI.CoefficientOfHeatTransfer U_c=1000
    "Heat transfer coefficient";
equation
  U = U_c

;
end Constant;

within Greenhouses.Flows.FluidFlow.HeatTransfer.SinglePhaseCorrelations;
model DittusBoelter1930
  "The Dittus-Boelter correlation for turbulent single phase flow"
  extends
    Greenhouses.Flows.FluidFlow.HeatTransfer.BaseClasses.PartialSinglePhaseCorrelation;
  //extends
  //  ThermoCycle.Components.HeatFlow.HeatTransfer.BaseClasses.PartialPipeCorrelation;
  extends
    Greenhouses.Flows.FluidFlow.HeatTransfer.BaseClasses.PartialPlateHeatExchangerCorrelation;

  //parameter Modelica.SIunits.Length d_h(min=0)=0 "Hydraulic diameter";
  //parameter Modelica.SIunits.Area A_cro(min=0)=Modelica.Constants.pi * d_h^2 / 4
  //  "Cross-sectional area";

  parameter Real a = 0.023 "Factor: 0.023 pipe, 0.035 plate HX?";
  parameter Real b = 0.800 "Reynolds exponent";
  parameter Real c = 0.400 "Prandl exponent: 0.4 heating, 0.3 cooling";

  Modelica.Units.SI.Length cLen(min=0) "Characteristic length";
  Modelica.Units.SI.Velocity cVel "Characteristic velocity";

  Modelica.Units.SI.ReynoldsNumber Re(min=0);
  Modelica.Units.SI.PrandtlNumber Pr(min=0);
  Modelica.Units.SI.NusseltNumber Nu(min=0);

  Medium.ThermalConductivity lambda;
  Medium.DynamicViscosity eta;
  Medium.Density rho;

  Modelica.Units.SI.VolumeFlowRate V_dot;

equation
  rho = Medium.density(state);
  cLen  = d_h;
  V_dot = m_dot / rho;
  cVel  = abs(V_dot) / A_cro;
  // Get transport properties from Medium model
  Pr = min(100, Medium.prandtlNumber(state));
  assert(Pr > 0, "Invalid Prandtl number, make sure transport properties are calculated.");
  eta = min(10, Medium.dynamicViscosity(state));
  assert(eta > 0, "Invalid viscosity, make sure transport properties are calculated.");
  lambda = min(10, Medium.thermalConductivity(state));
  assert(lambda > 0, "Invalid thermal conductivity, make sure transport properties are calculated.");
  // Use transport properties to determine dimensionless numbers
  Re = (rho * abs(cVel) * cLen) / eta;
  //assert(Re > 1000, "Invalid Reynolds number, Dittus-Boelter is only for fully turbulent flow.");
  Nu =  a * Re^b * Pr^c;
  U  = Nu * lambda / cLen

;
end DittusBoelter1930;

within Greenhouses.Flows.FluidFlow.HeatTransfer.SinglePhaseCorrelations;
model Gnielinski2010 "Gnielinski pipe equations"
  extends
    Greenhouses.Flows.FluidFlow.HeatTransfer.BaseClasses.PartialSinglePhaseCorrelation;
  extends
    Greenhouses.Flows.FluidFlow.HeatTransfer.BaseClasses.PartialPipeCorrelation;

  import Modelica.Constants.pi;

  // General variables
  parameter Modelica.Units.SI.Length d_i(min=0) = d_h
    "Hydraulic diameter (2*V/A_lateral)";
  parameter Modelica.Units.SI.Length l(min=0) = 0.250 "Pipe or plate length";
  //parameter Modelica.SIunits.Area A_cro(min=0) = Modelica.Constants.pi * d_i^2 / 4 "Cross-sectional area";
  Modelica.Units.SI.ReynoldsNumber Re(min=0);
  Modelica.Units.SI.ReynoldsNumber Re_tur(min=0);
  Modelica.Units.SI.ReynoldsNumber Re_lam(min=0);
  Modelica.Units.SI.PrandtlNumber Pr(min=0);

  // Fluid properties
  Medium.ThermalConductivity lambda;
  Medium.DynamicViscosity eta;
  Medium.SpecificHeatCapacity cp;
  Medium.Density rho;

  // VDI Heat Atlas, 2010, page 694
  Modelica.Units.SI.NusseltNumber Nu_m_T_1(min=0);
  Modelica.Units.SI.NusseltNumber Nu_m_T_2(min=0);
  Modelica.Units.SI.NusseltNumber Nu_m_T_3(min=0);
  Modelica.Units.SI.NusseltNumber Nu_m_T(min=0);

  // VDI Heat Atlas, 2010, page 696, fully developed turbulent flow
  Real gamma;
  Real xtra "Reynolds correction factor";
  Real zeta "Friction factor";
  Real K "Correction term";
  Modelica.Units.SI.NusseltNumber Nu_m(min=0);

  // Other things to define
  Modelica.Units.SI.Length cLen(min=0) "Characteristic length";
  Modelica.Units.SI.Velocity cVel "Characteristic velocity";

  // Output variables
  Modelica.Units.SI.NusseltNumber Nu(min=0);

  // General purpose variables
  Real numerator;
  Real denominator;
  Modelica.Units.SI.VolumeFlowRate V_dot;

equation
  // Get transport properties from Medium model
  eta = Medium.dynamicViscosity(state);
  assert(eta > 0, "Invalid viscosity, make sure transport properties are calculated.");
  lambda = Medium.thermalConductivity(state);
  assert(lambda > 0, "Invalid thermal conductivity, make sure transport properties are calculated.");
  cp = Medium.specificHeatCapacityCp(state);
  assert(cp > 0, "Invalid heat capacity, make sure that your are not in the two-phase region.");
  rho = Medium.density(state);
  // Define some basic variables
  V_dot = m_dot / rho;
  cVel  = V_dot / A_cro "Characteristic velocity";
  cLen  = d_i;
  Pr    = cp * eta / lambda;
  //assert(Pr >= 0.1, "Invalid Prandtl number, the correlation is not valid.");
  //assert(Pr <= 1e3, "Invalid Prandtl number, the correlation is not valid.");
  Re    = (rho * abs(cVel) * cLen) / eta;
  Re_lam = noEvent(min(Re,2300));
  Re_tur = noEvent(max(Re,1e4));

  // VDI Heat Atlas, 2010, page 694, constant wall temperature
  Nu_m_T_1 = 3.66 "Eq. 4";
  Nu_m_T_2 = 1.615 * ( Re_lam * Pr * d_i/l) ^(1/3) "Eq. 5";
  Nu_m_T_3 = (2/(1+22*Pr))^(1/6) * ( Re_lam * Pr * d_i/l) ^(1/2) "Eq. 11";
  Nu_m_T   = (Nu_m_T_1^3 + 0.7^3 + (Nu_m_T_2-0.7)^3 + Nu_m_T_3^3)^(1/3) "Eq. 12";

  // VDI Heat Atlas, 2010, page 696, fully developed turbulent flow
  zeta  = (1.80 * log10(Re_tur)-1.50)^(-2) "Eq. 27";
  xtra  = 0.;
  K     = 1.;
  numerator   = (zeta/8.) * (Re_tur-xtra) * Pr;
  denominator = 1 + 12.7 * sqrt(zeta/8.) *( Pr^(2./3.) - 1.);
  Nu_m        = numerator / denominator *( 1 + (d_i/l)^(2./3.))*K;

  // Instead of the linear transition, we employ a smoother one
  gamma = Greenhouses.Functions.transition_factor(
    start=2300,
    stop=1e4,
    position=Re);
  Nu    = (1-gamma)*Nu_m_T + gamma*Nu_m;
  U     = Nu * lambda / cLen

  ;
end Gnielinski2010;

within Greenhouses.Flows.FluidFlow.HeatTransfer.SinglePhaseCorrelations;
model Martin2010
  "The Martin approach for plate heat exchangers from VDI Heat Atlas"
  extends
    Greenhouses.Flows.FluidFlow.HeatTransfer.BaseClasses.PartialSinglePhaseCorrelation;
  extends
    Greenhouses.Flows.FluidFlow.HeatTransfer.BaseClasses.PartialPlateHeatExchangerCorrelation;

  parameter Modelica.Units.SI.Length s_w(
    min=0,
    displayUnit="mm",
    nominal=0.00075) = 0.00075 "Wall thickness";
  parameter Modelica.Units.SI.ThermalConductivity lambda_w(
    min=0,
    nominal=15) = 15 "Conductivity of the wall";
  parameter Modelica.Units.SI.Length L_p(
    min=0,
    displayUnit="cm",
    nominal=0.20) = 0.2 "Plate length";
  parameter Modelica.Units.SI.ReynoldsNumber Re_turb(
    min=0,
    nominal=2000.0) = 2000.00 "Flow transition Re";
  parameter Modelica.Units.SI.ReynoldsNumber Re_tran(
    min=0,
    nominal=100.0) = 100.00 "Flow transition range";
  parameter Real c_q(min=0,nominal=0.10) = 0.122 "Empirical constant";
  parameter Real   q(min=0,nominal=0.35) = 0.374 "Empirical constant";
  parameter Real B_0(min=0,nominal=64.0) = 64.00 "Shape factor";
  // Parameters from Focke paper
  parameter Real B_1(min=0,nominal=597.) = 597.0
    "Empirical pressure drop factor B_1";
  parameter Real C_1(min=0,nominal=3.85) = 3.850
    "Empirical pressure drop factor C_1";
  parameter Real K_1(min=0,nominal=39.0) = 39.00
    "Empirical pressure drop factor K_1";
  parameter Real   n(min=0,nominal=0.29) = 0.289
    "Empirical pressure drop factor n";
  // Parameters determined by Martin
  parameter Real   a(min=0,nominal=3.80) = 3.800
    "Empirical pressure drop factor a";
  parameter Real   b(min=0,nominal=0.18) = 0.180
    "Empirical pressure drop factor b";
  parameter Real   c(min=0,nominal=0.36) = 0.360
    "Empirical pressure drop factor c";

  Modelica.Units.SI.ReynoldsNumber Re(min=0);
  Modelica.Units.SI.PrandtlNumber Pr(min=0);
  Modelica.Units.SI.NusseltNumber Nu(min=0);
  Real Hg(min=0) "Hagen number";
  Real xi(min=0) "Friction factor";
  Real xi_0(min=0);
  Real xi_0_lam(min=0);
  Real xi_0_tur(min=0) "Friction factor, 0 deg";
  Real xi_1(min=0);
  Real xi_1_lam(min=0);
  Real xi_1_tur(min=0) "Friction factor, 90 deg";
  Real lamTurb(min=0,max=1,nominal=0.5) "Laminar or turbulent flow";
  Modelica.Units.SI.Velocity w "Fluid velocity";
  //Modelica.SIunits.Area A_0(min=0) "Plate projection";
  //Modelica.SIunits.Area A_p(min=0) "Plate surface";

  Medium.Density rho;
  Medium.Temperature T;
  Medium.Temperature T_f_w;
  Medium.Temperature T_f_w_in;
  Medium.DynamicViscosity eta;
  Medium.DynamicViscosity eta_f_w "Viscosity of fluid at wall temperature";
  Medium.ThermalConductivity lambda;
  Medium.ThermodynamicState state_f_w "Thermodynamic state at wall";
  Medium.AbsolutePressure delta_p;
  Modelica.Units.SI.VolumeFlowRate V_dot "Volume flow";
  //Modelica.SIunits.HeatFlowRate Q_dot "Heat flow";
  //Modelica.SIunits.CoefficientOfHeatTransfer alpha;

  Real part1;
  Real part2;

equation
  // Get the required thermophysical properties
  rho = Medium.density(state);
  T   = Medium.temperature(state);
  // Get transport properties from Medium model
  Pr = min(100, Medium.prandtlNumber(state));
  assert(Pr > 0, "Invalid Prandtl number, make sure transport properties are calculated.");
  eta = min(10, Medium.dynamicViscosity(state));
  assert(eta > 0, "Invalid viscosity, make sure transport properties are calculated.");
  lambda = min(10, Medium.thermalConductivity(state));
  assert(lambda > 0, "Invalid thermal conductivity, make sure transport properties are calculated.");
  // Get the required additional thermophysical properties
  T_f_w_in = q_dot / U + T;
  // Disable the correction term
  T_f_w = T; //min(Medium.saturationTemperature(Medium.pressure(filteredState)),T_f_w_in);
  state_f_w = Medium.setState_pTX(Medium.pressure(state),T_f_w);
  eta_f_w = min(10, Medium.dynamicViscosity(state_f_w));
  assert(eta_f_w > 0, "Invalid viscosity at wall, make sure transport properties are calculated.");

  // Implement the basic equations ...
  xi    = 2 * delta_p * d_h / rho / w^2 / L_p "Eq. 1";
  Re    = rho * w * d_h / eta "Eq. 2";
  Nu    = alpha * d_h / lambda "Eq. 3";
  // ... and the more specific ones
  //d_h   = 4 * a_hat / Phi "Eq. 4";
  //X     = 2 * Modelica.Constants.pi*a_hat/Lambda "Eq. 5";
  //Phi   = 1/6 * ( 1 + Modelica.Fluid.Utilities.regRoot(1+X^2) + 4 * Modelica.Fluid.Utilities.regRoot(1+X^2/2)) "Eq. 6";
  // Determine average velocity
  V_dot = m_dot / rho;
  w     = V_dot / A_cro "Eq. 7";
  // Account for the enhancement factor: U > alpha
  //A_0   = B_p * L_p;
  //A_p   = Phi * A_0 "Eq. 8";
  //Q_dot = q_dot * A_0;
  //alpha = Q_dot / A_p / delta_T                "Eq. 9";
  //U     = Phi * alpha "Enhanced HTC";

  // Pressure drop equations for longitudinal flow (0) and 90 deg patterns (1)
  lamTurb = Greenhouses.Functions.transition_factor(
    start=Re_turb - Re_tran,
    stop=Re_turb + Re_tran,
    position=Re);
  xi_0_lam = B_0/Re "Eq. 11";
  xi_0_tur = (1.8 * log10(Re) - 1.5) ^(-2) "Eq. 12";
  xi_0     = (1-lamTurb)*xi_0_lam + lamTurb*xi_0_tur;
  xi_1_lam = B_1 / Re + C_1 "Eq. 14";
  xi_1_tur = K_1 / Re^n "Eq. 15";
  xi_1     = a * ((1-lamTurb)*xi_1_lam + lamTurb*xi_1_tur);
  // Get the overall factor
  part1    = cos(phi)/Modelica.Fluid.Utilities.regRoot( b * tan(phi) + c * sin(phi) + xi_0/cos(phi));
  part2    = (1-cos(phi))/Modelica.Fluid.Utilities.regRoot(xi_1);
  xi       = 1/(part1 + part2)^2 "Eq. 18";

  // Continue with heat transfer equations
  //Hg  = rho * delta_p * d_h^3 / eta^2 / L_p   "Eq. 23";
  Hg  = xi / 2 * Re^2 "Eq. 18 and 23";
  Nu  = c_q * Pr^(1/3) * (eta/eta_f_w)^(1/6) * (2 * Hg * sin(2*phi))^q "Eq. 25"

  ;
end Martin2010;

within Greenhouses.Flows.FluidFlow.HeatTransfer.SinglePhaseCorrelations;
model MuleyManglik1999
  "Heat transfer in plate heat exchangers, Muley and Manglik 1999"
  extends
    Greenhouses.Flows.FluidFlow.HeatTransfer.BaseClasses.PartialSinglePhaseCorrelation;
  extends
    Greenhouses.Flows.FluidFlow.HeatTransfer.BaseClasses.PartialPlateHeatExchangerCorrelation;

  parameter Modelica.Units.SI.ReynoldsNumber Re_lam=400 "Fully laminar";
  parameter Modelica.Units.SI.ReynoldsNumber Re_tur=1000 "Fully turbulent";
  Modelica.Units.SI.ReynoldsNumber Re(min=0);
  Real lamTur(min=-0.1,max=1.1);
  Modelica.Units.SI.PrandtlNumber Pr(min=0);
  Modelica.Units.SI.NusseltNumber Nu(min=0);
  Modelica.Units.SI.NusseltNumber Nu_lam(min=0);
  Modelica.Units.SI.NusseltNumber Nu_tur(min=0);

  Medium.Density rho;
  Medium.Temperature T;
  Medium.Temperature T_f_w;
  Medium.Temperature T_f_w_in;
  Medium.DynamicViscosity eta;
  Medium.DynamicViscosity eta_f_w "Viscosity of fluid at wall temperature";
  Medium.ThermalConductivity lambda;
  Medium.ThermodynamicState state_f_w "Thermodynamic state at wall";
  Modelica.Units.SI.VolumeFlowRate V_dot "Volume flow";
  Modelica.Units.SI.Velocity w "Fluid velocity";

  Real commonTerm;

equation
  // Get the required thermophysical properties
  rho = Medium.density(state);
  T   = Medium.temperature(state);
  // Get transport properties from Medium model
  Pr = min(100, Medium.prandtlNumber(state));
  assert(Pr > 0, "Invalid Prandtl number, make sure transport properties are calculated.");
  eta = min(10, Medium.dynamicViscosity(state));
  assert(eta > 0, "Invalid viscosity, make sure transport properties are calculated.");
  lambda = min(10, Medium.thermalConductivity(state));
  assert(lambda > 0, "Invalid thermal conductivity, make sure transport properties are calculated.");
  // Get the required additional thermophysical properties
  T_f_w_in = q_dot / U + T;
  // Disable the correction term
  T_f_w = T; //min(Medium.saturationTemperature(Medium.pressure(filteredState)),T_f_w_in);
  state_f_w = Medium.setState_pTX(Medium.pressure(state),T_f_w);
  eta_f_w = min(10, Medium.dynamicViscosity(state_f_w));
  assert(eta_f_w > 0, "Invalid viscosity at wall, make sure transport properties are calculated.");

  V_dot = m_dot / rho;
  w  = abs(V_dot) / A_cro;
  // Use transport properties to determine dimensionless numbers
  Re    = rho * w * d_h / eta;
  lamTur = Greenhouses.Functions.transition_factor(
    start=Re_lam,
    stop=Re_tur,
    position=Re);

  Nu = alpha * d_h / lambda;
  Nu = (1-lamTur)*Nu_lam + lamTur*Nu_tur;

  commonTerm = Pr^(1/3) * ( eta/eta_f_w) ^(0.14);
  Nu_tur =(2.668e-1 - 6.967e-3*phi + 7.244e-5*phi^2)*(2.078e+1 - 5.094e+1*Phi +
    4.116e+1*Phi^2 - 1.015e+1*Phi^3)*Re^(0.728 + 0.0543*sin(Modelica.Constants.pi*phi/
    Modelica.Units.Conversions.from_deg(45) + 3.7))*commonTerm;

  Nu_lam =0.44*(phi/Modelica.Units.Conversions.from_deg(30))^(0.38)*Re^(1/2)*commonTerm

  ;
end MuleyManglik1999;

