within Greenhouses.Flows.HeatAndVapourTransfer;
model AirThroughScreen
  "Heat and mass flux exchange and air exchange rate through the screen"
  extends Greenhouses.Interfaces.HeatAndVapour.Element1D;

  /*********************** Parameters ***********************/
  parameter Modelica.Units.SI.Area A "floor surface";
  parameter Modelica.Units.SI.Length W "length of the screen when closed (SC=1)";
  parameter Real K "Screen flow coefficient (check values in Info)";

  /*********************** Varying inputs ***********************/
  Real SC=0 "Screen closure 1:closed, 0:open" ;

  /*********************** Variables ***********************/
  Modelica.Units.SI.CoefficientOfHeatTransfer HEC_ab;
  Modelica.Units.SI.Density rho_air;
  Modelica.Units.SI.Density rho_mean;
  Modelica.Units.SI.Density rho_top;
  Modelica.Units.SI.SpecificHeatCapacity c_p_air=1005;
  Real f_AirTop;
  Real R=8314 "gas constant";
  Modelica.Units.SI.MolarMass M_H=18;
  Real VEC_AirTop(unit="kg/(s.Pa.m2)") "Mass transfer coefficient";
  Real MV_flow2;

equation
  // Air exchange rate
  // rho_air = Modelica.Media.Interfaces.PartialPureSubstance.density_pT(1e5, HeatPort_a.T);
  // rho_top = Modelica.Media.Interfaces.PartialPureSubstance.density_pT(1e5, HeatPort_b.T);
  rho_air = Modelica.Media.Air.ReferenceAir.Air_pT.density_pT(1e5,HeatPort_a.T);
  rho_top = Modelica.Media.Air.ReferenceAir.Air_pT.density_pT(1e5,HeatPort_b.T);
  rho_mean = (rho_air+rho_top)/2;

  f_AirTop = SC*K*max(1e-9,abs(dT))^0.66 + (1-SC)*(max(1e-9,0.5*rho_mean*W*(1-SC)*Modelica.Constants.g_n*max(1e-9,abs(rho_air - rho_top))))^0.5/rho_mean;

  // Heat exchange coefficient and heat exchange
  HEC_ab=rho_air*c_p_air*f_AirTop;
  Q_flow = A*HEC_ab*dT;

  // Mass exchange coefficient VEC and mass exchange MV
  VEC_AirTop = M_H*f_AirTop/R/287;
  MV_flow2 = A*M_H/R*f_AirTop*(MassPort_a.VP/HeatPort_a.T - MassPort_b.VP/HeatPort_b.T);
  MV_flow = A*VEC_AirTop*dP

  ;
end AirThroughScreen;

within Greenhouses.Flows.HeatAndVapourTransfer;
model Convection_Condensation "Upward or downward heat exchange by free convection from an horizontal or inclined surface.
  Mass transfer by condensation from the air (filled port) to the cover/screen (empty port).
  If studying heat exchange of Air-Floor: connect the filled port to the floor and the unfilled port to the air."
  extends Greenhouses.Interfaces.HeatAndVapour.Element1D;

  /*********************** Parameters ***********************/
  parameter Modelica.Units.SI.Angle phi
    "inclination of the surface (0 if horizontal, 25 for typical cover)";
  parameter Modelica.Units.SI.Area A "floor surface";
  parameter Boolean floor=false
    "true if floor, false if cover or thermal screen heat flux";
  //parameter Real X=3 "characteristic dimension of the floor - half diameter of Benard-cell" ;
  parameter Boolean thermalScreen=false
    "presence of a thermal screen in the greenhouse" ;
  parameter Boolean Air_Cov=true
    "True if heat exchange air-cover, False if heat exchange air-screen"                             ;
  parameter Boolean topAir=false "False if MainAir-Cov; True for: TopAir-Cov"
                                                                  ;

  /*********************** Varying inputs ***********************/
  Real SC=0 "Screen closure 1:closed, 0:open" ;

  /*********************** Variables ***********************/
  Modelica.Units.SI.CoefficientOfHeatTransfer HEC_ab;
  Real VEC_ab(unit="kg/(s.Pa.m2)") "Mass transfer coefficient";
  Real s=11
    "Slope of the differentiable switch function for vapour pressure differences";
  Modelica.Units.SI.CoefficientOfHeatTransfer HEC_up_flr;
  Modelica.Units.SI.CoefficientOfHeatTransfer HEC_down_flr;

equation
  //Heat Transfer
  if not floor then
    if thermalScreen then
      if Air_Cov then
        if not topAir then
          //Exchange main air-cover (with screen)
          HEC_ab=(1-SC)*1.7*max(1e-9,abs(dT))^0.33*(cos(phi))^(-0.66)
            "Changed 17/4/18, before it was 0";
        else
          //Exchange top air-cover
          HEC_ab=SC*1.7*max(1e-9,abs(dT))^0.33*(cos(phi))^(-0.66)
            "Changed 17/4/18. SC added";
        end if;
      else
        //Exchange air-screen
        HEC_ab=SC*1.7*max(1e-9,abs(dT))^0.33;
      end if;
    else
      //Exchange main air-cover (no screen)
      HEC_ab = 1.7*max(1e-9,abs(dT))^0.33*(cos(phi))^(-0.66);
    end if;
    HEC_up_flr=0 "dummy";
    HEC_down_flr=0;
  else
    //if HeatPort_a.T>HeatPort_b.T then
    //  HEC_ab = 1.7*max(1e-9,abs(dT))^0.33;
    //else
    //  HEC_ab = 1.3*max(1e-9,abs(dT))^0.25;
    //end if;
    // The conditions here above are smoothed using a differentiable switch function, in order to avoid events during simulation
     HEC_up_flr=1/(1+exp(-s*dT))*1.7*abs(dT)^0.33 "Used for dT>0";
     HEC_down_flr=1/(1+exp(s*dT))*1.3*abs(dT)^0.25 "Used for dT<0";
     HEC_ab = HEC_up_flr+HEC_down_flr;
  end if;

  Q_flow = A*HEC_ab*dT;

  //Mass Transfer
  VEC_ab=max(0,6.4e-9*HEC_ab);
  MV_flow=max(0,A*VEC_ab*dP)
    "The fluxes due to condensation are prohibited from being negative";

//   if dP>0 then
//     VEC_ab = 6.4e-9*HEC_ab;
//     MV_flow = A*VEC_ab*dP;
//   else
//     VEC_ab = 0;
//     MV_flow=0
//       "The fluxes due to condensation are prohibited from being negative";
//   end if

  ;
end Convection_Condensation;

within Greenhouses.Flows.HeatAndVapourTransfer;
model Convection_Evaporation
  "Upward heat exchange by free convection between the thermal screen (filled port) and top air (empty port). Mass transfer by evaporation from upper side of the screen to the air at the top compartment"
  extends Greenhouses.Interfaces.HeatAndVapour.Element1D;

  /*********************** Parameters ***********************/
  parameter Modelica.Units.SI.Area A "floor surface";

  /*********************** Varying inputs ***********************/
  Real SC=0 "Screen closure 1:closed, 0:open" ;
  Modelica.Units.SI.MassFlowRate MV_AirScr=0
    "Mass flow rate from the main air zone to the screen"
    ;

  /*********************** Variables ***********************/
  Modelica.Units.SI.CoefficientOfHeatTransfer HEC_ab;
  Real VEC_ab(unit="kg/(s.Pa.m2)") "Mass transfer coefficient";

equation
  //Heat Transfer: Exchange air-screen
  HEC_ab=SC*1.7*max(1e-9,abs(dT))^0.33;
  Q_flow = A*HEC_ab*dT;

  //Mass Transfer
  VEC_ab = max(0,min(6.4e-9*HEC_ab, MV_AirScr/A/max(1e-9,dP)));
  MV_flow = max(0, A*VEC_ab*dP)
    "The fluxes due to evaporation are prohibited from being negative";
//   if dP>0 then
//     VEC_ab = min(6.4e-9*HEC_ab, MV_AirScr/A/max(1e-9,dP));
//     MV_flow = A*VEC_ab*dP;
//   else
//     VEC_ab = 0;
//     MV_flow=0
//       "The fluxes due to evaporation are prohibited from being negative";
//   end if

  ;
end Convection_Evaporation;

within Greenhouses.Flows.HeatAndVapourTransfer;
model Ventilation
  "Heat and vapour mass flows exchanged from the greenhouse air to the outside air by ventilation"
  extends Greenhouses.Interfaces.HeatAndVapour.Element1D;

  /*********************** Parameters ***********************/
  parameter Modelica.Units.SI.Area A "Greenhouse floor surface";
  parameter Boolean thermalScreen=false
    "presence of a thermal screen in the greenhouse";
  parameter Boolean topAir=false
    "False for: Main air zone; True for: Top air zone" ;
  parameter Boolean forcedVentilation=false
    "presence of a mechanical ventilation system in the greenhouse";
  parameter Modelica.Units.SI.VolumeFlowRate phi_VentForced=0
    "Air flow capacity of the forced ventilation system"
    ;

  /*********************** Varying inputs ***********************/
  Real SC=0 "Screen closure 1:closed, 0:open" ;
  Modelica.Units.SI.Velocity u=0 "Wind speed"
    ;
  Real U_vents(min=0,max=1)=0
    "From 0 to 1, control of the aperture of the roof vents"                             ;
  Real U_VentForced=0 "From 0 to 1, control of the forced ventilation"   ;

  /*********************** Variables ***********************/
  Modelica.Units.SI.CoefficientOfHeatTransfer HEC_ab;
  Modelica.Units.SI.Density rho_air=1.2;
  Modelica.Units.SI.SpecificHeatCapacity c_p_air=1005;
  Real f_vent(unit="m3/(m2.s)")
    "Air exchange rate from the greenhouse air to the outside air function of wind and temperature";
  Real R=8314 "gas constant";
  Modelica.Units.SI.MolarMass M_H=18;
  Real f_vent_total(unit="m3/(m2.s)");
  Real f_ventForced(unit="m3/(m2.s)");

  VentilationRates.NaturalVentilationRate_2 NaturalVentilationRate(
    thermalScreen=thermalScreen,
    u=u,
    dT=dT,
    T_a=HeatPort_a.T,
    T_b=HeatPort_b.T,
    U_roof=U_vents,
    SC=SC) ;
  VentilationRates.ForcedVentilationRate ForcedVentilationRate(
    A=A,
    phi_VentForced=phi_VentForced,
    U_VentForced=U_VentForced)
    ;
equation
  // Natural ventilation rate (including leakage)
  if not topAir then
    f_vent = NaturalVentilationRate.f_vent_air;
  else
    f_vent = NaturalVentilationRate.f_vent_top;
  end if;

  // Forced ventilation rate
  if forcedVentilation then
    if not topAir then
      f_ventForced = ForcedVentilationRate.f_ventForced
        "Forced ventilation is always in the main air zone";
    else
      f_ventForced = 0;
    end if;
  else
    f_ventForced=0;
  end if;

  // Total ventilation
  f_vent_total = f_vent+f_ventForced;

  // Heat transfer
  HEC_ab=rho_air*c_p_air*f_vent_total;
  Q_flow = A*HEC_ab*dT;

  // Moisture transfer
  MV_flow = A*M_H*f_vent_total/R*(MassPort_a.VP/HeatPort_a.T - MassPort_b.VP/HeatPort_b.T)

  ;
end Ventilation;

within Greenhouses.Flows.HeatAndVapourTransfer.VentilationRates;
model ForcedVentilationRate
  "Air exchange rate due to a forced ventilation system"

  /*********************** Parameters ***********************/
  parameter Modelica.Units.SI.Area A "Greenhouse floor surface";
  parameter Modelica.Units.SI.VolumeFlowRate phi_VentForced
    "Air flow capacity of the forced ventilation system";

  /*********************** Varying inputs ***********************/
  Real U_VentForced=0 "Control of the forced ventilation"  ;

  /*********************** Variables ***********************/
  output Real f_ventForced "Air exchange rate at the main air compartment";

equation
  f_ventForced = U_VentForced*phi_VentForced/A

  ;
end ForcedVentilationRate;

within Greenhouses.Flows.HeatAndVapourTransfer.VentilationRates;
model NaturalVentilationRate_1
  "Air exchange rate from the greenhouse air to the outside air function of wind and temperature by De Jong (1990)"

  /*********************** Parameters ***********************/
  parameter Modelica.Units.SI.Angle phi=25/180*Modelica.Constants.pi
    "inclination of the roof (0 if horizontal, 25 for typical cover)";
  parameter Real fr_window=0.078 "number of windows per m2 greenhouse";
  parameter Modelica.Units.SI.Length l "length of the window";
  parameter Modelica.Units.SI.Length h "width of the window";
    parameter Boolean thermalScreen=false
    "presence of a thermal screen in the greenhouse";

  /*********************** Varying inputs ***********************/
  Modelica.Units.SI.Velocity u=0 "Wind speed"
    ;
  Modelica.Units.SI.Angle theta_l=0 "window opening at the leeside side"
    ;
  Modelica.Units.SI.Angle theta_w=0 "window opening at the windward side"
    ;
  Modelica.Units.SI.TemperatureDifference dT=10
    ;

  /*********************** Variables ***********************/
  Real f_vent;
  Real f_vent_wind;
  Real f_vent_temp;
  Real C_f
    "constant of discharge of energy caused by friction in the window opening";
  Real beta "thermal expansion coefficient";
  output Real f_vent_top
    "Air exchange rate at the top air compartment in presence of a thermal screen";
  output Real f_vent_air "Air exchange rate at the main air compartment";

equation
  // Temperature driven ventilation
  C_f = 0.6 "de Jong (1990)";
  beta = 1/283;
  f_vent_temp = C_f*l/3*(abs(Modelica.Constants.g_n*beta*dT))^0.5*(h*(sin(phi)-sin(phi-theta_l)))^1.5 + C_f*l/3*(abs(Modelica.Constants.g_n*beta*dT))^0.5*(h*(sin(phi)-sin(phi-theta_w)))^1.5;

  // Wind driven ventilation
  f_vent_wind = (2.29e-2*(1-exp(-theta_l/21.1)) + 1.2e-3*theta_w*exp(theta_w/211))*l*h*u;

  // Air exchange rate from greenhouse air to outside air
  f_vent = 0.5*fr_window*(f_vent_wind^2 + (f_vent_temp)^2)^0.5
    "Based on De Jong(1990)";

  if thermalScreen then
    f_vent_top=f_vent;
    f_vent_air=0;
  else
    f_vent_top=0;
    f_vent_air=f_vent;
  end if

  ;
end NaturalVentilationRate_1;

within Greenhouses.Flows.HeatAndVapourTransfer.VentilationRates;
model NaturalVentilationRate_2
  "Air exchange rate from the greenhouse air to the outside air function of wind and temperature by Boulard and Baille (1995)"

  /*********************** Parameters ***********************/
  parameter Boolean thermalScreen=false
    "Presence of a thermal screen in the greenhouse";
  parameter Real C_d=0.75
    "Ventilation discharge coefficient, function of greenhouse shape";
  parameter Real C_w=0.09
    "Ventilation global wind pressure coefficient, function of greenhouse shape";
  parameter Real eta_RfFlr=0.1
    "Ratio between the maximum roof vent area and the greenhouse floor area A_roof/A_floor";
  parameter Modelica.Units.SI.Length h_vent=0.68
    "Vertical dimension of a single ventilation opening";
  parameter Real c_leakage=1.5e-4 "Greenhouse leakage coefficient";

  /*********************** Varying inputs ***********************/
  Real SC=0 "Screen closure 1:closed, 0:open" ;
  Real U_roof(min=0,max=1)=0 "Control of the aperture of the roof vents"  ;
  Modelica.Units.SI.Velocity u=0 "Wind speed"
    ;
  Modelica.Units.SI.TemperatureDifference dT=10 "T_a-T_b"
    ;
  Modelica.Units.SI.Temperature T_a=293.15 ;
  Modelica.Units.SI.Temperature T_b=276.15 ;

  /*********************** Variables ***********************/
  Real f_vent(unit="m3/(m2.s)");
  Real f_leakage(unit="m3/(m2.s)") "Air exchange rate due to leakage";
  Modelica.Units.SI.Temperature T_mean;
  output Real f_vent_top(unit="m3/(m2.s)")
    "Air exchange rate at the top air compartment in presence of a thermal screen";
  output Real f_vent_air(unit="m3/(m2.s)") "Air exchange rate at the main air compartment";

equation
  T_mean = (T_a+T_b)/2;
  // Roof ventilation
  f_vent = U_roof*eta_RfFlr*C_d/2*abs(Modelica.Constants.g_n*h_vent/2*abs(dT)/T_mean + C_w*u^2)^0.5;

  // Leakage rate
  f_leakage = max(0.25,u)*c_leakage;

  if thermalScreen then
    f_vent_top=SC*f_vent+0.5*f_leakage "Changed 17/4/18. Added SC";
    f_vent_air=(1-SC)*f_vent+0.5*f_leakage
      "Changed 17/4/18. Added (1-SC)*f_vent";
  else
    f_vent_top=0;
    f_vent_air=f_vent+f_leakage;
  end if

  ;
end NaturalVentilationRate_2;

within Greenhouses.Flows.HeatTransfer;
model AirThroughScreen "Heat exchange and air exchange rate through the screen"
  extends Modelica.Thermal.HeatTransfer.Interfaces.Element1D;

  /*********************** Parameters ***********************/
  parameter Modelica.Units.SI.Area A "floor surface";
  parameter Modelica.Units.SI.Length W "length of the screen when closed (SC=1)";
  parameter Real K "Screen flow coefficient (check values in Info)";

  /*********************** Varying inputs ***********************/
  Real SC=0 "Screen closure 1:closed, 0:open" ;

  /*********************** Variables ***********************/
  Modelica.Units.SI.CoefficientOfHeatTransfer HEC_ab;
  Modelica.Units.SI.Density rho_air;
  Modelica.Units.SI.Density rho_mean;
  Modelica.Units.SI.Density rho_top;
  Modelica.Units.SI.SpecificHeatCapacity c_p_air=1005;
  Real f_AirTop;

equation
  // Air exchange rate
  rho_air = Modelica.Media.Air.ReferenceAir.Air_pT.density_pT(1e5,port_a.T);
  rho_top = Modelica.Media.Air.ReferenceAir.Air_pT.density_pT(1e5,port_b.T);
  rho_mean = (rho_air+rho_top)/2;

  f_AirTop = SC*K*max(1e-9,abs(dT))^0.66 + (1-SC)*(max(1e-9,0.5*rho_mean*W*(1-SC)*Modelica.Constants.g_n*max(1e-9,abs(rho_air - rho_top))))^0.5/rho_mean;

  // Heat exchange coefficient and heat exchange
  HEC_ab=rho_air*c_p_air*f_AirTop;
  Q_flow = A*HEC_ab*dT

  ;
end AirThroughScreen;

within Greenhouses.Flows.HeatTransfer;
model CanopyFreeConvection "Leaves heat exchange by free convection with air"
  extends Modelica.Thermal.HeatTransfer.Interfaces.Element1D;

  /*********************** Parameters ***********************/
  parameter Modelica.Units.SI.Area A "floor surface";
  parameter Modelica.Units.SI.CoefficientOfHeatTransfer U=5
    "Leaves heat transfer coefficient ";

  /*********************** Varying inputs ***********************/
  Real LAI = 1 "Leaf Area Index"
    ;

  /*********************** Variables ***********************/
  Modelica.Units.SI.CoefficientOfHeatTransfer HEC_ab;

equation
  HEC_ab = 2*LAI*U;
  Q_flow = A*HEC_ab*dT

  ;
end CanopyFreeConvection;

within Greenhouses.Flows.HeatTransfer;
model FreeConvection "Upward or downward heat exchange by free convection from an horizontal or inclined 
  surface. If studying heat exchange of Air-Floor: connect the filled port to the floor 
  and the unfilled port to the air."
  extends Modelica.Thermal.HeatTransfer.Interfaces.Element1D;

  /*********************** Parameters ***********************/
  parameter Modelica.Units.SI.Angle phi
    "inclination of the surface (0 if horizontal, 25 for typical cover)";
  parameter Modelica.Units.SI.Area A "floor surface";
  parameter Boolean floor=false
    "true if floor, false if cover or thermal screen heat flux";
  //parameter Real X=3 "characteristic dimension of the floor - half diameter of Benard-cell" ;
  parameter Boolean thermalScreen=false
    "presence of a thermal screen in the greenhouse" ;
  parameter Boolean Air_Cov=true
    "True if heat exchange air-cover, False if heat exchange air-screen"                             ;
  parameter Boolean topAir=false "False if MainAir-Cov; True for: TopAir-Cov"
                                                                  ;

  /*********************** Varying inputs ***********************/
  Real SC=0 "Screen closure 1:closed, 0:open" ;

  /*********************** Variables ***********************/
  Modelica.Units.SI.CoefficientOfHeatTransfer HEC_ab;
  Real s=11
    "Slope of the differentiable switch function for vapour pressure differences";
  Modelica.Units.SI.CoefficientOfHeatTransfer HEC_up_flr;
  Modelica.Units.SI.CoefficientOfHeatTransfer HEC_down_flr;

equation
  if not floor then
    if thermalScreen then
      if Air_Cov then
        if not topAir then
          //Exchange main air-cover (with screen)
          HEC_ab=0;
        else
          //Exchange top air-cover
          HEC_ab=1.7*max(1e-9,abs(dT))^0.33*(cos(phi))^(-0.66);
        end if;
      else
        //Exchange air-screen
        HEC_ab=SC*1.7*max(1e-9,abs(dT))^0.33;
      end if;
    else
      //Exchange main air-cover (no screen)
      HEC_ab = 1.7*max(1e-9,abs(dT))^0.33*(cos(phi))^(-0.66);
    end if;
    HEC_up_flr=0;
    HEC_down_flr=0;
  else
//     if port_a.T>port_b.T then
//       HEC_ab = 1.7*max(1e-9,abs(dT))^0.33;
//     else
//       HEC_ab = 1.3*max(1e-9,abs(dT))^0.25;
//     end if;
// The conditions here above are smoothed using a differentiable switch function, in order to avoid events during simulation
     HEC_up_flr=1/(1+exp(-s*dT))*1.7*abs(dT)^0.33 "Used for dT>0";
     HEC_down_flr=1/(1+exp(s*dT))*1.3*abs(dT)^0.25 "Used for dT<0";
     HEC_ab = HEC_up_flr+HEC_down_flr;
  end if;

  Q_flow = A*HEC_ab*dT

  ;
end FreeConvection;

within Greenhouses.Flows.HeatTransfer;
model FreeVentilation "Heat exchange by ventilation"
  extends Modelica.Thermal.HeatTransfer.Interfaces.Element1D;

  /*********************** Parameters ***********************/
  parameter Modelica.Units.SI.Area A "floor surface";
  parameter Modelica.Units.SI.Angle phi=25/180*Modelica.Constants.pi
    "inclination of the roof (0 if horizontal, 25 for typical cover)";
  parameter Real fr_window=0.078 "number of windows per m2 greenhouse";
  parameter Modelica.Units.SI.Length l "length of the window";
  parameter Modelica.Units.SI.Length h "width of the window";
  parameter Real f_leakage=1.5e-4 "Greenhouse leakage coefficient";
  parameter Boolean thermalScreen=false
    "presence of a thermal screen in the greenhouse";
  parameter Boolean topAir=false
    "False for: Main air zone; True for: Top air zone" ;

  /*********************** Varying inputs ***********************/

  Modelica.Units.SI.Angle theta_l=0 "window opening at the leeside side"
    ;
  Modelica.Units.SI.Angle theta_w=0 "window opening at the windward side"
    ;
  Modelica.Units.SI.Velocity u=0 "Wind speed"
    ;

  /*********************** Variables ***********************/
  Modelica.Units.SI.CoefficientOfHeatTransfer HEC_ab;
  Modelica.Units.SI.Density rho_air=1.2;
  Modelica.Units.SI.SpecificHeatCapacity c_p_air=1005;
  Real f_vent;

  HeatAndVapourTransfer.VentilationRates.NaturalVentilationRate_1
                                                           airExchangeRate(
    phi=phi,
    fr_window=fr_window,
    l=l,
    h=h,
    thermalScreen=thermalScreen,
    u=u,
    theta_l=theta_l,
    theta_w=theta_w,
    dT=dT) ;
equation
  if not topAir then
    f_vent = airExchangeRate.f_vent_air;
  else
    f_vent = airExchangeRate.f_vent_top;
  end if;

  if thermalScreen then
    if topAir then
      HEC_ab=rho_air*c_p_air*(f_vent + max(0.25,u)*f_leakage);
    else
      HEC_ab=0;
    end if;
  else
    HEC_ab=rho_air*c_p_air*(f_vent + max(0.25,u)*f_leakage);
  end if;

  // Heat exchange coefficient and heat exchange
  //HEC_ab=rho_air*c_p_air*(f_vent + u*f_leakage);
  Q_flow = A*HEC_ab*dT

  ;
end FreeVentilation;

within Greenhouses.Flows.HeatTransfer;
model OutsideAirConvection
  "Cover heat exchange by convection with outside air function of wind speed"
  extends Modelica.Thermal.HeatTransfer.Interfaces.Element1D;

  /*********************** Parameters ***********************/
  parameter Modelica.Units.SI.Area A "floor surface";
  parameter Modelica.Units.SI.Angle phi
    "inclination of the surface (0 if horizontal, 25 for typical cover)";

  /*********************** Varying inputs ***********************/
  Modelica.Units.SI.Velocity u=0 "Wind speed"
    ;

  /*********************** Variables ***********************/
  Modelica.Units.SI.CoefficientOfHeatTransfer HEC_ab;
  Real alpha;
  Real s=11
    "Slope of the differentiable switch function for vapour pressure differences";
  Real alpha_a;
  Real alpha_b;
  Real du;

equation
//    if u<4 then
//      alpha = 2.8 + 1.2*u;
//    else
//      alpha = 2.5*u^0.8;
//    end if;

  //The conditions here above are smoothed using a differentiable switch function, in order to avoid events during simulation
  du=4-u;
  alpha_a=1/(1+exp(-s*du))*(2.8 + 1.2*u) "Used for du>0, i.e. u<4";
  alpha_b=1/(1+exp(s*du))*2.5*u^0.8 "Used for du<0, i.e. u>4";
  alpha = alpha_a+alpha_b;

  //alpha=max(2.8,2.5*u^0.8) "Approximation to avoid many events during solution";

  HEC_ab = alpha/cos(phi);
  Q_flow = A*HEC_ab*dT

  ;
end OutsideAirConvection;

within Greenhouses.Flows.HeatTransfer;
model PipeFreeConvection
  "Heating pipe heat exchange by free or hindered convection with air"
  extends Modelica.Thermal.HeatTransfer.Interfaces.Element1D;

  /*********************** Parameters ***********************/
  parameter Modelica.Units.SI.Area A "floor surface";
  parameter Modelica.Units.SI.Length d
    "characteristic dimension of the pipe (pipe diameter)";
  parameter Modelica.Units.SI.Length l "length of heating pipes per m^2 floor surface";
  parameter Boolean freePipe=true
    "true if pipe in free air, false if hindered pipe";

  /*********************** Variables ***********************/
  Modelica.Units.SI.CoefficientOfHeatTransfer HEC_ab;
  Real alpha;

equation
  if abs(dT)>0 then
    if freePipe then
      alpha = 1.28*d^(-0.25)*max(1e-9,abs(dT))^0.25;
    else
      alpha = 1.99*max(1e-9,abs(dT))^0.32;
    end if;
  else
    alpha=0;
  end if;
  HEC_ab = alpha*Modelica.Constants.pi*d*l;
  Q_flow = A*HEC_ab*dT

  ;
end PipeFreeConvection;

within Greenhouses.Flows.HeatTransfer;
model PipeFreeConvection_N
  "Heating pipe heat exchange by free or hindered convection with air"

  /*********************** Parameters ***********************/
  parameter Integer N_p(min=1)=1 "number of pipes in parallel";
  parameter Integer N(min=1)=2 "number of cells for pipe side";
  parameter Modelica.Units.SI.Area A "floor surface";
  parameter Modelica.Units.SI.Length d
    "characteristic dimension of the pipe (pipe diameter)";
  parameter Modelica.Units.SI.Length l "length of heating pipes";
  parameter Boolean freePipe=true
    "true if pipe in free air, false if hindered pipe";

  /*********************** Variables ***********************/
  Modelica.Units.SI.CoefficientOfHeatTransfer HEC_ab[N];
  Real alpha[N];
  Modelica.Units.SI.HeatFlowRate Q_flow;
  Modelica.Units.SI.TemperatureDifference dT[N] "port_a.T - port_b.T";

  Greenhouses.Interfaces.Heat.HeatPorts_a[N] heatPorts_a ;
  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_b
             port_b ;
equation
  for i in 1:N loop
    dT[i] = heatPorts_a[i].T-port_b.T;
    if freePipe then
      alpha[i] = 1.28*d^(-0.25)*max(1e-9,abs(dT[i]))^0.25;
    else
      alpha[i] = 1.99*max(1e-9,abs(dT[i]))^0.32;
    end if;
    HEC_ab[i] = alpha[i]*Modelica.Constants.pi*d*l*N_p/A
      "*A_pipe/A to change units from m-2pipe to m-2floor";
    heatPorts_a[i].Q_flow = A/N*HEC_ab[i]*dT[i];
  end for;

  Q_flow = sum(heatPorts_a.Q_flow);
  port_b.Q_flow = -Q_flow

  ;
end PipeFreeConvection_N;

within Greenhouses.Flows.HeatTransfer;
model Radiation_N "Lumped thermal element for radiation heat transfer"

  /*********************** Parameters ***********************/
  parameter Modelica.Units.SI.Area A "floor surface";
  parameter Real epsilon_a "emissivity coefficient of surface A";
  parameter Real epsilon_b "emissivity coefficient of surface B";
//   parameter Modelica.SIunits.Temperature T_inlet_min=333.15
//     "Pipe Minimum Inlet Temperature";

  /*********************** Varying inputs ***********************/
  Real FFa = 1 "View factor of element A"
    ;
  Real FFb = 1 "View factor of element B"
    ;
  Real FFab1 = 0 "View factor of intermediate element between A and B"
    ;
  Real FFab2 = 0 "View factor of intermediate element between A and B"
    ;
  Real FFab3 = 0 "View factor of intermediate element between A and B"
    ;
  Real FFab4 = 0 "View factor of intermediate element between A and B"
    ;

  Real dT4[N];
  Modelica.Units.SI.HeatFlowRate Q_flow;
  Real REC_ab(unit="W/(m2.K4)");

  // Discretization
  parameter Integer N(min=1)=2 "Number of discrete flow volumes";

  Greenhouses.Interfaces.Heat.HeatPorts_a[N] heatPorts_a ;
  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_b
             port_b ;
equation
  for i in 1:N loop
    dT4[i]=heatPorts_a[i].T^4 - port_b.T^4;
  end for;

  REC_ab = epsilon_a*epsilon_b*FFa*FFb*(1-FFab1)*(1-FFab2)*(1-FFab3)*(1-FFab4)*Modelica.Constants.sigma;
  heatPorts_a.Q_flow = A/N*REC_ab*dT4;

  Q_flow = sum(heatPorts_a.Q_flow);

  port_b.Q_flow = -Q_flow
  ;
end Radiation_N;

