within Greenhouses.Flows.VapourMassTransfer;
model MV_AirThroughScreen
  "Vapour mass flow exchanged from the greenhouse main air zone (below the thermal screen) to the top air zone (above the screen)"
  extends Greenhouses.Interfaces.Vapour.Element1D;

  /*********************** Parameters ***********************/
  parameter Modelica.Units.SI.Area A "floor surface";
  parameter Boolean input_f_AirTop=true
    "True if input the exchange rate, False to compute it in this model";
  parameter Real f_AirTop=0
    "Air exchange rate computed in model AirThroughScreen"                       ;
  parameter Modelica.Units.SI.Length W "length of the screen when closed (SC=1)"
    ;
  parameter Real K "Screen flow coefficient (check values in Info)" ;

  /*********************** Varying inputs ***********************/
  Real SC=0 "Screen closure 1:closed, 0:open" ;
  Modelica.Units.SI.Temperature T_a=300 "Temperature at port a (filled square)"
    ;
  Modelica.Units.SI.Temperature T_b=300 "Temperature at port b (empty square)"
    ;

  /*********************** Variables ***********************/
  Real f_AirTopp;
  Modelica.Units.SI.Density rho_air;
  Modelica.Units.SI.Density rho_mean;
  Modelica.Units.SI.Density rho_top;
  Modelica.Units.SI.SpecificHeatCapacity c_p_air=1005;
  Real R=8314 "gas constant";
  Modelica.Units.SI.MolarMass M_H=18;
  Modelica.Units.SI.TemperatureDifference dT;
  Real VEC_AirTop(unit="kg/(s.Pa.m2)") "Mass transfer coefficient";

equation
  // Air exchange rate
  if input_f_AirTop then
    f_AirTopp = f_AirTop;
    rho_air=999 "dumb";
    rho_top=999;
    rho_mean=999;
    dT=999;
  else
    rho_air = Modelica.Media.Air.ReferenceAir.Air_pT.density_pT(1e5,T_a);
    rho_top = Modelica.Media.Air.ReferenceAir.Air_pT.density_pT(1e5,T_b);
    rho_mean = (rho_air+rho_top)/2;
    dT=T_a-T_b;
    f_AirTopp = SC*K*abs(dT)^0.66 + (1-SC)/rho_mean*(0.5*rho_mean*W*(1-SC)*Modelica.Constants.g_n*abs(rho_air - rho_top))^0.5;
  end if;

  // Mass exchange coefficient VEC and mass exchange MV
  VEC_AirTop = M_H*f_AirTopp/R/287;
  MV_flow = A*VEC_AirTop*dP

  ;
end MV_AirThroughScreen;

within Greenhouses.Flows.VapourMassTransfer;
model MV_CanopyTranspiration
  "Vapour mass flow released by the canopy due to transpiration processes. The model must be connected like the following: canopy (filled port) - air (unfilled port)"
  extends Greenhouses.Interfaces.Vapour.Element1D;

  /*********************** Parameters ***********************/
  parameter Modelica.Units.SI.Area A "floor surface";
//   parameter Boolean rb_constant=true
//     "if true, constant boundary layer resistance of the canopy for vapour transport, else, computed with d and u";
//  parameter Modelica.SIunits.Length d=0.5 "characteristic length of the leaf" ;

  /*********************** Varying inputs ***********************/
  Real CO2_ppm(unit="umol/mol")=350 "CO2 concentration in ppm of internal air"  ;
  Real LAI = 1 "Leaf Area Index"
    ;
//  Modelica.SIunits.Velocity u = 0.04 "Local air velocity"   ;
//  Modelica.SIunits.HeatFlux I_g = 300 "outside global solar radiation"  ;
  Modelica.Units.SI.HeatFlux R_can=100 "Global irradiation above the canopy"
    ;

  Modelica.Units.SI.Temperature T_can=300 "Temperature of the canopy (port a)"
    ;
//  Modelica.SIunits.Temperature T_air=300
//    "Temperature of the inside air (port b)"
//    ;

  /*********************** Variables ***********************/
  Real E_kgsm2(unit="kg/(s.m2)") "Canopy transpiration";
  Real E_Wm2(unit="W/m2") "Canopy transpiration";
  Modelica.Units.SI.PressureCoefficient gamma=65.8 "psychometric constant";
  Real r_s(unit="s/m") "stomatal resistance of the leaves";
  Real r_bV(unit="s/m") "boundary layer resistance to heat mass of the leaves";
//  Real r_bH(unit="s/m") "boundary layer resistance to heat transfer of the leaves";
  Modelica.Units.SI.Density rho=1.23 "of the air";
  Modelica.Units.SI.SpecificHeatCapacity C_p=1005 "of the air";

  Real Le=0.89 "Lewis number for vapour";
  Real r_min(unit="s/m") "minimum possible canopy resistance";
  Real r_I "short-wave radiation resistance";
  Real r_T "temperature resistance";
  Real r_CO2 "CO2 resistance";
  Real r_VP "vapour pressure deficit resistance";
  Modelica.Units.SI.Pressure VP_can "vapour pressure of the canopy";
  Modelica.Units.SI.Pressure VP_air "vapour pressure of interior air";
  Real C_1(unit="W/m2");
  Real C_2(unit="W/m2");
  Real C_3(unit="1/K2");
  Real C_4;
  Real C_5(unit="1/Pa2");
  Modelica.Units.SI.Temperature T_m
    "temperature at which the resistance on the leave is minimal";
  Real VEC_canAir(unit="kg/(s.Pa.m2)") "Mass transfer coefficient";
  Real S_rs;
  Modelica.Units.SI.SpecificEnergy DELTAH=2.45e6 "latent heat of water vaporization";

  Real r_s2(unit="s/m");

equation
  VP_can = port_a.VP;
  VP_air = port_b.VP;

  // Boundary layer resistance to heat mass (determined by micro-climatic conditions)
//   // r_bV computed from the resistance to heat transport r_bH
//   r_bV = Le^(2/3)*r_bH;
//   r_bH = 1174*d^0.5 / (d*abs(T_can - T_air) + max(1e-9,207*u^2))^0.25;

  // Since no wind speed in the greenhouse is measured, a constant value is used
  r_bV = 275;

  // Stomatal resistance (actively regulated by the canopy)
//  r_T = 1 + C_3*(T_can - T_m)^2;
//   r_CO2 = min(1.5,1 + C_4*(CO2_ppm - 200)^2);
//   r_VP = min(3.8,1 + C_5*(VP_can - VP_air)^2);
//   if I_g==0 then
//     //Nighttime
//     r_min = 658.5;
//     C_1 = 0;
//     C_2 = -999 "avoid division by 0";
//     C_3 = 0.5e-2;
//     T_m = 273.15+33.6;
//     C_4 = 1.1e-11;
//     C_5 = 5.2e-6;
//     r_I = -999;
//     r_s = r_min * r_T * r_CO2 * r_VP "Stanghellini (1987)";
//   else
//     //Daytime
//     r_min = 82;
//     C_1 = 4.3;
//     C_2 = 0.54;
//     C_3 = 2.3e-2;
//     T_m = 273.15+24.5;
//     C_4 = 6.1e-7;
//     C_5 = 4.3e-6;
//     r_I = (P_can/(2*LAI) + C_1) / (P_can/(2*LAI) + C_2)
//       "P_can/LAI is the radiation flux per m2 of leaf";
//     r_s = r_min * r_I * r_T * r_CO2 * r_VP "Stanghellini (1987)";
//   end if;

  // Simplification
  r_s2 = r_min * r_I * r_CO2 * r_VP "Stanghellini (1987) eq 3.51";
  r_min = 82;
  r_I = (R_can/(2*LAI) + C_1) / (R_can/(2*LAI) + C_2)
    "R_can/(2*LAI) is the mean irradiation per unit leaf area";
  r_CO2 = min(1.5,1 + C_4*(CO2_ppm - 200)^2);
  r_VP = min(3.8,1 + C_5*(VP_can - VP_air)^2);

  r_T = 1+C_3*(T_can-T_m)^2;
  C_3 = 0.5e-2*(1-S_rs) + 2.3e-2*S_rs;
  T_m = (33.6+273.15)*(1-S_rs) + (24.5+273.15)*S_rs;
  r_s = r_min * r_I * r_CO2 * r_VP * r_T;

  C_1 = 4.3;
  C_2 = 0.54;
  S_rs = 1/(1+exp(-(R_can-5)))
    "Value of the differentiable switch to make the condition above a differentiable equation. 0: nightttime, 1: daytime";
  C_4 = 1.1e-11*(1-S_rs) + 6.1e-7*S_rs;
  C_5 = 5.2e-6*(1-S_rs) + 4.3e-6*S_rs;

  // Canopy transpiration
  VEC_canAir = 2*rho*C_p*LAI / (DELTAH*gamma*(r_bV + r_s));

  MV_flow = A*VEC_canAir*(VP_can - VP_air);

  E_kgsm2 = MV_flow/A;
  E_Wm2 = E_kgsm2*DELTAH

  ;
end MV_CanopyTranspiration;

within Greenhouses.Flows.VapourMassTransfer;
model MV_cnv_condensation
  "Vapour mass transfer (and possible condensation) caused by convection at a surface. The model must be connected as following: air (filled port) - surface (empty port)"
  extends Greenhouses.Interfaces.Vapour.Element1D;

  /*********************** Parameters ***********************/
  parameter Modelica.Units.SI.Area A "floor surface";

  /*********************** Varying inputs ***********************/
  Modelica.Units.SI.CoefficientOfHeatTransfer HEC_ab=0
    "Heat transfer coefficient between nodes a and b, provided by the adecuate model in HeatTransfer folder"
    ;
  /*********************** Variables ***********************/
  Real VEC_ab(unit="kg/(s.Pa.m2)") "Mass transfer coefficient";

equation
  if dP>0 then
    VEC_ab = 6.4e-9*HEC_ab;
    MV_flow = A*VEC_ab*dP;
  else
    VEC_ab = 0;
    MV_flow=0
      "The fluxes due to condensation are prohibited from being negative";
  end if

  ;
end MV_cnv_condensation;

within Greenhouses.Flows.VapourMassTransfer;
model MV_cnv_evaporation
  "Vapour mass transfer (and possible evaporation) caused by convection at a surface. The model must be connected as following: surface (filled port) - air (empty port)"
  extends Greenhouses.Interfaces.Vapour.Element1D;

  /*********************** Parameters ***********************/
  parameter Modelica.Units.SI.Area A "floor surface";

  /*********************** Varying inputs ***********************/
  Modelica.Units.SI.CoefficientOfHeatTransfer HEC_ab=0
    "Heat transfer coefficient between nodes a and b, provided by the adecuate model in HeatTransfer folder"
    ;
  Real VEC_AirScr(unit="kg/(s.Pa.m2)")=0
    "Mass transfer coefficient at the lower part of the screen in contact with the main air zone"       ;
  Modelica.Units.SI.Pressure VP_air=1e5 "Vapour pressure at the main air zone";

  /*********************** Variables ***********************/
  Real VEC_ab(unit="kg/(s.Pa.m2)") "Mass transfer coefficient";

equation
  // Port a: screen; Port b: air in top compartment
  // dP => VP_scr - VP_topAir

  if dP>0 then
    VEC_ab = min(6.4e-9*HEC_ab, VEC_AirScr*(VP_air-port_a.VP)/dP);
    MV_flow = A*VEC_ab*dP;
  else
    VEC_ab = 0;
    MV_flow=0
      "The fluxes due to evaporation are prohibited from being negative";
  end if

  ;
end MV_cnv_evaporation;

within Greenhouses.Flows.VapourMassTransfer;
model MV_ventilation
  "Vapour mass flow exchanged from the greenhouse air to the outside air by ventilation"
  extends Greenhouses.Interfaces.Vapour.Element1D;

  /*********************** Parameters ***********************/
  parameter Modelica.Units.SI.Area A "floor surface";
  parameter Modelica.Units.SI.Angle phi=25/180*Modelica.Constants.pi
    "inclination of the roof (0 if horizontal, 25 for typical cover)";
  parameter Real fr_window=0.078 "number of windows per m2 greenhouse";
  parameter Modelica.Units.SI.Length l "length of the window";
  parameter Modelica.Units.SI.Length h "width of the window";
  parameter Boolean thermalScreen=false
    "presence of a thermal screen in the greenhouse";
  parameter Boolean topAir=false
    "False for: Main air zone; True for: Top air zone" ;

  /*********************** Varying inputs ***********************/

  Modelica.Units.SI.Angle theta_l=0 "window opening at the leeside side"
    ;
  Modelica.Units.SI.Angle theta_w=0 "window opening at the windward side"
    ;
  Modelica.Units.SI.Temperature T_a=300 "Temperature at port a (filled square)"
    ;
  Modelica.Units.SI.Temperature T_b=300 "Temperature at port b (empty square)"
    ;
  Modelica.Units.SI.Velocity u=0 "Wind speed"
    ;

  /*********************** Variables ***********************/
  Real f_vent;
  Real R=8314 "gas constant";
  Modelica.Units.SI.MolarMass M_H=18 "kg/kmol";

  HeatAndVapourTransfer.VentilationRates.NaturalVentilationRate_1
    airExchangeRate(
    phi=phi,
    fr_window=fr_window,
    l=l,
    h=h,
    thermalScreen=thermalScreen,
    u=u,
    theta_l=theta_l,
    theta_w=theta_w,
    dT=T_a - T_b)
    ;
equation
  // Mass exchange coefficient and mass exchange
  if not topAir then
    f_vent = airExchangeRate.f_vent_air;
    MV_flow = A*M_H*f_vent/R*(port_a.VP/T_a - port_b.VP/T_b);
  else
    f_vent = airExchangeRate.f_vent_top;
    MV_flow = A*M_H*f_vent/R/283*dP;
  end if

  ;
end MV_ventilation;

within Greenhouses.Functions;
function DerivativeSaturatedVapourPressure
  "Slope of the tangent at the saturated vapour pressure at any temperature"

  input Real TSat(unit="degC",displayUnit="degC",
                                          nominal=20) "Saturation temperature";
  output Modelica.Units.SI.PressureCoefficient dpSat_dT(displayUnit="Pa/K", nominal=
        1000) "Slope of saturation pressure";

algorithm
  dpSat_dT := 47.82*exp(0.0545*TSat);

end DerivativeSaturatedVapourPressure;

within Greenhouses.Functions;
function MultiLayer_TauRho
  "Transmission and reflection coefficient of a double layer"
  input Real tau_1;
  input Real tau_2;
  input Real rho_1;
  input Real rho_2;
  output Real tau_12;
  output Real rho_12;

algorithm
  tau_12:= tau_1*tau_2/(1-rho_1*rho_2);
  rho_12:= rho_1 + tau_1^2*rho_2/(1-rho_1*rho_2);

end MultiLayer_TauRho;

within Greenhouses.Functions;
function SaturatedVapourPressure "Saturated vapour pressure at any temperature"

  input Real TSat(unit="degC",displayUnit="degC",
                                          nominal=20) "Saturation temperature";
  output Modelica.Units.SI.Pressure pSat(displayUnit="Pa", nominal=1e5)
    "Saturation pressure";

algorithm
  pSat := -274.36 + 877.52*exp(0.0545*TSat);

end SaturatedVapourPressure;

within Greenhouses.Functions;
function transition_factor
  "Get weighting factor for smooth transition (from 0 to 1)"
  extends Modelica.Icons.Function;
  import Modelica.Constants.pi;
  import Modelica.Constants.e;

  input Real start =    0.25 "start of transition interval";
  input Real stop =     0.75 "end of transition interval";
  input Real position = 0.0 "current position";
  input Integer order = 2 "Smooth up to which derivative?";

  output Real tFactor "weighting factor";

protected
  Real[4] a_map = {-1/2, -2/pi, -3/4, -8/pi} "First parameters";
  Real[4] b_map = {1/2,   1/2,   1/2,  1/2} "Second parameters";

  // Rename variables to match with Richter2008, p.68ff
  Real phi "current phase";
  Real a "multiplier";
  Real b "addition";
  Real x_t "Start of transition";
  Real x "Current position";
  Real DELTAx "Length of transition";

  // Parameters for generalised logistic function
  Real A = 0 "Lower asymptote";
  Real K = 1 "Upper asymptote";
  Real B = 8 "Growth rate";
  Real nu= 1 "Symmetry changes";
  Real Q = nu "Zero correction";
  Real M = nu "Maximum growth for Q = nu";
  Real X = 0;
  Real END =     0;
  Real START =   0;
  Real factor =  0;

algorithm
  assert(order>=0, "This function only supports positive values for the order of smooth derivatives.");
  assert(start<stop, "There is only support for positive differences, please provide start < stop.");

  // 0th to 2nd order
  a      := a_map[order+1];
  b      := b_map[order+1];
  x      := position;
  DELTAx := stop - start;
  x_t    := start + 0.5*DELTAx;
  phi    := (x - x_t) / DELTAx * pi;

  // higher order
  // We need to do some arbitrary scaling:
  END   :=  4.0;
  START := -2.0;
  factor := (END-START) / (stop-start);
  X := START + (position - start) * factor;

  tFactor := 1-smooth(5,noEvent(
  if position < start then
    1
  elseif position > stop then
    0
  else
    if (order == 0) then
      a                      * sin(phi)                                         + b
    elseif (order == 1) then
      a * ( 1/2 * cos(phi)   * sin(phi) + 1/2*phi)                              + b
    elseif (order == 2) then
      a * ( 1/3 * cos(phi)^2 * sin(phi) + 2/3 * sin(phi))                       + b
    else
      1 - (A + ( K-A)  / ( 1 + Q * e^(-B*(X - M)))^(1/nu))));
//     elseif (order == 3) then
//       a * ( 1/4 * cos(phi)^3 * sin(phi) + 3/8 * cos(phi) * sin(phi) + 3/8*phi)  + b

  ;
end transition_factor;

within Greenhouses.Functions;
function transition_factor_alt
  "An alternative definition of the transition range"
  extends Greenhouses.Functions.transition_factor(start=switch - 0.5*trans,
      stop=switch + 0.5*trans);
  input Real switch = 0.5 "centre of transition interval";
  input Real trans = 0.05*switch "transition duration";

end transition_factor_alt;

within Greenhouses.Functions;
function WaterVapourPressure
  "Water vapour pressure of a gas computed by the relative humidity and the saturation water vapour pressure at the gas temperature"
  input Real TSat(unit="degC",displayUnit="degC",
                                          nominal=20) "Saturation temperature";
  input Real RH(nominal=70) "(0...100) %, Relative humidity";
  output Modelica.Units.SI.Pressure VP "Water vapour pressure";

algorithm
  VP := RH/100*Greenhouses.Functions.SaturatedVapourPressure(TSat);

end WaterVapourPressure;

