  extends Modelica.Electrical.Analog.Interfaces.TwoPin;
  parameter Real R(start=1) "Resistance";
  parameter Real L(start=1) "Inductance";
  Modelica.Units.SI.Current i(start=0) = p.i "Current";
  Modelica.Electrical.Analog.Basic.Resistor resistor(final R=R) ;
  Modelica.Electrical.Analog.Basic.Inductor inductor(final L=L) ;
equation
  connect(p, resistor.p) ;
  connect(resistor.n, inductor.p) ;
  connect(inductor.n, n) 
  ;
end RLSeries;

