within HanserModelica.InductionMachines;
model IMC_Characteristics "Characteristic curves of Induction machine with squirrel cage"
  extends Modelica.Icons.Example;
  import Modelica.Constants.pi;
  parameter Integer m=3 "Number of phases";
  parameter Modelica.Units.SI.Voltage VsNominal=100
    "Nominal stator RMS voltage per phase";
  parameter Modelica.Units.SI.Current IsNominal=100
    "Nominal stator RMS voltage per phase";
  parameter Modelica.Units.SI.Frequency fsNominal=imcData.fsNominal
    "Nominal frequency";
  parameter Modelica.Units.SI.AngularVelocity w_Load(displayUnit="rev/min") =
    1440.45*2*Modelica.Constants.pi/60 "Nominal load speed";
  parameter Integer p=imcData.p "Number of pole pairs";
  Real speedPerUnit = p*imc.wMechanical/(2*pi*fsNominal) "Per unit speed";
  Real slip = 1-speedPerUnit "Slip";
  output Modelica.Units.SI.Current I=currentRMSSensor.I " RMS current";
  Modelica.Electrical.QuasiStatic.Polyphase.Sources.VoltageSource voltageSource(
    m=m,
    f=fsNominal,
    V=fill(VsNominal, m),
    phi=-Modelica.Electrical.Polyphase.Functions.symmetricOrientation(m))
    ;
  Modelica.Electrical.QuasiStatic.Polyphase.Basic.Star star(m=m) ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Basic.Ground ground ;
  Modelica.Electrical.QuasiStatic.Polyphase.Sensors.PowerSensor powerSensor(m=m)
    ;
  Modelica.Electrical.QuasiStatic.Polyphase.Sensors.CurrentQuasiRMSSensor
    currentRMSSensor(m=m)
    ;
  Modelica.Magnetic.QuasiStatic.FundamentalWave.BasicMachines.InductionMachines.IM_SquirrelCage imc(
    Js=imcData.Js,
    p=imcData.p,
    fsNominal=imcData.fsNominal,
    TsRef=imcData.TsRef,
    alpha20s(displayUnit="1/K") = imcData.alpha20s,
    frictionParameters=imcData.frictionParameters,
    gammar(fixed=true, start=-pi/2),
    statorCoreParameters=imcData.statorCoreParameters,
    strayLoadParameters=imcData.strayLoadParameters,
    alpha20r(displayUnit="1/K") = imcData.alpha20r,
    Rs=imcData.Rs*m/3,
    Lssigma=imcData.Lssigma*m/3,
    Lm=imcData.Lm*m/3,
    Lrsigma=imcData.Lrsigma*m/3,
    Rr=imcData.Rr*m/3,
    TrRef=imcData.TrRef,
    m=m,
    Jr=0*imcData.Jr,
    TsOperational=imcData.TsRef,
    effectiveStatorTurns=imcData.effectiveStatorTurns,
    TrOperational=imcData.TrRef) ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Basic.Ground groundMachine
    ;
  Modelica.Electrical.QuasiStatic.Polyphase.Basic.Star starMachine(m=
        Modelica.Electrical.Polyphase.Functions.numberOfSymmetricBaseSystems(m))
    ;
  Modelica.Magnetic.QuasiStatic.FundamentalWave.Utilities.MultiTerminalBox terminalBox(m=m, terminalConnection="Y") ;
  Modelica.Mechanics.Rotational.Sources.Speed speed(exact=true) ;
  Modelica.Blocks.Sources.Ramp ramp(
    height=3*2*pi*fsNominal/p,
    duration=1,
    offset=-2*pi*fsNominal/p) ;
  parameter ParameterRecords.IMC imcData "Induction machine parameters" ;
equation
  connect(ground.pin, star.pin_n)
    ;
  connect(star.plug_p, voltageSource.plug_n) ;
  connect(powerSensor.currentN, currentRMSSensor.plug_p) ;
  connect(powerSensor.voltageP, powerSensor.currentP) ;
  connect(powerSensor.voltageN, star.plug_p) ;
  connect(terminalBox.plug_sn, imc.plug_sn) ;
  connect(terminalBox.plug_sp, imc.plug_sp) ;
  connect(starMachine.plug_p, terminalBox.starpoint) ;
  connect(currentRMSSensor.plug_n, terminalBox.plugSupply) ;
  connect(starMachine.pin_n, groundMachine.pin) ;
  connect(imc.flange, speed.flange) ;
  connect(ramp.y, speed.w_ref) ;
  connect(voltageSource.plug_p, powerSensor.currentP) 
  ;
end IMC_Characteristics;

within HanserModelica.InductionMachines;
model IMC_Inverter1 "Induction machine with squirrel cage and inverter"
  extends Modelica.Icons.Example;
  import Modelica.Constants.pi;
  parameter Integer m=3 "Number of phases";
  parameter Modelica.Units.SI.Voltage VsNominal=100
    "Nominal RMS voltage per phase";
  parameter Modelica.Units.SI.Current IsNominal=100
    "Nominal RMS current per phase";
  parameter Modelica.Units.SI.Frequency fsNominal=imcData.fsNominal
    "Nominal frequency";
  parameter Modelica.Units.SI.Frequency f=fsNominal
    "Maximum operational frequency";
  Modelica.Units.SI.Frequency fActual=ramp.y "Actual frequency";
  parameter Modelica.Units.SI.Time tRamp=1 "Frequency ramp";
  parameter Modelica.Units.SI.Torque TLoad=161.4 "Nominal load torque";
  parameter Modelica.Units.SI.Time tStep=1.5 "Time of load torque step";
  parameter Modelica.Units.SI.Inertia JLoad=0.29 "Load's moment of inertia";
  output Modelica.Units.SI.Current I=currentRMSSensor.I "Transient RMS current";
  Modelica.Magnetic.FundamentalWave.BasicMachines.InductionMachines.IM_SquirrelCage
    imc(
    p=imcData.p,
    fsNominal=imcData.fsNominal,
    TsRef=imcData.TsRef,
    alpha20s(displayUnit="1/K") = imcData.alpha20s,
    Jr=imcData.Jr,
    Js=imcData.Js,
    frictionParameters=imcData.frictionParameters,
    phiMechanical(fixed=true),
    wMechanical(fixed=true),
    statorCoreParameters=imcData.statorCoreParameters,
    strayLoadParameters=imcData.strayLoadParameters,
    TrRef=imcData.TrRef,
    m=m,
    Rs=imcData.Rs*m/3,
    Lssigma=imcData.Lssigma*m/3,
    Lszero=imcData.Lszero*m/3,
    Lm=imcData.Lm*m/3,
    Lrsigma=imcData.Lrsigma*m/3,
    Rr=imcData.Rr*m/3,
    TsOperational=imcData.TsRef,
    effectiveStatorTurns=imcData.effectiveStatorTurns,
    alpha20r=imcData.alpha20r,
    TrOperational=imcData.TrRef)
    ;
  Modelica.Blocks.Sources.Ramp ramp(duration=tRamp, height=f) ;
  Modelica.Electrical.Machines.Utilities.VfController vfController(
    final m=m,
    BasePhase=+Modelica.Constants.pi/2,
    fNominal=fsNominal,
    VNominal=VsNominal)                 ;
  Modelica.Electrical.Polyphase.Sources.SignalVoltage signalVoltage(final m=m)
    ;
  Modelica.Electrical.Polyphase.Basic.Star star(final m=m)
    ;
  Modelica.Electrical.Analog.Basic.Ground ground ;
  Modelica.Mechanics.Rotational.Components.Inertia loadInertia(J=JLoad)
    ;
  Modelica.Mechanics.Rotational.Sources.TorqueStep loadTorqueStep(
    startTime=tStep,
    stepTorque=-TLoad,
    useSupport=false,
    offsetTorque=0) ;
  Modelica.Electrical.Machines.Utilities.MultiTerminalBox terminalBox(terminalConnection="Y", m=m) ;
  Modelica.Electrical.Polyphase.Sensors.CurrentQuasiRMSSensor currentRMSSensor(
      final m=m) ;
  Modelica.Electrical.Polyphase.Basic.Star starMachine(final m=
        Modelica.Electrical.Polyphase.Functions.numberOfSymmetricBaseSystems(m))
    ;
  Modelica.Electrical.Analog.Basic.Ground groundMachine ;
  Modelica.Electrical.Polyphase.Sensors.VoltageQuasiRMSSensor voltageRMSSensor(
      final m=m) ;
  parameter ParameterRecords.IMC imcData "Induction machine parameters" ;
initial equation
  sum(imc.is) = 0;
  imc.is[1:2] = zeros(2);
  imc.ir[1:m - 1] = zeros(m - 1);

equation
  connect(loadTorqueStep.flange, loadInertia.flange_b)
    ;
  connect(terminalBox.plug_sn, imc.plug_sn) ;
  connect(terminalBox.plug_sp, imc.plug_sp) ;
  connect(imc.flange, loadInertia.flange_a) ;
  connect(currentRMSSensor.plug_n, terminalBox.plugSupply) ;
  connect(ground.p, star.pin_n) ;
  connect(ramp.y, vfController.u) ;
  connect(vfController.y, signalVoltage.v) ;
  connect(starMachine.plug_p, terminalBox.starpoint) ;
  connect(groundMachine.p,starMachine. pin_n) ;
  connect(star.plug_p, signalVoltage.plug_n) ;
  connect(signalVoltage.plug_p, currentRMSSensor.plug_p) ;
  connect(voltageRMSSensor.plug_n, terminalBox.plug_sn) ;
  connect(terminalBox.plug_sp,voltageRMSSensor. plug_p) 
  ;
end IMC_Inverter1;

