within HanserModelica.InductionMachines;
model IMC_Steinmetz "Induction machine with squirrel cage and Steinmetz-connection"
  extends Modelica.Icons.Example;
  constant Integer m=3 "Number of phases";
  parameter Modelica.Units.SI.Voltage VsNominal=100
    "Nominal RMS voltage per phase";
  parameter Modelica.Units.SI.Current IsNominal=100
    "Nominal RMS current per phase";
  parameter Modelica.Units.SI.Frequency fsNominal=imcData.fsNominal
    "Nominal frequency";
  parameter Modelica.Units.SI.Time tStart1=0.1 "Start time";
  parameter Modelica.Units.SI.Capacitance Cr=0.0035 "Motor's running capacitor";
  parameter Modelica.Units.SI.Capacitance Cs=5*Cr
    "Motor's (additional) starting capacitor";
  parameter Modelica.Units.SI.AngularVelocity wSwitch(displayUnit="rev/min") =
    1350*2*Modelica.Constants.pi/60
    "Speed for switching off the starting capacitor";
  parameter Modelica.Units.SI.Torque tauLoad=2/3*161.4 "Nominal load torque";
  parameter Modelica.Units.SI.AngularVelocity wLoad(displayUnit="rev/min") =
    1462.5*2*Modelica.Constants.pi/60 "Nominal load speed";
  parameter Modelica.Units.SI.Inertia JLoad=0.29 "Load's moment of inertia";
  Modelica.Magnetic.FundamentalWave.BasicMachines.InductionMachines.IM_SquirrelCage
    imc(
    p=imcData.p,
    fsNominal=imcData.fsNominal,
    TsRef=imcData.TsRef,
    alpha20s(displayUnit="1/K") = imcData.alpha20s,
    Jr=imcData.Jr,
    Js=imcData.Js,
    frictionParameters=imcData.frictionParameters,
    phiMechanical(fixed=true),
    wMechanical(fixed=true),
    statorCoreParameters=imcData.statorCoreParameters,
    strayLoadParameters=imcData.strayLoadParameters,
    TrRef=imcData.TrRef,
    Rs=imcData.Rs*m/3,
    Lssigma=imcData.Lssigma*m/3,
    Lszero=imcData.Lszero*m/3,
    Lm=imcData.Lm*m/3,
    Lrsigma=imcData.Lrsigma*m/3,
    Rr=imcData.Rr*m/3,
    effectiveStatorTurns=imcData.effectiveStatorTurns,
    TsOperational=imcData.TsRef,
    alpha20r=imcData.alpha20r,
    TrOperational=imcData.TrRef)
    ;
  Modelica.Electrical.Analog.Sources.SineVoltage sineVoltage(f=fsNominal, V=
        sqrt(2)*VsNominal)
    ;
  Modelica.Electrical.Analog.Basic.Ground ground ;
  Modelica.Blocks.Sources.BooleanStep booleanStep(startTime=tStart1) ;
  Modelica.Electrical.Analog.Ideal.IdealClosingSwitch idealCloser ;
  Modelica.Mechanics.Rotational.Components.Inertia loadInertia(J=JLoad) ;
  Modelica.Mechanics.Rotational.Sources.QuadraticSpeedDependentTorque
    quadraticLoadTorque(
    w_nominal=wLoad,
    TorqueDirection=false,
    tau_nominal=-tauLoad,
    useSupport=false) ;
  Modelica.Electrical.Machines.Utilities.TerminalBox terminalBox(terminalConnection="D") ;
  Modelica.Electrical.Polyphase.Basic.PlugToPin_p pin3(m=m, k=3) ;
  Modelica.Electrical.Polyphase.Basic.PlugToPin_p pin2(m=m, k=2) ;
  Modelica.Electrical.Polyphase.Basic.PlugToPin_p pin1(m=m, k=1) ;
  Modelica.Electrical.Analog.Basic.Capacitor cRun(C=Cr) ;
  Modelica.Electrical.Analog.Basic.Capacitor cStart(C=Cs) ;
  Modelica.Electrical.Analog.Ideal.IdealOpeningSwitch idealOpener ;
  Modelica.Blocks.Logical.GreaterThreshold greaterThreshold(threshold= wSwitch) ;
  Modelica.Mechanics.Rotational.Sensors.SpeedSensor speedSensor ;
  Modelica.Electrical.Polyphase.Sensors.CurrentSensor currentSensor annotation
    (Placement(transformation(
        origin={-10,-10},
        extent={{-10,-10},{10,10}},
        rotation=270)));
  Modelica.Blocks.Math.RootMeanSquare rmsI[m](f=fill(fsNominal, m)) ;
  parameter ParameterRecords.IMC imcData "Induction machine parameters" ;
initial equation
  imc.is = zeros(3);
  imc.rotorCage.electroMagneticConverter.V_m = Complex(0, 0);
  cStart.v = 0;
  cRun.v = 0;
equation
  connect(ground.p, sineVoltage.n) ;
  connect(sineVoltage.p, idealCloser.p) ;
  connect(booleanStep.y, idealCloser.control) ;
  connect(pin3.pin_p, sineVoltage.n) ;
  connect(idealCloser.n, pin2.pin_p) ;
  connect(cRun.n, pin1.pin_p) ;
  connect(loadInertia.flange_b, quadraticLoadTorque.flange) ;
  connect(cRun.p, idealCloser.n) ;
  connect(pin1.pin_p, cStart.n) ;
  connect(idealOpener.n, cStart.p) ;
  connect(idealOpener.p, idealCloser.n) ;
  connect(greaterThreshold.y, idealOpener.control) ;
  connect(terminalBox.plug_sn, imc.plug_sn) ;
  connect(terminalBox.plug_sp, imc.plug_sp) ;
  connect(imc.flange, loadInertia.flange_a) ;
  connect(speedSensor.flange, imc.flange) ;
  connect(speedSensor.w, greaterThreshold.u) ;
  connect(pin3.plug_p, currentSensor.plug_p) ;
  connect(pin2.plug_p, currentSensor.plug_p) ;
  connect(pin1.plug_p, currentSensor.plug_p) ;
  connect(currentSensor.plug_n, terminalBox.plugSupply) ;
  connect(rmsI.u, currentSensor.i) 
  ;
end IMC_Steinmetz;

within HanserModelica.InductionMachines;
model IMC_withLosses "Induction machine with squirrel cage and losses"
  extends Modelica.Icons.Example;
  import Modelica.Constants.pi;
  constant Integer m=3 "Number of phases";
  Modelica.Units.SI.Power Ps=electricalPowerSensor.apparentPower.re
    "Stator active power";
  Modelica.Units.SI.ReactivePower Qs=electricalPowerSensor.apparentPower.im
    "Stator reactive power";
  Modelica.Units.SI.ApparentPower Ss=sqrt(Ps^2 + Qs^2) "Stator apparent power";
protected
  parameter Real Ptable[:]={1E-6,1845,3549,5325,7521,9372,11010,12930,
      14950,16360,18500,18560,20180,22170} "Table of measured power data";
  parameter Real Itable[:]={11.0,11.20,12.27,13.87,16.41,18.78,21.07,
      23.92,27.05,29.40,32.85,32.95,35.92,39.35} "Table of measured current data";
  parameter Real wtable[:]=Modelica.Units.Conversions.from_rpm(  {1500,1496,1493,1490,1486,1482,1479,1475,1471,
      1467,1462,1462,1458,1453}) "Table of measured speed data";
  parameter Real ctable[:]={0.085,0.327,0.506,0.636,0.741,0.797,0.831,
      0.857,0.875,0.887,0.896,0.896,0.902,0.906} "Table of measured power factor data";
  parameter Real etable[:]={0,0.7250,0.8268,0.8698,0.8929,0.9028,0.9064,
      0.9088,0.9089,0.9070,0.9044,0.9043,0.9008,0.8972} "Table of measured efficiency data";
public
  output Modelica.Units.SI.Power Pm=powerSensor.power "Mechanical output power";
  output Modelica.Units.SI.Power Ps_sim=sqrt(3)*imcData.VsNominal*I_sim*pfs_sim
    "Simulated stator power";
  output Modelica.Units.SI.Power Ps_meas=sqrt(3)*imcData.VsNominal*I_meas*
      pfs_meas "Simulated stator power";
  output Modelica.Units.SI.Power loss_sim=Ps_sim - Pm "Simulated total losses";
  output Modelica.Units.SI.Power loss_meas=Ps_meas - Pm "Measured total losses";
  output Modelica.Units.SI.Current I_sim=currentRMSSensor.I "Simulated current";
  output Modelica.Units.SI.Current I_meas=combiTable1Ds.y[1] "Measured current";
  output Modelica.Units.SI.AngularVelocity w_sim(displayUnit="rev/min") = imc.wMechanical
    "Simulated speed";
  output Modelica.Units.SI.AngularVelocity w_meas(displayUnit="rev/min") =
    combiTable1Ds.y[2] "Measured speed";
  output Real pfs_sim=if noEvent(Ss > Modelica.Constants.small) then Ps/
      Ss else 0 "Simulated power factor";
  output Real pfs_meas=combiTable1Ds.y[3] "Measured power factor";
  output Real eff_sim=if noEvent(abs(Ps) > Modelica.Constants.small)
       then Pm/Ps else 0 "Simulated efficiency";
  output Real eff_meas=combiTable1Ds.y[4] "Measured efficiency";

  Modelica.Magnetic.QuasiStatic.FundamentalWave.BasicMachines.InductionMachines.IM_SquirrelCage imc(
    p=imcData.p,
    fsNominal=imcData.fsNominal,
    TsRef=imcData.TsRef,
    alpha20s(displayUnit="1/K") = imcData.alpha20s,
    Jr=imcData.Jr,
    Js=imcData.Js,
    frictionParameters=imcData.frictionParameters,
    statorCoreParameters=imcData.statorCoreParameters,
    strayLoadParameters=imcData.strayLoadParameters,
    TrRef=imcData.TrRef,
    wMechanical(fixed=true, start=imcData.w0),
    gammar(fixed=true, start=pi/2),
    gamma(fixed=true, start=-pi/2),
    Rs=imcData.Rs*m/3,
    Lssigma=imcData.Lssigma*m/3,
    Lm=imcData.Lm*m/3,
    Lrsigma=imcData.Lrsigma*m/3,
    Rr=imcData.Rr*m/3,
    m=m,
    effectiveStatorTurns=imcData.effectiveStatorTurns,
    TsOperational=imcData.TNominal,
    alpha20r=imcData.alpha20r,
    TrOperational=imcData.TNominal)
                               ;
  Modelica.Magnetic.QuasiStatic.FundamentalWave.Utilities.MultiTerminalBox terminalBox(terminalConnection="D", m=m) ;
  Modelica.Electrical.QuasiStatic.Polyphase.Sensors.PowerSensor
    electricalPowerSensor(m=m) ;
  Modelica.Electrical.QuasiStatic.Polyphase.Sensors.CurrentQuasiRMSSensor
    currentRMSSensor(m=m) ;
  Modelica.Electrical.QuasiStatic.Polyphase.Sources.VoltageSource sineVoltage(
    final m=m,
    f=imcData.fsNominal,
    V=fill(imcData.VsNominal/sqrt(3), m)) ;
  Modelica.Electrical.QuasiStatic.Polyphase.Basic.Star star(final m=m)
    ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Basic.Ground ground ;
  Modelica.Mechanics.Rotational.Sensors.PowerSensor powerSensor ;
  Modelica.Mechanics.Rotational.Components.Inertia loadInertia(J=imcData.Jr) ;
  Modelica.Mechanics.Rotational.Sources.Torque torque ;
