model EquivalentCircuit "Comparison of equivalent circuits of electric and magnetic circuits"
  extends Modelica.Icons.Example;
  constant Integer m=3 "Number of phases";
  parameter Modelica.Units.SI.Voltage VNominal=400 "Nominal phase voltage";
  parameter Modelica.Units.SI.Frequency fNominal=50 "Nominal frequency";
  // Equivalent electric circuit
  parameter Modelica.Units.SI.Resistance R=0.56 "Winding resistance";
  parameter Modelica.Units.SI.Inductance Lsigma=4.848E-3 "Stray inductance";
  parameter Modelica.Units.SI.Inductance Lm=0.2114 "Magnetizing inductance";
  parameter Real effectiveTurns = 135.0 "Number of effective turns";
  parameter Modelica.Units.SI.Conductance Gc=908.2E-6
    "Electric loss conductance";
  // Equivalent magnetic circuit
  parameter Modelica.Units.SI.Conductance G=m*effectiveTurns^2*Gc/2
    "Magnetic loss conductance";
  parameter Modelica.Units.SI.Reluctance R_msigma=m*effectiveTurns^2/2/Lsigma
    "Stray reluctance";
  parameter Modelica.Units.SI.Reluctance R_m=m*effectiveTurns^2/2/Lm
    "Main field reluctance";
  Modelica.Units.SI.ComplexCurrent i_e[m]=resistor_e.i
    "Current of electric circuit";
  Modelica.Units.SI.ComplexCurrent i_m[m]=resistor_m.i
    "Current of magnetic circuit";
  Modelica.Units.SI.Power coreLoss_e=sum(core_e.conductor.LossPower);
  Modelica.Units.SI.Power coreLoss_m=core_m.lossPower;
  Modelica.Electrical.QuasiStatic.Polyphase.Sources.VoltageSource sineVoltage_e(
    m=m,
    phi=-Modelica.Electrical.Polyphase.Functions.symmetricOrientation(m),
    gamma(fixed=true, start=0),
    f=fNominal,
    V=fill(VNominal, m)) ;
  Modelica.Electrical.QuasiStatic.Polyphase.Sources.VoltageSource sineVoltage_m(
    m=m,
    phi=-Modelica.Electrical.Polyphase.Functions.symmetricOrientation(m),
    gamma(fixed=true, start=0),
    f=fNominal,
    V=fill(VNominal, m)) ;
  Modelica.Electrical.QuasiStatic.Polyphase.Basic.Resistor resistor_e(m=m,
      R_ref=fill(R, m)) ;
  Modelica.Electrical.QuasiStatic.Polyphase.Basic.Resistor resistor_m(m=m,
      R_ref=fill(R, m)) ;
  Modelica.Electrical.QuasiStatic.Polyphase.Basic.Conductor core_e(m=m, G_ref=
        fill(Gc, m)) ;
  Modelica.Magnetic.QuasiStatic.FundamentalWave.Components.PolyphaseElectroMagneticConverter
    converter_m(m=m, effectiveTurns=effectiveTurns)
    ;
  Modelica.Magnetic.QuasiStatic.FundamentalWave.Components.EddyCurrent core_m(G=G)
    ;
  Modelica.Magnetic.QuasiStatic.FundamentalWave.Components.Reluctance main_m(
    R_m(d=R_m, q=R_m))
    ;
  Modelica.Electrical.QuasiStatic.Polyphase.Basic.Inductor stray_e(m=m, L=fill(
        Lsigma, m))
    ;
  Modelica.Magnetic.QuasiStatic.FundamentalWave.Components.Reluctance stray_m(R_m(d=R_msigma, q=R_msigma))
    ;
  Modelica.Electrical.QuasiStatic.Polyphase.Basic.Inductor main_e(m=m, L=fill(
        Lm, m)) ;
  Modelica.Electrical.QuasiStatic.Polyphase.Sensors.PowerSensor powerb_e(m=m)
    ;
  Modelica.Electrical.QuasiStatic.Polyphase.Sensors.PowerSensor powerb_m(m=m)
    ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Basic.Ground ground_e
    ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Basic.Ground ground_m
    ;
  Modelica.Magnetic.QuasiStatic.FundamentalWave.Components.Ground mground_m
    ;
  Modelica.Electrical.QuasiStatic.Polyphase.Basic.Star star_e(m=m) ;
  Modelica.Electrical.QuasiStatic.Polyphase.Basic.Star star_m(m=m) ;
equation
  connect(sineVoltage_e.plug_n, star_e.plug_p) ;
  connect(resistor_e.plug_p, sineVoltage_e.plug_p) ;
  connect(core_e.plug_n, sineVoltage_e.plug_n) ;
  connect(resistor_e.plug_n, powerb_e.currentP) ;
  connect(star_e.pin_n, ground_e.pin) ;
  connect(powerb_e.currentP, powerb_e.voltageP) ;
  connect(powerb_e.voltageN, sineVoltage_e.plug_n) ;
  connect(sineVoltage_m.plug_n, star_m.plug_p) ;
  connect(sineVoltage_m.plug_n, converter_m.plug_n) ;
  connect(converter_m.port_n, main_m.port_n) ;
  connect(converter_m.port_p,core_m. port_p) ;
  connect(core_m.port_n, main_m.port_p) ;
  connect(converter_m.port_n, mground_m.port_p) ;
  connect(sineVoltage_m.plug_p, resistor_m.plug_p) ;
  connect(resistor_m.plug_n, powerb_m.currentP) ;
  connect(powerb_m.currentN, converter_m.plug_p) ;
  connect(star_m.pin_n, ground_m.pin) ;
  connect(powerb_m.currentP, powerb_m.voltageP) ;
  connect(powerb_m.voltageN, sineVoltage_m.plug_n) ;
  connect(powerb_e.currentN,core_e. plug_p) ;
  connect(core_e.plug_p, stray_e.plug_p) ;
  connect(stray_e.plug_n, main_e.plug_p) ;
  connect(core_e.plug_n, main_e.plug_n) ;
  connect(core_m.port_n, stray_m.port_p) ;
  connect(stray_m.port_n, converter_m.port_n) 
  ;
end EquivalentCircuit;

