within HanserModelica.Magnetic.Components;
model Transformer "Transformer model"
  parameter Integer N1 "Number of primary turns";
  parameter Integer N2 "Number of secondary turns";
  parameter Modelica.Units.SI.Resistance R1 "Primary resistance";
  parameter Modelica.Units.SI.Resistance R2 "Secondary resistance";
  parameter Modelica.Units.SI.Permeance G_m1sigma "Primary stray inductance";
  parameter Modelica.Units.SI.Permeance G_m2sigma "Secondary stray inductance";
  parameter Modelica.Units.SI.Reluctance R_m "Main field reluctance";
  parameter Modelica.Units.SI.Conductance Gc "Eddy current loss conductance";
  Modelica.Units.SI.Current i1(start=0) = p1.i "Primary current";
  Modelica.Units.SI.Current i2(start=0) = p2.i "Secondary current";
  Modelica.Units.SI.Voltage v1=p1.v - n1.v "Primary voltage";
  Modelica.Units.SI.Voltage v2=p2.v - n2.v "Secondary voltage";
  Modelica.Electrical.Analog.Interfaces.PositivePin p1 ;
  Modelica.Electrical.Analog.Interfaces.PositivePin p2 ;
  Modelica.Electrical.Analog.Interfaces.NegativePin n1 ;
  Modelica.Electrical.Analog.Interfaces.NegativePin n2 ;
  Modelica.Magnetic.FluxTubes.Basic.ElectroMagneticConverter converter1(final N = N1) ;
  Modelica.Magnetic.FluxTubes.Basic.ElectroMagneticConverter converter2(final N = N2) ;
  Modelica.Magnetic.FluxTubes.Basic.Ground ground ;
  Modelica.Electrical.Analog.Basic.Resistor resistor2(final R = R2) ;
  Modelica.Magnetic.FluxTubes.Basic.ConstantPermeance strayPermeanc1(final G_m = G_m1sigma) ;
  Modelica.Electrical.Analog.Basic.Resistor resistor1(final R = R1) ;
  Modelica.Magnetic.FluxTubes.Basic.ConstantPermeance strayPermeanc2(final G_m = G_m2sigma) ;
  Modelica.Magnetic.FluxTubes.Basic.EddyCurrent eddyCurrent(useConductance = true, final G = Gc) ;
  Modelica.Magnetic.FluxTubes.Basic.ConstantReluctance mainReluctance(final R_m=R_m) ;
  Modelica.Magnetic.FluxTubes.Basic.Crossing crossing ;
equation
  connect(converter1.n, n1) ;
  connect(resistor2.p, p2) ;
  connect(converter2.n, n2) ;
  connect(resistor1.p, p1) ;
  connect(resistor1.n, converter1.p) ;
  connect(resistor2.n, converter2.p) ;
  connect(converter1.port_p, eddyCurrent.port_p) ;
  connect(eddyCurrent.port_n, strayPermeanc1.port_p) ;
  connect(eddyCurrent.port_n, mainReluctance.port_p) ;
  connect(strayPermeanc2.port_p, converter2.port_p) ;
  connect(converter2.port_n, strayPermeanc2.port_n) ;
  connect(crossing.port_p1, converter2.port_p) ;
  connect(crossing.port_n2, converter2.port_n) ;
  connect(crossing.port_p2, converter1.port_n) ;
  connect(strayPermeanc1.port_n, converter1.port_n) ;
  connect(ground.port, converter1.port_n) ;
  connect(mainReluctance.port_n, crossing.port_n1) 
  ;
end Transformer;

within HanserModelica.MoveTo_Modelica.ComplexBlocks.ComplexMath;
block Bode "Calculate quantities to plot Bode diagram"
  parameter Boolean useDivisor = true "Use divisor input, if true" ;
  constant Modelica.Units.SI.AmplitudeLevelDifference dB=20
    "Amplitude level difference";
  Modelica.ComplexBlocks.Interfaces.ComplexInput u "Dividend if useDivisor == true" ;
  Modelica.ComplexBlocks.Interfaces.ComplexInput divisor if useDivisor "Divisor" ;
  Modelica.Blocks.Interfaces.RealOutput abs_y "Absolute value of ratio u / divisor" ;
  Modelica.Blocks.Interfaces.RealOutput arg_y(unit="rad") "Angle of ratio u / divisor" ;
  Modelica.ComplexBlocks.Interfaces.ComplexOutput y "Quotient y = u / divisor" ;
  Modelica.ComplexBlocks.Sources.ComplexConstant complexOne(final k=Complex(1, 0)) if not useDivisor "Complex(1,0)" ;
  Division                                    division(final useConjugateInput1=false, final useConjugateInput2=false) ;
  Modelica.ComplexBlocks.ComplexMath.ComplexToPolar complexToPolar(final useConjugateInput=false) ;
  Modelica.Blocks.Interfaces.RealOutput dB_y(unit="dB") "Log10 of absolute value of ratio u / divisor in dB" ;
  Modelica.Blocks.Math.Log10 log10_y ;
  Modelica.Blocks.Math.Gain gain(final k=dB) ;
  Modelica.Blocks.Nonlinear.Limiter limiter(final uMax=Modelica.Constants.inf, final uMin=Modelica.Constants.eps) ;
equation

  connect(complexOne.y, division.u2) ;
  connect(divisor, division.u2) ;
  connect(division.u1, u) ;
  connect(division.y, y) ;
  connect(complexToPolar.u, y) ;
  connect(complexToPolar.phi, arg_y) ;
  connect(complexToPolar.len, abs_y) ;
  connect(log10_y.y, gain.u) ;
  connect(gain.y, dB_y) ;
  connect(limiter.y, log10_y.u) ;
  connect(complexToPolar.len, limiter.u) 
  ;
end Bode;

within HanserModelica.MoveTo_Modelica.ComplexBlocks.ComplexMath;
block Division "Output first input divided by second input"
  extends Modelica.ComplexBlocks.Interfaces.ComplexSI2SO;
equation
  y.re = (u1.re*u2.re + u1.im*u2.im) / (u2.re^2 + u2.im^2);
  y.im = (u1.im*u2.re - u1.re*u2.im) / (u2.re^2 + u2.im^2)
  ;
end Division;

