within HanserModelica.SynchronousMachines;
model SMEE_Rectifier "Electrical excited synchronous machine with rectifier"

  extends Modelica.Icons.Example;
  import Modelica.Constants.pi;
  constant Integer m=3 "Number of phases";
  parameter Modelica.Units.SI.AngularVelocity wNominal=2*pi*smeeData.fsNominal/
      smee.p "Nominal speed";
  parameter Modelica.Units.SI.Voltage VDC0=sqrt(2*3)*smeeData.VsNominal
    "No-load DC voltage";
  parameter Modelica.Units.SI.Resistance RLoad=VDC0^2/smeeData.SNominal
    "Load resistance";
  parameter Modelica.Units.SI.Voltage Ve0=smee.IeOpenCircuit*
      Modelica.Electrical.Machines.Thermal.convertResistance(
      smee.Re,
      smee.TeRef,
      smee.alpha20e,
      smee.TeOperational) "No load excitation voltage";
  parameter Real k=2*Ve0/smeeData.VsNominal "Voltage controller: gain";
  parameter Modelica.Units.SI.Time Ti=smeeData.Td0Transient/2
    "Voltage controller: integral time constant";
  output Modelica.Units.SI.Current ie=smee.ie "Excitation current";
  Modelica.Magnetic.FundamentalWave.BasicMachines.SynchronousMachines.SM_ElectricalExcited
    smee(
    fsNominal=smeeData.fsNominal,
    TsRef=smeeData.TsRef,
    Lrsigmad=smeeData.Lrsigmad,
    Lrsigmaq=smeeData.Lrsigmaq,
    Rrd=smeeData.Rrd,
    Rrq=smeeData.Rrq,
    TrRef=smeeData.TrRef,
    VsNominal=smeeData.VsNominal,
    IeOpenCircuit=smeeData.IeOpenCircuit,
    Re=smeeData.Re,
    TeRef=smeeData.TeRef,
    sigmae=smeeData.sigmae,
    useDamperCage=true,
    p=2,
    Jr=0.29,
    Js=0.29,
    statorCoreParameters(VRef=100),
    strayLoadParameters(IRef=100),
    brushParameters(ILinear=0.01),
    ir(each fixed=true),
    Rs=smeeData.Rs*m/3,
    Lssigma=smeeData.Lssigma*m/3,
    Lmd=smeeData.Lmd*m/3,
    Lmq=smeeData.Lmq*m/3,
    effectiveStatorTurns=smeeData.effectiveStatorTurns,
    TsOperational=smeeData.TsRef,
    alpha20s=smeeData.alpha20s,
    alpha20r=smeeData.alpha20r,
    TrOperational=smeeData.TrRef,
    TeOperational=smeeData.TeRef,
    alpha20e=smeeData.alpha20e)
    ;
  parameter Modelica.Electrical.Machines.Utilities.SynchronousMachineData smeeData(
    SNominal=30e3,
    VsNominal=100,
    fsNominal=50,
    IeOpenCircuit=10,
    x0=0.1,
    xd=1.6,
    xq=1.6,
    xdTransient=0.1375,
    xdSubtransient=0.121428571,
    xqSubtransient=0.148387097,
    Ta=0.014171268,
    Td0Transient=0.261177343,
    Td0Subtransient=0.006963029,
    Tq0Subtransient=0.123345081,
    alpha20s(displayUnit="1/K") = Modelica.Electrical.Machines.Thermal.Constants.alpha20Zero,
    alpha20r(displayUnit="1/K") = Modelica.Electrical.Machines.Thermal.Constants.alpha20Zero,
    alpha20e(displayUnit="1/K") = Modelica.Electrical.Machines.Thermal.Constants.alpha20Zero,
    effectiveStatorTurns=64,
    TsSpecification=373.15,
    TsRef=373.15,
    TrSpecification=373.15,
    TrRef=373.15,
    TeSpecification=373.15,
    TeRef=373.15) "Synchronous machine data" ;

  Modelica.Electrical.Machines.Utilities.TerminalBox terminalBox(terminalConnection="Y") ;
  Modelica.Electrical.Analog.Basic.Ground ground ;
  Modelica.Mechanics.Rotational.Sources.Speed speed
    ;
  Modelica.Blocks.Sources.Constant constantSpeed(k=wNominal) ;
  Modelica.Mechanics.Rotational.Sensors.SpeedSensor speedSensor
    ;
  Modelica.Blocks.Math.Gain setPointGain(k=(smeeData.VsNominal/wNominal)/
        unitMagneticFlux)
    ;
  Modelica.Blocks.Continuous.LimPID voltageController(
    controllerType=Modelica.Blocks.Types.SimpleController.PI,
    k=k,
    Ti=Ti,
    yMax=2.5*Ve0,
    yMin=0,
    initType=Modelica.Blocks.Types.Init.InitialState,
    Td=0.001)
    ;
  Modelica.Electrical.Analog.Sources.SignalVoltage excitationVoltage
    ;
  Modelica.Electrical.Analog.Basic.Ground groundExcitation ;
  Modelica.Electrical.Analog.Basic.Capacitor capacitor1(           v(
        fixed=true, start=0), C=20E-6)
                              ;
  Modelica.Electrical.Analog.Basic.Capacitor capacitor2(           v(
        fixed=true, start=0), C=20E-6)
                              ;
  Modelica.Electrical.Analog.Basic.Resistor resistor(R=RLoad) ;
  Modelica.Electrical.Analog.Sensors.VoltageSensor voltageSensor
    ;
  Modelica.Blocks.Continuous.Filter filter(
    analogFilter=Modelica.Blocks.Types.AnalogFilter.CriticalDamping,
    filterType=Modelica.Blocks.Types.FilterType.LowPass,
    order=2,
    f_cut=20,
    gain=1/sqrt(2*3),
    normalized=true) ;
protected
  constant Modelica.Units.SI.MagneticFlux unitMagneticFlux=1
    ;
public
  Modelica.Electrical.PowerConverters.ACDC.DiodeBridge2mPulse rectifier ;
initial equation
  smee.is[1:2] = zeros(2);
  //conditional damper cage currents are defined as fixed start values
  smee.ie = 0;
equation
  connect(terminalBox.plug_sn, smee.plug_sn) ;
  connect(terminalBox.plug_sp, smee.plug_sp) ;
  connect(excitationVoltage.p, smee.pin_ep) ;
  connect(excitationVoltage.n, smee.pin_en) ;
  connect(excitationVoltage.n, groundExcitation.p) ;
  connect(smee.flange, speed.flange) ;
  connect(speed.flange, speedSensor.flange) ;
  connect(constantSpeed.y, speed.w_ref) ;
  connect(setPointGain.y, voltageController.u_s) ;
  connect(speedSensor.w, setPointGain.u) ;
  connect(voltageController.y, excitationVoltage.v) ;
  connect(capacitor1.n, capacitor2.p) ;
  connect(capacitor1.n, ground.p) ;
  connect(filter.y, voltageController.u_m) ;
  connect(voltageSensor.v, filter.u) ;
  connect(resistor.p, capacitor1.p) ;
  connect(resistor.n, capacitor2.n) ;
  connect(voltageSensor.n, capacitor2.n) ;
  connect(voltageSensor.p, capacitor1.p) ;
  connect(rectifier.dc_p, capacitor1.p) ;
  connect(rectifier.dc_n, capacitor2.n) ;
  connect(rectifier.ac, terminalBox.plugSupply) 
  ;
end SMEE_Rectifier;

