  parameter Modelica.Units.SI.Voltage Ve=smeeData.Re*smeeData.IeOpenCircuit
    "Excitation current";
  parameter Modelica.Units.SI.Angle gamma0(displayUnit="deg") = 0
    "Initial rotor displacement angle";
  parameter Modelica.Units.SI.AngularVelocity wNominal=2*pi*smeeData.fsNominal/
      p "Nominal angular velocity";
  Modelica.Units.SI.Current irRMS=sqrt(smee.ir[1]^2 + smee.ir[2]^2)/sqrt(2)
    "Quasi RMS rotor current";
  output Modelica.Units.SI.Current ie=smee.ie "Excitation current";
  Modelica.Magnetic.FundamentalWave.BasicMachines.SynchronousMachines.SM_ElectricalExcited
    smee(
    phiMechanical(start=-(pi + gamma0)/smee.p, fixed=true),
    fsNominal=smeeData.fsNominal,
    TsRef=smeeData.TsRef,
    Lrsigmad=smeeData.Lrsigmad,
    Lrsigmaq=smeeData.Lrsigmaq,
    Rrd=smeeData.Rrd,
    Rrq=smeeData.Rrq,
    TrRef=smeeData.TrRef,
    VsNominal=smeeData.VsNominal,
    IeOpenCircuit=smeeData.IeOpenCircuit,
    Re=smeeData.Re,
    TeRef=smeeData.TeRef,
    p=p,
    Jr=0.29,
    Js=0.29,
    useDamperCage=true,
    statorCoreParameters(VRef=100),
    strayLoadParameters(IRef=100),
    brushParameters(ILinear=0.01),
    ir(each fixed=true),
    wMechanical(fixed=true, start=wNominal),
    m=m,
    Rs=smeeData.Rs*m/3,
    Lssigma=smeeData.Lssigma*m/3,
    Lmd=smeeData.Lmd*m/3,
    Lmq=smeeData.Lmq*m/3,
    sigmae=smeeData.sigmae*m/3,
    TsOperational=smeeData.TsRef,
    alpha20s=smeeData.alpha20s,
    effectiveStatorTurns=smeeData.effectiveStatorTurns,
    alpha20r=smeeData.alpha20r,
    TrOperational=smeeData.TrRef,
    TeOperational=smeeData.TeRef,
    alpha20e=smeeData.alpha20e)
    ;
  Modelica.Electrical.Analog.Basic.Ground groundExcitation ;
  Modelica.Electrical.Polyphase.Sensors.MultiSensor multiSensor(m=m)
    ;
  Modelica.Electrical.Polyphase.Sensors.CurrentQuasiRMSSensor currentRMSSensor(
      m=m) ;
  Modelica.Electrical.Polyphase.Sources.SineVoltage sineVoltage(
    final m=m,
    final V=fill(VNominal*sqrt(2), m),
    final f=fill(fNominal, m),
    phase=-Modelica.Electrical.Polyphase.Functions.symmetricOrientation(m) -
        fill(phi, m))
    ;
  Modelica.Electrical.Polyphase.Basic.Star star(final m=m)
    ;
  Modelica.Electrical.Analog.Basic.Ground ground ;
  Modelica.Electrical.Analog.Sources.ConstantCurrent constantCurrent(I=smeeData.IeOpenCircuit) ;
  Modelica.Electrical.Machines.Utilities.TerminalBox terminalBox(terminalConnection="Y", m=m) ;

  Modelica.Electrical.Polyphase.Ideal.IdealClosingSwitch switch(
    final m=m,
    Ron=fill(1e-5*m/3, m),
    Goff=fill(1e-5*m/3, m)) ;
  Modelica.Blocks.Sources.BooleanStep booleanStep(startTime=0.1)
                                                               ;
  Modelica.Blocks.Routing.BooleanReplicator booleanReplicator(nout=m) ;
  Modelica.Mechanics.Rotational.Sources.ConstantTorque constantTorque(tau_constant=0) ;
  parameter ParameterRecords.SMEE1 smeeData "Synchronous machine data" ;
initial equation
  // sum(smee.is) = 0;
  smee.is[1:2] = zeros(2);
  //conditional damper cage currents are defined as fixed start values
equation
  connect(star.pin_n, ground.p)
    ;
  connect(star.plug_p, sineVoltage.plug_n)
    ;
  connect(terminalBox.plugSupply, currentRMSSensor.plug_n) ;
  connect(terminalBox.plug_sn, smee.plug_sn) ;
  connect(terminalBox.plug_sp, smee.plug_sp) ;
  connect(sineVoltage.plug_p, switch.plug_p) ;
  connect(booleanReplicator.y, switch.control) ;
  connect(booleanStep.y, booleanReplicator.u)
    ;
  connect(switch.plug_n, multiSensor.pc) ;
  connect(multiSensor.nv, terminalBox.plug_sn) ;
  connect(multiSensor.nc, currentRMSSensor.plug_p) ;
  connect(multiSensor.pv, multiSensor.pc) ;
  connect(constantCurrent.p, groundExcitation.p) ;
  connect(constantCurrent.p, smee.pin_en) ;
  connect(smee.pin_ep, constantCurrent.n) ;
  connect(smee.flange, constantTorque.flange) 
  ;
end SMEE_Synchronization1;

