within IBPSA.Fluid.Geothermal.Borefields.BaseClasses.HeatTransfer.ThermalResponseFactors;
function finiteLineSource
  "Finite line source solution of Claesson and Javed"
  extends Modelica.Icons.Function;

  input Modelica.Units.SI.Time t "Time";
  input Modelica.Units.SI.ThermalDiffusivity aSoi "Ground thermal diffusivity";
  input Modelica.Units.SI.Distance dis "Radial distance between borehole axes";
  input Modelica.Units.SI.Height len1 "Length of emitting borehole";
  input Modelica.Units.SI.Height burDep1 "Buried depth of emitting borehole";
  input Modelica.Units.SI.Height len2 "Length of receiving borehole";
  input Modelica.Units.SI.Height burDep2 "Buried depth of receiving borehole";
  input Boolean includeRealSource = true "True if contribution of real source is included";
  input Boolean includeMirrorSource = true "True if contribution of mirror source is included";

  output Real h_21 "Thermal response factor of borehole 1 on borehole 2";

protected
  Real lowBou(unit="m-1") "Lower bound of integration";
  // Upper bound is infinite
  Real uppBou(unit="m-1") = max(100.0, 10.0/dis) "Upper bound of integration";
  Modelica.Units.SI.Distance disMin
    "Minimum distance between sources and receiving line";
  Modelica.Units.SI.Time timTre "Time treshold for evaluation of the solution";

algorithm

  h_21 := 0;
  if t > 0 and (includeRealSource or includeMirrorSource) then
    // Find the minimum distance between the line source and the line where the
    // finite line source solution is evaluated.
    if includeRealSource then
      if (burDep2 + len2) < burDep1 then
        disMin := sqrt(dis^2 + (burDep1 - burDep2 - len2)^2);
      elseif burDep2 > (burDep1 + len1) then
        disMin := sqrt(dis^2 + (burDep1 - burDep2 + len1)^2);
      else
        disMin := dis;
      end if;
    else
      disMin := sqrt(dis^2 + (burDep1 + burDep2)^2);
    end if;
    // The traveled distance of the temperature front is assumed to be:
    // d = 5*sqrt(aSoi*t).
    // The solution is only evaluated at times when the traveled distance is
    // greater than the minimum distance.
    timTre := disMin^2/(25*aSoi);

    if t >= timTre then
      lowBou := 1.0/sqrt(4*aSoi*t);
      h_21 := Modelica.Math.Nonlinear.quadratureLobatto(
        function
          IBPSA.Fluid.Geothermal.Borefields.BaseClasses.HeatTransfer.ThermalResponseFactors.finiteLineSource_Integrand(
          dis=dis,
          len1=len1,
          burDep1=burDep1,
          len2=len2,
          burDep2=burDep2,
          includeRealSource=includeRealSource,
          includeMirrorSource=includeMirrorSource),
        lowBou,
        uppBou,
        1.0e-6);
    else
      // Linearize the solution at times below the time treshold.
      lowBou := 1.0/sqrt(4*aSoi*timTre);
      h_21 := t/timTre*Modelica.Math.Nonlinear.quadratureLobatto(
        function
          IBPSA.Fluid.Geothermal.Borefields.BaseClasses.HeatTransfer.ThermalResponseFactors.finiteLineSource_Integrand(
          dis=dis,
          len1=len1,
          burDep1=burDep1,
          len2=len2,
          burDep2=burDep2,
          includeRealSource=includeRealSource,
          includeMirrorSource=includeMirrorSource),
        lowBou,
        uppBou,
        1.0e-6);
    end if;
  end if

;
end finiteLineSource;

within IBPSA.Electrical.Transmission.Functions;
function R_AC_correction
  "This function computes the correction factor of the DC resistance for AC systems at 60 Hz"
  input String size "Size of the commercial cable (AWG or kcmil)";
  input IBPSA.Electrical.Transmission.Types.Material material
    "Material of the cable";
  output Real correction "Correction factor";
algorithm
  if material == IBPSA.Electrical.Transmission.Types.Material.Al then
    if size == "1/0" then
      correction := 1.0;
    elseif size == "2/0" then
      correction := 1.001;
    elseif size == "3/0" then
      correction := 1.001;
    elseif size == "4/0" then
      correction := 1.001;
    elseif size == "250" then
      correction := 1.002;
    elseif size == "300" then
      correction := 1.003;
    elseif size == "350" then
      correction := 1.004;
    elseif size == "400" then
      correction := 1.005;
    elseif size == "500" then
      correction := 1.007;
    elseif size == "600" then
      correction := 1.01;
    elseif size == "700" then
      correction := 1.013;
    elseif size == "750" then
      correction := 1.015;
    elseif size == "800" then
      correction := 1.017;
    elseif size == "1000" then
      correction := 1.026;
    elseif size == "1250" then
      correction := 1.04;
    elseif size == "1500" then
      correction := 1.058;
    elseif size == "1750" then
      correction := 1.079;
    elseif size == "2000" then
      correction := 1.1;
    elseif size == "2500" then
      correction := 1.142;
    else
      correction := 1.0;
    end if;

  elseif material == IBPSA.Electrical.Transmission.Types.Material.Cu then
    if size == "1/0" then
      correction := 1.0;
    elseif size == "2/0" then
      correction := 1.001;
    elseif size == "3/0" then
      correction := 1.002;
    elseif size == "4/0" then
      correction := 1.004;
    elseif size == "250" then
      correction := 1.005;
    elseif size == "300" then
      correction := 1.006;
    elseif size == "350" then
      correction := 1.009;
    elseif size == "400" then
      correction := 1.011;
    elseif size == "500" then
      correction := 1.018;
    elseif size == "600" then
      correction := 1.025;
    elseif size == "700" then
      correction := 1.034;
    elseif size == "750" then
      correction := 1.039;
    elseif size == "800" then
      correction := 1.044;
    elseif size == "1000" then
      correction := 1.067;
    elseif size == "1250" then
      correction := 1.102;
    elseif size == "1500" then
      correction := 1.142;
    elseif size == "1750" then
      correction := 1.185;
    elseif size == "2000" then
      correction := 1.233;
    elseif size == "2500" then
      correction := 1.326;
    else
      correction := 1.0;
    end if;
  else
    assert(material <> IBPSA.Electrical.Transmission.Types.Material.Al and
           material <> IBPSA.Electrical.Transmission.Types.Material.Cu,
    "In function IBPSA.Electrical.Transmission.Functions.R_AC_Correction,
    does not support material " + String(material) + ".
    The selected cable has the R_AC_Correction of the Copper.",
    level = AssertionLevel.warning);

    correction := 1.0;
  end if
;
end R_AC_correction;

