within IBPSA.Fluid.HeatPumps.Compressors;
model ReciprocatingCompressor
  "Model for a reciprocating compressor, based on Jin (2002)"
  extends IBPSA.Fluid.HeatPumps.Compressors.BaseClasses.PartialCompressor;

  parameter Modelica.Units.SI.VolumeFlowRate pisDis "Piston displacement";

  parameter Real cleFac(
    min = 0,
    final unit = "1")
    "Clearance factor";

  parameter Modelica.Units.SI.Efficiency etaEle
    "Electro-mechanical efficiency of the compressor";

  parameter Modelica.Units.SI.Power PLos(min=0)
    "Constant part of the compressor power losses";

  parameter Modelica.Units.SI.AbsolutePressure pDro
    "Pressure drop at suction and discharge of the compressor";

  parameter Modelica.Units.SI.TemperatureDifference dTSup(min=0)
    "Superheating at compressor suction";

  Modelica.Units.SI.MassFlowRate m_flow "Refrigerant mass flow rate";

  Modelica.Units.SI.Power PThe "Theoretical power consumed by the compressor";

  Modelica.Units.SI.Efficiency COP(start=5) "Heating COP of the compressor";

protected
  Modelica.Units.SI.IsentropicExponent k(start=1.2)
    "Isentropic exponent of the refrigerant";

  Real pisDis_norm
    "Normalized piston displacement at part load conditions";

equation
  // Limit compressor speed to the full load speed
  pisDis_norm = IBPSA.Utilities.Math.Functions.smoothLimit(y, 0.0, 1.0, 0.001);

  if isOn then
    // Suction pressure
    pSuc = IBPSA.Utilities.Math.Functions.smoothMin(pEva - pDro, pCon - pDro, 0.01*ref.pCri);
    // Discharge pressure
    pDis = pCon + pDro;
    // Refrigerant mass flow rate
    k = ref.isentropicExponentVap_Tv(TSuc, vSuc);
    m_flow = pisDis_norm*pisDis/vSuc*(1 + cleFac
       - cleFac*(PR)^(1/k));
    // Theoretical power of the compressor
    PThe = k/(k-1) * m_flow*pSuc*vSuc*((PR)^((k-1)/k)-1);
    // Power consumed by the compressor
    P = PThe/etaEle + PLos;
    // Temperature at suction of the compressor
    TSuc = port_a.T + dTSup;
    // Energy balance of the compressor
    port_a.Q_flow = m_flow * (hEva - hCon);
    port_b.Q_flow = - (port_a.Q_flow + P);
    -port_b.Q_flow = P * COP;
  else
    // Heat pump is turned off
    k = 1.0;
    pSuc = pEva;
    pDis = pCon;
    m_flow = 0;
    PThe = 0;
    P = 0;
    TSuc = port_a.T;
    port_a.Q_flow = 0;
    port_b.Q_flow = 0;
    COP = 1.0;
  end if

  ;
end ReciprocatingCompressor;

within IBPSA.Utilities.Math.Functions;
function smoothHeaviside
  "Twice continuously differentiable approximation to the Heaviside function"
  extends Modelica.Icons.Function;
  input Real x "Argument";
  input Real delta(min=Modelica.Constants.eps) "Parameter used for scaling";
  output Real y "Result";
protected
  Real dx=0.5*x/delta "Scaled input argument";
  Real xpow2=dx*dx "=dx*dx";
algorithm
  y := smooth(2, max(0, min(1, 0.5+dx*(1.875+xpow2*(-5+6*xpow2)))))

 ;
end smoothHeaviside;

within IBPSA.Utilities.Math.Functions.BaseClasses;
function der_spliceFunction "Derivative of splice function"
  extends Modelica.Icons.Function;
  input Real pos;
  input Real neg;
  input Real x;
  input Real deltax=1;
  input Real dpos;
  input Real dneg;
  input Real dx;
  input Real ddeltax=0;
  output Real out;
protected
  constant Real lim = 0.9999999999 "Limit in criterion for smoothing range";
  Real scaledX1 "x scaled to -1 ... 1 interval";
  Real scaledXp "x scaled to -pi/2 ... pi/2 interval";
  Real scaledXt "x scaled to -inf ... inf interval";
  Real dscaledX1;
  Real y;
algorithm
  scaledX1 := x/deltax;
  if scaledX1 <= -lim then
    y := 0.0;
  elseif scaledX1 >= lim then
    y := 1.0;
  else
    scaledXp := scaledX1*0.5*Modelica.Constants.pi;
    scaledXt := Modelica.Math.tan(scaledXp);
    y := 0.5*Modelica.Math.tanh(scaledXt) + 0.5;
  end if;
  out := dpos*y + (1 - y)*dneg;

  if (abs(scaledX1) < lim) then
    dscaledX1 := (dx - scaledX1*ddeltax)/deltax;
    out := out + (pos - neg)*dscaledX1*0.25*Modelica.Constants.pi*(1 - Modelica.Math.tanh(scaledXt)^2)*(scaledXt^2 + 1);
  end if

;
end der_spliceFunction;

within IBPSA.Fluid.Movers.BaseClasses.Euler;
function efficiency
  "Computes efficiency with the Euler number correlation"
  extends Modelica.Icons.Function;
  input IBPSA.Fluid.Movers.BaseClasses.Euler.peak peak
    "Operation point with maximum efficiency";
  input Modelica.Units.SI.PressureDifference dp
    "Pressure rise";
  input Modelica.Units.SI.VolumeFlowRate V_flow
    "Volumetric flow rate";
  input Real V_flow_dp_small(
    final unit="m3.Pa/s",
    min = Modelica.Constants.eps)
    "Small number for regularisation";
  output Modelica.Units.SI.Efficiency eta
    "Efficiency";

protected
  Real log_r_Eu "Log10 of Eu/Eu_peak";

algorithm
  log_r_Eu:= log10(
               IBPSA.Utilities.Math.Functions.smoothMax(
                 x1=dp * peak.V_flow^2,
                 x2=V_flow_dp_small,
                 deltaX=V_flow_dp_small/2)
              /IBPSA.Utilities.Math.Functions.smoothMax(
                 x1=peak.dp * V_flow^2,
                 x2=V_flow_dp_small,
                 deltaX=V_flow_dp_small/2));
  eta:= peak.eta*
          IBPSA.Fluid.Movers.BaseClasses.Euler.correlation(x=log_r_Eu)

          ;
end efficiency;

