within IBPSA.Media.Refrigerants.R410A;
function enthalpySatVap_T
  "Function that calculates the specific enthalpy of saturated R410A vapor based on temperature"
  input Modelica.Units.SI.Temperature T "Temperature of refrigerant";
  output Modelica.Units.SI.SpecificEnthalpy h
    "Specific enthalpy of saturated liquid refrigerant";

protected
  final constant Real a[:] = {406.0598, -34.78156, 262.8079, 223.8549, -1162.627, 570.6635}
    "Coefficients for polynomial equation";

  Real x
    "Independent variable";

algorithm
  // Independent variable
  x := IBPSA.Utilities.Math.Functions.smoothMax(1-T/TCri, 1e-4, 5e-3)^(1/3);
  // Pressure of saturated liquid refrigerant
  h := 1000*IBPSA.Utilities.Math.Functions.polynomial(a = a, x = x)

;
end enthalpySatVap_T;

within IBPSA.Fluid.HeatPumps.ModularReversible.RefrigerantCycle.Frosting.Functions;
function wetterAfjei1997
  "Correction of COP for icing and defrost according to Wetter, Afjei and Glass"
  extends
    IBPSA.Fluid.HeatPumps.ModularReversible.RefrigerantCycle.Frosting.Functions.partialIcingFactor;
protected
  parameter Real offLin=0.03 "First factor for linear term, offset";
  parameter Real sloLin=-0.004 "Second factor for linear term, slope";
  parameter Real gauFac=0.1534 "Parameter for gaussian curve, factor";
  parameter Real gauMea=0.8869 "Parameter for gaussian curve, mean";
  parameter Real gauSig=26.06 "Parameter for gaussian curve, sigma";
  Real fac "Probability of icing";
  Real linTer "Linear part of equation";
  Real gauTer "Gaussian part of equation";
algorithm
  linTer :=offLin + sloLin*TEvaInMea;
  gauTer :=gauFac*Modelica.Math.exp(-(TEvaInMea - gauMea)*(TEvaInMea - gauMea)/
    gauSig);
  fac := gauTer + IBPSA.Utilities.Math.Functions.smoothMax(
    x1=1E-5,
    x2= linTer,
    deltaX=0.25E-5);
  iceFac:=1 - fac;
  );
end wetterAfjei1997;

