within IBPSA.Fluid.Geothermal.Borefields.BaseClasses.HeatTransfer.ThermalResponseFactors;
function finiteLineSource_Integrand_Equivalent
  "Integrand function for finite line source evaluation"
  extends Modelica.Icons.Function;

  input Real u(unit="1/m") "Integration variable";
  input Modelica.Units.SI.Distance dis[n_dis] "Radial distance between borehole axes";
  input Integer wDis[n_dis];
  input Modelica.Units.SI.Height len1 "Length of emitting boreholes";
  input Modelica.Units.SI.Height burDep1 "Buried depth of emitting boreholes";
  input Modelica.Units.SI.Height len2 "Length of receiving boreholes";
  input Modelica.Units.SI.Height burDep2 "Buried depth of receiving boreholes";
  input Integer nBor2 "Number of receiving boreholes over which the response is averaged";
  input Integer n_dis "Number of unique distances between emitting and receiving boreholes";
  input Boolean includeRealSource = true "true if contribution of real source is included";
  input Boolean includeMirrorSource = true "true if contribution of mirror source is included";

  output Real y(unit="m") "Value of integrand";

protected
  Real f "Intermediate variable";
algorithm
  if includeRealSource then
    f := sum({
      +IBPSA.Fluid.Geothermal.Borefields.BaseClasses.HeatTransfer.ThermalResponseFactors.finiteLineSource_Erfint(
       (burDep2 - burDep1 + len2)*u),
      -IBPSA.Fluid.Geothermal.Borefields.BaseClasses.HeatTransfer.ThermalResponseFactors.finiteLineSource_Erfint(
       (burDep2 - burDep1)*u),
      +IBPSA.Fluid.Geothermal.Borefields.BaseClasses.HeatTransfer.ThermalResponseFactors.finiteLineSource_Erfint(
       (burDep2 - burDep1 - len1)*u),
      -IBPSA.Fluid.Geothermal.Borefields.BaseClasses.HeatTransfer.ThermalResponseFactors.finiteLineSource_Erfint(
       (burDep2 - burDep1 + len2 - len1)*u)});
  else
    f := 0;
  end if;
  if includeMirrorSource then
    f := f + sum({
      +IBPSA.Fluid.Geothermal.Borefields.BaseClasses.HeatTransfer.ThermalResponseFactors.finiteLineSource_Erfint(
      (burDep2 + burDep1 + len2)*u),
      -IBPSA.Fluid.Geothermal.Borefields.BaseClasses.HeatTransfer.ThermalResponseFactors.finiteLineSource_Erfint(
      (burDep2 + burDep1)*u),
      +IBPSA.Fluid.Geothermal.Borefields.BaseClasses.HeatTransfer.ThermalResponseFactors.finiteLineSource_Erfint(
      (burDep2 + burDep1 + len1)*u),
      -IBPSA.Fluid.Geothermal.Borefields.BaseClasses.HeatTransfer.ThermalResponseFactors.finiteLineSource_Erfint(
      (burDep2 + burDep1 + len2 + len1)*u)});
  end if;

  y := 0.5/(nBor2*len2*u^2)*f* (wDis*exp(-dis.*dis*u^2))

;
end finiteLineSource_Integrand_Equivalent;

within IBPSA.Fluid.Geothermal.Borefields.BaseClasses.HeatTransfer.LoadAggregation;
impure function temperatureResponseMatrix
  "Reads and possibly writes a matrix with a time series of the borefield's temperature response"
  extends Modelica.Icons.Function;

  input Integer nBor "Number of boreholes";
  input Real cooBor[nBor, 2] "Borehole coordinates";
  input Modelica.Units.SI.Height hBor "Borehole length";
  input Modelica.Units.SI.Height dBor "Borehole buried depth";
  input Modelica.Units.SI.Radius rBor "Borehole radius";
  input Modelica.Units.SI.ThermalDiffusivity aSoi "Thermal diffusivity of soil";
  input Modelica.Units.SI.ThermalConductivity kSoi
    "Thermal conductivity of soil";
  input Integer nSeg "Number of line source segments per borehole";
  input Integer nClu "Number of clusters for g-function calculation";
  input Integer nTimSho "Number of time steps in short time region";
  input Integer nTimLon "Number of time steps in long time region";
  input Integer nTimTot "Number of g-function points";
  input Real ttsMax "Maximum non-dimensional time for g-function calculation";
  input String sha "SHA-1 encryption of the g-function arguments";
  input Boolean forceGFunCalc
    "Set to true to force the thermal response to be calculated at the start";

  output Modelica.Units.SI.ThermalResistance TStep[nTimTot,2]
    "Temperature step-response time series";

protected
  String pathSave "Path of the folder used to save the g-function";
  Modelica.Units.SI.Time[nTimTot] tGFun "g-function evaluation times";
  Real[nTimTot] gFun "g-function vector";
  Boolean writegFun = false "True if g-function was succesfully written to file";
  Integer labels[nBor](each fixed=false) "Cluster label associated with each data point";
  Integer cluSiz[nClu](each fixed=false) "Size of the clusters";
  Integer nCluUni "Number of unique borehole clusters";

algorithm
  pathSave := "tmp/temperatureResponseMatrix/" + sha + "TStep.mat";

  if forceGFunCalc or not Modelica.Utilities.Files.exist(pathSave) then
    (labels, cluSiz, nCluUni) :=
      IBPSA.Fluid.Geothermal.Borefields.BaseClasses.HeatTransfer.ThermalResponseFactors.clusterBoreholes(
      nBor=nBor,
      cooBor=cooBor,
      hBor=hBor,
      dBor=dBor,
      rBor=rBor,
      nClu=nClu);
    (tGFun,gFun) :=
      IBPSA.Fluid.Geothermal.Borefields.BaseClasses.HeatTransfer.ThermalResponseFactors.gFunction(
      nBor=nBor,
      cooBor=cooBor,
      hBor=hBor,
      dBor=dBor,
      rBor=rBor,
      aSoi=aSoi,
      nSeg=nSeg,
      nClu=nCluUni,
      nTimSho=nTimSho,
      nTimLon=nTimLon,
      ttsMax=ttsMax,
      labels = labels,
      cluSiz = cluSiz[1:nCluUni]);

    for i in 1:nTimTot loop
      TStep[i,1] := tGFun[i];
      TStep[i,2] := gFun[i]/(2*Modelica.Constants.pi*hBor*nBor*kSoi);
    end for;

    //creation of a temporary folder in the simulation folder
    Modelica.Utilities.Files.createDirectory("tmp");
    Modelica.Utilities.Files.createDirectory("tmp/temperatureResponseMatrix");

    writegFun := Modelica.Utilities.Streams.writeRealMatrix(
      fileName=pathSave,
      matrixName="TStep",
      matrix=TStep,
      append=false);
  end if;

  TStep := Modelica.Utilities.Streams.readRealMatrix(
    fileName=pathSave,
    matrixName="TStep",
    nrow=nTimTot,
    ncol=2)

  ;
end temperatureResponseMatrix;

