  IBPSA.Electrical.Transmission.LowVoltageCables.Cu95 cu95;
  IBPSA.Electrical.Transmission.LowVoltageCables.Cu100 cu100;
algorithm

  assert(Transmission.Functions.selectVoltageLevel(V_nominal) == IBPSA.Electrical.Types.VoltageLevel.Low,
  "In function IBPSA.Electrical.Transmission.Functions.selectCable_low,
  cable autosizing has a nominal Voltage " + String(V_nominal) + " [V].
  The low voltage cables do not support such a voltage level.",
  level=AssertionLevel.error);

  // Check if it's possible to compute the current
  if V_nominal > 0 then
    I_nominal :=safety_factor*P_nominal/V_nominal;
  else
    I_nominal :=0;
  end if;

  // Assumed the material is Copper
  if I_nominal < cu10.Amp then
        cable := cu10;
  elseif I_nominal >= cu10.Amp and I_nominal < cu20.Amp then
        cable := cu20;
  elseif I_nominal >= cu20.Amp and I_nominal < cu25.Amp then
        cable := cu25;
  elseif I_nominal >= cu25.Amp and I_nominal < cu35.Amp then
        cable := cu35;
  elseif I_nominal >= cu35.Amp and I_nominal < cu50.Amp then
        cable := cu50;
  elseif I_nominal >= cu50.Amp and I_nominal < cu95.Amp then
        cable := cu95;
  elseif I_nominal >= cu95.Amp and I_nominal < cu100.Amp then
        cable := cu100;
  else
    assert(I_nominal < cu100.Amp,
"In function IBPSA.Electrical.Transmission.Functions.selectCable_low,
  cable autosizing does not support a current of " + String(I_nominal) + " [A].
  The selected cable will be undersized.",
  level=AssertionLevel.warning);
        cable := cu100;
  end if
;
end selectCable_low;

within IBPSA.Utilities.Math.Functions.Examples;
model InverseXDerivative_2_Check
  "Model that checks the correct implementation of the 2nd order derivative of InverseXRegularized"
  extends Modelica.Icons.Example;
  IBPSA.Utilities.Diagnostics.CheckEquality cheEqu1(
    threShold=1e-3)
    "Block for checking integration error";
  IBPSA.Utilities.Diagnostics.CheckEquality cheEqu2(
    threShold=1e-3)
    "Block for checking integration error";
  constant Real gain = 4 "Gain for computing the mass flow rate";

  parameter Real delta = 0.7 "Smoothing coefficient";

  Real x "Independent variable";
  Real y_comp "Comparison value";
  Real y "Dependent variable";
  Real der_y_comp "1st order derivative of comparison value";
  Real der_y "1st order derivative of dependent variable";

  Real err "Integration error";
  Real der_err "Integration error";
initial equation
 y = y_comp;
 der_y = der_y_comp;
equation
  x = time^3*gain;
  y = IBPSA.Utilities.Math.Functions.inverseXRegularized(
    x = x,
    delta = delta);

  der_y = der(y);
  der_y_comp = der(y_comp);
  der(der_y) = der(der_y_comp);
  cheEqu1.u1 = y;
  cheEqu1.u2 = y_comp;
  err = cheEqu1.y;
  cheEqu2.u1 = der_y;
  cheEqu2.u2 = der_y_comp;
  der_err = cheEqu2.y;

  assert(abs(err) < 1E-3, "Error in implementation.");
  assert(abs(der_err) < 1E-3, "Error in implementation.")
;
end InverseXDerivative_2_Check;

