model InverseXRegularized
  "Test problem for function that replaces 1/x around the origin by a twice continuously differentiable function"
  extends Modelica.Icons.Example;
  Real x "Independent variable";
  parameter Real delta = 0.5 "Small value for approximation";
  final parameter Real deltaInv = 1/delta "Inverse value of delta";

  final parameter Real a = -15*deltaInv "Polynomial coefficient";
  final parameter Real b = 119*deltaInv^2 "Polynomial coefficient";
  final parameter Real c = -361*deltaInv^3 "Polynomial coefficient";
  final parameter Real d = 534*deltaInv^4 "Polynomial coefficient";
  final parameter Real e = -380*deltaInv^5 "Polynomial coefficient";
  final parameter Real f = 104*deltaInv^6 "Polynomial coefficient";

  Real y "Function value";
  Real xInv "Function value";
  Real dy_dt "First derivative of y with respect to t";
  Real d2y_dt2 "Second derivative of y with respect to t";
equation
  x=2*time-1;
  xInv = if ( abs(x) > 0.1)   then 1 / x else 0;
  y = IBPSA.Utilities.Math.Functions.inverseXRegularized(
       x=x,
       delta=delta, deltaInv=deltaInv,
       a=a, b=b, c=c, d=d, e=e, f=f);
  dy_dt=der(y);
  d2y_dt2=der(dy_dt)
  ;
end InverseXRegularized;

within IBPSA.Electrical.DC.Lines;
model TwoPortRCLine "Model of a two port DC resistance and capacity (T-model)"
  extends IBPSA.Electrical.Transmission.BaseClasses.PartialTwoPortRLC(
    redeclare package PhaseSystem_p = PhaseSystems.TwoConductor,
    redeclare package PhaseSystem_n = PhaseSystems.TwoConductor,
    redeclare Interfaces.Terminal_n terminal_n,
    redeclare Interfaces.Terminal_p terminal_p,
    final L=0);
  parameter Boolean use_C = false
    "Set to true to add a capacitance in the center of the line"
    ;
  parameter Modelica.Units.SI.Voltage Vc_start=V_nominal
    "Initial value of the voltage of the capacitance in the middle of the line";
  Modelica.Units.SI.Voltage Vc(start=Vc_start, stateSelect=StateSelect.prefer)
    "Voltage of the capacitor";
initial equation
  if C>0 and use_C then
    Vc = Vc_start;
  end if;
equation
  terminal_p.v[1] - (Vc+terminal_p.v[2]) = terminal_p.i[1]*R_actual/2;
  terminal_n.v[1] - (Vc+terminal_p.v[2]) = terminal_n.i[1]*R_actual/2;

  if C>0 and use_C then
    C*der(Vc) = terminal_p.i[1] + terminal_n.i[1];
  else
    Vc = 0.5*(terminal_p.v[1] - terminal_p.v[2] + terminal_n.v[1] - terminal_n.v[2]);
  end if;

  terminal_p.v[2] = terminal_n.v[2];
  terminal_p.i[2] + terminal_n.i[2] = 0;

  // Joule losses
  LossPower = R_actual/2*terminal_p.i[1]^2 + R_actual/2*terminal_n.i[1]^2

  ;
end TwoPortRCLine;

