within IBPSA.Fluid.Movers.BaseClasses.Characteristics;
function power "Flow vs. electrical power characteristics for fan or pump"
  extends Modelica.Icons.Function;
  input IBPSA.Fluid.Movers.BaseClasses.Characteristics.powerParameters per
    "Pressure performance data";
  input Modelica.Units.SI.VolumeFlowRate V_flow "Volumetric flow rate";
  input Real r_N(unit="1") "Relative speed";
  input Real d[:] "Derivatives at support points for spline interpolation";
  input Real delta "Small value for switching implementation around zero speed";
  output Modelica.Units.SI.Power P "Power consumption";

protected
   Integer n=size(per.V_flow, 1) "Dimension of data vector";

  Modelica.Units.SI.VolumeFlowRate rat "Ratio of V_flow/r_N";
   Integer i "Integer to select data interval";

algorithm
  if n == 1 then
    P := r_N^3*per.P[1];
  else
    i :=1;
    // The use of the max function to avoids problems for low speeds
    // and turned off pumps
    rat:=V_flow/
            IBPSA.Utilities.Math.Functions.smoothMax(
              x1=r_N,
              x2=0.1,
              deltaX=delta);
    for j in 1:n-1 loop
       if rat > per.V_flow[j] then
         i := j;
       end if;
    end for;
    // Extrapolate or interpolate the data
    P:=r_N^3*IBPSA.Utilities.Math.Functions.cubicHermiteLinearExtrapolation(
                x=rat,
                x1=per.V_flow[i],
                x2=per.V_flow[i + 1],
                y1=per.P[i],
                y2=per.P[i + 1],
                y1d=d[i],
                y2d=d[i+1]);
  end if
  ;
end power;

within IBPSA.Media.Refrigerants.R410A;
function pressureVap_Tv
"Function that calculates the pressure R410A vapor based on temperature and specific volume"
  input Modelica.Units.SI.Temperature T "Temperature of refrigerant";
  input Modelica.Units.SI.SpecificVolume v "Specific volume of refrigerant";
  output Modelica.Units.SI.AbsolutePressure p "Pressure of refrigerant vapor";

protected
  Modelica.Units.SI.SpecificVolume v_abs "Smoothed specific volume";

algorithm
  v_abs := IBPSA.Utilities.Math.Functions.smoothMax(v, 1.01*b, 0.01*b);

  p := R*T/(v_abs-b);
  for i in 1:size(A, 1) loop
    p := p + (A[i] + B[i]*T + C[i]*Modelica.Math.exp(-k*T/TCri))/(v_abs - b)^(i+1);
  end for

;
end pressureVap_Tv;

