within IBPSA.Fluid.BaseClasses;
block IndexMassFraction
  "Computes the index of a substance in the mass fraction vector Xi"
  replaceable package Medium =
      Modelica.Media.Interfaces.PartialCondensingGases "Medium model"
      ;
  parameter String substanceName="" "Name of species substance";

protected
  parameter Integer i_x = sum(
    if Modelica.Utilities.Strings.isEqual(string1=Medium.substanceNames[i],
                                          string2=substanceName,
                                          caseSensitive=false) then i else 0
                                          for i in 1:Medium.nXi) "Index of substance"
                                          ;
initial equation
  assert(i_x > 0, "Substance '" + substanceName + "' is not present in medium '"
                  + Medium.mediumName + "'.\n"
                  + "Change medium model to one that has '" + substanceName + "' as a substance.")

  ;
end IndexMassFraction;

within IBPSA.Fluid.HeatPumps.ModularReversible.Controls.Safety.BaseClasses;
partial model PartialOperationalEnvelope
  "Indicates if the device operation is within a defined envelope"
  extends BaseClasses.PartialSafetyWithCounter;
  parameter Modelica.Units.SI.Temperature tabUppHea[:,2]
    "Upper boundary for heating with second column as useful temperature side";
  parameter Modelica.Units.SI.Temperature tabLowCoo[:,2]
    "Lower boundary for cooling with second column as useful temperature side";
  parameter Boolean use_TConOutHea=true
    "=true to use condenser outlet temperature for envelope in heating mode, false for inlet"
    ;
  parameter Boolean use_TEvaOutHea=false
    "=true to use evaporator outlet temperature for envelope in heating mode, false for inlet"
    ;
  parameter Boolean use_TConOutCoo=false
    "=true to use useful side outlet temperature for envelope in cooling mode, false for inlet"
    ;
  parameter Boolean use_TEvaOutCoo=true
    "=true to use evaporator outlet temperature for envelope in cooling mode, false for inlet"
    ;

  parameter Modelica.Units.SI.TemperatureDifference dTHys=5
    "Temperature deadband in the operational envelope";

  IBPSA.Fluid.HeatPumps.ModularReversible.Controls.Safety.BaseClasses.BoundaryMap bouMapHea(
    final tab=tabUppHea,
    final dT=dTHys,
    final isUppBou=true) "Operational boundary map for heating operation"
    ;

  IBPSA.Fluid.HeatPumps.ModularReversible.Controls.Safety.BaseClasses.BoundaryMap bouMapCoo(
    final tab=tabLowCoo,
    final dT=dTHys,
    final isUppBou=false) "Operational boundary map for cooling operation"
    ;
  Modelica.Blocks.Logical.LogicalSwitch swiHeaCoo
    "Switch between heating and cooling envelope"
    ;
equation
  connect(ySet,swiErr.u1)  ;
  connect(swiHeaCoo.y, booPasThr.u)
    ;
  connect(bouMapCoo.noErr, swiHeaCoo.u3)
    ;
  connect(bouMapHea.noErr, swiHeaCoo.u1)


  ;
end PartialOperationalEnvelope;

within IBPSA.Fluid.HeatPumps.ModularReversible.RefrigerantCycle.BaseClasses;
partial model PartialCarnot
  "Model with components for Carnot efficiency calculation"
  parameter Boolean useForChi "=false to use in heat pump models";
  parameter Real etaCarnot_nominal=0.3 "Constant Carnot effectiveness";
  parameter Boolean use_constAppTem=false
    "=true to fix approach temperatures at nominal values. This can improve simulation speed";
  parameter Modelica.Units.SI.TemperatureDifference TAppCon_nominal(min=0)
    "Temperature difference between refrigerant and working fluid outlet in condenser"
    ;

  parameter Modelica.Units.SI.TemperatureDifference TAppEva_nominal(min=0)
    "Temperature difference between refrigerant and working fluid outlet in evaporator"
    ;
  parameter Modelica.Units.SI.TemperatureDifference dTCarMin=5
    "Minimal temperature difference, used to avoid division errors"
     ;
  Modelica.Blocks.Sources.RealExpression reaCarnotCOP(final y=TUseSidAct/
        IBPSA.Utilities.Math.Functions.smoothMax(
        x1=dTCarMin,
        x2=(TConAct - TEvaAct),
        deltaX=0.25)) "Internal calculation of Carnot COP"
    ;
  Modelica.Blocks.Math.MultiProduct
                               proQUse_flow(nu=3)
                                            "Calculate QUse_flow" ;
  Modelica.Blocks.Math.Product proPEle "Calculate electrical power consumption" ;
  Modelica.Blocks.Sources.Constant constPEle
    "Constant electrical power consumption" ;
  Modelica.Blocks.Routing.RealPassThrough pasThrYMea "From signal bus"
    ;
  Modelica.Units.SI.Temperature TUseSidAct = if useForChi then TEvaAct else TConAct
    "Useful side refrigerant temperature";
  Modelica.Units.SI.Temperature TConAct = pasThrTCon.y + TAppCon
    "Refrigerant condensation temperature";
  Modelica.Units.SI.Temperature TEvaAct = pasThrTEva.y - TAppEva
    "Refrigerant evaporation temperature";
  Modelica.Units.SI.TemperatureDifference TAppCon = if use_constAppTem then TAppCon_nominal
      else TAppCon_nominal * QCon_flow_internal/QCon_flow_nominal
      "Condenser approach temperature";
  Modelica.Units.SI.TemperatureDifference TAppEva = if use_constAppTem then TAppEva_nominal
      else TAppEva_nominal * QEva_flow_internal/QEva_flow_nominal
      "Evaporator approach temperature ";
  Modelica.Blocks.Sources.Constant constZer(final k=0)
    "Constant zero value if off" ;
  Modelica.Blocks.Logical.Switch swiPEle
    "If device is off, no heat exchange occurs" ;
  Modelica.Blocks.Logical.Switch swiQUse
    "If device is off, no heat exchange occurs" ;

  Modelica.Blocks.Routing.RealPassThrough pasThrTEva
    "Evaporator outlet pass through" ;
  Modelica.Blocks.Routing.RealPassThrough pasThrTCon
    "Condenser outlet pass through" ;
  Modelica.Blocks.Sources.RealExpression reaCarnotEff(y=etaCarnot_nominal)
    "Internal calculation of Carnot effectiveness"
    ;
protected
  parameter Modelica.Units.SI.HeatFlowRate QCon_flow_nominal
    "Nominal condenser heat flow rate";
  parameter Modelica.Units.SI.HeatFlowRate QEva_flow_nominal
    "Nominal evaporator heat flow rate";
  Modelica.Units.SI.HeatFlowRate QCon_flow_internal = if useForChi then
    swiPEle.y - swiQUse.y else swiQUse.y
    "Condenser heat flow rate";
  Modelica.Units.SI.HeatFlowRate QEva_flow_internal = if useForChi then
    swiQUse.y else swiPEle.y - swiQUse.y
     "Evaporator heat flow rate";

equation
  connect(proPEle.u1, constPEle.y) ;
  connect(pasThrYMea.y, proPEle.u2)
    ;
  connect(constZer.y, swiPEle.u3) ;
  connect(proPEle.y, swiPEle.u1) ;
  connect(proQUse_flow.y, swiQUse.u1) ;
  connect(swiQUse.u3, constZer.y) ;
  connect(reaCarnotCOP.y, proQUse_flow.u[1]) ;
  connect(proPEle.y, proQUse_flow.u[2]) ;
  connect(reaCarnotEff.y, proQUse_flow.u[3]) 
  ;
end PartialCarnot;

within IBPSA.Fluid.FixedResistances.Validation.PlugFlowPipes;
model PlugFlowULg "Validation against data from Université de Liège"
  extends Modelica.Icons.Example;
  package Medium = IBPSA.Media.Water;

  parameter Modelica.Units.SI.MassFlowRate m_flow_nominal=1
    "Nominal mass flow rate, used for regularization near zero flow";
  parameter Modelica.Units.SI.Temperature T_start_in=pipeDataULg.T_start_in +
      273.15 "Initial temperature at pipe inlet";
  parameter Modelica.Units.SI.Temperature T_start_out=pipeDataULg.T_start_out
       + 273.15 "Initial temperature at pipe outlet";
  parameter Modelica.Units.SI.SpecificHeatCapacity cp_default=
      Medium.specificHeatCapacityCp(state=sta_default)
    "Heat capacity of medium";
  parameter Medium.ThermodynamicState sta_default=Medium.setState_pTX(
      T=Medium.T_default,
      p=Medium.p_default,
      X=Medium.X_default) "Default medium state";

  Fluid.Sources.MassFlowSource_T WaterCityNetwork(
    redeclare package Medium = Medium,
    m_flow=1.245,
    use_m_flow_in=true,
    nPorts=1) "Mass flow source"
              ;
  Fluid.HeatExchangers.Heater_T Boiler(
    redeclare package Medium = Medium,
    m_flow_nominal=1,
    dp_nominal=0) "Boiler with adjustable outlet temperature"
                  ;
  Fluid.Sources.Boundary_pT Sewer1(
    redeclare package Medium = Medium,
    nPorts=1) "Mass flow sink"
    ;
  Fluid.Sensors.TemperatureTwoPort senTem_out(
    redeclare package Medium = Medium,
    m_flow_nominal=m_flow_nominal,
    tau=0,
    T_start=T_start_out) "Temperature sensor"
    ;
  Fluid.Sensors.TemperatureTwoPort senTem_in(
    redeclare package Medium = Medium,
    m_flow_nominal=m_flow_nominal,
    tau=0,
    T_start=T_start_in) "Temperature sensor"
    ;
  Modelica.Blocks.Sources.CombiTimeTable DataReader(
    tableOnFile=true,
    tableName="dat",
    fileName=pipeDataULg.filNam,
    columns=2:pipeDataULg.nCol,
    extrapolation=Modelica.Blocks.Types.Extrapolation.HoldLastPoint)
    "Measurement data"
    ;

  Modelica.Blocks.Math.UnitConversions.From_degC Tout
    "Ambient temperature in degrees"
    ;
  Modelica.Thermal.HeatTransfer.Sources.FixedTemperature TBou(T=295.15)
    "Fixed boundary condition"
                         ;
  Modelica.Blocks.Math.UnitConversions.From_degC Tin
    "Input temperature into pipe"
    ;

  replaceable Data.PipeDataULg151202 pipeDataULg constrainedby
    Data.BaseClasses.PipeDataULg
    "Measurement dataset from ULg (use Change Class... to choose from different experiments)"
    ;
  Modelica.Blocks.Math.Gain gain(k=1)
    "Gain to test variations of mass flow rate within measurement uncertainty "
    ;
  PlugFlowPipe pipe(
    redeclare package Medium = Medium,
    dh=0.05248,
    length=39,
    dIns(displayUnit="mm") = 0.013,
    kIns=0.04,
    m_flow_nominal=m_flow_nominal,
    thickness=3.9e-3,
    T_start_out=T_start_out,
    T_start_in=T_start_in,
    R=((1/(2*pipe.kIns)*log((0.0603/2 + pipe.dIns)/(0.0603/2))) + 1/(5*(0.0603
         + 2*pipe.dIns)))/Modelica.Constants.pi,
    initDelay=true,
    m_flow_start=pipeDataULg.m_flowIni,
    cPip=500,
    rhoPip=8000) "Pipe"
    ;
  Fluid.Sensors.EnthalpyFlowRate senEntOut(redeclare package Medium = Medium,
      m_flow_nominal=m_flow_nominal) "Outlet enthalpy sensor"
    ;
  Modelica.Blocks.Math.Add heatLossSim(k1=-1)
    "Difference between inflowing and outflowing enthalpy streams"
    ;
  Modelica.Blocks.Continuous.Integrator eneLosInt "Integrate model error"
    ;
  Fluid.Sensors.EnthalpyFlowRate senEntIn(redeclare package Medium = Medium,
      m_flow_nominal=m_flow_nominal) "Inlet enthalpy sensor"
    ;
  Modelica.Blocks.Math.Add delT(k2=-1)
    "Temperature difference between in- and outlet"
    ;
  Modelica.Blocks.Math.Product heaLosMea
    "Heat loss from measurement (mflow*cp*DeltaT)"
    ;
  Modelica.Blocks.Math.Gain gain3(k=cp_default) "Specific heat of water"
    ;
  Modelica.Blocks.Math.Feedback heaLosDiff
    "Difference between simulated and measurement enthalpy flow difference"
    ;
  Modelica.Blocks.Sources.Constant Tamb(k=273 + 18)
    "Ambient temperature in Kelvin";
equation
  connect(DataReader.y[3], Tout.u) ;
  connect(DataReader.y[5], Tin.u)
    ;
  connect(DataReader.y[1], gain.u) ;
  connect(senTem_in.port_a, Boiler.port_b)
    ;
  connect(Boiler.port_a, WaterCityNetwork.ports[1])
    ;
  connect(gain.y, WaterCityNetwork.m_flow_in) ;
  connect(Tin.y, Boiler.TSet) ;
  connect(Sewer1.ports[1], senTem_out.port_b)
    ;
  connect(senTem_out.port_a, senEntOut.port_b)
    ;
  connect(senEntOut.port_a, pipe.port_b)
    ;
  connect(pipe.port_a, senEntIn.port_b)
    ;
  connect(senTem_in.port_b, senEntIn.port_a)
    ;
  connect(TBou.port, pipe.heatPort)
    ;
  connect(gain.y, gain3.u)
    ;
  connect(heaLosMea.y, heaLosDiff.u2)
    ;
  connect(heatLossSim.y, heaLosDiff.u1)
    ;
  connect(heaLosDiff.y, eneLosInt.u)
    ;
  connect(delT.u1, Tin.y) ;
  connect(Tout.y, delT.u2) ;
  connect(heaLosMea.u1, gain3.y) ;
  connect(heaLosMea.u2, delT.y) ;
  connect(heatLossSim.u2, senEntIn.H_flow)
    ;
  connect(heatLossSim.u1, senEntOut.H_flow)

  ;
end PlugFlowULg;

