    minVolFloRatSaf(final mEvaMin_flow=safCtrPar.r_mEvaMinPer_flow*
        mEva_flow_nominal, final mConMin_flow=safCtrPar.r_mConMinPer_flow*
        mCon_flow_nominal) if safCtrPar.use_minFlowCtr
    "Block to ensure minimal flow rates"
    ;

  Modelica.Blocks.Interfaces.IntegerOutput minFlowErr
    if safCtrPar.use_minFlowCtr
    "Number of errors from violating minimum flow rates"
    ;
  Modelica.Blocks.Routing.RealPassThrough reaPasThrOnOff if not (safCtrPar.use_minOnTime
     or safCtrPar.use_minOffTime or safCtrPar.use_maxCycRat)
    "No on off control" ;
  Modelica.Blocks.Routing.RealPassThrough reaPasThrOpeEnv
    if not safCtrPar.use_opeEnv "No operational envelope control"  ;
  Modelica.Blocks.Routing.RealPassThrough reaPasThrAntFre
    if not safCtrPar.use_antFre "No antifreeze control"  ;
  Modelica.Blocks.Routing.RealPassThrough reaPasThrMinVolRat
    if not safCtrPar.use_minFlowCtr  "No minimum flow rate control"
    ;
equation

  connect(sigBus, onOffCtr.sigBus) ;

  connect(sigBus, opeEnv.sigBus) ;

  connect(sigBus, antFre.sigBus) ;

  connect(antFre.err, antFreErr) ;
  connect(opeEnv.err, opeEnvErr) ;
  connect(minVolFloRatSaf.yOut, yOut) ;
  connect(sigBus, minVolFloRatSaf.sigBus) ;

  connect(minVolFloRatSaf.err, minFlowErr) ;
  connect(reaPasThrOnOff.y, reaPasThrOpeEnv.u)
    ;
  connect(reaPasThrOpeEnv.y, reaPasThrAntFre.u)
    ;
  connect(reaPasThrAntFre.y, reaPasThrMinVolRat.u)
    ;
  connect(reaPasThrMinVolRat.y, yOut) ;
  connect(onOffCtr.yOut, opeEnv.ySet) ;
  connect(opeEnv.yOut, antFre.ySet) ;
  connect(antFre.yOut, minVolFloRatSaf.ySet) ;
  connect(antFre.yOut, reaPasThrMinVolRat.u) ;
  connect(reaPasThrAntFre.y, minVolFloRatSaf.ySet) ;
  connect(opeEnv.yOut, reaPasThrAntFre.u) ;
  connect(reaPasThrOpeEnv.y, antFre.ySet) ;
  connect(onOffCtr.yOut, reaPasThrOpeEnv.u) ;
  connect(reaPasThrOnOff.y, opeEnv.ySet) ;

  connect(ySet, onOffCtr.ySet) ;
  connect(ySet, reaPasThrOnOff.u) ;
  );
end Safety;

within IBPSA.Fluid.Sources;
model TraceSubstancesFlowSource
  "Source with mass flow that does not take part in medium mass balance (such as CO2)"

  replaceable package Medium =
    IBPSA.Media.Air(extraPropertiesNames={"CO2"}) "Medium in the component"
      ;

  parameter Integer nPorts=0 "Number of ports" ;

  parameter String substanceName = "CO2" "Name of trace substance";
  parameter Boolean use_m_flow_in = false
    "Get the trace substance mass flow rate from the input connector"
    ;

  parameter Modelica.Units.SI.MassFlowRate m_flow=0
    "Fixed mass flow rate going out of the fluid port"
    ;
  Modelica.Blocks.Interfaces.RealInput m_flow_in(final unit="kg/s")
    if use_m_flow_in "Prescribed mass flow rate for extra property"
    ;

  Modelica.Fluid.Interfaces.FluidPorts_b ports[nPorts](
    redeclare each package Medium = Medium)
    "Connector for fluid ports"
    ;

protected
  parameter Medium.ExtraProperty C_in_internal[Medium.nC](
    final quantity=Medium.extraPropertiesNames)=
     {if (Modelica.Utilities.Strings.isEqual(string1=Medium.extraPropertiesNames[i],
                                             string2=substanceName,
                                             caseSensitive=false)) then 1 else 0
                                             for i in 1:Medium.nC}
     "Boundary trace substances"
     ;
  Modelica.Blocks.Interfaces.RealInput m_flow_in_internal(final unit="kg/s")
    "Needed to connect to conditional connector";

  Modelica.Units.SI.SpecificEnthalpy h_default=Medium.specificEnthalpy(
      Medium.setState_pTX(
      Medium.p_default,
      Medium.T_default,
      Medium.X_default)) "Enthalpy of outstreaming medium";

initial equation
  assert(sum(C_in_internal) > 1E-4, "Trace substance '" + substanceName + "' is not present in medium '"
         + Medium.mediumName + "'.\n"
         + "Check source parameter and medium model.");

  // Only one connection allowed to a port to avoid unwanted ideal mixing
  for i in 1:nPorts loop
    assert(cardinality(ports[i]) <= 1,"
Each ports[i] of boundary shall at most be connected to one component.
If two or more connections are present, ideal mixing takes
place in these connections, which is usually not the intention
of the modeller. Increase nPorts to add an additional port.
");
  end for;

equation
  sum(ports.m_flow) = -m_flow_in_internal;

  connect(m_flow_in, m_flow_in_internal);
  if not use_m_flow_in then
    m_flow_in_internal = m_flow;
  end if;

  assert(m_flow_in_internal >= 0, "Reverse flow for species source is not yet implemented.");

  for i in 2:nPorts loop
    ports[1].p = ports[i].p;
  end for;

  ports.C_outflow = fill(C_in_internal, nPorts);
  ports.h_outflow = fill(h_default, nPorts);
  ports.Xi_outflow = fill(Medium.X_default[1:Medium.nXi], nPorts)

  ;
end TraceSubstancesFlowSource;

within IBPSA.Controls.Continuous.Examples;
model LimPIDWithReset
  "Example that demonstrates the controller output reset"
  extends Modelica.Icons.Example;

  Plant plaWitRes "Plant connected to controller with reset" ;
  Controller conWitRes(reset=IBPSA.Types.Reset.Parameter)
    "Controller with reset" ;
  Plant plaNoRes "Plant connected to controller without reset" ;
  Controller conNoRes(reset=IBPSA.Types.Reset.Disabled)
    "Controller without reset" ;
  Modelica.Blocks.Sources.Pulse TSet(
    amplitude=20,
    width=50,
    offset=293.15,
    y(unit="K"),
    period=180)    "Temperature set point"
    ;

protected
  model Plant
    "Plant model"
    extends Modelica.Blocks.Icons.Block;

    Modelica.Blocks.Interfaces.RealInput Q_flow(unit="W")
      "Heat flow rate added to system"
      ;
    Modelica.Blocks.Interfaces.RealOutput T(unit="K")
      "Controlled temperature"
      ;

    Modelica.Thermal.HeatTransfer.Components.HeatCapacitor cap(
      C=10,
      T(fixed=true,
        start=293.15)) "Heat capacitor"
      ;
    Modelica.Thermal.HeatTransfer.Components.HeatCapacitor cap1(
      C=10,
      T(fixed=true,
          start=293.15)) "Heat capacitor"
      ;

    Modelica.Thermal.HeatTransfer.Sensors.TemperatureSensor temSen
      "Temperature sensor"
      ;
    Modelica.Thermal.HeatTransfer.Sources.PrescribedHeatFlow preHea
      "Prescribed heat flow rate"
      ;
    Modelica.Thermal.HeatTransfer.Components.ThermalConductor theCon(G=5)
      "Thermal conductor"
      ;
    Modelica.Thermal.HeatTransfer.Sources.FixedTemperature TBou(T=293.15)
      "Boundary condition"
      ;
    Modelica.Thermal.HeatTransfer.Components.ThermalConductor theCon1(G=1)
      "Thermal conductor"
      ;

  equation
    connect(Q_flow, preHea.Q_flow)
      ;
    connect(T, temSen.T)
      ;
    connect(TBou.port, theCon.port_a)
      ;
    connect(cap.port, theCon1.port_a)
      ;
    connect(theCon1.port_b, cap1.port)
      ;
    connect(cap1.port, temSen.port)
      ;
    connect(theCon.port_b, cap.port)
      ;
    connect(preHea.port, cap.port)

    ;
  end Plant;

  model Controller "PID controller with optional output reset"
    extends Modelica.Blocks.Icons.Block;

    parameter IBPSA.Types.Reset reset=IBPSA.Types.Reset.Disabled
      "Type of controller output reset";

    Modelica.Blocks.Interfaces.RealInput TSet(unit="K") "Temperature set point"
      ;

    Modelica.Blocks.Interfaces.RealInput u_m(unit="K")
      "Measured temperature"
      ;

    Modelica.Blocks.Interfaces.RealOutput y
      "Control signal"
      ;

    IBPSA.Controls.Continuous.LimPID conPID(
      final reset=reset,
      yMax=1,
      yMin=0,
      Ti=1,
      k=10) "PI controller"
      ;
    Modelica.Blocks.Math.Gain gain(k=5000)
                                          "Gain for heat flow rate"
      ;
    Modelica.Blocks.Logical.GreaterThreshold trigger(threshold=303.15)
      "Trigger input for controller reset"
      ;

  equation
    connect(conPID.y,gain. u)
      ;
    connect(trigger.y,conPID. trigger) ;
    connect(u_m, conPID.u_m) ;
    connect(conPID.u_s, TSet) ;
    connect(trigger.u, TSet) ;
    connect(gain.y, y)

    ;
  end Controller;

equation
  connect(plaWitRes.T, conWitRes.u_m) ;
  connect(conWitRes.y, plaWitRes.Q_flow)
    ;

  connect(plaNoRes.T, conNoRes.u_m) ;
  connect(conNoRes.y, plaNoRes.Q_flow)
    ;
  connect(TSet.y, conWitRes.TSet) ;
  connect(TSet.y, conNoRes.TSet) 
 ;
end LimPIDWithReset;

