within IBPSA.Airflow.Multizone.BaseClasses;
partial model DoorDiscretized
  "Door model using discretization along height coordinate"
  extends IBPSA.Airflow.Multizone.BaseClasses.TwoWayFlowElementBuoyancy;

  parameter Integer nCom=10 "Number of compartments for the discretization";

  parameter Modelica.Units.SI.PressureDifference dp_turbulent(
    min=0,
    displayUnit="Pa") = 0.01
    "Pressure difference where laminar and turbulent flow relation coincide. Recommended: 0.01";

  Modelica.Units.SI.PressureDifference dpAB[nCom](each nominal=1)
    "Pressure difference between compartments";
  Modelica.Units.SI.Velocity v[nCom](each nominal=0.01)
    "Velocity in compartment from A to B";
  Modelica.Units.SI.Velocity vTop "Velocity at top of opening from A to B";
  Modelica.Units.SI.Velocity vBot "Velocity at bottom of opening from A to B";

protected
  parameter Modelica.Units.SI.Length dh=hOpe/nCom "Height of each compartment";

  parameter Medium.ThermodynamicState sta_default=Medium.setState_pTX(
      T=Medium.T_default,
      p=Medium.p_default,
      X=Medium.X_default);

  parameter Modelica.Units.SI.Density rho_default=Medium.density(sta_default)
    "Density, used to compute fluid volume";

  parameter Real hAg[nCom](each unit="m2/s2")=
    {Modelica.Constants.g_n*(hA - (i - 0.5)*dh) for i in 1:nCom}
    "Product g*h_i for each compartment";

  parameter Real hBg[nCom](each unit="m2/s2")=
    {Modelica.Constants.g_n*(hB - (i - 0.5)*dh) for i in 1:nCom}
    "Product g*h_i for each compartment";
  Modelica.Units.SI.AbsolutePressure pA[nCom](each nominal=101325)
    "Pressure in compartments of room A";
  Modelica.Units.SI.AbsolutePressure pB[nCom](each nominal=101325)
    "Pressure in compartments of room B";

  Modelica.Units.SI.VolumeFlowRate dV_flow[nCom]
    "Volume flow rate through compartment from A to B";
  Modelica.Units.SI.VolumeFlowRate dVAB_flow[nCom]
    "Volume flow rate through compartment from A to B if positive";
  Modelica.Units.SI.VolumeFlowRate dVBA_flow[nCom]
    "Volume flow rate through compartment from B to A if positive";
  Modelica.Units.SI.VolumeFlowRate VZerCom_flow=VZer_flow/nCom
    "Small flow rate for regularization";

  Real m(min=0.5, max=1) "Flow exponent, m=0.5 for turbulent, m=1 for laminar";
  Real CVal "Flow coefficient for each compartment, C = V_flow/ dp^m";
  Modelica.Units.SI.Area dA "Compartment area";
  Real gaiFlo[nCom] "Gain to sum up the positive flows and set the negative to zero in a differentiable way";
equation
  dA = A/nCom;

  for i in 1:nCom loop
    // pressure drop in each compartment
    pA[i] = port_a1.p + rho_a1_inflow*hAg[i];
    pB[i] = port_a2.p + rho_a2_inflow*hBg[i];
    dpAB[i] = pA[i] - pB[i];
    v[i] = dV_flow[i]/dA;
    // assignment of net volume flows
    gaiFlo[i] = IBPSA.Utilities.Math.Functions.smoothHeaviside(x=dV_flow[i], delta=VZerCom_flow);
    dVAB_flow[i] =  dV_flow[i] * gaiFlo[i];
    dVBA_flow[i] = -dV_flow[i] * (1-gaiFlo[i]);
  end for;
  // add positive and negative flows
  VAB_flow = sum(dVAB_flow);
  VBA_flow = sum(dVBA_flow);
  vTop = v[nCom];
  vBot = v[1]
  ;
end DoorDiscretized;

within IBPSA.Electrical.AC.OnePhase.Conversion;
model ACACTransformer "AC AC transformer simplified equivalent circuit"
  extends IBPSA.Electrical.Icons.RefAngleConversion;
  extends IBPSA.Electrical.Interfaces.PartialConversion(
    redeclare package PhaseSystem_p = PhaseSystems.OnePhase,
    redeclare package PhaseSystem_n = PhaseSystems.OnePhase,
    redeclare replaceable Interfaces.Terminal_n terminal_n
      constrainedby Interfaces.Terminal_n(
      i(start = zeros(PhaseSystem_n.n),
      each stateSelect = StateSelect.prefer)),
    redeclare replaceable Interfaces.Terminal_p terminal_p
      constrainedby Interfaces.Terminal_p(
      i(start = zeros(PhaseSystem_p.n),
      each stateSelect = StateSelect.prefer)));
  parameter Modelica.Units.SI.Voltage VHigh
    "Rms voltage on side 1 of the transformer (primary side)";
  parameter Modelica.Units.SI.Voltage VLow
    "Rms voltage on side 2 of the transformer (secondary side)";
  parameter Modelica.Units.SI.ApparentPower VABase
    "Nominal power of the transformer";
  parameter Real XoverR
    "Ratio between the complex and real components of the impedance (XL/R)";
  parameter Real Zperc "Short circuit impedance";
  parameter Boolean ground_1 = false
    "If true, connect side 1 of converter to ground"
    ;
  parameter Boolean ground_2 = true
    "If true, connect side 2 of converter to ground"
    ;
  parameter Modelica.Units.SI.Angle phi_1=0
    "Angle of the voltage side 1 at initialization"
    ;
  parameter Modelica.Units.SI.Angle phi_2=phi_1
    "Angle of the voltage side 2 at initialization"
    ;
  Modelica.Units.SI.Efficiency eta "Efficiency";
  Modelica.Units.SI.Power PLoss[2] "Loss power";

  Modelica.Units.SI.Voltage V1[2](start=PhaseSystem_n.phaseVoltages(VHigh,
        phi_1)) "Voltage at the winding - primary side";
  Modelica.Units.SI.Voltage V2[2](start=PhaseSystem_p.phaseVoltages(VLow, phi_2))
    "Voltage at the winding - secondary side";
protected
  Real N = VHigh/VLow "Winding ratio";
  Modelica.Units.SI.Current IHigh=VABase/VHigh
    "Nominal current on primary side";
  Modelica.Units.SI.Current ILow=VABase/VLow
    "Nominal current on secondary side";
  Modelica.Units.SI.Current IscHigh=IHigh/Zperc
    "Short circuit current on primary side";
  Modelica.Units.SI.Current IscLow=ILow/Zperc
    "Short circuit current on secondary side";
  Modelica.Units.SI.Impedance Zp=VHigh/IscHigh
    "Impedance of the primary side (module)";
  Modelica.Units.SI.Impedance Z1[2]={Zp*cos(atan(XoverR)),Zp*sin(atan(XoverR))}
    "Impedance of the primary side of the transformer";
  Modelica.Units.SI.Impedance Zs=VLow/IscLow
    "Impedance of the secondary side (module)";
  Modelica.Units.SI.Impedance Z2[2]={Zs*cos(atan(XoverR)),Zs*sin(atan(XoverR))}
    "Impedance of the secondary side of the transformer";
  Modelica.Units.SI.Power P_p[2]=PhaseSystem_p.phasePowers_vi(terminal_p.v,
      terminal_p.i) "Power transmitted at pin p (secondary)";
  Modelica.Units.SI.Power P_n[2]=PhaseSystem_n.phasePowers_vi(terminal_n.v,
      terminal_n.i) "Power transmitted at pin n (primary)";
  Modelica.Units.SI.Power S_p=Modelica.Fluid.Utilities.regRoot(P_p[1]^2 + P_p[2]
      ^2, delta=0.1) "Apparent power at terminal p";
  Modelica.Units.SI.Power S_n=Modelica.Fluid.Utilities.regRoot(P_n[1]^2 + P_n[2]
      ^2, delta=0.1) "Apparent power at terminal n";

equation
  // Efficiency
  eta = IBPSA.Utilities.Math.Functions.smoothMin(
        x1=
        Modelica.Fluid.Utilities.regRoot(P_p[1]^2 + P_p[2]^2, delta=0.01)/
        Modelica.Fluid.Utilities.regRoot(P_n[1]^2 + P_n[2]^2 + 1e-6, delta=0.01),
        x2=
        Modelica.Fluid.Utilities.regRoot(P_n[1]^2 + P_n[2]^2, delta=0.01)/
        Modelica.Fluid.Utilities.regRoot(P_p[1]^2 + P_p[2]^2 + 1e-6, delta=0.01),
        deltaX = 0.01);

  // Ideal transformation
  V2 = V1/N;
  terminal_p.i[1] + terminal_n.i[1]*N = 0;
  terminal_p.i[2] + terminal_n.i[2]*N = 0;

  // Losses due to the impedance
  terminal_n.v = V1 + IBPSA.Electrical.PhaseSystems.OnePhase.product(
    terminal_n.i, Z1);
  V2 = terminal_p.v;

  // Loss of power
  PLoss = P_p + P_n;

  // The two sides have the same reference angle
  terminal_p.theta = terminal_n.theta;

  if ground_1 then
    Connections.potentialRoot(terminal_n.theta);
  end if;
  if ground_2 then
    Connections.root(terminal_p.theta);
  end if

  ;
end ACACTransformer;

within IBPSA.Fluid.Sensors;
model Velocity "Ideal sensor for flow velocity"
  extends IBPSA.Fluid.Sensors.BaseClasses.PartialDynamicFlowSensor;
  extends Modelica.Icons.RoundSensor;
  parameter Medium.Density
    d_start=Medium.density(Medium.setState_pTX(p_start, T_start, X_start))
    "Initial or guess value of density"
    ;
  parameter Modelica.Units.SI.Temperature T_start=Medium.T_default
    "Temperature used to compute d_start"
    ;
  parameter Modelica.Units.SI.Pressure p_start=Medium.p_default
    "Pressure used to compute d_start"
    ;
  parameter Modelica.Units.SI.MassFraction X_start[Medium.nX]=Medium.X_default
    "Mass fraction used to compute d_start"
    ;

  parameter Modelica.Units.SI.Area A "Cross sectional area of flow channel";
  Modelica.Units.SI.VolumeFlowRate V_flow
    "Volume flow rate from port_a to port_b";
  Modelica.Blocks.Interfaces.RealOutput v(final quantity="Velocity",
                                          final unit="m/s")
    "Flow velocity from port_a to port_b"
    ;
protected
  Medium.Density dMed(start=d_start)
    "Medium temperature to which the sensor is exposed";

  Medium.Density d_a_inflow(start=d_start)
    "Density of inflowing fluid at port_a";
  Medium.Density d_b_inflow(start=d_start)
    "Density of inflowing fluid at port_b, or rho_a_inflow if uni-directional flow";
  Medium.Density d(start=d_start) "Density of the passing fluid";
initial equation
  if dynamic then
    if initType == Modelica.Blocks.Types.Init.SteadyState then
      der(d) = 0;
     elseif initType == Modelica.Blocks.Types.Init.InitialState or
           initType == Modelica.Blocks.Types.Init.InitialOutput then
      d = d_start;
    end if;
  end if;
equation
  if allowFlowReversal then
     d_a_inflow = Medium.density(state=
                    Medium.setState_phX(p=port_b.p, h=port_b.h_outflow, X=port_b.Xi_outflow));
     d_b_inflow = Medium.density(state=
                    Medium.setState_phX(p=port_a.p, h=port_a.h_outflow, X=port_a.Xi_outflow));
     dMed = Modelica.Fluid.Utilities.regStep(
              x=port_a.m_flow,
              y1=d_a_inflow,
              y2=d_b_inflow,
              x_small=m_flow_small);
  else
     dMed = Medium.density(state=Medium.setState_phX(
              p=port_b.p,
              h=port_b.h_outflow,
              X=port_b.Xi_outflow));
     d_a_inflow = dMed;
     d_b_inflow = dMed;
  end if;
  // Output signal of density sensor that is used to compute
  // the volume flow rate
  if dynamic then
    der(d) = (dMed-d)*k*tauInv;
  else
    d = dMed;
  end if;
  // Volume flow rate
  V_flow = port_a.m_flow/d;
  // Flow velocity
  v = V_flow / A
;
end Velocity;

within IBPSA.ThermalZones.ReducedOrder.Validation.VDI6007.BaseClasses;
block VerifyDifferenceThreePeriods "Assert when condition is violated"
  extends IBPSA.Utilities.Diagnostics.BaseClasses.PartialInputCheck(
    message="Inputs differ by more than threShold.\n  Check output 'satisfied' for when violation(s) happened.");
  parameter Modelica.Units.SI.Time endTime=0
    "Start time for deactivating the assert (period one)";
  parameter Modelica.Units.SI.Time startTime2=0
    "Start time for activating the assert (period two)";
  parameter Modelica.Units.SI.Time endTime2=0
    "Start time for deactivating the assert (period two)";
  parameter Modelica.Units.SI.Time startTime3=0
    "Start time for activating the assert (period three)";
  parameter Modelica.Units.SI.Time endTime3=0
    "Start time for deactivating the assert (period three)";
  parameter Modelica.Units.SI.Time tau(min=1) = 60
    "Time constant for filtering signal";

  Modelica.Blocks.Interfaces.BooleanOutput satisfied(start=true, fixed=true)
    ;

  Modelica.Blocks.Interfaces.RealOutput diff "Difference abs(u1-u2) after filtering"
    ;

protected
  parameter Modelica.Units.SI.Time t1(fixed=false)
    "Simulation end time period one";
  parameter Modelica.Units.SI.Time t3(fixed=false)
    "Simulation end time period two";
  parameter Modelica.Units.SI.Time t5(fixed=false)
    "Simulation end time period three";
  parameter Modelica.Units.SI.Time t2(fixed=false)
    "Simulation start time period two";
  parameter Modelica.Units.SI.Time t4(fixed=false)
    "Simulation start time period three";
  Integer nFai "Number of test violations";
  Real diffExa "Exact, non-filtered value of the difference between the inputs";

initial equation
  t1 = time + endTime;
  t2 = time + startTime2;
  t3 = time + endTime2;
  t4 = time + startTime3;
  t5 = time + endTime3;
  nFai = 0;
  diff = if (time >= t0) and (time < t1) or
            (time >= t2) and (time < t3) or
            (time >= t4) and (time < t5)
         then
           abs(u1 - u2)
         else
           0;
equation
  if (time >= t0) and (time < t1) or
     (time >= t2) and (time < t3) or
     (time >= t4) and (time < t5) then
     diffExa = abs(u1 - u2);
  else
    diffExa = 0; // Test is not needed in this time domain
  end if;
  der(diff) = (diffExa-diff)/tau;

  // Output whether test is satisfied, using a small hysteresis that is scaled using threShold
  satisfied = not ( (pre(satisfied) and diff > 1.01*threShold) or (not pre(satisfied) and diff >= 0.99*threShold));

  // Count the number of failures and raise an assertion in the terminal section.
  // This ensures that if the model is in an FMU, no asserts are triggered during
  // the solver iterations.
  when not satisfied then
    nFai = pre(nFai) + 1;
  end when;

  when terminal() then
    assert(nFai == 0, message);
  end when

;
end VerifyDifferenceThreePeriods;

