within IBPSA.Fluid.HeatPumps.ModularReversible.BaseClasses;
model EvaporatorCondenserWithCapacity
  "Evaporaotr or condenser model with added capacity for heat losses to the ambient"
  extends IBPSA.Fluid.Interfaces.TwoPortHeatMassExchanger(
    redeclare final IBPSA.Fluid.MixingVolumes.MixingVolume vol(final V=
          m_flow_nominal*tau/rho_default,
    final prescribedHeatFlowRate=true));

  parameter Boolean isCon "=true for condenser, false for evaporator"
    ;
  parameter Boolean use_cap=true
    "False if capacity and heat losses are neglected"
    ;
  parameter Modelica.Units.SI.HeatCapacity C
    "Capacity of heat exchanger, set to zero to ignore its dry mass"
    ;
  parameter Modelica.Units.SI.Temperature TCap_start=Medium.T_default
    "Initial temperature of heat capacity"
    ;
  Modelica.Units.SI.ThermalConductance GOut
    "Exterior heat transfer coefficient,
    set to zero to ignore external heat loss but keep the dry mass"
      ;
  Modelica.Blocks.Interfaces.RealOutput GInn
    "Interior heat transfer coefficient"
      ;
  Modelica.Thermal.HeatTransfer.Components.Convection conIns if use_cap
    "Convection between the wall and the working fluid" ;
  Modelica.Thermal.HeatTransfer.Components.Convection conOut if use_cap
    "Convection and conduction between the wall and ambient air" ;
  Modelica.Thermal.HeatTransfer.Components.HeatCapacitor heaCap(
    final C=C,
    final T(final fixed=(energyDynamics == Modelica.Fluid.Types.Dynamics.FixedInitial),
        final start=TCap_start),
    final der_T(final fixed=(energyDynamics == Modelica.Fluid.Types.Dynamics.SteadyStateInitial),
        start=0)) if use_cap "Heat Capacity" ;
  Modelica.Blocks.Sources.RealExpression heaLosInt(final y=GInn) if use_cap
    "Nominal heat loss coefficient to the interior" ;
  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a port_out if use_cap
    "Temperature and heat flow to the ambient"
    ;
  Modelica.Blocks.Sources.RealExpression heaLosExt(final y=GOut) if use_cap
    "Nominal heat loss coefficient to the exterior" ;

  Modelica.Thermal.HeatTransfer.Sources.PrescribedHeatFlow preHea(final alpha=0,
      final T_ref=293.15) "Heat flow rate of the condenser" ;
  Modelica.Blocks.Interfaces.RealInput Q_flow
    "Heat flow rate from the refrigerant to the medium"
    ;

  Modelica.Thermal.HeatTransfer.Sensors.TemperatureSensor senT
    "Temperature sensor for the condenser volume" ;
  Modelica.Blocks.Interfaces.RealOutput T(
    final unit="K",
    displayUnit="degC")
    "Temperature of the condenser volume" ;
equation
  connect(conIns.fluid, heaCap.port) ;
  connect(heaCap.port, conOut.solid) ;
  connect(conIns.Gc, heaLosInt.y) ;
  connect(conOut.fluid, port_out)
    ;
  connect(conOut.Gc, heaLosExt.y) ;
  connect(vol.heatPort, conIns.solid) ;
  connect(vol.heatPort, preHea.port) ;
  connect(preHea.Q_flow, Q_flow)
  ;
  connect(senT.port, vol.heatPort) ;
  connect(senT.T, T)

  ;
end EvaporatorCondenserWithCapacity;

within IBPSA.Utilities.Math.Functions;
function besselJ0 "Bessel function of the first kind of order 0, J0"
  extends Modelica.Icons.Function;

  input Real x "Independent variable";
  output Real J0 "Bessel function J0(x)";

protected
  constant Real P[5] = {1.0,
            -0.1098628627e-2,
            0.2734510407e-4,
            -0.2073370639e-5,
            0.2093887211e-6};
  constant Real Q[5] = {-0.1562499995e-1,
            0.1430488765e-3,
            -0.6911147651e-5,
            0.7621095161e-6,
            -0.934945152e-7};
  constant Real R[6] = {57568490574.0,
            -13362590354.0,
            651619640.7,
            -11214424.18,
            77392.33017,
            -184.9052456};
  constant Real S[6] = {57568490411.0,
            1029532985.0,
            9494680.718,
            59272.64853,
            267.8532712,
            1.0};
  Real ax = abs(x);
  Real xx;
  Real y;
  Real z;
  Real coeff1;
  Real coeff2;

algorithm
  if ax < 8.0 then
    y := x^2;
    coeff1 := R[6];
    coeff2 := S[6];
    for i in 1:5 loop
      coeff1 := R[6-i] + y*coeff1;
      coeff2 := S[6-i] + y*coeff2;
    end for;
    J0 := coeff1/coeff2;
  else
    z := 8/ax;
    y := z^2;
    xx := ax - 0.785398164;
    coeff1 := P[5];
    coeff2 := Q[5];
    for i in 1:4 loop
      coeff1 := P[5-i] + y*coeff1;
      coeff2 := Q[5-i] + y*coeff2;
    end for;
    J0 := sqrt(0.636619772/ax)*(cos(xx)*coeff1 - z*sin(xx)*coeff2);
  end if

;
end besselJ0;

