within IBPSA.Electrical.DC.Loads;
model Conductor "Model of a generic DC load"
    extends IBPSA.Electrical.Interfaces.ResistiveLoad(
     redeclare package PhaseSystem = PhaseSystems.TwoConductor,
     redeclare Interfaces.Terminal_n terminal);
protected
  Modelica.Units.SI.Voltage absDV
    "Absolute value of the voltage difference between the two conductors (used by the linearized model)";
equation

  absDV = abs(terminal.v[1]-terminal.v[2]);

  if linearized then

    // Linearized version of the model
    if absDV <= (8/9)*V_nominal then
      terminal.i[1] + P*(2/(0.8*V_nominal) - (terminal.v[1]-terminal.v[2])/(0.8*V_nominal)^2) = 0;
    elseif absDV >= (12/11)*V_nominal then
      terminal.i[1] + P*(2/(1.2*V_nominal) - (terminal.v[1]-terminal.v[2])/(1.2*V_nominal)^2) = 0;
    else
      terminal.i[1] + P*(2/V_nominal - (terminal.v[1]-terminal.v[2])/V_nominal^2) = 0;
    end if;

  else
    // Full nonlinear version of the model
    // PhaseSystem.activePower(terminal.v, terminal.i) + P = 0;
    if initMode == IBPSA.Electrical.Types.InitMode.zero_current then
      i[1] = - homotopy(actual= P/(v[1] - v[2]),  simplified= 0);
    else
      i[1] = - homotopy(actual= P/(v[1] - v[2]),  simplified= P*(2/V_nominal - (v[1]-v[2])/V_nominal^2));
    end if;

  end if;

  // Since the connector is a two conductor, the sum of the currents at the terminal
  // is null
  sum(i) = 0
  ;
end Conductor;

within IBPSA.Fluid.FMI.Conversion.Validation;
model AirToOutletFlowReversal
  "Validation model for air to outlet converter with flow reversal enabled"
  extends IBPSA.Fluid.FMI.Conversion.Validation.AirToOutlet(
    allowFlowReversal = true);
  BoundaryCondition bouAirNoC(
    redeclare package Medium = IBPSA.Media.Air (
      X_default={0.015, 0.985}))
      "Boundary condition" ;
  BoundaryCondition bouAirWithC(
    redeclare package Medium = IBPSA.Media.Air (
    X_default={0.015, 0.985},
    extraPropertiesNames={"CO2"}))
   "Boundary condition" ;
  BoundaryCondition bouDryAirNoC(
    redeclare package Medium = Modelica.Media.Air.SimpleAir)
    "Boundary condition" ;
  BoundaryCondition bouDryAirWithC(
    redeclare package Medium = Modelica.Media.Air.SimpleAir (
      extraPropertiesNames={"CO2"}))
     "Boundary condition" ;

protected
  model BoundaryCondition
    extends Modelica.Blocks.Icons.Block;

    replaceable package Medium = Modelica.Media.Interfaces.PartialMedium
      "Medium in the component";

    final parameter Boolean use_p_in=false
      "= true to use a pressure from connector, false to output Medium.p_default";

    Adaptors.Inlet bouInlAirNoC(
      redeclare package Medium = Medium,
      allowFlowReversal=true,
      use_p_in=false)                "Boundary condition for air inlet"
      ;
    Sources.Boundary_pT bou(
      redeclare package Medium = Medium,
      nPorts=1,
      p=Medium.p_default + 1000,
      T=298.15,
      C=fill(0.7, Medium.nC)) "Boundary condition"
      ;
    Interfaces.Inlet inlet(
      use_p_in=use_p_in,
      redeclare package Medium = Medium,
      allowFlowReversal=true)
      "Fluid inlet"
      ;

    FixedResistances.PressureDrop res(
      redeclare package Medium = Medium,
      m_flow_nominal=0.1,
      dp_nominal=1000,
      linearized=true) "Flow resistance"
      ;
  equation
    connect(bouInlAirNoC.inlet, inlet)
      ;
    connect(res.port_b, bou.ports[1])
      ;
    connect(res.port_a, bouInlAirNoC.port_b)
      ;
  end BoundaryCondition;

equation
  connect(bouAirNoC.inlet, conAirNoC.outlet)
    ;
  connect(bouAirWithC.inlet, conAirWithC.outlet)
    ;
  connect(bouDryAirNoC.inlet, conDryAirNoC.outlet)
    ;
  connect(bouDryAirWithC.inlet, conDryAirWithC.outlet)

  ;
end AirToOutletFlowReversal;

within IBPSA.Electrical.Interfaces;
model Load "Partial model for a generic load"
  replaceable package PhaseSystem =
      IBPSA.Electrical.PhaseSystems.PartialPhaseSystem constrainedby
    IBPSA.Electrical.PhaseSystems.PartialPhaseSystem "Phase system"
    ;
  parameter Boolean linearized = false "If true, the load model is linearized"
    ;
  parameter IBPSA.Electrical.Types.Load mode(
    min=IBPSA.Electrical.Types.Load.FixedZ_steady_state,
    max=IBPSA.Electrical.Types.Load.VariableZ_y_input) = IBPSA.Electrical.Types.Load.FixedZ_steady_state
    "Type of load model (e.g., steady state, dynamic, prescribed power consumption, etc.)"
    ;

  parameter Modelica.Units.SI.Power P_nominal=0
    "Nominal power (negative if consumed, positive if generated). Used if mode <> IBPSA.Electrical.Types.Load.VariableZ_P_input"
    ;

  parameter Modelica.Units.SI.Voltage V_nominal(min=0, start=110)
    "Nominal voltage (V_nominal >= 0)" ;
  parameter IBPSA.Electrical.Types.InitMode initMode(
  min=IBPSA.Electrical.Types.InitMode.zero_current,
  max=IBPSA.Electrical.Types.InitMode.linearized) = IBPSA.Electrical.Types.InitMode.zero_current
    "Initialization mode for homotopy operator"  ;

  Modelica.Units.SI.Voltage v[:](start=PhaseSystem.phaseVoltages(V_nominal)) =
    terminal.v "Voltage vector";
  Modelica.Units.SI.Current i[:](each start=0) = terminal.i "Current vector";
  Modelica.Units.SI.Power S[PhaseSystem.n]=PhaseSystem.phasePowers_vi(v, -i)
    "Phase powers";
  Modelica.Units.SI.Power P(start=0)
    "Power of the load (negative if consumed, positive if fed into the electrical grid)";

  Modelica.Blocks.Interfaces.RealInput y(min=0, max=1, unit="1")
    if (mode == IBPSA.Electrical.Types.Load.VariableZ_y_input)
    "Fraction of the nominal power consumed" ;
  Modelica.Blocks.Interfaces.RealInput Pow(unit="W")
    if (mode == IBPSA.Electrical.Types.Load.VariableZ_P_input)
    "Power consumed" ;
  replaceable IBPSA.Electrical.Interfaces.Terminal terminal(
    redeclare replaceable package PhaseSystem = PhaseSystem)
    "Generalized electric terminal"
    ;

protected
  Modelica.Blocks.Interfaces.RealInput y_internal
    "Hidden value of the input load for the conditional connector";
  Modelica.Blocks.Interfaces.RealInput P_internal
    "Hidden value of the input power for the conditional connector";
  Real load(min=eps, max=1)
    "Internal representation of control signal, used to avoid singularity";
  constant Real eps = 1E-10
    "Small number used to avoid a singularity if the power is zero";
  constant Real oneEps = 1-eps
    "Small number used to avoid a singularity if the power is zero";

initial equation
  if mode == IBPSA.Electrical.Types.Load.VariableZ_P_input then
    assert(abs(P_nominal) < 1E-10, "*** Warning: P_nominal = " + String(P_nominal) + ", but this value will be ignored.",
           AssertionLevel.warning);
  end if;

equation
  assert(y_internal>=0 and y_internal<=1+eps, "The power load fraction P (input of the model) must be within [0,1]");

  // Connection between the conditional and inner connector
  connect(y,y_internal);
  connect(Pow,P_internal);

  // If the power is fixed, inner connector value is equal to 1
  if mode==IBPSA.Electrical.Types.Load.FixedZ_steady_state or
     mode==IBPSA.Electrical.Types.Load.FixedZ_dynamic then
    y_internal   = 1;
    P_internal = 0;
  elseif mode==IBPSA.Electrical.Types.Load.VariableZ_y_input then
    P_internal = 0;
  elseif mode==IBPSA.Electrical.Types.Load.VariableZ_P_input then
    y_internal = 1;
  end if;

  // Value of the load, depending on the type: fixed or variable
  if mode==IBPSA.Electrical.Types.Load.VariableZ_y_input then
    load = eps + oneEps*y_internal;
  else
    load = 1;
  end if;

  // Power consumption
  if mode==IBPSA.Electrical.Types.Load.FixedZ_steady_state or
     mode==IBPSA.Electrical.Types.Load.FixedZ_dynamic then
    P = P_nominal;
  elseif mode==IBPSA.Electrical.Types.Load.VariableZ_P_input then
    P = P_internal;
  else
    P = P_nominal*load;
  end if

  ;
end Load;

within IBPSA.Utilities.Psychrometrics.Functions;
function TDewPoi_pW
  "Function to compute the water vapor partial pressure for a given dew point temperature of moist air"
  extends Modelica.Icons.Function;

  input Modelica.Units.SI.Pressure p_w(displayUnit="Pa", min=200)
    "Water vapor partial pressure";
  output Modelica.Units.SI.Temperature T "Dew point temperature";

protected
  function pW_TDewPoi_inversion
    "Internal function to solve eps=f(NTU, Z) for NTU for cross flow unmixed"
    extends Modelica.Math.Nonlinear.Interfaces.partialScalarFunction;

    input Modelica.Units.SI.Pressure p_w(displayUnit="Pa", min=200)
      "Water vapor partial pressure";

  algorithm
    y :=IBPSA.Utilities.Psychrometrics.Functions.pW_TDewPoi(T=u) - p_w;
  end pW_TDewPoi_inversion;

algorithm
  T := Modelica.Math.Nonlinear.solveOneNonlinearEquation(
      f=function pW_TDewPoi_inversion(p_w=p_w),
      u_min=200,
      u_max=400)
  ;
end TDewPoi_pW;

within IBPSA.Fluid.Geothermal.Borefields.Validation;
model Sandbox "Validation of BorefieldOneUTube based on the experiment of Beier et al. (2011)"
  extends Modelica.Icons.Example;
  package Medium = IBPSA.Media.Water;

  parameter Modelica.Units.SI.Temperature T_start=273.15 + 22.09
    "Initial temperature of the sandbox";

  // mSenFac is set to its numerical value because it is a constant in the borehole model.
  // mSenFac = 1 +
  //  (1.8e6*Modelica.Constants.pi*(borFieDat.conDat.rTub^2
  //        -(borFieDat.conDat.rTub-borFieDat.conDat.eTub)^2)
  //        +2.4e6*2*Modelica.Constants.pi*borFieDat.conDat.rBor*0.002/2)
  //        /(4.2e6*Modelica.Constants.pi*(borFieDat.conDat.rTub-borFieDat.conDat.eTub)^2)

  constant Real mSenFac = 1.59186
  "Scaling factor for the borehole capacitances, modified to account for the thermal mass of the pipes and the borehole casing";

  IBPSA.Fluid.Geothermal.Borefields.OneUTube borHol(
    redeclare package Medium = Medium, borFieDat=
    borFieDat,
    tLoaAgg=60,
    energyDynamics=Modelica.Fluid.Types.Dynamics.FixedInitial,
    mSenFac=mSenFac,
    TExt0_start=T_start,
    dT_dz=0) "Borehole"
    ;
  IBPSA.Fluid.Movers.FlowControlled_m_flow pum(
    redeclare package Medium = Medium,
    T_start=T_start,
    addPowerToMedium=false,
    use_inputFilter=false,
    energyDynamics=Modelica.Fluid.Types.Dynamics.SteadyState,
    m_flow_nominal=borFieDat.conDat.mBorFie_flow_nominal,
    nominalValuesDefineDefaultPressureCurve=true,
    inputType=IBPSA.Fluid.Types.InputType.Constant,
    dp_nominal=60E3) "Circulation pump"
    ;
  IBPSA.Fluid.Sensors.TemperatureTwoPort TBorFieIn(
    redeclare package Medium = Medium,
    T_start=T_start,
    m_flow_nominal=borFieDat.conDat.mBorFie_flow_nominal,
    tau=0)
    "Inlet temperature of the borefield"
    ;
  IBPSA.Fluid.Sensors.TemperatureTwoPort TBorFieOut(
    redeclare package Medium = Medium,
    T_start=T_start,
    m_flow_nominal=borFieDat.conDat.mBorFie_flow_nominal,
    tau=0)
    "Outlet temperature of the borefield"
    ;
  parameter IBPSA.Fluid.Geothermal.Borefields.Validation.BaseClasses.SandBox_Borefield borFieDat "Borefield data"
    ;
  IBPSA.Fluid.Sources.Boundary_ph sin(
    redeclare package Medium = Medium,
    nPorts=1) "Sink"
    ;
  Modelica.Blocks.Sources.CombiTimeTable sandBoxMea(
    tableOnFile=true,
    tableName="data",
    offset={0,0,0},
    columns={2,3,4},
    fileName=Modelica.Utilities.Files.loadResource(
      "modelica://IBPSA/Resources/Data/Fluid/Geothermal/Borefields/HeatTransfer/Validation/Beier_Smith_Spitler_2011_SandBox.txt"))
    ;
  IBPSA.Fluid.HeatExchangers.HeaterCooler_u hea(
    redeclare package Medium = Medium,
    dp_nominal=10000,
    show_T=true,
    energyDynamics=Modelica.Fluid.Types.Dynamics.SteadyState,
    T_start=T_start,
    Q_flow_nominal=1056,
    m_flow_nominal=borFieDat.conDat.mBorFie_flow_nominal,
    m_flow(start=borFieDat.conDat.mBorFie_flow_nominal),
    p_start=100000) "Heater"
    ;
equation
  connect(TBorFieIn.port_b, borHol.port_a)
    ;
  connect(borHol.port_b, TBorFieOut.port_a)
    ;
  connect(pum.port_b, TBorFieIn.port_a) ;
  connect(sin.ports[1], TBorFieOut.port_b) ;
  connect(hea.port_b, pum.port_a)
    ;
  connect(hea.port_a, TBorFieOut.port_b) ;
  connect(sandBoxMea.y[3], hea.u) 
  ;
end Sandbox;

within IBPSA.Fluid.Interfaces;
block LumpedVolumeDeclarations "Declarations for lumped volumes"
  replaceable package Medium =
    Modelica.Media.Interfaces.PartialMedium "Medium in the component"
      ;

  // Assumptions
  parameter Modelica.Fluid.Types.Dynamics energyDynamics=Modelica.Fluid.Types.Dynamics.DynamicFreeInitial
    "Type of energy balance: dynamic (3 initialization options) or steady state"
    ;
  parameter Modelica.Fluid.Types.Dynamics massDynamics=energyDynamics
    "Type of mass balance: dynamic (3 initialization options) or steady state, must be steady state if energyDynamics is steady state"
    ;
  final parameter Modelica.Fluid.Types.Dynamics substanceDynamics=energyDynamics
    "Type of independent mass fraction balance: dynamic (3 initialization options) or steady state"
    ;
  final parameter Modelica.Fluid.Types.Dynamics traceDynamics=energyDynamics
    "Type of trace substance balance: dynamic (3 initialization options) or steady state"
    ;

  // Initialization
  parameter Medium.AbsolutePressure p_start = Medium.p_default
    "Start value of pressure"
    ;
  parameter Medium.Temperature T_start=Medium.T_default
    "Start value of temperature"
    ;
  parameter Medium.MassFraction X_start[Medium.nX](
       quantity=Medium.substanceNames) = Medium.X_default
    "Start value of mass fractions m_i/m"
    ;
  parameter Medium.ExtraProperty C_start[Medium.nC](
       quantity=Medium.extraPropertiesNames)=fill(0, Medium.nC)
    "Start value of trace substances"
    ;
  parameter Medium.ExtraProperty C_nominal[Medium.nC](
       quantity=Medium.extraPropertiesNames) = fill(1E-2, Medium.nC)
    "Nominal value of trace substances. (Set to typical order of magnitude.)"
   ;
  parameter Real mSenFac(min=1)=1
    "Factor for scaling the sensible thermal mass of the volume"
    ;

protected
  // The parameter below is evaluated by OCT during compilation, and
  // if false, the assert statement won't be optimized away during
  // code generation.
  final parameter Boolean wrongEnergyMassBalanceConfiguration=
    not (energyDynamics <> Modelica.Fluid.Types.Dynamics.SteadyState or
         massDynamics == Modelica.Fluid.Types.Dynamics.SteadyState)
    "True if configuration of energy and mass balance is wrong."
    ;
initial equation
  if wrongEnergyMassBalanceConfiguration then
  assert(not wrongEnergyMassBalanceConfiguration,
         "In " + getInstanceName() +
         ": energyDynamics is selected as steady state, and therefore massDynamics must also be steady-state.");
  end if

;
end LumpedVolumeDeclarations;

