within IBPSA.Utilities.Psychrometrics;
model hSat_pTSat
  "Calculate saturation enthalpy given a saturation (dry bulb) temperature"
  extends Modelica.Blocks.Icons.Block;

  Modelica.Blocks.Interfaces.RealInput p(
    final quantity="Pressure",
    final unit="Pa",
    displayUnit="bar") = 101325
    "Pressure of the fluid"
    ;
  Modelica.Blocks.Interfaces.RealInput TSat(
    final quantity="ThermodynamicTemperature",
    final unit="K",
    min = 0.0,
    start = 288.15,
    nominal = 300,
    displayUnit="degC")
    "Saturation temperature of the fluid"
    ;

  Modelica.Blocks.Interfaces.RealOutput hSat(
    final quantity="SpecificEnergy",
    final unit="J/kg")
    "Dew point temperature of air"
    ;

protected
  constant Integer watIdx = 1 "Index of water";
  constant Integer othIdx = 2 "Index of other species";
  constant Real phiSat(min=0, max=1) = 1 "Saturation relative humidity";
  Modelica.Units.SI.AbsolutePressure pSat
    "Saturation pressure of water vapor in air at TSat";
  Real XSat[2]
    "Mass fractions of water and air in moist air at saturation";

equation
  pSat = IBPSA.Utilities.Psychrometrics.Functions.saturationPressure(TSat);
  XSat[watIdx] = IBPSA.Utilities.Psychrometrics.Functions.X_pSatpphi(
    pSat=pSat, p=p, phi=phiSat);
  XSat[othIdx] = 1 - XSat[watIdx];
  hSat = IBPSA.Media.Air.specificEnthalpy_pTX(p=p, T=TSat, X=XSat)
  ;
end hSat_pTSat;

within IBPSA.Media.Examples.BaseClasses;
partial model FluidProperties
  "Model that tests the implementation of the fluid properties"
  extends PartialProperties;

  Medium.ThermodynamicState state_phX "Medium state";
  Medium.ThermodynamicState state_psX "Medium state";

  Modelica.Media.Interfaces.Types.DerDensityByPressure ddpT
    "Density derivative w.r.t. pressure";
  Modelica.Media.Interfaces.Types.DerDensityByTemperature ddTp
    "Density derivative w.r.t. temperature";
  Modelica.Units.SI.Density[Medium.nX] dddX
    "Density derivative w.r.t. mass fraction";

equation

   // Check setting the states
    state_pTX = Medium.setState_pTX(p=p, T=T, X=X);
    state_phX = Medium.setState_phX(p=p, h=h, X=X);
    state_psX = Medium.setState_psX(p=p, s=s, X=X);
    checkState(state_pTX, state_phX, errAbs, "state_phX");
    checkState(state_pTX, state_psX, errAbs, "state_psX");

    // Check the implementation of the functions
    ddpT = Medium.density_derp_T(state_pTX);
    ddTp = Medium.density_derT_p(state_pTX);
    dddX   = Medium.density_derX(state_pTX)
   ;
end FluidProperties;

within IBPSA.Fluid.Movers.Validation;
model PumpCurveConstruction
  "Validation model that tests that the pump curve is properly extrapolated to V=0 and dp=0"
  extends Modelica.Icons.Example;

  package Medium = IBPSA.Media.Water "Medium model";

  parameter Modelica.Units.SI.MassFlowRate m_flow_nominal=1
    "Nominal mass flow rate at zero pump head";
  parameter Modelica.Units.SI.VolumeFlowRate V_flow_nominal=m_flow_nominal/1000
    "Nominal mass flow rate at zero pump head";

  parameter Modelica.Units.SI.PressureDifference dp_nominal=10000
    "Nominal pump head at zero mass flow rate";

  Actuators.Valves.TwoWayLinear val1(
    redeclare package Medium = Medium,
    m_flow_nominal=m_flow_nominal,
    use_inputFilter=false,
    dpValve_nominal=dp_nominal/1000,
    from_dp=false) "Valve with very small pressure drop if fully open"
    ;
  Sources.Boundary_pT sou(
    redeclare package Medium = Medium,
    use_p_in=false,
    nPorts=8,
    p=101325,
    T=293.15) "Pressure boundary condition"
    ;

  IBPSA.Fluid.Movers.SpeedControlled_y pum(
    redeclare package Medium = Medium,
    energyDynamics=Modelica.Fluid.Types.Dynamics.SteadyState,
    use_inputFilter=false,
    per(pressure(V_flow={0,0.5*V_flow_nominal,V_flow_nominal}, dp={dp_nominal,
            0.5*dp_nominal,0})),
    inputType=IBPSA.Fluid.Types.InputType.Constant)
    "Pump with 3 data points for the pressure flow relation"
    ;

  IBPSA.Fluid.Movers.SpeedControlled_y pum_dp(
    redeclare package Medium = Medium,
    energyDynamics=Modelica.Fluid.Types.Dynamics.SteadyState,
    use_inputFilter=false,
    per(pressure(V_flow={0.5*V_flow_nominal,0.75*V_flow_nominal,V_flow_nominal},
          dp={0.5*dp_nominal,0.25*dp_nominal,0})),
    inputType=IBPSA.Fluid.Types.InputType.Constant)
    "Pump with 2 data points for the pressure flow relation, with data at dp=0"
    ;

  IBPSA.Fluid.Movers.SpeedControlled_y pum_m_flow(
    redeclare package Medium = Medium,
    energyDynamics=Modelica.Fluid.Types.Dynamics.SteadyState,
    use_inputFilter=false,
    per(pressure(V_flow={0,0.25*V_flow_nominal,0.5*V_flow_nominal}, dp={
            dp_nominal,0.75*dp_nominal,0.5*dp_nominal})),
    inputType=IBPSA.Fluid.Types.InputType.Constant)
    "Pump with 2 data points for the pressure flow relation, with data at m_flow=0"
    ;

  IBPSA.Fluid.Movers.SpeedControlled_y pum_no(
    redeclare package Medium = Medium,
    energyDynamics=Modelica.Fluid.Types.Dynamics.SteadyState,
    use_inputFilter=false,
    per(pressure(V_flow={0.25*V_flow_nominal,0.5*V_flow_nominal,0.75*
            V_flow_nominal}, dp={0.75*dp_nominal,0.5*dp_nominal,0.25*dp_nominal})),
    inputType=IBPSA.Fluid.Types.InputType.Constant)
    "Pump with 2 data points for the pressure flow relation, with no data at m_flow=0 and dp=0"
    ;

  Modelica.Blocks.Sources.Ramp yVal(
    duration=1,
    offset=1,
    height=-0.99) "Input signal for valve"
    ;

  Actuators.Valves.TwoWayLinear val2(
    redeclare package Medium = Medium,
    m_flow_nominal=m_flow_nominal,
    use_inputFilter=false,
    dpValve_nominal=dp_nominal/1000,
    from_dp=false) "Valve with very small pressure drop if fully open"
    ;

  Actuators.Valves.TwoWayLinear val3(
    redeclare package Medium = Medium,
    m_flow_nominal=m_flow_nominal,
    use_inputFilter=false,
    dpValve_nominal=dp_nominal/1000,
    from_dp=false) "Valve with very small pressure drop if fully open"
    ;

  Actuators.Valves.TwoWayLinear val4(
    redeclare package Medium = Medium,
    m_flow_nominal=m_flow_nominal,
    use_inputFilter=false,
    dpValve_nominal=dp_nominal/1000,
    from_dp=false) "Valve with very small pressure drop if fully open"
    ;

equation
  connect(pum.port_a, val1.port_b) ;
  connect(val1.port_a, sou.ports[1]) ;
  connect(yVal.y, val1.y) ;
  connect(pum_dp.port_a, val2.port_b) ;
  connect(pum_m_flow.port_a, val3.port_b) ;
  connect(sou.ports[2], val2.port_a) ;
  connect(val3.port_a, sou.ports[3]) ;
  connect(yVal.y, val2.y) ;
  connect(yVal.y, val3.y) ;

  connect(val4.port_a, sou.ports[4]) ;
  connect(val4.port_b, pum_no.port_a) ;
  connect(yVal.y, val4.y) ;
  connect(pum_no.port_b, sou.ports[5]) ;
  connect(pum_m_flow.port_b, sou.ports[6]) ;
  connect(pum_dp.port_b, sou.ports[7]) ;
  connect(pum.port_b, sou.ports[8]) 
  ;
end PumpCurveConstruction;

within IBPSA.Fluid.Geothermal.Borefields.BaseClasses.HeatTransfer.ThermalResponseFactors.Validation;
model GFunction_100boreholes
  "g-Function calculation for a field of 10 by 10 boreholes"
  extends Modelica.Icons.Example;

  parameter Integer nBor = 100 "Number of boreholes";
  parameter Modelica.Units.SI.Position cooBor[nBor,2]={{7.5*mod(i - 1, 10),7.5*
      floor((i - 1)/10)} for i in 1:nBor} "Coordinates of boreholes";
  parameter Modelica.Units.SI.Height hBor=150 "Borehole length";
  parameter Modelica.Units.SI.Height dBor=4 "Borehole buried depth";
  parameter Modelica.Units.SI.Radius rBor=0.075 "Borehole radius";
  parameter Modelica.Units.SI.ThermalDiffusivity aSoi=1e-6
    "Ground thermal diffusivity used in g-function evaluation";
  parameter Integer nSeg = 12 "Number of line source segments per borehole";
  parameter Integer nTimSho = 26 "Number of time steps in short time region";
  parameter Integer nTimLon = 50 "Number of time steps in long time region";
  parameter Real ttsMax = exp(5) "Maximum non-dimensional time for g-function calculation";

  final parameter Integer nTimTot=nTimSho+nTimLon;
  final parameter Real[nTimTot] gFun(each fixed=false);
  final parameter Real[nTimTot] lntts(each fixed=false);
  final parameter Modelica.Units.SI.Time[nTimTot] tGFun(each fixed=false);
  final parameter Real[nTimTot] dspline(each fixed=false);

  parameter Integer nClu=5 "Number of clusters to be generated";
  parameter Integer labels[nBor](each fixed=false) "Cluster label associated with each data point";
  parameter Integer cluSiz[nClu](each fixed=false) "Size of the clusters";

  Real gFun_int "Interpolated value of g-function";
  Real lntts_int "Non-dimensional logarithmic time for interpolation";

  discrete Integer k "Current interpolation interval";
  discrete Modelica.Units.SI.Time t1 "Previous value of time for interpolation";
  discrete Modelica.Units.SI.Time t2 "Next value of time for interpolation";
  discrete Real gFun1 "Previous g-function value for interpolation";
  discrete Real gFun2 "Next g-function value for interpolation";
  parameter Modelica.Units.SI.Time ts=hBor^2/(9*aSoi)
    "Bore field characteristic time";

initial equation
  // Evaluate g-function for the specified bore field configuration
  (labels, cluSiz) = IBPSA.Fluid.Geothermal.Borefields.BaseClasses.HeatTransfer.ThermalResponseFactors.clusterBoreholes(
    nBor = nBor,
    cooBor = cooBor,
    hBor = hBor,
    dBor = dBor,
    rBor = rBor,
    nClu = nClu);
  (tGFun,gFun) =
    IBPSA.Fluid.Geothermal.Borefields.BaseClasses.HeatTransfer.ThermalResponseFactors.gFunction(
      nBor = nBor,
      cooBor = cooBor,
      hBor = hBor,
      dBor = dBor,
      rBor = rBor,
      aSoi = aSoi,
      nSeg = nSeg,
      nTimSho = nTimSho,
      nTimLon = nTimLon,
      ttsMax = ttsMax,
      nClu = nClu,
      labels = labels,
      cluSiz = cluSiz);
  lntts = log(tGFun/ts .+ Modelica.Constants.small);
  // Initialize parameters for interpolation
  dspline = IBPSA.Utilities.Math.Functions.splineDerivatives(
    x = tGFun,
    y = gFun);
  k = 1;
  t1 = tGFun[1];
  t2 = tGFun[2];
  gFun1 = gFun[1];
  gFun2 = gFun[2];

equation
  // Dimensionless logarithmic time
  lntts_int = log(IBPSA.Utilities.Math.Functions.smoothMax(time, 1e-6, 2e-6)/ts);
  // Interpolate g-function
  gFun_int = IBPSA.Utilities.Math.Functions.cubicHermiteLinearExtrapolation(
    x = time,
    x1 = t1,
    x2 = t2,
    y1 = gFun1,
    y2 = gFun2,
    y1d = dspline[pre(k)],
    y2d = dspline[pre(k)+1]);
  // Update interpolation parameters, when needed
  when time >= pre(t2) then
    k = min(pre(k) + 1, nTimTot);
    t1 = tGFun[k];
    t2 = tGFun[k+1];
    gFun1 = gFun[k];
    gFun2 = gFun[k+1];
  end when

   ;
end GFunction_100boreholes;

within IBPSA.Utilities.Math.Functions;
function smoothLimit
  "Once continuously differentiable approximation to the limit function"
  extends Modelica.Icons.Function;
  input Real x "Variable";
  input Real l "Low limit";
  input Real u "Upper limit";
  input Real deltaX "Width of transition interval";
  output Real y "Result";

protected
  Real cor;
algorithm
  cor :=deltaX/10;
  y := IBPSA.Utilities.Math.Functions.smoothMax(x,l+deltaX,cor);
  y := IBPSA.Utilities.Math.Functions.smoothMin(y,u-deltaX,cor)
  ;
end smoothLimit;

