  IBPSA.Fluid.Sources.Boundary_pT amb(
    redeclare package Medium = Medium,
    T=298.15,
    nPorts=1)
    "Ambient conditions, used to test the relative temperature sensor"
     ;
  IBPSA.Fluid.Sources.MassFlowSource_T masFloRat(
    redeclare package Medium = Medium,
    use_T_in=true,
    use_m_flow_in=true,
    nPorts=1) "Flow boundary condition"  ;
  Modelica.Blocks.Sources.Ramp TDryBul(
    height=10,
    duration=1,
    offset=273.15 + 30) "Dry bulb temperature"
                 ;
  IBPSA.Fluid.Sensors.TemperatureTwoPort temSteSta(
   redeclare package Medium = Medium,
   m_flow_nominal=2,
   tau=0) "Steady state temperature sensor"
    ;

    Modelica.Blocks.Sources.Pulse m_flow1(
    period=30,
    offset=0,
    amplitude=-1) "Mass flow rate"
    ;
  IBPSA.Fluid.Sensors.TemperatureTwoPort temDyn(
    redeclare package Medium = Medium,
    m_flow_nominal=2,
    initType=Modelica.Blocks.Types.Init.InitialState,
    T_start=293.15) "Dynamic temperature sensor"
    ;
  RelativeTemperature senRelTem(redeclare package Medium = Medium)
    "Temperature difference sensor" ;
  IBPSA.Fluid.Sources.Boundary_pT sin(
    redeclare package Medium = Medium,
    T=293.15,
    nPorts=2) "Flow boundary condition"
     ;
  IBPSA.Fluid.Sensors.TemperatureTwoPort temDynLoss(
    redeclare package Medium = Medium,
    m_flow_nominal=2,
    initType=Modelica.Blocks.Types.Init.InitialState,
    transferHeat=true,
    T_start=293.15,
    TAmb=293.15,
    tauHeaTra=30) "Dynamic temperature sensor with heat transfer"
    ;
  Modelica.Blocks.Math.Add add_m_flow
    "Add two pulse functions for mass flow rate"
    ;
    Modelica.Blocks.Sources.Pulse m_flow2(
    amplitude=1,
    offset=0,
    period=45) "Mass flow rate"
    ;
equation
  connect(TDryBul.y, masFloRat.T_in)    ;
  connect(masFloRat.ports[1], temSteSta.port_a) ;
  connect(temSteSta.port_b, temDyn.port_a) ;
  connect(amb.ports[1], senRelTem.port_a) ;
  connect(temDyn.port_b, temDynLoss.port_a)
    ;
  connect(masFloRat.m_flow_in, add_m_flow.y) ;
  connect(add_m_flow.u1, m_flow1.y)
    ;
  connect(m_flow2.y, add_m_flow.u2) ;
  connect(sin.ports[1], temDynLoss.port_b)
    ;
  connect(sin.ports[2], senRelTem.port_b) 
    ;
end TemperatureDryBulb;

