model EulerComparison
  "Validates the Euler number method at nominal mover speed"
  extends Modelica.Icons.Example;

  parameter Integer nOri(min=1)=size(per1.power.V_flow,1)
    "Number of data points for pressure curve"
    ;
  parameter Modelica.Units.SI.Density rhoCon=1.2
    "Constant density";

  parameter IBPSA.Fluid.Movers.Data.Fans.Greenheck.BIDW13 per1
    "Mover performance curves with flow rate, pressure rise, and power";
  IBPSA.Fluid.Movers.BaseClasses.FlowMachineInterface eff1(
    per=per1,
    rho_default=rhoCon,
    nOri=nOri,
    computePowerUsingSimilarityLaws=false)
    "Flow machine interface using power characteristic"
    ;
  parameter IBPSA.Fluid.Movers.Data.Generic per2(
    final powerOrEfficiencyIsHydraulic=per1.powerOrEfficiencyIsHydraulic,
    final etaHydMet=
           IBPSA.Fluid.Movers.BaseClasses.Types.HydraulicEfficiencyMethod.EulerNumber,
    final etaMotMet=
           IBPSA.Fluid.Movers.BaseClasses.Types.MotorEfficiencyMethod.NotProvided,
    pressure=per1.pressure,
    power=per1.power)
    "Peak condition";
  IBPSA.Fluid.Movers.BaseClasses.FlowMachineInterface eff2(
    per=per2,
    rho_default=rhoCon,
    nOri=nOri,
    computePowerUsingSimilarityLaws=false)
    "Flow machine interface using power Euler correlation"
    ;

  Modelica.Blocks.Sources.Constant y(k=1) "Control signal"
    ;
  Modelica.Blocks.Sources.Constant rho(k=rhoCon) "Density"
    ;

  Modelica.Units.SI.VolumeFlowRate V_flow = m_flow.y/rhoCon "Volumetric flow rate";
  Modelica.Units.SI.Power P1(displayUnit="W")=
    if per1.powerOrEfficiencyIsHydraulic
    then eff1.WHyd
    else eff1.PEle
    "Power from interpolation (total or hydraulic depending on data)";
  Modelica.Units.SI.Power P2(displayUnit="W")=
    if per1.powerOrEfficiencyIsHydraulic
    then eff2.WHyd
    else eff2.PEle
    "Power from Euler number (total or hydraulic depending on data)";
  Modelica.Units.SI.Efficiency eta1=
    if per1.powerOrEfficiencyIsHydraulic
    then eff1.etaHyd
    else eff1.eta
    "Efficiency from interpolation (total or hydraulic depending on data)";
  Modelica.Units.SI.Efficiency eta2=
    if per1.powerOrEfficiencyIsHydraulic
    then eff2.etaHyd
    else eff2.eta
    "Efficiency from Euler number (total or hydraulic depending on data)";

  Modelica.Blocks.Sources.Ramp m_flow(
    height=eff1.V_flow_max*rhoCon,
    duration=1)
    "Mass flow rate"
    ;
equation
  connect(eff1.rho, rho.y)
    ;
  connect(y.y, eff1.y_in)
    ;
  connect(m_flow.y, eff1.m_flow) ;
  connect(y.y, eff2.y_in) ;
  connect(rho.y, eff2.rho) ;
  connect(m_flow.y, eff2.m_flow) 
  ;
end EulerComparison;

within IBPSA.Utilities.Psychrometrics.Functions.BaseClasses;
function der_pW_TDewPoi "Derivative of function pW_TDewPoi"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Temperature T "Dew point temperature";
  input Real dT "Temperature differential";
  output Real dp_w "Differential of water vapor partial pressure";
protected
  constant Real C8=-5.800226E3;
  constant Real C9=1.3914993E0;
  constant Real C10=-4.8640239E-2;
  constant Real C11=4.1764768E-5;
  constant Real C12=-1.4452093E-8;
  constant Real C13=6.5459673E0;
algorithm
  dp_w := Modelica.Math.exp(C8/T + C9 + T*(C10 + T*(C11 + T*C12)) + C13*
    Modelica.Math.log(T))*(-C8/T/T + C10 + 2*C11*T + 3*C12*T*T + C13/T)*dT
  ;
end der_pW_TDewPoi;

