equation
  connect(conRoom.port_b, volumeHall.heatPort) ;
  connect(port_a_toZone, volumeHall.ports[1]) ;
  connect(port_b_toZone, volumeHall.ports[2]) ;
  connect(col.port_b, oriOutBottom.port_a) ;
