model Ctrl_Heating_TES
  "Heating curve control for heating based on a water storage tank"
  extends Interfaces.Partial_Ctrl_Heating_TES;

equation
  TTopSet = max(TDHWSet, heatingCurve.TSup) + dTSafetyTop;
  TBotSet = max(TDHWSet, heatingCurve.TSup) + dTSafetyBot;
  THPSet = TTopSet + dTHPTankSet;

  if noEvent(TTankTop < TTopSet and TTankBot < (TBotSet - dTSafetyBot)) then
    // top too cold, system MUST be on except if bottom is still very hot (temp inversion?)
    onOff = 1;
  elseif noEvent(TTankBot < TBotSet and onOff > 0.5) then
    // HP running, top is fine, bottom too cold: keep running
    onOff = 1;
  else
    // all other cases: shut down
    onOff = 0;
  end if

  ;
end Ctrl_Heating_TES;

within IndustrialControlSystems.Controllers;
model PD "Proportional + Derivative controller"
  extends Interfaces.Controller;
  parameter Real Kp = 5 "|Parameters| Proportional gain" ;
  parameter Real Td = 1 "|Parameters| Derivative time" ;
  parameter Real N =  10 "|Parameters| Derivative filter ratio"  ;
  Real Fin "Filtered input";
  Real satin "input of the saturation block";
initial equation

  if Ts > 0 then
    // Discrete time initialisation
    pre(Fin) = if AntiWindup then max(CSmin,min(CSmax,CS_start)) else CS_start - bias;
  else
    // Continuous time initialisation
    Fin = if AntiWindup then max(CSmin,min(CSmax,CS_start)) else CS_start - bias;
  end if;

equation

  if Ts > 0 then
    // Discrete time controller
    when sample(0,Ts) then
      CS    = if AntiWindup then max(CSmin,min(CSmax,satin)) else satin;
      satin = if ts then tr else Kp*N*(SP - PV) + pre(bias) - Kp*N*Fin;
      Fin = IndustrialControlSystems.LinearSystems.Discrete.Functions.f1Pole(
        alfa,
        SP - PV,
        pre(SP) - pre(PV),
        pre(Fin),
        Ts,
        1,
        Td/N);
    end when;
  else
    // Continuous time controller
    CS    = if AntiWindup then max(CSmin,min(CSmax,satin)) else satin;
    satin = if ts then tr else N*Kp*(SP - PV) + bias - Fin;
    Fin + Td/N*der(Fin) = Kp*N*(SP - PV);
  end if

  ;
end PD;

within IndustrialControlSystems.Controllers.Blocks;
model I "Integrator with tracking mode (and limiter)"
  extends IndustrialControlSystems.Controllers.Interfaces.Block;
  parameter Real T = 1 "Integral time" ;
  parameter Real y_start = 0 "State initial value" ;
protected
  Real Y;
initial equation
  y = y_start;
equation
  if AntiWindup then
    if not ts then
      der(Y) = 1/T*u + 1/eps*(y - Y);
      y = max(Ymin,min(Ymax,Y));
    else
      der(Y) = 1/eps*(y - Y);
      y = max(Ymin,min(Ymax,tr));
    end if;

  else
    Y = 0;
    if not ts then
      T*der(y) = u;
    else
      eps*der(y) = (-y + tr);
    end if;
  end if
  ;
end I;

