within IndustrialControlSystems.LinearSystems.Discrete;
model ComplexPoles "Process with complex poles"
  extends Interfaces.DiscreteBaseBlock;
  parameter Real xi = 0.8 "|Block parameters| Damping coefficient";
  parameter Real omegan = 0.1 "|Block parameters| Natural frequency";
  parameter Real mu = 1 "|Block parameters| Gain";
  parameter Real y_start = 0 "|Initial conditions| Output initial value";
  parameter Real dy_start = 0 "|Initial conditions| Slope initial value";
protected
  Real u_pre1;
  Real y_pre1;
initial equation
  pre(y) = y_start;
  pre(y_pre1) = dy_start;
equation
  assert(xi>= 0 and xi <= 1,"Dumping coefficient must be between 0 and 1.");

  when sample(0,Ts) then
    y = Functions.fCmplx(alfa,u,pre(u),pre(u_pre1),pre(y),pre(y_pre1),Ts,mu,xi,omegan);
    u_pre1 = pre(u);
    y_pre1 = pre(y);
  end when
  ;
end ComplexPoles;

within IndustrialControlSystems.LinearSystems.Discrete.Functions;
function f1p1z "Function lead lag process: k(1+sT1)/(1+sT2)"
  input Real alfa "Parametro di discretizzazione";
  input Real T1 "Zero";
  input Real T2 "Polo";
  input Real u "Current input";
  input Real u_pre "Previous input";
  input Real y_pre "Previous output";
  input Real Ts "Sampling time [s]";
  input Real k "Gain";
  output Real y "Output";
protected
  Real A;
  Real B;
  Real C;
  Real D;
  Real E;
  Real F;
algorithm
  A := alfa*Ts;
  B := Ts - alfa*Ts;
  C := A + T1;
  D := B - T1;
  E := A + T2;
  F := B - T2;
  y := (C*k*u + D*k*u_pre - F*y_pre)/E
  ;
end f1p1z;

