  Modelica.Blocks.Interfaces.RealInput d(quantity="Position", unit="m") ;
  Modelica.Blocks.Interfaces.RealOutput f(quantity="Force", unit="N") ;
equation
  f = k*(iC + i)/(abs(d))^pd "Force on magnet"
  ;
