within MagLev.Control;
block F2i "Transform reference force to reference current"
  extends Modelica.Blocks.Interfaces.SISO;
  parameter Real k(unit="N.m4/A")=17.31E-9 "Force per current and distance^pd";
  parameter SI.Current iC=0 "Equivalent current describing force between pm and iron core without coil current";
  parameter Integer pd=4 "Power of distance to calculate force";
  parameter SI.Current iMax=1 "Max. current";
  parameter Boolean useSteadyStatePosition=false "Otherwise actual position";
  parameter SI.Position d0=-0.02 "Steady state position below coil";
  Modelica.Blocks.Interfaces.RealInput d "Connector of Real input signal" ;
  Modelica.Blocks.Interfaces.RealOutput fMax "Connector of Real output signal" ;
  Modelica.Blocks.Interfaces.RealOutput fMin "Connector of Real output signal" ;
equation
  //fMax and fMin are calculated immdiately after actual position d is available
  fMax = (iC + iMax)*k/(abs(if useSteadyStatePosition then d0 else d))^pd;
  fMin = iC*k/(abs(if useSteadyStatePosition then d0 else d))^pd;
  //convert reference force (output of speed controller) to reference current continuosly
  //i.e. refercne current is available before current controller is triggered
  y = u/k*(abs(if useSteadyStatePosition then d0 else d))^pd - iC
  ;
end F2i;

within MagLev.Control;
block InvertHallSensor "Invert Hall sensor equation"
  extends Modelica.Blocks.Icons.Block;
  parameter SI.Voltage alfa=2.48 "Coefficient 1 (constant)";
  parameter Real beta(unit="V.m2")=2.92E-4 "Coefficient 2  (distance)";
  parameter SI.Resistance gamma=0.48 "Coefficient 3 (current)";
  Modelica.Blocks.Interfaces.RealInput i(quantity="Current", unit="A") ;
  Modelica.Blocks.Interfaces.RealInput e(quantity="Voltage", unit="V") ;
  Modelica.Blocks.Interfaces.RealOutput d(quantity="Position", unit="m")  ;
equation
  d=-sqrt(beta/abs(e - alfa - gamma*i))
  ;
end InvertHallSensor;

