block E2d "Calculate position from hall sensor signal"
  extends Modelica.Clocked.ClockSignals.Interfaces.ClockedBlockIcon;
  extends MagLev.Control.BaseBlocks.E2d;
  Modelica.Clocked.ClockSignals.Interfaces.ClockInput clock ;
  Modelica.Clocked.RealSignals.Sampler.SampleClocked sample_e ;
  InvertHallSensor invertHallSensor(
    alfa=alfa,
    beta=beta,
    gamma=gamma) ;
  Modelica.Clocked.RealSignals.NonPeriodic.UnitDelay unitDelay_i(y_start=i0) ;
  Modelica.Clocked.RealSignals.NonPeriodic.UnitDelay unitDelay_e(y_start=e0) ;
  InvertHallSensor invertHallSensor_pre(
    alfa=alfa,
    beta=beta,
    gamma=gamma) ;
  Modelica.Blocks.Math.Feedback feedback ;
  Modelica.Blocks.Math.Division division ;
  Modelica.Blocks.Sources.RealExpression Ts(y=interval(sample_e.y)) ;
equation
  connect(e, sample_e.u) ;
  connect(clock, sample_e.clock) ;
  connect(sample_e.y, invertHallSensor.e) ;
  connect(invertHallSensor.d, d) ;
  connect(sample_e.y, unitDelay_e.u) ;
  connect(unitDelay_e.y, invertHallSensor_pre.e) ;
  connect(unitDelay_i.y, invertHallSensor_pre.i) ;
  connect(invertHallSensor_pre.d, feedback.u2) ;
  connect(invertHallSensor.d, feedback.u1) ;
  connect(feedback.y, division.u1) ;
  connect(division.y, d_der) ;
  connect(Ts.y, division.u2) ;
  connect(i, invertHallSensor.i)
    ;
