    final Ron=RonTransistor,
    final Goff=GoffTransistor,
    final Vknee=VkneeTransistor,
    final useHeatPort=useHeatPort) ;
  Modelica.Electrical.Analog.Ideal.IdealDiode diodeHS_n(
    final Ron=RonDiode,
    final Goff=GoffDiode,
    final Vknee=VkneeDiode,
    final useHeatPort=useHeatPort) ;
  Modelica.Electrical.Analog.Ideal.IdealGTOThyristor transistorLS_n(
    final Ron=RonTransistor,
    final Goff=GoffTransistor,
    final Vknee=VkneeTransistor,
    final useHeatPort=useHeatPort) ;
  Modelica.Electrical.Analog.Ideal.IdealDiode diodeLS_n(
    final Ron=RonDiode,
    final Goff=GoffDiode,
    final Vknee=VkneeDiode,
    final useHeatPort=useHeatPort) ;
  Modelica.Blocks.Logical.And andHSp
    ;
  Modelica.Blocks.Logical.And andLSp
    ;
  Modelica.Blocks.Logical.Not not_p
    ;
  Modelica.Blocks.Logical.And andLSn
    ;
  Modelica.Blocks.Logical.And andHSn
    ;
  Modelica.Blocks.Logical.Not not_n
    ;
equation
  if not useHeatPort then
    LossPower = transistorHS_p.LossPower + diodeHS_p.LossPower
              + transistorLS_p.LossPower + diodeLS_p.LossPower
              + transistorHS_n.LossPower + diodeHS_n.LossPower
              + transistorLS_n.LossPower + diodeLS_n.LossPower;
  end if;
  connect(transistorHS_p.p, diodeHS_p.n)
    ;
  connect(transistorHS_n.p, diodeHS_n.n)
    ;
  connect(transistorLS_n.n, diodeLS_n.p)
    ;
  connect(transistorLS_n.p, diodeLS_n.n)
    ;
  connect(transistorHS_n.n, diodeHS_n.p)
    ;
  connect(transistorLS_p.n, diodeLS_p.p)
    ;
  connect(transistorLS_p.p, diodeLS_p.n)
    ;
  connect(transistorHS_p.n, diodeHS_p.p)
    ;
  connect(transistorHS_p.n, transistorLS_p.p)
    ;
  connect(diodeHS_p.heatPort, heatPort) ;
  connect(diodeLS_p.heatPort, heatPort) ;
  connect(transistorHS_p.heatPort, heatPort) ;
  connect(transistorLS_p.heatPort, heatPort) ;
  connect(transistorLS_n.heatPort, heatPort) ;
  connect(transistorHS_n.heatPort, heatPort) ;
  connect(diodeHS_n.heatPort, heatPort) ;
  connect(diodeLS_n.heatPort, heatPort) ;
  connect(dc_p1, transistorHS_p.p)
    ;
  connect(dc_n1, transistorLS_p.n) ;
  connect(dc_n1, transistorLS_n.n)
    ;
  connect(dc_p1, transistorHS_n.p)
    ;
  connect(transistorHS_p.n, dc_p2) ;
  connect(transistorLS_n.p, dc_n2) ;
  connect(transistorHS_n.n, transistorLS_n.p)
    ;
  connect(transistorHS_p.fire, andHSp.y)
    ;
  connect(transistorLS_p.fire, andLSp.y)
    ;
  connect(andLSp.u1, not_p.y)
    ;
  connect(andLSn.y, transistorLS_n.fire)
    ;
  connect(andHSn.y, transistorHS_n.fire)
    ;
  connect(not_n.y, andLSn.u1)
    ;
  connect(enableLogic.internalEnable[1], andLSp.u2) ;
  connect(enableLogic.internalEnable[1], andLSn.u2) ;
  connect(enableLogic.internalEnable[1], andHSp.u2) ;
  connect(enableLogic.internalEnable[1], andHSn.u2) ;
  connect(fire_p, not_p.u) ;
  connect(fire_p, andHSp.u1) ;
  connect(fire_n, not_n.u) ;
  connect(fire_n, andHSn.u1) 
  ;
end HBridge;

within MagLev.DCDC.Switching.Control;
model SignalPWM
  "Generates a pulse width modulated (PWM) boolean fire signal"
  extends Modelica.Electrical.PowerConverters.Icons.Control;
  import MagLev.Types.SingleReferenceType;
  parameter Boolean useInternalSampleHold=true
    "Enables internal sample-hold";
  parameter Boolean useConstantDutyCycle=true
    "Enables constant duty cycle";
  parameter Real constantDutyCycle=0 "Constant duty cycle"
    ;
  parameter SI.Frequency f=1000 "Switching frequency";
  parameter SI.Time startTime=0 "Start time";
  parameter SingleReferenceType refType=MagLev.Types.SingleReferenceType.Sawtooth "Type of reference signal";
  parameter Boolean commonComparison=true "Common or separated comparison for fire_p and fire_n"
    ;
  Modelica.Blocks.Interfaces.RealInput dutyCycle if not
    useConstantDutyCycle "Duty cycle"
    ;
  Modelica.Blocks.Interfaces.BooleanOutput fire "Firing PWM signal"
    ;
  Modelica.Blocks.Interfaces.BooleanOutput notFire "Firing PWM signal"
    ;
  Modelica.Blocks.Sources.Constant const(final k=constantDutyCycle)
 if useConstantDutyCycle
    ;
  Modelica.Blocks.Nonlinear.Limiter limiter(uMax=1, uMin=0)
    ;

  Modelica.Blocks.Discrete.ZeroOrderHold zeroOrderHold(
     final startTime=startTime, final samplePeriod=1/f) if useInternalSampleHold
    ;
  Modelica.Blocks.Sources.SawTooth sawtooth(
    final period=1/f,
    final amplitude=1,
    final nperiod=-1,
    final offset=0,
    final startTime=startTime) if refType==SingleReferenceType.Sawtooth
    ;
  Modelica.Blocks.Sources.Trapezoid triangle(
    rising=0.5/f,
    width=0,
    falling=0.5/f,
    final period=1/f,
    final amplitude=1,
    final nperiod=-1,
    final offset=0,
    final startTime=startTime) if refType==SingleReferenceType.Triangle
    ;
  Modelica.Blocks.Logical.Greater greaterEqual_p ;
  Modelica.Blocks.Logical.Not inverse if commonComparison
    ;
  Modelica.Blocks.Math.Add add(final k1=-1, final k2=+1) if not commonComparison ;
  Modelica.Blocks.Sources.Constant constOne(final k=1) if not commonComparison ;
  Modelica.Blocks.Logical.Greater greaterEqual_n if not commonComparison ;
  Modelica.Blocks.Routing.RealPassThrough
                            realPassThrough
                                      if not useInternalSampleHold
    ;
equation
  connect(const.y, limiter.u) ;
  connect(dutyCycle, limiter.u) ;
  connect(limiter.y, zeroOrderHold.u) ;
  connect(constOne.y, add.u2)
    ;
  connect(add.y, greaterEqual_n.u1)
    ;
  connect(greaterEqual_p.y, fire)
    ;
  connect(greaterEqual_n.y, notFire)
    ;
  connect(greaterEqual_p.y, inverse.u)
    ;
  connect(inverse.y, notFire)
    ;
  connect(triangle.y, greaterEqual_p.u2) ;
  connect(triangle.y, greaterEqual_n.u2) ;
  connect(greaterEqual_n.u2, sawtooth.y) ;
  connect(greaterEqual_p.u2, sawtooth.y) ;
  connect(add.u1, greaterEqual_p.u1) ;
  connect(zeroOrderHold.y, greaterEqual_p.u1) ;
  connect(limiter.y, realPassThrough.u) ;
  connect(realPassThrough.y, greaterEqual_p.u1) 
  ;
end SignalPWM;

