  connect(converter.dc_p2, coil.pin_p) ;
  connect(speedController.y, f2i.u) ;
  connect(positionController.y, firstOrder.u) ;
  connect(f2i.y, currentController.u) ;
  connect(firstOrder.y, speedController.u) ;
  connect(f2i.fMax, speedController.yMaxVar) ;
  connect(adda.vRef, converter.vRef) ;
  connect(currentController.yMaxVar, adda.vBat)
    ;
  connect(currentController.y, adda.v)
    ;
  connect(adda.i, currentController.u_m) ;
  connect(e2d.d_der, speedController.u_m) ;
  connect(e2d.d, f2i.d) ;
  connect(e2d.d, positionController.u_m) ;
  connect(coil.flange, magnet.flange) ;
  connect(converter.vBat, adda.vSrc) ;
  connect(converter.iAct, adda.iAct) ;
  connect(referencePosition.y, positionController.u) ;
  connect(f2i.fMin, speedController.yMinVar) ;
  connect(periodicClock1.y, adda.clock) ;
  connect(periodicClock1.y, positionController.clock) ;
  connect(coil.e, e2d.e) ;
  connect(periodicClock1.y, e2d.clock) ;
  connect(adda.i, e2d.i) 
  ;
end PositionControl;

