    y(fixed=false, start=data.v0),
    kp=data.kpI,
    Ti=data.TiI,
    constantUpperLimit=false,
    symmetricLimits=false,
    yMax=data.Vsrc,
    yMin=0,
    x(fixed=true, start=data.v0/data.kpI))
                     ;
  DCDC.Switching.Converter converter(fSw=data.fSw)
      ;
  parameter ParameterRecords.DataZeltomStd data ;
  Control.F2i f2i(k=data.k,
    iC=data.iC,
    pd=data.pd,
    iMax=data.iMax,
    useSteadyStatePosition=false,         d0=data.d0)
    ;
  Control.Discrete.LimitedPI speedController(
    samplePeriod=1/data.fSw,
    startTime=0.2/data.fSw,
    y(fixed=false, start=data.f0),
    kp=data.kpv,
    Ti=data.Tiv,
    symmetricLimits=false,
    constantUpperLimit=false,
    yMax=data.fMax,
    constantLowerLimit=false,
    yMin=0,
    x(fixed=true, start=data.f0/data.kpv))
    ;
  Control.Discrete.FirstOrder firstOrder(
    samplePeriod=1/data.fSw,
    startTime=0.1/data.fSw,
    y(fixed=true, start=0),
    k=1,
    T=data.Tiv)
               ;
  Control.Discrete.PController positionController(samplePeriod=1/data.fSw, kp=data.ktuneP*data.kpP,
    d0=data.d0)                                                                                     ;
  Control.Discrete.Adda adda(samplePeriod=1/data.fSw,
    vBat0=data.Vsrc,
    vRef0=data.v0,
    i0=data.i0)                                       ;
  Control.Discrete.E2d e2d(
    samplePeriod=1/data.fSw,
    i0=data.i0,
    e0=data.e0,
    alfa=data.alfa,
    beta=data.beta,
    gamma=data.gamma) ;
  Components.Magnet magnet(
    m=data.m,
    d(fixed=true, start=data.d0),
    d_der(fixed=true)) ;
  Control.ReferencePosition referencePosition(refPos=MagLev.Types.RefPos.Trapezoid,
                                                                                offset=data.d0)
                                                                               ;
equation
  connect(voltageSource.n, ground.p) ;
  connect(voltageSource.n, converter.dc_n1) ;
  connect(voltageSource.p, converter.dc_p1) ;
  connect(converter.dc_n2, coil.pin_n) ;
  connect(converter.dc_p2, coil.pin_p) ;
  connect(speedController.y, f2i.u) ;
  connect(positionController.y, firstOrder.u) ;
  connect(f2i.y, currentController.u) ;
  connect(firstOrder.y, speedController.u) ;
  connect(f2i.fMax, speedController.yMaxVar) ;
  connect(adda.vRef, converter.vRef) ;
  connect(currentController.yMaxVar, adda.vBat)
    ;
  connect(currentController.y, adda.v)
    ;
  connect(adda.i, currentController.u_m) ;
  connect(e2d.d_der, speedController.u_m) ;
  connect(e2d.d, f2i.d) ;
  connect(e2d.d, positionController.u_m) ;
  connect(coil.flange, magnet.flange) ;
  connect(converter.vBat, adda.vSrc) ;
  connect(converter.iAct, adda.iAct) ;
  connect(referencePosition.y, positionController.u) ;
  connect(f2i.fMin, speedController.yMinVar) ;
  connect(coil.e, e2d.e) ;
  connect(adda.i, e2d.i) 
  ;
end PositionControl;

