block Microcontroller "Use as an inner block, defining the characteristics of the AVR microcontroller"
  import SIunits =
         Modelica.Units.SI;
  import Modelica_DeviceDrivers;
  import Modelica_DeviceDrivers.EmbeddedTargets.AVR.Constants;
  import Modelica_DeviceDrivers.EmbeddedTargets.AVR.Types;
  extends Modelica_DeviceDrivers.Utilities.Icons.GenericIC;
  constant Types.Platform platform ;
  constant SIunits.Frequency cpuFrequency = Constants.cpuFrequency[platform] "Default frequency is the platform default (can be modified)" ;
  constant SIunits.Frequency minADCFrequency = Constants.minADCFrequency[platform] "Minimum recommended frequency to sample the ADC" ;
  constant SIunits.Frequency maxADCFrequency = Constants.maxADCFrequency[platform] "Maximum recommended frequency to sample the ADC" ;
  constant Integer adcResolution = Constants.adcResolution[platform] "Bits of resolution in the ADC" ;
  constant SIunits.Frequency desiredFrequency=if desiredPeriod==0 then 0 else (1/desiredPeriod) "Used to try to select a reasonable default pre-scaler and counter for real-time synchronization. Select this or a period (automatically re-calculated)" ;
  constant SIunits.Time desiredPeriod=0 "Used to try to select a reasonable default pre-scaler and counter for real-time synchronization." 
  ;
end Microcontroller;

within Modelica_DeviceDrivers.EmbeddedTargets.AVR.Blocks;
block SynchronizeRealtime "A pseudo realtime synchronization"
  import SIunits =
         Modelica.Units.SI;
  import Modelica_DeviceDrivers.EmbeddedTargets.AVR.Constants;
  import Modelica_DeviceDrivers.EmbeddedTargets.AVR.Types;
  import Modelica_DeviceDrivers.EmbeddedTargets.AVR.Functions;
  outer Microcontroller mcu;
  constant SIunits.Frequency desiredFrequency=mcu.desiredFrequency "Override the MCU global real-time settings" ;
  constant Real maxError = 0.01 "Used when calculating allowed clock parameters. 0.01=1% maximum error." ;
  constant Types.TimerSelect timer ;
  constant Types.TimerPrescaler prescaler = Functions.Utilities.reasonableClockSelect(mcu.cpuFrequency, desiredFrequency, maxError, prescalerConstants) "Pre-scaler for the clock." ;
  constant Integer count = Functions.Utilities.getClockCounterValue(mcu.cpuFrequency / prescalerConstants[prescaler], desiredFrequency, maxError) "The number of counts to be made. A value of 249 counts 250 steps." ;
  constant Integer iterations = div(integer(mcu.cpuFrequency / (desiredFrequency * prescalerConstants[prescaler])),(count+1)) "The number of times each interrupt should be executed." ;
  final parameter Real actualInterval = (prescalerConstants[prescaler] * (count+1) * iterations) / mcu.cpuFrequency;
protected
  constant SIunits.Frequency prescalerConstants[Types.TimerPrescaler] = Constants.prescalerTimer[mcu.platform, timer, :];
  Functions.Timers.Timer clock = Functions.Timers.Timer(timer, prescaler, clearTimerOnMatch=false);
  Functions.RealTimeSynchronization.Init sync = Functions.RealTimeSynchronization.Init(clock, count, iterations);
algorithm
  if not initial() then
    Functions.RealTimeSynchronization.wait(sync);
  end if
;
end SynchronizeRealtime;

