  connect(Torque_Equation.y, Torque.tau)
    ;
  connect(motor.flange1, Torque_Sensor.flange_a)
    ;
  connect(Torque_Sensor.tau, motor.mech_torque) ;
  connect(Synchronous_Speed.y, motor.we) ;
