within OpenIMDML.Functions.ParameterEstimation;
function RUNInductionMotorParameterEstimation "Iterative method for estimating the induction motor equivalent
circuit parameters using only the motor nameplate data."

  import          Modelica.Units.SI;
  import         Modelica.Units.NonSI;
  import Modelica.Units.Conversions.*;
  import Complex;
  import Modelica.ComplexMath.arg;
  import Modelica.ComplexMath.real;
  import Modelica.ComplexMath.imag;
  import Modelica.ComplexMath.j;
  import Modelica.ComplexMath.abs;
  import OpenIMDML.Functions.ParameterEstimation.MotorParameterEstimationAuxiliaryFunctions.MotorParameterEstimationGaussSeidel;
  import OpenIMDML.Functions.ParameterEstimation.MotorParameterEstimationAuxiliaryFunctions.NEMALetterCode;
  import OpenIMDML.Functions.ParameterEstimation.MotorParameterEstimationAuxiliaryFunctions.NEMADesignClass;
  import OpenIMDML.Functions.ParameterEstimation.MotorParameterEstimationAuxiliaryFunctions.mean2numbers;

  // Inputs
  input Real Php = 15 "Rated Output HorsePower";
  input Real eff = 0.917 "Full Load Efficiency";
  input Real PF = 0.77 "Full Load Power Factor";
  input Real f = 60 "System Electrical Frequency";
  input Integer N = 6 "Number of Poles";
  input Real Nr = 1180 "Full Load Speed";
  input String NEMACode = "F" "NEMA Code Letter";
  input String NEMADesign = "B" "Nema Design Class";
  input Real VRated = 230 "Rated Terminal Voltage";

  // Variables
protected
   Complex I1;
   Real Pout "Rated Output HorsePower";
   Real Pin;
   Real Ploss;
   Real Sin;
   Real Qin;
   Real Ns;
   Real s;
   Real ILR;
   //output Real Pmech;
   //output Real Pstray;
   //output Real Pcore;
   Real Pmech;
   Real Pstray;
   Real Pcore;
   Real Pconv;
   //output Real PAG;
   //output Real PSCL;
   Real PAG;
   Real PSCL;
   Real PRCL;
   Real I1mag;
   Real R1;
   Real I1_r;
   Real I1_i;

  // Parameter
  //parameter Real Fmech = 0.53871877102;
  parameter Real Fmech = 0.536;
  parameter Real Fcore = 0.0;
  //parameter Real Fstray = if Pout < 91e3 then 0.018 elseif (91e3 <= Pout and Pout < 375e3) then 0.015 elseif (375e3 <= Pout and Pout < 1850e3) then 0.012 else 0.009;
  parameter Real Fstray = 0;

algorithm
  clearlog();
  Pout := Php*746;
  Pin := Pout/eff;
  Ploss := Pin - Pout;
  Sin := Pout/(eff*PF);
  Qin := sqrt(Sin^2 - Pin^2);
  I1mag := Sin/VRated;
  I1 := (Pin - j*Qin)/VRated;
  I1_r := real(I1);
  I1_i := imag(I1);
  Ns := 120*f/N;
  s := (Ns - Nr)/Ns;
  ILR := Php*(1e3*MotorParameterEstimationAuxiliaryFunctions.NEMALetterCode(
    NEMACode))/VRated;
  Pmech := Ploss*Fmech;
  Pstray := Pout*Fstray;
  Pcore := Pout*Fcore;
  Pconv := Pout + Pmech + Pstray;
  PAG := Pconv/(1-s);
  PSCL := Pin - PAG - Pcore;
  PRCL := PAG - Pconv;
  R1 := PSCL/(I1mag^2);
  Modelica.Utilities.Streams.print("(1) - Up to here it is working fine");

  MotorParameterEstimationAuxiliaryFunctions.MotorParameterEstimationGaussSeidel(
    I1_r,
    I1_i,
    R1,
    VRated,
    ILR,
    s,
    PAG,
    Qin,
    NEMADesign)
;
end RUNInductionMotorParameterEstimation;

within OpenIMDML.Functions.ParameterEstimation.MotorParameterEstimationAuxiliaryFunctions;
function mean2numbers "Mean of two values"

  input Real a;
  input Real b;
  output Real c;
algorithm

  c:= (a + b)/2
  ;
end mean2numbers;

within OpenIMDML.Functions.ParameterEstimation.MotorParameterEstimationAuxiliaryFunctions;
function MotorParameterEstimationGaussSeidel "Function that generates the parameter estimation calculation"

  import Modelica.Units.SI;
  import Modelica.Units.NonSI;
  import Modelica.Units.Conversions.*;
  import Complex;
  import Modelica.ComplexMath.arg;
  import Modelica.ComplexMath.real;
  import Modelica.ComplexMath.imag;
  import Modelica.ComplexMath.j;
  import Modelica.ComplexMath.abs;

  parameter Integer n = 10;

  // Input Variables
  input Real I1_real;
  input Real I1_imag;
  input Real R1;
  input Real VRated;
  input Real ILR;
  input Real s;
  input Real PAG;
  input Real Qin;
  input String MotorDesign;

  // Output Variables
  output Real r1;
  output Real R2_final;
  output Real X1_final;
  output Real X2_final;
  output Real XM_final;

  // Intermediate Variables
protected
  Real XLR[n];
  Real Emag;
  Real I2_real[n];
  Real I2_imag[n];
  Real E_real[n];
  Real E_imag[n];
  Real X1[n];
  Real R2[n];
  Real X2[n];
  Real XM[n];

  /*Real [:] XLR;
  Real Emag;
  Real [:] I2_real;
  Real [:] I2_imag;
  Real [:] E_real;
  Real [:] E_imag;
  Real [:] X1;
  Real [:] R2;
  Real [:] X2;
  Real [:] XM;*/

algorithm

E_real[1] := VRated;
E_imag[1] := 0;
I2_real[1] := I1_real;
I2_imag[1] := 0;
R2[1] := 0;
X2[1] := 0;
XM[1] := 0;
XLR[1] := 0;

Modelica.Utilities.Streams.print("(2) - Up to here it is working fine.");

  for i in 2:n loop
    Emag :=sqrt(E_real[i-1]^2 + E_imag[i-1]^2);
    R2[i] := s*((Emag)^2 + sqrt((Emag)^4 - 4*PAG*(X2[i-1])^2))/(2*PAG);
    XLR[i] := sqrt((VRated/ILR)^2 - (R1 + R2[i])^2);
    X1[i] := XLR[i]*NEMADesignClass(MotorDesign);
    X2[i] := XLR[i]*(1 - NEMADesignClass(MotorDesign));
    XM[i] := Emag^2/(Qin - (I1_real^2 + I1_imag^2)*X1[i] - (I2_real[i]^2 + I2_imag[i]^2)^2*X2[i]);
    E_real[i] := VRated - (I1_real*R1 - I1_imag*X1[i]);
    E_imag[i] := -(I1_imag*R1 + I1_real*X1[i]);
    I2_real[i] := ((E_real[i]*R2[i]/s) + E_imag[i]*X2[i])/((R2[i]/s)^2 + X2[i]^2);
    I2_imag[i] := ((E_imag[i]*R2[i]/s) - E_real[i]*X2[i])/((R2[i]/s)^2 + X2[i]^2);
  end for;

r1:=R1;
X1_final := X1[n];
X2_final := X2[n];
R2_final := R2[n];
XM_final := XM[n];

Modelica.Utilities.Streams.print("Estimated Parameter R1, R2, X1, X2, and Xm [ohm].")
;
end MotorParameterEstimationGaussSeidel;

within OpenIMDML.Functions.ParameterEstimation.MotorParameterEstimationAuxiliaryFunctions;
function NEMADesignClass "NEMA design class range"

input String Design;
output Real Ratio;

algorithm

Ratio := if Design == "A" then 0.5 elseif Design == "B" then 0.6 elseif Design == "C" then 0.7 else 0.5
;
