within OpenIPSL.Electrical.Banks;
model PwCapacitorBank "Capacitor Bank with Bank.2013"
  OpenIPSL.Interfaces.PwPin p
    ;
  parameter Integer nsteps "number of steps";
  parameter Types.PerUnit G=0 "Active power losses";
  parameter Types.PerUnit B=0 "Reactive power";
equation
  p.vr = (p.ir*G + p.ii*B)/(G*G + B*B);
  p.vi = ((-p.ir*B) + p.ii*G)/(G*G + B*B)
  ;
end PwCapacitorBank;

within OpenIPSL.Electrical.Banks;
model PwCapacitorBankWithModification "Capacitor Bank with Bank modification at time t1.
              2014/03/10"
  OpenIPSL.Interfaces.PwPin p
    ;
  parameter Integer nsteps "Number of steps";
  parameter Types.PerUnit Go "Active power losses in each element";
  parameter Types.PerUnit Bo "Reactive power in each element";
  parameter Types.Time t1 "Time for bank Modification";
  parameter Integer nmod "Number of step to switch on/off (+/-)";
  Types.PerUnit G;
  Types.PerUnit B;
  Integer nt;
equation
  if time > t1 then
    nt = nsteps + nmod;
  else
    nt = nsteps;
  end if;
  G = nt*Go;
  B = nt*Bo;
  p.vr = (p.ir*G + p.ii*B)/(G*G + B*B);
  p.vi = ((-p.ir*B) + p.ii*G)/(G*G + B*B)
  ;
end PwCapacitorBankWithModification;

within OpenIPSL.Electrical.Banks;
model PwShunt "Thyristor controlled Shunt reactor/capacitor"
  OpenIPSL.Interfaces.PwPin p
    ;
  Modelica.Blocks.Interfaces.RealInput Q
    "Reactive power produced by the shunt [pu]"
    ;
  parameter Types.Frequency fn=50 "Frequency rating";
  Types.PerUnit c "Capacitance";
  Types.PerUnit l "Inductance";
  Types.PerUnit v;
  Types.Angle anglev;
  Types.PerUnit i;
  Types.Angle anglei;
equation
  v = sqrt(p.vr^2 + p.vi^2);
  anglev = atan2(p.vi, p.vr);
  i = sqrt(p.ir^2 + p.ii^2);
  anglei = atan2(p.ii, p.ir);
  if Q >= 0 then
    c = Q/(v^2*2*C.pi*fn);
    l = 0;
    anglei = anglev + C.pi/2;
    i = v*2*C.pi*fn*c;
  else
    l = v^2/(2*C.pi*fn*(-Q));
    c = 0;
    anglei = anglev - C.pi/2;
    i = v/(2*C.pi*fn*l);
  end if

  ;
end PwShunt;

