within OpenIPSL.Electrical.Branches;
model PwLine "Model for a transmission Line based on the pi-equivalent circuit"
  outer OpenIPSL.Electrical.SystemBase SysData;
  import Modelica.ComplexMath.conj;
  import Modelica.ComplexMath.real;
  import Modelica.ComplexMath.imag;
  import Modelica.ComplexMath.j;
  OpenIPSL.Interfaces.PwPin_p p ;
  OpenIPSL.Interfaces.PwPin_n n ;
  parameter Types.PerUnit R "Resistance"
    ;
  parameter Types.PerUnit X "Reactance"
    ;
  parameter Types.PerUnit G "Shunt half conductance"
    ;
  parameter Types.PerUnit B "Shunt half susceptance"
    ;
  parameter Types.ApparentPower S_b=SysData.S_b
    "System base power"
    ;
  parameter Types.Time t1=Modelica.Constants.inf
    ;
  parameter Types.Time t2=Modelica.Constants.inf
    ;
  parameter Integer opening=1 ;
  parameter Boolean displayPF=false "Display power flow results:" ;
  Types.ActivePower P12;
  Types.ActivePower P21;
  Types.ReactivePower Q12;
  Types.ReactivePower Q21;
  Complex vs(re=p.vr, im=p.vi);
  Complex is(re=p.ir, im=p.ii);
  Complex vr(re=n.vr, im=n.vi);
  Complex ir(re=n.ir, im=n.ii);
protected
  parameter Complex Y(re=G, im=B);
  parameter Complex Z(re=R, im=X);
equation
  //Calculations for the power flow display
  P12 = real(vs*conj(is))*S_b;
  P21 = -real(vr*conj(ir))*S_b;
  Q12 = imag(vs*conj(is))*S_b;
  Q21 = -imag(vr*conj(ir))*S_b;
  //PI model with different line openings
  if time >= t1 and time < t2 then
    if opening == 1 then
      is = Complex(0);
      ir = Complex(0);
    elseif opening == 2 then
      is = Complex(0);
      ir = (vr - ir*Z)*Y;
    else
      ir = Complex(0);
      is = (vs - is*Z)*Y;
    end if;
  else
    vs - vr = Z*(is - vs*Y);
    vr - vs = Z*(ir - vr*Y);
  end if
  ;
end PwLine;

within OpenIPSL.Electrical.Branches.Generic;
model ULTC "Discrete tap changer based on Hisken"
  parameter Real m0 = 1.0375 "Initial tap ratio, from power flow";
  parameter Types.Time Ttap = 20 "Time delay of tap change";
  parameter Types.PerUnit vlow = 1.04 "Lower voltage deadband";
  parameter Types.PerUnit vhigh = 1.06 "Upper voltage deadband";
  parameter Real m_max = 1.1 "Maximum tap position";
  parameter Real m_min = 0.9 "Minimum tap position";
  parameter Real m_step = 0.0125 "Step size";
  Real m(start = m0, fixed = true) "Tap ratio";
  Types.PerUnit vk "Voltage at primary";
  Types.PerUnit vm "Voltage at secondary";
  Types.Angle anglevk "Angle at primary";
  Types.Angle anglevm "Angle at secondary ";
  Types.Time x1(start = 0, fixed = true) "Timer";
  Real y1;
  Real y2;
  Real y3;
  Real y4;
  Real y5;
  Real y7;
  Real y6;
  Boolean y2l0 "Loop breaker for when-clauses";
  Boolean y3l0 "Loop breaker for when-clauses";
  Modelica.Blocks.Logical.ZeroCrossing zeroCrossing(enable = true) ;
  Interfaces.PwPin p ;
  Interfaces.PwPin n ;
equation
  n.vi = p.vi * m;
  n.vr = p.vr * m;
  p.ir + n.ir * m = 0;
  p.ii + n.ii * m = 0;
  vk = sqrt(p.vr ^ 2 + p.vi ^ 2);
  vm = sqrt(n.vr ^ 2 + n.vi ^ 2);
  anglevk = atan2(p.vi, p.vr);
  anglevm = atan2(n.vi, n.vr);
  der(x1) = y1 * y7;
  y2 + vlow - vm = 0;
  y3 - vhigh + vm = 0;
  y6 - m + m_max - m_step / 2 = 0;
  y4 - m + m_min - m_step / 2 = 0;
  y5 - x1 + Ttap = 0;
  if y2 < 0 or y3 <0 then
    y1 = 1;
  else
    y1 = 0;
  end if;
  if y6 < 0 and vm < vlow then
    y7 = 1;
  elseif y4 > 0 and vm > vhigh then
    y7 = 1;
  else
    y7 = 0;
  end if;
  y2l0 = y2 < 0;
  y3l0 = y3 < 0;
  zeroCrossing.u = y5;
  when zeroCrossing.y and pre(y2l0) then
    reinit(x1, 0);
    m = pre(m) + m_step;
  elsewhen zeroCrossing.y and pre(y3l0) then
    reinit(x1, 0);
    m = pre(m) - m_step;
  end when
  ;
end ULTC;

within OpenIPSL.Electrical.Branches.PSAT;
model PhaseShiftingTransformer "Phase Shifting Transformer (PST)"

  model PhaseShifter "Controller for shifting the phase (internal model)"
    parameter Types.PerUnit pref=0.01 "Desired power flow"
      ;
    parameter Real Kp=0.5 "Proportional gain"
      ;
    parameter Real Ki=0.1 "Integral gain"
      ;
    parameter Types.Time Tm=0.001 "Measurement time constant"
      ;
    parameter Types.Angle alpha_max=C.pi/2 "Maximum phase angle"
      ;
    parameter Types.Angle alpha_min=-C.pi/2 "Minimum phase angle"
      ;
    parameter Types.PerUnit pmes0=0.01 "Initial measured power flow"
      ;
    parameter Types.Angle alpha0=0 "Initial phase shifting angle"
      ;

    outer Types.PerUnit pk "Actual secondary power flow";
    Types.PerUnit pmes(start=pmes0) "Measured power flow";
    Types.Angle alpha(start=alpha0) "Shifting angle";

  Interfaces.PwPin p
    ;
  Interfaces.PwPin n ;
  equation
    if alpha > alpha_max and der(pmes) > 0 then
    der(alpha) = 0;
    der(pmes) = (pk - pmes)/Tm;
    p.vr = n.vr*cos(alpha_max) - n.vi*sin(alpha_max);
    p.vi = n.vr*sin(alpha_max) + n.vi*cos(alpha_max);

  elseif alpha < alpha_min and der(pmes) < 0 then
    der(alpha) = 0;
    der(pmes) = (pk - pmes)/Tm;
    p.vr = n.vr*cos(alpha_min) - n.vi*sin(alpha_min);
    p.vi = n.vr*sin(alpha_min) + n.vi*cos(alpha_min);
  else
    der(alpha) = Kp*(pk - pmes)/Tm + Ki*(pmes - pref);
    der(pmes) = (pk - pmes)/Tm;
    p.vr = n.vr*cos(alpha) - n.vi*sin(alpha);
    p.vi = n.vr*sin(alpha) + n.vi*cos(alpha);
  end if;
  p.ir + n.ir = 0;
  p.ii + n.ii = 0;

  end PhaseShifter;

  parameter Types.ApparentPower S_b=SysData.S_b "System base power"
    ;
  parameter Types.Voltage V_b=40e3 "Sending end bus voltage"
    ;
  parameter Types.ApparentPower Sn=SysData.S_b "Power rating"
    ;
  parameter Types.Voltage Vn=40e3 "Voltage rating"
    ;
  parameter Types.PerUnit rT=0.01 "Resistance (transformer base)"
    ;
  parameter Types.PerUnit xT=0.1 "Reactance (transformer base)"
    ;
  parameter Real m=1.0 "Optional fixed tap ratio"
    ;
  parameter Types.PerUnit pref=0.01 "Desired power flow"
    ;
  parameter Real Kp=0.5 "Proportional gain"
    ;
  parameter Real Ki=0.1 "Integral gain"
    ;
  parameter Types.Time Tm=0.001 "Measurement time constant"
    ;
  parameter Types.Angle alpha_max=C.pi/2 "Maximum phase angle"
    ;
  parameter Types.Angle alpha_min=-C.pi/2 "Minimum phase angle"
    ;
  parameter Types.PerUnit pmes0=0.01 "Initial measured power flow"
    ;
  parameter Types.Angle alpha0=0 "Initial phase shifting angle"
    ;

  outer OpenIPSL.Electrical.SystemBase SysData;
  inner Types.PerUnit pk "Actual primary power flow";
  Types.Angle anglevk "Angle at primary";
  Types.Angle anglevm "Angle at secondary";
  Types.PerUnit vk "Voltage at primary";
  Types.PerUnit vm "Voltage at secondary";

  TwoWindingTransformer twoWindingTransformer(
    S_b=S_b,
    V_b=V_b,
    Sn=Sn,
    Vn=Vn,
    rT=rT,
    xT=xT,
    m=m) ;
  PhaseShifter phaseShifter(
    pref=pref,
    Kp=Kp,
    Ki=Ki,
    Tm=Tm,
    alpha_max=alpha_max,
    alpha_min=alpha_min,
    pmes0=pmes0,
    alpha0=alpha0) ;
  Interfaces.PwPin n ;
  Interfaces.PwPin p ;
equation
  vk = sqrt(p.vr^2 + p.vi^2);
  vm = sqrt(n.vr^2 + n.vi^2);
  anglevk = atan2(p.vi, p.vr);
  anglevm = atan2(n.vi, n.vr);
  pk=p.vr*p.ir + p.vi*p.ii;

  connect(twoWindingTransformer.p, p) ;
  connect(twoWindingTransformer.n, phaseShifter.p) ;
  connect(phaseShifter.n, n) 
  ;
end PhaseShiftingTransformer;

