  parameter Real m0=0.98 "Initial tap ratio [pu/pu]"
    ;
  parameter Real m_max=0.98 "Maximum tap ratio [pu/pu]"
    ;
  parameter Real m_min=0.9785 "Minimum tap ratio [pu/pu]"
    ;
  parameter Types.PerUnit H=0.001 "Integral deviation"
