  parameter Types.Voltage V2=Vn/kT "Secondary voltage";
  parameter Types.Impedance Zn = Vn^2/Sn "Transformer base impedance";
  parameter Types.Impedance Zb = Vbus1^2/S_b "System base impedance";
  parameter Types.PerUnit r = rT * Zn/Zb "Resistance(system base)";
  parameter Types.PerUnit x = xT * Zn/Zb "Reactance(system base)";
  parameter Types.PerUnit vref=v_ref*(V2/Vbus2);
initial equation
  m = m0;
equation
  vk = sqrt(p.vr^2 + p.vi^2);
  vm = sqrt(n.vr^2 + n.vi^2);
  anglevk = atan2(p.vi, p.vr);
  anglevm = atan2(n.vi, n.vr);
  if m > m_max and der(m) > 0 then
    r*p.ir - x*p.ii = 1/m_max^2*p.vr - 1/m_max*n.vr;
    r*p.ii + x*p.ir = 1/m_max^2*p.vi - 1/m_max*n.vi;
    r*n.ir - x*n.ii = n.vr - 1/m_max*p.vr;
    x*n.ir + r*n.ii = n.vi - 1/m_max*p.vi;
    der(m) = 0;
  elseif m < m_min and der(m) < 0 then
    r*p.ir - x*p.ii = 1/m_min^2*p.vr - 1/m_min*n.vr;
    r*p.ii + x*p.ir = 1/m_min^2*p.vi - 1/m_min*n.vi;
    r*n.ir - x*n.ii = n.vr - 1/m_min*p.vr;
    x*n.ir + r*n.ii = n.vi - 1/m_min*p.vi;
    der(m) = 0;
  else
    r*p.ir - x*p.ii = 1/m^2*p.vr - 1/m*n.vr;
    r*p.ii + x*p.ir = 1/m^2*p.vi - 1/m*n.vi;
    r*n.ir - x*n.ii = n.vr - 1/m*p.vr;
    x*n.ir + r*n.ii = n.vi - 1/m*p.vi;
    der(m) = (-H*m) + K*(vm - vref);
  end if
  ;
end ULTC_VoltageControl;

within OpenIPSL.Electrical.Branches.PSSE;
model TwoWindingTransformer
  "Static Two-winding transformer according to PSS/E, without phase shift"
  outer OpenIPSL.Electrical.SystemBase SysData;
  import Modelica.ComplexMath.j;
  import Modelica.ComplexMath.conj;
  OpenIPSL.Interfaces.PwPin p ;
  OpenIPSL.Interfaces.PwPin n ;
  parameter Types.ApparentPower S_b=SysData.S_b "System base power"
    ;
  parameter Integer CZ=1 "Impedance I/O code" ;
  parameter Types.PerUnit R "Specified R"
    ;
  parameter Types.PerUnit X "Specified X"
    ;
  parameter Types.PerUnit G "Magnetizing G"
    ;
  parameter Types.PerUnit B "Magnetizing B"
    ;
  parameter Integer CW=1 "Winding I/O code" ;
  parameter Types.PerUnit t1=1 "Ratio of winding 1"
    ;
  parameter Types.Voltage VNOM1=0 "Nominal voltage of winding 1"
    ;
  parameter Types.Voltage VB1=300e3 "Bus base voltage of winding 1"
    ;
  parameter Types.PerUnit t2=1 "Tap ratio of winding 2"
    ;
  parameter Types.Voltage VNOM2=0 "Nominal Voltage of winding 2"
    ;
  parameter Types.Voltage VB2=300e3 "Bus base voltage of winding 2"
    ;
  parameter Types.Angle ANG1=0 "Winding (1-2) Angle"
    ;
  parameter Types.ApparentPower S_n=S_b "Nominal power of the winding"
    ;
protected
  parameter Types.Voltage VNOM1_int=if abs(VNOM1) < Modelica.Constants.eps then VB1
       else VNOM1;
  parameter Types.Voltage VNOM2_int=if abs(VNOM2) < Modelica.Constants.eps then VB2
       else VNOM2;
  parameter Types.PerUnit r=if CZ == 1 then R else R*S_b/S_n;
  parameter Types.PerUnit x=if CZ == 1 then X else X*S_b/S_n;
  parameter Complex t=T1/T2*(cos(ANG1) + j*sin(ANG1));
  parameter Types.PerUnit T2=if CW == 1 then t2 elseif CW == 3 then t2*(VNOM2_int/VB2)
       else t2/VB2;
  parameter Types.PerUnit T1=if CW == 1 then t1 elseif CW == 3 then t1*(VNOM1_int/VB1)
       else t1/VB1;
  parameter Complex Ym(re=G, im=B);
  parameter Complex xeq(re=r*abs(T2)^2, im=x*abs(T2)^2);
  Complex ei(re=p.vr, im=p.vi);
  Complex ej(re=n.vr, im=n.vi);
  Complex ii(re=p.ir, im=p.ii);
  Complex ij(re=n.ir, im=n.ii);
equation
  ej = ei/t + xeq*ij;
  (ii - ei*Ym)*conj(t) = -ij
  ;
end TwoWindingTransformer;

within OpenIPSL.Electrical.Branches.Simulink.LTC;
model LTC "Load tap changing transformer branch"
  Modelica.Blocks.Continuous.LimIntegrator imLimitedIntegrator(
    outMax=1,
    k=1,
    outMin=-delay1,
    y_start=-delay1,
    initType=Modelica.Blocks.Types.Init.InitialOutput)
    ;
  LTC_deadband deadband1(Uplim=Uplim, Downlim=Downlim)
    ;
  parameter Real Uplim=0.01;
  parameter Real Downlim=-0.01;
  parameter Real Ymin=0.88 "Min Ratio";
  parameter Real Ymax=1.2 "Max Ratio";
  parameter Real delay1;
  parameter Real delay2;
  parameter Real positionNo=33;
  parameter Real r0=1 "Transformer Ratio";
  LTC_switch lTC_switch
    ;
  Modelica.Blocks.Sources.Constant imSetPoint(k=0)
    ;
  Modelica.Blocks.Sources.Constant imSetPoint1(k=1)
    ;
  Modelica.Blocks.Interfaces.RealOutput r ;
  LTC_lookup lTC_lookup(Uplim=Uplim, Downlim=Downlim)
    ;
  Modelica.Blocks.Continuous.LimIntegrator imLimitedIntegrator1(
    outMin=Ymin,
    outMax=Ymax,
    k=(Ymax - Ymin)/(positionNo*delay2),
    y_start=r0,
    initType=Modelica.Blocks.Types.Init.InitialOutput)
    ;
  LTC_quantizer lTC_quantizer
    ;
  Modelica.Blocks.Interfaces.RealInput u ;
  Modelica.Blocks.Math.Add add(k2=-1)
    ;
equation
  connect(lTC_lookup.out, lTC_switch.LTCin) ;
  connect(r, lTC_quantizer.n) ;
  connect(imLimitedIntegrator1.y, lTC_quantizer.p)
    ;
  connect(imLimitedIntegrator1.u, lTC_switch.r) ;
  connect(imLimitedIntegrator.y, lTC_switch.Signalin)
    ;
  connect(deadband1.signal, imLimitedIntegrator.u) ;
  connect(imSetPoint.y, lTC_switch.Normalin) ;
  connect(add.y, deadband1.u)
    ;
  connect(lTC_lookup.u, deadband1.u) ;
  connect(add.u1, u)
    ;
  connect(imSetPoint1.y, add.u2) 
  ;
end LTC;

