within OpenIPSL.Electrical.Controls.PSAT.AVR;
model AVRTypeI "PSAT AVR Type 1"

  Modelica.Blocks.Interfaces.RealInput v "Generator termminal voltage [pu]"
    ;
  Modelica.Blocks.Interfaces.RealOutput vf "Field voltage [pu]" ;
  Modelica.Blocks.Interfaces.RealInput vref
    "Reference generator terminal voltage [pu]" ;
  parameter Types.PerUnit vrmax=7.57 "Maximum regulator voltage";
  parameter Types.PerUnit vrmin=0 "Minimum regulator voltage";
  parameter Real K0=7.04 "Regulator gain, [pu/pu]";
  parameter Types.Time T1=6.67 "First pole";
  parameter Types.Time T2=1 "First zero";
  parameter Types.Time T3=1 "Second pole";
  parameter Types.Time T4=1 "Second pole";
  parameter Types.Time Te=0.4 "Field circuit time constant";
  parameter Types.Time Tr=0.05 "Measurement time constant";
  parameter Real Ae=0.0006 "1st ceiling coefficient";
  parameter Real Be=0.9 "2nd ceiling coefficient";
  parameter Types.PerUnit v0=1 "Initialization";
protected
  parameter Types.PerUnit vf00(fixed=false) "Initialization";
  parameter Types.PerUnit vr0=vf00 - Ae*Modelica.Math.exp(Be*abs(vf00)) "Initialization";
public
  Modelica.Blocks.Interfaces.RealOutput vref0 "Voltage reference at t=0 [pu]"
    ;
  Modelica.Blocks.Interfaces.RealInput vf0
    "Reference generator terminal voltage [pu]" ;
  Modelica.Blocks.Math.Feedback feedback
    ;
  Modelica.Blocks.Continuous.FirstOrder firstOrder(
    y_start=vf00,
    initType=Modelica.Blocks.Types.Init.InitialOutput,
    k=1,
    T=Te) ;
  NonElectrical.Nonlinear.CeilingBlock ceilingBlock
    ;
  Modelica.Blocks.Continuous.FirstOrder firstOrder2(
    k=1,
    T=Tr,
    initType=Modelica.Blocks.Types.Init.InitialOutput,
    y_start=v0)
    ;
  Modelica.Blocks.Math.Feedback feedback2
    ;
  Modelica.Blocks.Continuous.TransferFunction transferFunction(
    b={(K0*T2*T4),K0*(T2 + T4),K0},
    a={(T1*T3),(T1 + T3),1},
    initType=Modelica.Blocks.Types.Init.InitialOutput,
    y_start=vr0)
    ;
  Modelica.Blocks.Nonlinear.Limiter limiter(uMax=vrmax, uMin=vrmin)
    ;
initial algorithm
  vf00 := vf0;
algorithm
  vref0 := v0 + (vr0/K0);

equation
  connect(firstOrder.y, vf)
    ;
  connect(ceilingBlock.u, vf) ;
  connect(ceilingBlock.y, feedback.u2)
    ;
  connect(v, firstOrder2.u) ;
  connect(feedback2.u2, firstOrder2.y) ;
  connect(feedback2.u1, vref) ;
  connect(feedback.y, firstOrder.u)
    ;
  connect(feedback2.y, transferFunction.u)
    ;
  connect(transferFunction.y, limiter.u)
    ;
  connect(limiter.y, feedback.u1)

  ;
end AVRTypeI;

within OpenIPSL.Electrical.Controls.PSAT.AVR;
model AVRTypeII "PSAT AVR Type 2"

  Modelica.Blocks.Interfaces.RealInput v "Generator terminal voltage [pu]"
    ;
  Modelica.Blocks.Interfaces.RealOutput vf "Field voltage [pu]" ;
  Modelica.Blocks.Interfaces.RealInput vref
    "Reference generator terminal voltage [pu]" ;
  parameter Types.PerUnit vrmin=-5 "Minimum regulator voltage";
  parameter Types.PerUnit vrmax=5 "Maximum regulator voltage";
  parameter Real Ka=100 "Amplifier gain [pu/pu]";
  parameter Types.Time Ta=0.5 "Amplifier time constant";
  parameter Real Kf=0.15 "Stabilizer gain [pu/pu]";
  parameter Types.Time Tf=0.1 "Stabilizer time constant";
  parameter Real Ke=0 "Field circuit integral deviation [pu/pu]";
  parameter Types.Time Te=0.2 "Field circuit time constant";
  parameter Types.Time Tr=0.001 "Measurement time constant";
  parameter Real Ae=0.0006 "1st ceiling coefficient";
  parameter Real Be=0.9 "2nd ceiling coefficient";
  parameter Types.PerUnit v0=1 "Initial measured voltage";
protected
  parameter Types.PerUnit vfstate=vr10 - (Ae*Modelica.Math.exp(Be*
      abs(vf00))*vf00);
  parameter Types.PerUnit vf00(fixed=false) "Initialization of vf";
  parameter Types.PerUnit vr10=Ke*vf00 + Ae*Modelica.Math.exp(Be*abs(
      vf00))*vf00 "Initialization";
  parameter Types.PerUnit vr20=-vf00*Kf/Tf "Initialization";
public
  Modelica.Blocks.Interfaces.RealOutput vref0 "Voltage reference at t=0 [pu]"
    ;
  Modelica.Blocks.Interfaces.RealInput vf0
    "Reference generator terminal voltage [pu]" ;
  Modelica.Blocks.Math.Feedback feedback
    ;
  Modelica.Blocks.Continuous.TransferFunction ExcitationSystem(
    y_start=vf00,
    a={Te,Ke},
    x_start={vfstate},
    initType=Modelica.Blocks.Types.Init.InitialOutput)
    ;
  NonElectrical.Nonlinear.CeilingBlock ceilingBlock(Ae=Ae, Be=Be)
    ;
  Modelica.Blocks.Continuous.Derivative derivativeBlock(
    y_start=0,
    initType=Modelica.Blocks.Types.Init.SteadyState,
    T=Tf,
    x_start=vf00,
    k=Kf) ;
  Modelica.Blocks.Math.Feedback feedback1
    ;
  Modelica.Blocks.Continuous.FirstOrder firstOrder2(
    k=1,
    T=Tr,
    y_start=v0,
    initType=Modelica.Blocks.Types.Init.SteadyState) ;
  Modelica.Blocks.Math.Feedback Verr
    ;
  NonElectrical.Continuous.SimpleLagLim simpleLagLim(
    outMax=vrmax,
    outMin=vrmin,
    K=Ka,
    T=Ta,
    y_start=vr10)
    ;
initial algorithm
  vf00 := vf0;
algorithm
  vref0 := v0 + vr10/Ka;

equation
  connect(ExcitationSystem.y, vf)
    ;
  connect(ceilingBlock.y, feedback.u2)
    ;
  connect(v, firstOrder2.u) ;
  connect(Verr.u2, firstOrder2.y)
    ;
  connect(Verr.y, feedback1.u1)
    ;
  connect(Verr.u1, vref) ;
  connect(feedback.y, ExcitationSystem.u)
    ;
  connect(ceilingBlock.u, vf) ;
  connect(derivativeBlock.u, vf) ;
  connect(feedback1.u2, derivativeBlock.y) ;
  connect(feedback1.y, simpleLagLim.u)
    ;
  connect(simpleLagLim.y, feedback.u1)

  ;
end AVRTypeII;

within OpenIPSL.Electrical.Controls.PSAT.AVR;
model AVRtypeIII "PSAT AVR Type 3"
  parameter Types.PerUnit vfmax=5;
  parameter Types.PerUnit vfmin=-5;
  parameter Types.PerUnit K0=20 "regulator gain";
  parameter Types.Time T2=0.1 "regulator pole";
  parameter Types.Time T1=0.45 "Regulator zero";
  parameter Types.Time Te=0.1 "Field circuit time constant";
  parameter Types.Time Tr=0.0015 "Measurement time constant";
  Real vm;
  Real vr;
  Real vf1;
  Modelica.Blocks.Nonlinear.Limiter limiter1(uMax=vfmax, uMin=vfmin)
    ;
  Modelica.Blocks.Interfaces.RealInput v(start=1) ;
  Modelica.Blocks.Interfaces.RealOutput vf ;
  Modelica.Blocks.Interfaces.RealInput vs ;
  Modelica.Blocks.Interfaces.RealInput vf0(start=1) ;
protected
  parameter Types.PerUnit vref(fixed=false);
  parameter Types.PerUnit s0(fixed=false);
initial equation
  vref = v;
  s0 = vs;
  vf1 = vf0;
  vm = v;
  vr = K0*(1 - T1/T2)*(vref + vs - vm);
equation
  der(vm) = (v - vm)/Tr;
  der(vr) = (K0*(1 - T1/T2)*(vref + vs - vm) - vr)/T2;
  der(vf1) = ((vr + K0*(T1/T2)*(vref + vs - vm) + vf0)*(1 + s0*(v/vm - 1)) -
    vf1)/Te;
  limiter1.u = vf1;
  limiter1.y = vf
  ;
end AVRtypeIII;

within OpenIPSL.Electrical.Controls.PSAT.OEL;
model FieldCurrent
  "Estimates the field current from P,Q,V and the d- and q-axis reactances"

  Modelica.Blocks.Interfaces.RealInput v "generator terminal voltage [pu]"
    ;
  Modelica.Blocks.Interfaces.RealInput p "active power [pu]" ;
  Modelica.Blocks.Interfaces.RealInput q "reactive power [pu]" ;
  Modelica.Blocks.Interfaces.RealOutput ifield "estimated field current [pu]"
    ;
  parameter Types.PerUnit xd;
  parameter Types.PerUnit xq;
protected
  Real gamma_p;
  Real gamma_q;
equation
  gamma_p = xq*p/v;
  gamma_q = xq*q/v;
  ifield = sqrt((v + gamma_q)^2 + p^2) + ((xd/xq - 1)*(gamma_q*(v + gamma_q) +
    gamma_p^2)/sqrt((v + gamma_q)^2 + p^2))

  ;
end FieldCurrent;

within OpenIPSL.Electrical.Controls.PSAT.OEL;
model OEL "PSATs Over-Excitation Limiter"
  outer OpenIPSL.Electrical.SystemBase SysData;
  Modelica.Blocks.Interfaces.RealInput v "Generator terminal voltage [pu]"
    ;
  Modelica.Blocks.Interfaces.RealInput p "Active power [pu]" ;
  Modelica.Blocks.Interfaces.RealInput q "Reactive power [pu]" ;
  FieldCurrent field_current(xd=Z_MBtoSB*xd, xq=Z_MBtoSB*xq)
    ;
  Modelica.Blocks.Interfaces.RealOutput v_ref ;
  parameter Types.Time T0=10 "Integrator time constant";
  parameter Types.PerUnit xd "d-axis estimated generator reactance (machine base)";
  parameter Types.PerUnit xq "q-axis estimated generator reactance (machine base)";
  parameter Types.PerUnit if_lim "Maximum field current (system base)";
  parameter Types.PerUnit vOEL_max "Maximum output signal (machine base)";
  parameter Types.ApparentPower Sn=SysData.S_b "Power rating" ;
  parameter Types.Voltage Vn=V_b "Voltage rating"
    ;
  parameter Types.Voltage V_b=400e3 "Base voltage of the bus";

  Modelica.Blocks.Math.Feedback add
    ;
  Modelica.Blocks.Sources.Constant currentLimit(k=if_lim) ;
  Modelica.Blocks.Continuous.LimIntegrator limIntegrator(
    k=1/T0,
    outMax=vOEL_max,
    outMin=0,
    strict=true)
    ;
  Modelica.Blocks.Interfaces.RealInput v_ref0 "Generator terminal voltage [pu]"
    ;
  Modelica.Blocks.Math.Feedback difference ;
protected
  parameter Real Z_MBtoSB=(SysData.S_b*Vn^2)/(Sn*V_b^2)
    "Z(machine base) -> Z(system base)";
  parameter Real I_MBtoSB=(Sn*V_b)/(SysData.S_b*Vn)
    "I(machine base) -> I(system base)";

equation
  connect(field_current.ifield, add.u1)
    ;
  connect(currentLimit.y, add.u2) ;
  connect(v_ref, difference.y)
    ;
  connect(field_current.v, v) ;
  connect(limIntegrator.y, difference.u2) ;
  connect(difference.u1, v_ref0) ;
  connect(p, field_current.p) ;
  connect(q, field_current.q) ;
  connect(add.y, limIntegrator.u)

  ;
end OEL;

