    ;
  Modelica.Blocks.Interfaces.RealInput Vg "Voltage magnitude
of the generator to which the PSS is connected through the AVR"
    ;
  OpenIPSL.NonElectrical.Continuous.DerivativeLag
                                         derivativeLag(
    T=Tw,
    y_start=0,
    x_start=0,
    K=Tw)
    ;
