within OpenIPSL.Electrical.Controls.PSAT.TG;
model TGTypeI "TG Type I"
  Modelica.Blocks.Interfaces.RealInput w "Rotor speed [pu]" ;
  Modelica.Blocks.Interfaces.RealOutput pm "Mechanical power [pu]" ;
  parameter Types.PerUnit wref=1 "Speed reference";
  parameter Types.PerUnit pref "Active power reference";
  parameter Types.PerUnit R "Droop";
  parameter Types.PerUnit pmax "Maximum turbine output";
  parameter Types.PerUnit pmin "Minimum turbine output";
  parameter Types.Time Ts "Governor time constant";
  parameter Types.Time Tc "Servo time constant";
  parameter Types.Time T3 "Transient gain time constant";
  parameter Types.Time T4 "Power fraction time constant";
  parameter Types.Time T5 "Reheat time constant";
  Types.PerUnit pin "Turbine output";
protected
  parameter Types.PerUnit pin0=pref "Initialization";
  parameter Types.PerUnit xg10=pin0 "Initialization";
  parameter Types.PerUnit xg20=(1 - T3/Tc)*xg10 "Initialization";
  parameter Types.PerUnit xg30=(1 - T4/T5)*(xg20 + T3*xg10/Tc) "Initialization";
  Types.PerUnit pinstar;
  Types.PerUnit xg1(start=xg10, fixed=true);
  Types.PerUnit xg2(start=xg20, fixed=true);
  Types.PerUnit xg3(start=xg30, fixed=true);
equation
  pinstar = pref + (wref - w)/R;
  if pinstar >= pmin and pinstar <= pmax then
    pin = pinstar;
  elseif pinstar > pmax then
    pin = pmax;
  else
    pin = pmin;
  end if;
  der(xg1) = (pin - xg1)/Ts;
  der(xg2) = ((1 - T3/Tc)*xg1 - xg2)/Tc;
  der(xg3) = ((1 - T4/T5)*(xg2 + T3*xg1/Tc) - xg3)/T5;
  pm = xg3 + (xg2 + T3*xg1/Tc)*T4/T5
  ;
end TGTypeI;

within OpenIPSL.Electrical.Controls.PSAT.TG;
model TGTypeII "TG Type II"
  Modelica.Blocks.Interfaces.RealInput pm0 "Initial mechanical power [pu]"
    ;
  Modelica.Blocks.Interfaces.RealOutput pm "Mechanical power [pu]" ;
  Modelica.Blocks.Interfaces.RealInput w "Rotor speed [pu]" ;
  Modelica.Blocks.Math.Add add1(k2=-1) ;
  Modelica.Blocks.Continuous.TransferFunction transferFunction1(a={Ts,1}, b={T3,
        1}) ;
  parameter Types.PerUnit wref=1 "Reference speed";
  parameter Types.PerUnit R=0.2 "Droop";
  parameter Types.PerUnit pmax0=1 "Maximum turbine output";
  parameter Types.PerUnit pmin0=0 "Minimum turbine output";
  parameter Types.Time Ts=0.1 "Governor Time constant";
  parameter Types.Time T3=-0.1 "Transient gain time constant";
  parameter Types.ApparentPower S_b=100e6 "System base power"
    ;
  parameter Types.ApparentPower Sn=20e6 "Nominal power";
  Modelica.Blocks.Math.Gain gain1(k=1/Ro) ;
  Modelica.Blocks.Sources.Constant const(k=wref) ;
  Modelica.Blocks.Math.Add add2 ;
  Modelica.Blocks.Nonlinear.Limiter limiter1(uMax=pmax, uMin=pmin) ;
protected
  parameter Real Ro=R*S_b/Sn;
  parameter Real pmax=pmax0*Sn/S_b;
  parameter Real pmin=pmin0*Sn/S_b;
equation

  connect(add2.u1, pm0) ;
  connect(add1.u1, const.y) ;
  connect(w, add1.u2) ;
  connect(add2.u2, transferFunction1.y) ;
  connect(gain1.y, transferFunction1.u) ;
  connect(add1.y, gain1.u) ;
  connect(add2.y, limiter1.u) ;
  connect(limiter1.y, pm) 
  ;
end TGTypeII;

within OpenIPSL.Electrical.Controls.PSAT.TG;
model TGTypeIII
  "Hydro Turbine (Linear model) and Governor (Standard model)- control scheme Type 3"
  parameter Types.PerUnit P_0 "Active power"
    ;
  parameter Types.PerUnit wref=1 "Reference speed";
  parameter Types.PerUnit Tg "Pilot valve droop";
  parameter Types.PerUnit gmax "Maximum gate opening";
  parameter Types.PerUnit gmin "Minimum gate opening";
  parameter Types.PerUnit vmax "Maximum gate opening rate";
  parameter Types.PerUnit vmin "Minimum gate opening rate";
  parameter Types.Time Tp "Pilot valve time constant";
  parameter Types.Time Tr "Dashpot time constant";
  parameter Real delta "Transient speed droop [pu/pu]";
  parameter Real sigma "Permanent speed droop [pu/pu]";
  parameter Types.Time Tw "Water starting time";
  parameter Real a11 "Deriv. of flow rate vs. turbine head";
  parameter Real a13 "Deriv. of flow rate vs. gate position";
  parameter Real a21 "Deriv. of torque vs. turbine head";
  parameter Real a23 "Deriv. of torque vs. gate position";
  parameter Real int3;
  Types.PerUnit deltaG "Gate position variation";
  Types.PerUnit G "Gate position";
  Modelica.Blocks.Continuous.Integrator integrator(initType=Modelica.Blocks.Types.Init.NoInit,
      y_start=0) ;
  Modelica.Blocks.Math.Gain gain(k=1/(Tg*Tp))
    ;
  Modelica.Blocks.Math.Gain gain1(k=1/Tp) ;
  Modelica.Blocks.Continuous.Integrator integrator1(initType=Modelica.Blocks.Types.Init.NoInit,
      y_start=0)
    ;
  Modelica.Blocks.Math.Feedback feedback
    ;
  Modelica.Blocks.Math.Gain gain2(k=delta + sigma) ;
  Modelica.Blocks.Math.Gain gain3(k=sigma/Tr) ;
  Modelica.Blocks.Math.Gain gain5(k=1/Tr) ;
  Modelica.Blocks.Continuous.Integrator integrator2(initType=Modelica.Blocks.Types.Init.NoInit,
      y_start=0) ;
  Modelica.Blocks.Math.Feedback feedback1 ;
  Modelica.Blocks.Math.Gain gain4(k=1/(a11*Tw)) ;
  Modelica.Blocks.Continuous.Integrator integrator3(initType=Modelica.Blocks.Types.Init.NoInit,
      y_start=int3) ;
  Modelica.Blocks.Math.Feedback feedback2 ;
  Modelica.Blocks.Math.Gain G6(k=(a11*a23 - a13*a21)/a11)
    ;
  Modelica.Blocks.Math.Gain gain7(k=a13*a21/(a11*a11*Tw))
    ;
  Modelica.Blocks.Interfaces.RealInput w "Rotor speed [pu]" ;
  Modelica.Blocks.Interfaces.RealOutput pm "Mechanical power [pu]" ;
  Modelica.Blocks.Nonlinear.Limiter limiter(uMax=vmax, uMin=vmin)
    ;
  Modelica.Blocks.Nonlinear.Limiter limiter1(uMax=gmax, uMin=gmin)
    ;
  Modelica.Blocks.Math.Add add(k1=+1, k2=-1)
    ;
  Modelica.Blocks.Math.Add3 add3_1(
    k1=-1,
    k2=1,
    k3=1) ;
  Modelica.Blocks.Math.Add add1
    ;
  Modelica.Blocks.Math.Add add2
    ;
  Modelica.Blocks.Sources.Constant const(k=P_0)
    ;
  Modelica.Blocks.Sources.Constant const1(k=wref)
    ;
equation
  deltaG = limiter1.y;
  G = add1.y;
  connect(gain1.y, feedback.u2) ;
  connect(feedback.y, integrator1.u) ;
  connect(gain.y, feedback.u1) ;
  connect(gain5.y, feedback1.u2) ;
  connect(feedback1.y, integrator2.u) ;
  connect(integrator2.y, gain3.u) ;
  connect(gain4.y, feedback2.u2) ;
  connect(feedback2.y, integrator3.u) ;
  connect(gain7.y, feedback2.u1) ;
  connect(gain1.u, integrator1.y) ;
  connect(integrator2.y, gain5.u) ;
  connect(integrator3.y, gain4.u) ;
  connect(integrator1.y, limiter.u) ;
  connect(limiter.y, integrator.u) ;
  connect(integrator.y, limiter1.u) ;
  connect(feedback1.u1, limiter1.y) ;
  connect(limiter1.y, gain2.u) ;
  connect(w, add.u2) ;
  connect(gain2.y, add3_1.u1) ;
  connect(add.y, add3_1.u2) ;
  connect(gain3.y, add3_1.u3) ;
  connect(add3_1.y, gain.u) ;
  connect(limiter1.y, add1.u2) ;
  connect(add1.y, G6.u) ;
  connect(add1.y, gain7.u) ;
  connect(G6.y, add2.u1) ;
  connect(integrator3.y, add2.u2) ;
  connect(const.y, add1.u1) ;
  connect(const1.y, add.u1) ;
  connect(add2.y, pm) 
  ;
end TGTypeIII;

within OpenIPSL.Electrical.Controls.PSAT.TG;
model TGTypeIV
  "Hydro Turbine (Linear model) and Governor (Standard model with PI controller)- control scheme Type 4"
  parameter Types.PerUnit wref "Reference speed";
  parameter Types.PerUnit Tg "Pilot valve droop";
  parameter Types.PerUnit gmax "Maximum gate opening";
  parameter Types.PerUnit gmin "Minimum gate opening";
  parameter Types.PerUnit vmax "Maxmimum gate opening rate";
  parameter Types.PerUnit vmin "Maximum gate opening rate";
  parameter Types.Time Tp "Pilot valve time constant";
  parameter Types.Time Tr "Dashpot time constant";
  parameter Real sigma "Permanent speed droop [pu/pu]";
  parameter Real delta "Transient speed droop [pu/pu]";
  parameter Types.Time Tw "Water starting time";
  parameter Real a11 "Deriv. of flow rate vs. turbine head";
  parameter Real a13 "Deriv. of flow rate vs. gate position";
  parameter Real a21 "Deriv. of torque vs. turbine head";
  parameter Real a23 "Deriv. of torque vs. gate position";
  parameter Real Kp "Proportional droop";
  parameter Real Ki "Integral droop";
  parameter Real Pref;
  Types.PerUnit deltaG "Gate position variation";
  Types.PerUnit v "Gate opening rate";
  Modelica.Blocks.Continuous.Integrator integrator3(initType=Modelica.Blocks.Types.Init.NoInit,
      y_start=int3)
    ;
  Modelica.Blocks.Math.Gain gain(k=1/(Tg*Tp))
    ;
  Modelica.Blocks.Math.Gain gain1(k=1/Tp) ;
  Modelica.Blocks.Continuous.Integrator integrator2(initType=Modelica.Blocks.Types.Init.NoInit,
      y_start=int2)
    ;
  Modelica.Blocks.Math.Feedback feedback
    ;
  Modelica.Blocks.Math.Gain gain2(k=delta + sigma) ;
  Modelica.Blocks.Math.Gain gain3(k=delta/Tr) ;
  Modelica.Blocks.Math.Gain gain5(k=1/Tr) ;
  Modelica.Blocks.Continuous.Integrator integrator4(initType=Modelica.Blocks.Types.Init.NoInit,
      y_start=int4) ;
  Modelica.Blocks.Math.Feedback feedback1 ;
  Modelica.Blocks.Math.Gain gain4(k=1/(a11*Tw)) ;
  Modelica.Blocks.Continuous.Integrator integrator5(initType=Modelica.Blocks.Types.Init.NoInit,
      y_start=int5) ;
  Modelica.Blocks.Math.Feedback feedback2 ;
  Modelica.Blocks.Math.Gain G6(k=(a11*a23 - a13*a21)/a11)
    ;
  Modelica.Blocks.Math.Gain gain7(k=a13*a21/(a11*a11*Tw))
    ;
  Modelica.Blocks.Interfaces.RealInput w "Rotor speed [pu]" ;
  Modelica.Blocks.Interfaces.RealOutput Pm "Mechanical power [pu]" ;
  Modelica.Blocks.Continuous.Integrator integrator1(initType=Modelica.Blocks.Types.Init.NoInit,
      y_start=int1)
    ;
  Modelica.Blocks.Math.Gain gain6(k=Ki)
    ;
  Modelica.Blocks.Math.Gain gain8(k=Kp)
    ;
  Modelica.Blocks.Nonlinear.Limiter limiter(uMax=vmax, uMin=vmin)
    ;
  Modelica.Blocks.Nonlinear.Limiter limiter1(uMax=gmax, uMin=gmin)
    ;
  Modelica.Blocks.Math.Add add1(k1=+1, k2=-1)
    ;
  Modelica.Blocks.Math.Add add2
    ;
  Modelica.Blocks.Math.Add3 add3_1(
    k1=-1,
    k2=+1,
    k3=+1) ;
  Modelica.Blocks.Math.Add add3
    ;
  Modelica.Blocks.Sources.Constant const1(k=wref)
    ;
protected
  parameter Real int1=sigma*Pref;
  parameter Real int2=0;
  parameter Real int3=Pref;
  parameter Real int4=Tr*Pref;
  parameter Real int5=a13*a21/a11*Pref;
equation
  deltaG = limiter1.y;
  v = limiter.y;
  connect(gain1.y, feedback.u2) ;
  connect(feedback.y, integrator2.u) ;
  connect(gain.y, feedback.u1) ;
  connect(gain5.y, feedback1.u2) ;
  connect(feedback1.y, integrator4.u) ;
  connect(integrator4.y, gain3.u) ;
  connect(gain4.y, feedback2.u2) ;
  connect(feedback2.y, integrator5.u) ;
  connect(gain7.y, feedback2.u1) ;
  connect(gain1.u, integrator2.y) ;
