  connect(limiter.y, integrator3.u) ;
  connect(integrator2.y, limiter.u) ;
  connect(integrator3.y, limiter1.u) ;
  connect(limiter1.y, gain2.u) ;
  connect(limiter1.y, feedback1.u1) ;
