  connect(add2.y, add3_1.u2) ;
  connect(add3_1.u3, gain3.y) ;
  connect(G6.y, add3.u1) ;
  connect(integrator5.y, add3.u2) ;
  connect(add3.y, Pm) ;
  connect(limiter1.y, G6.u) ;
