  parameter Types.Time Tw "Water starting time";
  parameter Real Kp "Proportional droop [pu/pu]";
  parameter Real Ki "Integral droop [pu/pu]";
  parameter Real sigma "Permanent speed droop [pu/pu]";
  parameter Types.PerUnit Pref;
  Types.PerUnit G "Gate opening";
  Modelica.Blocks.Continuous.Integrator integrator(initType=Modelica.Blocks.Types.Init.NoInit,
      y_start=Pref)
    ;
  Modelica.Blocks.Math.Gain gain(k=1/Tg, y(start=0))
    ;
  Modelica.Blocks.Continuous.Integrator integrator3(initType=Modelica.Blocks.Types.Init.SteadyState,
      y_start=Pref) ;
  Modelica.Blocks.Math.Gain gain7(k=1/Tw)
    ;
  Modelica.Blocks.Math.MultiSum multiSum3(k={-1,1}, nu=2)
    ;
  Modelica.Blocks.Interfaces.RealInput w "Rotor speed [pu]" ;
  Modelica.Blocks.Interfaces.RealOutput Pm "Power Pm [pu]" ;
  Modelica.Blocks.Continuous.Integrator integrator4(initType=Modelica.Blocks.Types.Init.SteadyState,
      y_start=Pref)
    ;
  Modelica.Blocks.Math.Gain Integral(k=Ki)
    ;
  Modelica.Blocks.Math.Gain gain9(k=1/Tp)
    ;
  Modelica.Blocks.Math.MultiSum multiSum6( k={-1,1}, nu=2)
    ;
  Modelica.Blocks.Math.Gain gain6(k=sigma) ;
  Modelica.Blocks.Continuous.Integrator integrator5(initType=Modelica.Blocks.Types.Init.NoInit,
      y_start=0)
    ;
  Modelica.Blocks.Math.Gain Proportional(k=Kp)
    ;
  Modelica.Blocks.Math.Gain gain8(k=1/Tp) ;
  Modelica.Blocks.Math.Division division(y(start=1))
    ;
  Modelica.Blocks.Math.Product product1
    ;
  Modelica.Blocks.Math.MultiProduct square(nu=2) ;
  Modelica.Blocks.Sources.Constant one(k=1) ;
  Modelica.Blocks.Interfaces.RealInput pref "Reference power [pu]" ;
  Modelica.Blocks.Math.Feedback p_feedback ;
  Modelica.Blocks.Nonlinear.Limiter limiter2(uMax=vmax, uMin=vmin)
    ;
  Modelica.Blocks.Nonlinear.Limiter limiter3(uMax=gmax, uMin=gmin)
    ;
  Modelica.Blocks.Math.Add add1
    ;
  Modelica.Blocks.Math.Add add2(k1=+1, k2=-1)
    ;
  Modelica.Blocks.Math.Add add3(k1=+1, k2=-1)
    ;
  Modelica.Blocks.Interfaces.RealInput wref "Reference rotor speed [pu]"
    ;
  Modelica.Blocks.Math.Feedback w_feedback ;
equation
  G = limiter3.y;
  connect(division.y, square.u[1]) ;
  connect(division.y, square.u[2]) ;
  connect(square.y, product1.u1) ;
  connect(square.y, multiSum3.u[1]) ;
  connect(one.y, multiSum3.u[2]) ;
  connect(integrator3.y, division.u1) ;
  connect(limiter3.y, division.u2) ;
  connect(add1.y, p_feedback.u1) ;
  connect(Proportional.y, add1.u2) ;
  connect(integrator4.y, add1.u1) ;
  connect(gain8.y, add3.u2) ;
  connect(add3.y, integrator5.u) ;
  connect(add1.y, add2.u1) ;
  connect(pref, p_feedback.u2) ;
  connect(wref, w_feedback.u1) ;
  connect(w, w_feedback.u2) ;
  connect(gain6.y, multiSum6.u[1]) ;
  connect(w_feedback.y, multiSum6.u[2]) ;
  connect(multiSum6.y, gain9.u) ;
  connect(gain9.y, add3.u1) ;
  connect(gain6.u, p_feedback.y) ;
  connect(integrator5.y, gain8.u) ;
  connect(integrator5.y, Proportional.u) ;
  connect(integrator5.y, Integral.u) ;
  connect(Integral.y, integrator4.u) ;
  connect(limiter3.y, add2.u2) ;
  connect(gain.y, limiter2.u) ;
  connect(limiter2.y, integrator.u) ;
  connect(integrator.y, limiter3.u) ;
  connect(add2.y, gain.u) ;
  connect(gain7.y, integrator3.u) ;
  connect(multiSum3.y, gain7.u) ;
  connect(integrator3.y, product1.u2) ;
  connect(product1.y, Pm) 
  ;
end TGTypeV;

within OpenIPSL.Electrical.Controls.PSAT.TG;
model TGTypeVI
  "Hydro Turbine (Nonlinear model) and Governor (PID controller combined with servomotor)- control scheme Type 6"
  parameter Types.PerUnit gmax "Maximum gate opening";
  parameter Types.PerUnit gmin "Minimum gate opening";
  parameter Types.PerUnit vmax "Maximum gate opening rate";
  parameter Types.PerUnit vmin "Minimum gate opening rate";
  parameter Types.Time Ta "Pilot valve time constant";
  parameter Types.Time Tw "Water starting time";
  parameter Real beta "Transient speed droop [pu/pu]";
  parameter Real Kp "Proportional droop [pu/pu]";
  parameter Types.TimeAging Ki "Integral droop";
  parameter Types.Time Kd "Derivative droop";
  parameter Types.Time Td "Derivative droop time constant";
  parameter Real Rp "Permanent droop [pu/pu]";
  parameter Real Ka "Pilot valve gain [pu/pu]";
  parameter Types.PerUnit dref;
  parameter Types.PerUnit po;
  Types.PerUnit G "Gate opening [pu]";
  Modelica.Blocks.Continuous.Integrator integrator(initType=Modelica.Blocks.Types.Init.NoInit,
      y_start=po*(gmax - gmin))
    ;
  Modelica.Blocks.Sources.Constant one(k=1) ;
  Modelica.Blocks.Math.Feedback feedback
    ;
  Modelica.Blocks.Continuous.Integrator integrator3(initType=Modelica.Blocks.Types.Init.NoInit,
      y_start=po) ;
  Modelica.Blocks.Math.MultiSum multiSum3(nu=2, k={1,-1})
    ;
  Modelica.Blocks.Interfaces.RealOutput Pm "Mechanical power [pu]" ;
  Modelica.Blocks.Math.Gain gain9(k=Kp)
    ;
  Modelica.Blocks.Math.MultiSum multiSum5( k={1,1,1}, nu=3)
    ;
  Modelica.Blocks.Math.Feedback feedback1
    ;
  Modelica.Blocks.Math.Gain gain6(k=Rp) ;
  Modelica.Blocks.Math.Feedback w_fb ;
  Modelica.Blocks.Continuous.Integrator integrator5(initType=Modelica.Blocks.Types.Init.NoInit,
      y_start=po*(gmax - gmin))
    ;
  Modelica.Blocks.Math.Gain Proportional(k=beta)
    ;
  Modelica.Blocks.Math.Gain gain8(k=Ki) ;
  Modelica.Blocks.Nonlinear.Limiter limiter(uMax=vmax, uMin=vmin)
    ;
  Modelica.Blocks.Nonlinear.Limiter limiter1(uMax=gmax, uMin=gmin)
    ;
  Modelica.Blocks.Math.Division division
    ;
  Modelica.Blocks.Math.Product product1
    ;
  Modelica.Blocks.Math.MultiProduct square(nu=2) ;
  Modelica.Blocks.Interfaces.RealInput pe "Active power [pu]" ;
  Modelica.Blocks.Continuous.Derivative derivative(k=Kd, T=Td)
    ;
  Modelica.Blocks.Continuous.TransferFunction transferFunction(a={Ta,1}, b={Ka})
    ;
  Modelica.Blocks.Math.Feedback servo_fb
    ;
  Modelica.Blocks.Math.Gain Gain10(k=1/(gmax - gmin))
    ;
  Modelica.Blocks.Math.MultiSum multiSum4(nu=2, k={-1,1}) ;
  Modelica.Blocks.Math.Gain gain7(k=1/Tw) ;
  Modelica.Blocks.Logical.Switch switch1 ;
  Modelica.Blocks.Math.RealToBoolean realToBoolean(threshold=0.5) ;
  Modelica.Blocks.Sources.Constant const(k=dref) ;
  Modelica.Blocks.Interfaces.RealInput pref "Active power reference [pu]"
    ;
  Modelica.Blocks.Interfaces.RealInput wref "Rotor speed reference [pu]"
    ;
  Modelica.Blocks.Interfaces.RealInput we "Rotor speed [pu]" ;
equation
  G = Gain10.y;
  connect(division.y, square.u[1]) ;
  connect(division.y, square.u[2]) ;
  connect(square.y, multiSum3.u[1]) ;
  connect(product1.y, Pm) ;
  connect(gain8.y, integrator5.u) ;
  connect(feedback1.y, gain9.u) ;
  connect(feedback1.y, gain8.u) ;
  connect(feedback1.y, derivative.u) ;
  connect(limiter1.y, Gain10.u) ;
  connect(Proportional.y, multiSum3.u[2]) ;
  connect(multiSum3.y, multiSum4.u[1]) ;
  connect(one.y, multiSum4.u[2]) ;
  connect(multiSum4.y, gain7.u) ;
  connect(gain7.y, integrator3.u) ;
  connect(multiSum3.y, product1.u1) ;
  connect(switch1.y, gain6.u) ;
  connect(limiter1.y, switch1.u1) ;
  connect(w_fb.y, Proportional.u) ;
  connect(integrator3.y, division.u1) ;
  connect(limiter1.y, servo_fb.u2) ;
  connect(we, w_fb.u2) ;
  connect(wref, w_fb.u1) ;
  connect(feedback.y, switch1.u3) ;
  connect(pe, feedback.u1) ;
  connect(pref, feedback.u2) ;
  connect(switch1.u2, realToBoolean.y) ;
  connect(realToBoolean.u, const.y) ;
  connect(feedback1.u2, gain6.y) ;
  connect(w_fb.y, feedback1.u1) ;
  connect(gain9.y, multiSum5.u[1]) ;
  connect(integrator5.y, multiSum5.u[2]) ;
  connect(derivative.y, multiSum5.u[3]) ;
  connect(multiSum5.y, servo_fb.u1) ;
  connect(servo_fb.y, transferFunction.u) ;
  connect(transferFunction.y, limiter.u) ;
  connect(limiter.y, integrator.u) ;
  connect(integrator.y, limiter1.u) ;
  connect(Gain10.y, division.u2) ;
  connect(integrator3.y, product1.u2) 
  ;
end TGTypeVI;

