  parameter Real VR0(fixed=false);
  parameter Real Efd0(fixed=false);
  parameter Real Ifd0(fixed=false);
  parameter Real VE0(fixed=false);
  parameter Real VFE0(fixed=false);
initial equation
  Ifd0 = XADIFD;
  // Finding initial value of excitation voltage, VE0, via going through conditions of FEX function
  VE0 = invFEX(
    K_C=K_C,
    Efd0=Efd0,
    Ifd0=Ifd0);
  // Case IN>0 not checked because it will be resolved in the next iteration
  VFE0 = VE0*(SE(
    VE0,
    S_EE_1,
    S_EE_2,
    E_1,
    E_2) + K_E) + Ifd0*K_D;
  VR0 = VFE0;
  V_REF = VR0/K_A + ECOMP0;
equation
  connect(imLeadLag.y, simpleLagLim.u)
    ;
  connect(limiter1.y, rotatingExciterWithDemagnetization.I_C)
    ;
  connect(ECOMP, imSimpleLag.u)
    ;
  connect(VUEL,hV_GATE.u2) ;
  connect(imSimpleLag.y, DiffV.u2) ;
  connect(add3_1.y, imLeadLag.u)
    ;
  connect(DiffV.y, add3_1.u2) ;
  connect(VOTHSG, add3_1.u1) ;
  connect(derivative.y, add3_1.u3) ;
  connect(derivative.u, rotatingExciterWithDemagnetization.V_FE) ;
  connect(rotatingExciterWithDemagnetization.EFD,
    rectifierCommutationVoltageDrop.V_EX)
    ;
  connect(rectifierCommutationVoltageDrop.XADIFD,
    rotatingExciterWithDemagnetization.XADIFD) ;
  connect(rectifierCommutationVoltageDrop.EFD, EFD) ;
  connect(lV_GATE.y, limiter1.u)
    ;
  connect(lowLim.y, rotatingExciterWithDemagnetization.outMin) ;
  connect(FEMAX.y, DiffV1.u1) ;
  connect(DiffV1.u2, rotatingExciterWithDemagnetization.XADIFD) ;
  connect(se1.VE_IN, EFD) ;
  connect(DiffV2.u1, const.y) ;
  connect(DiffV2.u2, se1.VE_OUT) ;
  connect(division.u1, DiffV1.y) ;
  connect(DiffV2.y, division.u2)
    ;
  connect(division.y, rotatingExciterWithDemagnetization.outMax) ;
  connect(XADIFD, rotatingExciterWithDemagnetization.XADIFD) ;
  connect(simpleLagLim.y, DiffV3.u2)
    ;
  connect(gain.u, rotatingExciterWithDemagnetization.V_FE) ;
  connect(gain.y, DiffV3.u1) ;
  connect(DiffV3.y, gain1.u) ;
  connect(gain1.y,hV_GATE.u1)
    ;
  connect(VOEL, lV_GATE.u2) ;
  connect(hV_GATE.y, lV_GATE.u1) 
  ;
end ESAC2A;

