  extends OpenIPSL.Electrical.Controls.PSSE.ES.BaseClasses.BaseExciter;
  import
    OpenIPSL.Electrical.Controls.PSSE.ES.BaseClasses.calculate_dc_exciter_params;
  parameter Types.Time T_R=0 "Regulator input filter time constant";
  parameter Types.PerUnit K_A=40 "Regulator output gain";
  parameter Types.Time T_A=0.04 "Regulator output time constant";
  parameter Types.Time T_B=0 "Regulator denominator (lag) time constant";
  parameter Types.Time T_C=0 "Regulator numerator (lead) time constant";
  parameter Types.PerUnit V_RMAX=7.3 "Maximum regulator output";
  parameter Types.PerUnit V_RMIN=-7.3 "Minimum regulator output";
  parameter Types.PerUnit K_E=1 "Exciter field proportional constant";
  parameter Types.Time T_E=0.8 "Exciter field time constant";
  parameter Types.PerUnit K_F=0.03 "Rate feedback excitation system stabilizer gain";
  parameter Types.Time T_F=1 "Rate feedback time constant";
  parameter Types.PerUnit E_1=2.4 "Exciter output voltage for saturation factor S_E(E_1)";
  parameter Types.PerUnit S_EE_1=0.03 "Exciter saturation factor at exciter output voltage E1";
  parameter Types.PerUnit E_2=5.0000 "Exciter output voltage for saturation factor S_E(E_2)";
  parameter Types.PerUnit S_EE_2=0.50000 "Exciter saturation factor at exciter output voltage E2";
  NonElectrical.Continuous.LeadLag LL(
    T1=T_C,
    T2=T_B,
    K=1,
    y_start=VR0/K_A,
    x_start=V_REF - ECOMP0)
    ;
  Modelica.Blocks.Math.Add3 V_Erro1(k3=-1)
    ;
  Modelica.Blocks.Continuous.Derivative imDerivativeLag(
    k=K_F,
    T=T_F,
    y_start=0,
    initType=Modelica.Blocks.Types.Init.InitialOutput,
    x_start=Efd0)
    ;
  Modelica.Blocks.Math.Add3 V_Erro2
    ;
  NonElectrical.Continuous.SimpleLagLim SL(
    K=K_A,
    T=T_A,
    y_start=VR0,
    outMax=V_RMAX0,
    outMin=V_RMIN0)
    ;
  BaseClasses.RotatingExciter rotatingExciter(
    T_E=T_E,
    E_1=E_1,
    E_2=E_2,
    S_EE_1=S_EE_1,
    S_EE_2=S_EE_2,
    Efd0=Efd0,
    K_E=K_E0)
    ;
  NonElectrical.Continuous.SimpleLag TransducerDelay(
    K=1,
    T=T_R,
    y_start=ECOMP0)
    ;
protected
  parameter Types.PerUnit SE_Efd0(fixed=false);
  parameter Types.PerUnit VR0(fixed=false);
  parameter Types.PerUnit V_RMAX0(fixed=false);
  parameter Types.PerUnit K_E0(fixed=false);
  parameter Types.PerUnit V_RMIN0(fixed=false);
initial equation
  SE_Efd0 = OpenIPSL.NonElectrical.Functions.SE(
    EFD0,
    S_EE_1,
    S_EE_2,
    E_1,
    E_2);
  (V_RMAX0,V_RMIN0,K_E0) = calculate_dc_exciter_params(
    V_RMAX,
    V_RMIN,
    K_E,
    E_2,
    S_EE_2,
    Efd0,
    SE_Efd0);
  VR0 = Efd0*(K_E0 + SE_Efd0);
  V_REF = VR0/K_A + ECOMP0;
equation
  connect(V_Erro1.y, LL.u)
    ;
  connect(LL.y, SL.u)
    ;
  connect(DiffV.y, V_Erro1.u2)
    ;
  connect(SL.y, rotatingExciter.I_C)
    ;
  connect(rotatingExciter.EFD, EFD)
    ;
  connect(imDerivativeLag.y, V_Erro1.u3) ;
  connect(imDerivativeLag.u, EFD) ;
  connect(VOTHSG, V_Erro2.u1) ;
  connect(VUEL, V_Erro2.u2) ;
  connect(VOEL, V_Erro2.u3) ;
  connect(V_Erro2.y, V_Erro1.u1) ;
  connect(TransducerDelay.y, DiffV.u2) ;
  connect(TransducerDelay.u, ECOMP)

  ;
end IEEEX1;

within OpenIPSL.Electrical.Controls.PSSE.ES;
model SCRX "SCRX - Bus Fed or Solid Fed Static Exciter (AC4A from [IEEE1992] / AC4C from [IEEE2016])"
  extends Icons.VerifiedModel;
  extends OpenIPSL.Electrical.Controls.PSSE.ES.BaseClasses.BaseExciter;
  parameter Real T_AT_B=0.1 "Ratio between regulator numerator (lead) and denominator (lag) time constants";
  parameter Types.Time T_B=1 "Regulator denominator (lag) time constant";
  parameter Types.PerUnit K=100 "Excitation power source output gain";
  parameter Types.Time T_E=0.005 "Excitation power source output time constant";
  parameter Types.PerUnit E_MIN=-10 "Minimum exciter output";
  parameter Types.PerUnit E_MAX=10 "Maximum exciter output";
  parameter Boolean C_SWITCH=false "Feeding selection. False for bus fed, and True for solid fed";
  parameter Real r_cr_fd=10 "Ratio between crowbar circuit resistance and field circuit resistance";
  Modelica.Blocks.Math.Add3 V_erro
    ;
  OpenIPSL.NonElectrical.Continuous.LeadLag imLeadLag(
    K=1,
    y_start=VR0/K,
    T1=T_AT_B*T_B,
    T2=T_B) ;
  OpenIPSL.NonElectrical.Logical.NegCurLogic negCurLogic(nstartvalue=Efd0,
      RC_rfd=r_cr_fd)
    ;
  NonElectrical.Continuous.SimpleLagLim simpleLagLim(
    K=K,
    T=T_E,
    y_start=VR0,
    outMax=E_MAX,
    outMin=E_MIN)
    ;
  Modelica.Blocks.Logical.Switch switch1
    ;
  Modelica.Blocks.Sources.BooleanConstant booleanConstant(k=C_SWITCH)
    ;
  Modelica.Blocks.Math.Product product
    ;
  Modelica.Blocks.Math.Add DiffV1(k2=-1) ;
protected
  parameter Types.PerUnit VR0(fixed=false);
initial equation
  if not C_SWITCH then
    VR0 = Efd0/ECOMP0;
    V_REF = VR0/K + ECOMP0;
  else
    VR0 = Efd0;
    V_REF = VR0/K + ECOMP0;
  end if;
equation
  connect(V_erro.y, imLeadLag.u)
    ;
  connect(imLeadLag.y, simpleLagLim.u)
    ;
  connect(booleanConstant.y, switch1.u2) ;
  connect(product.u2, simpleLagLim.y) ;
  connect(product.y, switch1.u3) ;
  connect(switch1.u1, simpleLagLim.y) ;
  connect(ECOMP, DiffV.u2) ;
  connect(DiffV.y, V_erro.u2)
    ;
  connect(VOTHSG, V_erro.u1) ;
  connect(DiffV1.u2, VOEL) ;
  connect(DiffV1.u1, VUEL) ;
  connect(DiffV1.y, V_erro.u3) ;
  connect(negCurLogic.Efd, EFD)
    ;
  connect(product.u1, DiffV.u2) ;
  connect(switch1.y, negCurLogic.Vd) ;
  connect(XADIFD, negCurLogic.XadIfd) 
  ;
end SCRX;

