  Modelica.Blocks.Interfaces.RealInput VOTHSG ;
  Modelica.Blocks.Interfaces.RealInput ECOMP ;
  Modelica.Blocks.Sources.Constant VoltageReference(k=V_REF)
    ;
  Modelica.Blocks.Math.Add DiffV(k2=-1)
    ;
