within OpenIPSL.Electrical.Controls.PSSE.OEL;
model IF_comparisor "Discrete over excitation limiter based on comparison and if-statements"
  Modelica.Blocks.Interfaces.RealInput p
    ;
  Modelica.Blocks.Interfaces.RealOutput n1
    ;
  Modelica.Blocks.Interfaces.RealOutput n2 ;
  parameter Real HighCurrentLimit=1.5;
  parameter Real MediumCurrentLimit=1.2;
  parameter Real LowCurrentLimit=1.1;
  parameter Real LL=1 - HighCurrentLimit;
  parameter Real ML=1 - MediumCurrentLimit;
  parameter Real HL=1 - LowCurrentLimit;
  Modelica.Blocks.Interfaces.RealOutput n3
    ;
  Modelica.Blocks.Interfaces.RealOutput n4
    ;
equation
  if p >= HL then
    n1 = 100;
    n2 = 0;
    n3 = 0;
    n4 = 0;
  elseif p >= ML and p < HL then
    n1 = 0;
    n2 = -0.1;
    n3 = 0;
    n4 = 0;
  elseif p >= LL and p < ML then
    n1 = 0;
    n2 = 0;
    n3 = -0.2;
    n4 = 0;
  else
    n1 = 0;
    n2 = 0;
    n3 = 0;
    n4 = -0.5;
  end if
  ;
end IF_comparisor;

within OpenIPSL.Electrical.Controls.PSSE.OEL;
model OEL "Over excitation limiter system from PSSE"
  Modelica.Blocks.Interfaces.RealInput IFD "Field current" ;
  Modelica.Blocks.Sources.Constant IFDSetpoint(k=IFDdes)
    ;
  Modelica.Blocks.Continuous.LimIntegrator imLimitedIntegrator(
    outMin=Vmin,
    outMax=Vmax,
    k=KMX,
    y_start=0,
    initType=Modelica.Blocks.Types.Init.InitialOutput)
    ;
  Modelica.Blocks.Interfaces.RealOutput VOEL "OEL output" ;
  parameter Types.PerUnit IFD1=1.1 "Low OEL limit";
  parameter Types.PerUnit IFD2=1.2 "Medium OEL limit";
  parameter Types.PerUnit IFD3=1.5 "High OEL limit";
  parameter Types.Time TIME1=60 "Timing for low OEL";
  parameter Types.Time TIME2=30 "Timimg for medium OEL";
  parameter Types.Time TIME3=15 "Timing for high OEL";
  parameter Types.PerUnit IFDdes=1 "IFD setpoint";
  parameter Types.PerUnit Vmax=0 "Max. OEL output";
  parameter Types.PerUnit Vmin=-0.05 "Min. OEL output";
  parameter Types.PerUnit KMX=1 "Control constant";
  IF_comparisor comparisor(
    HighCurrentLimit=IFD3,
    MediumCurrentLimit=IFD2,
    LowCurrentLimit=IFD1)
    ;
  Modelica.Blocks.Continuous.LimIntegrator imLimitedIntegrator1(
    outMin=Vmin,
    outMax=Vmax,
    k=KMX,
    y_start=6,
    initType=Modelica.Blocks.Types.Init.InitialOutput)
    ;
  Modelica.Blocks.Continuous.LimIntegrator imLimitedIntegrator2(
    outMin=Vmin,
    outMax=Vmax,
    k=KMX,
    y_start=6,
    initType=Modelica.Blocks.Types.Init.InitialOutput)
    ;
  Modelica.Blocks.Continuous.LimIntegrator imLimitedIntegrator3(
    outMin=Vmin,
    outMax=Vmax,
    k=KMX,
    y_start=7.5,
    initType=Modelica.Blocks.Types.Init.InitialOutput)
    ;
  Modelica.Blocks.Math.Add add(k1=-1)
    ;
  Modelica.Blocks.Math.MultiSum multiSum(nu=4)
    ;
equation
  connect(comparisor.n1, imLimitedIntegrator.u) ;
  connect(comparisor.n2, imLimitedIntegrator1.u) ;
  connect(comparisor.n3, imLimitedIntegrator2.u) ;
  connect(comparisor.n4, imLimitedIntegrator3.u) ;
  connect(add.y,comparisor. p) ;
  connect(add.u2, IFD) ;
  connect(IFDSetpoint.y, add.u1) ;
  connect(multiSum.y, VOEL)
    ;
  connect(imLimitedIntegrator.y, multiSum.u[1]) ;
  connect(imLimitedIntegrator1.y, multiSum.u[2]) ;
  connect(imLimitedIntegrator2.y, multiSum.u[3]) ;
  connect(imLimitedIntegrator3.y, multiSum.u[4]) 
  ;
end OEL;

