within OpenIPSL.Electrical.Controls.PSSE.PSS;
model IEE2ST "IEE2ST - IEEE Stabilizing Model With Dual-Input Signals (extension of IEEEST, [PSSE-AGV2])"
  parameter Types.PerUnit K_1=1 "First input filter gain";
  parameter Types.PerUnit K_2=1 "Second input filter gain";
  parameter Types.Time T_1=0.005 "First input filter time constant";
  parameter Types.Time T_2=0.005 "Second input filter time constant";
  parameter Types.Time T_3=10 "Power system stabilizer washout numerator time constant. If T_3 equals 0, sT_3 will equal 1.0";
  parameter Types.Time T_4=10 "Power system stabilizer washout denominator time constant. It must be greater than 0";
  parameter Types.Time T_5=0.16 "First power system stabilizer numerator (lead) time constant";
  parameter Types.Time T_6=0.02 "First power system stabilizer denominator (lag) time constant";
  parameter Types.Time T_7=0.16 "Second power system stabilizer numerator (lead) time constant";
  parameter Types.Time T_8=0.02 "Second power system stabilizer denominator (lag) time constant";
  parameter Types.Time T_9=0.16 "Third power system stabilizer numerator (lead) time constant";
  parameter Types.Time T_10=0.02 "Third power system stabilizer denominator (lag) time constant";
  parameter Types.PerUnit L_SMAX = 0.1 "Maximum output for sequence of washout filters";
  parameter Types.PerUnit L_SMIN = -0.1 "Minimum output for sequence of washout filters";
  parameter Types.PerUnit V_CU=0 "Maximum power system stabilizer output";
  parameter Types.PerUnit V_CL=0 "Minimum power system stabilizer output";
  Modelica.Blocks.Interfaces.RealInput V_S1 "PSS input signal 1"
    ;
  Modelica.Blocks.Interfaces.RealInput V_S2 "PSS input signal 2"
    ;
  Modelica.Blocks.Math.Add add
    ;
  Modelica.Blocks.Nonlinear.Limiter limiter(uMax=L_SMAX, uMin=L_SMIN)
    ;
  Modelica.Blocks.Interfaces.RealOutput VOTHSG "PSS output signal"
    ;
  Modelica.Blocks.Continuous.Derivative imDerivativeLag(
    k=T_3,
    T=T_4,
    y_start=0,
    initType=Modelica.Blocks.Types.Init.InitialOutput)
    ;
  NonElectrical.Continuous.SimpleLag imSimpleLag(
    K=K_1,
    T=T_1,
    y_start=K_1*ICS10)
    ;
  NonElectrical.Continuous.SimpleLag imSimpleLag1(
    K=K_2,
    T=T_2,
    y_start=ICS20)
    ;
  NonElectrical.Continuous.LeadLag imLeadLag(
    K=1,
    T1=T_5,
    T2=T_6,
    y_start=0) ;
  NonElectrical.Continuous.LeadLag imLeadLag1(
    K=1,
    T1=T_7,
    T2=T_8,
    y_start=0) ;
  NonElectrical.Continuous.LeadLag imLeadLag2(
    K=1,
    T1=T_9,
    T2=T_10,
    y_start=0) ;
  Modelica.Blocks.Interfaces.RealInput VCT
    "Compensated machine terminal voltage [pu]" ;
protected
  Modelica.Blocks.Interfaces.RealOutput VSS
    ;
protected
  parameter Types.PerUnit ICS10(fixed=false);
  parameter Types.PerUnit ICS20(fixed=false);
initial equation
  ICS10 = V_S1;
  ICS20 = V_S2;
equation
  if V_CU == 0 and not V_CL == 0 then
    if VCT > V_CL then
      VOTHSG = VSS;
    else
      VOTHSG = 0;
    end if;
  elseif V_CL == 0 and not V_CU == 0 then
    if VCT < V_CU then
      VOTHSG = VSS;
    else
      VOTHSG = 0;
    end if;
  elseif V_CU == 0 and V_CL == 0 then
    VOTHSG = VSS;
  elseif VCT > V_CL and VCT < V_CU then
    VOTHSG = VSS;
  else
    VOTHSG = 0;
  end if;
  connect(limiter.y, VSS)
    ;
  connect(V_S2, imSimpleLag1.u)
    ;
  connect(imSimpleLag1.y, add.u2) ;
  connect(V_S1, imSimpleLag.u)
    ;
  connect(imSimpleLag.y, add.u1) ;
  connect(imLeadLag2.y, limiter.u)
    ;
  connect(imLeadLag1.y, imLeadLag2.u)
    ;
  connect(imLeadLag.y, imLeadLag1.u)
    ;
  connect(imLeadLag.u, imDerivativeLag.y)
    ;
  connect(add.y, imDerivativeLag.u)

  ;
end IEE2ST;

within OpenIPSL.Electrical.Controls.PSSE.PSS;
model PSS2A "PSS2A - Dual-Input Stabilizer Model [IEEE1992]"
  extends BaseClasses.BasePSS;
  parameter Real T_w1=10 "Washout 1 time constant";
  parameter Real T_w2=10 "Washout 2 time constant";
  parameter Real T_6=1e-9 "Lag 1 time constant";
  parameter Real T_w3=10 "Washout 3 time constant";
  parameter Real T_w4=1e-9 "Washout 4 time constant";
  parameter Real T_7=10 "Lag 2 time constant";
  parameter Real K_S2=0.99 "Lag 2 gain";
  parameter Real K_S3=1 "gain";
  parameter Real T_8=0.5 "Ramp-tracking filter time constant";
  parameter Real T_9=0.1 "Ramp-tracking filter time constant";
  parameter Real K_S1=20 "PSS gain";
  parameter Real T_1=0.15
    "Leadlag1 time constant (data from IEEE std, not representative, need to be tuned following system parameters)";
  parameter Real T_2=0.025 "Leadlag1 time constant";
  parameter Real T_3=0.15 "Leadlag2 time constant";
  parameter Real T_4=0.025 "Leadlag2 time constant";
  parameter Real V_STMAX=0.1 "PSS output limiation";
  parameter Real V_STMIN=-0.1 "PSS output limiation";
  parameter Integer M = 5 "Ramp tracking filter coefficient";
  parameter Integer N = 1 "Ramp tracking filter coefficient";
  OpenIPSL.NonElectrical.Continuous.LeadLag Leadlag1(
    K=1,
    T1=T_1,
    T2=T_2,
    y_start=0,
    x_start=0) ;
  OpenIPSL.NonElectrical.Continuous.LeadLag Leadlag2(
    K=1,
    T1=T_3,
    T2=T_4,
    y_start=0,
    x_start=0) ;
  OpenIPSL.NonElectrical.Continuous.SimpleLag SimpleLag1(
    K=1,
    T=T_6,
    y_start=0) ;
  OpenIPSL.NonElectrical.Continuous.SimpleLag SimpleLag2(
    K=K_S2,
    T=T_7,
    y_start=0) ;
  Modelica.Blocks.Math.Add add(k2=+K_S3) ;
  Modelica.Blocks.Math.Add add1(k2=-1) ;
  Modelica.Blocks.Math.Gain gain(k=K_S1) ;
  Modelica.Blocks.Nonlinear.Limiter limiter(uMax=V_STMAX, uMin=V_STMIN) ;
  NonElectrical.Continuous.RampTrackingFilter rampTrackingFilter(
    M=M,
    N=N,
    T_1=T_8,
    T_2=T_9) ;
  NonElectrical.Continuous.DerivativeLag derivativeLag(
    K=T_w1,
    T=T_w1,
    y_start=0) ;
  NonElectrical.Continuous.DerivativeLag derivativeLag1(
    y_start=0,
    K=T_w2,
    T=T_w2) ;
  NonElectrical.Continuous.DerivativeLag derivativeLag2(
    y_start=0,
    K=T_w3,
    T=T_w3) ;
  NonElectrical.Continuous.DerivativeLag derivativeLag3(
    y_start=0,
    K=T_w4,
    T=T_w4) ;
equation
  connect(SimpleLag1.y, add.u1) ;
  connect(SimpleLag2.y, add.u2) ;
  connect(add1.u2, add.u2) ;
  connect(add1.y, gain.u) ;
  connect(gain.y, Leadlag1.u) ;
  connect(Leadlag1.y, Leadlag2.u) ;
  connect(Leadlag2.y, limiter.u) ;
  connect(rampTrackingFilter.y, add1.u1) ;
  connect(derivativeLag.y, derivativeLag1.u) ;
  connect(derivativeLag1.y, SimpleLag1.u) ;
  connect(derivativeLag3.u, derivativeLag2.y) ;
  connect(derivativeLag3.y, SimpleLag2.u) ;
  connect(V_S1, derivativeLag.u)
    ;
  connect(V_S2, derivativeLag2.u) ;
  connect(limiter.y, VOTHSG)
    ;
  connect(add.y, rampTrackingFilter.u)

  ;
end PSS2A;

within OpenIPSL.Electrical.Controls.PSSE.PSS;
