  connect(transferFunction.y, transferFunction1.u) ;
  connect(transferFunction1.y, transferFunction2.u) ;
  connect(transferFunction2.y, transferFunction3.u) ;
  connect(transferFunction4.y, transferFunction5.u) ;
  connect(K.u, transferFunction2.y) ;
  connect(add.y, transferFunction4.u) ;
  connect(transferFunction3.y, add.u1) ;
  connect(K.y, add.u2) ;
  connect(transferFunction5.y, limiter.u)
    ;
  connect(VOTHSG, limiter.y)

  ;
