    initType=Modelica.Blocks.Types.Init.InitialOutput)
    ;
  Types.PerUnit G "Gate opening";
  Types.PerUnit c "Desired gate opening";
  Types.PerUnit Q "Turbine flow";
  Types.PerUnit H "Turbine head";
  Modelica.Blocks.Math.Add add(k2=-1)
    ;
  Modelica.Blocks.Math.Add add1
    ;
  Modelica.Blocks.Math.Division division
    ;
  Modelica.Blocks.Math.Product product
    ;
  Modelica.Blocks.Math.Add add2(k1=-1)
    ;
  Modelica.Blocks.Math.Add add3(k2=-1)
    ;
  Modelica.Blocks.Math.Add add4(k2=-1)
    ;
  Modelica.Blocks.Math.Product product1
    ;
  Modelica.Blocks.Math.Product product2
    ;
  NonElectrical.Continuous.SimpleLead simpleLead(
    K=r*T_r,
    T=T_r,
    y_start=0)
    ;
protected
  parameter Real q0(fixed=false);
  //=Pm0/(A_t*h0)+q_NL "water flow initial value";
  parameter Real g0(fixed=false);
  //=q0/sqrt(h0) "the gate opening initial value";
  parameter Real c0(fixed=false);
  //=g0 "desired gate position";
  parameter Real e0=0 "initial output for the filter";
  parameter Real nref(fixed=false);
  //=R*c0 "speed reference";
  parameter Types.PerUnit P_m0(fixed=false);
initial algorithm
  P_m0 := PMECH0;
  q0 := P_m0/(A_t*h0) + q_NL;
  g0 := q0/sqrt(h0);
  //
  //
  c0 := g0;
  //c0_calculation(g0,G_MIN,G_MAX);
  nref := R*c0;
  //
equation
  G = g.y;
  c = g.u;
  Q = q.y;
  H = product.y;
  connect(add.y, SimpleLag1.u) ;
  connect(n_ref.y, add.u1) ;
  connect(add1.y, add.u2) ;
  connect(Gain3.y, add1.u2) ;
  connect(Velocity_Limiter.y, Position_Limiter.u) ;
  connect(Position_Limiter.y, Gain3.u) ;
  connect(g.u, Gain3.u) ;
  connect(division.y, product.u1) ;
  connect(product.u2, product.u1) ;
  connect(product.y, add2.u1) ;
  connect(hs.y, add2.u2) ;
  connect(add2.y, q.u) ;
  connect(q.y, add3.u1) ;
  connect(qNL.y, add3.u2) ;
  connect(Gain4.y, product1.u2) ;
  connect(product1.y, add4.u2) ;
  connect(product1.u1, g.y) ;
  connect(division.u2, g.y) ;
  connect(division.u1, add3.u1) ;
  connect(Gain6.y, add4.u1) ;
  connect(product2.y, Gain6.u) ;
  connect(add3.y, product2.u2) ;
  connect(product2.u1, add2.u1) ;
  connect(simpleLead.y, Velocity_Limiter.u) ;
  connect(simpleLead.u, SimpleLag1.y) ;
  connect(add4.y, PMECH)
    ;
  connect(SPEED, add1.u1) ;
  connect(Gain4.u, add1.u1) 
  ;
end HYGOV;

