model LoadLimiter "GE General GGOV1 Governor/Turbine Temperature Control"
  parameter Types.PerUnit Kturb = 1.5 "Turbine gain";
  parameter Types.PerUnit Kpload = 2 "Load limiter proportional gain for PI controller";
  parameter Types.TimeAging Kiload = 0.67 "Load limiter integral gain for PI controller";
  parameter Types.PerUnit Dm = 0 "Mechanical damping coefficient";
  parameter Types.PerUnit Wfnl = 0.2 "No load fuel flow";
  Modelica.Blocks.Math.Gain KPLOAD(k = Kpload) ;
  Modelica.Blocks.Continuous.Integrator s6(k = 1, y_start = s60, initType = Modelica.Blocks.Types.Init.InitialOutput) ;
  Modelica.Blocks.Math.Add LoadlimiterPI ;
  Modelica.Blocks.Math.Add diff(k2 = -1) ;
  Modelica.Blocks.Math.Gain gain(k = 1 / Kturb) ;
  Modelica.Blocks.Nonlinear.Limiter maxLimiter(uMax = 1, uMin = -Modelica.Constants.inf) ;
  Modelica.Blocks.Math.Add tlim ;
  Modelica.Blocks.Math.Gain Gain(k = Kiload) ;
  Modelica.Blocks.Interfaces.RealOutput FSRT "Controller Output" ;
  Modelica.Blocks.Interfaces.RealInput LDREF "Load Limiter reference value (pu)" ;
  Modelica.Blocks.Interfaces.RealInput TEXM "Measured Exhaust Temperature" ;
  Modelica.Blocks.Interfaces.RealInput PELEC "Machine electrical power (pu)" ;
  Modelica.Blocks.Sources.Constant const(k = Wfnl) ;
protected
  parameter Types.PerUnit Pmech0(fixed = false);
  parameter Types.PerUnit s60(fixed = false);
  parameter Types.PerUnit fsr0(fixed = false);
initial equation
  Pmech0 = PELEC;
  s60 = fsr0;
  fsr0 = (Pmech0 + Dm) / Kturb + Wfnl;
equation
  connect(gain.y, tlim.u2) ;
  connect(diff.y, KPLOAD.u) ;
  connect(KPLOAD.y, LoadlimiterPI.u2) ;
  connect(LoadlimiterPI.y, maxLimiter.u) ;
  connect(maxLimiter.y, FSRT) ;
  connect(gain.u, LDREF) ;
  connect(const.y, tlim.u1) ;
  connect(s6.u, Gain.y) ;
  connect(s6.y, LoadlimiterPI.u1) ;
  connect(Gain.u, diff.y) ;
  connect(diff.u1, tlim.y) ;
  connect(diff.u2, TEXM) 
  ;
end LoadLimiter;

