within OpenIPSL.Electrical.Controls.PSSE.TG.BaseClasses.GGOV1;
model PIDGovernor "GE GGOV1 General Governor Frequency Controller"
  parameter Integer Rselect=1 "Feedback signal for governor droop" ;
  parameter Types.PerUnit R=0.04 "Permanent droop";
  parameter Types.Time T_pelec=1 "Electrical power transducer time constant";
  parameter Types.PerUnit maxerr=0.05 "Maximum value for speed error signal";
  parameter Types.PerUnit minerr=-0.05 "Minimum value for speed error signal";
  parameter Types.PerUnit Kpgov=10 "Governor proportional gain";
  parameter Types.TimeAging Kigov=2 "Governor integral gain";
  parameter Types.Time Kdgov=0 "Governor derivative gain";
  parameter Types.Time Tdgov=1 "Governor derivative controller time constant";
  parameter Types.PerUnit Kturb=1.5 "Turbine gain";
  parameter Types.TimeAging Kimw=0 "Power controller (reset) gain";
  parameter Types.PerUnit db=0 "Speed governor deadband";
  parameter Types.PerUnit Wfnl=0.2 "No load fuel flow";
  parameter Types.PerUnit Dm=0 "Mechanical damping coefficient";
  Modelica.Blocks.Math.Gain KPGOV(k=Kpgov) ;
  Modelica.Blocks.Continuous.Integrator s2(
    k=1,
    initType=Modelica.Blocks.Types.Init.InitialOutput,
    y_start=s20) ;
  Modelica.Blocks.Continuous.Derivative s1(
    k=Kdgov,
    T=Tdgov,
    y_start=0,
    initType=Modelica.Blocks.Types.Init.InitialOutput) ;
  Modelica.Blocks.Math.Add3 GovernorPID ;
  Modelica.Blocks.Nonlinear.DeadZone deadZone(uMax=db) ;
  Modelica.Blocks.Nonlinear.Limiter limiterSerror(uMax=maxerr, uMin=minerr) ;
  Modelica.Blocks.Math.Add3 add3_2(k1=-1, k3=-1) ;
  Modelica.Blocks.Math.Gain r(k=R) "Permanent droop" ;
  Modelica.Blocks.Math.Add add2 ;
  Modelica.Blocks.Continuous.LimIntegrator s7(
    k=Kimw,
    outMax=1.1*R,
    initType=Modelica.Blocks.Types.Init.InitialOutput,
    y_start=s70) "Power controller" ;
  Modelica.Blocks.Math.Add add3(k2=-1) ;
  OpenIPSL.NonElectrical.Continuous.SimpleLag s0(
    T=T_pelec,
    y_start=s00,
    K=1) ;
  Modelica.Blocks.Math.Gain KPGOV1(k=Kigov) ;
  OpenIPSL.Electrical.Controls.PSSE.TG.BaseClasses.GGOV1.R_select rSELECT(Rselect=Rselect)
    ;
  Modelica.Blocks.Interfaces.RealInput PELEC
    "Machine electrical power (pu)"
    ;
  Modelica.Blocks.Interfaces.RealInput PMW_SET
  "Supervisory Load Controller Setpoint"
    ;
  Modelica.Blocks.Interfaces.RealInput P_REF ;
  Modelica.Blocks.Interfaces.RealInput SPEED
    "Machine speed deviation from nominal (pu)"
    ;
  Modelica.Blocks.Interfaces.RealInput VSTROKE "Valve Stroke" ;

  Modelica.Blocks.Interfaces.RealInput GOVOUT1
    "Governor Output before Limiter" ;

  Modelica.Blocks.Interfaces.RealOutput FSRN ;
protected
  parameter Types.PerUnit Pe0(fixed=false);
  parameter Types.PerUnit Pmech0(fixed=false);
  parameter Types.PerUnit s00(fixed=false);
  parameter Types.PerUnit s20(fixed=false);
  parameter Types.PerUnit s70(fixed=false);
  parameter Types.PerUnit fsr0(fixed=false);
initial equation
  Pe0 = PELEC;
  Pmech0 = PELEC;
  s00 = Pe0;
  s20 = fsr0;
  s70 = 0;
  //assume s70=0
  fsr0 = (Pmech0 + Dm)/Kturb + Wfnl;

equation
  connect(deadZone.y, limiterSerror.u) ;
  connect(add3_2.y, deadZone.u) ;
  connect(add2.y, add3_2.u2) ;
  connect(KPGOV.y, GovernorPID.u2) ;
  connect(PELEC, s0.u) ;
  connect(FSRN, GovernorPID.y) ;
  connect(KPGOV1.y, s2.u) ;
  connect(s2.y, GovernorPID.u3) ;
  connect(s1.y, GovernorPID.u1) ;
  connect(P_REF, add2.u1) ;
  connect(r.y, add3_2.u3) ;
  connect(r.u, rSELECT.y) ;
  connect(add3.y, s7.u) ;
  connect(PMW_SET, add3.u1) ;
  connect(s0.y, add3.u2) ;
  connect(s0.y, rSELECT.Pelect) ;
  connect(VSTROKE, rSELECT.ValveStroke) ;
  connect(GOVOUT1, rSELECT.GovernorOutput) ;
  connect(limiterSerror.y, KPGOV1.u) ;
  connect(KPGOV.u, limiterSerror.y) ;
  connect(s1.u, limiterSerror.y) ;
  connect(add2.u2, s7.y) ;
  connect(SPEED, add3_2.u1) 
  ;
end PIDGovernor;

within OpenIPSL.Electrical.Controls.PSSE.TG.BaseClasses.GGOV1;
model PIDGovernorDU "GE GGOV1DU General Governor Frequency Controller"
  parameter Integer Rselect=1 "Feedback signal for governor droop" ;
  parameter Types.PerUnit R=0.04 "Permanent droop";
  parameter Types.Time T_pelec=1 "Electrical power transducer time constant";
  parameter Types.PerUnit maxerr=0.05 "Maximum value for speed error signal";
  parameter Types.PerUnit minerr=-0.05 "Minimum value for speed error signal";
  parameter Types.PerUnit Kpgov=10 "Governor proportional gain";
  parameter Types.TimeAging Kigov=2 "Governor integral gain";
  parameter Types.Time Kdgov=0 "Governor derivative gain";
  parameter Types.Time Tdgov=1 "Governor derivative controller time constant";
  parameter Types.PerUnit Kturb=1.5 "Turbine gain";
  parameter Types.PerUnit Wfnl=0.2 "No load fuel flow";
  parameter Types.TimeAging Kimw=0 "Power controller (reset) gain";
  parameter Types.PerUnit db=0 "Speed governor deadband";
  parameter Types.PerUnit Dm=0 "Mechanical damping coefficient";
  Modelica.Blocks.Math.Gain KPGOV(k=Kpgov) ;
  Modelica.Blocks.Continuous.Integrator s2(
    k=1,
    initType=Modelica.Blocks.Types.Init.InitialOutput,
    y_start=s20) ;
  Modelica.Blocks.Continuous.Derivative s1(
    k=Kdgov,
    T=Tdgov,
    y_start=0,
    initType=Modelica.Blocks.Types.Init.InitialOutput) ;
  Modelica.Blocks.Math.Add3 GovernorPID ;
  Modelica.Blocks.Nonlinear.DeadZone deadZone(uMax=db) ;
  Modelica.Blocks.Nonlinear.Limiter limiterSerror(uMax=maxerr, uMin=minerr) ;
  Modelica.Blocks.Math.Add3 add3_2(k1=-1, k3=-1) ;
  Modelica.Blocks.Math.Gain r(k=R) "Permanent droop" ;
  Modelica.Blocks.Math.Add add2 ;
  Modelica.Blocks.Continuous.LimIntegrator s7(
    k=Kimw,
    outMax=1.1*R,
    initType=Modelica.Blocks.Types.Init.InitialOutput,
    y_start=s70) "Power controller" ;
  Modelica.Blocks.Math.Add add3(k2=-1) ;
  OpenIPSL.NonElectrical.Continuous.SimpleLag s0(
    T=T_pelec,
    y_start=s00,
    K=1) ;
  Modelica.Blocks.Math.Gain KPGOV1(k=Kigov/Kpgov) ;
  Modelica.Blocks.Math.Add LoadlimiterPI2(k1=-1) ;
  Modelica.Blocks.Interfaces.RealInput PELEC
    "Machine electrical power (pu)"
    ;
  Modelica.Blocks.Interfaces.RealInput PMW_SET
    "Supervisory Load Controller Setpoint"
    ;
  Modelica.Blocks.Interfaces.RealInput P_REF ;
  Modelica.Blocks.Interfaces.RealInput SPEED
    "Machine speed deviation from nominal (pu)"
    ;
  Modelica.Blocks.Interfaces.RealInput VSTROKE "Valve Stroke" ;

  Modelica.Blocks.Interfaces.RealInput GOVOUT1
    "Governor Output before Limiter" ;

  Modelica.Blocks.Interfaces.RealOutput FSRN ;
  OpenIPSL.Electrical.Controls.PSSE.TG.BaseClasses.GGOV1.R_select rSELECT(Rselect = Rselect) ;
protected
  parameter Types.PerUnit Pe0(fixed=false);
  parameter Types.PerUnit Pmech0(fixed=false);
  parameter Types.PerUnit s00(fixed=false);
  parameter Types.PerUnit s20(fixed=false);
  parameter Types.PerUnit s70(fixed=false);
  parameter Types.PerUnit fsr0(fixed=false);
initial equation
  Pe0 = PELEC;
  Pmech0 = PELEC;
  s00 = Pe0;
  s20 = fsr0;
  s70 = 0;
  //assume s70=0
  fsr0 = (Pmech0 + Dm)/Kturb + Wfnl;

equation
  connect(deadZone.y, limiterSerror.u) ;
  connect(add3_2.y, deadZone.u) ;
  connect(add2.y, add3_2.u2) ;
  connect(add3.y, s7.u) ;
  connect(s2.u, KPGOV1.y) ;
  connect(KPGOV1.u, LoadlimiterPI2.y) ;
  connect(PELEC, s0.u) ;
  connect(FSRN, GovernorPID.y) ;
  connect(add3_2.u3, r.y) ;
  connect(add2.u2, s7.y) ;
  connect(P_REF, add2.u1) ;
  connect(SPEED, add3_2.u1) ;
  connect(rSELECT.y, r.u) ;
  connect(PMW_SET, add3.u1) ;
  connect(s0.y, add3.u2) ;
  connect(s0.y, rSELECT.Pelect) ;
  connect(VSTROKE, rSELECT.ValveStroke) ;
  connect(GOVOUT1, rSELECT.GovernorOutput) ;
  connect(KPGOV.y, GovernorPID.u2) ;
  connect(s1.y, GovernorPID.u1) ;
  connect(s2.y, GovernorPID.u3) ;
  connect(LoadlimiterPI2.u1, s2.y) ;
  connect(GOVOUT1, LoadlimiterPI2.u2) ;
  connect(limiterSerror.y, KPGOV.u) ;
  connect(s1.u, limiterSerror.y) 
  ;
end PIDGovernorDU;

within OpenIPSL.Electrical.Controls.PSSE.TG.BaseClasses.GGOV1;
block R_select "Selects the feedback signal used in GGOV1 and GGOV1DU frequency control systems"
  // extends Modelica.Blocks.Icons.Block;
  parameter Integer Rselect=0 "Feedback signal for
                    governor droop" ;
  Modelica.Blocks.Interfaces.RealOutput y ;
  Modelica.Blocks.Interfaces.RealInput Pelect ;
  Modelica.Blocks.Interfaces.RealInput ValveStroke ;

  Modelica.Blocks.Interfaces.RealInput GovernorOutput ;

equation
  y = if Rselect == 1 then Pelect elseif Rselect == (-1) then ValveStroke
