within OpenIPSL.Electrical.Controls.PSSE.TG.BaseClasses.GGOV1;
model Turbine "GE General GGOV1 and GGOV1DU Turbine Model"
  parameter Integer Flag = 1 "Switch for fuel source characteristic"
    ;
  parameter Types.DelayType delay=Types.DelayType.FixedDelay "Delay type (for linearisation)";
  parameter Types.Time Tact = 0.5 "Actuator time constant";
  parameter Types.PerUnit Kturb = 1.5 "Turbine gain";
  parameter Types.Time Tb = 0.1 "Turbine lag time constant";
  parameter Types.Time Tc = 0 "Turbine lead time constant";
  parameter Types.Time Teng = 0 "Transport lag time constant for diesel engine";
  parameter Types.Time Tfload = 3 "Load Limiter time constant";
  parameter Types.PerUnit Dm = 0 "Mechanical damping coefficient";
  parameter Types.PerUnit Vmax = 1 "Maximum valve position limit";
  parameter Types.PerUnit Vmin = 0.15 "Minimum valve position limit";
  parameter Types.TimeAging Ropen = 0.1 "Maximum valve opening rate";
  parameter Types.TimeAging Rclose = -0.1 "Maximum valve closing rate";
  parameter Types.Time Tsa = 4 "Temperature detection lead time constant";
  parameter Types.Time Tsb = 5 "Temperature detection lag time constant";
  parameter Types.Time DELT = 0.005 "Time step used in simulation";
  parameter Types.PerUnit Wfnl = 0.2 "No load fuel flow";
  Modelica.Blocks.Math.Product product ;
  OpenIPSL.NonElectrical.Continuous.LeadLag s4(K = 1, T1 = Tc, T2 = Tb, y_start = s40) ;
  Modelica.Blocks.Math.Gain gain1(k = Kturb) ;
  Modelica.Blocks.Math.Add add4(k2 = -1) ;
  Modelica.Blocks.Math.Add add5(k1 = -1) ;
  Modelica.Blocks.Math.Gain gain2(k = Dm) ;
  OpenIPSL.Electrical.Controls.PSSE.TG.BaseClasses.GGOV1.Flag flag10(Flag=Flag) ;
  OpenIPSL.Electrical.Controls.PSSE.TG.BaseClasses.GGOV1.Dm_select dm_select(Dm = Dm) ;
  Modelica.Blocks.Math.Gain Tactgain(k = 1 / Tact) ;
  Modelica.Blocks.Nonlinear.Limiter V1(uMax = Ropen, uMin = Rclose) ;
  Modelica.Blocks.Continuous.Integrator s3(k = 1, initType = Modelica.Blocks.Types.Init.InitialOutput, y_start = s30) ;
  Modelica.Blocks.Math.Add add8(k2 = -1) ;
  Modelica.Blocks.Interfaces.RealInput SPEED "Machine speed deviation from nominal (pu)" ;
  Modelica.Blocks.Interfaces.RealInput FSR "Governor Output" ;
  Modelica.Blocks.Interfaces.RealOutput PMECH "Turbine mechanical power (pu)" ;
  OpenIPSL.NonElectrical.Continuous.SimpleLag s5(T = Tfload, y_start = s50, K = 1) ;
  OpenIPSL.NonElectrical.Continuous.LeadLag s9(T1 = Tsa, T2 = Tsb, y_start = s90, K = 1) ;
  Modelica.Blocks.Math.Product product1 ;
  Modelica.Blocks.Interfaces.RealOutput TEXM "Measured Exhaust Temperature" ;
  Modelica.Blocks.Interfaces.RealOutput VSTROKE "Valve Position" ;
  Modelica.Blocks.Interfaces.RealInput PELEC "Machine electrical power (pu)" ;
  Modelica.Blocks.Sources.Constant const(k = Wfnl) ;
  Modelica.Blocks.Math.Add Dw2w ;
  Modelica.Blocks.Sources.Constant const1(k = 1) ;
  Modelica.Blocks.Nonlinear.Limiter limiter(uMax=Vmax, uMin=Vmin) ;
  Modelica.Blocks.Nonlinear.FixedDelay fixedDelay(delayTime=Teng)
    if delay == Types.DelayType.FixedDelay "Use fixed delay model"
    ;
  Modelica.Blocks.Nonlinear.PadeDelay padeDelay(
    delayTime=C.eps,
    n=2,
    balance=true) if delay == Types.DelayType.PadeDelay "Use pade delay model"
    ;
protected
  parameter Types.PerUnit Pmech0(fixed = false);
  parameter Types.PerUnit s30(fixed = false);
  parameter Types.PerUnit s40(fixed = false);
  parameter Types.PerUnit s50(fixed = false);
  parameter Types.PerUnit s90(fixed = false);
  parameter Types.PerUnit fsr0(fixed = false);
initial equation
  Pmech0 = PELEC;
  s30 = fsr0;
  s40 = Pmech0;
  s50 = s90;
  s90 = fsr0;
  fsr0 = (Pmech0 + Dm) / Kturb + Wfnl;
equation
  connect(s4.y, add5.u2) ;
  connect(product.y, add4.u1) ;
  connect(gain2.y, add5.u1) ;
  connect(dm_select.y, gain2.u) ;
  connect(V1.y, s3.u) ;
  connect(Tactgain.y, V1.u) ;
  connect(add8.y, Tactgain.u) ;
  connect(add5.y, PMECH) ;
  connect(s5.u, s9.y) ;
  connect(product1.u2, gain2.u) ;
  connect(product1.u1, add4.u1) ;
  connect(s9.u, product1.y) ;
  connect(s5.y, TEXM) ;
  connect(const.y, add4.u2) ;
  connect(Dw2w.y, dm_select.speed) ;
  connect(flag10.speed, dm_select.speed) ;
  connect(add4.y, gain1.u) ;
  connect(flag10.y, product.u1) ;
  connect(limiter.y, product.u2) ;
  connect(VSTROKE, limiter.y) ;
  connect(add8.u2, limiter.y) ;
  connect(s3.y, limiter.u) ;
  connect(const1.y, Dw2w.u2) ;
  connect(SPEED, Dw2w.u1) ;
  connect(FSR, add8.u1) ;
  connect(fixedDelay.y, s4.u) ;
  connect(padeDelay.y, s4.u) ;
  connect(gain1.y, fixedDelay.u) ;
  connect(gain1.y, padeDelay.u) 
  ;
end Turbine;

within OpenIPSL.Electrical.Controls.Simulink.ES;
model ExcitationSystem
  "This ES is composed by the OEL and PSS and excitation part"
  parameter Real V0=1 "Reference value of terminal voltage";
  parameter Real L2=4 "Exciter parameter";
  parameter Real G=70 "Exciter parameter";
  parameter Real Ta=10 "Exciter parameter";
  parameter Real Tb=20 "Exciter parameter";
  parameter Real vfd0 "Initial Filed voltage";
  parameter Real r "OEL parameter";
  parameter Real f "OEL parameter";
  parameter Real L1 "OEL parameter";
  parameter Real ifd_lim "OEL parameter";
  parameter Real Kp "Washout gain";
  parameter Real Tw "Washout time constant";
  parameter Real T1 "Lead-lag filter time constant";
  parameter Real T2 "Lead-lag filter time constant";
  parameter Real C "PSS output limiation";
  OpenIPSL.Electrical.Controls.Simulink.OEL.OEL oEL(
    init_OEL_Timer=0,
    ifd_lim=ifd_lim,
    r=r,
    f=f,
    L1=L1) ;
  Modelica.Blocks.Sources.Constant V_0(k=V0) "Reference terminal voltage "
    ;
  Modelica.Blocks.Interfaces.RealInput ifd "Field current"
    ;
  Modelica.Blocks.Interfaces.RealInput V "Terminal voltage "
    ;
  Modelica.Blocks.Interfaces.RealInput omega "Speed"
    ;
  Modelica.Blocks.Interfaces.RealOutput vfd "Field voltage"
    ;
  Modelica.Blocks.Math.Gain Ka(k=10)
    ;
  Modelica.Blocks.Continuous.LimIntegrator imLimitedIntegrator(
    outMin=0,
    outMax=L2,
    k=1,
    y_start=vfd0,
    initType=Modelica.Blocks.Types.Init.InitialOutput)
    ;
  OpenIPSL.NonElectrical.Continuous.LeadLag tgr(
    K=G,
    T1=Ta,
    T2=Tb,
    y_start=vfd0) "Transient gain rudection"
    ;
  OpenIPSL.Electrical.Controls.Simulink.PSS.PSS pSS(
    Kp=Kp,
    Tw=Tw,
    T1=T1,
    T2=T2,
    C=C) ;
  Modelica.Blocks.Math.Feedback feedback
    ;
  Modelica.Blocks.Math.Add3 add3_1(k2=-1)
    ;
equation
  connect(oEL.ifd, ifd) ;
  connect(omega, pSS.omega) ;
  connect(imLimitedIntegrator.y, vfd)
    ;
  connect(Ka.y, imLimitedIntegrator.u) ;
  connect(oEL.OEL_output, tgr.u) ;
  connect(feedback.y, Ka.u)
    ;
  connect(tgr.y, feedback.u1)
    ;
  connect(feedback.u2, vfd) ;
  connect(V, add3_1.u2)
    ;
  connect(V_0.y, add3_1.u1)
    ;
  connect(pSS.Upss, add3_1.u3) ;
  connect(add3_1.y, oEL.VolContinput) 
  ;
end ExcitationSystem;

