within OpenIPSL.Electrical.Controls.Simulink.TG;
model Governor "Speed governor model for hydro turbines"
  Modelica.Blocks.Interfaces.RealInput Omega "Rotor speed in p.u" ;
  Modelica.Blocks.Sources.Constant Omega_n(k=1) "Nominal rotor speed in p.u"
    ;
  Modelica.Blocks.Math.Gain Gain1(k=2)
    ;
  Modelica.Blocks.Math.Gain Gain2(k=0.4)
    ;
  Modelica.Blocks.Continuous.Integrator Integrator(
    k=1,
    y_start=p0,
    initType=Modelica.Blocks.Types.Init.InitialOutput)
    ;
  Modelica.Blocks.Math.Gain Droop(k=D) "Permanent speed droop" ;
  Modelica.Blocks.Math.Gain Gain3(k=5)
    ;
  Modelica.Blocks.Nonlinear.Limiter Limited(uMin=-0.1, uMax=0.1)
    ;
  Modelica.Blocks.Continuous.LimIntegrator imLimitedIntegrator(
    outMax=1,
    k=1,
    outMin=0,
    y_start=p0,
    initType=Modelica.Blocks.Types.Init.InitialOutput)
    ;
  Modelica.Blocks.Interfaces.RealOutput z "Gate opening" ;
  parameter Real D "Permanent speed droop, g19=g20=0.08, all others=0.04";
  parameter Real p0 "Initialization, initial electrical power";
  Modelica.Blocks.Interfaces.RealInput Pm_set ;
  Modelica.Blocks.Interfaces.RealInput Pe ;
  OpenIPSL.NonElectrical.Continuous.SimpleLag SimpleLag1(
    K=1,
    T=2,
    y_start=p0)
    ;
  Modelica.Blocks.Math.Feedback feedback
    ;
  Modelica.Blocks.Math.Add add(k2=-1) ;
  Modelica.Blocks.Math.Add add1 ;
  Modelica.Blocks.Math.Add add2(k1=-1) ;
  Modelica.Blocks.Math.Add add3 ;
equation
  connect(Gain3.y, Limited.u) ;
  connect(Limited.y, imLimitedIntegrator.u) ;
  connect(imLimitedIntegrator.y, z) ;
  connect(feedback.y, Gain3.u) ;
  connect(feedback.u2, z) ;
  connect(Pe, SimpleLag1.u) ;
  connect(add.y, Droop.u) ;
  connect(add.u2, SimpleLag1.y) ;
  connect(Pm_set, add.u1)
    ;
  connect(Droop.y, add1.u2) ;
  connect(add2.u1, Omega)
    ;
  connect(Omega_n.y, add2.u2) ;
  connect(add2.y, add1.u1) ;
  connect(Gain1.u, add1.y) ;
  connect(Gain2.u, add1.y) ;
  connect(Gain2.y, Integrator.u) ;
  connect(add3.y, feedback.u1)
    ;
  connect(Integrator.y, add3.u2) ;
  connect(Gain1.y, add3.u1) 
