model Breaker "Circuit breaker with time or signal control"
  parameter Boolean enableTrigger=false "=true, if external trigger signal is used"
    ;
  parameter Types.Time t_o=Modelica.Constants.inf "Opening time"
    ;
  parameter Boolean rc_enabled=false "Enable reclosure" ;
  parameter Types.Time t_rc=Modelica.Constants.inf "Reclosing time"
     ;
  Interfaces.PwPin s "Sending pin"
    ;
  Interfaces.PwPin r "Receiving pin"
    ;
  Modelica.Blocks.Interfaces.BooleanInput Trigger if enableTrigger ;
  Complex vs(re=s.vr, im=s.vi);
  Complex vr(re=r.vr, im=r.vi);
  Complex is(re=s.ir, im=s.ii);
  Complex ir(re=r.ir, im=r.ii);

protected
  Modelica.Blocks.Interfaces.BooleanOutput Open "Help variable to indicate open circuit breaker" ;
equation
  if not enableTrigger then
    if not rc_enabled and time >= t_o then
      Open = true;
    elseif rc_enabled and time >= t_o and time < t_rc then
      Open = true;
    else
      Open = false;
    end if;
  end if;

  if Open then
    is = Complex(0);
    ir = Complex(0);
  else
    vs = vr;
    is = -ir;
  end if;

  connect(Trigger, Open) 
  ;
end Breaker;

within OpenIPSL.Electrical.Events;
model PwFault "Transitory short-circuit on a node. Shunt impedance connected only during a specified interval of time.
              Developed by AIA. 2014/12/16"
  OpenIPSL.Interfaces.PwPin p ;
  parameter Types.PerUnit R "Resistance";
  parameter Types.PerUnit X "Reactance";
  parameter Types.Time t1 "Start time of the fault";
  parameter Types.Time t2 "End time of the fault";
  import Modelica.Constants.eps;
protected
  parameter Boolean ground=abs(R) < eps and abs(X) < eps;
equation
  if time < t1 then
    p.ii = 0;
    p.ir = 0;
  elseif time < t2 and ground then
    p.vr = 1E-10;
    // This is to avoid numerical problems
    p.vi = 0;
  elseif time < t2 then
    p.ii = (R*p.vi - X*p.vr)/(X*X + R*R);
    p.ir = (R*p.vr + X*p.vi)/(R*R + X*X);
  else
    p.ii = 0;
    p.ir = 0;
  end if
  ;
end PwFault;

within OpenIPSL.Electrical.Events;
model PwFaultPQ "Transitory short-circuit on a node with active and reactive power information"
  OpenIPSL.Interfaces.PwPin p ;
  parameter Types.PerUnit R "Resistance";
  parameter Types.PerUnit X "Reactance";
  parameter Types.Time t1 "Start time of the fault";
  parameter Types.Time t2 "End time of the fault";
  Types.PerUnit P "Active power supplied to the fault";
  Types.PerUnit Q "Reactive power supplied to the fault";
equation
  p.ir = if time < t1 then 0 else if time < t2 then 1/X*(p.vi - R*p.ii) else 0;
  p.ii = if time < t1 then 0 else if time < t2 then (R*p.vi - X*p.vr)/(X*X + R*
    R) else 0;
  P = p.vr*p.ir + p.vi*p.ii;
  Q = (-p.vr*p.ii) + p.vi*p.ir
  ;
end PwFaultPQ;

