within OpenIPSL.Electrical.Loads.PSAT;
model ExponentialRecovery "Exload - Exponential Recovery Load"
  extends BaseClasses.baseLoad;
  parameter Types.Time Tp=1 "Active power time constant";
  parameter Types.Time Tq=1 "Reactive power time constant";
  parameter Real alpha_s=2 "Static active power exponent";
  parameter Real alpha_t=1.5 "Dynamic active power exponent";
  parameter Real beta_s=2 "Static reactive power exponent";
  parameter Real beta_t=1.5 "Dynamic reactive power exponent";
  Types.PerUnit ps "Static real power absorption";
  Types.PerUnit pt "Transient real power absorption";
  Types.PerUnit qs "Static imaginary power absorption";
  Types.PerUnit qt "Transient imaginary power absorption";
protected
  Real xp(start=0);
  Real xq(start=0);
equation
  der(xp) = (-xp/Tp) + ps - pt;
  P = xp/Tp + pt;
  ps = P_0/S_b*(v/v_0)^alpha_s;
  pt = P_0/S_b*(v/v_0)^alpha_t;
  der(xq) = (-xq/Tq) + qs - qt;
  Q = xq/Tq + qt;
  qs = Q_0/S_b*(v/v_0)^beta_s;
  qt = Q_0/S_b*(v/v_0)^beta_t
  ;
end ExponentialRecovery;

within OpenIPSL.Electrical.Loads.PSAT;
model FrequencyDependent "Fl - Frequency Dependent Load"
  extends BaseClasses.baseLoad;
  parameter Real alpha_p=0 "Active power voltage coefficient";
  parameter Real alpha_q=0 "Reactive power voltage coefficient";
  parameter Real beta_p=1.3 "Active power frequency coefficient";
  parameter Real beta_q=1.3 "Reactive power frequency coefficient";
  parameter Types.Time Tf=0.1 "Filter time constant";
  Types.PerUnit deltaw "Frequency deviation";
protected
  Real a "Auxiliary variable, voltage division";
  Real x(start=0) "auxiliary variable";
initial equation
  der(x) = 0;
equation
  a = v/v_0;
  der(x) = -deltaw/Tf;
  0 = x + 1/(2*C.pi*fn)*1/Tf*(anglev - angle_0) - deltaw;
  P = P_0/S_b*a^alpha_p*(1 + deltaw)^beta_p;
  Q = Q_0/S_b*a^alpha_q*(1 + deltaw)^beta_q
  ;
end FrequencyDependent;

within OpenIPSL.Electrical.Loads.PSAT;
model Mixed "Mixload - Mixed Load"
  extends BaseClasses.baseLoad;
  parameter Types.PerUnit Kpf=0 "Frequency coefficient for the active power";
  parameter Real alpha=0 "Voltage exponent for the active power";
  parameter Types.Time Tpv=0.12 "Time constant of dV/dt for the active power";
  parameter Types.PerUnit Kqf=0 "Frequency coefficient for the reactive power";
  parameter Real beta=0 "Voltage exponent for the reactive power";
  parameter Types.Time Tqv=0.075 "Time constant of dV/dt for the reactive power";
  parameter Types.Time Tfv=0.005 "Time constant of voltage magnitude filter";
  parameter Types.Time Tft=0.007 "Time constant of voltage angle filter";
  Types.PerUnit deltaw "Frequency deviation";
protected
  Real a "Auxiliary variable, voltage division";
  Real b "Auxiliary variable, derivation";
  Real x(start=-v_0/Tfv);
  Real y(start=0);
equation
  a = v/v_0;
  der(x) = ((-v/Tfv) - x)/Tfv;
  b = x + v/Tfv;
  der(y) = -1/Tft*(1/(2*C.pi*fn*Tft)*(anglev - angle_0) + y);
  deltaw = y + 1/(2*C.pi*fn*Tft)*(anglev - angle_0);
  P = Kpf*deltaw + P_0/S_b*(a^alpha + Tpv*b);
  Q = Kqf*deltaw + Q_0/S_b*(a^beta + Tqv*b)
  ;
end Mixed;

within OpenIPSL.Electrical.Loads.PSAT;
model PQ "Pl - Constant PQ Load"
  extends BaseClasses.baseLoad;
  parameter Types.PerUnit Vmax=1.2 "maximum voltage"
    ;
  parameter Types.PerUnit Vmin=0.8 "minimum voltage"
    ;
  parameter Boolean forcePQ=true
    "force constant PQ-load, false may cause simulation problems" ;
equation
  if forcePQ or initial() then
    P = P_0/S_b;
    Q = Q_0/S_b;
  elseif (v > Vmax) then
    // needs a better implementation
    P = P_0*v^2/(Vmax^2)/S_b;
    Q = Q_0*v^2/(Vmax^2)/S_b;
  elseif (v < Vmin) then
    P = P_0*v^2/Vmin^2/S_b;
    Q = Q_0*v^2/(Vmin^2)/S_b;
  else
    P = P_0/S_b;
    Q = Q_0/S_b;
  end if

  ;
end PQ;

within OpenIPSL.Electrical.Loads.PSAT;
model PQvar "Equations come from the mathematical separation in between reals and imaginary of S=P+jQ=UI*"
  extends BaseClasses.baseLoad;
  parameter Types.Time t_start_1=1
    "Start time of first load variation"
    ;
  parameter Types.Time t_end_1=2
    "End time of first load variation"
    ;
  parameter Types.ActivePower dP1=0
    "First active load variation" ;
  parameter Types.ReactivePower dQ1=0
    "First reactive load variation"
    ;
  parameter Types.Time t_start_2=2
    "Start time of second Load variation"
    ;
  parameter Types.Time t_end_2=3
    "End time of second load variation"
    ;
  parameter Types.ActivePower dP2=0
    "Second active load variation"
    ;
  parameter Types.ReactivePower dQ2=0
    "Second reactive load variation"
    ;
  parameter Types.PerUnit Vmax=1.2 "maximum voltage"
    ;
  parameter Types.PerUnit Vmin=0.8 "minimum voltage"
    ;
  parameter Boolean forcePQ=true
    "force 'constant' PQ-load, false may cause simulation problems"
    ;
protected
  Types.PerUnit Pd(start=P_0/S_b) "active
  power demand";
  Types.PerUnit Qd(start=Q_0/S_b) "reactive power demand";
equation
  // forcePQ=false needs better implementation
  if forcePQ or initial() then
    P = Pd;
    Q = Qd;
  elseif noEvent(v > Vmax) then
    P = Pd*v^2/(Vmax^2)/S_b;
    Q = Qd*v^2/(Vmax^2)/S_b;
  elseif noEvent(v < Vmin) then
    P = Pd*v^2/Vmin^2/S_b;
    Q = Qd*v^2/(Vmin^2)/S_b;
  else
    P = Pd;
    Q = Qd;
  end if;
  if time >= t_start_1 and time < t_end_1 then
    Pd = (P_0 + dP1)/S_b;
    Qd = (Q_0 + dQ1)/S_b;
  elseif time >= t_start_2 and time < t_end_2 then
    Pd = (P_0 + dP2)/S_b;
    Qd = (Q_0 + dQ2)/S_b;
  else
    Pd = P_0/S_b;
    Qd = Q_0/S_b;
  end if;
end PQvar;

within OpenIPSL.Electrical.Loads.PSAT;
model ThermostaticallyControlled "Thload - Thermostatically Controlled Load"
  extends OpenIPSL.Electrical.Loads.PSAT.BaseClasses.baseLoad;
  parameter Real Kl=2 "Ceiling conductance output";
  parameter Real Kp=10 "Gain of the proportional controller [pu/pu]";
  parameter Real Ki=25 "Gain of the integral controller [pu/pu]";
  parameter Types.Time Ti=10 "Time constant of integral controller";
  parameter Types.Time T1=1200 "Time constant of the thermal load";
  parameter Modelica.Units.NonSI.Temperature_degC T_ref=70 "Reference temperature";
  parameter Modelica.Units.NonSI.Temperature_degC T0=10 "Initial temperature";
  parameter Types.PerUnit G0 = P_0/100*v_0^2 "Initial conductance";
  parameter Types.PerUnit Gmax = Kl*G0 "Maximum conductance";
  parameter Types.PerUnit Gmin = 0 "Minimum conductance";
  parameter Real K1 = (T_ref-T0)/P_0 "Active power gain [pu/pu]";
  parameter Real K3=1 "Gain anti wind-up";

  OpenIPSL.NonElectrical.Continuous.SimpleLag
                                        firstOrder(
    K=1,
    T=T1,
    y_start=0)
    ;
  Modelica.Blocks.Math.Gain gain(k=K1)
                                 ;
  Modelica.Blocks.Math.Gain gain1(k=Kp)
                                 ;
  Modelica.Blocks.Math.Add add(k2=-1, k1=+1)
    ;
  Modelica.Blocks.Continuous.LimIntegrator
                                    Limiter(outMax=Gmax, outMin=Gmin,
    k=Ki/Ti,
    limitsAtInit=true,
    initType=Modelica.Blocks.Types.Init.InitialOutput,
    y_start=G0 - Kp*(T_ref - T0))
    ;
  Modelica.Blocks.Interfaces.RealInput t_ref "Reference temperature"
    ;
  Modelica.Blocks.Interfaces.RealInput t_a "Ambient temperature"
                                          ;
  Modelica.Blocks.Math.Product product ;
  Modelica.Blocks.Math.Add add1(k2=+1, k1=+1)
    ;
  Modelica.Blocks.Nonlinear.Limiter Limiter1(strict=false,
    uMax=Gmax,
    uMin=Gmin)
    ;
  Modelica.Blocks.Math.Add add4(k2=+1, k1=+1)
    ;
  Modelica.Blocks.Math.Gain gain2(k=K3)
                                 ;
  Modelica.Blocks.Sources.RealExpression realExpression(y=v^2)
    ;

equation

   P=((Limiter1.y)*(v^2))/S_b;
   Q = Q_0/S_b;

  connect(t_ref, add.u1) ;
  connect(product.y, gain.u) ;
  connect(gain1.y, add1.u1) ;
  connect(Limiter.y, add1.u2) ;
  connect(add1.y, Limiter1.u)
    ;
  connect(Limiter1.y, product.u2) ;
  connect(gain.y, add4.u2) ;
  connect(add4.u1, t_a) ;
  connect(firstOrder.u, add4.y) ;
  connect(gain1.u, add.y) ;
  connect(gain2.u, add.y) ;
  connect(gain2.y, Limiter.u)
    ;
  connect(realExpression.y, product.u1) ;
  connect(firstOrder.y, add.u2) 
  ;
end ThermostaticallyControlled;

