within OpenIPSL.Electrical.Loads.PSSE.BaseClasses;
partial model baseLoad "Base load for PSSE models"
  extends OpenIPSL.Electrical.Essentials.pfComponent(
    final enabledisplayPF=false,
    final enablefn=false,
    final enableV_b=false,
    final enableS_b=true,
    final enableangle_0=true,
    final enablev_0=true,
    final enableQ_0=true,
    final enableP_0=true);
 import Modelica.ComplexMath.j;
  parameter Types.ComplexPower S_p=Complex(P_0,Q_0)
    "Consumption of original constant power load";
  parameter Types.ComplexPower S_i=Complex(0.0,0.0)
    "Consumption of original constant current load";
  parameter Types.ComplexPower S_y=Complex(0.0,0.0)
    "Consumption of original constant shunt admittance load";
  parameter Complex a=Complex(1.0,0.0)
    "Load transfer fraction for constant current load";
  parameter Complex b=Complex(0.0,1.0)
    "Load transfer fraction for constant shunt admittance load";
  parameter Types.PerUnit PQBRAK=0.7 "Constant power characteristic threshold";
  parameter Integer characteristic=1 ;
  OpenIPSL.Interfaces.PwPin p(
    vr(start=vr0),
    vi(start=vi0),
    ir(start=ir0),
    ii(start=ii0))
    ;
  Types.Angle angle(start=angle_0) "Bus voltage angle";
  Types.PerUnit v(start=v_0) "Bus voltage magnitude";
  Types.PerUnit P "Active power consumption";
  Types.PerUnit Q "Reactive power consumption";
protected
  parameter Types.PerUnit p0=(S_i.re*v_0 + S_y.re*v_0^2 + S_p.re)/S_b "Initial active power";
  parameter Types.PerUnit q0=(S_i.im*v_0 + S_y.im*v_0^2 + S_p.im)/S_b "Initial reactive power";
  parameter Types.PerUnit vr0=v_0*cos(angle_0) "Initial real voltage";
  parameter Types.PerUnit vi0=v_0*sin(angle_0) "Initial imaginary voltage";
  parameter Types.PerUnit ir0=(p0*vr0 + q0*vi0)/(vr0^2 + vi0^2) "Initial real current";
  parameter Types.PerUnit ii0=(p0*vi0 - q0*vr0)/(vr0^2 + vi0^2) "Initial imaginary current";
  parameter Complex S_P=Complex((1 - a.re - b.re)*S_p.re, (1 - a.im - b.im)*S_p.im)
      /S_b "[pu]";
  parameter Complex S_I=(S_i + Complex(a.re*S_p.re/v_0, a.im*S_p.im/v_0))/S_b
    "[pu]";
  parameter Complex S_Y=(S_y + Complex(b.re*S_p.re/v_0^2, b.im*S_p.im/v_0^2))/
      S_b "[pu]";
  //Constant current load vary function when voltage is below 0.5
  parameter Real a2=1.502;
  parameter Real b2=1.769;
  //Constant Power load vary function when voltage is below 0.5
  parameter Real a0=0.4881;
  parameter Real a1=-0.4999;
  parameter Real b1=0.1389;
  parameter Real wp=3.964;
protected
  Real kP(start=1);
  Real kI(start=1);
equation
  P = p.vr*p.ir + p.vi*p.ii;
  Q = (-p.vr*p.ii) + p.vi*p.ir;
  angle = atan2(p.vi, p.vr);
  v = sqrt(p.vr^2 + p.vi^2);
  //Voltage dependency characteristic
  if characteristic == 1 then
    if v < PQBRAK/2 and v > 0 then
      kP = 2*(v/PQBRAK)^2;
      kI = 1;
    elseif v > PQBRAK/2 and v < PQBRAK then
      kP = 1 - 2*((v - PQBRAK)/PQBRAK)^2;
      kI = 1;
    else
      kP = 1;
      kI = 1;
    end if;
  else
    if v < PQBRAK then
      kP = a0 + a1*cos(v*wp) + b1*sin(v*wp);
    else
      kP = 1;
    end if;
    if v < 0.5 then
      kI = a2*b2*v^(b2 - 1)*exp(-a2*v^b2);
    else
      kI = 1;
    end if;
  end if
  ;
end baseLoad;

within OpenIPSL.Electrical.Machines.PSAT;
model MotorTypeI "Induction Machine - Order I"
  extends OpenIPSL.Electrical.Essentials.pfComponent(
    final enabledisplayPF=false,
    final enablefn=false,
    final enableV_b=false,
    final enableangle_0=true,
    final enablev_0=true,
    final enableQ_0=true,
    final enableP_0=true,
    final enableS_b=true);
  parameter Integer Sup=1 "Start-up control" ;
  parameter Types.PerUnit Rs=0.01 "Stator resistance"
    ;
  parameter Types.PerUnit Xs=0.15 "Stator reactance"
    ;
  parameter Types.PerUnit Rr1=0.05 "1st cage rotor resistance"
    ;
  parameter Types.PerUnit Xr1=0.15 "1st cage rotor reactance"
    ;
  parameter Types.PerUnit Xm=5 "Magnetizing reactance"
    ;
  parameter Types.Time Hm=3 "Inertia constant [Ws/VA]"
    ;
  parameter Types.PerUnit a=0.5 "1st coefficient of tau_m(w)"
    ;
  parameter Types.PerUnit b=0.00 "2nd coefficient of tau_m(w)"
    ;
  parameter Types.PerUnit c=0.00 "3rd coefficient of tau_m(w)"
    ;
  parameter Types.Time tup=0 "Start up time"
    ;
  Types.PerUnit v(start=v_0) "Bus voltage magnitude";
  Types.Angle anglev(start=angle_0) "Bus voltage angle";
  Types.PerUnit s(start=Rr1*P_0/S_b*(Q_0/S_b + v_0*v_0/Xm)/(v_0*v_0*v_0*v_0*(Xs + Xr1)));
  Types.PerUnit Tm;
  Types.PerUnit P(start=P_0/S_b);
  Types.PerUnit Q(start=Q_0/S_b);
  Types.PerUnit Re;
  OpenIPSL.Interfaces.PwPin p(
    vr(start=vr0),
    vi(start=vi0),
    ir(start=ir0),
    ii(start=ii0))
    ;
protected
  parameter Types.PerUnit vr0=v_0*cos(angle_0);
  parameter Types.PerUnit vi0=v_0*sin(angle_0);
  parameter Types.PerUnit ir0=(P_0/S_b*vr0 + Q_0/S_b*vi0)/(vr0^2 + vi0^2);
  parameter Types.PerUnit ii0=(P_0/S_b*vi0 - Q_0/S_b*vr0)/(vr0^2 + vi0^2);
  parameter Types.PerUnit A=a + b + c;
  parameter Types.PerUnit B=(-b) - 2*c;
  parameter Types.PerUnit C=c;
  parameter Types.PerUnit Xe=Xs + Xr1;
initial equation
  der(s) = 0;
equation
  P = p.vr*p.ir + p.vi*p.ii;
  Q = (-p.vr*p.ii) + p.vi*p.ir;
  anglev = atan2(p.vi, p.vr);
  v = sqrt(p.vr^2 + p.vi^2);
  Tm = A + B*s + C*s*s;
  Re = Rs + Rr1/s;
  //s=Rr1/(Re-Rs);
  der(s) = (Tm - P)/(2*Hm);
  p.ii = (-p.vr/Xm) + (p.vi*Re - p.vr*Xe)/(Re*Re + Xe*Xe);
  p.ir = p.vi/Xm + (p.vr*Re + p.vi*Xe)/(Re*Re + Xe*Xe)
  ;
end MotorTypeI;

within OpenIPSL.Electrical.Machines.PSAT;
model MotorTypeIII "Induction Machine - Order III"
  extends OpenIPSL.Electrical.Essentials.pfComponent(
    final enabledisplayPF=false,
    final enablefn=false,
    final enableV_b=false,
    final enableangle_0=true,
    final enablev_0=true,
    final enableQ_0=true,
    final enableP_0=true,
    final enableS_b=true);
  parameter Integer Sup=1 "Start up control" ;
  parameter Types.PerUnit Rs=0.01 "Stator resistance"
    ;
  parameter Types.PerUnit Xs=0.15 "Stator reactance"
    ;
  parameter Types.PerUnit Rr1=0.05 "1st cage rotor resistance"
    ;
  parameter Types.PerUnit Xr1=0.15 "1st cage rotor reactance"
    ;
  parameter Types.PerUnit Xm=5 "Magnetizing reactance"
    ;
  parameter Types.Time Hm=3 "Inertia constant"
    ;
  parameter Types.PerUnit a=0.25 "1st coefficient of tau_m(w)"
    ;
  parameter Types.PerUnit b=0.00 "2nd coefficient of tau_m(w)"
    ;
  parameter Types.PerUnit c=0.00 "3rd coefficient of tau_m(w)"
    ;
  parameter Types.Time tup=0 "Start up time"
    ;
  Types.PerUnit v(start=v_0) "Bus voltage magnitude";
  Types.PerUnit anglev(start=angle_0) "Bus voltage angle";
  Types.PerUnit s(start=S0);
  Types.PerUnit Tm;
  Types.PerUnit Te;
  Types.PerUnit P(start=P_0/S_b);
  Types.PerUnit Q(start=Q_0/S_b);
  Types.PerUnit Vr;
  Types.PerUnit Vm;
  Types.PerUnit Ir;
  Types.PerUnit Im;
  Types.PerUnit epr(start=epr0);
  Types.PerUnit epm(start=epm0);
  Types.PerUnit I;
  Types.Angle anglei;
  OpenIPSL.Interfaces.PwPin p(
    vr(start=vr0),
    vi(start=vi0),
    ir(start=ir0),
    ii(start=ii0))
    ;

  import Modelica.Constants.pi;
protected
  parameter Types.AngularVelocity Omegab=2*pi*fn "Base freq";
  parameter Types.PerUnit vr0=v_0*cos(angle_0);
  parameter Types.PerUnit vi0=v_0*sin(angle_0);
  parameter Types.PerUnit ir0=(P_0/S_b*vr0 + Q_0/S_b*vi0)/(vr0^2 + vi0^2);
  parameter Types.PerUnit ii0=(P_0/S_b*vi0 - Q_0/S_b*vr0)/(vr0^2 + vi0^2);
  parameter Types.PerUnit i2=ir0*ir0 + ii0*ii0;
  parameter Types.PerUnit A=a + b + c;
  parameter Types.PerUnit B=(-b) - 2*c;
  parameter Types.PerUnit C=c;
  parameter Types.PerUnit X0=Xs + Xm;
  parameter Types.PerUnit Xp=Xs + Xr1*Xm/(Xr1 + Xm);
  parameter Types.Time Tp0=(Xr1 + Xm)/(Omegab*Rr1);
  parameter Real RZs2=1/(Rs*Rs + Xp*Xp);
  parameter Real K=Rr1/((Xr1 + Xm)*A);
  parameter Real K2=1 + Tp0*Tp0*Omegab*Omegab*S0*S0;
  parameter Real K1=Tp0*Omegab*S0;
  parameter Real a03=Rs*Rs + Xp*Xp;
  //r1^2+(xS +xR1xm/(xR1 + xm))^2
  parameter Real a13=Rs/a03;
  parameter Real a23=Xp/a03;
  parameter Real S0=K*((-Q_0/S_b) + X0*i2);
  parameter Real epm0=(K1*(X0 - Xp)*ir0 + (X0 - Xp)*(-1)*ii0)/K2;
  parameter Real epr0=(K1*(X0 - Xp)*(-1)*ii0 - (X0 - Xp)*ir0)/K2;
initial equation
  der(s) = 0;
  der(epr) = 0;
  der(epm) = 0;
equation
  anglev = atan2(p.vi, p.vr);
  anglei = atan2(p.ii, p.ir);
  v = sqrt(p.vr^2 + p.vi^2);
  I = sqrt(p.ii^2 + p.ir^2);
  Vr = p.vi;
  Vm = p.vr;
  Im = p.ir;
  Ir = -p.ii;
  P = p.vr*p.ir + p.vi*p.ii;
  Q = (-p.vr*p.ii) + p.vi*p.ir;
  der(s) = (Tm - Te)/(2*Hm);
  Tm = A + B*s + C*s*s;
  Te = epr*Ir + epm*Im;
  der(epr) = Omegab*s*epm - (epr + (X0 - Xp)*Im)/Tp0;
  der(epm) = (-Omegab*s*epr) - (epm - (X0 - Xp)*Ir)/Tp0;
  Im = (-a23*((-Vr) - epr)) + a13*(Vm - epm);
  Ir = a13*((-Vr) - epr) + a23*(Vm - epm)
  ;
end MotorTypeIII;

within OpenIPSL.Electrical.Machines.PSAT;
