  parameter Types.PerUnit a=0.13 "1st coefficient of tau_m(w)"
    ;
  parameter Types.PerUnit b=0.02 "2nd coefficient of tau_m(w)"
    ;
  parameter Types.PerUnit c=0.024 "3rd coefficient of tau_m(w)"
    ;
  parameter Types.Time tup=0 "Start up time"
    ;
  Types.PerUnit v(start=v_0) "Bus voltage magnitude";
  Types.Angle anglev(start=angle_0) " Bus voltage angle";
  Types.PerUnit s(start=S0);
  //(start=Rr1*P_0*(Q_0+v_0*v_0/Xm)/(v_0*v_0*v_0*v_0*(Xs + Xr1)));
  Types.PerUnit Tm;
  Types.PerUnit Te;
  Types.PerUnit P(start=P_0/S_b);
  Types.PerUnit Q(start=Q_0/S_b);
  Types.PerUnit e1r(start=epr0);
  Types.PerUnit e1m(start=epm0);
  Types.PerUnit e2r(start=0.0353);
  Types.PerUnit e2m(start=0.9995);
  Types.PerUnit Vr;
  Types.PerUnit Vm;
  Types.PerUnit Ir;
  Types.PerUnit Im;
  OpenIPSL.Interfaces.PwPin p(
    vr(start=vr0),
    vi(start=vi0),
    ir(start=ir0),
    ii(start=ii0))
    ;
  import Modelica.Constants.pi;

protected
  parameter Types.AngularVelocity Omegab=2*pi*fn "Base freq in rad/s";
  parameter Types.PerUnit vr0=v_0*cos(angle_0);
  parameter Types.PerUnit vi0=v_0*sin(angle_0);
  parameter Types.PerUnit ir0=(P_0*vr0 + Q_0*vi0)/(vr0^2 + vi0^2);
  parameter Types.PerUnit ii0=(P_0*vi0 - Q_0*vr0)/(vr0^2 + vi0^2);
  parameter Types.PerUnit A=a + b + c;
  parameter Types.PerUnit B=(-b) - 2*c;
  parameter Types.PerUnit C=c;
  parameter Types.PerUnit X0=Xs + Xm;
  parameter Types.PerUnit X1=Xs + Xr1*Xm/(Xr1 + Xm);
  parameter Types.Time T10=(Xr1 + Xm)/(Omegab*Rr1);
  parameter Types.PerUnit X2=Xs + Xr1*Xm*Xr2/(Xr1*Xr2 + Xr1*Xm + Xr2*Xm);
  parameter Types.Time T20=(Xr2 + Xr1*Xm/(Xr1 + Xm))/(Omegab*Rr2);
  parameter Real a05=Rs^2 + X2^2;
  parameter Real a15=Rs/a05;
  parameter Real a25=X2/a05;
  parameter Real a35=X0 - X1;
  parameter Real a45=X1 - X2;
  parameter Types.PerUnit i2=ir0*ir0 + ii0*ii0;
  parameter Real K=Rr1/((Xr1 + Xm)*A);
  parameter Real K2=1 + T10*T10*Omegab*Omegab*S0*S0;
  parameter Real K1=T10*Omegab*S0;
  parameter Types.PerUnit S0=K*((-Q_0/S_b) + X0*i2);
  parameter Real epm0=(K1*(X0 - X1)*ir0 + (X0 - X1)*(-1)*ii0)/K2;
  parameter Real epr0=(K1*(X0 - X1)*(-1)*ii0 - (X0 - X1)*ir0)/K2;
initial equation
  der(e2r) = 0;
  der(e2m) = 0;
  der(s) = 0;
  der(e1r) = 0;
  der(e1m) = 0;
equation
  anglev = atan2(p.vi, p.vr);
  v = sqrt(p.vr^2 + p.vi^2);
  Vr = p.vi;
  Vm = p.vr;
  Im = p.ir;
  Ir = -p.ii;
  P = p.vr*p.ir + p.vi*p.ii;
  Q = (-p.vr*p.ii) + p.vi*p.ir;
  Ir = a15*((-Vr) - e2r) + a25*(Vm - e2m);
  Im = (-a25*((-Vr) - e2r)) + a15*(Vm - e2m);
  der(s) = (Tm - Te)/(2*Hm);
  Te = e2r*Ir + e2m*Im;
  der(e1r) = Omegab*s*e1m - (e1r + a35*Im)/T10;
  der(e1m) = (-Omegab*s*e1r) - (e1m - a35*Ir)/T10;
  der(e2r) = (-Omegab*s*(e1m - e2m)) + der(e1r) + (e1r - e2r - a45*Im)/T20;
  der(e2m) = Omegab*s*(e1r - e2r) + der(e1m) + (e1m - e2m + a45*Ir)/T20;
  Tm = A + B*s + C*s*s
  ;
end MotorTypeV;

within OpenIPSL.Electrical.Machines.PSAT;
model Order2 "Second Order Synchronous Machine with Inputs and Outputs"
  extends BaseClasses.baseMachine(vf(start=vf00), xq0=x1d);
protected
  parameter Real K=1/(ra^2 + x1d^2) "a constant for scaling";
  parameter Real c1=ra*K "scaled ra";
  parameter Real c2=x1d*K "scaled x'd";
  parameter Real c3=x1d*K "scaled x'd";
  parameter Types.PerUnit vf00=V_MBtoSB*(vq0 + ra*iq0 + x1d*id0) "Initial value (SB)";
equation
  id = -c1*vd - c3*vq + vf_MB*c3;
  iq = c2*vd - c1*vq + vf_MB*c1;
  vf0 = vf00
  ;
end Order2;

within OpenIPSL.Electrical.Machines.PSAT;
model Order3 "Third Order Synchronous Machine with Inputs and Outputs"
  extends BaseClasses.baseMachine(vf(start=vf00), xq0=xq);
  parameter Types.PerUnit xd "d-axis synchronous reactance"
    ;
  parameter Types.Time T1d0 "d-axis open circuit transient time constant"
    ;
  parameter Types.PerUnit xq "q-axis synchronous reactance"
    ;
  Types.PerUnit e1q(start=e1q0) "q-axis transient voltage";

protected
  parameter Real K=1/(ra^2 + xq*x1d) "a constant for scaling";
  parameter Real c1=ra*K "scaled ra";
  parameter Real c2=x1d*K "scaled x'd";
  parameter Real c3=xq*K " scaled xq";
  parameter Types.PerUnit vf00=V_MBtoSB*(e1q0 + (xd - x1d)*id0) "Inititial value (system base)";
  parameter Real e1q0=vq0 + ra*iq0 + x1d*id0 "Initialization";
initial equation
  der(e1q) = 0;
equation
  der(e1q) = ((-e1q) - (xd - x1d)*id + vf_MB)/T1d0;
  id = (-c1*vd) - c3*vq + e1q*c3;
  iq = c2*vd - c1*vq + e1q*c1;
  vf0 = vf00
  ;
end Order3;

within OpenIPSL.Electrical.Machines.PSAT;
model Order4 "Fourth Order Synchronous Machine with Inputs and Outputs"
  extends BaseClasses.baseMachine(vf(start=vf00), xq0=xq);
  parameter Types.PerUnit xd=1.9 "d-axis synchronous reactance"
    ;
  parameter Types.PerUnit xq=1.7 "q-axis synchronous reactance"
    ;
  parameter Types.PerUnit x1q=0.5 "q-axis transient reactance"
    ;
  parameter Types.Time T1d0=8 "d-axis open circuit transient time constant"
    ;
  parameter Types.Time T1q0=0.8 "q-axis open circuit transient time constant"
    ;
  Types.PerUnit e1q(start=e1q0) "q-axis transient voltage";
  Types.PerUnit e1d(start=e1d0) "d-axis transient voltage";
protected
  parameter Types.PerUnit vf00=V_MBtoSB*(e1q0 + (xd - x1d)*id0) "Initial value (system base)";
  parameter Types.PerUnit e1q0=vq0 + ra*iq0 + x1d*id0 "Initialization";
  parameter Types.PerUnit e1d0=vd0 + ra*id0 - x1q*iq0 "Initialization";
initial equation
  der(e1q) = 0;

equation
  der(e1q) = ((-e1q) - (xd - x1d)*id + vf_MB)/T1d0;
  if abs(xq-x1q) < Modelica.Constants.small then // safe-guard against division by zero.
    der(e1d) = ((-e1d) + (xq - x1q)*iq)/T1q0 "differential equations *";
  else
    der(e1d) = (-e1d)/T1q0 "differential equations *";
  end if;
  e1q = vq + ra*iq + x1d*id;
  e1d = vd + ra*id - x1q*iq "relation between voltages and currents *";
  vf0 = vf00
  ;
end Order4;

within OpenIPSL.Electrical.Machines.PSAT;
model Order5_Type1 "5th order machine model, type 1"
  extends BaseClasses.baseMachine(vf(start=vf00), xq0=xq);
  parameter Types.PerUnit xd=1.9 "d-axis synchronous reactance"
    ;
  parameter Types.PerUnit xq=1.7 "q-axis synchronous reactance"
    ;
  parameter Types.PerUnit x1q=0.5 "q-axis transient reactance"
    ;
  parameter Types.Time T1d0=8 "d-axis open circuit transient time constant"
    ;
  parameter Types.Time T1q0=0.8 "q-axis open circuit transient time constant"
    ;
  parameter Types.Time T2q0=0.02
    "q-axis open circuit sub-transient time constant"
    ;
  Types.PerUnit e1q(start=e1q0) "q-axis transient voltage";
  Types.PerUnit e1d(start=e1d0) "d-axis transient voltage";
  Types.PerUnit e2d(start=e2d0) "d-axis sub-transient voltage";
protected
  parameter Types.PerUnit vf00=V_MBtoSB*(e1q0 + (xd - x1d)*id0) "Init. val. [pu, SB]";
  parameter Types.PerUnit e1q0=vq0 + ra*iq0 + x1d*id0 "Initialization";
  parameter Types.PerUnit e1d0=vd0 + ra*id0 - x1q*iq0 "Initialization*";
  parameter Types.PerUnit e2d0=vd0 + ra*id0 - x1q*iq0 "Initialization";
initial equation
  der(e1q) = 0;
  der(e1d) = 0;
  der(e2d) = 0;
equation
  der(e1q) = ((-e1q) - (xd - x1d)*id + vf_MB)/T1d0;
  der(e1d) = ((-e1d) + (xq - x1q - T2q0/T1q0*x1d/x1q*(xq - x1q))*iq)/T1q0
    "differential equations/";
  der(e2d) = ((-e2d) + e1d + (x1q - x1d + T2q0/T1q0*x1d/x1q*(xq - x1q))*iq)/
    T2q0 "differential equations/";
  e1q = vq + ra*iq + x1d*id;
  e2d = vd + ra*id - x1q*iq "relation between voltages and currents/";
  vf0 = vf00
  ;
end Order5_Type1;

within OpenIPSL.Electrical.Machines.PSAT;
model Order5_Type2 "5th order machine model, type 2"
  extends BaseClasses.baseMachine(vf(start=vf00), xq0=xq);
  parameter Types.PerUnit xd=1.9 "d-axis synchronous reactance"
    ;
  parameter Types.PerUnit xq=1.7 "q-axis synchronous reactance"
    ;
  parameter Types.PerUnit x2d=0.204 "d-axis sub-transient reactance"
    ;
  parameter Types.PerUnit x2q=0.3 "q-axis sub-transient reactance"
    ;
  parameter Types.Time T1d0=8 "d-axis open circuit transient time constant"
    ;
  parameter Types.Time T2d0=0.8 "d-axis open circuit sub-transient time constant"
    ;
  parameter Types.Time T2q0=0.02 "q-axis open circuit sub-transient time constant"
    ;
  parameter Types.Time Taa=0.002 "d-axis additional leakage time constant"
    ;
  Types.PerUnit e1q(start=e1q0) "q-axis transient voltage";
  Types.PerUnit e2q(start=e2q0) "q-axis sub-transient voltage";
  Types.PerUnit e2d(start=e2d0) "d-axis sub-transient voltage";
protected
  parameter Types.PerUnit e2q0=vq0 + ra*iq0 + x2d*id0 "Initialization";
  parameter Types.PerUnit e2d0=vd0 + ra*id0 - x2q*iq0 "Initialization";
  parameter Types.PerUnit K1=xd - x1d - (T2d0*x2d*(xd - x1d))/(T1d0*x1d);
  parameter Types.PerUnit K2=x1d - x2d + (T2d0*x2d*(xd - x1d))/(T1d0*x1d);
  parameter Types.PerUnit e1q0=(-K1*Taa/T1d0*id0) + (1 - Taa/T1d0)*(e2q0 + K2*id0);
  parameter Types.PerUnit vf00=V_MBtoSB*(K1*id0 + e1q0)/(1 - Taa/T1d0)
    "Initial value (system base)";
initial equation
  //der(e1q) = 0;
  der(e2q) = 0;
  der(e2d) = 0;
equation
  der(e1q) = ((-e1q) - (xd - x1d - T2d0/T1d0*x2d/x1d*(xd - x1d))*id + (1 - Taa/
    T1d0)*vf_MB)/T1d0;
  der(e2d) = ((-e2d) + (xq - x2q)*iq)/T2q0;
  der(e2q) = ((-e2q) + e1q - (x1d - x2d + T2d0/T1d0*x2d/x1d*(xd - x1d))*id +
    Taa/T1d0*vf_MB)/T2d0 "differential equations";
  e2q = vq + ra*iq + x2d*id;
  e2d = vd + ra*id - x2q*iq "relation between voltages and currents";
  vf0 = vf00
  ;
end Order5_Type2;

within OpenIPSL.Electrical.Machines.PSAT;
model Order6 "6th order machine model"
  extends BaseClasses.baseMachine(vf(start=vf00), xq0=xq);
  parameter Types.PerUnit xd=1.9 "d-axis synchronous reactance"
    ;
  parameter Types.PerUnit xq=1.7 "q-axis synchronous reactance"
    ;
  parameter Types.PerUnit x1q=0.5 "q-axis transient reactance"
    ;
  parameter Types.PerUnit x2d=0.204 "d-axis sub-transient reactance"
    ;
  parameter Types.PerUnit x2q=0.3 "q-axis sub-transient reactance"
    ;
  parameter Types.Time T1d0=8 "d-axis open circuit transient time constant"
    ;
  parameter Types.Time T1q0=0.8 "q-axis open circuit transient time constant"
    ;
  parameter Types.Time T2d0=0.04 "d-axis open circuit sub-transient time constant"
    ;
  parameter Types.Time T2q0=0.02 "q-axis open circuit sub-transient time constant"
    ;
  parameter Types.Time Taa=2e-3 "d-axis additional leakage time constant"
    ;

  Types.PerUnit e1q(start=e1q0, fixed=true) "q-axis transient voltage";
  Types.PerUnit e1d(start=e1d0) "d-axis transient voltage";
  Types.PerUnit e2q(start=e2q0, fixed=true) "q-axis sub-transient voltage";
  Types.PerUnit e2d(start=e2d0) "d-axis sub-transient voltage";
protected
  parameter Types.PerUnit e2q0=vq0 + ra*iq0 + x2d*id0 "Initialization";
  parameter Types.PerUnit e2d0=vd0 + ra*id0 - x2q*iq0 "Initialization";
  parameter Types.PerUnit e1d0=(xq - x1q - T2q0*x2q*(xq - x1q)/(T1q0*x1q))*iq0;
  parameter Types.PerUnit K1=xd - x1d - T2d0*x2d*(xd - x1d)/(T1d0*x1d);
  parameter Types.PerUnit K2=x1d - x2d + T2d0*x2d*(xd - x1d)/(T1d0*x1d);
  parameter Types.PerUnit e1q0=e2q0 + K2*id0 - Taa/T1d0*((K1 + K2)*id0 + e2q0);
  parameter Types.PerUnit vf00=V_MBtoSB*(K1*id0 + e1q0)/(1 - Taa/T1d0)
    "Init. val. (pu, SB)";
initial equation
  der(e1d) = 0;
  // der(e1d) = 0;
  der(e2d) = 0;
  // der(e2q) = 0;
equation

  der(e1q) = ((-e1q) - (xd - x1d - T2d0/T1d0*x2d/x1d*(xd - x1d))*id + (1 - Taa/
    T1d0)*vf_MB)/T1d0;
  der(e1d) = ((-e1d) + (xq - x1q - T2q0/T1q0*x2q/x1q*(xq - x1q))*iq)/T1q0;
  der(e2d) = ((-e2d) + e1d + (x1q - x2q + T2q0/T1q0*x2q/x1q*(xq - x1q))*iq)/
    T2q0;
  der(e2q) = ((-e2q) + e1q - (x1d - x2d + T2d0/T1d0*x2d/x1d*(xd - x1d))*id +
    Taa/T1d0*vf_MB)/T2d0;
  e2q = vq + ra*iq + x2d*id;
  e2d = vd + ra*id - x2q*iq;
  vf0 = vf00
  ;
end Order6;

within OpenIPSL.Electrical.Machines.PSAT.BaseClasses;
partial model baseMachine "Base machine for PSAT models"
  extends OpenIPSL.Electrical.Essentials.pfComponent(
    final enabledisplayPF=false,
    final enablefn=false,
    final enableangle_0=true,
    final enablev_0=true,
    final enableQ_0=true,
    final enableP_0=true,
    final enableV_b=true,
    final enableS_b=true);
  import CM = Modelica.ComplexMath;
  import Complex;
  parameter Types.ApparentPower Sn "Power rating"
    ;
  parameter Types.Voltage Vn "Voltage rating"
    ;
  parameter Types.PerUnit ra "Armature resistance"
    ;
  parameter Types.PerUnit x1d "d-axis transient reactance"
    ;
  parameter Types.Time M "Mechanical starting time, 2H [Ws/VA]"
    ;
  parameter Real D "Damping coefficient"
    ;

  OpenIPSL.Interfaces.PwPin p(
    vr(start=vr0),
    vi(start=vi0),
    ir(start=ir0),
    ii(start=ii0)) ;
  Modelica.Blocks.Interfaces.RealOutput delta(
    start=delta0,
    quantity="Angle",
    unit="rad",
    displayUnit="rad") "Rotor angle" ;
  Modelica.Blocks.Interfaces.RealOutput w(start=1) "Rotor speed [pu]"
    ;
  Modelica.Blocks.Interfaces.RealOutput v(start=v_0)
    "Generator terminal voltage [pu]" ;
  Modelica.Blocks.Interfaces.RealOutput P(start=p0) "Active power [pu]"
    ;
  Modelica.Blocks.Interfaces.RealOutput Q(start=q0) "Reactive power [pu]"
    ;
  Modelica.Blocks.Interfaces.RealInput vf "Field voltage [pu]" ;
  Modelica.Blocks.Interfaces.RealOutput vf0 "Initial field voltage [pu]"
    ;
  Modelica.Blocks.Interfaces.RealOutput pm0(start=pm00)
    "Initial mechanical power [pu]" ;
  Modelica.Blocks.Interfaces.RealInput pm(start=pm00) "Mechanical power [pu]"
    ;
  Types.Angle anglev(start=angle_0) "Bus voltage angle";
  Types.PerUnit vd(start=vd0) "d-axis voltage";
  Types.PerUnit vq(start=vq0) "q-axis voltage";
  Types.PerUnit id(start=id0) "d-axis current";
  Types.PerUnit iq(start=iq0) "q-axis current";
protected
  Types.PerUnit pe(start=pm00) "electrical power transmitted through the air-gap";
  Types.PerUnit vf_MB=vf*V_b/Vn "field voltage on machine base";
  parameter Types.AngularVelocity w_b=2*C.pi*fn "Base frequency in rad/s";
  // Define multiplicative transforms to go from one pu-base to another:
  parameter Real S_SBtoMB=S_b/Sn "S(system base) -> S(machine base)";
  parameter Real I_MBtoSB=(Sn*V_b)/(S_b*Vn) "I(machine base) -> I(system base)";
  parameter Real V_MBtoSB=Vn/V_b "V(machine base) -> V(system base)";
  parameter Real Z_MBtoSB=(S_b*Vn^2)/(Sn*V_b^2)
    "Z(machine base) -> Z(system base)";

  // Initialize stator quantities (system base):
  parameter Types.PerUnit p0=P_0/S_b
    "Initial active power generation in pu (system base)";
  parameter Types.PerUnit q0=Q_0/S_b
    "Initial reactive power generation in pu (system base)";
  parameter Complex Vt0=CM.fromPolar(v_0, angle_0)
    "Init. val., conjugate";
  parameter Complex S0(re=p0, im=-q0) "Init. val., conjugate";
  parameter Complex I0=S0/(CM.conj(Vt0)) "Init. val., conjugate";
  parameter Types.PerUnit vr0=CM.real(Vt0) "Init. val.";
  parameter Types.PerUnit vi0=CM.imag(Vt0) "Init. val.";
  parameter Types.PerUnit ir0=-CM.real(I0) "Init. val.";
  parameter Types.PerUnit ii0=-CM.imag(I0) "Init. val.";

  // Initialize DQ-quantities (machine base)
  parameter Types.PerUnit xq0 "used for setting the initial rotor angle";
  parameter Types.Angle delta0=CM.arg((Vt0 + ((ra + CM.j*xq0)*Z_MBtoSB*I0)))
    "Init. val. rotor angle";
  parameter Complex Vdq0=Vt0*CM.fromPolar(1/V_MBtoSB, (-delta0 + (C.pi/2)))
    "Init. val (machine base)";
  parameter Complex Idq0=I0*CM.fromPolar(1/I_MBtoSB, (-delta0 + (C.pi/2)))
    "(pu, machine base)";
  parameter Types.PerUnit vd0=CM.real(Vdq0) "Init. val.";
  parameter Types.PerUnit vq0=CM.imag(Vdq0) "Init. val.";
  parameter Types.PerUnit id0=CM.real(Idq0) "Init. val.";
  parameter Types.PerUnit iq0=CM.imag(Idq0) "Init. val.";

  parameter Types.PerUnit pm00=((vq0 + ra*iq0)*iq0 + (vd0 + ra*id0)*id0)/S_SBtoMB
    "Initial value (system base)";

equation
  v = sqrt(p.vr^2 + p.vi^2);
  anglev = atan2(p.vi, p.vr);
  der(delta) = w_b*(w - 1);
  if D > Modelica.Constants.eps then
    der(w) = (pm*S_SBtoMB - pe - D*(w - 1))/M;
  else
    der(w) = (pm*S_SBtoMB - pe)/M;
  end if;
  [p.ir; p.ii] = -[sin(delta), cos(delta); -cos(delta), sin(delta)]*[id; iq]*
    I_MBtoSB;
  [p.vr; p.vi] = [sin(delta), cos(delta); -cos(delta), sin(delta)]*[vd; vq]*
    V_MBtoSB;
  P = -p.vr*p.ir - p.vi*p.ii;
  Q = -p.vi*p.ir + p.vr*p.ii;
  pe = (vq + ra*iq)*iq + (vd + ra*id)*id "pu, machine base";
  pm0 = pm00 "pu, system base"
  ;
end baseMachine;

within OpenIPSL.Electrical.Machines.PSSE;
model GENCLS "Classic generator model that can also represent an infinite bus"
  extends Icons.VerifiedModel;
  extends OpenIPSL.Electrical.Essentials.pfComponent(
    final enabledisplayPF=false,
    final enableangle_0=true,
    final enablev_0=true,
    final enableQ_0=true,
    final enableP_0=true,
    final enablefn=false,
    final enableV_b=false,
    final enableS_b=false);
  OpenIPSL.Interfaces.PwPin p(
    vr(start=vr0),
    vi(start=vi0),
    ir(start=ir0),
    ii(start=ii0)) ;
  parameter Types.ApparentPower M_b=100e6 "Machine base power rating"
    ;
  parameter Types.Time H=0 "Inertia constant"
    ;
  parameter Real D=0 "Damping coefficient"
    ;
  parameter Types.PerUnit R_a=0 "Armature resistance"
    ;
  parameter Types.PerUnit X_d=0.2 "d-axis transient reactance"
    ;
  Types.Angle delta(start=delta0, fixed=true) "Rotor angle";
  Types.PerUnit omega(start=0, fixed=true) "Rotor speed";
  Types.PerUnit V(start=v_0) "Bus voltage magnitude";
  Types.Angle anglev(start=angle_0) "Bus voltage angle";
  Types.PerUnit eq(start=vf0, fixed=true) "Constant emf behind transient reactance";
  Types.PerUnit vd(start=vd0) "d-axis voltage";
  Types.PerUnit vq(start=vq0) "q-axis voltage";
  Types.PerUnit id(start=id0) "d-axis current";
  Types.PerUnit iq(start=iq0) "q-axis current";
  Types.PerUnit P(start=P_0/S_b) "Active power (system base)";
  Types.PerUnit Q(start=Q_0/S_b) "Reactive power (system base)";
protected
  parameter Real CoB=M_b/S_b "Change from system to machine base";
  parameter Types.PerUnit p0=P_0/M_b "Initial active power (machine base)";
  parameter Types.PerUnit q0=Q_0/M_b "Initial reactive power (machine base)";
  parameter Types.PerUnit vr0=v_0*cos(angle_0);
  parameter Types.PerUnit vi0=v_0*sin(angle_0);
  parameter Types.PerUnit ir0=(p0*vr0 + q0*vi0)/(vr0^2 + vi0^2);
  parameter Types.PerUnit ii0=(p0*vi0 - q0*vr0)/(vr0^2 + vi0^2);
  parameter Types.Angle delta0=atan2(vi0 + R_a*ii0 + X_d*ir0, vr0 + R_a*ir0 - X_d*ii0);
  parameter Types.PerUnit vd0=vr0*cos(C.pi/2 - delta0) - vi0*sin(C.pi/2 - delta0);
  parameter Types.PerUnit vq0=vr0*sin(C.pi/2 - delta0) + vi0*cos(C.pi/2 - delta0);
  parameter Types.PerUnit id0=ir0*cos(C.pi/2 - delta0) - ii0*sin(C.pi/2 - delta0);
  parameter Types.PerUnit iq0=ir0*sin(C.pi/2 - delta0) + ii0*cos(C.pi/2 - delta0);
  parameter Types.PerUnit vf0=vq0 + R_a*iq0 + X_d*id0;
equation
  //Swing equation
  //in PSS/E setting to zero is equivalent to removing the swing equation
  if abs(H) > C.eps then
    der(delta) = omega*2*C.pi*fn;
    der(omega) = (P_0/S_b - P - D*omega)/(2*H);
  else
    der(delta) = 0;
    der(omega) = 0;
  end if;
  // d-q voltage and current equations
  der(eq) = 0 "Classical model assumes constant emf";
  vq = eq - R_a*iq - X_d*id "q-axis voltage equation";
  vd = X_d*iq - R_a*id "d-axis voltage equation";
  // Park's transformation
  [p.ir; p.ii] = -CoB*[sin(delta), cos(delta); -cos(delta), sin(delta)]*[id; iq];
  [p.vr; p.vi] = [sin(delta), cos(delta); -cos(delta), sin(delta)]*[vd; vq];
  //Power injections
  -P = p.vr*p.ir + p.vi*p.ii;
  -Q = p.vi*p.ir - p.vr*p.ii;
  // Terminal voltage magnitude and angle
  V = sqrt(p.vr^2 + p.vi^2);
  anglev = atan2(p.vi, p.vr)
  ;
end GENCLS;

within OpenIPSL.Electrical.Machines.PSSE;
model GENSAE "SALIENT POLE GENERATOR MODEL (EXPONENTIAL SATURATION)"
  extends Icons.VerifiedModel;
  // Import of Dependencies
  import OpenIPSL.NonElectrical.Functions.SE_exp;
  import Complex;
  import Modelica.ComplexMath.arg;
  import Modelica.ComplexMath.real;
  import Modelica.ComplexMath.imag;
  import Modelica.ComplexMath.abs;
  import Modelica.ComplexMath.conj;
  import Modelica.ComplexMath.fromPolar;
  import Modelica.ComplexMath.j;
  //Extending machine base
  extends BaseClasses.baseMachine(
    EFD(start=efd0),
    XADIFD(start=efd0),
    PMECH(start=pm0),
    delta(start=delta0, fixed=true),
    id(start=id0),
    iq(start=iq0),
    ud(start=ud0),
    uq(start=uq0),
    Te(start=pm0));
  Types.PerUnit Epq(start=Epq0) "q-axis voltage behind transient reactance";
  Types.PerUnit PSIkd(start=PSIkd0) "d-axis rotor flux linkage";
  Types.PerUnit PSIppq(start=PSIppq0) "q-axis subtransient flux linkage";
  Types.PerUnit PSIppd(start=PSIppd0) "d-axis subtransient flux linkage";
  Types.PerUnit PSId(start=PSId0) "d-axis flux linkage";
  Types.PerUnit PSIq(start=PSIq0) "q-axis flux linkage";
  Types.PerUnit XadIfd(start=efd0) "Machine field current";
  Types.PerUnit PSIpp "Air-gap flux";
protected
  parameter Complex Zs=Complex(R_a,Xppd) "Equivalent impedance";
  parameter Complex VT=Complex(v_0*cos(angle_0),v_0*sin(angle_0))
    "Complex terminal voltage";
  parameter Complex S=Complex(p0,q0) "Complex power on machine base";
  parameter Complex It=Complex(real(S/VT),-imag(S/VT))
    "Complex current, machine base";
  parameter Complex Is=Complex(real(It + VT/Zs),imag(It + VT/Zs))
    "Equivalent internal current source";
  parameter Complex PSIpp0=Complex(real(Zs*Is),imag(Zs*Is))
    "Sub-transient flux linkage in stator reference frame";
  parameter Real ang_PSIpp0=arg(PSIpp0) "flux angle";
  parameter Real ang_It=arg(It) "current angle";
  parameter Real ang_PSIpp0andIt=ang_PSIpp0 - ang_It "angle difference";
  parameter Types.PerUnit abs_PSIpp0=abs(PSIpp0)
    "magnitude of sub-transient flux linkage";
  parameter Real a=abs_PSIpp0 + abs_PSIpp0*dsat*(Xq - Xl)/(Xd - Xl);
  parameter Real b=(It.re^2 + It.im^2)^0.5*(Xppd - Xq);
  //Initializion rotor angle position
  parameter Real delta0=atan(b*cos(ang_PSIpp0andIt)/(b*sin(ang_PSIpp0andIt) - a))
       + ang_PSIpp0 "initial rotor angle in radians";
  parameter Complex DQ_dq=cos(delta0) - j*sin(delta0) "Parks transformation";
  parameter Complex I_dq=real(It*DQ_dq) - j*imag(It*DQ_dq);
  //Initialization of current and voltage components in synchronous reference frame.
  parameter Types.PerUnit iq0=real(I_dq) "q-axis component of initial current";
  parameter Types.PerUnit id0=imag(I_dq) "d-axis component of initial current";
  parameter Types.PerUnit ud0=v_0*cos(angle_0 - delta0 + C.pi/2)
    "d-axis component of initial voltage";
  parameter Types.PerUnit uq0=v_0*sin(angle_0 - delta0 + C.pi/2)
    "q-axis component of initial voltage";
  parameter Complex PSIpp0_dq=real(PSIpp0*DQ_dq) + j*imag(PSIpp0*DQ_dq)
    "Flux linkage in rotor reference frame";
  parameter Types.PerUnit PSIppq0=-imag(PSIpp0_dq)
    "q-axis component of the sub-transient flux linkage";
  parameter Types.PerUnit PSIppd0=real(PSIpp0_dq)
    "d-axis component of the sub-transient flux linkage";
  parameter Types.PerUnit PSIkd0=(PSIppd0 - (Xpd - Xl)*K3d*id0)/(K3d + K4d)
    "d-axis initial rotor flux linkage";
  parameter Types.PerUnit PSId0=PSIppd0 - Xppd*id0;
  parameter Types.PerUnit PSIq0=(-PSIppq0) - Xppq*iq0;
  //Initialization mechanical power and field voltage.
  parameter Types.PerUnit Epq0=uq0 + Xpd*id0 + R_a*iq0;
  parameter Real dsat=SE_exp(
      abs_PSIpp0,
      S10,
      S12,
      1,
      1.2) "To include saturation of during initialization";
  parameter Types.PerUnit efd0=Epq0 + (Xd - Xpd)*id0 + PSIppd0*dsat
    "Initial field voltage magnitude";
  parameter Types.PerUnit pm0=p0 + R_a*iq0*iq0 + R_a*id0*id0
    "Initial mechanical power (pu machine base)";
  // Constants
  parameter Real K1d=(Xpd - Xppd)*(Xd - Xpd)/(Xpd - Xl)^2;
  parameter Real K2d=(Xpd - Xl)*(Xppd - Xl)/(Xpd - Xppd);
  parameter Real K3d=(Xppd - Xl)/(Xpd - Xl);
  parameter Real K4d=(Xpd - Xppd)/(Xpd - Xl);
initial equation
  der(Epq) = 0;
  der(PSIkd) = 0;
  der(PSIppq) = 0;
equation
  //Interfacing outputs with the internal variables
  XADIFD = XadIfd;
  PMECH0 = pm0;
  EFD0 = efd0;
  ISORCE = XadIfd;
  der(Epq) = 1/Tpd0*(EFD - XadIfd);
  der(PSIkd) = 1/Tppd0*(Epq - PSIkd - (Xpd - Xl)*id);
  der(PSIppq) = 1/Tppq0*((-PSIppq) + (Xq - Xppq)*iq - PSIppq*(Xq-Xl)/(Xd-Xl)*SE_exp(
   PSIpp,
   S10,
   S12,
   1,
   1.2));
  PSIppd = Epq*K3d + PSIkd*K4d;
  PSId = PSIppd - Xppd*id;
  PSIq = (-PSIppq) - Xppq*iq;
  PSIpp = sqrt(PSIppd*PSIppd + PSIppq*PSIppq);
  XadIfd = Epq + K1d*(Epq - PSIkd - (Xpd - Xl)*id) + (Xd - Xpd)*id + (SE_exp(
    PSIpp,
    S10,
    S12,
    1,
    1.2))*PSIppd;
  Te = PSId*iq - PSIq*id;
  ud = (-PSIq) - R_a*id;
  uq = PSId - R_a*iq
  ;
end GENSAE;

within OpenIPSL.Electrical.Machines.PSSE;
model GENSAL "SALIENT POLE GENERATOR MODEL (QUADRATIC SATURATION ON D-AXIS)"
  extends Icons.VerifiedModel;
  // Import of Dependencies
  import OpenIPSL.NonElectrical.Functions.SE;
  import Complex;
  import Modelica.ComplexMath.arg;
  import Modelica.ComplexMath.real;
  import Modelica.ComplexMath.imag;
  import Modelica.ComplexMath.conj;
  import Modelica.ComplexMath.fromPolar;
  import Modelica.ComplexMath.j;
  //Extending machine base class
  extends BaseClasses.baseMachine(
    EFD(start=efd0),
    XADIFD(start=efd0),
    PMECH(start=pm0),
    delta(start=delta0, fixed=true),
    id(start=id0),
    iq(start=iq0),
    ud(start=ud0),
    uq(start=uq0),
    Te(start=pm0));
  Types.PerUnit Epq(start=Epq0) "q-axis voltage behind transient reactance";
  Types.PerUnit PSIkd(start=PSIkd0) "d-axis rotor flux linkage";
  Types.PerUnit PSIppq(start=PSIppq0) "q-axis subtransient flux linkage";
  Types.PerUnit PSIppd(start=PSIppd0) "d-axis subtransient flux linkage";
  Types.PerUnit PSId(start=PSId0) "d-axis flux linkage";
  Types.PerUnit PSIq(start=PSIq0) "q-axis flux linkage";
  Types.PerUnit XadIfd(start=efd0) "Machine field current";
protected
  parameter Complex Zs=Complex(R_a,Xppd) "Equivalent impedance";
  parameter Complex VT=Complex(v_0*cos(angle_0),v_0*sin(angle_0))
    "Complex terminal voltage";
  parameter Complex S=Complex(p0,q0) "Complex power on machine base";
  parameter Complex It=Complex(real(S/VT),-imag(S/VT))
    "Complex current, machine base";
  parameter Complex Is=Complex(real(It + VT/Zs),imag(It + VT/Zs))
    "Equivalent internal current source";
  parameter Complex PSIpp0=Complex(real(Zs*Is),imag(Zs*Is))
    "Sub-transient flux linkage in stator reference frame";
  parameter Complex a=Complex(0.0,(Xq - Xppd));
  parameter Complex Epqp=Complex(real(PSIpp0 + a*It),imag(PSIpp0 + a*It));
  parameter Real delta0=arg(Epqp) "rotor angle in radians";
  parameter Complex DQ_dq=Complex(cos(delta0),-sin(delta0)) "Parks transformation";
  parameter Complex I_dq=Complex(real(It*DQ_dq), -imag(It*DQ_dq));
  //Initialization of current and voltage components in synchronous reference frame.
  parameter Types.PerUnit iq0=real(I_dq) "q-axis component of initial current";
  parameter Types.PerUnit id0=imag(I_dq) "d-axis component of initial current";
  parameter Types.PerUnit ud0=v_0*cos(angle_0 - delta0 + C.pi/2)
    "d-axis component of initial voltage";
  parameter Types.PerUnit uq0=v_0*sin(angle_0 - delta0 + C.pi/2)
    "q-axis component of initial voltage";
  parameter Complex PSIpp0_dq=Complex(real(PSIpp0*DQ_dq),imag(PSIpp0*DQ_dq))
    "Flux linkage in rotor reference frame";
  parameter Types.PerUnit PSIppq0=-imag(PSIpp0_dq)
    "q-axis component of the sub-transient flux linkage";
  parameter Types.PerUnit PSIppd0=real(PSIpp0_dq)
    "d-axis component of the sub-transient flux linkage";
  parameter Types.PerUnit PSIkd0=(PSIppd0 - (Xpd - Xl)*K3d*id0)/(K3d + K4d)
    "d-axis initial rotor flux linkage";
  parameter Types.PerUnit PSId0=PSIppd0 - Xppd*id0;
  parameter Types.PerUnit PSIq0=(-PSIppq0) - Xppq*iq0;
  //Initialization mechanical power and field voltage.
  parameter Types.PerUnit Epq0=uq0 + Xpd*id0 + R_a*iq0;
  parameter Real dsat=SE(
      Epq0,
      S10,
      S12,
      1,
      1.2);
  parameter Types.PerUnit efd0=Epq0*(1 + dsat) + (Xd - Xpd)*id0
    "Initial field voltage magnitude";
  parameter Types.PerUnit pm0=p0 + R_a*iq0*iq0 + R_a*id0*id0
    "Initial mechanical power (machine base)";
  // Constants
  parameter Real K1d=(Xpd - Xppd)*(Xd - Xpd)/(Xpd - Xl)^2;
  parameter Real K2d=(Xpd - Xl)*(Xppd - Xl)/(Xpd - Xppd);
  parameter Real K3d=(Xppd - Xl)/(Xpd - Xl);
  parameter Real K4d=(Xpd - Xppd)/(Xpd - Xl);
initial equation
  der(Epq) = 0;
  der(PSIkd) = 0;
  der(PSIppq) = 0;
equation
  //Interfacing outputs with the internal variables
  XADIFD = XadIfd;
  PMECH0 = pm0;
  EFD0 = efd0;
  ISORCE = XadIfd;
  der(Epq) = 1/Tpd0*(EFD - XadIfd);
  der(PSIkd) = 1/Tppd0*(Epq - PSIkd - (Xpd - Xl)*id);
  der(PSIppq) = 1/Tppq0*((-PSIppq) + (Xq - Xppq)*iq);
  PSIppd = Epq*K3d + PSIkd*K4d;
  PSId = PSIppd - Xppd*id;
  PSIq = (-PSIppq) - Xppq*iq;
  XadIfd = K1d*(Epq - PSIkd - (Xpd - Xl)*id) + (Xd - Xpd)*id + (SE(
    Epq,
    S10,
    S12,
    1,
    1.2) + 1)*Epq;
  Te = PSId*iq - PSIq*id;
  ud = (-PSIq) - R_a*id;
  uq = PSId - R_a*iq
  ;
end GENSAL;

within OpenIPSL.Electrical.Machines.PSSE;
model Plant "Framework for an electrical plant including controllers"
  extends Interfaces.Generator;

  replaceable OpenIPSL.Electrical.Machines.PSSE.BaseClasses.baseMachine machine(
    M_b=100000000,
    Tpd0=1,
    Tppd0=1,
    Tppq0=1,
    H=1,
    D=1,
    Xd=0.01,
    Xq=0.01,
    Xpd=0.01,
    Xppd=0.01,
    Xppq=0.01,
    Xl=0.01,
    S10=1,
    S12=1)
    ;
  replaceable Controls.PSSE.ES.BaseClasses.BaseExciter exciter
    ;
  Modelica.Blocks.Sources.Constant zero(k=0) ;
  replaceable Controls.PSSE.TG.BaseClasses.BaseGovernor governor
    ;
  replaceable OpenIPSL.Electrical.Controls.PSSE.PSS.BaseClasses.BasePSS pss
    ;
equation
  connect(pss.V_S2, governor.PMECH0) ;
  connect(pss.V_S1, machine.SPEED) ;
  connect(machine.p, pwPin)
    ;
  connect(exciter.XADIFD, machine.XADIFD) ;
  connect(machine.EFD0, exciter.EFD0) ;
  connect(exciter.ECOMP, machine.ETERM) ;
  connect(zero.y, exciter.VUEL) ;
  connect(governor.PMECH, machine.PMECH) ;
  connect(governor.SPEED, machine.SPEED) ;
  connect(machine.PMECH0, governor.PMECH0) ;

  connect(exciter.EFD, machine.EFD) ;
  connect(zero.y, exciter.VOEL) ;
  connect(pss.VOTHSG, exciter.VOTHSG) 
  ;
end Plant;

within OpenIPSL.Electrical.Machines.PSSE.BaseClasses;
partial model baseMachine "Base machine for PSSE models"
  import Complex;
  import Modelica.ComplexMath.arg;
  import Modelica.ComplexMath.real;
  import Modelica.ComplexMath.imag;
  import Modelica.ComplexMath.conj;
  import Modelica.Blocks.Interfaces.*;
  extends OpenIPSL.Electrical.Essentials.pfComponent(
    final enabledisplayPF=false,
    final enablefn=false,
    final enableV_b=false,
    final enableangle_0=true,
    final enablev_0=true,
    final enableQ_0=true,
    final enableP_0=true,
    final enableS_b=true);
  //Machine parameters
  parameter Types.ApparentPower M_b "Machine base power"
    ;
  parameter Types.Time Tpd0 "d-axis transient open-circuit time constant"
    ;
  parameter Types.Time Tppd0 "d-axis sub-transient open-circuit time constant"
    ;
  parameter Types.Time Tppq0 "q-axis sub-transient open-circuit time constant"
    ;
  parameter Types.Time H "Inertia constant"
    ;
  parameter Real D "Speed damping"
    ;
  parameter Types.PerUnit Xd "d-axis reactance"
    ;
  parameter Types.PerUnit Xq "q-axis reactance"
    ;
  parameter Types.PerUnit Xpd "d-axis transient reactance"
    ;
  parameter Types.PerUnit Xppd "d-axis sub-transient reactance"
    ;
  parameter Types.PerUnit Xppq "q-axis sub-transient reactance"
    ;
  parameter Types.PerUnit Xl "leakage reactance"
    ;
  parameter Types.PerUnit S10 "Saturation factor at 1.0 pu"
    ;
  parameter Types.PerUnit S12 "Saturation factor at 1.2 pu"
    ;
  parameter Types.PerUnit R_a=0 "Armature resistance"
    ;
  parameter Types.PerUnit w0(min=-1+C.eps)=0 "Initial speed deviation from nominal"
    ;
  OpenIPSL.Interfaces.PwPin p(
    vr(start=vr0),
    vi(start=vi0),
    ir(start=ir0),
    ii(start=ii0))
    ;
  RealOutput SPEED "Machine speed deviation from nominal [pu]"
    ;
  RealInput PMECH "Turbine mechanical power (machine base)"
    ;
  RealOutput PMECH0 "Initial value of machine electrical power (machine base)"
    ;
  RealOutput ETERM(start=v_0) "Machine terminal voltage [pu]"
    ;
  RealInput EFD "Generator main field voltage [pu]"
    ;
  RealOutput EFD0 "Initial generator main field voltage [pu]"
    ;
  RealOutput PELEC(start=p0) "Machine electrical power (machine base)"
    ;
  RealOutput ISORCE "Machine source current [pu]"
    ;
  RealOutput ANGLE "Machine relative rotor angle"
    ;
  RealOutput XADIFD "Machine field current [pu]" ;
  Types.PerUnit w(start=w0, fixed=true) "Machine speed deviation";
  Types.Angle delta "Rotor angle";
  Types.PerUnit Vt(start=v_0) "Bus voltage magnitude";
  Types.Angle anglev(start=angle_0) "Bus voltage angle";
  Types.PerUnit I(start=sqrt(ir0^2 + ii0^2)) "Terminal current magnitude";
  Types.Angle anglei(start=atan2(ii0, ir0)) "Terminal current angle";
  Types.PerUnit P(start=P_0/S_b) "Active power (system base)";
  Types.PerUnit Q(start=Q_0/S_b) "Reactive power (system base)";
  Types.PerUnit Te "Electrical torque [pu]";
  Types.PerUnit id "d-axis armature current [pu]";
  Types.PerUnit iq "q-axis armature current [pu]";
  Types.PerUnit ud "d-axis terminal voltage [pu]";
  Types.PerUnit uq "q-axis terminal voltage [pu]";
protected
  parameter Types.AngularVelocity w_b=2*C.pi*fn "System base speed";
  parameter Real CoB=M_b/S_b;
  parameter Types.PerUnit vr0=v_0*cos(angle_0)
    "Real component of initial terminal voltage";
  parameter Types.PerUnit vi0=v_0*sin(angle_0)
    "Imaginary component of initial terminal voltage";
  parameter Types.PerUnit ir0=-CoB*(p0*vr0 + q0*vi0)/(vr0^2 + vi0^2)
    "Real component of initial armature current (system base)";
  parameter Types.PerUnit ii0=-CoB*(p0*vi0 - q0*vr0)/(vr0^2 + vi0^2)
    "Imaginary component of initial armature current (system base)";
  parameter Types.PerUnit p0=P_0/M_b "Initial active power generation (machine base)";
  parameter Types.PerUnit q0=Q_0/M_b
    "Initial reactive power generation (machine base)";
equation
  //Interfacing outputs with the internal variables
  ANGLE = delta;
  SPEED = w;
  ETERM = Vt;
  PELEC = P/CoB;
  [p.ir; p.ii] = -CoB*[sin(delta), cos(delta); -cos(delta), sin(delta)]*[id; iq];
  [p.vr; p.vi] = [sin(delta), cos(delta); -cos(delta), sin(delta)]*[ud; uq];
  -P = p.vr*p.ir + p.vi*p.ii;
  -Q = p.vi*p.ir - p.vr*p.ii;
  Vt = sqrt(p.vr^2 + p.vi^2);
  anglev = atan2(p.vi, p.vr);
  I = sqrt(p.ii^2 + p.ir^2);
  anglei = atan2(p.ii, p.ir);
  der(w) = ((PMECH - D*w)/(w + 1) - Te)/(2*H);
  der(delta) = w_b*w
  ;
end baseMachine;

within OpenIPSL.Electrical.Renewables.PSSE;
package AddOnBlocks
  "This package contains additional add ons that can be added to the original renewable models."
  model IrradianceToPower "PV Array Power Output from Irradiance."

    parameter Modelica.Units.SI.ActivePower Ypv = 1000 "Rated capacity of the PV array";
    parameter Modelica.Units.SI.Temperature Tcstc = 25 "PV cell temperature under standard test conditions";
    parameter Real fpv = 0.9 "PV derating factor";
    parameter Real ap = -0.48 "Temperature coefficient of power";
    parameter Modelica.Units.SI.RadiantEnergyFluenceRate Gtstc = 1000;




    Modelica.Blocks.Interfaces.RealOutput Ppv
      ;
    Modelica.Blocks.Sources.CombiTimeTable SolarRadiation
      ;
    Modelica.Blocks.Sources.CombiTimeTable SolarArrayTemperature
      ;




  equation

    Ppv = Ypv*fpv*(SolarRadiation.y[1]/Gtstc)*(1 + ap*(SolarArrayTemperature.y[1] - Tcstc))

    ;
  end IrradianceToPower;
end AddOnBlocks;

within OpenIPSL.Electrical.Renewables.PSSE;
model BESS "Framework for a battery energy storage system plant including controllers"
parameter Types.ApparentPower M_b=RenewableGenerator.SysData.S_b "Machine base power" ;
extends OpenIPSL.Electrical.Essentials.pfComponent(
    final enablefn=true,
    final enableV_b=false,
    final enableangle_0=true,
    final enablev_0=true,
    final enableQ_0=true,
    final enableP_0=true,
    final enabledisplayPF=true,
    final enableS_b=true);

  // Parameters for selection
  parameter Integer QFunctionality = 0 "BESS Reactive Power Control Options" ;
  parameter Integer PFunctionality = 0 "BESS Real Power Control Options" ;

  replaceable
    OpenIPSL.Electrical.Renewables.PSSE.InverterInterface.BaseClasses.BaseREGC
    RenewableGenerator(
    M_b=M_b,
    P_0=P_0,
    Q_0=Q_0,
    v_0=v_0,
    angle_0=angle_0) ;
  replaceable
    OpenIPSL.Electrical.Renewables.PSSE.ElectricalController.BaseClasses.BaseREECC
    RenewableController(
    pfflag=pfflag,
    vflag=vflag,
    qflag=qflag,
    pqflag=false) ;
  Interfaces.PwPin pwPin
    ;
  replaceable
    OpenIPSL.Electrical.Renewables.PSSE.PlantController.BaseClasses.BaseREPC
    PlantController(
    M_b=M_b,
    P_0=P_0,
    Q_0=Q_0,
    v_0=v_0,
    angle_0=angle_0,
    fflag=fflag,
    refflag=refflag) if QFunctionality >= 4 ;
  Modelica.Blocks.Math.Gain gain(k=1)
                                 if QFunctionality < 4
    ;
  Modelica.Blocks.Math.Gain gain1(k=1)
                                  if QFunctionality < 4
    ;
  Modelica.Blocks.Sources.Constant freq_ref(k=SysData.fn) if QFunctionality >= 4
    ;
  Modelica.Blocks.Interfaces.RealInput FREQ if QFunctionality >= 4 "Connection Point Frequency"
    ;

  Modelica.Blocks.Sources.Constant PAUX(k=0)
    ;
  Modelica.Blocks.Interfaces.RealInput branch_ir if QFunctionality >= 4 "Measured Branch Real Current"
    ;
  Modelica.Blocks.Interfaces.RealInput branch_ii if QFunctionality >= 4 "Measured Branch Imaginary Current"
    ;
  Modelica.Blocks.Interfaces.RealInput regulate_vr if QFunctionality >= 4 "Regulated Branch Real Voltage"
    ;
  Modelica.Blocks.Interfaces.RealInput regulate_vi if QFunctionality >= 4 "Regulated Branch Imaginary Voltage"
    ;
protected
      parameter Boolean pfflag = (if QFunctionality == 0 then true else false);
