        parameter OpenIPSL.Types.PerUnit SOCmin "Minimum allowable state of charge";
        parameter OpenIPSL.Types.PerUnit SOCmax "Maximum allowable state of charge";
equation
  ipmax_SOC = if SOC <= SOCmin then 0 else 1;
  ipmin_SOC = if SOC >= SOCmax then 0 else 1

  ;
end StateOfChargeLogic;

within OpenIPSL.Electrical.Renewables.PSSE.InverterInterface;
model REGCA1 "Renewable energy generator/converter model A"
  extends BaseClasses.BaseREGC;
  Modelica.Blocks.Sources.RealExpression Vt(y=VT)
    ;
  Modelica.Blocks.Math.Add add(k2=-1)
    ;
  Modelica.Blocks.Sources.Constant Vo_limit(k=Volim)
    ;
  Modelica.Blocks.Nonlinear.Limiter min_limiter(uMax=Modelica.Constants.inf,
      uMin=0) ;
  Modelica.Blocks.Math.Add add1(k2=-1)
    ;
  Modelica.Blocks.Nonlinear.Limiter IOLIM(uMax=Modelica.Constants.inf,
                                                    uMin=Iolim)
    ;
  OpenIPSL.Electrical.Renewables.PSSE.InverterInterface.BaseClasses.LVACM LVACM(lvpnt0=
        lvpnt0, lvpnt1=lvpnt1)
    ;
  OpenIPSL.NonElectrical.Continuous.SimpleLag simpleLag(
    K=1,
    T=Tfltr,
    y_start=v_0)
    ;
  OpenIPSL.Electrical.Renewables.PSSE.InverterInterface.BaseClasses.LVPL LVPL(
    Brkpt=Brkpt,
    Lvpl1=Lvpl1,
    Zerox=Zerox)
    ;
  Modelica.Blocks.Math.Product IP
    ;
public
  Modelica.Blocks.Math.Gain KHV(k=Khv)
    ;
  Modelica.Blocks.Logical.Switch switch1 ;
  Modelica.Blocks.Sources.BooleanConstant Lvplsw_logic(k=Lvplsw)
    ;
  Modelica.Blocks.Nonlinear.Limiter limiter4(uMax=rrpwr, uMin=-Modelica.Constants.inf)
    ;
  Modelica.Blocks.Math.Add add2(k2=-1)
    ;
  Modelica.Blocks.Sources.RealExpression Terminal_Voltage1(y=Vt.y) ;
  Modelica.Blocks.Sources.RealExpression LowerLimit(y=-Modelica.Constants.inf)
    ;
  Modelica.Blocks.Math.Add add3(k2=-1)
    ;
  Modelica.Blocks.Nonlinear.Limiter limiter1(uMax=Iqrmax, uMin=Iqrmin)
    ;
  Modelica.Blocks.Continuous.Integrator integrator(
    k=1/Tg,
    initType=Modelica.Blocks.Types.Init.InitialState,
    y_start=Iq0)
    ;
  Modelica.Blocks.Math.Gain gain(k=-1)
    ;
  Modelica.Blocks.Sources.RealExpression Constant(y=Modelica.Constants.inf)
    ;
  Modelica.Blocks.Continuous.Integrator integrator1(
    k=1/Tg,
    initType=Modelica.Blocks.Types.Init.InitialState,
    y_start=Ip0)
    ;
  Modelica.Blocks.Nonlinear.VariableLimiter variableLimiter
    ;
equation
  [IP.y; IOLIM.y] = -[cos(delta), sin(delta); -sin(delta), cos(delta)]*[p.ir/CoB; p.ii/CoB];
  V_t = VT;
  Pgen = -(1/CoB)*(p.vr*p.ir + p.vi*p.ii);
  Qgen = -(1/CoB)*(p.vi*p.ir - p.vr*p.ii);
  IQ0 = Iq0;
  IP0 = Ip0;
  V_0 = v_0;
  p_0 = p0;
  q_0 = q0;

  connect(add.y,KHV. u)
    ;
  connect(LVPL.V,simpleLag. y)
    ;
  connect(LVACM.y,IP. u2) ;
  connect(switch1.u1,LVPL. y)
    ;
  connect(Lvplsw_logic.y,switch1. u2) ;
  connect(KHV.y,min_limiter. u)
    ;
  connect(Vt.y,add. u1) ;
  connect(simpleLag.u,LVACM. Vt) ;
  connect(Vo_limit.y,add. u2)
    ;
  connect(add2.y,limiter4. u)
    ;
  connect(Terminal_Voltage1.y,LVACM. Vt) ;
  connect(add3.y,limiter1. u)
    ;
  connect(limiter1.y,integrator. u)
    ;
  connect(integrator.y,add3. u2) ;
  connect(gain.y,add3. u1) ;
  connect(gain.u, Iqcmd) ;
  connect(Ipcmd,add2. u1) ;
  connect(Constant.y, switch1.u3) ;
  connect(limiter4.y, integrator1.u)
    ;
  connect(LowerLimit.y, variableLimiter.limit2) ;
  connect(integrator1.y, variableLimiter.u)
    ;
  connect(variableLimiter.limit1, switch1.y) ;
  connect(variableLimiter.y, add2.u2) ;
  connect(IP.u1, add2.u2) ;
  connect(add1.y, IOLIM.u)
    ;
  connect(add1.u1, integrator.y) ;
  connect(min_limiter.y, add1.u2) 
  ;
end REGCA1;

within OpenIPSL.Electrical.Renewables.PSSE.InverterInterface.BaseClasses;
partial model BaseREGC "Base renewable generator/converter for PSSE models"
  import Complex;
  import Modelica.ComplexMath.arg;
  import Modelica.ComplexMath.real;
  import Modelica.ComplexMath.imag;
  import Modelica.ComplexMath.conj;
  import Modelica.Blocks.Interfaces.*;
  parameter OpenIPSL.Types.ApparentPower M_b=SysData.S_b "Machine base power" ;
  extends OpenIPSL.Electrical.Essentials.pfComponent(
    final enabledisplayPF=false,
    final enablefn=false,
    final enableV_b=false,
    final enableangle_0=true,
    final enablev_0=true,
    final enableQ_0=true,
    final enableP_0=true,
    final enableS_b=true);

  // Set of Model Parameters
  parameter Modelica.Units.SI.Time Tg = 0.02 "Converter time constant" ;
  parameter Modelica.Units.SI.TimeAging rrpwr = 10 "Low Voltage Power Logic (LVPL) ramp rate limit" ;
  parameter OpenIPSL.Types.PerUnit Brkpt = 0.9 "LVPL characteristic voltage 2" ;
  parameter OpenIPSL.Types.PerUnit Zerox = 0.5 "LVPL characteristic voltage 1" ;
  parameter OpenIPSL.Types.PerUnit Lvpl1 = 1.22 "LVPL gain" ;
  parameter OpenIPSL.Types.PerUnit Volim = 1.2 "Voltage limit for high voltage reactive current management" ;
  parameter OpenIPSL.Types.PerUnit lvpnt1 = 0.8 "High voltage point for low voltage active current management" ;
  parameter OpenIPSL.Types.PerUnit lvpnt0 = 0.4 "Low voltage point for low voltage active current management" ;
  parameter OpenIPSL.Types.PerUnit Iolim = -1.3 "Current limit for high voltage reactive current management (specified as a negative value)" ;
  parameter Modelica.Units.SI.Time Tfltr = 0.02 "Voltage filter time constant for low voltage active current management" ;
  parameter Real Khv = 0.7 "Overvoltage compensation gain used in the high voltage reactive current management" ;
  parameter Modelica.Units.SI.TimeAging Iqrmax = 9999 "Upper limit on rate of change for reactive current" ;
  parameter Modelica.Units.SI.TimeAging Iqrmin = -9999 "Lower limit on rate of change for reactive current" ;

  parameter Boolean Lvplsw=true "Enable (true) or disable (false) low voltage power logic." ;

  OpenIPSL.Interfaces.PwPin p(
    vr(start=vr0),
    vi(start=vi0),
    ir(start=-ir0*CoB),
    ii(start=-ii0*CoB)) ;
  Modelica.Blocks.Interfaces.RealInput Iqcmd "Imaginary Command Current"
                                                                        ;
  Modelica.Blocks.Interfaces.RealInput Ipcmd "Real Command Current" ;
  Modelica.Blocks.Interfaces.RealOutput IQ0 "Initial Reactive Power" ;
  Modelica.Blocks.Interfaces.RealOutput IP0 "Initial Active Power" ;
  Modelica.Blocks.Interfaces.RealOutput V_0 "Initial Terminal Voltage Magnitude" ;
  Modelica.Blocks.Interfaces.RealOutput q_0 "Initial Reactive Power" ;
  Modelica.Blocks.Interfaces.RealOutput p_0 "Initial Active Power" ;
  Modelica.Blocks.Interfaces.RealOutput V_t "Terminal Voltage Magnitude" ;
  Modelica.Blocks.Interfaces.RealOutput Pgen "Active Power injection"
    ;
  Modelica.Blocks.Interfaces.RealOutput Qgen "Reactive Power injection"
    ;
protected
  OpenIPSL.Types.Angle delta(start=angle_0);
  OpenIPSL.Types.PerUnit VT(start=v_0) "Bus voltage magnitude";
  OpenIPSL.Types.Angle anglev(start=angle_0) "Bus voltage angle";
  parameter OpenIPSL.Types.PerUnit p0=P_0/M_b "Initial active power (machine base)";
  parameter OpenIPSL.Types.PerUnit q0=Q_0/M_b "Initial reactive power (machine base)";
  parameter OpenIPSL.Types.PerUnit vr0=v_0*cos(angle_0);
  parameter OpenIPSL.Types.PerUnit vi0=v_0*sin(angle_0);
  parameter OpenIPSL.Types.PerUnit ir0=(p0*vr0 + q0*vi0)/(vr0^2 + vi0^2);
  parameter OpenIPSL.Types.PerUnit ii0=(p0*vi0 - q0*vr0)/(vr0^2 + vi0^2);
  parameter OpenIPSL.Types.PerUnit Isr0=ir0 "Source current re M_b";
  parameter OpenIPSL.Types.PerUnit Isi0=ii0 "Source current im M_b";
  parameter OpenIPSL.Types.PerUnit Ip0=Isr0*cos(-angle_0) - Isi0*sin(-angle_0);
  parameter OpenIPSL.Types.PerUnit Iq0=(Isr0*sin(-angle_0) + cos(-angle_0)*Isi0);
  parameter Real CoB=M_b/S_b "Change of base";

equation
  anglev = atan2(p.vi, p.vr);
  VT = sqrt(p.vr*p.vr + p.vi*p.vi);
  delta = anglev

 ;
end BaseREGC;

within OpenIPSL.Electrical.Renewables.PSSE.InverterInterface.BaseClasses;
model LVACM "Low Voltage Active Control Management"
        parameter OpenIPSL.Types.PerUnit lvpnt0 "Low voltage point for low voltage active current management";
        parameter OpenIPSL.Types.PerUnit lvpnt1 "High voltage point for low voltage active current management";
  Modelica.Blocks.Interfaces.RealOutput y
    ;
  Modelica.Blocks.Interfaces.RealInput Vt
    ;

equation
  y = smooth(1,noEvent(if Vt <= lvpnt0 then 0 elseif Vt >= lvpnt1 then 1 else (1/(lvpnt1-lvpnt0))*(Vt-lvpnt0)))
    ;
end LVACM;

within OpenIPSL.Electrical.Renewables.PSSE.InverterInterface.BaseClasses;
model LVPL "Low Voltage Power Logic"
  Modelica.Blocks.Interfaces.RealOutput y
    ;
  Modelica.Blocks.Interfaces.RealInput V
    ;
        parameter OpenIPSL.Types.PerUnit Brkpt "LVPL characteristic voltage 2";
        parameter OpenIPSL.Types.PerUnit Lvpl1 "LVPL gain ";
        parameter OpenIPSL.Types.PerUnit Zerox "LVPL characteristic voltage 1";
equation

  y = noEvent(if V < Zerox then 0 else if V > Brkpt then Lvpl1 else (V-Zerox)*(Lvpl1/(Brkpt-Zerox)))

    ;
end LVPL;

