model SoftPMU "Model of a PMU measuring phasors on a line"
  outer OpenIPSL.Electrical.SystemBase SysData;
  OpenIPSL.Interfaces.PwPin p
    "the positive direction of the current is from connector p ..." ;
  OpenIPSL.Interfaces.PwPin n "... and to connector n" ;
  parameter Types.PerUnit v_0 = 1 "Voltage magnitude initial value" ;
  parameter Types.Angle angle_0 = 0 "Voltage angle initial value" ;
  parameter Types.Time Ts = 0.01 "Derivative smoothing filter time constant" ;
  parameter Types.Frequency fn = SysData.fn "System base frequency" ;
public
  Types.PerUnit Vr=p.vr "real part of the voltage phasor";
  Types.PerUnit Vi=p.vi "imaginary part of the voltage phasor";
  Types.PerUnit Ir=p.ir "real part of the current phasor";
  Types.PerUnit Ii=p.ii "imaginary part of the current phasor";
  Types.Frequency freq "frequency estimate";
protected
  parameter Types.PerUnit vr_0=v_0*cos(angle_0);
  parameter Types.PerUnit vi_0=v_0*sin(angle_0);
public
  NonElectrical.Nonlinear.FrequencyCalc fCalc(
    real_start=vr_0,
    imag_start=vi_0,
    start_guess=true,
    Ts=Ts)
    ;
equation
  connect(p, n);
  fCalc.real_part = p.vr;
  fCalc.imag_part = p.vi;
  freq = fCalc.y/(2*C.pi) + fn
  ;
end SoftPMU;

within OpenIPSL.Electrical.Solar.PowerFactory.DIgSILENT;
model Controller "Controller for the solar plant"
  parameter Real Kp = 0.005 "Gain, Active Power PI-Controller";
  parameter Types.Time Tip = 0.03 "Integration Time Constant, Active Power PI-Ctrl.";
  parameter Types.Time Tr = 0.001 "Measurement Delay";
  parameter Types.Time Tmpp = 5 "Time Delay MPP-Tracking";
  parameter Types.PerUnit id_min = 0 "Min. Active Current Limit";
  parameter Types.PerUnit id_max = 1 "Max. Active Current Limit";
  parameter Types.Voltage U_min = 200 "Minimal allowed DC-voltage";
  parameter Real iq_min = -1 "Min. Reactive Current Limit";
  parameter Real iq_max = 1 "Max. Reactive Current Limit";
  parameter Real Deadband = 0.1 "Deadband for Dynamic AC Voltage Support";
  parameter Real K_FRT = 2 "Gain for Dynamic AC Voltage Support";
  parameter Boolean i_EEG = false "false = acc. TC2007; true = acc. SDLWindV";
  parameter Types.PerUnit maxAbsCur = 1 "Max. allowed absolute current";
  parameter Types.PerUnit maxIq = 1 "Max.abs reactive current in normal operation";
  parameter Types.PerUnit uac0 = 1 "Initial voltage magnitude";
  parameter Types.PerUnit iq0 = -0.2 "Initial q-axis current";
  parameter Types.PerUnit id0 = 0.6 "Initial d-axis current";
  Modelica.Blocks.Interfaces.RealInput vdcref ;
  Modelica.Blocks.Interfaces.RealInput uac ;
  Modelica.Blocks.Interfaces.RealInput pred ;
  Modelica.Blocks.Math.Feedback feedback ;
  Modelica.Blocks.Continuous.FirstOrder MPP_delay(T = Tmpp, initType = Modelica.Blocks.Types.Init.SteadyState) ;
  Modelica.Blocks.Interfaces.RealInput vdcin ;
  Modelica.Blocks.Continuous.FirstOrder voltage_measurement_delay(T = Tr, initType = Modelica.Blocks.Types.Init.InitialOutput, y_start = uac0) ;
  Modelica.Blocks.Sources.Constant reference_voltage(k = uac0) ;
  Modelica.Blocks.Nonlinear.Limiter limiter(uMax=Modelica.Constants.inf, uMin=U_min) ;
  Modelica.Blocks.Math.Feedback feedback1 ;
  Modelica.Blocks.Continuous.FirstOrder filter(T = Tr, initType = Modelica.Blocks.Types.Init.SteadyState, y_start = 0) ;
  Modelica.Blocks.Interfaces.RealOutput id_ref ;
  Modelica.Blocks.Interfaces.RealOutput iq_ref ;
  OpenIPSL.Electrical.Solar.PowerFactory.DIgSILENT.Auxiliary.ReactivePowerSupport reactivePowerSupport(Deadband = Deadband, K_FRT = K_FRT, i0 = iq0, i_EEG = i_EEG, iq_max = iq_max, iq_min = iq_min) ;
  OpenIPSL.Electrical.Solar.PowerFactory.DIgSILENT.CurrentLimiter current_limiter(Deadband = Deadband, maxAbsCur = maxAbsCur, maxIq = maxIq, i_EEG = i_EEG) ;
  OpenIPSL.Electrical.Solar.PowerFactory.DIgSILENT.Auxiliary.ActivePowerController activePowerController(K = Kp, T = Tip, id0 = id0,yo_max = id_max, yo_min = id_min) ;
equation
  connect(vdcref, MPP_delay.u) ;
  connect(uac, voltage_measurement_delay.u) ;
  connect(voltage_measurement_delay.y, feedback.u1) ;
  connect(reference_voltage.y, feedback.u2) ;
  connect(vdcin, feedback1.u1) ;
  connect(feedback1.y, filter.u) ;
  connect(filter.y, activePowerController.yi) ;
  connect(MPP_delay.y, limiter.u) ;
  connect(limiter.y, feedback1.u2) ;
  connect(feedback.y, reactivePowerSupport.duac) ;
  connect(current_limiter.iqout, iq_ref) ;
  connect(current_limiter.idout, id_ref) ;
  connect(reactivePowerSupport.iq, current_limiter.iqin) ;
  connect(current_limiter.duac, feedback.y) ;
  connect(activePowerController.yo, current_limiter.idin) ;
  connect(activePowerController.pred, pred) 
  ;
end Controller;

within OpenIPSL.Electrical.Solar.PowerFactory.DIgSILENT;
model CurrentLimiter "Limiter of d- and q-axis currents"
  parameter Types.PerUnit maxAbsCur;
  parameter Types.PerUnit maxIq;
  parameter Types.PerUnit Deadband;
  parameter Boolean i_EEG;
  Modelica.Blocks.Interfaces.RealInput idin ;
  Modelica.Blocks.Interfaces.RealInput iqin ;
  Modelica.Blocks.Interfaces.RealInput duac ;
  Modelica.Blocks.Interfaces.RealOutput idout ;
  Modelica.Blocks.Interfaces.RealOutput iqout ;
  Modelica.Blocks.Nonlinear.Limiter dlim_normal_op(uMax=maxAbsCur, uMin=-maxAbsCur) ;
  Modelica.Blocks.Nonlinear.Limiter qlim_frt_op(uMax=maxAbsCur, uMin=-maxAbsCur) ;
  Modelica.Blocks.Nonlinear.VariableLimiter qlim_normal_op ;
  Modelica.Blocks.Nonlinear.VariableLimiter dlim_frt_op ;
  Modelica.Blocks.Sources.Constant maximum_current(k = maxAbsCur) ;
  Modelica.Blocks.Math.Add add(k1 = -1, k2 = +1) ;
  Modelica.Blocks.Math.Abs abs1 ;
  Modelica.Blocks.Math.Gain gain(k = -1) ;
  Modelica.Blocks.Math.Min min ;
  Modelica.Blocks.Sources.Constant const(k = maxIq) ;
  Modelica.Blocks.Math.Gain gain1(k = -1) ;
  Modelica.Blocks.Math.Pythagoras pythagoras(u1IsHypotenuse = true) ;
  Modelica.Blocks.Sources.Constant const1(k = maxAbsCur) ;
  Modelica.Blocks.Nonlinear.Limiter limiter(uMax=maxAbsCur, uMin=0) ;
  OpenIPSL.Electrical.Solar.PowerFactory.General.Picdro picdro(Tdrop = if i_EEG then 0 else 0.5, Tpick = 0) ;
  Modelica.Blocks.Nonlinear.DeadZone deadZone(uMax=Deadband, uMin=-Deadband) ;
  Modelica.Blocks.Logical.GreaterEqualThreshold greaterEqualThreshold(threshold = Deadband) ;
  Modelica.Blocks.Math.Abs abs ;
  Modelica.Blocks.Logical.Switch switch_q_frt_normal ;
  Modelica.Blocks.Logical.Switch switch1 ;
equation
  connect(abs1.u, duac) ;
  connect(add.y, dlim_frt_op.limit2) ;
  connect(gain.u, add.y) ;
  connect(const.y, min.u1) ;
  connect(gain1.u, min.y) ;
  connect(qlim_normal_op.u, iqin) ;
  connect(pythagoras.y, limiter.u) ;
  connect(limiter.y, min.u2) ;
  connect(deadZone.u, duac) ;
  connect(deadZone.y, abs.u) ;
  connect(abs.y, greaterEqualThreshold.u) ;
  connect(greaterEqualThreshold.y, picdro.condition) ;
  connect(switch_q_frt_normal.y, iqout) ;
  connect(switch_q_frt_normal.u2, picdro.trip) ;
  connect(pythagoras.u2, iqin) ;
  connect(const1.y, pythagoras.u1) ;
  connect(gain1.y, qlim_normal_op.limit2) ;
  connect(qlim_normal_op.limit1, min.y) ;
  connect(qlim_normal_op.y, switch_q_frt_normal.u3) ;
  connect(qlim_frt_op.u, iqin) ;
  connect(qlim_frt_op.y, switch_q_frt_normal.u1) ;
  connect(switch1.u2, picdro.trip) ;
  connect(dlim_normal_op.y, switch1.u3) ;
  connect(dlim_frt_op.y, switch1.u1) ;
  connect(switch1.y, idout) ;
  connect(maximum_current.y, add.u1) ;
  connect(dlim_normal_op.u, idin) ;
  connect(dlim_frt_op.u, idin) ;
  connect(abs1.y, add.u2) ;
  connect(gain.y, dlim_frt_op.limit1) 
  ;
end CurrentLimiter;

