model ActivePowerController "Controller for the active power of a PV plant"
  parameter Real K = 0.005 "Gain of the PI-Controller";
  parameter Types.Time T=0.03 "Integration Time Constant of the PI controller";
  parameter Real yo_min "Minimum d-axis current";
  parameter Real yo_max "Maximum d-axis current";
  parameter Types.PerUnit id0 "Initial d-axis current";
  Modelica.Blocks.Interfaces.RealInput yi ;
  Modelica.Blocks.Interfaces.RealOutput yo ;
  Modelica.Blocks.Interfaces.RealInput pred ;
  Modelica.Blocks.Continuous.LimIntegrator I(initType = Modelica.Blocks.Types.Init.InitialOutput,k = K / T, limitsAtInit = false,outMax = yo_max, outMin = yo_min, y_start = id0) if with_I ;
  Modelica.Blocks.Sources.Constant disable(k = 0) if not with_I ;
  Modelica.Blocks.Math.Add add ;
  Modelica.Blocks.Math.Gain P(k = K) ;
  Modelica.Blocks.Continuous.Integrator tracker(initType = Modelica.Blocks.Types.Init.InitialOutput, k = 1 / 0.1, y_start = id0) ;
  Modelica.Blocks.Math.Feedback feedback ;
  Modelica.Blocks.Nonlinear.Limiter limiter(uMax=yo_max, uMin=yo_min) ;
  Modelica.Blocks.Math.Product product ;
  Modelica.Blocks.Nonlinear.Limiter limiter1(uMax=yo_max, uMin=yo_min) ;
  //protected
  Modelica.Blocks.Interfaces.RealOutput yo1 ;
  Modelica.Blocks.Interfaces.RealOutput yo2 ;
  Modelica.Blocks.Interfaces.RealOutput x ;
  parameter Boolean with_I = if T > 0 then true else false;
equation
  yo = if pred < 1 then min(yo1,yo2) else yo1;
  if pred < 1 then
    tracker.u = feedback.y;
  else
    tracker.u = 0;
  end if;
  connect(P.y, add.u1) ;
  connect(I.u, yi) ;
  connect(yi, P.u) ;
  connect(I.y, x) ;
  connect(disable.y, x) ;
  connect(feedback.u2, tracker.y) ;
  connect(product.y, limiter.u) ;
  connect(product.u1, tracker.y) ;
  connect(pred, product.u2) ;
  connect(limiter.y, yo2) ;
  connect(x, add.u2) ;
  connect(feedback.u1, yo1) ;
  connect(limiter1.u, add.y) ;
  connect(yo1, limiter1.y) 
  ;
end ActivePowerController;

