within OpenIPSL.Electrical.Solar.PowerFactory.General;
model ElmGenstat "Static generator"
  extends OpenIPSL.Electrical.Essentials.pfComponent(
    final enabledisplayPF=false,
    final enablefn=true,
    final enableV_b=false,
    final enableangle_0=true,
    final enablev_0=true,
    final enableQ_0=false,
    final enableP_0=false,
    final enableS_b=true);
  parameter Types.ApparentPower M_b "Machine base power"
    ;
  parameter Boolean pll_connected = false "Enable/disable use of PLL inputs" ;
  Types.Angle angle_i;
  Types.Angle angle_v;
  Modelica.Blocks.Interfaces.RealInput id_ref ;
  Modelica.Blocks.Interfaces.RealInput iq_ref ;
  OpenIPSL.Interfaces.PwPin p(vr(start=v_0*cos(angle_0)), vi(start=v_0*sin(angle_0))) ;
  Modelica.Blocks.Interfaces.RealOutput i ;
  Modelica.Blocks.Interfaces.RealOutput v ;
  Modelica.Blocks.Interfaces.RealInput sinref if pll_connected "Optional PLL input for sine" ;
  Modelica.Blocks.Interfaces.RealInput cosref if pll_connected "Optional PLL input for cosine"
                                                                                              ;
  Modelica.Blocks.Interfaces.RealOutput P ;
  Modelica.Blocks.Interfaces.RealOutput Q ;

protected
  Modelica.Blocks.Interfaces.RealOutput sinu "Internal sine of the voltage angle";
  Modelica.Blocks.Interfaces.RealOutput cosu "Internal cosine of the voltage angle";

equation
  if pll_connected then
    connect(sinref, sinu);
    connect(cosref, cosu);
  else
    sinu = p.vi/v;
    cosu = p.vr/v;
  end if;
  p.ir*S_b/M_b = -(id_ref * cosu - iq_ref * sinu);
  p.ii*S_b/M_b = -(id_ref * sinu + iq_ref * cosu);
  -P = p.vr * p.ir + p.vi * p.ii;
  -Q = p.vi * p.ir - p.vr * p.ii;
  v = sqrt(p.vr ^ 2 + p.vi ^ 2);
  angle_v = atan2(p.vi, p.vr);
  i = sqrt(p.ii ^ 2 + p.ir ^ 2)*S_b/M_b;
  angle_i = atan2(p.ii, p.ir)
  ;
end ElmGenstat;

within OpenIPSL.Electrical.Solar.PowerFactory.General;
model ElmPhi_pll "Phase-locked loop (PLL)"
  parameter Real angle_0rad;
  parameter Real omega_0;
  parameter Real v_0;
  parameter Boolean PLLEnable = false "Enable/disable PLL (PLL not implemented yet)";
  OpenIPSL.Interfaces.PwPin p ;
  Modelica.Blocks.Interfaces.RealOutput sinphi ;
  Modelica.Blocks.Interfaces.RealOutput cosphi ;
  Types.PerUnit v;
equation
  v = sqrt(p.vr ^ 2 + p.vi ^ 2);
  sinphi = p.vi/v;
  cosphi = p.vr/v;
  p.ii = 0;
  p.ir = 0
  ;
end ElmPhi_pll;

within OpenIPSL.Electrical.Solar.PowerFactory.General;
model ElmVac "Controllable voltage source"
  extends OpenIPSL.Electrical.Essentials.pfComponent(
    final enabledisplayPF=false,
    final enablefn=true,
    final enableV_b=false,
    final enableangle_0=true,
    final enablev_0=true,
    final enableQ_0=false,
    final enableP_0=false,
    final enableS_b=true);
  Types.PerUnit P;
  Types.PerUnit Q;
  Types.Angle phiu;
  Modelica.Blocks.Interfaces.RealInput f0 ;
  Modelica.Blocks.Interfaces.RealInput v(start=v_0, fixed=true) ;
  OpenIPSL.Interfaces.PwPin p ;
initial equation
  phiu = angle_0;
equation
  der(phiu) = 2*fn*C.pi*(f0-fn/50);
  p.vr = v*cos(phiu);
  p.vi = v*sin(phiu);
  -P = p.vr * p.ir + p.vi * p.ii;
  -Q = p.vi * p.ir - p.vr * p.ii
;
end ElmVac;

within OpenIPSL.Electrical.Solar.PowerFactory.General;
model Picdro "Pick-up drop-off implementation for protection functions"
  parameter Types.Time Tpick "Pick-up time delay";
  parameter Types.Time Tdrop "Drop-off time delay";
  Modelica.Blocks.Interfaces.BooleanInput condition ;
  Modelica.Blocks.Interfaces.BooleanOutput trip ;
  Modelica.Blocks.Logical.Timer timer ;
  Modelica.Blocks.Logical.GreaterThreshold greaterThreshold(threshold = Tpick + 1e-8) ;
  Modelica.Blocks.Logical.RSFlipFlop rSFlipFlop ;
  Modelica.Blocks.Logical.Timer timer1 ;
  Modelica.Blocks.Logical.GreaterThreshold greaterThreshold1(threshold = Tdrop + 1e-8) ;
  Modelica.Blocks.Logical.Not not1 ;
equation
  connect(condition, timer.u) ;
  connect(greaterThreshold.u, timer.y) ;
  connect(rSFlipFlop.Q, trip) ;
  connect(greaterThreshold.y, rSFlipFlop.S) ;
  connect(timer1.y, greaterThreshold1.u) ;
  connect(not1.y, timer1.u) ;
  connect(greaterThreshold1.y, rSFlipFlop.R) ;
  connect(not1.u, greaterThreshold.y) 

;
end Picdro;

within OpenIPSL.Electrical.Solar.PSAT.ConstantPQPV;
model PQ1 "Constant PQ Generator, Solar Photo-Voltaic Generator"
  outer OpenIPSL.Electrical.SystemBase SysData "Use outer SystemBase record";
  OpenIPSL.Interfaces.PwPin p
    ;
  parameter Types.ApparentPower S_b=SysData.S_b "System base power"
    ;
  parameter Types.ApparentPower Sn=SysData.S_b "Nominal power";
  parameter Types.PerUnit v_0=1.00018548610126 "Voltage magnitude"
    ;
  parameter Types.Angle angle_0=-0.0000253046024029618 "Voltage angle"
    ;
  parameter Types.PerUnit P_0=0.4 "Active power"
    ;
  parameter Types.PerUnit Q_0=0.3 "Reactive power"
    ;
  parameter Types.Time Td=15 "d-axis inverter time constant";
  parameter Types.Time Tq=15 "q-axis inverter time constant";
protected
  parameter Real CoB=Sn/S_b;
  parameter Types.PerUnit Pref=P_0*CoB "active power initialization";
  parameter Types.PerUnit Qref=Q_0*CoB "reactive power initialization";
  parameter Types.PerUnit vd0=-v_0*sin(angle_0) "d-axis voltage initialization";
  parameter Types.PerUnit vq0=v_0*cos(angle_0) "q-axis voltage initialization";
  parameter Types.PerUnit idref=(vq0*Qref + Pref*vd0)/(vq0^2 + vd0^2) "d-axis current initialization";
  parameter Types.PerUnit iqref=((-vd0*Qref) + Pref*vq0)/(vq0^2 + vd0^2) "q-axis current initialization";
public
  Types.PerUnit v "Bus voltage magnitude";
  Types.Angle anglev "Bus voltage angle";
  Types.PerUnit id(start=idref) "d-axis current";
  Types.PerUnit iq(start=iqref) "q-axis current";
  Types.PerUnit vd(start=vd0) "d-axis voltage";
  Types.PerUnit vq(start=vq0) "q-axis voltage";
  Types.PerUnit P(start=Pref) "Active power";
  Types.PerUnit Q(start=Qref) "Reactive power";
  Types.PerUnit idref1(start=idref) "d-axis current setpoint";
  Types.PerUnit iqref1(start=iqref) "q-axis current setpoint";
equation
  P = vd*id + vq*iq;
  Q = vq*id - vd*iq;
  idref1 = (vq*Qref + Pref*vd)/(vq^2 + vd^2);
  iqref1 = ((-vd*Qref) + Pref*vq)/(vq^2 + vd^2);
  der(id) = (idref1 - id)/Td;
  der(iq) = (iqref1 - iq)/Tq;
  v = sqrt(p.vr^2 + p.vi^2);
  anglev = atan2(p.vi, p.vr);
  p.ir = -iq
    "change of sign due to the fact than in modelica when entering is + and in this case is going out";
  p.ii = id
    "change of sign due to the fact than in modelica when entering is + and in this case is going out";
  p.vr = vq;
  p.vi = -vd
  ;
end PQ1;

within OpenIPSL.Electrical.Solar.PSAT.ConstantPQPV;
model PV1 "Constant PV Generator, Solar Photo-Voltaic Generator"
  outer OpenIPSL.Electrical.SystemBase SysData "Use outer SystemBase record";
  OpenIPSL.Interfaces.PwPin p
    ;
  parameter Types.ApparentPower S_b=SysData.S_b "System base power"
    ;
  parameter Types.ApparentPower Sn=SysData.S_b "Nominal power";
  parameter Types.PerUnit v_0=1.00018548610126 "Voltage magnitude"
    ;
  parameter Types.Angle angle_0=-0.0000253046024029618 "Voltage angle"
    ;
  parameter Types.PerUnit P_0=0.4 "Active power"
    ;
  parameter Types.PerUnit Q_0=0.3 "Reactive power"
    ;
  parameter Types.PerUnit vref=1.0002 "Voltage reference";
  parameter Types.Time Td=0.15 "d-axis inverter time constant";
  parameter Types.Time Tq=0.15 "q-axis inverter time constant";
  parameter Real Ki=50.9005 "Integral gain of the voltage controller";
  parameter Real Kp=0.0868 "Proportional gain of the voltage controller";
protected
  parameter Real CoB=Sn/S_b;
  parameter Types.PerUnit Pref=P_0*CoB "active power initialization";
  parameter Types.PerUnit vd0=-v_0*sin(angle_0) "d-axis voltage initialization";
  parameter Types.PerUnit vq0=v_0*cos(angle_0) "q-axis voltage initialization";
  parameter Types.PerUnit idref=(vq0*Q_0*CoB + Pref*vd0)/(vq0^2 + vd0^2) "d-axis current initialization";
  parameter Types.PerUnit iqref=((-vd0*Q_0*CoB) + Pref*vq0)/(vq0^2 + vd0^2) "q-axis current initialization";
  Types.PerUnit x(start=Q_0*CoB);
  Types.PerUnit Qref(start=Q_0*CoB) "reactive power initialization";
public
  Types.PerUnit v "Bus voltage magnitude";
  Types.Angle anglev "Bus voltage angle";
  Types.PerUnit idref1(start=idref) "d-axis current setpoint";
  Types.PerUnit iqref1(start=iqref) "q-axis current setpoint";
  Types.PerUnit id(start=idref) "d-axis current";
  Types.PerUnit iq(start=iqref) "q-axis current";
  Types.PerUnit vd(start=vd0) "d-axis voltage";
  Types.PerUnit vq(start=vq0) "q-axs voltage";
  Types.PerUnit P(start=Pref) "Active power";
  Types.PerUnit Q(start=Q_0*CoB) "Reactive power";
equation
  der(x) = Ki*(vref - v);
  Qref = x + Kp*(vref - v);
  P = vd*id + vq*iq;
  Q = vq*id - vd*iq;
  idref1 = (vq*Qref + Pref*vd)/(vq^2 + vd^2);
  iqref1 = ((-vd*Qref) + Pref*vq)/(vq^2 + vd^2);
  der(id) = (idref1 - id)/Td;
  der(iq) = (iqref1 - iq)/Tq;
  v = sqrt(p.vr^2 + p.vi^2);
  anglev = atan2(p.vi, p.vr);
  p.ir = -iq "change of sign due to the fact than in modelica when entering is + and in this case is going out";
  p.ii = id "change of sign due to the fact than in modelica when entering is + and in this case is going out";
  p.vr = vq;
  p.vi = -vd
  ;
end PV1;

within OpenIPSL.Electrical.Sources;
model CurrentSourceReImInput
  "Ideal current source with user defined real and imaginary parts of the current phasor"
  extends OpenIPSL.Electrical.Essentials.pfComponent(enableS_b = true);
  Types.Angle angle "Bus voltage angle";
  Types.Voltage v "Bus voltage magnitude";
  Types.ActivePower P "Active Power absorbed or provided by the source";
  Types.ReactivePower Q "Reactive Power absorbed or provided by the source";
  OpenIPSL.Interfaces.PwPin p
    ;
  Modelica.Blocks.Interfaces.RealInput iRe "Real Part of voltage phasor"
    ;
  Modelica.Blocks.Interfaces.RealInput iIm "Imaginary Part of Voltage Phasor"
    ;
equation
  p.ir =iRe;
  p.ii =iIm;
  v = sqrt(p.vr^2 + p.vi^2);
  angle = atan2(p.vi, p.vr);
  P = -(p.vr*p.ir + p.vi*p.ii)*S_b;
  Q = -(p.vr*p.ii - p.vi*p.ir)*S_b
  ;
end CurrentSourceReImInput;

