  Real[2, 1] Vin=[Ain.vr; Ain.vi];
  Real[2, 1] Vout=[Aout.vr; Aout.vi];
  // Writing matrix for currents (in and out)
  Real[2, 1] Iin=[Ain.ir; Ain.ii];
  Real[2, 1] Iout=[Aout.ir; Aout.ii];

equation
  // Equations according to pi model
  Iin = A*Vin + B*Vout;
  Iout = B*Vin + A*Vout

