within OpenIPSL.Electrical.ThreePhase.Branches.MonoTri.LineFcn;
function MT_InfiniteImpedances "Calculation of impedance matrices for hybrid line."
  extends Modelica.Icons.Function;
  input Real[1, 18] Yser;
  input Real[1, 18] Ysht;
  output Real[1, 32] Y;
  //Writing the Y_ser matrix
protected
  parameter Real Gaaser=Yser[1, 1];
  parameter Real Baaser=Yser[1, 2];
  parameter Real Gabser=Yser[1, 3];
  parameter Real Babser=Yser[1, 4];
  parameter Real Gacser=Yser[1, 5];
  parameter Real Bacser=Yser[1, 6];
  parameter Real Gbaser=Yser[1, 7];
  parameter Real Bbaser=Yser[1, 8];
  parameter Real Gbbser=Yser[1, 9];
  parameter Real Bbbser=Yser[1, 10];
  parameter Real Gbcser=Yser[1, 11];
  parameter Real Bbcser=Yser[1, 12];
  parameter Real Gcaser=Yser[1, 13];
  parameter Real Bcaser=Yser[1, 14];
  parameter Real Gcbser=Yser[1, 15];
  parameter Real Bcbser=Yser[1, 16];
  parameter Real Gccser=Yser[1, 17];
  parameter Real Bccser=Yser[1, 18];
  //Writing the Y_sht matrix
  parameter Real Gaasht=Ysht[1, 1];
  parameter Real Baasht=Ysht[1, 2];
  parameter Real Gabsht=Ysht[1, 3];
  parameter Real Babsht=Ysht[1, 4];
  parameter Real Gacsht=Ysht[1, 5];
  parameter Real Bacsht=Ysht[1, 6];
  parameter Real Gbasht=Ysht[1, 7];
  parameter Real Bbasht=Ysht[1, 8];
  parameter Real Gbbsht=Ysht[1, 9];
  parameter Real Bbbsht=Ysht[1, 10];
  parameter Real Gbcsht=Ysht[1, 11];
  parameter Real Bbcsht=Ysht[1, 12];
  parameter Real Gcasht=Ysht[1, 13];
  parameter Real Bcasht=Ysht[1, 14];
  parameter Real Gcbsht=Ysht[1, 15];
  parameter Real Bcbsht=Ysht[1, 16];
  parameter Real Gccsht=Ysht[1, 17];
  parameter Real Bccsht=Ysht[1, 18];
  //Calculating the parameters for the MonoxTri interface
  //Calculating some auxiliary variables
  parameter Real G1=(Gaasht + Gaaser + Gbbsht + Gbbser + Gccsht + Gccser)/3;
  parameter Real B1=(Baasht + Baaser + Bbbsht + Bbbser + Bccsht + Bccser)/3;
  parameter Real G2=(Gbasht + Gbaser + Gacsht + Gacser + Gcbsht + Gcbser)/3;
  parameter Real B2=(Bbasht + Bbaser + Bacsht + Bacser + Bcbsht + Bcbser)/3;
  parameter Real G3=(Gabsht + Gabser + Gbcsht + Gbcser + Gcasht + Gcaser)/3;
  parameter Real B3=(Babsht + Babser + Bbcsht + Bbcser + Bcasht + Bcaser)/3;
  //Calculating the element of Matrix A
  parameter Real Ar=(2*G1 - G2 - sqrt(3)*B2 - G3 + sqrt(3)*B3)/2;
  parameter Real Ai=(2*B1 - B2 + sqrt(3)*G2 - B3 - sqrt(3)*G3)/2;
  //Calculating elements of Matrix MB
  parameter Real MB1r=-(2*Gaaser - Gbaser - sqrt(3)*Bbaser - Gcaser + sqrt(3)*
      Bcaser)/6;
  parameter Real MB1i=-(2*Baaser - Bbaser + sqrt(3)*Gbaser - Bcaser - sqrt(3)*
      Gcaser)/6;
  parameter Real MB2r=-(2*Gabser - Gbbser - sqrt(3)*Bbbser - Gcbser + sqrt(3)*
      Bcbser)/6;
  parameter Real MB2i=-(2*Babser - Bbbser + sqrt(3)*Gbbser - Bcbser - sqrt(3)*
      Gcbser)/6;
  parameter Real MB3r=-(2*Gacser - Gbcser - sqrt(3)*Bbcser - Gccser + sqrt(3)*
      Bccser)/6;
  parameter Real MB3i=-(2*Bacser - Bbcser + sqrt(3)*Gbcser - Bccser - sqrt(3)*
      Gccser)/6;
  //Calculating elements of Matrix C
  parameter Real C1r=-(2*Gaaser - Gabser + sqrt(3)*Babser - Gacser - sqrt(3)*
      Bacser)/2;
  parameter Real C1i=-(2*Baaser - Babser - sqrt(3)*Gabser - Bacser + sqrt(3)*
      Gacser)/2;
  parameter Real C2r=-(2*Gbaser - Gbbser + sqrt(3)*Bbbser - Gbcser - sqrt(3)*
      Bbcser)/2;
  parameter Real C2i=-(2*Bbaser - Bbbser - sqrt(3)*Gbbser - Bbcser + sqrt(3)*
      Gbcser)/2;
  parameter Real C3r=-(2*Gcaser - Gcbser + sqrt(3)*Bcbser - Gccser - sqrt(3)*
      Bccser)/2;
  parameter Real C3i=-(2*Bcaser - Bcbser - sqrt(3)*Gcbser - Bccser + sqrt(3)*
      Gccser)/2;
  //Calculating elements of Matrix D
  parameter Real D11r=Gaaser + Gaasht;
  parameter Real D11i=Baaser + Baasht;
  parameter Real D12r=Gabser + Gabsht;
  parameter Real D12i=Babser + Babsht;
  parameter Real D13r=Gacser + Gacsht;
  parameter Real D13i=Bacser + Bacsht;
  parameter Real D21r=Gbaser + Gbasht;
  parameter Real D21i=Bbaser + Bbasht;
  parameter Real D22r=Gbbser + Gbbsht;
  parameter Real D22i=Bbbser + Bbbsht;
  parameter Real D23r=Gbcser + Gbcsht;
  parameter Real D23i=Bbcser + Bbcsht;
  parameter Real D31r=Gcaser + Gcasht;
  parameter Real D31i=Bcaser + Bcasht;
  parameter Real D32r=Gcbser + Gcbsht;
  parameter Real D32i=Bcbser + Bcbsht;
  parameter Real D33r=Gccser + Gccsht;
  parameter Real D33i=Bccser + Bccsht;
algorithm
  Y := [Ar, Ai, MB1r, MB1i, MB2r, MB2i, MB3r, MB3i, C1r, C1i, C2r, C2i, C3r,
    C3i, D11r, D11i, D12r, D12i, D13r, D13i, D21r, D21i, D22r, D22i, D23r, D23i,
    D31r, D31i, D32r, D32i, D33r, D33i]
;
end MT_InfiniteImpedances;

within OpenIPSL.Electrical.ThreePhase.Branches.MonoTri.MonoTriFcn;
function Inverse "Calculation of filter admittances, given filter's impedances"
  extends Modelica.Icons.Function;
  input Real[1, 18] I;
  output Real[1, 18] O;
  // Writing every element of the matrix to be inverted
protected
  parameter Real a11=I[1, 1];
  parameter Real b11=I[1, 2];
  parameter Real a12=I[1, 3];
  parameter Real b12=I[1, 4];
  parameter Real a13=I[1, 5];
  parameter Real b13=I[1, 6];
  parameter Real a21=I[1, 7];
  parameter Real b21=I[1, 8];
  parameter Real a22=I[1, 9];
  parameter Real b22=I[1, 10];
  parameter Real a23=I[1, 11];
  parameter Real b23=I[1, 12];
  parameter Real a31=I[1, 13];
  parameter Real b31=I[1, 14];
  parameter Real a32=I[1, 15];
  parameter Real b32=I[1, 16];
  parameter Real a33=I[1, 17];
  parameter Real b33=I[1, 18];
  // Calculating the real and imaginary part of the matrix's determinant
  parameter Real A=a13*a21*a32 - a13*b21*b32 - b13*a21*b32 - b13*b21*a32 + a12*
      a23*a31 - a12*b23*b31 - b12*a23*b31 - b12*b23*a31 + a11*a22*a33 - a11*b22
      *b33 - b11*a22*b33 - b11*b22*a33 - (a33*a21*a12 - a33*b21*b12 - b33*a21*
      b12 - b33*b21*a12) - (a11*a23*a32 - a11*b23*b32 - b11*a23*b32 - b11*b23*
      a32) - (a13*a22*a31 - a13*b22*b31 - b13*a22*b31 - b13*b22*a31);
  parameter Real B=a13*a21*b32 + a13*b21*a32 + b13*a21*a32 - b13*b21*b32 + a12*
      a23*b31 + a12*b23*a31 + b12*a23*a31 - b12*b23*b31 + a11*a22*b33 + a11*b22
      *a33 + b11*a22*a33 - b11*b22*b33 - (a33*a21*b12 + a33*b21*a12 + b33*a21*
      a12 - b33*b21*b12) - (a11*a23*b32 + a11*b23*a32 + b11*a23*a32 - b11*b23*
      b32) - (a13*a22*b31 + a13*b22*a31 + b13*a22*a31 - b13*b22*b31);
  // Calculating the elements for the inverted matrix
  parameter Real r11=(A*(a22*a33 - a32*a23 - b22*b33 + b32*b23) + B*(a22*b33 +
      b22*a33 - a32*b23 - b32*a23))/(A*A + B*B);
  parameter Real x11=(A*(a22*b33 + b22*a33 - a32*b23 - b32*a23) - B*(a22*a33 -
      a32*a23 - b22*b33 + b32*b23))/(A*A + B*B);
  parameter Real r12=(A*(a13*a32 - a12*a33 - b13*b32 + b12*b33) + B*(a13*b32 +
      b13*a32 - a12*b33 - b12*a33))/(A*A + B*B);
  parameter Real x12=(A*(a13*b32 + b13*a32 - a12*b33 - b12*a33) - B*(a13*a32 -
      a12*a33 - b13*b32 + b12*b33))/(A*A + B*B);
  parameter Real r13=(A*(a12*a23 - a13*a22 - b12*b23 + b13*b22) + B*(a12*b23 +
      b12*a23 - a13*b22 - b13*a22))/(A*A + B*B);
  parameter Real x13=(A*(a12*b23 + b12*a23 - a13*b22 - b13*a22) - B*(a12*a23 -
      a13*a22 - b12*b23 + b13*b22))/(A*A + B*B);
  parameter Real r21=(A*(a23*a31 - a21*a33 - b23*b31 + b21*b33) + B*(a23*b31 +
      b23*a31 - a21*b33 - b21*a33))/(A*A + B*B);
  parameter Real x21=(A*(a23*b31 + b23*a31 - a21*b33 - b21*a33) - B*(a23*a31 -
      a21*a33 - b23*b31 + b21*b33))/(A*A + B*B);
  parameter Real r22=(A*(a11*a33 - a13*a31 - b11*b33 + b13*b31) + B*(a11*b33 +
      b11*a33 - a13*b31 - b13*a31))/(A*A + B*B);
  parameter Real x22=(A*(a11*b33 + b11*a33 - a13*b31 - b13*a31) - B*(a11*a33 -
      a13*a31 - b11*b33 + b13*b31))/(A*A + B*B);
  parameter Real r23=(A*(a13*a21 - a11*a23 - b13*b21 + b11*b23) + B*(a13*b21 +
      b13*a21 - a11*b23 - b11*a23))/(A*A + B*B);
  parameter Real x23=(A*(a13*b21 + b13*a21 - a11*b23 - b11*a23) - B*(a13*a21 -
      a11*a23 - b13*b21 + b11*b23))/(A*A + B*B);
  parameter Real r31=(A*(a21*a32 - a22*a31 - b21*b32 + b22*b31) + B*(a21*b32 +
      b21*a32 - a22*b31 - b22*a31))/(A*A + B*B);
  parameter Real x31=(A*(a21*b32 + b21*a32 - a22*b31 - b22*a31) - B*(a21*a32 -
      a22*a31 - b21*b32 + b22*b31))/(A*A + B*B);
  parameter Real r32=(A*(a12*a31 - a11*a32 - b12*b31 + b11*b32) + B*(a12*b31 +
      b12*a31 - a11*b32 - b11*a32))/(A*A + B*B);
  parameter Real x32=(A*(a12*b31 + b12*a31 - a11*b32 - b11*a32) - B*(a12*a31 -
      a11*a32 - b12*b31 + b11*b32))/(A*A + B*B);
  parameter Real r33=(A*(a11*a22 - a12*a21 - b11*b22 + b12*b21) + B*(a11*b22 +
      b11*a22 - a12*b21 - b12*a21))/(A*A + B*B);
  parameter Real x33=(A*(a11*b22 + b11*a22 - a12*b21 - b12*a21) - B*(a11*a22 -
      a12*a21 - b11*b22 + b12*b21))/(A*A + B*B);
algorithm
  O := [r11, x11, r12, x12, r13, x13, r21, x21, r22, x22, r23, x23, r31, x31,
    r32, x32, r33, x33]
;
end Inverse;

within OpenIPSL.Electrical.ThreePhase.Branches.MonoTri.MonoTriFcn;
function NegZerFilter "Calculation of negative, and zero-sequence filters used in Norton equivalent."
  extends Modelica.Icons.Function;
  input Real[1, 18] Z;
  output Real[1, 18] Y;

  // Getting data for the positive filter
protected
  parameter Real g0=1;
  parameter Real b0=0;
  parameter Real g1=0;
  parameter Real b1=0;
  parameter Real g2=1;
  parameter Real b2=0;

  // Writing the positive filter matrix
  parameter Real c11=(g0 + g1 + g2)/3;
  parameter Real d11=(b0 + b1 + b2)/3;
  parameter Real c12=(2*g0 - g1 - b1*sqrt(3) - g2 + b2*sqrt(3))/6;
  parameter Real d12=(2*b0 + g1*sqrt(3) - b1 - g2*sqrt(3) - b2)/6;
  parameter Real c13=(2*g0 - g1 + b1*sqrt(3) - g2 - b2*sqrt(3))/6;
  parameter Real d13=(2*b0 - g1*sqrt(3) - b1 + g2*sqrt(3) - b2)/6;
  parameter Real c21=c13;
  parameter Real d21=d13;
  parameter Real c22=c11;
  parameter Real d22=d11;
  parameter Real c23=c12;
  parameter Real d23=d12;
  parameter Real c31=c12;
  parameter Real d31=d12;
  parameter Real c32=c13;
  parameter Real d32=d13;
  parameter Real c33=c11;
  parameter Real d33=d11;

  // Getting the elements of matrix Z (zii = rii +j*xii)
  parameter Real r11=Z[1, 1];
  parameter Real x11=Z[1, 2];
  parameter Real r12=Z[1, 3];
  parameter Real x12=Z[1, 4];
  parameter Real r13=Z[1, 5];
  parameter Real x13=Z[1, 6];
  parameter Real r21=Z[1, 7];
  parameter Real x21=Z[1, 8];
  parameter Real r22=Z[1, 9];
  parameter Real x22=Z[1, 10];
  parameter Real r23=Z[1, 11];
  parameter Real x23=Z[1, 12];
  parameter Real r31=Z[1, 13];
  parameter Real x31=Z[1, 14];
  parameter Real r32=Z[1, 15];
  parameter Real x32=Z[1, 16];
  parameter Real r33=Z[1, 17];
  parameter Real x33=Z[1, 18];

  // Getting the result for F*Z = Y (yii = gii + j*bii)
  parameter Real g11=c11*r11 - d11*x11 + c12*r21 - d12*x21 + c13*r31 - d13*x31;
  parameter Real b11=c11*x11 + d11*r11 + c12*x21 + d12*r21 + c13*x31 + d13*r31;
  parameter Real g12=c11*r12 - d11*x12 + c12*r22 - d12*x22 + c13*r32 - d13*x32;
  parameter Real b12=c11*x12 + d11*r12 + c12*x22 + d12*r22 + c13*x32 + d13*r32;
  parameter Real g13=c11*r13 - d11*x13 + c12*r23 - d12*x23 + c13*r33 - d13*x33;
  parameter Real b13=c11*x13 + d11*r13 + c12*x23 + d12*r23 + c13*x33 + d13*r33;
  parameter Real g21=c21*r11 - d21*x11 + c22*r21 - d22*x21 + c23*r31 - d23*x31;
  parameter Real b21=c21*x11 + d21*r11 + c22*x21 + d22*r21 + c23*x31 + d23*r31;
  parameter Real g22=c21*r12 - d21*x12 + c22*r22 - d22*x22 + c23*r32 - d23*x32;
  parameter Real b22=c21*x12 + d21*r12 + c22*x22 + d22*r22 + c23*x32 + d23*r32;
  parameter Real g23=c21*r13 - d21*x13 + c22*r23 - d22*x23 + c23*r33 - d23*x33;
  parameter Real b23=c21*x13 + d21*r13 + c22*x23 + d22*r23 + c23*x33 + d23*r33;
  parameter Real g31=c31*r11 - d31*x11 + c32*r21 - d32*x21 + c33*r31 - d33*x31;
  parameter Real b31=c31*x11 + d31*r11 + c32*x21 + d32*r21 + c33*x31 + d33*r31;
  parameter Real g32=c31*r12 - d31*x12 + c32*r22 - d32*x22 + c33*r32 - d33*x32;
  parameter Real b32=c31*x12 + d31*r12 + c32*x22 + d32*r22 + c33*x32 + d33*r32;
  parameter Real g33=c31*r13 - d31*x13 + c32*r23 - d32*x23 + c33*r33 - d33*x33;
  parameter Real b33=c31*x13 + d31*r13 + c32*x23 + d32*r23 + c33*x33 + d33*r33;

algorithm
  // The output value receive the filtered value
  Y := [g11, b11, g12, b12, g13, b13, g21, b21, g22, b22, g23, b23, g31, b31,
    g32, b32, g33, b33]
;
end NegZerFilter;

within OpenIPSL.Electrical.ThreePhase.Branches.MonoTri.MonoTriFcn;
function PositiveFilter "Calculation of positive-sequence filter used in Norton equivalent."
  extends Modelica.Icons.Function;
  input Real[1, 18] Z;
  output Real[1, 18] Y;

  // Getting data for the positive filter
protected
  parameter Real g0=0;
  parameter Real b0=0;
  parameter Real g1=1;
  parameter Real b1=0;
  parameter Real g2=0;
  parameter Real b2=0;

  // Writing the positive filter matrix
  parameter Real c11=(g0 + g1 + g2)/3;
  parameter Real d11=(b0 + b1 + b2)/3;
  parameter Real c12=(2*g0 - g1 - b1*sqrt(3) - g2 + b2*sqrt(3))/6;
  parameter Real d12=(2*b0 + g1*sqrt(3) - b1 - g2*sqrt(3) - b2)/6;
  parameter Real c13=(2*g0 - g1 + b1*sqrt(3) - g2 - b2*sqrt(3))/6;
  parameter Real d13=(2*b0 - g1*sqrt(3) - b1 + g2*sqrt(3) - b2)/6;
  parameter Real c21=c13;
  parameter Real d21=d13;
  parameter Real c22=c11;
  parameter Real d22=d11;
  parameter Real c23=c12;
  parameter Real d23=d12;
  parameter Real c31=c12;
  parameter Real d31=d12;
  parameter Real c32=c13;
  parameter Real d32=d13;
  parameter Real c33=c11;
  parameter Real d33=d11;

  // Getting the elements of matrix Z (zii = rii +j*xii)
  parameter Real r11=Z[1, 1];
  parameter Real x11=Z[1, 2];
  parameter Real r12=Z[1, 3];
  parameter Real x12=Z[1, 4];
  parameter Real r13=Z[1, 5];
  parameter Real x13=Z[1, 6];
  parameter Real r21=Z[1, 7];
  parameter Real x21=Z[1, 8];
  parameter Real r22=Z[1, 9];
  parameter Real x22=Z[1, 10];
  parameter Real r23=Z[1, 11];
  parameter Real x23=Z[1, 12];
  parameter Real r31=Z[1, 13];
  parameter Real x31=Z[1, 14];
  parameter Real r32=Z[1, 15];
  parameter Real x32=Z[1, 16];
  parameter Real r33=Z[1, 17];
  parameter Real x33=Z[1, 18];

  // Getting the result for F*Z = Y (yii = gii + j*bii)
  parameter Real g11=c11*r11 - d11*x11 + c12*r21 - d12*x21 + c13*r31 - d13*x31;
  parameter Real b11=c11*x11 + d11*r11 + c12*x21 + d12*r21 + c13*x31 + d13*r31;
  parameter Real g12=c11*r12 - d11*x12 + c12*r22 - d12*x22 + c13*r32 - d13*x32;
  parameter Real b12=c11*x12 + d11*r12 + c12*x22 + d12*r22 + c13*x32 + d13*r32;
  parameter Real g13=c11*r13 - d11*x13 + c12*r23 - d12*x23 + c13*r33 - d13*x33;
  parameter Real b13=c11*x13 + d11*r13 + c12*x23 + d12*r23 + c13*x33 + d13*r33;
  parameter Real g21=c21*r11 - d21*x11 + c22*r21 - d22*x21 + c23*r31 - d23*x31;
  parameter Real b21=c21*x11 + d21*r11 + c22*x21 + d22*r21 + c23*x31 + d23*r31;
  parameter Real g22=c21*r12 - d21*x12 + c22*r22 - d22*x22 + c23*r32 - d23*x32;
  parameter Real b22=c21*x12 + d21*r12 + c22*x22 + d22*r22 + c23*x32 + d23*r32;
  parameter Real g23=c21*r13 - d21*x13 + c22*r23 - d22*x23 + c23*r33 - d23*x33;
  parameter Real b23=c21*x13 + d21*r13 + c22*x23 + d22*r23 + c23*x33 + d23*r33;
  parameter Real g31=c31*r11 - d31*x11 + c32*r21 - d32*x21 + c33*r31 - d33*x31;
  parameter Real b31=c31*x11 + d31*r11 + c32*x21 + d32*r21 + c33*x31 + d33*r31;
  parameter Real g32=c31*r12 - d31*x12 + c32*r22 - d32*x22 + c33*r32 - d33*x32;
  parameter Real b32=c31*x12 + d31*r12 + c32*x22 + d32*r22 + c33*x32 + d33*r32;
  parameter Real g33=c31*r13 - d31*x13 + c32*r23 - d32*x23 + c33*r33 - d33*x33;
  parameter Real b33=c31*x13 + d31*r13 + c32*x23 + d32*r23 + c33*x33 + d33*r33;

algorithm
  // The output value receive the filtered value
  Y := [g11, b11, g12, b12, g13, b13, g21, b21, g22, b22, g23, b23, g31, b31,
    g32, b32, g33, b33]
;
end PositiveFilter;

within OpenIPSL.Electrical.ThreePhase.Branches.MonoTri.TransformerFcn;
function D_D "Calculation of impedance matrices for a delta-delta-connected hybrid transformer."
  extends Modelica.Icons.Function;
  input Real X;
  input Real R;
  input Real tap;
  output Real[1, 32] V;
protected
  parameter Real sGser=((1/tap)/3)*(2*R/(R*R + X*X));
  parameter Real sBser=((1/tap)/3)*(-2*X/(R*R + X*X));
  parameter Real mGser=((1/tap)/3)*(-R/(R*R + X*X));
  parameter Real mBser=((1/tap)/3)*(X/(R*R + X*X));
  parameter Real sGshk=((1 - tap)/(3*tap*tap))*(2*R/(R*R + X*X));
  parameter Real sBshk=((1 - tap)/(3*tap*tap))*(-2*X/(R*R + X*X));
  parameter Real mGshk=((1 - tap)/(3*tap*tap))*(-R/(R*R + X*X));
  parameter Real mBshk=((1 - tap)/(3*tap*tap))*(X/(R*R + X*X));

  //Writing the Y_ser matrix according to Simulight
  parameter Real Gaaser=sGser;
  parameter Real Baaser=sBser;
  parameter Real Gabser=mGser;
  parameter Real Babser=mBser;
  parameter Real Gacser=mGser;
  parameter Real Bacser=mBser;
  parameter Real Gbaser=mGser;
  parameter Real Bbaser=mBser;
  parameter Real Gbbser=sGser;
  parameter Real Bbbser=sBser;
  parameter Real Gbcser=mGser;
  parameter Real Bbcser=mBser;
  parameter Real Gcaser=mGser;
  parameter Real Bcaser=mBser;
  parameter Real Gcbser=mGser;
  parameter Real Bcbser=mBser;
  parameter Real Gccser=sGser;
  parameter Real Bccser=sBser;

  //Writing the Y_sht_k matrix according to Simulight
  parameter Real Gaask=sGshk;
  parameter Real Baask=sBshk;
  parameter Real Gabsk=mGshk;
  parameter Real Babsk=mBshk;
  parameter Real Gacsk=mGshk;
  parameter Real Bacsk=mBshk;
  parameter Real Gbask=mGshk;
  parameter Real Bbask=mBshk;
  parameter Real Gbbsk=sGshk;
  parameter Real Bbbsk=sBshk;
  parameter Real Gbcsk=mGshk;
  parameter Real Bbcsk=mBshk;
  parameter Real Gcask=mGshk;
  parameter Real Bcask=mBshk;
  parameter Real Gcbsk=mGshk;
  parameter Real Bcbsk=mBshk;
  parameter Real Gccsk=sGshk;
  parameter Real Bccsk=sBshk;

  //Writing the Y_sht_m matrix according to Simulight
  parameter Real Gaasm=0;
  parameter Real Baasm=0;
  parameter Real Gabsm=0;
  parameter Real Babsm=0;
  parameter Real Gacsm=0;
  parameter Real Bacsm=0;
  parameter Real Gbasm=0;
  parameter Real Bbasm=0;
  parameter Real Gbbsm=0;
  parameter Real Bbbsm=0;
  parameter Real Gbcsm=0;
  parameter Real Bbcsm=0;
  parameter Real Gcasm=0;
  parameter Real Bcasm=0;
  parameter Real Gcbsm=0;
  parameter Real Bcbsm=0;
  parameter Real Gccsm=0;
  parameter Real Bccsm=0;

  //Calculating the parameters for the MonoxTri interface

  parameter Real G1=(Gaask + Gaaser + Gbbsk + Gbbser + Gccsk + Gccser)/3;
  parameter Real B1=(Baask + Baaser + Bbbsk + Bbbser + Bccsk + Bccser)/3;
  parameter Real G2=(Gbask + Gbaser + Gacsk + Gacser + Gcbsk + Gcbser)/3;
  parameter Real B2=(Bbask + Bbaser + Bacsk + Bacser + Bcbsk + Bcbser)/3;
  parameter Real G3=(Gabsk + Gabser + Gbcsk + Gbcser + Gcask + Gcaser)/3;
  parameter Real B3=(Babsk + Babser + Bbcsk + Bbcser + Bcask + Bcaser)/3;

  //Calculating the element of Matrix A
  parameter Real Ar=(2*G1 - G2 - sqrt(3)*B2 - G3 + sqrt(3)*B3)/2;
  parameter Real Ai=(2*B1 - B2 + sqrt(3)*G2 - B3 - sqrt(3)*G3)/2;

  //Calculating elements of Matrix MB
  parameter Real MB1r=-(2*Gaaser - Gbaser - sqrt(3)*Bbaser - Gcaser + sqrt(3)*
      Bcaser)/6;
  parameter Real MB1i=-(2*Baaser - Bbaser + sqrt(3)*Gbaser - Bcaser - sqrt(3)*
      Gcaser)/6;
