function Y_Yg "Calculation of impedance matrices for a wye-grounded-wye-connected hybrid transformer."
  extends Modelica.Icons.Function;
  input Real X;
  input Real R;
  input Real tap;
  output Real[1, 32] V;
protected
  parameter Real sGser=((1/tap)/3)*(2*R/(R*R + X*X));
  parameter Real sBser=((1/tap)/3)*(-2*X/(R*R + X*X));
  parameter Real mGser=((1/tap)/3)*(-R/(R*R + X*X));
  parameter Real mBser=((1/tap)/3)*(X/(R*R + X*X));

  parameter Real sGshk=((1 - tap)/(3*tap*tap))*(2*R/(R*R + X*X));
  parameter Real sBshk=((1 - tap)/(3*tap*tap))*(-2*X/(R*R + X*X));
  parameter Real mGshk=((1 - tap)/(3*tap*tap))*(-R/(R*R + X*X));
  parameter Real mBshk=((1 - tap)/(3*tap*tap))*(X/(R*R + X*X));

  parameter Real sGshm=((3*tap - 2)/(3*tap))*(R/(R*R + X*X));
  parameter Real sBshm=((3*tap - 2)/(3*tap))*(-X/(R*R + X*X));
  parameter Real mGshm=(1/(3*tap))*(R/(R*R + X*X));
  parameter Real mBshm=(1/(3*tap))*(-X/(R*R + X*X));

  //Writing the Y_ser matrix according to Simulight
  parameter Real Gaaser=sGser;
  parameter Real Baaser=sBser;
  parameter Real Gabser=mGser;
  parameter Real Babser=mBser;
  parameter Real Gacser=mGser;
  parameter Real Bacser=mBser;
  parameter Real Gbaser=mGser;
  parameter Real Bbaser=mBser;
  parameter Real Gbbser=sGser;
  parameter Real Bbbser=sBser;
  parameter Real Gbcser=mGser;
  parameter Real Bbcser=mBser;
  parameter Real Gcaser=mGser;
  parameter Real Bcaser=mBser;
  parameter Real Gcbser=mGser;
  parameter Real Bcbser=mBser;
  parameter Real Gccser=sGser;
  parameter Real Bccser=sBser;

  //Writing the Y_sht_k matrix according to Simulight
  parameter Real Gaask=sGshk;
  parameter Real Baask=sBshk;
  parameter Real Gabsk=mGshk;
  parameter Real Babsk=mBshk;
  parameter Real Gacsk=mGshk;
  parameter Real Bacsk=mBshk;
  parameter Real Gbask=mGshk;
  parameter Real Bbask=mBshk;
  parameter Real Gbbsk=sGshk;
  parameter Real Bbbsk=sBshk;
  parameter Real Gbcsk=mGshk;
  parameter Real Bbcsk=mBshk;
  parameter Real Gcask=mGshk;
  parameter Real Bcask=mBshk;
  parameter Real Gcbsk=mGshk;
  parameter Real Bcbsk=mBshk;
  parameter Real Gccsk=sGshk;
  parameter Real Bccsk=sBshk;

  //Writing the Y_sht_m matrix according to Simulight
  parameter Real Gaasm=sGshm;
  parameter Real Baasm=sBshm;
  parameter Real Gabsm=mGshm;
  parameter Real Babsm=mBshm;
  parameter Real Gacsm=mGshm;
  parameter Real Bacsm=mBshm;
  parameter Real Gbasm=mGshm;
  parameter Real Bbasm=mBshm;
  parameter Real Gbbsm=sGshm;
  parameter Real Bbbsm=sBshm;
  parameter Real Gbcsm=mGshm;
  parameter Real Bbcsm=mBshm;
  parameter Real Gcasm=mGshm;
  parameter Real Bcasm=mBshm;
  parameter Real Gcbsm=mGshm;
  parameter Real Bcbsm=mBshm;
  parameter Real Gccsm=sGshm;
  parameter Real Bccsm=sBshm;

  //Calculating the parameters for the MonoxTri interface

  parameter Real G1=(Gaask + Gaaser + Gbbsk + Gbbser + Gccsk + Gccser)/3;
  parameter Real B1=(Baask + Baaser + Bbbsk + Bbbser + Bccsk + Bccser)/3;
  parameter Real G2=(Gbask + Gbaser + Gacsk + Gacser + Gcbsk + Gcbser)/3;
  parameter Real B2=(Bbask + Bbaser + Bacsk + Bacser + Bcbsk + Bcbser)/3;
  parameter Real G3=(Gabsk + Gabser + Gbcsk + Gbcser + Gcask + Gcaser)/3;
  parameter Real B3=(Babsk + Babser + Bbcsk + Bbcser + Bcask + Bcaser)/3;

  //Calculating the element of Matrix A
  parameter Real Ar=(2*G1 - G2 - sqrt(3)*B2 - G3 + sqrt(3)*B3)/2;
  parameter Real Ai=(2*B1 - B2 + sqrt(3)*G2 - B3 - sqrt(3)*G3)/2;

  //Calculating elements of Matrix MB
  parameter Real MB1r=-(2*Gaaser - Gbaser - sqrt(3)*Bbaser - Gcaser + sqrt(3)*
      Bcaser)/6;
  parameter Real MB1i=-(2*Baaser - Bbaser + sqrt(3)*Gbaser - Bcaser - sqrt(3)*
      Gcaser)/6;
  parameter Real MB2r=-(2*Gabser - Gbbser - sqrt(3)*Bbbser - Gcbser + sqrt(3)*
      Bcbser)/6;
  parameter Real MB2i=-(2*Babser - Bbbser + sqrt(3)*Gbbser - Bcbser - sqrt(3)*
      Gcbser)/6;
  parameter Real MB3r=-(2*Gacser - Gbcser - sqrt(3)*Bbcser - Gccser + sqrt(3)*
      Bccser)/6;
  parameter Real MB3i=-(2*Bacser - Bbcser + sqrt(3)*Gbcser - Bccser - sqrt(3)*
      Gccser)/6;

  //Calculating elements of Matrix C
  parameter Real C1r=-(2*Gaaser - Gabser + sqrt(3)*Babser - Gacser - sqrt(3)*
      Bacser)/2;
  parameter Real C1i=-(2*Baaser - Babser - sqrt(3)*Gabser - Bacser + sqrt(3)*
      Gacser)/2;
  parameter Real C2r=-(2*Gbaser - Gbbser + sqrt(3)*Bbbser - Gbcser - sqrt(3)*
      Bbcser)/2;
  parameter Real C2i=-(2*Bbaser - Bbbser - sqrt(3)*Gbbser - Bbcser + sqrt(3)*
      Gbcser)/2;
  parameter Real C3r=-(2*Gcaser - Gcbser + sqrt(3)*Bcbser - Gccser - sqrt(3)*
      Bccser)/2;
  parameter Real C3i=-(2*Bcaser - Bcbser - sqrt(3)*Gcbser - Bccser + sqrt(3)*
      Gccser)/2;

  //Calculating elements of Matrix D
  parameter Real D11r=Gaaser + Gaasm;
  parameter Real D11i=Baaser + Baasm;
  parameter Real D12r=Gabser + Gabsm;
  parameter Real D12i=Babser + Babsm;
  parameter Real D13r=Gacser + Gacsm;
  parameter Real D13i=Bacser + Bacsm;
  parameter Real D21r=Gbaser + Gbasm;
  parameter Real D21i=Bbaser + Bbasm;
  parameter Real D22r=Gbbser + Gbbsm;
  parameter Real D22i=Bbbser + Bbbsm;
  parameter Real D23r=Gbcser + Gbcsm;
  parameter Real D23i=Bbcser + Bbcsm;
  parameter Real D31r=Gcaser + Gcasm;
  parameter Real D31i=Bcaser + Bcasm;
  parameter Real D32r=Gcbser + Gcbsm;
  parameter Real D32i=Bcbser + Bcbsm;
  parameter Real D33r=Gccser + Gccsm;
  parameter Real D33i=Bccser + Bccsm;
algorithm
  V := [Ar, Ai, MB1r, MB1i, MB2r, MB2i, MB3r, MB3i, C1r, C1i, C2r, C2i, C3r,
    C3i, D11r, D11i, D12r, D12i, D13r, D13i, D21r, D21i, D22r, D22i, D23r, D23i,
    D31r, D31i, D32r, D32i, D33r, D33i]
;
end Y_Yg;

within OpenIPSL.Electrical.ThreePhase.Branches.Transformer;
model Transformer_3Ph "Three Phase transformer modeled as a PI-equivalent device"
  extends ThreePhaseComponent;

  import OpenIPSL.Electrical.ThreePhase.Branches.Transformer.TransfConnection.Yg_Yg;
  import OpenIPSL.Electrical.ThreePhase.Branches.Transformer.TransfConnection.D_D;
  import OpenIPSL.Electrical.ThreePhase.Branches.Transformer.TransfConnection.Y_Y;
  import OpenIPSL.Electrical.ThreePhase.Branches.Transformer.TransfConnection.D_Yg;
  import OpenIPSL.Electrical.ThreePhase.Branches.Transformer.TransfConnection.Yg_D;
  import OpenIPSL.Electrical.ThreePhase.Branches.Transformer.TransfConnection.D_Y;
  import OpenIPSL.Electrical.ThreePhase.Branches.Transformer.TransfConnection.Y_D;
  import OpenIPSL.Electrical.ThreePhase.Branches.Transformer.TransfConnection.Y_Yg;
  import OpenIPSL.Electrical.ThreePhase.Branches.Transformer.TransfConnection.Yg_Y;

  OpenIPSL.Interfaces.PwPin Ain
    ;
  OpenIPSL.Interfaces.PwPin Bin
    ;
  OpenIPSL.Interfaces.PwPin Cin
    ;
  OpenIPSL.Interfaces.PwPin Aout
    ;
  OpenIPSL.Interfaces.PwPin Bout
    ;
  OpenIPSL.Interfaces.PwPin Cout
    ;
  parameter Integer Connection=0
    "0 Yg-Yg; 1 D-D; 2 Y-Y; 3 D-Yg; 4 Yg-D; 5 D-Y; 6 Y-D; 7 Y-Yg; 8 Yg-Y;"
    ;
  parameter Real tap=1 "Nominal tap ratio (Vs/Vp)"
    ;
  parameter Types.PerUnit X=0.001 "Leakage reactance"
    ;
  parameter Types.PerUnit R=0.1 "Windings copper resistance"
    ;
protected
  function ConnectionType
    input Integer Connection;
    input Real X, R, tap;
    output Real[12, 12] PiEquations;
  algorithm
    if Connection == 0 then
      PiEquations := Yg_Yg(
          X,
          R,
          tap);
    elseif Connection == 1 then
      PiEquations := D_D(
          X,
          R,
          tap);
    elseif Connection == 2 then
      PiEquations := Y_Y(
          X,
          R,
          tap);
    elseif Connection == 3 then
      PiEquations := D_Yg(
          X,
          R,
          tap);
    elseif Connection == 4 then
      PiEquations := Yg_D(
          X,
          R,
          tap);
    elseif Connection == 5 then
      PiEquations := D_Y(
          X,
          R,
          tap);
    elseif Connection == 6 then
      PiEquations := Y_D(
          X,
          R,
          tap);
    elseif Connection == 7 then
      PiEquations := Y_Yg(
          X,
          R,
          tap);
    elseif Connection == 8 then
      PiEquations := Yg_Y(
          X,
          R,
          tap);
    end if;
  end ConnectionType;

  // Getting pi model matrix for Yg_Yg connection
  parameter Real[12, 12] OperPI=ConnectionType(
      Connection,
      X,
      R,
      tap);
  parameter Real[6, 6] Amat=OperPI[1:6, 1:6];
  parameter Real[6, 6] Bmat=OperPI[1:6, 7:12];
  parameter Real[6, 6] Cmat=OperPI[7:12, 1:6];
  parameter Real[6, 6] Dmat=OperPI[7:12, 7:12];

  // Writing matrix for voltages (in and out)
  Real[6, 1] Vin=[Ain.vr; Ain.vi; Bin.vr; Bin.vi; Cin.vr; Cin.vi];
  Real[6, 1] Vout=[Aout.vr; Aout.vi; Bout.vr; Bout.vi; Cout.vr; Cout.vi];
  // Writing matrix for currents (in and out)
  Real[6, 1] Iin=[Ain.ir; Ain.ii; Bin.ir; Bin.ii; Cin.ir; Cin.ii];
  Real[6, 1] Iout=[Aout.ir; Aout.ii; Bout.ir; Bout.ii; Cout.ir; Cout.ii];

equation
  // Equations according to pi model
  Iin = Amat*Vin + Bmat*Vout;
  Iout = Cmat*Vin + Dmat*Vout

  ;
end Transformer_3Ph;

within OpenIPSL.Electrical.ThreePhase.Branches.Transformer.TransfConnection;
function D_D "Calculation of impedance matrices for a delta-delta-connected three-phase transformer."
  extends Modelica.Icons.Function;
  input Real X;
  input Real R;
  input Real tap;
  output Real[12, 12] PiMatrix;
protected
  parameter Real sGser=((1/tap)/3)*(2*R/(R*R + X*X));
  parameter Real sBser=((1/tap)/3)*(-2*X/(R*R + X*X));
  parameter Real mGser=((1/tap)/3)*(-R/(R*R + X*X));
  parameter Real mBser=((1/tap)/3)*(X/(R*R + X*X));
  parameter Real sGshk=((1 - tap)/(3*tap*tap))*(2*R/(R*R + X*X));
  parameter Real sBshk=((1 - tap)/(3*tap*tap))*(-2*X/(R*R + X*X));
  parameter Real mGshk=((1 - tap)/(3*tap*tap))*(-R/(R*R + X*X));
  parameter Real mBshk=((1 - tap)/(3*tap*tap))*(X/(R*R + X*X));

  //Writing the Y_ser matrix according to Simulight
  parameter Real[6, 6] Y_ser=[sGser, -sBser, mGser, -mBser, mGser, -mBser;
      sBser, sGser, mBser, mGser, mBser, mGser; mGser, -mBser, sGser, -sBser,
      mGser, -mBser; mBser, mGser, sBser, sGser, mBser, mGser; mGser, -mBser,
      mGser, -mBser, sGser, -sBser; mBser, mGser, mBser, mGser, sBser, sGser];

  //Writing the Y_sht_k matrix according to Simulight
  parameter Real[6, 6] Yshtk=[sGshk, -sBshk, mGshk, -mBshk, mGshk, -mBshk;
      sBshk, sGshk, mBshk, mGshk, mBshk, mGshk; mGshk, -mBshk, sGshk, -sBshk,
      mGshk, -mBshk; mBshk, mGshk, sBshk, sGshk, mBshk, mGshk; mGshk, -mBshk,
      mGshk, -mBshk, sGshk, -sBshk; mBshk, mGshk, mBshk, mGshk, sBshk, sGshk];

  //Writing the Y_sht_m matrix according to Simulight
  parameter Real[6, 6] Yshtm=zeros(6, 6);

  //Calculating the parameters for the Transformer
  //Writing the matrix A (Yser1+Yshtk)
  parameter Real[6, 6] A=Y_ser + Yshtk;

  //Writing the matrix B (-Yser1)
  parameter Real[6, 6] B=-Y_ser;

  //Writing the matrix MC (-Yser2)
  parameter Real[6, 6] C=-Y_ser;

  //Writing the matrix D (Yser2+Yshtm)
  parameter Real[6, 6] D=Y_ser + Yshtm;
algorithm
  PiMatrix := [A, B; C, D]
;
end D_D;

within OpenIPSL.Electrical.ThreePhase.Branches.Transformer.TransfConnection;
function D_Y "Calculation of impedance matrices for a delta-wye-connected three-phase transformer."
  extends Modelica.Icons.Function;
  input Real X;
  input Real R;
  input Real tap;
  output Real[12, 12] PiMatrix;

protected
  parameter Real sGser=((1/tap)/sqrt(3))*(R/(R*R + X*X));
  parameter Real sBser=((1/tap)/sqrt(3))*(-X/(R*R + X*X));
  parameter Real mGser=((1/tap)/sqrt(3))*(-R/(R*R + X*X));
  parameter Real mBser=((1/tap)/sqrt(3))*(X/(R*R + X*X));
  parameter Real sGshk=((2 - tap*sqrt(3))/(3*tap*tap))*(R/(R*R + X*X));
  parameter Real sBshk=((2 - tap*sqrt(3))/(3*tap*tap))*(-X/(R*R + X*X));
  parameter Real mGshk=((tap*sqrt(3) - 1)/(3*tap*tap))*(R/(R*R + X*X));
  parameter Real mBshk=((tap*sqrt(3) - 1)/(3*tap*tap))*(-X/(R*R + X*X));
  parameter Real nGshk=((-1)/(3*tap*tap))*(R/(R*R + X*X));
  parameter Real nBshk=((-1)/(3*tap*tap))*(-X/(R*R + X*X));
  parameter Real sGshm=((2*tap - sqrt(3))/(3*tap))*(R/(R*R + X*X));
  parameter Real sBshm=((2*tap - sqrt(3))/(3*tap))*(-X/(R*R + X*X));
  parameter Real mGshm=(-1/3)*(R/(R*R + X*X));
  parameter Real mBshm=(-1/3)*(-X/(R*R + X*X));
  parameter Real nGshm=((sqrt(3) - tap)/(3*tap))*(R/(R*R + X*X));
  parameter Real nBshm=((sqrt(3) - tap)/(3*tap))*(-X/(R*R + X*X));
  parameter Real zero=1e-6;

  //Writing the Y_ser1 matrix according to Simulight
  parameter Real[6, 6] Y_ser1=[sGser, -sBser, mGser, -mBser, zero, zero;
      sBser, sGser, mBser, mGser, zero, zero; zero, zero, sGser, -sBser,
      mGser, -mBser; zero, zero, sBser, sGser, mBser, mGser; mGser, -mBser,
      zero, zero, sGser, -sBser; mBser, mGser, zero, zero, sBser, sGser];

  //Writing the Y_ser2 matrix according to Simulight
  parameter Real[6, 6] Y_ser2=[sGser, -sBser, zero, zero, mGser, -mBser;
      sBser, sGser, zero, zero, mBser, mGser; mGser, -mBser, sGser, -sBser,
      zero, zero; mBser, mGser, sBser, sGser, zero, zero; zero, zero, mGser,
      -mBser, sGser, -sBser; zero, zero, mBser, mGser, sBser, sGser];

  //Writing the Y_sht_k matrix according to Simulight
  parameter Real[6, 6] Yshtk=[sGshk, -sBshk, mGshk, -mBshk, nGshk, -nBshk;
      sBshk, sGshk, mBshk, mGshk, nBshk, nGshk; nGshk, -nBshk, sGshk, -sBshk,
      mGshk, -mBshk; nBshk, nGshk, sBshk, sGshk, mBshk, mGshk; mGshk, -mBshk,
      nGshk, -nBshk, sGshk, -sBshk; mBshk, mGshk, nBshk, nGshk, sBshk, sGshk];

  //Writing the Y_sht_m matrix according to Simulight
  parameter Real[6, 6] Yshtm=[sGshm, -sBshm, mGshm, -mBshm, nGshm, -nBshm;
      sBshm, sGshm, mBshm, mGshm, nBshm, nGshm; nGshm, -nBshm, sGshm, -sBshm,
      mGshm, -mBshm; nBshm, nGshm, sBshm, sGshm, mBshm, mGshm; mGshm, -mBshm,
      nGshm, -nBshm, sGshm, -sBshm; mBshm, mGshm, nBshm, nGshm, sBshm, sGshm];

  //Calculating the parameters for the Transformer
  //Writing the matrix A (Yser1+Yshtk)
  parameter Real[6, 6] A=Y_ser1 + Yshtk;

  //Writing the matrix B (-Yser1)
  parameter Real[6, 6] B=-Y_ser1;

  //Writing the matrix MC (-Yser2)
  parameter Real[6, 6] C=-Y_ser2;

  //Writing the matrix D (Yser2+Yshtm)
  parameter Real[6, 6] D=Y_ser2 + Yshtm;

algorithm
  PiMatrix := [A, B; C, D]
;
end D_Y;

within OpenIPSL.Electrical.ThreePhase.Branches.Transformer.TransfConnection;
function D_Yg "Calculation of impedance matrices for a delta-grounded-wye-connected three-phase transformer."
  extends Modelica.Icons.Function;
  input Real X;
  input Real R;
  input Real tap;
  output Real[12, 12] PiMatrix;
protected
  parameter Real sGser=(1/tap/sqrt(3))*(R/(R*R + X*X));
  parameter Real sBser=(1/tap/sqrt(3))*(-X/(R*R + X*X));
  parameter Real mGser=(1/tap/sqrt(3))*(-R/(R*R + X*X));
  parameter Real mBser=(1/tap/sqrt(3))*(X/(R*R + X*X));
  parameter Real sGshk=((2/3/tap/tap) - (1/tap/sqrt(3)))*(R/(R*R + X*X));
  parameter Real sBshk=((2/3/tap/tap) - (1/tap/sqrt(3)))*(-X/(R*R + X*X));
  parameter Real mGshk=((1/3/tap/tap))*(-R/(R*R + X*X));
  parameter Real mBshk=((1/3/tap/tap))*(X/(R*R + X*X));
  parameter Real nGshk=((1/sqrt(3)/tap) - (1/3/tap/tap))*(R/(R*R + X*X));
  parameter Real nBshk=((1/sqrt(3)/tap) - (1/3/tap/tap))*(-X/(R*R + X*X));
  parameter Real sGshm=(1 - (1/tap/sqrt(3)))*(R/(R*R + X*X));
  parameter Real sBshm=(1 - (1/tap/sqrt(3)))*(-X/(R*R + X*X));
  parameter Real mGshm=(1/tap/sqrt(3))*(R/(R*R + X*X));
  parameter Real mBshm=(1/tap/sqrt(3))*(-X/(R*R + X*X));
  parameter Real zero=1e-6;

  //Writing the Y_ser1 matrix according to Simulight
  parameter Real[6, 6] Y_ser1=[sGser, -sBser, zero, zero, mGser, -mBser;
      sBser, sGser, zero, zero, mBser, mGser; mGser, -mBser, sGser, -sBser,
      zero, zero; mBser, mGser, sBser, sGser, zero, zero; zero, zero, mGser,
      -mBser, sGser, -sBser; zero, zero, mBser, mGser, sBser, sGser];

  //Writing the Y_ser2 matrix according to Simulight
  parameter Real[6, 6] Y_ser2=[sGser, -sBser, mGser, -mBser, zero, zero;
      sBser, sGser, mBser, mGser, zero, zero; zero, zero, sGser, -sBser,
      mGser, -mBser; zero, zero, sBser, sGser, mBser, mGser; mGser, -mBser,
      zero, zero, sGser, -sBser; mBser, mGser, zero, zero, sBser, sGser];

  //Writing the Y_sht_k matrix according to Simulight
  parameter Real[6, 6] Yshtk=[sGshk, -sBshk, mGshk, -mBshk, nGshk, -nBshk;
      sBshk, sGshk, mBshk, mGshk, nBshk, nGshk; nGshk, -nBshk, sGshk, -sBshk,
      mGshk, -mBshk; nBshk, nGshk, sBshk, sGshk, mBshk, mGshk; mGshk, -mBshk,
      nGshk, -nBshk, sGshk, -sBshk; mBshk, mGshk, nBshk, nGshk, sBshk, sGshk];

  //Writing the Y_sht_m matrix according to Simulight
  parameter Real[6, 6] Yshtm=[sGshm, -sBshm, mGshm, -mBshm, zero, zero; sBshm,
      sGshm, mBshm, mGshm, zero, zero; zero, zero, sGshm, -sBshm, mGshm, -
      mBshm; zero, zero, sBshm, sGshm, mBshm, mGshm; mGshm, -mBshm, zero,
      zero, sGshm, -sBshm; mBshm, mGshm, zero, zero, sBshm, sGshm];

  //Calculating the parameters for the Transformer
  //Writing the matrix A (Yser1+Yshtk)
  parameter Real[6, 6] A=Y_ser1 + Yshtk;

  //Writing the matrix B (-Yser1)
  parameter Real[6, 6] B=-Y_ser1;

  //Writing the matrix MC (-Yser2)
  parameter Real[6, 6] C=-Y_ser2;

  //Writing the matrix D (Yser2+Yshtm)
  parameter Real[6, 6] D=Y_ser2 + Yshtm;
algorithm
  PiMatrix := [A, B; C, D]
;
end D_Yg;

within OpenIPSL.Electrical.ThreePhase.Branches.Transformer.TransfConnection;
function Yg_D "Calculation of impedance matrices for a grounded-wye-delta-connected three-phase transformer."
  extends Modelica.Icons.Function;
  input Real X;
  input Real R;
  input Real tap;
  output Real[12, 12] PiMatrix;

protected
  parameter Real sGser=(1/tap/sqrt(3))*(R/(R*R + X*X));
  parameter Real sBser=(1/tap/sqrt(3))*(-X/(R*R + X*X));
  parameter Real mGser=(1/tap/sqrt(3))*(-R/(R*R + X*X));
  parameter Real mBser=(1/tap/sqrt(3))*(X/(R*R + X*X));
