within OpenIPSL.Electrical.ThreePhase.Buses;
model Bus_1Ph "Single-phase bus"
  extends ThreePhaseComponent;
  OpenIPSL.Interfaces.PwPin p1(vr(start=V_1*cos(angle_1)),
                               vi(start=V_1*sin(angle_1)))
    ;

  parameter Types.PerUnit V_1=1 "Voltage magnitude for phase 1"
    ;
  parameter Types.Angle angle_1=0 "Voltage angle for phase 1"
    ;
  Types.PerUnit V1(start=V_1) "Bus voltage magnitude for phase 1";
  Types.Angle angle1(start=angle_1) "Bus voltage angle for phase 1";

protected
  Real[1, 2] Vin=[p1.vr, p1.vi];

equation
  V1 = sqrt(Vin[1, 1]^2 + Vin[1, 2]^2);
  angle1 = atan2(Vin[1, 2], Vin[1, 1]);
  p1.ir = 0;
  p1.ii = 0

  ;
end Bus_1Ph;

within OpenIPSL.Electrical.ThreePhase.Buses;
model Bus_2Ph "Two-phase bus"
  extends ThreePhaseComponent;
  import Modelica.Constants.pi;
  OpenIPSL.Interfaces.PwPin p1(vr(start=V_1*cos(angle_1)),
                               vi(start=V_1*sin(angle_1)))
    ;
  OpenIPSL.Interfaces.PwPin p2(vr(start=V_2*cos(angle_2)),
                               vi(start=V_2*sin(angle_2)))
    ;

  parameter Types.PerUnit V_1=1 "Voltage magnitude for phase 1"
    ;
  parameter Types.PerUnit V_2=1 "Voltage magnitude for phase 2"
    ;
  parameter Types.Angle angle_1=0 "Voltage angle for phase 1"
    ;
  parameter Types.Angle angle_2=-2*C.pi/3 "Voltage angle for phase 2"
    ;
  Types.PerUnit V1(start=V_1) "Bus voltage magnitude for phase 1";
  Types.Angle angle1(start=angle_1)
    "Bus voltage angle for phase 1";
  Types.PerUnit V2(start=V_2) "Bus voltage magnitude for phase 2";
  Types.Angle angle2(start=angle_2)
    "Bus voltage angle for phase 2";

protected
  Real[1, 4] Vin=[p1.vr, p1.vi, p2.vr, p2.vi];

equation
  V1 = sqrt(Vin[1, 1]^2 + Vin[1, 2]^2);
  angle1 = atan2(Vin[1, 2], Vin[1, 1]);
  V2 = sqrt(Vin[1, 3]^2 + Vin[1, 4]^2);
  angle2 = atan2(Vin[1, 4], Vin[1, 3]);
  p1.ir = 0;
  p1.ii = 0;
  p2.ir = 0;
  p2.ii = 0

  ;
end Bus_2Ph;

within OpenIPSL.Electrical.ThreePhase.Buses;
model Bus_3Ph "Three-phase bus"
  extends ThreePhaseComponent;
  OpenIPSL.Interfaces.PwPin p1(vr(start=V_A*cos(angle_A)),
                               vi(start=V_A*sin(angle_A)))
    ;
  OpenIPSL.Interfaces.PwPin p2(vr(start=V_B*cos(angle_B)),
                               vi(start=V_B*sin(angle_B)))
    ;
  OpenIPSL.Interfaces.PwPin p3(vr(start=V_C*cos(angle_C)),
                               vi(start=V_C*sin(angle_C)))
    ;

  parameter Types.PerUnit V_A=1 "Voltage magnitude for phase A"
    ;
  parameter Types.PerUnit V_B=1 "Voltage magnitude for phase B"
    ;
  parameter Types.PerUnit V_C=1 "Voltage magnitude for phase C"
    ;
  parameter Types.Angle angle_A=0 "Voltage angle for phase A"
    ;
  parameter Types.Angle angle_B=-2*C.pi/3 "Voltage angle for phase B"
    ;
  parameter Types.Angle angle_C=2*C.pi/3 "Voltage angle for phase C"
    ;
  Types.PerUnit Va(start=V_A) "Bus voltage magnitude for phase A";
  Types.Angle angle_a(start=angle_A)
    "Bus voltage angle for phase A";
  Types.PerUnit Vb(start=V_B) "Bus voltage magnitude for phase B";
  Types.Angle angle_b(start=angle_B)
    "Bus voltage angle for phase B";
  Types.PerUnit Vc(start=V_C) "Bus voltage magnitude for phase C";
  Types.Angle angle_c(start=angle_C)
    "Bus voltage angle for phase C";

protected
  Real[1, 6] Vin=[p1.vr, p1.vi, p2.vr, p2.vi, p3.vr, p3.vi];

equation
  Va = sqrt(Vin[1, 1]^2 + Vin[1, 2]^2);
  angle_a = atan2(Vin[1, 2], Vin[1, 1]);
  Vb = sqrt(Vin[1, 3]^2 + Vin[1, 4]^2);
  angle_b = atan2(Vin[1, 4], Vin[1, 3]);
  Vc = sqrt(Vin[1, 5]^2 + Vin[1, 6]^2);
  angle_c = atan2(Vin[1, 6], Vin[1, 5]);
  p1.ir = 0;
  p1.ii = 0;
  p2.ir = 0;
  p2.ii = 0;
  p3.ir = 0;
  p3.ii = 0

  ;
end Bus_3Ph;

within OpenIPSL.Electrical.ThreePhase.Buses;
model InfiniteBus "Three-phase infinite bus"
  extends ThreePhaseComponent;
  parameter Types.Voltage V_b=400e3
    "Base voltage of the bus"
    ;
  parameter Types.PerUnit V_A=1
    "Voltage magnitude for phase A"
    ;
  parameter Types.Angle angle_A = 0 "Voltage angle for phase A"
    ;
  parameter Types.PerUnit V_B=1 "Voltage magnitude for phase B"
    ;
  parameter Types.Angle angle_B = -2*C.pi/3 "Voltage angle for phase B"
    ;
  parameter Types.PerUnit V_C=1 "Voltage magnitude for phase C"
    ;
  parameter Types.Angle angle_C= 2*C.pi/3 "Voltage angle for phase C"
    ;
  parameter Types.ActivePower P_A=1e6
    "Initial active power"
    ;
  parameter Types.ReactivePower Q_A=0
    "Initial reactive power"
    ;
  parameter Types.ActivePower P_B=1e6
    "Initial active power"
    ;
  parameter Types.ReactivePower Q_B=0
    "Initial reactive power"
    ;
  parameter Types.ActivePower P_C=1e6
    "Initial active power"
    ;
  parameter Types.ReactivePower Q_C=0
    "Initial reactive power"
    ;
  parameter Types.Frequency fn=SysData.fn
    "System frequency"
    ;
  OpenIPSL.Interfaces.PwPin p1
    ;
  OpenIPSL.Interfaces.PwPin p2
    ;
  OpenIPSL.Interfaces.PwPin p3
    ;
  Types.ActivePower Pa "Active Power supplied by the Infinite bus (phase a)";
  Types.ReactivePower Qa "Reactive Power supplied by the Infinite bus (phase a)";
  Types.ActivePower Pb "Active Power supplied by the Infinite bus (phase b)";
  Types.ReactivePower Qb "Reactive Power supplied by the Infinite bus (phase b)";
  Types.ActivePower Pc "Active Power supplied by the Infinite bus (phase c)";
  Types.ReactivePower Qc "Reactive Power supplied by the Infinite bus (phase c)";
equation
  // Equations for Phase A
  p1.vr = V_A*cos(angle_A);
  p1.vi = V_A*sin(angle_A);
  Pa = -(p1.vr*p1.ir + p1.vi*p1.ii)*S_p;
  Qa = -(p1.vr*p1.ii - p1.vi*p1.ir)*S_p;
  // Equations for Phase B
  p2.vr = V_B*cos(angle_B);
  p2.vi = V_B*sin(angle_B);
  Pb = -(p2.vr*p2.ir + p2.vi*p2.ii)*S_p;
  Qb = -(p2.vr*p2.ii - p2.vi*p2.ir)*S_p;
  // Equations for Phase C
  p3.vr = V_C*cos(angle_C);
  p3.vi = V_C*sin(angle_C);
  Pc = -(p3.vr*p3.ir + p3.vi*p3.ii)*S_p;
  Qc = -(p3.vr*p3.ii - p3.vi*p3.ir)*S_p
  ;
end InfiniteBus;

within OpenIPSL.Electrical.ThreePhase.Buses;
model MeasurementBus "Three-phase active and reactive power measurement bus"
  extends ThreePhaseComponent;
  OpenIPSL.Interfaces.PwPin p1 "Phase A output" ;
  OpenIPSL.Interfaces.PwPin p2 "Phase B output" ;
  OpenIPSL.Interfaces.PwPin p3 "Phase C output" ;
  OpenIPSL.Interfaces.PwPin p4 "Phase A input" ;
  OpenIPSL.Interfaces.PwPin p5 "Phase B input" ;
  OpenIPSL.Interfaces.PwPin p6 "Phase C input" ;
  Types.ActivePower Pa "Active power suplyed in phase a";
  Types.ReactivePower Qa "Reactive power suplyed in phase a";
  Types.ActivePower Pb "Active power suplyed in phase b";
  Types.ReactivePower Qb "Reactive power suplyed in phase b";
  Types.ActivePower Pc "Active power suplyed in phase c";
  Types.ReactivePower Qc "Reactive power suplyed in phase c";
  Modelica.Blocks.Interfaces.RealOutput pa(unit="1") = Pa/S_b "[pu, system base]" ;
  Modelica.Blocks.Interfaces.RealOutput pb(unit="1") = Pb/S_b "[pu, system base]" ;
  Modelica.Blocks.Interfaces.RealOutput pc(unit="1") = Pc/S_b "[pu, system base]" ;

  Modelica.Blocks.Interfaces.RealOutput qa(unit="1") = Qa/S_b "[pu, system base]" ;
  Modelica.Blocks.Interfaces.RealOutput qb(unit="1") = Qb/S_b "[pu, system base]" ;
  Modelica.Blocks.Interfaces.RealOutput qc(unit="1") = Qc/S_b "[pu, system base]" ;
equation
  // Equations for Phase A
  Pa = -(p1.vr*p1.ir + p1.vi*p1.ii)*S_p;
  Qa = -(p1.vr*p1.ii - p1.vi*p1.ir)*S_p;
  // Equations for Phase B
  Pb = -(p2.vr*p2.ir + p2.vi*p2.ii)*S_p;
  Qb = -(p2.vr*p2.ii - p2.vi*p2.ir)*S_p;
  // Equations for Phase C
  Pc = -(p3.vr*p3.ir + p3.vi*p3.ii)*S_p;
  Qc = -(p3.vr*p3.ii - p3.vi*p3.ir)*S_p;
  connect(p4, p1) ;
  connect(p5, p2) ;
  connect(p6, p3) 
  ;
end MeasurementBus;

within OpenIPSL.Electrical.ThreePhase.Loads;
model DeltaDynLoad_3Ph "Variable three-phase delta load"
  extends ThreePhaseComponent;
  import Modelica.Blocks.Interfaces.*;
  Modelica.Blocks.Interfaces.RealInput DynFact "Load Curve [pu]" ;
  OpenIPSL.Interfaces.PwPin A ;
  OpenIPSL.Interfaces.PwPin B ;
  OpenIPSL.Interfaces.PwPin C ;
  parameter Integer ModelType=0 "0- Constant Power Model, 1- ZIP Model;"
    ;
  parameter Types.ActivePower P_ab=1e6 "Active power for line AB"
    ;
  parameter Types.ReactivePower Q_ab=0 "Reactive power for line AB"
    ;
  parameter Types.ActivePower P_bc=1e6 "Active power for line BC"
    ;
  parameter Types.ReactivePower Q_bc=0 "Reactive power for line BC"
    ;
  parameter Types.ActivePower P_ca=1e6 "Active power for line CA"
    ;
  parameter Types.ReactivePower Q_ca=0 "Reactive power for line CA"
    ;
  parameter Real A_ab=0 "Percentage of Constant Power Load for Line AB (%)"
    ;
  parameter Real B_ab=0 "Percentage of Constant Current Load for Line AB (%)"
    ;
  parameter Real C_ab=0 "Percentage of Constant Impedance Load for Line AB (%)"
    ;
  parameter Real A_bc=0 "Percentage of Constant Power Load for Line BC (%)"
    ;
  parameter Real B_bc=0 "Percentage of Constant Current Load for Line BC (%)"
    ;
  parameter Real C_bc=0
    "Percentage of Constant Impedance Load] for Line BC (%)"
    ;
  parameter Real A_ca=0 "Percentage of Constant Power Load for Line CA (%)"
    ;
  parameter Real B_ca=0 "Percentage of Constant Current Load for Line CA (%)"
    ;
  parameter Real C_ca=0 "Percentage of Constant Impedance Load for Line CA (%)"
    ;

protected
  Real[1, 6] TPhasePower=[P_ab, P_bc, Pca, Q_ab, Q_bc, Q_ca]/S_p*DynFact;
  parameter Real[1, 9] ZIP_coef=[A_ab/100, B_ab/100, C_ab/100, A_bc/100, B_bc/
      100, C_bc/100, A_ca/100, B_ca/100, C_ca/100];

  // Calculating the Line Voltage in p.u.
  Real Vabr=(A.vr - B.vr)/sqrt(3);
  Real Vabi=(A.vi - B.vi)/sqrt(3);
  Real Vbcr=(B.vr - C.vr)/sqrt(3);
  Real Vbci=(B.vi - C.vi)/sqrt(3);
  Real Vcar=(C.vr - A.vr)/sqrt(3);
  Real Vcai=(C.vi - A.vi)/sqrt(3);

  // Calculating the Magnitude of V and V squared
  Real Vab=sqrt(Vabr^2 + Vabi^2);
  Real Vbc=sqrt(Vbcr^2 + Vbci^2);
  Real Vca=sqrt(Vcar^2 + Vcai^2);
  Real Vab2=Vab^2;
  Real Vbc2=Vbc^2;
  Real Vca2=Vca^2;

  // Calculating the Coefficients for Adjusting the Power
  Real Coef_A=ZIP_coef[1, 1] + ZIP_coef[1, 2]*Vab + ZIP_coef[1, 3]*Vab2;
  Real Coef_B=ZIP_coef[1, 4] + ZIP_coef[1, 5]*Vbc + ZIP_coef[1, 6]*Vbc2;
  Real Coef_C=ZIP_coef[1, 7] + ZIP_coef[1, 8]*Vca + ZIP_coef[1, 9]*Vca2;

  Real[1, 3] in_coef=[Coef_A, Coef_B, Coef_C];

  function Coefficients
    input Real[1, 3] in_coef;
    input Integer ModelType;
    output Real[1, 3] Coef;

  algorithm
    if ModelType == 0 then
      Coef := [1, 1, 1];
    elseif ModelType == 1 then
      Coef := in_coef;
    end if;
  end Coefficients;

  Real[1, 3] Coef=Coefficients(in_coef, ModelType);

  function PowerDefinition
    input Integer ModelType;
    input Real[1, 6] TPhasePower;
    input Real[1, 3] Coef;
    output Real[1, 6] Cor_Power;
    // Identifying input elements for the Coefficients
  protected
    parameter Real coef_A=Coef[1, 1];
    parameter Real coef_B=Coef[1, 2];
    parameter Real coef_C=Coef[1, 3];
    // Identifying input elements for Power
    parameter Real Pab_cor=TPhasePower[1, 1]*coef_A;
    parameter Real Pbc_cor=TPhasePower[1, 2]*coef_B;
    parameter Real Pca_cor=TPhasePower[1, 3]*coef_C;
    parameter Real Qab_cor=TPhasePower[1, 4]*coef_A;
    parameter Real Qbc_cor=TPhasePower[1, 5]*coef_B;
    parameter Real Qca_cor=TPhasePower[1, 6]*coef_C;
  algorithm
    Cor_Power := [Pab_cor, Pbc_cor, Pca_cor, Qab_cor, Qbc_cor, Qca_cor];
  end PowerDefinition;

  Real[1, 6] Power=PowerDefinition(
      ModelType,
      TPhasePower,
      Coef);
  Real Pab=Power[1, 1];
  Real Pbc=Power[1, 2];
  Real Pca=Power[1, 3];
  Real Qab=Power[1, 4];
  Real Qbc=Power[1, 5];
  Real Qca=Power[1, 6];

  // Calculating the Line Current in Delta Load:

  Real Iabr=(Pab*Vabr + Qab*Vabi)/Vab2;
  Real Iabi=(Pab*Vabi - Qab*Vabr)/Vab2;
  Real Ibcr=(Pbc*Vbcr + Qbc*Vbci)/Vbc2;
  Real Ibci=(Pbc*Vbci - Qbc*Vbcr)/Vbc2;
  Real Icar=(Pca*Vcar + Qca*Vcai)/Vca2;
  Real Icai=(Pca*Vcai - Qca*Vcar)/Vca2;

equation

  A.ir = (Iabr - Icar)/sqrt(3);
  A.ii = (Iabi - Icai)/sqrt(3);
  B.ir = (Ibcr - Iabr)/sqrt(3);
  B.ii = (Ibci - Iabi)/sqrt(3);
  C.ir = (Icar - Ibcr)/sqrt(3);
  C.ii = (Icai - Ibci)/sqrt(3)

  ;
end DeltaDynLoad_3Ph;

within OpenIPSL.Electrical.ThreePhase.Loads;
model DeltaLoad_2Ph "Two-phase delta load"
  extends ThreePhaseComponent;
  OpenIPSL.Interfaces.PwPin A(
    vr(start=var0),
    vi(start=vai0),
    ir(start=iar0),
    ii(start=iai0)) ;
  OpenIPSL.Interfaces.PwPin B(
    vr(start=vbr0),
    vi(start=vbi0),
    ir(start=ibr0),
    ii(start=ibi0)) ;
  parameter Integer ModelType=0 "0- Constant Power Model, 1- ZIP Model;"
    ;

  parameter Types.PerUnit VA=1 "Voltage magnitude for phase A"
    ;
  parameter Types.Angle AngA= 0 "Voltage angle for phase A"
    ;
  parameter Types.PerUnit VB=1 "Voltage magnitude for phase B"
    ;
  parameter Types.Angle AngB = -2*C.pi/3 "Voltage angle for phase B"
    ;
  parameter Types.ActivePower P_ab=1e6
    "Initial active power"
    ;
  parameter Types.ReactivePower Q_ab=0
    "Initial reactive power"
    ;

  parameter Real A_ab=0 "Percentage of Constant Power Load for Line AB [%]"
    ;
  parameter Real B_ab=0 "Percentage of Constant Current Load for Line AB [%]"
    ;
  parameter Real C_ab=0 "Percentage of Constant Impedance Load for Line AB [%]"
    ;

protected
  parameter Real[1, 2] TPhasePower=[P_ab, Q_ab]/S_p;
  parameter Real[1, 3] ZIP_coef=[A_ab/100, B_ab/100, C_ab/100];

  // Calculating the Line Voltage in p.u.
  Real Vabr=(A.vr - B.vr)/sqrt(3);
  Real Vabi=(A.vi - B.vi)/sqrt(3);

  // Calculating the Magnitude of V and V squared
  Real Vab=sqrt(Vabr^2 + Vabi^2);
  Real Vab2=Vab^2;

  // Calculating the Coefficients for Adjusting the Power
  Real Coef_A=ZIP_coef[1, 1] + ZIP_coef[1, 2]*Vab + ZIP_coef[1, 3]*Vab2;

  Real in_coef=Coef_A;

  function Coefficients
    input Real in_coef;
    input Integer ModelType;
    output Real Coef;

  algorithm
    if ModelType == 0 then
      Coef := 1;
    elseif ModelType == 1 then
      Coef := in_coef;
    end if;
  end Coefficients;

  Real Coef=Coefficients(in_coef, ModelType);

  // Calculating new value for Active and Reactive Power
  Real Pab=TPhasePower[1, 1]*Coef;
  Real Qab=TPhasePower[1, 2]*Coef;

  // Initializing voltages for each pin
  parameter Real var0=VA*cos(AngA) "Initialization";
  parameter Real vai0=VA*sin(AngA) "Initialization";
  parameter Real vbr0=VB*cos(AngB) "Initialization";
  parameter Real vbi0=VB*sin(AngB) "Initialization";
  parameter Real iar0=(TPhasePower[1, 1]*(var0 - vbr0) + TPhasePower[1, 2]*(
      vai0 - vbi0))/((var0 - vbr0)^2 + (vai0 - vbi0)^2) "Initialization";
  parameter Real iai0=(TPhasePower[1, 1]*(vai0 - vbi0) - TPhasePower[1, 2]*(
      var0 - vbr0))/((var0 - vbr0)^2 + (vai0 - vbi0)^2) "Initialization";
  parameter Real ibr0=-iar0 "Initialization";
  parameter Real ibi0=-iai0 "Initialization";
equation
  A.ir = (Pab*(A.vr - B.vr) + Qab*(A.vi - B.vi))/((A.vr - B.vr)^2 + (A.vi - B.vi)
    ^2);
  A.ii = (Pab*(A.vi - B.vi) - Qab*(A.vr - B.vr))/((A.vr - B.vr)^2 + (A.vi - B.vi)
    ^2);
  B.ir = -(Pab*(A.vr - B.vr) + Qab*(A.vi - B.vi))/((A.vr - B.vr)^2 + (A.vi - B.vi)
    ^2);
  B.ii = -(Pab*(A.vi - B.vi) - Qab*(A.vr - B.vr))/((A.vr - B.vr)^2 + (A.vi - B.vi)
    ^2)

  ;
end DeltaLoad_2Ph;

within OpenIPSL.Electrical.ThreePhase.Loads;
model DeltaLoad_3Ph "Three-phase delta load"
  extends ThreePhaseComponent;
  import Modelica.Constants.pi;
  OpenIPSL.Interfaces.PwPin A(vr(start=var0), vi(start=vai0)) ;
  OpenIPSL.Interfaces.PwPin B(vr(start=vbr0), vi(start=vbi0)) ;
  OpenIPSL.Interfaces.PwPin C(vr(start=vcr0), vi(start=vci0)) ;
  parameter Integer ModelType=0 "0- Constant Power Model, 1- ZIP Model;"
    ;
  parameter Types.PerUnit VA=1 "Voltage magnitude for phase A"
    ;
  parameter Types.Angle AngA= 0 "Voltage angle for phase A"
    ;
  parameter Types.PerUnit VB=1 "Voltage magnitude for phase B"
    ;
  parameter Types.Angle AngB = -2*pi/3 "Voltage angle for phase B"
    ;
  parameter Types.PerUnit VC=1 "Voltage magnitude for phase C"
    ;
  parameter Types.Angle AngC= 2*pi/3 "Voltage angle for phase C"
    ;
  parameter Types.ActivePower P_ab=1e6
    "Initial active power"
    ;
  parameter Types.ReactivePower Q_ab=0
    "Initial reactive power"
    ;
  parameter Types.ActivePower P_bc=1e6
    "Initial active power"
    ;
  parameter Types.ReactivePower Q_bc=0
    "Initial reactive power"
    ;
  parameter Types.ActivePower P_ca=1e6
    "Initial active power"
    ;
  parameter Types.ReactivePower Q_ca=0
    "Initial reactive power"
    ;

  parameter Real A_ab=0 "Percentage of Constant Power Load for Line AB [%]"
    ;
  parameter Real B_ab=0 "Percentage of Constant Current Load for Line AB [%]"
    ;
  parameter Real C_ab=0 "Percentage of Constant Impedance Load for Line AB [%]"
    ;
  parameter Real A_bc=0 "Percentage of Constant Power Load for Line BC [%]"
    ;
  parameter Real B_bc=0 "Percentage of Constant Current Load for Line BC [%]"
    ;
  parameter Real C_bc=0
    "Percentage of Constant Impedance Load] for Line BC [%]"
    ;
  parameter Real A_ca=0 "Percentage of Constant Power Load for Line CA [%]"
    ;
  parameter Real B_ca=0 "Percentage of Constant Current Load for Line CA [%]"
    ;
  parameter Real C_ca=0 "Percentage of Constant Impedance Load for Line CA [%]"
    ;

protected
  parameter Real[1, 6] TPhasePower=[P_ab, P_bc, P_ca, Q_ab, Q_bc, Q_ca]/S_p;
  parameter Real[1, 9] ZIP_coef=[A_ab/100, B_ab/100, C_ab/100, A_bc/100, B_bc/
      100, C_bc/100, A_ca/100, B_ca/100, C_ca/100];

  // Calculating the Line Voltage in p.u.
  Real Vabr=(A.vr - B.vr)/sqrt(3);
  Real Vabi=(A.vi - B.vi)/sqrt(3);
  Real Vbcr=(B.vr - C.vr)/sqrt(3);
  Real Vbci=(B.vi - C.vi)/sqrt(3);
  Real Vcar=(C.vr - A.vr)/sqrt(3);
  Real Vcai=(C.vi - A.vi)/sqrt(3);
  Real[3, 2] Vline=[Vabr, Vabi; Vbcr, Vbci; Vcar, Vcai];

  // Calculating the Magnitude of V and V squared
  function Voltages
    input Real[3, 2] Vline;
    output Real[2, 3] out_volt;
  protected
    Real Vab=sqrt(Vline[1, 1]^2 + Vline[1, 2]^2);
    Real Vbc=sqrt(Vline[2, 1]^2 + Vline[2, 2]^2);
    Real Vca=sqrt(Vline[3, 1]^2 + Vline[3, 2]^2);
    Real Vab2=Vab^2;
    Real Vbc2=Vbc^2;
    Real Vca2=Vca^2;
  algorithm
    out_volt := [Vab, Vbc, Vca; Vab2, Vbc2, Vca2];
  end Voltages;

  Real[2, 3] Volt=Voltages(Vline);

  // Calculating the Coefficients for Adjusting the Power
  Real Coef_A=ZIP_coef[1, 1] + ZIP_coef[1, 2]*Volt[1, 1] + ZIP_coef[1, 3]*Volt[
      2, 1];
  Real Coef_B=ZIP_coef[1, 4] + ZIP_coef[1, 5]*Volt[1, 2] + ZIP_coef[1, 6]*Volt[
      2, 2];
  Real Coef_C=ZIP_coef[1, 7] + ZIP_coef[1, 8]*Volt[1, 3] + ZIP_coef[1, 9]*Volt[
      2, 3];

  Real[1, 3] in_coef=[Coef_A, Coef_B, Coef_C];

  function Coefficients
    input Real[1, 3] in_coef;
    input Integer ModelType;
    output Real[1, 3] Coef;

  algorithm
    if ModelType == 0 then
      Coef := [1, 1, 1];
    elseif ModelType == 1 then
      Coef := in_coef;
    end if;
  end Coefficients;

  Real[1, 3] Coef=Coefficients(in_coef, ModelType);

  // Calculating new value for Active and Reactive Power
  Real Pab=TPhasePower[1, 1]*Coef[1, 1];
  Real Pbc=TPhasePower[1, 2]*Coef[1, 2];
  Real Pca=TPhasePower[1, 3]*Coef[1, 3];
  Real Qab=TPhasePower[1, 4]*Coef[1, 1];
  Real Qbc=TPhasePower[1, 5]*Coef[1, 2];
  Real Qca=TPhasePower[1, 6]*Coef[1, 3];

  // Initializing voltages and currents for each pin
  parameter Real var0=VA*cos(AngA) "Initialization";
  parameter Real vai0=VA*sin(AngA) "Initialization";
  parameter Real vbr0=VB*cos(AngB) "Initialization";
  parameter Real vbi0=VB*sin(AngB) "Initialization";
  parameter Real vcr0=VC*cos(AngC) "Initialization";
  parameter Real vci0=VC*sin(AngC) "Initialization";

equation

  A.ir = (Pab*(A.vr - B.vr) + Qab*(A.vi - B.vi))/((A.vr - B.vr)^2 + (A.vi - B.vi)
    ^2) - (Pca*(C.vr - A.vr) + Qca*(C.vi - A.vi))/((C.vr - A.vr)^2 + (C.vi - A.vi)
    ^2);
  A.ii = (Pab*(A.vi - B.vi) - Qab*(A.vr - B.vr))/((A.vr - B.vr)^2 + (A.vi - B.vi)
    ^2) - (Pca*(C.vi - A.vi) - Qca*(C.vr - A.vr))/((C.vr - A.vr)^2 + (C.vi - A.vi)
    ^2);
  B.ir = (Pbc*(B.vr - C.vr) + Qbc*(B.vi - C.vi))/((B.vr - C.vr)^2 + (B.vi - C.vi)
    ^2) - (Pab*(A.vr - B.vr) + Qab*(A.vi - B.vi))/((A.vr - B.vr)^2 + (A.vi - B.vi)
    ^2);
  B.ii = (Pbc*(B.vi - C.vi) - Qbc*(B.vr - C.vr))/((B.vr - C.vr)^2 + (B.vi - C.vi)
    ^2) - (Pab*(A.vi - B.vi) - Qab*(A.vr - B.vr))/((A.vr - B.vr)^2 + (A.vi - B.vi)
    ^2);
  C.ir = (Pca*(C.vr - A.vr) + Qca*(C.vi - A.vi))/((C.vr - A.vr)^2 + (C.vi - A.vi)
    ^2) - (Pbc*(B.vr - C.vr) + Qbc*(B.vi - C.vi))/((B.vr - C.vr)^2 + (B.vi - C.vi)
    ^2);
  C.ii = (Pca*(C.vi - A.vi) - Qca*(C.vr - A.vr))/((C.vr - A.vr)^2 + (C.vi - A.vi)
    ^2) - (Pbc*(B.vi - C.vi) - Qbc*(B.vr - C.vr))/((B.vr - C.vr)^2 + (B.vi - C.vi)
    ^2)

