  Real Pb=TPhasePower[1, 2]*Coef[1, 2];
  Real Pc=TPhasePower[1, 3]*Coef[1, 3];
  Real Qa=TPhasePower[1, 4]*Coef[1, 1];
  Real Qb=TPhasePower[1, 5]*Coef[1, 2];
  Real Qc=TPhasePower[1, 6]*Coef[1, 3];

  // Initializing voltages for each pin
  parameter Real var0=VA*cos(AngA) "Initialization";
  parameter Real vai0=VA*sin(AngA) "Initialization";
  parameter Real vbr0=VB*cos(AngB) "Initialization";
  parameter Real vbi0=VB*sin(AngB) "Initialization";
  parameter Real vcr0=VC*cos(AngC) "Initialization";
  parameter Real vci0=VC*sin(AngC) "Initialization";

equation
  Pa = A.vr*A.ir + A.vi*A.ii;
  Qa = A.vi*A.ir - A.vr*A.ii;
  Pb = B.vr*B.ir + B.vi*B.ii;
  Qb = B.vi*B.ir - B.vr*B.ii;
  Pc = C.vr*C.ir + C.vi*C.ii;
  Qc = C.vi*C.ir - C.vr*C.ii
  ;
end WyeLoad_3Ph;

within OpenIPSL.Electrical.Wind;
model WindGenerator "Generic wind power generation model"
  import Modelica.Constants.pi;
  import Modelica.Constants.e;
  Modelica.Blocks.Interfaces.RealOutput Vw "Connector of Real output signal"
    ;
  parameter Types.Time tstart=5 "Start time of the wind gust";
  parameter Types.Time tstop=10 "Stop time of the wind gust";
  parameter SI.Velocity v0=14 "steady state wind speed";
  parameter SI.Velocity vmax=25 "peak wind speed for Mexican Hat";
  parameter SI.Velocity wmag=-4 "magnitude of the gust of wind";
  parameter Real sigma=1 "Mexican hat wavelet shape factor";
  parameter Integer typ=1 "1:constant 2:gust 3:mexican hat";
protected
  parameter Types.Time wgwidth=tstop - tstart;
equation
  if typ == 1 then
    Vw = v0;
  elseif typ == 2 then
    if time > tstart and time < tstop then
      Vw = v0 + wmag*(1 - cos((time - tstart)*2*Modelica.Constants.pi/wgwidth))
        /2;
    else
      Vw = v0;
    end if;
  else
    Vw = v0 + (vmax - v0)*(1 - (time - (tstop + tstart)/2)^2/sigma^2)*Modelica.Constants.e
      ^(-(time - (tstop + tstart)/2)^2/(2*sigma^2))
      "2/(sqrt(3*sigma)*Modelica.Constants.pi^(1/4))*(1 - ((time - (tstop + tstart)/2)/sigma)^2)*Modelica.Constants.e^((-((time - (tstop + tstart)/2)/sigma)^2)/(2*sigma^2)) + v0";
  end if
  ;
end WindGenerator;

within OpenIPSL.Electrical.Wind.GE.Type_3.Electrical_Control;
model Electrical_Control "Type 3 wind machine electrical control"
  import Modelica.Constants.inf;
  parameter Types.PerUnit qmax=1;
  parameter Types.PerUnit qmin=0;
  parameter Real KQi=1;
  parameter Types.PerUnit ex_x0_0=1;
  parameter Types.PerUnit ex_x1_0=1;
  parameter Real KVi=1;
  parameter Types.PerUnit xiqmax=1;
  parameter Types.PerUnit xiqmin=1;
  Modelica.Blocks.Interfaces.RealInput Qgen
    "Reactive Power produced by the Generator" ;
  Modelica.Blocks.Interfaces.RealInput Qord "Reactive power command"
    ;
  Modelica.Blocks.Interfaces.RealInput Pord "Active power command" ;
  Modelica.Blocks.Interfaces.RealInput Vterm "Terminal voltage" ;
  Modelica.Blocks.Interfaces.RealOutput Ipcmd "Current command" ;
  Modelica.Blocks.Interfaces.RealOutput Efd "Excitation voltage" ;
protected
  Modelica.Blocks.Math.Division division1 ;
  Modelica.Blocks.Nonlinear.Limiter limiter1(uMax=1.1, uMin=-inf) ;
  Modelica.Blocks.Nonlinear.Limiter limiter2(uMax=qmax, uMin=qmin) ;
  Modelica.Blocks.Math.Add add1(k1=-1) ;
  Modelica.Blocks.Continuous.LimIntegrator limIntegrator1(
    k=KQi,
    y_start=ex_x0_0,
    outMax=99999,
    outMin=-99999) ;
  Modelica.Blocks.Math.Add add2(k2=-1) ;
  Modelica.Blocks.Math.Gain gain1(k=KVi) ;
  lim_exc_s1 lim_exc_s11(
    typpe=1,
    xiqmax=xiqmax,
    xiqmin=xiqmin) ;
  lim_exc_s1 lim_exc_s12(
    typpe=2,
    xiqmax=xiqmax,
    xiqmin=xiqmin) ;
  Modelica.Blocks.Continuous.Integrator integrator1(y_start=ex_x1_0)
    ;
  Modelica.Blocks.Sources.Constant const(k=0) ;
equation
  connect(const.y, lim_exc_s12.Efd) ;

  connect(integrator1.y, lim_exc_s12.Vref) ;

  connect(lim_exc_s11.Efd, lim_exc_s12.y) ;
  connect(lim_exc_s12.Vt, Vterm) ;
  connect(lim_exc_s12.y, Efd) ;

  connect(gain1.y, lim_exc_s11.Vref) ;

  connect(lim_exc_s11.y, integrator1.u) ;
  connect(lim_exc_s11.Vt, Vterm) ;
  connect(Qgen, add1.u1) ;
  connect(Qord, limiter2.u) ;

  connect(limiter1.y, Ipcmd) ;
  connect(Vterm, division1.u2) ;
  connect(add2.u2, Vterm) ;

  connect(Pord, division1.u1) ;

  connect(add2.y, gain1.u) ;

  connect(limIntegrator1.y, add2.u1) ;

  connect(add1.y, limIntegrator1.u) ;
  connect(limiter2.y, add1.u2) ;
  connect(division1.y, limiter1.u) 
  ;
end Electrical_Control;

within OpenIPSL.Electrical.Wind.GE.Type_3.Electrical_Control;
model lim_exc_s1 "Exciter limiter model for wind machine"
  extends Modelica.Blocks.Icons.Block;
  parameter Types.PerUnit xiqmin=1;
  parameter Types.PerUnit xiqmax=1;
  parameter Integer typpe=1
      ;
  Modelica.Blocks.Interfaces.RealInput Efd "Input: Excitation voltage"
    ;
  Modelica.Blocks.Interfaces.RealInput Vt "Terminal Voltage" ;
  Modelica.Blocks.Interfaces.RealOutput y
    "Output: saturated excitation voltage" ;
  Modelica.Blocks.Interfaces.RealInput Vref "Reference Voltage " ;
equation
  if typpe == 1 then
    if Efd >= Vt + xiqmax and Vref >= 0 or Efd <= Vt + xiqmin and Vref <= 0 then
      y = 0;
    else
      y = Vref;
    end if;
  elseif typpe == 2 then
    if Vref >= Vt + xiqmax then
      y = Vt + xiqmax;
    elseif Vref <= Vt + xiqmin then
      y = Vt + xiqmin;
    else
      y = Vref;
    end if;
  else
    y = 0;
  end if
  ;
end lim_exc_s1;

within OpenIPSL.Electrical.Wind.GE.Type_3.Generator;
model Generator "Implementation of type 3 wind generator"
  import Modelica.Constants.pi;
  parameter Types.Frequency freq=50;
  parameter Real omega_0=2*pi*freq;
  parameter Real Kpllp=1;
  parameter Types.PerUnit ge_x0_0=1;
  parameter Types.PerUnit ge_x1_0=1;
  parameter Types.PerUnit ge_x2_0=1;
  parameter Types.ApparentPower GEN_base=1;
  parameter Types.ApparentPower SYS_base=1;
  parameter Types.PerUnit Lpp=1;
  Modelica.Blocks.Interfaces.RealInput Efd "Excitation voltage" ;
  Modelica.Blocks.Interfaces.RealInput Ipcmd "Current command" ;
  Modelica.Blocks.Interfaces.RealOutput Vt "Terminal voltage" ;
  Modelica.Blocks.Interfaces.RealOutput Pgen "Active power" ;
  Modelica.Blocks.Interfaces.RealOutput Qgen "Reactive power" ;
  OpenIPSL.Interfaces.PwPin p ;
  Types.Angle Anglet;
protected
  Types.PerUnit Vt_re;
  Types.PerUnit Vt_im;
  Modelica.Blocks.Continuous.Integrator integrator1(k=omega_0, y_start=ge_x2_0)
    ;
  Modelica.Blocks.Nonlinear.Limiter limiter1(uMax=0.1, uMin=-0.1) ;
  Modelica.Blocks.Math.Gain gain1(k=Kpllp/omega_0) ;
  Modelica.Blocks.Math.Cos cos1 ;
  Modelica.Blocks.Math.Sin sin1 ;
  Modelica.Blocks.Math.Product product1 ;
  Modelica.Blocks.Math.Product product2 ;
  Modelica.Blocks.Math.Add add1(k2=-1) ;
  Modelica.Blocks.Math.Gain gain2(k=1/Lpp) ;
  Modelica.Blocks.Math.Gain gain3(k=1/Lpp) ;
  Modelica.Blocks.Continuous.Integrator integrator2(k=1/0.01, y_start=ge_x0_0)
    ;
  Modelica.Blocks.Continuous.Integrator integrator3(k=1/0.01, y_start=ge_x1_0)
    ;
  Modelica.Blocks.Math.Add add2(k2=-1) ;
  Modelica.Blocks.Math.Add add3(k2=-1) ;
  Modelica.Blocks.Math.Gain gain4(k=-1/Lpp) ;
  Modelica.Blocks.Math.Add add4(k2=-1) ;
  Modelica.Blocks.Math.Product product3 ;
  Modelica.Blocks.Math.Product product4 ;
  Modelica.Blocks.Math.Product product5 ;
  Modelica.Blocks.Math.Product product6 ;
  Modelica.Blocks.Math.Add add5 ;
  Modelica.Blocks.Math.Add add6 ;
  Modelica.Blocks.Math.Add add7(k2=-1) ;
equation
  connect(integrator2.y, gain4.u) ;
  connect(gain4.y, product5.u1) ;
  connect(gain4.y, product3.u1) ;

  connect(add3.u1, Ipcmd) ;

  connect(Efd, add2.u1) ;
  connect(gain2.y, add6.u2) ;

  connect(add7.u1, add4.y) ;
  connect(gain3.y, add7.u2) ;
  connect(add6.u1, add5.y) ;
  connect(integrator3.y, product6.u1) ;

  connect(integrator3.y, product4.u1) ;
  connect(product3.u2, sin1.y) ;

  connect(product6.u2, sin1.y) ;

  connect(product1.y, add1.u1) ;

  connect(product2.y, add1.u2) ;

  connect(cos1.y, product1.u2) ;

  connect(sin1.y, product2.u1) ;

  connect(add1.y, gain1.u) ;
  connect(cos1.y, product4.u2) ;
  connect(cos1.y, product5.u2) ;
  connect(product4.y, add4.u1) ;

  connect(product3.y, add4.u2) ;

  connect(product5.y, add5.u1) ;

  connect(product6.y, add5.u2) ;

  connect(integrator1.y, sin1.u) ;
  connect(integrator1.y, cos1.u) ;

  connect(gain1.y, limiter1.u) ;
  connect(limiter1.y, integrator1.u) ;
  connect(integrator3.y, add3.u2) ;
  connect(integrator2.y, add2.u2) ;
  connect(add3.y, integrator3.u) ;

  connect(add2.y, integrator2.u) ;
  Vt_re = p.vr;
  Vt_im = p.vi;
  add7.y*GEN_base/SYS_base = -p.ir;
  add6.y*GEN_base/SYS_base = -p.ii;
  Vt = sqrt(Vt_re^2 + Vt_im^2);
  Anglet = atan(Vt_im/Vt_re);
  product1.u1 = Vt_im;
  product2.u2 = Vt_re;
  gain2.u = Vt_re;
  gain3.u = Vt_im;
  Pgen = Vt_re*add7.y + Vt_im*add6.y;
  Qgen = Vt_im*add7.y - Vt_re*add6.y
  ;
end Generator;

within OpenIPSL.Electrical.Wind.GE.Type_3.Turbine;
model Cp_function "Block for power coefficient (Cp) calculation"
  extends Modelica.Blocks.Icons.Block;
  Modelica.Blocks.Interfaces.RealInput Lambda "Lambda" ;
  Modelica.Blocks.Interfaces.RealInput Theta "Pitch angle" ;
  Modelica.Blocks.Interfaces.RealOutput y "Cp" ;
protected
  Modelica.Blocks.Math.MatrixGain matrixGain1(K=[-0.41909, 0.21808, -0.012406,
        -0.00013365, 0.000011524; -0.067606, 0.060405, -0.013934, 0.0010683, -0.000023895;
        0.015727, -0.010996, 0.0021495, -0.00014855, 0.0000027937; -0.00086018,
        0.00057051, -0.00010479, 0.0000059924, -0.000000089194; 0.000014788, -0.0000094839,
        0.0000016167, -0.000000071535, 0.00000000049686]) ;
  Multi_Powers multi_Powers1 ;
  Multi_Powers multi_Powers2 ;
equation
  connect(Theta, multi_Powers2.u1) ;
  connect(Lambda, multi_Powers1.u1) ;
  connect(multi_Powers1.y[1], matrixGain1.u[1]) ;
  connect(multi_Powers1.y[2], matrixGain1.u[2]);
  connect(multi_Powers1.y[3], matrixGain1.u[3]);
  connect(multi_Powers1.y[4], matrixGain1.u[4]);
  connect(multi_Powers1.y[5], matrixGain1.u[5]);
  y = matrixGain1.y[1]*multi_Powers2.y[1] + matrixGain1.y[2]*multi_Powers2.y[2]
     + matrixGain1.y[3]*multi_Powers2.y[3] + matrixGain1.y[4]*multi_Powers2.y[4]
     + matrixGain1.y[5]*multi_Powers2.y[5]
  ;
end Cp_function;

within OpenIPSL.Electrical.Wind.GE.Type_3.Turbine;
block Multi_Powers "Multiplexer block for four input connectors"
