  [y] = [1; u1; u2; u3; u4]
  ;
end Multi_Powers;

within OpenIPSL.Electrical.Wind.GE.Type_3.Turbine;
model Rotor_Model "Model with wind machine's rotor equations"
  Modelica.Blocks.Interfaces.RealInput Pm "Mechanical Power Input" ;
  Modelica.Blocks.Interfaces.RealInput Pe "Electrical Power Input" ;
  Modelica.Blocks.Interfaces.RealOutput omega_gen
    "Engine shaft angular velocity" ;
  Modelica.Blocks.Interfaces.RealOutput omega_turb
    "engine shaft angular velocity" ;
  parameter Types.Time H=0.3 "inertia";
  parameter Types.Time Hg=0.3;
  parameter Real wbase=1;
  parameter Real Dtg=1;
  parameter Real Ktg=1;
  parameter Types.PerUnit wt_x6_0=1;
  parameter Types.PerUnit wt_x7_0=1;
  parameter Types.PerUnit wt_x8_0=1;
  parameter Types.PerUnit wt_x9_0=1;
  parameter Real wndtge_ang0=1;
  parameter Real wndtge_spd0=1;
protected
  Modelica.Blocks.Continuous.Integrator integrator1(y_start=wt_x6_0)
    ;
  Modelica.Blocks.Continuous.Integrator integrator2(y_start=wt_x8_0)
    ;
  Modelica.Blocks.Continuous.Integrator integrator3(y_start=wt_x7_0)
    ;
  Modelica.Blocks.Continuous.Integrator integrator4(y_start=wt_x9_0)
    ;
  Modelica.Blocks.Math.Add3 add31 ;
  Modelica.Blocks.Math.Division division1 ;
  Modelica.Blocks.Math.Division division2 ;
  Modelica.Blocks.Math.Add3 add32(
    k1=-1,
    k2=-1,
    k3=-1) ;
  Modelica.Blocks.Math.Gain i2H(k=1/(2*H)) ;
  Modelica.Blocks.Math.Gain Gain_i2Hg(k=1/(2*Hg)) ;
  Modelica.Blocks.Math.Gain Gain1_wbase(k=wbase) ;
  Modelica.Blocks.Math.Gain Gain_wbase(k=wbase) ;
  Modelica.Blocks.Math.Add add1(k1=-1) ;
  Modelica.Blocks.Math.Gain Gain_Dtg(k=Dtg) ;
  Modelica.Blocks.Math.Add add2(k1=-1) ;
  Modelica.Blocks.Math.Gain Gain_Ktg(k=Ktg) ;
  Modelica.Blocks.Math.Add add3 ;
  Modelica.Blocks.Math.Add add4 ;
  Modelica.Blocks.Math.Add add5 ;
  Modelica.Blocks.Sources.Constant Const1_wndtge_spd0(k=wndtge_spd0)
    ;
  Modelica.Blocks.Sources.Constant Const_wndtge_spd0(k=wndtge_spd0) ;
  Modelica.Blocks.Sources.Constant Const_wndtge_ang0(k=wndtge_ang0) ;
equation
  connect(Const_wndtge_spd0.y, add5.u1) ;
  connect(Const1_wndtge_spd0.y, add4.u2) ;
  connect(omega_gen, add4.y) ;
  connect(omega_turb, add5.y) ;
  connect(Const_wndtge_ang0.y, add3.u1) ;

  connect(Pe, division2.u1) ;

  connect(Pm, division1.u1) ;
  connect(integrator2.y, Gain_wbase.u) ;

  connect(Gain_wbase.y, integrator4.u) ;

  connect(integrator1.y, Gain1_wbase.u) ;

  connect(Gain1_wbase.y, integrator3.u) ;

  connect(Gain_Ktg.y, add31.u1) ;
  connect(Gain_Ktg.y, add32.u3) ;
  connect(add2.y, Gain_Ktg.u) ;
  connect(add32.y, Gain_i2Hg.u) ;
  connect(Gain_i2Hg.y, integrator2.u) ;
  connect(add1.y, Gain_Dtg.u) ;
  connect(Gain_Dtg.y, add32.u1) ;
  connect(Gain_Dtg.y, add31.u3) ;
  connect(i2H.y, integrator1.u) ;
  connect(add31.y, i2H.u) ;

  connect(integrator2.y, add4.u1) ;

  connect(add5.u2, integrator1.y) ;

  connect(add1.u1, integrator1.y) ;
  connect(add1.u2, integrator2.y) ;
  connect(add3.u2, integrator4.y) ;

  connect(add3.y, add2.u2) ;
  connect(integrator3.y, add2.u1) ;

  connect(division2.u2, add4.y) ;

  connect(division1.u2, add5.y) ;
  connect(division2.y, add32.u2) ;
  connect(division1.y, add31.u2) 

  ;
end Rotor_Model;

within OpenIPSL.Electrical.Wind.GE.Type_3.Turbine;
model Turbine_Model "Type 3 wind turbine model"
  parameter Types.ApparentPower GEN_base=1000000;
  parameter Types.ApparentPower WT_base=1000000;
  parameter Real Kpp=1;
  parameter Real Kip=1;
  parameter Types.TimeAging pirat=1;
  parameter Types.Angle pimax=1;
  parameter Types.Angle pimin=1;
  parameter Types.TimeAging pwrat=1;
  parameter Types.PerUnit pwmax=1;
  parameter Types.PerUnit pwmin=1;
  parameter Real Kic=1;
  parameter Real Kpc=1;
  parameter Types.Time Tp=1;
  parameter Types.Time Tpc=1;
  parameter Real Kptrq=1;
  parameter Real Kitrq=1;
  parameter Real Dtg=1;
  parameter Types.Time H=1;
  parameter Types.Time Hg=1;
  parameter Real Ktg=1;
  parameter Real KI=1;
  parameter Real wndtge_kp=1;
  parameter Types.PerUnit wt_x0_0=1;
  parameter Types.PerUnit wt_x1_0=1;
  parameter Types.PerUnit wt_x2_0=1;
  parameter Types.PerUnit wt_x3_0=1;
  parameter Types.PerUnit wt_x4_0=1;
  parameter Types.PerUnit wt_x5_0=1;
  parameter Types.PerUnit wt_x6_0=1;
  parameter Types.PerUnit wt_x7_0=1;
  parameter Types.PerUnit wt_x8_0=1;
  parameter Types.PerUnit wt_x9_0=1;
  parameter Real wbase=1;
  parameter Real wndtge_ang0=1;
  parameter Real wndtge_spd0=1;
  Modelica.Blocks.Interfaces.RealInput Pelec "Electrical power" ;
  Modelica.Blocks.Interfaces.RealInput Wind_Speed "Wind speed" ;
  Modelica.Blocks.Interfaces.RealOutput Pord "Active power command" ;
  Rotor_Model rotor_Model1(
    wt_x6_0=wt_x6_0,
    wt_x7_0=wt_x7_0,
    wt_x8_0=wt_x8_0,
    wt_x9_0=wt_x9_0,
    Dtg=Dtg,
    H=H,
    Hg=Hg,
    Ktg=Ktg,
    wbase=wbase,
    wndtge_ang0=wndtge_ang0,
    wndtge_spd0=wndtge_spd0) ;
  Wind_Power_Model wind_Power_Model1(KI=KI, wndtge_kp=wndtge_kp) ;
protected
  Boolean thlim1(start=true);
  Boolean pwlim2(start=true);
  Modelica.Blocks.Math.Gain Change_Base(k=GEN_base/WT_base) ;
  Modelica.Blocks.Math.Add add1(k2=-1) ;
  Modelica.Blocks.Continuous.Integrator integrator1(k=1/5, y_start=wt_x5_0)
    ;
  Modelica.Blocks.Math.Add add2(k1=-1) ;
  Modelica.Blocks.Math.Gain Gain_Kpp(k=Kpp) ;
  Modelica.Blocks.Continuous.Integrator integrator2(k=Kip, y_start=wt_x1_0)
    ;
  Modelica.Blocks.Math.Add3 add31 ;
  Modelica.Blocks.Continuous.Integrator integrator3(k=Kic, y_start=wt_x3_0)
    ;
  Modelica.Blocks.Math.Add add3 ;
  Modelica.Blocks.Math.Gain Gain_Kpc(k=Kpc) ;
  Modelica.Blocks.Math.Add add4(k1=-1) ;
  Modelica.Blocks.Math.Add add5(k2=-1) ;
  Modelica.Blocks.Math.Gain Gain_iTP(k=1/Tp) ;
  Modelica.Blocks.Nonlinear.Limiter limiter1(uMax=pirat) ;
  Modelica.Blocks.Continuous.LimIntegrator limIntegrator1(
    y_start=wt_x0_0,
    outMax=pimax,
    outMin=pimin,
    initType=Modelica.Blocks.Types.Init.InitialOutput) ;
  Modelica.Blocks.Math.Gain Gain_Kptrq(k=Kptrq) ;
  Modelica.Blocks.Math.Add add6 ;
  Modelica.Blocks.Continuous.Integrator integrator4(k=Kitrq, y_start=wt_x2_0)
    ;
  Modelica.Blocks.Math.Product product1 ;
  Modelica.Blocks.Continuous.LimIntegrator limIntegrator2(
    outMax=pwmax,
    outMin=pwmin,
    y_start=wt_x4_0) ;
  Modelica.Blocks.Nonlinear.Limiter limiter2(uMax=pwrat) ;
  Modelica.Blocks.Math.Gain Gain_iTPc(k=1/Tpc) ;
  Modelica.Blocks.Math.Add add8(k2=-1) ;
  Modelica.Blocks.Math.Gain Change_Base1(k=WT_base/GEN_base) ;
  Modelica.Blocks.Sources.Constant const(k=1) ;
equation
  connect(Pelec, Change_Base.u) ;
  connect(Wind_Speed, wind_Power_Model1.Wind_Speed) ;

  connect(integrator1.y, add2.u1) ;

  connect(add1.u2, integrator1.y) ;
  connect(add1.y, integrator1.u) ;
  connect(Change_Base1.y, Pord) ;
  connect(const.y, add4.u1) ;

  connect(add4.u2, limIntegrator2.y) ;
  connect(limIntegrator2.y, Change_Base1.u) ;
  connect(add8.y, Gain_iTPc.u) ;
  connect(add5.y, Gain_iTP.u) ;
  connect(Gain_iTPc.y, limiter2.u) ;
  connect(product1.y, add8.u1) ;

  connect(limIntegrator2.y, add8.u2) ;
  connect(limiter2.y, limIntegrator2.u) ;
  connect(integrator4.y, add6.u2) ;

  connect(add31.u2, integrator2.y) ;

  connect(add3.y, add31.u3) ;
  connect(add2.y, Gain_Kptrq.u) ;
  connect(rotor_Model1.omega_gen, product1.u1) ;
  connect(add6.y, product1.u2) ;
  connect(Gain_Kptrq.y, add6.u1) ;

  connect(wind_Power_Model1.Theta, limIntegrator1.y) ;
  connect(limIntegrator1.y, add5.u2) ;
  connect(limiter1.y, limIntegrator1.u) ;
  connect(Gain_iTP.y, limiter1.u) ;
  connect(add31.y, add5.u1) ;
  connect(integrator3.y, add3.u2) ;

  connect(add4.y, Gain_Kpc.u) ;
  connect(Gain_Kpc.y, add3.u1) ;
  connect(Gain_Kpp.y, add31.u1) ;

  connect(add2.y, Gain_Kpp.u) ;

  connect(Change_Base.y, rotor_Model1.Pe) ;
  connect(rotor_Model1.omega_gen, add2.u2) ;
  connect(wind_Power_Model1.Pm, rotor_Model1.Pm) ;
  connect(rotor_Model1.omega_turb, wind_Power_Model1.omega) ;
  add1.u1 = if Change_Base.y >= 0.75 then 1.2 else ((-0.67*Change_Base.y) +
    1.42)*Change_Base.y + 0.51;
  integrator2.u = if thlim1 then add2.y else 0;
  integrator3.u = if thlim1 then add4.y else 0;
  integrator4.u = if pwlim2 then add2.y else 0;
  thlim1 = not (limIntegrator1.y <= pimin + C.eps and limiter1.y < 0);
  pwlim2 = not (limIntegrator2.y >= pwmax and limiter2.y > 0)
  ;
end Turbine_Model;

within OpenIPSL.Electrical.Wind.GE.Type_3.Turbine;
model Wind_Power_Model "Model for wind power in a type 3 machine"
  Modelica.Blocks.Interfaces.RealInput Wind_Speed "Wind speed" ;
  Modelica.Blocks.Interfaces.RealInput Theta "Pitch angle" ;
  Modelica.Blocks.Interfaces.RealInput omega "Turbine speed" ;
  Modelica.Blocks.Interfaces.RealOutput Pm "Mechanical power" ;
  import Modelica.Constants.inf;
  parameter Real KI=1;
  parameter Real wndtge_kp=1;
protected
  Modelica.Blocks.Nonlinear.Limiter limiter1(uMax=inf, uMin=0.1) ;
  Modelica.Blocks.Math.Division division1 ;
  Modelica.Blocks.Math.Gain Gain_KI(k=KI) ;
  Modelica.Blocks.Nonlinear.Limiter limiter2(uMax=inf, uMin=0.1) ;
  Modelica.Blocks.Math.Gain Gain_wndtge_kp(k=wndtge_kp) ;
  Modelica.Blocks.Math.Product product2 ;
  Modelica.Blocks.Math.Product product3 ;
  Modelica.Blocks.Math.Product product4 ;
  Cp_function cp_function1 ;
equation
  connect(limiter1.y, division1.u2) ;
  connect(Wind_Speed, limiter1.u) ;
  connect(omega, division1.u1) ;
  connect(division1.y, Gain_KI.u) ;
  connect(Wind_Speed, product2.u1) ;
  connect(Wind_Speed, product3.u1) ;

  connect(Wind_Speed, product3.u2) ;

  connect(Theta, cp_function1.Theta) ;
  connect(product4.y, Gain_wndtge_kp.u) ;

  connect(Gain_wndtge_kp.y, Pm) ;
  connect(product2.y, product4.u2) ;
  connect(cp_function1.y, product4.u1) ;
  connect(limiter2.y, cp_function1.Lambda) ;

  connect(Gain_KI.y, limiter2.u) ;

  connect(product3.y, product2.u2) 

  ;
end Wind_Power_Model;

within OpenIPSL.Electrical.Wind.PSAT.PSAT_Type_3;
model ElecBlk "Electrical block for Type 3 wind machine"
  Modelica.Blocks.Interfaces.RealInput omega_m "Rotor Speed" ;
  Modelica.Blocks.Interfaces.RealInput idr(start=idr0, fixed=false) "idr"
    ;
  Modelica.Blocks.Interfaces.RealInput iqr(start=iqr0, fixed=false) "iqr"
    ;
  Modelica.Blocks.Interfaces.RealOutput Tel "Electrical Torque" ;
  Modelica.Blocks.Interfaces.RealOutput Vbus "Bus Voltage Magnitude"
    ;
  parameter Types.ApparentPower Sbase=100000000 "Power Rating [Normalization Factor]";
  parameter Types.PerUnit Vbus0=1 "Voltage from Power Flow";
  parameter Types.Angle angle_0=-0.00243 "Angle from Power Flow";
  parameter Types.PerUnit Pc=0.0160000000000082 "Active Power, PowerFlow";
  parameter Types.PerUnit Qc=0.030527374471207 "Reactive Power, Power Flow";
  parameter Types.PerUnit omega_m0=min(max(0.5*Pc*Sbase/Pnom + 0.5, 0.5), 1);
  parameter Types.ApparentPower Pnom=10 "Nominal Power";
  parameter Types.Voltage Vbase=400000 "Voltage rating";
  parameter Types.Frequency freq=50 "frequency rating";
  parameter Types.PerUnit Rs=0.1 "stator Resistance";
  parameter Types.PerUnit Xs=1 "stator Reactance";
  parameter Types.PerUnit Rr=0.1 "Rotor Resitance";
  parameter Types.PerUnit Xr=0.8 "rotor Reactance";
  parameter Types.PerUnit Xm=30 "magnetisation reactance";
  parameter Types.Time Hm=0.3 "inertia";
  parameter Types.PerUnit x1=Xm + Xs "stator plus magnetisation impedances";
  parameter SI.AngularVelocity wbase=2*C.pi*freq/poles "basis for angular speed";
  parameter Real k=x1*Pnom/Vbus0/Xm/Sbase "gain for iqr_off computation";
  parameter Types.PerUnit ids0=((-vds0^2) + vds0*Xm*iqr0 - x1*Qc)/(Rs*vds0 - x1*vqs0);
  parameter Types.PerUnit iqs0=((-vds0*vqs0) + vqs0*Xm*iqr0 - Rs*Qc)/(Rs*vds0 - x1*vqs0);
  parameter Types.PerUnit idr0=-(vqs0 + Rs*iqs0 + x1*ids0)/Xm;
  parameter Types.PerUnit iqr0=-x1*Pnom*(2*omega_m0 - 1)/Vbus0/Xm/Sbase/omega_m0;
  parameter Types.PerUnit vds0=-Vbus0*sin(angle_0);
  parameter Types.PerUnit vqs0=Vbus0*cos(angle_0);
  parameter Types.PerUnit vdr0=(-Rr*idr0) + (1 - omega_m0)*((Xm + Xr)*iqr0 + Xm*iqs0);
  parameter Types.PerUnit vqr0=(-Rr*iqr0) - (1 - omega_m0)*((Xm + Xr)*idr0 + Xm*ids0);
  parameter Integer poles=2 "Number of poles-pair";
  Types.PerUnit vds(start=vds0, fixed=false) "stator tension, in dq";
  Types.PerUnit vqs(start=vqs0, fixed=false) "stator tension, in dq";
  Types.PerUnit p "Active power";
  Types.PerUnit q "Reactive Power";
  Types.PerUnit ids(start=ids0, fixed=false) "stator current, in dq";
  Types.PerUnit iqs(start=iqs0, fixed=false) "stator current, in dq";
  Types.PerUnit vdr(start=vdr0, fixed=false) "rotor voltage in dq";
  Types.PerUnit vqr(start=vqr0, fixed=false) "rotor voltage in dq";
  OpenIPSL.Interfaces.PwPin pin ;
  Real slip;
  Types.Angle Anglebus=atan(pin.vi/pin.vr);
  parameter Types.TimeAging i2Hm=1/(2*Hm) "inverse inertia";
equation
  Vbus = sqrt(vds^2 + vqs^2);
  vqs = pin.vr;
  vds = -pin.vi;
  -p = pin.vr*pin.ir + pin.vi*pin.ii;
  -q = pin.vi*pin.ir - pin.vr*pin.ii;
  p = vds*ids + vqs*iqs + vdr*idr + vqr*iqr;
  q = (-Xm*Vbus*idr/x1) - Vbus^2/Xm;
  vds = (-Rs*ids) + x1*iqs + Xm*iqr;
  vqs = (-Rs*iqs) - x1*ids - Xm*idr;
  slip = 1 - omega_m;
  vdr = (-Rr*idr) + slip*(x1*iqr + Xm*iqs);
  vqr = (-Rr*iqr) - slip*(x1*idr + Xm*ids);
  Tel = Xm*(iqr*ids - idr*iqs)
  ;
end ElecBlk;

within OpenIPSL.Electrical.Wind.PSAT.PSAT_Type_3;
model ElecDynBlk "Dynamical equations for electrical block of a type 3 wind machine"
  Modelica.Blocks.Interfaces.RealInput omega_m "Rotor Speed" ;
  Modelica.Blocks.Interfaces.RealInput Vbus "Vbus" ;
  Modelica.Blocks.Interfaces.RealOutput idr(start=idr0, fixed=false)
    "saturated idr" ;
  Modelica.Blocks.Interfaces.RealOutput iqr(start=iqr0, fixed=false)
    "saturated iqr" ;
  parameter Types.ApparentPower Sbase=100000000 "Power Rating [Normalization Factor]";
  parameter Types.PerUnit Vbus0=1 "Voltage from Power Flow";
  parameter Types.Angle angle_0=-0.00243 "Angle from Power Flow";
  parameter Types.PerUnit Pc=0.0160000000000082 "Active Power, PowerFlow";
  parameter Types.PerUnit Qc=0.030527374471207 "Reactive Power, Power Flow";
  parameter Types.PerUnit omega_m0=min(max(0.5*Pc*Sbase/Pnom + 0.5, 0.5), 1);
  parameter Types.ApparentPower Pnom=10 "Nominal Power";
  parameter Types.Voltage Vbase=400000 "Voltage rating";
  parameter Types.Frequency freq=50 "frequency rating";
  parameter Types.PerUnit Rs=0.1 "stator Resistance";
  parameter Types.PerUnit Xs=1 "stator Reactance";
  parameter Types.PerUnit Rr=0.1 "Rotor Resitance";
  parameter Types.PerUnit Xr=0.8 "rotor Reactance";
  parameter Types.PerUnit Xm=30 "magnetisation reactance";
  parameter Types.Time Hm=0.3 "inertia";
  parameter Types.PerUnit x1=Xm + Xs "stator plus magnetisation impedances";
  parameter Types.PerUnit x2=Xm + Xr "rotor plus magnetisation impedances";
  parameter SI.AngularVelocity wbase=2*C.pi*freq/poles "basis for angular speed";
  parameter Types.PerUnit iqr_max;
  parameter Types.PerUnit idr_max;
  parameter Types.PerUnit iqr_min;
  parameter Types.PerUnit idr_min;
  parameter Integer poles=2 "Number of poles-pair";
  parameter Real Kv=10 "Voltage control gain";
  parameter Types.Time Te=0.01 "Power Control time constant";
  parameter Real k=x1*Pnom/Vbus0/Xm/Sbase "gain for iqr_off computation";
  parameter Types.PerUnit ids0=((-vds0^2) + vds0*Xm*iqr0 - x1*Qc)/(Rs*vds0 - x1*vqs0);
  parameter Types.PerUnit iqs0=((-vds0*vqs0) + vqs0*Xm*iqr0 - Rs*Qc)/(Rs*vds0 - x1*vqs0);
  parameter Types.PerUnit idr0=-(vqs0 + Rs*iqs0 + x1*ids0)/Xm;
  parameter Types.PerUnit iqr0=-x1*Pnom*(2*omega_m0 - 1)/Vbus0/Xm/Sbase/omega_m0;
  parameter Types.PerUnit vds0=-Vbus0*sin(angle_0);
  parameter Types.PerUnit vqs0=Vbus0*cos(angle_0);
  parameter Types.PerUnit vdr0=(-Rr*idr0) + (1 - omega_m0)*(x2*iqr0 + Xm*iqs0);
  parameter Types.PerUnit vqr0=(-Rr*iqr0) - (1 - omega_m0)*(x2*idr0 + Xm*ids0);
  Types.PerUnit idrI "internal, non saturated idr";
  Types.PerUnit iqrI "internal, non saturated iqr";
  Types.PerUnit Vref;
  Types.PerUnit iqr_off;
  Types.PerUnit pwa;
  parameter Types.TimeAging i2Hm=1/(2*Hm) "inverse inertia";
protected
  parameter Types.Time Tdmy = 1 "dummy time constant";
initial equation
  0 = ((-(Xs + Xm)*pwa/Vbus/Xm/omega_m) - iqr - iqr_off);
  Vref = Vbus0 - (idrI + Vbus0/Xm)/Kv;
  iqr_off = (-k*max(min(2*omega_m0 - 1, 1), 0)/omega_m0) - iqrI;
equation
  der(Vref) = 0;
  der(iqr_off) = 0;
  pwa = max(min(2*omega_m - 1, 1), 0)*Pnom/Sbase;
  der(iqrI) = ((-(Xs + Xm)*pwa/Vbus/Xm/omega_m) - iqr - iqr_off)/Te;
  der(idrI) = (Kv*(Vbus - Vref) - Vbus/Xm - idr)/Tdmy;
  iqr = min(max(iqrI, iqr_min), iqr_max);
  idr = min(max(idrI, idr_min), idr_max);
  when iqrI > iqr_max and der(iqrI) < 0 then
    reinit(iqrI, iqr_max);
  elsewhen iqrI < iqr_min and der(iqrI) > 0 then
    reinit(iqrI, iqr_min);
  end when;
  when idrI > idr_max and der(idrI) < 0 then
    reinit(idrI, idr_max);
  elsewhen idrI < idr_min and der(idrI) > 0 then
    reinit(idrI, idr_min);
  end when
  ;
end ElecDynBlk;

within OpenIPSL.Electrical.Wind.PSAT.PSAT_Type_3;
model MechaBlk "Mechanical block for Type 3 wind machine model"
  Modelica.Blocks.Interfaces.RealInput Tm "engine shaft torque" ;
  Modelica.Blocks.Interfaces.RealInput Tel "electromagnetical torque"
    ;
  Modelica.Blocks.Interfaces.RealOutput omega_m "engine shaft angular velocity"
    ;
  parameter Types.ApparentPower Sbase=100000000 "Power Rating [Normalization Factor]";
  parameter Types.ApparentPower Pnom=10000000 "Nominal Power";
  parameter Types.Time Hm=0.3 "inertia";
  parameter Types.PerUnit Pc=0.016 "Input Power Flow";
initial equation
  if Pc < Pnom/Sbase and Pc > 0 then
    omega_m = 0.5*Pc*Sbase/Pnom + 0.5;
  elseif Pc*Sbase >= Pnom then
    omega_m = 1;
  else
    omega_m = 0.5;
  end if;
  Tel = Tm;
equation
  der(omega_m) = (Tm - Tel)/(2*Hm)
  ;
end MechaBlk;

within OpenIPSL.Electrical.Wind.PSAT.PSAT_Type_3;
model PitchControl "Pitch control block for Type 3 wind machine model"
  Modelica.Blocks.Interfaces.RealInput omega_m "Real voltage" ;
  Modelica.Blocks.Interfaces.RealOutput theta_p(start=theta_p0)
    "saturated theta_p" ;
  parameter Real Kp=10 "Pitch control gain";
  parameter Types.Time Tp=3 "Pitch control time constant";
  parameter Types.Angle theta_p0=0;
  parameter Types.Angle theta_p_min;
  parameter Types.Angle theta_p_max;
  Real theta_pI "internal non-saturated theta_p";
  Types.Angle phi;
initial equation
  (Kp*phi - theta_pI)/Tp = 0;
equation
  theta_p = min(max(theta_pI, theta_p_min), theta_p_max);
  phi = ceil(0.5*floor(1000*(omega_m - 1)*2))/1000;
  der(theta_pI) = (Kp*phi - theta_p)/Tp;
  when theta_pI > theta_p_max and der(theta_pI) < 0 then
    reinit(theta_pI, theta_p_max);
  elsewhen theta_pI < theta_p_min and der(theta_pI) > 0 then
    reinit(theta_pI, theta_p_min);
  end when
  ;
end PitchControl;

