within OpenIPSL.Electrical.Wind.PSAT.PSAT_Type_3;
model WindBlk "Wind block for Type 3 wind machine model"
  import Modelica.Constants.pi;
  Modelica.Blocks.Interfaces.RealInput vw "Real voltage" ;
  Modelica.Blocks.Interfaces.RealInput theta_p "Pitch angle" ;
  Modelica.Blocks.Interfaces.RealInput omega_m "Mechanical speed" ;
  Modelica.Blocks.Interfaces.RealOutput Tm "Mechanical torque" ;
  parameter SI.Velocity vw_base=15 "Vw Nominal";
  parameter SI.Density rho=1.225 "Air Density";
  parameter Types.ApparentPower Sbase=100000000 "Power Rating [Normalization Factor]";
  parameter SI.Length l=75 "Blade length";
  parameter Real ngb=0.01123596 "gear box ratio";
  parameter Real Radapt=ngb*l "r_{gearbox}*r";
  parameter Integer poles=2 "Number of poles-pair";
  parameter Types.Frequency freq=50 "frequency rating";
  parameter SI.AngularVelocity wbase=2*pi*freq;
  parameter SI.Area Ar=pi*l^2 "blades area";
  Real lambda "Tip speed Ratio";
  Real lambdai "Tip Speed Ratio optimal";
  Real cp "Capacity coefficient";
  Types.ApparentPower Pw "Power in the Wind";
equation
  lambda = omega_m*wbase*Radapt/(vw*vw_base);
  lambdai = 1/(1/(lambda + 0.08*theta_p) - 0.035/(theta_p^3 + 1));
  cp = 0.22*(116/lambdai - 0.4*theta_p - 5)*exp(-12.5/lambdai);
  Pw = 0.5*rho*cp*Ar*(vw*vw_base)^3/(Sbase);
  Tm = Pw/omega_m
  ;
end WindBlk;

within OpenIPSL.Electrical.Wind.PSSE.Submodels;
model CCL "Model for calculation of converter current limits"
  parameter Types.PerUnit Qmax;
  parameter Boolean pqflag;
  parameter Types.PerUnit ImaxTD "Converter current limit";
  parameter Types.PerUnit Iphl "Hard active current limit";
  parameter Types.PerUnit Iqhl "Hard reactive current limit";
  Modelica.Blocks.Interfaces.RealOutput IQmin ;
  Modelica.Blocks.Interfaces.RealInput IpCMD ;
  Modelica.Blocks.Interfaces.RealInput IqCMD ;
  Modelica.Blocks.Interfaces.RealOutput IQmax ;
  Modelica.Blocks.Interfaces.RealOutput IPmax ;
  Modelica.Blocks.Math.Min min1 ;
  Modelica.Blocks.Sources.Constant const1(k=Iphl) ;
  Modelica.Blocks.Sources.Constant const2(k=Iqhl) ;
  Modelica.Blocks.Math.Min min2 ;
  Modelica.Blocks.Math.Min min3 ;
  Modelica.Blocks.Math.Min min4 ;
  Modelica.Blocks.Math.Min min5 ;
  Modelica.Blocks.Math.Gain gain(k=-1) ;
  Modelica.Blocks.Math.Gain gain1(k=-1) ;
  Modelica.Blocks.Interfaces.RealInput Vt ;
  Modelica.Blocks.Sources.Constant const3(k=ImaxTD)
                                                  ;
  Modelica.Blocks.Sources.Constant const4(k=ImaxTD)
                                                  ;
protected
  Modelica.Blocks.Interfaces.RealInput Iqmax ;
protected
  Modelica.Blocks.Interfaces.RealOutput IQmin1 ;
  Modelica.Blocks.Interfaces.RealOutput IQmax1 ;
  Modelica.Blocks.Interfaces.RealOutput IQmin2 ;
  Modelica.Blocks.Interfaces.RealOutput IQmax2 ;
  Modelica.Blocks.Interfaces.RealOutput IPmax1 ;
  Modelica.Blocks.Interfaces.RealOutput IPmax2 ;
  Modelica.Blocks.Interfaces.RealInput Available_remain1
    "sqrt(ImaxTD^2 - IpCMD^2)" ;
  Modelica.Blocks.Interfaces.RealInput Available_remain2
    "sqrt(ImaxTD^2 - IqCMD^2)" ;
equation
  Available_remain1 = sqrt(ImaxTD^2 - IpCMD^2);
  Available_remain2 = sqrt(ImaxTD^2 - IqCMD^2);
  Iqmax = (Qmax - 1.6)*(Vt - 1) + Qmax;
  if pqflag then
    IQmin = IQmin1;
    IQmax = IQmax1;
    IPmax = IPmax1;
  else
    IQmin = IQmin2;
    IQmax = IQmax2;
    IPmax = IPmax2;
  end if;
  connect(const1.y, min1.u2) ;
  connect(const1.y, min3.u1) ;
  connect(const2.y, min5.u1) ;
  connect(min5.y, min4.u2) ;
  connect(min2.u1, min5.y) ;
  connect(min2.y, IQmax2) ;
  connect(min1.y, IPmax2) ;
  connect(min3.y, IPmax1) ;
  connect(gain.u, min2.y) ;
  connect(gain.y, IQmin2) ;
  connect(gain1.u, min4.y) ;
  connect(Iqmax, min5.u2) ;
  connect(min1.u1, Available_remain2) ;
  connect(const3.y, min2.u2) ;
  connect(const4.y, min3.u2) ;
  connect(Available_remain1, min4.u1) ;
  connect(gain1.y, IQmin1)
    ;
  connect(IQmax1, min4.y) 
  ;
end CCL;

within OpenIPSL.Electrical.Wind.PSSE.Submodels;
model HVRCL "Model for the High Voltage Ractive Current Limiter"
  //The 'High Voltage Reactive Current Management' block limits the reactive current injected into the network equations such that the terminal voltage of the machine never exceeds Volim of nominal, as long as the converter is within current limits."
  parameter Types.PerUnit VHVRCR "Threshold voltage for HVRCL";
  parameter Types.PerUnit CurHVRCR "Max. reactive current at VHVRCR";
  Modelica.Blocks.Interfaces.RealInput Vt ;
  Modelica.Blocks.Interfaces.RealOutput Iq_HVRCL ;
  Modelica.Blocks.Interfaces.RealInput Iq ;
equation
  if Vt > VHVRCR then
    Iq_HVRCL = CurHVRCR;
  else
    Iq_HVRCL = Iq;
  end if
  ;
end HVRCL;

within OpenIPSL.Electrical.Wind.PSSE.Submodels;
model LVACL "Model for the Low Voltage Active Current Limiter"
  //The Low Voltage Active Current Management block is designed to capture the characteristic
  //of active power under very low voltage scenarios. This low voltage limit is designed to reduce active current in a linear fashion.
  // The protection function is activated when
  //the terminal voltage drops below 0.8 pu and strangling power completely if the terminal voltage is lower than
  //0.4 pu. For voltages between 0.8 pu and 0.4 pu to reduce the active power is linear according to equation
  Modelica.Blocks.Interfaces.RealOutput Ip_LVACL ;
  Modelica.Blocks.Interfaces.RealInput Vt ;
  Modelica.Blocks.Interfaces.RealInput Ip_LVPL ;
equation
  if Vt < 0.4 then
    Ip_LVACL = 0;
  elseif Vt > 0.8 then
    Ip_LVACL = Ip_LVPL;
  else
    Ip_LVACL = Ip_LVPL*1.25*Vt;
  end if
  ;
end LVACL;

within OpenIPSL.Electrical.Wind.PSSE.Submodels;
model LVPL "Low voltage power logic"
  parameter Types.PerUnit VLVPL1 "LVPL voltage 1 (Low voltage power logic)";
  parameter Types.PerUnit VLVPL2 "LVPL voltage 2";
  parameter Real GLVPL "LVPL gain";
  parameter Real K=GLVPL/(VLVPL2 - VLVPL1);
  Modelica.Blocks.Interfaces.RealInput Vt ;
  Modelica.Blocks.Interfaces.RealOutput LVPL ;
equation
  if Vt < VLVPL1 then
    LVPL = 0;
  elseif Vt > VLVPL2 then
    LVPL = 1e+6;
  else
    LVPL = K*(Vt - VLVPL1);
  end if
  ;
end LVPL;

within OpenIPSL.Electrical.Wind.PSSE.WT3G;
model WT3G1 "Wind Machine Model with DFIG and Ative Power Control done by a Converter (Type 3)"
  extends OpenIPSL.Electrical.Essentials.pfComponent;
  parameter Types.PerUnit X_eq "Equivalent reactance for current injection";
  parameter Types.PerUnit K_pll "PLL first integrator gain";
  parameter Types.TimeAging K_ipll "PLL second integrator gain";
  parameter Types.PerUnit P_llmax "PLL maximum limit";
  parameter Types.Power P_rated "Turbine rating, not used in the equation";
  parameter Complex Zs(re=0, im=X_eq) "Equivalent impedance (ZSORCE)"
    ;
  parameter Types.ApparentPower M_b=100 "Machine base power"
    ;
  Types.PerUnit VT(start=v_0) "Bus voltage magnitude";
  Types.Angle anglev(start=angle_0) "Bus voltage angle";
  Types.PerUnit VY(start=0) "y-axis terminal voltage";
  Types.PerUnit VX(start=v_0) "x-axis terminal voltage";
  Complex Is "Equivalent internal current source";
  OpenIPSL.Interfaces.PwPin p(
    vr(start=vr0),
    vi(start=vi0),
    ir(start=ir1),
    ii(start=ii1)) ;
  Modelica.Blocks.Continuous.Integrator imIntegrator(
    k=wbase,
    y_start=angle_0,
    initType=Modelica.Blocks.Types.Init.InitialOutput)
    ;
  Modelica.Blocks.Continuous.LimIntegrator imIntegrator1(
    outMin=-P_llmax,
    outMax=P_llmax,
    y_start=0,
    initType=Modelica.Blocks.Types.Init.InitialOutput,
    k=K_ipll) ;
  OpenIPSL.NonElectrical.Continuous.SimpleLag imSimpleLag(
    K=1,
    T=0.02,
    y_start=Eqcmd0)
    ;
  OpenIPSL.NonElectrical.Continuous.SimpleLag imSimpleLag1(
    K=1,
    T=0.02,
    y_start=Ix0)
    ;
  Modelica.Blocks.Math.Gain imGain(k=-1/X_eq)
    ;
  Modelica.Blocks.Interfaces.RealOutput Iy(start=Iy0) ;
  Modelica.Blocks.Interfaces.RealOutput Ix(start=Ix0) ;
  Modelica.Blocks.Interfaces.RealOutput Iterm(start=Iy0) ;
  Modelica.Blocks.Interfaces.RealInput Eqcmd(start=Eqcmd0) ;
  Modelica.Blocks.Interfaces.RealInput Ipcmd(start=Ipcmd0) ;
  Modelica.Blocks.Math.Gain imGain1(k=K_pll/wbase)
    ;
  Modelica.Blocks.Math.Add add
    ;
  Modelica.Blocks.Nonlinear.Limiter imLimited(uMin=-P_llmax, uMax=P_llmax)
    ;
  Modelica.Blocks.Interfaces.RealOutput delta(start=angle_0) ;
  Modelica.Blocks.Interfaces.RealOutput V=VT ;
  Modelica.Blocks.Interfaces.RealOutput P "On machine base" ;
  Modelica.Blocks.Interfaces.RealOutput Q ;
  Modelica.Blocks.Interfaces.RealOutput ipcmd0=Ipcmd0 ;
  Modelica.Blocks.Interfaces.RealOutput eqcmd0=Eqcmd0 ;
protected
 parameter Types.AngularVelocity wbase=2*C.pi*fn "System base speed";
  parameter Types.PerUnit p0=P_0/M_b
    "initial value of bus active power in p.u. machinebase";
  parameter Types.PerUnit q0=Q_0/M_b
    "initial value of bus reactive power in p.u. machinebase";
  parameter Types.PerUnit vr0=v_0*cos(angle_0)
    "Real component of initial terminal voltage";
  parameter Types.PerUnit vi0=v_0*sin(angle_0)
    "Imaginary component of initial terminal voltage";
  parameter Types.PerUnit ir0=(p0*vr0 + q0*vi0)/(vr0^2 + vi0^2)
    "Real component of initial armature current, mbase";
  parameter Types.PerUnit ii0=(p0*vi0 - q0*vr0)/(vr0^2 + vi0^2)
    "Imaginary component of initial armature current, mbase";
  parameter Types.PerUnit Isr0=ir0 + vi0/X_eq "Source current re mbase";
  parameter Types.PerUnit Isi0=ii0 - vr0/X_eq "Source current im mbase";
  parameter Real CoB=M_b/S_b;
  parameter Types.PerUnit ir1=-CoB*(p0*vr0 + q0*vi0)/(vr0^2 + vi0^2)
    "Real component of initial armature current, sbase";
  parameter Types.PerUnit ii1=-CoB*(p0*vi0 - q0*vr0)/(vr0^2 + vi0^2)
    "Imaginary component of initial armature current, sbase";
  parameter Types.PerUnit Ix0=Isr0*cos(-angle_0) - Isi0*sin(-angle_0);
  parameter Types.PerUnit Iy0=Isr0*sin(-angle_0) + cos(-angle_0)*Isi0;
  parameter Types.PerUnit Eqcmd0=-Iy0*X_eq;
  parameter Types.PerUnit Ipcmd0=Ix0;
  parameter Types.PerUnit VX0=cos(angle_0)*vr0 + sin(angle_0)*vi0;
  parameter Types.PerUnit VY0=(-sin(angle_0)*vr0) + cos(angle_0)*vi0;
protected
  Modelica.Blocks.Interfaces.RealInput Vy ;

equation
  anglev = atan2(p.vi, p.vr);
  VT = sqrt(p.vr*p.vr + p.vi*p.vi);
  Iterm = sqrt(p.ir*p.ir + p.ii*p.ii);
  Is.re = p.ir/CoB - p.vi/X_eq;
  //Note that, the positive direction for p.ir is the antidirection of ir0
  Is.im = p.ii/CoB + p.vr/X_eq;
  Vy = VY;
  [Ix; Iy] = -[cos(delta), sin(delta); -sin(delta), cos(delta)]*[Is.re; Is.im];
  [VX; VY] = [cos(delta), sin(delta); -sin(delta), cos(delta)]*[p.vr; p.vi];
  -P = p.vr*p.ir/CoB + p.vi*p.ii/CoB;
  -Q = p.vi*p.ir/CoB - p.vr*p.ii/CoB;
  connect(Eqcmd, imSimpleLag.u)
    ;
  connect(Ipcmd, imSimpleLag1.u)
    ;
  connect(add.y, imLimited.u)
    ;
  connect(imLimited.y, imIntegrator.u)
    ;
  connect(imIntegrator.y, delta)
    ;
  connect(Vy, imGain1.u) ;
  connect(imSimpleLag.y, imGain.u)
    ;
  connect(imGain.y, Iy)
    ;
  connect(imSimpleLag1.y, Ix)
    ;
  connect(imGain1.y, add.u2) ;
  connect(imIntegrator1.u, add.u2) ;
  connect(imIntegrator1.y, add.u1) 
  ;
end WT3G1;

within OpenIPSL.Electrical.Wind.PSSE.WT4G;
model WT4G1 "Wind Generator Model with Power Converter (Type 4)"
  extends Icons.VerifiedModel;
  // Extending the PF component
  extends OpenIPSL.Electrical.Essentials.pfComponent;
  // Model parameters
  parameter Types.ApparentPower M_b "Machine base power";
  parameter Types.Time T_IQCmd "Converter time constant for I_Qcmd";
  parameter Types.Time T_IPCmd "Converter time constant for I_Pcmd";
  parameter Types.PerUnit V_LVPL1 "LVPL voltage 1 (Low voltage power logic)";
  parameter Types.PerUnit V_LVPL2 "LVPL voltage 2";
  parameter Real G_LVPL "LVPL gain";
  parameter Types.PerUnit V_HVRCR "HVRCR voltage (High voltage reactive current limiter)";
  parameter Types.PerUnit CUR_HVRCR "HVRCR current (Max. reactive current at VHVRCR)";
  parameter Types.PerUnit RIp_LVPL "Rate of LVACR active current change";
  parameter Types.Time T_LVPL "Voltage sensor for LVACR time constant";
  // Variables
  Complex Is "Equivalent internal current source";
  OpenIPSL.Interfaces.PwPin p(
    vr(start=vr0),
    vi(start=vi0),
    ir(start=ir1),
    ii(start=ii1)) ;
  OpenIPSL.NonElectrical.Continuous.SimpleLag K1(
    K=1,
    T=T_IQCmd,
    y_start=Iy0)
    ;
  Modelica.Blocks.Continuous.Integrator K(
    y_start=Ix0,
    k=1/T_IPCmd,
    initType=Modelica.Blocks.Types.Init.InitialOutput)
    ;
  Modelica.Blocks.Interfaces.RealOutput Iy(start=Iy0) ;
  Modelica.Blocks.Interfaces.RealOutput V=VT ;
  Modelica.Blocks.Interfaces.RealOutput P(start=p0) ;
  Modelica.Blocks.Interfaces.RealOutput Q(start=q0) ;
  Modelica.Blocks.Math.Feedback Iperr(y(start=0, fixed=false))
    ;
  OpenIPSL.Electrical.Wind.PSSE.Submodels.LVACL lVACL
    ;
  OpenIPSL.Electrical.Wind.PSSE.Submodels.HVRCL hVRCL(VHVRCR=V_HVRCR, CurHVRCR=
        CUR_HVRCR)
    ;
  Modelica.Blocks.Interfaces.RealOutput IyL(start=Iy0) ;
  Modelica.Blocks.Interfaces.RealOutput IxL(start=Ix0) ;
  OpenIPSL.Electrical.Wind.PSSE.Submodels.LVPL lVPL(
    VLVPL1=V_LVPL1,
    VLVPL2=V_LVPL2,
    GLVPL=G_LVPL)
    ;
  Modelica.Blocks.Nonlinear.Limiter imLimited_max(uMin=-Modelica.Constants.inf,
      uMax=RIp_LVPL)
    ;
  Modelica.Blocks.Nonlinear.VariableLimiter variableLimiter(y(start=Ipcmd0))
    ;
  Modelica.Blocks.Sources.Constant const(k=-Modelica.Constants.inf)
    ;
  //Initialization parameters
  Modelica.Blocks.Interfaces.RealInput I_qcmd(start=Iy0) ;
  Modelica.Blocks.Interfaces.RealInput I_pcmd(start=Ipcmd0) ;
  Modelica.Blocks.Interfaces.RealOutput I_qcmd0 ;
  Modelica.Blocks.Interfaces.RealOutput I_pcmd0 ;
  OpenIPSL.NonElectrical.Continuous.SimpleLag K2(
    K=1,
    T=T_LVPL,
    y_start=v_0)
    ;
protected
  Types.Angle delta(start=angle_0);
  Types.PerUnit VT(start=v_0) "Bus voltage magnitude";
  Types.Angle anglev(start=angle_0) "Bus voltage angle";
  parameter Types.PerUnit p0=P_0/M_b
    "initial value of bus active power in p.u. machinebase";
  parameter Types.PerUnit q0=Q_0/M_b
    "initial value of bus reactive power in p.u. machinebase";
  parameter Types.PerUnit vr0=v_0*cos(angle_0)
    "Real component of initial terminal voltage";
  parameter Types.PerUnit vi0=v_0*sin(angle_0)
    "Imaginary component of initial terminal voltage";
  parameter Types.PerUnit ir0=(p0*vr0 + q0*vi0)/(vr0^2 + vi0^2)
    "Real component of initial armature current, M_b";
  parameter Types.PerUnit ii0=(p0*vi0 - q0*vr0)/(vr0^2 + vi0^2)
    "Imaginary component of initial armature current, M_b";
  parameter Types.PerUnit Isr0=ir0 "Source current re M_b";
  parameter Types.PerUnit Isi0=ii0 "Source current im M_b";
  parameter Real CoB=M_b/S_b;
  parameter Types.PerUnit ir1=-CoB*(p0*vr0 + q0*vi0)/(vr0^2 + vi0^2)
    "Real component of initial armature current, S_b";
  parameter Types.PerUnit ii1=-CoB*(p0*vi0 - q0*vr0)/(vr0^2 + vi0^2)
    "Imaginary component of initial armature current, S_b";
  parameter Types.PerUnit Ipcmd0=Ix0;
  parameter Types.PerUnit Ix0=Isr0*cos(-angle_0) - Isi0*sin(-angle_0);
  parameter Types.PerUnit Iy0=-(Isr0*sin(-angle_0) + cos(-angle_0)*Isi0);
  Modelica.Blocks.Interfaces.RealInput Vtt=VT ;
equation
  I_qcmd0 = Iy0;
  I_pcmd0 = Ix0;
  anglev = atan2(p.vi, p.vr);
  VT = sqrt(p.vr*p.vr + p.vi*p.vi);
  delta = anglev;
  Is.re = p.ir/CoB;
  Is.im = p.ii/CoB;
  [IxL; -IyL] = -[cos(delta), sin(delta); -sin(delta), cos(delta)]*[Is.re; Is.im];
  -P = p.vr*p.ir + p.vi*p.ii;
  -Q = p.vi*p.ir - p.vr*p.ii;
  connect(Iperr.u1, I_pcmd) ;
  connect(lVACL.Ip_LVACL, IxL) ;
  connect(hVRCL.Iq_HVRCL, IyL) ;
  connect(I_qcmd, K1.u)
    ;
  connect(Iperr.y, imLimited_max.u)
    ;
  connect(imLimited_max.y, K.u)
    ;
  connect(K.y, variableLimiter.u)
    ;
  connect(variableLimiter.y, lVACL.Ip_LVPL)
    ;
  connect(Iperr.u2, lVACL.Ip_LVPL) ;
  connect(const.y, variableLimiter.limit2) ;
  connect(K1.y, hVRCL.Iq)
    ;
  connect(Iy, hVRCL.Iq) ;
  connect(lVPL.LVPL, variableLimiter.limit1) ;
  connect(Vtt, hVRCL.Vt) ;
  connect(lVACL.Vt, hVRCL.Vt) ;
  connect(lVPL.Vt, K2.y)
    ;
  connect(K2.u, hVRCL.Vt) 
  ;
end WT4G1;

