    H=2.137,
    angle_0=0,
    Q_0=1000000*((0.07332*30)),
    v_0=0.9705,
    P_0=5194860)
    ;
  Modelica.Blocks.Sources.Constant const(k=-Modelica.Constants.inf)
    ;
  OpenIPSL.Electrical.Controls.PSSE.ES.ST5B sT5B(
