within OpenIPSL.NonElectrical.Continuous;
block DerivativeLag "Derivative lag transfer function block"
  extends Modelica.Blocks.Interfaces.SISO;
  parameter Real K "Gain";
  parameter Types.Time T "Time constant";
  parameter Real y_start "Output start value"
    ;
  parameter Real x_start=0 "Start value of state variable"
    ;
  Modelica.Blocks.Sources.RealExpression par1(y=T)
    ;
  Modelica.Blocks.Continuous.TransferFunction TF(
    initType=Modelica.Blocks.Types.Init.InitialOutput,
    x_start={x_start},
    b={K_dummy,0},
    y_start=y_start,
    a={T_dummy,1})
    ;
protected
  parameter Types.Time T_dummy=if abs(T) < Modelica.Constants.eps
       then 1000 else T "Lead time constant";
  parameter Types.Time K_dummy=if abs(K) < Modelica.Constants.eps
       then 1 else K "Lead time constant";
equation
  if abs(par1.y) < Modelica.Constants.eps then
    y = u;
  else
    y = TF.y;
  end if;
  connect(TF.u, u)

  ;
end DerivativeLag;

within OpenIPSL.NonElectrical.Continuous;
block IntegratorLimVar
  "Integrator with a non windup limiter and variable limits"
  extends Modelica.Blocks.Interfaces.SISO;
  parameter Real K "Gain" ;
  parameter Real y_start "Output start value"
    ;
  Modelica.Blocks.Interfaces.RealInput outMax ;
  Modelica.Blocks.Interfaces.RealInput outMin ;
protected
  Real x "Dummy variable for input";
  Real w "Dummy variable for output";
  Real initVar "Dummy variable to be used as setting quantity";
  Boolean ReachUpper "Flag for reaching upper limit";
  Boolean ReachLower "Flag for reaching lower limit";
  Boolean Rising "Flag to know if input is positive";
  Boolean Falling "Flag to know if input is negative";
  Boolean Reinit "Flag to reset state variable";
initial equation
  if y_start >= outMax then
    w = outMax;
  elseif y_start<= outMin then
    w = outMin;
  else
    w = y_start;
  end if;
algorithm
  if u>Modelica.Constants.eps then
    Rising := true;
    Falling := false;
  elseif u<-Modelica.Constants.eps then
    Rising := false;
    Falling := true;
  else
    Rising := false;
    Falling := false;
  end if;
  // Flags for reaching limits and setting inputs and outputs:
  if w > outMax then
    ReachUpper := true;
    ReachLower := false;
  elseif w < outMin then
    ReachLower := true;
    ReachUpper := false;
  else
    ReachUpper := false;
    ReachLower := false;
  end if;
  // Updating flag for resetting state variable:
  if ReachUpper and Falling then
    Reinit := true;
    initVar := outMax;
  elseif ReachLower and Rising then
    Reinit := true;
    initVar := outMin;
  end if;
equation
  assert(
    outMax > outMin,
    "Upper limit must be greater than lower limit",
    AssertionLevel.error);
  // Equations depending on flags:
  if ReachUpper then
    x = 0;
    y = outMax;
  elseif ReachLower then
    x = 0;
    y = outMin;
  else
    x = u;
    y = w;
  end if;
  // Differential equation for integration block:
  der(w) = K*x;
  // Restarting state variable depending on flag:
  when Reinit then
    reinit(w,initVar);
  end when
  ;
end IntegratorLimVar;

within OpenIPSL.NonElectrical.Continuous;
block LeadLag "Lead-Lag filter"
  extends Modelica.Blocks.Interfaces.SISO;
  parameter Real K "Gain";
  parameter Types.Time T1 "Lead time constant";
  parameter Types.Time T2 "Lag time constant";
  parameter Real y_start "Output start value"
    ;
  parameter Real x_start=0 "Start value of state variable"
    ;
  Modelica.Blocks.Sources.RealExpression par1(y=T1)
    ;
  Modelica.Blocks.Sources.RealExpression par2(y=T2)
    ;
  Modelica.Blocks.Continuous.TransferFunction TF(
    b={K*T1,K},
    a={T2_dummy,1},
    y_start=y_start,
    initType=Modelica.Blocks.Types.Init.InitialOutput,
    x_start={x_start})
    ;
protected
  parameter Types.Time T2_dummy=if abs(T1 - T2) < Modelica.Constants.eps
       then 1000 else T2 "Lead time constant";
equation
  if abs(par1.y - par2.y) < Modelica.Constants.eps then
    y = K*u;
  else
    y = TF.y;
  end if;
  connect(TF.u, u)

  ;
end LeadLag;

within OpenIPSL.NonElectrical.Continuous;
block LeadLagLim "Lead-Lag filter with a non-windup limiter"
  extends Modelica.Blocks.Interfaces.SISO;
  parameter Real K "Gain";
  parameter Types.Time T1 "Lead time constant";
  parameter Types.Time T2 "Lag time constant";
  parameter Real outMax "Maximum output value";
  parameter Real outMin "Minimum output value";
  parameter Real y_start "Output start value"
    ;
  Modelica.Blocks.Math.Add add2(k2=1)
    ;
  Modelica.Blocks.Math.Gain gain(k=T1/T2)
    ;
  Modelica.Blocks.Math.Add add3(k2=-1)
    ;
  Modelica.Blocks.Continuous.Integrator integrator(
    y_start=y_start,
    k=1/T1,
    initType=Modelica.Blocks.Types.Init.SteadyState)
    ;
  Modelica.Blocks.Math.Gain gain1(k=T2/T1 - 1)
    ;
  Modelica.Blocks.Nonlinear.Limiter limiter(uMax=outMax, uMin=outMin)
    ;
equation
  connect(add2.y, gain.u)
    ;
  connect(integrator.u, add3.y)
    ;
  connect(integrator.y, add3.u2) ;
  connect(gain1.u, add3.u2) ;
  connect(gain1.y, add2.u2) ;
  connect(u, add2.u1)
    ;
  connect(gain.y, limiter.u)
    ;
  connect(limiter.y, y) ;
  connect(add3.u1, y) 
  ;
end LeadLagLim;

within OpenIPSL.NonElectrical.Continuous;
model RampTrackingFilter "Ramp-tracking filter"
  extends Modelica.Blocks.Interfaces.SISO;
  import Modelica.Blocks.Continuous;
  parameter Real T_1;
  parameter Real T_2;
  parameter Integer M = 5 ">=0, M*N<=8";
  parameter Integer N = 1 ">=0, M*N<=8";
  parameter Real y_start = 0 "Output start value";
  Continuous.TransferFunction TF1[M](b=fill({1},M), a=fill({T_2,1},M),each y_start=y_start);
  Continuous.TransferFunction TF2[N](b=fill({T_1,1},N), a=fill({T_2,1},N), each y_start=y_start);
equation
  if M == 0 or N == 0 then
    u = y;
  elseif M == 1 then
    connect(u, TF2[1].u);
    for i in 1:N-1 loop
      connect(TF2[i].y, TF2[i+1].u);
    end for;
    connect(TF2[N].y, TF1[1].u);
    connect(TF1[1].y, y);
  elseif N == 1 then
    connect(u, TF2[1].u);
    connect(TF2[1].y, TF1[1].u);
    for i in 1:M-2 loop
      connect(TF1[i].y, TF1[i+1].u);
    end for;
    connect(TF1[M-1].y, y);
    connect(u, TF1[M].u);
  elseif M == 1 and N ==1 then
    connect(u, TF2[1].u);
    connect(TF2[1].y, TF1[1].u);
    connect(TF1[1].y, y);
  else
    connect(u, TF2[1].u);
    for i in 1:N-1 loop
      connect(TF2[i].y, TF2[i+1].u);
    end for;
    connect(TF2[N].y, TF1[1].u);
    for i in 1:M-2 loop
      connect(TF1[i].y, TF1[i+1].u);
    end for;
    connect(TF1[M-1].y, y);
    connect(u, TF1[M].u);
  end if
  ;
end RampTrackingFilter;

within OpenIPSL.NonElectrical.Continuous;
block SimpleLag "First order lag transfer function block"
  extends Modelica.Blocks.Interfaces.SISO(y(start=y_start));
  Modelica.Blocks.Sources.RealExpression const(y=T)
    ;
  Real state(start=y_start);
  parameter Real K "Gain";
  parameter Types.Time T "Lag time constant";
  parameter Real y_start "Output start value";
protected
  parameter Real T_mod=if T < Modelica.Constants.eps then 1000 else T;
initial equation
  state = y_start;
equation
  T_mod*der(state) = K*u - state;
  if abs(const.y) <= Modelica.Constants.eps then
    y = u*K;
  else
    y = state;
  end if
  ;
end SimpleLag;

within OpenIPSL.NonElectrical.Continuous;
block SimpleLagLim
  "First order lag transfer function block with a non windup limiter"
  extends Modelica.Blocks.Interfaces.SISO(y(start=y_start));
  Modelica.Blocks.Sources.RealExpression const(y=T)
    ;
  Real state;
  parameter Real K "Gain";
  parameter Types.Time T "Lag time constant";
  parameter Real y_start "Output start value";
  parameter Real outMax "Maximum output value";
  parameter Real outMin "Minimum output value";
protected
  parameter Real T_mod=if T < Modelica.Constants.eps then 1000 else T;
initial equation
  state = y_start;
equation
  T_mod*der(state) = K*u - state;
  when state > outMax and K*u - state < 0 then
    reinit(state, outMax);
  elsewhen state < outMin and K*u - state > 0 then
    reinit(state, outMin);
  end when;
  if abs(const.y) <= Modelica.Constants.eps then
    y = max(min(u*K, outMax), outMin);
  else
    y = max(min(state, outMax), outMin);
  end if
  ;
end SimpleLagLim;

within OpenIPSL.NonElectrical.Continuous;
block SimpleLagLimVar
  "First order lag transfer function block with a non windup limiter and variable limits"
  extends Modelica.Blocks.Interfaces.SISO(y(start=y_start));
  Modelica.Blocks.Interfaces.RealInput outMax ;
  Modelica.Blocks.Interfaces.RealInput outMin ;
  Modelica.Blocks.Sources.RealExpression const(y=T)
    ;
  parameter Real K "Gain";
  parameter Types.Time T "Lag time constant";
  parameter Real y_start "Output start value";
  parameter Real T_mod=if T < Modelica.Constants.eps then 1000 else T;
  Real state;
initial equation
  state = y_start;
equation
  T_mod*der(state) = K*u - y;
  when abs(y - outMax) <= Modelica.Constants.eps and K*u - y < 0 or abs(y -
      outMin) <= Modelica.Constants.eps and K*u - y > 0 then
    reinit(state, y);
  end when;
  if abs(const.y) <= Modelica.Constants.eps then
    y = max(min(u*K, outMax), outMin);
  else
    y = max(min(state, outMax), outMin);
  end if
  ;
end SimpleLagLimVar;

within OpenIPSL.NonElectrical.Continuous;
block SimpleLagRateLimBlock
  "First order lag transfer function block with a non windup limiter, rate limits and blocking input"
  extends Modelica.Blocks.Interfaces.SISO(y(start=y_start));
  parameter Real K "Gain" ;
  parameter Types.Time T "Lag time constant"
    ;
  parameter Real y_start "Output start value"
    ;
  parameter Real outMax "Maximum output value" ;
  parameter Real outMin "Minimum output value" ;
  parameter Real rmin "Minimum rate limit" ;
  parameter Real rmax "Maximum rate limit" ;
  Real x;
  Real rate;
  Modelica.Blocks.Interfaces.RealInput Block ;
initial equation
  y = y_start;
equation
  assert(
    T >= 1e-10,
    "Time constant must be greater than 0",
    AssertionLevel.error);
  assert(
    outMax > outMin,
    "Upper limit must be greater than lower limit",
    AssertionLevel.error);
  rate = if u > outMax then (outMax - x)/T elseif u < outMin then (outMin - x)/
    T else (u - x)/T;
  if Block > 0 then
    der(x) = 0;
  else
    der(x) = if rate > rmax then rmax elseif rate < rmin then rmin else rate;
  end if;
  y = if x > outMax then outMax elseif x < outMin then outMin else x
  ;
end SimpleLagRateLimBlock;

within OpenIPSL.NonElectrical.Continuous;
block SimpleLagRateLimVar
  "First order lag transfer function block with a non windup limiter, rate limits, variable output limits and blocking input"
  extends Modelica.Blocks.Interfaces.SISO;
  parameter Types.Time T "Lag time constant"
    ;
  parameter Real y_start "Output start value"
    ;
  parameter Real rmin "Minimum rate limit";
  parameter Real rmax "Maximum rate limit";
  Real rate "Rate";
  Real x;
  Modelica.Blocks.Interfaces.RealInput outMin ;
  Modelica.Blocks.Interfaces.RealInput outMax ;
initial equation
  x = y_start;
  y = y_start;
equation
  assert(
    T >= 1e-10,
    "Time constant must be greater than 0",
    AssertionLevel.error);
  rate = if u > outMax then (outMax - x)/T elseif u < outMin then (outMin - x)/
    T else (u - x)/T;
  der(x) = if rate > rmax then rmax elseif rate < rmin then rmin else rate;
  y = if x > outMax then outMax elseif x < outMin then outMin else x
  ;
end SimpleLagRateLimVar;

