within OpenIPSL.NonElectrical.Nonlinear;
model FEX "FEX=f(IN)"
  Modelica.Blocks.Interfaces.RealInput u ;
  Modelica.Blocks.Interfaces.RealOutput y ;
equation
  if u <= 0 then
    y = 1;
  elseif u > 0 and u <= 0.433 then
    y = 1 - 0.577*u;
  elseif u > 0.433 and u < 0.75 then
    y = sqrt(0.75 - u^2);
  elseif u >= 0.75 and u <= 1 then
    y = 1.732*(1 - u);
  else
    y = 0;
  end if
  ;
end FEX;

within OpenIPSL.NonElectrical.Nonlinear;
model FrequencyCalc "Frequency deviation calculation from a rotating phasor"
  parameter Boolean start_guess=false;
  parameter Real real_start=1 "Phasor initial real part";
  parameter Real imag_start=0 "Phasor initial imaginary part";
  parameter Types.Time Ts = 0.01 "Smoothing filter time constant";

  Modelica.Blocks.Interfaces.RealInput real_part
    ;
  Modelica.Blocks.Interfaces.RealOutput y "O/P is in rad/sec"
    ;
  Modelica.Blocks.Continuous.Der derOfReal
    ;
  Modelica.Blocks.Math.Product ImagXderReal ;
  Modelica.Blocks.Math.Add diff(k2=-1) ;
  Modelica.Blocks.Math.Division division
    ;
  Modelica.Blocks.Interfaces.RealInput imag_part
    ;
  Modelica.Blocks.Math.Product RealXderImag ;
  Modelica.Blocks.Math.Product imag2 ;
  Modelica.Blocks.Math.Product real2 ;
  Modelica.Blocks.Math.Add sum ;
  Modelica.Blocks.Continuous.Der derOfImag
    ;

protected
  parameter Modelica.Blocks.Types.Init init_type=if start_guess == true then
      Modelica.Blocks.Types.Init.InitialState else Modelica.Blocks.Types.Init.NoInit;

equation
  connect(diff.y, division.u1) ;
  connect(sum.y, division.u2) ;
  connect(division.y, y) ;
  connect(real2.y, sum.u1) ;
  connect(imag2.y, sum.u2) ;
  connect(real_part, derOfReal.u) ;
  connect(imag2.u1, imag_part) ;
  connect(imag2.u2, imag_part) ;
  connect(derOfImag.y, RealXderImag.u2) ;
  connect(derOfImag.u, imag_part) ;
  connect(real_part, RealXderImag.u1) ;
  connect(RealXderImag.y, diff.u1) ;
  connect(ImagXderReal.y, diff.u2) ;
  connect(ImagXderReal.u1, imag_part) ;
  connect(derOfReal.y, ImagXderReal.u2) ;
  connect(real2.u2, real_part) ;
  connect(real2.u1, real_part) 

;
end FrequencyCalc;

within OpenIPSL.NonElectrical.Nonlinear;
model SaturationBlockTan
  "Block 1 in the OEL to decide the input signal of MIN Gate"
  parameter Real r "Exiciter parameter";
  parameter Real f "Exiciter parameter";
  Modelica.Blocks.Interfaces.RealInput p1 ;
  Modelica.Blocks.Interfaces.RealOutput n1 ;
equation
  if p1 <= (-0.1) then
    n1 = -1;
  elseif p1 > (-0.1) and p1 < 0 then
    n1 = 0;
  else
    n1 = tan(r)*p1 + f;
  end if
  ;
end SaturationBlockTan;

