within PhotoVoltaics.Components.Converters;
model PolyphaseConverter "Ideal polyphase DC/AC converter"

  import Modelica.Constants.pi;
  extends Modelica.Electrical.PowerConverters.Interfaces.DCAC.DCtwoPin;
  extends .PhotoVoltaics.Icons.Converter;

  Modelica.Electrical.Polyphase.Interfaces.PositivePlug ac "AC output"
    ;
  Modelica.Blocks.Interfaces.RealInput vDCRef(final unit = "V")
    "DC voltage"                                                             ;

  parameter Modelica.Units.SI.Frequency f=50 "Frequency";
  parameter Modelica.Units.SI.Voltage VRef=400
    "Reference line to line voltage";
  parameter Modelica.Units.SI.Time Ti=1E-6
    "Internal integration time constant";
  Modelica.Units.SI.Power powerDC=vDC*iDC "Power of DC side";

  Modelica.Electrical.Analog.Sources.SignalVoltage signalVoltage ;
  Modelica.Electrical.Analog.Sensors.CurrentSensor currentSensor ;
  Modelica.Blocks.Math.Product product ;
  Modelica.Blocks.Math.Feedback feedback ;
  Modelica.Electrical.Machines.SpacePhasors.Blocks.FromPolar fromPolar ;
  Modelica.Blocks.Continuous.Integrator integrator(k=sqrt(3)/VRef/Ti)      ;
  Modelica.Blocks.Math.Gain gain(final k=1)    ;
  Modelica.Electrical.Machines.SpacePhasors.Blocks.FromSpacePhasor fromSpacePhasor(m=3)
    ;
  Modelica.Blocks.Sources.Constant zeroConst(final k=0) ;
  Modelica.Electrical.Polyphase.Sources.SignalCurrent signalCurrent
    ;
  Modelica.Electrical.Polyphase.Basic.Star star ;
  Modelica.Electrical.Analog.Basic.Ground ground
    ;
  Modelica.Blocks.Sources.Constant constOmega(final k=2*pi*f) ;
  Modelica.Blocks.Math.RectangularToPolar rectangularToPolar
    ;

  Modelica.Electrical.Polyphase.Sensors.VoltageSensor voltageSensorAC(
      final m=3) ;
  Modelica.Blocks.Math.Product productPower[3] ;
  Modelica.Blocks.Math.Add add
    ;
  Modelica.Blocks.Interfaces.RealInput phi "Phase angle of current with respect to voltage" ;

  Modelica.Blocks.Continuous.Integrator integratorOmega(final k=1) ;
  Modelica.Blocks.Continuous.FirstOrder firstOrder[3](k=ones(3), T=fill(Ti, 3),
    initType=fill(Modelica.Blocks.Types.Init.InitialState, 3),
    y_start=fill(0, 3))                                                        ;
  Modelica.Electrical.Machines.SpacePhasors.Blocks.Rotator rotatorOut ;
  Modelica.Blocks.Math.Gain neg(final k=-1) ;
  Modelica.Electrical.Machines.SpacePhasors.Blocks.ToSpacePhasor toSpacePhasor ;
  Modelica.Electrical.Machines.SpacePhasors.Blocks.Rotator rotatorIn ;
  Modelica.Blocks.Math.Sum sum3(nin=3) ;
equation
  connect(currentSensor.n,signalVoltage. p) ;
  connect(signalVoltage.v,vDCRef)  ;
  connect(dc_p, currentSensor.p) ;
  connect(dc_n, signalVoltage.n) ;
  connect(product.y,feedback. u1) ;
  connect(feedback.y,integrator. u) ;
  connect(gain.y,feedback. u2) ;
  connect(product.u1, currentSensor.i) ;
  connect(product.u2, vDCRef) ;
  connect(star.plug_p, signalCurrent.plug_p)
    ;
  connect(ground.p, star.pin_n)
    ;
  connect(fromSpacePhasor.zero, zeroConst.y) ;
  connect(integrator.y, fromPolar.u[1]) ;
  connect(voltageSensorAC.plug_n, star.plug_p) ;
  connect(voltageSensorAC.plug_p, ac) ;
  connect(rectangularToPolar.y_arg, add.u1) ;
  connect(add.y, fromPolar.u[2]) ;
  connect(constOmega.y, integratorOmega.u) ;
  connect(fromSpacePhasor.y, firstOrder.u) ;
  connect(firstOrder.y, signalCurrent.i) ;
  connect(fromPolar.y, rotatorOut.u) ;
  connect(neg.y, rotatorOut.angle) ;
  connect(rotatorIn.u, toSpacePhasor.y) ;
  connect(rotatorIn.angle, integratorOmega.y) ;
  connect(neg.u, integratorOmega.y) ;
  connect(rotatorOut.y, fromSpacePhasor.u) ;
  connect(rectangularToPolar.u_re, rotatorIn.y[1]) ;
  connect(rectangularToPolar.u_im, rotatorIn.y[2]) ;
  connect(sum3.y, gain.u) ;
  connect(productPower.u2, voltageSensorAC.v) ;
  connect(sum3.u, productPower.y) ;
  connect(firstOrder.y, productPower.u1) ;
  connect(signalCurrent.plug_n, voltageSensorAC.plug_p) ;
  connect(voltageSensorAC.v, toSpacePhasor.u) ;
  connect(add.u2, phi) 
  ;
end PolyphaseConverter;

within PhotoVoltaics.Components.Converters;
model QuasiStaticPolyphaseConverter
  "Ideal quasi stastic polyphase DC/AC converter"
  extends Modelica.Electrical.PowerConverters.Interfaces.DCAC.DCtwoPin;
  extends .PhotoVoltaics.Interfaces.QuasiStatic.ACplug;
  extends .PhotoVoltaics.Icons.Converter;
  parameter Modelica.Units.SI.Voltage VRef=400
    "Reference line to line voltage";
  parameter Modelica.Units.SI.Time Ti=1E-6
    "Internal integration time constant";
  Modelica.Units.SI.Power powerDC=vDC*iDC "Power of DC side";
  Modelica.Units.SI.Power powerAC=Modelica.ComplexMath.real(vAC*
      Modelica.ComplexMath.conj(iAC)) "Complex apparent power of AC side";
  Modelica.Blocks.Interfaces.RealInput vDCRef(final unit = "V") "DC voltage" ;
  Modelica.Electrical.Analog.Sources.SignalVoltage signalVoltage ;
  Modelica.Electrical.Analog.Sensors.CurrentSensor currentSensor ;
  Modelica.Blocks.Math.Product product ;
  Modelica.Blocks.Math.Feedback feedback ;
  Sources.Electrical.VariableUnrootedPolyphaseCurrentSource
    variableCurrentSource(final m=m) ;
  Modelica.Electrical.QuasiStatic.Polyphase.Basic.Star star(final m=m)
    ;
  Modelica.Electrical.QuasiStatic.Polyphase.Sensors.PowerSensor
    powerSensor(final m=m) ;
  Modelica.Electrical.QuasiStatic.Polyphase.Sensors.PotentialSensor
    potentialSensor(final m=m) ;
  Modelica.Electrical.QuasiStatic.Polyphase.Blocks.ToSpacePhasor
    toSpacePhasor(final m=m) ;
  Modelica.ComplexBlocks.ComplexMath.ComplexToReal complexToReal ;
  Modelica.Electrical.QuasiStatic.Polyphase.Blocks.FromSpacePhasor
    fromSpacePhasor(final m=m) ;
  Modelica.Electrical.Machines.SpacePhasors.Blocks.FromPolar fromPolar ;
  Modelica.Electrical.Machines.SpacePhasors.Blocks.ToPolar toPolar ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Basic.Ground ground
    ;
  Modelica.Blocks.Continuous.Integrator integrator(k=sqrt(3)/VRef/Ti)      ;
  Modelica.Blocks.Math.Gain gain(final k = -1) ;
equation
  connect(signalVoltage.n, dc_n) ;
  connect(currentSensor.p, dc_p) ;
  connect(currentSensor.n, signalVoltage.p) ;
  connect(signalVoltage.v, vDCRef) ;
  connect(currentSensor.i, product.u1) ;
  connect(vDCRef, product.u2) ;
  connect(product.y, feedback.u1) ;
  connect(powerSensor.currentP, powerSensor.voltageP) ;
  connect(powerSensor.voltageN, star.plug_p) ;
  connect(potentialSensor.v, toSpacePhasor.u) ;
  connect(complexToReal.u, powerSensor.apparentPower) ;
  connect(fromSpacePhasor.y, variableCurrentSource.I) ;
  connect(fromSpacePhasor.u, fromPolar.y) ;
  connect(integrator.y, fromPolar.u[1]) ;
  connect(toSpacePhasor.y, toPolar.u) ;
  connect(toPolar.y[2], fromPolar.u[2]) ;
  connect(star.pin_n, ground.pin) ;
  connect(powerSensor.currentP, ac) ;
  connect(potentialSensor.plug_p, ac) ;
  connect(feedback.y, integrator.u) ;
  connect(powerSensor.currentN, variableCurrentSource.plug_n) ;
  connect(variableCurrentSource.plug_p, star.plug_p) ;
  connect(gain.u, complexToReal.re) ;
  connect(gain.y, feedback.u2) 
  ;
end QuasiStaticPolyphaseConverter;

