  connect(currentSensor.i, product.u1) ;
  connect(vDCRef, product.u2) ;
  connect(product.y, feedback.u1) ;
  connect(powerSensor.currentP, powerSensor.voltageP) ;
  connect(complexToReal.u, powerSensor.apparentPower) ;
  connect(feedback.y, integrator.u) ;
  connect(powerSensor.currentP, ac_p) ;
  connect(potentialSensor.pin_p, ac_p) ;
  connect(potentialSensor.pin_n, ac_n) ;
  connect(powerSensor.voltageN, ac_n) ;
  connect(complexToPolar.u,potentialSensor.v)  ;
  connect(polarToComplex.y, variableCurrentSource.I) ;
  connect(integrator.y, polarToComplex.len) ;
  connect(polarToComplex.phi, complexToPolar.phi) ;
  connect(gain.u, complexToReal.re) ;
  connect(gain.y, feedback.u2) ;
  connect(powerSensor.currentN, variableCurrentSource.pin_n) ;
  connect(variableCurrentSource.pin_p, ac_n) 
  ;
end QuasiStaticSinglePhaseConverter;

