within PhotoVoltaics.Components.Diodes;
model Diode "Diode with one exponential function"
  extends .PhotoVoltaics.Interfaces.PartialDiode;
equation
  i = Ids * (exp(v / m / Vt) - 1) + v / R
  ;
end Diode;

within PhotoVoltaics.Components.Diodes;
model Diode2exp "Diode with two superimposed exponential functions"
  extends .PhotoVoltaics.Interfaces.PartialDiode;
  parameter Modelica.Units.SI.Voltage Bv=5.1 "Breakthrough voltage";
  parameter Modelica.Units.SI.Current Ibv=0.7 "Breakthrough knee current";
  parameter Real Nbv = 0.74 "Breakthrough emission coefficient";
equation
  i = Ids * (exp(v / m / Vt) - 1) - Ibv * exp(-(v + Bv) / (Nbv * m * Vt)) + v / R
  ;
end Diode2exp;

within PhotoVoltaics.Components.Diodes;
model Diode2Module "Diode model with four different sections including breakthrough"
  extends .PhotoVoltaics.Interfaces.PartialDiode;
  parameter Modelica.Units.SI.Voltage Bv=5.1 "Breakthrough voltage";
  parameter Modelica.Units.SI.Current Ibv=0.7 "Breakthrough knee current";
  parameter Real Nbv = 0.74 "Breakthrough emission coefficient";
  parameter Integer ns = 1 "Number of series connected cells per module";
  parameter Integer nsModule(final min = 1) = 1 "Number of series connected modules";
  parameter Integer npModule(final min = 1) = 1 "Number of parallel connected modules";
  final parameter Modelica.Units.SI.Voltage VtRef=Modelica.Constants.k*
      TRef/Q "Reference voltage equivalent of temperature";
  final parameter Modelica.Units.SI.Voltage VBv=(-m*Nbv*log(IdsRef*Nbv/
      Ibv)*VtRef) - Bv "Voltage limit of approximation of breakthrough";
  final parameter Modelica.Units.SI.Current IdsRef=IRef/(exp(VRef/m/VtRef)
       - 1) "Reference saturation current";
  final parameter Modelica.Units.SI.Voltage VNegLin=(-VRef/m/VtRef*(Nbv*m*
      VtRef)) - Bv "Limit of linear range left of breakthrough";
  Modelica.Units.SI.Voltage VNeg "Limit of linear negative voltage range";
  Modelica.Units.SI.Voltage vCell=v/ns/nsModule "Cell voltage";
  Modelica.Units.SI.Voltage vModule=v/nsModule "Module voltage";
  Modelica.Units.SI.Current iModule=i/npModule "Module current";
equation
  // Voltage limit of negative range
  VNeg = m * Vt * log(Vt / VtRef);
  // Current approximation
  i / npModule = smooth(1, if v / ns / nsModule > VNeg then Ids * (exp(v / ns / nsModule / m / Vt) - 1) + v / ns / nsModule / R elseif v / ns / nsModule > VBv then Ids * v / ns / nsModule / m / VtRef + v / ns / nsModule / R
   elseif v / ns / nsModule > VNegLin then (-Ibv * exp(-(v / ns / nsModule + Bv) / (Nbv * m * Vt))) + Ids * VBv / m / VtRef + v / ns / nsModule / R else Ids * v / ns / nsModule / m / Vt - Ibv * exp(VRef / m / VtRef) * (1 - (v / ns / nsModule + Bv) / (Nbv * m * Vt) - VRef / m / VtRef) + v / ns / nsModule / R)
  ;
end Diode2Module;

within PhotoVoltaics.Components.SimplePhotoVoltaics;
model SimpleModule "Simple module consisting of series connected cells"
  extends .PhotoVoltaics.Interfaces.PartialComponent;
  parameter Real shadow[moduleData.ns] = zeros(moduleData.ns) "Shadow vector based on: 0 = full sun, 1 = full shadow";
  SimpleCell cell[moduleData.ns](
    final useHeatPort=fill(useHeatPort, moduleData.ns),
    final T=fill(T, moduleData.ns),
    final constantIrradiance=fill(constantIrradiance, moduleData.ns),
    final moduleData=fill(moduleData, moduleData.ns),
    final useConstantIrradiance=fill(false, moduleData.ns),
    final shadow=shadow) ;
  Modelica.Thermal.HeatTransfer.Components.ThermalCollector collectorModule(final m = moduleData.ns) if useHeatPort ;
  Diodes.Diode diode[moduleData.nb](final useHeatPort = fill(useHeatPort, moduleData.nb), final T = fill(T, moduleData.nb), final m = fill(1, moduleData.nb), final R = fill(1E8, moduleData.nb), final TRef = fill(moduleData.TRef, moduleData.nb), final IRef = fill(moduleData.IscRef, moduleData.nb), final alphaI = fill(0, moduleData.nb), final alphaV = fill(0, moduleData.nb), final VRef = fill(0.5, moduleData.nb)) ;
  Modelica.Thermal.HeatTransfer.Components.ThermalCollector collectorByPass(final m = moduleData.nb) if useHeatPort ;
  Modelica.Blocks.Routing.Replicator replicator(final nout=moduleData.ns) ;

equation
  assert(mod(moduleData.ns, moduleData.nb) == 0, "Simple: number of bypassed cells cannot be determined unambiguously");
  // Connect cells to module
  connect(p, cell[1].p) ;
  for k in 1:moduleData.ns - 1 loop
    connect(cell[k].n, cell[k + 1].p);
  end for;
  // Inter-module connections
  connect(cell[moduleData.ns].n, n) ;
  connect(cell.heatPort, collectorModule.port_a) ;
  connect(collectorModule.port_b, heatPort) ;
  // Connect bypass diodes
  for k in 1:moduleData.nb loop
    connect(diode[k].n, cell[(k - 1) * div(moduleData.ns, moduleData.nb) + 1].p) ;
    connect(diode[k].p, cell[k * div(moduleData.ns, moduleData.nb)].n) ;
  end for;
  connect(collectorByPass.port_a, diode.heatPort) ;
  connect(collectorByPass.port_b, heatPort) ;
  connect(irradiance, replicator.u) ;
  connect(replicator.y, cell.variableIrradiance) 
  ;
end SimpleModule;

within PhotoVoltaics.Components.SimplePhotoVoltaics;
model SimpleModuleSymmetric "Simple module consisting of symmetric series connected cells"
  extends .PhotoVoltaics.Interfaces.PartialCell(diode(
      final m=m,
      final R=1E8,
      final Bv=moduleData.BvCell,
      final Ibv=moduleData.Ibv,
      final Nbv=moduleData.Nbv,
      final IRef=moduleData.IscRef,
      final alphaI=moduleData.alphaIsc,
      final alphaV=moduleData.alphaVoc,
      final ns=moduleData.ns,
      final VRef=moduleData.VocCellRef,
      final nsModule=1,
      final npModule=1), signalCurrent(
      final IRef=IphRef,
      final irradianceRef=moduleData.irradianceRef,
      final alphaRef=moduleData.alphaIsc));

  final parameter Real m(start = 2, fixed = false) "Ideality factor of diode";
  final parameter Modelica.Units.SI.Current IsdRef(start=1E-4, fixed=false)
    "Reference saturation current of cell";
  final parameter Modelica.Units.SI.Current IphRef=moduleData.IscRef
    "Reference photo current of cell";
  Modelica.Units.SI.Voltage vCell=v/moduleData.ns "Cell voltage";
  Modelica.Units.SI.Current iCell=i "Cell current";
  Modelica.Units.SI.Current iCellGenerating=-iCell
    "Negative cell current (generating)";
  Modelica.Units.SI.Power powerCell=vCell*iCell "Cell power";
  Modelica.Units.SI.Power powerCellGenerating=vCell*iCellGenerating
    "Negative power consumption (generating)";
initial equation
  IphRef = IsdRef * (exp(moduleData.VocCellRef / m / moduleData.VtCellRef) - 1);
  IphRef = IsdRef * (exp(moduleData.VmpCellRef / m / moduleData.VtCellRef) - 1) + moduleData.ImpRef
  ;
end SimpleModuleSymmetric;

