model SimpleModulePolyphase
  "Simple module supplies transient three-phase AC grid with maximum power tracker"

  import Modelica.Constants.pi;
  extends Modelica.Icons.Example;

  Modelica.Electrical.Analog.Basic.Ground groundDC ;
  Modelica.Electrical.Analog.Sensors.PowerSensor powerSensor ;
  Modelica.Electrical.Polyphase.Basic.Star star ;
  Modelica.Electrical.Analog.Basic.Ground ground
    ;
  Modelica.Electrical.Polyphase.Sources.CosineVoltage cosineVoltage(
    f=fill(50, 3),
    V=fill(400*sqrt(2/3), 3),
    phase=-Modelica.Electrical.Polyphase.Functions.symmetricOrientation(3))
    ;
  Modelica.Blocks.Sources.Ramp ramp(
    height=-100,
    duration=2,
    offset=1000,
    startTime=1)                                                                                 ;
  Modelica.Blocks.Sources.Constant powerfactor(k=-acos(0.9))
    ;
  PhotoVoltaics.Components.SimplePhotoVoltaics.SimpleModuleSymmetric module(
    moduleData=moduleData,
    useConstantIrradiance=false,
    T=298.15) ;
  PhotoVoltaics.Components.Blocks.MPTrackerSample mpTracker(VmpRef=moduleData.VmpRef, ImpRef=moduleData.ImpRef,
    samplePeriod=0.1)                                                                                           ;
  PhotoVoltaics.Components.Converters.PolyphaseConverter converter
    ;
  parameter PhotoVoltaics.Records.SHARP_NU_S5_E3E moduleData ;
  Modelica.Electrical.Polyphase.Sensors.PowerSensor powerSensorGrid
    ;
  Modelica.Electrical.Polyphase.Sensors.VoltageQuasiRMSSensor
    voltageQuasiRMSSensor(m=3) ;
  Modelica.Electrical.Polyphase.Sensors.CurrentQuasiRMSSensor
    currentQuasiRMSSensor(final m=3) ;
  Modelica.Blocks.Math.Division powerFactorActual ;
  Modelica.Blocks.Math.Product product ;
  Modelica.Blocks.Math.Gain gain(final k=3)
                                 ;

  Modelica.Units.SI.Power powerDC=powerSensor.power "DC power";
  Modelica.Units.SI.Power powerAC=powerSensorGrid.power "AC real power";
  Modelica.Units.SI.ApparentPower aparrentPowerAC=powerFactorActual.u2
    "AC apparent power";
  Real powerFactorAC = powerFactorActual.y "Actual power factor";

  Modelica.Blocks.Nonlinear.Limiter limiter(uMax=Modelica.Constants.inf, uMin=Modelica.Constants.small) ;
equation
  connect(powerSensor.pc,powerSensor. pv) ;
  connect(powerSensor.nv,groundDC. p) ;
  connect(ground.p,star. pin_n)
    ;
  connect(cosineVoltage.plug_n,star. plug_p)
    ;
  connect(module.variableIrradiance, ramp.y) ;
  connect(module.n, groundDC.p) ;
  connect(module.p, powerSensor.pc) ;
  connect(converter.dc_p, powerSensor.nc)
    ;
  connect(converter.dc_n, groundDC.p)
    ;
  connect(mpTracker.power, powerSensor.power) ;
  connect(mpTracker.vRef, converter.vDCRef)
    ;
  connect(powerfactor.y, converter.phi) ;
  connect(converter.ac, powerSensorGrid.pc) ;
  connect(powerSensorGrid.pv, powerSensorGrid.pc) ;
  connect(powerSensorGrid.nv, star.plug_p) ;
  connect(powerSensorGrid.nc, currentQuasiRMSSensor.plug_p) ;
  connect(currentQuasiRMSSensor.plug_n, cosineVoltage.plug_p) ;
  connect(voltageQuasiRMSSensor.plug_n, star.plug_p) ;
  connect(voltageQuasiRMSSensor.plug_p, currentQuasiRMSSensor.plug_n) ;
  connect(powerFactorActual.u1, powerSensorGrid.power) ;
  connect(gain.u, product.y) ;
  connect(product.u1, currentQuasiRMSSensor.I) ;
  connect(product.u2, voltageQuasiRMSSensor.V) ;
  connect(limiter.y, powerFactorActual.u2) ;
  connect(limiter.u, gain.y) 
  ;
end SimpleModulePolyphase;

