within PhotoVoltaics.Sources.Blocks;
block PowerRamp "Generate ramp signal based logarithmic range"
  parameter Real height = 1 "Height of ramps";
  parameter Modelica.Units.SI.Time duration(min=0.0, start=2)
    "Duration of ramp (= 0.0 gives a Step)";
  parameter Real offset = 0 "Offset of output signal";
  parameter Modelica.Units.SI.Time startTime=0
    "Output = offset for time < startTime";
  parameter Real ref = 1 "Reference value, determined by ref * 10 ^ (ramp function)";
  extends Modelica.Blocks.Interfaces.SO;
equation
  y = ref * 10 ^ (offset + (if time < startTime then 0 else if time < startTime + duration then (time - startTime) * height / duration else height))
  ;
end PowerRamp;

within PhotoVoltaics.Sources.Blocks;
block TriangleAndStep "Multiple steps and triangles"
  parameter Modelica.Units.SI.Time T=1 "Total time of varying outputs";
  parameter Integer stepNumber = 5 "Number of steps";
  parameter Real stepHeight = 1 "Total step height";
  parameter Real stepOffset = 0 "Offset";
  parameter Modelica.Units.SI.Time startTime=0 "Start time";
  parameter Real triangleHeight = 1 "Height of triangle output";
  parameter Real triangleOffset = 0 "Offset of triangle output";
  Modelica.Blocks.Sources.Ramp ramp(
    final startTime=startTime,
    final height=stepNumber - 1,
    final duration=T*(stepNumber - 1)/stepNumber,
    final offset=0) ;
  Modelica.Blocks.Math.RealToInteger realToInteger ;
  Modelica.Blocks.Math.IntegerToReal integerToReal ;
  Modelica.Blocks.Math.Feedback feedback ;
  Modelica.Blocks.Sources.Constant constantOffset(final k = stepOffset) ;
  Modelica.Blocks.Math.Add add ;
  Modelica.Blocks.Math.Gain gain(final k = stepHeight / (stepNumber - 1)) ;
  Modelica.Blocks.Sources.Trapezoid trapezoid(final amplitude = triangleHeight, final rising = T / stepNumber / 2, final width = 0, final falling = T / stepNumber / 2, final period = T / stepNumber, final nperiod = stepNumber, final offset = triangleOffset, final startTime = startTime) ;
  Modelica.Blocks.Interfaces.RealOutput step ;
  Modelica.Blocks.Interfaces.RealOutput triangle ;
  Modelica.Blocks.Sources.Step const(offset=0, startTime=0, height=0.5) ;
  Modelica.Blocks.Nonlinear.Limiter limiter(final uMax=Modelica.Constants.inf, final uMin=0) ;
equation
  connect(realToInteger.y, integerToReal.u) ;
  connect(ramp.y, feedback.u1) ;
  connect(integerToReal.y, gain.u) ;
  connect(constantOffset.y, add.u1) ;
  connect(gain.y, add.u2) ;
  connect(add.y, step) ;
  connect(trapezoid.y, triangle) ;
  connect(const.y, feedback.u2) ;
  connect(feedback.y, limiter.u) ;
  connect(limiter.y, realToInteger.u) 
  ;
end TriangleAndStep;

within PhotoVoltaics.Sources.Electrical;
model IdealBattery "Re-chargeable ideal battery without loss"
  parameter Integer ns(min = 1) = 1 "Number of series cells";
  parameter Integer np(min = 1) = 1 "Number of parallel cells";
  parameter Modelica.Units.SI.Voltage V1Cell
    "Maximum cell voltage > V0Cell";
  parameter Modelica.Units.SI.Voltage V0Cell
    "Minimum cell voltage < V1Cell";
  final parameter Modelica.Units.SI.Voltage V1=V1Cell*ns
    "Maximum battery voltage > V0";
  final parameter Modelica.Units.SI.Voltage V0=V0Cell*ns
    "Maximum battery voltage < V1";
  parameter Boolean allowOvercharge = false
    "Allows overcharging without error";
  parameter Boolean allowUndercharge = false
    "Allows undercharging without error";
  parameter Modelica.Units.SI.Energy ECell
    "Total cell energy between V0Cell and V1Cell";
  final parameter Modelica.Units.SI.Capacitance CCell=2*ECell/(V1Cell^2 -
      V0Cell^2) "Total charge of battery";
  parameter Modelica.Units.SI.Voltage ViniCell=V1Cell
    "Initial cell voltage";
  Modelica.Units.SI.Voltage v=pin_p.v - pin_n.v "Battery voltage";
  Modelica.Units.SI.Voltage vCell=v/ns "Cell voltage";
  Modelica.Units.SI.Current i=capacitor.i "Battery current";
  Modelica.Units.SI.Current iCell=i/np "Cell current";
  Modelica.Units.SI.Power power=v*i "Battery power";
  Modelica.Units.SI.Power powerCell=power/ns/np "Cell power";
  Modelica.Units.SI.Energy energy "Energy";
  Modelica.Units.SI.Energy energyCell "Cell energy";
  Modelica.Electrical.Analog.Basic.Capacitor capacitor(final C = CCell * np / ns, v(start = ns * ViniCell, fixed = true)) ;
  Modelica.Electrical.Analog.Interfaces.PositivePin pin_p "Positive pin"
                                                          ;
  Modelica.Electrical.Analog.Interfaces.NegativePin pin_n "Negative pin"
                                                          ;
initial equation
  energyCell = CCell * (ViniCell ^ 2 - V0Cell ^ 2) / 2;
equation
  der(energy) = power;
  energyCell * ns * np = energy;
  assert(vCell >= V0Cell or allowUndercharge, "Battery: cell voltage less than V0Cell");
  assert(vCell <= V1Cell or allowOvercharge, "Battery: cell voltage greater than V1Cell");
  connect(pin_p, capacitor.p) ;
  connect(capacitor.n, pin_n) 
  ;
end IdealBattery;

within PhotoVoltaics.Sources.Electrical;
model SignalCurrent "Generic current source using the input signal as source current"
  extends Modelica.Electrical.Analog.Interfaces.ConditionalHeatPort(T = 298.15);
  parameter Modelica.Units.SI.Temperature TRef=298.15
    "Reference temperature";
  parameter Modelica.Units.SI.Current IRef=1
    "Reference current at reference irradiance and reference temperature";
  parameter Modelica.Units.SI.Irradiance irradianceRef=1000
    "Reference solar irradiance";
  parameter Modelica.Units.SI.LinearTemperatureCoefficient alphaRef=0
    "Temperature coefficient of reference current at TRref";
  Modelica.Electrical.Analog.Interfaces.PositivePin p ;
  Modelica.Electrical.Analog.Interfaces.NegativePin n ;
  Modelica.Units.SI.Voltage v
    "Voltage drop between the two pins (= p.v - n.v)";
  Modelica.Units.SI.Current i
    "Current flowing from pin p to pin n as input signal";
  Modelica.Blocks.Interfaces.RealInput irradiance(unit = "W/m2") "Irradiance" ;
equation
  i = IRef * (irradiance / irradianceRef + alphaRef * (T_heatPort - TRef));
  v = p.v - n.v;
  0 = p.i + n.i;
  i = p.i;
  LossPower = 0
  ;
end SignalCurrent;

