within PhotoVoltaics.Sources.Irradiance;
model Irradiance "Simple solar irradiance without considering weather conditions"
  import Modelica.Constants.pi;
  import PhotoVoltaics.Functions.rad;
  import PhotoVoltaics.Functions.degree;
  import PhotoVoltaics.Functions.dayOfTheYear;
  parameter Integer startDay(final min = 1, final max = 31) = 10 "Day";
  parameter Integer startMonth(final min = 1, final max = 12) = 9 "Month";
  parameter Integer startYear = 2016 "Year";
  parameter Integer TimeZone = 1 "Time zone";
  parameter Modelica.Units.SI.Angle longitude=0.2856929452589518
    "Longitude";
  parameter Modelica.Units.SI.Angle latitude=0.8418964085999744
    "Latitude";
  parameter Modelica.Units.SI.Irradiance irradianceRef=1000
    "Reference solar irradiance";
  parameter Modelica.Units.SI.Angle gamma=10*pi/180
    "Angle of PV module with w.r.t. horizontal plane";
  parameter Modelica.Units.SI.Angle azimuth=0
    "Azimuth of the PV module orientation";
  Integer startDayOfYear(start = dayOfTheYear(startDay, startMonth, startYear), fixed = true) "Start day of year in simulation";
  Integer dayOfYear(final start = dayOfTheYear(startDay, startMonth, startYear), fixed = true) "Actual day of year";
  Integer daysOfYear(final start = dayOfTheYear(31, 12, startYear), fixed = true) "Total number of days of year";
  Integer year(final start = startYear, fixed = true) "Actual year";
  Modelica.Units.SI.Angle Jprime(final start=dayOfTheYear(
              startDay,
              startMonth,
              startYear)/dayOfTheYear(
              31,
              12,
              startYear)*2*pi, fixed=true)
    "Equivalent Angle of the day of the year w.r.t. total number of days";
  Real delta_J;
  Real timeequation_J;
  Modelica.Units.NonSI.Time_day localTimeDays "Local time in days";
  Integer localDays "Locale day";
  Modelica.Units.SI.Time localTime "Local time";
  Modelica.Units.NonSI.Time_hour localTimeHours
    "Local time in unit hours";
  Modelica.Units.NonSI.Time_hour LocalMeanTimeHours
    "Local mean time in unit hours";
  Modelica.Units.NonSI.Time_hour trueMeanTimeHours
    "True mean time in unit hours";
  Modelica.Units.SI.Angle hoursAngle "Hours angle";
  Modelica.Units.SI.Angle sunHeight "Sun height";
  Modelica.Units.SI.Angle sunAzimuth1 "Sun azimuth before 12 p.m.";
  Modelica.Units.SI.Angle sunAzimuth2 "Sun azimuth after 12 p.m.";
  Modelica.Units.SI.Angle sunAzimuth "Sun azimuth";
  Modelica.Units.SI.Angle angleOfIncidence
    "Angle of incidence between a vector in sun direction and a normal vector";
  Modelica.Units.SI.Irradiance directIrradianceHorizontal
    "Direct irradiance on the horizontal in W/m^2";
  Modelica.Units.SI.Irradiance directIrradianceInclined
    "Direct irradiance on the inclined plane in w/m^2";
  Modelica.Blocks.Interfaces.RealOutput irradiance "Irradiance of inclined area"
                                                   ;
algorithm
  // Calculate ratio of day w.r.t. total number of days of a year as equivalent angle
  when sample(24 * 3600, 24 * 3600) then
    dayOfYear := mod(pre(dayOfYear), pre(daysOfYear)) + 1;
  end when;
  when startDayOfYear + localDays == daysOfYear + 1 then
    startDayOfYear := 1;
    year := pre(year) + 1;
    daysOfYear := dayOfTheYear(31, 12, year);
  end when;
  // One full year is reached
  // Reset start day of year
  // Increment year
  // Determined actual number of total days of year
equation
  Jprime = dayOfYear / daysOfYear * 2 * pi;
  delta_J = rad(0.3948 - 23.2559 * cos(Jprime + rad(9.1)) - 0.3915 * cos(2 * Jprime + rad(5.4)) - 0.1764 * cos(3 * Jprime + rad(26)));
  timeequation_J = 0.0066 + 7.3525 * cos(Jprime + rad(85.9)) + 9.9359 * cos(2 * Jprime + rad(108.9)) + 0.3387 * cos(3 * Jprime + rad(105.2));
  // Zeit LZ = time
  localTime = time;
  // Convert time into unit hours
  localTimeHours = localTime / 3600;
  // Convert time into unit days
  localTimeDays = localTimeHours / 24;
  // Convert time from real days into integer days (floor)
  localDays = integer(floor(localTimeDays));
  // Calculate locale mean time
  LocalMeanTimeHours = localTimeHours - TimeZone + 4 / 60 * longitude * 180 / Modelica.Constants.pi;
  // cos(latitude)*tan(...)
  trueMeanTimeHours = LocalMeanTimeHours + timeequation_J / 60;
  hoursAngle = rad((12 - trueMeanTimeHours) * 15);
  sunHeight = degree(asin(cos(hoursAngle) * cos(latitude) * cos(delta_J) + sin(latitude) * sin(delta_J))) * (Modelica.Constants.pi / 180);
  sunAzimuth1 = Modelica.Constants.pi - acos((sin(sunHeight) * sin(latitude) - sin(delta_J)) / (cos(sunHeight) * cos(latitude)));
  sunAzimuth2 = Modelica.Constants.pi + acos((sin(sunHeight) * sin(latitude) - sin(delta_J)) / (cos(sunHeight) * cos(latitude)));
  sunAzimuth = if mod(localTimeHours, 24) <= 12 then sunAzimuth1 else sunAzimuth2;
  angleOfIncidence = acos((-cos(sunHeight) * sin(gamma) * cos(sunAzimuth - azimuth)) + sin(sunHeight) * cos(gamma));
  directIrradianceHorizontal = if sunHeight < 0 then 0 else irradianceRef * sin(sunHeight);
  directIrradianceInclined = if angleOfIncidence > pi / 2 then 0 else if abs(sin(sunHeight)) < 1E-5 then 0 else directIrradianceHorizontal * (cos(angleOfIncidence) / sin(sunHeight));
  irradiance = directIrradianceInclined
  ;
end Irradiance;

within PhotoVoltaics.Sources.Irradiance;
model IrradianceFixedSun "Simple solar irradiance with fixed sun position"
  import Modelica.Constants.pi;
  parameter Modelica.Units.SI.Irradiance irradianceRef=1000
    "Reference solar irradiance";
  parameter Modelica.Units.SI.Angle sunHeight "Sun height";
  parameter Modelica.Units.SI.Angle sunAzimuth "Sun azimuth";
  Modelica.Units.SI.Angle angleOfIncidence
    "Angle of incidence between a vector in sun direction and a normal vector";
  Modelica.Units.SI.Irradiance directIrradianceHorizontal
    "Direct irradiance on the horizontal";
  Modelica.Units.SI.Irradiance directIrradianceInclined
    "Direct irradiance on the inclined plane";
  Modelica.Blocks.Interfaces.RealOutput irradiance ;
  Modelica.Blocks.Interfaces.RealInput gamma ;
  Modelica.Blocks.Interfaces.RealInput azimuth ;
equation
  angleOfIncidence = acos((-cos(sunHeight) * sin(gamma) * cos(sunAzimuth - azimuth)) + sin(sunHeight) * cos(gamma));
  directIrradianceHorizontal = if sunHeight < 0 then 0 else irradianceRef * sin(sunHeight);
  directIrradianceInclined = if angleOfIncidence > pi / 2 then 0 else if abs(sin(sunHeight)) < 1E-5 then 0 else directIrradianceHorizontal * (cos(angleOfIncidence) / sin(sunHeight));
  irradiance = directIrradianceInclined
  ;
end IrradianceFixedSun;

within PhotoVoltaics.Sources.Irradiance;
model IrradianceVariableLocation "Simple solar irradiance without considering weather conditions"
  import Modelica.Constants.pi;
  import PhotoVoltaics.Functions.rad;
  import PhotoVoltaics.Functions.degree;
  import PhotoVoltaics.Functions.dayOfTheYear;
  parameter Integer startDay(final min = 1, final max = 31) = 10 "Day";
  parameter Integer startMonth(final min = 1, final max = 12) = 9 "Month";
  parameter Integer startYear = 2016 "Year";
  parameter Integer TimeZone = 1 "Time zone";
  parameter Modelica.Units.SI.Angle longitude=0.2856929452589518
    "Longitude";
  parameter Modelica.Units.SI.Angle latitude=0.8418964085999744
    "Latitude";
  parameter Modelica.Units.SI.Irradiance irradianceRef=1000
    "Reference solar irradiance";
  Integer startDayOfYear(start = dayOfTheYear(startDay, startMonth, startYear)) "Start day of year in simulation";
  Integer dayOfYear(final start = dayOfTheYear(startDay, startMonth, startYear)) "Actual day of year";
  Integer daysOfYear(final start = dayOfTheYear(31, 12, startYear)) "Total number of days of year";
  Integer year(final start = startYear) "Actual year";
  Modelica.Units.SI.Angle Jprime(final start=dayOfTheYear(
              startDay,
              startMonth,
              startYear)/dayOfTheYear(
              31,
              12,
              startYear)*2*pi)
    "Equivalent Angle of the day of the year w.r.t. total number of days";
  Real delta_J;
  Real timeequation_J;
  Modelica.Units.NonSI.Time_day localTimeDays "Local time in days";
  Integer localDays "Locale day";
  Modelica.Units.SI.Time localTime "Local time";
  Modelica.Units.NonSI.Time_hour localTimeHours
    "Local time in unit hours";
  Modelica.Units.NonSI.Time_hour LocalMeanTimeHours
    "Local mean time in unit hours";
  Modelica.Units.NonSI.Time_hour trueMeanTimeHours
    "True mean time in unit hours";
  Modelica.Units.SI.Angle hoursAngle "Hours angle";
  Modelica.Units.SI.Angle sunHeight "Sun height";
  Modelica.Units.SI.Angle sunAzimuth1 "Sun azimuth before 12 p.m.";
  Modelica.Units.SI.Angle sunAzimuth2 "Sun azimuth after 12 p.m.";
  Modelica.Units.SI.Angle sunAzimuth "Sun azimuth";
  Modelica.Units.SI.Angle angleOfIncidence
    "Angle of incidence between a vector in sun direction and a normal vector";
  Modelica.Units.SI.Irradiance directIrradianceHorizontal
    "Direct irradiance on the horizontal in W/m^2";
  Modelica.Units.SI.Irradiance directIrradianceInclined
    "Direct irradiance on the inclined plane in w/m^2";
  Modelica.Blocks.Interfaces.RealOutput irradiance "Irradiance of inclined area" ;
  Modelica.Blocks.Interfaces.RealInput gamma "Inclination angle of area" ;
  Modelica.Blocks.Interfaces.RealInput azimuth "Azimuth of area" ;
algorithm
  // Calculate ratio of day w.r.t. total number of days of a year as equivalent angle
  when sample(24 * 3600, 24 * 3600) then
    dayOfYear := mod(pre(dayOfYear), pre(daysOfYear)) + 1;
  end when;
  when startDayOfYear + localDays == daysOfYear + 1 then
    startDayOfYear := 1;
    year := pre(year) + 1;
    daysOfYear := dayOfTheYear(31, 12, year);
  end when;
  // One full year is reached
  // Reset start day of year
  // Increment year
  // Determined actual number of total days of year
equation
  Jprime = dayOfYear / daysOfYear * 2 * pi;
  delta_J = rad(0.3948 - 23.2559 * cos(Jprime + rad(9.1)) - 0.3915 * cos(2 * Jprime + rad(5.4)) - 0.1764 * cos(3 * Jprime + rad(26)));
  timeequation_J = 0.0066 + 7.3525 * cos(Jprime + rad(85.9)) + 9.9359 * cos(2 * Jprime + rad(108.9)) + 0.3387 * cos(3 * Jprime + rad(105.2));
  // Zeit LZ = time
  localTime = time;
  // Convert time into unit hours
  localTimeHours = localTime / 3600;
  // Convert time into unit days
  localTimeDays = localTimeHours / 24;
  // Convert time from real days into integer days (floor)
  localDays = integer(floor(localTimeDays));
  // Calculate locale mean time
  LocalMeanTimeHours = localTimeHours - TimeZone + 4 / 60 * longitude * 180 / Modelica.Constants.pi;
  // cos(latitude)*tan(...)
  trueMeanTimeHours = LocalMeanTimeHours + timeequation_J / 60;
  hoursAngle = rad((12 - trueMeanTimeHours) * 15);
  sunHeight = degree(asin(cos(hoursAngle) * cos(latitude) * cos(delta_J) + sin(latitude) * sin(delta_J))) * (Modelica.Constants.pi / 180);
  sunAzimuth1 = Modelica.Constants.pi - acos((sin(sunHeight) * sin(latitude) - sin(delta_J)) / (cos(sunHeight) * cos(latitude)));
  sunAzimuth2 = Modelica.Constants.pi + acos((sin(sunHeight) * sin(latitude) - sin(delta_J)) / (cos(sunHeight) * cos(latitude)));
  sunAzimuth = if mod(localTimeHours, 24) <= 12 then sunAzimuth1 else sunAzimuth2;
  angleOfIncidence = acos((-cos(sunHeight) * sin(gamma) * cos(sunAzimuth - azimuth)) + sin(sunHeight) * cos(gamma));
  directIrradianceHorizontal = if sunHeight < 0 then 0 else irradianceRef * sin(sunHeight);
  directIrradianceInclined = if angleOfIncidence > pi / 2 then 0 else if abs(sin(sunHeight)) < 1E-5 then 0 else directIrradianceHorizontal * (cos(angleOfIncidence) / sin(sunHeight));
  irradiance = directIrradianceInclined
  ;
end IrradianceVariableLocation;

within PlanarMechanics;
model PlanarWorld
  "Planar world coordinate system + gravity field + default animation definition"

  SI.Position r_0[3]
    "Position vector from world frame to the connector frame origin, resolved in world frame";
  MB.Frames.Orientation R
    "Orientation object to rotate the world frame into the connector frame";

  parameter SI.Acceleration[2] constantGravity={0,-9.81}
    "Constant gravity acceleration vector resolved in world frame" ;

  parameter Boolean enableAnimation=true
    "= true, if animation of all components is enabled" ;
  parameter Boolean animateWorld=true
    "= true, if world coordinate system shall be visualized" ;
  parameter Boolean animateGravity=true
    "= true, if gravity field shall be visualized (acceleration vector or field center)"
    ;
  parameter String label1="x" "Label of horizontal axis in icon" ;
  parameter String label2="y" "Label of vertical axis in icon" ;
  SI.Acceleration[2] g "Constant gravity acceleration vector resolved in world frame";

  parameter SI.Length axisLength=nominalLength/2 "Length of world axes arrows"
    ;
  parameter SI.Diameter axisDiameter=axisLength/defaultFrameDiameterFraction
    "Diameter of world axes arrows"
    ;
  parameter Boolean axisShowLabels=true "= true, if labels shall be shown"
    ;
  parameter MB.Types.Color axisColor_x=Types.Defaults.FrameColor
    "Color of x-arrow"
    ;
  parameter MB.Types.Color axisColor_y=axisColor_x "Color of y-arrow"
    ;
  parameter MB.Types.Color axisColor_z=axisColor_x "Color of z-arrow"
    ;

  parameter SI.Position gravityArrowTail[2]={0,0}
    "Position vector from origin of world frame to arrow tail, resolved in world frame"
    ;
  parameter SI.Length gravityArrowLength=axisLength/2 "Length of gravity arrow"
    ;
  parameter SI.Diameter gravityArrowDiameter=gravityArrowLength/
      defaultWidthFraction "Diameter of gravity arrow" ;
  parameter MB.Types.Color gravityArrowColor={0,180,0} "Color of gravity arrow" ;

  parameter SI.Length defaultZPosition=0
    "Default for z positions of all the elements"
    ;
  parameter SI.Length nominalLength=1 "\"Nominal\" length of PlanarMechanics"
    ;
  parameter SI.Length defaultJointLength=nominalLength/10
    "Default for the fixed length of a shape representing a joint"
    ;
  parameter SI.Length defaultJointWidth=nominalLength/10
    "Default for the fixed width of a shape representing a joint"
    ;
  parameter SI.Diameter defaultBodyDiameter=nominalLength/9
    "Default for diameter of sphere representing the center of mass of a body"
    ;
  parameter Real defaultWidthFraction=20
    "Default for shape width as a fraction of shape length (e.g., for Parts.FixedTranslation)"
    ;
  parameter SI.Diameter defaultArrowDiameter=nominalLength/40
    "Default for arrow diameter (e.g., of forces, torques, sensors)"
    ;
  parameter SI.Length defaultForceLength=nominalLength/10
    "Default for the fixed length of a shape representing a force (e.g., damper)"
    ;
  parameter SI.Length defaultForceWidth=nominalLength/20
    "Default for the fixed width of a shape representing a force (e.g., spring, bushing)"
    ;
  parameter Real defaultFrameDiameterFraction=40
    "Default for arrow diameter of a coordinate system as a fraction of axis length"
    ;
  parameter MB.Types.SpecularCoefficient defaultSpecularCoefficient(min=0) = 0.7
    "Default reflection of ambient light (= 0: light is completely absorbed)"
    ;
  parameter Real defaultN_to_m(unit="N/m", min=0) = 1000
    "Default scaling of force arrows (length = force/defaultN_to_m)"
    ;
  parameter Real defaultNm_to_m(unit="N.m/m", min=0) = 1000
    "Default scaling of torque arrows (length = torque/defaultNm_to_m)"
    ;

protected
  parameter Integer ndim=if enableAnimation and animateWorld then 1 else 0;
  parameter Integer ndim2=if enableAnimation and animateWorld and
      axisShowLabels then 1 else 0;

  // Parameters to define axes labels
  parameter SI.Length scaledLabel=Modelica.Mechanics.MultiBody.Types.Defaults.FrameLabelHeightFraction*
      axisDiameter;
  parameter SI.Length labelStart=1.05*axisLength;

  // coordinate system
protected
  Visualizers.Internal.CoordinateSystem coordinateSystem(
    r=r_0,
    R=R,
    r_shape=zeros(3),
    axisLength=axisLength,
    axisDiameter=axisDiameter,
    axisShowLabels=axisShowLabels,
    scaledLabel=scaledLabel,
    labelStart=labelStart,
    color_x=axisColor_x,
    color_y=axisColor_y,
    color_z=axisColor_z) if enableAnimation and animateWorld;
  // gravity visualization
  Visualizers.Internal.Arrow gravityArrow(
    r=r_0,
    R=R,
    r_tail={gravityArrowTail[1],gravityArrowTail[2],0},
    r_head=gravityArrowLength*Modelica.Math.Vectors.normalize({g[1],g[2],0}),
    diameter=gravityArrowDiameter,
    color=gravityArrowColor,
    specularCoefficient=0) if enableAnimation and animateGravity;

equation
  r_0 = {0,0,0};
  R = MB.Frames.nullRotation();

  g = constantGravity

    ;
end PlanarWorld;

within PlanarMechanics;
model PlanarWorldIn3D
  "Planar world coordinate system + gravity field + default animation definition"

  MB.Interfaces.Frame_a MBFrame_a if connectToMultiBody
    ;

  SI.Position r_0[3]
    "Position vector from world frame to the connector frame origin, resolved in world frame";
  MB.Frames.Orientation R
    "Orientation object to rotate the world frame into the connector frame";

