  connect(prismatic.frame_b, body1.frame_a) ;
  connect(prismatic.flange_a, force.flange) ;
  connect(prismatic.frame_b, revolute.frame_a) ;
  connect(revolute.frame_b, fixedTranslation.frame_a) ;
  connect(revolute.flange_a, angleSensor.flange) 
  ;
