    R=planarWorld.R) if planarWorld.enableAnimation and animate;
  MB.Visualizers.Advanced.Shape rim1(
    shapeType="cylinder",
    color={195,195,195},
    specularCoefficient=0.5,
    length=R*2,
    width=0.1,
    height=0.1,
    lengthDirection={1,0,0},
    widthDirection={0,0,1},
    r_shape={-R,0,0},
    r=MB.Frames.resolve1(planarWorld.R,{frame_a.x,frame_a.y,0})+planarWorld.r_0,
    R=MB.Frames.absoluteRotation(planarWorld.R,MB.Frames.planarRotation({0,0,1},phi,0)))
    if planarWorld.enableAnimation and animate;
  MB.Visualizers.Advanced.Shape rim2(
    shapeType="cylinder",
    color={195,195,195},
    specularCoefficient=0.5,
    length=R*2,
    width=0.1,
    height=0.1,
    lengthDirection={1,0,0},
    widthDirection={0,0,1},
    r_shape={-R,0,0},
    r=MB.Frames.resolve1(planarWorld.R,{frame_a.x,frame_a.y,0})+planarWorld.r_0,
    R=MB.Frames.absoluteRotation(planarWorld.R,MB.Frames.planarRotation({0,0,1},phi-Modelica.Constants.pi/2,0)))
    if planarWorld.enableAnimation and animate;
initial equation

equation
  //Differential Equations
  x = frame_a.x;
  phi = frame_a.phi;
  w = der(phi);
  z = der(w);
  vx = der(frame_a.x);
  //holonomic constraint
  frame_a.y = R;
  //non-holonomic constraint
  vx = -w*R;
  //balance forces
  frame_a.fx*R = frame_a.t

  ;
end IdealRolling;

within PlanarMechanics.Joints;
model Prismatic "A prismatic joint"
  extends PlanarMechanics.Interfaces.PartialTwoFrames;

  parameter Boolean useFlange=false
    "= true, if force flange enabled, otherwise implicitly grounded"
    ;
  parameter Boolean animate = true "= true, if animation shall be enabled" ;
  parameter StateSelect stateSelect=StateSelect.default
    "Priority to use s and v as states" ;

  parameter SI.Position r[2] "Direction of the rod wrt. body system at phi=0";
  final parameter SI.Length l = Modelica.Math.Vectors.length(r) "Length of r";
  final parameter Real e[2](each final unit="1") = Modelica.Math.Vectors.normalizeWithAssert(r)
    "Unit vector in direction of r";

  Modelica.Mechanics.Translational.Interfaces.Flange_a flange_a(f = f, s = s) if useFlange
   ;

  Modelica.Mechanics.Translational.Interfaces.Flange_b support if useFlange
    "1-dim. translational flange of the drive support (assumed to be fixed in the world frame, NOT in the joint)"
    ;

  parameter SI.Length zPosition = planarWorld.defaultZPosition
    "Position z of the prismatic joint box" ;
  parameter SI.Distance boxWidth=l/planarWorld.defaultWidthFraction
    "Width of prismatic joint box"
    ;
  input MB.Types.Color boxColor=Types.Defaults.JointColor
    "Color of prismatic joint box"
    ;
  input MB.Types.SpecularCoefficient specularCoefficient = planarWorld.defaultSpecularCoefficient
    "Reflection of ambient light (= 0: light is completely absorbed)"
    ;

  SI.Position s(final stateSelect = stateSelect, start = 0)
    "Elongation of the joint" ;
  SI.Velocity v(final stateSelect = stateSelect, start = 0)
    "Velocity of elongation" ;
  SI.Acceleration a(start = 0) "Acceleration of elongation" ;
  SI.Force f "Force in direction of elongation";
  Real e0[2] "Unit vector in direction of r resolved w.r.t. inertial frame";
  SI.Position r0[2]
    "Translation vector of the prismatic rod resolved w.r.t. inertial frame";
  Real R[2,2] "Rotation matrix";

  //Visualization
  MB.Visualizers.Advanced.Shape box(
    shapeType="box",
    color=boxColor,
    specularCoefficient=specularCoefficient,
    length=s,
    width=boxWidth,
    height=boxWidth,
    lengthDirection={e0[1],e0[2],0},
    widthDirection={0,0,1},
    r_shape={frame_a.x,frame_a.y,zPosition},
    r=planarWorld.r_0,
    R=planarWorld.R) if planarWorld.enableAnimation and animate;

protected
  Modelica.Mechanics.Translational.Components.Fixed fixed
    ;

equation
  //resolve the rod w.r.t. inertial system
  R = {{cos(frame_a.phi), -sin(frame_a.phi)}, {sin(frame_a.phi),cos(frame_a.phi)}};
  e0 = R*e;
  r0 = e0*s;
  //differential equations
  v = der(s);
  a = der(v);
  //actuation force
  if not useFlange then
    f = 0;
  end if;
  //rigidly connect positions
  frame_a.x + r0[1] = frame_b.x;
  frame_a.y + r0[2] = frame_b.y;
  frame_a.phi = frame_b.phi;
  //balance forces including lever principle
  frame_a.fx + frame_b.fx = 0;
  frame_a.fy + frame_b.fy = 0;
  frame_a.t  + frame_b.t + r0*{frame_b.fy,-frame_b.fx} = 0;
  {frame_a.fx,frame_a.fy}*e0 = f;

  connect(fixed.flange,support)  
  ;
end Prismatic;

within PlanarMechanics.Joints;
model Revolute "A revolute joint"
  extends PlanarMechanics.Interfaces.PartialTwoFrames;

  parameter Boolean useFlange=false
    "= true, if force flange enabled, otherwise implicitly grounded"
    ;
  parameter Boolean animate = true "= true, if animation shall be enabled" ;
  parameter StateSelect stateSelect=StateSelect.default
    "Priority to use phi and w as states" ;

  Modelica.Mechanics.Rotational.Interfaces.Flange_a flange_a(phi = phi, tau = t) if useFlange ;

  Modelica.Mechanics.Rotational.Interfaces.Flange_b support if useFlange
    "1-dim. rotational flange of the drive support (assumed to be fixed in the world frame, NOT in the joint)"
    ;

  parameter SI.Length zPosition = planarWorld.defaultZPosition
    "Position z of cylinder representing the joint axis" ;
  parameter SI.Distance cylinderLength=planarWorld.defaultJointLength
    "Length of cylinder representing the joint axis"
    ;
  parameter SI.Distance cylinderDiameter=planarWorld.defaultJointWidth
    "Diameter of cylinder representing the joint axis"
    ;
  input MB.Types.Color cylinderColor=Types.Defaults.JointColor
    "Color of cylinder representing the joint axis"
    ;
  input MB.Types.SpecularCoefficient specularCoefficient = planarWorld.defaultSpecularCoefficient
    "Reflection of ambient light (= 0: light is completely absorbed)"
    ;
  parameter Boolean extraLine=false
    "Enable black line in the cylinder to show the joint rotation"
    ;

  SI.Angle phi(final stateSelect = stateSelect, start = 0) "Angular position"
    ;
  SI.AngularVelocity w(final stateSelect = stateSelect, start = 0)
    "Angular velocity"
    ;
  SI.AngularAcceleration z(start = 0) "Angular acceleration" ;
  SI.Torque t "Torque";

  // The following is defined in order to omit if-statements in visualization block (cylinder)
protected
  final Modelica.Mechanics.MultiBody.Types.ShapeExtra extra=if extraLine then 1 else 0
    "Extra parameter to visualize black line in visualized cylinder" ;

  //Visualization
public
  MB.Visualizers.Advanced.Shape cylinder(
    shapeType="cylinder",
    color=cylinderColor,
    specularCoefficient=specularCoefficient,
    length=cylinderLength,
    width=cylinderDiameter,
    height=cylinderDiameter,
    lengthDirection={0,0,1},
    widthDirection={1,0,0},
    r_shape={0,0,-cylinderLength/2},
    r=MB.Frames.resolve1(planarWorld.R,{frame_a.x,frame_a.y,zPosition})+planarWorld.r_0,
    R=MB.Frames.absoluteRotation(planarWorld.R,MB.Frames.planarRotation({0,0,1}, phi, w)),
    extra=extra) if planarWorld.enableAnimation and animate;

protected
  Modelica.Mechanics.Rotational.Components.Fixed fixed
    "support flange is fixed to ground"
    ;

equation
  //Differential Equations
  w = der(phi);
  z = der(w);
  //actutation torque
  if not useFlange then
    t = 0;
  end if;
  //rigidly connect positions
  frame_a.x = frame_b.x;
  frame_a.y = frame_b.y;
  frame_a.phi + phi = frame_b.phi;
  //balance forces
  frame_a.fx + frame_b.fx = 0;
  frame_a.fy + frame_b.fy = 0;
  frame_a.t + frame_b.t = 0;
  frame_a.t = t;
  connect(fixed.flange,support)  
  ;
end Revolute;

within PlanarMechanics.Parts;
model Body "Body component with mass and inertia"

  Interfaces.Frame_a frame_a
    ;
  outer PlanarWorld planarWorld "planar world model";
  parameter Boolean animate = true "= true, if animation shall be enabled" ;
  parameter StateSelect stateSelect=StateSelect.default
    "Priority to use phi, w and a as states" ;
  parameter SI.Mass m "Mass of the body";
  parameter SI.Inertia I
    "Inertia of the body with respect to the origin of frame_a along the z-axis of frame_a";
  parameter SI.Length zPosition = planarWorld.defaultZPosition
    "Position z of the body" ;
  parameter SI.Diameter sphereDiameter=planarWorld.defaultBodyDiameter
    "Diameter of sphere" ;
  parameter Boolean enableGravity = true
    "= true, if gravity effects should be taken into account" ;
  input MB.Types.Color sphereColor=Types.Defaults.BodyColor "Color of sphere"
    ;
  input MB.Types.SpecularCoefficient specularCoefficient = planarWorld.defaultSpecularCoefficient
    "Reflection of ambient light (= 0: light is completely absorbed)"
    ;
  SI.Force f[2] "Force";
  SI.Position r[2](each final stateSelect=stateSelect, start={0,0}) "Translational position"
    ;
  SI.Velocity v[2](each final stateSelect=stateSelect, start={0,0}) "Velocity" ;
  SI.Acceleration a[2](start={0,0}) "Acceleration" ;
  SI.Angle phi(final stateSelect=stateSelect, start=0) "Angle" ;
  SI.AngularVelocity w(final stateSelect=stateSelect, start = 0) "Angular velocity"
    ;
  SI.AngularAcceleration z(start = 0) "Angular acceleration"
    ;
  //Visualization
  MB.Visualizers.Advanced.Shape sphere(
    shapeType="sphere",
    color=sphereColor,
    specularCoefficient=specularCoefficient,
    length=sphereDiameter,
    width=sphereDiameter,
    height=sphereDiameter,
    lengthDirection={0,0,1},
    widthDirection={1,0,0},
    r_shape={0,0,0} -{0,0,1}*sphereDiameter/2,
    r=MB.Frames.resolve1(planarWorld.R,{frame_a.x,frame_a.y,zPosition})+planarWorld.r_0,
    R=MB.Frames.absoluteRotation(planarWorld.R,MB.Frames.axisRotation(3,frame_a.phi,w)))
    if planarWorld.enableAnimation and animate;
equation
  //The velocity is a time-derivative of the position
  r = {frame_a.x, frame_a.y};
  v = der(r);
  phi = frame_a.phi;
  w = der(phi);
  //The acceleration is a time-derivative of the velocity
  a = der(v);
  z = der(w);
  //Newton's law
  f = {frame_a.fx, frame_a.fy};
  if enableGravity then
    f + m*planarWorld.g = m*a;
  else
    f = m*a;
  end if;
  frame_a.t = I*z
  ;
end Body;

within PlanarMechanics.Parts;
model Damper "Linear (velocity dependent) damper"
  extends BaseClasses.TwoConnectorShapes;
  extends Modelica.Thermal.HeatTransfer.Interfaces.PartialElementaryConditionalHeatPort(
    final T=293.15);
  parameter StateSelect stateSelect=StateSelect.default
    "Priority to use phi and w as states" ;
  parameter SI.TranslationalDampingConstant d=1 "Damping constant";
  SI.Length[2] r0(each final stateSelect=stateSelect,start={0,0});
  Real[2] d0;
  SI.Velocity vx(start = 0);
  SI.Velocity vy(start = 0);
  SI.Velocity v;
  SI.Force f;
  parameter SI.Position s_small = 1.E-10
    "Prevent zero-division by regularization if distance between frame_a and frame_b is zero"
    ;

  parameter Boolean enableAssert = false
    "Cause an assert when the distance between frame_a and frame_b < s_small" ;

  //Visualization
  parameter SI.Length length_a = planarWorld.defaultForceLength
    "Length of cylinder at frame_a side"
    ;
  input SI.Diameter diameter_a = planarWorld.defaultForceWidth
    "Diameter of cylinder at frame_a side"
    ;
  input SI.Diameter diameter_b = 0.6*diameter_a
    "Diameter of cylinder at frame_b side"
    ;
  input MB.Types.Color color_a = {0,127,255} "Color of cylinder at frame_a side"
    ;
  input MB.Types.Color color_b = {0,64,200} "Color of cylinder at frame_b side"
    ;

  SI.Distance length
    "Distance between the origin of frame_a and the origin of frame_b";
protected
  SI.Position r0_b[3] = {d0[1], d0[2], 0} * noEvent(min(length_a, length));
  MB.Visualizers.Advanced.Shape cylinder_a(
    shapeType="cylinder",
    color=color_a,
    specularCoefficient=specularCoefficient,
    length=noEvent(min(length_a, length)),
    width=diameter_a,
    height=diameter_a,
    lengthDirection={d0[1], d0[2], 0},
    widthDirection={0,0,1},
    r=MB.Frames.resolve1(planarWorld.R,{frame_a.x,frame_a.y,zPosition})+planarWorld.r_0,
    R=planarWorld.R) if planarWorld.enableAnimation and animate;
  MB.Visualizers.Advanced.Shape cylinder_b(
    shapeType="cylinder",
    color=color_b,
    specularCoefficient=specularCoefficient,
    length=noEvent(max(length - length_a, 0)),
    width=diameter_b,
    height=diameter_b,
    lengthDirection={r0[1], r0[2], 0},
    widthDirection={0,0,1},
    r_shape=r0_b,
    r=MB.Frames.resolve1(planarWorld.R,{frame_a.x,frame_a.y,zPosition})+planarWorld.r_0,
    R=planarWorld.R) if planarWorld.enableAnimation and animate;

equation
  if enableAssert then
    assert(noEvent(length > s_small), "
 The distance between the origin of frame_a and the origin of frame_b
 of a Spring component became smaller as parameter s_small
 (= a small number, defined in the \"Advanced\" menu). The distance is
 set to s_small, although it is smaller, to avoid a division by zero
 when computing the direction of the line force. Possible reasons
 for this situation:
 - At initial time the distance may already be zero: Change the initial
   positions of the bodies connected by this element.
 - Hardware stops are not modeled or are modeled not stiff enough.
   Include stops, e.g., stiff springs, or increase the stiffness
   if already present.
 - Another error in your model may lead to unrealistically large forces
   and torques that would in reality destroy the stops.
 - The flange_b connector might be defined by a pre-defined motion,
   e.g., with Modelica.Mechanics.Translational.Position and the
   predefined flange_b.s is zero or negative.
 ");
  end if;

  length = Modelica.Math.Vectors.length(r0);
  frame_a.x + r0[1] = frame_b.x;
  frame_a.y + r0[2] = frame_b.y;
  d0= Modelica.Math.Vectors.normalize({r0[1],r0[2]},s_small);
  der(frame_a.x) + vx = der(frame_b.x);
  der(frame_a.y) + vy = der(frame_b.y);
  v = {vx,vy}*d0;
  f = -d*v;
  frame_a.fx = d0[1] * f;
  frame_a.fy = d0[2] * f;
  frame_a.t = 0;
  frame_a.fx + frame_b.fx = 0;
  frame_a.fy + frame_b.fy = 0;
  frame_a.t + frame_b.t = 0;

  lossPower = -f*v

  ;
end Damper;

within PlanarMechanics.Parts;
model Fixed
  "Frame fixed in the planar world frame at a given position and orientation"

  parameter SI.Position r[2] = {0,0}
    "Fixed absolute x,y-position, resolved in planarWorld frame";
  parameter SI.Angle phi = 0 "Fixed angle";

  Interfaces.Frame_b frame
    ;
equation
  {frame.x,frame.y} = r;
  frame.phi = phi
  ;
end Fixed;

within PlanarMechanics.Parts;
model FixedRotation "A fixed translation between two components (rigid rod)"
  extends PlanarMechanics.Interfaces.PartialTwoFrames;

  parameter SI.Angle alpha "Fixed rotation angle";
  parameter Boolean animate = true "= true, if animation shall be enabled"
    ;
  parameter SI.Length zPosition = planarWorld.defaultZPosition
    "Position z of cylinder representing the fixed rotation" ;
  parameter SI.Length cylinderLength=planarWorld.defaultJointLength
    "Length of cylinder representing the fixed rotation"
    ;
  parameter SI.Length cylinderDiameter=planarWorld.defaultJointWidth
    "Diameter of cylinder representing the fixed rotation"
    ;
  input MB.Types.Color color=Types.Defaults.RodColor
    "Color of cylinder representing the fixed rotation"
    ;
  input MB.Types.SpecularCoefficient
    specularCoefficient = planarWorld.defaultSpecularCoefficient
    "Reflection of ambient light (= 0: light is completely absorbed)"
    ;
  //Visualization
  MB.Visualizers.Advanced.Shape cylinder(
    shapeType="cylinder",
    color=color,
    specularCoefficient=specularCoefficient,
    length=cylinderLength,
    width=cylinderDiameter,
    height=cylinderDiameter,
    lengthDirection={0,0,1},
    widthDirection={1,0,0},
    r_shape={0,0,-0.05},
    r=MB.Frames.resolve1(planarWorld.R,{frame_a.x,frame_a.y,zPosition})+planarWorld.r_0,
    R=planarWorld.R) if planarWorld.enableAnimation and animate;
equation
  frame_a.x = frame_b.x;
  frame_a.y = frame_b.y;
  frame_a.phi + alpha = frame_b.phi;
  frame_a.fx + frame_b.fx = 0;
  frame_a.fy + frame_b.fy = 0;
  frame_a.t + frame_b.t = 0
  ;
end FixedRotation;

within PlanarMechanics.Parts;
model FixedTranslation "A fixed translation between two components (rigid rod)"
  extends PlanarMechanics.Interfaces.PartialTwoFrames;

  parameter SI.Length r[2] = {1,0}
    "Fixed x,y-length of the rod resolved w.r.t to body frame_a at phi = 0";
  final parameter SI.Length l = Modelica.Math.Vectors.length(r)
    "Length of vector r";
  SI.Position r0[2] "Length of the rod resolved w.r.t to inertal frame";
  Real R[2,2] "Rotation matrix from world frame to frame_a";

  parameter Boolean animate = true "= true, if animation shall be enabled"
    ;
  parameter SI.Length zPosition = planarWorld.defaultZPosition
    "Position z of cylinder representing the fixed translation" ;
  parameter SI.Distance width=l/planarWorld.defaultWidthFraction
    "Width of shape"
    ;
  input MB.Types.Color color=Types.Defaults.RodColor
    "Color of shape" ;
  input MB.Types.SpecularCoefficient
    specularCoefficient = planarWorld.defaultSpecularCoefficient
    "Reflection of ambient light (= 0: light is completely absorbed)"
    ;
  //Visualization
  MB.Visualizers.Advanced.Shape cylinder(
    shapeType="cylinder",
    color=color,
    specularCoefficient=specularCoefficient,
    length=l,
    width=width,
    height=width,
    lengthDirection={r0[1]/l,r0[2]/l,0},
    widthDirection={0,0,1},
    r_shape={0,0,0},
    r=MB.Frames.resolve1(planarWorld.R,{frame_a.x,frame_a.y,zPosition})+planarWorld.r_0,
    R=planarWorld.R) if planarWorld.enableAnimation and animate;
equation
  //resolve the rod w.r.t inertial system
//  sx0 = cos(frame_a.phi)*sx + sin(frame_a.phi)*sy;
//  sy0 = -sin(frame_a.phi)*sx + cos(frame_a.phi)*sy;
  R = {{cos(frame_a.phi), -sin(frame_a.phi)}, {sin(frame_a.phi),cos(frame_a.phi)}};
  r0 = R*r;
  //rigidly connect positions
  frame_a.x + r0[1] = frame_b.x;
  frame_a.y + r0[2] = frame_b.y;
  frame_a.phi = frame_b.phi;
  //balance forces including lever principle
  frame_a.fx + frame_b.fx = 0;
  frame_a.fy + frame_b.fy = 0;
//  frame_a.t + frame_b.t - sx0*frame_b.fy + sy0*frame_b.fx = 0;
  frame_a.t + frame_b.t + r0*{frame_b.fy,-frame_b.fx} = 0
  ;
end FixedTranslation;

within PlanarMechanics.Parts;
model Spring "Linear 2D translational spring"
  extends BaseClasses.TwoConnectorShapes;

  parameter StateSelect stateSelect=StateSelect.default
    "Priority to use phi and w as states" ;
  parameter SI.TranslationalSpringConstant c_x(final min=0, start=1)
    "Spring constant in x dir";
  parameter SI.TranslationalSpringConstant c_y(final min=0, start=1)
    "Spring constant in y dir";
  parameter SI.RotationalSpringConstant c_phi(final min=0, start=1.0e5)
    "Spring constant";
  parameter SI.Position s_relx0=0 "Unstretched spring length";
  parameter SI.Position s_rely0=0 "Unstretched spring length";
  parameter SI.Angle phi_rel0=0 "Unstretched spring angle";

  SI.Position s_relx(final stateSelect=stateSelect, start = 0) "Spring length"
    ;
  SI.Position s_rely(final stateSelect=stateSelect, start = 0) "Spring length"
    ;

  SI.Angle phi_rel(final stateSelect=stateSelect, start = 0) "Spring angle"
                   ;
  SI.Force f_x "Force in x direction";
  SI.Force f_y "Force in y direction";

  parameter SI.Position s_small = 1.E-10
    "Prevent zero-division if distance between frame_a and frame_b is zero" ;

  parameter Boolean enableAssert = true
    "Cause an assert when the distance between frame_a and frame_b < s_small" ;

  //Visualization
  parameter Integer numberOfWindings = 5 "Number of spring windings"
    ;
  input SI.Length width = planarWorld.defaultJointWidth "Width of spring"
    ;
  input SI.Length coilWidth = width/10 "Width of spring coil"
    ;
  input MB.Types.Color color = Types.Defaults.SpringColor "Color of spring"
    ;

  SI.Length length
    "Distance between the origin of frame_a and the origin of frame_b";
  SI.Position r_rel_0[3]
    "Position vector (3D) from frame_a to frame_b resolved in multibody world frame";
  Real e_rel_0[3](each final unit="1")
    "Unit vector (3D) in direction from frame_a to frame_b, resolved in multibody world frame";

protected
  MB.Visualizers.Advanced.Shape shapeCoil(
    shapeType="spring",
    color=color,
    specularCoefficient=specularCoefficient,
    length=length,
    width=width,
    height=coilWidth*2,
    lengthDirection=e_rel_0,
    widthDirection= {0,1,0},
    extra=numberOfWindings,
    r=MB.Frames.resolve1(planarWorld.R,{frame_a.x,frame_a.y,zPosition})+planarWorld.r_0,
    R=planarWorld.R) if planarWorld.enableAnimation and animate;
equation

  if enableAssert then
    assert(noEvent(length > s_small), "
The distance between the origin of frame_a and the origin of frame_b
of a Spring component became smaller as parameter s_small
(= a small number, defined in the \"Advanced\" menu). The distance is
set to s_small, although it is smaller, to avoid a division by zero
when computing the direction of the line force. Possible reasons
for this situation:
- At initial time the distance may already be zero: Change the initial
  positions of the bodies connected by this element.
- Hardware stops are not modeled or are modeled not stiff enough.
  Include stops, e.g., stiff springs, or increase the stiffness
  if already present.
- Another error in your model may lead to unrealistically large forces
  and torques that would in reality destroy the stops.
- The flange_b connector might be defined by a pre-defined motion,
  e.g., with Modelica.Mechanics.Translational.Position and the
  predefined flange_b.s is zero or negative.
",    level = AssertionLevel.warning);
  end if;

  r_rel_0 = {s_relx, s_rely, 0};
  length = Modelica.Math.Vectors.length(r_rel_0);
  e_rel_0 = r_rel_0/Modelica.Mechanics.MultiBody.Frames.Internal.maxWithoutEvent(length, s_small);

  phi_rel = frame_b.phi - frame_a.phi;
  frame_a.t = 0;
  frame_b.t = 0;
  s_relx = frame_b.x-frame_a.x;
  s_rely = frame_b.y-frame_a.y;
  f_x = c_x*(s_relx - s_relx0);
  f_y = c_y*(s_rely - s_rely0);
  frame_a.fx = -f_x;
  frame_b.fx = f_x;
  frame_a.fy = -f_y;
  frame_b.fy = f_y

  ;
end Spring;

within PlanarMechanics.Sensors;
model AbsoluteAcceleration
  "Measure absolute acceleration of origin of frame connector"
  extends Internal.PartialAbsoluteSensor;

  Modelica.Blocks.Interfaces.RealOutput a[3](
    final quantity = {"Acceleration", "Acceleration", "AngularAcceleration"},
    final unit = {"m/s2", "m/s2", "rad/s2"})
    "Vector of absolute measurements of frame_a on acceleration level, resolved in frame defined by resolveInFrame"
    ;
  Interfaces.Frame_resolve frame_resolve
    if resolveInFrame == Modelica.Mechanics.MultiBody.Types.ResolveInFrameA.frame_resolve
    "Coordinate system in which output vector v is optionally resolved"
    ;

  parameter Modelica.Mechanics.MultiBody.Types.ResolveInFrameA resolveInFrame=
    Modelica.Mechanics.MultiBody.Types.ResolveInFrameA.frame_a
    "Frame in which output vector v shall be resolved (1: world, 2: frame_a, 3: frame_resolve)";

protected
  Internal.BasicAbsolutePosition position(
    resolveInFrame=Modelica.Mechanics.MultiBody.Types.ResolveInFrameA.world)
    ;
  Modelica.Blocks.Continuous.Der der1[3] ;
  TransformAbsoluteVector transformAbsoluteVector(
    frame_r_in=position.resolveInFrame,
    frame_r_out=resolveInFrame) ;
  Interfaces.ZeroPosition zeroPosition
    ;
  Interfaces.ZeroPosition zeroPosition1 if not (
    resolveInFrame == Modelica.Mechanics.MultiBody.Types.ResolveInFrameA.frame_resolve)
    ;
  Modelica.Blocks.Continuous.Der der2[3] ;
equation
  connect(position.r, der1.u) ;
  connect(position.frame_a, frame_a) ;
  connect(zeroPosition.frame_resolve, position.frame_resolve) ;
  connect(transformAbsoluteVector.frame_a, frame_a) ;
  connect(transformAbsoluteVector.frame_resolve, zeroPosition1.frame_resolve)
    ;
  connect(transformAbsoluteVector.frame_resolve, frame_resolve) ;

  connect(der1.y, der2.u) ;
  connect(der2.y, transformAbsoluteVector.r_in) ;
  connect(transformAbsoluteVector.r_out, a) 
  ;
end AbsoluteAcceleration;

within PlanarMechanics.Sensors;
model AbsolutePosition
  "Measure absolute position and orientation of the origin of frame connector"
  extends Internal.PartialAbsoluteSensor;

  Modelica.Blocks.Interfaces.RealOutput r[3](
    final quantity = {"Position", "Position", "Angle"},
    final unit = {"m", "m", "rad"})
    "Vector of absolute measurements of frame_a on position level, resolved in frame defined by resolveInFrame"
    ;
  Interfaces.Frame_resolve frame_resolve if resolveInFrame ==
    Modelica.Mechanics.MultiBody.Types.ResolveInFrameA.frame_resolve
