  else
    FrameB := Modelica.Mechanics.MultiBody.Types.ResolveInFrameB.frame_resolve;
  end if

  ;
end fromFrameAtoFrameB;

within PlanarMechanics.Utilities.Functions;
function atan3b
  "Obsolete function: Four quadrant inverse tangent (select solution that is closest to given angle y0)"
  import Modelica.Math;
  extends Modelica.Math.Icons.AxisCenter;
  extends Modelica.Icons.ObsoleteModel;
  input Real u1;
  input Real u2;
  input SI.Angle y0=0 "y shall be in the range: -pi < y-y0 < pi";
  output SI.Angle y;
protected
  Real pi = Modelica.Constants.pi;
  Real w;
algorithm
  w :=Math.atan2(u1, u2);
  y := w + 2*pi*div(abs(w-y0)+pi,2*pi)*(if y0 > w then +1 else -1)
  ;
end atan3b;

within PlanarMechanics.Utilities.Functions;
function atan3b_dder "Obsolete function: Second deviation of atan3"
  extends Modelica.Icons.Function;
  extends Modelica.Icons.ObsoleteModel;

  import Modelica.Math;
  input Real u1;
  input Real u2;
  input SI.Angle y0=0 "y shall be in the range: -pi < y-y0 < pi";
  input Real u1_der;
  input Real u2_der;
  input Real u1_dder;
  input Real u2_dder;
  output SI.AngularAcceleration y_dder;
algorithm
  y_dder := (2*u1*u2/((u1*u1+u2*u2)*(u1*u1+u2*u2)))*u2_der - (2*u1*u2/((u1*u1+u2*u2)*(u1*u1+u2*u2)))*u1_der

  ;
end atan3b_dder;

within PlanarMechanics.Utilities.Functions;
function atan3b_der "Obsolete function: First deviation of atan3"
  extends Modelica.Icons.Function;
  extends Modelica.Icons.ObsoleteModel;

  import Modelica.Math;
  input Real u1;
  input Real u2;
  input SI.Angle y0=0 "y shall be in the range: -pi < y-y0 < pi";
  input Real u1_der;
  input Real u2_der;
  output SI.AngularVelocity y_der;
algorithm
  y_der := u2/(u1*u1+u2*u2)*u1_der - u1/(u1*u1+u2*u2)*u2_der
  ;
end atan3b_der;

within PlanarMechanics.Utilities.Functions;
function limitBySform "Returns a S-shaped transition"
  extends Modelica.Icons.Function;

  input Real x_min "Abscissa for y_min";
  input Real x_max "Abscissa for y_max";
  input Real y_min "First value of y";
  input Real y_max "Second value of y";
  input Real x "Current abscissa value";
  output Real y "Current ordinate";
protected
  Real x2;
algorithm
  x2 := x - x_max/2 - x_min/2;
  x2 := x2*2/(x_max-x_min);
  if x2 > 1 then
    y := 1;
  elseif x2 < -1 then
    y := -1;
  else
    y := -0.5*x2^3 + 1.5*x2;
  end if;
  y := y*(y_max-y_min)/2;
  y := y + y_max/2 + y_min/2

  ;
end limitBySform;

within PlanarMechanics.Utilities.Functions;
function limitByStriple "Returns a point-symmetric Triple S-Function"
  extends Modelica.Icons.Function;

  input Real x_max "Abscissa for y_max";
  input Real x_sat "Abscissa for y_sat";
  input Real y_max "Peak ordinate";
  input Real y_sat "Saturated ordinate";
  input Real x "Current abscissa value";
  output Real y "Current ordinate";
algorithm
  if x > x_max then
    y :=Functions.limitBySform(
      x_max,
      x_sat,
      y_max,
      y_sat,
      x);
  elseif x < -x_max then
    y :=Functions.limitBySform(
      -x_max,
      -x_sat,
      -y_max,
      -y_sat,
      x);
  else
    y :=Functions.limitBySform(
      -x_max,
      x_max,
      -y_max,
      y_max,
      x);
  end if

  ;
end limitByStriple;

within PlanarMechanics.Utilities.Functions;
function round "Round to nearest Integer"
  extends Modelica.Icons.Function;

  input Real v "Real number";
  output Integer i "Real number v rounded to nearest integer";

algorithm
  i :=if v >= 0 then integer(floor(v + 0.5)) else integer(ceil(v - 0.5))
  ;
end round;

within PlanarMechanics.VehicleComponents;
model AirResistanceLongitudinal "Velocity dependent longitudinal air resistance"

  parameter Real c_W(min=0, start=0.5) "Drag coefficient";
  parameter SI.Area area(min=0, start=2) "Frontal cross area of vehicle";
  parameter SI.Density rho = 1.18 "Air density";
  parameter SI.Length r[2] = {1,0} "Driving direction of vehicle at angle frame_a.phi = 0";

  SI.Velocity vAir[2]
    "Air velocity relative to vehicle (vAir = -v_veh + v_wind), resolved in frame_a";
  SI.Force fDrag "Scalar drag force";

protected
  SI.Force f_long "Air force acting in x-direction of frame_a, resolved in frame_a";
  SI.Velocity v_wind_0[2] "Wind velocity, resolved in inertial frame";
  SI.Velocity v0[2] "Velocity resolved in inertial frame";
  constant SI.Velocity v_eps = 1e-3
    "Minimum vehicle velocity to apply this air drag model";
  final parameter Real e[2](each final unit="1") = Modelica.Math.Vectors.normalizeWithAssert(r)
    "Unit vector in direction of r";
  Real R[2,2] "Rotation matrix";
  Real R0a[2,2] "Rotation matrix from inertial frame to frame_a";
  Real Rae[2,2] "Rotation matrix from frame_a to e";

public
  Interfaces.Frame_a frame_a ;

equation
  R0a = {{cos(frame_a.phi), -sin(frame_a.phi)}, {sin(frame_a.phi),cos(frame_a.phi)}};
  Rae = {{e[1], -e[2]}, {e[2], e[1]}};
  R = R0a*Rae;

  // Vehicle environment
  v_wind_0=zeros(2);
  v0 = der({frame_a.x,frame_a.y});

  // Air velocity resolved in frame_a
  vAir = transpose(R)*( -v0 + v_wind_0);

  // Force and torque
  fDrag = 0.5*area*rho*vAir[1]*vAir[1]*c_W;
  f_long = noEvent(if vAir[1] > -v_eps then 0 else fDrag);
  {frame_a.fx, frame_a.fy} = R*{f_long, 0};
  frame_a.t = 0

  ;
end AirResistanceLongitudinal;

