    radius=0.25,
    N=1000)
    ;
  VehicleComponents.DifferentialGear differentialGear
    ;
  Modelica.Blocks.Sources.Pulse pulse(
    period=2,
    offset=0,
    startTime=1,
    width=30,
    amplitude=-2)
    ;
  Modelica.Mechanics.Rotational.Sources.Torque torque
    ;
  Modelica.Mechanics.Rotational.Sources.ConstantTorque constantTorque1(
      tau_constant=25)
    ;
  Modelica.Mechanics.Rotational.Components.Inertia inertia(
    phi(fixed=true, start=0),
    w(fixed=true, start=0),
    J=1) ;
  Modelica.Mechanics.Rotational.Components.Inertia inertia1(
    phi(fixed=true, start=0),
    w(fixed=true, start=0),
    J=1) ;
  Modelica.Mechanics.Rotational.Components.Inertia inertia2(
    J=1,
    phi(fixed=true, start=0),
    w(fixed=true, start=0)) ;
  Modelica.Mechanics.Rotational.Components.Inertia inertia3(
    phi(fixed=true, start=0),
    w(fixed=true, start=0),
    J=1) ;
  Parts.FixedTranslation fixedTranslation1(r={0,2}) ;
  Parts.FixedTranslation fixedTranslation2(r={0.75,0}) ;
  Parts.FixedTranslation fixedTranslation3(r={-0.75,0}) ;
  Parts.FixedTranslation fixedTranslation4(r={0.75,0}) ;
  Parts.FixedTranslation fixedTranslation5(r={-0.75,0}) ;
  Parts.FixedTranslation leftTrail(r={0.,-0.05}) ;
  Parts.FixedTranslation rightTrail(r={0.,-0.05}) ;
  Joints.Revolute revolute(useFlange=true) ;
  Joints.Revolute revolute2(
    useFlange=true,
    phi(fixed=true, start=-0.43633231299858),
    w(fixed=true))  ;
  inner PlanarWorld planarWorld(defaultWidthFraction=10, constantGravity={0,0})
    ;
equation
  connect(wheelJoint2.flange_a, inertia1.flange_b) ;
  connect(inertia.flange_b, wheelJoint1.flange_a) ;
  connect(fixedTranslation2.frame_b, fixedTranslation1.frame_a) ;
  connect(fixedTranslation2.frame_a, wheelJoint2.frame_a) ;
  connect(fixedTranslation3.frame_b, fixedTranslation1.frame_a) ;
  connect(wheelJoint3.frame_a, fixedTranslation3.frame_a) ;
  connect(inertia2.flange_b, wheelJoint3.flange_a) ;
  connect(body1.frame_a, fixedTranslation1.frame_a) ;
  connect(fixedTranslation1.frame_b, fixedTranslation4.frame_b) ;
  connect(fixedTranslation1.frame_b, fixedTranslation5.frame_b) ;
  connect(inertia3.flange_b, wheelJoint4.flange_a) ;
  connect(pulse.y, torque.tau) ;
  connect(differentialGear.flange_right, wheelJoint3.flange_a) ;
  connect(differentialGear.flange_left, wheelJoint2.flange_a) ;
  connect(constantTorque1.flange, differentialGear.flange_b) ;
  connect(body.frame_a, leftTrail.frame_b) ;
  connect(leftTrail.frame_b, wheelJoint1.frame_a) ;
  connect(body2.frame_a, rightTrail.frame_b) ;
  connect(wheelJoint4.frame_a, rightTrail.frame_b) ;
  connect(leftTrail.frame_a, revolute2.frame_a) ;
  connect(revolute2.frame_b, fixedTranslation4.frame_a) ;
  connect(torque.flange, revolute2.flange_a) ;
  connect(revolute.flange_a, revolute2.flange_a) ;
  connect(revolute.frame_a, rightTrail.frame_a) ;
  connect(revolute.frame_b, fixedTranslation5.frame_a) 
  ;
end TwoTrackWithDifferentialGear;

within PlanarMechanics.VehicleComponents.Wheels;
model DryFrictionWheelJoint "Dry-Friction based wheel joint"
  extends PlanarMechanics.VehicleComponents.Wheels.BaseClasses.WheelBase
    ;

  outer PlanarWorld planarWorld "planar world model";
  parameter StateSelect stateSelect=StateSelect.default
    "Priority to use acceleration as states" ;

  parameter SI.Length r[2] "Driving direction of the wheel at angle phi = 0";
  parameter SI.Force N "Normal force";
  parameter SI.Velocity vAdhesion "Adhesion velocity";
  parameter SI.Velocity vSlide "Sliding velocity";
  parameter Real mu_A "Friction coefficient at adhesion";
  parameter Real mu_S "Friction coefficient at sliding";
  final parameter SI.Length l = Modelica.Math.Vectors.length(r) "Length of r";
  final parameter Real e[2](each final unit="1") = Modelica.Math.Vectors.normalizeWithAssert(r)
    "Unit vector in direction of r";
  Real e0[2] "Unit vector in direction of r resolved w.r.t. inertial frame";
  Real R[2,2] "Rotation matrix";
  SI.Angle phi_roll(stateSelect=stateSelect, start=0) "Roll angle of the wheel"
    ;
  SI.AngularVelocity w_roll(final stateSelect=stateSelect, start=0)
    "Roll velocity of wheel" ;
  SI.Velocity v[2] "Velocity";
  SI.Velocity v_lat(start=0) "Driving in lateral direction"
    ;
  SI.Velocity v_long(start=0) "Velocity in longitudinal direction"
    ;
  SI.Velocity v_slip_long(start=0) "Slip velocity in longitudinal direction"
    ;
  SI.Velocity v_slip_lat( start=0) "Slip velocity in lateral direction"
    ;
  SI.Velocity v_slip "Slip velocity";
  SI.Force f "Longitudinal force";
  SI.Force f_lat "Longitudinal force";
  SI.Force f_long "Longitudinal force";
  parameter Boolean animate = true "= true, if animation shall be enabled"
     ;
  parameter SI.Length zPosition = planarWorld.defaultZPosition
    "Position z of the body" ;
  parameter SI.Length diameter = 0.1 "Diameter of the rims"
    ;
  parameter SI.Length width = diameter * 0.6 "Width of the wheel"
    ;
  input MB.Types.SpecularCoefficient specularCoefficient = planarWorld.defaultSpecularCoefficient
    "Reflection of ambient light (= 0: light is completely absorbed)"
    ;
  MB.Visualizers.Advanced.Shape cylinder(
    shapeType="cylinder",
    color={63,63,63},
    specularCoefficient=specularCoefficient,
    length=width,
    width=radius*2,
    height=radius*2,
    lengthDirection={-e0[2],e0[1],0},
    widthDirection={0,0,1},
    r_shape=-0.03*{-e0[2],e0[1],0},
    r=MB.Frames.resolve1(planarWorld.R,{frame_a.x,frame_a.y,zPosition})+planarWorld.r_0,
    R=planarWorld.R) if planarWorld.enableAnimation and animate;
  MB.Visualizers.Advanced.Shape rim1(
    shapeType="cylinder",
    color={195,195,195},
    specularCoefficient=specularCoefficient,
    length=radius*2,
    width=diameter,
    height=diameter,
    lengthDirection={0,0,1},
    widthDirection={1,0,0},
    r_shape={0,0,-radius},
    r=MB.Frames.resolve1(planarWorld.R,{frame_a.x,frame_a.y,zPosition})+planarWorld.r_0,
    R=MB.Frames.absoluteRotation(planarWorld.R,MB.Frames.planarRotation({-e0[2],e0[1],0},flange_a.phi,0)))
    if planarWorld.enableAnimation and animate;
  MB.Visualizers.Advanced.Shape rim2(
    shapeType="cylinder",
    color={195,195,195},
    specularCoefficient=specularCoefficient,
    length=radius*2,
    width=diameter,
    height=diameter,
    lengthDirection={0,0,1},
    widthDirection={1,0,0},
    r_shape={0,0,-radius},
    r=MB.Frames.resolve1(planarWorld.R,{frame_a.x,frame_a.y,zPosition})+planarWorld.r_0,
    R=MB.Frames.absoluteRotation(planarWorld.R,MB.Frames.planarRotation({-e0[2],e0[1],0},flange_a.phi+Modelica.Constants.pi/2,0)))
    if planarWorld.enableAnimation and animate;
equation
  R = {{cos(frame_a.phi), -sin(frame_a.phi)}, {sin(frame_a.phi),cos(frame_a.phi)}};
  e0 = R*e;
  v = der({frame_a.x,frame_a.y});
  phi_roll = flange_a.phi;
  w_roll = der(phi_roll);
  v_long = v*e0;
  v_lat = -v[1]*e0[2] + v[2]*e0[1];
  v_slip_lat = v_lat - 0;
  v_slip_long = v_long - radius*w_roll;
  v_slip = sqrt(v_slip_long^2 + v_slip_lat^2)+0.0001;
  -f_long*radius = flange_a.tau;
  frame_a.t = 0;
  f =N*noEvent(Utilities.Functions.limitByStriple(
    vAdhesion,
    vSlide,
    mu_A,
    mu_S,
    v_slip));
  f_long =f*v_slip_long/v_slip;
  f_lat  =f*v_slip_lat/v_slip;
  f_long = {frame_a.fx, frame_a.fy}*e0;
  f_lat = {frame_a.fy, -frame_a.fx}*e0;
  lossPower = f*v_slip

  ;
end DryFrictionWheelJoint;

