function randomdis "generates a triangular distributed random number according to a, b and c"
  input Real E[:] "Events of Discrete Distribution";
  input Real P[:] "Probability of Discrete Distribution";
  input Real r128 "A random number with a uniform distribution on the interval (0,1]";
  output Real timeValue;
protected
  Real CumP[size(P, 1)];
algorithm
  timeValue := E[size(P, 1)];
  CumP[1] := P[1];
  for i in 2:size(P, 1) loop
    CumP[i] := CumP[i - 1] + P[i];
  end for;
  for i in 1:size(P, 1) loop
    if r128 <= CumP[i] then
      timeValue := E[i];
      return;
    end if;
  end for;
end randomdis;

within PNlib.Functions.Random;

function randomexp "generates a exponential distributed random number according to lambda"
  input Real lambda;
  input Real r128 "A random number with a uniform distribution on the interval (0,1]";
  output Real delay;
protected
  Real lambda_ = lambda;
  Real r128_ = r128;
algorithm
  if r128_ < 10^(-10) then
    r128_ := 10^(-10);
  end if;
  if lambda_ <= 0 then
    lambda_ := 10^(-10);
  end if;
  delay := -Modelica.Math.log(r128_)/lambda_;
end randomexp;

within PNlib.Functions.Random;

function randomtriangular "generates a triangular distributed random number according to a, b and c"
  input Real a "Lower limit";
  input Real b "Upper limit";
  input Real c "Most likely value";
  input Real r128 "A random number with a uniform distribution on the interval (0,1]";
  output Real delay;
protected
  Real r128_ = r128;
  Real help;
algorithm
  if r128_ < 10^(-10) then
    r128_ := 10^(-10);
  end if;
  help := (c - a)/(b - a);
  if r128_ <= help then
    delay := sqrt(r128_*(b - a)*(c - a)) + a;
  else
    delay := b - sqrt((1 - r128_)*(b - a)*(b - c));
  end if;
end randomtriangular;

