within ThermofluidStream.FlowControl;
model MCV "Flow rate control valve"
  extends ThermofluidStream.Interfaces.SISOFlow(final clip_p_out=false, final L = 100, final p_min=p_min_par);
  //the component implements its own clip_p_out and requires a minimum L value for numeric reasons (otherwise dr_set will get very small)

  import Mode = ThermofluidStream.FlowControl.Internal.Types.MassflowControlValveMode;

  parameter Mode mode = Mode.mass_flow "Valve mode"
    ;
  parameter Boolean setpointFromInput = false "= true, if flow rate input connector is enabled"
    ;
  parameter SI.MassFlowRate massFlow_set_par = 0 "Mass flow rate set value"
    ;
  parameter SI.VolumeFlowRate volumeFlow_set_par = 0 "Volume flow rate set value"
    ;

  parameter SI.Time TC = 0.1 "Time constant of setpoint dynamic";
  parameter Real k1(unit="1") = 100 "Time constant factor"
    ;
  parameter Real k2(unit="1") = 100 "Integrator windup factor"
    ;
  parameter SI.Pressure p_min_par = dropOfCommons.p_min "Minimal steady-state output pressure"
    ;
  parameter Boolean enableClippingOutput = false "= true, if clippingOutput is enabled";

  Modelica.Blocks.Interfaces.RealInput setpoint_var if setpointFromInput "Flow rate input connector"
    ;
  Modelica.Blocks.Interfaces.RealOutput clippingOutput = (dp - dp_int) if enableClippingOutput ""
    ;

  SI.Density rho_in = Medium.density(inlet.state) "Inlet density";
  SI.VolumeFlowRate V_flow = m_flow/rho_in "Inlet volume flow rate";

  constant SI.Pressure eps = 1;

protected
  SI.MassFlowRate m_flow_set "Setpoint mass flow rate";
  SI.VolumeFlowRate V_flow_set "Setpoint volume flow rate";
  Modelica.Blocks.Interfaces.RealInput setpoint "Internal setpoint connector";

  SI.Pressure dr = outlet.r - inlet.r "Inertial pressure difference";
  SI.Pressure dr_set;

public
  SI.Pressure dp_int(start=-1e5) "Initial pressure difference";
  // dp corr for anti windup "back calculation" compensation after "Integrator windup and how to avoid it" 1989 Astrom
  SI.Pressure dp_corr = k2*(dp - dp_int) "Corrected pressure difference";

initial equation
  dp_int = 0;

equation
  connect(setpoint_var, setpoint);
  if setpointFromInput then
    m_flow_set = setpoint;
    V_flow_set = setpoint;
  else
    setpoint = 0;
    m_flow_set = massFlow_set_par;
    V_flow_set = volumeFlow_set_par;
  end if;

  // Compute dr_set required for desired mass-flow or Volume-flow dynamic
  if mode==Mode.mass_flow then
    dr_set = - L/TC * (m_flow_set - m_flow);
  else
    dr_set = - L/TC*(V_flow_set*rho_in - m_flow);
  end if;

  // compute pressure drop dynamic very fast, so dr tracks dr_set.
  // dr is limited, since it can be very high for non-smooth systems (e.g. a jump in input pressure)
  TC/k1 * der(dp_int) = max(-1e8, min(1e8,dr)) - dr_set +  dp_corr;

  // limit dp to a so that p_out > p_min and no pressure is created
  dp = max(p_min - p_in, min(0, dp_int));

  h_out = h_in;
  Xi_out = Xi_in

  ;
end MCV;

within ThermofluidStream.FlowControl;
model PCV "Pressure and pressure-drop control valve"
  extends ThermofluidStream.Interfaces.SISOFlow(final clip_p_out=true);

  import Mode = ThermofluidStream.FlowControl.Internal.Types.PressureControlValveMode;


  parameter Mode mode = Mode.drop "Valve mode"
    ;
  parameter Boolean pressureFromInput = false "= true, if pressure input connector is enabled";
  parameter SI.AbsolutePressure pressure_set_par = 0 "Setpoint for pressure / pressure difference"
    ;

  parameter SI.MassFlowRate m_flow_reg = dropOfCommons.m_flow_reg "Regularization mass flow"
    ;

  Modelica.Blocks.Interfaces.RealInput pressure_set_var(unit="Pa") if pressureFromInput "Pressure input connector [Pa]"
    ;

protected
  Modelica.Blocks.Interfaces.RealInput pressure_set(unit="Pa") "Internal pressure connector [Pa]";
  SI.Pressure dp_raw "Not normalized desired dp";

equation
  connect(pressure_set_var, pressure_set);
  if not pressureFromInput then
    pressure_set = pressure_set_par;
  end if;

  // normalize dp: upper limit=0: because valve should not create pressure.
  // if reversed flow condition, dp is set to 0, such that the valve will also not create pressure in this condition.
  // for the flow-direction-normalization regstep is used in a way, that dp=0 for m_flow = 0 (m_flow - m_flow_reg).
  // the motherclass will further normalize dp, such that p_out >= dp_min.
  dp = ThermofluidStream.Undirected.Internal.regStep(m_flow - m_flow_reg, min(0, dp_raw), 0, m_flow_reg);

  if mode ==Mode.drop then
    dp_raw = -pressure_set;
  else
    dp_raw = pressure_set - p_in;
  end if;

  h_out = h_in;
  Xi_out = Xi_in

    ;
end PCV;

within ThermofluidStream.FlowControl;
model SpecificValveType "Specific technical valve types"

  extends ThermofluidStream.FlowControl.Internal.PartialValve;

  import FlowCoeffType = ThermofluidStream.FlowControl.Internal.Types.FlowCoefficientTypes;

  replaceable record zetaValueRecord = Internal.Curves.SlideValveZetaCurve
    constrainedby Internal.Curves.PartialCharacteristicZetaCurves "Select valve type"
    ;

  parameter FlowCoeffType flowCoefficient = FlowCoeffType.Kvs "Select type of flow coefficient"
    ;
  //Set valve data as parameter
  parameter Modelica.Units.SI.Diameter d_valve "Flow diameter"
    ;
  //Reference Values
  parameter Real Kvs(unit = "m3/h")  "Kvs-value (metric) from data sheet (valve fully open)"
    ;
  parameter Real Cvs_US "Cvs-value (US [gal/min]) from data sheet (valve fully open)"
    ;
  parameter Real Cvs_UK "Cvs-value (UK [gal/min]) from data sheet (valve fully open)"
    ;
  parameter SI.MassFlowRate m_flow_ref_set "Reference mass flow rate"
    ;

protected
  Modelica.Units.SI.Area A_valve=0.25*Modelica.Constants.pi*d_valve^2 "Cross-sectional area";
  constant zetaValueRecord valveData;

  SI.VolumeFlowRate V_flow_ref=
    if flowCoefficient == FlowCoeffType.Kvs then Kvs/secondsPerHour
    elseif flowCoefficient == FlowCoeffType.Cvs_US then (Cvs_US/1.1561)/secondsPerHour
    elseif flowCoefficient == FlowCoeffType.Cvs_UK then (Cvs_UK/0.9626)/secondsPerHour
    elseif flowCoefficient == FlowCoeffType.flowDiameter then A_valve*sqrt((2/zeta1)*(dp_ref/rho_ref))
    else m_flow_ref_set/rho_ref "Reference volume flow";

  Real k_u_zeta(unit="1") "Kv/Kvs respecting zeta curve";

  Modelica.Blocks.Tables.CombiTable1Ds combiTable1D_zeta(
  final smoothness = Modelica.Blocks.Types.Smoothness.MonotoneContinuousDerivative1,
  final tableOnFile = false,
  final table = valveData.zetaTable) "Interpolation of zeta datapoints";

  Real zeta(unit="1", start = 0) "zeta value for pressure loss calculation";
  Real zeta1(unit="1") = valveData.zetaTable[end,2] "zeta value for fully open valve";

equation

  //Calculate reference mass flow rate from reference volume flow rate
  m_flow_ref = V_flow_ref*rho_ref;

  //Retrieving pressure loss coefficient from actuation signal
  combiTable1D_zeta.u = u;
  zeta = combiTable1D_zeta.y[1];

  //Evaluate characteristic for given pressure loss curve
  k_u_zeta = sqrt(zeta1/zeta);

  k_u = k_min + (1 - k_min)*k_u_zeta

  ;
end SpecificValveType;

within ThermofluidStream.FlowControl;
model TanValve "Valve with tan-shaped flow resistance"
  extends Interfaces.SISOFlow(final clip_p_out=true);

  Modelica.Blocks.Interfaces.RealInput u(unit="1") "Valve control signal []"
    ;

  parameter Utilities.Units.Inertance L = dropOfCommons.L "Inertance"
    ;
  parameter Boolean invertInput = false "= true, if input u_in is inverted"
    ;
  parameter SI.MassFlowRate m_flow_ref = 0.1 "Reference mass flow rate";
  parameter SI.Pressure p_ref = 1e5 "Reference pressure";
  parameter Real relativeLeakiness(unit="1") = 1e-3 "Imperfection of valve";

protected
  Real k(unit="(Pa.s)/kg");
  Real u2(unit="1");

equation
  if invertInput then
    u2 = max(relativeLeakiness,min(1-relativeLeakiness,u));
  else
    u2 = max(relativeLeakiness,min(1-relativeLeakiness,1-u));
  end if;

  k = p_ref/m_flow_ref*tan(u2*Modelica.Constants.pi/2);

  dp = -k*inlet.m_flow;
  h_out = h_in;
  Xi_out = Xi_in

  ;
end TanValve;

within ThermofluidStream.FlowControl.Internal;
partial model PartialValve "Partial implementation of a physical valve"

  extends Interfaces.SISOFlow(final clip_p_out=true);

  parameter Boolean invertInput = false "= true, if input u_in is inverted"
    ;
  parameter Real k_min(unit="1", min = 1e-5, max = 1) = 0.03 "Remaining flow at actuation signal u = 0";

  Modelica.Blocks.Interfaces.RealInput u_in(unit="1") "Valve control input signal []"
    ;

  Real u(unit="1") "Actuation input for flow calculation";
  parameter Modelica.Units.SI.Pressure dp_ref=1e5
    "Reference pressure difference"
    ;
  parameter Modelica.Units.SI.Density rho_ref=1000 "Reference density"
    ;

protected
  final constant Real secondsPerHour(final unit="s/h") = 3600 "Unit conversion parameter";

  //Medium properties
  Modelica.Units.SI.Density rho=Medium.density(inlet.state) "Inlet density";

  SI.MassFlowRate m_flow_ref "Reference mass flow rate derived from flow coefficient inputs";
  Real k_u(unit="1") "Kv/Kvs, respecting flow characteristics";

equation
  //Inversion of input signal, actuation has to be between 0 and 1
  assert(u_in <=1 and u_in >=0, "Actuator signal out of valid range [0,1]", level = AssertionLevel.warning);
  if invertInput then
      u = max(0, min(1, 1-u_in));
  else
      u = max(0, min(1, u_in));
  end if;

  //Generic pressure loss calculation
  dp = -sign(inlet.m_flow)*dp_ref*(rho_ref/rho)*(1/(k_u)*(inlet.m_flow/m_flow_ref))^2;
  h_out = h_in;
  Xi_out = Xi_in

  ;
end PartialValve;

within ThermofluidStream.FlowControl.Internal.ControlValve;
function equalPercentageCharacteristics "Equal percentage"

  extends Internal.ControlValve.partialValveCharacteristics;

algorithm
  k_u := k_min*exp(u*log(1/k_min));

end equalPercentageCharacteristics;

within ThermofluidStream.FlowControl.Internal.ControlValve;
function linearCharacteristics "Linear"

  extends Internal.ControlValve.partialValveCharacteristics;

algorithm
  k_u := k_min + (1 - k_min)*u;

end linearCharacteristics;

within ThermofluidStream.FlowControl.Internal.ControlValve;
function parabolicCharacteristics "Parabolic"

  extends Internal.ControlValve.partialValveCharacteristics;

algorithm
  k_u := k_min + (1 - k_min)*u^2;

end parabolicCharacteristics;

within ThermofluidStream.FlowControl.Internal.ControlValve;
partial function partialValveCharacteristics
  "Partial function for control valve characteristics"
  extends Modelica.Icons.Function;

  input Real u(unit="1");
  input Real k_min(unit="1");

  output Real k_u(unit="1");

end partialValveCharacteristics;

