within ThermofluidStream.HeatExchangers;
model CounterFlowNTU "Counter flow heat exchanger using the epsilon-NTU method"

  extends ThermofluidStream.HeatExchangers.Internal.PartialNTU;

equation
  //Calculating heat exchanger effectiveness derived from NTU correlations (see VDI Waermeatlas)
  effectiveness = if noEvent(C_r < 1) then (1 - exp(-NTU*(1 - C_r)))/(1 - C_r*exp(-NTU*(1 - C_r))) else NTU/(1 + NTU)

  ;
end CounterFlowNTU;

within ThermofluidStream.HeatExchangers;
model CrossFlowNTU "Cross flow heat exchanger using the epsilon-NTU method"

  extends ThermofluidStream.HeatExchangers.Internal.PartialNTU(crossFlow=true);

equation
  //Calculating heat exchanger effectiveness derived from NTU correlations (see VDI Waermeatlas)
  //it is assumed that both fluids are unmixed
  effectiveness = 1 - exp((1/C_r)*NTU^(0.22)*(exp(-C_r*NTU^(0.78)) - 1))

  ;
end CrossFlowNTU;

within ThermofluidStream.HeatExchangers;
model DiscretizedCounterFlowHEX "Discretized heat exchanger for single- or two-phase working fluids without pressure drop"

  extends Internal.PartialDiscretizedHEX;

initial equation
  if initializeMassFlow then
    inletA.m_flow = m_flow_0_A;
    inletB.m_flow = m_flow_0_B;
  end if;

equation
  //Connecting equations (to interconnect pipes)
  //Fluid Side B
  connect(inletB, thermalElementB[1].inlet) ;
  for i in 1:nCells - 1 loop
    connect(thermalElementB[i].outlet, thermalElementB[i + 1].inlet);
  end for;
  connect(thermalElementB[nCells].outlet, outletB) ;

  //Fluid Side A
  connect(inletA, thermalElementA[1].inlet) ;
  for i in 1:nCells - 1 loop
    connect(thermalElementA[i].outlet, thermalElementA[i + 1].inlet);
  end for;
  connect(thermalElementA[nCells].outlet, outletA) ;

  connect(thermalElementB.heatPort, thermalConductor.port_b) ;

  for i in 1:nCells loop
    connect(thermalElementA[i].heatPort, thermalConductor[nCells + 1 - i].port_a) ;
  end for

  ;
end DiscretizedCounterFlowHEX;

