within ThermofluidStream.HeatExchangers.Internal;
function calculateEfficiency "Calculates heat exchanger efficiency"
  extends Modelica.Icons.Function;

  replaceable package MediumA = Media.myMedia.Interfaces.PartialMedium "Medium model A";
  replaceable package MediumB = Media.myMedia.Interfaces.PartialMedium "Medium model B";

  input MediumA.ThermodynamicState state_A_in "Inlet A thermodynamic state";
  input MediumB.ThermodynamicState state_B_in "Inlet B thermodynamic state";

  input MediumA.ThermodynamicState state_A_out "Outlet A thermodynamic state";
  input MediumB.ThermodynamicState state_B_out "Outlet B thermodynamic state";

  input SI.MassFlowRate m_flow_A "Mass flow rate of medium A";
  input SI.MassFlowRate m_flow_B "Mass flow rate of medium B";

  input SI.Power Q_flow "Heat flow rate";

  output Real efficiency(unit="1") = 0 "Heat exchanger efficiency";

protected
  SI.SpecificEnthalpy h_A_in = MediumA.specificEnthalpy(state_A_in) "Inlet A specific enthalpy";
  SI.SpecificEnthalpy h_B_in = MediumB.specificEnthalpy(state_B_in) "Inlet B specific enthalpy";

  SI.Pressure p_A = MediumA.pressure(state_A_out) "Outlet A pressure";
  SI.Pressure p_B = MediumB.pressure(state_B_out) "Outlet B pressure";

  SI.MassFraction[MediumA.nXi] Xi_A = MediumA.massFraction(state_A_out) "Outlet A mass fractions";
  SI.MassFraction[MediumB.nXi] Xi_B = MediumB.massFraction(state_B_out) "Outlet B mass fractions";

  SI.Temperature T_A_in = MediumA.temperature(state_A_in) "Inlet A temperature";
  SI.Temperature T_B_in = MediumB.temperature(state_B_in) "Inlet B temperature";

  constant SI.SpecificEnthalpy dh_0 = 1e4 "Initial specific enthalpy difference";
  constant SI.SpecificEnthalpy dh_fin = 1e1 "Stop condition";
  constant Real devisor(unit="1") = 3.5;
  SI.SpecificEnthalpy dh "Specific enthalpy difference";

  SI.SpecificEnthalpy dh_A=0 "Medium A specific enthalpy difference";
  SI.SpecificEnthalpy dh_B=0 "medium B specific enthalpy difference";

  constant SI.Power eps = 1e-8 "Minimum power";

algorithm
  if T_A_in == T_B_in then
    return;
  end if;

  dh :=dh_0;
  while dh > dh_fin loop
    if T_A_in > T_B_in then
      if MediumA.temperature(MediumA.setState_phX(p_A, h_A_in-(dh+dh_A), Xi_A)) > T_B_in then
        dh_A :=dh + dh_A;
      else
        dh :=dh/devisor;
      end if;
    else
      if MediumA.temperature(MediumA.setState_phX(p_A, h_A_in+(dh+dh_A), Xi_A)) < T_B_in then
        dh_A :=dh + dh_A;
      else
        dh :=dh/devisor;
      end if;
    end if;
  end while;

  dh :=dh_0;
  while dh > dh_fin loop
    if T_B_in > T_A_in then
      if MediumB.temperature(MediumB.setState_phX(p_B, h_B_in-(dh+dh_B), Xi_B)) > T_A_in then
        dh_B :=dh + dh_B;
      else
        dh :=dh/devisor;
      end if;
    else
      if MediumB.temperature(MediumB.setState_phX(p_B, h_B_in+(dh+dh_B), Xi_B)) < T_A_in then
        dh_B :=dh + dh_B;
      else
        dh :=dh/devisor;
      end if;
    end if;
  end while;

  efficiency := max(0, min(1, abs(Q_flow)/max(min(dh_A*abs(m_flow_A), dh_B*abs(m_flow_B)),eps)));

end calculateEfficiency;

within ThermofluidStream.HeatExchangers.Internal;
model ConductionElementHEX "ConductionElement for single-phase fluids"
  extends PartialConductionElementHEX;

  parameter SI.CoefficientOfHeatTransfer U_nom = 3000 "Nominal thermal transmittance";
  parameter SI.MassFlowRate m_flow_nom = 1 "Nominal mass flow rate (for heat transfer calculation)";

  constant Real Re_exp(unit="1") = 0.8 "Reynolds-exponent for heat transfer calculation";

equation
  //Estimation of heat transfer coefficient
  U = max(U_min, U_nom*(abs(m_flow/(m_flow_nom/nCellsParallel)))^Re_exp)

  ;
end ConductionElementHEX;

within ThermofluidStream.HeatExchangers.Internal;
model ConductionElementHEX_twoPhase "ConductionElement for two-phase fluids"
  extends PartialConductionElementHEX(redeclare replaceable package Medium = Media.myMedia.Interfaces.PartialTwoPhaseMedium);

  import Modelica.Math;

  parameter SI.CoefficientOfHeatTransfer U_liq_nom = 700 "Nominal coefficient of heat transfer for liquid flow";
  parameter SI.CoefficientOfHeatTransfer U_vap_nom = 500 "Nominal coefficient of heat transfer for vapour flow";
  parameter SI.CoefficientOfHeatTransfer U_tp_nom = 1000 "Nominal coefficient of heat transfer for condensation/evaporation";

  parameter SI.MassFlowRate m_flow_nom = 0.3 "Nominal mass flow rate for heat transfer calculation";
  parameter SI.MassFraction delta_x = 0.05 "Value for interpolation width";

  constant Real Re_exp_cond(unit="1") = 0.4 "Reynolds-Exponent for heat transfer calculation at condensation (Yan&Lin, 1999)";
  constant Real Re_exp_evap(unit="1") = 0.5 "Reynolds-Exponent for heat transfer calculation at evaporation (Yan&Lin, 1999)";

  Real x "Vapor quality calculated from specific enthalpies";

protected
  SI.CoefficientOfHeatTransfer U_liq "Coefficient of heat transfer for liquid flow";
  SI.CoefficientOfHeatTransfer U_tp "Coefficient of heat transfer for condensation/evaporation";
  SI.CoefficientOfHeatTransfer U_vap "Coefficient of heat transfer for vapour flow";

  SI.SpecificEnthalpy h_dew = Medium.dewEnthalpy(Medium.setSat_p(Medium.pressure(state))) "Dew enthalpy at inlet";
  SI.SpecificEnthalpy h_bubble = Medium.bubbleEnthalpy(Medium.setSat_p(Medium.pressure(state))) "Bubble enthalpy at inlet";

equation
  //Estimation of heat transfer coefficient
  x = (h - h_bubble)/(h_dew - h_bubble);

  //Heat transfer coefficients for each zone dependent on mass-flow rate
  U_liq = max(U_min, U_liq_nom*(abs(inlet.m_flow)/(m_flow_nom/nCellsParallel))^
    Re_exp_cond);
  U_vap = max(U_min, U_vap_nom*(abs(inlet.m_flow)/(m_flow_nom/nCellsParallel))^
    Re_exp_evap);
  U_tp = max(U_min, U_tp_nom);

  //Coefficient of heat transfer dependent on vapor quality (interpolation in phase-transition regions)
  U = smooth(1, noEvent(
      if x < -delta_x then U_liq
      elseif x < delta_x then U_liq + 0.5*(U_tp - U_liq)*(1 + Math.sin(x*Modelica.Constants.pi/(2*delta_x)))
      elseif x < 1 - delta_x then U_tp
      elseif x < 1 + delta_x then U_tp + 0.5*(U_vap - U_tp)*(1 + Math.sin((x - 1)*Modelica.Constants.pi/(2*delta_x)))
      else U_vap))

  ;
end ConductionElementHEX_twoPhase;

within ThermofluidStream.HeatExchangers.Internal;
partial model PartialConductionElementHEX "Parent for CEs for discretizedHEX"
  extends Processes.Internal.PartialConductionElement(
