        -4.5340839289219472E-05,7.6129675309037664E-02,2.4169481088097051E+01},
        Cv.to_degC(123.15),
        Cv.to_degC(1273.15),
        Cv.to_degC(state.T))

    ;
  end thermalConductivity

  ;
end DryAirNasa;

