within ThermofluidStream.Processes;
model FlowResistance "Flow resistance model"
  extends Interfaces.SISOFlow(
    final L=if computeL then l/areaHydraulic else L_value,
    final clip_p_out=true);

  import Modelica.Constants.pi "Constant Pi";
  import ThermofluidStream.Processes.Internal.ShapeOfResistance "Shape of cross sectional area";

  replaceable function pLoss = Internal.FlowResistance.pleaseSelectPressureLoss
    constrainedby Internal.FlowResistance.partialPressureLoss "Pressure loss function"
    ;
  parameter SI.Length l(min=0) "Length"
    ;
  parameter ShapeOfResistance shape=ThermofluidStream.Processes.Internal.ShapeOfResistance.circular "Cross section shape"
    ;
  parameter SI.Radius r(min=0) = 0 "Radius"
    ;
  parameter SI.Length a(min=0) = 0 "Rectangle width"
    ;
  parameter SI.Length b(min=0) = 0 "Rectangle height"
    ;
  parameter SI.Area areaCrossInput(min=0) = 0 "Cross-sectional area"
    ;
  parameter SI.Length perimeterInput(min=0) = 0 "Wetted perimeter"
    ;
  parameter Boolean computeL = true "= true, if inertance L is computed from the geometry"
    ;
  parameter Utilities.Units.Inertance L_value = dropOfCommons.L "Inertance"
    ;
  parameter SI.Density rho_min = dropOfCommons.rho_min "Minimal inlet density"
    ;

  final parameter SI.Length D_h = 4*areaCross/perimeter "Hydraulic diameter";
  final parameter SI.Length perimeter=
    if shape == ShapeOfResistance.circular then 2*pi*r
    elseif shape == ShapeOfResistance.rectangle then 2*a+2*b
    else perimeterInput "Perimeter";

  final parameter SI.Area areaCross=
    if shape == ShapeOfResistance.circular then pi*r*r
    elseif shape == ShapeOfResistance.rectangle then a*b
    else areaCrossInput "Cross-sectional area";

  final parameter SI.Area areaHydraulic= pi*D_h*D_h*1/4 "Hydraulic cross-sectional area";

protected
  SI.Density rho_in = max(rho_min, Medium.density(inlet.state)) "Inlet density";
  SI.DynamicViscosity mu_in = Medium.dynamicViscosity(inlet.state) "Inlet dynamic viscosity";

equation
  dp = -pLoss(m_flow, rho_in, mu_in, D_h/2, l);
  h_out = h_in;
  Xi_out = Xi_in

  ;
end FlowResistance;

within ThermofluidStream.Processes;
model Nozzle "Model for dynamic pressure difference"
  extends ThermofluidStream.Interfaces.SISOFlow(final L = L_value, final clip_p_out=true);

  parameter Boolean assumeConstantDensity=true "= true, if incompressibility is assumed (use '= false' for Ma > 0.3)"
    ;
  parameter Boolean area_in_FromInput = false "= true, if input connector for inlet cross section area is enabled"
    ;
  parameter SI.Area A_in = 1 "Inlet cross-sectional area"
    ;
  parameter Boolean area_out_FromInput = false "= true, if input connector for outlet cross section area is enabled"
    ;
  parameter SI.Area A_out = 1 "Outlet cross-sectional area"
    ;
  parameter ThermofluidStream.Utilities.Units.Inertance L_value = dropOfCommons.L "Inertance"
    ;

  // ------ Parameter Display Configuration  ------------------------
  parameter Boolean displayCompressibilityApproach = true "= true, if  assumeConstantDensity is displayed"
    ;
  parameter Boolean displayInletArea = true "= true, if inlet area A_in is displayed"
    ;
  parameter Boolean displayOutletArea = true "= true, if outlet area A_out is displayed"
    ;
  parameter Boolean displayInertance = false "=true, if inertance L is displayed"
    ;
  final parameter Boolean dA_in = displayInletArea and not area_in_FromInput "Display inlet area"
    ;
  final parameter Boolean dA_out = displayOutletArea and not area_out_FromInput "Display outlet area"
    ;
  final parameter Boolean displayA = dA_in or dA_out "Display inlet area or display outlet area"
    ;
  final parameter String AreaString=
    if dA_in and dA_out then "A_in=%A_in, A_out=%A_out"
    elseif dA_in and not dA_out then "A_in = %A_in"
    elseif not dA_in and dA_out then "A_out = %A_out"
    else ""
    ;
  final parameter String compressibilityString=
    if assumeConstantDensity then "incompressible"
    else "compressible"
    ;
  final parameter String displayPos1=
    if displayCompressibilityApproach then
      compressibilityString
    elseif displayA then
      AreaString
    elseif displayInertance then
      "L = %L_value"
    else "" ;
  final parameter String displayPos2=
    if displayCompressibilityApproach and displayA then
      AreaString
    elseif displayInertance and not displayPos1 == "L = %L" then
      "L = %L_value"
    else "" ;
  final parameter String displayPos3=
    if displayCompressibilityApproach and displayA and displayInertance then
      "L = %L_value"
    else "" ;
  //-----------------------------------------------------------------

  Modelica.Blocks.Interfaces.RealInput A_in_var(unit = "m2") if area_in_FromInput "Inlet cross-sectional area input connector [m2]" ;
  Modelica.Blocks.Interfaces.RealInput A_out_var(unit = "m2") if area_out_FromInput "Outlet cross-sectional area input connector [m2]" ;


protected
  Modelica.Blocks.Interfaces.RealInput A_in_internal(unit = "m2") "Internal connector for inlet cross-sectional area";
  Modelica.Blocks.Interfaces.RealInput A_out_internal(unit = "m2") "Internal connector for outlet cross-section area";

  SI.Density rho_in = Medium.density(inlet.state) "Inlet density";
  SI.Density rho_out "Outlet density";

  SI.Velocity v_in "Inlet velocity";
  SI.Velocity v_out "Outlet velocity";
  //SI.Density rho_mean;
equation

   connect(A_in_var, A_in_internal);
   if not area_in_FromInput then
     A_in_internal = A_in;
   end if;

  connect(A_out_var, A_out_internal);
   if not area_out_FromInput then
     A_out_internal = A_out;
   end if;

   if assumeConstantDensity then
      rho_out = rho_in;
   else
      rho_out = Medium.density(outlet.state);
   end if;

  v_in = m_flow/(rho_in*A_in_internal);
  v_out = m_flow/(rho_out*A_out_internal);
  //rho_mean = (rho_in + rho_out)/2;
  dp = (rho_in/2)*v_in^2 - (rho_out/2)*v_out^2; //beware of density assumption....
  h_out = h_in + 1/2*(v_in^2 - v_out^2);
  Xi_out = Xi_in

    ;
end Nozzle;

within ThermofluidStream.Processes;
model Pump "A simple pump model"

  extends Internal.PartialTurboComponent(redeclare function dp_tau =
        dp_tau_pump);

  parameter Real max_rel_volume(min=0, max=1, unit="1") = 0.05 "Maximum relative volume change (checking incompressibility approach)"
    ;

  replaceable function dp_tau_pump =
      Internal.TurboComponent.pleaseSelect_dp_tau
    constrainedby Internal.TurboComponent.partial_dp_tau(
      redeclare package Medium = Medium) "Pump characteristic curve"
    ;

  Real eta(unit="1") = if noEvent(abs(W_t)>1e-4) then dp*v_in*m_flow/W_t else 0.0 "Efficiency";

protected
  SI.SpecificVolume v_out = 1/max(rho_min, Medium.density(inlet.state)) "Specific volume at outlet";

equation
  // test for incompressibility
  assert(abs(v_in- v_out)/v_in < max_rel_volume, "Medium in pump is assumed to be incompressible, but check failed", dropOfCommons.assertionLevel)

  ;
end Pump;

within ThermofluidStream.Processes;
model ThermalConvectionPipe "Very simple model of thermal convection"

  extends Interfaces.SISOFlow(final clip_p_out=false);

  parameter SI.Length l(min=0) "Length";
  parameter SI.Radius r "Radius";
  parameter SI.ReynoldsNumber Re_D_crit = 2300 "Critical Reynolds number for laminar-turbulent transition"
    ;
  //parameter Real C_dh(unit="J/(K.s)") = 1e-6 "Dimensionless constant for mass flow regularization";
  parameter SI.MassFlowRate m_flow_reg = dropOfCommons.m_flow_reg "Nominal mass flow rate for regularization"
    ;

  // ------ Parameter Display Configuration  ------------------------
  parameter Boolean displayLength = true "= true, if length l is displayed"
    ;
  parameter Boolean displayRadius = true "= true, if radius r is displayed"
    ;
  final parameter String parameterString=
    if displayParameters and displayLength and displayRadius then
      "l = %l, r = %r"
    elseif displayParameters and displayLength and not displayRadius then
      "l = %l"
    elseif  displayParameters and not displayLength and displayRadius then
      "r = %r"
    else "";
  //-----------------------------------------------------------------

  Medium.ThermodynamicState center_state = Medium.setState_phX(p_in,h_in+dh/2,Xi_in) "State at (h_in+h_out)/2";
  Medium.Temperature T = Medium.temperature(center_state) "Temperature at center state";

  Integer turb_flag "= 0 for laminar flow, = 1 for turbulent flow (Re > 2300)";

  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a heatPort ;


protected
  SI.Area A_cond = 2*Modelica.Constants.pi*r*l "Heat transfer area";
  SI.Area A_cross = Modelica.Constants.pi*r^2
    "Cross-sectional area";
  SI.Volume V = A_cross*l "Volume";
  constant SI.NusseltNumber Nu_laminar = 4.36 "Nusselt number for laminar flow";
  SI.CoefficientOfHeatTransfer h_avg "Average heat transfer coefficient";

  SI.ThermalConductivity k =  Medium.thermalConductivity(center_state) "Center state thermal conductivity ";

  SI.Density rho = Medium.density(center_state) "Center state density";
  SI.Mass M = V*rho "Mass";
  SI.SpecificEnthalpy dh "Specific enthalpy difference (outlet-inlet)";

  //Flow characteristics
  SI.DynamicViscosity mu = Medium.dynamicViscosity(center_state) "Center state dynamic viscosity";
  SI.ReynoldsNumber Re_D "Reynolds number";
  SI.NusseltNumber Nu_turb "Nusselt number for turbulent flow";
  SI.PrandtlNumber Pr = Medium.prandtlNumber(center_state) "Center state Prandtl number";

  SI.Velocity v_m "Mean fluid velocity";

  //SI.VelocityOfSound c = Medium.velocityOfSound(center_state) "Velocity of sound";

  parameter Real eps(unit="1") = Modelica.Constants.eps;

equation

  //mean velocity calculation
  v_m = inlet.m_flow/(rho*A_cross);

  //Reynolds number for pipe flow
  Re_D = max((rho*v_m*2*r)/(mu), 1);

  //Nusselt number for turbulent flow and constant heat flux
  Nu_turb = ((0.0396*Re_D+eps)^(0.75)*Pr)/(1+(2.44*Re_D+eps)^(-0.125)*(Pr-1));


//    //Calculation of heat transfer coefficient dependent on flow characteristics
//     if noEvent(Re_D < Re_D_crit) then
//
//       h_avg = (Nu_laminar*k)/(2*r);
//
//       turb_flag = 0;
//
//     else
//       h_avg = (Nu_turb*k)/(2*r);
//
//       turb_flag = 1;
//     end if;


   //assuming constant conditions
   h_avg = (Nu_turb*k)/(2*r);
   turb_flag = 1;

  heatPort.Q_flow = h_avg*A_cond*(heatPort.T - T);

  //der(dh)*M/2 + inlet.m_flow*dh = heatPort.Q_flow;

  dh = (inlet.m_flow*heatPort.Q_flow)/((inlet.m_flow)^2+(m_flow_reg/10)^2);

  //dh = (inlet.m_flow*heatPort.Q_flow)/((inlet.m_flow)^2 + 0.5*M^2*C_dh*(c/l)^2);

  dp = 0;
  h_out = h_in+dh;
  Xi_out = Xi_in

  ;
end ThermalConvectionPipe;

within ThermofluidStream.Processes;
model TransportDelay "Delay model based on fluid velocity"

  extends Interfaces.SISOFlow(final clip_p_out=false);

  parameter SI.Length l "Length";
  parameter SI.Radius r "Radius";
  parameter SI.Density rho_min = dropOfCommons.rho_min "Minimum density"
    ;
  parameter Real v_min(unit="1/s", min=0) = 0.01 "Minimum nondimensional speed"
    ;
  parameter Real v_max(unit="1/s", min=0) = 50 "Maximum nondimensional speed"
    ;

  // ------ Parameter Display Configuration  ------------------------
  parameter Boolean displayLength = true "= true, if length l is displayed"
    ;
  parameter Boolean displayRadius = true "= true, if radius r is displayed"
    ;
  final parameter Boolean d1l = displayParameters and displayLength  "displayLength at position 1"
    ; //d1l -> Display at position 1 l=length
  final parameter Boolean d1r = displayParameters and displayRadius and not d1l  "displayRadius at position 1"
    ;
  final parameter Boolean d2r = displayParameters and displayRadius and not d1r  "displayRadius at position 2"
    ;
  //-----------------------------------------------------------------


  constant Medium.ThermodynamicState state_0 = Medium.setState_phX(Medium.p_default, Medium.h_default, Medium.X_default[1:Medium.nXi]) "Default state";
  constant SI.MassFraction Xi_0[Medium.nXi] = Medium.massFraction(state_0) "Default mass fractions";
  constant SI.SpecificVolume v_0 = 1/Medium.density(state_0) "Default specific volume";

  Real x(unit="1") "Relative position s/l";
  Real v(unit="1/s") = der(x) "Relative speed v/l";

protected
  SI.SpecificInternalEnergy u_in = Medium.specificInternalEnergy(inlet.state) "Inlet internal energy";
  SI.SpecificVolume v_in = 1/max(rho_min, Medium.density(inlet.state)) "Inlet specific volume";

  SI.SpecificInternalEnergy u_out "Outlet internal energy";
  SI.SpecificVolume v_out "Outlet specific volume";

  SI.Area A = r^2*Modelica.Constants.pi "Cross-sectional area";

initial equation
  x = 0;

equation
  v = min(v_max, max(v_min, inlet.m_flow*v_in/A/l));

  (,u_out) = spatialDistribution(u_in,
    Medium.specificInternalEnergy(Medium.setState_phX(p_out, Medium.h_default, Medium.X_default[1:Medium.nXi])),
    x,
    true,
    initialPoints = {0.0,1.0},
    initialValues = {Medium.specificInternalEnergy(state_0), Medium.specificInternalEnergy(state_0)});
  (,v_out) = spatialDistribution(v_in,
    1/max(rho_min, Medium.density(Medium.setState_phX(p_out, Medium.h_default, Medium.X_default[1:Medium.nXi]))),
    x,
    true,
    initialPoints = {0.0,1.0},
    initialValues = {v_0, v_0});
  for i in 1:Medium.nXi loop
    (,Xi_out[i]) = spatialDistribution(Xi_in[i],
      0,
      x,
      true,
      initialPoints = {0.0,1.0},
      initialValues = {Xi_0[i], Xi_0[i]});
  end for;

  dp = 0;
  h_out = u_out + p_out * v_out;
  Xi_out = Xi_in
  ;
end TransportDelay;

within ThermofluidStream.Processes;
model Turbine "Turbine using ideal gas assumptions"
  extends Internal.PartialTurboComponent(redeclare function dp_tau =
        dp_tau_turbine);

  replaceable function dp_tau_turbine =
      Internal.TurboComponent.pleaseSelect_dp_tau
    constrainedby Internal.TurboComponent.partial_dp_tau(
      redeclare package Medium = Medium) "Turbine characteristic curve"
    ;

  parameter Real max_rel_R(min=0, max=1, unit="1") = 0.05 "Maximum relative allowed divergence from ideal gas"
    ;

protected
  Real R_in(unit="J/(kg.K)") = p_in/Medium.temperature(inlet.state)/Medium.density(inlet.state);
  Real R_out(unit="J/(kg.K)") = p_out/Medium.temperature(outlet.state)/Medium.density(outlet.state);

equation
  // test for ideal gas
  assert(abs(R_in- R_in)/R_in < max_rel_R, "Medium in turbine is assumed to be ideal gas, but check failed", dropOfCommons.assertionLevel)

  ;
end Turbine;

within ThermofluidStream.Processes.Internal;
partial model PartialConductionElement "Partial model of quasi-stationary mass and heat transfer"

  extends Interfaces.SISOFlow(final clip_p_out=false);

  parameter SI.Volume V(displayUnit="l")=0.001 "Volume";
  parameter Internal.InitializationMethodsCondElement init=ThermofluidStream.Processes.Internal.InitializationMethodsCondElement.inlet "Initialization for specific enthalpy"
    ;
  parameter Medium.Temperature T_0 = Medium.T_default "Initial Temperature"
    ;
  parameter SI.SpecificEnthalpy h_0 = Medium.h_default "Initial specific enthalpy"
    ;
  parameter SI.Density rho_min = dropOfCommons.rho_min "Minimal density"
    ;
  parameter Boolean neglectPressureChanges = true "=true, if pressure changes are neglected"
    ;
  parameter SI.MassFlowRate m_flow_assert(max=0) = -dropOfCommons.m_flow_reg "Assertion threshold for negative massflows"
    ;
  parameter Boolean enforce_global_energy_conservation = false "= true, if global conservation of energy is enforced"
    ;
  parameter SI.Time T_e = 100 "Time constant for global conservation of energy"
    ;

  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a heatPort(Q_flow=Q_flow, T=T_heatPort) ;

  SI.SpecificEnthalpy h(start=Medium.h_default, stateSelect = StateSelect.prefer) "Volume? specific enthalpy";

  Medium.ThermodynamicState state = Medium.setState_phX(p_in, h, Xi_in) "Volume thermodynamic state";
  SI.Temperature T = Medium.temperature(state) "Volume temperature";
  SI.ThermalConductance k "Thermal conductance";

  SI.Energy deltaE_system(start=0, fixed=true) "Energy difference between m_flow*(h_in-h_out) and Q_flow";

  SI.Mass M "Mass (of the volume)";

protected
  SI.Density rho = max(rho_min, Medium.density(state)) "Volume density";

  //for stability reasons the model for reverse flow is different. see documentation/information
  SI.SpecificEnthalpy h_in_norm = if noEvent(inlet.m_flow >= 0) then h_in else h "Inlet specific enthalpy";

  SI.Temperature T_heatPort "Heatport Temperature";
  SI.HeatFlowRate Q_flow "Heat flow rate";

initial equation
  if init == Internal.InitializationMethodsCondElement.T then
    h = Medium.specificEnthalpy(Medium.setState_pTX(p_in, T_0, Xi_in));
  elseif init == Internal.InitializationMethodsCondElement.h then
    h = h_0;
  else
    h = Medium.specificEnthalpy(inlet.state);
  end if;

equation
  assert(noEvent(inlet.m_flow > m_flow_assert), "Negative mass flow rate at inlet", dropOfCommons.assertionLevel);

  //mass is assumed to be quasisationary-> this violates the conservation of mass since m_flow_in = -m_flow_out. see documentation/information
  M = V*rho;

  // Mass is assumed to be (quasi-)stationary-> assumption: der(M)=0.
  // V=const
  // lhs: der(U) = der(H - pV) = der(M)*h +  M*der(h) - V*der(p) = M*der(h)
  // one can not simply add der(M)*h to the left side, since the right side is also assuming sationary mass (m_flow_in=-m_flow_out)
  // on RHS: Q_flow + m_flow_in*h_in + m_flow_out*h = Q_flow + m_flow_in*h_in + (m_flow_in-m_flow_in+ m_flow_out)*h = Q_flow + m_flow_in*(h_in-h) + der(M)*h = Q_flow + m_flow*(h_in-h)
  // or:     Q_flow + m_flow_in*h_in + m_flow_out*h = Q_flow + (m_flow_in+m_flow_out-m_flow_out)*h_in + m_flow_out*h = Q_flow + m_flow_out*(h-h_in) + der(M)*h_in = Q_flow + m_flow*(h_in - h)
  // so there is a resulting term on the RHS with der(M)*(h(k) + h_out(1-k)) with k in [0,1]; that also would have to be accounted for when der(M) not 0 on LHS
  // to improve the equation p_in and M would have to be filtered and a value for k would have to be found, all that resulted in only moderate improvements
  // therefore energy that is accumulated with system border around the component (deltaE_system) is slowly fed back into the system when enforce_global_energy_conservation is true
  //(then energy stored in the system e.g. by evaproation/condension, while still being visible short-term, neglegted in logterm)
  if not neglectPressureChanges then
    M*der(h) = Q_flow + m_flow*(h_in_norm - h) + V*der(p_in) + (if enforce_global_energy_conservation then deltaE_system/T_e else 0);
  else
    //neglegt V*der(p), since p might not be smooth -> to notice a difference der(p) must be about 1e7 Pa/s. see documentation/information
    M*der(h) = Q_flow + m_flow*(h_in_norm - h)+ (if enforce_global_energy_conservation then deltaE_system/T_e else 0);
  end if;
  if enforce_global_energy_conservation then
    der(deltaE_system) = Q_flow + m_flow*(h_in_norm - h);
  else
    deltaE_system = 0;
  end if;

  Q_flow = k*(T_heatPort - T);

  dp = 0;
  h_out = h;
  Xi_out = Xi_in

  ;
end PartialConductionElement;

within ThermofluidStream.Processes.Internal;
partial model PartialTurboComponent "Partial model of turbo component"
  extends Interfaces.SISOFlow(m_flowStateSelect = StateSelect.prefer, final clip_p_out=true);

  import ThermofluidStream.Utilities.Types.InitializationMethods;
  import Quantity = ThermofluidStream.Sensors.Internal.Types.MassFlowQuantities;

  parameter Boolean omega_from_input = false "= true, if omega input connector is enabled"
    ;
  parameter Boolean enableAccessHeatPort = false "= true, if heatPort is enabled"
    ;
  parameter SI.MomentOfInertia J_p = 5e-4 "Moment of inertia"
    ;
  parameter Boolean enableOutput = false "= true, if selectable quantity output connector is enabled"
    ;
  parameter Quantity outputQuantity=Quantity.m_flow_kgps "Output quantity"
    ;
  parameter SI.AngularVelocity omega_reg = dropOfCommons.omega_reg "Normalization angular velocity"
    ;
  parameter SI.MassFlowRate m_flow_reg = dropOfCommons.m_flow_reg "Normalization mass flow rate"
    ;
  parameter SI.Density rho_min = dropOfCommons.rho_min "Minimum density (relevant at p=0)"
    ;
  parameter StateSelect omegaStateSelect = if omega_from_input then StateSelect.default else StateSelect.prefer "State select for angular velocity"
    ;
  parameter InitializationMethods initOmega = ThermofluidStream.Utilities.Types.InitializationMethods.none "Initialization method for angular velocity"
    ;
  parameter SI.AngularVelocity omega_0 = 0 "Initial value for angular velocity"
    ;
  parameter SI.AngularAcceleration omega_dot_0 = 0 "Initial value for der(omega)"
    ;
  parameter Boolean initPhi = false "= true, if angle is initialized"
    ;
  parameter SI.Angle phi_0 = 0 "Initial value for angle"
    ;

  Modelica.Mechanics.Rotational.Interfaces.Flange_a flange(phi=phi, tau=tau) if not omega_from_input "Flange"
    ;
  Modelica.Blocks.Interfaces.RealInput omega_input(unit = "rad/s") = omega if omega_from_input "Angular velocity input connector [rad/s]"
    ;
  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a heatport(Q_flow = Q_t) if enableAccessHeatPort "HeatPort"
    ;
  Modelica.Blocks.Interfaces.RealOutput output_val(unit=Sensors.Internal.getFlowUnit(outputQuantity)) = getQuantity(inlet.state, m_flow, outputQuantity, rho_min) if enableOutput "Quantity output connector"
    ;

  replaceable function dp_tau = TurboComponent.pleaseSelect_dp_tau
    constrainedby TurboComponent.partial_dp_tau(redeclare package Medium=Medium)  "Component characteristic curve"
      ;

function getQuantity = Sensors.Internal.getFlowQuantity (
  redeclare package Medium = Medium) "Function to compute a selectable quantity"
  ;

  SI.Power W_t "Power (technichal work flow rate)";
  SI.Power Q_t "Heat flow rate";
  SI.Torque tau_st "Steady-state torque";

protected
  SI.SpecificVolume v_in = 1/max(rho_min, Medium.density(inlet.state)) "Inlet specific volume";

  // intermediate quantities related to thermodynamical state
  SI.SpecificEnergy dh "Difference of specific enthalpy";

  // quantities related to inertia of component and mechanical power
  SI.Angle phi "Angle";
  SI.AngularVelocity omega(stateSelect=omegaStateSelect) "Angular velocity";
  SI.Torque tau "Torque";
  SI.Torque tau_normalized "Normalized torque";


initial equation
  if initOmega == InitializationMethods.state then
    omega = omega_0;
  elseif initM_flow == InitializationMethods.derivative then
    der(omega) = omega_dot_0;
  elseif initM_flow == InitializationMethods.steadyState then
    der(omega) = 0;
  end if;

  if initPhi then
    phi = phi_0;
  end if;

equation
  // Compute pressure difference dp, and steady-state torque tau_st
  (dp, tau_st) = dp_tau(m_flow, omega, inlet.state, m_flow_reg, omega_reg, rho_min);
  h_out = h_in + dh;
  Xi_out = Xi_in;

  // Regularize tau_st/W_t such that the equations does not break for m_flow->0
  W_t = tau_st*omega;
  dh = (m_flow*W_t)/(m_flow^2 + (m_flow_reg)^2);
  if noEvent(W_t >= 0) then
    // if work is given to fluid, dump access heat to port
    Q_t = W_t - m_flow*dh;
    tau_normalized = tau_st;
  else
    // if work is taken from fluid, reduce tau, so that the work can be taken from the fluid
    Q_t = 0;
    tau_normalized = dh*m_flow/(noEvent(if abs(omega)>omega_reg then omega else (if omega < 0 then -omega_reg else omega_reg)));
  end if;

  // Angle and angular velocity
  if noEvent(omega_from_input) then
    tau = 0;
    phi = 0;
  else
    J_p * der(omega) = tau - tau_normalized;
    omega = der(phi);
  end if

  ;
end PartialTurboComponent;

within ThermofluidStream.Processes.Internal.FlowResistance;
function laminarPressureLoss "Laminar pressure loss function (Hagen-Poiseuille)"
  extends Internal.FlowResistance.partialPressureLoss;

  import Modelica.Constants.pi;

algorithm
  pressureLoss := m_flow * (8*mu*l)/(pi*rho*r^4)

  ;
end laminarPressureLoss;

within ThermofluidStream.Processes.Internal.FlowResistance;
function laminarTurbulentPressureLoss "Pressure loss function (Cheng 2008) for laminar, transient and turbulent flow regimes"
  extends Internal.FlowResistance.partialPressureLoss;
  import Modelica.Constants.pi;

  input SI.Length ks_input(min=1e-7) = 1e-7 "Surface roughness"
    ;
  input ThermofluidStream.Processes.Internal.Material material=ThermofluidStream.Processes.Internal.Material.other "Material of pipe"
    ;

protected
  constant SI.ReynoldsNumber R_laminar_DarcyWeisbach_min = 500 "Minimal Reynolds number to use the general equation. Laminar flow before";
  SI.Length ks "Surface roughness";

  Real a(unit="1") "Laminar flow factor for the DarcyWeisbach equation (= 1 for laminar flow, = 0 for turbulent flow)";
  Real b(unit="1") "Turbulent flow factor for the DarcyWeisbach equation (= 1 for fully smooth turbulent flow, = 0 for fully rough turbulent flow)";
  Real lambda_aux(unit="1") "Darcy friction factor for Darcy-Weisbach equation";

  SI.Velocity u "Velocity";
  SI.ReynoldsNumber Re "Reynolds number";
  constant Real eps(unit="1") = 0.001;
algorithm
  if material == ThermofluidStream.Processes.Internal.Material.concrete then
    ks :=5e-3;
  elseif material == ThermofluidStream.Processes.Internal.Material.wood then
    ks :=0.5e-3;
  elseif material == ThermofluidStream.Processes.Internal.Material.castIron then
    ks :=0.25e-3;
  elseif material == ThermofluidStream.Processes.Internal.Material.galvanizedIron then
    ks :=0.15e-3;
  elseif material == ThermofluidStream.Processes.Internal.Material.steel then
    ks :=0.059e-3;
  elseif material == ThermofluidStream.Processes.Internal.Material.drawnPipe then
    ks :=0.0015e-3;
  else
    ks :=ks_input;
  end if;

  assert(ks <r, "Surface roughness shall be smaller than pipe radius");

  u :=m_flow/(r^2*pi*rho);
  // add eps to Re to avoid 0^0 error in computation of lambda_aux for Re=0 (-> a=1).
  Re :=abs(u)*rho*2*r/mu + eps;

  // cheng 2008. Formulas for Friction Factor in Transitional Regimes. Journal of Hydraulic Engineering.
  a := 1/(1+(Re/2720)^9);
  b := 1/(1+(Re/(160*2*r/ks))^2);
  //compute lambda_aux = Re*lambda to avoid division by zero at Re=0 and to avoid if-else
  lambda_aux := 64^a * Re^(1-a) * ((1.8*log10(Re/6.8))^(2*(a-1)*b) * (2*log10(3.7*2*r/ks))^(2*(a-1)*(1-b)));

  pressureLoss := lambda_aux*l*mu*u/(8*r^2)

  ;
end laminarTurbulentPressureLoss;

within ThermofluidStream.Processes.Internal.FlowResistance;
function laminarTurbulentPressureLossHaaland "Pressure loss function (Haaland 1983) for laminar, transient and turbulent flow regimes"
  extends Internal.FlowResistance.partialPressureLoss;

  import Modelica.Constants.pi;

  input SI.ReynoldsNumber Re_laminar = 2000 "Upper limit for laminar flow (Reynolds number)"
    ;
  input SI.ReynoldsNumber Re_turbulent = 4000 "Lower limit for turbulent flow (Reynolds number)"
    ;
  input Real shape_factor(unit="1") = 64 "Laminar pressure loss factor (Hagen-Poiseuille)"
    ;
  input Real n(unit="1") = 1 "Transition coefficient (see documentation)"
    ;
  input SI.Length ks_input(min=1e-7) = 1e-7 "Surface roughness"
    ;
  input ThermofluidStream.Processes.Internal.Material material = ThermofluidStream.Processes.Internal.Material.other "Material of pipe"
    ;

protected
  SI.Length ks "Surface roughness";

  SI.Length diameter=r*2 "Diameter";
  SI.Area area=pi*r^2 "Cross-sectional area";
  Real relative_roughness "Relative surface roughness";

  SI.ReynoldsNumber Re_abs "Absolute value of Reynolds number";
  SI.ReynoldsNumber Re_abs_limited "Limited absolute value of Reynolds number";

  Real friction_factor(unit="1");
  SI.Pressure pressureLossLaminar "Laminar pressure loss";
  SI.Pressure pressureLossTurbulent "Turbulent pressure loss";

  constant SI.ReynoldsNumber Re_small=1e-5 "Lower limit of turbulent Reynolds number to avoid division by zero";

algorithm
  if material == ThermofluidStream.Processes.Internal.Material.concrete then
    ks := 5e-3;
  elseif material == ThermofluidStream.Processes.Internal.Material.wood then
    ks := 0.5e-3;
  elseif material == ThermofluidStream.Processes.Internal.Material.castIron then
    ks := 0.25e-3;
  elseif material == ThermofluidStream.Processes.Internal.Material.galvanizedIron then
    ks := 0.15e-3;
  elseif material == ThermofluidStream.Processes.Internal.Material.steel then
    ks := 0.059e-3;
  elseif material == ThermofluidStream.Processes.Internal.Material.drawnPipe then
    ks := 0.0015e-3;
  else
    ks := ks_input;
  end if;

  relative_roughness := ks/diameter;

  //absolute Reynolds number
  Re_abs := abs(m_flow)*diameter/(area*mu);
  Re_abs_limited := max(Re_small, min(1, Re_abs));

  friction_factor :=
    (-1.8/n*log10((6.9/Re_abs_limited)^n + (relative_roughness/3.75)^(1.11*n)))^(-2);

  pressureLossLaminar := m_flow*mu*shape_factor*l/(2*rho*diameter^2*area);
  pressureLossTurbulent := m_flow*abs(m_flow)*friction_factor*l/(2*rho*diameter*
    area^2);

  pressureLoss := Utilities.Functions.blendFunction(
    y1=pressureLossLaminar,
    y2=pressureLossTurbulent,
    x1=Re_laminar,
    x2=Re_turbulent,
    x=Re_abs)

  ;
end laminarTurbulentPressureLossHaaland;

within ThermofluidStream.Processes.Internal.FlowResistance;
function linearQuadraticPressureLoss "Linear-quadratic pressure loss function"
  extends Internal.FlowResistance.partialPressureLoss;

  input Real k(unit="Pa.s/kg") = 0 "Linear resistance coefficient"
    ;
  input Real k2(unit="(Pa.s.s)/(kg.kg)") = 0 "Quadratic resistance coefficient"
    ;

algorithm
  pressureLoss :=k*m_flow + k2*m_flow*abs(m_flow)

  ;
end linearQuadraticPressureLoss;

within ThermofluidStream.Processes.Internal.FlowResistance;
partial function partialPressureLoss "Partial pressure loss function"
  extends Modelica.Icons.Function;

  input SI.MassFlowRate m_flow "Mass flow rate";
  input SI.Density rho "Density";
  input SI.DynamicViscosity mu "Dynamic viscosity";
  input SI.Length r(min=0) "Radius";
  input SI.Length l(min=0) "Length";

  output SI.Pressure pressureLoss "pressure loss (dp)"

  ;
end partialPressureLoss;

within ThermofluidStream.Processes.Internal.FlowResistance;
function pleaseSelectPressureLoss "Please select pressure loss function"
  extends Internal.FlowResistance.partialPressureLoss;

algorithm
  assert(false, "Please select pressure loss function");

  pressureLoss :=0

  ;
end pleaseSelectPressureLoss;

within ThermofluidStream.Processes.Internal.FlowResistance;
function referencePressureLoss "Pressure loss function based on reference values"
  extends Internal.FlowResistance.partialPressureLoss;

  input SI.Pressure dp_ref "Reference pressure loss"
    ;
  input SI.MassFlowRate m_flow_ref "Reference mass flow rate"
    ;
  input SI.Density rho_ref "Reference density"
    ;
  input ThermofluidStream.Processes.Internal.ReferencePressureDropFunction dp_function=ThermofluidStream.Processes.Internal.ReferencePressureDropFunction.linear "Pressure loss function"
    ;
  input Real m(unit = "1") = 1.5 "Exponent for pressure loss function"
    ;

algorithm
  if dp_function == ThermofluidStream.Processes.Internal.ReferencePressureDropFunction.linear then
    pressureLoss := rho_ref/rho*dp_ref*m_flow/m_flow_ref;
  elseif dp_function == ThermofluidStream.Processes.Internal.ReferencePressureDropFunction.quadratic then
    pressureLoss := rho_ref/rho*dp_ref*Modelica.Fluid.Utilities.regSquare(m_flow/m_flow_ref);
  elseif dp_function == ThermofluidStream.Processes.Internal.ReferencePressureDropFunction.customExponent then
    pressureLoss := rho_ref/rho*dp_ref*Modelica.Fluid.Utilities.regPow(m_flow/m_flow_ref, m);
  end if

  ;
end referencePressureLoss;

within ThermofluidStream.Processes.Internal.FlowResistance;
function zetaPressureLoss "Pressure loss coefficient function"
  extends Internal.FlowResistance.partialPressureLoss;

  input Real zeta( unit = "1") "Pressure loss coefficient (dp = zeta*rho/2*v^2)"
    ;

  input Boolean fromGeometry = true "= true, if cross-sectional area if calculated from geometry"
    ;
  input SI.Area A = Modelica.Constants.pi*r*r "Cross-sectional area"
    ;

protected
  SI.Area A_zeta "Cross-sectional area";

algorithm
  if fromGeometry then
    A_zeta := Modelica.Constants.pi*r*r;
  else
    A_zeta := A;
  end if;

  pressureLoss := zeta/(2*rho)*Modelica.Fluid.Utilities.regSquare(m_flow/A_zeta)

  ;
end zetaPressureLoss;

within ThermofluidStream.Processes.Internal.TurboComponent;
function dp_tau_const_isentrop "Compressor model with parameter characteristic curve and constant isentropic efficiency"
  extends partial_dp_tau;

  import R_m = Modelica.Constants.R "General gas constant";

  input Real omega_ref(unit="rad/s")= 1000 "Reference speed, that produces pr=1"
    ;
  input Real skew(unit="1") = 0 "Scewness factor for mixed part of pr equation"
    ;
  input Real m_flow_ref(unit="kg/s") = 0.25 "Reference mass_flow, that produces pr=-1"
    ;
  input Real eta(unit="1") = 1 "Isentropic efficienty"
    ;
  input Real k(unit="1") = 2 "Exponential factor used for pr<1"
    ;
  input SI.Volume V_ref= 0.001 "Reference volume for chocke torque calculation"
    ;
  input Boolean kappaFromMedia = true "=true, if isentropic coefficient is calculated using the media model"
    ;
  input Real kappa_fixed(unit="1") = 1.4 "Isentropic coefficient"
    ;


protected
  SI.Pressure p_in = Medium.pressure(state_in) "Inlet pressure";
  SI.Temperature T_in = Medium.temperature(state_in) "Inlet temperature";
  Real kappa(unit="1") = if kappaFromMedia then Medium.isentropicExponent(state_in) else kappa_fixed "Inlet isentropic coefficient";
  Real R(unit="J/(kg.K)") = R_m/Medium.molarMass(state_in) "Inlet specific gas constant";

  SI.SpecificEnergy w_t_is "Specific technical work (for isentropic reference)";
  SI.SpecificEnergy w_t "Specific technical work";
  Real pr(unit="1") "Pressure ratio = p2/p1";

algorithm
  // Calculate the pressure ratio pr from characteristic curve
  pr := abs(omega)*omega/(omega_ref^2) - skew*omega*m_flow/(omega_ref*m_flow_ref) - abs(m_flow)*m_flow/(m_flow_ref^2) + 1;
  // make sure pressure ratio is always positive
  if pr < 1 then
    pr := k^(pr-1);
  end if;
  // Calculate the pressure difference dp from the pressure ratio pr
  dp := p_in*(pr-1);

  // Compute the technical work for isentropic reference w_t_is
  if pr >= 0 then
    // use this instead of h_in - Medium.isentropicEnthalpy(p_in+dp, state_in);
    // to make it more robust, isentropicEnthalpy fails to solve often
    w_t_is := kappa/(kappa - 1)*(R*T_in*(abs(pr)^((kappa - 1)/kappa) - 1));
  end if;

  //constant isenthalpic coefficient for compression and expansion
  if w_t_is*m_flow >= 0 then
    w_t :=w_t_is/eta;
  else
    w_t :=eta*w_t_is;
  end if;

  if sign(m_flow) == 1 and sign(omega) == 1 then
    tau_st := w_t*m_flow*omega/(omega^2 + omega_norm^2);
  else
    tau_st := +V_ref*dp* omega^2/(omega^2 + omega_norm^2) * m_flow^2/(m_flow^2 + m_flow_norm^2);
  end if;
  tau_st := tau_st + V_ref*dp* omega_norm^2/(omega^2 + omega_norm^2)

  ;
end dp_tau_const_isentrop;

within ThermofluidStream.Processes.Internal.TurboComponent;
function dp_tau_nominal_flow "Pump model with the nominal massflow model"
  extends partial_dp_tau;

  input Boolean parametrizeByDesignPoint= false "= true, if pump characteristic curve is computed from one design point"
    ;
  input SI.Pressure dp_D=500000 "Design pressure difference"
    ;
  input SI.VolumeFlowRate V_flow_D(displayUnit="l/min")=0.0016666666666667 "Design volume flow rate"
    ;
  input SI.AngularVelocity omega_D=314.2 "Design angular velocity"
    ;
  input Real slip_D(unit="1", min=0, max=1) = 0.5 "Design slip ((V_flow_nominal-V_flow)/V_flow_nominal)"
    ;
  input Real eta_D(unit="1", min=0.001, max=1) = 0.75 "Design efficiency"
    ;

  input SI.Volume V_r_input=0.0001 "Reference volume of pump"
    ;
  input Real k_p_input(unit="N.s/(m5)") = 1e5 "Linear pressure factor"
    ;
  input Real k_fric_input(unit="N.s/(m2)") = 1e-2 "Linear friction factor"
    ;

protected
  SI.SpecificVolume v_in = 1/max(rho_min, Medium.density(state_in)) "Inlet specific volume";

  SI.VolumeFlowRate V_flow_nominal "Nominal volume flow rate";
  SI.VolumeFlowRate V_flow "Volume flow rate";
  //slip = (V_flow_nominal - V_flow)/V_flow_nominal

  SI.Volume V_r = if parametrizeByDesignPoint then V_flow_D*radPrevolution/omega_D/(1-slip_D) else V_r_input "Pump volume";
  Real k_p(unit="N.s/(m5)") = if parametrizeByDesignPoint then dp_D/(slip_D/(1-slip_D)*V_flow_D) else k_p_input "Linear pressure factor";
  Real k_fric(unit="N.s/(m2)") = if parametrizeByDesignPoint then (dp_D*(1-slip_D))/(slip_D*omega_D)*(1/eta_D-1) else k_fric_input "Linear frication factor";

  constant Real radPrevolution(unit="rad") = 2*Modelica.Constants.pi;

algorithm
  // calc nominal and actual flow through pump
  V_flow := v_in*m_flow;
  V_flow_nominal := omega*V_r/radPrevolution;

  //calc dp as linear resistance model and w_t as volume change work in positive flow direction
  dp := k_p*(V_flow_nominal - V_flow);
  // for positive dp, if fluid goes against pressure gradient, Work performed is positive, else negative.
  // additionally a linear friction is added.
  tau_st := V_flow*dp*omega/(omega^2 + omega_norm^2) + k_fric*(V_flow_nominal - V_flow)

  ;
end dp_tau_nominal_flow;

