within ThermofluidStream.Undirected.FlowControl;
model BasicControlValve "Basic valve model with optional flow characteristics for incompressible fluids"

  extends ThermofluidStream.Undirected.FlowControl.Internal.PartialValve;

  import FlowCoeffType = ThermofluidStream.FlowControl.Internal.Types.FlowCoefficientTypesBasic;

  replaceable function valveCharacteristics = ThermofluidStream.FlowControl.Internal.ControlValve.linearCharacteristics
    constrainedby ThermofluidStream.FlowControl.Internal.ControlValve.partialValveCharacteristics
    "Select valve characteristics"
    ;

  parameter FlowCoeffType flowCoefficient = FlowCoeffType.Kvs "Select type of flow coefficient"
    ;
  //Reference Values
  parameter Real Kvs(unit = "m3/h")  "Kvs-value (metric) from data sheet (valve fully open)"
    ;
  parameter Real Cvs_US "Cvs-value (US [gal/min]) from data sheet (valve fully open)"
    ;
  parameter Real Cvs_UK "Cvs-value (UK [gal/min]) from data sheet (valve fully open)"
    ;
  parameter SI.MassFlowRate m_flow_ref_set "Set reference mass flow in kg/s"
    ;

protected
  SI.VolumeFlowRate V_flow_ref=
    if flowCoefficient == FlowCoeffType.Kvs then Kvs/secondsPerHour
    elseif flowCoefficient == FlowCoeffType.Cvs_US then (Cvs_US/1.1561)/secondsPerHour
    elseif flowCoefficient == FlowCoeffType.Cvs_UK then (Cvs_UK/0.9626)/secondsPerHour
    else m_flow_ref_set/rho_ref "Reference volume flow rate";

equation
  //Calculate reference mass flow from reference volume flow
  m_flow_ref = V_flow_ref*rho_ref;

  k_u = valveCharacteristics(u, k_min)

  ;
end BasicControlValve;

within ThermofluidStream.Undirected.FlowControl;
model CheckValve "Valve to enforce non negative mass flow rates"

  extends ThermofluidStream.Undirected.Interfaces.SISOBiFlow(final clip_p_out=false);

  parameter SI.MassFlowRate m_flow_ref = dropOfCommons.m_flow_reg "Reference mass flow rate for regularization"
    ;
  parameter SI.Pressure p_ref = 1e5 "Reference pressure for regularization"
    ;

equation
  //Forwards model
  dp_fore = if m_flow < 0 then p_ref*((m_flow/m_flow_ref)^2) else 0;
  h_fore_out = h_rear_in;
  Xi_fore_out = Xi_rear_in;

  //Rearwards model
  dp_rear = - dp_fore; // - because of the inverted direction
  h_rear_out = h_fore_in;
  Xi_rear_out = Xi_fore_in

  ;
end CheckValve;

within ThermofluidStream.Undirected.FlowControl;
model MCV "Flow rate control valve"

  extends Interfaces.SISOBiFlow(final clip_p_out=false, final L = 100, final p_min=p_min_par);

  import Mode = ThermofluidStream.FlowControl.Internal.Types.MassflowControlValveMode;



  parameter Mode mode = Mode.mass_flow "Valve mode"
    ;
  parameter Boolean setpointFromInput = false "= true, if flow rate input connector is enabled"
    ;
  parameter SI.MassFlowRate massFlow_set_par = 0 "Mass flow rate set value"
    ;
  parameter SI.VolumeFlowRate volumeFlow_set_par = 0 "Volume flow rate set value"
    ;
  parameter SI.Time TC = 0.1 "Time constant of setpoint dynamic";
  parameter Real k1(unit="1") = 100 "Time constant factor"
    ;
  parameter Real k2(unit="1") = 100 "Integrator windup factor"
    ;
  parameter SI.Pressure p_min_par = dropOfCommons.p_min "Minimal steady-state output pressure"
    ;
  parameter Boolean enableClippingOutput = false "= true, if clippingOutput is enabled";

  Modelica.Blocks.Interfaces.RealInput setpoint_var if setpointFromInput "Flow rate input connector"
    ;
  Modelica.Blocks.Interfaces.RealOutput clippingOutput = (dp - dp_int) if enableClippingOutput ""
    ;

  SI.Density rho_rear_in = Medium.density(rear.state_forwards) "Inlet density rear port";
  SI.Density rho_fore_in = Medium.density(fore.state_rearwards) "Inlet density fore port";
  SI.Density rho_in = Undirected.Internal.regStep(m_flow, rho_rear_in, rho_fore_in, m_flow_reg) "Inlet density";


  SI.VolumeFlowRate V_flow_fore = m_flow/rho_rear_in "Volume flow rate fore port";
  SI.VolumeFlowRate V_flow_rear = m_flow/rho_fore_in "Volume flow rate rear port";
  SI.VolumeFlowRate V_flow = Undirected.Internal.regStep(m_flow, V_flow_fore, V_flow_rear, m_flow_reg) "Volume flow rate";

  constant SI.Pressure eps = 1;
  SI.Pressure dp = Undirected.Internal.regStep(m_flow, dp_fore, -dp_rear, m_flow_reg) "Pressure difference";

protected
  SI.MassFlowRate m_flow_set "Setpoint mass flow rate";
  SI.VolumeFlowRate V_flow_set "Setpoint volume flow rate";
  Modelica.Blocks.Interfaces.RealInput setpoint "Internal setpoint connector";

  SI.Pressure dr = fore.r - rear.r "Inertial pressure difference";
  SI.Pressure dr_set;
public
  SI.Pressure dp_int(start=-1e5);
  SI.Pressure dp_corr_fore = k2*(dp_fore - dp_int);
  SI.Pressure dp_corr_rear = k2*(dp_rear + dp_int);
  SI.Pressure dp_corr = Undirected.Internal.regStep(m_flow, dp_corr_fore, -dp_corr_rear, m_flow_reg);

initial equation
  dp_int = 0;

equation
  connect(setpoint_var, setpoint);
  if setpointFromInput then
    m_flow_set = setpoint;
    V_flow_set = setpoint;
  else
    setpoint = 0;
    m_flow_set = massFlow_set_par;
    V_flow_set = volumeFlow_set_par;
  end if;

  // compute dr_set required for desired mass-flow or Volume-flow dynamic
  if mode==Mode.mass_flow then
    dr_set = - L/TC * (m_flow_set - m_flow);
  else
    dr_set = - L/TC*(V_flow_set*rho_in - m_flow);
  end if;

  // compute pressure drop dynamic very fast, so dr tracks dr_set.
  // dr is limited, since it can be very high for non-smooth systems (e.g. a jump in input pressure)
  TC/k1 * der(dp_int) = max(-1e8, min(1e8,dr)) - dr_set + dp_corr;

  // limit dp to a so that p_out > p_min and no pressure is created
  dp_fore = max(p_min - p_rear_in, min(0, dp_int));
  dp_rear = max(p_min - p_fore_in, min(0, -dp_int));

  h_fore_out = h_rear_in;
  h_rear_out = h_fore_in;

  Xi_fore_out = Xi_rear_in;
  Xi_rear_out = Xi_fore_in

  ;
end MCV;

within ThermofluidStream.Undirected.FlowControl;
model SpecificValveType "Specific technical valve types"

  extends ThermofluidStream.Undirected.FlowControl.Internal.PartialValve;

  import FlowCoeffType = ThermofluidStream.FlowControl.Internal.Types.FlowCoefficientTypes;

  replaceable record ZetaValueRecord = ThermofluidStream.FlowControl.Internal.Curves.SlideValveZetaCurve
    constrainedby ThermofluidStream.FlowControl.Internal.Curves.PartialCharacteristicZetaCurves "Select valve type"
    ;

  parameter FlowCoeffType flowCoefficient = FlowCoeffType.Kvs "Select type of flow coefficient"
    ;
  //Set valve data as parameter
  parameter Modelica.Units.SI.Diameter d_valve "Flow diameter"
    ;
  //Reference Values
  parameter Real Kvs(unit = "m3/h")  "Kvs-value (metric) from data sheet (valve fully open)"
    ;
  parameter Real Cvs_US "Cvs-value (US [gal/min]) from data sheet (valve fully open)"
    ;
  parameter Real Cvs_UK "Cvs-value (UK [gal/min]) from data sheet (valve fully open)"
    ;
  parameter SI.MassFlowRate m_flow_ref_set "Set reference mass flow in kg/s"
    ;

protected
  constant ZetaValueRecord valveData;
  Modelica.Units.SI.Area A_valve=0.25*Modelica.Constants.pi*d_valve^2 "Cross-sectional valve area";

  Real k_u(unit="1") "Kv/Kvs, respecting flow characteristics";
  Real k_u_zeta(unit="1") "Kv/Kvs respecting zeta curve";

  Modelica.Blocks.Tables.CombiTable1Ds combiTable1D_zeta(
  final smoothness = Modelica.Blocks.Types.Smoothness.MonotoneContinuousDerivative1,
  final tableOnFile = false,
  final table = valveData.zetaTable) "Interpolation of pressure loss coefficient datapoints";

  Real zeta(unit="1", start = 0) "Pressure loss coefficient";
  Real zeta1(unit="1") = valveData.zetaTable[end,2] "Pressure loss coefficient for fully opened valve";

  SI.VolumeFlowRate V_flow_ref=
    if flowCoefficient == FlowCoeffType.Kvs then Kvs/secondsPerHour
    elseif flowCoefficient == FlowCoeffType.Cvs_US then (Cvs_US/1.1561)/secondsPerHour
    elseif flowCoefficient == FlowCoeffType.Cvs_UK then (Cvs_UK/0.9626)/secondsPerHour
    elseif flowCoefficient == FlowCoeffType.flowDiameter then A_valve*sqrt((2/zeta1)*(dp_ref/rho_ref))
    else m_flow_ref_set/rho_ref "Reference volume flow rate";

equation
  //Calculate reference mass flow rate from reference volume flow rate
  m_flow_ref = V_flow_ref*rho_ref;

  //Retrieving pressure loss coefficient from input
  combiTable1D_zeta.u = u;
  zeta = combiTable1D_zeta.y[1];

  //Evaluate characteristic for given pressure loss curve
  k_u_zeta = sqrt(zeta1/zeta);

  k_u = k_min + (1 - k_min)*k_u_zeta

  ;
end SpecificValveType;

within ThermofluidStream.Undirected.FlowControl;
model TanValve "Valve with tan-shaped flow resistance"

  extends ThermofluidStream.Undirected.Interfaces.SISOBiFlow(final clip_p_out=true);

  Modelica.Blocks.Interfaces.RealInput u(unit="1") "Valve control input []"
    ;

  parameter Utilities.Units.Inertance L = dropOfCommons.L "Inertance"
    ;
  parameter Boolean invertInput = false "= true, if input u is inverted"
    ;
  parameter SI.MassFlowRate m_flow_ref = 0.1 "Reference mass flow rate";
  parameter SI.Pressure p_ref = 1e5 "Reference pressure";
  parameter Real relativeLeakiness(unit="1") = 1e-3 "Imperfection of valve";

protected
  Real k(unit="(Pa.s)/kg");
  Real u2(unit="1");

equation
  if invertInput then
    u2 = max(relativeLeakiness,min(1-relativeLeakiness,u));
  else
    u2 = max(relativeLeakiness,min(1-relativeLeakiness,1-u));
  end if;

  k = p_ref/m_flow_ref*tan(u2*Modelica.Constants.pi/2);

  //forwards model
  dp_fore = -k*m_flow;
  h_fore_out = h_rear_in;
  Xi_fore_out = Xi_rear_in;

  //rearwards model
  dp_rear = - dp_fore; // - because of the inverted direction
  h_rear_out = h_fore_in;
  Xi_rear_out = Xi_fore_in

  ;
end TanValve;

within ThermofluidStream.Undirected.FlowControl.Internal;
partial model PartialValve "Partial valve model"

  extends Interfaces.SISOBiFlow(final clip_p_out=true);

  parameter Boolean invertInput = false "= true, if input u_in is inverted"
    ;
  parameter Real k_min(unit="1", min = 0.001, max = 1) = 0.03 "Remaining flow at actuation signal u = 0 (fraction of maximum mass flow at u = 1)";


  parameter Modelica.Units.SI.Pressure dp_ref=1e5 "Reference pressure difference"
    ;
  parameter Modelica.Units.SI.Density rho_ref=1000 "Reference density"
    ;

  Modelica.Blocks.Interfaces.RealInput u_in(unit="1") "Valve control signal []"
    ;

  Real u(unit="1") "Actuation input for flow calculation";

protected
  constant Real secondsPerHour(final unit="s/h") = 3600 "Parameter for unit conversion";

  //Medium properties
  Modelica.Units.SI.Density rho_rear_in=Medium.density(rear.state_forwards) "Inlet density rear port";
  Modelica.Units.SI.Density rho_fore_in=Medium.density(fore.state_rearwards) "Inlet density fore port";

  SI.MassFlowRate m_flow_ref "Reference mass flow derived from flow coefficient inputs";
  Real k_u(unit="1") "Kv/Kvs, respecting flow characteristics";

equation
  //Inversion of input signal, actuation has to be between 0 and 1
  assert(u_in <=1 and u_in >=0, "Actuator signal out of valid range [0,1]", level = AssertionLevel.warning);
  if invertInput then
      u = max(0, min(1, 1-u_in));
  else
      u = max(0, min(1, u_in));
  end if;

   //forwards model
  dp_fore = -sign(m_flow)*dp_ref*(rho_ref/rho_rear_in)*(1/(k_u)*(m_flow/m_flow_ref))^2;
  h_fore_out = h_rear_in;
  Xi_fore_out = Xi_rear_in;

  //rearwards model
  dp_rear = sign(m_flow)*dp_ref*(rho_ref/rho_fore_in)*(1/(k_u)*(m_flow/m_flow_ref))^2;
  h_rear_out = h_fore_in;
  Xi_rear_out = Xi_fore_in

  ;
end PartialValve;

