within ThermofluidStream.Undirected.HeatExchangers;
model DiscretizedCounterFlowHEX "Discretized heat exchanger for single- or two-phase working fluids without pressure drop"

  extends Internal.PartialDiscretizedHEX;

initial equation
  if initializeMassFlow then
    rearA.m_flow = m_flow_0_A;
    rearB.m_flow = m_flow_0_B;
  end if;

equation
  //Connecting equations (to interconnect pipes)
  //Fluid side B
  connect(rearB, thermalElementB[1].rear) ;
  for i in 1:nCells - 1 loop
    connect(thermalElementB[i].fore, thermalElementB[i + 1].rear);
  end for;
  connect(thermalElementB[nCells].fore, foreB) ;

  //Fluid side A
  connect(rearA, thermalElementA[1].rear) ;
  for i in 1:nCells - 1 loop
    connect(thermalElementA[i].fore, thermalElementA[i + 1].rear);
  end for;
  connect(thermalElementA[nCells].fore, foreA) ;

  connect(thermalElementB.heatPort, thermalConductor.port_b) ;

  for i in 1:nCells loop
    connect(thermalElementA[i].heatPort, thermalConductor[nCells + 1 - i].port_a) ;
  end for

  ;
end DiscretizedCounterFlowHEX;

within ThermofluidStream.Undirected.HeatExchangers;
model DiscretizedCrossFlowHEX "Discretized heat exchanger for single- or two-phase working fluid without pressure drop"

  extends Internal.PartialDiscretizedHEX(nCellsParallel=nCells,final crossFlow=true);

  Processes.FlowResistance flowResistanceA[nCells](
    redeclare package Medium = MediumA,
    each r(each displayUnit="mm") = 0.025,
    each l=1,
    redeclare function pLoss = ThermofluidStream.Processes.Internal.FlowResistance.linearQuadraticPressureLoss (each k=50)) ;
  Topology.JunctionMN junctionMN(
    redeclare package Medium = MediumA,
    N=1,
    M=nCells) ;
  Topology.JunctionMN junctionMN1(redeclare package Medium = MediumA, N=nCells) ;

initial equation

  if initializeMassFlow then
    rearB.m_flow = m_flow_0_B;
    flowResistanceA.m_flow = m_flow_0_A/nCells*ones(nCells);
  else
    for i in 1:nCells - 1 loop
      flowResistanceA[i + 1].m_flow = flowResistanceA[1].m_flow;
    end for;
  end if;

equation
  //Connecting equations (to interconnect pipes)

  //Fluid side B
  connect(rearB, thermalElementB[1].rear) ;
  for i in 1:nCells - 1 loop
    connect(thermalElementB[i].fore, thermalElementB[i + 1].rear);
  end for;
  connect(thermalElementB[nCells].fore, foreB) ;

  connect(thermalElementA.heatPort, thermalConductor.port_a) ;
  connect(thermalElementB.heatPort, thermalConductor.port_b) ;

  //Fluid side A
  connect(junctionMN1.fores[1], foreA) ;
  connect(junctionMN.rears[1], rearA) ;
  connect(junctionMN.fores, thermalElementA.rear) ;
  connect(flowResistanceA.rear, thermalElementA.fore) ;
  connect(flowResistanceA.fore, junctionMN1.rears) 

  ;
end DiscretizedCrossFlowHEX;

within ThermofluidStream.Undirected.HeatExchangers.Internal;
model ConductionElementHEX "ConductionElement for single-phase fluids"

  extends PartialConductionElementHEX;

  parameter SI.CoefficientOfHeatTransfer U_nom = 3000 "Nominal heat transfer coefficient to medium";
  parameter SI.MassFlowRate m_flow_nom = 1 "Nominal mass flow rate for heat transfer calculation"
    ;

  constant Real Re_exp = 0.8 "Reynolds-exponent for heat transfer calculation";

initial equation
  assert(init <> Processes.Internal.InitializationMethodsCondElement.port, "This initialization will lead to large nonlinear equation systems. Please choose 'T0', 'h0', 'rear' or 'fore'.");

equation
  //Estimation of heat transfer coefficient
  U = max(U_min, U_nom*(abs(m_flow/(m_flow_nom/nCellsParallel)))^Re_exp)

  ;
end ConductionElementHEX;

within ThermofluidStream.Undirected.HeatExchangers.Internal;
model ConductionElementHEX_twoPhase "ConductionElement for two-phase fluids"

  extends PartialConductionElementHEX(redeclare replaceable package Medium = Media.myMedia.Interfaces.PartialTwoPhaseMedium);

  import Modelica.Math;

  parameter SI.CoefficientOfHeatTransfer U_liq_nom = 700 "Nominal coefficient of heat transfer for liquid region";
  parameter SI.CoefficientOfHeatTransfer U_vap_nom = 500 "Nominal coefficient of heat transfer for vapour region";
  parameter SI.CoefficientOfHeatTransfer U_tp_nom = 1000 "Nominal coefficient of heat transfer for two-phase region";

  parameter SI.MassFlowRate m_flow_nom = 0.3 "Nominal mass-flow rate for heat transfer calculation";
  parameter SI.MassFraction delta_x = 0.05 "Value for interpolation width";

  constant Real Re_exp_cond(unit="1") = 0.4 "Reynolds-Exponent for heat transfer calculation at condensation (Yan&Lin, 1999)";
  constant Real Re_exp_evap(unit="1") = 0.5 "Reynolds-Exponent for heat transfer calculation at evaporation (Yan&Lin, 1999)";

  Real x "Vapor quality calculated from enthalpies";

protected
  SI.CoefficientOfHeatTransfer U_liq "Coefficient of heat transfer for liquid region";
  SI.CoefficientOfHeatTransfer U_tp "Coefficient of heat transfer for two-phase region";
  SI.CoefficientOfHeatTransfer U_vap "Coefficient of heat transfer for vapour region";

  SI.SpecificEnthalpy h_dew = Medium.dewEnthalpy(Medium.setSat_p(Medium.pressure(state))) "Dew enthalpy at inlet";
  SI.SpecificEnthalpy h_bubble = Medium.bubbleEnthalpy(Medium.setSat_p(Medium.pressure(state))) "Bubble enthalpy at inlet";

initial equation
  assert(init <> Processes.Internal.InitializationMethodsCondElement.port, "This initialization will lead to large nonlinear equation systems. Please choose 'h0', 'rear' or 'fore'.");
  assert(init <> Processes.Internal.InitializationMethodsCondElement.T, "Temperature might is not independent of pressrue in the 2-phase area. Please choose 'h0', 'rear' or 'fore'.");

equation
  //1) Calculated from enthalpies --> can go below zero and above one (needed for heat transfer calculations)!
  x = (h - h_bubble)/(h_dew - h_bubble);

  U_liq = max(U_min, U_liq_nom*(abs(m_flow)/(m_flow_nom/nCellsParallel))^Re_exp_cond);
  U_vap = max(U_min, U_vap_nom*(abs(m_flow)/(m_flow_nom/nCellsParallel))^Re_exp_evap);
  U_tp = max(U_min, U_tp_nom);

  //Coefficient of heat transfer dependent on vapor quality (interpolation in phase-transition regions)
  U = smooth(1, noEvent(
      if x < -delta_x then U_liq
      elseif x < delta_x then U_liq + 0.5*(U_tp - U_liq)*(1 + Math.sin(x*Modelica.Constants.pi/(2*delta_x)))
      elseif x < 1 - delta_x then U_tp
      elseif x < 1 + delta_x then U_tp + 0.5*(U_vap - U_tp)*(1 + Math.sin((x - 1)*Modelica.Constants.pi/(2*delta_x)))
      else U_vap))

  ;
end ConductionElementHEX_twoPhase;

within ThermofluidStream.Undirected.HeatExchangers.Internal;
partial model PartialConductionElementHEX "Parent for CEs for discretizedHEX"

  extends Processes.Internal.PartialConductionElement(final neglectPressureChanges=true);

  parameter SI.Area A = 1 "Heat transfer area";
  parameter Integer nCellsParallel = 1 "Number of parallel discretization elements";

  constant SI.CoefficientOfHeatTransfer U_min = 1 "Minimum thermal transmittance for temperature adaption at zero massflow";

  SI.CoefficientOfHeatTransfer U "Thermal transmittance";

equation
  k = U*A

  ;
end PartialConductionElementHEX;

