within ThermofluidStream.Undirected.Internal;
function regStep
  "Approximation of a general step, such that the characteristic is continuous and differentiable"
  extends Modelica.Icons.Function;
  input Real x "Abscissa value";
  input Real y1 "Ordinate value for x > 0";
  input Real y2 "Ordinate value for x < 0";
  input Real x_small(min=0) = 1e-5
    "Approximation of step for -x_small <= x <= x_small; x_small >= 0 required";
  output Real y "Ordinate value to approximate y = if x > 0 then y1 else y2";
algorithm
  y := smooth(1, if x >  x_small then y1 else
                 if x < -x_small then y2 else
                 if x_small > 0 then (x/x_small)*((x/x_small)^2 - 3)*(y2-y1)/4 + (y1+y2)/2 else (y1+y2)/2)
  ;
end regStep;

within ThermofluidStream.Undirected.Internal;
function regStepState "Apply regStep on State"
  extends Modelica.Icons.Function;

  replaceable package Medium = Media.myMedia.Interfaces.PartialMedium
    "Medium model"
    ;

  input SI.MassFlowRate m_flow;
  input Medium.ThermodynamicState state_forwards;
  input Medium.ThermodynamicState state_rearwards;
  input SI.MassFlowRate m_flow_reg;

  output Medium.ThermodynamicState state;

protected
  SI.Pressure p;
  SI.SpecificEnthalpy h;
  Medium.MassFraction Xi[Medium.nXi];

  Medium.MassFraction Xi_forwards[Medium.nXi] = Medium.massFraction(state_forwards);
  Medium.MassFraction Xi_rearwards[Medium.nXi] = Medium.massFraction(state_rearwards);

algorithm
  p := regStep(m_flow, Medium.pressure(state_forwards), Medium.pressure(state_rearwards), m_flow_reg);
  h := regStep(m_flow, Medium.specificEnthalpy(state_forwards), Medium.specificEnthalpy(state_rearwards), m_flow_reg);
  for i in 1:Medium.nXi loop
    Xi[i] := regStep(m_flow, Xi_forwards[i], Xi_rearwards[i], m_flow_reg);
  end for;

  state := Medium.setState_phX(p, h, Xi)

  ;
end regStepState;

within ThermofluidStream.Undirected.Processes;
model ConductionElement "Model of quasi-sationary mass and heat transfer"

  extends Internal.PartialConductionElement;

  parameter Boolean resistanceFromAU = true "= true, if thermal conductance is given by U*A"
    ;
  parameter SI.Area A = 1 "Heat transfer area"
    ;
  parameter SI.CoefficientOfHeatTransfer U = 200 "Thermal transmittance"
    ;
  parameter SI.ThermalConductance k_par = 200 "Thermal conductance"
    ;
  final parameter SI.ThermalConductance k_internal = if resistanceFromAU then A*U else k_par;

  // ------ Parameter Display Configuration  ------------------------
  parameter Boolean displayVolume = true "= true, if volume V is displayed"
    ;
  parameter Boolean displayConduction = true "= true, if thermal conductance is displayed"
    ;
  final parameter Boolean displayAnything = displayParameters and (displayVolume or displayConduction)
    ;
  final parameter String parameterString=
    if displayParameters and displayVolume and displayConduction then
      "V=%V, "+conductionString
    elseif displayParameters and displayVolume and not displayConduction then
      "V=%V"
    elseif  displayParameters and not displayVolume  and displayConduction then
      conductionString
    else "" ;
  final parameter String conductionString=
    if resistanceFromAU then "A=%A, U=%U"
    else "k=%k_par" ;
  //-----------------------------------------------------------------

equation
  k = k_internal

  ;
end ConductionElement;

within ThermofluidStream.Undirected.Processes;
model FlowResistance "Flow resistance model"
  extends Interfaces.SISOBiFlow(final L=if computeL then l/(r^2*pi) else L_value, final clip_p_out=true);

  import Modelica.Constants.pi "Constant number pi";

  parameter SI.Radius r(min=0) "Radius";
  parameter SI.Length l(min=0) "Length";
  replaceable function pLoss = ThermofluidStream.Processes.Internal.FlowResistance.pleaseSelectPressureLoss
    constrainedby ThermofluidStream.Processes.Internal.FlowResistance.partialPressureLoss
    "Pressure loss function"
    ;

  parameter Boolean computeL = true "= true, if inertance L is computed from the geometry"
    ;
  parameter Utilities.Units.Inertance L_value = dropOfCommons.L "Inertance"
    ;
  parameter SI.Density rho_min = dropOfCommons.rho_min "Minium inlet density"
    ;

protected
  SI.Density rho_rear_in = max(rho_min, Medium.density(rear.state_forwards)) "Inlet density of rear port";
  SI.DynamicViscosity mu_rear_in = Medium.dynamicViscosity(rear.state_forwards) "Inlet dynamic viscosity of rear port";

  SI.Density rho_fore_in = max(rho_min, Medium.density(fore.state_rearwards)) "Inlet density of fore port";
  SI.DynamicViscosity mu_fore_in = Medium.dynamicViscosity(fore.state_rearwards) "Inlet dynamic viscosity of fore port";

equation
  //Forwards model
  dp_fore = -pLoss(m_flow, rho_rear_in, mu_rear_in, r, l);
  h_fore_out = h_rear_in;
  Xi_fore_out = Xi_rear_in;

  //Rearwards model
  dp_rear = -pLoss(-m_flow, rho_fore_in, mu_fore_in, r, l);
  h_rear_out = h_fore_in;
  Xi_rear_out = Xi_fore_in

  ;
end FlowResistance;

within ThermofluidStream.Undirected.Processes;
model TransportDelay "Delay model based on fluid velocity"

  extends ThermofluidStream.Undirected.Interfaces.SISOBiFlow(final clip_p_out=false);

  parameter SI.Length l "Length";
  parameter SI.Radius r "Radius";
  parameter SI.Density rho_min = dropOfCommons.rho_min "Minimum density"
    ;
  parameter Real v_min(unit="1/s", min=0) = 0.01 "Minimum nondimensional speed"
    ;
  parameter Real v_max(unit="1/s", min=0) = 50 "Maximum nondimensional speed"
    ;

  // ------ Parameter Display Configuration  ------------------------
  parameter Boolean displayLength = true "= true, if length l is displayed"
    ;
  parameter Boolean displayRadius = true "= true, if radius r is displayed"
    ;
  final parameter Boolean d1l = displayParameters and displayLength  "displayLength at position 1"
    ; //d1l -> Display at position 1 l=length
  final parameter Boolean d1r = displayParameters and displayRadius and not d1l  "displayRadius at position 1"
    ;
  final parameter Boolean d2r = displayParameters and displayRadius and not d1r  "displayRadius at position 2"
    ;
  //-----------------------------------------------------------------

  constant Medium.ThermodynamicState state_0 = Medium.setState_phX(Medium.p_default, Medium.h_default, Medium.X_default[1:Medium.nXi]) "Default medium state";
  constant SI.MassFraction Xi_0[Medium.nXi] = Medium.massFraction(state_0) "Default mass fractions";
  constant SI.SpecificVolume v_0 = 1/Medium.density(state_0) "Default specific volume";

  Real x(unit="1") "Relative position s/l";
  Real v(unit="1/s") "Relative speed v/l";

protected
  SI.SpecificInternalEnergy u_rear_in = Medium.specificInternalEnergy(rear.state_forwards) "Inlet internal energy rear port";
  SI.SpecificInternalEnergy u_fore_in = Medium.specificInternalEnergy(fore.state_rearwards) "Inlet internal energy fore port";
  SI.SpecificVolume v_rear_in = 1/max(rho_min, Medium.density(rear.state_forwards)) "Inlet specific volume rear port";
  SI.SpecificVolume v_fore_in = 1/max(rho_min, Medium.density(fore.state_rearwards)) "Inlet specific volume fore port";

  SI.SpecificInternalEnergy u_rear_out "Outlet internal energy rear port";
  SI.SpecificInternalEnergy u_fore_out "Outlet internal energy fore port";
  SI.SpecificVolume v_rear_out "Outlet specific volume rear port";
  SI.SpecificVolume v_fore_out "Outlet specific volume fore port";

  SI.Area A = r^2*Modelica.Constants.pi "Cross-sectional area";

initial equation
  x = 0;

equation
  if m_flow >= 0 then
    v = min(v_max, max(v_min, m_flow*v_rear_in/A/l));
  else
    v = -min(v_max, max(v_min, -m_flow*v_fore_in/A/l));
  end if;

  der(x) = v;

  (u_rear_out,u_fore_out) = spatialDistribution(u_rear_in, u_fore_in,
    x, v>=0,
    initialPoints = {0.0,1.0},
    initialValues = {Medium.specificInternalEnergy(state_0), Medium.specificInternalEnergy(state_0)});
  (v_rear_out,v_fore_out) = spatialDistribution(v_rear_in, v_fore_in,
    x, v>=0,
    initialPoints = {0.0,1.0},
    initialValues = {v_0, v_0});

  for i in 1:Medium.nXi loop
    (Xi_rear_out[i], Xi_fore_out[i]) = spatialDistribution(Xi_rear_in[i], Xi_fore_in[i],
      x, v>=0,
      initialPoints = {0.0,0.0},
      initialValues = {Xi_0[i], Xi_0[i]});
  end for;

    //Forwards model
  dp_fore = 0;
  h_fore_out = u_fore_out + p_fore_out * v_fore_out;
  Xi_fore_out = Xi_rear_in;

  //Rearwards model
  dp_rear = 0;
  h_rear_out = u_rear_out + p_rear_out * v_rear_out;
  Xi_rear_out = Xi_fore_in
  ;
end TransportDelay;

within ThermofluidStream.Undirected.Processes.Internal;
partial model PartialConductionElement "Partial model of quasi-stationary mass and heat transfer"

  extends Interfaces.SISOBiFlow(final clip_p_out=false);

  parameter SI.Volume V(displayUnit="l")=0.001 "Volume";
  parameter ThermofluidStream.Undirected.Processes.Internal.InitializationMethodsCondElement init=ThermofluidStream.Undirected.Processes.Internal.InitializationMethodsCondElement.rear "Initialization method for specific enthalpy"
    ;
  parameter SI.Temperature T_0 = Medium.T_default "Initial Temperature"
    ;
  parameter SI.SpecificEnthalpy h_0 = Medium.h_default "Initial specific enthalpy"
    ;
  parameter SI.Density rho_min = dropOfCommons.rho_min "Minimal density"
    ;
  parameter Boolean neglectPressureChanges = true "=true, if pressure changes are neglected"
    ;
  parameter SI.MassFlowRate m_flow_reg = dropOfCommons.m_flow_reg "Regularization massflow to switch between positive- and negative-massflow model"
    ;
  parameter Boolean enforce_global_energy_conservation = false "= true, if global conservation of energy is enforced"
    ;
  parameter SI.Time T_e = 100 "Time constant for global conservation of energy"
    ;

  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a heatPort(Q_flow=Q_flow, T=T_heatPort)
    ;

  SI.SpecificEnthalpy h(start=Medium.h_default, stateSelect = StateSelect.prefer) "Medium specific enthalpy";

  Medium.ThermodynamicState state = Medium.setState_phX(p, h, Xi) "Medium thermodynamic state";
  SI.Temperature T = Medium.temperature(state) "Medium temperature";
  SI.ThermalConductance k "Thermal conductance";

  SI.Energy deltaE_system(start=0, fixed=true) "Energy difference between m_flow*(h_in-h_out) and Q_flow";

  SI.Mass M "Medium mass";

protected
  SI.Pressure p = Undirected.Internal.regStep(m_flow, p_rear_in, p_fore_in, m_flow_reg) "Pressure";
  Medium.MassFraction[Medium.nXi] Xi = Undirected.Internal.regStep(m_flow, Xi_rear_in, Xi_fore_in, m_flow_reg) "Mass fractions";
  //h_in only in rhs of ODE--> h still smooth, better results at low massflow than using regStep
  SI.SpecificEnthalpy h_in = if m_flow >= 0 then h_rear_in else h_fore_in "Inlet specific enthalpy";

  SI.Density rho = max(rho_min, Medium.density(state)) "Medium density";
  SI.SpecificEnthalpy h_out = Medium.specificEnthalpy(state) "Outlet specific enthalpy";

  SI.Temperature T_heatPort "Heatport temperature";
  SI.HeatFlowRate Q_flow "Heat flow rate";

initial equation
  if init == Internal.InitializationMethodsCondElement.T then
     h = Medium.specificEnthalpy(Medium.setState_pTX(p, T_0, Xi));
  elseif init == Internal.InitializationMethodsCondElement.h then
     h = h_0;
  elseif init == InitializationMethodsCondElement.port then
     h = h_in;
  elseif init == Internal.InitializationMethodsCondElement.fore then
     h = h_fore_in;
   else
     h = h_rear_in;
   end if;

equation
  //mass is assumed to be quasisationary-> this violates the conservation of mass since m_flow_in = -m_flow_out. see documentation/information
  M = V*rho;

  // Mass is assumed to be (quasi-)stationary-> assumption: der(M)=0.
  // V=const
  // lhs: der(U) = der(H - pV) = der(M)*h +  M*der(h) - V*der(p) = M*der(h)
  // one can not simply add der(M)*h to the left side, since the right side is also assuming sationary mass (m_flow_in=-m_flow_out)
  // on RHS: Q_flow + m_flow_in*h_in + m_flow_out*h = Q_flow + m_flow_in*h_in + (m_flow_in-m_flow_in+ m_flow_out)*h = Q_flow + m_flow_in*(h_in-h) + der(M)*h = Q_flow + m_flow*(h_in-h)
  // or:     Q_flow + m_flow_in*h_in + m_flow_out*h = Q_flow + (m_flow_in+m_flow_out-m_flow_out)*h_in + m_flow_out*h = Q_flow + m_flow_out*(h-h_in) + der(M)*h_in = Q_flow + m_flow*(h_in - h)
  // so there is a resulting term on the RHS with der(M)*(h(k) + h_out(1-k)) with k in [0,1]; that also would have to be accounted for when der(M) not 0 on LHS
  // to improve the equation p_in and M would have to be filtered and a value for k would have to be found, all that resulted in only moderate improvements
  // therefore energy that is accumulated with system border around the component (deltaE_system) is slowly fed back into the system when enforce_global_energy_conservation is true
  //(then energy stored in the system e.g. by evaproation/condension, while still being visible short-term, neglegted in logterm)
  if not neglectPressureChanges then
    M*der(h) = Q_flow + abs(m_flow)*(h_in - h_out) + V*der(p) + (if enforce_global_energy_conservation then deltaE_system/T_e else 0);
  else
    //neglegt V*der(p), since p might not be smooth -> to notice a difference der(p) must be about 1e7 Pa/s. see documentation/information
    M*der(h) = Q_flow + abs(m_flow)*(h_in - h_out) + (if enforce_global_energy_conservation then deltaE_system/T_e else 0);
  end if;
  if enforce_global_energy_conservation then
    der(deltaE_system) = Q_flow + abs(m_flow)*(h_in - h_out);
  else
    deltaE_system = 0;
  end if;

  Q_flow = k*(T_heatPort - T);

  //Forwards model
  dp_fore = 0;
  h_fore_out = h;
  Xi_fore_out = Xi_rear_in;

  //Rearwards model
  dp_rear = 0;
  h_rear_out = h;
  Xi_rear_out = Xi_fore_in

  ;
end PartialConductionElement;

