  parameter Boolean continuous_flow_reversal=false "true: continuous flow reversal - false: discontinuous flow reversal";
  parameter Boolean diffusion=false "true: energy balance equation with diffusion - false: energy balance equation without diffusion";

  Volumes.TwoPhaseCavityOnePipe DynamicCondenser(
    Vf0=Vf0,
    P0=P0c,
    Ns=Ns,
    L2=L2,
    NbTubT=ntubest,
    Lc=Lc,
    NbTubV=ntubesV,
    Dext=Dc + 2*ec,
    R=Rv,
    L=Lv,
    Vertical=true,
    wsftype=wsftype,
    dynamic_energy_balance=dynamic_energy_balance,
    steady_state=steady_state,
    continuous_flow_reversal=continuous_flow_reversal,
    diffusion=diffusion)
    ;
  DynamicOnePhaseFlowPipe pipe_3(
    D=Dc,
    L=L2,
    ntubes=ntubest,
    Ns=Ns,
    dynamic_energy_balance=dynamic_energy_balance,
    dynamic_mass_balance=dynamic_mass_balance,
    simplified_dynamic_energy_balance=simplified_dynamic_energy_balance,
    steady_state=steady_state,
    continuous_flow_reversal=continuous_flow_reversal,
    diffusion=diffusion,
    advection=advection,
    option_temperature=option_temperature,
    inertia=inertia,
    T0=T0,
    h0=h0)
    ;
  Interfaces.Connectors.FluidInlet  C1vap "Vapor inlet" ;
  Interfaces.Connectors.FluidOutlet  C2ex "Condensed water extraction outlet"
    ;
  Interfaces.Connectors.FluidInlet  Ce1 "Cooling water inlet" ;
  Interfaces.Connectors.FluidOutlet  Ce2 "Cooling water outlet" ;
  ThermoSysPro.InstrumentationAndControl.Connectors.OutputReal sortieReelle
    ;

  Interfaces.Connectors.FluidInlet  C1 "Extra water inlet" ;
  Thermal.HeatTransfer.HeatExchangerWall Wall_3(
    D=Dc,
    e=ec,
    lambda=lambda,
    cpw=cp,
    rhow=rho,
    L=L2,
    Ns=Ns,
    ntubes=ntubest,
    dynamic_energy_balance=dynamic_energy_balance,
    steady_state=steady_state)
    ;
  Interfaces.Connectors.FluidInlet  C2vap "Vapor inlet" ;
equation

  if (cardinality(C1) == 1) then
    C1.Q = 0;
    C1.h = 1.e5;
    C1.h_vol_1 = 1.e5;
    C1.diff_res_1 = 0;
    C1.diff_on_1 = false;
    C1.ftype = ftype;
    C1.Xco2 = 0;
    C1.Xh2o = 1;
    C1.Xo2 = 0;
    C1.Xso2 = 0;
  end if;

  if (cardinality(C2vap) == 1) then
    C2vap.Q = 0;
    C2vap.h = 1.e5;
    C2vap.h_vol_1 = 1.e5;
    C2vap.diff_res_1 = 0;
    C2vap.diff_on_1 = false;
    C2vap.ftype = ftype;
    C2vap.Xco2 = 0;
    C2vap.Xh2o = 1;
    C2vap.Xo2 = 0;
    C2vap.Xso2 = 0;
  end if;

  connect(DynamicCondenser.Cl, C2ex)
                               ;
  connect(DynamicCondenser.yLevel, sortieReelle)
    ;
  connect(DynamicCondenser.Cth3, Wall_3.WT2)
                                      ;
  connect(Wall_3.WT1, pipe_3.CTh) ;
  connect(DynamicCondenser.CvBP, C1vap)
    ;
  connect(C2vap, DynamicCondenser.CvGCT)
    ;
  connect(pipe_3.C2, Ce2) ;
  connect(pipe_3.C1, Ce1)
    ;
  connect(C1, DynamicCondenser.Ce) 
  ;
end DynamicCondenser;

