within TILMedia;
model SLEMedium
  "Medium with solid-liquid equilibrium (SLE), with h and p as independent variables"

  replaceable model SLEMediumType = TILMedia.SLEMediumTypes.TILMedia_SodiumAcetate
    constrainedby TILMedia.SLEMediumTypes.BaseSLEMedium "Type of the SLE medium"
    ;

  input SI.SpecificEnthalpy h "Specific enthalpy" ;
  SI.Density d "Density";
  input SI.AbsolutePressure p "Pressure" ;
  input SI.MassFraction iota=0 "metastable state transition [0,1]" ;
  SI.Temperature T "Temperature";
  SI.SpecificHeatCapacity cp "Specific heat capacity";
  SI.MassFraction q "Liquid mass fraction";
  SI.ThermalConductivity lambda "Thermal conductivity";
  SI.SpecificEnthalpy h_fusion=sleMedium.h_fusion;
  constant SI.Temperature TStableLimit=sleMedium.TStableLimit
    "Above this temperature all cristals in the solution are dissolved. Metastable states are possible after exceeding this temperature.";
  constant SI.Temperature TSupercoolingLimit(min=-Modelica.Constants.inf) = sleMedium.TSupercoolingLimit
    "There is no metastable state below this temperature. Crystallization starts when this temperature is reached.";

  function density_h = TILMedia.Internals.SLEMediumFunctions.density_h (
      d_s=sleMedium.d_s,
      d_l=sleMedium.d_l,
      h_fusion=sleMedium.h_fusion);
  function specificEnthalpy_T = TILMedia.Internals.SLEMediumFunctions.specificEnthalpy_T (
      TSupercoolingLimit=sleMedium.TSupercoolingLimit,
      cp_s=sleMedium.cp_s,
      cp_l=sleMedium.cp_l,
      T_s=sleMedium.T_s,
      T_l=sleMedium.T_l,
      h_fusion=sleMedium.h_fusion);
protected
  SLEMediumType sleMedium(T=T);
equation
  q = TILMedia.Internals.SLEMediumFunctions.quality_h(
    h,
    iota,
    sleMedium.cp_s,
    sleMedium.cp_l,
    sleMedium.h_fusion,
    sleMedium.T_s,
    sleMedium.T_l);
  T = TILMedia.Internals.SLEMediumFunctions.temperature_h(
    h,
    iota,
    sleMedium.cp_s,
    sleMedium.cp_l,
    sleMedium.h_fusion,
    sleMedium.T_s,
    sleMedium.T_l);

  cp = sleMedium.cp_s + (sleMedium.cp_l - sleMedium.cp_s)*q;
  d = 1/(1/sleMedium.d_s + (1/sleMedium.d_l - 1/sleMedium.d_s)*q);
  lambda = sleMedium.lambda_s + (sleMedium.lambda_l - sleMedium.lambda_s)*q

  ;
end SLEMedium;

