model EPP_to_QS "Adapter to MSL Quasistationary interface"




  extends TransiEnt.Basics.Icons.Block;




  Modelica.Electrical.QuasiStatic.SinglePhase.Sources.VariableVoltageSource VariableVoltageSource ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Basic.Ground ground ;
  TransiEnt.Components.Sensors.ElectricFrequencyVoltage electricFrequencyAndVoltage_L2_1 ;
  Modelica.ComplexBlocks.ComplexMath.PolarToComplex polarToComplex
    ;
  Modelica.Blocks.Sources.Constant phi(k=0) ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Sensors.PowerSensor powerSensor ;
  TransiEnt.Components.Boundaries.Electrical.ApparentPower.ApparentPower terminal(useInputConnectorP=true, useCosPhi=false) ;
  Modelica.ComplexBlocks.ComplexMath.ComplexToReal complexToReal
    ;
  TransiEnt.Basics.Interfaces.Electrical.ApparentPowerPort epp ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Interfaces.PositivePin voltageP ;
equation








  connect(polarToComplex.y, VariableVoltageSource.V) ;
  connect(phi.y, polarToComplex.phi) ;
  connect(complexToReal.re, terminal.P_el_set) ;
  connect(complexToReal.im, terminal.Q_el_set) ;
  connect(epp, terminal.epp) ;
  connect(voltageP, powerSensor.voltageP)
    ;
  connect(VariableVoltageSource.pin_n, ground.pin)
    ;
  connect(electricFrequencyAndVoltage_L2_1.f, VariableVoltageSource.f)
    ;
  connect(electricFrequencyAndVoltage_L2_1.epp, terminal.epp) ;
  connect(electricFrequencyAndVoltage_L2_1.v, polarToComplex.len) ;
  connect(powerSensor.voltageN, ground.pin) ;
  connect(powerSensor.apparentPower, complexToReal.u) ;
  connect(VariableVoltageSource.pin_p, powerSensor.currentP) ;
  connect(powerSensor.currentN, voltageP) ;
  connect(voltageP, voltageP)

  ;
end EPP_to_QS;

