block FirstOrderWithGradientLim "First order transfer function block (= 1 pole, allows Tau = 0 and a gain)"
  extends Modelica.Blocks.Interfaces.SISO;
  parameter Real k(unit="1")=1 "Gain";
  parameter Modelica.Units.SI.Time Tau=0 "Time Constant, set Tau=0 for no signal smoothing";


  parameter Integer initOption = 1 "Initialisation option" ;
  parameter Real y_start=1 "Start value at output" ;
  parameter Boolean evaluate_y_start = false "true for Evaluate=true for y_start";
  parameter Boolean enable_gradientLimiter = true "enable gradient limitation defined by input connectors" ;




  Modelica.Blocks.Interfaces.RealInput maxGrad if enable_gradientLimiter  "limit for maximum gradient" ;
  Modelica.Blocks.Interfaces.RealInput minGrad if enable_gradientLimiter "limit for lowest gradient" ;




protected
  Modelica.Blocks.Sources.RealExpression dummyMaxGrad(y=Modelica.Constants.inf) if not enable_gradientLimiter ;
protected
  Modelica.Blocks.Interfaces.RealInput maxGrad_ "required for conditional maxGrad";
  Modelica.Blocks.Interfaces.RealInput minGrad_ "required for conditional minGrad";
protected
  Real y_aux(stateSelect=if Tau==0 then StateSelect.never else StateSelect.always);
  Modelica.Blocks.Sources.RealExpression dummyMinGrad(y=-Modelica.Constants.inf) if not enable_gradientLimiter ;
initial equation
  if Tau < Modelica.Constants.eps then

  elseif initOption == 1 then 
    y_aux = u;
  elseif initOption == 2 then 
    y_aux = y_start;
  elseif initOption == 3 and Tau>0 then 
    der(y_aux) = 0;
  elseif initOption == 4 then 
    y_aux = 0;
  else
    assert(false, "Unknown init option in component " + getInstanceName());
   end if;
equation
  if Tau < Modelica.Constants.eps then
    y=k*u;
    y_aux=0;
  else
    if enable_gradientLimiter then
      der(y_aux) = min(maxGrad_,max(minGrad_,(k*u - y_aux)/Tau));
    else
      der(y_aux) = (k*u - y_aux)/Tau;
    end if;
    y=y_aux;
  end if;


  connect(maxGrad, maxGrad_);
  connect(minGrad, minGrad_);
  connect(dummyMaxGrad.y, maxGrad_);
  connect(dummyMinGrad.y, minGrad_)
  ;
end FirstOrderWithGradientLim;

