block SmoothLimPID "P, PI, PD, and PID controller with smoothed limited output, anti-windup compensation and setpoint weighting"




  import InitPID =
         Modelica.Blocks.Types.Init;
  import Modelica.Blocks.Types.Init;
  import Modelica.Blocks.Types.SimpleController;
  extends Modelica.Blocks.Interfaces.SVcontrol;
  output Real controlError = u_s - u_m "Control error (set point - measurement)";




protected
  parameter Boolean with_I = controllerType==SimpleController.PI or
                             controllerType==SimpleController.PID ;
  parameter Boolean with_D = controllerType==SimpleController.PD or
                             controllerType==SimpleController.PID ;
public
  Modelica.Blocks.Sources.Constant Dzero(k=0) if not with_D ;
  Modelica.Blocks.Sources.Constant Izero(k=0) if not with_I ;
  constant Modelica.Units.SI.Time unitTime=1 ;




  parameter .Modelica.Blocks.Types.SimpleController controllerType=
         .Modelica.Blocks.Types.SimpleController.PID "Type of controller";
  parameter Real thres = 0.1 "Smooting region of the limiter";
  parameter Real k(min=0, unit="1") = 1 "Gain of controller";
  parameter Modelica.Units.SI.Time Ti(min=Modelica.Constants.small) = 0.5 "Time constant of Integrator block" ;
  parameter Modelica.Units.SI.Time Td(min=0) = 0.1 "Time constant of Derivative block" ;
  parameter Real yMax(start=1) "Upper limit of output";
  parameter Real yMin=-yMax "Lower limit of output";
  parameter Real wp(min=0) = 1 "Set-point weight for Proportional block (0..1)";
  parameter Real wd(min=0) = 0 "Set-point weight for Derivative block (0..1)"
       ;
  parameter Real Ni(min=100*Modelica.Constants.eps) = 0.9 "Ni*Ti is time constant of anti-windup compensation"
     ;
  parameter Real Nd(min=100*Modelica.Constants.eps) = 10 "The higher Nd, the more ideal the derivative block"
       ;
  parameter .Modelica.Blocks.Types.Init initType=.Modelica.Blocks.Types.Init.InitialState "Type of initialization (1: no init, 2: steady state, 3: initial state, 4: initial output)" ;
  parameter Real xi_start=0 "Initial or guess value value for integrator output (= integrator state)"
    ;
  parameter Real xd_start=0 "Initial or guess value for state of derivative block"
    ;
  parameter Real y_start=0 "Initial value of output"
    ;




  Modelica.Blocks.Math.Add addP(k1=wp, k2=-1) ;
  Modelica.Blocks.Math.Add addD(k1=wd, k2=-1) if with_D ;
  Modelica.Blocks.Math.Gain P(k=1) ;
  Modelica.Blocks.Continuous.Integrator I(
    k=unitTime/Ti,
    y_start=xi_start,
    initType=if initType == InitPID.SteadyState then Init.SteadyState else if initType == InitPID.InitialState or initType == InitPID.InitialState then Init.InitialState else Init.NoInit) if with_I ;
  Modelica.Blocks.Continuous.Derivative D(
    k=Td/unitTime,
    T=max([Td/Nd,1.e-14]),
    x_start=xd_start,
    initType=if initType ==InitPID.SteadyState  or initType ==InitPID.InitialOutput
         then Init.SteadyState else if initType ==InitPID.InitialState  then
        Init.InitialState else Init.NoInit) if with_D ;
  Modelica.Blocks.Math.Gain gainPID(k=k) ;
  Modelica.Blocks.Math.Add3 addPID ;
  Modelica.Blocks.Math.Add3 addI(k2=-1) if with_I ;
  Modelica.Blocks.Math.Add addSat(k1=+1, k2=-1) if with_I ;
  Modelica.Blocks.Math.Gain gainTrack(k=1/(k*Ni)) if with_I ;
  TransiEnt.Basics.Blocks.SplineLim limiter(
    uMax=yMax,
    uMin=yMin,
    thres=thres) ;




initial equation
  if initType==InitPID.InitialOutput then
     gainPID.y = y_start;
  end if;
equation
  assert(yMax >= yMin, "LimPID: Limits must be consistent. However, yMax (=" + String(yMax) +
                       ") < yMin (=" + String(yMin) + ")");
  if initType ==InitPID.InitialOutput  and (y_start < yMin or y_start > yMax) then
      Modelica.Utilities.Streams.error("LimPID: Start value y_start (=" + String(y_start) +
         ") is outside of the limits of yMin (=" + String(yMin) +") and yMax (=" + String(yMax) + ")");
  end if;




  connect(u_s, addP.u1) ;
  connect(u_s, addD.u1) ;
  connect(u_s, addI.u1) ;
  connect(addP.y, P.u) ;
  connect(addD.y, D.u)
    ;
  connect(addI.y, I.u) ;
  connect(P.y, addPID.u1) ;
  connect(D.y, addPID.u2)
    ;
  connect(I.y, addPID.u3) ;
  connect(addPID.y, gainPID.u)
    ;
  connect(gainPID.y, addSat.u2) ;
  connect(gainPID.y, limiter.u)
    ;
  connect(limiter.y, addSat.u1) ;
  connect(limiter.y, y)
    ;
  connect(addSat.y, gainTrack.u) ;
  connect(gainTrack.y, addI.u3) ;
  connect(u_m, addP.u2) ;
  connect(u_m, addD.u2) ;
  connect(u_m, addI.u2) ;
  connect(Dzero.y, addPID.u2) ;
  connect(Izero.y, addPID.u3) 
  ;
end SmoothLimPID;

within TransiEnt.Basics.Blocks;
model SplineLim "Spline smoothed limiter"




extends Modelica.Blocks.Interfaces.SISO;




  final parameter Real lim=(uMax-uMin)*thres;
  final parameter Real xa=uMin - lim*sqrt(2);
  final parameter Real xb=uMin + lim;
  final parameter Real xc=uMax - lim;
  final parameter Real xd=uMax + lim*sqrt(2);
  final parameter Real ya=uMin;
  final parameter Real yb=uMin + lim;
  final parameter Real yc=uMax - lim;
  final parameter Real yd=uMax;
protected
  final parameter Real dya=0;
  final parameter Real dyb=1;
  parameter Real[4] coef1(each fixed=false);
  parameter Real[4] coef2(each fixed=false);




public
  parameter Real uMax = 1 "Maximum";
  parameter Real uMin = -uMax "Minimum";
  parameter Real thres(max=0.5, min=Modelica.Constants.eps) = 0.1 "Share of (uMax-uMin) from which on spline interpolation shall be used";















initial equation
  assert(uMax >= uMin, "Limiter: Limits must be consistent. However, uMax (=" + String(uMax) +
                       ") < uMin (=" + String(uMin) + ")");
  assert(thres<=0.5, "For a continuous course the transition zones may not overlap!");
  ya = coef1[1] + xa*(coef1[2] + xa*(coef1[3] + xa*coef1[4]));
  yb = coef1[1] + xb*(coef1[2] + xb*(coef1[3] + xb*coef1[4]));
  dya = coef1[2] + xa*(2*coef1[3] + xa*3*coef1[4]);
  dyb = coef1[2] + xb*(2*coef1[3] + xb*3*coef1[4]);
  yc = coef2[1] + xc*(coef2[2] + xc*(coef2[3] + xc*coef2[4]));
  yd = coef2[1] + xd*(coef2[2] + xd*(coef2[3] + xd*coef2[4]));
  dyb = coef2[2] + xc*(2*coef2[3] + xc*3*coef2[4]);
  dya = coef2[2] + xd*(2*coef2[3] + xd*3*coef2[4]);
equation
  y = smooth(1, noEvent(
    if u <= xa then uMin
    elseif u >= xd then uMax
    elseif u > xa and u < xb then coef1[1] + u*coef1[2] + u^2*coef1[3] + u^3*coef1[4]
    elseif u > xc and u < xd then coef2[1] + u*coef2[2] + u^2*coef2[3] + u^3*coef2[4]
    else u));




  ;
end SplineLim;

