within TransiEnt.Basics.Functions;
function efficiency_linear "Approximizes efficiency between two defined points linearly"




  extends efficiency_base;




protected
parameter Real m=(Efficiency_Mat[1,2]-Efficiency_Mat[2,2]) /(Efficiency_Mat[1,1] - Efficiency_Mat[2,2]) "slope between two points";
parameter Real b= Efficiency_Mat[1,2] - Efficiency_Mat[1,1]*m "konstant Coefficient";
parameter Real Efficiency_min=Efficiency_Mat[1,2];
parameter Real Efficiency_max= Efficiency_Mat[2,2];




public
input Real Efficiency_Mat[:,2];




algorithm
eta:=m*x + b;
assert(Efficiency_Mat[1,2]<=1.12,  "Efficiency_Mat[1,2] invalid (>1.12)");
assert(Efficiency_Mat[1,2]>0.01, "Efficiency_Mat[1,2] invalid (<0.01)");
assert(Efficiency_Mat[2,2]<=1.12,  "Efficiency_Mat[2,2] invalid (>1.12)");
assert(Efficiency_Mat[2,2]>0.01, "Efficiency_Mat[2,2] invalid (<0.01)")
                                                                                              ;
end efficiency_linear;

within TransiEnt.Basics.Functions;
function efficiency_quadratic "Approximizes efficiency between three defined points quadratically"




  extends efficiency_base;




input Real Efficiency_Mat[:,2];




protected
  Real P_n2[3]={Efficiency_Mat[1, 1]^2,Efficiency_Mat[2, 1]^2,Efficiency_Mat[3, 1]^2};
  Real c[3]=Modelica.Math.Matrices.solve([ones(3),Efficiency_Mat[:, 1],P_n2], Efficiency_Mat[:, 2]) "Coefficients of quadratic power curve";




algorithm
  eta := c[1] + x*c[2] + x^2*c[3]
    ;
end efficiency_quadratic;

within TransiEnt.Basics.Functions;
function findAll "Finds all occurences of e in a given vector v and returns the positions"




  extends TransiEnt.Basics.Icons.Function;




  input Real e "Search for e";
  input Real v[:] "Real vector";
  input Real eps(min=0) = 0
    "Element e is equal to a element v[i] of vector v if abs(e-v[i]) <= eps";
  output Integer result[:]
    "all occurrences of e; result=0, if not found";




protected
  Integer i;
  Integer j;
  Integer result_internal[size(v,1)];




algorithm
  i := 1;
  j := 1;
  for i in 1:size(v, 1) loop
    if abs(v[i] - e) <= eps then
      result_internal[j] := i;
      j := j + 1;
    end if;
  end for;
  if j==1 then
    result:={0};
  else
    result:=result_internal[1:j - 1];
  end if
  ;
end findAll;

within TransiEnt.Basics.Functions;
function findSetDifference "Creates a vector which only contains the elements of vector which do not exist in subset"




  extends TransiEnt.Basics.Icons.Function;




  input Integer vector[:];
  input Integer subset[:] "Subset of vector";
  output Integer disjunction[size(vector,1)-size(subset,1)] "Disjunctive vector";




protected
  Integer positionOfDisjunctiveElements[size(vector, 1)] "Vector which contains zeros of disjunctive elements";
  Integer idx;




algorithm
  idx := 1;
  positionOfDisjunctiveElements := Modelica.Math.Vectors.find(vector, subset);
  for i in 1:size(vector, 1) loop
    if positionOfDisjunctiveElements[i] == 0 then
      disjunction[idx] := vector[i];
      idx := idx + 1;
    end if;
  end for
  ;
end findSetDifference;

within TransiEnt.Basics.Functions;
function find_max "Finds the minimum (maximum) value of a vector"




  extends Icons.Function;




input Real vector[:];
input Real stateVector[:]=ones(size(vector,1));
input Integer cond=1 "Only use items where statevector[i]=cond";
output Integer index;




protected
  Real value "Min/Max value of vector";




algorithm
  value:=vector[1];
  index:=1;
  for i in 1:size(vector,1) loop
    if vector[i]>value and stateVector[i]==cond then
      value:=vector[i];
      index:=i;
    end if;
  end for
  ;
end find_max;

within TransiEnt.Basics.Functions;
function find_min "Finds the minimum (maximum) value of a vector"




  extends Icons.Function;




input Real vector[:];
input Real stateVector[:]=ones(size(vector,1));
input Integer cond=1 "Only use items where statevector[i]=cond";
output Integer index;




protected
  Real value "Min/Max value of vector";




algorithm
  value:=vector[1];
  index:=1;
  for i in 1:size(vector,1) loop
    if vector[i]<value and stateVector[i]==cond then
      value:=vector[i];
      index:=i;
    end if;
  end for
  ;
end find_min;

