within TransiEnt.Basics.Functions;
function getNumberOfOccurences "Returns number of occurences of e in a given vector v"




  extends TransiEnt.Basics.Icons.Function;




  input Real e "Search for e";
  input Real v[:] "Real vector";
  input Real eps(min=0) = 0
    "Element e is equal to a element v[i] of vector v if abs(e-v[i]) <= eps";
  output Integer result
    "number of occurrences of e; result=0, if not found";




protected
  Integer i;




algorithm
  result := 0;
  i := 1;
  for i in 1:size(v, 1) loop
    if abs(v[i] - e) <= eps then
      result := result + 1;
    end if;
  end for
  ;
end getNumberOfOccurences;

within TransiEnt.Basics.Functions;
function getPrimaryEnergyCarrierFromHeat "Maps the enum 'primaryEnergyCarrierHeat' to 'primaryEnergyCarrier'"




  extends Icons.Function;
  import HeatType = TransiEnt.Basics.Types.TypeOfPrimaryEnergyCarrierHeat;
  import GeneralType = TransiEnt.Basics.Types.TypeOfPrimaryEnergyCarrier;




  input HeatType heatType;
  output GeneralType generalType;




algorithm
  if heatType == HeatType.NaturalGas then
    generalType :=GeneralType.NaturalGas;
  elseif heatType ==HeatType.DistrictHeating then
    generalType :=GeneralType.DistrictHeating;
  elseif heatType ==HeatType.Oil then
    generalType :=GeneralType.Oil;
  elseif heatType ==HeatType.Electricity then
    generalType :=GeneralType.Electricity;
  elseif heatType ==HeatType.Solar then
    generalType :=GeneralType.Solar;
  elseif heatType ==HeatType.Biomass then
    generalType :=GeneralType.Biomass;
  elseif heatType ==HeatType.Garbage then
    generalType :=GeneralType.Garbage;
  else
    generalType :=GeneralType.Others;
  end if
  ;
end getPrimaryEnergyCarrierFromHeat;

within TransiEnt.Basics.Functions;
function hist "Smooth Cubic function to that can be used to implement two point control without state events"




 extends Icons.Function;




 input Real x;
 input Real p;
 input Real e = 1;
 output Real y;




algorithm
  y:=-(x+0.5)*(x-0.5)*x*1/(0.0474)*e+p
  ;
end hist;

within TransiEnt.Basics.Functions;
function inverseXRegularized "Function that approximates 1/x by a twice continuously differentiable function"





  extends Icons.Function;




  input Real x "Abscissa value";
  input Real delta(min=0) "Abscissa value below which approximation occurs";
  output Real y "Function value";




protected
  Real delta2 "Delta^2";
  Real x2_d2 "=x^2/delta^2";




algorithm
  if (abs(x) > delta) then
    y := 1/x;
  else
    delta2 :=delta*delta;
    x2_d2  := x*x/delta2;
    y      := x/delta2 + x*abs(x/delta2/delta*(2 - x2_d2*(3 - x2_d2)));
  end if
  ;
end inverseXRegularized;

within TransiEnt.Basics.Functions;
function MeanValue "Function calculates the mean value of an vector"




  extends Icons.Function;




  input Real x[:] "Vector of values";
  output Real result "Mean Value";




algorithm
  result:=0 "initialisation of variable";
  for i in 1:size(x, 1) loop
      result:=result + x[i];
  end for "Sum up all elements";
  result:=result / size(x, 1) "Divide through the number of elements"
  ;
end MeanValue;

