within TransiEnt.Basics.Functions;
function sat "Smooth saturation of input x between xmin and xmax without state events"




  extends Icons.Function;




  input Real x;
  input Real xmin;
  input Real xmax;
  output Real y;




algorithm
  y := Modelica.Math.tanh(2*(x-xmin)/(xmax-xmin)-1)*(xmax-xmin)/2 + (xmax+xmin)/2
  ;
end sat;

within TransiEnt.Basics.Functions;
function standardDeviation "function calculates the standard deviation"




  extends Icons.Function;
  import TransiEnt;




  input Real x[:] "Input Vector";
  output Real result "Result value";




protected
  Real mean;




algorithm
  result:=0 "variable initilaisation";
  mean:=TransiEnt.Basics.Functions.MeanValue(x) "gets the mean value of x";
  for i in 1:size(x, 1) loop
      result:=result + (x[i] - mean) ^ 2;
  end for "sums up the squared difference between value and mean value";
  result:=result / size(x, 1);
  result:=sqrt(result)
  ;
end standardDeviation;

within TransiEnt.Basics.Functions.GasProperties;
function comps2Elements_idealGas "Universal function to calculate the molar flow rates of a medium's elements out the components"




  import TransiEnt;
  extends TransiEnt.Basics.Icons.Function;
  import Modelica.Utilities.Strings;




  input TILMedia.GasTypes.BaseGas gasType ;
  input Modelica.Units.SI.MassFraction[:] xi_in;
  input Modelica.Units.SI.MassFlowRate m_flow;




protected
  parameter Integer nc = gasType.nc_propertyCalculation "Number of components in fuel gas";
  parameter String[nc] gasCompNames=TransiEnt.Basics.Functions.GasProperties.shortenCompName(gasType.gasNames) "Component names in fuel gas";
  parameter TransiEnt.Basics.Records.GasProperties.StoichiometricCoefficientsCombustion compStoichiometry;
  constant Modelica.Units.SI.MolarMass[nc] M_iC=TransiEnt.Basics.Functions.GasProperties.getMolarMasses_idealGas(gasType, nc) "Molar masses of the gas components";




  Modelica.Units.SI.MolarFlowRate[nc] n_flow_components "Molar flowrate of components";
  Modelica.Units.SI.MassFraction[nc] xi;
  Integer foundComp "Component find indexer";
public
  output Modelica.Units.SI.MolarFlowRate[5] n_flow_elements "Molar flowrate of elements";
algorithm





  if nc > 1 then
    for i in 1:size(xi_in,1) loop
      xi[i] := xi_in[i];
    end for;
      xi[end] := 1 - sum(xi_in);
  else
    xi[1] := 1;
  end if;

  for i in 1:nc loop
    n_flow_components[i] := xi[i] * m_flow / M_iC[i];
  end for;

  for i in 1:size(gasCompNames,1) loop
    foundComp :=0;
    for j in 1:size(compStoichiometry.names, 1) loop
      if Strings.isEqual(compStoichiometry.names[j],gasCompNames[i], caseSensitive = false) then
        foundComp :=foundComp + 1;
        for k in 1:size(compStoichiometry.stoich,2) loop
          n_flow_elements[k] := n_flow_elements[k] + n_flow_components[i] * compStoichiometry.stoich[j,k];
        end for;
      end if;
      assert(j < size(compStoichiometry.names, 1) or foundComp == 1, "The gas component " + gasCompNames[i] + " is not listed in the stoichiometric record. Complete record or select another gasType.", level = AssertionLevel.warning);
    end for;
  end for
  ;
end comps2Elements_idealGas;

