model Demand_3Tables "Three seperate tables for load profile data: electricity demand, heat demand for heating, heat demand for hot water"




  extends TransiEnt.Basics.Tables.Combined.CombinedTables.Base.Demand_combined;




  outer TransiEnt.SimCenter simCenter;




  parameter Real heatDemand=1 "scaling factor for space heating demand of the consumer" ;
  parameter Real waterDemand=1 "scaling factor for warm water demand of the consumer" ;
  parameter Real electricityDemand=1 "scaling factor for electricity demand of the consumer" ;
  parameter DataPrivacy datasource_el=DataPrivacy.isPublic "Source of electricity table data"   ;
  parameter DataPrivacy datasource_heating=DataPrivacy.isPublic "Source of heating table data"   ;
  parameter DataPrivacy datasource_dhw=DataPrivacy.isPublic "Source of domestic hot water table data"   ;
  final parameter String environment_variable_name_el=if datasource_el ==DataPrivacy.isPublic then Types.PUBLIC_DATA else Types.PRIVATE_DATA  ;
  final parameter String environment_variable_name_heating=if datasource_dhw ==DataPrivacy.isPublic then Types.PUBLIC_DATA else Types.PRIVATE_DATA  ;
  final parameter String environment_variable_name_dhw=if datasource_heating ==DataPrivacy.isPublic then Types.PUBLIC_DATA else Types.PRIVATE_DATA  ;
  parameter String relativepath_el="electricity/Household/ElectricityDemand_20Households_measured_3-4MWh_3600s.csv"
                                    ;
  parameter String relativepath_heating="heat/Household/Heating_20Households_simulated_6MWh_3600s.csv" ;
  parameter String relativepath_dhw="heat/Household/HotWater_VDI4655_60s.txt" ;
  parameter Boolean use_absolute_path_el = false "Should only be used for testing purposes" ;
  parameter Boolean use_absolute_path_heating = false "Should only be used for testing purposes" ;
  parameter Boolean use_absolute_path_dhw = false "Should only be used for testing purposes" ;
  parameter String absolute_path_el = ""  ;
  parameter String absolute_path_heating = ""  ;
  parameter String absolute_path_dhw = ""  ;
  parameter String tableName_el="default" ;
  parameter String tableName_heating="default" ;
  parameter String tableName_dhw="default" ;
  parameter Integer consumer_count=1 "Starting number of the table columns";
  final parameter Integer columns_el[:]={consumer_count+1} "Columns of electricity table to be interpolated";
  final parameter Integer columns_heating[:]={consumer_count+1} "Columns of heating table to be interpolated";
  final parameter Integer columns_dhw[:]={consumer_count+1} "Columns of domestic hot water table to be interpolated";
  parameter Modelica.Blocks.Types.Smoothness smoothness=simCenter.tableInterpolationSmoothness "Smoothness of table interpolation" ;
  parameter Modelica.Blocks.Types.Extrapolation extrapolation=Modelica.Blocks.Types.Extrapolation.LastTwoPoints "Extrapolation of data outside the definition range" ;
  final parameter String complete_relative_path_el = Functions.fullPathName(Modelica.Utilities.System.getEnvironmentVariable(environment_variable_name_el) + relativepath_el);
  final parameter String complete_relative_path_heating = Functions.fullPathName(Modelica.Utilities.System.getEnvironmentVariable(environment_variable_name_heating) + relativepath_heating);
  final parameter String complete_relative_path_dhw = Functions.fullPathName(Modelica.Utilities.System.getEnvironmentVariable(environment_variable_name_dhw) + relativepath_dhw);
  final parameter String genericFileName_el = if use_absolute_path_el then absolute_path_el else complete_relative_path_el;
  final parameter String genericFileName_heating = if use_absolute_path_heating then absolute_path_heating else complete_relative_path_heating;
  final parameter String genericFileName_dhw = if use_absolute_path_dhw then absolute_path_dhw else complete_relative_path_dhw;




  Modelica.Blocks.Sources.CombiTimeTable combiTimeTable_el(
    tableOnFile=true,
    smoothness=smoothness,
    offset={0},
    startTime=0,
    tableName=tableName_el,
    extrapolation=Modelica.Blocks.Types.Extrapolation.HoldLastPoint,
    fileName=genericFileName_el,
    columns=columns_el) ;
  Modelica.Blocks.Sources.CombiTimeTable combiTimeTable_heating(
    tableOnFile=true,
    smoothness=smoothness,
    offset={0},
    startTime=0,
    tableName=tableName_heating,
    extrapolation=Modelica.Blocks.Types.Extrapolation.HoldLastPoint,
    fileName=genericFileName_heating,
    columns=columns_heating) ;
  Modelica.Blocks.Sources.CombiTimeTable combiTimeTable_dhw(
    tableOnFile=true,
    smoothness=smoothness,
    offset={0},
    startTime=0,
    tableName=tableName_dhw,
    extrapolation=Modelica.Blocks.Types.Extrapolation.HoldLastPoint,
    fileName=genericFileName_dhw,
    columns=columns_dhw) ;
  Modelica.Blocks.Math.Gain gain(k=waterDemand) ;
  Modelica.Blocks.Math.Gain gain1(k=heatDemand) ;
  Modelica.Blocks.Math.Gain gain2(k=electricityDemand) ;
equation




  connect(combiTimeTable_el.y[1], gain2.u) ;
  connect(combiTimeTable_heating.y[1], gain1.u) ;
  connect(combiTimeTable_dhw.y[1], gain.u) ;
  connect(gain.y, demand.hotWaterPowerDemand) ;
  connect(gain1.y, demand.heatingPowerDemand) ;
  connect(gain2.y, demand.electricPowerDemand) 
  ;
end Demand_3Tables;

within TransiEnt.Basics.Tables.Combined.CombinedTables;
model Demand_Table_combined "Table with combined load profile data for consumer: y[1]=electricity demand, y[2]=heat demand for heating, y[3] = heat demand for hot water"




  extends TransiEnt.Basics.Tables.Combined.CombinedTables.Base.Demand_combined;




  outer TransiEnt.SimCenter simCenter;




  parameter Integer consumer_count=1 "Starting number of the table column group";
  parameter Real heatDemand=1 "scaling factor for space heating demand of the consumer";
  parameter Real waterDemand=1 "scaling factor for warm water demand of the consumer";
