model BoundaryIdealGas_pTxi "Gas boundary for ideal gases with p, T, xi as inputs"




  extends TransiEnt.Basics.Icons.GasSource;
  outer TransiEnt.SimCenter simCenter;




  parameter TILMedia.GasTypes.BaseGas gasModel "Medium in the component" ;
  parameter Boolean calculateMass=false "True if mass in boundary shall be calculated" ;
  parameter Boolean calculateH_GCV=false "True if energy related to GCV shall be calculated" ;
  parameter Boolean calculateH_NCV=false "True if energy related to NCV shall be calculated" ;
  parameter Boolean variable_p=false "True, if mass flow defined by variable input" ;
  parameter Boolean variable_T=false "True, if temperature defined by variable input" ;
  parameter Boolean variable_xi=false "True, if composition defined by variable input"    ;
  parameter Boolean verbose = false "Show initial gas compostion in log" ;
  parameter SI.AbsolutePressure p_const=simCenter.p_amb_const+simCenter.p_eff_2 "Constant absolute pressure" ;
  parameter SI.Temperature T_const=simCenter.T_ground "Constant temperature of source" ;
  parameter SI.MassFraction xi_const[gasModel.nc - 1]=gasModel.xi_default "Constant composition" ;
  parameter SI.Pressure Delta_p= 0 "Flange pressure drop at nominal mass flow (zero refers to ideal boundary)"
                                                                                                    ;
  parameter SI.MassFlowRate m_flow_nom=0 "Nominal flange mass flow (zero refers to ideal boundary)" ;




  Modelica.Units.SI.Mass m(start=0, stateSelect=StateSelect.never) ;
  SI.AbsolutePressure p_in;
  SI.Temperature T_in;
  SI.MassFraction xi_in[gasModel.nc - 1];




public
  TransiEnt.Basics.Interfaces.Gas.IdealGasEnthPortIn gasPort(Medium=gasModel) ;
  TransiEnt.Basics.Interfaces.General.PressureIn p=p_in if (variable_p) "Variable absolute pressure"
    ;
  TransiEnt.Basics.Interfaces.General.TemperatureIn T=T_in if (variable_T) "Variable temperature"
    ;
  TransiEnt.Basics.Interfaces.General.MassFractionIn xi[gasModel.nc - 1]=xi_in
    if (variable_xi) "Variable mass composition"
    ;




  Modelica.Blocks.Sources.RealExpression xi_actual[gasModel.nc - 1](y=noEvent(actualStream(gasPort.xi_outflow))) if calculateH_GCV     ;
  Modelica.Blocks.Math.Product product if calculateH_GCV     ;
  Modelica.Blocks.Continuous.Integrator integrator if calculateH_GCV     ;
  Modelica.Blocks.Interfaces.RealOutput H_GCV ;
  Modelica.Blocks.Sources.Constant zero(k=0, y(unit="J")) if not calculateH_GCV     ;
  Modelica.Blocks.Sources.RealExpression MassFlow(y=gasPort.m_flow) if calculateH_GCV           ;
  Modelica.Blocks.Sources.RealExpression xi_actual2[gasModel.nc - 1](y=noEvent(actualStream(gasPort.xi_outflow))) if calculateH_NCV     ;
  Modelica.Blocks.Math.Product product1 if calculateH_NCV    ;
  Modelica.Blocks.Continuous.Integrator integrator1 if calculateH_NCV    ;
  Modelica.Blocks.Interfaces.RealOutput H_NCV ;
  Modelica.Blocks.Sources.Constant zero1(k=0, y(unit="J")) if not calculateH_NCV    ;
  Modelica.Blocks.Sources.RealExpression Massflow2(y=gasPort.m_flow) if calculateH_NCV          ;
protected
  TILMedia.Gas_pT gas_pT(
    p=p_in,
    xi=xi_in,
    gasType=gasModel,
    T=T_in)           ;
  Basics.Media.IdealGasGCV_xi_Block idealGasGCV_xi(idealGasType=gasModel) if calculateH_GCV ;
  Basics.Media.IdealGasNCV_xi_Block idealGasNCV_xi(idealGasType=gasModel) if calculateH_NCV ;
initial equation
  if verbose and variable_xi then
    TransiEnt.Basics.Functions.GasProperties.verboseXi(gasModel.gasNames, xi_in);
  end if;
equation




  if (not variable_p) then
    p_in=p_const;
  end if;
  if (not variable_T) then
    T_in=T_const;
  end if;
  if (not variable_xi) then
    xi_in=xi_const;
  end if;

  if calculateMass then
    der(m) = gasPort.m_flow;
  else
    m=0;
  end if;

  gasPort.h_outflow=gas_pT.h;
  if Delta_p>0 then
    gasPort.p=p_in + Delta_p/m_flow_nom*gasPort.m_flow;
  else
    gasPort.p=p_in;
  end if;
  gasPort.xi_outflow=xi_in;
  connect(idealGasGCV_xi.xi_in,xi_actual. y) ;
  connect(product.u1,idealGasGCV_xi. GCV) ;
  connect(product.y,integrator. u) ;
  connect(zero.y, H_GCV) ;
  connect(product.u2,MassFlow. y) ;
  connect(idealGasNCV_xi.xi_in,xi_actual2. y) ;
  connect(idealGasNCV_xi.NCV,product1. u1) ;
  connect(product1.y,integrator1. u) ;
  connect(integrator1.y, H_NCV) ;
  connect(zero1.y, H_NCV) ;
    connect(product1.u2,Massflow2. y) ;
  connect(integrator.y, H_GCV) 
  ;
end BoundaryIdealGas_pTxi;

