within TransiEnt.Components.Boundaries.Heat;
model Heatflow_L1 "Ideal Heat flow boundary with constant or prescribed power and constant pressure loss"




  import TransiEnt;
  extends TransiEnt.Components.Boundaries.Heat.Base.PartialHeatBoundary;




  parameter SI.Power Q_flow_const=100e3 "Constant heating Power"                                       ;
  parameter Boolean use_Q_flow_in=true "Use external Value for Q_flow" ;
  parameter Boolean use_T_out_limit=false "Use limitation of output temperature" ;
  parameter SI.Pressure p_drop=simCenter.p_nom[2]-simCenter.p_nom[1] "Nominal pressure drop";
  parameter Boolean change_sign=false "Change sign on input values, false: negative setpoint will produce heat";
  parameter SI.Temperature T_out_limit_const=273.15+100 "maximum output temperature - if change_sign==true: minimum output temperature" ;
  parameter Boolean useVariableToutlimit=false "Define limit of output muss flow by input";




  TransiEnt.Basics.Interfaces.Thermal.HeatFlowRateIn Q_flow_prescribed if use_Q_flow_in "RealInput (for specification of boundary power)"
    ;
  TransiEnt.Basics.Interfaces.General.TemperatureIn T_out_limit_prescribed if useVariableToutlimit ;
protected
  TransiEnt.Basics.Interfaces.Thermal.HeatFlowRateIn Q_flow_internal "Needed for conditional connector";
  TransiEnt.Basics.Interfaces.General.TemperatureIn T_out_limit_internal "Needed for conditional connector";




public
  SI.SpecificEnthalpy h;
  SI.SpecificEnthalpy h_out_limit;
equation




  if not use_Q_flow_in then
    Q_flow_internal = Q_flow_const;
  end if;
  if not useVariableToutlimit then
    T_out_limit_internal=T_out_limit_const;
  end if;

  - fluidPortOut.p + fluidPortIn.p = p_drop;

  fluidPortIn.m_flow + fluidPortOut.m_flow = 0;


  if use_T_out_limit then
    fluidPortOut.h_outflow =if change_sign then max(h_out_limit,inStream(fluidPortIn.h_outflow) + h) else min(h_out_limit,inStream(fluidPortIn.h_outflow) - h);
    fluidPortIn.h_outflow =if change_sign then max(h_out_limit,inStream(fluidPortOut.h_outflow) + h) else min(h_out_limit,inStream(fluidPortOut.h_outflow) - h);
  else
    fluidPortOut.h_outflow =if change_sign then inStream(fluidPortIn.h_outflow) + h else inStream(fluidPortIn.h_outflow) - h;
    fluidPortIn.h_outflow =if change_sign then inStream(fluidPortOut.h_outflow) + h else inStream(fluidPortOut.h_outflow) - h;
  end if;
   fluidPortIn.xi_outflow  = inStream(fluidPortOut.xi_outflow);
   fluidPortOut.xi_outflow = inStream(fluidPortIn.xi_outflow);
  h = Q_flow_internal/max(abs(fluidPortOut.m_flow), simCenter.m_flow_small);

 if use_T_out_limit then
     h_out_limit = TILMedia.Internals.VLEFluidConfigurations.FullyMixtureCompatible.VLEFluidFunctions.specificEnthalpy_pTxi(
       vleFluidType=Medium,
       p=fluidPortOut.p,
       T=T_out_limit_internal,
       xi=fluidPortOut.xi_outflow);
  else
    h_out_limit=-999;
  end if;




  connect(Q_flow_prescribed, Q_flow_internal);
  connect(T_out_limit_prescribed,T_out_limit_internal)
  ;
end Heatflow_L1;

within TransiEnt.Components.Boundaries.Heat;
model Heatflow_L1_idContrMFlow_temp "Heat flow boundary with pump with ideal mass flow control to get a given outlet temperature"




  extends Base.Heatflow_L1_idContr_temp_base;




  TransiEnt.Basics.Interfaces.Thermal.HeatFlowRateIn Q_flow_set "Setpoint value of the heat flow, should be negative" ;




equation
  Q_flow=fluidPortOut.m_flow*(fluidPortOut.h_outflow-inStream(fluidPortIn.h_outflow));
  fluidPortOut.m_flow=min(0,Q_flow_set/(fluidPortOut.h_outflow-inStream(fluidPortIn.h_outflow)))
   ;
end Heatflow_L1_idContrMFlow_temp;

within TransiEnt.Components.Boundaries.Heat;
model Heatflow_L1_idContrQFlow_temp "Heat flow boundary with ideal heat flow rate control to get a given outlet temperature"




  extends Base.Heatflow_L1_idContr_temp_base;




equation
  fluidPortIn.p=fluidPortOut.p;
  Q_flow=fluidPortOut.m_flow*(fluidPortOut.h_outflow-inStream(fluidPortIn.h_outflow))
   ;
end Heatflow_L1_idContrQFlow_temp;

within TransiEnt.Components.Boundaries.Heat;
model Heatflow_L2 "Heat flow boundary with prescribed power and given volume (L2)"




  import TransiEnt;
  extends TransiEnt.Components.Boundaries.Heat.Base.PartialHeatBoundary;




  parameter SI.Power Q_flow_n=100e3 "|Heat demand|Nominal heating power";
  parameter Boolean use_Q_flow_in=true "|Heat demand|Use external value for Q_flow" ;
  parameter Boolean change_sign=false "Change sign on input value (false: setpoint < 0 means producing heat)";
  parameter SI.Power Q_flow_const=100e3 "|Heat demand|Constant heating power" ;
  parameter SI.MassFlowRate m_flow_nom=simCenter.m_flow_nom "|Heat exchanger|Nominal mass flow rate";
  parameter SI.Pressure p_nom=simCenter.p_nom[1] "Nominal pressure" ;
  parameter ClaRa.Basics.Units.EnthalpyMassSpecific h_nom=1e5 "|Heat exchanger|Nominal specific enthalpy";
  parameter SI.HeatCapacity C=1e9 "|Heat exchanger|Heat capacity (geometry is calculated by this value)" ;
  parameter SI.Pressure p_start=simCenter.p_nom[1] "Start value of system pressure" ;
  parameter SI.Temperature T_start=323.15 "|Heat exchanger|Initial temperature" ;
  parameter Integer initOption=0 "|Heat exchanger|Type of initialisation" ;
  replaceable model PressureLoss = ClaRa.Basics.ControlVolumes.Fundamentals.PressureLoss.Generic_PL.LinearPressureLoss_L2
   constrainedby ClaRa.Basics.ControlVolumes.Fundamentals.PressureLoss.Generic_PL.PressureLoss_L2 "|Heat exchanger|Pressure loss model" ;
  parameter Real valveAuthority=0.6 "|Valve|Valve authority";
  parameter SI.Pressure Delta_p_nom=simCenter.p_nom[2]-simCenter.p_nom[1] "|Valve|Nominal pressure drop";




protected
  TransiEnt.Basics.Interfaces.Thermal.HeatFlowRateIn Q_flow_internal;
public
  TransiEnt.Basics.Interfaces.Thermal.HeatFlowRateIn Q_flow_prescribed if use_Q_flow_in "RealInput (for specification of boundary power)"
    ;




  ClaRa.Components.HeatExchangers.IdealShell_L2 heatExchanger(
    medium=Medium,
    width=(C/4186/1000)^(1/3),
    length=(C/4186/1000)^(1/3),
    height=(C/4186/1000)^(1/3),
    m_flow_nom=m_flow_nom,
    p_nom=p_nom,
    showData=false,
    h_nom=h_nom,
    h_start=(T_start - 273.15)*4186,
    initOption=initOption,
    p_start(displayUnit="Pa") = p_start,
    redeclare model PressureLoss = PressureLoss)       ;
  Modelica.Thermal.HeatTransfer.Sources.PrescribedHeatFlow heatDemand
    ;
  ClaRa.Components.VolumesValvesFittings.Valves.GenericValveVLE_L1 controlValve(
      openingInputIsActive=true,
    showData=false,
    redeclare model PressureLoss = ClaRa.Components.VolumesValvesFittings.Valves.Fundamentals.LinearNominalPoint (
        Delta_p_nom=Delta_p_nom*valveAuthority,
        m_flow_nom=m_flow_nom,
        CL_valve=[0,0.1; 1,1]),
    medium=Medium)                                         ;
  Modelica.Blocks.Math.Gain normalizer(k=1/Q_flow_n)
    ;
  Modelica.Blocks.Math.Gain signChanger(k=if change_sign then 1 else -1)
    ;
equation




  if not use_Q_flow_in then
    Q_flow_internal = Q_flow_const;
  end if;




  connect(Q_flow_internal, Q_flow_prescribed);
  connect(signChanger.u, Q_flow_internal);
  connect(heatDemand.Q_flow, signChanger.y);
  connect(normalizer.u, Q_flow_internal);
  connect(heatDemand.port, heatExchanger.heat) ;
  connect(normalizer.y, controlValve.opening_in) ;
  connect(controlValve.inlet, fluidPortIn) ;
  connect(controlValve.outlet, heatExchanger.inlet) ;
  connect(heatExchanger.outlet, fluidPortOut) 
  ;
end Heatflow_L2;

within TransiEnt.Components.Boundaries.Heat.Base;
partial model Heatflow_L1_idContr_temp_base "Base class for heat flow boundaries with ideal control to get a given outlet temperature"




  extends TransiEnt.Basics.Icons.Model;
  import      Modelica.Units.SI;




  parameter TILMedia.VLEFluidTypes.BaseVLEFluid medium=simCenter.fluid1 "Medium to be used" ;
  parameter Boolean use_varTemp=false "true if variable temperature input should be used" ;
  parameter SI.Temperature T_out_set_const=46 + 273.15 "Constant outlet set temperature" ;
  parameter TransiEnt.Basics.Types.TypeOfResource typeOfResource=TransiEnt.Basics.Types.TypeOfResource.Consumer "Select the kind of resource" ;




  outer TransiEnt.SimCenter simCenter;
  outer TransiEnt.ModelStatistics modelStatistics;




  TransiEnt.Basics.Interfaces.Thermal.FluidPortIn fluidPortIn(Medium=medium) ;
  TransiEnt.Basics.Interfaces.Thermal.FluidPortOut fluidPortOut(Medium=medium) ;
  TransiEnt.Basics.Interfaces.General.TemperatureIn T_out_set=T_out_set_in if use_varTemp "Setpoint value of the output temperature" ;




  TILMedia.Internals.VLEFluidConfigurations.FullyMixtureCompatible.VLEFluid_pT fluidOut(
    vleFluidType=medium,
    p=fluidPortOut.p,
    T=T_out_set_in) ;
  TransiEnt.Components.Statistics.Collectors.LocalCollectors.CollectHeatingPower collectHeatingPower(typeOfResource=typeOfResource)                                 ;




  SI.Temperature T_out_set_in;
  SI.HeatFlowRate Q_flow;




equation
  if not use_varTemp then
    T_out_set_in=T_out_set_const;
  end if;
  fluidPortIn.m_flow+fluidPortOut.m_flow=0;
  fluidPortIn.h_outflow=inStream(fluidPortOut.h_outflow);
  fluidPortOut.h_outflow=fluidOut.h;
  collectHeatingPower.heatFlowCollector.Q_flow=Q_flow;




  connect(modelStatistics.heatFlowCollector[TransiEnt.Basics.Types.TypeOfResource.Consumer],collectHeatingPower.heatFlowCollector)
   ;
end Heatflow_L1_idContr_temp_base;

