within TransiEnt.Components.Electrical.Grid.Components.Base;
partial model PartialSpecificElement1PinComplex "Partial modell for one pin Inductor, Capacitor and Resistor, based on ComplexPowerPort"












  parameter SI.Length l(min = 0) = 1 "length of element";





  TransiEnt.Basics.Interfaces.Electrical.ComplexPowerPort epp_p ;













protected
  SI.ComplexCurrent I;
  SI.ComplexPower S_lost;
  SI.ComplexVoltage U_drop;
  SI.ComplexImpedance Z;
  SI.ActivePower P(start=0);
  SI.ReactivePower Q(start=0);




equation
  S_lost.re = epp_p.P;
  S_lost.im = epp_p.Q;
  U_drop.re = epp_p.v*cos(epp_p.delta); 
  U_drop.im = epp_p.v*sin(epp_p.delta); 
    I = Modelica.ComplexMath.conj(S_lost / U_drop);
    U_drop = I * Z;
    epp_p.P=P;
    epp_p.Q=Q;




  ;
end PartialSpecificElement1PinComplex;

within TransiEnt.Components.Electrical.Grid.Components.Base;
partial model PartialSpecificElement2Pin "Partial modell for two pin Inductor, Capacitor and Resistor"












  parameter SI.Length l(min = 0) = 1 "length of element";




  TransiEnt.Basics.Interfaces.Electrical.ApparentPowerPort epp_p ;
  TransiEnt.Basics.Interfaces.Electrical.ApparentPowerPort epp_n ;












protected
  SI.ComplexPower S;
  SI.ComplexVoltage U;
  SI.ComplexCurrent I;
  SI.ComplexPower S_lost;
  SI.ComplexVoltage U_drop;
  SI.ComplexImpedance Z;
  SI.ActivePower P(stateSelect=StateSelect.prefer);




equation
  epp_p.f = epp_n.f;
  P = S.re;
  S.re = epp_p.P;
  S.im = epp_p.Q;
  U.re = epp_p.v;
  U.im = 0;
    I = Modelica.ComplexMath.conj(S / U);
    U_drop = I * Z;
    S_lost = U_drop * Modelica.ComplexMath.conj(I);
    epp_n.v =Modelica.ComplexMath.abs(U - U_drop);
    epp_n.P = -Modelica.ComplexMath.real(S - S_lost);
    epp_n.Q = -Modelica.ComplexMath.imag(S - S_lost);




  ;
end PartialSpecificElement2Pin;

within TransiEnt.Components.Electrical.Grid.Components.Base;
partial model PartialSpecificElement2PinComplex "Partial modell for two pin Inductor, Capacitor and Resistor, active losses"












  parameter SI.Length l(min = 0) = 1 "length of element";




  TransiEnt.Basics.Interfaces.Electrical.ComplexPowerPort epp_p ;
  TransiEnt.Basics.Interfaces.Electrical.ComplexPowerPort epp_n ;









public
     SI.ComplexPower S;
     SI.ComplexVoltage U;
     SI.ComplexCurrent I;
     SI.ComplexPower S_lost;
     SI.ComplexVoltage U_drop;
     SI.ActivePower P(start=0);
     SI.ReactivePower Q(start=0);
     SI.ComplexImpedance Z;
equation
   epp_p.f = epp_n.f;
   Connections.branch(epp_p.f,epp_n.f);
      P = S.re;
      Q = S.im;
      S.re = epp_p.P;
      S.im = epp_p.Q;
      U.re = epp_p.v*cos(epp_p.delta); 
      U.im = epp_p.v*sin(epp_p.delta); 
        I = Modelica.ComplexMath.conj(S / U);
        U_drop = I * Z;
        S_lost = U_drop * Modelica.ComplexMath.conj(I);
        epp_n.v =Modelica.ComplexMath.abs(U - U_drop);    
        epp_n.delta=Modelica.ComplexMath.arg(U - U_drop);
        epp_n.P = -Modelica.ComplexMath.real(S - S_lost);
        epp_n.Q = -Modelica.ComplexMath.imag(S - S_lost);




  ;
end PartialSpecificElement2PinComplex;

