model TwoAxisSynchronousMachineComplex "ComplexPowerPort: Stationary Two-Axis SM model with excitation voltage input"




  extends TransiEnt.Components.Electrical.Machines.Base.PartialQuasiStationaryGeneratorComplex;




  parameter SI.Reactance X_d=2 "Synchronous reactance d-component"               ;
  parameter SI.Reactance X_q=1.95 "Synchronous reactance q-component"               ;
  parameter SI.Resistance R_a=0.3 "Resistance for losses"              ;




  Modelica.Units.SI.ComplexPower S_c;
  Modelica.Units.SI.Voltage v_d(start=0) ;
  Modelica.Units.SI.Voltage v_q(start=v_n) ;
  Modelica.Units.SI.Current i_d(start=0) ;
  Modelica.Units.SI.Current i_q(start=0) ;
  Modelica.Units.SI.Voltage e(start=v_n) ;
  Modelica.Units.SI.Angle theta_absolut(start=0.17453292519943295) ;




equation




  if OwnFrequency==true then
  v_d*i_d+v_q*i_q + D_cage * der(theta)= (mpp.tau * omega);
  else
    v_d*i_d+v_q*i_q = (mpp.tau * omega);
  end if;

  S_c.re=epp.P;
  S_c.im=epp.Q;
   e=E_input;

  v_d=X_q*i_q-R_a*i_d;
  v_q=e-X_d*i_d-R_a*i_q;
   v_d^2+v_q^2=v_grid^2;
   cos(theta_absolut)=if v_q < v_grid then v_q/v_grid else 1;
   theta=theta_absolut+delta_lsm;

  S_c.re=-((v_d+R_a*i_d)*i_d+(v_q+R_a*i_q)*i_q);
  S_c.im=-(v_q*i_d-v_d*i_q)
  ;
end TwoAxisSynchronousMachineComplex;

