model TwoAxisSynchronousMachineComplexSubtransient "ComplexPowerPort: Subtransient Two-Axis SM model with excitation voltage input"




  extends TransiEnt.Components.Electrical.Machines.Base.PartialQuasiStationaryGeneratorComplex;




  parameter SI.Reactance X_d=2 "Synchronous reactance d-component"               ;
  parameter SI.Reactance X_q=1.95 "Synchronous reactance q-component"               ;
  parameter SI.Resistance R_a=0.3 "Resistance for losses"               ;
  parameter SI.Reactance X_d_trans=0.25 "Transient reactance d-component"               ;
  parameter SI.Reactance X_q_trans=0.3 "Transient reactance q-component"               ;
  parameter Modelica.Units.SI.Time T_d0_trans=0.2 "Time constant d-component" ;
  parameter Modelica.Units.SI.Time T_q0_trans=0.2 "Time constant q=component" ;
  parameter SI.Reactance X_d_subtrans=0.5 "Subtransient reactance d-component"               ;
  parameter SI.Reactance X_q_subtrans=0.25 "Subtransient reactance q-component"               ;
  parameter Modelica.Units.SI.Time T_d0_subtrans=0.11 "Time constant d-component, subtransient part" ;
  parameter Modelica.Units.SI.Time T_q0_subtrans=0.08 "Time constant q-component, subtransient part" ;




  Modelica.Units.SI.ComplexPower S_c;
  Modelica.Units.SI.Voltage v_d(start=0) ;
  Modelica.Units.SI.Voltage v_q(start=v_n) ;
  Modelica.Units.SI.Current i_d(start=0) ;
  Modelica.Units.SI.Current i_q(start=0) ;
  Modelica.Units.SI.Voltage e_FD;
  Modelica.Units.SI.Voltage e_d_trans(start=0) ;
  Modelica.Units.SI.Voltage e_q_trans(start=v_n) ;
  Modelica.Units.SI.Voltage e_d_subtrans(start=0) ;
  Modelica.Units.SI.Voltage e_q_subtrans(start=v_n) ;
  Modelica.Units.SI.Angle theta_absolut(start=0.17453292519943295) ;




initial equation
  der(e_d_trans)=0;
  der(e_q_trans)=0;
  der(e_d_subtrans)=0;
  der(e_q_subtrans)=0;
equation




if OwnFrequency==true then
  v_d*i_d+v_q*i_q + D_cage*der(theta) = (mpp.tau * omega);
else
  v_d*i_d+v_q*i_q = (mpp.tau * omega);
end if;
  S_c.re=epp.P;
  S_c.im=epp.Q;


  T_d0_trans*der(e_q_trans)=-e_q_trans-(X_d-X_d_trans)*i_d+e_FD;
  T_q0_trans*der(e_d_trans)=-e_d_trans+(X_q-X_q_trans)*i_q;

  T_d0_subtrans*der(e_q_subtrans)=e_q_trans-(X_d_trans-X_d_subtrans)*i_d-e_q_subtrans;
  T_q0_subtrans*der(e_d_subtrans)=e_d_trans+(X_q_trans-X_q_subtrans)*i_q-e_d_subtrans;

  v_d=X_q_subtrans*i_q-R_a*i_d+e_d_subtrans;
  v_q=-X_d_subtrans*i_d-R_a*i_q+e_q_subtrans;
  v_d^2+v_q^2=v_grid^2;
  cos(theta_absolut)=if v_q < v_grid then v_q/v_grid else 1;
  S_c.re=-((v_d+R_a*i_d)*i_d+(v_q+R_a*i_q)*i_q);
  S_c.im=-(v_q*i_d-v_d*i_q);
  e_FD=E_input;
  theta=theta_absolut+delta_lsm
  ;
end TwoAxisSynchronousMachineComplexSubtransient;

