partial model PartialQuasiStationaryGeneratorComplex "Abstract class for quasistationary generators for ComplexPowerPort"




  extends TransiEnt.Components.Electrical.Machines.Base.PartialQuasiStationaryGenerator(redeclare TransiEnt.Basics.Interfaces.Electrical.ComplexPowerPort epp);








  parameter Modelica.Units.SI.ActivePower P_el_n=180e3 "Nominal active power" ;
  parameter Modelica.Units.SI.ApparentPower S_n=225e3 "Nominal apparent power" ;
  parameter Boolean IsSlack=false "true for Slack bus" ;
   parameter SI.Angle angle_slacklsm=0 "Set voltage angle at port or polar wheel angle at slack machine" ;
   parameter Boolean OwnFrequency=false "true for own frequency, only possible when IsSlack=false" ;
   parameter Real D_cage=0 "Cage Damping" ;
  final parameter Modelica.Units.SI.PowerFactor cosphi_n=P_el_n/S_n;
  final parameter Modelica.Units.SI.ReactivePower Q_n=sqrt(S_n^2 - P_el_n^2);









  SI.ReactivePower Q_is( start=Q_n) = -epp.Q ;
  Modelica.Units.SI.Power P_mech=-mpp.tau*der(mpp.phi);
    SI.Frequency f_complex(start=simCenter.f_n,fixed=IsSlack);
    SI.Angle delta_lsm(start=0.17453292519943295) ;
    SI.Angle theta(start=0.17453292519943295) ;
initial equation
  if OwnFrequency==true then
    der(f_complex)=0;
    omega=Modelica.Units.Conversions.from_Hz(simCenter.f_n);
  end if;
equation





  if IsSlack==true then

    if simCenter.use_reference_polar_wheel then
     theta=angle_slacklsm;
    else
      delta_lsm=angle_slacklsm;
    end if;

  Connections.root(epp.f);
  else

    Connections.potentialRoot(epp.f);
  end if;
  if OwnFrequency==true then
     der(theta)=Modelica.Units.Conversions.from_Hz(f_complex - epp.f);
    else
    epp.f=f_complex;
  end if;
  epp.delta=delta_lsm;
  f_complex =Modelica.Units.Conversions.to_Hz(der(mpp.phi))
  ;
end PartialQuasiStationaryGeneratorComplex;

