model ACExciter "Simple Voltage Controller with PT1-dynamics with AC Exciter"




  extends TransiEnt.Components.Electrical.Machines.ExcitationSystemsVoltageController.PartialExcitationSystem(redeclare TransiEnt.Basics.Interfaces.Electrical.ComplexPowerPort epp1);








  parameter SI.Voltage v_n=simCenter.v_n "Nominal Voltage";
  parameter Real TA=0.1 "Time constant of Controller";
  parameter Real KA=100 "Gain of Controller";
  parameter Real TB=0.06 "Pole Lead";
  parameter Real TC=0.17 "Zero Lead";
  parameter Real TE=1 "Time constant of Exciter";
  parameter Real KE=1 "Gain of Exciter";
  parameter Real A=0.1 "coefficient for saturation";
  parameter Real B=0.03 "coefficient for saturation";
  parameter Real TST=1 "Time constantb of stabilization loop";
  parameter Real KST=0.5 "Gain of stabilization loop";
  parameter Real KD=0.38 "Konstant for load dependency";
  parameter Real R_g=0.5 "resistance of excitation circuit";
  parameter Real KC=1 "Gain of rectifier";












  Modelica.Blocks.Continuous.FirstOrder firstOrder2(
    T=TE,
    k=1,
    initType=Modelica.Blocks.Types.Init.SteadyState,
    y_start=v_n) ;
  Modelica.Blocks.Math.Feedback feedback ;
  Modelica.Blocks.Sources.RealExpression realExpression1(y=v_n) ;
  Sensors.ElectricVoltageComplex electricVoltageComplex ;
  Modelica.Blocks.Continuous.FirstOrder firstOrder1(
    initType=Modelica.Blocks.Types.Init.SteadyState,
    k=KA,
    T=TA,
    y_start=v_n) ;
  Modelica.Blocks.Continuous.TransferFunction transferFunction(
    b={TC,1},
    a={TB,1},
    initType=Modelica.Blocks.Types.Init.SteadyState,
    x_start={v_n}) ;
  Modelica.Blocks.Nonlinear.Limiter limiter(uMax=2*v_n) ;
  Modelica.Blocks.Continuous.Derivative derivative(
    k=KST,
    T=TST,
    initType=Modelica.Blocks.Types.Init.InitialOutput,
    x_start=0)                                                   ;
  Modelica.Blocks.Math.Feedback feedback1
                                         ;
  Modelica.Blocks.Math.Gain gain1(k=KD) ;
  Modelica.Blocks.Math.Product product ;
  Modelica.Blocks.Math.Gain gain2(k=KC) ;
  Modelica.Blocks.Math.Division division ;
  Modelica.Blocks.Math.Gain gain(k=KE) ;
  Modelica.Blocks.Math.Sum sum1(k={1,-1,-1,-1}, nin=4) ;
  Basics.Blocks.UserDefinedFunction IFD(y=IFD.u/R_g) ;
  Basics.Blocks.UserDefinedFunction FEX(y=if FEX.u <= 0.433 then 1 - 0.0577*FEX.u else if FEX.u > 0.433 and FEX.u < 0.75 then sqrt(0.75 - (FEX.u)^2) else 1.732*(1 - FEX.u)) ;
  Basics.Blocks.UserDefinedFunction Saturation(y=A*exp(B*(Saturation.u - v_n)/v_n)) ;
equation




  connect(feedback.u1,realExpression1. y) ;
  connect(y, y) ;
  connect(electricVoltageComplex.v, feedback.u2) ;
  connect(electricVoltageComplex.epp, epp1) ;
  connect(firstOrder1.u, transferFunction.y) ;
  connect(limiter.u, firstOrder1.y) ;
  connect(feedback.y, feedback1.u1) ;
  connect(feedback1.y, transferFunction.u) ;
  connect(derivative.y, feedback1.u2) ;
  connect(firstOrder2.y, derivative.u) ;
  connect(y, product.y) ;
  connect(product.u2, derivative.u) ;
  connect(division.y, gain2.u) ;
  connect(gain.u, derivative.u) ;
  connect(firstOrder2.u, sum1.y) ;
  connect(IFD.y, gain1.u) ;
  connect(division.u1, gain1.u) ;
  connect(FEX.y, product.u1) ;
  connect(FEX.u, gain2.y) ;
  connect(division.u2, derivative.u) ;
  connect(limiter.y, sum1.u[1]) ;
  connect(gain.y, sum1.u[2]) ;
  connect(gain1.y, sum1.u[3]) ;
  connect(Saturation.u, derivative.u) ;
  connect(Saturation.y, sum1.u[4]) ;
  connect(IFD.u, derivative.u) 
  ;
end ACExciter;

