  parameter Modelica.Units.SI.Voltage VfLimit=1.1*v_n;
  parameter Real L1=-20 "lower bound of OEL timer";
  parameter Real L2=5  "upper bound of OEL timer";
  parameter Real L3=1 "upper limit of integrator";
  parameter Real K2=-1 "reset constant of OEL";
  parameter Real K1=2 "";
  parameter Real K3=4 "feedback gain of OEL";
  parameter Real D= 2 "normal condition";




  outer TransiEnt.SimCenter simCenter;




    Modelica.Blocks.Interfaces.RealOutput Voel
    ;
  Modelica.Blocks.Interfaces.RealInput Vf
    ;




  Modelica.Blocks.Logical.Switch switchingTime
    ;
  Modelica.Blocks.Math.Feedback Feedback ;
  Modelica.Blocks.Sources.RealExpression realExpression1(y=VfLimit)
                                                                ;
   Modelica.Blocks.Logical.GreaterEqualThreshold greaterEqualThresholdDown(threshold=
       0)                                                                                     ;
  Modelica.Blocks.Sources.RealExpression realExpression(y=K2)
    ;
  Modelica.Blocks.Continuous.LimIntegrator limIntegrator(
    k=1,
    outMax=L3,
    outMin=0,
    use_reset=false,
    initType=Modelica.Blocks.Types.Init.InitialOutput)
    ;
  Modelica.Blocks.Continuous.LimIntegrator limIntegrator1(
    k=K1,
    outMax=L2,
    outMin=L1,
    initType=Modelica.Blocks.Types.Init.InitialOutput,
    y_start=L1)
               ;
  Modelica.Blocks.Math.Gain gain(k=K3) ;
  TransiEnt.Basics.Blocks.UserDefinedFunction OELBlock(y=if (OELBlock.u <= D and OELBlock.u < 0) then -1 elseif (D < OELBlock.u and OELBlock.u <= 0) then 0 else OELBlock.u) ;
equation




  connect(realExpression1.y,Feedback. u2) ;
  connect(Feedback.u1,Vf)
    ;
  connect(greaterEqualThresholdDown.y,switchingTime. u2) ;
  connect(realExpression.y,switchingTime. u3) ;
  connect(limIntegrator1.y,greaterEqualThresholdDown. u)
    ;
  connect(switchingTime.y, limIntegrator.u) ;
  connect(gain.u, Feedback.y) ;
  connect(gain.y, switchingTime.u1) ;
  connect(OELBlock.u, Feedback.y) ;
  connect(OELBlock.y, limIntegrator1.u) ;
  connect(limIntegrator.y, Voel) 
  ;
end OverExcitationLimiterSummation;

within TransiEnt.Components.Electrical.PowerTransformation;
model IdealTriac "Basic model of a PowerTransformer with constant loss in percent"




  import TransiEnt;
  extends TransiEnt.Basics.Icons.Model;




  parameter Boolean isValveMode = true "Valve mode (input between 1 and 0) / Schedule mode (reduces output by provided value)";
  parameter Boolean change_of_sign = false;
  final parameter Real sign = if change_of_sign then -1 else 1;




  TransiEnt.Basics.Interfaces.Electrical.ActivePowerPort epp_in "power port on generator side" ;
  TransiEnt.Basics.Interfaces.Electrical.ActivePowerPort epp_out "power port on consumer side (smaller power flow if triac active)" ;
  Modelica.Blocks.Interfaces.RealInput u ;




  Modelica.Units.SI.ActivePower P_el_in=epp_in.P "Power on input";
  Modelica.Units.SI.ActivePower P_el_out=-epp_out.P "Power on output";
  Modelica.Units.SI.ActivePower P_loss=P_el_in - P_el_out "Power lost / curtailed";
equation




  if isValveMode then
  epp_in.P * sign* u + epp_out.P = 0;
  else
    epp_out.P = min(0, - (epp_in.P + sign * u));
  end if;
  epp_in.f = epp_out.f
  ;
end IdealTriac;

within TransiEnt.Components.Electrical.PowerTransformation;
model SimpleTransformer "Transformer modell of a predefined Dy with simple efficiency modell"




  extends TransiEnt.Basics.Icons.Model;




protected
  parameter Real CalcRatio = if UseRatio == true then ratio else U_P / (U_S);




public
  parameter Boolean UseRatio = false "True: Use ratio value to calculate LV Voltage; False: Use MV and LV Voltage to calculate ratio"
                                                                                            ;
  parameter Real ratio = 25 "turn ratio" ;
  parameter SI.Voltage U_P = 10e3 "high voltage side" ;
  parameter SI.Voltage U_S = 400/sqrt(3) "low voltage side" ;
  parameter Real eta( min = 0, max = 1) = 1 "efficiency of transformer" ;




  Basics.Interfaces.Electrical.ApparentPowerPort epp_p ;
  Basics.Interfaces.Electrical.ApparentPowerPort epp_n ;





equation
    if (epp_p.P > 0) then
      epp_p.P * eta + epp_n.P = 0;
    else
      epp_p.P * 1/eta + epp_n.P = 0;
    end if;
  epp_p.Q + epp_n.Q = 0;
  epp_p.f = epp_n.f;
  epp_p.v = CalcRatio * epp_n.v;




  ;
end SimpleTransformer;

