  i_g_mag=i_2_mag;
end if;
if i_g_mag>(i_r*sqrt(3)) then
  overload=true;
else
  overload=false;
end if;
usage=i_g_mag/(i_r*sqrt(3));




  connect(simpleTransformer.epp_n, epp_n) ;
  connect(piModelTransformerComplexComponent.epp_p, epp_p) ;
  connect(piModelTransformerComplexComponent.epp_n, simpleTransformer.epp_p) 
  ;
