model TapChangerController "Simple model for TapChanger, model with reaction starting timer"




  extends TransiEnt.Basics.Icons.Controller;




  parameter Real numberTaps=5 "number of taps for each direction";
  parameter SI.Voltage v_prim_n=simCenter.v_n "nominal voltage on primary side";
  parameter SI.Voltage v_sec_n=30e3 "nominal voltage on secondary side";
  parameter SI.Voltage v_deadband=0.025*v_sec_n "deadband voltage for secondary side";
  parameter SI.Voltage v_max=1.05*v_sec_n "maximum voltage on secondary side";
  parameter SI.Time T_delay=10 "time delay of tap changer";
  parameter Real idleRatio=v_prim_n/v_sec_n "Ratio without tap change";
  parameter Real tapRatio=(v_max-v_sec_n)/numberTaps "Voltage change with one tap change";




  outer TransiEnt.SimCenter simCenter;




  TransiEnt.Basics.Interfaces.Electrical.ComplexPowerPort epp "connect this epp with secondary" ;
  Modelica.Blocks.Interfaces.RealOutput RatioOut ;




   TransiEnt.Components.Sensors.ElectricVoltageComplex electricVoltageComplex "measurement of voltage on secondary side" ;
   Modelica.Blocks.Logical.Timer timerUp                ;
   Modelica.Blocks.Logical.Timer timerDown                ;
   Modelica.Blocks.Logical.GreaterEqualThreshold greaterEqualThresholdUp(threshold=T_delay) ;
   Modelica.Blocks.Logical.GreaterEqualThreshold greaterEqualThresholdDown(threshold=T_delay) ;
   Modelica.Blocks.Logical.Pre preUp ;
   Modelica.Blocks.Logical.Pre         pre2                    ;
   Modelica.Blocks.Logical.And andUp ;
   Modelica.Blocks.Logical.And andDown ;
   Modelica.Blocks.Logical.Not notUp ;
   Modelica.Blocks.Logical.Not notDown ;
   Modelica.Blocks.Sources.BooleanExpression activateUpBlock(y=activateUp) ;
   Modelica.Blocks.Sources.BooleanExpression activateDownBlock(y=activateDown) ;




 Real currentTap( start=0, fixed=true, min=-numberTaps, max=numberTaps) ;
 Boolean activateUp(start=false);
 Boolean activateDown(start=false);
equation





  if electricVoltageComplex.v > v_sec_n+v_deadband then
      activateDown = true;
      activateUp = false;
    elseif electricVoltageComplex.v < v_sec_n-v_deadband then
      activateUp = true;
      activateDown = false;
    else
      activateUp = false;
      activateDown = false;
  end if;

  when timerDown.y >= T_delay then
     currentTap = (if pre(currentTap)-1 <= -numberTaps-1 then pre(currentTap) else pre(currentTap)-1);
  elsewhen timerUp.y >= T_delay then
     currentTap = (if pre(currentTap)+1 >= numberTaps+1 then pre(currentTap) else pre(currentTap) +1);
  end when;

  RatioOut=v_prim_n/(v_sec_n+pre(currentTap)*tapRatio);




  connect(electricVoltageComplex.epp, epp) ;
  connect(timerUp.y, greaterEqualThresholdUp.u) ;
  connect(preUp.u, greaterEqualThresholdUp.y) ;
  connect(timerDown.y, greaterEqualThresholdDown.u) ;
  connect(greaterEqualThresholdDown.y, pre2.u) ;
  connect(timerUp.u, andUp.y) ;
  connect(timerDown.u, andDown.y) ;
  connect(andUp.u1, notUp.y) ;
  connect(preUp.y, notUp.u) ;
  connect(andDown.u1, notDown.y) ;
  connect(pre2.y, notDown.u) ;
  connect(activateUpBlock.y, andUp.u2) ;
  connect(activateDownBlock.y, andDown.u2) 
  ;
end TapChangerController;

