model ControllerCompressor_dp "Controller to control the pressure difference of a compressor"




  import      Modelica.Units.SI;
  extends TransiEnt.Basics.Icons.Controller;








  parameter Boolean p_paramBefore=true "true if the pressure before the compressor is given by a parameter, false if it is given by an input"
                                                                                                    ;
  parameter Boolean p_paramAfter=false "true if the pressure after the compressor is given by a parameter, false if it is given by an input"
                                                                                                    ;
  parameter SI.Pressure p_beforeCompParam=30e5 "Pressure before the compressor" ;
  parameter SI.Pressure p_afterCompParam=50e5 "Pressure after the compressor" ;




  outer TransiEnt.SimCenter simCenter;




  TransiEnt.Basics.Interfaces.General.PressureIn p_beforeCompIn if not p_paramBefore "Pressure before the compressor"                                  ;
  TransiEnt.Basics.Interfaces.General.PressureIn p_afterCompIn if not p_paramAfter "Pressure after the compressor"                                 ;
  TransiEnt.Basics.Interfaces.General.PressureDifferenceOut Delta_p "Pressure difference of the compressor"                            ;
protected
  Modelica.Blocks.Sources.Constant p_beforeCompConst(k=p_beforeCompParam)
                                                          if p_paramBefore ;
  Modelica.Blocks.Sources.Constant p_afterCompConst(k=p_afterCompParam)
                                                         if p_paramAfter ;
  TransiEnt.Basics.Interfaces.General.PressureOut p_beforeComp ;
  TransiEnt.Basics.Interfaces.General.PressureOut p_afterComp ;








equation




  Delta_p=p_afterComp-p_beforeComp;




  connect(p_beforeCompIn, p_beforeComp) ;
  connect(p_beforeCompConst.y, p_beforeComp) ;
  connect(p_afterComp, p_afterCompIn) ;
  connect(p_afterCompConst.y, p_afterComp) ;
  connect(p_beforeComp, p_beforeComp) 
  ;
end ControllerCompressor_dp;

within TransiEnt.Components.Gas.Compressor.Controller;
model ControllerValveAndCompressor_dp "Controls the mass flow through a valve or a compressor depending on the pressure difference"




  extends TransiEnt.Basics.Icons.Controller;




















  TransiEnt.Basics.Interfaces.General.PressureDifferenceIn dp_desired "Desired pressure difference" ;
  TransiEnt.Basics.Interfaces.General.MassFlowRateOut m_flow_valve "Desired mass flow through valve" ;
  TransiEnt.Basics.Interfaces.General.PressureDifferenceOut dp_comp "Desired compressor pressure difference" ;
  TransiEnt.Basics.Interfaces.General.MassFlowRateIn m_flow "Mass flow rate through unit" ;




equation




  if dp_desired<0 then
    m_flow_valve = m_flow;
    dp_comp = dp_desired;
  else
    dp_comp = dp_desired;
    m_flow_valve = 0;
  end if
  ;
end ControllerValveAndCompressor_dp;

within TransiEnt.Components.Gas.Compressor.Controller;
model ControllerValveAndCompressor_mflow "Controls the mass flow through a valve or a compressor depending on the pressure difference"




  extends TransiEnt.Basics.Icons.Controller;
  import      Modelica.Units.SI;








  parameter SI.Pressure p_before_low=1e5 "Lower limit for hysteresis to limit mass flow for too low pressures" ;
  parameter SI.Pressure p_before_high=1.1e5 "Higher limit for hysteresis to limit mass flow for too low pressures" ;












  TransiEnt.Basics.Interfaces.General.MassFlowRateIn m_flowDesired "Desired mass flow rate" ;
  TransiEnt.Basics.Interfaces.General.PressureIn p_before "Pressure before the valve/compressor" ;
  TransiEnt.Basics.Interfaces.General.PressureIn p_after "Pressure after the valve/compressor" ;
  TransiEnt.Basics.Interfaces.General.MassFlowRateOut m_flowValve "Mass flow rate through the valve" ;
  TransiEnt.Basics.Interfaces.General.MassFlowRateOut m_flowCompressor "Mass flow rate through the compressor" ;




  Modelica.Blocks.Logical.Hysteresis hysteresis(uLow=p_before_low, uHigh=p_before_high,
    pre_y_start=true)                           ;
equation




  if not
        (hysteresis.y) then
    m_flowValve=0;
    m_flowCompressor=0;
  elseif p_before>p_after then
    m_flowValve=m_flowDesired;
    m_flowCompressor=0;
  else
    m_flowCompressor=m_flowDesired;
    m_flowValve=0;
  end if;
  connect(p_before, hysteresis.u) 
  ;
end ControllerValveAndCompressor_mflow;

