model Dryer_L1 "Ideally dries a syngas flow"




  extends TransiEnt.Basics.Icons.Model;
  import      Modelica.Units.SI;




  final parameter Integer N_comp_1=medium_gas.nc-1 "Number of components in the gas -1";




  parameter TransiEnt.Basics.Media.Gases.VLE_VDIWA_SG4_var medium_gas "Gas medium in the dryer" ;
  parameter TILMedia.VLEFluidTypes.TILMedia_SplineWater medium_water "Water medium in the dryer" ;
  parameter Integer positionOfWater(min=1,max=N_comp_1+1)=3 "Position of the water component in the gas medium vector" ;
  parameter SI.PressureDifference pressureLoss=0e5 "Pressure loss in hydrogen flow direction" ;




  outer TransiEnt.SimCenter simCenter;




  TransiEnt.Basics.Interfaces.Gas.RealGasPortIn gasPortIn(Medium=medium_gas) ;
  TransiEnt.Basics.Interfaces.Gas.RealGasPortOut gasPortOut(Medium=medium_gas) ;
  TransiEnt.Basics.Interfaces.Thermal.FluidPortOut fluidPortOut(Medium=medium_water) ;




protected
  TILMedia.Internals.VLEFluidConfigurations.FullyMixtureCompatible.VLEFluid_ph gasIn(
    computeSurfaceTension=false,
    deactivateDensityDerivatives=true,
    vleFluidType=medium_gas,
    p=gasPortIn.p,
    h=inStream(gasPortIn.h_outflow),
    xi=inStream(gasPortIn.xi_outflow),
    deactivateTwoPhaseRegion=true) ;
  TILMedia.Internals.VLEFluidConfigurations.FullyMixtureCompatible.VLEFluid_ph gasOut(
    computeSurfaceTension=false,
    deactivateDensityDerivatives=true,
    vleFluidType=medium_gas,
    p=gasPortOut.p,
    h=gasPortOut.h_outflow,
    xi=gasPortOut.xi_outflow,
    deactivateTwoPhaseRegion=true) ;
  TILMedia.Internals.VLEFluidConfigurations.FullyMixtureCompatible.VLEFluid_ph fluidOut(
    vleFluidType=medium_water,
    p=fluidPortOut.p,
    h=fluidPortOut.h_outflow,
    xi=fluidPortOut.xi_outflow) ;
public
  inner Summary summary(
    gasPortIn(
      mediumModel=medium_gas,
      xi=gasIn.xi,
      x=gasIn.x,
      m_flow=gasPortIn.m_flow,
      T=gasIn.T,
      p=gasPortIn.p,
      h=gasIn.h,
      rho=gasIn.d),
    gasPortOut(
      mediumModel=medium_gas,
      xi=gasOut.xi,
      x=gasOut.x,
      m_flow=-gasPortOut.m_flow,
      T=gasOut.T,
      p=gasPortOut.p,
      h=gasOut.h,
      rho=gasOut.d),
    fluidPortOut(
      mediumModel=medium_water,
      xi=fluidOut.xi,
      x=fluidOut.x,
      m_flow=-fluidPortOut.m_flow,
      T=fluidOut.T,
      p=fluidPortOut.p,
      h=fluidOut.h,
      rho=fluidOut.d)) ;




protected
  model Summary
    extends TransiEnt.Basics.Icons.Record;
    TransiEnt.Basics.Records.FlangeRealGas gasPortIn;
    TransiEnt.Basics.Records.FlangeRealGas gasPortOut;
    TransiEnt.Basics.Records.FlangeRealGas fluidPortOut;
  end Summary;
equation





  gasPortIn.m_flow + gasPortOut.m_flow + fluidPortOut.m_flow = 0;
  if not
        (positionOfWater==N_comp_1+1) then
    fluidPortOut.m_flow = -gasIn.xi[positionOfWater]*gasPortIn.m_flow;
  else
    fluidPortOut.m_flow = -(1-sum(gasIn.xi))*gasPortIn.m_flow;
  end if;

  gasPortOut.p = gasPortIn.p - pressureLoss;

  fluidOut.T = gasIn.T;
  gasOut.T = gasIn.T;

  if not
        (positionOfWater==N_comp_1+1) then
    for i in cat(1,1:positionOfWater-1,positionOfWater+1:N_comp_1) loop
      gasOut.xi[i] = gasIn.xi[i]/(1 - gasIn.xi[positionOfWater]);
    end for;
    gasOut.xi[positionOfWater] = 0;        
  else
    gasOut.xi = gasIn.xi/sum(gasIn.xi);
  end if;

  gasPortIn.h_outflow =inStream(gasPortOut.h_outflow);
  gasPortIn.xi_outflow =inStream(gasPortOut.xi_outflow);




  ;
end Dryer_L1;

within TransiEnt.Components.Gas.GasCleaning;
model PressureSwingAdsorptionReactor_L1 "Pressure swing adsorption reactor with constant efficiency of hydrogen separation"




  import      Modelica.Units.SI;
  extends TransiEnt.Basics.Icons.PSA;




  final parameter Basics.Media.Gases.VLE_VDIWA_SG6_var medium "Medium in the pressure swing adsorber";




  parameter SI.PressureDifference pressureLoss=0.2e5 "Pressure loss in H2 flow direction" ;
  parameter SI.Efficiency eta_h2 = 0.8 "Efficiency of hydrogen separation" ;




  outer TransiEnt.SimCenter simCenter;




  TransiEnt.Basics.Interfaces.Gas.RealGasPortIn gasPortIn(Medium=medium) ;
  TransiEnt.Basics.Interfaces.Gas.RealGasPortOut gasPortOut_hydrogen(Medium=medium) ;
  TransiEnt.Basics.Interfaces.Gas.RealGasPortOut gasPortOut_offGas(Medium=medium) ;




protected
  TILMedia.Internals.VLEFluidConfigurations.FullyMixtureCompatible.VLEFluid_ph gasIn(
    computeSurfaceTension=false,
    deactivateDensityDerivatives=true,
    vleFluidType=medium,
    p=gasPortIn.p,
    h=inStream(gasPortIn.h_outflow),
    xi=inStream(gasPortIn.xi_outflow),
    deactivateTwoPhaseRegion=true) ;
  TILMedia.Internals.VLEFluidConfigurations.FullyMixtureCompatible.VLEFluid_ph gasOut_hydrogen(
    computeSurfaceTension=false,
    deactivateDensityDerivatives=true,
    vleFluidType=medium,
    p=gasPortOut_hydrogen.p,
    h=gasPortOut_hydrogen.h_outflow,
    xi=gasPortOut_hydrogen.xi_outflow,
    deactivateTwoPhaseRegion=true) ;
  TILMedia.Internals.VLEFluidConfigurations.FullyMixtureCompatible.VLEFluid_ph gasOut_offGas(
    computeSurfaceTension=false,
    deactivateDensityDerivatives=true,
    vleFluidType=medium,
    p=gasPortOut_offGas.p,
    h=gasPortOut_offGas.h_outflow,
    xi=gasPortOut_offGas.xi_outflow,
    deactivateTwoPhaseRegion=true) ;
public
  inner Summary summary(
    outline(pressureLoss=pressureLoss, eta_h2=eta_h2),
    gasPortIn(
      mediumModel=medium,
      xi=gasIn.xi,
      x=gasIn.x,
      m_flow=gasPortIn.m_flow,
      T=gasIn.T,
      p=gasPortIn.p,
      h=gasIn.h,
      rho=gasIn.d),
    gasPortOut_hydrogen(
      mediumModel=medium,
      xi=gasOut_hydrogen.xi,
      x=gasOut_hydrogen.x,
      m_flow=-gasPortOut_hydrogen.m_flow,
      T=gasOut_hydrogen.T,
      p=gasPortOut_hydrogen.p,
      h=gasOut_hydrogen.h,
      rho=gasOut_hydrogen.d),
    gasPortOut_offGas(
      mediumModel=medium,
      xi=gasOut_offGas.xi,
      x=gasOut_offGas.x,
      m_flow=-gasPortOut_offGas.m_flow,
      T=gasOut_offGas.T,
      p=gasPortOut_offGas.p,
      h=gasOut_offGas.h,
      rho=gasOut_offGas.d)) ;




protected
  SI.MassFraction sum_xi_offGas "Sum of the off gas components' xi's in gasIn";
  model Outline
    input SI.PressureDifference pressureLoss "Pressure loss in hydrogen flow direction";
    input SI.Efficiency eta_h2 "Efficiency of hydrogen separation";
  end Outline;
  model Summary
    extends TransiEnt.Basics.Icons.Record;
    Outline outline;
    TransiEnt.Basics.Records.FlangeRealGas gasPortIn;
    TransiEnt.Basics.Records.FlangeRealGas gasPortOut_hydrogen;
    TransiEnt.Basics.Records.FlangeRealGas gasPortOut_offGas;
  end Summary;
equation





  gasPortIn.m_flow + gasPortOut_hydrogen.m_flow + gasPortOut_offGas.m_flow = 0;
  gasPortOut_hydrogen.m_flow = -eta_h2*gasIn.xi[4]*gasPortIn.m_flow;

  gasPortOut_hydrogen.p = gasPortIn.p - pressureLoss;

  gasOut_hydrogen.T = gasIn.T;
  gasOut_offGas.T = gasIn.T;


  gasOut_hydrogen.xi[1:3] = zeros(3);
  gasOut_hydrogen.xi[4] = 1; 
  gasOut_hydrogen.xi[5] = 0;

  sum_xi_offGas = 1-eta_h2*gasIn.xi[4];
  for i in {1,2,3,5} loop
    gasOut_offGas.xi[i] = gasIn.xi[i]/sum_xi_offGas;
  end for;
  gasOut_offGas.xi[4] = (1 - eta_h2)*gasIn.xi[4]/sum_xi_offGas;

  gasPortIn.h_outflow = inStream(gasPortOut_hydrogen.h_outflow);
  gasPortIn.xi_outflow = inStream(gasPortOut_hydrogen.xi_outflow);




  ;
end PressureSwingAdsorptionReactor_L1;

