    computeSurfaceTension=false,
    deactivateDensityDerivatives=true,
    vleFluidType=medium1,
    p=gasPortIn1.p,
    h=inStream(gasPortIn1.h_outflow),
    xi=inStream(gasPortIn1.xi_outflow),
