model Prereformer_L1 "Ideally transforms ethane, propane and butane with water into carbon monoxide and methane"




  extends Base.PartialFixedBedReactorRealGas_L1(
    redeclare final Basics.Media.Gases.VLE_VDIWA_NG7_SG_var medium,
    pressureLoss=2e5,
    final N_reac=3,
    final Delta_H={3.713e3, 16.687e3, 31.420e3});
  import      Modelica.Units.SI;




  constant SI.MolarMass M_comp[medium.nc-1] = {0.01604,0.03007,0.0441,0.05812,0.02801,0.04401,0.01802,0.02801} "Molar masses of components of vle_ng7_sg";




















equation




  gasPortOut.xi_outflow[1]=inStream(gasPortIn.xi_outflow[1])+M_comp[1]*(5/3*inStream(gasPortIn.xi_outflow[2])/M_comp[2]+7/3*inStream(gasPortIn.xi_outflow[3])/M_comp[3]+3*inStream(gasPortIn.xi_outflow[4])/M_comp[4]); 
  gasPortOut.xi_outflow[2:4]=zeros(3); 
  gasPortOut.xi_outflow[5]=inStream(gasPortIn.xi_outflow[5]); 
  gasPortOut.xi_outflow[6]=inStream(gasPortIn.xi_outflow[6]); 
  gasPortOut.xi_outflow[7]=max(0,inStream(gasPortIn.xi_outflow[7])-M_comp[7]*(1/3*inStream(gasPortIn.xi_outflow[2])/M_comp[2]+2/3*inStream(gasPortIn.xi_outflow[3])/M_comp[3]+1*inStream(gasPortIn.xi_outflow[4])/M_comp[4])); 
  gasPortOut.xi_outflow[8]=inStream(gasPortIn.xi_outflow[8])+M_comp[8]*(1/3*inStream(gasPortIn.xi_outflow[2])/M_comp[2]+2/3*inStream(gasPortIn.xi_outflow[3])/M_comp[3]+1*inStream(gasPortIn.xi_outflow[4])/M_comp[4]); 
  Q_reac=sum(inStream(gasPortIn.xi_outflow[2:4]).*gasPortIn.m_flow./M_comp[2:4].*Delta_H[1:3]);




  ;
end Prereformer_L1;

