model WaterGasShiftReactor_L1 "Performs ideal water gas shift reaction with given conversion"




  extends Base.PartialFixedBedReactorRealGas_L1(
    redeclare final Basics.Media.Gases.VLE_VDIWA_SG6_var medium,
    pressureLoss=3.5e5,
    final N_reac=1,
    final Delta_H={-41150});
  import      Modelica.Units.SI;




  constant SI.MolarMass M_CO2=0.04401 "Molar mass of CO2";
  constant SI.MolarMass M_H2O=0.01802 "Molar mass of H2O";
  constant SI.MolarMass M_H2=0.00202 "Molar mass of H2";
  constant SI.MolarMass M_CO=0.02801 "Molar mass of CO";




  parameter Real conversion=0.97 "Conversion rate of CO" ; 
















equation




  gasPortOut.xi_outflow[1]=inStream(gasPortIn.xi_outflow[1]); 
  gasPortOut.xi_outflow[2]=inStream(gasPortIn.xi_outflow[2])+conversion*inStream(gasPortIn.xi_outflow[5])*M_CO2/M_CO; 
  gasPortOut.xi_outflow[3]=max(0,inStream(gasPortIn.xi_outflow[3])-conversion*inStream(gasPortIn.xi_outflow[5])*M_H2O/M_CO); 
  gasPortOut.xi_outflow[4]=inStream(gasPortIn.xi_outflow[4])+conversion*inStream(gasPortIn.xi_outflow[5])*M_H2/M_CO; 
  gasPortOut.xi_outflow[5]=(1-conversion)*inStream(gasPortIn.xi_outflow[5]); 
  Q_reac=conversion*inStream(gasPortIn.xi_outflow[5])*gasPortIn.m_flow/M_CO*Delta_H[1];




  ;
end WaterGasShiftReactor_L1;

within TransiEnt.Components.Gas.Reactor.Base;
partial model PartialFixedbedReactorIdealGas_L4 "Discretized model of a fixed-bed reactor using ideal gas models"





  extends TransiEnt.Basics.Icons.FixedBedReactor_L4;
  import TransiEnt;
  import Modelica.Constants.pi;
  import      Modelica.Units.SI;




  final parameter Integer N_comp=medium.nc "number of components";
  final parameter SI.CrossSection A_c = N_tube*pi/4*dia_tube_i^2 "total crosssectional area of all reactor tubes";
  final parameter SI.Length Delta_x=l/N_cv "Length of one control volume";






  replaceable parameter TILMedia.GasTypes.BaseGas medium=simCenter.gasModel2 "Medium model" ;
  parameter Boolean useHomotopy=simCenter.useHomotopy "true if homotopy should be used" ;
  parameter Integer N_cv=1 "Number of control volumes" ;
  parameter Integer N_reac "Number of reactions" ;
  parameter Integer nu[N_reac,N_comp-1] "Matrix with stochiometric coefficients of all components-1 in all reactions"
                                                                                                    ;
  parameter SI.MolarEnergy E_i[N_reac] "Activation energies" ;
  parameter SI.MolarEnthalpy dH_R_i[N_reac] "Reaction enthalpies" ;
  parameter SI.Efficiency eff[N_cv,N_reac] "Effectiveness factors for the reactions" ;
  parameter SI.PressureDifference Delta_p "Total pressure loss over the reactor" ;
  parameter Integer pressureCalculation=1 "Method of pressure calculation" ;
  parameter Real N_tube "Number of tubes" ;
  parameter SI.Diameter dia_tube_i "Inner tube diameter" ;
  parameter SI.Length l "Length of reactor" ;
  parameter SI.Diameter dia_part "Equivalent pellet diameter" ;
  parameter SI.VolumeFraction eps_bed "Bed porosity" ;
  parameter SI.VolumeFraction eps_cat "Catalyst porosity" ;
  parameter SI.Density d_cat "Density of catalyst particle" ;
  parameter SI.Density d_bed = d_cat*(1-eps_bed) "Density of fixed-bed" ; 
  parameter SI.SpecificHeatCapacity cp_cat "Specific heat capacity of catalyst" ;
  parameter SI.Temperature T_nom[N_cv] "Nominal gas and catalyst temperature in the control volumes" ;
  parameter SI.Pressure p_nom[N_cv] "Nominal pressure in the control volumes" ;
  parameter SI.MassFraction xi_nom[N_cv,N_comp-1] "Nominal values for mass fractions" ;




  outer TransiEnt.SimCenter simCenter;




  TransiEnt.Basics.Interfaces.Gas.IdealGasEnthPortIn gasPortIn(Medium=medium) ;
  TransiEnt.Basics.Interfaces.Gas.IdealGasEnthPortOut gasPortOut(Medium=medium) ;
  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a heat[N_cv]      ;




protected
  TILMedia.Gas_pT gasBulk[N_cv](
    p=if useHomotopy then homotopy(p,p_nom) else p,
    T=if useHomotopy then homotopy(T,T_nom) else T,
    xi= if useHomotopy then homotopy(xi,xi_nom) else xi,
    each gasType=medium,
    each computeTransportProperties=true)
    ;
  TILMedia.Gas_ph gasIn(
    p=gasPortIn.p,
    h= inStream(gasPortIn.h_outflow),
    xi= inStream(gasPortIn.xi_outflow),
    gasType=medium,
    computeTransportProperties=true)
    ;




protected
  Real k_i[N_cv,N_reac] "Rate constants for reactions N_reac";
  Real K_i[N_cv,N_reac] "Equilibrium constants for reactions N_reac";
  Real r_i_eff[N_cv,N_comp-1] "Effective reaction rate of components in mol/(kg cat s)";
  Real RR_eff[N_cv,N_reac] "Effective reaction rates of reactions N_reac in mol/(kg cat s)";
  Real RR[N_cv,N_reac] "Reaction rates of reactions N_reac in mol/(kg cat s)";
  SI.MassFlowRate m_flow = max(gasPortIn.m_flow,0) "Mass flow through the reactor";
public
  SI.Temperature T[N_cv] "Gas and catalyst temperature in the control volumes" ;
  SI.Pressure p[N_cv] "Pressure in the control volumes" ;
  SI.MassFraction xi[N_cv,N_comp-1] "Mass fraction in the control volumes" ;

equation




  for n in 1:N_cv loop
    RR_eff[n,:] = RR[n,:] .* eff[n,:];
    r_i_eff[n,:] = RR_eff[n,:] * nu[:,:];

    if n == 1 then
      for i in 1:N_comp-1 loop
        eps_bed*der(xi[1,i])*gasBulk[1].d = 1/(Delta_x*A_c)*m_flow*(gasIn.xi[i] - xi[1,i]) + gasBulk[1].M_i[i]*d_bed*r_i_eff[1,i]; 
      end for;
      (d_bed*cp_cat+(eps_bed+(1-eps_bed)*eps_cat)*gasBulk[1].d*gasBulk[1].cp)*A_c*der(T[1]) = 1/Delta_x*m_flow*(gasIn.cp*gasIn.T-gasBulk[1].cp*T[1]) + heat[1].Q_flow/Delta_x - A_c*d_bed*RR_eff[1,:]*dH_R_i;
    else
      for i in 1:N_comp-1 loop
        eps_bed*der(xi[n,i])*gasBulk[n].d = 1/(Delta_x*A_c)*m_flow*(xi[n-1,i] - xi[n,i]) + gasBulk[n].M_i[i]*d_bed*r_i_eff[n,i]; 
      end for;
      (d_bed*cp_cat+(eps_bed+(1-eps_bed)*eps_cat)*gasBulk[n].d*gasBulk[n].cp)*A_c*der(T[n]) = 1/Delta_x*m_flow*(gasBulk[n-1].cp*T[n-1]-gasBulk[n].cp*T[n]) + heat[n].Q_flow/Delta_x - A_c*d_bed*RR_eff[n,:]*dH_R_i;
    end if;

    if pressureCalculation==1 then
      p[n] = gasPortIn.p - Delta_p*(2*n-1)/(2*N_cv); 
    else
      p[n] = gasPortIn.p - Delta_p*n/N_cv; 
    end if;

  end for;
  gasPortIn.p = gasPortOut.p + Delta_p;
  gasPortIn.m_flow + gasPortOut.m_flow = 0;
  gasPortOut.h_outflow = gasBulk[N_cv].h;
  gasPortOut.xi_outflow = xi[N_cv,:];
  gasPortIn.h_outflow = inStream(gasPortOut.h_outflow);
  gasPortIn.xi_outflow = inStream(gasPortOut.xi_outflow);




  ;
end PartialFixedbedReactorIdealGas_L4;

