  parameter SI.MolarEnthalpy Delta_H[N_reac] "Reaction enthalpy for the reactions in J/mol" ;
  parameter SI.PressureDifference pressureLoss "Pressure loss over the reactor" ;
  parameter Boolean useFluidModelsForSummary=false "True, if fluid models shall be used for the summary" ;




  outer TransiEnt.SimCenter simCenter;




  TransiEnt.Basics.Interfaces.Gas.RealGasPortIn gasPortIn(Medium=medium) ;
  TransiEnt.Basics.Interfaces.Gas.RealGasPortOut gasPortOut(Medium=medium) ;




protected
  TILMedia.Internals.VLEFluidConfigurations.FullyMixtureCompatible.VLEFluid_ph gasIn(
    computeSurfaceTension=false,
    deactivateDensityDerivatives=true,
    vleFluidType=medium,
