  extends TransiEnt.Components.Gas.VolumesValvesFittings.Base.VolumeRealGas_L4(
    redeclare model Geometry =
        ClaRa.Basics.ControlVolumes.Fundamentals.Geometry.PipeGeometry_N_cv (
        z_in=z_in,
