within TransiEnt.Components.Heat.Fan;
model Fan_L1 "Simple L1 model for fan"




  import SI = ClaRa.Basics.Units;




    model Outline
    extends ClaRa.Basics.Icons.RecordIcon;
    input SI.VolumeFlowRate V_flow_out "Volume flow rate";
    input SI.Power P_hyd "Hydraulic power";
    input SI.Power P_mech "Mechanical power";
    input SI.Power P_el "Electrical power";
    input ClaRa.Basics.Units.Power P_el_loss "Electric Power lost at conversion";
    input SI.PressureDifference Delta_p "Pressure difference";
    end Outline;
  model Summary
    extends ClaRa.Basics.Icons.RecordIcon;
    Outline outline;
    ClaRa.Basics.Records.FlangeGas  inlet;
    ClaRa.Basics.Records.FlangeGas  outlet;
  end Summary;




  parameter Real eta_polytropic = 0.85 "polytropic efficiency" ;
  parameter Real eta_mech = 0.95 "mechanical efficiency" ;
  parameter Real eta_el = 0.9 "electric efficiency" ;
  parameter SI.MassFlowRate m_flow_max = 15 "maximum mass flow rate" ;
  parameter SI.Time timeConstant_m_flow = 60 "time constant of mass flow with respect to set point variation" ;
  parameter TILMedia.GasTypes.BaseGas medium1=simCenter.airModel "Medium"
    ;
  parameter Boolean showData=false "True if a data port containing p,T,h,s,m_flow shall be shown, else false" ;




    outer ClaRa.SimCenter simCenter;




  ClaRa.Basics.Interfaces.GasPortIn inlet(Medium=medium1) ;
  ClaRa.Basics.Interfaces.GasPortOut outlet(Medium=medium1) ;
  TransiEnt.Basics.Interfaces.Electrical.ActivePowerPort epp
    ;
  Modelica.Blocks.Interfaces.RealInput m_flow_set ;




  TransiEnt.Components.Boundaries.Electrical.ActivePower.Power Power ;
  TILMedia.Gas_pT air_inlet(
    p=inlet.p,
    T=inStream(inlet.T_outflow),
    xi=inStream(inlet.xi_outflow),
    gasType=medium1) ;
  TILMedia.Gas_pT air_outlet(
    gasType=medium1,
    T=T_out,
    p=outlet.p,
    xi=air_inlet.xi) ;
  Modelica.Blocks.Sources.RealExpression realExpression(y=P_el)      ;
  ClaRa.Components.BoundaryConditions.BoundaryGas_Txim_flow boundaryGas_Txim_flow(
    variable_m_flow=true,
    medium=medium1,
    variable_T=true,
    xi_const=medium1.xi_default) ;
  ClaRa.Components.BoundaryConditions.BoundaryGas_Txim_flow
                                                       boundaryGas_Txim_flow1(
    medium=medium1,
    variable_m_flow=true,
    variable_T=true,
    xi_const=medium1.xi_default) ;
  Modelica.Blocks.Sources.RealExpression realExpression1(y=air_outlet.T)    ;
  Summary summary(
    outline(
      V_flow_out=V_flow_out,
      P_hyd=P_hyd,
      P_mech=P_mech,
      P_el=P_el,
      P_el_loss=P_el - P_hyd,
      Delta_p=air_outlet.p - air_inlet.p),
    inlet(
      mediumModel=medium1,
      m_flow=inlet.m_flow,
      T=air_inlet.T,
      p=air_inlet.p,
      h=air_inlet.h,
      xi=air_inlet.xi,
      H_flow=inlet.m_flow*air_inlet.h),
    outlet(
      mediumModel=medium1,
      m_flow=outlet.m_flow,
      T=air_outlet.T,
      p=air_outlet.p,
      h=air_outlet.h,
      xi=air_outlet.xi,
      H_flow=outlet.m_flow*air_outlet.h)) ;
  Modelica.Blocks.Continuous.FirstOrder firstOrder(T=timeConstant_m_flow) ;
  Modelica.Blocks.Nonlinear.VariableLimiter massFlowLimit(strict=true) ;
  Modelica.Blocks.Sources.RealExpression realExpression3(y=m_flow_max) ;
  Modelica.Blocks.Sources.RealExpression realExpression4(y=0) ;
  Modelica.Blocks.Sources.RealExpression realExpression2(y=inStream(inlet.T_outflow)) ;
  Modelica.Blocks.Math.Gain gain(k=-1) ;




 Real kappa "Ratio of specific heats";
 SI.Temperature T_out "outlet fluid temperature";
 SI.EnthalpyMassSpecific Delta_h "fluid enthalpy difference";
 SI.Pressure    Delta_p(final start=100) "pressure difference across fan";
 SI.Power    P_hyd "Hydraulic power";
 SI.Power    P_mech "Mechanical power";
 SI.Power    P_el "Electric power";
 SI.MassFlowRate     m_flow "fluid mass flow rate";
 SI.VolumeFlowRate     V_flow_out "outlet volume flow rate";
 SI.Power P_check "residuum power for verification purpose";
 SI.Energy E_check "residuum energy for verification purpose";
equation




  m_flow = firstOrder.y;
  air_inlet.cv * kappa = air_inlet.cp;
  Delta_p = air_inlet.p - air_outlet.p;
  P_hyd = Delta_h*m_flow;
  P_mech = P_hyd/(eta_mech);
  P_el = P_mech/(eta_el);
  V_flow_out = m_flow / air_outlet.d;
  T_out = air_inlet.T * (air_outlet.p/air_inlet.p)^((kappa -1.0)/(eta_polytropic*kappa));
  Delta_h = air_outlet.h - air_inlet.h;
  P_check = P_hyd + summary.inlet.H_flow + summary.outlet.H_flow;
   der(E_check) = P_check;




  connect(Power.epp, epp) ;
  connect(realExpression.y, Power.P_el_set) ;
  connect(boundaryGas_Txim_flow.gas_a, outlet) ;
  connect(boundaryGas_Txim_flow1.gas_a, inlet) ;
  connect(realExpression1.y, boundaryGas_Txim_flow.T) ;
  connect(m_flow_set, massFlowLimit.u) ;
  connect(realExpression4.y, massFlowLimit.limit2) ;
  connect(realExpression3.y, massFlowLimit.limit1) ;
  connect(massFlowLimit.y, firstOrder.u) ;
  connect(firstOrder.y, boundaryGas_Txim_flow.m_flow) ;
  connect(firstOrder.y, gain.u) ;
  connect(gain.y, boundaryGas_Txim_flow1.m_flow) ;
  connect(realExpression2.y, boundaryGas_Txim_flow1.T) 
     ;
end Fan_L1;

