model Convection_L4 "Lumped thermal element for heat convection (Q_flow = Gc*dT)"
  parameter ClaRa.Basics.Units.Length length=1 "Length of plate"     ;
  parameter ClaRa.Basics.Units.Length width= 1 "Width of plate"     ;
  parameter ClaRa.Basics.Units.CoefficientOfHeatTransfer alpha = 10 "Signal representing the convective thermal conductance in [W/K]"    ;
  parameter Integer N_ax = 1;
protected
  final parameter ClaRa.Basics.Units.Length Delta_x[N_ax]=ClaRa.Basics.Functions.GenerateGrid(
      {0},
      length,
      N_ax) "Discretisation scheme" ;
   final parameter ClaRa.Basics.Units.Area A_heat[N_ax]={Delta_x[i]*width for i in 1:N_ax} "Area for heat transfer";
public
  ClaRa.Basics.Interfaces.HeatPort_a[N_ax] solid ;
  ClaRa.Basics.Interfaces.HeatPort_b[N_ax] fluid ;
equation
  solid.Q_flow + fluid.Q_flow = zeros(N_ax);
  solid.Q_flow = alpha.*A_heat.*(solid.T - fluid.T);

