    diameter_i=diameter_i,
    diameter_o=diameter_o,
    pipe_wall_thickness=pipe_wall_thickness,
    K=K,
    p_start=p_start_supply,
    T_start=T_start_supply,
    m_flow_start=m_flow_start,
