  connect(waterPortIn_supply, singlePipe_LX_supply.waterPortIn) ;
  connect(waterPortOut_return, singlePipe_LX_return.waterPortOut) ;
  connect(singlePipe_LX_supply.waterPortOut, waterPortOut_supply) ;
  connect(heat_supply, singlePipe_LX_supply.heat)
    ;
  connect(heat_return, singlePipe_LX_return.heat) 
  ;
