      TransiEnt.Components.Heat.VolumesValvesFittings.Pipes.Base.HT_Single_Buried_L2              constrainedby TransiEnt.Components.Heat.VolumesValvesFittings.Pipes.Base.HT_PlugFlow_Base_L2
                                                                                                                                                                                      ;
  inner TransiEnt.Components.Heat.VolumesValvesFittings.Pipes.Base.pipe_parameters pipe_parameter(
    calc_initial_dstrb=calc_initial_dstrb,
    depth=depth,
    diameter_i=diameter_i,
    p_start=p_start,
    T_start=T_start,
    m_flow_start=m_flow_start,
    diameter_o=diameter_o,
    length=length,
    z_in=z_in,
    z_out=z_out,
    pipe_wall_thickness=pipe_wall_thickness,
    K=K,
    v_nom=v_nom,
    lambda_insulation=lambda_insulation) ;




public
  TransiEnt.Basics.Interfaces.Thermal.FluidPortIn waterPortIn(Medium=simCenter.fluid1)
    "Inlet port" ;
  TransiEnt.Basics.Interfaces.Thermal.FluidPortOut waterPortOut(each Medium=
        simCenter.fluid1) "Outlet port" ;
  Pipes.Base.dp_residencetime dp_residencetime(calc_initial_dstrb=calc_initial_dstrb) ;
  HeatTransfer hT_PlugFlow_LX_nom ;
  HeatTransfer hT_PlugFlow_LX_rev ;
  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a heat
    ;
  Base.Fluid_Volume fluid_Volume(
    p_nom=p_start,
    h_nom=pipe_parameter.h_start,
    h_start=pipe_parameter.h_start,
    p_start=p_start,
    V_const=pipe_parameter.carrier_pipe_capacity/(pipe_parameter.rho*pipe_parameter.cp_w))
                                 if activate_volumes ;
  Modelica.Thermal.HeatTransfer.Sources.FixedHeatFlow fixedHeatFlow(Q_flow=0) if activate_volumes ;
equation




  connect(dp_residencetime.residence_time_reversed, hT_PlugFlow_LX_rev.residence_time) ;
  connect(dp_residencetime.residence_time_nom, hT_PlugFlow_LX_nom.residence_time) ;
  connect(heat, heat)
    ;
  connect(hT_PlugFlow_LX_rev.heat, heat) ;
  connect(heat, hT_PlugFlow_LX_nom.heat) ;
  connect(waterPortIn, hT_PlugFlow_LX_rev.waterPortOut) ;
  connect(hT_PlugFlow_LX_rev.waterPortIn, dp_residencetime.waterPortIn) ;
  connect(dp_residencetime.waterPortOut, hT_PlugFlow_LX_nom.waterPortIn) ;
  if not activate_volumes then
    connect(hT_PlugFlow_LX_nom.waterPortOut, waterPortOut) ;
  else
    connect(fluid_Volume.waterPort_in[1], hT_PlugFlow_LX_nom.waterPortOut) ;
    connect(fluid_Volume.waterPort_in[2], waterPortOut) ;
  end if;
  connect(fixedHeatFlow.port, fluid_Volume.heatPort) 
  ;
end SinglePipe_L2;

within TransiEnt.Components.Heat.VolumesValvesFittings.Pipes.Base;
model dp_residencetime "Calculates the residence time as well as the pressure loss and delays enthalpy changes according to it"




  import      Modelica.Units.SI;
  outer TransiEnt.SimCenter simCenter;
  outer TransiEnt.Components.Heat.VolumesValvesFittings.Pipes.Base.pipe_parameters pipe_parameter;




  parameter Boolean calc_initial_dstrb = true "Activates the calculation of a initial temperature distribution inside the pipes"
                                                                                                                                ;
  final parameter SI.Pressure p_start = pipe_parameter.p_start "Pressure at start of simulation";
  final parameter SI.Temperature T_start = pipe_parameter.T_start "Temperature at start of simulation";
  final parameter SI.Temperature T_start_out = pipe_parameter.T_start_out;
  final parameter SI.MassFlowRate m_flow_start= 0.005 "Start Massflow";
  final parameter SI.MassFlowRate m_flow_small_local=0.05*Modelica.Constants.pi/4*diameter_i*diameter_i*rho*v_nom "For linearization of pressure drop at mass flow below 5% of nominal velocity";
  final parameter SI.Length diameter_i = pipe_parameter.diameter_i "Inner Diameter of the Pipe";
  final parameter SI.Height z_in = pipe_parameter.z_in "Inlet Height of the pipe";
  final parameter SI.Height z_out = pipe_parameter.z_out "Outlet Height of the pipe";
  final parameter SI.Height dz = z_in - z_out "Height difference between inlet and outlet";
  final parameter SI.Length length = pipe_parameter.length "Length of the pipe";
  final parameter SI.Length K = pipe_parameter.K "average height of surface asperities";
  final parameter SI.Velocity v_nom= simCenter.v_nom "Design Velocity of the pipe. Typically smaller than 2 m/s";

  final parameter SI.SpecificEnthalpy h_start = pipe_parameter.h_start;
  final parameter SI.SpecificEnthalpy h_start_out = pipe_parameter.h_start_out;
  final parameter SI.SpecificHeatCapacity cp_w = pipe_parameter.cp_w;
  final parameter SI.Density rho =  pipe_parameter.rho;
  final parameter SI.DynamicViscosity dyn_vis =  pipe_parameter.dyn_vis;
  final SI.SpecificEnthalpy h_in(start=h_start) = waterPortIn.h_outflow "Inlet enthalpy";
  final SI.SpecificEnthalpy h_out(start=h_start_out) = waterPortOut.h_outflow "Outlet enthalpy";




  SI.Pressure dp(start= 0.005) "Pressure difference between inlet and outlet by friction";
  SI.Pressure dp_h(start = 0) "Pressure difference between inlet and outlet due to geostatic height difference";
  SI.PressureDifference dp_small;
  Real time_flow;
  Real time_reversed;
  SI.Velocity v_water "Velocity of the fluid";
  Real x "Coordinate for spatialDistribution";




  TransiEnt.Basics.Interfaces.Thermal.FluidPortIn waterPortIn(Medium=simCenter.fluid1) "Inlet port"
    ;
  TransiEnt.Basics.Interfaces.Thermal.FluidPortOut waterPortOut(Medium=simCenter.fluid1) "Outlet port"
    ;
  Modelica.Fluid.Dissipation.PressureLoss.StraightPipe.dp_overall_IN_con inCon(
    d_hyd=diameter_i,
    L=length,
    roughness=Modelica.Fluid.Dissipation.Utilities.Types.Roughness.Considered,
    K=K)
    ;
  Modelica.Fluid.Dissipation.PressureLoss.StraightPipe.dp_overall_IN_var inVar(
      rho=rho, eta=dyn_vis)
               ;
  Modelica.Blocks.Interfaces.RealOutput residence_time_nom
    ;
  Modelica.Blocks.Interfaces.RealOutput residence_time_reversed
    ;
initial equation
  x = 0;
equation





  v_water = waterPortIn.m_flow/(rho*(1/4)*Modelica.Constants.pi*diameter_i^2);
  der(x) = v_water;
  (time_reversed,time_flow) = spatialDistribution(
    time,
    time,
    x/length,
    noEvent(v_water >= 0),
    {1/v_nom,1.0},
    {if calc_initial_dstrb then -((Modelica.Constants.pi*(1/4))*diameter_i^2*rho*cp_w) else 0,if calc_initial_dstrb then -((Modelica.Constants.pi*(1/4))*diameter_i^2*rho*cp_w) else 0});

  residence_time_nom = min(36000, time - time_flow);
  residence_time_reversed = min(36000, time - time_reversed);

  (waterPortIn.h_outflow,waterPortOut.h_outflow) = spatialDistribution(
    inStream(waterPortIn.h_outflow),
    inStream(waterPortOut.h_outflow),
    x/length,
    noEvent(v_water >= 0),
    {1/v_nom,1.0},
    {h_start_out,h_start_out});

  waterPortIn.m_flow + waterPortOut.m_flow = 0;
  waterPortIn.xi_outflow = inStream(waterPortOut.xi_outflow);
  waterPortOut.xi_outflow = inStream(waterPortIn.xi_outflow);

  dp_small = Modelica.Fluid.Dissipation.PressureLoss.StraightPipe.dp_overall_DP(
    inCon,
    inVar,
    m_flow_small_local);
  if noEvent(abs(waterPortIn.m_flow) < m_flow_small_local) then
    dp = dp_small/m_flow_small_local*waterPortIn.m_flow;
  else
    dp = Modelica.Fluid.Dissipation.PressureLoss.StraightPipe.dp_overall_DP(
      inCon,
      inVar,
      waterPortIn.m_flow);
  end if;
  if dz == 0 then
    dp_h = 0;
  else
    dp_h = rho*dz*Modelica.Constants.g_n;
  end if;
  waterPortOut.p = waterPortIn.p - (dp+dp_h)
  ;
end dp_residencetime;

within TransiEnt.Components.Heat.VolumesValvesFittings.Pipes.Base;
model Fluid_Volume "A very simple control volume for liquid"








  extends ClaRa.Basics.Icons.Volume;
  import Modelica.Constants.eps;
  import ClaRa;
  import      Modelica.Units.SI;
  outer TransiEnt.SimCenter simCenter;




  inner parameter TILMedia.VLEFluidTypes.BaseVLEFluid   medium=simCenter.fluid1 "Medium in the component"
                                     ;
  inner parameter Boolean useHomotopy=simCenter.useHomotopy "True, if homotopy method is used during initialisation"
                                                                    ;
  parameter SI.Pressure p_nom=1e5 "Nominal pressure"                    ;
  parameter SI.SpecificEnthalpy h_nom=1e5 "Nominal specific enthalpy" ;
  parameter Boolean Use_steady_state_mass_balance= true "Steady state mass balance"
    ;
  parameter SI.SpecificEnthalpy h_start= 1e5 "Start value of sytsem specific enthalpy"
                                                    ;
  parameter SI.Pressure p_start= 1e5 "Start value of sytsem pressure"
                                          ;
  final parameter SI.Volume V_start(min=0.00001) = V_const "Start Volume";
  parameter Integer nPorts = 2 "Number of fluid ports";
protected
  parameter SI.Density d_nom= TILMedia.VLEFluidFunctions.density_phxi(medium, p_nom, h_nom) "Nominal density";
  parameter SI.Density d_start= TILMedia.VLEFluidFunctions.density_phxi(medium, p_start, h_start) "Start density";




 SI.SpecificEnthalpy h_ports[nPorts] "Specific enthalpy vector inflowing";
public
  SI.Volume V(start= V_start) "Volume";
  SI.Mass m(min = 0.000001,start=V_start*d_start) "Total system mass";
  SI.SpecificEnthalpy h(start=h_start, stateSelect=StateSelect.prefer);
  SI.Pressure             p(start=p_start, stateSelect=StateSelect.prefer) "System pressure";
  SI.Temperature  T "System temperature";
  SI.Temperature T_ports[nPorts] "Inlet Temperature";
  SI.Density d = bulk.d;
  Real drhodt;
  SI.HeatFlowRate Q_flow "Heat Flow Rate";
  SI.EnthalpyFlowRate H_flow[nPorts] "Enthalpy flow rate passing from inlet to volume";
  parameter SI.Volume V_const = 2 "Volume";
  final parameter SI.Mass m_const(min = 0.000001) = V_start*d_start "Total system mass";




public
  TransiEnt.Basics.Interfaces.Thermal.FluidPortIn[nPorts] waterPort_in(each Medium=medium) "Fluid port" ;
  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a heatPort ;




public
  TILMedia.VLEFluid_ph[nPorts] fluidPorts(
    each vleFluidType=medium,
    each computeTransportProperties=false,
    each computeVLEAdditionalProperties=false,
    each computeVLETransportProperties=false,
    each deactivateTwoPhaseRegion=true,
    final h=h_ports,
    final p=waterPort_in.p) ;
protected
  inner TILMedia.VLEFluid_ph  bulk(vleFluidType =    medium, p=p, h=h,
    computeVLEAdditionalProperties=false,
    computeVLETransportProperties=false,
    deactivateTwoPhaseRegion=true,
    computeTransportProperties=false)
    ;




equation
  assert(nPorts>0, "It is not allowed to have less than 1 fluid port");



    if Use_steady_state_mass_balance then
     m= m_const;
     V = m/d;
    sum(waterPort_in.m_flow) = 0 "Mass Balance";

   drhodt = 0;
    else
    V= V_const;
      m= if useHomotopy then V*homotopy(bulk.d,d_nom) else V*bulk.d;
   drhodt*V=sum(waterPort_in.m_flow)
                               "Mass balance";
   drhodt=der(p)*bulk.drhodp_hxi
                             + der(h)*bulk.drhodh_pxi;
    end if;                                                
   for i in 1:nPorts loop
   H_flow[i] =waterPort_in[i].m_flow*h_ports[i];
   end for;
 der(h) = (sum(H_flow) + Q_flow)/m "Energy balance";
 for i in 1:nPorts loop
   h_ports[i]=if useHomotopy then homotopy(actualStream(waterPort_in[i].h_outflow), inStream(waterPort_in[i].h_outflow)) else actualStream(waterPort_in[i].h_outflow);
  end for;



  for i in 1:nPorts loop
    waterPort_in[i].h_outflow = h;
  end for;
  for i in 1:nPorts loop
    waterPort_in[i].p = p;
  end for;
   T = bulk.T "Temperature in Volume";
  for i in 1:nPorts loop
   T_ports[i] = fluidPorts[i].T "Temperature at Inlet";
   end for;
   heatPort.T = bulk.T;
   Q_flow = heatPort.Q_flow "Heat Flow Rate";
    ;
end Fluid_Volume;

