model ConstantInertia "1D-rotational component with inertia"




  extends TransiEnt.Components.Mechanical.Base.PartialMechanicalConnection;




  SI.AngularAcceleration alpha(start=0) "Absolute angular acceleration of component (= der(omega))"
    ;
  SI.Power P_rot=omega*alpha*J "Power from changes in rotational energy";




  outer TransiEnt.ModelStatistics modelStatistics;
equation




  alpha = der(omega);
  J*alpha = mpp_a.tau + mpp_b.tau;
  E_kin=J*omega^2/2
  ;
end ConstantInertia;

within TransiEnt.Components.Mechanical;
model TwoStateIdealClutch "1D-rotational clutch"




  outer TransiEnt.ModelStatistics modelStatistics;




  TransiEnt.Basics.Interfaces.General.MechanicalPowerPort mpp_a "Left flange of shaft" ;
  TransiEnt.Basics.Interfaces.General.MechanicalPowerPort mpp_b "Right flange of shaft" ;
  Modelica.Blocks.Interfaces.BooleanInput isRunning "Virtual disconnection (only for statistics component)" ;
equation




  0 = mpp_a.tau + mpp_b.tau;
  if noEvent(isRunning) then
    mpp_a.phi = mpp_b.phi;
  else
    mpp_a.tau = 0;
  end if
  ;
end TwoStateIdealClutch;

within TransiEnt.Components.Mechanical;
model TwoStateInertiaWithIdealClutch "1D-rotational component with inertia. Sends zero inertia to statistics if shut down signal is true"




  extends TransiEnt.Components.Mechanical.Base.PartialMechanicalConnection;




  SI.AngularAcceleration alpha(start=0) "Absolute angular acceleration of component (= der(omega))"
    ;
  SI.Power P_rot "Power from changes in rotational energy";




  outer TransiEnt.ModelStatistics modelStatistics;




   Modelica.Blocks.Interfaces.BooleanInput isRunning "Virtual disconnection (only for statistics component)"
                                                            ;
equation




  alpha = der(omega);
  if noEvent(isRunning) then
    P_rot =omega*alpha*J;
    mpp_b.tau = J*alpha - mpp_a.tau;
    E_kin=J*omega^2/2;
  else
    mpp_b.tau=0;
    P_rot=0;
    E_kin=0;
  end if
  ;
end TwoStateInertiaWithIdealClutch;

