  Basics.Media.RealGasGCV_xi realGasGCV_InToOut(realGasType=medium, xi_in=inStream(gasPortIn.xi_outflow))  ;
  Basics.Media.RealGasGCV_xi realGasGCV_OutToIn(realGasType=medium, xi_in=gasPortIn.xi_outflow)  ;




