  TransiEnt.Basics.Interfaces.General.MassFlowRateOut m_flow_aux "Auxiliary mass flow rate" ;












equation
  assert(xiNumber<=medium.nc, "xiNumber is out of range!");
  m_flow = gasPortIn.m_flow;
  if xiNumber==0 then
