within TransiEnt.Components.Statistics.Functions;
function repCostResVal "Calculates the cost of replacements and the residual value based on investment cost, interest rate, price change rate, observation period and life time; price changes are neglected"
  extends TransiEnt.Basics.Icons.Function;
  input Real C_inv;
  input Real interestRate;
  input Real priceChangeRate;
  input Real observationPeriod;
  input Real lifeTime;
  output Real C_rep=0 "Replacement cost";
  output Real C_res=0 "Residual value";
protected
  Integer numberOfReplacements "How many times has the component to be replaced?";
algorithm
  if noEvent(lifeTime<Modelica.Constants.eps) then
    C_rep:=0;
    C_res:=0;
  else
    C_rep:=0;
    numberOfReplacements:=integer(ceil(observationPeriod/lifeTime)) - 1;
    for i in 1:numberOfReplacements loop
      C_rep:=C_rep+C_inv*(1+priceChangeRate)^(i*lifeTime)/(1+interestRate)^(i*lifeTime);
    end for;
    C_res:=C_inv*(1+priceChangeRate)^(numberOfReplacements*lifeTime)*((numberOfReplacements+1)*lifeTime-observationPeriod)/lifeTime*1/(1+interestRate)^observationPeriod;
  end if
  ;
end repCostResVal;

within TransiEnt.Components.Statistics.Functions.CO2Allocation;
function AllocationMethod_CreditsElectrical "credits electrical to thermal generation"
  extends TransiEnt.Basics.Icons.Function;




  extends Basics.BasicAllocationMethod;
  parameter Real m_flow_spec_el_ref = 600/3600;
algorithm




  m_flow_spec_el := m_flow_spec_el_ref * eta_el;
  m_flow_spec_th := m_flow_spec - m_flow_spec_el;
  alloc_m_flow_spec :={m_flow_spec_el, m_flow_spec_th}
  ;
end AllocationMethod_CreditsElectrical;

within TransiEnt.Components.Statistics.Functions.CO2Allocation;
function AllocationMethod_CreditsThermal "credits thermal to electrical generation"
  extends TransiEnt.Basics.Icons.Function;




  extends Basics.BasicAllocationMethod;
  parameter Real m_flow_spec_th_ref = 200/3600;
algorithm




  m_flow_spec_th := m_flow_spec_th_ref * eta_th;
  m_flow_spec_el := m_flow_spec - m_flow_spec_th;
  alloc_m_flow_spec :={m_flow_spec_el, m_flow_spec_th}
  ;
end AllocationMethod_CreditsThermal;

within TransiEnt.Components.Statistics.Functions.CO2Allocation;
function AllocationMethod_Efficiencies "efficiencies method"
  extends TransiEnt.Basics.Icons.Function;




  extends Basics.BasicAllocationMethod;
algorithm




  m_flow_spec_el := m_flow_spec * eta_th / (eta_th + eta_el);
  m_flow_spec_th := m_flow_spec * eta_el / (eta_th + eta_el);
alloc_m_flow_spec :={m_flow_spec_el,m_flow_spec_th}
  ;
end AllocationMethod_Efficiencies;

within TransiEnt.Components.Statistics.Functions.CO2Allocation;
function AllocationMethod_Finnish "finnish method"
  extends TransiEnt.Basics.Icons.Function;




  extends Basics.BasicAllocationMethod;




  parameter Real eta_el_ref = 0.4 "reference electrical efficiency";
  parameter Real eta_th_ref = 0.8 "reference thermal efficiency (AG Energiebilanzen)";

  parameter Real PEE= 1 - 1 / ( (eta_th / eta_th_ref) + (eta_el / eta_el_ref));
algorithm




  m_flow_spec_el := m_flow_spec * ((1-PEE) * eta_el / eta_el_ref);
  m_flow_spec_th := m_flow_spec * ((1-PEE) * eta_th / eta_th_ref);
alloc_m_flow_spec :={m_flow_spec_el,m_flow_spec_th}
  ;
end AllocationMethod_Finnish;

