model FirstOrderThreeStateTurbine "Generic model of a turbine with three states (halt / startup / running), pyhsical constraints (Pmin,Pmax,Pgradmax) and first order dynamic"




  extends Base.PartialTurbine;





  parameter SI.Power P_n=2e9 "Nominal power" ;
  parameter Real P_min_star=0.2 "Dimensionless minimum power (=20% of nominal power)" ;
  parameter Real P_max_star=1 "Dimensionless maximum power (=Nominal power)" ;
  parameter Real P_grad_max_star=0.12/60 "Dimensionless maximum power gradient per second (12% of P_nom per minute)" ;
  parameter Real P_grad_max_star_primCntrl=0.02/30 "Dimensionless maximum power gradient per second for primary control - default 2% in 30 sec" ;
  parameter SI.Time T_plant=10 "Turbine first order dynamic" ;
  parameter SI.Time t_startup=0 "Startup time (no output during startup)" ;
  parameter SI.Time t_min_operating=0 "Minimum operation time" ;
  parameter SI.Time MinimumDownTime=0 "Minimum time the plant needs to be shut down before starting again" ;
  parameter Base.GradientLimitingChoices gradLimChoice=Base.GradientLimitingChoices.GradLimInFirstOrder "options of gradient limitation" ;
  parameter Boolean useFirstOrderGradLimt=(gradLimChoice > Base.GradientLimitingChoices.GradLimInCntrl) "Activate gradient limitation in first order" ;
  parameter Boolean useSlewRateLimiter=(gradLimChoice == Base.GradientLimitingChoices.GradLimInCntrl) "choose if slewRateLimiter is activated" ;
  parameter Boolean smoothShutDown=true "shut down process will be smoothed - power gradient will be limit by 'P_grad_operating'" ;
  parameter Real Td=1e-3 "The higher Nd, the closer y follows u" ;
  parameter Boolean useThresh=false "Use threshould for suppression of numerical noise" ;
  parameter Real thres=1e-7 "If abs(u-y)< thres, y becomes a simple pass through of u. Increasing thres can improve simulation speed. However to large values can make the simulation unstable. 
     A good starting point is the choice thres = tolerance/1000." ;
  parameter Boolean useHomotopyVarSlewRateLim=simCenter.useHomotopy "true if homotopy shall be used in variableSlewRateLimiter" ;
  parameter Real P_turb_init=0 "Initial or guess value of turbine power (in p.u.)";
  parameter Real thres_hyst=1e-10 "Threshold for hysteresis for switch from halt to startup (chattering might occur, hysteresis might help avoiding this)" ;
  parameter SI.Time t_eps=10 "Threshold time for transitions" ;
  outer SimCenter simCenter;




  Modelica.Blocks.Interfaces.BooleanOutput isGeneratorRunning ;
  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerIn P_spinning_set "Setpoint for spinning reserve power" ;




  Modelica.Blocks.Math.Gain normalize(k=1/P_n) ;
  Basics.Blocks.SwitchNoEvent switchOnOff ;
  Modelica.Blocks.Sources.Constant shutdown(k=0) ;
  Modelica.Blocks.Math.Gain normalizePbal(k=1/P_n) ;
  Modelica.Blocks.Math.MultiSum P_total(nu=2, k={1,1}) ;
  Modelica.Blocks.Math.Gain deNormalize(k=P_n) ;
  Boundaries.Mechanical.Power MechanicalBoundary ;
  Modelica.Blocks.Nonlinear.Limiter P_max_star_limiter_total(uMax=0, uMin=-P_max_star) "Upper limit is nominal power" ;




  Real P_set_star=normalize.y;
  Real P_is_star=deNormalize.u;
  replaceable OperatingStates.ThreeStateDynamic operationStatus(
    useSlewRateLimiter=useSlewRateLimiter,
    useHomotopyVarSlewRateLim=useHomotopyVarSlewRateLim,
    t_startup=t_startup,
    P_star_init=P_turb_init/P_n,
    t_min_operating=t_min_operating,
    P_min_operating=P_min_star,
    P_max_operating=P_max_star,
    P_grad_operating=P_grad_max_star,
    smoothShutDown=smoothShutDown,
    thres_hyst=thres_hyst,
    thres=thres,
    useThresh=useThresh,
    P_grad_inf=P_grad_max_star,
    Td=Td,
    t_eps=t_eps,
    MinimumDownTime=MinimumDownTime) constrainedby TransiEnt.Components.Turbogroups.OperatingStates.PartialStateDynamic "Operating State Model" ;
  Basics.Blocks.FirstOrderWithGradientLim plantDynamic(
    Tau=T_plant,
    initOption=2,
    y_start=-P_turb_init/P_n,
    evaluate_y_start=true,
    enable_gradientLimiter=useFirstOrderGradLimt) ;
  Modelica.Blocks.Sources.BooleanExpression isOperating(y=operationStatus.isOperating) ;
  Basics.Blocks.FirstOrderWithGradientLim plantPrimaryCtrlDynamic(
    Tau=7,
    initOption=3,                                                 y_start=0, enable_gradientLimiter=useFirstOrderGradLimt) ;
  Modelica.Blocks.Sources.RealExpression primarCntrlMaxGrad(y=P_grad_max_star_primCntrl) if useFirstOrderGradLimt ;
  Modelica.Blocks.Sources.RealExpression primarCntrlMinGrad(y=-P_grad_max_star_primCntrl) if useFirstOrderGradLimt ;
equation




  connect(MechanicalBoundary.mpp, mpp) ;
  connect(P_target, normalize.u) ;
  connect(deNormalize.y, MechanicalBoundary.P_mech_set) ;
  connect(P_spinning_set, normalizePbal.u) ;
  connect(P_max_star_limiter_total.u, switchOnOff.y) ;
  connect(normalize.y, operationStatus.P_set_star) ;
  connect(P_max_star_limiter_total.y, plantDynamic.u) ;
  connect(shutdown.y, switchOnOff.u3) ;
  connect(operationStatus.P_set_star_lim, switchOnOff.u1) ;
  connect(plantDynamic.y, P_total.u[1]) ;
  connect(P_total.y, deNormalize.u) ;
  connect(plantPrimaryCtrlDynamic.y, P_total.u[2]) ;
  connect(plantPrimaryCtrlDynamic.u, normalizePbal.y) ;
  connect(switchOnOff.u2, isOperating.y) ;
  connect(isGeneratorRunning, isOperating.y) ;
  connect(operationStatus.P_grad_star_max_out, plantDynamic.maxGrad) ;
  connect(operationStatus.P_grad_star_min_out, plantDynamic.minGrad) ;
  connect(primarCntrlMinGrad.y, plantPrimaryCtrlDynamic.minGrad) ;
  connect(primarCntrlMaxGrad.y, plantPrimaryCtrlDynamic.maxGrad) ;
  connect(plantDynamic.y, operationStatus.P_actual_star) 
  ;
end FirstOrderThreeStateTurbine;

