partial model PartialStateDynamic "State graph model with state-depentend maximum values and gradients"




  extends TransiEnt.Basics.Icons.Block;




  outer SimCenter simCenter;




  parameter SI.Time t_eps = 10 "Threshold time for transitions";
  parameter Real P_star_init = 0 "Power at startup (p.u.)";
  parameter SI.Frequency P_grad_inf=1 "Numerical value for unlimited gradients during shutdown";
  parameter SI.Time T_thresh=simCenter.thres "Time constant of numerical element between saturation and gradient limiter";
  parameter Real Td=simCenter.Td "Time constant of derivative approximation in slew rate limiter";
  parameter Boolean useThresh=simCenter.useThresh "Use threshould for suppression of numerical noise";
  parameter Real thres=simCenter.thres "If abs(u-y)< thres, y becomes a simple pass through of u. Increasing thres can improve simulation speed. However to large values can make the simulation unstable. 
     A good starting point is the choice thres = tolerance/1000.";
  parameter SI.Frequency P_grad_operating = 0.02/60 "Maximum Gradient during operation";
  parameter Boolean useSlewRateLimiter=true "choose if slewRateLimiter is activated";
  parameter Boolean useHomotopyVarSlewRateLim=simCenter.useHomotopy "true if homotopy shall be used in variableSlewRateLimiter" ;




  Modelica.Blocks.Interfaces.RealOutput P_grad_star_max_out "Relative maximum gradient in operation"
                                                                                   ;
  Modelica.Blocks.Interfaces.RealOutput P_grad_star_min_out "Relative minium gradient in operation"
                                                                                   ;




    inner Modelica.StateGraph.StateGraphRoot
                         stateGraphRoot
      ;
  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerIn P_set_star "Connector of setpoint input signal" ;
  Modelica.Blocks.Nonlinear.VariableLimiter variableLimiter ;
  Basics.Blocks.VariableSlewRateLimiter variableSlewRateLimiter(
    thres=thres,
    useConstantLimits=false,
    useThresh=false,
    y_start=-P_star_init,
    Td=Td,
    useHomotopy=useHomotopyVarSlewRateLim) if useSlewRateLimiter ;
  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerOut P_set_star_lim "Limited output signal" ;
  Modelica.Blocks.Sources.RealExpression P_min_of_state(y=P_min) ;
  Modelica.Blocks.Sources.RealExpression P_max_of_state(y=P_max) ;
  Modelica.Blocks.Sources.RealExpression P_grad_min_of_state(y=P_grad_min)                       ;
  Modelica.Blocks.Sources.RealExpression P_grad_max_of_state(y=P_grad_max)                       ;
  Modelica.Blocks.Logical.Switch deactivatePower
                                         if not useSlewRateLimiter ;




  Boolean isOperating;
  Basics.Interfaces.Electrical.ElectricPowerIn P_actual_star "Connector of actual power" ;
  Modelica.Blocks.Sources.RealExpression zeroPower(y=0) if not useSlewRateLimiter ;
  Modelica.Blocks.Sources.BooleanExpression deactivationSignal(y=false) if not useSlewRateLimiter ;
protected
  Real P_min,P_max,P_grad_min,P_grad_max;
equation




  connect(P_max_of_state.y, variableLimiter.limit1) ;
  connect(P_min_of_state.y, variableLimiter.limit2) ;
  connect(variableLimiter.u, P_set_star) ;
  if useSlewRateLimiter==false then
  else
      connect(variableSlewRateLimiter.y, P_set_star_lim) ;
      connect(variableLimiter.y, variableSlewRateLimiter.u) ;
      connect(P_grad_min_of_state.y, variableSlewRateLimiter.minGrad) ;
      connect(P_grad_max_of_state.y, variableSlewRateLimiter.maxGrad) ;
  end if;
  connect(P_grad_min_of_state.y, P_grad_star_min_out) ;
  connect(P_grad_max_of_state.y, P_grad_star_max_out) ;
  connect(variableLimiter.y, deactivatePower.u3) ;
  connect(deactivatePower.y, P_set_star_lim) ;
  connect(zeroPower.y, deactivatePower.u1) ;
  connect(deactivationSignal.y, deactivatePower.u2) 
  ;
end PartialStateDynamic;

within TransiEnt.Components.Turbogroups.OperatingStates;
model PumpstorageStates "Limits input signal by value and gradient depending on active state out of three possible operating states (halt, startup, operating)"
  extends TransiEnt.Components.Turbogroups.OperatingStates.PartialStateDynamic;




  parameter TransiEnt.Basics.Types.OnOffPumpstorageStatus init_state=TransiEnt.Basics.Types.off "State of Pumpstorage at initialization" ;
  parameter SI.Time t_startup = 120 "Startup time";
  parameter Real P_min_operating_pump = 0.1 "Minimum power pump operation (p.u.)";
  parameter Real P_min_operating_turb = 0.1 "Minimum power turbine operation (p.u.)";
  parameter Real P_max_operating_pump = 1 "Maximum power pump operation (p.u.)";
  parameter Real P_max_operating_turb = 1 "Maximum power turbine operation (p.u.)";
  parameter SI.Frequency P_grad_startup = 1/max(t_startup,1) "Maximum Gradient during startup";




  Modelica.StateGraph.StepWithSignal
                                  halt(nOut=2, nIn=5)
                                              ;
  Modelica.StateGraph.Transition startupPumpSuccess(
    condition=true,
    enableTimer=true,
    waitTime=t_startup) ;
  Modelica.StateGraph.StepWithSignal operatingPump(       nOut=1, nIn=2)
                                                                  ;
  Modelica.StateGraph.StepWithSignal startupPump(nOut=2, nIn=1) ;
  Modelica.StateGraph.Transition thresholdPump(
    waitTime=t_eps,
    condition=P_set_star >= P_min_operating_pump + thres,
    enableTimer=true)                             ;
  Modelica.StateGraph.Transition noThreshold(
    enableTimer=true,
    condition=P_set_star < P_min_operating_pump - thres,
    waitTime=t_eps)                                ;
  Modelica.StateGraph.Transition noThreshold2(
    condition=P_set_star < P_min_operating_pump - thres,
    enableTimer=true,
    waitTime=t_eps) ;
  Modelica.StateGraph.Transition thresholdTurb(
    waitTime=t_eps,
    condition=P_set_star <= -P_min_operating_turb - thres,
    enableTimer=true)                              ;
  Modelica.StateGraph.StepWithSignal startupTurb(nOut=2, nIn=1) ;
  Modelica.StateGraph.Transition noThreshold1(
    waitTime=t_eps,
    condition=P_set_star > -P_min_operating_turb + thres,
    enableTimer=true)                              ;
  Modelica.StateGraph.Transition startupTurbSuccess(
    condition=true,
    enableTimer=true,
    waitTime=t_startup) ;
  Modelica.StateGraph.StepWithSignal operatingTurb(       nOut=1, nIn=2)
                                                                  ;
  Modelica.StateGraph.Transition noThreshold3(
    waitTime=t_eps,
    condition=P_set_star > -P_min_operating_turb + thres,
    enableTimer=true)
                    ;
  Modelica.StateGraph.InitialStep init(nIn=0, nOut=3) ;
  Modelica.StateGraph.Transition initHalt(condition=init_state == TransiEnt.Basics.Types.off) ;
  Modelica.StateGraph.Transition initOperatingPump(condition=init_state == TransiEnt.Basics.Types.on1) ;
  Modelica.StateGraph.Transition initOperatingTurb(condition=init_state == TransiEnt.Basics.Types.on2) ;
equation




  isOperating = not halt.active;
  P_min = if operatingPump.active then P_min_operating_pump elseif operatingTurb.active then -P_max_operating_turb else 0;
  P_max = if operatingPump.active then P_max_operating_pump elseif operatingTurb.active then -P_min_operating_turb else 0;
  P_grad_min = if halt.active then -P_grad_inf elseif (startupPump.active or startupTurb.active) then -P_grad_startup else -P_grad_operating;
  P_grad_max = if halt.active then P_grad_inf elseif (startupPump.active or startupTurb.active) then P_grad_startup else P_grad_operating;




  connect(startupPumpSuccess.outPort, operatingPump.inPort[1]) ;
  connect(thresholdPump.inPort, halt.outPort[1]) ;
  connect(thresholdPump.outPort, startupPump.inPort[1]) ;
  connect(startupPump.outPort[1], startupPumpSuccess.inPort) ;
  connect(startupPump.outPort[2], noThreshold.inPort) ;
  connect(noThreshold.outPort,halt. inPort[2]) ;
  connect(noThreshold2.outPort, halt.inPort[3]) ;
  connect(P_max_of_state.y, variableLimiter.limit1) ;
  connect(P_min_of_state.y, variableLimiter.limit2) ;
  connect(P_grad_max_of_state.y, variableSlewRateLimiter.maxGrad) ;
  connect(P_grad_min_of_state.y, variableSlewRateLimiter.minGrad) ;
  connect(variableLimiter.u, P_set_star) ;
  connect(variableSlewRateLimiter.y, P_set_star_lim) ;
  connect(thresholdTurb.outPort, startupTurb.inPort[1]) ;
  connect(startupTurb.outPort[1], noThreshold1.inPort) ;
  connect(noThreshold1.outPort, halt.inPort[1]) ;
  connect(startupTurbSuccess.outPort, operatingTurb.inPort[1]) ;
  connect(noThreshold3.outPort, halt.inPort[4]) ;
  connect(startupTurb.outPort[2], startupTurbSuccess.inPort) ;
  connect(operatingPump.outPort[1], noThreshold2.inPort) ;
  connect(operatingTurb.outPort[1], noThreshold3.inPort) ;
  connect(halt.outPort[2], thresholdTurb.inPort) ;
  connect(init.outPort[1], initHalt.inPort);
  connect(init.outPort[2], initOperatingPump.inPort);
  connect(init.outPort[3], initOperatingTurb.inPort);
  connect(initHalt.outPort, halt.inPort[5]);
  connect(initOperatingPump.outPort, operatingPump.inPort[2]);
  connect(initOperatingTurb.outPort, operatingTurb.inPort[2])
  ;
end PumpstorageStates;

within TransiEnt.Components.Turbogroups.OperatingStates;
model ThreeStateDynamic "Three state dynamic model - operating at init"




  extends TransiEnt.Components.Turbogroups.OperatingStates.PartialStateDynamic(deactivationSignal(y=turndown.active));
   import TransiEnt.Basics.Types;




  parameter SI.Time t_startup = 3600 "Startup time";
  parameter SI.Time t_min_operating = 0 "Minimum operation time";
  parameter Real P_min_operating = 0.3 "Minimum power  (p.u.)";
  parameter Real P_max_operating = 1 "Maximum power (p.u.)";
  parameter Boolean smoothShutDown=true "shut down process will be smoothed - power gradient will be limit by 'P_grad_operating'";
  parameter SI.Frequency P_grad_startup = P_grad_inf "Maximum Gradient during startup";
  parameter TransiEnt.Basics.Types.ThermalPlantStatus init_state=if P_star_init < P_min_operating then 0 else 1 "State of plant at initialization" ;
  parameter Real thres_hyst=1e-10 "Threshold for hysteresis for switch from halt to startup (chattering might occur, hysteresis might help avoiding this)";
  parameter SI.Time MinimumDownTime=0 "Minimum time the plant needs to be shut down before starting again";




  Modelica.StateGraph.StepWithSignal
                                  halt(nIn=4, nOut=1)
                                              ;
  Modelica.StateGraph.StepWithSignal operating_minimum(nOut=2, nIn=3) ;




  Modelica.StateGraph.Transition startupSuccess(
    condition=true,
    enableTimer=true,
    waitTime=t_startup) ;
  Modelica.StateGraph.StepWithSignal
                           startup(       nOut=2, nIn=2)
                                   ;
  Modelica.StateGraph.Transition threshold(
    waitTime=t_eps,
    enableTimer=true,
    condition=hysteresis.y)                                         ;
  Modelica.StateGraph.Transition noThreshold(
    waitTime=t_eps,
    enableTimer=true,
    condition=P_set_star > -P_min_operating + 2*thres)
                                                   ;
  Modelica.StateGraph.Transition noThreshold2(
    waitTime=t_eps,
    enableTimer=true,
    condition=P_set_star > -P_min_operating + 2*thres)
                    ;
 Modelica.StateGraph.Transition initOff(
    waitTime=0,
    condition=init_state == Types.off,
    enableTimer=false);
  Modelica.StateGraph.Transition initOn(
    waitTime=0,
    condition=init_state == Types.on1,
    enableTimer=false);
  Modelica.StateGraph.Transition initStartup(
    waitTime=t_startup,
    enableTimer=true,
    condition=init_state == Types.on2);
public
  Modelica.StateGraph.InitialStep init(nIn=0, nOut=3) ;
  Modelica.Blocks.Logical.Hysteresis hysteresis(uLow=max(P_min_operating - thres - thres_hyst, 1e-11), uHigh=max(P_min_operating - thres, 1e-10))
                                                                                                     ;
  Modelica.Blocks.Math.Gain gain(k=-1) ;
  Modelica.StateGraph.StepWithSignal DownTime(nIn=4, nOut=1)
                                                     ;
  Modelica.StateGraph.Transition minimumDownTimeBlock(enableTimer=true, waitTime=MinimumDownTime)
                                                                                       ;
  Modelica.StateGraph.Transition startupSuccess1(
    condition=true,
    enableTimer=true,
    waitTime=t_min_operating)
                        ;
  Modelica.StateGraph.StepWithSignal operating(nOut=2, nIn=3) ;
  Modelica.StateGraph.StepWithSignal turndown(nOut=1, nIn=1) ;
  Modelica.StateGraph.TransitionWithSignal
                                 turnDownSuccess(enableTimer=true, waitTime=0)
                        ;
  Modelica.Blocks.Sources.BooleanExpression booleanExpression(y=if smoothShutDown then (if useSlewRateLimiter then P_set_star_lim else P_actual_star)  >= -(P_min_operating + 1e-5) else true)
                                                                                                             ;
equation




  isOperating =operating_minimum.active or operating.active or init.active or turndown.active;
  P_min =if isOperating then -P_max_operating else 0;
  P_max =if isOperating then -P_min_operating else 0;
  P_grad_min = if halt.active then -P_grad_inf elseif startup.active then -P_grad_startup else -P_grad_operating;
  P_grad_max = if halt.active then P_grad_inf elseif startup.active then P_grad_startup else P_grad_operating;




  connect(halt.outPort[1], threshold.inPort)
    ;
  connect(startupSuccess.outPort, operating_minimum.inPort[1]) ;
  connect(threshold.outPort,startup. inPort[1]) ;
  connect(startup.outPort[1],startupSuccess. inPort) ;
  connect(startup.outPort[2],noThreshold. inPort) ;


  connect(init.outPort[1], initOff.inPort);
  connect(init.outPort[2], initOn.inPort);
  connect(init.outPort[3], initStartup.inPort);

  connect(halt.inPort[3], initOff.outPort);
  connect(operating_minimum.inPort[2], initOn.outPort);
  connect(startup.inPort[2], initStartup.outPort);
  connect(hysteresis.u, gain.y) ;
  connect(gain.u, P_set_star) ;
  connect(noThreshold.outPort, DownTime.inPort[2]) ;
  connect(halt.inPort[1], minimumDownTimeBlock.outPort) ;
  connect(DownTime.outPort[1], minimumDownTimeBlock.inPort) ;
  connect(operating_minimum.outPort[1], startupSuccess1.inPort) ;
  connect(startupSuccess1.outPort, operating.inPort[1]) ;
  connect(operating.outPort[1], noThreshold2.inPort) ;
  connect(turndown.inPort[1], noThreshold2.outPort) ;
  connect(turnDownSuccess.inPort, turndown.outPort[1]) ;
  connect(turnDownSuccess.outPort, DownTime.inPort[1]) ;
  connect(booleanExpression.y, turnDownSuccess.condition) 
  ;
end ThreeStateDynamic;

