within TransiEnt.Components.Visualization;
model DHG_PressureDiagram "Pressure diagram of district heating grids (pressure as a function of grid length) "
  input ClaRa.Basics.Units.Pressure p_supply[n]=zeros(n) "Pressure values at supply pipes' inputs and outputs in Pa" ;
  input ClaRa.Basics.Units.Pressure p_return[m]=zeros(m) "Pressure values at return pipes' inputs and outputs in Pa" ;
  input Real relative_positions_supply[n] "Supply pipes' relative input and output position in p.u." ;
  input Real relative_positions_return[m] "Supply pipes' relative input and output position in p.u." ;




  parameter Integer n=2 "Numer of inlet/outlet pairs in supply";
  parameter Integer m=4 "Number of inlet/outlet pairs in return";
  parameter Real minY=0 "Choose or guess the minimal value of the y-axis" ;
  parameter Real maxY(min=minY+Modelica.Constants.eps)=1 "Choose or guess the maximal value of the y-axis"
                                                      ;
  parameter String Unit="[-]" "Unit for plot variable" ;
public
  constant ClaRa.Basics.Types.Color colorh={167,25,48} "Line color"         ;
  constant ClaRa.Basics.Types.Color colorc={0,131,169} "Line color"         ;




protected
  Real y_supply[ size(relative_positions_supply, 1)];
  Real y_return[ size(relative_positions_return, 1)];
public
  final Real[size(relative_positions_supply, 1), 2] point_supply=transpose({relative_positions_supply*100,y_supply})  ;
  final Real[size(relative_positions_return, 1), 2] point_return=transpose({relative_positions_return*100,y_return})  ;
equation




  for i in 1:size(y_supply, 1) loop
     y_supply[i] = if p_supply[i] < minY then (1-(maxY -minY)/(maxY - minY))*100 else
           if  p_supply[i] > maxY then    (1-(maxY -maxY)/(maxY - minY))*100 else
               (1-(maxY -p_supply[i])/(maxY - minY))*100;
  end for;
  for i in 1:size(y_return, 1) loop
    y_return[i] = if p_return[i] < minY then     (1-(maxY -minY)/(maxY - minY))*100 else
          if  p_return[i] > maxY then    (1-(maxY -maxY)/(maxY - minY))*100 else
              (1-(maxY -p_return[i])/(maxY - minY))*100;
  end for
;
end DHG_PressureDiagram;

within TransiEnt.Consumer.Electrical;
model AverageLoadConsumer "Constant current for active power and constant impedance for reactive power"




  extends TransiEnt.Basics.Icons.ElectricalConsumer;
  import Modelica.Fluid.Utilities.regPow;




  outer TransiEnt.SimCenter simCenter;
  outer TransiEnt.ModelStatistics modelStatistics;




  parameter Boolean useInputConnectorP=false
    "Gets parameter from input connector" ;
  parameter SI.Power P_el_set_const=0 "Used, if not useInputConnectorP"
    ;
  parameter Boolean useCosPhi=true ;
  parameter SI.ReactivePower Q_el_set=0
    ;
  parameter SI.PowerFactor cosphi_set=1 ;
  parameter Integer behavior=1 ;





  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerIn P_el_set              if useInputConnectorP
    "active power input at nominal frequency" ;
