                         ;
  Modelica.Blocks.Sources.Constant T_ConsumerTarget(k=T_set) ;
  TransiEnt.Basics.Blocks.LimPID CTRL_T_room(
    controllerType=Modelica.Blocks.Types.SimpleController.PI,
    Ni=0.9,
    t_activation=t_ctrl_activationTime,
