  Modelica.Units.SI.ThermalConductance G_eff_room=Q_flow_cons/deltaT_room;
  parameter Real y_inactive=1 "Reference value for actuated variable (used before controller is activated)";
equation




  connect(heatLossConductance.port_a,heatCapacitor. port) ;
  connect(heatLossConductance.port_b,prescribedTemperature. port) ;
  connect(heatCapacitor.port,T_Room. port) ;
  connect(CTRL_T_room.y, Valve.opening_in) ;
  connect(T_Room.T, CTRL_T_room.u_m) ;
  connect(HX_Consumer.heat, T_Room.port) ;
  connect(HX_Consumer.outlet, Valve.inlet) ;
  connect(Valve.eye, eye) ;
  connect(tamb.y1, prescribedTemperature.T) ;
  connect(T_ConsumerTarget.y, to_DegC.Kelvin) ;
  connect(to_DegC.Celsius, CTRL_T_room.u_s) ;
  connect(fluidPortIn, HX_Consumer.inlet) ;
  connect(fluidPortOut, Valve.outlet) 
  ;
end ThermalHeatConsumer;

