model HeatPump "HeatPump with thermal storage"




  extends Base.Systems(
    final DHN=false,
    final el_grid=true,
    final gas_grid=false);
  outer TransiEnt.SimCenter simCenter;
  outer TransiEnt.ModelStatistics modelStatistics;




  parameter Boolean hotwater=true "Does the heat pump provide energy for the hot water? (if false: water is heated electrically)" ;
  parameter Boolean heating=true "Does the heat pump provide energy for space heating? (if false: space heating not accounted for)" ;
  parameter SI.TemperatureDifference Delta_T_internal=5 "Temperature difference between refrigerant and source/sink temperature" ;
  parameter SI.TemperatureDifference Delta_T_db=2 "Deadband of hysteresis control" ;
  parameter SI.HeatFlowRate Q_flow_n=3.5e3 "Nominal heat flow of heat pump at nominal conditions according to EN14511" ;
  parameter Real COP_n=3.7 "Coefficient of performance at nominal conditions according to EN14511" ;
  parameter SI.Power P_el_n=10e3 "Nominal electric power of the backup heater" ;
  parameter SI.Efficiency eta_Heater=0.95 "Efficiency of the backup heater" ;
  parameter SI.Temperature T_s_max=T_set "Maximum storage temperature" ;
  parameter SI.Temperature T_set=65 + 273.25 "Heatpump supply temperature" ;
  parameter SI.Temperature T_s_min=55 + 273.15 "Minimum storage temperature" ;
  parameter SI.Volume V_Storage=0.5 "Volume of the Storage" ;
  parameter SI.Height height=1.3 "Height of heat storage" ;
  parameter SI.Diameter d=sqrt(V_Storage/heatStorage.height*4/Modelica.Constants.pi) "Diameter of heat storage" ;
  parameter Modelica.Units.NonSI.Temperature_degC T_amb=15 "Assumed constant ambient temperature" ;
  parameter SI.SurfaceCoefficientOfHeatTransfer k=0.08 "Coefficient of heat transfer through tank surface" ;
  parameter SI.Temperature T_start=60 + 273.15 "Start value of the storage temperature" ;




  SI.Power P "Consumed or produced electric power";
  SI.Temperature T_source=simCenter.ambientConditions.temperature.value + 273.15 "Temperature of heat source" ;




  TransiEnt.Components.Boundaries.Electrical.ApparentPower.ApparentPower apparentPower(
    useInputConnectorQ=false,
    useInputConnectorP=true,
    useCosPhi=false) ;
  TransiEnt.Producer.Heat.Power2Heat.Heatpump.Heatpump heatPump(
    Delta_T_internal=Delta_T_internal,
    Delta_T_db=Delta_T_db,
    Q_flow_n=Q_flow_n,
    COP_n=COP_n,
    T_source=T_source,
    useFluidPorts=false,
    useHeatPort=false,
    T_set=T_s_max,
    redeclare connector PowerPortModel = TransiEnt.Basics.Interfaces.Electrical.ApparentPowerPort,
    redeclare model PowerBoundaryModel = TransiEnt.Components.Boundaries.Electrical.ApparentPower.ApparentPower,
    Power(useInputConnectorQ=false, useCosPhi=false)) ;
  TransiEnt.Storage.Heat.HotWaterStorage_constProp_L2.HotWaterStorage_constProp_L2 heatStorage(
    useFluidPorts=false,
    T_s_max=T_s_max,
    T_s_min=T_s_min,
    d=d,
    height=height,
    T_amb=T_amb,
    k=k,
    T_start=T_start) ;
  replaceable Producer.Heat.Power2Heat.Heatpump.Controller.ControlHeatpump_heatdriven_BVheatLoad Controller constrainedby TransiEnt.Producer.Heat.Power2Heat.Heatpump.Controller.Base.Controller(P_elHeater=P_el_n, CalculatePHeater=true, Q_flow_n=heatPump.Q_flow_n, Delta_T_db=Delta_T_db) "Control mode of the heat pump" ;
  Modelica.Blocks.Math.Add add1
                               if heating and hotwater ;
  Modelica.Blocks.Math.Add add2 if not hotwater ;
  TransiEnt.Producer.Heat.Power2Heat.ElectricBoiler.ElectricBoiler electricHeater(
    Q_flow_n=P_el_n*eta_Heater,
    eta=eta_Heater,
    useFluidPorts=false,
    usePowerPort=true,
    redeclare TransiEnt.Basics.Interfaces.Electrical.ApparentPowerPort epp,
    redeclare TransiEnt.Components.Boundaries.Electrical.ApparentPower.ApparentPower powerBoundary(useInputConnectorQ=false, cosphi_boundary=0.99) "PowerBoundary for ApparentPowerPort") ;
  Modelica.Blocks.Math.Add add3 ;
  Modelica.Blocks.Sources.RealExpression Tset(y=T_set) ;
  Modelica.Blocks.Sources.RealExpression Tsource(y=heatPump.T_source_internal) ;
equation




  P = epp.P;




  if heating and hotwater then
    connect(add1.y, heatStorage.Q_flow_demand) ;
  elseif heating then
    connect(demand.heatingPowerDemand, heatStorage.Q_flow_demand) ;
  else
    connect(demand.hotWaterPowerDemand, heatStorage.Q_flow_demand) ;
  end if;
  if hotwater then
    connect(demand.electricPowerDemand, apparentPower.P_el_set) ;
  else
    connect(add2.y, apparentPower.P_el_set) ;
  end if;
  connect(apparentPower.epp, epp) ;
  connect(heatStorage.SoC, Controller.SoC) ;
  connect(heatStorage.Q_flow_store, add3.y) ;
  connect(heatPump.Heat_output, add3.u1) ;
  connect(electricHeater.epp, epp) ;
  connect(heatStorage.T_stor_out, Controller.T) ;
  connect(demand.electricPowerDemand, add2.u1) ;
  connect(add2.u2, demand.hotWaterPowerDemand) ;
  connect(add1.u1, demand.heatingPowerDemand) ;
  connect(add1.u2, demand.hotWaterPowerDemand) ;
  connect(Controller.P_set_electricHeater, electricHeater.Q_flow_set) ;
  connect(electricHeater.Q_flow_gen, add3.u2) ;
  connect(heatPump.epp, epp) ;
  connect(Tset.y, Controller.T_set) ;
  connect(Tsource.y, Controller.T_source) ;
  connect(heatPump.Q_flow_set, Controller.Q_flow_set_HP) 
  ;
end HeatPump;

