model ElectricHeater_PV_oriented "operation preferably when excess PV energy available"
  extends TransiEnt.Consumer.Systems.HouseholdEnergyConverter.Systems.Control_elHeater.Base.Controller_elHeater;
  extends TransiEnt.Basics.Icons.Controller;




  parameter Real uLow_Boiler=0.4 "Lower SOC limit";
  parameter Real uHigh_Boiler=0.8 "Upper SOC limit to switch off the boiler";
  parameter Real uSet_Boiler=0.7 "SOC Setpoint for boiler operation ";
  parameter Real uLow_Heater=0.6 "Lower SOC limit to switch on the heater";
  parameter Real uHigh_Heater=1 "Upper SOC limit to switch off the heater";
  parameter Real Threshold=0.5 "Threshold of PV infeed power to start heater operation";
  parameter SI.Power P_elHeater=3000 "Nominal electrical power of the electrical heater";
  parameter SI.Power Q_flow_n_boiler=10000 "Nominal electrical power of the gas boiler";




  Modelica.Blocks.Logical.Switch switch1 ;
  Modelica.Blocks.Sources.RealExpression zero(y=0) ;
  Modelica.Blocks.Logical.And and1 ;
  Modelica.Blocks.Logical.Greater greaterThreshold ;
  Modelica.Blocks.Sources.RealExpression P_n(y=Threshold) ;
  Modelica.Blocks.Sources.RealExpression uHigh2(y=uHigh_Boiler) ;
  Modelica.Blocks.Sources.RealExpression uLow2(y=uLow_Boiler) ;
  TransiEnt.Basics.Blocks.Hysteresis_inputVariable hysteresis_Boiler ;
  Modelica.Blocks.Logical.Not not2 ;
  Modelica.Blocks.Sources.RealExpression uHigh3(y=uHigh_Heater) ;
  Modelica.Blocks.Sources.RealExpression uLow3(y=uLow_Heater) ;
  TransiEnt.Basics.Blocks.Hysteresis_inputVariable hysteresis_heater ;
  Modelica.Blocks.Logical.Not Not1 ;
  Modelica.Blocks.Sources.RealExpression zero1(y=0) ;
  Modelica.Blocks.Sources.RealExpression P_Heater(y=P_elHeater) ;
  Modelica.Blocks.Logical.Switch switch3 ;
  Modelica.Blocks.Continuous.FirstOrder firstOrder1(k=1) ;
  Modelica.Blocks.Sources.RealExpression Setpoint(y=uSet_Boiler) ;
  Modelica.Blocks.Continuous.LimPID PID(
    Ti=1,
    controllerType=Modelica.Blocks.Types.SimpleController.P,
    yMin=0,
    k=5,
    yMax=1) ;
  Modelica.Blocks.Sources.RealExpression Q_flow_boiler(y=Q_flow_n_boiler) ;
  Modelica.Blocks.Math.Product gain1 ;
equation




  connect(greaterThreshold.y, and1.u1) ;
  connect(hysteresis_Boiler.y, not2.u) ;
  connect(uHigh2.y, hysteresis_Boiler.uHigh) ;
  connect(uLow2.y, hysteresis_Boiler.uLow) ;
  connect(switch1.y, Q_flow_set_boiler) ;
  connect(zero.y, switch1.u3) ;
  connect(PV_excess, greaterThreshold.u1) ;
  connect(zero1.y, switch3.u3) ;
  connect(P_Heater.y, switch3.u1) ;
  connect(uLow3.y, hysteresis_heater.uLow) ;
  connect(uHigh3.y, hysteresis_heater.uHigh) ;
  connect(switch3.y, P_set_electricHeater) ;
  connect(hysteresis_heater.y, Not1.u) ;
  connect(Setpoint.y, PID.u_s) ;
  connect(PID.y, gain1.u1) ;
  connect(Q_flow_boiler.y, gain1.u2) ;
  connect(firstOrder1.y, PID.u_m) ;
  connect(gain1.y, switch1.u1) ;
  connect(Not1.y, and1.u2) ;
  connect(and1.y, switch3.u2) ;
  connect(not2.y, switch1.u2) ;
  connect(hysteresis_Boiler.u, SoC) ;
  connect(firstOrder1.u, SoC) ;
  connect(hysteresis_heater.u, SoC) ;
  connect(P_n.y, greaterThreshold.u2) 
  ;
end ElectricHeater_PV_oriented;

