model PBPDispatcher "Assigns bandwiths to primary balancing providers"




  extends TransiEnt.Basics.Icons.DiscreteBlock;




  parameter Integer nout "Number of outputs (=units in PBP pool)";
  parameter SI.Power P_min_setpoint=0 "Minimum possible setpoint per unit (increment)";




  Modelica.Blocks.Interfaces.RealInput P_el_PBP_offer[nout](each final quantity="Power", each final unit="W", each displayUnit="W") "PBP Offer of individual systems" ;
  Modelica.Blocks.Interfaces.RealOutput P_el_PBP_setpoints[nout](each final quantity="Power", each final unit="W", each displayUnit="W", each start=0, each fixed=true) "Individual setpoints for PBP bandwidth of units in pool" ;
  Modelica.Blocks.Interfaces.RealInput P_el_pbp_set(final quantity="Power", final unit="W", displayUnit="W") ;
  Modelica.Blocks.Interfaces.IntegerInput communicationTrigger(start=0, fixed=true) "Integer value changes if communication intervall has past" ;




  Integer[nout] merit_order(start=1:nout, each fixed=true) "Preferred order of PBP allocation";
  SI.Power P_missing "Not yet assigned PBP power (recalculated in every iteration)";
algorithm
  when {initial(), change(communicationTrigger)} then
    (, merit_order):= Modelica.Math.Vectors.sort(P_el_PBP_offer, false);  

    P_missing := P_el_pbp_set;

    for i in 1:nout loop
      if P_missing > 0 then


        P_el_PBP_setpoints[merit_order[i]] :=min(max(P_missing, P_min_setpoint), P_el_PBP_offer[merit_order[i]]);

        P_missing :=P_missing - P_el_PBP_setpoints[merit_order[i]];
      else

        P_el_PBP_setpoints[merit_order[i]]:=0;
      end if;
    end for;
    if P_missing > 0 then
      Modelica.Utilities.Streams.print(">> Warning: PBP Dispatcher could not assign total pool setpoint. Primary balancing might be endangered!");
    end if;
  end when
    ;
end PBPDispatcher;

