  Components.Sensors.ElectricActivePower P_is ;
  Basics.Blocks.RealToVector insertP_max_unload_star(final nout=param.nSystems, index=index) ;
  Basics.Blocks.RealToVector insertP_max_load_star(final nout=param.nSystems, index=index) ;
  Modelica.Blocks.Sources.RealExpression P_max_unload_star(y=batterySystem.batteryPowerLimit.P_max_unload_star)
                                                                               ;
  Modelica.Blocks.Sources.RealExpression P_max_load_star(y=batterySystem.batteryPowerLimit.P_max_load_star)
                                                                               ;
equation




  connect(poolControlBus.P_el_set, extractP_el_set.u) ;
  connect(insertSOC.y, poolControlBus.SOC) ;
  connect(insertP_el_is.y, poolControlBus.P_el_is) ;
  connect(thisIndex.y, extractP_el_set.index) ;
  connect(extractP_el_set.y, batterySystem.P_set) ;
  connect(SOC.y, insertSOC.u) ;
  connect(batterySystem.epp, P_is.epp_IN) ;
  connect(P_is.epp_OUT, epp) ;
  connect(P_is.P, insertP_el_is.u) ;
  connect(P_max_unload_star.y, insertP_max_unload_star.u) ;
  connect(P_max_load_star.y, insertP_max_load_star.u) ;
  connect(insertP_max_unload_star.y, poolControlBus.P_max_unload_star) ;
  connect(insertP_max_load_star.y, poolControlBus.P_max_load_star) 
  ;
end PoolControlledBatterySystem;

