model Coupled_ElectricGrid "Example for sector coupling in TransiEnt library"




  extends TransiEnt.Basics.Icons.Example;




  inner TransiEnt.SimCenter simCenter(useHomotopy=false) ;
  inner TransiEnt.ModelStatistics modelStatistics ;
  TransiEnt.Producer.Combined.LargeScaleCHP.ContinuousCHP CHP(
    P_el_n=3e6,
    Q_flow_n_CHP=CHP.P_el_n/0.3,
    PQCharacteristics=TransiEnt.Producer.Combined.LargeScaleCHP.Base.Characteristics.PQ_Characteristics_STGeneric(),
    p_nom=18e5,
    m_flow_nom=38,
    h_nom=110*4.2e3,
    T_feed_init=383.15) ;
  TransiEnt.Producer.Heat.Gas2Heat.SimpleGasBoiler.SimpleBoiler gasBoiler(Q_flow_n=5e6, typeOfPrimaryEnergyCarrier=TransiEnt.Basics.Types.TypeOfPrimaryEnergyCarrierHeat.NaturalGas,
    redeclare TransiEnt.Components.Boundaries.Heat.Heatflow_L2 heatFlowBoundary(
      Q_flow_n=gasBoiler.Q_flow_n,
      change_sign=true,
      m_flow_nom=38,
      p_nom=2400000,
      h_nom=4200*60,
      C=1e6,
      p_start=2400000,
      T_start=333.15))                                                                                                                                                               ;
  TransiEnt.Basics.Tables.GenericDataTable heatDemandTable(relativepath="heat/HeatDemand_HHWilhelmsburg_MFH3000_900s_01012012_31122012.txt", constantfactor=-1.2) ;
  Modelica.Blocks.Sources.RealExpression electricityDemandCHP(y=-min(max(0, electricDemand.epp.P + electricGrid_SubSystem.pVPlant.epp.P + electricGrid_SubSystem.windProduction.epp.P), 1e6)) ;
  TransiEnt.Consumer.Electrical.LinearElectricConsumer electricDemand ;
  TransiEnt.Producer.Electrical.Photovoltaics.PVProfiles.SolarProfileLoader solarProfile(change_of_sign=true, P_el_n=2e4) ;
  TransiEnt.Producer.Electrical.Wind.WindProfiles.WindProfileLoader windProfile(change_of_sign=true, P_el_n=2e6) ;
  TransiEnt.Basics.Tables.GenericDataTable electricDemandTable(relativepath="electricity/ElectricityDemand_VDI4665_ExampleHousehold_RG1_HH_2012_900s.txt", constantfactor=1500) ;
  TransiEnt.Components.Sensors.ElectricActivePower P_12(change_of_sign=true) ;
  TransiEnt.Grid.Electrical.LumpedPowerGrid.LumpedGrid UCTE(
    delta_pr=0.2/50/(3/150 - 0.2*0.01),
    P_pr_max_star=0.02,
    k_pr=0.5,
    T_r=150,
    lambda_sec=simCenter.P_n_ref_2/(simCenter.P_n_ref_1 + simCenter.P_n_ref_2)*3e9/0.2,
    P_pr_grad_max_star=0.02/30,
    beta=0.2,
    redeclare TransiEnt.Grid.Electrical.Noise.TypicalLumpedGridError genericGridError,
    isSecondaryControlActive=false) ;
  TransiEnt.Examples.Electric.ElectricGrid_SubSystem electricGrid_SubSystem ;
  TransiEnt.Components.Boundaries.Gas.BoundaryRealGas_pTxi gasGrid ;
  Modelica.Blocks.Sources.RealExpression heatLoss(y=-0.5e6) ;
  Modelica.Blocks.Math.Add totalHeatDemand ;
  Modelica.Blocks.Sources.RealExpression varHeatDemandCHP(y=-min(totalHeatDemand.y, CHP.Q_flow_n_CHP)) ;
  Modelica.Blocks.Sources.RealExpression varHeatDemandGasBoiler(y=-min(-totalHeatDemand.y + varHeatDemandCHP.y, gasBoiler.Q_flow_n)) ;
  Modelica.Blocks.Continuous.FirstOrder firstOrder(T=0.1) ;
  Modelica.Blocks.Sources.RealExpression residualElectricPowerForPtG(y=max(0, -(electricDemand.epp.P + electricGrid_SubSystem.pVPlant.epp.P + electricGrid_SubSystem.windProduction.epp.P + CHP.epp.P))) ;
  TransiEnt.Components.Boundaries.FluidFlow.BoundaryVLE_Txim_flow DHN_source(
    variable_m_flow=true,
    variable_T=true,
    changeSign=true) ;
  Modelica.Blocks.Sources.RealExpression m_flow_DHN(y=-38) ;
  TransiEnt.Components.Boundaries.FluidFlow.BoundaryVLE_pTxi dHN_sink(boundaryConditions(p_const=24e5, T_const=100 + 273.15)) ;
  Modelica.Blocks.Sources.RealExpression T_VL(y=273.15 + 60) ;
  ClaRa.Components.VolumesValvesFittings.Valves.GenericValveVLE_L1 valveVLE_L1_1(redeclare model PressureLoss = ClaRa.Components.VolumesValvesFittings.Valves.Fundamentals.Quadratic_EN60534_incompressible (Kvs_in=38/1000*3600, m_flow_nom=38))
                                                                                                                                                                                                        ;
  ClaRa.Components.Sensors.SensorVLE_L1_T T_vl_is(unitOption=2) ;
equation




  connect(P_12.epp_OUT, UCTE.epp) ;
  connect(CHP.outlet, gasBoiler.inlet) ;
  connect(electricGrid_SubSystem.epp_UCTE, P_12.epp_IN) ;
  connect(solarProfile.y1, electricGrid_SubSystem.solarRadiation) ;
  connect(windProfile.y1, electricGrid_SubSystem.windPower) ;
  connect(CHP.epp, electricGrid_SubSystem.epp_scheduledProducers) ;
  connect(electricDemand.epp, electricGrid_SubSystem.epp_electricityDemand) ;
  connect(gasGrid.gasPort, gasBoiler.gasIn) ;
  connect(varHeatDemandCHP.y, CHP.Q_flow_set) ;
  connect(varHeatDemandGasBoiler.y, gasBoiler.Q_flow_set) ;
  connect(heatLoss.y, totalHeatDemand.u1) ;
  connect(CHP.P_set, electricityDemandCHP.y) ;
  connect(residualElectricPowerForPtG.y, firstOrder.u) ;
  connect(electricDemandTable.y1, electricDemand.P_el_set) ;
  connect(heatDemandTable.y1, totalHeatDemand.u2) ;
  connect(m_flow_DHN.y, DHN_source.m_flow) ;
  connect(T_VL.y, DHN_source.T) ;
  connect(gasBoiler.outlet, valveVLE_L1_1.inlet) ;
  connect(valveVLE_L1_1.outlet, T_vl_is.port) ;
  connect(DHN_source.fluidPortOut, CHP.inlet) ;
  connect(dHN_sink.fluidPortIn, T_vl_is.port) 
  ;
end Coupled_ElectricGrid;

