model GridConnector "Model of a transmission grid in which node interconnections are defined by a matrix"
  extends TransiEnt.Basics.Icons.Model;








  final parameter Integer nTL=sum(connectMatrix) "number of transmission lines";
  final parameter Integer connectListElectric[nTL,2]=Components.MatrixListIndexMap(connectMatrix);




  parameter Integer nNodes=4 "Number of grid nodes to connect";
  parameter Integer connectMatrix[nNodes,nNodes]=[0,1,1,1; 0,0,0,2; 0,0,0,0; 0,0,0,0] "Number of connections between node[row] to node[column]. Multiples are possible. Matrix has to be size [nNodes, nNodes]";
  parameter Components.TransmissionLineRecord transmissionLineRecord[nTL]={Components.TransmissionLineRecord() for i in 1:nTL} "Transmission line parametrization. 
      Example: if connectionMatrix top row is [0,1,2,1]: 1st line connects region 1 to 2, 2nd & 3rd lines connects region 1 to 3 ,and 4th line connects region 1 to 4";
  parameter Boolean activateSwitch=false "Turn on activate switches for transmission lines";








  TransiEnt.Basics.Interfaces.Electrical.ComplexPowerPort epp[nNodes] ;
  Modelica.Blocks.Interfaces.BooleanInput switched_input[nTL] if activateSwitch ;




  Components.TransmissionLine transmissionLine[nTL](
    hasTransformers=transmissionLineRecord.hasTransformers,
    U_S=transmissionLineRecord.voltageLevel,
    activateSwitch=activateSwitch,
    ChooseVoltageLevel=transmissionLineRecord.ChooseVoltageLevel,
    p=transmissionLineRecord.p,
    LVCableType=transmissionLineRecord.LVCableType,
    MVCableType=transmissionLineRecord.MVCableType,
    HVCableType=transmissionLineRecord.HVCableType,
    l=transmissionLineRecord.l) ;








equation








  for i in 1:nTL loop
    connect(epp[connectListElectric[i, 1]], transmissionLine[i].epp_n) ;
    connect(epp[connectListElectric[i, 2]], transmissionLine[i].epp_p) ;
  end for;
  connect(switched_input, transmissionLine.switched_input) 
  ;
end GridConnector;

within TransiEnt.Grid.Electrical.GridConnector.Components;
function MatrixListIndexMap "Mapping of connection lines between nodes defined by matrix into a loopable connection list"
  input Integer matrix[:,:];
  output Integer list[sum(matrix),2];
protected
  Integer matrixDim=size(matrix, 1);
  Integer listDim=sum(matrix);
  Integer count;
algorithm
  count := 0;
  for i in 1:matrixDim loop
    for j in 1:matrixDim loop
      if matrix[i, j] > 0 then
        for k in 1:matrix[i, j] loop
          count := count + 1;
          list[count, 1] := i;
          list[count, 2] := j;

        end for;
      end if;
    end for;
  end for
  ;
end MatrixListIndexMap;

