  extends TransiEnt.Basics.Icons.Model;




  parameter Boolean hasTransformers=false "Activate voltage transformation at each end of the power line" ;
  parameter SI.Voltage U_S=220*1e3 "voltage level of transmission line" ;
  parameter Boolean activateSwitch=false ;
