  parameter Real p=1 "Number of parallel lines" ;
  parameter Boolean calculateOverload=true "choose if boolean variable 'overload' is calculated'" ;
  parameter TransiEnt.Basics.Units.SpecificResistance r_custom=0.06e-3 "Resistance load per unit length" ;
  parameter TransiEnt.Basics.Units.SpecificReactance x_custom=0.301e-3 "Reactance load per unit length" ;
  parameter TransiEnt.Basics.Units.SpecificCapacitance c_custom=0.0125e-9 "Capacitance load per unit length" ;
