  parameter TransiEnt.Components.Electrical.Grid.Characteristics.MVCabletypes MVCableType=TransiEnt.Components.Electrical.Grid.Characteristics.MVCabletypes.L1 "Type of Medium voltage cable" ;
  parameter TransiEnt.Components.Electrical.Grid.Characteristics.HVCabletypes HVCableType=TransiEnt.Components.Electrical.Grid.Characteristics.HVCabletypes.L1 "Type of high voltage cable" ;
  parameter SI.Length l=1 "Cable LengthCable Length" ;








public
  outer TransiEnt.SimCenter simCenter;








  Modelica.Blocks.Interfaces.BooleanInput switched_input if activateSwitch ;
  TransiEnt.Basics.Interfaces.Electrical.ComplexPowerPort epp_p ;
  TransiEnt.Basics.Interfaces.Electrical.ComplexPowerPort epp_n ;




  TransiEnt.Components.Electrical.Grid.PiModelComplex_advanced transmissionLine(
    activateSwitch=activateSwitch,
    ChooseVoltageLevel=3,
    p=p,
    r_custom=r_custom,
    x_custom=x_custom,
    c_custom=c_custom,
    i_r_custom=i_r_custom,
    LVCableType=LVCableType,
    MVCableType=MVCableType,
    HVCableType=HVCableType,
    l=l,
    calculateOverload=calculateOverload) ;
  TransiEnt.Components.Electrical.PowerTransformation.SimpleTransformerComplex simpleTransformerComplex_n(
    UseInput=false,
    U_P=simCenter.v_n,
