  TransiEnt.Components.Electrical.PowerTransformation.SimpleTransformerComplex simpleTransformerComplex_p(U_P=simCenter.v_n, U_S=U_S) if hasTransformers ;
equation




  if hasTransformers then
    connect(epp_p, simpleTransformerComplex_p.epp_p) ;
    connect(simpleTransformerComplex_p.epp_n, transmissionLine.epp_p) ;
    connect(transmissionLine.epp_n, simpleTransformerComplex_n.epp_n) ;
    connect(simpleTransformerComplex_n.epp_p, epp_n) ;
  else
    connect(epp_p, transmissionLine.epp_p) ;
    connect(transmissionLine.epp_n, epp_n) ;
  end if;
  connect(switched_input, transmissionLine.switched_input) 
  ;
