    T_r=T_r,
    beta=if isSecondaryControlActive then beta else 0,
    fixedStartValue_w=false) ;
  replaceable TransiEnt.Consumer.Electrical.LinearElectricConsumer Demand(kpf=kpf) constrainedby TransiEnt.Basics.Icons.ElectricalConsumer "Choice of power boundary model. The power boundary model must match the power port." ;
  Modelica.Blocks.Sources.Constant Load(k=P_L) ;
  replaceable TransiEnt.Basics.Interfaces.Electrical.ActivePowerPort epp  constrainedby TransiEnt.Basics.Interfaces.Electrical.PartialPowerPort "Choice of power port" ;
 TransiEnt.Basics.Interfaces.General.KineticEnergyOut E_kin                                                     "Output for kinetic Energy" ;
  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerIn P_tie_set "Input for power" ;
  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerIn P_tie_is "Input for actual power" ;
