                                              ;
equation




  E_kin=-modelStatistics.kineticEnergyCollector[simCenter.iSurroundingGrid].E_kin;
  P_load=modelStatistics.electricPower.P_demand;




  connect(PowerPlants.epp, Demand.epp) ;
  connect(Demand.epp, epp) ;
  connect(PowerPlantsSchedule.u, Load.y) ;
  connect(PowerPlantsSchedule.y, PowerPlantsGen.u[1]) ;
  connect(PowerPlantsGen.u[2], P_Z) ;
  connect(P_tie_set, PowerPlants.P_tie_set) ;
  connect(P_tie_is, PowerPlants.P_tie_is) ;
  connect(Load.y, Demand.P_el_set) ;
  connect(PowerPlants.P_el_set, PowerPlantsGen.y) 
    ;
