within TransiEnt.Grid.Electrical.Noise.Base;
model LumpedGridDynamicModel "Electric grid dynamic model considering self regulating effect, primary balancing provision and time constant of rotating masses"




  extends TransiEnt.Basics.Icons.ElectricSubModel;




  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerIn delta_P_Z "Input for power difference" ;
  TransiEnt.Basics.Interfaces.General.FrequencyOut f "Output for frequency" ;




  Modelica.Blocks.Math.Gain Delta_P_V_is(k=-k_pf) ;
  Modelica.Blocks.Math.MultiSum multiSum(nu=2) ;
  Modelica.Blocks.Math.Feedback feedback ;
  Modelica.Blocks.Nonlinear.Limiter Delta_P_pr_is(uMax=Delta_P_pr_max, uMin=-
        Delta_P_pr_max)
    ;
  TransiEnt.Basics.Blocks.VariableSlewRateLimiter slewRateLimiter(maxGrad_const=Delta_P_pr_dot_max,
    Td=5,
    useThresh=true,
    thres=1e-9)                                                                                     ;
  Modelica.Blocks.Continuous.Integrator f_star(
    k=1/T_AN,
    y_start=1,
    initType=Modelica.Blocks.Types.Init.NoInit) ;
  Modelica.Blocks.Sources.Constant f_0_Const(k=1)        ;
  Modelica.Blocks.Math.Gain Dimf(k=f_0_star) ;
  Modelica.Blocks.Math.MultiSum P_V(nu=2, k=fill(-1, P_V.nu)) ;
  Modelica.Blocks.Math.Gain delta_pr(k=1/delta_P_pr)
                                                   ;
  Modelica.Blocks.Math.MultiSum P_T(nu=3) ;
  Modelica.Blocks.Sources.Constant P_0_Const(k=P_0) ;
  Modelica.Blocks.Math.Feedback feedback1 ;
  Modelica.Blocks.Sources.Constant f_02(k=1)        ;
  parameter Real Delta_P_pr_dot_max=0.02/30;
  parameter Real Delta_P_pr_max=0.2;
  parameter Real delta_P_pr=0.2;
  parameter Real T_AN=10;
  parameter Real f_0_star=50;
  parameter Real P_0=1;
  parameter Real k_pf=1.5;
equation
  connect(feedback.y, Delta_P_V_is.u) ;
  connect(f_star.y, feedback.u2) ;
  connect(f_0_Const.y, feedback.u1) ;
  connect(Dimf.y, f) ;
  connect(f_star.y, Dimf.u) ;
  connect(multiSum.y, f_star.u) ;
  connect(Delta_P_V_is.y, P_V.u[1]) ;
  connect(delta_pr.y, slewRateLimiter.u) ;
  connect(Delta_P_pr_is.u, slewRateLimiter.y) ;
  connect(P_V.y, multiSum.u[1]) ;
  connect(P_T.y, multiSum.u[2]) ;
  connect(Delta_P_pr_is.y, P_T.u[1]) ;
  connect(P_T.u[2], delta_P_Z) ;
  connect(P_0_Const.y, P_V.u[2]) ;
  connect(P_0_Const.y, P_T.u[3]) ;
  connect(feedback1.y, delta_pr.u) ;
  connect(feedback1.u2, f_star.y) ;
  connect(f_02.y, feedback1.u1) 
  ;
end LumpedGridDynamicModel;

