model SecondaryBalancingController "Secondary balancing control model as proposed by ENTSO-E operational handbook"




  extends Modelica.Blocks.Interfaces.SISO;
  extends TransiEnt.Basics.Icons.Controller;




  parameter Real K_r = 1 "Sub grid participation factor"
                                    ;
  parameter Real T_r=10 "Time constant of secondary balancing power" ;
  parameter Real beta=6e9 "Gain of secondary balancing power" ;
  parameter Boolean is_singleton = true "Select true, if this is the only 2ndary ctrl in total grid model"
                                                                       ;
  parameter SI.Power P_n=simCenter.P_n_low;




   TransiEnt.Basics.Interfaces.Electrical.ElectricPowerIn P_tie_is             if not is_singleton "Requested power for exchange between multiple control areas" ;
   TransiEnt.Basics.Interfaces.Electrical.ElectricPowerIn P_tie_set            if not is_singleton "Requested power for exchange between multiple control areas" ;
  Modelica.Blocks.Interfaces.RealInput u "Frequency deviation" ;
  Modelica.Blocks.Interfaces.RealOutput y "Secondary balancing setpoint" ;




  outer TransiEnt.SimCenter simCenter;
  Modelica.Blocks.Math.Gain ProportionalGain(k=-K_r)
    ;
  Modelica.Blocks.Continuous.PI PI(k=beta, T=T_r,
    initType=Modelica.Blocks.Types.Init.InitialOutput,
    x_start=0,
    y_start=0)
    ;




  SI.Energy E_total_sec_bal_pos(start=0, fixed=true);
  SI.Energy E_total_sec_bal_neg(start=0, fixed=true);
  Modelica.Blocks.Math.Feedback delta_P_tie ;
  Modelica.Blocks.Math.Sum G(nin=2, k=-ones(G.nin)) ;
equation




  if is_singleton then
    delta_P_tie.u1 = 0;
    delta_P_tie.u2 = 0;
  end if;
  der(E_total_sec_bal_pos) = min(0,y) "only add up negative power = additional power output";
  der(E_total_sec_bal_neg) = max(0,y) "only add up positive power = reduced power output";




  connect(P_tie_is, delta_P_tie.u1) ;
  connect(P_tie_set, delta_P_tie.u2) ;
  connect(u, ProportionalGain.u) ;
  connect(G.y, PI.u) ;
  connect(ProportionalGain.y, G.u[1]) ;
  connect(delta_P_tie.y, G.u[2]) ;
  connect(PI.y, y) 
  ;
end SecondaryBalancingController;

