  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerIn P_R_pos[nout] "Reserved positive control power (values are supposed to be positive)" ;
  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerIn P_R_neg[nout] "Reserved negative control power (values are supposed to be positive)" ;
