within TransiEnt.Grid.Electrical.SecondaryControl.Activation;
model ProRataActivation "ProRata Activation of Secondary Control"




  extends Modelica.Blocks.Interfaces.DiscreteBlock(samplePeriod=60,startTime=60);
  extends TransiEnt.Grid.Electrical.SecondaryControl.Activation.PartialActivationType(y(start=zeros(nout), fixed=true));

  final Modelica.Units.SI.Power P_R_sum_pos=sum(P_R_pos) "Total positive reserved control power";
  final Modelica.Units.SI.Power P_R_sum_neg=sum(P_R_neg) "Total negative reserved control power";
  final Real c_min_pos=min(P_R_pos)/P_R_sum_pos;
  final Real c_min_neg=min(P_R_neg)/P_R_sum_neg;
  Modelica.Blocks.Nonlinear.VariableLimiter limiter ;
  Modelica.Blocks.Nonlinear.SlewRateLimiter slewRateLimiter[nout](Rising=P_grad_max_star .* P_max, each Td=Td) ;
  Modelica.Blocks.Sources.RealExpression maxLimit(y=P_R_sum_pos) ;
  Modelica.Blocks.Sources.RealExpression minLimit(y=-P_R_sum_neg) ;
algorithm
  when {sampleTrigger} then
    c := zeros(nout);
    for j in 1:nout loop

      if c_min_pos*u >= P_respond then
        for i in 1:nout loop
          c[i] := P_R_pos[i]/P_R_sum_pos; 
        end for;
        break;                            

      elseif c_min_neg*u <= -P_respond then
        for i in 1:nout loop
          c[i] := P_R_neg[i]/P_R_sum_neg; 
        end for;
        break;                            

      elseif abs(u) >= (nout+1 - j)*P_respond then
        for i in 1:(nout+1 - j) loop
          c[i] := 1/(nout+1 - j); 
        end for;
        break;                    
      end if;
    end for;
    for i in 1:nout loop
      slewRateLimiter[i].u := c[i]*limiter.y;
    end for;
  end when;
equation
  connect(u, limiter.u) ;
  connect(slewRateLimiter.y, y) ;
  connect(maxLimit.y, limiter.limit1) ;
  connect(minLimit.y, limiter.limit2) 
  ;
end ProRataActivation;

