    Medium=medium,
    p=p,
    m_flow=m_flow_in2) ;
initial equation
  m_flow_in1 = m_flow_out*splitRatio;
  m_flow_in2 = m_flow_out - m_flow_in1;
  h_out=(h_in1*m_flow_in1+h_in2*m_flow_in2)/m_flow_out;
  xi_out = (m_flow_in1*xi_in1+m_flow_in2*xi_in2)/m_flow_out;
  outlet.m_flow = m_flow_out;
  inlet1.p = p;
  inlet1.h=h_in1;
