model SupplyAndReturnTemperatureDHG "Table with supply and return temperatures according to technical connection conditions"




  parameter TransiEnt.Grid.Heat.HeatGridControl.Base.T_set_DHG.Generic_T_set_DHG T_set_DHG=Base.T_set_DHG.Sample_T_set_DHG() ;
  parameter Modelica.Units.NonSI.Temperature_degC T_supply_max_scale=max(T_set_DHG.T_set_DHG[:, 2]);
  parameter Modelica.Units.NonSI.Temperature_degC T_return_min_scale=max(T_set_DHG.T_set_DHG[:, 3]);




  TransiEnt.Basics.Interfaces.General.TemperatureOut T_supply_K ;
  TransiEnt.Basics.Interfaces.General.TemperatureOut T_return_K ;
  Modelica.Blocks.Tables.CombiTable1Ds combiTable1Ds(table=T_set_DHG.T_set_DHG, columns={2,3}) ;
  TransiEnt.Basics.Interfaces.General.TemperatureCelsiusIn T_amb ;
  TransiEnt.Basics.Interfaces.General.TemperatureCelsiusOut T_set[size(combiTable1Ds.columns, 1)] ;
  Modelica.Blocks.Math.Gain gain(k=T_supply_max_scale/max(T_set_DHG.T_set_DHG[:, 2])) ;
  Modelica.Blocks.Math.Gain gain1(k=T_return_min_scale/max(T_set_DHG.T_set_DHG[:, 3])) ;
equation




  T_supply_K=gain.y+273.15;
  T_return_K=gain1.y+273.15;
  connect(T_amb, combiTable1Ds.u) ;
  connect(combiTable1Ds.y[1], gain.u) ;
  connect(combiTable1Ds.y[2], gain1.u) ;
  connect(gain.y, T_set[1]) ;
  connect(gain1.y, T_set[2]) ;

