within TransiEnt.Grid.Heat.HeatGridControl.Controllers;
model DHNPowerScheduler_L0 "Sample model to calculate amount of power to be generated by large scale CHP plants"




 extends TransiEnt.Basics.Icons.LargeController;




  parameter Real MarginalCost_Coal=28;
  parameter Real MarginalCost_Gas=49;
  parameter Real P_max_GuD=127e6;




   Real pWT_max;
   Real pWT_min;
   Real pWW1_max;
   Real pWW1_min;
   Real pWW2_max;
   Real pWW2_min;
   Real E_KWK;
   Real E_WT_min;
   Real E_WW1_min;
   Real E_WW2_min;




  TransiEnt.Basics.Interfaces.Thermal.HeatFlowRateIn Q_flow_Target_WT "Q_flow_Target_WT: takes the heat flow to be supplied by one of the CHP plants [W]"
    ;
  TransiEnt.Basics.Interfaces.Thermal.HeatFlowRateIn Q_flow_Target_WW " Q_flow_Target_WW: takes the heat flow to be supplied by one of the CHP plants [W]"
    ;
  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerOut P_out_WT " P_out_WT: delivers the target value of power generation to one of the CHP plants [W]" ;
  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerOut P_out_WW1 "P_out_WW: delivers the target value of power generation to one of the CHP plants [W]" ;
  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerOut P_out_WW2 "P_out_WW: delivers the target value of power generation to one of the CHP plants [W]" ;
  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerOut P_out_total "Output for total power" ;
  Modelica.Blocks.Interfaces.RealInput spotPrice " spotPrice: takes the value of the spot price [Eur/MWh]" ;




  HeatFlowDivision schedulingTwoBlocks(HeatFlowCL=Base.DHGHeatFlowDivisionCharacteristicLines.SampleHeatFlowCharacteristicLines2Units()) ;
  TransiEnt.Producer.Combined.LargeScaleCHP.Base.PQBoundaries pQDiagram_WT(PQCharacteristics=TransiEnt.Producer.Combined.LargeScaleCHP.Base.Characteristics.PQ_Characteristics_WT()) ;
  TransiEnt.Producer.Combined.LargeScaleCHP.Base.PQBoundaries pQDiagram_WW1(PQCharacteristics=TransiEnt.Producer.Combined.LargeScaleCHP.Base.Characteristics.PQ_Characteristics_WW1()) ;
  TransiEnt.Producer.Combined.LargeScaleCHP.Base.PQBoundaries pQDiagram_WW2(PQCharacteristics=TransiEnt.Producer.Combined.LargeScaleCHP.Base.Characteristics.PQ_Characteristics_WW2()) ;
  Modelica.Blocks.Interfaces.RealOutput GasKW
    ;
equation




   pWT_max= pQDiagram_WT.P_max;
   pWT_min= pQDiagram_WT.P_min;
   pWW1_max= pQDiagram_WW1.P_max;
   pWW1_min= pQDiagram_WW1.P_min;
   pWW2_max= pQDiagram_WW2.P_max;
   pWW2_min= pQDiagram_WW2.P_min;
   if spotPrice>MarginalCost_Coal then
   P_out_WT= pWT_max;
   P_out_WW1= pWW1_max;
   P_out_WW2= pWW2_max;
   else
   P_out_WT= pWT_min;
   P_out_WW1= pWW1_min;
   P_out_WW2= pWW2_min;
   end if;
   if spotPrice>MarginalCost_Gas then
   GasKW=P_max_GuD;
   else
   GasKW=0;
   end if;
  P_out_total=P_out_WT+P_out_WW1+P_out_WW2;
   E_KWK=E_WT_min+E_WW1_min+E_WW2_min;
   der(E_WT_min)=pWT_min;
   der(E_WW1_min)=pWW1_min;
   der(E_WW2_min)=pWW2_min;




  connect(Q_flow_Target_WT, pQDiagram_WT.Q_flow) ;
  connect(schedulingTwoBlocks.Q_flow_i[1], pQDiagram_WW1.Q_flow) ;
  connect(schedulingTwoBlocks.Q_flow_i[2], pQDiagram_WW2.Q_flow) ;
  connect(schedulingTwoBlocks.Q_flow_total, Q_flow_Target_WW) 
  ;
end DHNPowerScheduler_L0;

within TransiEnt.Grid.Heat.HeatGridControl.HeatDemandPrediction;
model HeatingGenerationCharline "Characteristic line of the heating load in function of the ambient temperature"




    parameter HeatDemandPrediction.HeatingDemandCharacteristic.CharLineHeatDemand CharLine "Choose City's Characteristic Line" ;
    parameter Real Damping_Weekend=1 "Damping ratio for heat load at weekends (between 0 and 1)";
  parameter TransiEnt.Basics.Types.TypeOfWeekday BeginWeekday=2 "Weekday on which simulation begins";
    parameter Real TransitionDuration=5;
    parameter Boolean offsetOn=true "if 'true', the heat demand is sumperimposed with a daily profile on cold days";
    parameter Boolean weekendOn=true "if 'true', the heat demand on the weekend is damped by the constant factor 'Damping_Weekend'";
    parameter Boolean SummerDayTypicalHeatLoadCharLine=true "if true, on warm days a typical heat load profile is added to the minimum load on summer days - if 'false' the load on warm days is constant (=minimum load)";




    Real m=CharLine.m;
    Real c=CharLine.c;
    Real a=CharLine.a;
    Real SummerDayProfile;
  Modelica.Units.SI.Heat Q_dem;
    Real offset;





  TransiEnt.Basics.Interfaces.General.TemperatureCelsiusIn T_amb "Ambient temperature in Celsius"
    ;
  Basics.Interfaces.Thermal.HeatFlowRateOut Q_flow "Heat flow rate input" ;




  Basics.Tables.GenericDataTable SummerDayTypicalHeatLoad(relativepath="\\heat\\TypicalHeatLoadDay_AbsoluteValues_MonoIncreasing.txt", extrapolation=Modelica.Blocks.Types.Extrapolation.Periodic,
    constantfactor=1/637.6e6*CharLine.a)                                                                                                                                                         ;
  Basics.Blocks.Sources.WeekendPulse_Trapezoid weekendPulse(BeginningWeekday=BeginWeekday, k_weekend=Damping_Weekend) ;
  Basics.Tables.GenericDataTable OffsetvalueDailyprofile(extrapolation=Modelica.Blocks.Types.Extrapolation.Periodic, relativepath="\\heat\\TypicalHeatLoad_DHN_Normalized.txt") ;
  Modelica.Blocks.Sources.Trapezoid hour_of_day(
    falling=0,
    width=0,
    rising=3600*24*7,
    period=3600*24*7,
    startTime=-6*24*3600,
    offset=1,
    amplitude=6.9)                                                   ;
equation




  if offsetOn==true then
    offset=OffsetvalueDailyprofile.y1;
  else
    offset=1;
  end if;
  if SummerDayTypicalHeatLoadCharLine==true then
    SummerDayProfile=SummerDayTypicalHeatLoad.y1;
  else
    SummerDayProfile=0;
  end if;
  if weekendOn==true then
    if (m*T_amb+c*weekendPulse.y)*offset > a*weekendPulse.y+SummerDayProfile then
      Q_flow=(m*T_amb +c*weekendPulse.y)*offset;
      else
      Q_flow=a*weekendPulse.y+SummerDayProfile;
    end if;
  else
    if (m*T_amb+c)*offset > a+SummerDayProfile then
      Q_flow=(m*T_amb +c)*offset;
    else
      Q_flow=a+SummerDayProfile;
    end if;
  end if;
  der(Q_dem)=Q_flow;




  ;
end HeatingGenerationCharline;

