within TransiEnt.Producer.Combined.LargeScaleCHP;
model TwoBlockCHP "Example model of plants consisting of several units"




  extends TransiEnt.Basics.Icons.SteamCyclewHeatingCondenser2Blocks;




  outer TransiEnt.SimCenter simCenter;




  Modelica.Units.SI.Power P_out_net(displayUnit="MW");
  Modelica.Units.SI.HeatFlowRate Q_flow_gen(displayUnit="MW");




  parameter TILMedia.VLEFluidTypes.BaseVLEFluid   medium=simCenter.fluid1 "Medium to be used" ;
  parameter Boolean useGasPort=false "Choose if gas port is used or not" ;
  parameter TILMedia.VLEFluidTypes.BaseVLEFluid medium_gas=simCenter.gasModel1 if useGasPort==true "Gas Medium to be used - only if useGasPort==true" ;





  Basics.Interfaces.General.EyeOut eye ;

  replaceable ContinuousCHP Block_1(
    PQCharacteristics=Base.Characteristics.PQ_Characteristics_WW1(),
    P_el_n = 150.369e6,
    useGasPort=useGasPort)
                        constrainedby Base.PartialCHP ;
  replaceable ContinuousCHP Block_2(
    PQCharacteristics=Base.Characteristics.PQ_Characteristics_WW2(),
    P_el_n = 137.106e6,
    useGasPort=useGasPort)
                         constrainedby Base.PartialCHP ;

  TransiEnt.Components.Boundaries.FluidFlow.BoundaryVLE_Txim_flow massflow_Tm_flow4(variable_m_flow=true, variable_T=true) ;
  TransiEnt.Components.Boundaries.FluidFlow.BoundaryVLE_Txim_flow massflow_Tm_flow3(variable_m_flow=true, variable_T=true) ;

  Components.Visualization.InfoBoxLargeCHP infoBoxLargeCHP2 ;
  Components.Visualization.InfoBoxLargeCHP infoBoxLargeCHP3 ;

  Basics.Interfaces.Electrical.ElectricPowerIn P_set_B1 "Set power B1" ;
  Basics.Interfaces.Electrical.ElectricPowerIn P_set_B2 "Set power B2" ;
  Basics.Interfaces.Thermal.HeatFlowRateIn Q_flow_set_B1 "Set heat flow rate B1" ;
  Basics.Interfaces.Thermal.HeatFlowRateIn Q_flow_set_B2 "Set heat flow rate B2" ;
  TransiEnt.Basics.Interfaces.General.MassFlowRateIn m_flow_set_B1 "Set mass flow rate B1" ;
  TransiEnt.Basics.Interfaces.General.MassFlowRateIn m_flow_set_B2 "Set mass flow rate B2" ;
  Basics.Interfaces.General.TemperatureIn T_return_B2 "Set return temperature B2" ;
  Basics.Interfaces.Thermal.FluidPortOut outlet(Medium=medium) ;
  Basics.Interfaces.General.TemperatureIn T_return_B1 "Set return temperature B1" ;
  Basics.Interfaces.Electrical.ActivePowerPort epp ;
  Basics.Interfaces.Gas.RealGasPortIn gasPortIn(Medium=medium_gas) if useGasPort==true ;

  Components.Sensors.TemperatureSensor T_out_sensor ;
  Components.Sensors.TemperatureSensor T_in_sensor ;
  Basics.Interfaces.General.EyeOut eye_Block1 ;
  Basics.Interfaces.General.EyeOut eye_Block2 ;
equation





  P_out_net=-1*epp.P;
  Q_flow_gen=-1*outlet.m_flow*(outlet.h_outflow-inStream(Block_1.inlet.h_outflow));

  eye.P=P_out_net;
  eye.Q_flow=Q_flow_gen;
  eye.T_supply=T_out_sensor.T_celsius;
  eye.T_return=T_in_sensor.T_celsius;
  eye.p = outlet.p/1e5;
  eye.h_supply = outlet.h_outflow/1e3;
  eye.h_return = Block_1.inlet.h_outflow/1e3;
  eye.m_flow = -outlet.m_flow;





  connect(massflow_Tm_flow4.fluidPortOut, Block_1.inlet) ;
  connect(massflow_Tm_flow3.fluidPortOut, Block_2.inlet) ;
  connect(Block_1.eye, infoBoxLargeCHP3.eye) ;
  connect(Block_2.eye, infoBoxLargeCHP2.eye) ;
  connect(P_set_B1, Block_1.P_set) ;
  connect(Q_flow_set_B1, Block_1.Q_flow_set) ;
  connect(P_set_B2, Block_2.P_set) ;
  connect(Q_flow_set_B2, Block_2.Q_flow_set) ;
  connect(m_flow_set_B1, massflow_Tm_flow4.m_flow) ;
  connect(m_flow_set_B2, massflow_Tm_flow3.m_flow) ;
  connect(T_return_B2, massflow_Tm_flow3.T) ;
  connect(Block_1.outlet, outlet) ;
  connect(Block_2.outlet, outlet) ;
  connect(outlet, T_out_sensor.port) ;
  connect(massflow_Tm_flow4.T, T_return_B1) ;
  connect(Block_1.epp, epp) ;
  connect(Block_2.epp, epp) ;
  connect(massflow_Tm_flow3.fluidPortOut, T_in_sensor.port) ;

  connect(Block_1.eye, eye_Block1) ;
  connect(Block_2.eye, eye_Block2) ;
  if useGasPort then
    connect(Block_2.gasPortIn, gasPortIn) ;
    connect(Block_1.gasPortIn, gasPortIn) ;
  end if
  ;
end TwoBlockCHP;

within TransiEnt.Producer.Combined.LargeScaleCHP.Base;
model HeatInputTable "Table based model which delivers the amount of heat input required by a Large Scale CHP plant to produce a given el. and th. output"




  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerIn P ;
  TransiEnt.Basics.Interfaces.Thermal.HeatFlowRateIn Q_flow ;
  TransiEnt.Basics.Interfaces.Thermal.HeatFlowRateOut Q_flow_input ;




  parameter TransiEnt.Producer.Combined.LargeScaleCHP.Base.Characteristics.Generic_PQ_Characteristics PQCharacteristics=Characteristics.PQ_Characteristics_WW1() ;
  parameter SI.HeatFlowRate Q_flow_n=Q_flow_n_PQCharacteristics;
  parameter SI.Power P_el_n=P_el_n_PQCharacteristics;
  final parameter SI.HeatFlowRate Q_flow_n_PQCharacteristics=max(PQCharacteristics.PQboundaries[:, 1]);
  final parameter SI.Power P_el_n_PQCharacteristics=max(PQCharacteristics.PQboundaries[:, 2:3]);




  TransiEnt.Basics.Tables.GenericCombiTable2D genericCombiTable2D(combiTable2D(tableOnFile=false, table=PQCharacteristics.PQ_HeatInput_Matrix)) ;
  Modelica.Blocks.Math.Gain gain_Q_flow(k=PQCharacteristics.k_Q_flow*Q_flow_n_PQCharacteristics/Q_flow_n) ;
  Modelica.Blocks.Math.Gain gain_P_max(k=1/PQCharacteristics.k_P_el*P_el_n_PQCharacteristics/P_el_n) ;
  Modelica.Blocks.Math.Division division ;
  Modelica.Blocks.Sources.RealExpression realExpression(y=gain_P_max.u + gain_Q_flow.u) ;
  Modelica.Blocks.Sources.RealExpression realExpression1(y=max(1e-3, gain_P_max.y + gain_Q_flow.y)) ;
  Modelica.Blocks.Math.Product product ;
equation




  connect(Q_flow, gain_Q_flow.u) ;
  connect(genericCombiTable2D.u1, gain_P_max.y) ;
  connect(gain_P_max.u, P) ;
  connect(gain_Q_flow.y, genericCombiTable2D.u2) ;
  connect(division.u1, realExpression.y) ;
  connect(division.u2, realExpression1.y) ;
  connect(division.y, product.u2) ;
  connect(product.u1, genericCombiTable2D.y) ;
  connect(Q_flow_input, product.y) 
   ;
end HeatInputTable;

