  extends TransiEnt.Producer.Heat.Base.XtH_L1_idContrMFlow_temp_base(Q_flow_n=P_el_n/eta_el*eta_th);




  parameter SI.Power P_el_n=3.5e3 "Nominal electric power" ;
  parameter SI.Efficiency eta_el = 0.3 "Constant electric efficiency" ;
  parameter SI.Efficiency eta_th = 0.6 "Constant thermal efficiency" ;
  replaceable model ProducerCosts =
      TransiEnt.Components.Statistics.ConfigurationData.PowerProducerCostSpecs.Empty
    constrainedby TransiEnt.Components.Statistics.ConfigurationData.PowerProducerCostSpecs.PartialPowerPlantCostSpecs ;
  parameter Boolean usePowerPort=false "True if power port shall be used" ;
  parameter SI.SpecificEnthalpy HoC_fuel=40e6 "Heat of combustion of fuel, will be used if gasport is deactivated in model" ;




  Components.Statistics.Collectors.LocalCollectors.CollectElectricPower collectElectricPower(typeOfResource=typeOfResource) ;
   Modelica.Blocks.Sources.RealExpression realExpression(y=P_el) ;
  replaceable Components.Boundaries.Electrical.ActivePower.Power powerBoundary
                                                                             if usePowerPort constrainedby Components.Boundaries.Electrical.ActivePower.Power "Choice of power boundary model. The power boundary model must match the power port." ;
  replaceable Basics.Interfaces.Electrical.ActivePowerPort            epp if usePowerPort constrainedby Basics.Interfaces.Electrical.ActivePowerPort            "Choice of power port" ;
  Modelica.Blocks.Sources.RealExpression realExpression1(y=H_flow) ;
  Modelica.Blocks.Math.Division division ;




public
  SI.EnthalpyFlowRate H_flow "Consumed gas enthalpy flow rate";
  SI.Power P_el "Electric power";
  Modelica.Blocks.Sources.RealExpression HoC_constant(y=HoC_fuel) if not useGasPort ;




equation
  H_flow=-(Q_flow + P_el)/(eta_el + eta_th);
  P_el = Q_flow*eta_el/eta_th;
  collectElectricPower.powerCollector.P =-P_el;




  connect(modelStatistics.powerCollector[collectElectricPower.typeOfResource], collectElectricPower.powerCollector);
  if usePowerPort then
  connect(realExpression.y,powerBoundary. P_el_set) ;
  connect(powerBoundary.epp,epp)  ;
  end if;
  if useGasPort then
    connect(vleNCVSensor.NCV,division. u2) ;
    connect(m_flow_gas,division. y) ;
  end if;
  connect(division.u1, realExpression1.y) ;
  connect(HoC_constant.y, division.u2) 
  ;
end SmallScaleCHP_L1_idContrMFlow_temp;

within TransiEnt.Producer.Combined.SmallScaleCHP.Base;
connector ControlBus "Controls a CHP model"
replaceable record Specification=BaseCHPSpecification;
  Modelica.Units.SI.Temperature T_return;
  Modelica.Units.SI.Temperature T_supply;
Boolean switch;
  Modelica.Units.SI.Power P_el_set;
  Modelica.Units.SI.Power P_el_meas;
  Modelica.Units.SI.EnthalpyFlowRate Q_flow_meas;
  Modelica.Units.SI.Power P_el_pump_set;
  Modelica.Units.SI.Frequency f_grid;
  Modelica.Units.SI.Pressure dp
  ;
end ControlBus;

within TransiEnt.Producer.Combined.SmallScaleCHP.Base;
partial model PartialCHPController "Partial CHP controller model"
  import TransiEnt;
  extends TransiEnt.Basics.Icons.Controller;
  outer TransiEnt.SimCenter simCenter;




  parameter TransiEnt.Producer.Combined.SmallScaleCHP.Base.BaseCHPSpecification Specification ;
  parameter SI.Time t_OnOff=1800 "Minimum time between switching";
  parameter Boolean useGridTemperatures = false "Whether or not to use target grid temperatures";
  parameter SI.Temperature T_supply_const=363.15 "Target temperature of CHP" ;
  parameter SI.Temperature T_return_max=Specification.T_return_max "Maximum allowed return temperature";




  Real sigma "Heat fraction";
  SI.Time runningTime(start=0) "Total time running";
  SI.Time startTime(start=0) "Time since last start";
  SI.Time stopTime(start=-2*t_OnOff) "Time since last stop" ;
  Integer startCounter(start=0) "Counter to start on/off cycles";
  SI.TemperatureDifference dT "Target temperature difference";
  SI.Pressure dp "Measured pressure difference in CHP";
  Modelica.Units.NonSI.Temperature_degC T_supply_target "Target supply temperature";
  Real runningtime = if switch then 1 else 0;




  TransiEnt.Producer.Combined.SmallScaleCHP.Base.ControlBus controlBus(Specification=Specification) ;
protected
  Modelica.Blocks.Interfaces.BooleanInput switch(start=false) ;
  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerIn P_el_set(start=(Specification.P_el_max + Specification.P_el_min)/2) "Electric power input set value" ;
  TransiEnt.Basics.Interfaces.General.TemperatureOut T_return "Return temperature output" ;
  TransiEnt.Basics.Interfaces.General.TemperatureOut T_supply "Supply temperature output" ;
  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerOut P_el_meas  ;
  TransiEnt.Basics.Interfaces.Thermal.HeatFlowRateOut Q_flow_meas ;
  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerOut P_el_pump_set(start=0.01*Specification.P_el_min) ;
public
  Modelica.Blocks.Logical.Timer timer ;
initial algorithm




  stopTime:=-2*t_OnOff;
equation
  controlBus.P_el_set = P_el_set;
  controlBus.T_return = T_return;
  controlBus.T_supply = T_supply;
  controlBus.switch = switch;
  controlBus.P_el_meas = P_el_meas;
  controlBus.Q_flow_meas = Q_flow_meas;
  controlBus.P_el_pump_set = P_el_pump_set;
  controlBus.dp = dp;
  if (useGridTemperatures) then
    T_supply_target = simCenter.heatingCurve.T_supply;
  else
    T_supply_target = T_supply_const;
  end if;
   dT=T_supply_target-T_return;

  P_el_pump_set=max(min(0.1*Specification.P_el_min,dp*(Q_flow_meas)/(1000*4200*max(dT,1))),0.0001*Specification.P_el_min); 



  sigma = noEvent(if P_el_meas>0 then Q_flow_meas/P_el_meas else 0);
algorithm

  when (edge(switch)) then
    startCounter := startCounter + 1;
    startTime := time;
  end when;

  when (change(switch)) and pre(switch)==true then
    stopTime := time;
  end when;

   when (change(switch)) then
     runningTime := runningTime + (time - startTime);
   end when;
equation
  connect(timer.u, switch) 
  ;
end PartialCHPController;

within TransiEnt.Producer.Combined.SmallScaleCHP.Controller;
model ControllerExtP_el "CHP Controller that sets plant to a given electric power"




  extends TransiEnt.Producer.Combined.SmallScaleCHP.Base.PartialCHPController;
  extends TransiEnt.Basics.Icons.Controller;
  import TransiEnt;




  parameter Modelica.Units.SI.Power P_const=nDevices*Specification.P_el_max "Constant Power";
  parameter Boolean use_P_in=true "Use external controller";
  parameter Integer nDevices=1 "number of Devices";




  Boolean offCondition(start=true);
  Boolean onCondition;




  Modelica.Blocks.Nonlinear.Limiter limiter(uMin=Specification.P_el_min, uMax=
        nDevices*Specification.P_el_max)
    ;




  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerIn P_el_set_external if use_P_in "Input for electric power" ;
  Modelica.Blocks.Interfaces.RealOutput t_running( final quantity="Time", final unit="s", displayUnit="h") "total time of operation of CHP"
    ;
  TransiEnt.Basics.Interfaces.Thermal.HeatFlowRateOut Q_flow_meas_out "Produced heatflow rate"
    ;
  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerOut P_el_meas_out "Produced electric power"
    ;
equation
  onCondition = P_el_set > Specification.P_el_min and (time-stopTime >= t_OnOff);
 offCondition = P_el_set<Specification.P_el_min+1 or T_return > T_return_max;
  if pre(switch) == false and pre(onCondition) then
    switch = true;
  elseif pre(switch) and pre(offCondition) then
    switch = false;
  else
    switch = pre(switch);
  end if;
  if not use_P_in then
    limiter.u = P_const;
  end if;
  connect(P_el_meas, P_el_meas_out);
  connect(Q_flow_meas, Q_flow_meas_out);
  connect(P_el_set_external, limiter.u) ;
  connect(P_el_set, limiter.y) ;
  connect(Q_flow_meas_out, Q_flow_meas_out) ;
  connect(timer.y, t_running) 
  ;
end ControllerExtP_el;

within TransiEnt.Producer.Combined.SmallScaleCHP.Controller;
model ControllerExtQ_flow "CHP controller that sets plant to a given heat flow rate"




  import TransiEnt;
  extends TransiEnt.Basics.Icons.Controller;
  extends TransiEnt.Producer.Combined.SmallScaleCHP.Base.PartialCHPController;




  parameter Boolean useQ_flow_in=true "Use input or constant";
  parameter Modelica.Units.SI.HeatFlowRate Q_flow_const=400e3 "Fixed input" ;




  Boolean onCondition(start=true);
  Boolean offCondition;




  Modelica.Blocks.Continuous.LimPID PID(
    Ti=1,
    Td=0,
    k=100,
    yMin=Specification.P_el_min,
    yMax=Specification.P_el_max,
    strict=true)
    ;




 TransiEnt.Basics.Interfaces.Thermal.HeatFlowRateIn Q_flow_set if useQ_flow_in
    ;
equation
  onCondition = P_el_set >= Specification.P_el_min and (time - stopTime >= t_OnOff);


  offCondition = P_el_set <= Specification.P_el_min;
  if ((pre(switch) == true) and offCondition) then
    switch = false;

  elseif ((pre(switch) == false) and onCondition) then
    switch = true;

  else
    switch = pre(switch);
  end if;
  if not useQ_flow_in then
    PID.u_s=Q_flow_const;
  end if;
  connect(P_el_set, PID.y) ;
  connect(PID.u_m, Q_flow_meas) ;
  connect(Q_flow_set, PID.u_s) 
  ;
end ControllerExtQ_flow;

within TransiEnt.Producer.Combined.SmallScaleCHP.Controller;
model ControllerHeatLed "Controller that gets target temperatures from simCenter and has an input for storage Temperature"




  import TransiEnt;
  extends TransiEnt.Producer.Combined.SmallScaleCHP.Base.PartialCHPController;




  parameter Integer nDevices=1 "Number of CHP Units";
  parameter Modelica.Units.SI.Temperature T_turnOn=333.15 "Minimal allowed return/storage temperature";


  parameter Modelica.Units.SI.Temperature T_turnOff=363.15 "Maximum allowed Storage temperature";
  parameter Boolean useT_stor=false "if false T_return will be used";
  parameter Modelica.Units.SI.Temperature T_stor_target=363.15 "Target Storage Temperature" ;
  parameter Modelica.Blocks.Types.SimpleController controllerType=Modelica.Blocks.Types.SimpleController.PID "Type of controller" ;
  parameter Real k(
    min=0,
    unit="1") = 1 "Gain of controller" ;
  parameter Modelica.Units.SI.Time Ti(
    min=Modelica.Constants.small,
    start=0.5) = 0.1 "Time constant of Integrator block" ;
  parameter Modelica.Units.SI.Time Td(
    min=0,
    start=0.1) = 0 "Time constant of Derivative block" ;
  parameter Real yMax(start=1) = nDevices*Specification.P_el_max "Upper limit of output"
                                                                                        ;
  parameter Real yMin=Specification.P_el_min "Lower limit of output" ;
  parameter Real wp(min=0) = 1 "Set-point weight for Proportional block (0..1)" ;
  parameter Real wd(min=0) = 0 "Set-point weight for Derivative block (0..1)" ;
  parameter Real Ni(min=100*Modelica.Constants.eps) = 0.9 "Ni*Ti is time constant of anti-windup compensation"  ;
  parameter Real Nd(min=100*Modelica.Constants.eps) = 10 "The higher Nd, the more ideal the derivative block" ;
  parameter Modelica.Blocks.Types.Init initType=Modelica.Blocks.Types.Init.InitialState "Type of initialization (1: no init, 2: steady state, 3: initial state, 4: initial output)" ;
  parameter Boolean limitsAtInit=true "= false, if limits are ignored during initializiation" ;
  parameter Real xi_start=0 "Initial or guess value value for integrator output (= integrator state)" ;
  parameter Real xd_start=0 "Initial or guess value for state of derivative block" ;
  parameter Real y_start=Specification.P_el_max "Initial value of output" ;




  Boolean offCondition;
  Boolean onCondition;
  Modelica.Units.SI.Temperature T_return_target;




  Modelica.Blocks.Continuous.LimPID PID(
    Ti=Ti,
    Td=Td,
    k=k,
    xi_start=xi_start,
    y_start=y_start,
    initType=initType,
    wp=wp,
    Nd=Nd,
    wd=wd,
    yMax=yMax,
    yMin=yMin) ;




  TransiEnt.Basics.Interfaces.General.TemperatureIn T_stor_in if useT_stor ;
protected
  TransiEnt.Basics.Interfaces.General.TemperatureIn T_meas "Internal connector for T_stor";




public
  Modelica.Blocks.Math.Gain signChanger(k=1) ;
equation
  onCondition = (not switch) and ((T_return < T_turnOn) and PID.u_m <
    T_turnOn and (time - stopTime) > t_OnOff);
  offCondition = (T_return > T_return_max) or T_meas>T_turnOff
     and (timer.y) > t_OnOff;

  if ((pre(switch) == true) and pre(offCondition)) then
    switch = false;

  elseif ((pre(switch) == false) and pre(onCondition)) then
    switch = true;

  else
    switch = pre(switch);
  end if;
  T_return_target = simCenter.heatingCurve.T_return;
  if useGridTemperatures then
    PID.u_s=simCenter.heatingCurve.T_return;
  else
    PID.u_s = T_stor_target;
  end if;
  if useT_stor then
    connect(PID.u_m, T_stor_in)  ;

  else
    connect(PID.u_m, T_return)  ;
  end if;
  if (not useT_stor) then
    T_meas = T_stor_target;
  end if;
  connect(T_stor_in, T_meas);
  connect(PID.y, signChanger.u) ;
  connect(signChanger.y, P_el_set) 
  ;
end ControllerHeatLed;

within TransiEnt.Producer.Combined.SmallScaleCHP.SmallScaleCHP_simple.Control;
model ControlBoilerCHP_modulatingBoiler_HeatLed "Simple controller for a heat led CHP system with modulating boiler based on SoC or temperature of a heat storage"
  extends TransiEnt.Producer.Combined.SmallScaleCHP.SmallScaleCHP_simple.Control.Base.ControlBoilerCHP_Base;
  extends TransiEnt.Basics.Icons.Controller;




  parameter SI.Temperature TLow_CHP=354.15 "Storage charging level for CHP switch on" ;
  parameter SI.Temperature THigh_CHP=359.15 "Storage charging level for CHP switch off" ;
  parameter SI.Temperature TLow_Boiler=351.15 "Storage charging level for boiler switch on" ;
  parameter SI.Temperature THigh_Boiler=355.15 "Storage charging level for boiler switch off" ;
  parameter SI.Temperature Tset_Boiler=355.15 "Charging level setpoint for boiler operation" ;
  parameter Real SoCLow_CHP=0.55 "SoC limit to switch on the CHP" ;
  parameter Real SoCHigh_CHP=0.8 "SoC limit to switch off the CHP" ;
  parameter Real SoCLow_Boiler=0.4 "SoC limit to switch on the boiler" ;
  parameter Real SoCHigh_Boiler=0.6 "SoC limit to switch off the boiler" ;
  parameter Real SOCset_Boiler=0.5 "Storage temperature setpoint for boiler operation" ;
  parameter Real t_min_on_CHP=3600 "Minimum on time after startup of the CHP" ;
  parameter Real t_min_off_CHP=3600 "Minimum off time after shutdown of the CHP" ;




  Real uHigh_CHP;
  Real uLow_CHP;
  Real uHigh_Boiler;
  Real uLow_Boiler;
  Real uset_Boiler;




  Modelica.Blocks.Logical.Switch switch1 ;
  Modelica.Blocks.Sources.RealExpression zero(y=0) ;
  Modelica.Blocks.Logical.Not Not ;
  Modelica.Blocks.Sources.RealExpression uHigh(y=uHigh_CHP) ;
  Modelica.Blocks.Sources.RealExpression uLow(y=uLow_CHP) ;
  TransiEnt.Basics.Blocks.Hysteresis_inputVariable hysteresis_CHP ;
  TransiEnt.Basics.Blocks.OnOffRelais onOffRelais(
    init_state=2,
    t_min_on=t_min_on_CHP,
    t_min_off=t_min_off_CHP) ;
  Modelica.Blocks.Sources.RealExpression Q_CHP(y=Q_n_CHP) ;
  TransiEnt.Basics.Blocks.Hysteresis_inputVariable hysteresis_boiler ;
  Modelica.Blocks.Sources.RealExpression uHigh1(y=uHigh_Boiler) ;
  Modelica.Blocks.Sources.RealExpression uLow1(y=uLow_Boiler) ;
  Modelica.Blocks.Logical.Not Not1 ;
  Modelica.Blocks.Sources.RealExpression max_Storage_Heat(y=uset_Boiler) ;
  Modelica.Blocks.Continuous.FirstOrder firstOrder1(k=1) ;
  Modelica.Blocks.Continuous.LimPID PID(
    Ti=1,
    controllerType=Modelica.Blocks.Types.SimpleController.P,
    yMax=Q_n_Boiler,
    k=Q_n_Boiler,
    yMin=0,
    initType=Modelica.Blocks.Types.Init.InitialOutput,
    y_start=Q_n_Boiler) ;
  Modelica.Blocks.Logical.Switch switch3 ;
  Modelica.Blocks.Logical.And and1 ;
  Modelica.Blocks.Sources.RealExpression realExpression(y=0) ;
equation
  uHigh_CHP = if control_SoC then SoCHigh_CHP else THigh_CHP;
  uLow_CHP = if control_SoC then SoCLow_CHP else TLow_CHP;
  uHigh_Boiler = if control_SoC then SoCHigh_Boiler else THigh_Boiler;
  uLow_Boiler = if control_SoC then SoCLow_Boiler else TLow_Boiler;
  uset_Boiler = if control_SoC then SOCset_Boiler else Tset_Boiler;
  connect(hysteresis_CHP.y, Not.u) ;
  connect(uLow.y, hysteresis_CHP.uLow) ;
  connect(uHigh.y, hysteresis_CHP.uHigh) ;
  connect(Not.y,onOffRelais. u) ;
  connect(Q_CHP.y, switch1.u1) ;
  connect(onOffRelais.y,switch1. u2) ;
  connect(uHigh1.y,hysteresis_boiler. uHigh) ;
  connect(uLow1.y,hysteresis_boiler. uLow) ;
  connect(hysteresis_boiler.y,Not1. u) ;
  connect(zero.y,switch1. u3) ;
  connect(T, hysteresis_CHP.u) ;
  connect(SoC, hysteresis_CHP.u) ;
  connect(SoC,hysteresis_boiler. u) ;
  connect(T,hysteresis_boiler. u) ;
  connect(switch1.y, Q_flow_set_CHP) ;
  connect(SoC, firstOrder1.u) ;
  connect(firstOrder1.y, PID.u_m) ;
  connect(max_Storage_Heat.y, PID.u_s) ;
  connect(PID.y, switch3.u1) ;
  connect(and1.y, switch3.u2) ;
  connect(realExpression.y, switch3.u3) ;
  connect(switch3.y, Q_flow_set_boiler) ;
  connect(Not1.y, and1.u2) ;
  connect(Not.y, and1.u1) 
  ;
end ControlBoilerCHP_modulatingBoiler_HeatLed;

