model ControlBoilerCHP_modulatingBoiler_PriceLed "Simple controller for a price driven CHP system with modulating boiler based on SoC or temperature of a heat storage"
  extends TransiEnt.Producer.Combined.SmallScaleCHP.SmallScaleCHP_simple.Control.Base.ControlBoilerCHP_Base;
  extends TransiEnt.Basics.Icons.Controller;
  outer TransiEnt.SimCenter simCenter;




  parameter SI.Temperature TLow_CHP=354.15 "Storage charging level for CHP switch on " ;
  parameter SI.Temperature THigh_CHP=359.15 "Storage charging level for CHP switch off" ;
  parameter SI.Temperature TLow_Boiler=351.15 "Storage charging level for boiler switch on" ;
  parameter SI.Temperature THigh_Boiler=355.15 "Storage charging level for boiler switch off" ;
  parameter SI.Temperature Tset_Boiler=355.15 "Charging level setpoint for boiler operation" ;
  parameter Real SoCLow_CHP=0.55 "SoC limit to switch on the CHP" ;
  parameter Real SoCHigh_CHP=0.8 "SoC limit to switch off the CHP" ;
  parameter Real SoCLow_Boiler=0.4 "SoC limit to switch on the boiler" ;
  parameter Real SoCHigh_Boiler=0.6 "SoC limit to switch off the boiler" ;
  parameter Real SOCset_Boiler=0.5 "Storage temperature setpoint for boiler operation" ;
  parameter Real t_min_on_CHP=3600 "Minimum on time after startup of the CHP" ;
  parameter Real t_min_off_CHP=3600 "Minimum off time after shutdown of the CHP" ;
  parameter Real Price_Threshold(unit="€/Kwh") = 0.05 "Price limit for the operation of the CHP" ;




  Real uHigh_CHP;
  Real uLow_CHP;
  Real uHigh_Boiler;
  Real uLow_Boiler;
  Real uset_Boiler;




  Modelica.Blocks.Logical.Switch switch1 ;
  Modelica.Blocks.Sources.RealExpression zero(y=0) ;
  Modelica.Blocks.Logical.Not Not ;
  Modelica.Blocks.Sources.RealExpression uHigh(y=uHigh_CHP) ;
  Modelica.Blocks.Sources.RealExpression uLow(y=uLow_CHP) ;
  TransiEnt.Basics.Blocks.Hysteresis_inputVariable hysteresis_CHP ;
  TransiEnt.Basics.Blocks.OnOffRelais onOffRelais(
    init_state=2,
    t_min_on=t_min_on_CHP,
    t_min_off=t_min_off_CHP) ;
  Modelica.Blocks.Sources.RealExpression Q_CHP1(y=Q_n_CHP) ;
  TransiEnt.Basics.Blocks.Hysteresis_inputVariable hysteresis_boiler ;
  Modelica.Blocks.Sources.RealExpression uHigh1(y=uHigh_Boiler) ;
  Modelica.Blocks.Sources.RealExpression uLow1(y=uLow_Boiler) ;
  Modelica.Blocks.Logical.Not Not1 ;
  Modelica.Blocks.Sources.RealExpression max_Storage_Heat(y=uset_Boiler) ;
  Modelica.Blocks.Continuous.FirstOrder firstOrder1(k=1) ;
  Modelica.Blocks.Continuous.LimPID PID(
    Ti=1,
    controllerType=Modelica.Blocks.Types.SimpleController.P,
    yMax=Q_n_Boiler,
    k=Q_n_Boiler,
    yMin=0,
    initType=Modelica.Blocks.Types.Init.InitialOutput,
    y_start=Q_n_Boiler) ;
  Modelica.Blocks.Logical.Switch switch3 ;
  Modelica.Blocks.Sources.RealExpression realExpression(y=0) ;
  Modelica.Blocks.Sources.RealExpression electricityPrice(y=simCenter.electricityPrice.y1) ;
  Modelica.Blocks.Logical.GreaterThreshold hysteresis(threshold=Price_Threshold) ;
  Modelica.Blocks.Logical.And and2 ;
equation
  uHigh_CHP = if control_SoC then SoCHigh_CHP else THigh_CHP;
  uLow_CHP = if control_SoC then SoCLow_CHP else TLow_CHP;
  uHigh_Boiler = if control_SoC then SoCHigh_Boiler else THigh_Boiler;
  uLow_Boiler = if control_SoC then SoCLow_Boiler else TLow_Boiler;
  uset_Boiler = if control_SoC then SOCset_Boiler else Tset_Boiler;
  connect(hysteresis_CHP.y, Not.u) ;
  connect(uLow.y, hysteresis_CHP.uLow) ;
  connect(uHigh.y, hysteresis_CHP.uHigh) ;
  connect(Q_CHP1.y, switch1.u1) ;
  connect(onOffRelais.y, switch1.u2) ;
  connect(uHigh1.y, hysteresis_boiler.uHigh) ;
  connect(uLow1.y, hysteresis_boiler.uLow) ;
  connect(hysteresis_boiler.y, Not1.u) ;
  connect(zero.y, switch1.u3) ;
  connect(T, hysteresis_CHP.u) ;
  connect(SoC, hysteresis_CHP.u) ;
  connect(SoC, hysteresis_boiler.u) ;
  connect(T, hysteresis_boiler.u) ;
  connect(switch1.y, Q_flow_set_CHP) ;
  connect(SoC, firstOrder1.u) ;
  connect(firstOrder1.y, PID.u_m) ;
  connect(max_Storage_Heat.y, PID.u_s) ;
  connect(PID.y, switch3.u1) ;
  connect(realExpression.y, switch3.u3) ;
  connect(switch3.y, Q_flow_set_boiler) ;
  connect(Not.y, and2.u1) ;
  connect(and2.y, onOffRelais.u) ;
  connect(hysteresis.y, and2.u2) ;
  connect(electricityPrice.y, hysteresis.u) ;
  connect(Not1.y, switch3.u2) 
  ;
end ControlBoilerCHP_modulatingBoiler_PriceLed;

within TransiEnt.Producer.Combined.SmallScaleCHP.SmallScaleCHP_simple.Control;
model Control_BoilerCHP_simple_HeatLed "Simple 2-point-controller for a heat led CHP system based on SoC or temperature of a heat storage"
  extends TransiEnt.Producer.Combined.SmallScaleCHP.SmallScaleCHP_simple.Control.Base.ControlBoilerCHP_Base;
  extends TransiEnt.Basics.Icons.Controller;




  parameter SI.Temperature TLow_CHP=353.15 "Storage charging level for CHP switch on" ;
  parameter SI.Temperature THigh_CHP=357.15 "Storage charging level for CHP switch off" ;
  parameter SI.Temperature TLow_Boiler=347.15 "Storage charging level for boiler switch on" ;
  parameter SI.Temperature THigh_Boiler=355.15 "Storage charging level for boiler switch off" ;
  parameter Real SoCLow_CHP=0.5 "SoC limit to switch on the CHP" ;
  parameter Real SoCHigh_CHP=1 "SoC limit to switch off the CHP" ;
  parameter Real SoCLow_Boiler=0.2 "SoC limit to switch on the boiler" ;
  parameter Real SoCHigh_Boiler=0.7 "SoC limit to switch off the boiler" ;
  parameter Real t_min_on_CHP=3600 "Minimum on time after startup of the CHP" ;
  parameter Real t_min_off_CHP=3600 "Minimum off time after shutdown of the CHP" ;




  Real uHigh_CHP;
  Real uLow_CHP;
  Real uHigh_Boiler;
  Real uLow_Boiler;




  Modelica.Blocks.Logical.Switch switch1 ;
  Modelica.Blocks.Sources.RealExpression zero(y=0) ;
  Modelica.Blocks.Logical.Not Not ;
  Modelica.Blocks.Sources.RealExpression uHigh(y=uHigh_CHP) ;
  Modelica.Blocks.Sources.RealExpression uLow(y=uLow_CHP) ;
  TransiEnt.Basics.Blocks.Hysteresis_inputVariable hysteresis_HP ;
  TransiEnt.Basics.Blocks.OnOffRelais onOffRelais(
    init_state=2,
    t_min_on=t_min_on_CHP,
    t_min_off=t_min_off_CHP) ;
  Modelica.Blocks.Sources.RealExpression Q_CHP(y=Q_n_CHP) ;
  Modelica.Blocks.Logical.Switch switch2 ;
  Modelica.Blocks.Sources.RealExpression zero1(y=0) ;
  Modelica.Blocks.Sources.RealExpression Q_Boiler(y=Q_n_Boiler) ;
  TransiEnt.Basics.Blocks.Hysteresis_inputVariable hysteresis_heater ;
  Modelica.Blocks.Sources.RealExpression uHigh1(y=uHigh_Boiler) ;
  Modelica.Blocks.Sources.RealExpression uLow1(y=uLow_Boiler) ;
  Modelica.Blocks.Logical.Not Not1 ;
equation
  uHigh_CHP = if control_SoC then SoCHigh_CHP else THigh_CHP;
  uLow_CHP = if control_SoC then SoCLow_CHP else TLow_CHP;
  uHigh_Boiler = if control_SoC then SoCHigh_Boiler else THigh_Boiler;
  uLow_Boiler = if control_SoC then SoCLow_Boiler else TLow_Boiler;
  connect(hysteresis_HP.y,Not. u) ;
  connect(uLow.y,hysteresis_HP. uLow) ;
  connect(uHigh.y,hysteresis_HP. uHigh) ;
  connect(Not.y,onOffRelais. u) ;
  connect(Q_CHP.y, switch1.u1) ;
  connect(onOffRelais.y,switch1. u2) ;
  connect(zero1.y,switch2. u3) ;
  connect(uHigh1.y,hysteresis_heater. uHigh) ;
  connect(uLow1.y,hysteresis_heater. uLow) ;
  connect(hysteresis_heater.y,Not1. u) ;
  connect(Not1.y,switch2. u2) ;
  connect(zero.y,switch1. u3) ;
  connect(Q_Boiler.y, switch2.u1) ;
  connect(T, hysteresis_HP.u) ;
  connect(SoC, hysteresis_HP.u) ;
  connect(SoC, hysteresis_heater.u) ;
  connect(T, hysteresis_heater.u) ;
  connect(switch2.y, Q_flow_set_boiler) ;
  connect(switch1.y, Q_flow_set_CHP) 
  ;
end Control_BoilerCHP_simple_HeatLed;

