partial model PartialNaturalGasUnit "Adds a gas interface with a mass flow defining boundary to child components"




  extends TransiEnt.Basics.Icons.IndustryPlant;




  outer SimCenter simCenter;




  parameter TILMedia.VLEFluidTypes.BaseVLEFluid mediumGas=simCenter.gasModel1
                                                                           ;
  parameter Boolean useGasPort=true "True if gas port shall be used" ;
  parameter Boolean useSecondGasPort=false ;




  TransiEnt.Components.Boundaries.Gas.BoundaryRealGas_hxim_flow massFlowSink(
    m_flow_nom=0,
    p_nom=1000,
    m_flow_const=1,
    h_const=0,
    variable_m_flow=true,
    medium=mediumGas) if useGasPort ;
  TransiEnt.Components.Sensors.RealGas.NCVSensor      vleNCVSensor(flowDefinition=3) if useGasPort  ;








  TransiEnt.Basics.Interfaces.Gas.RealGasPortIn gasPortIn(Medium=mediumGas,m_flow(start=0)) if useGasPort ;
  TransiEnt.Basics.Interfaces.General.MassFlowRateOut m_flow_gas ;
  TransiEnt.Components.Boundaries.Gas.BoundaryRealGas_pTx massFlowSink_2(m_flow_nom=0, medium=mediumGas) if useSecondGasPort ;
  TransiEnt.Components.Sensors.RealGas.NCVSensor vleNCVSensor_2(flowDefinition=3) if useSecondGasPort ;
  TransiEnt.Basics.Interfaces.Gas.RealGasPortIn gasPortIn_2(Medium=mediumGas, m_flow(start=0)) if useSecondGasPort ;
  Modelica.Blocks.Sources.RealExpression m_flow_gas_2_var(y=massFlowSink_2.gasPort.m_flow) if useSecondGasPort ;
  Modelica.Blocks.Math.Product H_flow_secondGasPort ;
  Modelica.Blocks.Sources.RealExpression m_flow_gas_2_const(y=0) if not useSecondGasPort ;
  Modelica.Blocks.Routing.RealPassThrough m_flow_gas_2 ;
  Modelica.Blocks.Sources.RealExpression NCV_2_const(y=0) if not useSecondGasPort ;
  Modelica.Blocks.Routing.RealPassThrough NCV_2 ;
equation




  if useGasPort then
  connect(gasPortIn, vleNCVSensor.gasPortIn) ;
  connect(vleNCVSensor.gasPortOut, massFlowSink.gasPort) ;
  end if;
  connect(massFlowSink.m_flow, m_flow_gas) ;
  if useSecondGasPort then
    connect(gasPortIn_2, vleNCVSensor_2.gasPortIn) ;
    connect(vleNCVSensor_2.gasPortOut, massFlowSink_2.gasPort) ;
    connect(vleNCVSensor_2.NCV, NCV_2.u) ;
    connect(m_flow_gas_2_var.y, m_flow_gas_2.u) ;
  else
    connect(m_flow_gas_2_const.y, m_flow_gas_2.u) ;
    connect(NCV_2_const.y, NCV_2.u) ;
  end if;
  connect(m_flow_gas_2.y, H_flow_secondGasPort.u1) ;
  connect(NCV_2.y, H_flow_secondGasPort.u2) 
             ;
