partial model PartialBalancingPowerProvider "Abstract model of any kind of electric balancing power provider with statistics and control input"
extends TransiEnt.Basics.Icons.PartialModel;




  parameter SI.Power P_n=300e6 "Nominal power of plant"                     ;
  parameter Boolean isPrimaryControlActive = true ;
  parameter Boolean isSecondaryControlActive = false ;
  parameter Boolean isExternalSecondaryController=true "False, provider generates its own control setpoint (only for lumped plants)"
                                                                                                  ;
  parameter SI.Time t_SB_act=simCenter.t_SB_act "Maximum reaction time for SB" ;
  parameter Modelica.Units.SI.Power P_el_grad_max_SB=0.02*P_n/60 "Maximum power gradient for secondary balancing (default: 2%/min)" ;
  parameter EnergyResource typeOfBalancingPowerResource=EnergyResource.Conventional "Type of energy resource for global model statistics"  ;




  outer TransiEnt.ModelStatistics modelStatistics;
  outer TransiEnt.SimCenter simCenter;
TransiEnt.Basics.Interfaces.Electrical.ElectricPowerIn P_SB_set  if isSecondaryControlActive and isExternalSecondaryController "Secondary balancing setpoint"
                                                                                                  ;
protected
  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerIn P_SB_set_internal "Needed to connect to conditional connector for active power";

public
  TransiEnt.Components.Statistics.Collectors.LocalCollectors.CollectElectricPower generatedSBP ;
  TransiEnt.Components.Statistics.Collectors.LocalCollectors.CollectElectricPower collectSBPOffer[2] ;
  TransiEnt.Components.Statistics.Collectors.LocalCollectors.CollectElectricPower generatedPBP ;
  TransiEnt.Components.Statistics.Collectors.LocalCollectors.CollectElectricPower collectPBPOffer[2] ;

  replaceable TransiEnt.Producer.Electrical.Controllers.PrimaryBalancingController primaryBalancingController(
    Td_GradientLimiter=simCenter.Td,
    useThresh=simCenter.useThresh,
    thres=simCenter.thres,
    k_part=if isPrimaryControlActive then 1 else 0,
    P_n=P_n) constrainedby TransiEnt.Producer.Electrical.Controllers.Base.PartialPrimaryBalancingController ;
  replaceable TransiEnt.Components.Sensors.MechanicalFrequency gridFrequencySensor(final isDeltaMeasurement=true) constrainedby TransiEnt.Components.Sensors.PartialFrequency ;
  replaceable TransiEnt.Producer.Electrical.Base.ControlPower.IdealControlOffer controlPowerModel(P_SB_set=P_SB_set_internal) constrainedby TransiEnt.Producer.Electrical.Base.ControlPower.PartialBalancingPowerPotential ;
  Real P_SB_set_star=P_SB_set_internal/P_n;
equation

  generatedPBP.powerCollector.P = controlPowerModel.P_pr_provided;
  collectPBPOffer[1].powerCollector.P = controlPowerModel.P_pr_pos_offer;
  collectPBPOffer[2].powerCollector.P = controlPowerModel.P_pr_neg_offer;

  generatedSBP.powerCollector.P = controlPowerModel.P_sec_provided;
  collectSBPOffer[1].powerCollector.P = controlPowerModel.P_sec_pos_offer;
  collectSBPOffer[2].powerCollector.P = controlPowerModel.P_sec_neg_offer;
  if not isExternalSecondaryController or not isSecondaryControlActive then
    P_SB_set_internal = 0;
  end if;

  connect(gridFrequencySensor.f, primaryBalancingController.delta_f) ;
  connect(modelStatistics.primBalPowerCollector[typeOfBalancingPowerResource],generatedPBP.powerCollector);
  connect(modelStatistics.primBalPowerOfferCollector, collectPBPOffer.powerCollector);

  connect(P_SB_set_internal, P_SB_set);
  connect(modelStatistics.secBalPowerCollector[typeOfBalancingPowerResource],generatedSBP.powerCollector);
  connect(modelStatistics.secBalPowerOfferCollector, collectSBPOffer.powerCollector)
;
end PartialBalancingPowerProvider;

