  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerOut P_set_Block_1 ;
  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerOut P_set_Block_2 ;




  Modelica.Units.SI.Power P_set_sc;
equation




  P_set_sc=abs(P_set);
  if P_set_sc<=P_max_Block_1 then 
    P_set_Block_1=P_set;        
    P_set_Block_2=0;
  elseif P_max_Block_1<P_set_sc and P_set_sc<(P_max_Block_1+P_max_Block_2) then 
    P_set_Block_1=-1*P_max_Block_1;
    P_set_Block_2=-1*(P_set_sc-P_max_Block_1);
  else  
    P_set_Block_1=-1*P_max_Block_1;
    P_set_Block_2=-1*P_max_Block_2;
  end if
  ;
end SimpleTwoBlockCoordination;

