model LumpedGridGenerators "Lumped model of a number of generators for the use in a non-detailed electric grid model (including primary and secondary control models)"




  extends TransiEnt.Producer.Electrical.Base.PartialDispatchablePowerPlant(redeclare model ProducerCosts = TransiEnt.Components.Statistics.ConfigurationData.PowerProducerCostSpecs.BrownCoal);
  extends TransiEnt.Producer.Electrical.Base.ControlPower.PartialBalancingPowerProvider(
      final typeOfBalancingPowerResource=typeOfResource,
      primaryBalancingController(
      P_n=P_el_n,
      providedDroop=delta_pr,
      k_part=k_pr,
      maxGradientPrCtrl=P_pr_grad_max_star,
      maxValuePrCtrl=P_pr_max_star),
      controlPowerModel(
      P_n=P_el_n,
      P_el_is = P_el_is,
      P_pr_max=primaryBalancingController.maxValuePrCtrl,
      P_grad_max_star=P_el_grad_max_SB,
      is_running=is_running,
      P_PB_set=primaryBalancingController.P_PBP_set,
      P_SB_set=secondaryBalancingController.y),
      final isExternalSecondaryController=false,
    redeclare final TransiEnt.Components.Sensors.MechanicalFrequency gridFrequencySensor(isDeltaMeasurement=true));





 parameter SI.Time T_tc = simCenter.T_grid "Time constant of plant (For easy definition of J)" ;
  parameter SI.Inertia J=P_el_n*T_tc/(2*simCenter.f_n*Modelica.Constants.pi)^2 "Lumped moment of inertia of whole power plant" ;

  parameter Integer nSubgrid=2 "Index of subgrid for moment of inertia statistics"  ;

  parameter Real delta_pr=0.2 "Value used if plantType is set to 'Provided'" ;
  parameter Real P_pr_grad_max_star=0.02/30 "Two percent of design case power in 30s" ;
  parameter Real P_pr_max_star=0.2 "Two percent of design case power" ;
  parameter Real k_pr=1 "Participation factor primary control"   ;

  parameter Real P_sec_grad_max_star=0.12/60 "Maximum secondary power gradient (= 12% in five Minutes)"  ;
  parameter Real beta=1 "Gain of secondary balancing power"  ;
  parameter Real T_r=20 "Time constant of secondary balancing power"    ;
  parameter Real lambda_sec=1 "Sub grid participation factor"    ;

  parameter Boolean fixedStartValue_w = false "Whether or not the start value of the angular velocity of the plants mechanical components is fixed"
   ;
   Real delta_P_star = (P_el_set+P_el_is)/P_el_n;




  TransiEnt.Grid.Electrical.SecondaryControl.SecondaryBalancingController secondaryBalancingController(
    T_r=T_r,
    beta=beta,
    K_r=lambda_sec,
    is_singleton=false) ;
  TransiEnt.Components.Boundaries.Mechanical.Power Turbine ;
  replaceable TransiEnt.Components.Electrical.Machines.ActivePowerGenerator Generator(eta=1) constrainedby TransiEnt.Components.Electrical.Machines.Base.PartialActivePowerGenerator ;
   replaceable TransiEnt.Components.Electrical.Machines.ExcitationSystemsVoltageController.DummyExcitationSystem Exciter constrainedby TransiEnt.Components.Electrical.Machines.ExcitationSystemsVoltageController.PartialExcitationSystem ;
  TransiEnt.Components.Mechanical.ConstantInertia MechanicalConnection(
    omega(fixed=fixedStartValue_w, start=2*simCenter.f_n*Modelica.Constants.pi),
    J=J,
    nSubgrid=nSubgrid) ;
  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerIn P_tie_is "Actual tie line power" ;
  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerIn P_tie_set "Set point tie line power" ;
  Modelica.Blocks.Math.Sum sum1(nin=3) ;
  Modelica.Blocks.Continuous.FirstOrder PT1Transient(k=1,
    y_start=0,
    T=0.632/(P_sec_grad_max_star),
    initType=Modelica.Blocks.Types.Init.InitialOutput)
    ;
equation




  is_running = true "continuous plant";
  eta = eta_total;




  connect(Turbine.mpp,MechanicalConnection. mpp_a) ;
  connect(MechanicalConnection.mpp_b,Generator. mpp) ;
  connect(gridFrequencySensor.mpp,MechanicalConnection. mpp_b) ;
  connect(Generator.epp, epp) ;
  connect(P_el_set, sum1.u[1]) ;
  connect(primaryBalancingController.P_PBP_set, sum1.u[2]) ;
  connect(gridFrequencySensor.f, secondaryBalancingController.u) ;
  connect(P_tie_is, secondaryBalancingController.P_tie_is) ;
  connect(secondaryBalancingController.P_tie_set, P_tie_set) ;
  connect(sum1.y, Turbine.P_mech_set) ;
  connect(secondaryBalancingController.y, PT1Transient.u) ;
  connect(PT1Transient.y, sum1.u[3]) ;
  connect(Exciter.epp1, epp) ;
  connect(Exciter.y, Generator.E_input) 
     ;
end LumpedGridGenerators;

