model FourthOrderPlant "Transient behaviour by multiple first order systems according to VDI 3508, no states, no balancing controller"




  extends TransiEnt.Producer.Electrical.Base.PartialDispatchablePowerPlant(eta_total=Eff, P_el_n=
                                                                                                P_n);





  parameter Real Tu=60  ;
  parameter Real Tg=250 ;
  parameter Real Ts=130 ;

  parameter Real Eff=0.40 "Electric efficiency of the power plant"
    ;
  parameter Real eta_gen=1 "Efficiency of the generator"
    ;
  parameter Modelica.Units.SI.Power P_n "Nominal power in W" ;
  parameter Real Q_br_n = P_n / 0.40 "Rated thermal input"
    ;
  parameter Real alpha_HP_LP=0.162  ;

  parameter SI.Inertia J=10*P_el_n/(100*3.14)^2 "Lumped moment of inertia of whole power plant" ;

  parameter Integer nSubgrid=1 "Index of subgrid for moment of inertia statistics" ;

  parameter Boolean fixedStartValue_w = false "Whether or not the start value of the angular velocity of the plants mechanical components is fixed"
   ;




     Real delta_P_star = (P_el_set+P_el_is)/P_el_n;
  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerIn P_el_set "Electric power setpoint" ;
  Modelica.Blocks.Sources.RealExpression ValveOpening(y=1)
    ;
  Modelica.Blocks.Continuous.FirstOrder firstOrder(T=Tg/1.5)
    ;
  Modelica.Blocks.Continuous.FirstOrder firstOrder1(T=2*Tu)
    ;
  Modelica.Blocks.Continuous.Integrator integrator(k=1/Ts)
    ;
  Modelica.Blocks.Math.Product product1 ;
  Modelica.Blocks.Math.Feedback feedback
    ;
  Modelica.Blocks.Continuous.FirstOrder HPturbine(T=0.2, k=alpha_HP_LP)
    ;
  Modelica.Blocks.Continuous.FirstOrder LPturbine(T=25, k=1 - alpha_HP_LP)
    ;
  Modelica.Blocks.Math.Gain nominalToRelativeConverter(k=1/Q_br_n)
    ;
  Modelica.Blocks.Math.Gain relativeToNominal(k=1*P_n)
    ;
  Modelica.Blocks.Math.Add sum ;
  Modelica.Blocks.Math.Gain efficiency(k=1/eta_total) ;
  TransiEnt.Components.Boundaries.Mechanical.Power MechanicalBoundary(change_sign=true) ;
  TransiEnt.Components.Mechanical.ConstantInertia MechanicalConnection(
    omega(fixed=fixedStartValue_w, start=2*simCenter.f_n*Modelica.Constants.pi),
    J=J,
    nSubgrid=nSubgrid,
    P_n=P_el_n) ;
  replaceable TransiEnt.Components.Electrical.Machines.ActivePowerGenerator Generator(eta=eta_gen)  constrainedby TransiEnt.Components.Electrical.Machines.Base.PartialActivePowerGenerator "Choice of generator model. The generator model must match the power port." ;
  replaceable TransiEnt.Components.Electrical.Machines.ExcitationSystemsVoltageController.DummyExcitationSystem Exciter constrainedby TransiEnt.Components.Electrical.Machines.ExcitationSystemsVoltageController.PartialExcitationSystem "Choice of excitation system model with voltage control" ;
equation




  is_running = true "continuous plant";
  eta = eta_total "Constant efficiency";




  connect(firstOrder.y, firstOrder1.u) ;
  connect(ValveOpening.y, product1.u2) ;
  connect(integrator.y, product1.u1) ;
  connect(firstOrder1.y, feedback.u1) ;
  connect(integrator.u, feedback.y) ;
  connect(product1.y, feedback.u2) ;
  connect(product1.y, HPturbine.u) ;
  connect(product1.y, LPturbine.u) ;
  connect(firstOrder.u, nominalToRelativeConverter.y) ;
  connect(HPturbine.y, sum.u2) ;
  connect(LPturbine.y, sum.u1) ;
  connect(efficiency.y, nominalToRelativeConverter.u) ;
  connect(P_el_set, efficiency.u) ;
  connect(relativeToNominal.u, sum.y) ;
  connect(Generator.epp, epp) ;
  connect(MechanicalConnection.mpp_b, Generator.mpp) ;
  connect(MechanicalBoundary.mpp, MechanicalConnection.mpp_a) ;
  connect(relativeToNominal.y, MechanicalBoundary.P_mech_set) ;
  connect(Exciter.epp1, epp) ;
  connect(Exciter.y, Generator.E_input) 
  ;
end FourthOrderPlant;

