model SecondOrderPlant "Second order transient behaviour, no states, no additional controller"




  extends TransiEnt.Producer.Electrical.Base.PartialDispatchablePowerPlant;





  parameter Real P_el_max = 1.00 "Maximum load in % of nominal power (decimal expression)" ;
  parameter Real P_el_min = 0.30 "Minimum load in % of nominal power (decimal expression)" ;
  parameter Real P_el_grad= 0.025 "Ramp rate in % of nominal power per minute (decimal expression)" ;
  parameter TransiEnt.Producer.Electrical.Base.PartloadEfficiency.PartloadEfficiencyCharacteristic PartLoadCharLine=TransiEnt.Producer.Electrical.Base.PartloadEfficiency.ConstantEfficiency() ;
  parameter Real eta_gen=1 "Efficiency of the generator"
    ;

  parameter SI.Inertia J=10*P_el_n/(100*3.14)^2 "Lumped moment of inertia of whole power plant" ;

  parameter Integer nSubgrid=1 "Index of subgrid for moment of inertia statistics" ;

  parameter Boolean fixedStartValue_w = false "Whether or not the start value of the angular velocity of the plants mechanical components is fixed"
   ;




  Real delta_P_star = (P_el_set+P_el_is)/P_el_n;
  Real delta_f_star = (epp.f-simCenter.f_n)/simCenter.f_n;




  Modelica.Blocks.Continuous.FirstOrder P_el_net(                        k=1, T=0.5*((0.632/P_el_grad)*60))
    ;
  Modelica.Blocks.Continuous.FirstOrder Q_flow_source(                        k=
       1, T=0.5*((0.632/P_el_grad)*60))
          ;
  Modelica.Blocks.Math.Gain signChanger(k=-1)         ;
  Modelica.Blocks.Tables.CombiTable1Ds eta_rel(
    columns={2},
    table=PartLoadCharLine.CL_eta_P,
    smoothness=Modelica.Blocks.Types.Smoothness.ContinuousDerivative) ;
  Modelica.Blocks.Sources.RealExpression nominalPower(y=P_el_n) ;
  Modelica.Blocks.Math.Division relativeLoad ;
  Modelica.Blocks.Math.Division Q_flow_set ;
  Modelica.Blocks.Math.Product product ;
  Modelica.Blocks.Sources.RealExpression eta_max(y=eta_total) "maximum efficiency (nominal)" ;
  Modelica.Blocks.Math.Product eta_is ;
  TransiEnt.Components.Boundaries.Mechanical.Power MechanicalBoundary(change_sign=true) ;
  TransiEnt.Components.Mechanical.ConstantInertia MechanicalConnection(
    omega(fixed=fixedStartValue_w, start=2*simCenter.f_n*Modelica.Constants.pi),
    J=J,
    nSubgrid=nSubgrid,
    P_n=P_el_n) ;
  replaceable TransiEnt.Components.Electrical.Machines.ActivePowerGenerator Generator constrainedby TransiEnt.Components.Electrical.Machines.Base.PartialActivePowerGenerator(eta=eta_gen) ;
   replaceable TransiEnt.Components.Electrical.Machines.ExcitationSystemsVoltageController.DummyExcitationSystem Exciter constrainedby TransiEnt.Components.Electrical.Machines.ExcitationSystemsVoltageController.PartialExcitationSystem ;
equation




  is_running = true "continuous plant";
  eta = eta_is.y "Constant efficiency";




  connect(Q_flow_source.y, P_el_net.u) ;
  connect(P_el_set, signChanger.u) ;
  connect(eta_rel.u, relativeLoad.y) ;
  connect(nominalPower.y, relativeLoad.u2) ;
  connect(P_el_net.y, product.u1) ;
  connect(Q_flow_source.u, Q_flow_set.y) ;
  connect(signChanger.y, relativeLoad.u1) ;
  connect(signChanger.y, Q_flow_set.u1) ;
  connect(Q_flow_set.u2, eta_is.y) ;
  connect(eta_max.y, eta_is.u2) ;
  connect(eta_rel.y[1], eta_is.u1) ;
  connect(eta_is.y, product.u2) ;
  connect(MechanicalConnection.mpp_b,Generator. mpp) ;
  connect(MechanicalBoundary.mpp,MechanicalConnection. mpp_a) ;
  connect(Generator.epp, epp) ;
  connect(product.y, MechanicalBoundary.P_mech_set) ;
  connect(Exciter.epp1, epp) ;
  connect(Exciter.y, Generator.E_input) 
  ;
end SecondOrderPlant;

