model SimplePowerPlant "No transient behaviuor, no operating states, constant efficiency (with optional primary balancing controller)"




  extends TransiEnt.Producer.Electrical.Base.PartialDispatchablePowerPlant;
  extends TransiEnt.Producer.Electrical.Base.ControlPower.PartialBalancingPowerProvider(
    final typeOfBalancingPowerResource=typeOfResource,
    final P_n=P_el_n,
    primaryBalancingController(P_n=P_el_n, use_SlewRateLimiter=false),
    controlPowerModel(
      P_pr_max=primaryBalancingController.P_pr_max,
      isSecondaryControlActive=false,
      P_el_is=P_el_is,
      is_running=is_running,
      P_PB_set=primaryBalancingController.P_PBP_set,
      final P_n=P_el_n),
    redeclare final TransiEnt.Components.Sensors.MechanicalFrequency gridFrequencySensor(final isDeltaMeasurement=true));





  parameter SI.Inertia J=10*P_el_n/(100*3.14)^2 "Lumped moment of inertia of whole power plant" ;

  parameter Integer nSubgrid=1 "Index of subgrid for moment of inertia statistics" ;

  parameter Boolean fixedStartValue_w = false "Whether or not the start value of the angular velocity of the plants mechanical components is fixed"
   ;
  parameter SI.Efficiency eta_gen=1 "Generator efficiency" ;
  parameter Boolean useFirstOrderPrimaryCntrl = true "use first order block to delay primary control power" ;




  Real delta_P_star = (P_el_set+P_el_is)/P_el_n;
  replaceable TransiEnt.Components.Electrical.Machines.ActivePowerGenerator Generator(eta=eta_gen) constrainedby TransiEnt.Components.Electrical.Machines.Base.PartialActivePowerGenerator "Choice of generator model. The generator model must match the power port." ;
  replaceable TransiEnt.Components.Electrical.Machines.ExcitationSystemsVoltageController.DummyExcitationSystem Exciter constrainedby TransiEnt.Components.Electrical.Machines.ExcitationSystemsVoltageController.PartialExcitationSystem "Choice of excitation system model with voltage control" ;
  replaceable TransiEnt.Components.Mechanical.ConstantInertia MechanicalConnection(
    omega(fixed=fixedStartValue_w, start=2*simCenter.f_n*Modelica.Constants.pi),
    J=J,
    nSubgrid=nSubgrid,
    P_n=P_el_n) constrainedby TransiEnt.Components.Mechanical.Base.PartialMechanicalConnection ;
  Modelica.Blocks.Math.Add      targetSum       ;
  TransiEnt.Components.Boundaries.Mechanical.Power Turbine ;
  TransiEnt.Basics.Blocks.FirstOrderWithGradientLim firstOrderWithGradientLim(
    Tau=1,
    initOption=1,
    evaluate_y_start=true) if useFirstOrderPrimaryCntrl
                           ;
  Modelica.Blocks.Sources.RealExpression maxGradient(y=primaryBalancingController.maxGradientPrCtrl*primaryBalancingController.P_n) if useFirstOrderPrimaryCntrl
                                                                                                                                    ;
  Modelica.Blocks.Sources.RealExpression minGrad(y=-primaryBalancingController.maxGradientPrCtrl*primaryBalancingController.P_n) if useFirstOrderPrimaryCntrl
                                                                                                                                 ;
  Modelica.Blocks.Math.Gain dummy(k=1) if not useFirstOrderPrimaryCntrl
                                       ;
equation




  is_running = true "continuous plant";
  eta = eta_total "Constant efficiency";




  connect(MechanicalConnection.mpp_b, Generator.mpp) ;
  connect(gridFrequencySensor.mpp, MechanicalConnection.mpp_b) ;
  connect(Generator.epp, epp) ;
  connect(Turbine.mpp, MechanicalConnection.mpp_a) ;
  connect(targetSum.y, Turbine.P_mech_set) ;
  connect(Exciter.y, Generator.E_input) ;
  connect(Exciter.epp1, epp) ;
  connect(firstOrderWithGradientLim.u, primaryBalancingController.P_PBP_set) ;
  connect(maxGradient.y, firstOrderWithGradientLim.maxGrad) ;
  connect(minGrad.y, firstOrderWithGradientLim.minGrad) ;
  connect(P_el_set, targetSum.u1) ;
  connect(firstOrderWithGradientLim.y, targetSum.u2) ;
  connect(dummy.y, targetSum.u2) ;
  connect(dummy.u, primaryBalancingController.P_PBP_set) 
  ;
end SimplePowerPlant;

