model PhotovoltaicModuleQS "PV Module for quasi stationary boundaries with constant efficiency"




  extends TransiEnt.Basics.Icons.SolarElectricalModel;




  parameter SI.Area A_module=1 "PV Module surface";
  parameter SI.Efficiency eta=0.2 "Total efficiency from radiation to power output";




  Modelica.Blocks.Math.Gain PVPower(k=-A_module*eta)
    ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Basic.VariableConductor variableConductor ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Sensors.PowerSensor PowerSensorPVPanel ;
  Modelica.Blocks.Math.Feedback feedback
    ;
  Modelica.ComplexBlocks.ComplexMath.ComplexToReal complexToReal
    ;
  Modelica.Blocks.Continuous.PI         integrator(k=10, T=1/230/230/1e-6)
    ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Basic.Ground ground ;
  Modelica.Blocks.Interfaces.RealInput u ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Interfaces.PositivePin currentP ;
equation




  connect(complexToReal.u, PowerSensorPVPanel.apparentPower) ;
  connect(complexToReal.re,feedback. u2) ;
  connect(feedback.y,integrator. u) ;
  connect(PVPower.y,feedback. u1) ;
  connect(variableConductor.pin_n,PowerSensorPVPanel. currentN) ;
  connect(ground.pin,variableConductor. pin_p) ;
  connect(variableConductor.pin_p,PowerSensorPVPanel. voltageN) ;
  connect(integrator.y,variableConductor. G_ref) ;
  connect(u, PVPower.u) ;
