model Windturbine "Pitch controlled wind turbine model based on cp-lambda characteristic"




  import TransiEnt;
  extends TransiEnt.Producer.Electrical.Wind.Base.PartialWindTurbine(P_el_n=3.5e6);




  parameter SI.Velocity v_wind_small = 0.1 "Wind velocity considered as negligible" ;
  parameter Real J = 12e6 "Moment of inertia of entire plant" ;
  final parameter SI.Length D_Rotor=Rotor.D "Rotor diameter of wind turbine" ;
  parameter TransiEnt.Producer.Electrical.Wind.Characteristics.VariableSpeed.BetzCoefficientApproximation turbineCharacteristics=TransiEnt.Producer.Electrical.Wind.Characteristics.VariableSpeed.MOD2() "Characteristic behaviour of betz factor" ;
  parameter TransiEnt.Producer.Electrical.Wind.Characteristics.VariableSpeed.WindSpeedOperationRanges operationRanges=TransiEnt.Producer.Electrical.Wind.Characteristics.VariableSpeed.ExampleTurbineRanges() "Wind speed operation ranges" ;
  parameter Modelica.Blocks.Types.SimpleController controllerType_p=.Modelica.Blocks.Types.SimpleController.PID "Type of controller"
                                                                                                    ;
  parameter Real k_p=5e-5 "Gain of controller" ;
  parameter SI.Time Ti_p=14 "Integral time constant of controller" ;
  parameter SI.Time Td_p=3.5 "Derivative time constant of controller" ;
  parameter Real yMax_p=30 "Upper limit of PI controlled beta setpoint" ;
  parameter Real yMin_p=0 "Lower limit of output" ;
  parameter Real beta_start "Setpoint for pitch angle" ;
  parameter SI.Velocity v_wind_start=10 "Setpoint for wind speed" ;




  final parameter SI.AngularVelocity omega_n=Rotor.lambda_opt*v_fullload*2/Rotor.D "Nominal angular velocity of rotor";
  final parameter SI.AngularVelocity omega_start=if v_wind_start > 12 then omega_n else if (v_wind_start > 4 and v_wind_start < 12) then (Rotor.lambda_opt/Rotor.D*2*v_wind_start) else 1e-3;
  final parameter Real v_fullload = (8*P_el_n/(Rotor.rho*Modelica.Constants.pi*Rotor.D^2*Rotor.cp_opt))^(1/3);
public
  SI.ActivePower P_el_is = -epp.P;
  Boolean is_running(start=true, fixed=true) "For continuous plants always true, for discontinous depending on state";




 replaceable
 TransiEnt.Components.Electrical.Machines.VariableSpeedActivePowerGenerator Generator(changeSign=true)  ;
  Base.WindturbineRotor Rotor(
    beta_start=beta_start,
    turbineCharacteristics=TransiEnt.Producer.Electrical.Wind.Characteristics.VariableSpeed.VariableWTG_WU(),
    v_fullLoad=operationRanges.v_fullLoad,
    P_el_n=P_el_n) ;
  Modelica.Blocks.Sources.RealExpression v_wind1(y=max(v_wind_small, v_wind_internal))
                                                                   ;
  TransiEnt.Producer.Electrical.Wind.Controller.PitchController pitchController(
    turbine=TransiEnt.Producer.Electrical.Wind.Characteristics.VariableSpeed.ExampleTurbineRanges(),
    k=k_p,
    Ti=Ti_p,
    yMax=yMax_p,
    yMin=yMin_p,
    controllerTypePitchCtrl=controllerType_p,
    v_wind=v_wind1.y,
    Td=Td_p,
    beta_start=beta_start) ;
  Modelica.Blocks.Sources.RealExpression omega_is(y=Rotor.omega)
    ;
  Modelica.Blocks.Sources.RealExpression P_is(y=P_el_is)    ;
  Modelica.Blocks.Sources.Constant P_set(k=P_el_n) ;
  TransiEnt.Producer.Electrical.Wind.Controller.TorqueController torqueController(
    v_wind=v_wind1.y,
    k_turbine=Rotor.k_turbine,
    J=Inertia.J,
    lambdaOpt=Rotor.lambda_opt,
    rho=Rotor.rho,
    radius=Rotor.D/2,
    cp_opt=Rotor.cp_opt,
    v_cutIn=operationRanges.v_cutIn,
    tau_n=P_el_n/omega_n) ;
  Modelica.Blocks.Sources.RealExpression wind_fullload(y=operationRanges.v_fullLoad)
    ;
  TransiEnt.Components.Mechanical.ConstantInertia Inertia(
    omega(start=omega_start),
    nSubgrid=1,
    J=J) ;
 replaceable
 TransiEnt.Components.Electrical.Machines.ExcitationSystemsVoltageController.DummyExcitationSystem Exciter constrainedby TransiEnt.Components.Electrical.Machines.ExcitationSystemsVoltageController.PartialExcitationSystem
                                                                                                              ;




equation




  is_running=not pitchController.halt.active;
  eta = Rotor.cp * Generator.eta;




  connect(Generator.epp, epp) ;
  connect(v_wind1.y, Rotor.v_wind) ;
  connect(omega_is.y, torqueController.omega_is) ;
  connect(P_set.y, pitchController.u_s) ;
  connect(P_is.y, pitchController.u_m) ;
  connect(wind_fullload.y, torqueController.wind_fullload) ;
  connect(Rotor.flange, Inertia.mpp_a) ;
  connect(Inertia.mpp_b, Generator.mpp) ;
  connect(torqueController.y, Generator.tau_set) ;
  connect(pitchController.beta_set, Rotor.beta_set) ;
  connect(Exciter.epp1, epp) ;
  connect(Exciter.y, Generator.E_input) 
    ;
end Windturbine;

