model GeometryCSTR "Geometry of CSTR"




  import Modelica.Constants.pi;




  parameter Modelica.Units.SI.Diameter D_i=1 "Inner Diameter of CSTR";
  parameter Modelica.Units.SI.Diameter D_o=1.1 "Outer Diameter of CSTR";
