end GeometryCSTR;

within TransiEnt.Producer.Gas.BiogasPlant.Base;
model PitchedBladeImpeller "stirrer model of a pitched blade Impeller"




  import TransiEnt;
  import      Modelica.Units.SI;
  import Const = Modelica.Constants;
  extends TransiEnt.Basics.Icons.Model;




  final parameter Real k_s=11 "proportionality constant of shear Rate to speed of rotation";




  parameter SI.Diameter d "diameter of agitator/impeller";
  parameter SI.Diameter D "diameter of StirredTankReactor";
  parameter SI.Frequency n "stirring speed as revelutions per second";
  parameter SI.Height h "height of impeller blade";
  parameter Integer Z "number of blades";
  parameter SI.Angle alpha=Const.pi/4 "pitch angle of blades";
  parameter Boolean useBaffles=false "true if baffles are used to redirect flow";
  parameter SI.Length b_S      if useBaffles "baffle width" ;




  outer TransiEnt.SimCenter simCenter;




  input SI.Density rho "input for density of the medium" ;
  input SI.DynamicViscosity eta "input for efficiency of impeller" ;
  SI.ReynoldsNumber Re "Reynolds number in a Stirred Tank";
  Real Ne "Newton or Power number";
  SI.FroudeNumber Fr "Froude number";
  SI.Power P "Power demand of stirring";
  SI.Frequency gamma "shear rate";
  Real C1 "geometrical coefficient in Nusselt-Equation";
  Real C2 "geometrical coefficient in Nusselt-Equation";




  function PitchedBladeImpeller_Ne
    extends TransiEnt.Basics.Icons.Function;
    input Modelica.Units.SI.ReynoldsNumber Re;
    input Boolean useBaffles;
    output Real Ne;
  algorithm
    if useBaffles then
      if 1 < Re and Re < 24 then
        Ne := 80/Re;
      elseif 24 < Re and Re < 10^5 then
        Ne := 10/3;
      elseif Re > 10^5 then
        Ne := 10/3 "this is outside validity range";
      end if;
    else
      if 1 < Re and Re < 3.1 then
        Ne := 50/Re;
      elseif 3.1 < Re and Re < 553 then
        Ne := 4/(log(Re))^2;
      elseif 553 < Re and Re < 10^5 then
        Ne := 1/Re^0.1;
      elseif Re > 10^5 then
        Ne := 1/(10^0.5) "this is outside validity range";
      end if;
    end if
    ;
  end PitchedBladeImpeller_Ne;
  function PitchedBladeImpeller_C1
    extends TransiEnt.Basics.Icons.Function;
    input Modelica.Units.SI.Diameter D "Inner Diameter of CSTR";
    input Modelica.Units.SI.Diameter d "Diameter of stirrer";
    input Modelica.Units.SI.Height h "Height of stirrer blades";
    input Modelica.Units.SI.Angle alpha "Blade pitch angle";
    input Integer Z "Number of blades";
    output Real C1 "geometrical coefficient in Nusselt-Equation";
  protected
    constant Real relPos=1/3 "relative vertical position height over bottom/height of vessel";
  algorithm
    C1 := 0.54*(d/D)^(-0.25)*(h/D)^0.15*relPos^0.15*sin(alpha)^0.5*Z^0.15
    ;
  end PitchedBladeImpeller_C1;
  function PitchedBladeImpeller_C2
    extends TransiEnt.Basics.Icons.Function;
    input Modelica.Units.SI.Diameter D "Inner Diameter of CSTR";
    input Modelica.Units.SI.Diameter d "Diameter of stirrer";
    input Modelica.Units.SI.Height h "Height of stirrer blades";
    input Integer Z "Number of blades";
    output Real C2 "geometrical coefficient in Nusselt-Equation";
  protected
    constant Real relPos=1/3 "relative vertical position height over bottom/height of vessel";
  algorithm
    C2 := 0.825*(d/D)^(-0.25)*(h/D)^0.15*Z^0.15
    ;
  end PitchedBladeImpeller_C2;




equation
  Ne = PitchedBladeImpeller_Ne(Re, useBaffles);
  C1 = PitchedBladeImpeller_C1(
    D,
    d,
    h,
    alpha,
    Z);
  C2 = PitchedBladeImpeller_C2(
    D,
    d,
    h,
    Z);
  assert(
    Re > 1 and Re < 10^5,
    "Reynolds Number outside validity range",
    AssertionLevel.warning);
  gamma = k_s*n;
  Ne = P/(rho*n^3*d^5);
  Re = n*d^2*rho/eta;
  Fr = n^2*d/Const.g_n
  ;
end PitchedBladeImpeller;

within TransiEnt.Producer.Gas.BiogasPlant.Base.ADM1.ADM1_Functions;
function ADM1_Inhibition_BSM2
  "A Function calculating the inhibition Coefficients using constants from Rosén, C., & Jeppsson, U. (2006). Aspects on ADM1 Implementation within the BSM2 Framework."




  extends TransiEnt.Basics.Icons.Function;




  input Real pH "pH-Value";
  input Modelica.Units.SI.Concentration S_IN "Concentration of Inorganic Nitrogen";
  input TransiEnt.Producer.Gas.BiogasPlant.Base.ADM1.ADM1_Units.ConcentrationCOD S_h2 "Concentration of Hydrogen in solution";
  input Modelica.Units.SI.Concentration NH3 "Concentration of free Ammonia in solution";
  input String operationMode "mesophilic or thermophilic conditions";
  output Real[7] I "Inhibition Coefficients";




  replaceable Records.ADM1_parameters_BSM2 parameters ;
  final parameter ADM1_Units.ConcentrationCOD K_I_H2_c4=if operationMode == "thermophilic" then parameters.K_I_H2_c4_therm else parameters.K_I_H2_c4_meso "Inhibition Constant due to high Hydrogen Concentration affecting Valerate and Butyrate Degraders";
  final parameter ADM1_Units.ConcentrationCOD K_I_H2_pro=if operationMode == "thermophilic" then parameters.K_I_H2_pro_therm else parameters.K_I_H2_pro_meso "Inhibition Constant due to high Hydrogen Concentration affecting Propionate Degraders";
  final parameter Modelica.Units.SI.Concentration K_I_NH3=if operationMode == "thermophilic" then parameters.K_I_NH3_therm else parameters.K_I_NH3_meso "Inhibition Constant due to high Ammonia Concentration affecting Acetate Degraders";




protected
  Real I_IN "Inhibtion due to Nitrogen-Defficiency";
  Real I_pH;
  Real I_pH_ac;
  Real I_pH_h2 "Inhibition due to pH-Value";
  Real I_H2_fa;
  Real I_H2_c4;
  Real I_H2_pro "Inhibition due to Hydrogen-Concentration";
  Real I_NH3 "Inhibition due to Amonium-Concentration";
  Real I_su "composed Inhibition Coefficient affecting Sugar Degraders";
  Real I_aa "composed Inhibition Coefficient affecting Amino Acid Degraders";
  Real I_fa "composed Inhibition Coefficient affecting LCFA Degraders";
  Real I_c4 "composed Inhibition Coefficient affecting Valerate and Butyrate Degraders";
  Real I_pro "composed Inhibition Coefficient affecting Propionate Degraders";
  Real I_ac "composed Inhibition Coefficient affecting Acetate Degraders";
  Real I_h2 "composed Inhibition Coefficient affecting Hydrogen Degraders";




algorithm

  I_IN := S_IN/(S_IN + parameters.K_S_IN);

  I_pH := if pH < parameters.pH_UL then exp(-3*((pH - parameters.pH_UL)/(parameters.pH_UL - parameters.pH_LL))^2) else 1 "lower pH-Inhibition if pH Value below Uper Level (Parameters.pH_UL) affecting most microorganims";
  I_pH_ac := if pH < parameters.pH_UL_ac then exp(-3*((pH - parameters.pH_UL_ac)/(parameters.pH_UL_ac - parameters.pH_LL_ac))^2) else 1 "lower pH-Inhibition if pH Value below Uper Level (Parameters.pH_UL) affecting Acetate degraders";
  I_pH_h2 := if pH < parameters.pH_UL_h2 then exp(-3*((pH - parameters.pH_UL_h2)/(parameters.pH_UL_h2 - parameters.pH_LL_h2))^2) else 1 "lower pH-Inhibition if pH Value below Uper Level (Parameters.pH_UL) affecting Hydrogen degraders";


  I_H2_fa := if operationMode == "mesophilic" and S_h2 > 0 then 1/(1 + S_h2/parameters.K_I_H2_fa_meso) else 1 "Inhibition due to high Hydrogen Concentration affecting LCFA degraders (only for mesophilic conditions)";
  I_H2_c4 := if S_h2 > 0 then 1/(1 + S_h2/K_I_H2_c4) else 1 "Inhibition due to high Hydrogen Concentration affecting Valerate and Butyrate degraders";
  I_H2_pro := if S_h2 > 0 then 1/(1 + S_h2/K_I_H2_pro) else 1 "Inhibition due to high Hydrogen Concentration affecting Propionate degraders ";
  I_NH3 := if NH3 > 0 then 1/(1 + NH3/K_I_NH3) else 1 "Inhibition due to high Ammonia Concentration affecting Acetate Degraders";

  I_su := I_IN*I_pH "Sugar Degraders are inhibited by Nitrogen Defficiency and low pH-Value";
  I_aa := I_IN*I_pH "Amino Acid Degraders are inhibited by Nitrogen Defficiency and low pH-Value";
  I_fa := I_IN*I_pH*I_H2_fa "LCFA Degraders are inhibited by Nitrogen Defficiency, low pH-Value and high Hydrogen Concentration";
  I_c4 := I_IN*I_pH*I_H2_c4 "Valerate/Butyrate Degraders are inhibited by Nitrogen Defficiency, low pH-Value and high Hydrogen Concentration";
  I_pro := I_IN*I_pH*I_H2_pro "Propionate Degraders are inhibited by Nitrogen Defficiency, low pH-Value and high Hydrogen Concentration";
  I_ac := I_IN*I_pH_ac*I_NH3 "Acetate Degraders are inhibited by Nitrogen Defficiency, low pH-Value and high Ammonia Concentration";
  I_h2 := I_IN*I_pH_h2 "Hydrogen Degraders are inhibited by Nitrogen Defficiency and low pH-Value";
  I := {I_su,I_aa,I_fa,I_c4,I_pro,I_ac,I_h2} "vector of inhibition Coefficients"
  ;
end ADM1_Inhibition_BSM2;

within TransiEnt.Producer.Gas.BiogasPlant.Base.ADM1.ADM1_Functions;
function ADM1_Inhibition_manureBulkowska
  "A Function calculating the inhibition Coefficients using constants from Bułkowska, K., et al. (2015). ADM1-based modeling of anaerobic codigestion of maize silage and cattle manure–calibration of parameters and model verification (part II)"




  extends TransiEnt.Basics.Icons.Function;




  input Real pH "pH-Value";
  input Modelica.Units.SI.Concentration S_IN "Concentration of Inorganic Nitrogen";
  input TransiEnt.Producer.Gas.BiogasPlant.Base.ADM1.ADM1_Units.ConcentrationCOD S_h2 "Concentration of Hydrogen in solution";
  input Modelica.Units.SI.Concentration NH3 "Concentration of free Ammonia in solution";
  input String operationMode "mesophilic or thermophilic conditions";
  output Real[7] I "Inhibition Coefficients";




  replaceable Records.ADM1_parameters_manure_bulkowska parameters ;
  final parameter ADM1_Units.ConcentrationCOD K_I_H2_c4=if operationMode == "thermophilic" then parameters.K_I_H2_c4_therm else parameters.K_I_H2_c4_meso "Inhibition Constant due to high Hydrogen Concentration affecting Valerate and Butyrate Degraders";
  final parameter ADM1_Units.ConcentrationCOD K_I_H2_pro=if operationMode == "thermophilic" then parameters.K_I_H2_pro_therm else parameters.K_I_H2_pro_meso "Inhibition Constant due to high Hydrogen Concentration affecting Propionate Degraders";
  final parameter Modelica.Units.SI.Concentration K_I_NH3=if operationMode == "thermophilic" then parameters.K_I_NH3_therm else parameters.K_I_NH3_meso "Inhibition Constant due to high Ammonia Concentration affecting Acetate Degraders";




protected
  Real I_IN "Inhibtion due to Nitrogen-Defficiency";
  Real I_pH;
  Real I_pH_ac;
  Real I_pH_h2 "Inhibition due to pH-Value";
  Real I_H2_fa;
  Real I_H2_c4;
  Real I_H2_pro "Inhibition due to Hydrogen-Concentration";
  Real I_NH3 "Inhibition due to Amonium-Concentration";
  Real I_su "composed Inhibition Coefficient affecting Sugar Degraders";
  Real I_aa "composed Inhibition Coefficient affecting Amino Acid Degraders";
  Real I_fa "composed Inhibition Coefficient affecting LCFA Degraders";
  Real I_c4 "composed Inhibition Coefficient affecting Valerate and Butyrate Degraders";
  Real I_pro "composed Inhibition Coefficient affecting Propionate Degraders";
  Real I_ac "composed Inhibition Coefficient affecting Acetate Degraders";
  Real I_h2 "composed Inhibition Coefficient affecting Hydrogen Degraders";




algorithm

  I_IN := S_IN/(S_IN + parameters.K_S_IN);

  I_pH := if pH < parameters.pH_UL then exp(-3*((pH - parameters.pH_UL)/(parameters.pH_UL - parameters.pH_LL))^2) else 1 "lower pH-Inhibition if pH Value below Uper Level (pH_UL) affecting most microorganims";
  I_pH_ac := if pH < parameters.pH_UL_ac then exp(-3*((pH - parameters.pH_UL_ac)/(parameters.pH_UL_ac - parameters.pH_LL_ac))^2) else 1 "lower pH-Inhibition if pH Value below Uper Level (pH_UL) affecting Acetate degraders";
  I_pH_h2 := if pH < parameters.pH_UL_h2 then exp(-3*((pH - parameters.pH_UL_h2)/(parameters.pH_UL_h2 - parameters.pH_LL_h2))^2) else 1 "lower pH-Inhibition if pH Value below Uper Level (pH_UL) affecting Hydrogen degraders";


  I_H2_fa := if operationMode == "mesophilic" and S_h2 > 0 then 1/(1 + S_h2/parameters.K_I_H2_fa_meso) else 1 "Inhibition due to high Hydrogen Concentration affecting LCFA degraders (only for mesophilic conditions)";
  I_H2_c4 := if S_h2 > 0 then 1/(1 + S_h2/K_I_H2_c4) else 1 "Inhibition due to high Hydrogen Concentration affecting Valerate and Butyrate degraders";
  I_H2_pro := if S_h2 > 0 then 1/(1 + S_h2/K_I_H2_pro) else 1 "Inhibition due to high Hydrogen Concentration affecting Propionate degraders ";
  I_NH3 := if NH3 > 0 then 1/(1 + NH3/K_I_NH3) else 1 "Inhibition due to high Ammonia Concentration affecting Acetate Degraders";

  I_su := I_IN*I_pH "Sugar Degraders are inhibited by Nitrogen Defficiency and low pH-Value";
  I_aa := I_IN*I_pH "Amino Acid Degraders are inhibited by Nitrogen Defficiency and low pH-Value";
  I_fa := I_IN*I_pH*I_H2_fa "LCFA Degraders are inhibited by Nitrogen Defficiency, low pH-Value and high Hydrogen Concentration";
  I_c4 := I_IN*I_pH*I_H2_c4 "Valerate/Butyrate Degraders are inhibited by Nitrogen Defficiency, low pH-Value and high Hydrogen Concentration";
  I_pro := I_IN*I_pH*I_H2_pro "Propionate Degraders are inhibited by Nitrogen Defficiency, low pH-Value and high Hydrogen Concentration";
  I_ac := I_IN*I_pH_ac*I_NH3 "Acetate Degraders are inhibited by Nitrogen Defficiency, low pH-Value and high Ammonia Concentration";
  I_h2 := I_IN*I_pH_h2 "Hydrogen Degraders are inhibited by Nitrogen Defficiency and low pH-Value";
  I := {I_su,I_aa,I_fa,I_c4,I_pro,I_ac,I_h2} "vector of inhibition Coefficients"
  ;
end ADM1_Inhibition_manureBulkowska;

within TransiEnt.Producer.Gas.BiogasPlant.Base.ADM1.ADM1_Functions;
function VantHoffEquation "applies the van't Hoff Equation to a temperature-sensitive equilibrium constant"




  extends TransiEnt.Basics.Icons.Function;
  import Modelica.Constants.R;




  input Real K_ref "Equilibrium constant at reference temperature";
  input Modelica.Units.SI.MolarEnergy deltH0 "Enthalpy of Reaction for determination of equilibrium";
  input Modelica.Units.SI.Temperature T "Temperature at which equilibrium constant is calculated";
  output Real K "Equilibrium constant at Temperature T";




protected
  final parameter Modelica.Units.SI.Temperature T_ref=298.15 "Reference Temperature for equilibrium constant";





algorithm
  K := K_ref*exp(deltH0/R*(1/T_ref - 1/T))
  ;
end VantHoffEquation;

