model HeatTransferInsideReactor_tubeBundle_array "Model calculating the heat transfered between fluid and heating system"




  final parameter Modelica.Units.SI.Area A=Modelica.Constants.pi*d*l "Area through which heat is transported by Convection";




  parameter Modelica.Units.SI.Diameter D=1 "inner Diameter of reactor";
  parameter Modelica.Units.SI.Diameter d=0.1 "tube diameter";
  parameter Modelica.Units.SI.Length l=Modelica.Constants.pi*(D - d);
  parameter Real n = 8 "number of turns of tube";
  parameter Integer N_cv = 8 "Number of control volumes";




  outer TransiEnt.Producer.Gas.BiogasPlant.MaterialValues.SuspensionProperties_pT fluidProperties;
  outer TransiEnt.SimCenter simCenter;




  ClaRa.Basics.Interfaces.HeatPort_a heat_solid[N_cv] ;
  ClaRa.Basics.Interfaces.HeatPort_b heat_fluid ;




  TILMedia.Internals.VLEFluidConfigurations.FullyMixtureCompatible.VLEFluid_pT vleFluidWall(
    T=sum(heat_solid.T)/N_cv,
    computeTransportProperties=true,
    deactivateTwoPhaseRegion=true,
    redeclare TILMedia.VLEFluidTypes.TILMedia_InterpolatedWater vleFluidType,
    p=101300) ;
  Modelica.Units.SI.NusseltNumber Nu=TransiEnt.Producer.Gas.BiogasPlant.HeatTransfer.ForcedConvection.NusseltCSTR_Coil(
      Re=Re,
      Pr=fluidProperties.Pr,
      eta=fluidProperties.eta,
      eta_w=eta_w,
      C2=C2,
      D=D,
      d=d) "Nusselt Number ";




  input Modelica.Units.SI.ReynoldsNumber Re ;
  input Real C2 ;
  Modelica.Units.SI.HeatFlowRate Q_flow[N_cv] "Heat flow rate from solid -> fluid";
  Modelica.Units.SI.TemperatureDifference dT[N_cv] "= solid.T - fluid.T";
  Modelica.Units.SI.CoefficientOfHeatTransfer alpha=Nu*fluidProperties.lambda/D "heat transfer coefficient of convection";
  Modelica.Units.SI.DynamicViscosity eta_w "Dynamic Viscosity of fluid at wall temperature";




equation
  dT =heat_solid.T .- heat_fluid.T;
  heat_solid.Q_flow = Q_flow;
  heat_fluid.Q_flow = -sum(Q_flow);
  Q_flow = A*alpha*dT;
  eta_w = fluidProperties.eta; 
  ;
end HeatTransferInsideReactor_tubeBundle_array;

within TransiEnt.Producer.Gas.BiogasPlant.HeatTransfer.ForcedConvection;
function NusseltCSTR_Coil
  "Function calculating Nusselt Number for Heat Transfer from coil to medium"




  import Modelica.Constants.pi;
  extends TransiEnt.Basics.Icons.Function;




  input Modelica.Units.SI.ReynoldsNumber Re "Reynols number inside CSTR";
  input Modelica.Units.SI.PrandtlNumber Pr "Prandtl number of medium at its temperature";
  input Modelica.Units.SI.DynamicViscosity eta "viscosity of medium at its temperature";
  input Modelica.Units.SI.DynamicViscosity eta_w "viscosity of medium at wall temperature";
  input Real C2 "geometrical Coefficient in Nusselt-Equation";
  input Modelica.Units.SI.Diameter D "Inner Diameter of Reactor";
  input Modelica.Units.SI.Diameter d "outer diameter of tube of coil";
  output Modelica.Units.SI.NusseltNumber Nu "Nusselt number inside CSTR";




  constant Real a=0.56;
  constant Real b=1/3;
  constant Real c=0.14;




algorithm
  Nu := C2*(d/D)^(-0.3)*Re^a*Pr^b*(eta/eta_w)^c
  ;
end NusseltCSTR_Coil;

within TransiEnt.Producer.Gas.BiogasPlant.HeatTransfer.ForcedConvection;
function NusseltInsideCSTR "Model for calculating the nusselt number of a continous stirred tank reactor"




  import Modelica.Constants.pi;
  extends TransiEnt.Basics.Icons.Function;




  input Modelica.Units.SI.ReynoldsNumber Re "Reynols number inside CSTR";
  input Modelica.Units.SI.PrandtlNumber Pr "Prandtl number of medium at its temperature";
  input Modelica.Units.SI.DynamicViscosity eta "viscosity of medium at its temperature";
  input Modelica.Units.SI.DynamicViscosity eta_w "viscosity of medium at wall temperature";
  input Real C1 "geometrical Coefficient in Nusselt-Equation";
  output Modelica.Units.SI.NusseltNumber Nu "Nusselt number inside CSTR";




  constant Real a=2/3;
  constant Real b=1/3;
  constant Real c=0.14;




algorithm
  Nu := C1*Re^a*Pr^b*(eta/eta_w)^c
  ;
end NusseltInsideCSTR;

within TransiEnt.Producer.Gas.BiogasPlant.HeatTransfer.FreeConvection;
partial model FreeConvectionHeatTransfer_Gas "Heat Transfer due to natural Convection"




  replaceable parameter TILMedia.GasTypes.BaseGas medium constrainedby TILMedia.GasTypes.BaseGas "type record of the gas or gas mixture" ;
  parameter Boolean useMassFractionDefault=false;
  parameter Modelica.Units.SI.Pressure p=101300 "pressure of fluid";
  parameter Modelica.Units.SI.Area A "Area through which heat is transported by Convection";
  parameter Modelica.Units.SI.Length L "specific lenght of geometry";




  Modelica.Units.SI.ThermalConductivity lamda=gas.transp.lambda "Thermal conductivity of fluid at T_m";
  Modelica.Units.SI.Density rho=gas.d "Density of fluid at T_m";
  Modelica.Units.SI.PrandtlNumber Pr=gas.transp.Pr "Prandtl number of the fluid";
  Modelica.Units.SI.KinematicViscosity nue=gas.transp.eta/gas.d;
  Modelica.Units.SI.DynamicViscosity eta=gas.transp.eta;
  Modelica.Units.SI.LinearExpansionCoefficient beta=gas.beta "Isobaric thermal expansion coefficient at given conditions";
  Modelica.Units.SI.CoefficientOfHeatTransfer alpha=Nu*gas.transp.lambda/L "heat transfer coefficient of convection";
  Modelica.Units.SI.SpecificHeatCapacityAtConstantPressure cp=gas.cp "specific heat capacity of fluid at given conditions";
  Modelica.Units.SI.RayleighNumber Ra=RayleighNumber(
      l=L,
      beta=beta,
      dT=dT,
      Pr=gas.transp.Pr,
      nue=gas.transp.eta/gas.d);
  Modelica.Units.SI.NusseltNumber Nu "Nusselt Number ";
  Modelica.Units.SI.MassFraction xi[medium.nc - 1]=gas.gasType.xi_default "Mass Fraction" ;
  Modelica.Units.SI.HeatFlowRate Q_flow "Heat flow rate from solid -> fluid";
  Modelica.Units.SI.TemperatureDifference dT "= solid.T - fluid.T";
  Modelica.Units.SI.Temperature T_m=(heat_solid.T + heat_fluid.T)/2;




  ClaRa.Basics.Interfaces.HeatPort_a heat_solid ;
  ClaRa.Basics.Interfaces.HeatPort_b heat_fluid ;
  TILMedia.Gas_pT gas(
    gasType=medium,
    T=T_m,
    p=p,
    computeTransportProperties=true,
    xi=xi) ;
equation




  dT = heat_solid.T - heat_fluid.T;
  heat_solid.Q_flow = Q_flow;
  heat_fluid.Q_flow = -Q_flow;
  Q_flow = A*alpha*dT
  ;
end FreeConvectionHeatTransfer_Gas;

