model PEMElectrolyzer_L1 "PEMElectrolyzer_L1 Proton exchange membrane electrolyzer"




 extends TransiEnt.Producer.Gas.Electrolyzer.Base.PartialElectrolyzer(  P_el_n=1e6,P_el_max=3*P_el_n);




  parameter Boolean useHomotopy=simCenter.useHomotopy "true if homotopy method is used during initialization" ;
  parameter SI.LinearTemperatureCoefficient k_therm_relative=0.325436e-3 "temperature conductivity for heat losses relative to electrical power"  ; 
  parameter SI.Temperature T_amb=273.15+15 "ambient temperature for heat loss calculation" ;
  parameter Real specificWaterConsumption=10 "Mass of water per mass of hydrogen" ; 
  parameter SI.Efficiency eta_n(
    min=0,
    max=1)=0.75 "Nominal efficiency refering to the GCV (min = 0, max = 1)" ;
  parameter SI.Efficiency eta_scale(
    min=0,
    max=1)=0 "Sets a with increasing input power linear degrading efficiency coefficient (min=0,max=1)" ;
  parameter Integer whichInput=1 "use P_el_set or m_flow_H2_set as input" ;
  parameter Boolean useLeakageMassFlow=false "Constant leakage gas mass flow of 'm_flow_small' to avoid zero mass flow"  ;
  parameter SI.MassFlowRate m_flow_small=simCenter.m_flow_small "leakage mass flow if useLeakageMassFlow=true" ;




protected
  SI.MassFlowRate m_flow_H2 "H2 mass flow rate out of electrolyzer";
public
  SI.Mass mass_H2(start=0, fixed=true) "produced H2 mass";
  SI.HeatFlowRate Q_flow "waste heat";
  SI.HeatFlowRate Q_loss "heat losses to environment";
  SI.Efficiency eta_NCV(min=0, max=1) "Efficiency of the electrolyzer based on NCV" ;
  SI.Efficiency eta_GCV(min=0, max=1)=charline.eta "Efficiency of the electrolyzer based on GCV" ;
protected
  model Outline
    extends TransiEnt.Basics.Icons.Record;
    input SI.Power P_el "Consumed electric power";
    input SI.Energy W_el "Consumed electric energy";
    input SI.Power H_flow_NCV "Produced enthalpy flow based on NCV";
    input SI.Power H_flow_GCV "Produced enthalpy flow based on GCV";
    input SI.Mass mass_H2 "Produced hydrogen mass";
    input SI.Mass mass_H2O "Consumed water mass";
    input SI.Efficiency eta_NCV "Efficiency based on NCV";
    input SI.Efficiency eta_GCV "Efficiency based on GCV";
  end Outline;
  model Summary
    extends TransiEnt.Basics.Icons.Record;
    Outline outline;
    TransiEnt.Basics.Records.FlangeRealGas gasPortOut;
    TransiEnt.Basics.Records.Costs costs;
  end Summary;




public
  replaceable model Dynamics = TransiEnt.Producer.Gas.Electrolyzer.Base.ElectrolyzerDynamics0thOrder        constrainedby TransiEnt.Producer.Gas.Electrolyzer.Base.PartialElectrolyzerDynamics        "Dynamic behavior of electrolyser" ;
  replaceable model Charline = TransiEnt.Producer.Gas.Electrolyzer.Base.ElectrolyzerEfficiencyCharlineSilyzer200        constrainedby TransiEnt.Producer.Gas.Electrolyzer.Base.PartialElectrolyzerEfficiencyCharline        "Calculate the efficiency" ;




  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerIn P_el_set if whichInput==1 "Electric power input (set value)" ;
  TransiEnt.Basics.Interfaces.General.MassFlowRateIn m_flow_H2_set if whichInput==2 "Hydrogen mass flow rate input (set value)"  ;




protected
  Dynamics dynamics(final useHomotopy=useHomotopy, final P_el_n=P_el_n, final eta_n=eta_n) ;
  Charline charline(final P_el_n=P_el_n, final eta_n=eta_n, final eta_scale=eta_scale) ;
  Modelica.Blocks.Sources.Constant P_el_set_(k=0) if not whichInput==1;
  Modelica.Blocks.Sources.Constant m_flow_H2_set_(k=0) if not whichInput==2;
  TransiEnt.Producer.Gas.Electrolyzer.Base.GetInputsElectrolyzer getInputs ;
  TransiEnt.Components.Statistics.Collectors.LocalCollectors.CollectElectricPower collectElectricPower(typeOfResource=typeOfResource, integrateElPower=integrateElPower)
                                                                                                                                      ;
public
  inner Summary summary(
    outline(
      P_el=P_el,
      W_el=collectCosts.W_el_demand,
      H_flow_NCV=gasPortOut.m_flow*NCV_H2[end],
      H_flow_GCV=gasPortOut.m_flow*GCV_H2[end],
      mass_H2=mass_H2,
      mass_H2O=specificWaterConsumption*mass_H2,
      eta_NCV=eta_NCV,
      eta_GCV=eta_GCV),
    gasPortOut(
      mediumModel=medium,
      xi=vleFluidH2.xi,
      x=vleFluidH2.x,
      m_flow=-gasPortOut.m_flow,
      T=vleFluidH2.T,
      p=gasPortOut.p,
      h=vleFluidH2.h,
      rho=vleFluidH2.d),
    costs(
      costs=collectCosts.costsCollector.Costs,
      investCosts=collectCosts.costsCollector.InvestCosts,
      demandCosts=collectCosts.costsCollector.DemandCosts,
      oMCosts=collectCosts.costsCollector.OMCosts,
      otherCosts=collectCosts.costsCollector.OtherCosts,
      revenues=collectCosts.costsCollector.Revenues)) ;
equation







  gasPortOut.xi_outflow=xi_out;
  gasPortOut.h_outflow=vleFluidH2.h;
  if useLeakageMassFlow then
    gasPortOut.m_flow = -m_flow_H2-m_flow_small;
  else
    gasPortOut.m_flow=-m_flow_H2;
  end if;
  if whichInput==1 then
    P_el=getInputs.P_el_set;
  else
    m_flow_H2=getInputs.m_flow_H2_set;
  end if;
  if integrateH2Flow then
    der(mass_H2)=m_flow_H2;
  else
    mass_H2=0;
  end if;
  m_flow_H2O = specificWaterConsumption*m_flow_H2;
  eta_NCV=eta_GCV*NCV_H2[end]/GCV_H2[end];
  Q_flow=min(0,-(P_el-dynamics.H_flow_H2)+Q_loss);
  Q_loss=k_therm_relative*P_el*(T_out-T_amb);

  dynamics.H_flow_H2 = m_flow_H2 * (GCV_H2[end] + (vleFluidH2.h - h0));
  dynamics.P_el=P_el;
  dynamics.eta=eta_GCV;

  charline.P_el=P_el;




  connect(P_el_set_.y, getInputs.P_el_set);
  connect(m_flow_H2_set_.y, getInputs.m_flow_H2_set);
  connect(P_el_set, getInputs.P_el_set) ;
  connect(getInputs.m_flow_H2_set, m_flow_H2_set) 
  ;
end PEMElectrolyzer_L1;

within TransiEnt.Producer.Gas.Electrolyzer.Base;
model ElectrolyzerDynamics0thOrder "0th order electrolyzer dynamics"




  extends TransiEnt.Producer.Gas.Electrolyzer.Base.PartialElectrolyzerDynamics;
















equation
  H_flow_H2 = if useHomotopy then homotopy(P_el * eta, P_el_n * eta_n) else P_el * eta
  ;
end ElectrolyzerDynamics0thOrder;

within TransiEnt.Producer.Gas.Electrolyzer.Base;
model ElectrolyzerDynamics1stOrder "1st order electrolyzer dynamics"




  extends TransiEnt.Producer.Gas.Electrolyzer.Base.PartialElectrolyzerDynamics;








  parameter Modelica.Units.SI.Time tau(min=0) = 1 "Sets the time constant of the electrolyser";








equation
  P_el * eta = H_flow_H2 + tau * der(H_flow_H2)
  ;
end ElectrolyzerDynamics1stOrder;

within TransiEnt.Producer.Gas.Electrolyzer.Base;
model ElectrolyzerDynamics2ndOrder "2nd order electrolyzer dynamics"




  extends TransiEnt.Producer.Gas.Electrolyzer.Base.PartialElectrolyzerDynamics;








  parameter Real omega_n = 17 "Sets the natural frequency of the electrolyser";
  parameter Real zeta = 0.7 "Set the damping ratio of the electrolyser";




protected
  Real x1(final start=0);
  Real x2(final start=0);




equation

  der(x1) = x2;
  der(x2) = - 2 * zeta * omega_n  * x2 - omega_n^2 * x1 + omega_n^2 * P_el * eta;
  H_flow_H2 = x1
  ;
end ElectrolyzerDynamics2ndOrder;

within TransiEnt.Producer.Gas.Electrolyzer.Base;
model ElectrolyzerEfficiencyCharlineSilyzer100 "Efficiency charline for Silyzer 100"





  extends TransiEnt.Producer.Gas.Electrolyzer.Base.PartialElectrolyzerEfficiencyCharline(eta_n_cl=0.746699);




equation

  eta_cl =0.000000006999*(P_el/P_el_n*100)^4 - 0.000006*(P_el/P_el_n*100)^3 + 0.002056*(P_el/P_el_n*100)^2 - 0.3894*(P_el/P_el_n*100) + 98.35;

  eta = (eta_n/eta_n_cl - eta_scale * P_el/P_el_n) * eta_cl/100
  ;
end ElectrolyzerEfficiencyCharlineSilyzer100;

within TransiEnt.Producer.Gas.Electrolyzer.Base;
model ElectrolyzerEfficiencyCharlineSilyzer200 "Efficiency charline for Silyzer 200"





  extends TransiEnt.Producer.Gas.Electrolyzer.Base.PartialElectrolyzerEfficiencyCharline(eta_n_cl=0.62903);
  parameter Boolean use_arrayefficiency=false;




equation

  if use_arrayefficiency then
    eta_cl=if noEvent(P_el/P_el_n<0.02) then (0.06655*(0.392739)^3 - 0.2741*(0.392739)^2 + 0.8709*(0.392739) - 0.03432)/(0.392739)*P_el/P_el_n/0.02
    elseif noEvent(P_el/P_el_n<0.392739) then (0.06655*(0.392739)^3 - 0.2741*(0.392739)^2 + 0.8709*(0.392739) - 0.03432)/(0.392739)
    else 0.06655*(P_el/P_el_n)^2 - 0.2741*P_el/P_el_n + 0.8709 - 0.03432/(P_el/P_el_n);
  else
    eta_cl=if noEvent(P_el/P_el_n<0.04) then 0 else 0.06655*(P_el/P_el_n)^2 - 0.2741*P_el/P_el_n + 0.8709 - 0.03432/(P_el/P_el_n);
  end if;

  eta = (eta_n/eta_n_cl - eta_scale * P_el/P_el_n) * eta_cl
  ;
end ElectrolyzerEfficiencyCharlineSilyzer200;

