                                      ;
 TransiEnt.Basics.Interfaces.Electrical.ElectricPowerIn P_el_set "Desired output power"    ;




  TransiEnt.Basics.Blocks.LimPID limPID(
    y_max=P_el_max,
    y_min=0,
    k=k,
    Tau_i=Ti,
    Tau_d=Td,
