  Modelica.Blocks.Nonlinear.Limiter limiter(uMax=P_el_max, uMin=0) ;
protected
  Charline charline(final P_el_n=P_el_n, final eta_n=eta_n, final eta_scale=eta_scale) ;
protected
  Modelica.Blocks.Math.Min minimum if useMassFlowControl "Minimum of both input signals" ;
  Modelica.Blocks.Logical.Switch switch ;
  Modelica.Blocks.Sources.Constant const(k=0) ;
  Modelica.Blocks.Sources.BooleanExpression booleanExpression(y=(P_el_set < P_el_min or m_flow_feedIn < eta_min*P_el_min/141.8e6)) if useMassFlowControl ;
  Modelica.Blocks.Sources.BooleanExpression booleanExpression2(y=(P_el_set < P_el_min)) if useMassFlowControl==false ;
equation




