                                        ;
  Modelica.Blocks.Sources.BooleanExpression booleanExpression1(y=storageFull)                                                      ;
  Modelica.Blocks.Logical.Hysteresis hysteresis(uLow=p_maxLow, uHigh=p_maxHigh)
                                                ;
public
  Modelica.Blocks.Nonlinear.Limiter limiter(uMax=P_el_max, uMin=0) ;
