                                                                                                    ;
  Modelica.Blocks.Logical.Switch switch ;
  Modelica.Blocks.Sources.Constant const(k=0) ;
  Modelica.Blocks.Logical.Switch switch2
                                        ;
  Modelica.Blocks.Sources.BooleanExpression booleanExpression2(y=storageFull)                                                      ;
