  connect(P_el_set, minimum.u2) ;
  connect(m_flow_feedIn, limPID.u_s) ;
  connect(limPID.y, minimum.u1) ;
  connect(switch1.u2, booleanExpression1.y) ;
  connect(minimum.y, switch1.u1) ;
  connect(p, hysteresis.u) ;
  connect(P_el_set, limiter.u) ;
  connect(limiter.y, switch1.u3) ;
  connect(const.y,switch. u1) ;
  connect(switch1.y,switch. u3) ;
  connect(switch.y, P_el_ely) ;
  connect(booleanExpression.y, switch.u2) ;
  connect(booleanExpression2.y, switch2.u2) ;
  connect(switch2.u1, m_flow_bypass) ;
  connect(switch2.y, limPID.u_m) ;
  connect(m_flow_feedIn, switch2.u3) 
  ;
end FeedInStorageController;

