model FeedInStorageTWVController "Controller to control the three way valve after the electrolyzer to grid and storage"




  import TransiEnt;
  import Modelica.Constants.eps;
  extends TransiEnt.Basics.Icons.Controller;








  parameter Boolean StoreAllHydrogen=false "All Hydrogen is stored before beeing fed in";
  parameter SI.Pressure p_minLow=20e5 "Lower limit of the target pressure in storage" ;
  parameter SI.Pressure p_maxLow=29e5 "Lower limit of the target pressure in storage" ;
  parameter SI.Pressure p_maxHigh=30e5 "Upper limit of the target pressure in storage" ;
  parameter SI.Pressure p_minHigh=60e5 "if valve closed and p>p_high, open valve" ;
  parameter SI.Pressure p_minLow_constantDemand=50e5 "storage can be emptied via 'm_flow_hydrogenDemand_constant' up to 'p_minLow_constantDemand'" ;
  parameter SI.MassFlowRate m_flow_hydrogenDemand_constant=0 "constant hydrogen demand if hydrogen is available" ;




  SI.MassFlowRate m_flow_ely_min(start=eps) "Minimal mass flow rate limited to eps"
                                                                                   ;
  Boolean storageFull=hysteresis.y "true if storage is full";




  outer TransiEnt.SimCenter simCenter;




  TransiEnt.Basics.Interfaces.General.MassFlowRateIn m_flow_ely "H2 mass flow out of the electrolyser" ;
  TransiEnt.Basics.Interfaces.General.MassFlowRateIn m_flow_feedIn "maximum mass flow that can be fed into the natural gas system" ;
  Modelica.Blocks.Interfaces.RealOutput splitRatio "split ratio of the three way valve" ;




  Modelica.Blocks.Logical.Hysteresis hysteresis(uLow=p_maxLow, uHigh=p_maxHigh)
                                                ;
  TransiEnt.Basics.Interfaces.General.PressureIn p "Pressure in storage" ;
  Modelica.Blocks.Sources.RealExpression realExpression1
                                                        ;
  Modelica.Blocks.Logical.Hysteresis hysteresis1(uLow=-p_minHigh, uHigh=-p_minLow)        ;
  Modelica.Blocks.Logical.Switch switch1 ;
  Modelica.Blocks.Sources.RealExpression realExpression2(y=1)   ;
  Modelica.Blocks.Math.Gain gain(k=-1) ;
equation




  m_flow_ely_min = max(eps,m_flow_ely); 
  if StoreAllHydrogen==true then
    splitRatio= 1;


  else
    splitRatio=min(1,max(0,(m_flow_ely_min-(m_flow_feedIn))/m_flow_ely_min))+min(1,max(0,switch1.y));
  end if;




  connect(p,hysteresis. u) ;
  connect(hysteresis1.y, switch1.u2) ;
  connect(realExpression1.y, switch1.u3) ;
  connect(realExpression2.y,switch1. u1) ;
  connect(hysteresis1.u, gain.y) ;
  connect(p, gain.u) 
  ;
end FeedInStorageTWVController;

