within TransiEnt.Producer.Gas.Electrolyzer.Controller;
model OverloadController "Control overload operation of electrolyzer"




  import TransiEnt;
  extends TransiEnt.Basics.Icons.Controller;








  parameter SI.ActivePower P_el_n=1e6 "Nominal power of electrolyzer";


  parameter SI.ActivePower P_el_overload=1.5*P_el_n "Power at which the overload region begins";
  parameter SI.ActivePower P_el_cooldown=P_el_n "Power below which cooldown starts";
  parameter SI.Time t_overload=8*3600 "Seconds the electrolyzer can operate in overload region";
  parameter Real coolingToHeatingRatio=2 "Ratio of how much faster the electrolyser cools down than it heats up";








  Integer state(start=1) "Defines the state the electrolyser is in (1: ready to overheat, 2: working in overload, 3: cooling down)" ;
  Real overloadLevel(start=0) "Level of overheating";




  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerIn P_el_set ;
  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerOut P_el_ely ;




  Modelica.Blocks.Logical.Hysteresis hysteresis_coolingDown(
    uLow=0,
    pre_y_start=false,
    uHigh=if t_overload>0 then t_overload else 1)
               ;
  Modelica.Blocks.Sources.RealExpression Input_overload_hysteresis(y=overloadLevel) ;
equation




algorithm

  when t_overload>0 and ((P_el_set>P_el_overload and (state==1 or state==4)) or (overloadLevel<=t_overload and P_el_set>P_el_overload and state==3 and hysteresis_coolingDown.y==false)) then
    state :=2;
  end when;
  when t_overload>0 and (P_el_set<P_el_overload and P_el_set>P_el_cooldown and (state==2 or state==1 or (state==3 and hysteresis_coolingDown.y==false))) then
    state:=4;
  end when;
  when t_overload>0 and ((overloadLevel>=t_overload or P_el_set<=P_el_cooldown) and (state==2 or state==4)) then
    state:=3;
  end when;
  when t_overload>0 and (overloadLevel<=0 and state==3) then
    state:=1;
  end when;
equation
  if t_overload>0 then
    der(overloadLevel) = if state==2 then +1 elseif state==3 then -coolingToHeatingRatio else 0;
  else
    overloadLevel = 0;
  end if;
  if state==1 or state==2 or state==4 then
    P_el_ely=P_el_set;
  elseif state==3 then
    P_el_ely=min(P_el_set, P_el_cooldown);
  else
    P_el_ely=1e99; 
  end if;
  connect(Input_overload_hysteresis.y,hysteresis_coolingDown. u) 
  ;
end OverloadController;

within TransiEnt.Producer.Gas.Electrolyzer.Controller;
model OverloadControllerAdvanced "Control operation of electrolyzer with overload behaviour"




  import TransiEnt;
  extends TransiEnt.Basics.Icons.Controller;








  parameter SI.ActivePower P_el_n=1e6 "Nominal power of electrolyzer";
  parameter SI.ActivePower P_el_min=0.02 "Minimum relative power of electrolyzer";
  parameter Real P_rel_1=1.5 "Relative load at which overheating start - e.g.'1.5' means overheating starts at 150% of P_el_n";
  parameter Real P_rel_2=1.75 "Relative load point 2 for definition of overheating characteristic";
  parameter Real P_rel_3=2.25 "Relative load point 3 (maximum possible load) for definition of overheating characteristic";
  parameter Real P_rel_cooldown=1 "Maximum possible relative load if electrolyseur must be cooled down";
  parameter Modelica.Units.SI.Time t_1(displayUnit="h") = 360000 "Maximum possible duration in overload operation with relative load P_rel_1";
  parameter Modelica.Units.SI.Time t_2(displayUnit="h") = 10800 "Maximum possible duration in overload operation with relative load P_rel_2";
  parameter Modelica.Units.SI.Time t_3(displayUnit="h") = 900 "Maximum possible duration in overload operation with relative load P_rel_3";
  parameter Modelica.Units.SI.Time t_cooldown(displayUnit="h") = 3600 "Time needed for cooling down if electrolyzer was overheated";








  Real overloadLevel;




  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerIn P_el_set ;
  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerOut P_el_ely ;




  Modelica.Blocks.Logical.Hysteresis hysteresis_coolingDown(
    uLow=0,
    pre_y_start=false,
    uHigh=t_3) ;
  Modelica.Blocks.Sources.RealExpression Input_overload_hysteresis(y=overloadLevel) ;
equation




   if P_el_ely>P_rel_1*P_el_n and P_el_ely<=P_rel_2*P_el_n then
     der(overloadLevel)=(t_3/t_2-t_3/t_1)/(P_rel_2-P_rel_1)*(P_el_ely/P_el_n)+(t_3/t_1-(t_3/t_2-t_3/t_1)/(P_rel_2-P_rel_1)*P_rel_1);
   elseif P_el_ely>P_rel_2*P_el_n then
     der(overloadLevel)=(1-t_3/t_2)/(P_rel_3-P_rel_2)*(P_el_ely/P_el_n)+(t_3/t_2-(1-t_3/t_2)/(P_rel_3-P_rel_2)*P_rel_2);
   elseif P_el_ely<=P_rel_1*P_el_n and overloadLevel>0 and P_el_ely>P_el_n then
     der(overloadLevel)=0;
   elseif P_el_ely<=P_rel_cooldown*P_el_n and overloadLevel>0 then
     der(overloadLevel)=-t_3/t_cooldown;
   else
     der(overloadLevel)=0;
   end if;
   if P_el_set<=P_rel_3*P_el_n and hysteresis_coolingDown.y==false and P_el_set>P_el_min*P_el_n then
     P_el_ely=P_el_set;
   elseif P_el_set>P_rel_3*P_el_n and hysteresis_coolingDown.y==false and P_el_set>P_el_min*P_el_n then
     P_el_ely=P_rel_3*P_el_n;
   elseif P_el_set>P_rel_cooldown and hysteresis_coolingDown.y==true and P_el_set>P_el_min*P_el_n then
     P_el_ely=P_rel_cooldown*P_el_n;
   elseif P_el_set<=P_rel_cooldown and hysteresis_coolingDown.y==true and P_el_set>P_el_min*P_el_n then
     P_el_ely=P_el_set;
   else
     P_el_ely=0;
   end if;
  connect(Input_overload_hysteresis.y, hysteresis_coolingDown.u) 
  ;
end OverloadControllerAdvanced;

