  parameter SI.Time t_overload=5*3600 "Maximum time in seconds that the electrolyzer can work in overload" ;
  parameter Real coolingToHeatingRatio=2 "Ratio of how much faster the electrolyzer cools down than it heats up" ;
  parameter Integer startState=1 "Initial state of the electrolyzer (1: ready to overheat, 2: working in overload, 3: cooling down)" ;
  parameter Modelica.Blocks.Types.SimpleController controllerType=Modelica.Blocks.Types.SimpleController.P "Type of controller for feed-in control" ;
  parameter Real k=1 "Gain for feed-in control" ;
  parameter Real Ti=0.1 "Integrator time constant for feed-in control" ;
  parameter Real Td=0.1 "Derivative time constant for feed-in control" ;
  parameter SI.Pressure p_minLow=20e5 "Lower limit of the target pressure in storage" ;
  parameter SI.Pressure p_maxLow=29e5 "Lower limit of the maximum pressure in storage" ;
  parameter SI.Pressure p_maxHigh=30e5 "Upper limit of the maximum pressure in storage" ;
  parameter SI.Pressure p_minHigh=60e5 "if valve closed and p>p_high, open valve" ;
  parameter SI.Pressure p_minLow_constantDemand=50e5 "storage can be emptied via 'm_flow_hydrogenDemand_constant' up to 'p_minLow_constantDemand'" ;
  parameter SI.MassFlowRate m_flow_hydrogenDemand_constant=0 "constant hydrogen demand if hydrogen is available" ;
  parameter Boolean StoreAllHydrogen=false "All Hydrogen is stored before beeing fed in" ;








  outer TransiEnt.SimCenter simCenter;




  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerIn P_el_set "Set power"    ;
  TransiEnt.Basics.Interfaces.General.PressureIn p_storage "Pressure in storage" ;
  TransiEnt.Basics.Interfaces.General.MassFlowRateIn m_flow_ely "Hydrogen mass flow out of the electrolyser" ;
  TransiEnt.Basics.Interfaces.General.MassFlowRateIn m_flow_feedIn "Maximum mass flow that can be fed into the natural gas system" ;
  TransiEnt.Basics.Interfaces.General.MassFlowRateIn m_flow_bypass "Mass flow through bypass of storage" ;
  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerOut P_el_ely "Controlled power of the electrolyser" ;
  Modelica.Blocks.Interfaces.RealOutput splitRatio "Split ratio of the three way valve" ;
  TransiEnt.Basics.Interfaces.General.MassFlowRateOut m_flowDes_valve "Desired mass flow through the valve after the storage" ;




  TransiEnt.Producer.Gas.Electrolyzer.Controller.FeedInStorageController feedInStorageController(
    k=k,
    p_maxLow=p_maxLow,
    p_maxHigh=p_maxHigh,
    P_el_n=P_el_n,
    P_el_max=P_el_max,
    P_el_min=P_el_min,
    eta_n=eta_n,
    eta_scale=eta_scale,
    controllerType=controllerType,
    Ti=Ti,
    Td=Td,
    startState=startState,
    redeclare model Charline = Charline) ;
  TransiEnt.Producer.Gas.Electrolyzer.Controller.FeedInStorageTWVController feedInStorageTWVController(StoreAllHydrogen=StoreAllHydrogen,
    p_minLow=p_minLow,
    p_maxLow=p_maxLow,
    p_maxHigh=p_maxHigh,
    p_minHigh=p_minHigh,
    p_minLow_constantDemand=p_minLow_constantDemand,
    m_flow_hydrogenDemand_constant=m_flow_hydrogenDemand_constant)                                                                        ;
  Modelica.Blocks.Math.Feedback feedback ;
  TransiEnt.Producer.Gas.Electrolyzer.Controller.OverloadController overloadController(
    P_el_n=P_el_n,
    P_el_overload=P_el_overload,
    t_overload=t_overload,
    coolingToHeatingRatio=coolingToHeatingRatio,
    P_el_cooldown=P_el_cooldown,
    state(start=startState))
                           ;
public
  replaceable model Charline = TransiEnt.Producer.Gas.Electrolyzer.Base.ElectrolyzerEfficiencyCharlineSilyzer200        constrainedby TransiEnt.Producer.Gas.Electrolyzer.Base.PartialElectrolyzerEfficiencyCharline        "Calculate the efficiency" ;
  Modelica.Blocks.Sources.RealExpression realExpression(y=1) ;
  Modelica.Blocks.Math.Add add(k2=-1) ;
  Modelica.Blocks.Math.Product product ;
equation








  connect(feedInStorageController.p, p_storage) ;
  connect(feedInStorageTWVController.splitRatio, splitRatio) ;
  connect(feedInStorageTWVController.m_flow_ely, m_flow_ely) ;
  connect(m_flow_feedIn, feedback.u1) ;
  connect(feedInStorageController.m_flow_feedIn, m_flow_feedIn) ;
  connect(feedInStorageTWVController.m_flow_feedIn, m_flow_feedIn) ;
  connect(P_el_set, feedInStorageController.P_el_set) ;
  connect(feedInStorageController.P_el_ely, overloadController.P_el_set) ;
  connect(p_storage, feedInStorageTWVController.p) ;
  connect(m_flow_ely, feedInStorageController.m_flow_bypass) ;
  connect(P_el_ely, overloadController.P_el_ely) ;
  connect(realExpression.y, add.u1) ;
  connect(add.u2, feedInStorageTWVController.splitRatio) ;
  connect(add.y, product.u2) ;
  connect(product.u1, m_flow_ely) ;
  connect(product.y, feedback.u2) ;
  connect(feedback.y, m_flowDes_valve) 
  ;
end TotalFeedInStorageController;

