partial model PartialHeatPumpCharline "Partial heat pump model that produces a given heat flow with a charline"




  extends TransiEnt.Basics.Icons.HeatPump;
  import      Modelica.Units.SI;




  parameter Boolean use_Q_flow_input=true "true for Q_flow input, false for P_el input" ;
  parameter Boolean use_T_source_input_K=false "False, use outer ambient conditions" ;
  parameter SI.HeatFlowRate Q_flow_n=3.5e3 "Nominal heat flow of heat pump at nominal conditions according to EN14511" ;
  parameter Real COP_n=3.7 "Coefficient of performance at nominal conditions A2/W35 according to EN14511" ;
  replaceable model ProducerCosts = TransiEnt.Components.Statistics.ConfigurationData.PowerProducerCostSpecs.Empty constrainedby TransiEnt.Components.Statistics.ConfigurationData.PowerProducerCostSpecs.PartialPowerPlantCostSpecs ;
  parameter Boolean useFluidPorts=true "True if fluid ports shall be used" ;
  parameter TILMedia.VLEFluidTypes.BaseVLEFluid mediumWater=simCenter.fluid1 "Medium to be used" ;
  parameter SI.Pressure p_drop=heatFlowBoundary.simCenter.p_nom[2] - heatFlowBoundary.simCenter.p_nom[1] ;




  outer TransiEnt.SimCenter simCenter;
  outer TransiEnt.ModelStatistics modelStatistics;




  TransiEnt.Basics.Interfaces.Thermal.HeatFlowRateIn Q_flow_set if use_Q_flow_input "Setpoint value of the heat flow, should be negative" ;
  TransiEnt.Basics.Interfaces.General.TemperatureIn T_source_input_K
                                                     if use_T_source_input_K "Input ambient temperature in Kelvin" ;
  Modelica.Blocks.Interfaces.RealOutput DeltaT "Temperature difference between water and air" ;
protected
  TransiEnt.Basics.Interfaces.General.TemperatureIn T_source_internal;








public
  SI.HeatFlowRate Q_flow;
  Real COP;
  TransiEnt.Components.Statistics.Collectors.LocalCollectors.HeatingPlantCost collectCosts_HeatProducer(
    redeclare model HeatingPlantCostModel = ProducerCosts,
    Q_flow_fuel_is=0,
    m_flow_CDE_is=0,
    Q_flow_n=Q_flow_n,
    Q_flow_is=Q_flow,
    consumes_H_flow=false,
    produces_m_flow_CDE=false) ;
  TransiEnt.Components.Statistics.Collectors.LocalCollectors.CollectHeatingPower collectHeatingPower(typeOfResource=TransiEnt.Basics.Types.TypeOfResource.Conventional) ;
  Modelica.Blocks.Math.Gain Q_flow_set_(k=1) ;
  Modelica.Blocks.Sources.Constant const(k=1) ;
  Components.Sensors.TemperatureSensor T_in_sensor if useFluidPorts ;
public
  replaceable Components.Boundaries.Heat.Heatflow_L1 heatFlowBoundary(
    p_drop=p_drop,
    use_Q_flow_in=true,
    Medium=mediumWater,
    change_sign=false) if useFluidPorts constrainedby Components.Boundaries.Heat.Heatflow_L1 ;
  Modelica.Blocks.Sources.RealExpression PrescribedHeatFlow(y=Q_flow) ;
  Modelica.Blocks.Math.Gain gain(k=-1) ;
  Modelica.Blocks.Sources.RealExpression T_source(y=T_source_internal) ;
  Modelica.Blocks.Math.Sum sum1(nin=2) if useFluidPorts ;
  Modelica.Blocks.Sources.RealExpression Temperature(y=heat.T)     if not (useFluidPorts) ;
  Basics.Interfaces.Thermal.FluidPortOut waterPortOut(Medium=mediumWater)           if useFluidPorts ;
  Basics.Interfaces.Thermal.FluidPortIn waterPortIn(Medium=mediumWater)           if useFluidPorts ;
  Components.Sensors.TemperatureSensor T_out_sensor if useFluidPorts ;
  Modelica.Thermal.HeatTransfer.Sources.PrescribedHeatFlow heatFlowBoundary1 if not (useFluidPorts) ;
  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_b heat if not (useFluidPorts) ;
  Modelica.Blocks.Math.Sum sum2(nin=2) if not (useFluidPorts) ;
equation




  if not use_T_source_input_K then
    T_source_internal =Modelica.Units.Conversions.from_degC(simCenter.T_amb_var);
  end if;
  collectHeatingPower.heatFlowCollector.Q_flow = -Q_flow;




  connect(modelStatistics.heatFlowCollector[collectHeatingPower.typeOfResource], collectHeatingPower.heatFlowCollector);
  connect(modelStatistics.costsCollector, collectCosts_HeatProducer.costsCollector);
  connect(T_source_internal, T_source_input_K);
  if use_Q_flow_input then
    connect(Q_flow_set, Q_flow_set_.u) ;
  else
    connect(const.y, Q_flow_set_.u) ;
  end if;
  if useFluidPorts then
    connect(T_in_sensor.T, sum1.u[1]) ;
    connect(waterPortIn, heatFlowBoundary.fluidPortIn) ;
    connect(waterPortIn, T_in_sensor.port) ;
    connect(PrescribedHeatFlow.y, heatFlowBoundary.Q_flow_prescribed) ;
    connect(waterPortOut, T_out_sensor.port) ;
    connect(heatFlowBoundary.fluidPortOut, waterPortOut) ;
    connect(sum1.y, DeltaT) ;
    connect(gain.y, sum1.u[2]) ;
  end if;
  if not (useFluidPorts) then
    connect(heatFlowBoundary1.port, heat) ;
    connect(PrescribedHeatFlow.y, heatFlowBoundary1.Q_flow) ;
    connect(Temperature.y, sum2.u[1]) ;
    connect(sum2.y, DeltaT) ;
    connect(gain.y, sum2.u[2]) ;
  end if;
   connect(T_source.y, gain.u) 
  ;
end PartialHeatPumpCharline;

within TransiEnt.Producer.Heat.Base;
partial model XtH_L1_idContrMFlow_temp_base "Base class for heat producers with a pump with ideal mass flow control to get a given outlet temperature"




  extends TransiEnt.Basics.Icons.Model;
  import      Modelica.Units.SI;




  parameter TILMedia.VLEFluidTypes.BaseVLEFluid medium=simCenter.fluid1 "Medium to be used"      ;
  parameter Boolean use_varTemp=false "true if variable temperature input should be used" ;
  parameter SI.HeatFlowRate Q_flow_n = 3.5e3 "Nominal heat flow rate" ;
  parameter SI.Temperature T_out_set_const=46 + 273.15 "Constant outlet temperature" ;
  parameter SI.MassFlowRate m_flow_max=1e10 "Maximum mass flow" ;
  parameter Boolean allowOverheat=false "true if the heat producer is allowed to supply heat even if the outlet temperature is higher than T_out_const then" ;
  parameter SI.HeatFlowRate Q_flow_small=1 "Small heat flow rate under which the heat supply stops" ;
  parameter TransiEnt.Basics.Types.TypeOfResource typeOfResource=TransiEnt.Basics.Types.TypeOfResource.Conventional "Select the kind of resource" ;




  outer TransiEnt.SimCenter simCenter;
  outer TransiEnt.ModelStatistics modelStatistics;




  TransiEnt.Basics.Interfaces.Thermal.FluidPortIn fluidPortIn(Medium=medium) ;
  TransiEnt.Basics.Interfaces.Thermal.FluidPortOut fluidPortOut(Medium=medium) ;
  TransiEnt.Basics.Interfaces.General.TemperatureIn T_out_set=T_out_set_in if use_varTemp "Setpoint value of the output temperature" ;
  TransiEnt.Basics.Interfaces.Thermal.HeatFlowRateIn Q_flow_set "Setpoint value of the heat flow, should be negative" ;




  replaceable model ProducerCosts =
      TransiEnt.Components.Statistics.ConfigurationData.PowerProducerCostSpecs.Empty
    constrainedby TransiEnt.Components.Statistics.ConfigurationData.PowerProducerCostSpecs.PartialPowerPlantCostSpecs ;
  TILMedia.Internals.VLEFluidConfigurations.FullyMixtureCompatible.VLEFluid_pT fluidOut(
    vleFluidType=medium,
    p=fluidPortOut.p,
    T=T_out_set_in) ;
  TransiEnt.Components.Statistics.Collectors.LocalCollectors.HeatingPlantCost collectCosts_HeatProducer(
    redeclare model HeatingPlantCostModel = ProducerCosts,
    Q_flow_fuel_is=0,
    m_flow_CDE_is=0,
    Q_flow_n=Q_flow_n,
    Q_flow_is=Q_flow,
    consumes_H_flow=false,
    produces_m_flow_CDE=false)
                         ;
  TransiEnt.Components.Statistics.Collectors.LocalCollectors.CollectHeatingPower collectHeatingPower(typeOfResource=typeOfResource) ;




  SI.Temperature T_out_set_in;
  SI.HeatFlowRate Q_flow;




equation
  if not use_varTemp then
    T_out_set_in=T_out_set_const;
  end if;
  if inStream(fluidPortIn.h_outflow)>fluidOut.h then
    if -Q_flow_set<Q_flow_small or not allowOverheat then
      fluidPortOut.m_flow=0;
      fluidPortOut.h_outflow=inStream(fluidPortIn.h_outflow);
    else
      fluidPortOut.h_outflow=Q_flow_set/fluidPortOut.m_flow+inStream(fluidPortIn.h_outflow);
      fluidPortOut.m_flow=-m_flow_max; 
    end if;
  else
    fluidPortOut.h_outflow=fluidOut.h;
    fluidPortOut.m_flow=-max(0,min(m_flow_max,-Q_flow_set/(fluidPortOut.h_outflow-inStream(fluidPortIn.h_outflow))));
  end if;
  fluidPortIn.m_flow+fluidPortOut.m_flow=0;
  fluidPortIn.h_outflow=inStream(fluidPortOut.h_outflow);
  Q_flow=fluidPortOut.m_flow*(fluidPortOut.h_outflow-inStream(fluidPortIn.h_outflow));
  collectHeatingPower.heatFlowCollector.Q_flow=Q_flow;




  connect(modelStatistics.heatFlowCollector[TransiEnt.Basics.Types.TypeOfResource.Consumer],collectHeatingPower.heatFlowCollector);
  connect(modelStatistics.costsCollector, collectCosts_HeatProducer.costsCollector)
  ;
end XtH_L1_idContrMFlow_temp_base;

