model GB_L1_idContrMFlow_temp "Model for gas boilers with a pump with ideal mass flow control to get a given outlet temperature"




  extends TransiEnt.Producer.Electrical.Base.PartialNaturalGasUnit(final useSecondGasPort=false);
  extends TransiEnt.Producer.Heat.Base.XtH_L1_idContrMFlow_temp_base;




  parameter Real eta = 0.95 "Coefficient of performance at nominal conditions according to EN14511" ;
  parameter SI.SpecificEnthalpy HoC_fuel=40e6 "Heat of combustion of fuel, will be used if gasport is deactivated in model" ;




public
  SI.EnthalpyFlowRate H_flow "Consumed gas enthalpy flow rate";
  Modelica.Blocks.Math.Division division ;
   Modelica.Blocks.Sources.RealExpression realExpression1(y=H_flow) ;




  Modelica.Blocks.Sources.RealExpression HoC_constant(y=HoC_fuel) if not useGasPort ;
equation
  H_flow=-Q_flow/eta;
  if useGasPort then
    connect(vleNCVSensor.NCV,division. u2) ;
    connect(m_flow_gas,division. y) ;
  end if;
  connect(division.u1, realExpression1.y) ;
  connect(HoC_constant.y, division.u2) 
  ;
end GB_L1_idContrMFlow_temp;

