model GHP_L1_idContrMFlow_temp "Model for gas heat pumps with a pump with ideal mass flow control to get a given outlet temperature"




  extends TransiEnt.Producer.Electrical.Base.PartialNaturalGasUnit(final useSecondGasPort=false);
  extends TransiEnt.Producer.Heat.Base.XtH_L1_idContrMFlow_temp_base;




  parameter Boolean use_T_source_input_K = false "False, use outer ambient conditions" ;
  parameter Real COP_n = 1.37726 "Coefficient of performance at nominal conditions according to EN14511" ;
  parameter SI.SpecificEnthalpy HoC_fuel=40e6 "Heat of combustion of fuel, will be used if gasport is deactivated in model" ;




  TransiEnt.Basics.Interfaces.General.TemperatureIn T_source_input_K if use_T_source_input_K "Input ambient temperature in Kelvin" ;
protected
  TransiEnt.Basics.Interfaces.General.TemperatureIn T_source_internal;




public
  SI.TemperatureDifference DeltaT "Temperature difference between water and air";
  Real COP "Coefficient of performance";
  SI.EnthalpyFlowRate H_flow "Consumed gas enthalpy flow rate";
  SI.Temperature T_source_var=20+273.15 "Air temperature" ;
  Modelica.Blocks.Sources.RealExpression realExpression1(y=H_flow)  ;
  Modelica.Blocks.Math.Division division  ;
  Modelica.Blocks.Sources.RealExpression HoC_constant(y=HoC_fuel) if not useGasPort ;




equation
  if not use_T_source_input_K then
    T_source_internal=T_source_var;
  end if;
  H_flow=-Q_flow/COP;
  DeltaT=T_out_set_in - T_source_internal;
  COP=COP_n*1/1.37726*(4e-5*DeltaT^2-0.0111*DeltaT+1.7);




  connect(T_source_input_K, T_source_internal);
  if useGasPort then
    connect(vleNCVSensor.NCV, division.u2) ;
    connect(m_flow_gas, division.y) ;
  end if;
  connect(HoC_constant.y, division.u2) ;
  connect(realExpression1.y, division.u1) 
  ;
end GHP_L1_idContrMFlow_temp;

