within TransiEnt.Producer.Heat.Gas2Heat.SmallGasBoiler;
model Gasboiler_dynamic_L1 "Full modulating or staged gasboiler, signal based dynamic model with splitted ideal combustion and ideal heat-transfer"




  extends TransiEnt.Producer.Heat.Gas2Heat.SmallGasBoiler.Base.PartialGasboiler;




  parameter Integer dimension=2 "Boiler dimension" ;
  parameter Boolean modulating = true "Modulating operation, staged power production if false (select stages then!)" ;
  parameter Integer stages = 1 "Number of burner stages for non-modulating operation" ;
  parameter Real stagePercentage = 0.3 "Power percentage at burner stage 2" ;
  parameter SI.TemperatureDifference T_supply_tol = 3 "Acceptable absolute tolerance of supply temperature for controlling (consider dynamics of boiler!)" ;




  Integer stageSwitch(start=0);




protected
  Utilities.BoilerHeatDynamics boilerHeatDynamics(damping=if dimension == 1 then 25 else if dimension == 2 then 50 else 120) ;
  ClaRa.Components.BoundaryConditions.PrescribedHeatFlowScalar prescribedHeatFlow ;
  Components.Heat.HEX_ideal hex(Delta_p=Delta_p_nom) ;
equation




  if holdTemperature then
    Q_flow_set_internal =
    if modulating then waterPortIn.m_flow*cp_water*(T_supply_set_internal - temperatureWaterIn.T)
    else
      if stageSwitch == 1 then stagePercentage*Q_flow_n
      elseif stageSwitch == 2 then Q_flow_n
      else 0;
  end if;
  if modulating then
    stageSwitch = 0;
  else
    if stages == 1 then
      if pre(stageSwitch) == 0 and hex.fluidOut.T < T_supply_set_internal - T_supply_tol then
        stageSwitch = 2;
      elseif pre(stageSwitch) == 2 and hex.fluidOut.T > T_supply_set_internal + T_supply_tol then
        stageSwitch = 0;
      else
        stageSwitch = pre(stageSwitch);
      end if;
    else
      if pre(stageSwitch) == 0 and hex.fluidOut.T < T_supply_set_internal - T_supply_tol then
        stageSwitch = 2;
      elseif pre(stageSwitch) == 2 and hex.fluidOut.T > T_supply_set_internal + 0.5 * T_supply_tol then
        stageSwitch = 1;
      elseif pre(stageSwitch) == 1 and hex.fluidOut.T > T_supply_set_internal + T_supply_tol then
        stageSwitch = 0;
      elseif pre(stageSwitch) == 1 and hex.fluidOut.T < T_supply_set_internal - 0.5 * T_supply_tol then
        stageSwitch = 2;
      else
        stageSwitch = pre(stageSwitch);
      end if;
    end if;
  end if;




  connect(boilerHeatDynamics.out, prescribedHeatFlow.Q_flow) ;
  connect(prescribedHeatFlow.port, hex.heatport) ;
  connect(limiter.y, duty2EfficiencyCharline.Q_flow_set) ;
  connect(limiter.y, boilerHeatDynamics.set) ;
  connect(waterPortIn, hex.waterPortIn) ;
  connect(hex.waterPortOut, waterPortOut) 
  ;
end Gasboiler_dynamic_L1;

within TransiEnt.Producer.Heat.Gas2Heat.SmallGasBoiler;
model Gasboiler_dynamic_L2 "Full modulating or staged gasboiler with fluid volume"




  import TransiEnt;
  extends TransiEnt.Producer.Heat.Gas2Heat.SmallGasBoiler.Base.PartialGasboiler;




  replaceable model PressureLoss=ClaRa.Basics.ControlVolumes.Fundamentals.PressureLoss.Generic_PL.LinearPressureLoss_L2(Delta_p_nom=Delta_p_nom)
    constrainedby ClaRa.Basics.ControlVolumes.Fundamentals.PressureLoss.Generic_PL.PressureLoss_L2 "Pressure loss model" ;
  parameter SI.MassFlowRate m_flow_nom=55 "Nominal mass flow rates at inlet" ;
  parameter SI.Volume volume=10.5 "Volume of water inside the boiler" ;
  parameter Modelica.Units.NonSI.Temperature_degC T_init=65 "Initial temperature of boiler water" ;
  parameter SI.AbsolutePressure p_init=6e5 "Initial pressure of boiler water" ;
  parameter Boolean modulating = true "Modulating operation, staged power production if false (select stages then!)" ;
  parameter Integer stages = 1 "Number of burner stages for non-modulating operation" ;
  parameter Real stagePercentage = 0.3 "Power percentage at burner stage 2" ;
  parameter SI.TemperatureDifference T_supply_tol = 3 "Acceptable absolute tolerance of supply temperature for controlling (consider dynamics of boiler!)" ;




  Integer stageSwitch(start=0);




protected
  ClaRa.Components.BoundaryConditions.PrescribedHeatFlowScalar prescribedHeatFlow ;
  ClaRa.Basics.ControlVolumes.FluidVolumes.VolumeVLE_2 volumeHeatExchanger(
    redeclare model Geometry = ClaRa.Basics.ControlVolumes.Fundamentals.Geometry.GenericGeometry (volume=volume),
    redeclare model PressureLoss = PressureLoss,
    m_flow_nom=m_flow_nom,
    h_start=4200*T_init,
    p_start=p_init) ;
equation




  if holdTemperature then
    Q_flow_set_internal =
    if modulating then waterPortIn.m_flow*cp_water*(T_supply_set_internal - temperatureWaterIn.T)
    else
      if stageSwitch == 1 then stagePercentage*Q_flow_n
      elseif stageSwitch == 2 then Q_flow_n
      else 0;
  end if;
  if modulating then
    stageSwitch = 0;
  else
    if stages == 1 then
      if pre(stageSwitch) == 0 and volumeHeatExchanger.fluidOut.T < T_supply_set_internal - T_supply_tol then
        stageSwitch = 2;
      elseif pre(stageSwitch) == 2 and volumeHeatExchanger.fluidOut.T > T_supply_set_internal + T_supply_tol then
        stageSwitch = 0;
      else
        stageSwitch = pre(stageSwitch);
      end if;
    else
      if pre(stageSwitch) == 0 and volumeHeatExchanger.fluidOut.T < T_supply_set_internal - T_supply_tol then
        stageSwitch = 2;
      elseif pre(stageSwitch) == 2 and volumeHeatExchanger.fluidOut.T > T_supply_set_internal + 0.5 * T_supply_tol then
        stageSwitch = 1;
      elseif pre(stageSwitch) == 1 and volumeHeatExchanger.fluidOut.T > T_supply_set_internal + T_supply_tol then
        stageSwitch = 0;
      elseif pre(stageSwitch) == 1 and volumeHeatExchanger.fluidOut.T < T_supply_set_internal - 0.5 * T_supply_tol then
        stageSwitch = 2;
      else
        stageSwitch = pre(stageSwitch);
      end if;
    end if;
  end if;




  connect(limiter.y, duty2EfficiencyCharline.Q_flow_set) ;
  connect(waterPortIn, volumeHeatExchanger.inlet) ;
  connect(volumeHeatExchanger.outlet, waterPortOut) ;
  connect(prescribedHeatFlow.port, volumeHeatExchanger.heat) ;
  connect(prescribedHeatFlow.Q_flow, duty2EfficiencyCharline.Q_flow_set) 
  ;
end Gasboiler_dynamic_L2;

