within TransiEnt.Producer.Heat.Heat2Heat;
model Indirect_HEX_const_dT_L1 "Constant dT Heat Exchanger Model"




 import Modelica.Units.SI;
 import TIL = TILMedia.VLEFluidFunctions;
 outer TransiEnt.SimCenter simCenter;
 extends TransiEnt.Producer.Heat.Base.PartialHEX;




 parameter SI.Temperature T_start = 90 + 273.15 "Temperature at start of simulation";
 parameter Real dT_set = simCenter.dT "Setpoint temperature difference between supply and return pipe";
 parameter SI.MassFlowRate m_flow_min = 0.01 "Minimum mass flow rate to counteract possible zero massflow sitations";
 final parameter SI.SpecificHeatCapacityAtConstantPressure cp = TIL.specificIsobaricHeatCapacity_pTxi(simCenter.fluid1,simCenter.p_nom[2],T_start,{1,0,0});




 SI.HeatFlowRate Q_withdrawal "Heat taken out of the district heating";
 SI.Temperature T_out "Outlet temperature of the ideal HEX";




  Modelica.Blocks.Interfaces.RealInput Q_demand
    ;
  Modelica.Blocks.Interfaces.RealOutput T_out_calc ;
  Modelica.Blocks.Interfaces.RealOutput m_flow ;
  Modelica.Blocks.Interfaces.RealInput T_in ;
equation

    Q_withdrawal = Q_demand;
    m_flow = max(Q_withdrawal/(cp*dT_set),m_flow_min);
    T_out =  T_in - Q_withdrawal/(cp*m_flow);
    T_out_calc = T_out
    ;
end Indirect_HEX_const_dT_L1;

within TransiEnt.Producer.Heat.Heat2Heat;
model Indirect_HEX_const_T_out_L1 "Constant T_return Heat Exchanger Model"




  import Modelica.Units.SI;
  import TIL = TILMedia.VLEFluidFunctions;
  outer TransiEnt.SimCenter simCenter;
  extends TransiEnt.Producer.Heat.Base.PartialHEX;




  parameter SI.Temperature T_start = 90 + 273.15 "Temperature at start of simulation";
  parameter SI.HeatFlowRate Q_max = 90*1000 "Maximum Heat Supply";
  parameter SI.MassFlowRate m_flow_max = Q_max / (cp*(simCenter.T_supply - simCenter.T_return)) "Minimum mass flow rate";
  parameter SI.MassFlowRate m_flow_min = simCenter.m_flow_min "Minimum mass flow rate";
  final parameter SI.SpecificHeatCapacityAtConstantPressure cp=TIL.specificIsobaricHeatCapacity_pTxi(
        simCenter.fluid1,
        simCenter.p_nom[2],
        T_start,
        {1,0,0});
  parameter SI.Temperature T_out_const=simCenter.T_return "Desired constant outlet temperature";
  parameter SI.Efficiency overflow_rate=1 "Used to introduce inefficiencies in heat transfer by scaling the calculated mass flow";




  SI.MassFlowRate m_flow_calc;




  Modelica.Blocks.Interfaces.RealInput Q_demand ;
  Modelica.Blocks.Interfaces.RealOutput T_out_calc ;
  Modelica.Blocks.Interfaces.RealOutput m_flow ;

  Modelica.Blocks.Sources.RealExpression realExpression(y=m_flow_calc) ;
  Modelica.Blocks.Interfaces.RealInput T_in ;
  Modelica.Blocks.Continuous.FirstOrder T_in_delayed(
    k=1,
    T=1,
    initType=Modelica.Blocks.Types.Init.InitialOutput,
    y_start=simCenter.T_supply) ;
  Modelica.Blocks.Math.Gain usedT(k=1) ;
equation
  m_flow_calc = overflow_rate * max(Q_demand/(cp*(max(15, usedT.y - T_out_const))), m_flow_min);
  T_out_calc = T_in - Q_demand/(m_flow_calc*cp);
  connect(realExpression.y, m_flow) ;
  connect(T_in_delayed.u, T_in) ;
  connect(T_in_delayed.y, usedT.u) 
  ;
end Indirect_HEX_const_T_out_L1;

within TransiEnt.Producer.Heat.Heat2Heat;
model Substation_indirect_noStorage_L1 "Simple model of a substation with indirect connection."




 import      Modelica.Units.SI;
 outer TransiEnt.SimCenter simCenter;
 outer TransiEnt.ModelStatistics modelStatistics;




 parameter SI.Temperature T_start = simCenter.T_supply "Temperature at start of the simulation";
 parameter SI.MassFlowRate m_flow_min = simCenter.m_flow_min "Minimum mass flow rate to counteract possible zero massflow sitations, equals a simplified bypass";
 replaceable model room_heating_hex_model = TransiEnt.Producer.Heat.Heat2Heat.Indirect_HEX_const_T_out_L1  constrainedby TransiEnt.Producer.Heat.Base.PartialHEX            ;
 replaceable model dhw_heating_hex_model = TransiEnt.Producer.Heat.Heat2Heat.Indirect_HEX_const_T_out_L1  constrainedby TransiEnt.Producer.Heat.Base.PartialHEX            ;
 SI.Temperature T_mix "Mixing temperature from room and domestic hot water";
 room_heating_hex_model room_heating_hex(
    T_start=T_start,
    m_flow_min=m_flow_min)
                          ;
 dhw_heating_hex_model domestic_hot_water_hex(
    T_start=T_start,
    m_flow_min=m_flow_min)
                          ;




  TransiEnt.Basics.Interfaces.Thermal.FluidPortOut waterPortOut(Medium=simCenter.fluid1) ;
  TransiEnt.Basics.Interfaces.Thermal.FluidPortIn waterPortIn(Medium=simCenter.fluid1) ;
  Modelica.Blocks.Math.Gain signChanger_2(k=-1) ;
  Modelica.Blocks.Interfaces.RealInput Q_demand_RH ;
  Modelica.Blocks.Interfaces.RealInput Q_demand_DHW ;
  ClaRa.Components.Sensors.SensorVLE_L1_T T_in_sub(unitOption=1) ;
  Modelica.Blocks.Math.Add add_supply ;
  Modelica.Blocks.Math.Add add_return ;




   ClaRa.Components.BoundaryConditions.BoundaryVLE_Txim_flow m_flow_in(
    m_flow_const=-0.048,
    variable_m_flow=true,
    T_const(displayUnit="degC") = T_start,
    p_nom=simCenter.p_nom[2]) ;
  ClaRa.Components.BoundaryConditions.BoundaryVLE_Txim_flow m_flow_out(
    T_const(displayUnit="degC") = 363.15,
    m_flow_const=0.048,
    variable_T=true,
    variable_m_flow=true,
    p_nom=simCenter.p_nom[1]) ;
  Modelica.Blocks.Math.Gain signChanger_1(k=-1) ;
  ClaRa.Components.Sensors.SensorVLE_L1_T T_out_sub(unitOption=1)
                                                                 ;
equation




 T_mix = (domestic_hot_water_hex.m_flow *  domestic_hot_water_hex.T_out_calc +  room_heating_hex.m_flow * room_heating_hex.T_out_calc)/(domestic_hot_water_hex.m_flow+room_heating_hex.m_flow) "Richmann Mixing Rule with same material";
 m_flow_out.T = T_mix;
  connect(m_flow_out.steam_a, waterPortOut) ;
  connect(room_heating_hex.m_flow, signChanger_1.u) ;
  connect(domestic_hot_water_hex.m_flow, signChanger_2.u) ;
  connect(Q_demand_RH, room_heating_hex.Q_demand) ;
  connect(Q_demand_DHW, domestic_hot_water_hex.Q_demand) ;
  connect(T_in_sub.port, waterPortIn) ;
  connect(T_in_sub.T, room_heating_hex.T_in) ;
  connect(T_in_sub.T, domestic_hot_water_hex.T_in) ;
  connect(m_flow_in.steam_a, waterPortIn) ;
  connect(m_flow_in.m_flow, add_supply.y) ;
  connect(signChanger_2.y, add_supply.u2) ;
  connect(signChanger_1.y, add_supply.u1) ;
  connect(add_return.y, m_flow_out.m_flow) ;
  connect(room_heating_hex.m_flow, add_return.u2) ;
  connect(domestic_hot_water_hex.m_flow, add_return.u1) ;
  connect(T_out_sub.port, waterPortOut) 
  ;
end Substation_indirect_noStorage_L1;

within TransiEnt.Producer.Heat.HeaterCooler;
model EmergencyCooler_L2 "Emergency cooler, e.g. if return temperature to an aperature is too high."




import TransiEnt;
extends TransiEnt.Basics.Icons.Model;




parameter TILMedia.VLEFluidTypes.BaseVLEFluid Medium = simCenter.fluid1 "Medium in the component";
parameter SI.Temperature T_max=340 "Turn on threshold";
parameter SI.Temperature T_off=330 "Cooler turn off threshold";
parameter SI.Temperature T_stor_max=368.15 "Maximum storage temperature";
parameter SI.MassFlowRate m_flow_nom=simCenter.m_flow_nom;




  outer TransiEnt.SimCenter simCenter;
  outer TransiEnt.ModelStatistics modelStatistics;
Boolean switch;
Boolean switch_stor;




  TransiEnt.Basics.Interfaces.Thermal.FluidPortIn fpReturnIn(Medium=Medium) ;
  TransiEnt.Basics.Interfaces.Thermal.FluidPortOut fpReturnOut(Medium=Medium) ;
  TransiEnt.Basics.Interfaces.Thermal.FluidPortIn fpSupplyIn ;
  TransiEnt.Basics.Interfaces.Thermal.FluidPortOut fpSupplyOut(Medium=Medium) ;
  TransiEnt.Basics.Interfaces.General.TemperatureIn T_stor_in "Input for temperature stored in cooler" ;




  ClaRa.Components.HeatExchangers.IdealShell_L2 returnHeatExchanger(
    medium=Medium,
    p_start=simCenter.p_nom[1],
    h_start=50*4200,
    p_nom=simCenter.p_nom[1],
    z_in=1,
    redeclare model PressureLoss =
        ClaRa.Basics.ControlVolumes.Fundamentals.PressureLoss.Generic_PL.NoFriction_L2,
    m_flow_nom=m_flow_nom) ;
  TransiEnt.Components.Sensors.TemperatureSensor temperatureReturnIn ;
Modelica.Thermal.HeatTransfer.Sources.PrescribedHeatFlow returnCooler(Q_flow(
        start=0))
  ;
  TransiEnt.Components.Sensors.TemperatureSensor temperatureSupplyIn ;
Modelica.Thermal.HeatTransfer.Sources.PrescribedHeatFlow supplyCooler(Q_flow(
        start=0))
  ;
  TransiEnt.Components.Statistics.Collectors.LocalCollectors.CollectHeatingPower collectHeatingPower ;
ClaRa.Components.HeatExchangers.IdealShell_L2 returnHeatExchanger1(
    medium=Medium,
    h_start=50*4200,
    p_nom=simCenter.p_nom[1],
    m_flow_nom=m_flow_nom,
    p_start=simCenter.p_nom[2])
  ;




equation

  switch=  temperatureReturnIn.T_celsius > T_max or pre(switch) and temperatureReturnIn.T_celsius >= T_off;
  switch_stor = T_stor_in > T_stor_max or pre(switch_stor) and T_stor_in >= simCenter.heatingCurve.T_supply;
  if switch_stor then

    returnCooler.Q_flow=fpReturnIn.m_flow*4200*(T_max-temperatureReturnIn.T_celsius);
    supplyCooler.Q_flow=fpReturnIn.m_flow*4200*(T_max-temperatureSupplyIn.T_celsius);
  elseif switch then
    returnCooler.Q_flow=fpReturnIn.m_flow*4200*(T_max-temperatureReturnIn.T_celsius);
    supplyCooler.Q_flow=0;
  else
    returnCooler.Q_flow=0;
    supplyCooler.Q_flow=0;
  end if;
  collectHeatingPower.heatFlowCollector.Q_flow=returnCooler.Q_flow+supplyCooler.Q_flow;




  connect(collectHeatingPower.heatFlowCollector,modelStatistics.heatFlowCollector[3]);
  connect(temperatureReturnIn.port, fpReturnIn)
                                               ;
  connect(returnHeatExchanger.heat, returnCooler.port)         ;
  connect(fpReturnOut, fpReturnOut)
                                ;
  connect(returnHeatExchanger.inlet, fpReturnIn)
                                     ;
  connect(returnHeatExchanger.outlet, fpReturnOut)
                                       ;
  connect(fpReturnIn, fpReturnIn) ;
  connect(temperatureSupplyIn.port, fpSupplyIn)
                                               ;
  connect(fpSupplyOut, fpSupplyOut)
                                ;
  connect(fpSupplyIn, returnHeatExchanger1.inlet) ;
  connect(fpSupplyOut, returnHeatExchanger1.outlet) ;
  connect(returnHeatExchanger1.heat, supplyCooler.port) 
  ;
end EmergencyCooler_L2;

within TransiEnt.Producer.Heat.HeaterCooler;
model SupplementaryHeater_L2 "Model of a boiler that holds temperature in a grid"
  import TransiEnt;
  extends TransiEnt.Basics.Icons.Combustion;
  outer TransiEnt.SimCenter simCenter;
  outer TransiEnt.ModelStatistics modelStatistics;




  parameter TILMedia.VLEFluidTypes.BaseVLEFluid medium=simCenter.fluid1 "Medium in the component";
  parameter TILMedia.VLEFluidTypes.BaseVLEFluid fuelMedium=simCenter.gasModel1 "Fuel of the component";
  parameter TransiEnt.Basics.Types.TypeOfResource typeOfResource=EnergyResource.Conventional;
  parameter SI.TemperatureDifference dT_allowed=2 "Turn on threshold";
  parameter SI.Efficiency eta=0.94 "Efficiency of burner";
  parameter SI.Pressure p_nom=simCenter.p_nom[2] "Nominal and initial pressure";




  replaceable function CalorificValue =
      TransiEnt.Basics.Functions.GasProperties.getRealGasNCV_xi "Function to calculate specific heating value";
  ClaRa.Components.HeatExchangers.TubeBundle_L2 heatExchanger(
    medium=medium,
    m_flow_nom=20,
    h_start=70*4200,
    p_start=p_nom,
    p_nom=p_nom) ;
  TransiEnt.Components.Sensors.TemperatureSensor temperatureOut ;
  TransiEnt.Components.Sensors.TemperatureSensor temperatureIn ;
  Modelica.Thermal.HeatTransfer.Sources.PrescribedHeatFlow boilerHeat(Q_flow(start=0)) ;
  TransiEnt.Components.Statistics.Collectors.LocalCollectors.CollectHeatingPower collectHeatingPower(typeOfResource=EnergyResource.Conventional) ;




  Boolean switch(start=false);
  SI.MassFlowRate m_flow_fuel;




  TransiEnt.Basics.Interfaces.Thermal.FluidPortIn waterPortIn(Medium=medium) ;
  TransiEnt.Basics.Interfaces.Thermal.FluidPortOut waterPortOut(Medium=medium) ;
  TransiEnt.Basics.Interfaces.Gas.RealGasPortIn gasPortIn(Medium=fuelMedium) ;
equation
  assert(gasPortIn.m_flow >= 0, "Your boiler is a gas source.");





  if pre(switch) == false and (simCenter.heatingCurve.T_supply -
      temperatureIn.T_celsius) > dT_allowed then
    switch = true;

  elseif pre(switch) == true and (simCenter.heatingCurve.T_supply -
      temperatureIn.T_celsius) < 0 then
    switch = false;
  else
    switch = pre(switch);
  end if;
  if switch then
    boilerHeat.Q_flow =waterPortIn.m_flow*4200*(simCenter.heatingCurve.T_supply - temperatureIn.T_celsius);
  else
    boilerHeat.Q_flow = 0;
  end if;
  boilerHeat.Q_flow = -collectHeatingPower.heatFlowCollector.Q_flow;

  m_flow_fuel = -boilerHeat.Q_flow/CalorificValue(fuelMedium,inStream(gasPortIn.xi_outflow), 4.5e6)/eta;

  gasPortIn.m_flow = m_flow_fuel;
  gasPortIn.h_outflow = 0;
  gasPortIn.xi_outflow = zeros(fuelMedium.nc - 1);




  connect(collectHeatingPower.heatFlowCollector, modelStatistics.heatFlowCollector[
    typeOfResource]);
  connect(temperatureOut.port, waterPortOut) ;
  connect(temperatureIn.port, waterPortIn) ;
  connect(boilerHeat.port, heatExchanger.heat) ;
  connect(waterPortIn, heatExchanger.inlet) ;
  connect(waterPortOut, heatExchanger.outlet) 
    ;
end SupplementaryHeater_L2;

