within TransiEnt.Producer.Heat.Power2Heat.ElectricBoiler;
model ElectricBoiler_L1_idContrQFlow_temp "Model for electric boilers with ideal heat flow rate control to get a given outlet temperature"




  extends TransiEnt.Basics.Icons.Model;
  import      Modelica.Units.SI;




  parameter TILMedia.VLEFluidTypes.BaseVLEFluid medium=simCenter.fluid1 "Medium to be used" ;
  parameter Boolean use_varTemp=false "true if variable temperature input should be used" ;
  parameter SI.Temperature T_out_set_const=46 + 273.15 "Constant outlet set temperature" ;
  parameter SI.HeatFlowRate Q_flow_n=3.5e3 "Nominal heat flow rate" ;
  parameter Real eta=0.99 "Efficiency" ;
  parameter TransiEnt.Basics.Types.TypeOfResource typeOfResource=TransiEnt.Basics.Types.TypeOfResource.Consumer "Select the kind of resource" ;
  parameter Boolean usePowerPort=true "True if power port shall be used" ;




  outer TransiEnt.SimCenter simCenter;
  outer TransiEnt.ModelStatistics modelStatistics;




  TransiEnt.Basics.Interfaces.Thermal.FluidPortIn fluidPortIn(Medium=medium) ;
  TransiEnt.Basics.Interfaces.Thermal.FluidPortOut fluidPortOut(Medium=medium) ;
  TransiEnt.Basics.Interfaces.General.TemperatureIn T_out_set=T_out_set_in if use_varTemp "Setpoint value of the output temperature" ;




  TILMedia.Internals.VLEFluidConfigurations.FullyMixtureCompatible.VLEFluid_pT fluidOut(
    vleFluidType=medium,
    p=fluidPortOut.p,
    T=T_out_set_in) ;
  TransiEnt.Components.Statistics.Collectors.LocalCollectors.CollectHeatingPower collectHeatingPower(typeOfResource=typeOfResource) ;
  replaceable model ProducerCosts = TransiEnt.Components.Statistics.ConfigurationData.PowerProducerCostSpecs.Empty constrainedby TransiEnt.Components.Statistics.ConfigurationData.PowerProducerCostSpecs.PartialPowerPlantCostSpecs ;
  TransiEnt.Components.Statistics.Collectors.LocalCollectors.HeatingPlantCost collectCosts_HeatProducer(
    redeclare model HeatingPlantCostModel = ProducerCosts,
    Q_flow_fuel_is=0,
    m_flow_CDE_is=0,
    Q_flow_n=Q_flow_n,
    Q_flow_is=Q_flow,
    consumes_H_flow=false,
    produces_m_flow_CDE=false) ;
  TransiEnt.Components.Statistics.Collectors.LocalCollectors.CollectElectricPower collectElectricPower(typeOfResource=TransiEnt.Basics.Types.TypeOfResource.Consumer) ;
  Modelica.Blocks.Sources.RealExpression realExpression(y=P_el) ;
  replaceable TransiEnt.Components.Boundaries.Electrical.ActivePower.Power powerBoundary
                                                                             if usePowerPort constrainedby TransiEnt.Components.Boundaries.Electrical.ActivePower.Power "Choice of power boundary model. The power boundary model must match the power port." ;
  replaceable Basics.Interfaces.Electrical.ActivePowerPort epp            if usePowerPort constrainedby Basics.Interfaces.Electrical.ActivePowerPort "Choice of power port" ;




  SI.Temperature T_out_set_in;
  SI.HeatFlowRate Q_flow;
  SI.Power P_el "Consumed electric power";




equation
  if not use_varTemp then
    T_out_set_in = T_out_set_const;
  end if;
  fluidPortIn.m_flow + fluidPortOut.m_flow = 0;
  fluidPortIn.h_outflow = inStream(fluidPortOut.h_outflow);
  fluidPortOut.h_outflow = if inStream(fluidPortIn.h_outflow) < fluidOut.h then fluidOut.h else inStream(fluidPortIn.h_outflow);
  fluidPortIn.p = fluidPortOut.p;
  Q_flow = fluidPortOut.m_flow*(fluidPortOut.h_outflow - inStream(fluidPortIn.h_outflow));
  P_el = -Q_flow/eta;
  collectHeatingPower.heatFlowCollector.Q_flow = Q_flow;
  collectElectricPower.powerCollector.P = P_el;




  connect(modelStatistics.costsCollector, collectCosts_HeatProducer.costsCollector);
  connect(modelStatistics.heatFlowCollector[TransiEnt.Basics.Types.TypeOfResource.Consumer], collectHeatingPower.heatFlowCollector);
  connect(modelStatistics.powerCollector[collectElectricPower.typeOfResource], collectElectricPower.powerCollector);
  if usePowerPort then
  connect(powerBoundary.epp, epp) ;
  connect(realExpression.y, powerBoundary.P_el_set) ;
  end if
  ;
end ElectricBoiler_L1_idContrQFlow_temp;

