within TransiEnt.Producer.Heat.Power2Heat.ElectricBoiler.Controller;
model PtH_limiter "Dispatcher for Power to Heat units"




  extends TransiEnt.Basics.Icons.Controller;




  TransiEnt.Basics.Interfaces.Thermal.HeatFlowRateOut Q_flow_set_PtH "Heat flow rate output set value" ;
  TransiEnt.Basics.Interfaces.Thermal.HeatFlowRateIn Q_flow_set_demand "Set value of demanded heat flow rate"  ;
  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerIn P_RE_curtail "Electric power input" ;




  parameter Modelica.Units.SI.HeatFlowRate Q_flow_PtH_max=650e6 "maximum heating capacity of the PtH device";
  parameter Modelica.Units.SI.HeatFlowRate Q_flow_BP_min=0 "minimum heat flow of CHP-plant's back pressure mode";





 Integer OpMode;




equation
     if P_RE_curtail>=Q_flow_set_demand then 
        if Q_flow_set_demand<Q_flow_BP_min then 
           Q_flow_set_PtH=0; 
           OpMode=0;
         else
         Q_flow_set_PtH=Q_flow_set_demand;
         OpMode=1;
        end if;
     else 
       if P_RE_curtail>=Q_flow_PtH_max then
         Q_flow_set_PtH=Q_flow_PtH_max;   
         OpMode=3;
       else
         if Q_flow_set_demand<Q_flow_BP_min then 
           Q_flow_set_PtH=0; 
           OpMode=0;
         else
           Q_flow_set_PtH=P_RE_curtail;
           OpMode=4;
         end if;
       end if;
     end if
  ;
end PtH_limiter;

within TransiEnt.Producer.Heat.Power2Heat.Heatpump;
model EHP_L1_idContrMFlow_temp "Model for electric heat pumps with a pump with ideal mass flow control to get a given outlet temperature"




  extends TransiEnt.Producer.Heat.Base.XtH_L1_idContrMFlow_temp_base;




  parameter Boolean use_T_source_input_K = false "False, use outer ambient conditions" ;
  parameter Real COP_n = 3.4744 "Coefficient of performance at nominal conditions according to EN14511" ;
  parameter Boolean usePowerPort=true "True if power port shall be used" ;




  TransiEnt.Basics.Interfaces.General.TemperatureIn T_source_input_K if use_T_source_input_K "Input ambient temperature in Kelvin" ;
protected
  TransiEnt.Basics.Interfaces.General.TemperatureIn T_source_internal;




public
  TransiEnt.Components.Statistics.Collectors.LocalCollectors.CollectElectricPower collectElectricPower(typeOfResource=TransiEnt.Basics.Types.TypeOfResource.Consumer)
                                                                                                                                      ;
  Modelica.Blocks.Sources.RealExpression realExpression(y=P_el) ;
  replaceable TransiEnt.Components.Boundaries.Electrical.ActivePower.Power powerBoundary
                                                                             if usePowerPort constrainedby TransiEnt.Components.Boundaries.Electrical.ActivePower.Power "Choice of power boundary model. The power boundary model must match the power port." ;
  replaceable Basics.Interfaces.Electrical.ActivePowerPort epp            if usePowerPort constrainedby Basics.Interfaces.Electrical.ActivePowerPort "Choice of power port" ;




public
  SI.TemperatureDifference DeltaT "Temperature difference between water and air";
  Real COP "Coefficient of performance";
  SI.Power P_el "Consumed electric power";
  SI.Temperature T_source_var=20+273.15 "Air temperature" ;




equation
  if not use_T_source_input_K then
    T_source_internal=T_source_var;
  end if;
  P_el=-Q_flow/COP;
  DeltaT=T_out_set_in - T_source_internal;
  COP=COP_n*1/3.4744*(0.0005*DeltaT^2-0.0973*DeltaT+6.1408);
  collectElectricPower.powerCollector.P=P_el;




  connect(T_source_input_K, T_source_internal);
  connect(modelStatistics.powerCollector[collectElectricPower.typeOfResource],collectElectricPower.powerCollector);
  if usePowerPort then
  connect(powerBoundary.epp,epp)  ;
  connect(realExpression.y,powerBoundary. P_el_set) ;
  end if
  ;
end EHP_L1_idContrMFlow_temp;

within TransiEnt.Producer.Heat.Power2Heat.Heatpump;
model HeatPumpElectricCharline "Electric heat pump model that produces a given heat flow via fluid ports with a charline"




  extends TransiEnt.Producer.Heat.Base.PartialHeatPumpCharline(
                                            COP_n=3.4744);
  import      Modelica.Units.SI;




  parameter Boolean usePowerPort=false  ;








  replaceable TransiEnt.Basics.Interfaces.Electrical.ActivePowerPort epp if usePowerPort constrainedby TransiEnt.Basics.Interfaces.Electrical.PartialPowerPort "Choice of power port" ;
  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerIn P_el_set if not
                                                                        (use_Q_flow_input) "Setpoint value of the power, should be positive" ;




  replaceable TransiEnt.Components.Boundaries.Electrical.ActivePower.Power powerBoundary  if usePowerPort constrainedby TransiEnt.Components.Boundaries.Electrical.ActivePower.Power "Choice of power boundary model. The power boundary model must match the power port." ;
protected
  TransiEnt.Components.Statistics.Collectors.LocalCollectors.CollectElectricPower collectElectricPower(typeOfResource=TransiEnt.Basics.Types.TypeOfResource.Consumer)
                                                                                                                                      ;
  Modelica.Blocks.Sources.RealExpression realExpression(y=P_el) if usePowerPort ;
  Modelica.Blocks.Math.Gain P_el_set_(k=1) ;
  Modelica.Blocks.Sources.Constant const1(k=1)
                                          ;




public
  SI.Power P_el;
equation




  if use_Q_flow_input then
    Q_flow=Q_flow_set_.u;
    P_el=-Q_flow/COP;
  else
    Q_flow=-COP*P_el;
    P_el=P_el_set_.u;
  end if;

  COP=COP_n*1/3.4744*(0.0005*DeltaT^2-0.0973*DeltaT+6.1408); 

  collectElectricPower.powerCollector.P=P_el;




  connect(modelStatistics.powerCollector[collectElectricPower.typeOfResource],collectElectricPower.powerCollector);
  if usePowerPort then
    connect(powerBoundary.epp, epp) ;
  end if;
  if not
        (use_Q_flow_input) then
    connect(P_el_set_.u, P_el_set) ;
  else
    connect(const1.y, P_el_set_.u) ;
  end if;
  connect(realExpression.y, powerBoundary.P_el_set) 
;
end HeatPumpElectricCharline;

