model HeatPumpSystem "Heat pump system with storage and controller, input: heat demand, output: electrical power"




  outer TransiEnt.SimCenter simCenter;





  parameter Boolean Modulating=true "True: modulating heat pump operation, false: static operation with P_n" ;
  parameter Boolean MinTimes=true "If true, minimum operation and shutoff times are considered" ;
  parameter Boolean CalculatePHeater=false "If true, electrical heater power output is calculated for bivalent heat pump operation" ;
  parameter Boolean control_SoC=false "Choose controlled variable, 'true'=SoC, 'false'=Storage temperature" ;
  parameter TransiEnt.Basics.Types.OnOffRelaisStatus init_state=TransiEnt.Basics.Types.on_ready "State of relais at initialization" ;
  parameter SI.TemperatureDifference Delta_T_db=2 "Deadband of hysteresis control" ;

  parameter SI.Temperature T_s_min=303.15 "Minimum storage temperature" ;
  parameter SI.Volume V_Storage=0.5 "Volume of the Storage" ;
  parameter SI.Height height=1.3 "Height of heat storage" ;
  parameter Modelica.Units.NonSI.Temperature_degC T_amb=15 "Assumed constant temperature in tank installation room" ;
  parameter SI.SurfaceCoefficientOfHeatTransfer k=0.08 "Coefficient of heat transfer through tank surface" ;
  final parameter SI.Diameter d=sqrt(4*V_Storage/Modelica.Constants.pi/height) "Diameter of heat storage" ;

  parameter Boolean usePowerPort=true "True if power port shall be used" ;
  parameter Boolean use_T_source_input_K=false "False, use outer ambient conditions" ;
  SI.Temperature T_set=323.15 "Output temperature of the heat pump" ;
  SI.Temperature T_source=simCenter.ambientConditions.temperature.value + 273.15 "Temperature of heat source" ;
  parameter SI.TemperatureDifference Delta_T_internal=5 "Temperature difference between refrigerant and source/sink temperature" ;
  parameter SI.HeatFlowRate Q_flow_n=3.5e3 "Nominal heat flow of heat pump at nominal conditions according to EN14511" ;
  parameter Real COP_n=3.7 "Coefficient of performance at nominal conditions according to EN14511" ;

  parameter SI.Power P_el_n=10e3 "Nominal electric power of the backup heater" ;
  parameter SI.Efficiency eta_Heater=0.95 "Efficiency of the backup heater" ;




  Storage.Heat.HotWaterStorage_constProp_L2.HotWaterStorage_constProp_L2 heatStorage(
    useFluidPorts=false,
    T_s_max=T_set,
    T_s_min=T_s_min,
    height=height,
    d=d,
    T_start=T_s_min + 15,
    T_amb=T_amb,
    k=k) ;
  Modelica.Blocks.Sources.RealExpression realExpression(y=T_set) ;
  TransiEnt.Producer.Heat.Power2Heat.Heatpump.BivalentHeatPumpWithControl heatPumpWithControl(
    control_SoC=control_SoC,
    CalculatePHeater=CalculatePHeater,
    Delta_T_db=Delta_T_db,
    init_state=init_state,
    useFluidPorts=false,
    Delta_T_internal=Delta_T_internal,
    Q_flow_n=Q_flow_n,
    COP_n=COP_n,
    P_el_n_heater=P_el_n,
    T_source=T_source,
    Modulating=Modulating,
    usePowerPort=usePowerPort,
    redeclare connector PowerPortModel = PowerPortModel,
    redeclare model PowerBoundaryModel = PowerBoundaryModel) ;
  replaceable model PowerBoundaryModel = Components.Boundaries.Electrical.ActivePower.Power constrainedby TransiEnt.Components.Boundaries.Electrical.Base.PartialModelPowerBoundary "Choice of power boundary model" ;




  replaceable connector PowerPortModel = TransiEnt.Basics.Interfaces.Electrical.ActivePowerPort constrainedby TransiEnt.Basics.Interfaces.Electrical.ActivePowerPort "Choice of power port" ;
  PowerPortModel epp if usePowerPort ;
  TransiEnt.Basics.Interfaces.Thermal.HeatFlowRateIn Q_Demand ;
equation
  connect(heatPumpWithControl.epp, epp) ;
  connect(realExpression.y, heatPumpWithControl.T_set) ;
  connect(heatStorage.Q_flow_store, heatPumpWithControl.Heat_output) ;
  connect(heatStorage.Q_flow_demand, Q_Demand) ;
  connect(heatStorage.SoC, heatPumpWithControl.SoC) ;
  connect(heatStorage.T_stor_out, heatPumpWithControl.T) 
  ;
end HeatPumpSystem;

