within TransiEnt.Producer.Heat.Power2Heat.Heatpump.Controller;
model ControlHeatpump_heatdriven_BVheatLoad "Heat-driven operation, if bivalent mode selected, heater will switch on additionally to heatpump if heat demand cannot be met."
  extends TransiEnt.Producer.Heat.Power2Heat.Heatpump.Controller.Base.Controller;
  extends TransiEnt.Basics.Icons.Controller;




  parameter Real SoCSet_HP=0.7 ;
  parameter Real SoCLow_HP=0.5 "SoC limit to switch on the heat pump" ;
  parameter Real SoCHigh_HP=1 "SoC limit to switch off the heat pump" ;
  parameter Real SoCLow_Heater=0.25 "SoC limit to switch on the heater" ;
  parameter Real SoCHigh_Heater=0.6 "SoC limit to switch off the heater" ;
  input SI.Temperature THigh_HP=T_set+Delta_T_db/2 "Temperature limit to switch on the heatpump" ;
  input SI.Temperature TLow_HP=T_set-Delta_T_db/2
                                                 "Temperature limit to switch on the heatpump" ;
  input SI.Temperature TLow_Heater=T_set-Delta_T_db "Temperature limit to switch on the heater" ;
  input SI.Temperature THigh_Heater=T_set "Temperature limit to switch off the heater" ;




  Real uHigh_HP;
  Real uLow_HP;
  Real uHigh_Heater;
  Real uLow_Heater;
  Real uSet_HP;




public
  Modelica.Blocks.Logical.Switch switch1 ;
  Modelica.Blocks.Sources.RealExpression zero(y=0) ;
  Modelica.Blocks.Logical.Not Not
    ;
  Modelica.Blocks.Sources.RealExpression uHigh(y=uHigh_HP)
    ;
  Modelica.Blocks.Sources.RealExpression uLow(y=uLow_HP)
    ;
  TransiEnt.Basics.Blocks.Hysteresis_inputVariable hysteresis_HP ;
  TransiEnt.Basics.Blocks.OnOffRelais onOffRelais(
    init_state=init_state,
    t_min_on=t_min_on,
    t_min_off=t_min_off) if MinTimes and not Modulating
    ;
public
  Modelica.Blocks.Logical.Switch switch2  if CalculatePHeater  ;
  Modelica.Blocks.Sources.RealExpression zero1(y=0)  if CalculatePHeater  ;
  Modelica.Blocks.Sources.RealExpression P_Heater(y=P_elHeater)  if CalculatePHeater  ;
  TransiEnt.Basics.Blocks.Hysteresis_inputVariable hysteresis_heater  if CalculatePHeater  ;
  Modelica.Blocks.Sources.RealExpression uHigh1(y=uHigh_Heater)  if CalculatePHeater
    ;
  Modelica.Blocks.Sources.RealExpression uLow1(y=uLow_Heater)  if CalculatePHeater  ;
  Modelica.Blocks.Logical.Not Not1 if CalculatePHeater
    ;
  Modelica.Blocks.Sources.RealExpression Setpoint_HP(y=uSet_HP) if Modulating ;
  Modelica.Blocks.Continuous.LimPID PID(
    Ti=1,
    controllerType=Modelica.Blocks.Types.SimpleController.P,
    yMin=0,
    k=5,
    yMax=1) if Modulating ;
  Modelica.Blocks.Sources.RealExpression Q_flow(y=Q_flow_n)
                                                          ;
  Modelica.Blocks.Math.Product gain if Modulating ;
equation




  uHigh_HP=if control_SoC then SoCHigh_HP else THigh_HP;
  uLow_HP=if control_SoC then SoCLow_HP else TLow_HP;
  uHigh_Heater=if control_SoC then SoCHigh_Heater else THigh_Heater;
  uLow_Heater=if control_SoC then SoCLow_Heater else TLow_Heater;
  uSet_HP=if control_SoC then SoCSet_HP else T_set;




  connect(hysteresis_HP.y, Not.u) ;
  connect(uLow.y, hysteresis_HP.uLow) ;
  connect(uHigh.y, hysteresis_HP.uHigh) ;
  connect(Not.y, onOffRelais.u) ;
  connect(onOffRelais.y, switch1.u2) ;
  connect(T, hysteresis_HP.u) ;
  connect(switch1.y, Q_flow_set_HP) ;
  connect(switch2.y, P_set_electricHeater) ;
  connect(zero1.y, switch2.u3) ;
  connect(hysteresis_heater.u, T) ;
  connect(uHigh1.y, hysteresis_heater.uHigh) ;
  connect(uLow1.y, hysteresis_heater.uLow) ;
  connect(hysteresis_heater.y, Not1.u) ;
  connect(Not1.y, switch2.u2) ;
  connect(zero.y, switch1.u3) ;
  connect(P_Heater.y, switch2.u1) ;
  connect(SoC, hysteresis_HP.u) ;
  connect(SoC, hysteresis_heater.u) ;
  connect(Setpoint_HP.y, PID.u_s) ;
  connect(PID.y, gain.u2) ;
  connect(Q_flow.y, gain.u1) ;
  if not Modulating then
  connect(Q_flow.y, switch1.u1) ;
  end if;
  if not MinTimes or Modulating then
    connect(Not.y,switch1.u2);
  end if;
  connect(gain.y, switch1.u1) ;
  connect(SoC, PID.u_m) ;
  connect(T, PID.u_m) 
  ;
end ControlHeatpump_heatdriven_BVheatLoad;

within TransiEnt.Producer.Heat.Power2Heat.Heatpump.Controller;
model ControlHeatpump_heatdriven_BVTemp "Heat-driven operation with optional startup ramp, if bivalent mode selected, heater will switch on instead of heatpump below T_bivalent"
  extends TransiEnt.Producer.Heat.Power2Heat.Heatpump.Controller.Base.Controller(control_SoC=false);
  extends TransiEnt.Basics.Icons.Controller;




  parameter SI.Temperature T_bivalent=273.15 "Bivalent temperature where heatpump starts operating (if Tamb > T_bivalent)" ;
  parameter SI.Temperature T_heatingLimit=303.15 "Temperature limit above which heatpump is turned off (off ist Tamb>T_heatingLimit)" ;
  parameter Boolean Startupramp=false "If true, ramps at startup and shutdown are considered." ;
  parameter Real SoCSet_HP=0.7 "SoC setpoint for modulating operation" ;
  parameter Real SoCLow_HP=0.5 "SoC limit to switch on the heat pump" ;
  parameter Real SoCHigh_HP=1 "SoC limit to switch off the heat pump" ;




  Modelica.Blocks.Logical.GreaterEqualThreshold isBaseload(threshold=T_bivalent) if CalculatePHeater ;
  Modelica.Blocks.Logical.LessThreshold isHeatdemand(threshold=T_heatingLimit) if CalculatePHeater ;
  Modelica.Blocks.MathBoolean.And isStartRequest(nu=3) if CalculatePHeater ;
  Basics.Blocks.OnOffRelais onOffRelais(
    init_state=init_state,
    t_min_on=t_min_on,
    t_min_off=t_min_off) if MinTimes and not Modulating ;
  Modelica.Blocks.Math.BooleanToReal P_el_HP(realFalse=0, realTrue=Q_flow_n)
                                                                           if not Modulating ;
  Modelica.Blocks.Continuous.FirstOrder shutdown(T=60) if Startupramp ;
  Modelica.Blocks.Sources.BooleanExpression booleanExpression(y=onOffRelais.switch_to_on.outPort.set) if Startupramp and MinTimes and not Modulating ;
  Modelica.Blocks.Continuous.FirstOrder startup(T=10) if Startupramp ;
  Modelica.Blocks.Logical.Switch dynamic if Startupramp ;
  Modelica.Blocks.Math.Add add(k2=-1) if not control_SoC ;
  Modelica.Blocks.Logical.Switch Q_modulating if Modulating ;
  Modelica.Blocks.Continuous.LimPID PID(
    Ti=1,
    controllerType=Modelica.Blocks.Types.SimpleController.P,
    yMin=0,
    k=1000,
    yMax=Q_flow_n)
                  if Modulating ;
  Modelica.Blocks.Sources.RealExpression zero(y=0) if Modulating ;
  Basics.Blocks.Hysteresis_inputVariable controller(pre_y_start=true) ;
  Modelica.Blocks.Sources.RealExpression uHigh(y=if control_SoC then SoCHigh_HP else Delta_T_db/2) ;
  Modelica.Blocks.Sources.RealExpression uLow(y=if control_SoC then SoCLow_HP else -Delta_T_db/2) ;
  Modelica.Blocks.Sources.Constant zero1(k=0) ;
  Modelica.Blocks.Logical.Switch Q_flow_peakload if CalculatePHeater ;
  Modelica.Blocks.Sources.RealExpression P_heater(y=P_elHeater) ;
  Modelica.Blocks.Logical.And and_heater                                         if CalculatePHeater ;
  Modelica.Blocks.Logical.Not isBaseload2                                        if CalculatePHeater ;
  Modelica.Blocks.Sources.RealExpression uLow1(y=if control_SoC then SoCSet_HP else T_set) ;
equation




  connect(T, add.u2) ;
  connect(isStartRequest.y, P_el_HP.u) ;
  connect(shutdown.y, dynamic.u1) ;
  connect(startup.y, dynamic.u3) ;
  connect(booleanExpression.y, dynamic.u2) ;
  connect(P_el_HP.y, shutdown.u) ;
  connect(P_el_HP.y, startup.u) ;
  connect(dynamic.y, Q_flow_set_HP) ;
  connect(T_source, isBaseload.u) ;
  connect(T_source, isHeatdemand.u) ;
  connect(onOffRelais.y, isStartRequest.u[1]) ;
  connect(isHeatdemand.y, isStartRequest.u[3]) ;
  connect(isBaseload.y, isStartRequest.u[2]) ;
  connect(T_set, add.u1) ;
  if not CalculatePHeater then
    connect(onOffRelais.y, P_el_HP.u);
    connect(onOffRelais.y,Q_modulating. u2);
  end if;
  if not Startupramp then
    connect(P_el_HP.y, Q_flow_set_HP);
    connect(Q_modulating.y, Q_flow_set_HP);
  end if;
  if not MinTimes or Modulating then
    connect(controller.y, dynamic.u2);
    if CalculatePHeater then
      connect(controller.y, isStartRequest.u[1]);
      connect(controller.y, and_heater.u2);
    elseif not Modulating then
      connect(controller.y, P_el_HP.u);
    else
      connect(controller.y,Q_modulating. u2);
    end if;
  end if;
  connect(controller.y, onOffRelais.u) ;
  connect(T, PID.u_m) ;
  connect(isStartRequest.y,Q_modulating. u2) ;
  connect(Q_modulating.y, shutdown.u) ;
  connect(Q_modulating.y, startup.u) ;
  connect(uHigh.y, controller.uHigh) ;
  connect(uLow.y, controller.uLow) ;
  connect(controller.u, SoC) ;
  connect(controller.u, add.y) ;
  connect(Q_flow_peakload.y, P_set_electricHeater) ;
  connect(onOffRelais.y, and_heater.u2) ;
  connect(and_heater.y, Q_flow_peakload.u2) ;
  connect(isBaseload.y, isBaseload2.u) ;
  connect(isBaseload2.y, and_heater.u1) ;
  connect(zero1.y, Q_flow_peakload.u3) ;
  connect(P_heater.y, Q_flow_peakload.u1) ;
  connect(PID.y,Q_modulating. u1) ;
  connect(zero.y,Q_modulating. u3) ;
  connect(SoC, PID.u_m) ;
  connect(uLow1.y, PID.u_s) 
  ;
end ControlHeatpump_heatdriven_BVTemp;

