model IrradianceOnATiltedSurface "Combines the calculation of incidence angle of solar irradiance and different models for calculating the solar irradiance on a tilted surface"




  extends TransiEnt.Basics.Icons.Model;
  import Const = Modelica.Constants;
  import      Modelica.Units.SI;
  outer TransiEnt.SimCenter simCenter;




  parameter Boolean use_input_data=false "choose if input data is given by inputs - if not, simCenter data is used";




  TransiEnt.Basics.Interfaces.Ambient.IrradianceIn irradiance_direct_measured_input=irradiance_direct_measured ;
  TransiEnt.Basics.Interfaces.Ambient.IrradianceIn irradiance_diffuse_horizontal_input=irradiance_diffuse_horizontal ;




  SI.Angle angle_direct_tilted;            
  SI.Irradiance irradiance_direct_tilted;  
  SI.Angle angle_diffuse_tilted;           
  SI.Irradiance irradiance_diffuse_tilted;  
  SI.Angle angle_ground_tilted;            
  SI.Irradiance irradiance_ground_tilted;      
  inner SI.Irradiance irradiance_direct_measured "Measured direct irradiance";
  inner SI.Irradiance irradiance_diffuse_horizontal "Measured diffuse irradiance";




  replaceable model Skymodel=SkymodelBase constrainedby SkymodelBase ;
  Skymodel skymodel ;
equation




  if (not use_input_data) then
    irradiance_direct_measured=simCenter.i_direct;
    irradiance_diffuse_horizontal=simCenter.i_diffuse;
  end if;
  irradiance_direct_tilted=skymodel.irradiance_direct_tilted;
  angle_direct_tilted=skymodel.angle_tilted;
  irradiance_diffuse_tilted=skymodel.irradiance_diffuse_tilted;
  angle_diffuse_tilted=Modelica.Units.Conversions.from_deg(59.7 - 0.1388*Modelica.Units.Conversions.to_deg(skymodel.slope) + 0.001497*Modelica.Units.Conversions.to_deg(skymodel.slope)^2);
  irradiance_ground_tilted=skymodel.irradiance_ground_tilted;
  angle_ground_tilted=Modelica.Units.Conversions.from_deg(90 - 0.5788*Modelica.Units.Conversions.to_deg(skymodel.slope) + 0.002693*Modelica.Units.Conversions.to_deg(skymodel.slope)^2)
    ;
end IrradianceOnATiltedSurface;

