model ScaleMassFlow "Scaling mass flow up or down or leave it"




  extends TransiEnt.Basics.Icons.Model;
  import      Modelica.Units.SI;
  import Const = Modelica.Constants;
  outer TransiEnt.SimCenter simCenter;





  parameter TILMedia.VLEFluidTypes.BaseVLEFluid medium=simCenter.fluid1 ;
  parameter Integer n_parallel=1 "Number of parallel collector rows" ;
  parameter Boolean downscale=true "true, if massflow shall be scaled down" ;
  parameter Boolean upscale=false "true, if massflow shall be scaled up" ;




  SI.SpecificEnthalpy h_in;
  SI.SpecificEnthalpy h_out;




  ClaRa.Basics.Interfaces.FluidPortIn fluidPortIn(Medium=medium) ;
  ClaRa.Basics.Interfaces.FluidPortOut fluidPortOut(Medium=medium) ;




protected
  TILMedia.Internals.VLEFluidConfigurations.FullyMixtureCompatible.VLEFluid_ph vleFluidIn(
    vleFluidType=medium,
    p=fluidPortIn.p,
    h=h_in) ;
  TILMedia.Internals.VLEFluidConfigurations.FullyMixtureCompatible.VLEFluid_ph vleFluidOut(
    vleFluidType=medium,
    p=fluidPortOut.p,
    h=h_out) ;
equation




  h_in= if simCenter.useHomotopy then homotopy(actualStream(fluidPortIn.h_outflow), inStream(fluidPortIn.h_outflow)) else actualStream(fluidPortIn.h_outflow);
  h_out= if simCenter.useHomotopy then homotopy(actualStream(fluidPortOut.h_outflow), inStream(fluidPortOut.h_outflow)) else actualStream(fluidPortOut.h_outflow);
  if downscale and not upscale then
    fluidPortIn.m_flow + fluidPortOut.m_flow * n_parallel = 0;
  elseif upscale and not downscale then
    fluidPortIn.m_flow + fluidPortOut.m_flow / n_parallel = 0;
  else
    fluidPortIn.m_flow + fluidPortOut.m_flow = 0;
  end if;
  fluidPortIn.p = fluidPortOut.p;
  fluidPortIn.h_outflow = inStream(fluidPortOut.h_outflow);
  fluidPortIn.xi_outflow = inStream(fluidPortOut.xi_outflow);
  fluidPortOut.h_outflow = inStream(fluidPortIn.h_outflow);
  fluidPortOut.xi_outflow = inStream(fluidPortIn.xi_outflow)
  ;
end ScaleMassFlow;

within TransiEnt.Producer.Heat.SolarThermal.Base;
partial model SkymodelBase "Base model for modeling the influence of orientation of a surface for calculation of irradiance"




  import Const = Modelica.Constants;
  import      Modelica.Units.SI;
  extends ExtraTerrestrialIrradiance;
  extends TransiEnt.Basics.Icons.Model;




  parameter Real reflectance_ground=0.2 "Reflection coefficient of the ground";
  parameter Boolean direct_normal=true "=true, if the direct irradiance measured on a surface is normal to irradiance";




  outer SI.Irradiance irradiance_direct_measured "Measured direct irradiance";
  outer SI.Irradiance irradiance_diffuse_horizontal "Measured diffuse irradiance";
  SI.Irradiance irradiance_direct_horizontal "Direct horizontal irradiance";
  SI.Irradiance irradiance_direct_tilted, irradiance_diffuse_tilted, irradiance_ground_tilted;
  Real ratio_beam "Ratio between direct irradiance on a tilted surface and irradiance on a horizontal surface";
equation




  ratio_beam=max(Const.small, cos(angle_tilted) / max(cos(angle_horizontal),0.01));
  if direct_normal then
    irradiance_direct_horizontal=irradiance_direct_measured*max(cos(angle_horizontal),0);
  else
    irradiance_direct_horizontal=irradiance_direct_measured;
  end if
      ;
end SkymodelBase;

within TransiEnt.Producer.Heat.SolarThermal.Base;
model Skymodel_HDKR "HDKR model - Anisotropic calculation of the irradiance on a tilted surface"




  import Const = Modelica.Constants;
  import      Modelica.Units.SI;
  extends SkymodelBase;




protected
  Real anisotropyIndex "Anisotropy index";
  Real eff "Correction factor by KLUCHER";
equation




  anisotropyIndex= if irradiance_extraterrestrial<=25 then 0 else min(1,max(Const.small,irradiance_direct_horizontal/max(1.5,irradiance_extraterrestrial)));
  eff= sqrt(max(0,irradiance_direct_horizontal) / max(1,(irradiance_direct_horizontal + irradiance_diffuse_horizontal)));
  irradiance_direct_tilted= (irradiance_direct_horizontal)*ratio_beam;
  irradiance_diffuse_tilted= irradiance_diffuse_horizontal*(1-anisotropyIndex)*((1+cos(slope))/2)*(1+eff*(sin(slope/2))^3)+irradiance_diffuse_horizontal*anisotropyIndex*ratio_beam;
  irradiance_ground_tilted= (irradiance_direct_horizontal+irradiance_diffuse_horizontal)*reflectance_ground*(1-cos(slope))/2
  ;
end Skymodel_HDKR;

within TransiEnt.Producer.Heat.SolarThermal.Base;
model Skymodel_isotropicDiffuse "Isotropic calculation of the irradiance on a tilted surface"




  import Const = Modelica.Constants;
  import      Modelica.Units.SI;
  extends SkymodelBase;
equation




  irradiance_direct_tilted = irradiance_direct_horizontal*ratio_beam;
  irradiance_diffuse_tilted= irradiance_diffuse_horizontal*(1 + cos(slope))/2;
  irradiance_ground_tilted= (irradiance_direct_horizontal + irradiance_diffuse_horizontal)*reflectance_ground*(1 - cos(slope))/2
  ;
end Skymodel_isotropicDiffuse;

within TransiEnt.Producer.Heat.SolarThermal.Base;
model Skymodel_Klucher "Klucher model - Anisotropic calculation of the irradiance on a tilted surface"




  import Const = Modelica.Constants;
  import      Modelica.Units.SI;
  extends SkymodelBase;




protected
  Real eff;
equation




  eff= 1-(irradiance_diffuse_horizontal / max(1,(irradiance_direct_horizontal + irradiance_diffuse_horizontal)))^2;
  irradiance_direct_tilted= (irradiance_direct_horizontal)*ratio_beam;
  irradiance_diffuse_tilted= irradiance_diffuse_horizontal*(1+cos(slope))/2*(1+eff*sin(slope/2)^3)*(1+eff*cos(angle_tilted)^2*sin(angle_horizontal)^3);
  irradiance_ground_tilted= (irradiance_direct_horizontal+irradiance_diffuse_horizontal)*reflectance_ground*(1-cos(slope))/2
  ;
end Skymodel_Klucher;

within TransiEnt.Producer.Heat.SolarThermal.Base;
model SolarTime "Calculates the solar time"




  extends TransiEnt.Basics.Icons.Model;
  import Const = Modelica.Constants;
  import      Modelica.Units.SI;




  parameter Real[4] offset(unit={"d","h","m","s"})={0,0,0,0}; 
  parameter SI.Angle longitude_local=Modelica.Units.Conversions.from_deg(10)
                                                                            "East positive, west negative, 10 for Hamburg";
  parameter SI.Angle longitude_standard=Modelica.Units.Conversions.from_deg(15) "15 needed for offset calculation of central european time, 30 for central european summer time";
  parameter Real utc=longitude_standard*12/Const.pi "Difference between UTC and zone time; i.e. +1 in Amsterdam/Berlin/Bern/Rome; default works for standard time, beware of summer time !";




public
  Modelica.Units.NonSI.Time_day dayoftheyear "Day as floating point number. 0.0 at 1.1. 00:00:00, 1.0 at 2.1. 00:00:00 a.s.o.";
  Modelica.Units.NonSI.Time_day totaldays=365 "total days of the year, standard=365, leap year=366";
  SI.Time solarTime "Local solar time in seconds";
  SI.Time offset_sec; 
protected
  SI.Angle J; 
  SI.Time equationOfTime;
equation




  offset_sec=((offset[1]*24+offset[2])*60+offset[3])*60+offset[4];
  J=Modelica.Units.Conversions.from_deg((dayoftheyear)*360/totaldays);
  equationOfTime=60*(0.0066 + 7.3525*cos(J + Modelica.Units.Conversions.from_deg(85.9)) + 9.9359*cos(2*J + Modelica.Units.Conversions.from_deg(108.99)) + 0.3387*cos(3*J + Modelica.Units.Conversions.from_deg(105.2)));
  dayoftheyear=noEvent(integer((time+offset_sec)/(24*60*60)+1));
  solarTime=time-utc*60*60+offset_sec+4*60*Modelica.Units.Conversions.to_deg(longitude_local)+equationOfTime
  ;
end SolarTime;

