  TransiEnt.Basics.Interfaces.General.TemperatureIn T_solar_out ;
  TransiEnt.Basics.Interfaces.General.TemperatureIn T_solar_in ;
  Modelica.Blocks.Interfaces.RealOutput y ;




  Modelica.Blocks.Logical.Switch switch ;
  Modelica.Blocks.Sources.RealExpression OFF(y=y_small) ;
  Modelica.Blocks.Logical.Hysteresis hysteresis(uLow=delta_T_off, uHigh=delta_T_on) ;
  Modelica.Blocks.Math.Add difference(k2=-1) ;
  TransiEnt.Basics.Blocks.OnOffRelais onOffRelais(init_state=2,
    t_min_on=t_min_on,
    t_min_off=t_min_off)                          ;
  TransiEnt.Basics.Blocks.FirstOrder myFirstOrder(Tau=Tau_out, y_start=y_small) ;
