    y_max=100,
    y_min=1e-6,
    k=1e6) ;
equation




  connect(difference.y, hysteresis.u) ;
  connect(T_solar_out, difference.u1) ;
  connect(T_solar_in, difference.u2) ;
  connect(switch.u2, onOffRelais.y) ;
  connect(hysteresis.y, onOffRelais.u) ;
  if Tau_out>0 then
  else
  end if;
  connect(myFirstOrder.y, y) ;
  connect(switch.y, myFirstOrder.u) ;
