model ControllerPumpSolarCollectorTandG "Model for controlling the pump drive supplying of the collector field"
extends TransiEnt.Basics.Icons.Controller;
import      Modelica.Units.SI;
parameter SI.Irradiance G_min=0 "minimum Irradiance before collector is working" ;
parameter SI.Temperature T_set=323.15 "Temperature set point for controller" ;
parameter SI.MassFlowRate m_flow_min=0.01 "minimum massflow" ;
parameter SI.Pressure Delta_p=0 "Pressure loss of the system at minimum massflow" ;
parameter SI.Efficiency eta_mech=0.98 "mechanic efficiency of the drive" ;
parameter SI.Density rho_m=1000 "Fluid Density - mean value" ;
parameter SI.Temperature T_stor_max= 273.15+90 "Maximum Temperature at which collector is turned off" ;
parameter SI.Temperature T_min= 273.15 "MinimumTemperature at which collector is turned off" ;
parameter Real k_first(unit="1")=1 "Gain" ;
parameter SI.Time T(start=1) "Time Constant" ;
parameter Modelica.Blocks.Types.Init initType_first=Modelica.Blocks.Types.Init.NoInit "Type of initialization (1: no init, 2: steady state, 3/4: initial output)"   ;
parameter Real y_start_first=0 "Initial or guess value of output (= state)" ;
parameter Modelica.Blocks.Types.SimpleController controllerType= Modelica.Blocks.Types.SimpleController.PID "Type of controller" ;
parameter Real k_PID(min=0, unit="1") = 1 "Gain of controller" ;
parameter SI.Time Ti(min=Modelica.Constants.small)=0.5 "Time constant of Integrator block" ;
parameter SI.Time Td(min=0)= 0.1 "Time constant of Derivative block" ;
parameter Real yMax(start=1) "Upper limit of output"
                                                    ;
parameter Real yMin=0 "Lower limit of output" ;
parameter Real wp(min=0) = 1 "Set-point weight for Proportional block (0..1)"
                                                                             ;
parameter Real wd(min=0) = 0 "Set-point weight for Derivative block (0..1)" ;
parameter Real Ni(min=100*Modelica.Constants.eps) = 0.9 "Ni*Ti is time constant of anti-windup compensation" ;
parameter Real Nd(min=100*Modelica.Constants.eps) = 10 "The higher Nd, the more ideal the derivative block" ;
  parameter Modelica.Blocks.Types.Init initType_PID=Modelica.Blocks.Types.Init.InitialState "Type of initialization (1: no init, 2: steady state, 3: initial state, 4: initial output)" ;
parameter Boolean limitsAtInit = true "= false, if limits are ignored during initialization" ;
parameter Real xi_start=0 "Initial or guess value value for integrator output (= integrator state)" ;
parameter Real xd_start=0 "Initial or guess value for state of derivative block" ;
parameter Real y_start_PID=0 "Initial value of output" ;
parameter Boolean strict=false "= true, if strict limits with noEvent(..)" ;
parameter Real eps=1e-6 "smallest output" ;
parameter SI.TemperatureDifference Delta_T_db = 1 "Deadband of maximum storage temperature hysteresis" ;
  Modelica.Blocks.Continuous.LimPID PID(
    controllerType=controllerType,
    k=k_PID,
    Ti=Ti,
    Td=Td,
    wp=wp,
    wd=wd,
    Ni=Ni,
    Nd=Nd,
    yMax=yMax,
    yMin=yMin,
    initType=initType_PID,
    xi_start=xi_start,
    xd_start=xd_start,
    y_start=y_start_PID,
    strict=strict) ;
  Modelica.Blocks.Sources.Constant set_point_temp(k=T_set) ;
  Modelica.Blocks.Continuous.FirstOrder firstOrder(
    T=T,
    y_start=y_start_first,
    k=k_first,
    initType=initType_first)                            ;
  Modelica.Blocks.Logical.GreaterEqual greaterEqual ;
  Modelica.Blocks.Sources.Constant min_irradiance(k=G_min) ;
  Modelica.Blocks.Logical.Switch switch2 ;
  Modelica.Blocks.Sources.Constant zero(k=eps)
                                             ;
  TransiEnt.Basics.Interfaces.General.TemperatureIn T_out ;
  Modelica.Blocks.Interfaces.RealInput G_total ;
  TransiEnt.Basics.Interfaces.Electrical.ElectricPowerOut P_drive ;
  Modelica.Blocks.Sources.Constant P_drive_min(k=m_flow_min*Delta_p/(eta_mech*rho_m)) ;
  Modelica.Blocks.Math.Add add ;
  Modelica.Blocks.Logical.Hysteresis Hysteresis_T_stor(uLow=T_stor_max - Delta_T_db,                         uHigh=T_stor_max) ;
  TransiEnt.Basics.Interfaces.General.TemperatureIn T_stor
                                             ;
  Modelica.Blocks.Logical.And and1 ;
  TransiEnt.Basics.Interfaces.General.TemperatureIn T_in ;
  Modelica.Blocks.Logical.GreaterThreshold greaterThreshold_freezingPoint(threshold=T_min)  ;
  Modelica.Blocks.Logical.And and2 ;
  Modelica.Blocks.Logical.Not not1 ;
equation
  connect(PID.u_m, set_point_temp.y) ;
  connect(firstOrder.y,PID. u_s) ;
  connect(T_out, firstOrder.u) ;
  connect(min_irradiance.y, greaterEqual.u2) ;
  connect(add.u1, P_drive_min.y) ;
  connect(add.u2, PID.y) ;
  connect(switch2.u1, add.y) ;
  connect(switch2.u3, zero.y) ;
  connect(switch2.y, P_drive) ;
  connect(greaterEqual.u1, G_total) ;
  connect(T_stor, Hysteresis_T_stor.u) ;
  connect(greaterEqual.y, and1.u1) ;
  connect(T_in, greaterThreshold_freezingPoint.u) ;
  connect(greaterThreshold_freezingPoint.y, and2.u1) ;
  connect(and1.y, and2.u2) ;
  connect(and2.y, switch2.u2) ;
  connect(Hysteresis_T_stor.y, not1.u) ;
  connect(not1.y, and1.u2) 
  ;
end ControllerPumpSolarCollectorTandG;

