within TransiEnt.Storage.Gas.Base;
partial model PartialGasStorage_L2 "Partial model of a simple gas storage volume for real gases"




  extends TransiEnt.Storage.Gas.Base.PartialGasStorage(includeHeatTransfer=true);
  import Modelica.Constants.pi;




  final parameter SI.Diameter diameter=sqrt(4*V_geo/(pi*height)) "Diameter of storage";
  final parameter SI.Area A_heat=pi/2*diameter^2+pi*diameter*height "Surface area of storage";




  parameter SI.Height height=3.779*V_geo^(1/3) "Height of storage" ; 
  parameter Boolean start_pressure=true "true if a start pressure is defined, false if a start mass is defined" ;
  parameter SI.Pressure p_gas_start=1e5 "pressure in storage at t=0" ;
  parameter SI.ThermodynamicTemperature T_gas_start=283.15 "Temperature of gas in storage at t=0" ;












  replaceable model HeatTransfer =
    TransiEnt.Storage.Gas.Base.ConstantHTOuterTemperature_L2
    constrainedby TransiEnt.Storage.Gas.Base.HeatTransferOuterTemperature_L2 "Heat transfer model for inside the storage" ;
protected
  TILMedia.Internals.VLEFluidConfigurations.FullyMixtureCompatible.VLEFluid_ph gasBulk(
    vleFluidType=medium,
    computeSurfaceTension=false,
    p=gasPortIn.p,
    h=h_gas,
    xi=xi_gas,
    deactivateTwoPhaseRegion=true) ;
  TILMedia.Internals.VLEFluidConfigurations.FullyMixtureCompatible.VLEFluid_ph gasIn(
    vleFluidType=medium,
    computeSurfaceTension=false,
    deactivateDensityDerivatives=true,
    p=gasPortIn.p,
    h=actualStream(gasPortIn.h_outflow),
    xi=actualStream(gasPortIn.xi_outflow),
    deactivateTwoPhaseRegion=true) ;
  TILMedia.Internals.VLEFluidConfigurations.FullyMixtureCompatible.VLEFluid_ph gasOut(
    vleFluidType=medium,
    computeSurfaceTension=false,
    deactivateDensityDerivatives=true,
    p=gasPortOut.p,
    h=actualStream(gasPortOut.h_outflow),
    xi=actualStream(gasPortOut.xi_outflow),
    deactivateTwoPhaseRegion=true) ;
public
  HeatTransfer heatTransfer(final A_heat=A_heat) ;




protected
  SI.SpecificEnthalpy h_gas "Specific enthalpy of gas in storage";
  SI.HeatFlowRate Q_flow_ht "Heat flow from the gas to the wall";
  Real drhodt "Time derivative of the density (unit kg/(m3s))";




initial equation
  if start_pressure then
    gasBulk.p = p_gas_start;
  else
    gasBulk.p = TILMedia.Internals.VLEFluidConfigurations.FullyMixtureCompatible.VLEFluidFunctions.pressure_dTxi(
      vleFluidType=medium,
      d=m_gas_start/V_geo,
      T=T_gas_start,
      xi=gasBulk.xi);
  end if;
  gasBulk.T=T_gas_start;
equation
  p_gas = gasBulk.p;

  V_geo*drhodt=gasPortIn.m_flow+gasPortOut.m_flow "Conservation of Mass";






  V_geo*drhodt*h_gas - der(p_gas)*V_geo + m_gas*der(h_gas) = gasPortIn.m_flow*actualStream(gasPortIn.h_outflow) + gasPortOut.m_flow*actualStream(gasPortOut.h_outflow) + Q_flow_ht "Conservation of Energy"; 


  Q_flow_ht=if includeHeatTransfer then heatTransfer.heat.Q_flow else 0;
  gasBulk.d = m_gas/V_geo;
  gasPortOut.h_outflow=h_gas;
  gasPortOut.xi_outflow=gasBulk.xi;
  gasPortOut.p=gasBulk.p;
  gasPortIn.xi_outflow=xi_gas;
  gasPortIn.h_outflow=h_gas;
  heatTransfer.T_outer=gasBulk.T;
  H_flow_in_NCV=gasPortIn.m_flow*(NCV*cat(1,gasIn.xi,{1-sum(gasIn.xi)}));
  H_flow_out_NCV=gasPortOut.m_flow*(NCV*cat(1,gasOut.xi,{1-sum(gasOut.xi)}));
  H_gas_NCV=m_gas*(NCV*cat(1,gasBulk.xi,{1-sum(gasBulk.xi)}));
  H_flow_in_GCV=gasPortIn.m_flow*(GCV*cat(1,gasIn.xi,{1-sum(gasIn.xi)}));
  H_flow_out_GCV=gasPortOut.m_flow*(GCV*cat(1,gasOut.xi,{1-sum(gasOut.xi)}));
  H_gas_GCV=m_gas*(GCV*cat(1,gasBulk.xi,{1-sum(gasBulk.xi)}));




  connect(heatTransfer.heat, heat) 
  ;
end PartialGasStorage_L2;

within TransiEnt.Storage.Heat.HotWaterStorage_constProp_L4.Base;
model Buoyancy "Model to add buoyancy if there is a temperature inversion in the tank"





  extends TransiEnt.Basics.Icons.Block;
  extends TransiEnt.Basics.Icons.ThermalStorageBasic;




  parameter Modelica.Units.SI.Volume V "Volume of tank";
  parameter Integer N_cv(min=3) = 3 "Number of finite control volumes";
  parameter Modelica.Units.SI.Time tau(min=0) "Time constant for buoyancy mixing";
  parameter Modelica.Units.SI.Density rho=998 "Density, used to compute fluid mass";
  parameter Modelica.Units.SI.SpecificHeatCapacity c_v=4.2e3 "Specific heat capacity";
   final parameter Real k(unit="W/K") = V*rho*c_v/tau/N_cv "Proportionality constant, since we use Delta_T instead of dH";




  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a[N_cv] heatPort "Heat input into the volumes" ;




  Modelica.Units.SI.HeatFlowRate[N_cv - 1] Q_flow "Heat flow rate due to buoyancy from segment i to i+1";
  Modelica.Units.SI.TemperatureDifference Delta_T[N_cv - 1] "Driving Temperature difference between adjoining control volumes";
equation
  for i in 1:N_cv-1 loop

    Delta_T[i] = -heatPort[i].T+heatPort[i+1].T;

    Q_flow[i] = k*noEvent(smooth(1, if Delta_T[i]>0 then Delta_T[i]^2 else 0));
  end for;

  heatPort[1].Q_flow = -Q_flow[1];
  for i in 2:N_cv-1 loop
    heatPort[i].Q_flow = -Q_flow[i]+Q_flow[i-1];
  end for;
  heatPort[N_cv].Q_flow = Q_flow[N_cv-1]
  ;
end Buoyancy;

within TransiEnt.Storage.Heat.HotWaterStorage_constProp_L4.Base;
model Diffusion "Second order 1D finite difference approximation of heat diffusion"





  extends TransiEnt.Basics.Icons.Block;




  parameter SI.Area A=1 "cross section area of control volume";
  parameter Integer N_cv=100 "Number of control volumes";
  parameter SI.Length dx = 0.01 "Heigth of control volume";
  parameter SI.ThermalConductivity k = 0.6 "Thermal conductivity of fluid in storage";
  final parameter Real G_diff = A*k/dx;




  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a[N_cv] heatPort "Heat input into the volumes" ;
equation

  heatPort[1].Q_flow = - G_diff * (heatPort[2].T-heatPort[1].T);

  for i in 2:N_cv-1 loop
    heatPort[i].Q_flow = - G_diff*(heatPort[i+1].T-2*heatPort[i].T+heatPort[i-1].T);
  end for;

  heatPort[N_cv].Q_flow = - G_diff * (heatPort[N_cv-1].T-heatPort[N_cv].T)
  ;
end Diffusion;

within TransiEnt.Storage.Heat.HotWaterStorage_constProp_L4.Base;
function getIdxFromHeight "Returns index of closest control volume matching the given height"
  input Integer N "Number of volumes";
  input SI.Length h "Total height";
  input SI.Length hq "Query height";
  output Integer iq "Index";
protected
          SI.Length[N] Dh=(1/(2*N):1/N:1)*h;
algorithm
  assert(hq<=h and hq>=0, "Port height must be between 0 and h");
  iq:=N;
  if Dh[N]<= hq then
    iq:=1;
  end if;
  for i in 2:N loop
    if Dh[i]>=hq then
      iq:=if Dh[i]-hq > hq-Dh[i-1] then 2+N-i else N-i+1;
      break;
    end if;
  end for
  ;
end getIdxFromHeight;

within TransiEnt.Storage.Heat.HotWaterStorage_constProp_L4.Base;
function getPortCount "Returns vector with number of ports per control volume depending on location of fluid connectors"




  import TransiEnt.Basics.Functions.getNumberOfOccurences;




  input Integer N;
  input Integer i_prodIn[:];
  input Integer i_prodOut[:];
  input Integer i_gridIn[:];
  input Integer i_gridOut[:];
  output Integer portCount[N];




protected
  Integer n;




algorithm
  for i in 1:N loop
    if i>1 and i<N then
    portCount[i]:=2 "Volumes in between start at 2";
    else
      portCount[i]:=1 "Volumes at ends of tank start at 1";
    end if;
    n:=getNumberOfOccurences(i, i_prodIn);
    if n<>0 then
      portCount[i]:=portCount[i]+n;
    end if;
    n:=getNumberOfOccurences(i, i_prodOut);
    if n<>0 then
      portCount[i]:=portCount[i]+n;
    end if;
    n:=getNumberOfOccurences(i, i_gridIn);
    if n<>0 then
      portCount[i]:=portCount[i]+n;
    end if;
    n:=getNumberOfOccurences(i, i_gridOut);
    if n<>0 then
      portCount[i]:=portCount[i]+n;
    end if;
  end for
  ;
end getPortCount;

within TransiEnt.Storage.Heat.HotWaterStorage_constProp_L4.Base;
function getPortSubIndex "Returns index of control volumes fluid port for input fluid connectors"




  import TransiEnt.Basics.Functions.findAll;




  input Integer N;
  input Integer i_prodIn[:];
  input Integer i_prodOut[:];
  input Integer i_gridIn[:];
  input Integer i_gridOut[:];
  output Integer portSubIdx[4,max({size(i_prodIn,1),size(i_prodOut,1),size(i_gridIn,1),size(i_gridOut,1)})];




protected
  Integer portCount[N];
  Integer n[:];




algorithm
  for i in 1:N loop
    if i>1 and i<N then
    portCount[i]:=2 "Volumes in between start at 2";
    else
      portCount[i]:=1 "Volumes at ends of tank start at 1";
    end if;

    n:=findAll(i, i_prodIn);
    if n[1]<>0 then
      for j in n loop
        portCount[i]:=portCount[i]+1;
        portSubIdx[1,j]:=portCount[i];
      end for;
    end if;

    n:=findAll(i, i_prodOut);
    if n[1]<>0 then
      for j in n loop
        portCount[i]:=portCount[i]+1;
        portSubIdx[2,j]:=portCount[i];
      end for;
    end if;

    n:=findAll(i, i_gridIn);
    if n[1]<>0 then
      for j in n loop
        portCount[i]:=portCount[i]+1;
        portSubIdx[3,j]:=portCount[i];
      end for;
    end if;

    n:=findAll(i, i_gridOut);
    if n[1]<>0 then
      for j in n loop
        portCount[i]:=portCount[i]+1;
        portSubIdx[4,j]:=portCount[i];
      end for;
    end if;
  end for
  ;
end getPortSubIndex;

