within TransiEnt.Storage.Heat.HotWaterStorage_L4.Utilities;
function get_init_segment_enthalpy_linear "[nLayer, T1, T2, T3, T4, T1_layer, T2_layer, T3_layer, T4_layer] calculates initial values through linear interpolation between the four measured temperatures in the tank"
extends TransiEnt.Basics.Icons.Function;
  input Integer nLayer;
  input Real T_min;  
  input Real T_max;  
  output Real[nLayer] layered_h;
protected
  Real h_min;
  Real h_max;
  Real dh;
  Integer k=1;
  constant Real c_p = 4180;  
algorithm
  h_min :=c_p*T_min;
  h_max :=c_p*T_max;
layered_h[1]:=h_max;
dh:=(h_min - h_max)/(nLayer-1);
k:=1;
for i in 2:nLayer loop
  layered_h[i]:=h_max + k*dh;
  k:=k + 1;
end for
  ;
end get_init_segment_enthalpy_linear;

within TransiEnt.Storage.Heat.HotWaterStorage_L4.Utilities;
function get_init_segment_enthalpy_piecewise_linear "[nLayer, T1, T2, T3, T4, T1_layer, T2_layer, T3_layer, T4_layer] calculates initial values through linear interpolation between the four measured temperatures in the tank"
  extends TransiEnt.Basics.Icons.Function;
  input Integer nLayer;
  input Real T1;  
  input Real T2;  
  input Real T3;  
  input Real T4;  
  input Integer T1_layer;
  input Integer T2_layer;
  input Integer T3_layer;
  input Integer T4_layer;
  output Real[nLayer] layered_h;
protected
  Real dh;
  Integer k=1;
  constant Real c_p = 4180;  
algorithm
 for i in 1:T1_layer loop
   layered_h[i]:= c_p*T1;
  end for;
    dh:= c_p*(T2 - T1)/(T2_layer - T1_layer);
    k:=1;
  for i in (T1_layer+1):T2_layer loop
   layered_h[i]:= c_p*T1 + k*dh;
   k:=k + 1;
  end for;
    dh:=c_p*(T3 - T2)/(T3_layer - T2_layer);
    k:=1;
  for i in (T2_layer+1):T3_layer loop
   layered_h[i]:= c_p*T2 + k*dh;
   k:=k + 1;
  end for;
    dh:=c_p*(T4 - T3)/(T4_layer - T3_layer);
    k:=1;
  for i in (T3_layer+1):T4_layer loop
    layered_h[i]:=c_p*T3 + k*dh;
    k:=k + 1;
  end for;
  for i in T4_layer:nLayer loop
    layered_h[i]:=c_p*T4;
  end for
  ;
end get_init_segment_enthalpy_piecewise_linear;

within TransiEnt.Storage.Heat.HotWaterStorage_L4.Utilities;
function get_init_segment_enthalpy_piecewise_linear_Input_Kelvin "[nLayer, T1, T2, T3, T4, T1_layer, T2_layer, T3_layer, T4_layer] calculates initial values through linear interpolation between the four measured temperatures in the tank"
extends TransiEnt.Basics.Icons.Function;
  input Integer nLayer;
  input Real T_1;  
  input Real T_2;  
  input Real T_3;  
  input Real T_4;  
  input Integer T1_layer;
  input Integer T2_layer;
  input Integer T3_layer;
  input Integer T4_layer;
  output Real[nLayer] layered_h;
protected
  Real dh;
  Integer k=1;

  constant Real c_p = 4196;  
  Real T1= T_1-273.15;   
  Real T2= T_2-273.15;   
  Real T3= T_3-273.15;   
  Real T4= T_4-273.15;   
algorithm
 for i in 1:T1_layer loop
   layered_h[i]:= c_p*T1;
  end for;
    dh:= c_p*(T2 - T1)/(T2_layer - T1_layer);
    k:=1;
  for i in (T1_layer+1):T2_layer loop
   layered_h[i]:= c_p*T1 + k*dh;
   k:=k + 1;
  end for;
    dh:=c_p*(T3 - T2)/(T3_layer - T2_layer);
    k:=1;
  for i in (T2_layer+1):T3_layer loop
   layered_h[i]:= c_p*T2 + k*dh;
   k:=k + 1;
  end for;
    dh:=c_p*(T4 - T3)/(T4_layer - T3_layer);
    k:=1;
  for i in (T3_layer+1):T4_layer loop
    layered_h[i]:=c_p*T3 + k*dh;
    k:=k + 1;
  end for;
  for i in T4_layer:nLayer loop
    layered_h[i]:=c_p*T4;
  end for
  ;
end get_init_segment_enthalpy_piecewise_linear_Input_Kelvin;

within TransiEnt.Storage.Heat.HotWaterStorage_L4.Utilities;
function get_Layer "[height_port, layer_height, nLayer] Calculates the layer for a given height."
extends TransiEnt.Basics.Icons.Function;
  input Real height_port(min=0);
  input Real height_segment;
  input Integer nSeg(min=1);
  output Integer segment(min=1);
algorithm
  if (height_port == 0) then
    segment := nSeg;
  else
    segment :=nSeg + 1 - integer(ceil(height_port/height_segment));
  end if;
  assert(height_port <= nSeg*height_segment,
      "Height of port is higher than height of tank. Adjust!");
  assert(height_segment > 0,
      "Height of segment needs a positve value. Adjust!");
  assert(height_port >= 0,
      "Height of port needs a positve or zero value. Adjust!")
  ;
end get_Layer;

