within TransiEnt.Storage.Heat.PackedBedStorage_L4.Basics.EffectiveThermalConductivity;
model Constant "Constant"




  extends TransiEnt.Storage.Heat.PackedBedStorage_L4.Basics.EffectiveThermalConductivity.ThermalConductivityBasePackedBed;




  parameter ClaRa.Basics.Units.ThermalConductivity lambda_eff_const = 1 "Effective Thermal Conductivity of Packed Bed";
equation




  lambda_eff_axial = ones(iCom.N_cv)*lambda_eff_const;
  lambda_eff_radial = ones(iCom.N_cv)*lambda_eff_const
  ;
end Constant;

within TransiEnt.Storage.Heat.PackedBedStorage_L4.Basics.EffectiveThermalConductivity;
model PorosityWeightedThermalConductivities "Porosity Weighted"




  extends TransiEnt.Storage.Heat.PackedBedStorage_L4.Basics.EffectiveThermalConductivity.ThermalConductivityBasePackedBed;




  outer TILMedia.Gas_ph fluid[iCom.N_cv];
  outer TransiEnt.Basics.Media.SolidWithTemperatureVariantHeatCapacity rock[iCom.N_cv];
equation




   lambda_eff_axial = iCom.porosity*fluid.transp.lambda+(1-iCom.porosity)*rock.lambda;
   lambda_eff_radial = iCom.porosity*fluid.transp.lambda+(1-iCom.porosity)*rock.lambda
  ;
end PorosityWeightedThermalConductivities;

within TransiEnt.Storage.Heat.PackedBedStorage_L4.Basics.EffectiveThermalConductivity;
partial model ThermalConductivityBasePackedBed "Partial thermal conductivity model for packed beds"




  import SI = ClaRa.Basics.Units;




  constant String gas="true";




  outer parameter Boolean useHomotopy;




  outer TransiEnt.Storage.Heat.PackedBedStorage_L4.Basics.Records.IComPackedBedControlVolume_L4 iCom;
  outer TransiEnt.Storage.Heat.PackedBedStorage_L4.Basics.PackedBedGeometry.PackedBedGeometry_N_cv geo;




  SI.MassFlowRate m_flow[iCom.N_cv + 1] "Mass flow rate";
  SI.Power Q_flow[iCom.N_cv + 1] "Heat Conduction between cells";
  SI.ThermalConductivity lambda_eff_axial[iCom.N_cv] "Effective Thermal Conductivity of Packed Bed";
  SI.ThermalConductivity lambda_eff_radial[iCom.N_cv] "Effective Thermal Conductivity of Packed Bed";
equation




  for i in 2:iCom.N_cv loop
   Q_flow[i] = (iCom.T[i-1]-iCom.T[i])*geo.A_cross_bed_FM[i]/geo.Delta_x_FM[i]*(lambda_eff_axial[i-1]+lambda_eff_axial[i])/2;
  end for;
 Q_flow[1] = 0;
 Q_flow[iCom.N_cv+1] = 0
  ;
end ThermalConductivityBasePackedBed;

within TransiEnt.Storage.Heat.PackedBedStorage_L4.Basics.EffectiveThermalConductivity;
model VDIHeatAtlas "VDI Heat Atlas"




  extends TransiEnt.Storage.Heat.PackedBedStorage_L4.Basics.EffectiveThermalConductivity.ThermalConductivityBasePackedBed;




  parameter Real epsilon = 0.85 "Long wave emission factor";
  parameter Real CF = 1.4 "Additional form factor";
  parameter Real Phi = 0.001 "Form Coefficient Phi";
  parameter Real K_ax = 2 "Axial correction factor";
  parameter Real K_rad = 5.7 "Radial correction factor";
  final parameter Real B = CF*((1-iCom.porosity)/iCom.porosity)^(10/9);




  outer TILMedia.Gas_ph fluid[iCom.N_cv];
  outer TransiEnt.Basics.Media.SolidWithTemperatureVariantHeatCapacity rock[iCom.N_cv];




  ClaRa.Basics.Units.ThermalConductivity[iCom.N_cv] lambda_eff_0 "Effective Thermal Conductivity of Packed Bed at stagnant fluid";
protected
  Real w[iCom.N_cv] "Medium superficial velocity";
  Real k_c[iCom.N_cv];
  Real k_p[iCom.N_cv];
  Real N[iCom.N_cv];
  Real k_bed[iCom.N_cv];
  Real k_rad[iCom.N_cv];
  Real k_G[iCom.N_cv] = ones(iCom.N_cv) "Minor influence";
  Real Pe[iCom.N_cv] "Peclet Number";
equation




  for i in 1:iCom.N_cv loop
  w[i] = ((m_flow[i]+m_flow[i+1])/2) ./ fluid[i].d ./ geo.A_cross_bed_FM[i];
  k_p[i] = rock[i].lambda/fluid[i].transp.lambda;
  N[i] = 1/k_G[i]*(1+(k_rad[i]-B*k_G[i])/k_p[i]) - B*(1/k_G[i]-1)*(1+k_rad[i]/k_p[i]);
  k_c[i] = 2/N[i]*(B*(k_p[i]+k_rad[i]-1)/(N[i]^2*k_G[i]*k_p[i])*Modelica.Math.log((k_p[i]+k_rad[i])/(B*(k_G[i]+(1-k_G[i])*(k_p[i]+k_rad[i]))))
           + (B+1)/(2*B)*(k_rad[i]/k_G[i] - B*(1+(1-k_G[i])/k_G[i]*k_rad[i]))
           - (B-1)/(N[i]*k_G[i]));
  k_rad[i] = 4*Modelica.Constants.sigma/(2/epsilon - 1)*iCom.T[i]^3*iCom.d_v_m/fluid[i].transp.lambda;
  k_bed[i] = (1-sqrt(1-iCom.porosity))*iCom.porosity*(1/(iCom.porosity-1+1/k_G[i]) + k_rad[i])+ sqrt(1-iCom.porosity)*(Phi*k_p[i]+(1-Phi)*k_c[i]);
  lambda_eff_0[i] = k_bed[i]*fluid[i].transp.lambda;
  Pe[i] = noEvent(abs(w[i])) .* iCom.d_v_m .* fluid[i].d .* fluid[i].cp ./ (fluid[i].transp.lambda);
  lambda_eff_axial[i] = lambda_eff_0[i] + Pe[i]./K_ax.*fluid[i].transp.lambda; 
  lambda_eff_radial[i] = lambda_eff_0[i] + Pe[i]./K_rad.*fluid[i].transp.lambda;
  end for
  ;
end VDIHeatAtlas;

within TransiEnt.Storage.Heat.PackedBedStorage_L4.Basics.EffectiveThermalConductivity;
model ZehnerBauerSchluender "Zehner/Bauer/Schluender Correlation"




  extends TransiEnt.Storage.Heat.PackedBedStorage_L4.Basics.EffectiveThermalConductivity.ThermalConductivityBasePackedBed;




  outer TILMedia.Gas_ph fluid[iCom.N_cv];
  outer TransiEnt.Basics.Media.SolidWithTemperatureVariantHeatCapacity rock[iCom.N_cv];




  parameter Real epsilon = 0.85 "Long wave emission factor";
  parameter Real CF = 1.4 "Additional form factor";
  parameter Real Phi = 0.001 "Form Coefficient Phi";
  final parameter Real B = CF*((1-iCom.porosity)/iCom.porosity)^(10/9);




  ClaRa.Basics.Units.ThermalConductivity[iCom.N_cv] lambda_eff_0 "Effective Thermal Conductivity of Packed Bed at stagnant fluid";
protected
  Real k_c[iCom.N_cv];
  Real k_p[iCom.N_cv];
  Real N[iCom.N_cv];
  Real k_bed[iCom.N_cv];
  Real k_rad[iCom.N_cv];
  Real k_G[iCom.N_cv] = ones(iCom.N_cv) "Minor influence";
equation




  for i in 1:iCom.N_cv loop
  k_p[i] = rock[i].lambda/fluid[i].transp.lambda;
  N[i] = 1/k_G[i]*(1+(k_rad[i]-B*k_G[i])/k_p[i]) - B*(1/k_G[i]-1)*(1+k_rad[i]/k_p[i]);
  k_c[i] = 2/N[i]*(B*(k_p[i]+k_rad[i]-1)/(N[i]^2*k_G[i]*k_p[i])*Modelica.Math.log((k_p[i]+k_rad[i])/(B*(k_G[i]+(1-k_G[i])*(k_p[i]+k_rad[i]))))
           + (B+1)/(2*B)*(k_rad[i]/k_G[i] - B*(1+(1-k_G[i])/k_G[i]*k_rad[i]))
           - (B-1)/(N[i]*k_G[i]));
  k_rad[i] = 4*Modelica.Constants.sigma/(2/epsilon - 1)*iCom.T[i]^3*iCom.d_v_m/fluid[i].transp.lambda;
  k_bed[i] = (1-sqrt(1-iCom.porosity))*iCom.porosity*(1/(iCom.porosity-1+1/k_G[i]) + k_rad[i])+ sqrt(1-iCom.porosity)*(Phi*k_p[i]+(1-Phi)*k_c[i]);
  lambda_eff_0[i] = k_bed[i]*fluid[i].transp.lambda;
  end for;
  lambda_eff_axial = lambda_eff_0;
  lambda_eff_radial = lambda_eff_0
  ;
end ZehnerBauerSchluender;

