within TransiEnt.Storage.Heat.PackedBedStorage_L4.Basics.PackedBedGeometry;
model PackedBedGeometry_N_cv "Base class for packed bed geometry"




  import SI = ClaRa.Basics.Units;
  extends ClaRa.Basics.ControlVolumes.Fundamentals.Geometry.TubeType;




  outer parameter Real porosity = 0.5 "Packed bed porosity";




  parameter SI.Length z_in=0 "Height of inlet ports" ;
  parameter SI.Length z_out=0 "Height of outlet ports" ;
  parameter SI.Length z[N_cv]=fill(1,N_cv) "Height of center of cells" ;
  parameter SI.Length Delta_z_in[N_cv] = {sum(Delta_x[1:i]) - Delta_x[i]/2 for i in 1:N_cv} "Length from inlet to center of cells"
                                                                                          ;
  parameter Integer N_cv=10 "Number of control volumes" ;
  parameter SI.Length length = 1 "Length in flow direction" ;
  parameter SI.Length max_height[N_cv] = ones(N_cv) "max height per cross section" ;
  parameter SI.Length circumference[N_cv] = ones(N_cv) "Circumference of each cross section" ;
  parameter SI.Area A_cross_bed[N_cv](min=ones(N_cv)*Modelica.Constants.eps) = ones(N_cv) "Cross Area of packed bed" ;




  final parameter SI.Volume volume_bed[N_cv](min=ones(N_cv)*Modelica.Constants.eps) = A_cross_bed.*Delta_x "Volume of each packed bed control volume" ;
  final parameter SI.Area A_heat[N_cv](each min=Modelica.Constants.eps) = circumference.*Delta_x "Lateral heat transfer area of each control volume" ;
  final parameter SI.Length Delta_x[N_cv]=ClaRa.Basics.Functions.GenerateGrid(
      {0},
      length,
      N_cv) "Discretisation scheme"
                                   ;
  final parameter SI.Length Delta_x_FM[N_cv + 1]=cat(
      1,
      {Delta_x[1]/2},
      {(Delta_x[i - 1] + Delta_x[i])/2 for i in 2:N_cv},
      {Delta_x[N_cv]/2}) "Discretisation scheme (Flow model)"
                                                             ;
  final parameter SI.Volume volume_bed_FM[N_cv+1]=cat(
    1,
    {volume_bed[1]/2},
    {volume_bed[i-1]*Delta_x[i-1]/2/Delta_x_FM[i] + volume_bed[i]*Delta_x[i]/2/Delta_x_FM[i] for i in 2:N_cv},
    {volume_bed[N_cv]/2});
  final parameter SI.Area A_cross_bed_FM[N_cv + 1](min=ones(N_cv+1)*Modelica.Constants.eps) = cat(
    1,
    {A_cross_bed[1]},
    {(A_cross_bed[i] + A_cross_bed[i + 1])/2 for i in 1:N_cv - 1},
    {A_cross_bed[N_cv]}) "Cross section for mass flow" ;
  final parameter SI.Length x_abs[N_cv] = {sum(Delta_x[1:i]) - Delta_x[i]/2 for i in 1:N_cv} "Length from inlet to center of cells";

  final parameter SI.Volume volume_air[N_cv](min=ones(N_cv)*Modelica.Constants.eps) = porosity*volume_bed "Volume of air in the control volume" ;
  final parameter SI.Volume volume_rock[N_cv](min=ones(N_cv)*Modelica.Constants.eps) = (1-porosity)*volume_bed "Volume of rock in the control volume" ;
  final parameter SI.Area A_cross_air[N_cv](min=ones(N_cv)*Modelica.Constants.eps) = A_cross_bed*porosity "Cross Area of air in the control volume" ;
  final parameter SI.Area A_cross_rock[N_cv](min=ones(N_cv)*Modelica.Constants.eps) = A_cross_bed*(1-porosity) "Cross Area of rock in the control volume" ;
  final parameter SI.Area A_cross_air_FM[N_cv+1](min=ones(N_cv+1)*Modelica.Constants.eps) = A_cross_bed_FM*porosity "Cross Area of air in flow cell control volume" ;
  final parameter SI.Area A_cross_rock_FM[N_cv+1](min=ones(N_cv+1)*Modelica.Constants.eps) = A_cross_bed_FM*(1-porosity) "Cross Area of rock in flow cell control volume" ;

  final parameter SI.Volume volume_tot = sum(volume_bed)  "Total Volume";
  final parameter SI.Area A_heat_tot = sum(A_heat)  "Total Heat transfer area" 
                                                                                          ;
end PackedBedGeometry_N_cv;

within TransiEnt.Storage.Heat.PackedBedStorage_L4.Basics.PackedBedPressureLoss;
model Ergun "Empirical Correlation according to Ergun"




  import SI = ClaRa.Basics.Units;
  import TILMedia.GasObjectFunctions.density_phxi;
  import Modelica.Fluid.Dissipation.Utilities.Functions.General.SmoothPower;
  extends TransiEnt.Storage.Heat.PackedBedStorage_L4.Basics.PackedBedPressureLoss.PressureLossBasePackedBed;




  final parameter ClaRa.Basics.Units.Area permeability = 2*iCom.porosity*iCom.d_h^2/150;




equation
 if not frictionAtInlet and not frictionAtOutlet then
    for i in 2:iCom.N_cv loop
   v_FM[i] = (150*eta_FM[i]*(1-iCom.porosity)^2*geo.Delta_x_FM[i]*(sum(geo.Delta_x_FM)/(sum(geo.Delta_x_FM) - geo.Delta_x_FM[1] - geo.Delta_x_FM[iCom.N_cv + 1]))/(iCom.d_SM^2*iCom.porosity^3))^(-1) *dp_pb_V[i];
   v_FM[i] = (1.75*rho_FM[i]*(1-iCom.porosity)*geo.Delta_x_FM[i]*(sum(geo.Delta_x_FM)/(sum(geo.Delta_x_FM) - geo.Delta_x_FM[1] - geo.Delta_x_FM[iCom.N_cv + 1]))/(iCom.d_SM*iCom.porosity^3))^(-0.5)*ClaRa.Basics.Functions.ThermoRoot(dp_pb_I[i],Delta_p_smooth);
    end for;
    dp_pb_V[1] = 0;
    dp_pb_I[1] = 0;
    dp_pb_V[iCom.N_cv + 1] = 0;
    dp_pb_I[iCom.N_cv + 1] = 0;
  elseif not frictionAtInlet and frictionAtOutlet then
    for i in 2:iCom.N_cv + 1 loop
      v_FM[i] = (150*eta_FM[i]*(1-iCom.porosity)^2*geo.Delta_x_FM[i]*(sum(geo.Delta_x_FM)/(sum(geo.Delta_x_FM) - geo.Delta_x_FM[1]))/(iCom.d_SM^2*iCom.porosity^3))^(-1)*dp_pb_V[i];
 v_FM[i] = (1.75*rho_FM[i]*(1-iCom.porosity)*geo.Delta_x_FM[i]*(sum(geo.Delta_x_FM)/(sum(geo.Delta_x_FM) - geo.Delta_x_FM[1]))/(iCom.d_SM*iCom.porosity^3))^(-0.5)*ClaRa.Basics.Functions.ThermoRoot(dp_pb_I[i],Delta_p_smooth);
    end for;
    dp_pb_V[1] = 0;
    dp_pb_I[1] = 0;
  elseif frictionAtInlet and not frictionAtOutlet then
    for i in 1:iCom.N_cv loop
       v_FM[i] = (150*eta_FM[i]*(1-iCom.porosity)^2*geo.Delta_x_FM[i]*(sum(geo.Delta_x_FM)/(sum(geo.Delta_x_FM) - geo.Delta_x_FM[iCom.N_cv+1]))/(iCom.d_SM^2*iCom.porosity^3))^(-1)*dp_pb_V[i];
 v_FM[i] = (1.75*rho_FM[i]*(1-iCom.porosity)*geo.Delta_x_FM[i]*(sum(geo.Delta_x_FM)/(sum(geo.Delta_x_FM) - geo.Delta_x_FM[iCom.N_cv+1]))/(iCom.d_SM*iCom.porosity^3))^(-0.5)*ClaRa.Basics.Functions.ThermoRoot(dp_pb_I[i],Delta_p_smooth);
    end for;
    dp_pb_V[iCom.N_cv + 1] = 0;
    dp_pb_I[iCom.N_cv + 1] = 0;
  else

  for i in 1:iCom.N_cv+1 loop
 v_FM[i] = (150*eta_FM[i]*(1-iCom.porosity)^2*geo.Delta_x_FM[i]/(iCom.d_SM^2*iCom.porosity^3))^(-1)*dp_pb_V[i];
 v_FM[i] = (1.75*rho_FM[i]*(1-iCom.porosity)*geo.Delta_x_FM[i]/(iCom.d_SM*iCom.porosity^3))^(-0.5)*ClaRa.Basics.Functions.ThermoRoot(dp_pb_I[i],Delta_p_smooth);
 end for;
  end if
  ;
end Ergun;

within TransiEnt.Storage.Heat.PackedBedStorage_L4.Basics.PackedBedPressureLoss;
model MacDonald "Empirical correlation according to MacDonald et al"




  import SI = ClaRa.Basics.Units;
  import TILMedia.GasObjectFunctions.density_phxi;
  import Modelica.Fluid.Dissipation.Utilities.Functions.General.SmoothPower;
  extends TransiEnt.Storage.Heat.PackedBedStorage_L4.Basics.PackedBedPressureLoss.PressureLossBasePackedBed;




  final parameter ClaRa.Basics.Units.Area permeability = 2*iCom.porosity*iCom.d_h^2/217;




equation
 if not frictionAtInlet and not frictionAtOutlet then
    for i in 2:iCom.N_cv loop
   v_FM[i] = (217*eta_FM[i]*(1-iCom.porosity)^2*geo.Delta_x_FM[i]*(sum(geo.Delta_x_FM)/(sum(geo.Delta_x_FM) - geo.Delta_x_FM[1] - geo.Delta_x_FM[iCom.N_cv + 1]))/(iCom.d_SM^2*iCom.porosity^3))^(-1) *dp_pb_V[i];
   v_FM[i] = (1.83*rho_FM[i]*(1-iCom.porosity)*geo.Delta_x_FM[i]*(sum(geo.Delta_x_FM)/(sum(geo.Delta_x_FM) - geo.Delta_x_FM[1] - geo.Delta_x_FM[iCom.N_cv + 1]))/(iCom.d_SM*iCom.porosity^3))^(-0.5)*ClaRa.Basics.Functions.ThermoRoot(dp_pb_I[i],Delta_p_smooth);
    end for;
    dp_pb_V[1] = 0;
    dp_pb_I[1] = 0;
    dp_pb_V[iCom.N_cv + 1] = 0;
    dp_pb_I[iCom.N_cv + 1] = 0;
  elseif not frictionAtInlet and frictionAtOutlet then
    for i in 2:iCom.N_cv + 1 loop
      v_FM[i] = (217*eta_FM[i]*(1-iCom.porosity)^2*geo.Delta_x_FM[i]*(sum(geo.Delta_x_FM)/(sum(geo.Delta_x_FM) - geo.Delta_x_FM[1]))/(iCom.d_SM^2*iCom.porosity^3))^(-1)*dp_pb_V[i];
 v_FM[i] = (1.83*rho_FM[i]*(1-iCom.porosity)*geo.Delta_x_FM[i]*(sum(geo.Delta_x_FM)/(sum(geo.Delta_x_FM) - geo.Delta_x_FM[1]))/(iCom.d_SM*iCom.porosity^3))^(-0.5)*ClaRa.Basics.Functions.ThermoRoot(dp_pb_I[i],Delta_p_smooth);
    end for;
    dp_pb_V[1] = 0;
    dp_pb_I[1] = 0;
  elseif frictionAtInlet and not frictionAtOutlet then
    for i in 1:iCom.N_cv loop
       v_FM[i] = (217*eta_FM[i]*(1-iCom.porosity)^2*geo.Delta_x_FM[i]*(sum(geo.Delta_x_FM)/(sum(geo.Delta_x_FM) - geo.Delta_x_FM[iCom.N_cv+1]))/(iCom.d_SM^2*iCom.porosity^3))^(-1)*dp_pb_V[i];
 v_FM[i] = (1.83*rho_FM[i]*(1-iCom.porosity)*geo.Delta_x_FM[i]*(sum(geo.Delta_x_FM)/(sum(geo.Delta_x_FM) - geo.Delta_x_FM[iCom.N_cv+1]))/(iCom.d_SM*iCom.porosity^3))^(-0.5)*ClaRa.Basics.Functions.ThermoRoot(dp_pb_I[i],Delta_p_smooth);
    end for;
    dp_pb_V[iCom.N_cv + 1] = 0;
    dp_pb_I[iCom.N_cv + 1] = 0;
  else

  for i in 1:iCom.N_cv+1 loop
 v_FM[i] = (217*eta_FM[i]*(1-iCom.porosity)^2*geo.Delta_x_FM[i]/(iCom.d_SM^2*iCom.porosity^3))^(-1)*dp_pb_V[i];
 v_FM[i] = (1.83*rho_FM[i]*(1-iCom.porosity)*geo.Delta_x_FM[i]/(iCom.d_SM*iCom.porosity^3))^(-0.5)*ClaRa.Basics.Functions.ThermoRoot(dp_pb_I[i],Delta_p_smooth);
 end for;
  end if
  ;
end MacDonald;

within TransiEnt.Storage.Heat.PackedBedStorage_L4.Basics.PackedBedPressureLoss;
partial model PressureLossBasePackedBed "Base model for pressure loss in packed beds"




  import SI = ClaRa.Basics.Units;
  import TILMedia.GasObjectFunctions.density_phxi;
  import Modelica.Fluid.Dissipation.Utilities.Functions.General.SmoothPower;
  extends ClaRa.Basics.Icons.Delta_p;




  parameter SI.Pressure Delta_p_smooth=iCom.Delta_p_nom/iCom.N_cv*0.2 "|Small Mass Flows|For pressure losses below this value the square root of the quadratic pressure loss model is regularised";
  final parameter ClaRa.Basics.Units.Length Delta_x[iCom.N_cv]=geo.Delta_x;
  final parameter ClaRa.Basics.Units.Length Delta_x_FM[iCom.N_cv + 1]=geo.Delta_x_FM "flowModel grid";
  final parameter ClaRa.Basics.Units.MassFlowRate m_flow_nom=iCom.m_flow_nom "Nominal mass flow rate";
  final parameter ClaRa.Basics.Units.PressureDifference Delta_p_nom=iCom.Delta_p_nom "Nominal pressure loss wrt. all parallel tubes";
  final parameter ClaRa.Basics.Units.Area[iCom.N_cv+1] A_cross_bed_FM = geo.A_cross_bed_FM "Cross Area of Packed Bed";
  outer parameter Boolean frictionAtInlet;
  outer parameter Boolean frictionAtOutlet;




 outer TILMedia.Gas_ph fluid[iCom.N_cv];
 outer TILMedia.Gas_ph fluidInlet;
 outer TILMedia.Gas_ph fluidOutlet;
 outer TransiEnt.Storage.Heat.PackedBedStorage_L4.Basics.Records.IComPackedBedControlVolume_L4 iCom;
 outer parameter Boolean useHomotopy;
 outer TransiEnt.Storage.Heat.PackedBedStorage_L4.Basics.PackedBedGeometry.PackedBedGeometry_N_cv geo;




  ClaRa.Basics.Units.PressureDifference Delta_p[iCom.N_cv + 1] "Pressure difference";
  ClaRa.Basics.Units.MassFlowRate m_flow[iCom.N_cv + 1] "Massflow in FlowModel cells";
  SI.PressureDifference dp_pb_V[geo.N_cv + 1] "Part of Pressure Difference caused by Viscosity";
  SI.PressureDifference dp_pb_I[geo.N_cv + 1] "Part of Pressure Difference caused by Inertia";
  SI.DensityMassSpecific rho_FM[iCom.N_cv + 1] "Density in FlowModel cells";
  SI.Velocity v_FM[geo.N_cv+1] "Superficial Velocity at cell boundary";
  SI.DynamicViscosity eta_FM[geo.N_cv+1] "Dynamic Viscosity at cell boundary";
  Real Re[geo.N_cv+1] "Reynolds Number";
equation

  rho_FM[2:geo.N_cv] = {smooth(1, noEvent(max(1e-6, if m_flow[i] > 0 then density_phxi(
    iCom.p[i - 1],
    iCom.h[i - 1],
    iCom.xi[i - 1, :],
    iCom.fluidPointer[i - 1]) else density_phxi(
    iCom.p[i],
    iCom.h[i],
    iCom.xi[i, :],
    iCom.fluidPointer[i])))) for i in 2:iCom.N_cv};
  rho_FM[1] = smooth(1, noEvent(max(1e-6, if m_flow[1] > 0 then density_phxi(
    iCom.p_in[1],
    iCom.h_in[1],
    iCom.xi_in[1, :],
    iCom.fluidPointer_in[1]) else density_phxi(
    iCom.p[1],
    iCom.h[1],
    iCom.xi[1, :],
    iCom.fluidPointer[1]))));
  rho_FM[geo.N_cv + 1] = smooth(1, noEvent(max(1e-6, if m_flow[geo.N_cv + 1] > 0 then density_phxi(
    iCom.p[end],
    iCom.h[end],
    iCom.xi[end, :],
    iCom.fluidPointer[end]) else density_phxi(
    iCom.p_out[1],
    iCom.h_out[1],
    iCom.xi_out[1, :],
    iCom.fluidPointer_out[1]))));
  for i in 2:geo.N_cv loop
 eta_FM[i] = (fluid[i-1].transp.eta + fluid[i].transp.eta)/2;
  end for;
 eta_FM[1] = (fluidInlet.transp.eta+fluid[1].transp.eta)/2;
 eta_FM[geo.N_cv+1] = (fluidOutlet.transp.eta+fluid[geo.N_cv].transp.eta)/2;
 for i in 1:geo.N_cv+1 loop
 v_FM[i] = m_flow[i]/(rho_FM[i].*A_cross_bed_FM[i]); 
 Delta_p[i] = dp_pb_V[i] + dp_pb_I[i];
 Re[i] = noEvent(abs(v_FM[i])) .* iCom.d_h .* rho_FM[i] ./ (iCom.porosity .* eta_FM[i]);
 end for
  ;
end PressureLossBasePackedBed;

within TransiEnt.Storage.Heat.PackedBedStorage_L4.Basics.StorageAirVolumeGeometry;
model BlockShapedUnit "block"




  extends ClaRa.Basics.ControlVolumes.Fundamentals.Geometry.GenericGeometry(
    final volume=width*height*length,
    final N_heat=2,
    final A_heat={2*(width + height)*length,A_cross},
    final A_cross=(width*height),
    final A_front=A_cross,
    final A_hor=length*width,
    final height_fill=height,
    final shape=[0, 1; 1, 1],
    final z_in=zeros(N_inlet),
    final z_out=zeros(N_inlet),
    final N_inlet = 1,
    final N_outlet = 1,
    final CF_geo = ones(N_heat));
  extends TransiEnt.Storage.Heat.PackedBedStorage_L4.Basics.StorageAirVolumeGeometry.StorageAirVolumeGeometry;
  import SI = ClaRa.Basics.Units;




  parameter SI.Length height=1 "Height of the component" ;
  parameter SI.Length width=1 "Width of the component" ;
  parameter SI.Length length=1 "Length of the component" ;
equation




   for i in 1:N_inlet loop
     assert(if height_fill <> -1 then z_in[i]<=height_fill else true, "Position of inlet flange no. " +String(i)+ "("+String(z_in[i], significantDigits=3)+" m) must be below max. fill height of "+ String(height_fill, significantDigits=3) + " m in component " +  getInstanceName() + ".");
   end for;
   for i in 1:N_outlet loop
     assert(if height_fill <> -1 then z_out[i]<=height_fill else true, "Position of outlet flange no. " +String(i)+ "("+String(z_out[i], significantDigits=3)+" m) must be below max. fill height of "+ String(height_fill, significantDigits=3) + " m in component " +  getInstanceName() + ".");
   end for;
  for i in 1:N_inlet loop
    assert(z_in[i]>=0, "Position of inlet flange no. " +String(i)+ "("+String(z_in[i], significantDigits=3)+" m) must be positive in component " +  getInstanceName() + ".");
  end for;
  for i in 1:N_outlet loop
    assert(z_out[i]>=0, "Position of outlet flange no. " +String(i)+ "("+String(z_out[i], significantDigits=3)+" m) must be positive in component " +  getInstanceName() + ".");
  end for;
  assert(A_cross>0, "The cross section of the shell side must be > 0 but is "+String(A_cross, significantDigits=3) + " in instance" + getInstanceName() + ".");
  assert(volume>0, "The volume of the shell side must be > 0 but is "+String(volume, significantDigits=3) + " in instance" + getInstanceName() + ".")
  ;
end BlockShapedUnit;

