    ;
  connect(shiftOutput.gear, transmissionControlBus.currentGear) ;
  connect(forceSensor.f, normalise.u) ;
  connect(normalise.y, clutch.f_normalized) ;
  connect(outputSpeed.w, transmissionBus.outputSpeed) ;

